(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("plut-lives-5-e", [{"sp": "HDR", "t": "Βίοι Παράλληλοι"}, {"sp": "HDR", "t": "Δημοσθένης"}, {"sp": "N", "t": "ὁ μὲν γράψας τὸ ἐπὶ τῇ νίκῃ τῆς Ὀλυμπίασιν ἱπποδρομίας εἰς Ἀλκιβιάδην ἐγκώμιον, εἴτ’ Εὐριπίδης, ὡς ὁ πολὺς κρατεῖ λόγος, εἴθ’ ἕτερός τις ἦν, Σόσσιε, φησὶ χρῆναι τῷ εὐδαίμονι πρῶτον ὑπάρξαι τὰν πόλιν εὐδόκιμον ἐγὼ δὲ τῷ μὲν εὐδαιμονήσειν μέλλοντι τὴν ἀληθινὴν εὐδαιμονίαν, ἧς ἐν ἤθει καὶ διαθέσει τὸ πλεῖστόν ἐστιν, οὐδὲν διαφέρειν ἡγοῦμαι ἀδόξου καὶ ταπεινῆς πατρίδος ἢ μητρὸς ἀμόρφου καὶ μικρᾶς γενέσθαι. γελοῖον γάρ εἴ τις οἴοιτο τὴν Ἰουλίδα, μέρος μικρὸν οὖσαν οὐ μεγάλης νήσου τῆς Κέω, καὶ τὴν Αἴγιναν, ἣν τῶν Ἀττικῶν τις ἐκέλευεν ὡς λήμην ἀφαιρεῖν τοῦ Πειραιῶς, ὑποκριτὰς μὲν ἀγαθοὺς τρέφειν καὶ ποιητάς, ἄνδρα δ’ οὐκ ἄν ποτε δύνασθαι δίκαιον καὶ αὐτάρκη καὶ νοῦν ἔχοντα καὶ μεγαλόψυχον προενεγκεῖν. τὰς γὰρ ἄλλας τέχνας εἰκός ἐστι πρὸς ἐργασίαν ἢ δόξαν συνισταμένας ἐν ταῖς ἀδόξοις καὶ ταπειναῖς πόλεσιν ἀπομαραίνεσθαι, τὴν δ’ ἀρετὴν, ὥσπερ ἰσχυρὸν καὶ διαρκὲς φυτὸν, ἐν ἅπαντι ῥιζοῦσθαι τόπῳ, φύσεώς τε χρηστῆς καὶ φιλοπόνου ψυχῆς ἐπιλαμβανομένην. ὅθεν οὐδ’ ἡμεῖς, εἴ τι τοῦ φρονεῖν ὡς δεῖ καὶ βιοῦν ἐλλείπομεν, τοῦτο τῇ σμικρότητι τῆς πατρίδος, ἀλλ’ αὑτοῖς δικαίως ἀναθήσομεν.", "st": "Dem. 1.1"}, {"sp": "N", "t": "τῷ μέντοι σύνταξιν ὑποβεβλημένῳ καὶ ἱστορίαν ἐξ οὐ προχείρων οὐδ’ οἰκείων, ἀλλὰ ξένων τε τῶν πολλῶν καὶ διεσπαρμένων ἐν ἑτέροις συνιοῦσαν ἀναγνωσμάτων, τῷ ὄντι χρὴ πρῶτον ὑπάρχειν καὶ μάλιστα τὴν πόλιν εὐδόκιμον καὶ φιλόκαλον καὶ πολυάνθρωπον, ὡς βιβλίων τε παντοδαπῶν ἀφθονίαν ἔχων, καὶ ὅσα τοὺς γράφοντας διαφυγόντα σωτηρίᾳ μνήμης ἐπιφανεστέραν εἴληφε πίστιν ὑπολαμβάνων ἀκοῇ καὶ διαπυνθανόμενος, μὴ πολλῶν μηδ’ ἀναγκαίων ἐνδεὲς ἀποδιδοίη τὸ ἔργον. ἡμεῖς δὲ μικρὰν οἰκοῦντες πόλιν, καὶ ἵνα μὴ μικροτέρα γένηται φιλοχωροῦντες, ἐν δὲ Ῥώμῃ καὶ ταῖς περὶ τὴν Ἰταλίαν διατριβαῖς οὐ σχολῆς οὔσης γυμνάζεσθαι περὶ τὴν Ῥωμαϊκὴν διάλεκτον ὑπὸ χρειῶν πολιτικῶν καὶ τῶν διὰ φιλοσοφίαν πλησιαζόντων, ὀψέ ποτε καὶ πόρρω τῆς ἡλικίας ἠρξάμεθα Ῥωμαϊκοῖς γράμμασιν ἐντυγχάνειν. καὶ πρᾶγμα θαυμαστὸν μέν, ἀλλ’ ἀληθὲς ἐπάσχομεν. οὐ γὰρ οὕτως ἐκ τῶν ὀνομάτων τὰ πράγματα συνιέναι καὶ γνωρίζειν συνέβαινεν ἡμῖν, ὡς ἐκ τῶν πραγμάτων ἁμῶς γέ πως εἴχομεν ἐμπειρίαν ἐπακολουθεῖν δι’ αὐτὰ καὶ τοῖς ὀνόμασι. κάλλους δὲ Ῥωμαϊκῆς ἀπαγγελίας καὶ τάχους αἰσθάνεσθαι καὶ μεταφορᾶς ὀνομάτων καὶ ἁρμονίας καὶ τῶν ἄλλων οἷς ὁ λόγος ἀγάλλεται, χαρίεν μέν ἡγούμεθα καὶ οὐκ ἀτερπές· ἡ δὲ πρὸς τοῦτο μελέτη καὶ ἄσκησις οὐκ εὐχερής, ἀλλ’ οἷστισι πλείων τε σχολὴ καὶ τὰ τῆς ὥρας ἔτι πρὸς τὰς τοιαύτας ἐπιχωρεῖ φιλοτιμίας.", "st": "Dem. 2.1"}, {"sp": "N", "t": "διὸ καὶ γράφοντες ἐν τῷ βιβλίῳ τούτῳ, τῶν παραλλήλων βίων ὄντι πέμπτῳ, περὶ Δημοσθένους καὶ Κικέρωνος, ἀπὸ τῶν πράξεων καὶ τῶν πολιτειῶν τὰς φύσεις αὐτῶν καὶ τὰς διαθέσεις πρὸς ἀλλήλας ἐπισκεψόμεθα, τὸ δὲ τοὺς λόγους ἀντεξετάζειν καὶ ἀποφαίνεσθαι πότερος ἡδίων ἢ δεινότερος εἰπεῖν, ἐάσομεν. κακὴ γὰρ, ὥς φησιν ὁ Ἴων, ἡ δελφῖνος ἐν χέρσῳ βία, ἣν ὁ περιττὸς ἐν ἅπασι Κεκίλιος ἀγνοήσας ἐνεανιεύσατο σύγκρισιν τοῦ Δημοσθένους καὶ Κικέρωνος ἐξενεγκεῖν. ἀλλὰ γὰρ ἴσως, εἰ παντὸς ἦν τὸ γνῶθι σαυτὸν ἔχειν πρόχειρον, οὐκ ἂν ἐδόκει πρόσταγμα θεῖον εἶναι.", "st": "Dem. 3.1"}, {"sp": "N", "t": "Δημοσθένην γὰρ καὶ Κικέρωνα τὸν αὐτὸν ἔοικε πλάττων ἀπ’ ἀρχῆς ὁ δαίμων πολλὰς μὲν ἐμβαλεῖν εἰς τὴν φύσιν αὐτῶν τῶν ὁμοιοτήτων, ὥσπερ τὸ φιλότιμον καὶ φιλελεύθερον ἐν τῇ πολιτείᾳ, πρὸς δὲ κινδύνους καὶ πολέμους ἄτολμον, πολλὰ δ’ ἀναμῖξαι καὶ τῶν τυχηρῶν. δύο γὰρ ἑτέρους οὐκ ἂν εὑρεθῆναι δοκῶ ῥήτορας ἐκ μὲν ἀδόξων καὶ μικρῶν ἰσχυροὺς καὶ μεγάλους γενομένους, προσκρούσαντας δὲ βασιλεῦσι καὶ τυράννοις, θυγατέρας δ’ ἀποβαλόντας, ἐκπεσόντας δὲ τῆς πατρίδος, κατελθόντας δὲ μετὰ τιμῆς, ἀποδράντας δ’ αὖθις καὶ ληφθέντας ὑπὸ τῶν πολεμίων, ἅμα δὲ παυσαμένῃ τῇ τῶν πολιτῶν ἐλευθερίᾳ τὸν βίον συγκαταστρέψαντας· ὥστε, εἰ γένοιτο τῇ φύσει καὶ τῇ τύχῃ καθάπερ τεχνίταις ἅμιλλα, χαλεπῶς ἂν διακριθῆναι πότερον αὕτη τοῖς τρόποις ἢ τοῖς πράγμασιν ἐκείνη τοὺς ἄνδρας ὁμοιοτέρους ἀπείργασται. λεκτέον δὲ περὶ τοῦ πρεσβυτέρου πρότερον.", "st": "Dem. 3.3"}, {"sp": "N", "t": "Δημοσθένης ὁ πατὴρ Δημοσθένους ἦν μὲν τῶν καλῶν καὶ ἀγαθῶν ἀνδρῶν, ὡς ἱστορεῖ Θεόπομπος, ἐπεκαλεῖτο δὲ μαχαιροποιός ἐργαστήριον ἔχων μέγα καὶ δούλους τεχνίτας τοὺς τοῦτο πράττοντας, ἃ δ’ Αἰσχίνης ὁ ῥήτωρ εἴρηκε περὶ τῆς μητρός, ὡς ἐκ Γύλωνός τινος ἐπ’ αἰτίᾳ προδοσίας φεύγοντος ἐξ ἄστεος γεγόνοι καὶ βαρβάρου γυναικός, οὐκ ἔχομεν εἰπεῖν εἴτ’ ἀληθῶς εἴρηκεν εἴτε βλασφημῶν καὶ καταψευδόμενος. ἀπολειφθεὶς δ’ ὁ Δημοσθένης ὑπὸ τοῦ πατρὸς ἑπταέτης ἐν εὐπορίᾳ μικρὸν γὰρ ἀπέλιπεν ἡ σύμπασα τίμησις αὐτοῦ τῆς οὐσίας πεντεκαίδεκα ταλάντων ὑπὸ τῶν ἐπιτρόπων ἠδικήθη, τὰ μὲν νοσφισαμένων, τὰ δ’ ἀμελησάντων, ὥστε καὶ τῶν διδασκάλων αὐτοῦ τὸν μισθὸν ἀποστερῆσαι. διά τε δὴ τοῦτο τῶν ἐμμελῶν καὶ προσηκόντων ἐλευθέρῳ παιδὶ μαθημάτων ἀπαίδευτος δοκεῖ γενέσθαι καὶ διά τὴν τοῦ σώματος ἀσθένειαν καὶ θρύψιν, οὐ προϊεμένης τοῖς πόνοις τῆς μητρὸς αὐτὸν, οὐδὲ προσβιαζομένων τῶν παιδαγωγῶν. ἦν γὰρ ἐξ ἀρχῆς κάτισχνος καὶ νοσώδης, καὶ τὴν λοιδορουμένην ἐπωνυμίαν, τὸν Βάταλον, εἰς τὸ σῶμα λέγεται σκωπτόμενος ὑπὸ τῶν παίδων λαβεῖν. ἦν δὲ ὁ Βάταλος, ὡς μὲν ἔνιοί φασιν, αὐλητὴς τῶν κατεαγότων, καὶ δραμάτιον εἰς τοῦτο κωμῳδῶν αὐτὸν Ἀντιφάνης πεποίηκεν. ἔνιοί δέ τινες ὡς ποιητοῦ τρυφερὰ καὶ παροίνια γράφοντος τοῦ Βατάλου μέμνηνται. δοκεῖ δὲ καὶ τῶν οὐκ εὐπρεπῶν τι λεχθῆναι τοῦ σώματος μορίων παρὰ τοῖς Ἀττικοῖς τότε καλεῖσθαι βάταλος. ὁ δ’ Ἀργᾶς καὶ τοῦτο γάρ φασι τῷ Δημοσθένει γενέσθαι παρώνυμον ἢ πρὸς τὸν τρόπον, ὡς θηριώδη καὶ πικρὸν ἐτέθη· τὸν γὰρ ὄφιν ἔνιοι τῶν ποιητῶν ἀργᾶν ὀνομάζουσιν ἢ πρὸς τὸν λόγον, ὡς ἀνιῶντα τοὺς ἀκροωμένους· καὶ γὰρ Ἀργᾶς τοὔνομα ποιητὴς ἦν νόμων πονηρῶν καὶ ἀργαλέων. καὶ ταῦτα μὲν ταύτῃ.", "st": "Dem. 4.1"}, {"sp": "N", "t": "τῆς δὲ πρὸς τοὺς λόγους ὁρμῆς ἀρχὴν αὐτῷ φασι τοιαύτην γενέσθαι. Καλλιστράτου τοῦ ῥήτορος ἀγωνίζεσθαι τὴν περὶ Ὠρωποῦ κρίσιν ἐν τῷ δικαστηρίῳ μέλλοντος ἦν προσδοκία τῆς δίκης μεγάλη διά τε τὴν τοῦ ῥήτορος δύναμιν, ἀνθοῦντος τότε μάλιστα τῇ δόξῃ, καί διά τὴν πρᾶξιν οὖσαν περιβόητον. ἀκούσας οὖν ὁ Δημοσθένης τῶν διδασκάλων καί τῶν παιδαγωγῶν συντιθεμένων τῇ δίκῃ παρατυχεῖν, ἔπεισε τὸν ἑαυτοῦ παιδαγωγὸν δεόμενος καί προθυμούμενος ὅπως αὑτὸν ἀγάγοι πρὸς τὴν ἀκρόασιν. ὁ δ’ ἔχων πρὸς τοὺς ἀνοίγοντας τὰ δικαστήρια δημοσίους συνήθειαν, εὐπόρησε χώρας ἐν ᾗ καθήμενος ὁ παῖς ἀδήλως ἀκούσεται τῶν λεγομένων. εὐημερήσαντος δὲ τοῦ Καλλιστράτου καί θαυμασθέντος ὑπερφυῶς, ἐκείνου μὲν ἐζήλωσε τὴν δόξαν, ὁρῶν προπεμπόμενον ὑπὸ τῶν πολλῶν καί μακαριζόμενον, τοῦ δὲ λόγου μᾶλλον ἐθαύμασε καί κατενόησε τὴν ἰσχὺν ὡς πάντα χειροῦσθαι καί τιθασεύειν πεφυκότος. ὅθεν ἐάσας τὰ λοιπὰ μαθήματα καί τὰς παιδικὰς διατριβάς, αὐτὸς αὑτὸν ἤσκει καί διεπόνει ταῖς μελέταις, ὡς ἂν τῶν λεγόντων ἐσόμενος καί αὐτός. ἐχρήσατο δὲ Ἰσαίῳ πρὸς τὸν λόγον ὑφηγητῇ, καίπερ Ἰσοκράτους τότε σχολάζοντος, εἴτε, ὥς τινες λέγουσι, τὸν ὡρισμένον μισθὸν Ἰσοκράτει τελέσαι μὴ δυνάμενος, τὰς δέκα μνᾶς, διὰ τὴν ὀρφανίαν, εἴτε μᾶλλον τοῦ Ἰσαίου τὸν λόγον ὡς δραστήριον καί πανοῦργον ἐπὶ τὴν χρείαν ἀποδεχόμενος. Ἕρμιππος δέ φησιν ἀδεσπότοις ὑπομνήμασιν ἐντυχεῖν ἐν οἷς ἐγέγραπτο τὸν Δημοσθένην συνεσχολακέναι Πλάτωνι καί πλεῖστον εἰς τοὺς λόγους ὠφελῆσθαι, Κτησιβίου δὲ μέμνηται λέγοντος παρὰ Καλλίου τοῦ Συρακουσίου καί τινων ἄλλων τὰς Ἰσοκράτους τέχνας καί τὰς Ἀλκιδάμαντος κρύφα λαβόντα τὸν Δημοσθένην καταμαθεῖν.", "st": "Dem. 5.1"}, {"sp": "N", "t": "ὡς γοῦν ἐν ἡλικίᾳ γενόμενος τοῖς ἐπιτρόποις ἤρξατο δικάζεσθαι καὶ λογογραφεῖν ἐπ’ αὐτούς πολλὰς διαδύσεις καὶ παλινδικίας εὑρίσκοντας, ἐγγυμνασάμενος, κατὰ τὸν Θουκυδίδην, ταῖς μελέταις οὐκ ἀκινδύνως οὐδ’ ἀργῶς, κατευτυχήσας ἐκπρᾶξαι μὲν οὐδὲ πολλοστὸν ἠδυνήθη μέρος τῶν πατρῴων, τόλμαν δὲ πρὸς τὸ λέγειν καὶ συνήθειαν ἱκανὴν λαβών καὶ γευσάμενος τῆς περὶ τοὺς ἀγῶνας φιλοτιμίας καὶ δυνάμεως ἐπεχείρησεν εἰς μέσον παριέναι καὶ τὰ κοινὰ πράττειν. καὶ καθάπερ Λαομέδοντα τὸν Ὀρχομένιον λέγουσι καχεξίαν τινὰ σπληνὸς ἀμυνόμενον δρόμοις μακροῖς χρῆσθαι τῶν ἰατρῶν κελευσάντων, εἶθ’ οὕτως διαπονήσαντα τὴν ἕξιν ἐπιθέσθαι τοῖς στεφανίταις ἀγῶσι καὶ τῶν ἄκρων γενέσθαι δολιχοδρόμων, οὕτως τῷ Δημοσθένει συνέβη τὸ πρῶτον ἐπανορθώσεως ἕνεκα τῶν ἰδίων ἀποδύντι πρὸς τὸ λέγειν, ἐκ τούτου κτησαμένῳ δεινότητα καὶ δύναμιν ἐν τοῖς πολιτικοῖς ἤδη καθάπερ στεφανίταις ἀγῶσι πρωτεύειν τῶν ἀπὸ τοῦ βήματος ἀγωνιζομένων πολιτῶν.", "st": "Dem. 6.1"}, {"sp": "N", "t": "καίτοι τό γε πρῶτον ἐντυγχάνων τῷ δήμῳ θορύβοις περιέπιπτε καὶ κατεγελᾶτο δι’ ἀήθειαν, τοῦ λόγου συγκεχύσθαι ταῖς περιόδοις καὶ βεβασανίσθαι τοῖς ἐνθυμήμασι πικρῶς ἄγαν καὶ κατακόρως δοκοῦντος. ἦν δέ τις, ὡς ἔοικε, καὶ φωνῆς ἀσθένεια καὶ γλώττης ἀσάφεια καὶ πνεύματος κολοβότης ἐπιταράττουσα τὸν νοῦν τῶν λεγομένων τῷ διασπᾶσθαι τὰς περιόδους. τέλος δ’ ἀποστάντα τοῦ δήμου καὶ ῥεμβόμενον ἐν Πειραιεῖ δι’ ἀθυμίαν Εὔνομος ὁ Θριάσιος ἤδη πάνυ γέρων θεασάμενος ἐπετίμησεν, ὅτι τὸν λόγον ἔχων ὁμοιότατον τῷ Περικλέους προδίδωσιν ὑπ’ ἀτολμίας καὶ μαλακίας ἑαυτόν, οὔτε τοὺς ὄχλους ὑφιστάμενος εὐθαρσῶς, οὔτε τό σῶμα πρὸς τοὺς ἀγῶνας ἐξαρτυόμενος, ἀλλὰ τρυφῇ περιορῶν μαραινόμενον.", "st": "Dem. 6.3"}, {"sp": "N", "t": "πάλιν δέ ποτέ φασιν ἐκπεσόντος αὐτοῦ καὶ ἀπιόντος οἴκαδε συγκεχυμένου καὶ βαρέως φέροντος ἐπακολουθῆσαι Σάτυρον τὸν ὑποκριτὴν ἐπιτήδειον ὄντα καὶ συνελθεῖν. ὀδυρομένου δὲ τοῦ Δημοσθένους πρὸς αὐτόν ὅτι πάντων φιλοπονώτατος ὢν τῶν λεγόντων καὶ μικροῦ δέων καταναλωκέναι τὴν τοῦ σώματος ἀκμὴν εἰς τοῦτο χάριν οὐκ ἔχει πρὸς τὸν δῆμον, ἀλλὰ κραιπαλῶντες ἄνθρωποι ναῦται καὶ ἀμαθεῖς ἀκούονται καὶ κατέχουσι τὸ βῆμα, παρορᾶται δ’ αὐτός, ἀληθῆ λέγεις, ὦ Δημόσθενες, φάναι τὸν Σάτυρον, ἀλλ’ ἐγὼ τὸ αἴτιον ἰάσομαι ταχέως, ἄν μοι τῶν Εὐριπίδου τινὰ ῥήσεων ἢ Σοφοκλέους ἐθελήσῃς εἰπεῖν ἀπὸ στόματος. εἰπόντος δὲ τοῦ Δημοσθένους μεταλαβόντα τὸν Σάτυρον οὕτω πλάσαι καὶ διεξελθεῖν ἐν ἤθει πρέποντι καὶ διαθέσει τὴν αὐτὴν ῥῆσιν ὥσθ’ ὅλως ἑτέραν τῷ Δημοσθένει φανῆναι. πεισθέντα δ’ ὅσον ἐκ τῆς ὑποκρίσεως τῷ λόγῳ κόσμου καὶ χάριτος πρόσεστι, μικρὸν ἡγήσασθαι καὶ τὸ μηδὲν εἶναι τὴν ἄσκησιν ἀμελοῦντι τῆς προφορᾶς καὶ διαθέσεως τῶν λεγομένων. ἐκ τούτου κατάγειον μὲν οἰκοδομῆσαι μελετητήριον, ὃ δὴ διεσῴζετο καὶ καθ’ ἡμᾶς, ἐνταῦθα δὲ πάντως μὲν ἑκάστης ἡμέρας κατιόντα πλάττειν τὴν ὑπόκρισιν καὶ διαπονεῖν τὴν φωνήν, πολλάκις δὲ καὶ μῆνας ἑξῆς δύο καὶ τρεῖς συνάπτειν, ξυρούμενον τῆς κεφαλῆς θάτερον μέρος ὑπὲρ τοῦ μηδὲ βουλομένῳ πάνυ προελθεῖν ἐνδέχεσθαι δι’ αἰσχύνην.", "st": "Dem. 7.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ τάς πρὸς τοὺς ἐκτὸς ἐντεύξεις καὶ λόγους καὶ ἀσχολίας ὑποθέσεις ἐποιεῖτο καὶ ἀφορμὰς τοῦ φιλοπονεῖν. ἀπαλλαγεὶς γὰρ αὐτῶν τάχιστα κατέβαινεν εἰς τὸ μελετητήριον, καὶ διεξῄει τάς τε πράξεις ἐφεξῆς καὶ τοὺς ὑπὲρ αὐτῶν ἀπολογισμούς, ἔτι δὲ τοὺς λόγους οἷς παρέτυχε λεγομένοις, ἀναλαμβάνων εἰς ἑαυτὸν εἰς γνώμας ἀνῆγε καὶ περιόδους, ἐπανορθώσεις τε παντοδαπὰς καὶ μεταφράσεις ἐκαινοτόμει τῶν εἰρημένων ὑφ’ ἑτέρου πρὸς ἑαυτὸν ἢ ὑφ’ αὐτοῦ πάλιν πρὸς ἄλλον, ἐκ τούτου δόξαν εἶχεν ὡς οὐκ εὐφυὴς ὤν, ἀλλ’ ἐκ πόνου συγκειμένῃ δεινότητι καὶ δυνάμει χρώμενος. ἐδόκει τε τούτου σημεῖον εἶναι μέγα τὸ μὴ ῥᾳδίως ἀκοῦσαί τινα Δημοσθένους ἐπὶ καιροῦ λέγοντος, ἀλλὰ καὶ καθήμενον ἐν ἐκκλησίᾳ πολλάκις τοῦ δήμου καλοῦντος ὀνομαστὶ μὴ παρελθεῖν, εἰ μὴ τύχοι πεφροντικὼς καὶ παρεσκευασμένος. εἰς τοῦτο δὲ ἄλλοι τε πολλοὶ τῶν δημαγωγῶν ἐχλεύαζον αὐτόν, καὶ Πυθέας ἐπισκώπτων ἐλλυχνίων ἔφησεν ὄζειν αὐτοῦ τὰ ἐνθυμήματα. τοῦτον μὲν οὖν ἠμείψατο πικρῶς ὁ Δημοσθένης· οὐ ταὐτά γὰρ, εἶπεν, ἐμοὶ καὶ σοὶ, ὦ Πυθέα, ὁ λύχνος σύνοιδε. πρὸς δὲ τοὺς ἄλλους οὐ παντάπασιν ἦν ἔξαρνος, ἀλλ’ οὔτε γράψας οὔτ’ ἄγραφα κομιδῇ λέγειν ὡμολόγει. καὶ μέντοι δημοτικὸν ἀπέφαινεν ἄνδρα τὸν λέγειν μελετῶντα· θεραπείας γὰρ εἶναι τοῦτο δήμου παρασκευήν, τὸ δ’ ὅπως ἕξουσιν οἱ πολλοὶ πρὸς τὸν λόγον ἀφροντιστεῖν ὀλιγαρχικοῦ καὶ βίᾳ, μᾶλλον ἢ πειθοῖ προσέχοντος. τῆς δὲ πρὸς καιρὸν ἀτολμίας αὐτοῦ καὶ τοῦτο ποιοῦνται σημεῖον, ὅτι Δημάδης μὲν ἐκείνῳ θορυβηθέντι πολλάκις ἀναστὰς ἐκ προχείρου συνεῖπεν, ἐκεῖνος δ’ οὐδέποτε Δημάδῃ.", "st": "Dem. 8.1"}, {"sp": "N", "t": "πόθεν οὖν, φαίη τις ἄν, ὁ Αἰσχίνης πρὸς τὴν ἐν τοῖς λόγοις τόλμαν θαυμασιώτατον ἀπεκάλει τὸν ἄνδρα; πῶς δὲ Πύθωνι τῷ Βυζαντίῳ θρασυνομένῳ καὶ ῥέοντι πολλῷ κατὰ τῶν Ἀθηναίων ἀναστὰς μόνος ἀντεῖπεν, ἢ Λαμάχου τοῦ Μυρναίου γεγραφότος ἐγκώμιον Ἀλεξάνδρου καὶ Φιλίππου τῶν βασιλέων, ἐν ᾧ πολλὰ Θηβαίους καὶ Ὀλυνθίους εἰρήκει κακῶς, καὶ ἀναγινώσκοντος Ὀλυμπίασι, παραστὰς καὶ διεξελθὼν μεθ’ ἱστορίας καὶ ἀποδείξεως ὅσα Θηβαίοις καὶ Χαλκιδεῦσιν ὑπάρχει καλὰ πρὸς τὴν Ἑλλάδα, καὶ πάλιν ὅσων αἴτιοι γεγόνασι κακῶν οἱ κολακεύοντες Μακεδόνας, οὕτως ἐπέστρεψε τοὺς παρόντας ὥστε δείσαντα τῷ θορύβῳ τὸν σοφιστὴν ὑπεκδῦναι τῆς πανηγύρεως;", "st": "Dem. 9.1"}, {"sp": "N", "t": "ἀλλ’ ἔοικεν ὁ ἀνὴρ τοῦ Περικλέους τὰ μέν ἄλλα μὴ πρὸς αὑτὸν ἡγήσασθαι, τὸ δὲ πλάσμα καὶ τὸν σχηματισμὸν αὐτοῦ καὶ τὸ μὴ ταχέως μηδὲ περὶ παντὸς ἐκ τοῦ παρισταμένου λέγειν, ὥσπερ ἐκ τούτων μεγάλου γεγονότος, ζηλῶν καὶ μιμούμενος, οὐ πάνυ προσίεσθαι τὴν ἐν τῷ καιρῷ δόξαν, οὐδ’ ἐπὶ τύχῃ πολλάκις ἑκὼν εἶναι ποιεῖσθαι τὴν δύναμιν. ἐπεὶ τόλμαν γε καὶ θάρσος οἱ λεχθέντες ὑπ’ αὐτοῦ λόγοι τῶν γραφέντων μᾶλλον εἶχον, εἴ τι δεῖ πιστεύειν Ἐρατοσθένει καὶ Δημητρίῳ τῷ Φαληρεῖ καὶ τοῖς κωμικοῖς. ὧν Ἐρατοσθένης μέν φησὶν αὑτὸν ἐν τοῖς λόγοις πολλαχοῦ γεγονέναι παράβακχον, ὁ δὲ Φαληρεὺς τὸν ἔμμετρον ἐκεῖνον ὅρκον ὀμόσαι ποτὲ πρὸς τὸν δῆμον ὥσπερ ἐνθουσιῶντα", "st": "Dem. 9.2"}, {"sp": "N", "t": "μὰ γῆν, μὰ κρήνας, μὰ ποταμούς, μὰ νάματα.", "st": "Dem. 9.2b"}, {"sp": "N", "t": "τῶν δὲ κωμικῶν ὁ μέν τις αὑτὸν ἀποκαλεῖ ῥωποπερπερήθραν, ὁ δὲ παρασκώπτων ὡς χρώμενον τῷ ἀντιθέτῳ φησὶν οὕτως·", "st": "Dem. 9.5"}, {"sp": "N", "t": "Α. ἀπέλαβεν ὥσπερ ἔλαβεν.", "st": "Dem. 9.5b"}, {"sp": "N", "t": "Β. ἠγάπησεν ἂν<br>τὸ ῥῆμα τοῦτο παραλαβὼν Δημοσθένης.", "st": "Dem. 9.5c"}, {"sp": "N", "t": "ἐκτὸς εἰ μὴ νὴ Δία πρὸς τὸν ὑπὲρ Ἁλοννήσου λόγον ὁ Ἀντιφάνης καὶ τουτὶ πέπαιχεν, ἣν Ἀθηναίοις Δημοσθένης συνεβούλευε μὴ λαμβάνειν, ἀλλ’ ἀπολαμβάνειν παρὰ Φιλίππου.", "st": "Dem. 9.6"}, {"sp": "N", "t": "πλὴν τόν γε Δημάδην πάντες ὡμολόγουν τῇ φύσει χρώμενον ἀνίκητον εἶναι, καὶ παραφέρειν αὐτοσχεδιάζοντα τὰς τοῦ Δημοσθένους σκέψεις καὶ παρασκευάς. ἀρίστων δ’ ὁ Χῖος καὶ Θεοφράστου τινὰ δόξαν ἱστόρηκε περὶ τῶν ῥητόρων, ἐρωτηθέντα γὰρ ὁποῖος τις αὐτῷ φαίνεται ῥήτωρ ὁ Δημοσθένης, εἰπεῖν· ἄξιος τῆς πόλεως· ὁποῖος δέ Δημάδης, ὑπὲρ τὴν πόλιν. ὁ δ’ αὐτὸς φιλόσοφος Πολύευκτον ἱστορεῖ τόν Σφήττιον, ἕνα τῶν τότε πολιτευομένων Ἀθήνησιν, ἀποφαίνεσθαι μέγιστον μὲν εἶναι ῥήτορα Δημοσθένην, δυνατώτατον δὲ εἰπεῖν Φωκίωνα· πλεῖστον γὰρ ἐν βραχυτάτῃ λέξει νοῦν ἐκφέρειν. καὶ μέντοι καὶ τόν Δημοσθένην φασὶν αὐτόν, ὁσάκις ἂν ἀντερῶν αὐτῷ Φωκίων ἀναβαίνοι, λέγειν πρὸς τοὺς συνήθεις· ἡ τῶν ἐμῶν λόγων κοπὶς ἀνίσταται. τοῦτο μὲν οὖν ἄδηλον εἴτε πρὸς τόν λόγον τοῦ ἀνδρὸς ὁ Δημοσθένης εἴτε πρὸς τόν βίον καὶ τὴν δόξαν ἐπεπόνθει, πολλῶν πάνυ καὶ μακρῶν περιόδων ἓν ῥῆμα καὶ νεῦμα πίστιν ἔχοντος ἀνθρώπου κυριώτερον ἡγούμενος.", "st": "Dem. 10.1"}, {"sp": "N", "t": "τοῖς δὲ σωματικοῖς ἐλαττώμασι τοιαύτην ἐπῆγεν ἄσκησιν, ὡς ὁ Φαληρεύς Δημήτριος ἱστορεῖ, λέγων αὐτοῦ Δημοσθένους ἀκούειν πρεσβύτου γεγονότος, τὴν μὲν ἀσάφειαν καὶ τραυλότητα τῆς γλώττης ἐκβιάζεσθαι καὶ διαρθροῦν εἰς τὸ στόμα ψήφους λαμβάνοντα καὶ ῥήσεις ἅμα λέγοντα, τὴν δὲ φωνὴν ἐν τοῖς δρόμοις γυμνάζεσθαι καὶ ταῖς πρὸς τὰ σιμὰ προσβάσεσι διαλεγόμενον καὶ λόγους τινὰς ἢ στίχους ἅμα τῷ πνεύματι πυκνουμένῳ προφερόμενον εἶναι δ’ αὐτῷ μέγα κάτοπτρον οἴκοι, καὶ πρὸς τοῦτο τὰς μελέτας ἐξ ἐναντίας ἱστάμενον περαίνειν.", "st": "Dem. 11.1"}, {"sp": "N", "t": "λέγεται δέ, ἀνθρώπου προσελθόντος δεομένου συνηγορίας καὶ διεξιόντος ὡς ὑπό του λάβοι πληγάς, ἀλλὰ σύ γε, φάναι τὸν Δημοσθένην, τούτων ὧν λέγεις οὐδὲν πέπονθας. ἐπιτείναντος δὲ τὴν φωνὴν τοῦ ἀνθρώπου καὶ βοῶντος ἐγὼ, Δημόσθενες, οὐδὲν πέπονθα; νὴ Δία, φάναι, νῦν ἀκούω φωνὴν ἀδικουμένου καὶ πεπονθότος. οὕτως ᾤετο μέγα πρὸς πίστιν εἶναι τὸν τόνον καὶ τὴν ὑπόκρισιν τῶν λεγόντων, τοῖς μὲν οὖν πολλοῖς ὑποκρινόμενος ἤρεσκε θαυμαστῶς, οἱ δὲ χαρίεντες ταπεινὸν ἡγοῦντο καὶ ἀγεννὲς αὐτοῦ τὸ πλάσμα καὶ μαλακόν, ὧν καὶ Δημήτριος ὁ Φαληρεύς ἐστιν. Αἰσίωνα δέ φησιν Ἕρμιππος, ἐρωτηθέντα περὶ τῶν πάλαι ῥητόρων καὶ τῶν καθ’ αὑτὸν, εἰπεῖν ὡς ἀκούων μὲν ἄν τις ἐθαύμασεν ἐκείνους εὐκόσμως καὶ μεγαλοπρεπῶς τῷ δήμῳ διαλεγομένους, ἀναγινωσκόμενοι δ’ οἱ Δημοσθένους λόγοι πολὺ τῇ κατασκευῇ καὶ δυνάμει διαφέρουσιν. οἱ μὲν οὖν γεγραμμένοι τῶν λόγων ὅτι τὸ αὐστηρὸν πολὺ καὶ πικρὸν ἔχουσι, τί ἂν λέγοι τις; ἐν δὲ ταῖς ἀπαντήσεσι ταῖς παρὰ τὸν καιρὸν ἐχρῆτο καὶ τῷ γελοίῳ. Δημάδου μὲν γὰρ εἰπόντος ἐμὲ Δημοσθένης, ἡ ὗς τὴν Ἀθηνᾶν, αὕτη, εἶπεν, ἡ Ἀθηνᾶ πρώην ἐν Κολλυτῷ μοιχεύουσα ἐλήφθη. πρὸς δὲ τὸν κλέπτην ὃς ἐπεκαλεῖτο Χαλκοῦς, καὶ αὐτὸν εἰς τὰς ἀγρυπνίας αὐτοῦ καὶ νυκτογραφίας πειρώμενόν τι λέγειν, οἶδα, εἶπεν, ὅτι σε λυπῶ λύχνον καίων. ὑμεῖς δέ, ὦ ἄνδρες Ἀθηναῖοι, μὴ θαυμάζετε τὰς γινομένας κλοπάς, ὅταν τοὺς μὲν κλέπτας χαλκοῦς, τοὺς δὲ τοίχους πηλίνους ἔχωμεν. ἀλλὰ περὶ μὲν τούτων καίπερ ἔτι πλείω λέγειν ἔχοντες ἐνταῦθα παυσόμεθα· τὸν δ’ ἄλλον αὐτοῦ τρόπον καὶ τὸ ἦθος ἀπὸ τῶν πράξεων καὶ τῆς πολιτείας θεωρεῖσθαι δίκαιόν ἐστιν.", "st": "Dem. 11.2"}, {"sp": "N", "t": "ὥρμησε μὲν οὖν ἐπὶ τὸ πράττειν τὰ κοινὰ τοῦ Φωκικοῦ πολέμου συνεστῶτος, ὡς αὐτός τέ φησι καὶ λαβεῖν ἔστιν ἀπὸ τῶν Φιλιππικῶν δημηγοριῶν. αἱ μὲν γὰρ ἤδη διαπεπραγμένων ἐκείνων γεγόνασιν, αἱ δὲ πρεσβύταται τῶν ἔγγιστα πραγμάτων ἅπτονται. δῆλος δ’ ἐστὶ καὶ τὴν κατὰ Μειδίου παρασκευασάμενος εἰπεῖν δίκην δύο μὲν ἐπὶ τοῖς τριάκοντα γεγονὼς ἔτη, μηδέπω δ’ ἔχων ἰσχὺν ἐν τῇ πολιτείᾳ μηδὲ δόξαν. ὃ καὶ μάλιστά μοι δοκεῖ δείσας ἐπ’ ἀργυρίῳ καταθέσθαι τὴν πρὸς τὸν ἄνθρωπον ἔχθραν", "st": "Dem. 12.1"}, {"sp": "N", "t": "οὐ γάρ τι γλυκύθυμος ἀνὴρ ἦν οὐδ’ ἀγανόφρων,", "st": "Dem. 12.1b"}, {"sp": "N", "t": "ἀλλ’ ἔντονος καὶ βίαιος ὑπὲρ τὰς ἀμύνας, ὁρῶν δ’ οὐ φαῦλον οὐδὲ τῆς αὐτοῦ δυνάμεως ἔργον ἄνδρα καὶ πλούτῳ καὶ λόγῳ καὶ φίλοις εὖ πεφραγμένον καθελεῖν, τὸν Μειδίαν, ἐνέδωκε τοῖς ὑπὲρ αὐτοῦ δεομένοις. αἱ δὲ τρισχίλιαι καθ’ ἑαυτὰς οὐκ ἄν μοι δοκοῦσι τὴν Δημοσθένους ἀμβλῦναι πικρίαν, ἐλπίζοντος καὶ δυναμένου περιγενέσθαι.", "st": "Dem. 12.1c"}, {"sp": "N", "t": "λαβὼν δὲ τῆς πολιτείας καλὴν ὑπόθεσιν τὴν πρὸς Φίλιππον ὑπὲρ τῶν Ἑλλήνων δικαιολογίαν, καὶ πρὸς ταύτην ἀγωνιζόμενος ἀξίως, ταχὺ δόξαν ἔσχε καὶ περίβλεπτος ὑπὸ τῶν λόγων ἤρθη καὶ τῆς παρρησίας, ὥστε θαυμάζεσθαι μὲν ἐν τῇ Ἑλλάδι, θεραπεύεσθαι δ’ ὑπὸ τοῦ μεγάλου βασιλέως, πλεῖστον δ’ αὐτοῦ λόγον εἶναι παρὰ τῷ Φιλίππῳ τῶν δημαγωγούντων, ὁμολογεῖν δὲ καὶ τοὺς ἀπεχθανομένους ὅτι πρὸς ἔνδοξον αὐτοῖς ἄνθρωπον ὁ ἀγών ἐστι. καὶ γὰρ Αἰσχίνης καὶ Ὑπερείδης τοιαῦτα ὑπὲρ αὐτοῦ κατηγοροῦντες εἰρήκασιν.", "st": "Dem. 12.7"}, {"sp": "N", "t": "ὅθεν οὐκ οἶδ’ ὅπως παρέστη Θεοπόμπῳ λέγειν αὐτὸν ἀβέβαιον τῷ τρόπῳ γεγονέναι καὶ μήτε πράγμασι μήτ’ ἀνθρώποις πολὺν χρόνον τοῖς αὐτοῖς ἐπιμένειν δυνάμενον. φαίνεται γάρ, εἰς ἣν ἀπ’ ἀρχῆς τῶν πραγμάτων μερίδα καὶ τάξιν αὑτὸν ἐν τῇ πολιτείᾳ κατέστησε, ταύτην ἄχρι τέλους διαφυλάξας, καὶ οὐ μόνον ἐν τῷ βίῳ μὴ μεταβαλόμενος, ἀλλὰ καὶ τὸν βίον ἐπὶ τῷ μὴ μεταβαλέσθαι προέμενος. οὐ γάρ, ὡς Δημάδης ἀπολογούμενος διὰ τὴν ἐν τῇ πολιτείᾳ μεταβολὴν ἔλεγεν, αὑτῷ μὲν αὐτὸν τἀναντία πολλάκις εἰρηκέναι, τῇ δὲ πόλει μηδέποτε, καὶ Μελάνωπος ἀντιπολιτευόμενος Καλλιστράτῳ καὶ πολλάκις ὑπ’ αὐτοῦ χρήμασι μετατιθέμενος εἰώθει λέγειν πρὸς τὸν δῆμον· ὁ μὲν ἀνὴρ ἐχθρός, τὸ δὲ τῆς πόλεως νικάτω συμφέρον, Νικόδημος δ’ ὁ Μεσσήνιος Κασάνδρῳ προστιθέμενος πρότερον, εἶτ’ αὖθις ὑπὲρ Δημητρίου πολιτευόμενος οὐκ ἔφη τἀναντία λέγειν, ἀεὶ γὰρ εἶναι συμφέρον ἀκροᾶσθαι τῶν κρατούντων, οὕτω καὶ περὶ Δημοσθένους ἔχομεν εἰπεῖν οἷον ἐκτρεπομένου καὶ πλαγιάζοντος ἢ φωνὴν ἢ πρᾶξιν, ἀλλ’ ὥσπερ ἀφ’ ἑνὸς καὶ ἀμεταβλήτου διαγράμματος τῆς πολιτείας ἕνα τόνον ἔχων ἐν τοῖς πράγμασιν ἀεὶ διετέλεσε. Παναίτιος δ’ ὁ φιλόσοφος καὶ τῶν λόγων αὐτοῦ φησιν οὕτω γεγράφθαι τοὺς πλείστους ὡς μόνου τοῦ καλοῦ δι’ αὐτὸ αἱρετοῦ ὄντος, τὸν περὶ τοῦ στεφάνου, τὸν κατὰ Ἀριστοκράτους, τὸν ὑπὲρ τῶν ἀτελειῶν, τοὺς Φιλιππικούς· ἐν οἷς πᾶσιν οὐ πρὸς τὸ ἥδιστον ἢ ῥᾷστον ἢ λυσιτελέστατον ἄγει τοὺς πολίτας, ἀλλὰ πολλαχοῦ τὴν ἀσφάλειαν καὶ τὴν σωτηρίαν οἴεται δεῖν ἐν δευτέρᾳ τάξει τοῦ καλοῦ ποιεῖσθαι καὶ τοῦ πρέποντος, ὡς, εἴγε τῇ περὶ τὰς ὑποθέσεις αὐτοῦ φιλοτιμίᾳ καὶ τῇ τῶν λόγων εὐγενείᾳ παρῆν ἀνδρεία τε πολεμιστήριος καὶ τὸ καθαρῶς ἕκαστα πράττειν, οὐκ ἐν τῷ κατὰ Μοιροκλέα καὶ Πολύευκτον καὶ Ὑπερείδην ἀριθμῷ τῶν ῥητόρων, ἀλλ’ ἄνω μετὰ Κίμωνος καὶ Θουκυδίδου καὶ Περικλέους ἄξιος ἦν τίθεσθαι.", "st": "Dem. 13.1"}, {"sp": "N", "t": "τῶν γοῦν κατ’ αὑτὸν ὁ Φωκίων οὐκ ἐπαινουμένης προϊστάμενος πολιτείας, ἀλλὰ δοκῶν μακεδονίζειν, ὅμως δι’ ἀνδρείαν καὶ δικαιοσύνην οὐδὲν οὐδαμῇ χείρων ἔδοξεν Ἐφιάλτου καὶ Ἀριστείδου καὶ Κίμωνος ἀνὴρ γενέσθαι. Δημοσθένης δ’ οὐκ ὢν ἐν τοῖς ὅπλοις ἀξιόπιστος, ὥς φησιν ὁ Δημήτριος, οὐδὲ πρὸς τὸ λαμβάνειν παντάπασιν ἀπωχυρωμένος, ἀλλὰ τῷ μὲν παρὰ Φιλίππου καὶ Μακεδονίας ἀνάλωτος ὤν, τῷ δ’ ἄνωθεν ἐκ Σούσων καὶ Ἐκβατάνων ἐπιβατὸς χρυσίῳ γεγονὼς καὶ κατακεκλυσμένος, ἐπαινέσαι μὲν ἱκανώτατος ἦν τὰ τῶν προγόνων καλά, μιμήσασθαι δὲ οὐχ ὁμοίως. ἐπεὶ τούς γε καθ’ αὑτὸν ῥήτορας ἔξω δὲ λόγου τίθεμαι Φωκίωνα καὶ τῷ βίῳ παρῆλθε. φαίνεται δὲ καὶ μετὰ παρρησίας μάλιστα τῷ δήμῳ διαλεγόμενος καὶ πρὸς τὰς ἐπιθυμίας τῶν πολλῶν ἀντιτείνων καὶ τοῖς ἁμαρτήμασιν αὐτῶν ἐπιφυόμενος, ὡς ἐκ τῶν λόγων λαβεῖν ἔστιν, ἱστορεῖ δὲ καὶ Θεόπομπος ὅτι, τῶν Ἀθηναίων ἐπί τινα προβαλλομένων αὑτὸν κατηγορίαν, ὡς δ’ οὐχ ὑπήκουε, θορυβούντων, ἀναστὰς εἶπεν· ὑμεῖς ἐμοὶ, ὦ ἄνδρες Ἀθηναῖοι, συμβούλῳ μέν, κἂν μὴ θέλητε, χρήσεσθε· συκοφάντῃ δὲ οὐδὲ ἂν θέλητε. σφόδρα δ’ ἀριστοκρατικὸν αὐτοῦ πολίτευμα καὶ τὸ περὶ Ἀντιφῶντος· ὃν ὑπὸ τῆς ἐκκλησίας ἀφεθέντα συλλαβὼν ἐπὶ τὴν ἐξ Ἀρείου πάγου βουλὴν ἀνήγαγε, καὶ παρ’ οὐδὲν τὸ προσκροῦσαι τῷ δήμῳ θέμενος ἤλεγξεν ὑπεσχημένον Φιλίππῳ τὰ νεώρια ἐμπρήσειν καὶ παραδοθεὶς ὁ ἄνθρωπος ὑπὸ τῆς βουλῆς ἀπέθανε, κατηγόρησε δὲ καὶ τῆς ἱερείας Θεωρίδος ὡς ἄλλα τε ῥᾳδιουργούσης πολλὰ καὶ τοὺς δούλους ἐξαπατᾶν διδασκούσης· καὶ θανάτου τιμησάμενος ἀπέκτεινε.", "st": "Dem. 14.1"}, {"sp": "N", "t": "λέγεται δὲ καὶ τὸν κατὰ Τιμοθέου τὸν στρατηγοῦ λόγον, ᾧ χρησάμενος Ἀπολλόδωρος εἷλε τὸν ἄνδρα τοῦ ὀφλήματος, Δημοσθένης γράψαι τῷ Ἀπολλοδώρῳ, καθάπερ καὶ τοὺς πρὸς Φορμίωνα καὶ Στέφανον, ἐφ’ οἷς εἰκότως ἠδόξησε. καὶ γὰρ ὁ Φορμίων ἠγωνίζετο λόγῳ Δημοσθένους πρὸς τὸν Ἀπολλόδωρον, ἀτεχνῶς καθάπερ ἐξ ἑνὸς μαχαιροπωλίου τὰ κατ’ ἀλλήλων ἐγχειρίδια πωλοῦντος αὐτοῦ τοῖς ἀντιδίκοις. τῶν δὲ δημοσίων ὁ μὲν κατ’ Ἀνδροτίωνος καὶ Τιμοκράτους καὶ Ἀριστοκράτους ἑτέροις ἐγράφησαν, οὔπω τῇ πολιτείᾳ προσεληλυθότος· δοκεῖ γὰρ δυεῖν ἢ τριῶν δέοντα ἔτη τριάκοντα γεγονὼς ἐξενεγκεῖν τοὺς λόγους ἐκείνους· τὸν δὲ κατὰ Ἀριστογείτονος αὐτὸς ἠγωνίσατο, καὶ τὸν περὶ τῶν ἀτελειῶν, διὰ τὸν Χαβρίου παῖδα Κτήσιππον, ὥς φησὶν αὐτός, ὡς δ’ ἔνιοι λέγουσι, τὴν μητέρα τοῦ νεανίσκου μνώμενος. οὐ μὴν ἔγημε ταύτην, ἀλλὰ Σαμίᾳ τινὶ συνῴκησεν, ὡς ἱστορεῖ Δημήτριος ὁ Μάγνης ἐν τοῖς περὶ συνωνύμων. ὁ δὲ κατ’ Αἰσχίνου τῆς παραπρεσβείας ἄδηλον εἰ λέλεκται· καίτοι φησὶν Ἰδομενεὺς παρὰ τριάκοντα μόνας τὸν Αἰσχίνην ἀποφυγεῖν. ἀλλ’ οὐκ ἔοικεν οὕτως ἔχειν τἀληθές, εἰ δεῖ τοῖς περὶ στεφάνου γεγραμμένοις ἑκατέρων λόγοις τεκμαίρεσθαι. μέμνηται γὰρ οὐδέτερος αὐτῶν ἐναργῶς οὐδὲ τρανῶς ἐκείνου τοῦ ἀγῶνος ὡς ἄχρι δίκης προελθόντος. ταυτὶ μὲν οὖν ἕτεροι διακρινοῦσι μᾶλλον.", "st": "Dem. 15.1"}, {"sp": "N", "t": "ἡ δὲ τοῦ Δημοσθένους πολιτεία φανερὰ μὲν ἦν ἔτι καὶ τῆς εἰρήνης ὑπαρχούσης, οὐδὲν ἐῶντος ἀνεπιτίμητον τῶν πραττομένων ὑπὸ τοῦ Μακεδόνος, ἀλλ’ ἐφ’ ἑκάστῳ ταράττοντος τοὺς Ἀθηναίους καὶ διακαίοντος ἐπὶ τὸν ἄνθρωπον. διὸ καὶ παρὰ Φιλίππῳ πλεῖστος ἦν λόγος αὐτοῦ· καὶ ὅτε πρεσβεύων δέκατος ἧκεν εἰς Μακεδονίαν, ἤκουσε μὲν πάντων Φίλιππος, ἀντεῖπε δὲ μετὰ πλείστης ἐπιμελείας πρὸς τὸν ἐκείνου λόγον. οὐ μὴν ἔν γε ταῖς ἄλλαις τιμαῖς καὶ φιλοφροσύναις ὅμοιον αὑτὸν τῷ Δημοσθένει παρεῖχεν, ἀλλὰ προσήγετο τοὺς περὶ Αἰσχίνην καὶ Φιλοκράτην μᾶλλον. ὅθεν ἐπαινούντων ἐκείνων τὸν Φίλιππον ὡς καὶ λέγειν δυνατώτατον καὶ κάλλιστον ὀφθῆναι καὶ νὴ Δία συμπιεῖν ἱκανώτατον, ἠναγκάζετο βασκαίνων ἐπισκώπτειν ὡς τὸ μὲν σοφιστοῦ, τὸ δὲ γυναικός, τὸ δὲ σπογγιᾶς εἴη, βασιλέως δ’ οὐδὲν ἐγκώμιον.", "st": "Dem. 16.1"}, {"sp": "N", "t": "ἐπεὶ δ’ εἰς τὸ πολεμεῖν ἔρρεπε τὰ πράγματα, τοῦ μὲν Φιλίππου μὴ δυναμένου τὴν ἡσυχίαν ἄγειν, τῶν δ’ Ἀθηναίων ἐγειρομένων ὑπὸ τοῦ Δημοσθένους, πρῶτον μὲν εἰς Εὔβοιαν ἐξώρμησε τοὺς Ἀθηναίους καταδεδουλωμένην ὑπὸ τῶν τυράννων Φιλίππῳ· καί διαβάντες, ἐκείνου τὸ ψήφισμα γράψαντος, ἐξήλασαν τοὺς Μακεδόνας. δεύτερον δὲ Βυζαντίοις ἐβοήθησε καί Περινθίοις ὑπὸ τοῦ Μακεδόνος πολεμουμένοις, πείσας τὸν δῆμον ἀφέντα τὴν ἔχθραν καί τὸ μεμνῆσθαι τῶν περὶ τὸν συμμαχικὸν ἡμαρτημένων ἑκατέροις πόλεμον ἀποστεῖλαι δύναμιν αὐτοῖς, ὑφ’ ἧς ἐσώθησαν. ἔπειτα πρεσβεύων καί διαλεγόμενος τοῖς Ἕλλησι καί παροξύνων συνέστησε πλὴν ὀλίγων ἅπαντας ἐπὶ τὸν Φίλιππον, ὥστε σύνταξιν γενέσθαι πεζῶν μὲν μυρίων καί πεντακισχιλίων, ἱππέων δὲ δισχιλίων, ἄνευ τῶν πολιτικῶν δυνάμεων, χρήματα δὲ καί μισθοὺς τοῖς ξένοις εἰσφέρεσθαι προθύμως. ὅτε καί φησι Θεόφραστος, ἀξιούντων τῶν συμμάχων ὁρισθῆναι τὰς εἰσφοράς, εἰπεῖν Κρωβύλον τὸν δημαγωγόν ὡς οὐ τεταγμένα σιτεῖται πόλεμος.", "st": "Dem. 17.1"}, {"sp": "N", "t": "ἐπηρμένης δὲ τῆς Ἑλλάδος πρὸς τὸ μέλλον καί συνισταμένων κατ’ ἔθνη καί πόλεις Εὐβοέων, Ἀχαιῶν, Κορινθίων, Μεγαρέων, Λευκαδίων, Κερκυραίων, ὁ μέγιστος ὑπελείπετο τῷ Δημοσθένει τῶν ἀγώνων, Θηβαίους προσαγαγέσθαι τῇ συμμαχίᾳ, χώραν τε σύνορον τῆς Ἀττικῆς καί δύναμιν ἐναγώνιον ἔχοντας, καί μάλιστα τότε τῶν Ἑλλήνων εὐδοκιμοῦντας ἐν τοῖς ὅπλοις. ἦν δ’ οὐ ῥᾴδιον ἐπὶ προσφάτοις εὐεργετήμασι τοῖς περὶ τὸν Φωκικὸν πόλεμον τετιθασευμένους ὑπὸ τοῦ Φιλίππου μεταστῆσαι τοὺς Θηβαίους, καί μάλιστα ταῖς διὰ τὴν γειτνίασιν ἁψιμαχίαις ἀναξαινομένων ἑκάστοτε τῶν πολεμικῶν πρὸς ἀλλήλας διαφορῶν ταῖς πόλεσιν.", "st": "Dem. 17.5"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἐπεὶ Φίλιππος ὑπὸ τῆς περὶ τὴν Ἄμφισσαν εὐτυχίας ἐπαιρόμενος εἰς τὴν Ἐλάτειαν ἐξαίφνης ἐνέπεσε καὶ τὴν Φωκίδα κατέσχεν, ἐκπεπληγμένων τῶν Ἀθηναίων καὶ μηδενὸς τολμῶντος ἀναβαίνειν ἐπὶ τὸ βῆμα μηδὲ ἔχοντος ὅ τι χρὴ λέγειν, ἀλλ’ ἀπορίας οὔσης ἐν μέσῳ καὶ σιωπῆς, παρελθὼν μόνος ὁ Δημοσθένης συνεβούλευε τῶν Θηβαίων ἔχεσθαι· καὶ τἆλλα παραθαρρύνας καὶ μετεωρίσας, ὥσπερ εἰώθει, τὸν δῆμον ταῖς ἐλπίσιν, ἀπεστάλη πρεσβευτὴς μεθ’ ἑτέρων εἰς Θήβας. ἔπεμψε δὲ καὶ Φίλιππος, ὡς Μαρσύας φησίν, Ἀμύνταν μὲν καὶ Κλέαρχον Μακεδόνας, Δάοχον δὲ Θεσσαλὸν καὶ Θρασυδαῖον ἀντεροῦντας.", "st": "Dem. 18.1"}, {"sp": "N", "t": "τὸ μὲν οὖν συμφέρον οὐ διέφευγε τοὺς τῶν Θηβαίων λογισμούς, ἀλλ’ ἐν ὄμμασιν ἕκαστος εἶχε τὰ τὸν πολέμου δεινά, ἔτι τῶν Φωκικῶν τραυμάτων νεαρῶν παραμενόντων· ἡ δὲ τὸν ῥήτορος δύναμις, ὥς φησι Θεόπομπος, ἐκριπίζουσα τὸν θυμὸν αὐτῶν καὶ διακαίουσα τὴν φιλοτιμίαν ἐπεσκότησε τοῖς ἄλλοις ἅπασιν, ὥστε καὶ φόβον καὶ λογισμὸν καὶ χάριν ἐκβαλεῖν αὐτούς ἐνθουσιῶντας ὑπὸ τοῦ λόγου πρὸς τὸ καλόν, οὕτω δὲ μέγα καὶ λαμπρὸν ἐφάνη τὸ τοῦ ῥήτορος ἔργον ὥστε τὸν μὲν Φίλιππον εὐθὺς ἐπικηρυκεύεσθαι δεόμενον εἰρήνης, ὀρθὴν δὲ τὴν Ἑλλάδα γενέσθαι καὶ συνεξαναστῆναι πρὸς τὸ μέλλον, ὑπηρετεῖν δὲ μὴ μόνον τοὺς στρατηγοὺς τῷ Δημοσθένει ποιοῦντας τὸ προσταττόμενον, ἀλλὰ καὶ τοὺς βοιωτάρχας, διοικεῖσθαι δὲ τὰς ἐκκλησίας ἁπάσας οὐδὲν ἧττον ὑπ’ ἐκείνου τότε τὰς Θηβαίων ἢ τὰς Ἀθηναίων, ἀγαπωμένου παρ’ ἀμφοτέροις καὶ δυναστεύοντος οὐκ ἀδίκως οὐδὲ παρ’ ἀξίαν, ὥσπερ ἀποφαίνεται Θεόπομπος, ἀλλὰ καὶ πάνυ προσηκόντως.", "st": "Dem. 18.1b"}, {"sp": "N", "t": "τύχη δέ τις ἔοικε δαιμόνιος ἐν περιφορὰ πραγμάτων, εἰς ἐκεῖνο καιροῦ συμπεραίνουσα τὴν ἐλευθερίαν τῆς Ἑλλάδος, ἐναντιοῦσθαι τοῖς πραττομένοις, καὶ πολλὰ σημεῖα τοῦ μέλλοντος ἀναφαίνειν, ἐν οἷς ἥ τε Πυθία δεινὰ προὔφαινε μαντεύματα, καὶ χρησμὸς ᾔδετο παλαιὸς ἐκ τῶν Σιβυλλείων", "st": "Dem. 19.1"}, {"sp": "N", "t": "τῆς ἐπὶ Θερμώδοντι μάχης ἀπάνευθε γενοίμην,<br>αἰετὸς ἐν νεφέεσσι καὶ ἠέρι θηήσασθαι.", "st": "Dem. 19.1b"}, {"sp": "N", "t": "κλαίει ὁ νικηθείς, ὁ δὲ νικήσας ἀπόλωλε.", "st": "Dem. 19.1c"}, {"sp": "N", "t": "τὸν δὲ Θερμώδοντα φασιν εἶναι παρ’ ἡμῖν ἐν Χαιρωνείᾳ ποτάμιον μικρὸν εἰς τὸν Κηφισὸν ἐμβάλλον. ἡμεῖς δὲ νῦν μὲν οὐδὲν οὕτω τῶν ῥευμάτων ἴσμεν ὀνομαζόμενον, εἰκάζομεν δὲ τὸν καλούμενον Αἵμονα Θερμώδοντα λέγεσθαι τότε· καὶ γὰρ παραρρεῖ παρὰ τὸ Ἡράκλειον, ὅπου κατεστρατοπέδευον οἱ Ἕλληνες· καὶ τεκμαιρόμεθα τῆς μάχης γενομένης αἵματος ἐμπλησθέντα καὶ νεκρῶν τὸν ποταμὸν ταύτην διαλλάξαι τὴν προσηγορίαν. ὁ δὲ Δοῦρις οὐ ποταμὸν εἶναι φησι τὸν Θερμώδοντά, ἀλλ’ ἱστάντας τινὰς σκηνὴν καὶ περιορύττοντας ἀνδριαντίσκον εὑρεῖν λίθινον, ὑπὸ γραμμάτων τινῶν διασημαινόμενον ὡς εἴη Θερμώδων, ἐν ταῖς ἀγκάλαις Ἀμαζόνα φέροντα τετρωμένην. ἐπὶ δὲ τούτῳ χρησμὸν ἄλλον ᾄδεσθαι λέγοντα·", "st": "Dem. 19.2"}, {"sp": "N", "t": "τὴν δ’ ἐπὶ Θερμώδοντι μάχην μένε, παμμέλαν ὄρνι·<br>τηνεί τοι κρέα πολλὰ παρέσσεται ἀνθρώπεια.", "st": "Dem. 19.2b"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ὅπως ἔχει, διαιτῆσαι χαλεπόν ὁ δὲ Δημοσθένης λέγεται τοῖς τῶν Ἑλλήνων ὅπλοις ἐκτεθαρρηκὼς, καὶ λαμπρὸς ὑπὸ ῥώμης καὶ προθυμίας ἀνδρῶν τοσούτων προκαλουμένων τοὺς πολεμίους αἰρόμενος, οὔτε χρησμοῖς ἐᾶν προσέχειν οὔτε μαντείας ἀκούειν, ἀλλὰ καὶ τὴν Πυθίαν ὑπονοεῖν ὡς φιλιππίζουσαν, ἀναμιμνῄσκων Ἐπαμεινώνδου τοὺς Θηβαίους καὶ Περικλέους τοὺς Ἀθηναίους, ὡς ἐκεῖνοι τὰ τοιαῦτα δειλίας ἡγούμενοι προφάσεις ἐχρῶντο τοῖς λογισμοῖς. μέχρι μὲν οὖν τούτων ἀνὴρ ἦν ἀγαθός· ἐν δὲ τῇ μάχῃ καλὸν οὐδὲν οὐδ’ ὁμολογούμενον ἔργον οἷς εἶπεν ἀποδειξάμενος ᾤχετο λιπὼν τὴν τάξιν, ἀποδρὰς αἴσχιστα καὶ τὰ ὅπλα ῥίψας, οὐδὲ τὴν ἐπιγραφὴν τῆς ἀσπίδος, ὡς ἔλεγε Πυθέας, αἰσχυνθείς, ἐπιγεγραμμένης γράμμασι χρυσοῖς, ἀγαθῇ τύχῃ.", "st": "Dem. 20.1"}, {"sp": "N", "t": "παραυτίκα μὲν οὖν ὁ Φίλιππος ἐπὶ τῇ νίκῃ διὰ τὴν χαρὰν ἐξυβρίσας, καὶ κωμάσας ἐπὶ τοὺς νεκροὺς μεθύων, ᾖδε τὴν ἀρχὴν τοῦ Δημοσθένους ψηφίσματος πρὸς πόδα διαιρῶν καὶ ὑποκρούων·", "st": "Dem. 20.3"}, {"sp": "N", "t": "Δημοσθένης Δημοσθένους Παιανιεὺς τάδ’ εἶπεν·", "st": "Dem. 20.3b"}, {"sp": "N", "t": "ἐκνήψας δὲ καὶ τὸ μέγεθος τοῦ περιστάντος αὐτὸν ἀγῶνος ἐν νῷ λαβών ἔφριττε τὴν δεινότητα καὶ τὴν δύναμιν τοῦ ῥήτορος, ἐν μέρει μικρῷ μιᾶς ἡμέρας τὸν ὑπὲρ τῆς ἡγεμονίας καὶ τοῦ σώματος ἀναρρῖψαι κίνδυνον ἀναγκασθεὶς ὑπ’ αὐτοῦ. διῖκτο δ’ ἡ δόξα μέχρι τοῦ Περσῶν βασιλέως· κἀκεῖνος ἔπεμψε τοῖς σατράπαις ἐπὶ θάλασσαν γράμματα, χρήματα Δημοσθένει διδόναι κελεύων, καὶ προσέχειν ἐκείνῳ μάλιστα τῶν Ἑλλήνων, ὡς περισπάσαι δυναμένῳ καὶ κατασχεῖν ταῖς Ἑλληνικαῖς ταραχαῖς τὸν Μακεδόνα. ταῦτα μὲν οὖν ὕστερον ἐφώρασεν Ἀλέξανδρος, ἐν Σάρδεσιν ἐπιστολάς τινας ἀνευρὼν τοῦ Δημοσθένους καὶ γράμματα τῶν βασιλέως στρατηγῶν, δηλοῦντα τὸ πλῆθος τῶν δοθέντων αὐτῷ χρημάτων.", "st": "Dem. 20.3c"}, {"sp": "N", "t": "τότε δὲ τῆς ἀτυχίας τοῖς Ἕλλησι γεγενημένης οἱ μὲν ἀντιπολιτευόμενοι ῥήτορες ἐπεμβαίνοντες τῷ Δημοσθένει κατεσκεύαζον εὐθύνας καὶ γραφὰς ἐπ’ αὐτόν· ὁ δὲ δῆμος οὐ μόνον τούτων ἀπέλυεν, ἀλλὰ καὶ τιμῶν διετέλει καὶ προκαλούμενος αὖθις ὡς εὔνουν εἰς τὴν πολιτείαν, ὥστε καὶ τῶν ὀστέων ἐκ Χαιρωνείας κομισθέντων καὶ θαπτομένων τὸν ἐπὶ τοῖς ἀνδράσιν ἔπαινον εἰπεῖν ἀπέδωκεν, οὐ ταπεινῶς οὐδ’ ἀγεννῶς φέρων τὸ συμβεβηκός, ὡς γράφει καὶ τραγῳδεῖ Θεόπομπος, ἀλλὰ τῷ τιμᾶν μάλιστα καὶ κοσμεῖν τὸν σύμβουλον ἀποδεικνύμενος τὸ μὴ μεταμέλεσθαι τοῖς βεβουλευμένοις. τὸν μὲν οὖν λόγον εἶπεν ὁ Δημοσθένης, τοῖς δὲ ψηφίσμασιν οὐχ ἑαυτόν, ἀλλ’ ἐν μέρει τῶν φίλων ἕκαστον ἐπέγραφεν, ἐξοιωνιζόμενος τὸν ἴδιον δαίμονα καὶ τὴν τύχην, ἕως αὖθις ἀνεθάρρησε Φιλίππου τελευτήσαντος. ἐτελεύτησε δὲ τῇ περὶ Χαιρώνειαν εὐτυχίᾳ χρόνον οὐ πολὺν ἐπιβιώσας· καὶ τοῦτο δοκεῖ τῷ τελευταίῳ τῶν ἐπῶν ὁ χρησμὸς ἀποθεσπίσαι·", "st": "Dem. 21.1"}, {"sp": "N", "t": "κλαίει ὁ νικηθείς, ὁ δὲ νικήσας ἀπόλωλεν.", "st": "Dem. 21.1b"}, {"sp": "N", "t": "ἔγνω μὲν οὖν κρύφα τὴν τοῦ Φιλίππου τελευτὴν ὁ Δημοσθένης, προκαταλαμβάνων δὲ τὸ θαρρεῖν ἐπὶ τὰ μέλλοντα τοὺς Ἀθηναίους, προῆλθε φαιδρὸς εἰς τὴν βουλήν ὡς ὄναρ ἑωρακὼς ἀφ’ οὗ τι μέγα προσδοκᾶν Ἀθηναίοις ἀγαθόν καὶ μετ’ οὐ πολὺ παρῆσαν οἱ τὸν Φιλίππου θάνατον ἀπαγγέλλοντες. εὐθὺς οὖν ἔθυον εὐαγγέλια καὶ στεφανοῦν ἐψηφίσαντο Παυσανίαν. καὶ προῆλθεν ὁ Δημοσθένης ἔχων λαμπρὸν ἱμάτιον ἐστεφανωμένος, ἑβδόμην ἡμέραν τῆς θυγατρὸς αὐτοῦ τεθνηκυίας, ὡς ὁ Αἰσχίνης φησί λοιδορῶν ἐπὶ τούτῳ καὶ κατηγορῶν αὐτοῦ μισοτεκνίαν, αὐτὸς ὢν ἀγεννὴς καὶ μαλακός, εἰ τὰ πένθη καὶ τοὺς ὀδυρμοὺς ἡμέρου καὶ φιλοστόργου ψυχῆς ἐποιεῖτο σημεῖα, τὸ δὲ ἀλύπως φέρειν ταῦτα καὶ πρᾴως ἀπεδοκίμαζεν.", "st": "Dem. 22.1"}, {"sp": "N", "t": "ἐγὼ δ’, ὡς μὲν ἐπὶ θανάτῳ βασιλέως ἡμέρως οὕτω καὶ φιλανθρώπως ἐν οἷς ηὐτύχησε χρησαμένου πταίσασιν αὐτοῖς στεφανηφορεῖν καλῶς εἶχε καὶ θύειν, οὐκ ἄν εἴποιμι· πρὸς γὰρ τῷ νεμεσητῷ καὶ ἀγεννές, ζῶντα μὲν τιμᾶν καὶ ποιεῖσθαι πολίτην, πεσόντος δ’ ὑφ’ ἑτέρου μὴ φέρειν τὴν χαρὰν μετρίως, ἀλλ’ ἐπισκιρτᾶν τῷ νεκρῷ καὶ παιωνίζειν, ὥσπερ αὐτοὺς ἀνδραγαθήσαντας· ὅτι μέντοι τὰς οἴκοι τύχας καὶ δάκρυα καὶ ὀδυρμοὺς ἀπολιπὼν ταῖς γυναιξὶν ὁ Δημοσθένης, ἃ τῇ πόλει συμφέρειν ᾤετο, ταῦτ’ ἔπραττεν, ἐπαινῶ, καὶ τίθεμαι πολιτικῆς καὶ ἀνδρώδους ψυχῆς ἀεὶ πρὸς τὸ κοινὸν ἱστάμενον καὶ τὰ οἰκεῖα πάθη καὶ πράγματα τοῖς δημοσίοις ἐπανέχοντα τηρεῖν τὸ ἀξίωμα πολὺ μᾶλλον ἢ τοὺς ὑποκριτὰς τῶν βασιλικῶν καὶ τυραννικῶν προσώπων, οὓς ὁρῶμεν οὔτε κλαίοντας οὔτε γελῶντας ἐν τοῖς θεάτροις ὡς αὐτοὶ θέλουσιν, ἀλλ’ ὡς ὁ ἀγὼν ἀπαιτεῖ πρὸς τὴν ὑπόθεσιν.", "st": "Dem. 22.4"}, {"sp": "N", "t": "χωρὶς δὲ τούτων, εἰ δεῖ τὸν ἀτυχήσαντα μὴ περιορᾶν ἀπαρηγόρητον ἐν τῷ πάθει κείμενον, ἀλλὰ καὶ λόγοις χρῆσθαι κουφίζουσι καὶ πρὸς ἡδίω πράγματα τρέπειν τὴν διάνοιαν, ὥσπερ οἱ τοὺς ὀφθαλμιῶντας ἀπὸ τῶν λαμπρῶν καὶ ἀντιτύπων ἐπὶ τὰ χλωρὰ καὶ μαλακὰ χρώματα τὴν ὄψιν ἀπάγειν κελεύοντες, πόθεν ἄν τις ἐπαγάγοιτο βελτίω παρηγορίαν ἢ πατρίδος εὐτυχούσης ἐκ τῶν κοινῶν παθῶν ἐπὶ τὰ οἰκεῖα σύγκρασιν ποριζόμενος τοῖς βελτίοσιν ἀφανίζουσαν τὰ χείρω; ταῦτα μὲν οὖν εἰπεῖν προήχθημεν ὁρῶντες ἐπικλῶντα πολλοὺς καὶ ἀποθηλύνοντα τὸν Αἰσχίνην τῷ λόγῳ τούτῳ πρὸς οἶκτον.", "st": "Dem. 22.6"}, {"sp": "N", "t": "αἱ δὲ πόλεις πάλιν τοῦ Δημοσθένους ἀναρριπίζοντος αὐτάς συνίσταντο. καὶ Θηβαῖοι μὲν ἐπέθεντο τῇ φρουρᾷ καὶ πολλοὺς ἀνεῖλον, ὅπλα τοῦ Δημοσθένους αὐτοῖς συμπαρασκευάσαντος, Ἀθηναῖοι δ’ ὡς πολεμήσοντες μετ’ αὐτῶν παρεσκευάζοντο. καὶ τὸ βῆμα κατεῖχεν ὁ Δημοσθένης, καὶ πρὸς τοὺς ἐν Ἀσίᾳ στρατηγοὺς τοῦ βασιλέως ἔγραφε τὸν ἐκεῖθεν ἐπεγείρων πόλεμον Ἀλεξάνδρῳ, παῖδα καὶ Μαργίτην ἀποκαλῶν αὐτόν, ἐπεὶ μέντοι τὰ περὶ τὴν χώραν θέμενος παρῆν αὐτὸς μετὰ τῆς δυνάμεως εἰς τὴν Βοιωτίαν, ἐξεκέκοπτο μὲν ἡ θρασύτης τῶν Ἀθηναίων καὶ ὁ Δημοσθένης ἀπεσβήκει, Θηβαῖοι δὲ προδοθέντες ὑπ’ ἐκείνων ἠγωνίσαντο καθ’ αὑτοὺς καὶ τὴν πόλιν ἀπέβαλον. θορύβου δὲ μεγάλου τοὺς Ἀθηναίους περιεστῶτος, ἀπεστάλη μὲν ὁ Δημοσθένης αἱρεθεὶς μεθ’ ἑτέρων πρεσβευτὴς πρὸς Ἀλέξανδρον, δείσας δὲ τὴν ὀργὴν ἐκ τοῦ Κιθαιρῶνος ἀνεχώρησεν ὀπίσω καὶ τὴν πρεσβείαν ἀφῆκεν. εὐθὺς δ’ ὁ Ἀλέξανδρος ἐξῄτει πέμπων τῶν δημαγωγῶν δέκα μὲν, ὡς Ἰδομενεὺς καὶ Δοῦρις εἰρήκασιν, ὀκτὼ δ’, ὡς οἱ πλεῖστοι καὶ δοκιμώτατοι τῶν συγγραφέων, τούσδε, Δημοσθένην, Πολύευκτον, Ἐφιάλτην, Λυκοῦργον, Μοιροκλέα, Δήμωνα, Καλλισθένην, Χαρίδημον.", "st": "Dem. 23.1"}, {"sp": "N", "t": "ὅτε καὶ τὸν περὶ τῶν προβάτων λόγον ὁ Δημοσθένης προσῆψε τῷ δήμῳ, ἃ τοῖς λύκοις τοὺς κύνας ἐξέδωκε, διηγησάμενος αὑτὸν μὲν εἴκασε καὶ τοὺς σὺν αὐτῷ κυσὶν ὑπὲρ τοῦ δήμου μαχομένοις, Ἀλέξανδρον δὲ τὸν Μακεδόνα μονόλυκον προσηγόρευσεν. ἔτι δ’, ὥσπερ, ἔφη, τοὺς ἐμπόρους ὁρῶμεν, ὅταν ἐν τρυβλίῳ δεῖγμα περιφέρωσι, δι’ ὀλίγων πυρῶν τοὺς πολλοὺς πιπράσκοντας, οὕτως ἐν ἡμῖν λανθάνετε πάντας αὑτοὺς συνεκδιδόντες. ταῦτα μὲν οὖν Ἀριστόβουλος ὁ Κασσανδρεὺς ἱστόρηκε.", "st": "Dem. 23.5"}, {"sp": "N", "t": "βουλευομένων δὲ τῶν Ἀθηναίων καὶ διαπορούντων, ὁ Δημάδης λαβὼν πέντε τάλαντα παρὰ τῶν ἀνδρῶν ὡμολόγησε πρεσβεύσειν καὶ δεήσεσθαι τοῦ βασιλέως ὑπὲρ αὐτῶν, εἴτε τῇ φιλίᾳ πιστεύων, εἴτε προσδοκῶν μεστὸν εὑρήσειν ὥσπερ λέοντα φόνου κεκορεσμένον. ἔπεισε δ’ οὖν καὶ παρῃτήσατο τοὺς ἄνδρας ὁ Δημάδης, καὶ διήλλαξεν αὐτῷ τὴν πόλιν.", "st": "Dem. 23.5b"}, {"sp": "N", "t": "ἀπελθόντος δὲ Ἀλεξάνδρου μεγάλοι μὲν ἦσαν οὗτοι, ταπεινὰ δ’ ἔπραττεν ὁ Δημοσθένης, κινουμένῳ δὲ Ἄγιδι τῷ Σπαρτιάτῃ βραχέα συνεκινήθη πάλιν, εἶτ’ ἔπτηξε, τῶν μὲν Ἀθηναίων οὐ συνεξαναστάντων, τοῦ δ’ Ἄγιδος πεσόντος καὶ τῶν Λακεδαιμονίων συντριβέντων.", "st": "Dem. 24.1"}, {"sp": "N", "t": "εἰσήχθη δὲ τότε καὶ ἡ περὶ τοῦ στεφάνου γραφὴ κατὰ Κτησιφῶντος, γραφεῖσα μὲν ἐπὶ Χαιρώνδου ἄρχοντος μικρὸν ἐπάνω τῶν Χαιρωνικῶν, κριθεῖσα δ’ ὕστερον ἔτεσι δέκα ἐπ’ Ἀριστοφῶντος, γενομένη δὲ ὡς οὐδεμία τῶν δημοσίων περιβόητος διά τε τὴν δόξαν τῶν λεγόντων καὶ τὴν τῶν δικαζόντων εὐγένειαν, οἳ τοῖς ἐλαύνουσι τὸν Δημοσθένη τότε πλεῖστον δυναμένοις καὶ μακεδονίζουσιν οὐ προήκαντο τὴν κατ’ αὐτοῦ ψῆφον, ἀλλ’ οὕτω λαμπρῶς ἀπέλυσαν ὥστε τὸ πέμπτον μέρος τῶν ψήφων Αἰσχίνην μὴ μεταλαβεῖν. ἐκεῖνος μὲν οὖν εὐθὺς ἐκ τῆς πόλεως ᾤχετ’ ἀπιὼν, καὶ περὶ Ῥόδον καὶ Ἰωνίαν σοφιστεύων κατεβίωσε.", "st": "Dem. 24.2"}, {"sp": "N", "t": "μετ’ οὐ πολὺ δ’ Ἅρπαλος ἧκεν ἐξ Ἀσίας εἰς τὰς Ἀθήνας ἀποδρὰς Ἀλέξανδρον, αὑτῷ τε πράγματα συνειδὼς πονηρὰ δι’ ἀσωτίαν, κἀκεῖνον ἤδη χαλεπὸν ὄντα τοῖς φίλοις δεδοικώς. καταφυγόντος δὲ πρὸς τὸν δῆμον αὐτοῦ καὶ μετὰ τῶν χρημάτων καὶ τῶν νεῶν αὑτὸν παραδιδόντος, οἱ μὲν ἄλλοι ῥήτορες εὐθὺς ἐποφθαλμιάσαντες πρὸς τὸν πλοῦτον ἐβοήθουν καὶ συνέπειθον τοὺς Ἀθηναίους δέχεσθαι καὶ σῴζειν τὸν ἱκέτην. ὁ δὲ Δημοσθένης πρῶτον μὲν ἀπελαύνειν συνεβούλευε τὸν Ἅρπαλον, καὶ φυλάττεσθαι μὴ τὴν πόλιν ἐμβάλωσιν εἰς πόλεμον ἐξ οὐκ ἀναγκαίας καὶ ἀδίκου προφάσεως· ἡμέραις δ’ ὀλίγαις ὕστερον ἐξεταζομένων τῶν χρημάτων ἰδὼν αὑτὸν ὁ Ἅρπαλος ἡσθέντα βαρβαρικῇ κύλικι καὶ καταμανθάνοντα τὴν τορείαν καὶ τὸ εἶδος, ἐκέλευσε διαβαστάσαντα τὴν ὁλκὴν τοῦ χρυσίου σκέψασθαι. θαυμάσαντος δὲ τοῦ Δημοσθένους τὸ βάρος καὶ πυθομένου πόσον ἄγει, μειδιάσας ὁ Ἅρπαλος, ἄξει σοι, φησίν, εἴκοσι τάλαντα καὶ γενομένης τάχιστα τῆς νυκτὸς ἔπεμψεν αὑτῷ τὴν κύλικα μετὰ τῶν εἴκοσι ταλάντων, ἦν δ’ ἄρα δεινὸς ὁ Ἅρπαλος ἐρωτικοῦ πρὸς χρυσίον ἀνδρὸς ὄψει καὶ διαχύσει καὶ βολαῖς ὀμμάτων ἐνευρεῖν ἦθος. οὐ γὰρ ἀντέσχεν ὁ Δημοσθένης, ἀλλὰ πληγεὶς ὑπὸ τῆς δωροδοκίας ὥσπερ παραδεδεγμένος φρουρὰν προσκεχωρήκει τῷ Ἁρπάλῳ. καὶ μεθ’ ἡμέραν εὖ καὶ καλῶς ἐρίοις καὶ ταινίαις κατὰ τοῦ τραχήλου καθελιξάμενος εἰς τὴν ἐκκλησίαν προῆλθε· καὶ κελευόντων ἀνίστασθαι καὶ λέγειν, διένευεν ὡς ἀποκεκομμένης αὑτῷ τῆς φωνῆς. οἱ δ’ εὐφυεῖς χλευάζοντες οὐχ ὑπὸ συνάγχης ἔφραζον, ἀλλ’ ὑπ’ ἀργυράγχης εἰλῆφθαι νύκτωρ τὸν δημαγωγόν. ὕστερον δὲ τοῦ δήμου παντὸς αἰσθομένου τὴν δωροδοκίαν καὶ βουλόμενον ἀπολογεῖσθαι καὶ πείθειν οὐκ ἐῶντος, ἀλλὰ χαλεπαίνοντος καὶ θορυβοῦντος, ἀναστάς τις ἔσκωψεν εἰπών οὐκ ἀκούσεσθε, ὦ ἄνδρες Ἀθηναῖοι, τοῦ τὴν κύλικα ἔχοντος;", "st": "Dem. 25.1"}, {"sp": "N", "t": "τότε μὲν οὖν ἀπέπεμψαν ἐκ τῆς πόλεως τὸν Ἅρπαλον, δεδιότες δὲ μὴ λόγον ἀπαιτῶνται χρημάτων ὧν διηρπάκεσαν οἱ ῥήτορες, ζήτησιν ἐποιοῦντο νεανικήν καὶ τὰς οἰκίας ἐπιόντες ἠρεύνων, πλὴν τῆς Καλλικλέους τοῦ Ἀρρενείδου. μόνην γὰρ τὴν τούτου νεωστὶ γεγαμηκότος οὐκ εἴασαν ἐλεγχθῆναι, νύμφης ἔνδον οὔσης, ὡς ἱστορεῖ Θεόπομπος.", "st": "Dem. 25.7"}, {"sp": "N", "t": "ὁ δὲ Δημοσθένης ὁμόσε χωρῶν εἰσήνεγκε ψήφισμα τὴν ἐξ Ἀρείου πάγου βουλὴν ἐξετάσαι τὸ πρᾶγμα καὶ τοὺς ἐκείνῃ δόξαντας ἀδικεῖν δοῦναι δίκην. ἐν δὲ πρώτοις αὐτοῦ τῆς βουλῆς ἐκείνου καταψηφισαμένης, εἰσῆλθε μὲν εἰς τὸ δικαστήριον, ὀφλὼν δὲ πεντήκοντα ταλάντων δίκην καὶ παραδοθεὶς εἰς τὸ δεσμωτήριον, αἰσχύνῃ τῆς αἰτίας φησὶ καὶ δι’ ἀσθένειαν τοῦ σώματος οὐ δυναμένου φέρειν τὸν εἱργμὸν ἀποδρᾶναι τοὺς μὲν λαθόντα, τῶν δὲ λαθεῖν ἐξουσίαν δόντων. λέγεται γοῦν ὡς οὐ μακρὰν τοῦ ἄστεος φεύγων αἴσθοιτό τινας τῶν διαφόρων αὐτῷ πολιτῶν ἐπιδιώκοντας, καὶ βούλοιτο μὲν αὑτὸν ἀποκρύπτειν, ὡς δ’ ἐκεῖνοι φθεγξάμενοι τοὔνομα καὶ προσελθόντες ἐγγὺς ἐδέοντο λαβεῖν ἐφόδια παρ’ αὐτῶν, ἐπ’ αὐτὸ τοῦτο κομίζοντες ἀργύριον οἴκοθεν καὶ τούτου χάριν ἐπιδιώξαντες αὐτόν, ἅμα δὲ θαρρεῖν παρεκάλουν καὶ μὴ φέρειν ἀνιαρῶς τὸ συμβεβηκός, ἔτι μᾶλλον ἀνακλαύσασθαι τὸν Δημοσθένην καὶ εἰπεῖν πῶς δ’ οὐ μέλλω φέρειν βαρέως ἀπολείπων πόλιν ἐχθροὺς τοιούτους ἔχουσαν οἵους ἐν ἑτέρᾳ, φίλους εὑρεῖν οὐ ῥᾴδιόν ἐστιν;", "st": "Dem. 26.1"}, {"sp": "N", "t": "ἤνεγκε δὲ τὴν φυγὴν μαλακῶς, ἐν Αἰγίνῃ καὶ Τροιζῆνι καθεζόμενος τὰ πολλὰ καὶ πρὸς τὴν Ἀττικὴν ἀποβλέπων δεδακρυμένος, ὥστε φωνὰς οὐκ εὐγνώμονας οὐδ’ ὁμολογούσας τοῖς ἐν τῇ πολιτείᾳ νεανιεύμασιν ἀπομνημονεύεσθαι. λέγεται γὰρ ἐκ τοῦ ἄστεος ἀπαλλαττόμενος καὶ πρὸς τὴν ἀκρόπολιν ἀνατείνας τὰς χεῖρας εἰπεῖν ὦ δέσποινα Πολιάς, τί δὴ τρισὶ τοῖς χαλεπωτάτοις χαίρεις θηρίοις, γλαυκὶ καὶ δράκοντι καὶ δήμῳ; τοὺς δὲ προσιόντας αὐτῷ καὶ συνδιατρίβοντας νεανίσκους ἀπέτρεπε τῆς πολιτείας λέγων ὡς εἰ, δυεῖν προκειμένων ὁδῶν ἀπ’ ἀρχῆς, τῆς μὲν ἐπὶ τὸ βῆμα καὶ τὴν ἐκκλησίαν, τῆς δ’ ἄντικρυς εἰς τὸν ὄλεθρον, ἐτύγχανε προειδὼς τὰ κατὰ τὴν πολιτείαν κακά, φόβους καὶ φθόνους καὶ διαβολὰς καὶ ἀγῶνας, ἐπὶ ταύτην ἂν ὁρμήσαι τὴν εὐθὺ τοῦ θανάτου τείνουσαν.", "st": "Dem. 26.5"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἔτι φεύγοντος αὐτοῦ τὴν εἰρημένην φυγήν Ἀλέξανδρος μὲν ἐτελεύτησε, τὰ δ’ Ἑλληνικὰ συνίσταντο πάλιν, Λεωσθένους ἀνδραγαθοῦντος καί περιτειχίζοντος Ἀντίπατρον ἐν Λαμίᾳ πολιορκούμενον. Πυθέας μὲν οὖν ὁ ῥήτωρ καί Καλλιμέδων ὁ Κάραβος ἐξ Ἀθηνῶν φεύγοντες Ἀντιπάτρῳ προσεγένοντο, καί μετὰ τῶν ἐκείνου φίλων καί πρέσβεων περιιόντες οὐκ εἴων ἀφίστασθαι τοὺς Ἕλληνας οὐδὲ προσέχειν τοῖς Ἀθηναίοις· Δημοσθένης δὲ τοῖς ἐξ ἄστεος πρεσβεύουσι προσμίξας ἑαυτὸν ἠγωνίζετο καί συνέπραττεν ὅπως αἱ πόλεις συνεπιθήσονται τοῖς Μακεδόσι καί συνεκβαλοῦσιν αὐτοὺς τῆς Ἑλλάδος. ἐν δ’ Ἀρκαδίᾳ καί λοιδορίαν τοῦ Πυθέου καὶ τοῦ Δημοσθένους γενέσθαι πρὸς ἀλλήλους εἴρηκεν ὁ Φύλαρχος ἐν ἐκκλησίᾳ, τοῦ μὲν ὑπὲρ τῶν Μακεδόνων, τοῦ δ’ ὑπὲρ τῶν Ἑλλήνων λέγοντος, λέγεται δὲ τὸν μὲν Πυθέαν εἰπεῖν ὅτι, καθάπερ οἰκίαν εἰς ἣν ὄνειον εἰσφέρεται γάλα, κακόν τι πάντως ἔχειν νομίζομεν, οὕτω καί πόλιν ἀνάγκη νοσεῖν εἰς ἣν Ἀθηναίων πρεσβεία παραγίνεται· τὸν δὲ Δημοσθένη στρέψαι τὸ παράδειγμα, φήσαντα καί τὸ γάλα τὸ ὄνειον ἐφ’ ὑγιείᾳ καί τοὺς Ἀθηναίους ἐπὶ σωτηρίᾳ παραγίνεσθαι τῶν νοσούντων.", "st": "Dem. 27.1"}, {"sp": "N", "t": "ἐφ’ οἷς ἡσθεὶς ὁ τῶν Ἀθηναίων δῆμος ψηφίζεται τῷ Δημοσθένει κάθοδον. τὸ μὲν οὖν ψήφισμα Δήμων ὁ Παιανιεύς, ἀνεψιὸς ὢν Δημοσθένους, εἰσήνεγκεν· ἐπέμφθη δὲ τριήρης ἐπ’ αὐτὸν εἰς Αἴγιναν. ἐκ δὲ Πειραιῶς ἀνέβαινεν οὔτε ἄρχοντος οὔτε ἱερέως ἀπολειφθέντος, ἀλλὰ καί τῶν ἄλλων πολιτῶν ὁμοῦ πάντων ἀπαντώντων καί δεχομένων προθύμως. ὅτε καί φησιν αὐτὸν ὁ Μάγνης Δημήτριος ἀνατείναντα τὰς χεῖρας μακαρίσαι τῆς ἡμέρας ἐκείνης αὑτόν, ὡς βέλτιον Ἀλκιβιάδου κατιόντα· πεπεισμένους γάρ, οὐ βεβιασμένους, ὑπ’ αὐτοῦ δέχεσθαι τοὺς πολίτας. τῆς δὲ χρηματικῆς ζημίας αὐτῷ μενούσης οὐ γὰρ ἐξῆν χάριτι λῦσαι καταδίκην ἐσοφίσαντο πρὸς τὸν νόμον. εἰωθότες γὰρ ἐν τῇ θυσίᾳ τοῦ Διὸς τοῦ Σωτῆρος ἀργύριον τελεῖν τοῖς κατασκευάζουσι καί κοσμοῦσι τὸν βωμόν, ἐκείνῳ τότε ταῦτα ποιῆσαι καί παρασχεῖν πεντήκοντα ταλάντων ἐξέδωκαν, ὅσον ἦν τίμημα τῆς καταδίκης.", "st": "Dem. 27.6"}, {"sp": "N", "t": "οὐ μὴν ἐπὶ πολὺν χρόνον ἀπέλαυσε τῆς πατρίδος κατελθών, ἀλλὰ ταχὺ τῶν Ἑλληνικῶν πραγμάτων συντριβέντων Μεταγειτνιῶνος μὲν ἡ περὶ Κραννῶνα μάχη συνέπεσε, Βοηδρομιῶνος δὲ παρῆλθεν εἰς Μουνυχίαν ἡ φρουρά, Πυανεψιῶνος δὲ Δημοσθένης ἀπέθανε τόνδε τὸν τρόπον.", "st": "Dem. 28.1"}, {"sp": "N", "t": "ὡς Ἀντίπατρος καὶ Κρατερὸς ἠγγέλλοντο προσιόντες ἐπὶ τὰς Ἀθήνας, οἱ μὲν περὶ τὸν Δημοσθένην φθάσαντες ὑπεξῆλθον ἐκ τῆς πόλεως, ὁ δὲ δῆμος αὐτῶν θάνατον κατέγνω Δημάδου γράψαντος. ἄλλων δὲ ἀλλαχοῦ διασπαρέντων ὁ Ἀντίπατρος περιέπεμπε τοὺς συλλαμβάνοντας, ὧν ἡγεμὼν ἦν Ἀρχίας ὁ κληθεὶς Φυγαδοθήρας. τοῦτον δὲ Θούριον ὄντα τῷ γένει λόγος ἔχει τραγῳδίας ὑποκρίνεσθαί ποτε, καὶ τὸν Αἰγινήτην Πῶλον τὸν ὑπερβαλόντα τῇ τέχνῃ πάντας ἐκείνου γεγονέναι μαθητὴν ἱστοροῦσιν. Ἕρμιππος δὲ τὸν Ἀρχίαν ἐν τοῖς Λακρίτου τοῦ ῥήτορος μαθηταῖς ἀναγράφει· Δημήτριος δὲ τῆς Ἀναξιμένους διατριβῆς μετεσχηκέναι φησὶν αὐτόν. οὗτος οὖν ὁ Ἀρχίας Ὑπερείδην μὲν τὸν ῥήτορα καὶ Ἀριστόνικον τὸν Μαραθώνιον καὶ τὸν Δημητρίου τοῦ Φαληρέως ἀδελφὸν Ἱμεραῖον ἐν Αἰγίνῃ καταφυγόντας ἐπὶ τὸ Αἰάκειον ἀποσπάσας ἔπεμψεν εἰς Κλεωνὰς πρὸς Ἀντίπατρον· κἀκεῖ διεφθάρησαν, Ὑπερείδου δὲ καὶ τὴν γλῶτταν ἐκτμηθῆναι λέγουσι.", "st": "Dem. 28.2"}, {"sp": "N", "t": "τὸν δὲ Δημοσθένην πυθόμενος ἱκέτην ἐν Καλαυρείᾳ ἐν τῷ ἱερῷ Ποσειδῶνος καθέζεσθαι, διαπλεύσας ὑπηρετικοῖς καὶ ἀποβὰς μετὰ Θρᾳκῶν δορυφόρων ἔπειθεν ἀναστάντα βαδίζειν μετ’ αὐτοῦ πρὸς Ἀντίπατρον ὡς δυσχερὲς πεισόμενον οὐδέν. ὁ δὲ Δημοσθένης ἐτύγχανεν ὄψιν ἑωρακὼς κατὰ τοὺς ὕπνους ἐκείνης τῆς νυκτὸς ἀλλόκοτον. ἐδόκει γὰρ ἀνταγωνίζεσθαι τῷ Ἀρχίᾳ τραγῳδίαν ὑποκρινόμενος, εὐημερῶν δὲ καὶ κατέχων τὸ θέατρον ἐνδείᾳ παρασκευῆς καὶ χορηγίας κρατεῖσθαι. διὸ τοῦ Ἀρχίου πολλὰ φιλάνθρωπα διαλεχθέντος ἀναβλέψας πρὸς αὐτόν, ὥσπερ ἐτύγχανε καθήμενος, ὦ Ἀρχία, εἶπεν, οὔτε ὑποκρινόμενός με ἔπεισας πώποτε οὔτε νῦν πείσεις ἐπαγγελλόμενος. ἀρξαμένου δ’ ἀπειλεῖν τοῦ Ἀρχίου μετ’ ὀργῆς, νῦν, ἔφη, λέγεις τὰ ἐκ τοῦ Μακεδονικοῦ τρίποδος, ἄρτι δ’ ὑπεκρίνου. μικρὸν οὖν ἐπίσχες, ὅπως ἐπιστείλω τι τοῖς οἴκοι καὶ ταῦτ’ εἰπὼν ἐντὸς ἀνεχώρησε τοῦ ναοῦ· καὶ λαβὼν βιβλίον ὡς γράφειν μέλλων προσήνεγκε τῷ στόματι τὸν κάλαμον, καὶ δακών, ὥσπερ ἐν τῷ διανοεῖσθαι καὶ γράφειν εἰώθει, χρόνον τινὰ κατέσχεν, εἶτα συγκαλυψάμενος ἀπέκλινε τὴν κεφαλήν. οἱ μὲν οὖν παρὰ τὰς θύρας ἑστῶτες δορυφόροι κατεγέλων ὡς ἀποδειλιῶντος αὐτοῦ, καὶ μαλακὸν ἀπεκάλουν καὶ ἄνανδρον, ὁ δ’ Ἀρχίας προσελθὼν ἀνίστασθαι παρεκάλει, καὶ τοὺς αὐτοὺς ἀνακυκλῶν λόγους αὖθις ἐπηγγέλλετο διαλλαγὰς πρὸς τὸν Ἀντίπατρον. ἤδη δὲ συνῃσθημένος ὁ Δημοσθένης ἐμπεφυκότος αὐτῷ τοῦ φαρμάκου καὶ κρατοῦντος ἐξεκαλύψατο· καὶ διαβλέψας πρὸς τὸν Ἀρχίαν, οὐκ ἂν φθάνοις, εἶπεν, ἤδη τὸν ἐκ τῆς τραγῳδίας ὑποκρινόμενος Κρέοντα καὶ τὸ σῶμα τοῦτο ῥίπτων ἄταφον. ἐγὼ δ’, ὦ φίλε Πόσειδον, ἔτι ζῶν ἐξανίσταμαι τοῦ ἱεροῦ· τῷ δὲ Ἀντιπάτρῳ καὶ Μακεδόσιν οὐδ’ ὁ σὸς ναὸς καθαρὸς ἀπολέλειπται. ταῦτ’ εἰπὼν, καὶ κελεύσας ὑπολαβεῖν αὐτὸν ἤδη τρέμοντα καὶ σφαλλόμενον, ἅμα τῷ προελθεῖν καὶ παραλλάξαι τὸν βωμὸν ἔπεσε καὶ στενάξας ἀφῆκε τὴν ψυχήν.", "st": "Dem. 29.1"}, {"sp": "N", "t": "τὸ δέ φάρμακον Ἀρίστων μὲν ἐκ τοῦ καλάμου λαβεῖν φησιν αὐτόν, ὡς εἴρηται· πάππος δέ τις, οὗ τὴν ἱστορίαν Ἕρμιππος ἀνείληφε, φησὶ, πεσόντος αὐτοῦ παρὰ τὸν βωμὸν ἐν μὲν τῷ βιβλίῳ γεγραμμένην ἐπιστολῆς ἀρχὴν εὑρεθῆναι, Δημοσθένης Ἀντιπάτρῳ, καὶ μηδὲν ἄλλο· θαυμαζομένης δὲ τῆς περὶ τὸν θάνατον ὀξύτητος διηγεῖσθαι τοὺς παρὰ ταῖς θύραις Θρᾷκας ὡς ἔκ τινος ῥακίου λαβὼν εἰς τὴν χεῖρα προσθοῖτο τῷ στόματι καὶ καταπίοι τὸ φάρμακον αὐτοὶ δ’ ἄρα χρυσὸν ᾠήθησαν εἶναι τὸ καταπινόμενον ἡ δ’ ὑπηρετοῦσα παιδίσκη, πυνθανομένων τῶν περὶ τὸν Ἀρχίαν, φαίη πολὺν εἶναι χρόνον ἐξ οὗ φοροίη τὸν ἀπόδεσμον ἐκεῖνον ὁ Δημοσθένης ὡς φυλακτήριον. Ἐρατοσθένης δὲ καὶ αὐτὸς ἐν κρίκῳ φησὶ κοίλῳ τὸ φάρμακον φυλάσσειν· τὸν δέ κρίκον εἶναι τοῦτον αὐτῷ φόρημα περιβραχιόνιον. τῶν δ’ ἄλλων, ὅσοι γεγράφασι περὶ αὐτοῦ, πάμπολλοι δέ εἰσί, τὰς διαφορὰς οὐκ ἀναγκαῖον ἐπεξελθεῖν· πλὴν ὅτι Δημοχάρης ὁ τοῦ Δημοσθένους οἰκεῖος οἴεσθαί φησιν αὐτὸν οὐχ ὑπὸ φαρμάκου, θεῶν δὲ τιμῇ καὶ προνοίᾳ τῆς Μακεδόνων ὠμότητος ἐξαρπαγῆναι, συντόμως καταστρέψαντα καὶ ἀλύπως. κατέστρεψε δὲ ἕκτῃ ἐπὶ δέκα τοῦ Πυανεψιῶνος μηνός, ἐν ᾗ τὴν σκυθρωποτάτην τῶν Θεσμοφορίων ἡμέραν ἄγουσαι παρὰ τῇ θεῷ νηστεύουσιν αἱ γυναῖκες.", "st": "Dem. 30.1"}, {"sp": "N", "t": "τούτῳ μὲν ὀλίγον ὕστερον ὁ τῶν Ἀθηναίων δῆμος ἀξίαν ἀποδιδοὺς τιμήν εἰκόνα τε χαλκῆν ἀνέστησε καὶ τὸν πρεσβύτατον ἐψηφίσατο τῶν ἀπὸ γένους ἐν Πρυτανείῳ σίτησιν ἔχειν. καὶ τὸ ἐπίγραμμα τὸ θρυλούμενον ἐπεγράφη τῇ βάσει τοῦ ἀνδριάντος·", "st": "Dem. 30.1b"}, {"sp": "N", "t": "εἴπερ ἴσην ῥώμην γνώμῃ, Δημόσθενες, εἶχες,<br>οὔποτ’ ἂν Ἑλλήνων ἦρξεν Ἄρης Μακεδών.", "st": "Dem. 30.1c"}, {"sp": "N", "t": "οἱ γὰρ αὐτὸν τὸν Δημοσθένην τοῦτο ποιῆσαι λέγοντες ἐν Καλαυρίᾳ, μέλλοντα τὸ φάρμακον προσφέρεσθαι, κομιδῇ φλυαροῦσι.", "st": "Dem. 30.6"}, {"sp": "N", "t": "μικρὸν δὲ πρόσθεν ἢ παραβαλεῖν ἡμᾶς Ἀθήναζε λέγεταί τι τοιόνδε συμβῆναι. στρατιώτης ἐπὶ κρίσιν τινὰ καλούμενος ὑφ’ ἡγεμόνος, ὅσον εἶχε χρυσίδιον εἰς τὰς χεῖρας ἐνέθηκε τοῦ ἀνδριάντος. ἕστηκε δὲ τοὺς δακτύλους συνέχων δι’ ἀλλήλων, καὶ παραπέφυκεν οὐ μεγάλη πλάτανος. ἀπὸ ταύτης πολλὰ τῶν φύλλων, εἴτε πνεύματος ἐκ τύχης καταβαλόντος, εἴτ’ αὐτὸς οὕτως ὁ θεὶς ἐκάλυψε, περικείμενα καὶ συμπεσόντα λαθεῖν ἐποίησε τὸ χρυσίον οὐκ ὀλίγον χρόνον. ὡς δ’ ὁ ἄνθρωπος ἐπανελθὼν ἀνεῦρε καὶ διεδόθη λόγος ὑπὲρ τούτου, πολλοὶ τῶν εὐφυῶν ὑπόθεσιν λαβόντες εἰς τὸ ἀδωροδόκητον τοῦ Δημοσθένους διημιλλῶντο τοῖς ἐπιγράμμασι.", "st": "Dem. 31.1"}, {"sp": "N", "t": "Δημάδην δὲ χρόνον οὐ πολὺν ἀπολαύσαντα τῆς φυομένης δόξης ἡ Δημοσθένους δίκη κατήγαγεν εἰς Μακεδονίαν, οὓς ἐκολάκευεν αἰσχρῶς, ὑπὸ τούτων ἐξολούμενον δικαίως, ἐπαχθῆ μὲν ὄντα καὶ πρότερον αὐτοῖς, τότε δ’ εἰς αἰτίαν ἄφυκτον ἐμπεσόντα. γράμματα γὰρ ἐξέπεσεν αὐτοῦ, δι’ ὧν παρεκάλει Περδίκκαν ἐπιχειρεῖν Μακεδονίᾳ καὶ σῴζειν τοὺς Ἕλληνας ὡς ἀπὸ σαπροῦ καὶ παλαιοῦ στήμονος λέγων τὸν Ἀντίπατρον ἠρτημένους. ἐφ’ οἷς Δεινάρχου τοῦ Κορινθίου κατηγορήσαντος παροξυνθεὶς ὁ Κάσσανδρος ἐγκατέσφαξεν αὐτοῦ τῷ κόλπῳ τὸν υἱόν, εἶτα οὕτως ἐκεῖνον ἀνελεῖν προσέταξεν, ἐν τοῖς μεγίστοις διδασκόμενον ἀτυχήμασιν ὅτι πρώτους ἑαυτοὺς οἱ προδόται πωλοῦσιν, ὃ πολλάκις Δημοσθένους προαγορεύοντος οὐκ ἐπίστευσε.", "st": "Dem. 31.4"}, {"sp": "N", "t": "τὸν μὲν οὖν Δημοσθένους ἀπέχεις, Σόσσιε, βίον ἐξ ὧν ἡμεῖς ἀνέγνωμεν ἢ διηκούσαμεν.", "st": "Dem. 31.7"}, {"sp": "HDR", "t": "Κικέρων"}, {"sp": "N", "t": "Κικέρωνος δὲ τὴν μὲν μητέρα λέγουσιν Ἑλβίαν καὶ γεγονέναι καλῶς καὶ βεβιωκέναι, περὶ δὲ τοῦ πατρὸς οὐδὲν ἦν πυθέσθαι μέτριον, οἱ μὲν γὰρ ἐν κναφείῳ τινὶ καὶ γενέσθαι καὶ τραφῆναι τόν ἄνδρα λέγουσιν, οἱ δ’ εἰς Τύλλον Ἄττιον ἀνάγουσι τὴν ἀρχὴν τοῦ γένους, βασιλεύσαντα λαμπρῶς ἐν Οὐολούσκοις καὶ πολεμήσαντα Ῥωμαίοις οὐκ ἀδυνάτως. ὁ μέντοι πρῶτος ἐκ τοῦ γένους Κικέρων ἐπονομασθεὶς ἄξιος λόγου δοκεῖ γενέσθαι, διὸ τὴν ἐπίκλησιν οὐκ ἀπέρριψαν οἱ μετ’ αὐτόν, ἀλλ’ ἠσπάσαντο, καίπερ ὑπὸ πολλῶν χλευαζομένην. κίκερα γὰρ οἱ Λατῖνοι τόν ἐρέβινθον καλοῦσι, κἀκεῖνος ἐν τῷ πέρατι τῆς ῥινὸς διαστολὴν, ὡς ἔοικεν, ἀμβλεῖαν εἶχεν ὥσπερ ἐρεβίνθου διαφυήν, ἀφ’ ἧς ἐκτήσατο τὴν ἐπωνυμίαν. αὐτός γε μὴν Κικέρων, ὑπὲρ οὗ τάδε γέγραπται, τῶν φίλων αὐτὸν οἰομένων δεῖν, ὅτε πρῶτον ἀρχὴν μετῄει καὶ πολιτείας ἥπτετο, φυγεῖν τοὔνομα καὶ μεταθέσθαι, λέγεται νεανιευσάμενος εἰπεῖν ὡς ἀγωνιεῖται τόν Κικέρωνα τῶν Σκαύρων καὶ τῶν Κάτλων ἐνδοξότερον ἀποδεῖξαι. ταμιεύων δ’ ἐν Σικελίᾳ καὶ τοῖς θεοῖς ἀνάθημα ποιούμενος ἀργυροῦν τὰ μὲν πρῶτα δύο τῶν ὀνομάτων ἐπέγραψε, τόν τε Μᾶρκον καὶ τόν Τύλλιον, ἀντὶ δὲ τοῦ τρίτου σκώπτων ἐρέβινθον ἐκέλευσε παρὰ τὰ γράμματα τόν τεχνίτην ἐντορεῦσαι. ταῦτα μὲν οὖν περὶ τοῦ ὀνόματος ἱστόρηται.", "st": "Cic. 1.1"}, {"sp": "N", "t": "τεχθῆναι δὲ Κικέρωνα λέγουσιν ἀνωδύνως καί ἀπόνως λοχευθείσης αὐτοῦ τῆς μητρὸς ἡμέρᾳ τρίτῃ τῶν νέων Καλανδῶν, ἐν ᾗ νῦν οἱ ἄρχοντες εὔχονται καί θύουσιν ὑπὲρ τοῦ ἡγεμόνος. τῇ δὲ τίτθῃ φάσμα δοκεῖ γενέσθαι καί προειπεῖν ὡς ὄφελος μέγα πᾶσι Ῥωμαίοις ἐκτρεφούσῃ. ταῦτα δὲ ἄλλως ὀνείρατα καί φλύαρον εἶναι δοκοῦντα ταχέως αὐτὸς ἀπέδειξε μαντείαν ἀληθινὴν ἐν ἡλικίᾳ τοῦ μανθάνειν γενόμενος, δι’ εὐφυΐαν ἐκλάμψας καί λαβὼν ὄνομα καί δόξαν ἐν τοῖς παισίν, ὥστε τοὺς πατέρας αὑτῶν ἐπιφοιτᾶν τοῖς διδασκαλείοις ὄψει τε βουλομένους ἰδεῖν τὸν Κικέρωνα καὶ τὴν ὑμνουμένην αὐτοῦ περὶ τὰς μαθήσεις ὀξύτητα καί σύνεσιν ἱστορῆσαι, τοὺς δ’ ἀγροικοτέρους ὀργίζεσθαι τοῖς υἱέσιν ὁρῶντας ἐν ταῖς ὁδοῖς τὸν Κικέρωνα μέσον αὑτῶν ἐπὶ τιμῇ λαμβάνοντας. γενόμενος δ’, ὥσπερ ὁ Πλάτων ἀξιοῖ τὴν φιλομαθῆ καί φιλόσοφον φύσιν, οἷος ἀσπάζεσθαι πᾶν μάθημα καί μηδὲν λόγου μηδὲ παιδείας ἀτιμάζειν εἶδος, ἐρρύη πως προθυμότερον ἐπὶ ποιητικήν. καί τι καί ποιημάτιον ἔτι παιδὸς αὐτοῦ διασῴζεται, Πόντιος Γλαῦκος, ἐν τετραμέτρῳ πεποιημένον. προϊὼν δὲ τῷ χρόνῳ καί ποικιλώτερον ἁπτόμενος τῆς περὶ ταῦτα μούσης, ἔδοξεν οὐ μόνον ῥήτωρ, ἀλλὰ καί ποιητὴς ἄριστος εἶναι Ῥωμαίων. ἡ μὲν οὖν ἐπὶ τῇ ῥητορικῇ δόξα μέχρι νῦν διαμένει, καίπερ οὐ μικρᾶς γεγενημένης περὶ τοὺς λόγους καινοτομίας, τὴν δὲ ποιητικὴν αὐτοῦ, πολλῶν εὐφυῶν ἐπιγενομένων, παντάπασιν ἀκλεῆ καί ἄτιμον ἔρρειν συμβέβηκεν.", "st": "Cic. 2.1"}, {"sp": "N", "t": "ἀπαλλαγεὶς δὲ τῶν ἐν παισὶ διατριβῶν Φίλωνος ἤκουσε τοῦ ἐξ Ἀκαδημείας, ὃν μάλιστα Ῥωμαῖοι τῶν Κλειτομάχου συνήθων καί διὰ τὸν λόγον ἐθαύμασαν καί διὰ τὸν τρόπον ἠγάπησαν. ἅμα δὲ τοῖς περὶ Μούκιον ἀνδράσι συνών πολιτικοῖς καὶ πρωτεύουσι τῆς βουλῆς εἰς ἐμπειρίαν τῶν νόμων ὠφελεῖτο· καί τινα χρόνον καί στρατείας μετέσχεν ὑπὸ Σύλλᾳ περὶ τὸν Μαρσικὸν πόλεμον. εἶθ’ ὁρῶν εἰς στάσιν, ἐκ δὲ τῆς στάσεως εἰς ἄκρατον ἐμπίπτοντα τὰ πράγματα μοναρχίαν, ἐπὶ τὸν σχολαστὴν καί θεωρητικὸν ἐλθὼν βίον Ἕλλησί συνῆν φιλολόγοις καί προσεῖχε τοῖς μαθήμασιν, ἄχρι οὗ Σύλλας ἐκράτησε καί κατάστασίν τινα λαμβάνειν ἔδοξεν ἡ πόλις.", "st": "Cic. 3.1"}, {"sp": "N", "t": "ἐν δὲ τῷ χρόνῳ τούτῳ Χρυσόγονος ἀπελεύθερος Σύλλα προσαγγείλας τινὸς οὐσίαν ὡς ἐκ προγραφῆς ἀναιρεθέντος αὐτὸς ἐωνήσατο δισχιλίων δραχμῶν. ἐπεὶ δὲ Ῥώσκιος ὁ υἱὸς καί κληρονόμος τοῦ τεθνηκότος. ἠγανάκτει καί τὴν οὐσίαν ἀπεδείκνυε πεντήκοντα καί διακοσίων ταλάντων οὖσαν ἀξίαν, ὅ τε Σύλλας ἐλεγχόμενος ἐχαλέπαινε καί δίκην πατροκτονίας ἐπῆγε τῷ Ῥωσκίῳ, τοῦ Χρυσογόνου κατασκευάσαντος, ἐβοήθει δ’ οὐδείς, ἀλλ’ ἀπετρέποντο τοῦ Σύλλα τὴν χαλεπότητα δεδοικότες, οὕτω δὴ δι’ ἐρημίαν τοῦ μειρακίου τῷ Κικέρωνι προσφυγόντος οἱ φίλοι συμπαρώρμων, ὡς οὐκ ἂν αὐτῷ λαμπροτέραν αὖθις ἀρχὴν πρὸς δόξαν ἑτέραν οὐδὲ καλλίω γενησομένην. ἀναδεξάμενος οὖν τὴν συνηγορίαν καὶ κατορθώσας ἐθαυμάσθη· δεδιὼς δὲ τὸν Σύλλαν ἀπεδήμησεν εἰς τὴν Ἑλλάδα, διασπείρας λόγον ὡς τοῦ σώματος αὐτῷ θεραπείας δεομένου. καί γὰρ ἦν ὄντως ἰσχνὸς καί ἄσαρκος, ἀρρωστίᾳ στομάχου μικρὰ καί γλίσχρα μόγις ὀψὲ τῆς ὥρας προσφερόμενος· ἡ δὲ φωνὴ πολλὴ μὲν καί ἀγαθή, σκληρὰ δὲ καί ἄπλαστος, ὑπὸ δὲ τοῦ λόγου σφοδρότητα καί πάθος ἔχοντος ἀεὶ διὰ τῶν ἄνω τόνων ἐλαυνομένη φόβον παρεῖχεν ὑπὲρ τοῦ σώματος.", "st": "Cic. 3.4"}, {"sp": "N", "t": "ἀφικόμενος δ’ εἰς Ἀθήνας Ἀντιόχου τοῦ Ἀσκαλωνίτου διήκουσε, τῇ μὲν εὐροίᾳ τῶν λόγων αὐτοῦ καὶ χάριτι κηλούμενος, ἃ δ’ ἐν τοῖς δόγμασιν ἐνεωτέριζεν οὐκ ἐπαινῶν, ἤδη γὰρ ἐξίστατο τῆς νέας λεγομένης Ἀκαδημείας ὁ Ἀντίοχος καὶ τὴν Καρνεάδου στάσιν ἐγκατέλειπεν, εἴτε καμπτόμενος ὑπὸ τῆς ἐναργείας καὶ τῶν αἰσθήσεων, εἴτε, ὥς φασιν ἔνιοι, φιλοτιμίᾳ τινὶ καὶ διαφορᾷ πρὸς τοὺς Κλειτομάχου καὶ Φίλωνος συνήθεις τὸν Στωικὸν ἐκ μεταβολῆς θεραπεύων λόγον ἐν τοῖς πλείστοις. ὁ δὲ Κικέρων ἐκεῖνα ἠγάπα κἀκείνοις προσεῖχε μᾶλλον, διανοούμενος, εἰ παντάπασιν ἐκπέσοι τοῦ τὰ κοινὰ πράσσειν, δεῦρο μετενεγκάμενος τὸν βίον ἐκ τῆς ἀγορᾶς καὶ τῆς πολιτείας ἐν ἡσυχίᾳ μετὰ φιλοσοφίας καταζῆν.", "st": "Cic. 4.1"}, {"sp": "N", "t": "ἐπεὶ δ’ αὐτῷ Σύλλας τε προσηγγέλθη τεθνηκώς, καὶ τὸ σῶμα τοῖς γυμνασίοις ἀναρρωννύμενον εἰς ἕξιν ἐβάδιζε νεανικήν, ἥ τε φωνὴ λαμβάνουσα πλάσιν ἡδεῖα μὲν πρὸς ἀκοὴν ἐτέθραπτο, μετρίως δὲ πρὸς τὴν ἕξιν ἥρμοστο τοῦ σώματος, πολλὰ μὲν τῶν ἀπὸ Ῥώμης φίλων γραφόντων καὶ δεομένων, πολλὰ δ’ Ἀντιόχου παρακελευομένου τοῖς κοινοῖς ἐπιβαλεῖν πράγμασιν, αὖθις ὥσπερ ὄργανον ἐξηρτύετο τὸν ῥητορικὸν λόγον καὶ ἀνεκίνει τὴν πολιτικὴν δύναμιν, αὑτόν τε ταῖς μελέταις διαπονῶν καὶ τοὺς ἐπαινουμένους μετιὼν ῥήτορας. ὅθεν εἰς Ἀσίαν καὶ Ῥόδον ἔπλευσε, καὶ τῶν μὲν Ἀσιανῶν ῥητόρων Ξενοκλεῖ τῷ Ἀδραμυττηνῷ καὶ Διονυσίῳ τῷ Μάγνητι καὶ Μενίππῳ τῷ Καρὶ συνεσχόλασεν, ἐν δὲ Ῥόδῳ ῥήτορι μὲν Ἀπολλωνίῳ τῷ Μόλωνος, φιλοσόφῳ δὲ Ποσειδωνίῳ. λέγεται δὲ τὸν Ἀπολλώνιον οὐ συνιέντα τὴν Ῥωμαϊκὴν διάλεκτον δεηθῆναι τοῦ Κικέρωνος Ἑλληνιστὶ μελετῆσαι· τὸν δ’ ὑπακοῦσαι προθύμως, οἰόμενον οὕτως ἔσεσθαι βελτίονα τὴν ἐπανόρθωσιν· ἐπεὶ δ’ ἐμελέτησε, τοὺς μὲν ἄλλους ἐκπεπλῆχθαι καὶ διαμιλλᾶσθαι πρὸς ἀλλήλους τοῖς ἐπαίνοις, τὸν δ’ Ἀπολλώνιον οὔτ’ ἀκροώμενον αὐτοῦ διαχυθῆναι καὶ παυσαμένου σύννουν καθέζεσθαι πολὺν χρόνον, ἀχθομένου δὲ τοῦ Κικέρωνος εἰπεῖν· σὲ μὲν, ὦ Κικέρων, ἐπαινῶ καὶ θαυμάζω, τῆς δὲ Ἑλλάδος οἰκτείρω τὴν τύχην, ὁρῶν, ἃ μόνα τῶν καλῶν ἡμῖν ὑπελείπετο, καὶ ταῦτα Ῥωμαίοις διὰ σοῦ προσγενόμενα, παιδείαν καὶ λόγον.", "st": "Cic. 4.4"}, {"sp": "N", "t": "ὁ γοῦν Κικέρων ἐλπίδων μεστὸς ἐπὶ τὴν πολιτείαν φερόμενος ὑπὸ χρησμοῦ τινος ἀπημβλύνθη τὴν ὁρμήν. ἐρομένῳ γὰρ αὐτῷ τόν ἐν Δελφοῖς θεὸν ὅπως ἂν ἐνδοξότατος γένοιτο, προσέταξεν ἡ Πυθία τὴν ἑαυτοῦ φύσιν, ἀλλὰ μὴ τὴν τῶν πολλῶν δόξαν, ἡγεμόνα ποιεῖσθαι τοῦ βίου. καὶ τόν γε πρῶτον ἐν Ῥώμῃ χρόνον εὐλαβῶς διῆγε καὶ ταῖς ἀρχαῖς ὀκνηρῶς προσῄει καὶ παρημελεῖτο, ταῦτα δὴ τὰ Ῥωμαίων τοῖς βαναυσοτάτοις πρόχειρα καὶ συνήθη ῥήματα, Γραικὸς καὶ σχολαστικὸς ἀκούων. ἐπεὶ δὲ φύσει φιλότιμος ὢν καὶ παροξυνόμενος ὑπὸ τοῦ πατρὸς καὶ τῶν φίλων ἐπέδωκεν εἰς τὸ συνηγορεῖν ἑαυτόν, οὐκ ἠρέμα τῷ πρωτείῳ προσῆγεν, ἀλλ’ εὐθὺς ἐξέλαμψε τῇ δόξῃ καὶ διέφερε πολὺ τῶν ἀγωνιζομένων ἐπ’ ἀγορᾶς.", "st": "Cic. 5.1"}, {"sp": "N", "t": "λέγεται δὲ καὶ αὐτὸς οὐδὲν ἧττον νοσήσας τοῦ Δημοσθένους πρὸς τὴν ὑπόκρισιν, τοῦτο μὲν Ῥωσκίῳ τῷ κωμῳδῷ, τοῦτο δ’ Αἰσώπῳ τῷ τραγῳδῷ προσέχειν ἐπιμελῶς. τόν δ’ Αἴσωπον τοῦτον ἱστοροῦσιν ὑποκρινόμενον ἐν θεάτρῳ τόν περὶ τῆς τιμωρίας τοῦ Θυέστου βουλευόμενον Ἀτρέα, τῶν ὑπηρετῶν τινος ἄφνω παραδραμόντος, ἔξω τῶν ἑαυτοῦ λογισμῶν διὰ τὸ πάθος ὄντα τῷ σκήπτρῳ πατάξαι καὶ ἀνελεῖν. οὐ μικρὰ δὲ πρὸς τὸ πείθειν ὑπῆρχεν ἐκ τοῦ ὑποκρίνεσθαι ῥοπὴ τῷ Κικέρωνι. καὶ τούς γε τῷ βοᾶν μεγάλα χρωμένους ῥήτορας ἐπισκώπτων ἔλεγε δι’ ἀσθένειαν ἐπὶ τὴν κραυγὴν ὥσπερ χωλοὺς ἐφ’ ἵππον πηδᾶν. ἡ δὲ περὶ τὰ σκώμματα καὶ τὴν παιδιὰν ταύτην εὐτραπελία δικανικὸν μὲν ἐδόκει καὶ γλαφυρὸν, χρώμενος δ’ αὐτῇ κατακόρως πολλοὺς ἐλύπει καὶ κακοηθείας ἐλάμβανε δόξαν.", "st": "Cic. 5.4"}, {"sp": "N", "t": "ἀποδειχθεὶς δὲ ταμίας ἐν σιτοδείᾳ καὶ λαχὼν Σικελίαν ἠνώχλησε τοῖς ἀνθρώποις ἐν ἀρχῇ σῖτον εἰς Ῥώμην ἀποστέλλειν ἀναγκαζομένοις. ὕστερον δὲ τῆς ἐπιμελείας καὶ δικαιοσύνης καὶ πρᾳότητος αὐτοῦ πεῖραν λαμβάνοντες ὡς οὐδένα τῶν πώποθ’ ἡγεμόνων ἐτίμησαν. ἐπεὶ δὲ πολλοὶ τῶν ἀπὸ Ῥώμης νέων ἔνδοξοι καὶ γεγονότες καλῶς, αἰτίαν ἔχοντες ἀταξίας καὶ μαλακίας περὶ τὸν πόλεμον, ἀνεπέμφθησαν ἐπὶ τὸν στρατηγὸν τῆς Σικελίας, συνεῖπεν αὐτοῖς ὁ Κικέρων ἐπιφανῶς καὶ περιεποίησεν. ἐπὶ τούτοις οὖν μέγα φρονῶν εἰς Ῥώμην βαδίζων γελοῖόν τι παθεῖν φησι. συντυχὼν γὰρ ἀνδρὶ τῶν ἐπιφανῶν φίλῳ δοκοῦντι περὶ Καμπανίαν, ἐρέσθαι τίνα δὴ τῶν πεπραγμένων ὑπ’ αὐτοῦ λόγον ἔχουσι Ῥωμαῖοι καὶ τί φρονοῦσιν, ὡς ὀνόματος καὶ δόξης τῶν πεπραγμένων αὐτῷ τὴν πόλιν ἅπασαν ἐμπεπληκώς· τὸν δ’ εἰπεῖν· ποῦ γὰρ ἦς, ὦ Κικέρων, τὸν χρόνον τοῦτον; τότε μὲν οὖν ἐξαθυμῆσαι παντάπασιν, εἰ καθάπερ εἰς πέλαγος ἀχανὲς τὴν πόλιν ἐμπεσὼν ὁ περὶ αὐτοῦ λόγος οὐδὲν εἰς δόξαν ἐπίδηλον πεποίηκεν· ὕστερον δὲ λογισμὸν ἑαυτῷ διδοὺς πολὺ τῆς φιλοτιμίας ὑφεῖλεν, ὡς πρὸς ἀόριστον πρᾶγμα τὴν δόξαν ἁμιλλώμενος καὶ πέρας οὐκ ἐφικτὸν ἔχουσαν. οὐ μὴν ἀλλὰ τό γε χαίρειν ἐπαινούμενον διαφερόντως καὶ πρὸς δόξαν ἐμπαθέστερον ἔχειν ἄχρι παντὸς αὐτῷ παρέμεινε καὶ πολλοὺς πολλάκις τῶν ὀρθῶν ἐπετάραξε λογισμῶν.", "st": "Cic. 6.1"}, {"sp": "N", "t": "ἁπτόμενος δὲ τῆς πολιτείας προθυμότερον, αἰσχρὸν ἡγεῖτο τοὺς μὲν βαναύσους ὀργάνοις χρωμένους καὶ σκεύεσιν ἀψύχοις μηδενὸς ἀγνοεῖν ὄνομα μηδὲ χώραν ἢ δύναμιν αὐτῶν, τὸν δὲ πολιτικόν, ᾧ δι’ ἀνθρώπων αἱ κοιναὶ πράξεις περαίνονται, ῥᾳθύμως καὶ ἀμελῶς ἔχειν περὶ τὴν τῶν πολιτῶν γνῶσιν. ὅθεν οὐ μόνον τῶν ὀνομάτων εἴθιζε μνημονεύειν αὐτόν, ἀλλὰ καὶ τόπον ἐν ᾧ τῶν γνωρίμων ἕκαστος οἰκεῖ, καὶ χωρίον οὐ κέκτηται, καὶ φίλους οἷστισι χρῆται, καὶ γείτονας ἐγίνωσκε· καὶ πᾶσαν ὁδὸν Ἰταλίας διαπορευομένῳ Κικέρωνι πρόχειρον ἦν εἰπεῖν καὶ ἐπιδεῖξαι τοὺς τῶν φίλων ἀγροὺς καὶ τὰς ἐπαύλεις.", "st": "Cic. 7.1"}, {"sp": "N", "t": "οὐσίαν δὲ μικρὰν μέν, ἱκανὴν δὲ καὶ ταῖς δαπάναις ἐπαρκῆ κεκτημένος ἐθαυμάζετο μήτε μισθοὺς μήτε δῶρα προσιέμενος ἀπὸ τῆς συνηγορίας, μάλιστα δ’ ὅτε τὴν κατὰ Βέρρου δίκην ἀνέλαβε, τοῦτον γὰρ στρατηγὸν γεγονότα τῆς Σικελίας καὶ πολλὰ πεπονηρευμένον τῶν Σικελιωτῶν διωκόντων εἷλεν, οὐκ εἰπών, ἀλλ’ ἐξ αὐτοῦ τρόπον τινὰ τοῦ μὴ εἰπεῖν. τῶν γὰρ στρατηγῶν τῷ Βέρρῃ χαριζομένων καὶ τὴν δίκην ὑπερθέσεσι καὶ διακρούσεσι πολλαῖς εἰς τὴν ὑστάτην ἐκβαλλόντων, ὡς ἦν πρόδηλον ὅτι τοῖς λόγοις ὁ τῆς ἡμέρας οὐκ ἐξαρκέσει χρόνος οὐδὲ λήψεται πέρας ἡ κρίσις, ἀναστὰς ὁ Κικέρων ἔφη μὴ δεῖσθαι λόγων, ἀλλ’ ἐπαγαγὼν τοὺς μάρτυρας καὶ ἐπικρίνας ἐκέλευσε φέρειν τὴν ψῆφον τοὺς δικαστάς. ὅμως δὲ πολλὰ χαρίεντα διαμνημονεύεται καὶ περὶ ἐκείνην αὐτοῦ τὴν δίκην. βέρρην γὰρ οἱ Ῥωμαῖοι τὸν ἐκτετμημένον χοῖρον καλοῦσιν. ὡς οὖν ἀπελευθερικὸς ἄνθρωπος ἔνοχος τῷ ἰουδαΐζειν, ὄνομα Κεκίλιος, ἐβούλετο παρωσάμενος τοὺς Σικελιώτας κατηγορεῖν τοῦ Βέρρου· τί Ἰουδαίῳ πρὸς χοῖρον; ἔφη ὁ Κικέρων. ἦν δὲ τῷ Βέρρῃ ἀντίπαις υἱὸς, οὐκ ἐλευθερίως δοκῶν προΐστασθαι τῆς ὥρας. λοιδορηθεὶς οὖν ὁ Κικέρων εἰς μαλακίαν ὑπὸ τοῦ Βέρρου, τοῖς υἱοῖς, εἶπεν, ἐντὸς θυρῶν δεῖ λοιδορεῖσθαι. τοῦ δὲ ῥήτορος Ὁρτησίου τὴν μὲν εὐθεῖαν τῷ Βέρρῃ συνειπεῖν μὴ τολμήσαντος, ἐν δὲ τῷ τιμήματι πεισθέντος παραγενέσθαι καὶ λαβόντος ἐλεφαντίνην Σφίγγα μισθόν, εἶπέ τι πλαγίως ὁ Κικέρων πρὸς αὐτόν τοῦ δὲ φήσαντος αἰνιγμάτων λύσεως ἀπείρως ἔχειν, καὶ μὴν ἐπὶ τῆς οἰκίας ἔφη, τὴν Σφίγγα ἔχεις.", "st": "Cic. 7.3"}, {"sp": "N", "t": "οὕτω δὲ τοῦ Βέρρου καταδικασθέντος, ἑβδομήκοντα πέντε μυριάδων τιμησάμενος τὴν δίκην ὁ Κικέρων διαβολὴν ἔσχεν ὡς ἐπ’ ἀργυρίῳ τὸ τίμημα καθυφειμένος. οὐ μὴν ἀλλ’ οἱ Σικελιῶται χάριν εἰδότες ἀγορανομοῦντος αὐτοῦ πολλὰ μὲν ἄγοντες ἀπὸ τῆς νήσου, πολλὰ δὲ φέροντες ἧκον, ὧν οὐδὲν ἐποιήσατο κέρδος, ἀλλ’ ὅσον ἐπευωνίσαι τὴν ἀγορὰν ἀπεχρήσατο τῇ φιλοτιμίᾳ τῶν ἀνθρώπων.", "st": "Cic. 8.1"}, {"sp": "N", "t": "ἐκέκτητο δὲ χωρίον καλὸν ἐν Ἄρποις, καὶ περὶ Νέαν πόλιν ἦν ἀγρὸς καὶ περὶ Πομπηΐους ἕτερος, οὐ μεγάλοι· φερνή τε Τερεντίας τῆς γυναικὸς προσεγένετο μυριάδων δέκα, καὶ κληρονομία τις εἰς ἐννέα δηναρίων συναχθεῖσα μυριάδας, ἀπὸ τούτων ἐλευθερίως ἅμα καὶ σωφρόνως διῆγε μετὰ τῶν συμβιούντων Ἑλλήνων καὶ Ῥωμαίων φιλολογῶν, σπάνιον, εἴ ποτε, πρὸ δυσμῶν ἡλίου κατακλινόμενος, οὐχ οὕτω δι’ ἀσχολίαν, ὡς διὰ τὸ σῶμα τῷ στομάχῳ μοχθηρῶς διακείμενον. ἦν δὲ καὶ τὴν ἄλλην περὶ τὸ σῶμα θεραπείαν ἀκριβὴς καὶ περιττός, ὥστε καὶ τρίψεσι καὶ περιπάτοις ἀριθμῷ τεταγμένοις χρῆσθαι. τοῦτον τὸν τρόπον διαπαιδαγωγῶν τὴν ἕξιν ἄνοσον καὶ διαρκῆ πρὸς πολλοὺς καὶ μεγάλους ἀγῶνας καὶ πόνους συνεῖχεν. οἰκίαν δὲ τὴν μὲν πατρῴαν τῷ ἀδελφῷ παρεχώρησεν, αὐτὸς δ’ ᾤκει περὶ τὸ Παλάτιον ὑπὲρ τοῦ μὴ μακρὰν βαδίζοντας ἐνοχλεῖσθαι τοὺς θεραπεύοντας αὐτόν. ἐθεράπευον δὲ καθ’ ἡμέραν ἐπὶ θύρας φοιτῶντες οὐκ ἐλάττονες ἢ Κράσσον ἐπὶ πλούτῳ καὶ Πομπήιον διὰ τὴν ἐν τοῖς στρατεύμασι δύναμιν, θαυμαζομένους μάλιστα Ῥωμαίων καὶ μεγίστους ὄντας. Πομπήιος δὲ καὶ Κικέρωνα ἐθεράπευε, καὶ μεγάλα πρὸς δύναμιν αὐτῷ καὶ δόξαν ἡ Κικέρωνος συνέπραξε πολιτεία.", "st": "Cic. 8.3"}, {"sp": "N", "t": "στρατηγίαν δὲ μετιόντων ἅμα σὺν αὐτῷ πολλῶν καὶ μεγάλων πρῶτος ἁπάντων ἀνηγορεύθη· καὶ τὰς κρίσεις ἔδοξε καθαρῶς καὶ καλῶς βραβεῦσαι. λέγεται δὲ καὶ Λικίννιος Μᾶκερ, ἀνὴρ καὶ καθ’ αὑτὸν ἰσχύων ἐν τῇ πόλει μέγα καὶ Κράσσῳ χρώμενος βοηθῷ, κρινόμενος κλοπῆς ἐπ’ αὐτοῦ, τῇ δυνάμει καὶ σπουδῇ πεποιθώς, ἔτι τὴν ψῆφον τῶν κριτῶν διαφερόντων ἀπαλλαγεὶς οἴκαδε κείρασθαί τε τὴν κεφαλὴν κατὰ τάχος καὶ καθαρὸν ἱμάτιον ὡς νενικηκὼς λαβὼν αὖθις εἰς ἀγορὰν προϊέναι· τοῦ δὲ Κράσσου περὶ τὴν αὔλειον ἀπαντήσαντος αὐτῷ καὶ φράσαντος ὅτι πάσαις ἑάλωκε ταῖς ψήφοις, ἀναστρέψας καὶ κατακλινεὶς ἀποθανεῖν. τὸ δὲ πρᾶγμα τῷ Κικέρωνι δόξαν ἤνεγκεν ὡς ἐπιμελῶς βραβεύσαντι τὸ δικαστήριον. ἐπεὶ δὲ Οὐατίνιος, ἀνὴρ ἔχων τι τραχὺ καὶ πρὸς τοὺς ἄρχοντας ὀλίγωρον ἐν ταῖς συνηγορίαις, χοιράδων δὲ τὸν τράχηλον περίπλεως, ᾐτεῖτό τι καταστὰς παρὰ τοῦ Κικέρωνος, καὶ μὴ διδόντος, ἀλλὰ βουλευομένου πολὺν χρόνον, εἶπεν ὡς οὐκ ἂν αὐτός διστάσειε περὶ τούτου στρατηγῶν, ἐπιστραφεὶς ὁ Κικέρων, ἀλλ’ ἐγώ, εἶπεν, οὐκ ἔχω τηλικοῦτον.", "st": "Cic. 9.1"}, {"sp": "N", "t": "ἔτι δ’ ἡμέρας δύο ἢ τρεῖς ἔχοντι τῆς ἀρχῆς αὐτῷ προσήγαγέ τις Μανίλιον εὐθύνων κλοπῆς. ὁ δὲ Μανίλιος οὗτος εὔνοιαν εἶχε καὶ σπουδὴν ὑπὸ τοῦ δήμου, δοκῶν ἐλαύνεσθαι διὰ Πομπήϊον· ἐκείνου γὰρ ἦν φίλος. αἰτουμένου δ’ ἡμέρας αὐτοῦ μίαν ὁ Κικέρων μόνην τὴν ἐπιοῦσαν ἔδωκε· καὶ ὁ δῆμος ἠγανάκτησεν εἰθισμένων τῶν στρατηγῶν δέκα τοὐλάχιστον ἡμέρας διδόναι τοῖς κινδυνεύουσι. τῶν δὲ δημάρχων αὐτὸν διαγαγόντων ἐπὶ τὸ βῆμα καὶ κατηγορούντων, ἀκουσθῆναι δεηθεὶς εἶπεν ὅτι τοῖς κινδυνεύουσιν ἀεί, καθ’ ὅσον οἱ νόμοι παρείκουσι, κεχρημένος ἐπιεικῶς καὶ φιλανθρώπως δεινὸν ἡγεῖτο τῷ Μανιλίῳ ταὐτὰ μὴ παρασχεῖν ἧς οὖν ἔτι μόνης κύριος ἦν ἡμέρας στρατηγῶν, ταύτην ἐπίτηδες ὁρίσαι· τὸ γὰρ εἰς ἄλλον ἄρχοντα τὴν κρίσιν ἐκβαλεῖν οὐκ εἶναι βουλομένου βοηθεῖν. ταὐτὰ λεχθέντα θαυμαστὴν ἐποίησε τοῦ δήμου μεταβολήν καὶ πολλὰ κατευφημοῦντες αὐτόν ἐδέοντο τὴν ὑπὲρ τοῦ Μανιλίου συνηγορίαν ἀναλαβεῖν. ὁ δ’ ὑπέστη προθύμως, οὐχ ἥκιστα διὰ Πομπήϊον ἀπόντα· καὶ καταστὰς πάλιν ἐξ ὑπαρχῆς ἐδημηγόρησε, νεανικῶς τῶν ὀλιγαρχικῶν καὶ τῷ Πομπηίῳ φθονούντων καθαπτόμενος.", "st": "Cic. 9.4"}, {"sp": "N", "t": "ἐπὶ δὲ τὴν ὑπατείαν οὐχ ἧττον ὑπὸ τῶν ἀριστοκρατικῶν ἢ τῶν πολλῶν προήχθη διὰ τὴν πόλιν ἐξ αἰτίας αὐτῷ τοιαύτης συναγωνισαμένων. τῆς ὑπὸ Σύλλα γενομένης μεταβολῆς περὶ τὴν πολιτείαν ἐν ἀρχῇ μὲν ἀτόπου φανείσης, τότε δὲ τοῖς πολλοῖς ὑπὸ χρόνου καὶ συνηθείας ἤδη τινὰ κατάστασιν ἔχειν οὐ φαύλην δοκούσης, ἦσαν οἱ τὰ παρόντα διασεῖσαι καὶ μεταθεῖναι ζητοῦντες ἰδίων ἕνεκα πλεονεξιῶν, οὐ πρὸς τὸ βέλτιστον, Πομπηΐου μὲν ἔτι τοῖς βασιλεῦσιν ἐν Πόντῳ καὶ Ἀρμενίᾳ πολεμοῦντος, ἐν δὲ τῇ Ῥώμῃ μηδεμιᾶς ὑφεστώσης πρὸς τοὺς νεωτερίζοντας ἀξιομάχου δυνάμεως. οὗτοι κορυφαῖον εἶχον ἄνδρα τολμητὴν καὶ μεγαλοπράγμονα καὶ ποικίλον τὸ ἦθος, Λεύκιον Κατιλίναν, ὃς αἰτίαν ποτὲ πρὸς ἄλλοις ἀδικήμασι μεγάλοις ἔλαβε παρθένῳ συγγεγονέναι θυγατρί, κτεῖναι δ’ ἀδελφὸν αὑτοῦ· καὶ δίκην ἐπὶ τούτῳ φοβούμενος ἔπεισε Σύλλαν ὡς ἔτι ζῶντα τὸν ἄνθρωπον ἐν τοῖς ἀποθανουμένοις προγράψαι. τοῦτον οὖν προστάτην οἱ πονηροὶ λαβόντες ἄλλας τε πίστεις ἀλλήλοις ἔδοσαν καὶ καταθύσαντες ἄνθρωπον ἐγεύσαντο τῶν σαρκῶν, διέφθαρτο δ’ ὑπ’ αὐτοῦ πολὺ μέρος τῆς ἐν τῇ πόλει νεότητος, ἡδονὰς καὶ πότους καὶ γυναικῶν ἔρωτας ἀεὶ προξενοῦντος ἑκάστῳ καὶ τὴν εἰς ταῦτα δαπάνην ἀφειδῶς παρασκευάζοντος. ἐπῆρτο δ’ ἥ τε Τυρρηνία πρὸς ἀπόστασιν ὅλη καὶ τὰ πολλὰ τῆς ἐντὸς Ἄλπεων Γαλατίας. ἐπισφαλέστατα δ’ ἡ Ῥώμη πρὸς μεταβολὴν εἶχε διὰ τὴν ἐν ταῖς οὐσίαις ἀνωμαλίαν, τῶν μὲν ἐν δόξῃ μάλιστα καὶ φρονήματι κατεπτωχευμένων εἰς θέατρα καὶ δεῖπνα καὶ φιλαρχίας καὶ οἰκοδομίας, τῶν δὲ πλούτων εἰς ἀγεννεῖς καὶ ταπεινοὺς συνερρυηκότων ἀνθρώπους, ὥστε μικρᾶς ῥοπῆς δεῖσθαι τὰ πράγματα καὶ παντὸς εἶναι τοῦ τολμήσαντος ἐκστῆσαι τὴν πολιτείαν αὐτὴν ὑφ’ αὑτῆς νοσοῦσαν.", "st": "Cic. 10.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ βουλόμενος ὁ Κατιλίνας ἰσχυρόν τι προκαταλαβεῖν ὁρμητήριον ὑπατείαν μετῄει· καὶ λαμπρὸς ἦν ταῖς ἐλπίσιν ὡς Γαΐῳ Ἀντωνίῳ συνυπατεύσων, ἀνδρὶ καθ’ αὑτὸν μὲν οὔτε πρὸς τὸ βέλτιον οὔτε πρὸς τὸ χεῖρον ἡγεμονικῷ, προσθήκῃ δ’ ἄγοντος ἑτέρου δυνάμεως ἐσομένῳ. ταῦτα δὴ τῶν καλῶν καὶ ἀγαθῶν οἱ πλεῖστοι προαισθόμενοι τὸν Κικέρωνα προῆγον ἐπὶ τὴν ὑπατείαν· καὶ τοῦ δήμου δεξαμένου προθύμως ὁ μὲν Κατιλίνας ἐξέπεσε, Κικέρων δὲ καὶ Γάιος Ἀντώνιος ᾑρέθησαν. καίτοι τῶν μετιόντων ὁ Κικέρων μόνος ἦν ἐξ ἱππικοῦ πατρός, οὐ βουλευτοῦ, γεγονώς.", "st": "Cic. 11.1"}, {"sp": "N", "t": "καὶ τὰ μὲν περὶ Κατιλίναν ἔμελλεν ἔτι τοὺς πολλοὺς λανθάνοντα, προάγωνες δὲ μεγάλοι τὴν Κικέρωνος ὑπατείαν ἐξεδέξαντο. τοῦτο μὲν γὰρ οἱ κεκωλυμένοι κατὰ τοὺς Σύλλα νόμους ἄρχειν, οὔτ’ ἀσθενεῖς ὄντες οὔτ’ ὀλίγοι, μετιόντες ἀρχὰς ἐδημαγώγουν, πολλὰ τῆς Σύλλα τυραννίδος ἀληθῆ μὲν καὶ δίκαια κατηγοροῦντες, οὐ μὴν ἐν δέοντι τὴν πολιτείαν οὐδὲ σὺν καιρῷ κινοῦντες· τοῦτο δὲ νόμους εἰσῆγον οἱ δήμαρχοι πρὸς τὴν αὐτὴν ὑπόθεσιν, δεκαδαρχίαν καθιστάντες αὐτοκρατόρων ἀνδρῶν, οἷς ἐφεῖτο πάσης μὲν Ἰταλίας, πάσης δὲ Συρίας, καὶ ὅσα διὰ Πομπηΐου νεωστὶ προσώριστο κυρίους ὄντας πωλεῖν τὰ δημόσια, κρίνειν οὓς δοκοίη, φυγάδας ἐκβάλλειν, συνοικίζειν πόλεις, χρήματα λαμβάνειν ἐκ τοῦ ταμιείου, στρατιώτας τρέφειν καὶ καταλέγειν ὁπόσων δέοιντο. διὸ καὶ τῷ νόμῳ προσεῖχον ἄλλοι τε τῶν ἐπιφανῶν καὶ πρῶτος Ἀντώνιος ὁ τοῦ Κικέρωνος συνάρχων ὡς τῶν δέκα γενησόμενος. ἐδόκει δὲ καὶ τὸν Κατιλίνα νεωτερισμὸν εἰδὼς οὐ δυσχεραίνειν ὑπὸ πλήθους δανείων· ὃ μάλιστα τοῖς ἀρίστοις φόβον παρεῖχε.", "st": "Cic. 12.1"}, {"sp": "N", "t": "καὶ τοῦτον πρῶτον θεραπεύων ὁ Κικέρων ἐκείνῳ μὲν ἐψηφίσατο τῶν ἐπαρχιῶν Μακεδονίαν, αὑτῷ δὲ τὴν Γαλατίαν διδομένην παρῃτήσατο, καὶ κατειργάσατο τῇ χάριτι ταύτῃ τὸν Ἀντώνιον ὥσπερ ὑποκριτὴν ἔμμισθον αὐτῷ τὰ δεύτερα λέγειν ὑπὲρ τῆς πατρίδος, ὡς δ’ οὗτος ἑαλώκει καὶ χειροήθης ἐγεγόνει, μᾶλλον ἤδη θαρρῶν ὁ Κικέρων ἐνίστατο πρὸς τοὺς καινοτομοῦντας. ἐν μὲν οὖν τῇ βουλῇ κατηγορίαν τινὰ τοῦ νόμου διαθέμενος οὕτως ἐξέπληξεν αὐτοὺς τοὺς εἰσφέροντας ὥστε μηδέν’ ἀντιλέγειν. ἐπεὶ δ’ αὖθις ἐπεχείρουν καὶ παρεσκευασμένοι προεκαλοῦντο τοὺς ὑπάτους ἐπὶ τὸν δῆμον, οὐδὲν ὑποδείσας ὁ Κικέρων, ἀλλὰ τὴν βουλὴν ἕπεσθαι κελεύσας καὶ προελθών, οὐ μόνον ἐξέβαλε τὸν νόμον, ἀλλὰ καὶ τῶν ἄλλων ἀπογνῶναι τοὺς δημάρχους ἐποίησε, παρὰ τοσοῦτον τῷ λόγῳ κρατηθέντας ὑπ’ αὐτοῦ.", "st": "Cic. 12.1b"}, {"sp": "N", "t": "μάλιστα γὰρ οὗτος ὁ ἀνὴρ ἐπέδειξε Ῥωμαίοις ὅσον ἡδονῆς λόγος τῷ καλῷ προστίθησι, καὶ ὅτι τὸ δίκαιον ἀήττητόν ἐστιν ἂν ὀρθῶς λέγηται, καὶ δεῖ τὸν ἐμμελῶς πολιτευόμενον ἀεὶ τῷ μὲν ἔργῳ τὸ καλὸν ἀντὶ τοῦ κολακεύοντος αἱρεῖσθαι, τῷ δὲ λόγῳ τὸ λυποῦν ἀφαιρεῖν τοῦ συμφέροντος, δεῖγμα δὲ αὐτοῦ τῆς περὶ τὸν λόγον χάριτος καὶ τὸ περὶ τὰς θέας ἐν τῇ ὑπατείᾳ γενόμενον. τῶν γὰρ ἱππικῶν πρότερον ἐν τοῖς θεάτροις ἀναμεμιγμένων τοῖς πολλοῖς καὶ μετὰ τοῦ δήμου θεωμένων ὡς ἔτυχε, πρῶτος διέκρινεν ἐπὶ τιμῇ τοὺς ἱππέας ἀπὸ τῶν ἄλλων πολιτῶν Μᾶρκος Ὄθων στρατηγῶν, καὶ διένειμεν ἰδίαν ἐκείνοις θέαν, ἣν ἔτι καὶ νῦν ἐξαίρετον ἔχουσι. τοῦτο πρὸς ἀτιμίας ὁ δῆμος ἔλαβε, καὶ φανέντος ἐν θεάτρῳ τοῦ Ὄθωνος ἐφυβρίζων ἐσύριττεν, οἱ δ’ ἱππεῖς ὑπέλαβον κρότῳ τὸν ἄνδρα λαμπρῶς, αὖθις δὲ ὁ δῆμος ἐπέτεινε τὸν συριγμόν, εἶτα ἐκεῖνοι τὸν κρότον. ἐκ δὲ τούτου τραπόμενοι πρὸς ἀλλήλους ἐχρῶντο λοιδορίαις, καὶ τὸ θέατρον ἀκοσμία κατεῖχεν. ἐπεὶ δ’ ὁ Κικέρων ἧκε πυθόμενος καὶ τὸν δῆμον ἐκκαλέσας πρὸς τὸ τῆς Ἐνυοῦς ἱερὸν ἐπετίμησε καὶ παρῄνεσεν, ἀπελθόντες αὖθις εἰς τὸ θέατρον ἐκρότουν τὸν Ὄθωνα λαμπρῶς καὶ πρὸς τοὺς ἱππέας ἅμιλλαν ἐποιοῦντο περὶ τιμῶν καὶ δόξης τοῦ ἀνδρός.", "st": "Cic. 13.1"}, {"sp": "N", "t": "ἡ δὲ περὶ τὸν Κατιλίναν συνωμοσία πτήξασα καὶ καταδείσασα τὴν ἀρχήν αὖθις ἀνεθάρρει, καὶ συνῆγον ἀλλήλους καὶ παρεκάλουν εὐτολμότερον ἅπτεσθαι τῶν πραγμάτων πρὶν ἐπανελθεῖν Πομπήϊον ἤδη λεγόμενον ὑποστρέφειν μετὰ τῆς δυνάμεως. μάλιστα δὲ τὸν Κατιλίναν ἐξηρέθιζον οἱ Σύλλα πάλαι στρατιῶται, διαπεφυκότες μέν ὅλης τῆς Ἰταλίας, πλεῖστοι δὲ καὶ μαχιμώτατοι ταῖς Τυρρηνικαῖς ἐγκατεσπαρμένοι πόλεσιν, ἁρπαγὰς πάλιν καὶ διαφορήσεις πλούτων ἑτοίμων ὀνειροπολοῦντες. οὗτοι γὰρ ἡγεμόνα Μάλλιον ἔχοντες, ἄνδρα τῶν ἐπιφανῶς ὑπὸ Σύλλᾳ στρατευσαμένων, συνίσταντο τῷ Κατιλίνᾳ καὶ παρῆσαν εἰς Ῥώμην συναρχαιρεσιάσοντες. ὑπατείαν γὰρ αὖθις μετῄει, βεβουλευμένος ἀνελεῖν τὸν Κικέρωνα περὶ αὐτόν τῶν ἀρχαιρεσιῶν τὸν θόρυβον. ἐδόκει δὲ καὶ τὸ δαιμόνιον προσημαίνειν τὰ πρασσόμενα σεισμοῖς καὶ κεραυνοῖς καὶ φάσμασιν. αἱ δ’ ἀπ’ ἀνθρώπων μηνύσεις ἀληθεῖς μέν ἦσαν, οὔπω δ’ εἰς ἔλεγχον ἀποχρῶσαι κατ’ ἀνδρὸς ἐνδόξου καὶ δυναμένου μέγα τοῦ Κατιλίνᾳ. διὸ τὴν ἡμέραν τῶν ἀρχαιρεσιῶν ὑπερθέμενος ὁ Κικέρων ἐκάλει τὸν Κατιλίναν εἰς τὴν σύγκλητον καὶ περὶ τῶν λεγομένων ἀνέκρινεν. ὁ δὲ πολλοὺς οἰόμενος εἶναι τοὺς πραγμάτων καινῶν ἐφιεμένους ἐν τῇ βουλῇ, καὶ ἅμα τοῖς συνωμόταις ἐνδεικνύμενος, ἀπεκρίνατο τῷ Κικέρωνι μανικὴν ἀπόκρισιν τί γὰρ, ἔφη, πράττω δεινόν, εἰ, δυεῖν σωμάτων ὄντων, τοῦ μέν ἰσχνοῦ καὶ κατεφθινηκότος, ἔχοντος δὲ κεφαλήν, τοῦ δ’ ἀκεφάλου μέν, ἰσχυροῦ δὲ καὶ μεγάλου, τούτῳ κεφαλὴν αὐτὸς ἐπιτίθημι; τούτων εἴς τε τὴν βουλὴν καὶ τὸν δῆμον ᾐνιγμένων ὑπ’ αὐτοῦ, μᾶλλον ὁ Κικέρων ἔδεισε, καὶ τεθωρακισμένον αὐτόν οἵ τε δυνατοὶ πάντες ἀπὸ τῆς οἰκίας καὶ τῶν νέων πολλοὶ κατήγαγον εἰς τὸ πεδίον, τοῦ δὲ θώρακος ἐπίτηδες ὑπέφαινέ τι παραλύσας ἐκ τῶν ὤμων τοῦ χιτῶνος, ἐνδεικνύμενος τοῖς ὁρῶσι τὸν κίνδυνον. οἱ δ’ ἠγανάκτουν καὶ συνεστρέφοντο περὶ αὐτόν καὶ τέλος ἐν ταῖς ψήφοις τὸν μέν Κατιλίναν αὖθις ἐξέβαλον, εἵλοντο δὲ Σιλανὸν ὕπατον καὶ Μουρήναν.", "st": "Cic. 14.1"}, {"sp": "N", "t": "οὐ πολλῷ δ’ ὕστερον τούτων ἤδη τῷ Κατιλίνᾳ τῶν ἐν Τυρρηνίᾳ συνερχομένων καὶ καταλοχιζομένων, καὶ τῆς ὡρισμένης πρὸς τὴν ἐπίθεσιν ἡμέρας ἐγγὺς οὔσης, ἧκον ἐπὶ τὴν Κικέρωνος οἰκίαν περὶ μέσας νύκτας ἄνδρες οἱ πρῶτοι καὶ δυνατώτατοι Ῥωμαίων, Μᾶρκος τε Κράσσος καὶ Μᾶρκος Μάρκελλος καὶ Σκηπίων Μέτελλος· κόψαντες δὲ τὰς θύρας καὶ καλέσαντες τὸν θυρωρόν ἐκέλευον ἐπεγεῖραι καὶ φράσαι Κικέρωνι τὴν παρουσίαν αὐτῶν. ἦν δὲ τοιόνδε· τῷ Κράσσῳ μετὰ δεῖπνον ἐπιστολὰς ἀποδίδωσιν ὁ θυρωρός, ὑπὸ δή τινος ἀνθρώπου κομισθείσας ἀγνώστου, ἄλλας ἄλλοις ἐπιγεγραμμένας, αὐτῷ δὲ Κράσσῳ μίαν ἀδέσποτον. ἣν μόνην ἀναγνοὺς ὁ Κράσσος, ὡς ἔφραζε τὰ γράμματα φόνον γενησόμενον πολὺν διὰ Κατιλίνᾳ, καὶ παρῄνει τῆς πόλεως ὑπεξελθεῖν, τὰς ἄλλας οὐκ ἔλυσεν, ἀλλ’ ἧκεν εὐθὺς πρὸς τὸν Κικέρωνα, πληγεὶς ὑπὸ τοῦ δεινοῦ, καί τι τῆς αἰτίας ἀπολυόμενος ἣν ἔσχε διὰ φιλίαν τοῦ Κατιλίνᾳ.", "st": "Cic. 15.1"}, {"sp": "N", "t": "βουλευσάμενος οὖν ὁ Κικέρων ἅμ’ ἡμέρᾳ, βουλὴν συνήγαγε, καὶ τὰς ἐπιστολὰς κομίσας ἀπέδωκεν οἷς ἦσαν ἐπεσταλμέναι, κελεύσας φανερῶς ἀναγνῶναι. πᾶσαι δ’ ἦσαν ὁμοίως ἐπιβουλὴν φράζουσαι. ἐπεὶ δὲ καὶ Κόιντος Ἄρριος, ἀνὴρ στρατηγικός, ἀπήγγελλε τοὺς ἐν Τυρρηνίᾳ καταλοχισμούς, καὶ Μάλλιος ἀπηγγέλλετο σὺν χειρὶ μεγάλῃ περὶ τὰς πόλεις ἐκείνας αἰωρούμενος ἀεί τι προσδοκᾶν καινὸν ἀπὸ τῆς Ῥώμης, γίνεται δόγμα τῆς βουλῆς παρακατατίθεσθαι τοῖς ὑπάτοις τὰ πράγματα, δεξαμένους δ’ ἐκείνους ὡς ἐπίστανται διοικεῖν καὶ σῴζειν τὴν πόλιν. τοῦτο δ’ οὐ πολλάκις, ἀλλ’ ὅταν τι μέγα δείσῃ, ποιεῖν εἴωθεν ἡ σύγκλητος.", "st": "Cic. 15.4"}, {"sp": "N", "t": "ἐπεὶ δὲ ταύτην λαβὼν τὴν ἐξουσίαν ὁ Κικέρωνι τὰ μὲν ἔξω πράγματα Κοΐντῳ Μετέλλῳ διεπίστευσε, τὴν δὲ πόλιν εἶχε διὰ χειρὸς καὶ καθ’ ἡμέραν προῄει δορυφορούμενος ὑπ’ ἀνδρῶν τοσούτων τὸ πλῆθος ὥστε τῆς ἀγορᾶς πολὺ μέρος κατέχειν ἐμβάλλοντος αὐτοῦ τοὺς παραπέμποντας, οὐκέτι καρτερῶν τὴν μέλλησιν ὁ Κατιλίνας αὐτὸς μὲν ἐκπηδᾶν ἔγνω πρὸς τὸν Μάλλιον ἐπὶ τὸ στράτευμα, Μάρκιον δὲ καὶ Κέθηγον ἐκέλευσε ξίφη λαβόντας ἐλθεῖν ἐπὶ τὰς θύρας ἕωθεν ὡς ἀσπασομένους τὸν Κικέρωνα καὶ διαχρήσασθαι προσπεσόντας. τοῦτο Φουλβία, γυνὴ τῶν ἐπιφανῶν, ἐξαγγέλλει τῷ Κικέρωνι νυκτὸς ἐλθοῦσα καὶ διακελευσαμένη φυλάττεσθαι τοὺς περὶ τὸν Κέθηγον. οἱ δ’ ἧκον ἅμ’ ἡμέρᾳ, καὶ κωλυθέντες εἰσελθεῖν ἠγανάκτουν καὶ κατεβόων ἐπὶ θύραις, ὥστε ὑποπτότεροι γενέσθαι. προελθὼν δ’ ὁ Κικέρων ἐκάλει τὴν σύγκλητον εἰς τὸ τοῦ Στησίου Διὸς ἱερόν, ὃν Στάτορα Ῥωμαῖοι καλοῦσιν, ἱδρυμένον ἐν ἀρχῇ τῆς ἱερᾶς ὁδοῦ, πρὸς τὸ Παλάτιον ἀνιόντων, ἐνταῦθα καὶ τοῦ Κατιλίνα μετὰ τῶν ἄλλων ἐλθόντος ὡς ἀπολογησομένου, συγκαθίσαι μὲν οὐδεὶς ὑπέμεινε τῶν συγκλητικῶν, ἀλλὰ πάντες ἀπὸ τοῦ βάθρου μετῆλθον. ἀρξάμενος δὲ λέγειν ἐθορυβεῖτο, καὶ τέλος ἀναστὰς ὁ Κικέρων προσέταξεν αὐτῷ τῆς πόλεως ἀπαλλάττεσθαι· δεῖν γὰρ αὐτοῦ μὲν λόγοις, ἐκείνου δ’ ὅπλοις πολιτευομένου μέσον εἶναι τὸ τεῖχος. ὁ μὲν οὖν Κατιλίνας εὐθὺς ἐξελθὼν μετὰ τριακοσίων ὁπλοφόρων καὶ περιστησάμενος αὑτῷ ῥαβδουχίας ὡς ἄρχοντι καὶ πελέκεις καὶ σημαίας ἐπαράμενος, πρὸς τὸν Μάλλιον ἐχώρει· καὶ δισμυρίων ὁμοῦ τι συνηθροισμένων ἐπῄει τὰς πόλεις ἀναπείθων καὶ ἀφιστὰς, ὥστε τοῦ πολέμου φανεροῦ γεγονότος τὸν Ἀντώνιον ἀποσταλῆναι διαμαχούμενον.", "st": "Cic. 16.1"}, {"sp": "N", "t": "τοὺς δ’ ὑπολειφθέντας ἐν τῇ πόλει τῶν διεφθαρμένων ὑπὸ τοῦ Κατιλίνα συνῆγε καὶ παρεθάρρυνε Κορνήλιος Λέντλος Σούρας ἐπίκλησιν, ἀνὴρ γένους μὲν ἐνδόξου, βεβιωκὼς δὲ φαύλως καὶ δι’ ἀσέλγειαν ἐξεληλαμένος τῆς βουλῆς πρότερον, τότε δὲ στρατηγῶν τὸ δεύτερον, ὡς ἔθος ἐστὶ τοῖς ἐξ ὑπαρχῆς ἀνακτωμένοις τὸ βουλευτικὸν ἀξίωμα. λέγεται δὲ καὶ τὴν ἐπίκλησιν αὐτῷ γενέσθαι τὸν Σούραν ἐξ αἰτίας τοιαύτης. ἐν τοῖς κατὰ Σύλλαν χρόνοις ταμιεύων συχνὰ τῶν δημοσίων χρημάτων ἀπώλεσε καὶ διέφθειρεν. ἀγανακτοῦντος δὲ τοῦ Σύλλα καὶ λόγον ἀπαιτοῦντος ἐν τῇ συγκλήτῳ, προελθὼν ὀλιγώρως πάνυ καὶ καταφρονητικῶς λόγον μὲν οὐκ ἔφη διδόναι, παρέχειν δὲ τὴν κνήμην, ὥσπερ εἰώθεισαν οἱ παῖδες ὅταν ἐν τῷ σφαιρίζειν ἁμάρτωσιν. ἐκ τούτου Σούρας παρωνομάσθη· σούραν γὰρ οἱ Ῥωμαῖοι τὴν κνήμην λέγουσι. πάλιν δὲ δίκην ἔχων καὶ διαφθείρας ἐνίους τῶν δικαστῶν, ἐπεὶ δυσὶ μόναις ἀπέφυγε ψήφοις, ἔφη παρανάλωμα γεγονέναι τὸ θατέρῳ κριτῇ δοθέν ἀρκεῖν γὰρ εἰ καὶ μιᾷ ψήφῳ μόνον ἀπελύθη.", "st": "Cic. 17.1"}, {"sp": "N", "t": "τοῦτον ὄντα τῇ φύσει τοιοῦτον κεκινημένον ὑπὸ τοῦ Κατιλίνα προσδιέφθειραν ἐλπίσι κεναῖς ψευδομάντεις καὶ γόητες ἔπη πεπλασμένα καὶ χρησμοὺς ᾄδοντες, ὡς ἐκ τῶν Σιβυλλείων, προδηλοῦντας εἱμαρμένους εἶναι τῇ Ῥώμῃ Κορνηλίους τρεῖς μονάρχους, ὧν δύο μὲν ἤδη πεπληρωκέναι τὸ χρεών, Κίνναν τε καὶ Σύλλαν, τρίτῳ δὲ λοιπῷ Κορνηλίῳ ἐκείνῳ φέροντα τὴν μοναρχίαν ἥκειν τὸν δαίμονα, καὶ δεῖν πάντως δέχεσθαι καὶ μὴ διαφθείρειν μέλλοντα τοὺς καιροὺς, ὥσπερ Κατιλίνας.", "st": "Cic. 17.5"}, {"sp": "N", "t": "οὐδὲν οὖν ἐπενόει μικρὸν ὁ Λέντλος ἢ ἄσημον, ἀλλ’ ἐδέδοκτο τήν βουλὴν ἅπασαν ἀναιρεῖν τῶν τ’ ἄλλων πολιτῶν ὅσους δύναιτο, τήν πόλιν δ’ αὐτὴν καταπιμπράναι, φείδεσθαι τε μηδενὸς ἢ τῶν Πομπηΐου τέκνων ταῦτα δ’ ἐξαρπασαμένους ἔχειν ὑφ’ αὑτοῖς καὶ φυλάττειν ὅμηρα τῶν πρὸς Πομπήϊον διαλύσεων· ἤδη γὰρ ἐφοίτα πολὺς λόγος καὶ βέβαιος ὑπὲρ αὐτοῦ κατιόντος ἀπὸ τῆς μεγάλης στρατείας. καὶ νὺξ μὲν ὥριστο πρὸς τήν ἐπίθεσιν μία τῶν Κρονιάδων, ξίφη δὲ καὶ στυππεῖα καὶ θεῖον εἰς τήν Κεθήγου φέροντες οἰκίαν ἀπέκρυψαν. ἄνδρας δὲ τάξαντες ἑκατὸν καὶ μέρη τοσαῦτα τῆς Ῥώμης ἕκαστον ἐφ’ ἑκάστῳ διεκλήρωσαν, ὡς δι’ ὀλίγου πολλῶν ἁψάντων φλέγοιτο πανταχόθεν ἡ πόλις. ἄλλοι δὲ τοὺς ὀχετοὺς ἔμελλον ἐμφράξαντες ἀποσφάττειν τοὺς ὑδρευομένους.", "st": "Cic. 18.1"}, {"sp": "N", "t": "πραττομένων δὲ τούτων ἔτυχον ἐπιδημοῦντες Ἀλλοβρίγων δύο πρέσβεις, ἔθνους μάλιστα δὴ τότε πονηρὰ πράττοντος καὶ βαρυνομένου τήν ἡγεμονίαν. τούτους οἱ περὶ Λέντλον ὠφελίμους ἡγούμενοι πρὸς τὸ κινῆσαι καὶ μεταβαλεῖν τήν Γαλατίαν ἐποιήσαντο συνωμότας. καὶ γράμματα μὲν αὐτοῖς πρὸς τήν ἐκεῖ βουλήν, γράμματα δὲ πρὸς Κατιλίναν ἔδοσαν, τῇ μὲν ὑπισχνούμενοι τήν ἐλευθερίαν, τὸν δὲ Κατιλίναν παρακαλοῦντες ἐλευθερώσαντα τοὺς δούλους ἐπὶ τήν Ῥώμην ἐλαύνειν. συναπέστελλον δὲ μετ’ αὐτῶν πρὸς τὸν Κατιλίναν Τίτον τινὰ Κροτωνιάτην, κομίζοντα τὰς ἐπιστολάς. οἷα δ’ ἀνθρώπων ἀσταθμήτων καὶ μετ’ οἴνου τὰ πολλὰ καὶ γυναικῶν ἀλλήλοις ἐντυγχανόντων βουλεύματα πόνῳ καὶ λογισμῷ νήφοντι καὶ συνέσει περιττῇ διώκων ὁ Κικέρων, καὶ πολλοὺς μὲν ἔχων ἔξωθεν ἐπισκοποῦντας τὰ πραττόμενα καὶ συνεξιχνεύοντας αὐτῷ, πολλοῖς δὲ τῶν μετέχειν δοκούντων τῆς συνωμοσίας διαλεγόμενος κρύφα καὶ πιστεύων, ἔγνω τήν πρὸς τοὺς ξένους κοινολογίαν· καὶ νυκτὸς ἐνεδρεύσας ἔλαβε τὸν Κροτωνιάτην καὶ τὰ γράμματα, συνεργούντων ἀδήλως τῶν Ἀλλοβρίγων.", "st": "Cic. 18.4"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ βουλὴν ἀθροίσας εἰς τὸ τῆς Ὁμονοίας ἱερόν ἐξανέγνω τὰ γράμματα καὶ τῶν μηνυτῶν διήκουσεν. ἔφη δὲ καὶ Σιλανὸς Ἰούνιος ἀκηκοέναι τινὰς Κεθήγου λέγοντος ὡς ὕπατοί τε τρεῖς καὶ στρατηγοί τέτταρες ἀναιρεῖσθαι μέλλουσι. τοιαῦτα δ’ ἕτερα καὶ Πείσων, ἀνὴρ ὑπατικός, εἰσήγγειλε. Γάιος δὲ Σουλπίκιος, εἷς τῶν στρατηγῶν, ἐπὶ τήν οἰκίαν πεμφθεὶς τοῦ Κεθήγου πολλὰ μὲν ἐν αὐτῇ βέλη καὶ ὅπλα, πλεῖστα δὲ ξίφη καὶ μαχαίρας εὗρε νεοθήκτους ἁπάσας. τέλος δὲ τῷ Κροτωνιάτῃ ψηφισαμένης ἄδειαν ἐπὶ μηνύσει τῆς βουλῆς ἐξελεγχθεὶς ὁ Λέντλος ἀπωμόσατο τήν ἀρχήν στρατηγῶν γὰρ ἐτύγχανε, καὶ τήν περιπόρφυρον ἐν τῇ βουλῇ καταθέμενος διήλλαξεν ἐσθῆτα τῇ συμφορᾷ πρέπουσαν. οὗτος μὲν οὖν καὶ οἱ σὺν αὐτῷ παρεδόθησαν εἰς ἄδεσμον φυλακὴν τοῖς στρατηγοῖς.", "st": "Cic. 19.1"}, {"sp": "N", "t": "ἤδη δ’ ἑσπέρας οὔσης καὶ τοῦ δήμου περιμένοντος ἀθρόου, προελθὼν ὁ Κικέρων, καὶ φράσας τὸ πρᾶγμα τοῖς πολίταις καὶ προπεμφθείς, παρῆλθεν εἰς οἰκίαν φίλου γειτνιῶντος, ἐπεὶ τήν ἐκείνου γυναῖκες κατεῖχον, ἱεροῖς ἀπορρήτοις ὀργιάζουσαι θεόν ἣν Ῥωμαῖοι μὲν Ἀγαθήν, Ἕλληνες δὲ Γυναικείαν ὀνομάζουσι. θύεται δ’ αὐτῇ κατ’ ἐνιαυτὸν ἐν τῇ οἰκίᾳ τοῦ ὑπάτου διὰ γυναικὸς ἢ μητρὸς αὐτοῦ, τῶν Ἑστιάδων παρθένων παρουσῶν. εἰσελθὼν οὖν ὁ Κικέρων, καθ’ αὑτόν, ὀλίγων παντάπασιν αὐτῷ παρόντων, ἐφρόντιζεν ὅπως χρήσαιτο τοῖς ἀνδράσι. τήν τε γὰρ ἄκραν καὶ προσήκουσαν ἀδικήμασι τηλικούτοις τιμωρίαν ἐξηυλαβεῖτο καὶ κατώκνει δι’ ἐπιείκειαν ἤθους ἅμα καὶ ὡς μὴ δοκοίη τῆς ἐξουσίας ἄγαν ἐμφορεῖσθαι καὶ πικρῶς ἐπεμβαίνειν ἀνδράσι γένει τε πρώτοις καὶ φίλους δυνατοὺς ἐν τῇ πόλει κεκτημένοις· μαλακώτερόν τε χρησάμενος ὠρρώδει τὸν ἀπ’ αὐτῶν κίνδυνον. οὐ γὰρ ἀγαπήσειν μετριώτερόν τι θανάτου παθόντας, ἀλλ’ εἰς ἅπαν ἀναρραγήσεσθαι τόλμης, τῇ παλαιᾷ κακίᾳ, νέαν ὀργὴν προσλαβόντας· αὐτός τε δόξειν ἄνανδρος καὶ μαλακός, οὐδ’ ἄλλως δοκῶν εὐτολμότατος εἶναι τοῖς πολλοῖς.", "st": "Cic. 19.1b"}, {"sp": "N", "t": "ταῦτα τοῦ Κικέρωνος διαποροῦντος γίνεταί τι ταῖς γυναιξὶ σημεῖον θυούσαις. ὁ γὰρ βωμός, ἤδη τοῦ πυρὸς κατακεκοιμῆσθαι δοκοῦντος, ἐκ τῆς τέφρας καὶ τῶν κεκαυμένων φλοιῶν φλόγα πολλὴν ἀνῆκε καὶ λαμπράν. ὑφ’ ἧς αἱ μὲν ἄλλαι διεπτοήθησαν, αἱ δ’ ἱεραὶ παρθένοι τὴν τοῦ Κικέρωνος γυναῖκα Τερεντίαν ἐκέλευσαν ᾗ τάχος χωρεῖν πρός τὸν ἄνδρα καὶ κελεύειν οἷς ἔγνωκεν ἐγχειρεῖν ὑπὲρ τῆς πατρίδος, ὡς μέγα πρός τε σωτηρίαν καὶ δόξαν αὐτῷ τῆς θεοῦ φῶς διδούσης. ἡ δὲ Τερεντία καὶ γὰρ οὐδ’ ἄλλως ἦν πρᾳεῖά τις οὐδ’ ἄτολμος τὴν φύσιν, ἀλλὰ φιλότιμος γυνὴ καὶ μᾶλλον, ὡς αὐτός φησιν ὁ Κικέρων, τῶν πολιτικῶν μεταλαμβάνουσα παρ’ ἐκείνου φροντίδων ἢ μεταδιδοῦσα τῶν οἰκιακῶν ἐκείνῳ ταῦτα τε πρός αὐτὸν ἔφρασε καὶ παρώξυνεν ἐπὶ τοὺς ἄνδρας· ὁμοίως δὲ καὶ Κόιντος ὁ ἀδελφὸς καὶ τῶν ἀπὸ φιλοσοφίας ἑταίρων Πόπλιος Νιγίδιος, ᾧ τὰ πλεῖστα καὶ μέγιστα παρὰ τὰς πολιτικὰς ἐχρῆτο πράξεις.", "st": "Cic. 20.1"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ γενομένων ἐν συγκλήτῳ λόγων περὶ τιμωρίας τῶν ἀνδρῶν, ὁ πρῶτος ἐρωτηθεὶς γνώμην Σιλανὸς εἶπε τὴν ἐσχάτην δίκην δοῦναι προσήκειν ἀχθέντας εἰς τὸ δεσμωτήριον. καὶ προσετίθεντο τούτῳ πάντες ἐφεξῆς μέχρι Γαΐου Καίσαρος τοῦ μετὰ ταῦτα δικτάτορος γενομένου. τότε δὲ νέος ὢν ἔτι καὶ τὰς πρώτας ἔχων τῆς αὐξήσεως ἀρχάς, ἤδη δὲ τῇ πολιτείᾳ καὶ ταῖς ἐλπίσιν εἰς ἐκείνην τὴν ὁδὸν ἐμβεβηκὼς ᾗ τὰ Ῥωμαίων εἰς μοναρχίαν μετέστησε πράγματα, τοὺς μὲν ἄλλους ἐλάνθανε, τῷ δὲ Κικέρωνι πολλὰς μὲν ὑποψίας, λαβὴν δ’ οὐδεμίαν εἰς ἔλεγχον παρέδωκεν, ἀλλὰ καὶ λεγόντων ἦν ἐνίων ἀκούειν ὡς ἐγγὺς ἐλθὼν ἁλῶναι διεκφύγοι τὸν ἄνδρα, τινὲς δέ φασι παριδεῖν ἑκόντα καὶ παραλιπεῖν τὴν κατ’ ἐκείνου μήνυσιν φόβῳ τῶν φίλων αὐτοῦ καὶ τῆς δυνάμεως· παντὶ γὰρ εἶναι πρόδηλον ὅτι μᾶλλον ἂν ἐκεῖνοι γένοιντο προσθήκη Καίσαρι σωτηρίας ἢ Καῖσαρ ἐκείνοις κολάσεως.", "st": "Cic. 20.4"}, {"sp": "N", "t": "ἐπεὶ δ’ οὖν ἡ γνώμη περιῆλθεν εἰς αὐτόν, ἀναστὰς ἀπεφήνατο μὴ θανατοῦν τοὺς ἄνδρας, ἀλλὰ τὰς οὐσίας εἶναι δημοσίας, αὐτοὺς δ’ ἀπαχθέντας εἰς πόλεις τῆς Ἰταλίας ἃς ἂν δοκῇ Κικέρωνι, τηρεῖσθαι δεδεμένους ἄχρι ἂν οὗ καταπολεμηθῇ Κατιλίνας. οὔσης δὲ τῆς γνώμης ἐπιεικοῦς καὶ τοῦ λέγοντος εἰπεῖν δυνατωτάτου, ῥοπὴν ὁ Κικέρων προσέθηκεν οὐ μικράν, αὐτός τε γὰρ ἀναστὰς ἐνεχείρησεν εἰς ἑκάτερον, τὰ μὲν τῇ προτέρᾳ, τὰ δὲ τῇ γνώμη Καίσαρος συνειπών, οἵ τε φίλοι πάντες οἰόμενοι τῷ Κικέρωνι συμφέρειν τὴν Καίσαρος γνώμην ἧττον γὰρ ἐν αἰτίαις ἔσεσθαι μὴ θανατώσαντα τοὺς ἄνδρας ᾑροῦντο τὴν δευτέραν μᾶλλον γνώμην, ὥστε καὶ τὸν Σιλανὸν αὖθις μεταβαλλόμενον παραιτεῖσθαι καὶ λέγειν ὡς οὐδ’ αὐτὸς εἴποι θανατικὴν γνώμην· ἐσχάτην γὰρ ἀνδρὶ βουλευτῇ Ῥωμαίων εἶναι δίκην τὸ δεσμωτήριον. εἰρημένης δὲ τῆς γνώμης πρῶτος ἀντέκρουσεν αὐτῇ Κάτλος Λουτάτιος· εἶτα δεξάμενος Κάτων, καὶ τῷ λόγῳ σφοδρῶς συνεπερείσας ἐπὶ τὸν Καίσαρα τὴν ὑπόνοιαν, ἐνέπλησε θυμοῦ καὶ φρονήματος τὴν σύγκλητον, ὥστε θάνατον καταψηφίσασθαι τῶν ἀνδρῶν. περὶ δὲ δημεύσεως χρημάτων ἐνίστατο Καῖσαρ, οὐκ ἀξιῶν τὰ φιλάνθρωπα τῆς ἑαυτοῦ γνώμης ἐκβαλόντας ἑνὶ χρήσασθαι τῷ σκυθρωποτάτῳ, βιαζομένων δὲ πολλῶν ἐπεκαλεῖτο τοὺς δημάρχους, οἱ δ’ οὐχ ὑπήκουον, ἀλλὰ Κικέρων αὐτὸς ἐνδοὺς ἀνῆκε τὴν περὶ δημεύσεως γνώμην.", "st": "Cic. 21.1"}, {"sp": "N", "t": "ἐχώρει δὲ μετὰ τῆς βουλῆς ἐπὶ τοὺς ἄνδρας, οὐκ ἐν ταὐτῷ δὲ πάντες ἦσαν, ἄλλος δ’ ἄλλον ἐφύλαττε τῶν στρατηγῶν, καὶ πρῶτον ἐκ Παλατίου παραλαβὼν τὸν Λέντλον ἦγε διὰ τῆς ἱερᾶς ὁδοῦ καὶ τῆς ἀγορᾶς μέσης, τῶν μὲν ἡγεμονικωτάτων ἀνδρῶν κύκλῳ περιεσπειραμένων καὶ δορυφορούντων, τοῦ δὲ δήμου φρίττοντος τὰ δρώμενα καὶ παριόντος σιωπῇ, μάλιστα δὲ τῶν νέων, ὥσπερ ἱεροῖς τισι πατρίοις ἀριστοκρατικῆς τινος ἐξουσίας τελεῖσθαι μετὰ φόβου καὶ θάμβους δοκούντων. διελθὼν δὲ τὴν ἀγορὰν καὶ γενόμενος πρὸς τῷ δεσμωτηρίῳ παρέδωκε τὸν Λέντλον τῷ δημίῳ καὶ προσέταξεν ἀνελεῖν εἶθ’ ἑξῆς τὸν Κέθηγον, καὶ οὕτω τῶν ἄλλων ἕκαστον καταγαγὼν ἀπέκτεινεν. ὁρῶν δὲ πολλοὺς ἔτι τῶν ἀπὸ τῆς συνωμοσίας ἐν ἀγορᾷ συνεστῶτας ἀθρόους καὶ τὴν μὲν πρᾶξιν ἀγνοοῦντας, τὴν δὲ νύκτα προσμένοντας, ὡς ἔτι ζώντων τῶν ἀνδρῶν καὶ δυναμένων ἐξαρπασθῆναι, φθεγξάμενος μέγα πρὸς αὐτοὺς, ἔζησαν, εἶπεν. οὕτω δὲ Ῥωμαίων οἱ δυσφημεῖν μὴ βουλόμενοι τὸ τεθνάναι σημαίνουσιν.", "st": "Cic. 22.1"}, {"sp": "N", "t": "ἤδη δ’ ἦν ἑσπέρα, καὶ δι’ ἀγορᾶς ἀνέβαινεν εἰς τὴν οἰκίαν, οὐκέτι σιωπῇ τῶν πολιτῶν οὐδὲ τάξει προπεμπόντων αὐτόν, ἀλλὰ φωναῖς καὶ κρότοις δεχομένων καθ’ οὓς γένοιτο, σωτῆρα καὶ κτίστην ἀνακαλούντων τῆς πατρίδος. τὰ δὲ φῶτα πολλὰ κατέλαμπε τοὺς στενωπούς, λαμπάδια καὶ δᾷδας ἱστώντων ἐπὶ ταῖς θύραις. αἱ δὲ γυναῖκες ἐκ τῶν τεγῶν προὔφαινον ἐπὶ τιμῇ καὶ θέᾳ τοῦ ἀνδρός, ὑπὸ πομπῇ τῶν ἀρίστων μάλα σεμνῶς ἀνιόντος· ὧν οἱ πλεῖστοι πολέμους τε κατειργασμένοι μεγάλους καὶ διὰ θριάμβων εἰσεληλακότες καὶ προσκεκτημένοι γῆν καὶ θάλατταν οὐκ ὀλίγην ἐβάδιζον ἀνομολογούμενοι πρὸς ἀλλήλους πολλοῖς μὲν τῶν τότε ἡγεμόνων καὶ στρατηγῶν πλούτου καὶ λαφύρων καὶ δυνάμεως χάριν ὀφείλειν τὸν Ῥωμαίων δῆμον, ἀσφαλείας δὲ καὶ σωτηρίας ἑνὶ μόνῳ Κικέρωνι, τηλικοῦτον ἀφελόντι καὶ τοσοῦτον αὐτοῦ κίνδυνον. οὐ γὰρ τὸ κωλῦσαι τὰ πραττόμενα καὶ κολάσαι τοὺς πράττοντας ἐδόκει θαυμαστόν, ἀλλ’ ὅτι μέγιστον τῶν πώποτε νεωτερισμῶν οὗτος ἐλαχίστοις κακοῖς ἄνευ στάσεως καὶ ταραχῆς κατέσβεσε. καὶ γὰρ τὸν Κατιλίναν οἱ πλεῖστοι τῶν συνερρυηκότων πρὸς αὐτὸν ἅμα τῷ πυθέσθαι τὰ περὶ Λέντλον καὶ Κέθηγον ἐγκαταλιπόντες ᾤχοντο· καὶ μετὰ τῶν συμμεμενηκότων αὐτῷ διαγωνισάμενος πρὸς Ἀντώνιον αὐτός τε διεφθάρη καὶ τὸ στρατόπεδον.", "st": "Cic. 22.5"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἦσαν οἱ τὸν Κικέρωνα παρεσκευασμένοι καὶ λέγειν ἐπὶ τούτοις καὶ ποιεῖν κακῶς, ἔχοντες ἡγεμόνας τῶν εἰς τὸ μέλλον ἀρχόντων Καίσαρα μὲν στρατηγοῦντα, Μέτελλον δὲ καὶ Βηστίαν δημαρχοῦντας. οἳ τὴν ἀρχὴν παραλαβόντες, ἔτι τοῦ Κικέρωνος ἡμέρας ὀλίγας ἄρχοντος, οὐκ εἴων δημηγορεῖν αὐτόν, ἀλλ’ ὑπὲρ τῶν ἐμβόλων βάθρα θέντες οὐ παρίεσαν οὐδ’ ἐπέτρεπον λέγειν, ἀλλ’ ἐκέλευον, εἰ βούλοιτο, μόνον περὶ τῆς ἀρχῆς ἀπομόσαντα καταβαίνειν. κἀκεῖνος ἐπὶ τούτοις ὡς ὀμόσων προῆλθε· καὶ γενομένης αὐτῷ σιωπῆς ὤμνυεν, οὐ τὸν πάτριον, ἀλλ’ ἴδιόν τινα καὶ καινὸν ὅρκον, ἦ μὴν σεσωκέναι τὴν πατρίδα καὶ διατετηρηκέναι τὴν ἡγεμονίαν. ἐπώμνυε δὲ τὸν ὅρκον αὐτῷ σύμπας ὁ δῆμος, ἐφ’ οἷς ἔτι μᾶλλον ὅ τε Καῖσαρ οἵ τε δήμαρχοι χαλεπαίνοντες ἄλλας τε τῷ Κικέρωνι ταραχὰς ἐμηχανῶντο, καὶ νόμος ὑπ’ αὐτῶν εἰσήγετο καλεῖν Πομπήϊον μετὰ τῆς στρατιᾶς, ὡς δὴ καταλύσοντα τὴν Κικέρωνος δυναστείαν. ἀλλ’ ἦν ὄφελος μέγα τῷ Κικέρωνι καὶ πάσῃ τῇ πόλει δημαρχῶν τότε Κάτων καὶ τοῖς ἐκείνων πολιτεύμασιν ἀπ’ ἴσης μὲν ἐξουσίας, μείζονος δὲ δόξης ἀντιτασσόμενος, τά τε γὰρ ἄλλα ῥᾳδίως ἔλυσε, καὶ τὴν Κικέρωνος ὑπατείαν οὕτως ἦρε τῷ λόγῳ μεγάλην δημηγορήσας ὥστε τιμὰς αὐτῷ τῶν πώποτε μεγίστας ψηφίσασθαι καὶ προσαγορεῦσαι πατέρα πατρίδος, πρώτῳ γὰρ ἐκείνῳ δοκεῖ τοῦτο καθυπάρξαι, Κάτωνος αὐτὸν οὕτως ἐν τῷ δήμῳ προσαγορεύσαντος.", "st": "Cic. 23.1"}, {"sp": "N", "t": "καὶ μέγιστον μὲν ἴσχυσεν ἐν τῇ πόλει τότε, πολλοῖς δ’ ἐπίφθονον ἑαυτὸν ἐποίησεν ἀπ’ οὐδενὸς ἔργου πονηροῦ, τῷ δ’ ἐπαινεῖν ἀεὶ καὶ μεγαλύνειν αὐτὸς ἑαυτὸν ὑπὸ πολλῶν δυσχεραινόμενος. οὔτε γὰρ βουλὴν οὔτε δῆμον οὔτε δικαστήριον ἦν συνελθεῖν ἐν ᾧ μὴ Κατιλίναν ἔδει θρυλούμενον ἀκοῦσαι καὶ Λέντλον. ἀλλὰ καὶ τὰ βιβλία τελευτῶν κατέπλησε καὶ τὰ συγγράμματα τῶν ἐγκωμίων καὶ τὸν λόγον ἥδιστον ὄντα καὶ χάριν ἔχοντα πλείστην ἐπαχθῆ καὶ φορτικὸν ἐποίησε τοῖς ἀκροωμένοις, ὥσπερ τινὸς ἀεὶ κηρὸς αὐτῷ τῆς ἀηδίας ταύτης προσούσης. ὅμως δέ, καίπερ οὕτως ἀκράτῳ φιλοτιμίᾳ συνών, ἀπήλλακτο τοῦ φθονεῖν ἑτέροις, ἀφθονώτατος ὢν ἐν τῷ τοὺς πρὸ αὐτοῦ καὶ τοὺς καθ’ αὑτὸν ἄνδρας ἐγκωμιάζειν, ὡς ἐκ τῶν συγγραμμάτων λαβεῖν ἔστι. πολλὰ δ’ αὐτοῦ καὶ ἀπομνημονεύουσιν οἷον περὶ Ἀριστοτέλους, ὅτι χρυσίου ποταμὸς εἴη ῥέοντος, καὶ περὶ τῶν Πλάτωνος διαλόγων, ὡς τοῦ Διός, εἰ λόγῳ χρῆσθαι πέφυκεν, οὕτω διαλεγομένου. τὸν δὲ Θεόφραστον εἰώθει τρυφὴν ἰδίαν ἀποκαλεῖν. περὶ δὲ τῶν Δημοσθένους λόγων ἐρωτηθείς τίνα δοκοίη κάλλιστον εἶναι, τὸν μέγιστον εἶπε. καίτοι τινὲς τῶν προσποιουμένων δημοσθενίζειν ἐπιφύονται φωνῇ τοῦ Κικέρωνος, ἣν πρός τινα τῶν ἑταίρων ἔθηκεν ἐν ἐπιστολῇ γράψας, ἐνιαχοῦ τῶν λόγων ἀπονυστάζειν τὸν Δημοσθένη· τῶν δὲ μεγάλων καὶ θαυμαστῶν ἐπαίνων οἷς πολλαχοῦ χρῆται περὶ τοῦ ἀνδρός, καὶ ὅτι περὶ οὓς μάλιστα τῶν ἰδίων ἐσπούδασε λόγων, τοὺς κατ’ Ἀντωνίου, Φιλιππικοὺς ἐπέγραψεν, ἀμνημονοῦσι.", "st": "Cic. 24.1"}, {"sp": "N", "t": "τῶν δὲ κατ’ αὑτὸν ἐνδόξων ἀπὸ λόγου καὶ σοφίας οὐκ ἔστιν οὐδεὶς ὃν οὐκ ἐποίησεν ἐνδοξότερον ἢ λέγων ἢ γράφων εὐμενῶς περὶ ἑκάστου. Κρατίππῳ δὲ τῷ Περιπατητικῷ διεπράξατο μὲν Ῥωμαίῳ γενέσθαι παρὰ Καίσαρος ἄρχοντος ἤδη, διεπράξατο δὲ καὶ τὴν ἐξ Ἀρείου πάγου βουλὴν ψηφίσασθαι δεηθῆναι μένειν αὑτὸν ἐν Ἀθήναις καὶ διαλέγεσθαι τοῖς νέοις ὡς κοσμοῦντα τὴν πόλιν. ἐπιστολαὶ δὲ παρὰ τοῦ Κικέρωνος εἰσὶ πρός Ἡρώδην, ἕτεραι δὲ πρός τὸν υἱόν, ἐγκελευομένου συμφιλοσοφεῖν Κρατίππῳ. Γοργίαν δὲ τὸν ῥήτορα αἰτιώμενος εἰς ἡδονὰς καὶ πότους προάγειν τὸ μειράκιον ἀπελαύνει τῆς συνουσίας αὐτοῦ. καὶ σχεδὸν αὕτη τε τῶν Ἑλληνικῶν μία καὶ δευτέρα πρός Πέλοπα τὸν Βυζάντιον ἐν ὀργῇ τινι γέγραπται, τὸν μὲν Γοργίαν αὐτοῦ προσηκόντως ἐπικόπτοντος, εἴπερ ἦν φαῦλος καὶ ἀκόλαστος, ᾗπερ ἐδόκει, πρός δὲ τὸν Πέλοπα μικρολογουμένου καὶ μεμψιμοιροῦντος ὥσπερ ἀμελήσαντα τιμάς τινας αὐτῷ καὶ ψηφίσματα παρὰ Βυζαντίων γενέσθαι.", "st": "Cic. 24.7"}, {"sp": "N", "t": "ταῦτά τε δὴ φιλότιμα, καὶ τὸ πολλάκις ἐπαιρόμενον τοῦ λόγου τῇ δεινότητι τὸ πρέπον προΐεσθαι. Μουνατίῳ μὲν γάρ ποτε συνηγορήσας, ὡς ἀποφυγὼν τὴν δίκην ἐκεῖνος ἐδίωκεν ἑταῖρον αὐτοῦ Σαβῖνον, οὕτω λέγεται προπεσεῖν ὑπ’ ὀργῆς ὁ Κικέρων ὥστ’ εἰπεῖν· σὺ γὰρ ἐκείνην, ὦ Μουνάτιε, τὴν δίκην ἀπέφυγες διὰ σαυτόν, οὐκ ἐμοῦ πολὺ σκότος ἐν φωτὶ τῷ δικαστηρίῳ περιχέαντος; Μᾶρκον δὲ Κράσσον ἐγκωμιάζων ἀπὸ τοῦ βήματος εὐημέρησε, καὶ μεθ’ ἡμέρας αὖθις ὀλίγας λοιδορῶν αὐτόν, ὡς ἐκεῖνος εἶπεν οὐ γὰρ ἐνταῦθα πρώην αὐτὸς ἡμᾶς ἐπῄνεις; ναί, φησι, μελέτης ἕνεκεν γυμνάζων τὸν λόγον εἰς φαύλην ὑπόθεσιν. εἰπόντος δέ ποτε τοῦ Κράσσου μηδένα Κράσσον ἐν Ῥώμῃ βεβιωκέναι μακρότερον ἑξηκονταετίας, εἶθ’ ὕστερον ἀρνουμένου καὶ λέγοντος, τί δ’ ἂν ἐγὼ παθὼν τοῦτ’ εἶπον; ἤιδεις, ἔφη, Ῥωμαίους ἡδέως ἀκουσομένους καὶ διὰ τοῦτ’ ἐδημαγώγεις. ἀρέσκεσθαι δὲ τοῦ Κράσσου τοῖς Στωικοῖς φήσαντος, ὅτι πλούσιον εἶναι τὸν ἀγαθὸν ἀποφαίνουσιν, ὅρα μὴ μᾶλλον εἶπεν, ὅτι πάντα τοῦ σοφοῦ λέγουσιν εἶναι. διεβάλλετο δ’ εἰς φιλαργυρίαν ὁ Κράσσος. ἐπεὶ δὲ τοῦ Κράσσου τῶν παίδων ὁ ἕτερος Ἀξίῳ τινὶ δοκῶν ὅμοιος εἶναι, καὶ διὰ τοῦτο τῇ μητρὶ προστριβόμενος αἰσχρὰν ἐπὶ τῷ Ἀξίῳ διαβολήν εὐδοκίμησε λόγον ἐν βουλῇ διελθών, ἐρωτηθεὶς ὁ Κικέρων τί φαίνεται αὐτῷ, ἄξιος, εἶπε, Κράσσου.", "st": "Cic. 25.1"}, {"sp": "N", "t": "μέλλων δὲ Κράσσος εἰς Συρίαν ἀπαίρειν ἐβούλετο τὸν Κικέρωνα μᾶλλον αὐτῷ φίλον ἢ ἐχθρὸν εἶναι· καί φιλοφρονούμενος ἔφη βούλεσθαι δειπνῆσαι παρ’ αὐτῷ· κἀκεῖνος ὑπεδέξατο προθύμως. ὀλίγαις δ’ ὕστερον ἡμέραις περὶ Βατινίου φίλων τινῶν ἐντυγχανόντων ὡς μνωμένου διαλύσεις καί φιλίαν ἦν γὰρ ἐχθρός, οὐ δήπου καί Βατίνιος, εἶπε, δειπνῆσαι παρ’ ἐμοὶ βούλεται; πρὸς μὲν οὖν Κράσσον τοιοῦτος. αὐτὸν δὲ τὸν Βατίνιον ἔχοντα χοιράδας ἐν τῷ τραχήλῳ καί λέγοντα δίκην οἰδοῦντα ῥήτορα προσεῖπεν. ἀκούσας δ’ ὅτι τέθνηκεν, εἶτα μετὰ μικρὸν πυθόμενος σαφῶς ὅτι ζῇ, κακὸς τοίνυν ἀπόλοιτο κακῶς ὁ ψευσάμενος. ἐπεὶ δὲ Καίσαρι ψηφισαμένῳ τὴν ἐν Καμπανίᾳ χώραν κατανεμηθῆναι τοῖς στρατιώταις πολλοὶ μὲν ἐδυσχέραινον ἐν τῇ βουλῇ, Λεύκιος δὲ Γέλλιος ὁμοῦ τι πρεσβύτατος ὢν εἶπεν ὡς οὐ γενήσεται τοῦτο ζῶντος αὐτοῦ, περιμείνωμεν εἶπεν ὁ Κικέρων, μακρὰν γὰρ οὐκ αἰτεῖται Γέλλιος ὑπέρθεσιν. ἦν δέ τις Ὀκταούιος αἰτίαν ἔχων ἐκ Λιβύης γεγονέναι· πρὸς τοῦτον ἔν τινι δίκῃ λέγοντα τοῦ Κικέρωνος μὴ ἐξακούειν, καὶ μὴν οὐκ ἔχεις, εἶπε, τὸ οὖς ἀτρύπητον. Μετέλλου δὲ Νέπωτος εἰπόντος ὅτι πλείονας καταμαρτυρῶν ἀνῄρηκεν ἢ συνηγορῶν σέσωκεν, ὁμολογῶ γάρ, ἔφη, πίστεως ἐν ἐμοὶ πλέον ἢ δεινότητος εἶναι. νεανίσκου δέ τινος αἰτίαν ἔχοντος ἐν πλακοῦντι φάρμακον τῷ πατρὶ δεδωκέναι θρασυνομένου καί λέγοντος ὅτι λοιδορήσει τὸν Κικέρωνα, τοῦτο, ἔφη, παρὰ σοῦ βούλομαι μᾶλλον ἢ πλακοῦντα. Ποπλίου δὲ Σηστίου συνήγορον μὲν αὐτὸν ἔν τινι δίκῃ παραλαβόντος μεθ’ ἑτέρων, αὐτοῦ δὲ πάντα βουλομένου λέγειν καί μηδενὶ παριέντος εἰπεῖν, ὡς δῆλος ἦν ἀφιέμενος ὑπὸ τῶν δικαστῶν ἤδη τῆς ψήφου φερομένης, χρῶ σήμερον, ἔφη, τῷ καιρῷ, Σήστιε μέλλεις γὰρ αὔριον ἰδιώτης εἶναι. Πόπλιον δὲ Κώνσταν νομικὸν εἶναι βουλόμενον, ὄντα δ’ ἀμαθῆ καί ἀφυῆ, πρός τινα δίκην ἐκάλεσε μάρτυρα· τοῦ δὲ μηδὲν εἰδέναι φάσκοντος, ἴσως, ἔφη, δοκεῖς περὶ τῶν νομικῶν ἐρωτᾶσθαι. Μετέλλου δὲ Νέπωτος ἐν διαφορᾷ τινι πολλάκις λέγοντος τίς σοῦ πατήρ ἐστιν, ὁ Κικέρων σοὶ ταύτην ἔφη τὴν ἀπόκρισιν ἡ μήτηρ χαλεπωτέραν ἐποίησεν. ἐδόκει δ’ ἀκόλαστος ἡ μήτηρ εἶναι τοῦ Νέπωτος, αὐτὸς δέ τις εὐμετάβολος.", "st": "Cic. 26.1"}, {"sp": "N", "t": "καί ποτε τὴν δημαρχίαν ἀπολιπὼν ἄφνω πρὸς Πομπήϊον ἐξέπλευσεν εἰς Συρίαν, εἶτ’ ἐκεῖθεν ἐπανῆλθεν ἀλογώτερον. θάψας δὲ Φίλαγρον τὸν καθηγητὴν ἐπιμελέστερον ἐπέστησεν αὐτοῦ τῷ τάφῳ κόρακα λίθινον καί ὁ Κικέρων· τοῦτ’, ἔφη σοφώτερον ἐποίησας· πέτεσθαι γάρ σε μᾶλλον ἢ λέγειν ἐδίδαξεν. ἐπεὶ δὲ Μᾶρκος Ἄππιος ἔν τινι δίκῃ προοιμιαζόμενος εἶπε φίλον αὐτοῦ δεδεῆσθαι παρασχεῖν ἐπιμέλειαν καί λογιότητα καί πίστιν, εἶθ’ οὕτως, ἔφη, σιδηροῦς γέγονας ἄνθρωπος ὥστε μηδὲν ἐκ τοσούτων ὧν ᾐτήσαθ’ ὁ φίλος παρασχεῖν;", "st": "Cic. 26.1b"}, {"sp": "N", "t": "τὸ μὲν οὖν πρὸς ἐχθροὺς ἢ ἀντιδίκους σκώμμασι χρῆσθαι πικροτέροις δοκεῖ ῥητορικὸν εἶναι· τὸ δ’ οἷς ἔτυχε προσκρούειν ἕνεκα τοῦ γελοίου πολὺ συνῆγε μῖσος αὐτῷ. γράψω δὲ καὶ τούτων ὀλίγα. Μᾶρκον Ἀκυΐνιον ἔχοντα δύο γαμβροὺς φυγάδας Ἄδραστον ἐκάλει. Λευκίου δὲ Κόττα τιμητικὴν ἔχοντος ἀρχήν, φιλοινοτάτου δ’ ὄντος, ὑπατείαν μετιὼν ὁ Κικέρων ἐδίψησε, καὶ τῶν φίλων κύκλῳ περιστάντων ὡς ἔπινεν, ὀρθῶς φοβεῖσθε, εἶπε, μή μοι γένοιτο χαλεπὸς ὁ τιμητὴς ὅτι ὕδωρ πίνω. Βωκωνίῳ δ’ ἀπαντήσας ἄγοντι μεθ’ ἑαυτοῦ τρεῖς ἀμορφοτάτας θυγατέρας ἀνεφθέγξατο·", "st": "Cic. 27.1"}, {"sp": "N", "t": "Φοίβου ποτ’ οὐκ ἐῶντος ἔσπειρεν τέκνα.", "st": "Cic. 27.1b"}, {"sp": "N", "t": "Μάρκου δὲ Γελλίου δοκοῦντος οὐκ ἐξ ἐλευθέρων γεγονέναι, λαμπρᾷ δὲ τῇ φωνῇ καὶ μεγάλῃ γράμματα πρὸς τὴν σύγκλητον ἐξαναγνόντος, μὴ θαυμάζετε, εἶπε, καὶ αὐτὸς εἷς ἐστι τῶν ἀναπεφωνηκότων. ἐπεὶ δὲ Φαῦστος ὁ Σύλλα τοῦ μοναρχήσαντος ἐν Ῥώμῃ καὶ πολλοὺς ἐπὶ θανάτῳ προγράψαντος ἐν δανείοις γενόμενος καὶ πολλὰ τῆς οὐσίας διασπαθήσας ἀπάρτιον προέγραψε, ταύτην ἔφη μᾶλλον αὐτῷ τὴν προγραφὴν ἀρέσκειν ἢ τὴν πατρῴαν.", "st": "Cic. 27.5"}, {"sp": "N", "t": "ἐκ τούτων ἐγίνετο πολλοῖς ἐπαχθής· καὶ οἱ μετὰ Κλωδίου συνέστησαν ἐπ’ αὐτόν ἀρχὴν τοιαύτην λαβόντες. ἦν Κλώδιος ἀνὴρ εὐγενής, τῇ μὲν ἡλικίᾳ νέος, τῷ δὲ φρονήματι θρασὺς καὶ αὐθάδης, οὗτος ἐρῶν Πομπηίας τῆς Καίσαρος γυναικός εἰς τὴν οἰκίαν αὐτοῦ παρεισῆλθε κρύφα, λαβὼν ἐσθῆτα καὶ σκευὴν ψαλτρίας· ἔθυον γὰρ αἱ γυναῖκες τὴν ἀπόρρητον ἐκείνην καὶ ἀθέατον ἀνδράσι θυσίαν ἐν τῇ τοῦ Καίσαρος οἰκίᾳ, καὶ παρῆν ἀνὴρ οὐδείς· ἀλλὰ μειράκιον ὢν ἔτι καὶ μήπω γενειῶν ὁ Κλώδιος ἤλπιζε λήσεσθαι διαδὺς πρὸς τὴν Πομπηίαν μετὰ τῶν γυναικῶν, ὡς δ’ εἰσῆλθε νυκτὸς εἰς οἰκίαν μεγάλην, ἠπορεῖτο τῶν διόδων· καὶ πλανώμενον αὐτόν ἰδοῦσα Αὐρηλίας θεραπαινὶς τῆς Καίσαρος μητρός, ᾔτησεν ὄνομα, φθέγξασθαι δ’ ἀναγκασθέντος ἐκείνου καὶ φήσαντος ἀκόλουθον Πομπηίας ζητεῖν Ἄβραν τοὔνομα, συνεῖσα τὴν φωνὴν οὐ γυναικείαν οὖσαν ἀνέκραγε καὶ συνεκάλει τὰς γυναῖκας. αἱ δ’ ἀποκλείσασαι τὰς θύρας καὶ πάντα διερευνώμεναι λαμβάνουσι τὸν Κλώδιον εἰς οἴκημα παιδίσκης, ᾗ συνεισῆλθε, καταπεφευγότα. τοῦ δὲ πράγματος περιβοήτου γενομένου Καῖσάρ τε τὴν Πομπηΐαν ἀφῆκε καὶ δίκην ἀσεβείας ἀπεγράψατο τῷ Κλωδίῳ.", "st": "Cic. 28.1"}, {"sp": "N", "t": "Κικέρων δ’ ἦν μέν αὐτοῦ φίλος καί τῶν περὶ Κατιλίναν πραττομένων ἐχρῆτο προθυμοτάτῳ συνεργῷ καί φύλακι τοῦ σώματος, ἰσχυριζομένου δὲ πρὸς τὸ ἔγκλημα τῷ μηδὲ γεγονέναι κατ’ ἐκεῖνον ἐν Ῥώμῃ τὸν χρόνον, ἀλλ’ ἐν τοῖς πορρωτάτω χωρίοις διατρίβειν, κατεμαρτύρησεν ὡς ἀφιγμένου πρὸς αὐτὸν οἴκαδε καί διειλεγμένου περί τινων· ὅπερ ἦν ἀληθές, οὐ μὴν ἐδόκει μαρτυρεῖν ὁ Κικέρων διὰ τὴν ἀλήθειαν, ἀλλὰ πρὸς τὴν αὐτοῦ γυναῖκα Τερεντίαν ἀπολογούμενος. ἦν γὰρ αὐτῇ πρὸς τὸν Κλώδιον ἀπέχθεια διὰ τὴν ἀδελφὴν τὴν ἐκείνου Κλωδίαν, ὡς τῷ Κικέρωνι βουλομένην γαμηθῆναι καί τοῦτο διὰ Τύλλου τινὸς πράττουσαν, ὃς ἑταῖρος μέν ἦν καί συνήθης ἐν τοῖς μάλιστα Κικέρωνος, ἀεὶ δὲ πρὸς τὴν Κλωδίαν φοιτῶν καί θεραπεύων ἐγγὺς οἰκοῦσαν ὑποψίαν τῇ Τερεντίᾳ παρέσχε. χαλεπὴ δὲ τὸν τρόπον οὖσα καί τοῦ Κικέρωνος ἄρχουσα παρώξυνε τῷ Κλωδίῳ συνεπιθέσθαι καί καταμαρτυρῆσαι. κατεμαρτύρουν δὲ τοῦ Κλωδίου πολλοὶ τῶν καλῶν κἀγαθῶν ἀνδρῶν ἐπιορκίας, ῥᾳδιουργίας, ὄχλων δεκασμούς, φθορὰς γυναικῶν. Λεύκολλος δὲ καί θεραπαινίδας παρεῖχεν ὡς συγγένοιτο τῇ νεωτάτῃ τῶν ἀδελφῶν ὁ Κλώδιος, ὅτε Λευκούλλῳ συνῴκει. πολλὴ δ’ ἦν δόξα καί ταῖς ἄλλαις δυσὶν ἀδελφαῖς πλησιάζειν τὸν Κλώδιον, ὧν Τερτίαν μέν Μάρκιος ὁ Ῥήξ, Κλωδίαν δὲ Μέτελλος ὁ Κέλερ εἶχεν, ἣν Κουαδρανταρίαν ἐκάλουν, ὅτι τῶν ἐραστῶν τις αὐτῇ χαλκοῦς ἐμβαλὼν εἰς βαλάντιον ὡς ἀργύριον εἰσέπεμψε· τὸ δὲ λεπτότατον τοῦ χαλκοῦ νομίσματος κουαδράντην ἐκάλουν. ἐπὶ ταύτῃ μάλιστα τῶν ἀδελφῶν κακῶς ἤκουσεν ὁ Κλώδιος. οὐ μὴν ἀλλὰ τότε τοῦ δήμου πρὸς τοὺς καταμαρτυροῦντας αὐτοῦ καί συνεστῶτας ἀντιταττομένου φοβηθέντες οἱ δικασταὶ φυλακὴν περιεστήσαντο, καί τὰς δέλτους οἱ πλεῖστοι συγκεχυμένοις τοῖς γράμμασιν ἤνεγκαν. ὅμως δὲ πλείονες ἔδοξαν οἱ ἀπολύοντες γενέσθαι· καί τις ἐλέχθη καί δεκασμὸς διελθεῖν. ὅθεν ὁ μέν Κάτλος ἀπαντήσας τοῖς κριταῖς, ὑμεῖς, εἶπεν, ὡς ἀληθῶς ὑπὲρ ἀσφαλείας ᾐτήσασθε τὴν φυλακήν, φοβούμενοι μή τις ὑμῶν ἀφέληται τὸ ἀργύριον. Κικέρων δὲ τοῦ Κλωδίου πρὸς αὐτὸν λέγοντος ὅτι μαρτυρῶν οὐκ ἔσχε πίστιν παρὰ τοῖς δικασταῖς, ἀλλ’ ἐμοὶ μέν, εἶπεν, οἱ πέντε καί εἴκοσι τῶν δικαστῶν ἐπίστευσαν τοσοῦτοι γάρ σου κατεψηφίσαντο· σοὶ δὲ τριάκοντα οὐκ ἐπίστευσαν οὐ γὰρ πρότερον ἀπέλυσαν ἢ ἔλαβον τὸ ἀργύριον. ὁ μέντοι Καῖσαρ οὐ κατεμαρτύρησε κληθεὶς ἐπὶ τὸν Κλώδιον, οὐδ’ ἔφη μοιχείαν κατεγνωκέναι τῆς γυναικός, ἀφεικέναι δ’ αὐτὴν ὅτι τὸν Καίσαρος ἔδει γάμον οὐ πράξεως αἰσχρᾶς μόνον, ἀλλὰ καί φήμης καθαρὸν εἶναι.", "st": "Cic. 29.1"}, {"sp": "N", "t": "διαφυγὼν δὲ τόν κίνδυνον ὁ Κλώδιος καὶ δήμαρχος αἱρεθείς εὐθὺς εἴχετο τοῦ Κικέρωνος, πάνθ’ ὁμοῦ πράγματα καὶ πάντας ἀνθρώπους συνάγων καὶ ταράττων ἐπ’ αὐτόν, τόν τε γὰρ δῆμον ᾠκειώσατο νόμοις φιλανθρώποις, καὶ τῶν ὑπάτων ἑκατέρῳ μεγάλας ἐπαρχίας ἐψηφίσατο, Πείσωνι μὲν Μακεδονίαν, Γαβινίῳ δὲ Συρίαν, πολλοὺς δὲ τῶν ἀπόρων συνέτασσεν εἰς τὸ πολίτευμα, καὶ δούλους ὡπλισμένους περὶ αὑτὸν εἶχε. τῶν δὲ πλεῖστον δυναμένων τότε τριῶν ἀνδρῶν, Κράσσου μὲν ἄντικρυς Κικέρωνι πολεμοῦντος, Πομπηΐου δὲ θρυπτομένου πρὸς ἀμφοτέρους, Καίσαρος δὲ μέλλοντος εἰς Γαλατίαν ἐξιέναι μετὰ στρατεύματος, ὑπὸ τοῦτον ὑποδὺς ὁ Κικέρων, καίπερ οὐκ ὄντα φίλον, ἀλλ’ ὕποπτον ἐκ τῶν περὶ Κατιλίναν, ἠξίωσε πρεσβευτὴς αὐτῷ συστρατεύειν. δεξαμένου δὲ τοῦ Καίσαρος ὁ Κλώδιος ὁρῶν ἐκφεύγοντα τὴν δημαρχίαν αὐτοῦ τόν Κικέρωνα προσεποιεῖτο συμβατικῶς ἔχειν, καὶ τῇ Τερεντίᾳ τὴν πλείστην ἀνατιθεὶς αἰτίαν, ἐκείνου δὲ μεμνημένος ἐπιεικῶς ἀεὶ καὶ λόγους εὐγνώμονας ἐνδιδούς, ὡς ἄν τις οὐ μισῶν οὐδὲ χαλεπαίνων, ἀλλ’ ἐγκαλῶν μέτρια καὶ φιλικά, παντάπασιν αὐτοῦ τόν φόβον ἀνῆκεν, ὥστ’ ἀπειπεῖν τῷ Καίσαρι τὴν πρεσβείαν καὶ πάλιν ἔχεσθαι τῆς πολιτείας. ἐφ’ ᾧ παροξυνθεὶς ὁ Καῖσαρ τόν τε Κλώδιον ἐπέρρωσε καὶ Πομπήιον ἀπέστρεψε κομιδῇ τοῦ Κικέρωνος, αὐτός τε κατεμαρτύρησεν ἐν τῷ δήμῳ μὴ δοκεῖν αὐτῷ καλῶς μηδὲ νομίμως ἄνδρας ἀκρίτους ἀνῃρῆσθαι τοὺς περὶ Λέντλον καὶ Κέθηγον. αὕτη γὰρ ἦν ἡ κατηγορία, καὶ ἐπὶ τοῦθ’ ὁ Κικέρων ἐκαλεῖτο. κινδυνεύων οὖν καὶ διωκόμενος ἐσθῆτά μετήλλαξε καὶ κόμης ἀνάπλεως περιιὼν ἱκέτευε τὸν δῆμον. πανταχοῦ δ’ ὁ Κλώδιος ἀπήντα κατὰ τοὺς στενωπούς, ἀνθρώπους ἔχων ὑβριστὰς περὶ αὑτὸν καὶ θρασεῖς, οἳ πολλὰ μὲν χλευάζοντες ἀκολάστως εἰς τὴν μεταβολὴν καὶ τὸ σχῆμα τοῦ Κικέρωνος, πολλαχοῦ δὲ πηλῷ καὶ λίθοις βάλλοντες ἐνίσταντο ταῖς ἱκεσίαις.", "st": "Cic. 30.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τῷ Κικέρωνι πρῶτον μὲν ὀλίγου δεῖν σύμπαν τὸ τῶν ἱππικῶν πλῆθος συμμετέβαλε τὴν ἐσθῆτα, καὶ δισμυρίων οὐκ ἐλάττους νέων παρηκολούθουν κομῶντες καὶ συνικετεύοντες· ἔπειτα τῆς βουλῆς συνελθούσης ὅπως ψηφίσαιτο τὸν δῆμον ὡς ἐπὶ πένθεσι μεταβαλεῖν τὰ ἱμάτια, καὶ τῶν ὑπάτων ἐναντιωθέντων, Κλωδίου δὲ σιδηροφορουμένου περὶ τὸ βουλευτήριον, ἐξέδραμον οὐκ ὀλίγοι τῶν βουλευτικῶν καταρρηγνύμενοι τοὺς χιτῶνας καὶ βοῶντες. ὡς δ’ ἦν οὔτ’ οἶκτος οὔτε τις αἰδὼς πρὸς τὴν ὄψιν, ἀλλ’ ἔδει τὸν Κικέρωνα φεύγειν ἢ βίᾳ καὶ σιδήρῳ κριθῆναι πρὸς τὸν Κλώδιον, ἐδεῖτο Πομπηΐου βοηθεῖν ἐπίτηδες ἐκποδὼν γεγονότος καὶ διατρίβοντος ἐν ἀγροῖς περὶ τὸν Ἀλβανόν. καὶ πρῶτον μὲν ἔπεμψε Πείσωνα τὸν γαμβρὸν δεησόμενον ἔπειτα καὶ αὐτὸς ἀνέβη. πυθόμενος δ’ ὁ Πομπήιος οὐχ ὑπέμεινεν εἰς ὄψιν ἐλθεῖν, δεινὴ γὰρ αὐτὸν αἰδὼς εἶχε πρὸς τὸν ἄνδρα μεγάλους ἠγωνισμένον ἀγῶνας ὑπὲρ αὐτοῦ καὶ πολλὰ πρὸς χάριν ἐκείνῳ πεπολιτευμένον, ἀλλὰ Καίσαρι γαμβρὸς ὢν δεομένῳ προὔδωκε τὰς παλαιὰς χάριτας καὶ κατὰ θύρας ἄλλας ὑπεξελθὼν ἀπεδίδρασκε τὴν ἔντευξιν. οὕτω δὴ προδοθεὶς ὁ Κικέρων ὑπ’ αὐτοῦ καὶ γεγονὼς ἔρημος ἐπὶ τοὺς ὑπάτους κατέφυγε. καὶ Γαβίνιος μὲν ἦν χαλεπὸς ἀεί, Πείσων δὲ διελέχθη πρᾳότερον αὐτῷ, παραινῶν ἐκστῆναι καὶ ὑποχωρῆσαι τῇ τοῦ Κλωδίου ῥύμῃ καὶ τὴν μεταβολὴν τῶν καιρῶν ἐνεγκεῖν καὶ γενέσθαι πάλιν σωτῆρα τῆς πατρίδος ἐν στάσεσι καὶ κακοῖς δι’ ἐκεῖνον οὔσης.", "st": "Cic. 31.1"}, {"sp": "N", "t": "τοιαύτης τυχὼν ἀποκρίσεως ὁ Κικέρων ἐβουλεύετο σὺν τοῖς φίλοις· καὶ Λεύκουλλος μὲν ἐκέλευε μένειν, ὡς περιεσόμενον, ἄλλοι δὲ φεύγειν, ὡς ταχὺ τοῦ δήμου ποθήσοντος αὐτόν, ὅταν ἐμπλησθῇ τῆς Κλωδίου μανίας καὶ ἀπονοίας. ταῦτ’ ἔδοξε Κικέρωνι· καὶ τὸ μὲν ἄγαλμα τῆς Ἀθηνᾶς, ὃ πολὺν χρόνον ἔχων ἐπὶ τῆς οἰκίας ἱδρυμένον ἐτίμα διαφερόντως, εἰς Καπιτώλιον κομίσας ἀνέθηκεν ἐπιγράψας Ἀθηνᾷ Ῥώμης φύλακι, πομποὺς δὲ παρὰ τῶν φίλων λαβών περὶ μέσας νύκτας ὑπεξῆλθε τῆς πόλεως καὶ πεζῇ διὰ Λευκανίας ἐπορεύετο, λαβέσθαι Σικελίας βουλόμενος.", "st": "Cic. 31.5"}, {"sp": "N", "t": "ὡς δ’ ἦν φανερὸς ἤδη πεφευγώς, ἐπήγαγεν αὐτῷ φυγῆς ψῆφον ὁ Κλώδιος, καὶ διάγραμμα προὔθηκεν εἴργειν πυρὸς καὶ ὕδατος τὸν ἄνδρα καὶ μὴ παρέχειν στέγην ἐντὸς μιλίων πεντακοσίων Ἰταλίας. τοῖς μὲν οὖν ἄλλοις ἐλάχιστος ἦν τοῦ διαγράμματος τούτου λόγος αἰδουμένοις τὸν Κικέρωνα, καὶ πᾶσαν ἐνδεικνύμενοι φιλοφροσύνην παρέπεμπον αὐτόν· ἐν δ’ Ἱππωνίῳ, πόλει τῆς Λευκανίας, ἣν Οὐιβῶνα νῦν καλοῦσιν, Οὐίβιος, Σικελὸς ἀνὴρ, ἄλλα τε πολλὰ τῆς Κικέρωνος φιλίας ἀπολελαυκὼς καὶ γεγονὼς ὑπατεύοντος αὐτοῦ τεκτόνων ἔπαρχος, οἰκίᾳ μὲν οὐκ ἐδέξατο, τὸ χωρίον δὲ καταγράψειν ἐπηγγέλλετο, καὶ Γάιος Οὐεργίλιος, ὁ τῆς Σικελίας στρατηγός, ἐν τοῖς μάλιστα Κικέρωνι κεχρημένος, ἔγραψεν ἀπέχεσθαι τῆς Σικελίας. ἐφ’ οἷς ἀθυμήσας ὥρμησεν ἐπὶ Βρεντέσιον, κἀκεῖθεν εἰς Δυρράχιον ἀνέμῳ φορῷ περαιούμενος, ἀντιπνεύσαντος πελαγίου μεθ’ ἡμέραν ἐπαλινδρόμησεν, εἶτ’ αὖθις ἀνήχθη. λέγεται δὲ καὶ καταπλεύσαντος εἰς Δυρράχιον αὐτοῦ καὶ μέλλοντος ἀποβαίνειν σεισμόν τε τῆς γῆς καὶ σπασμὸν ἅμα γενέσθαι τῆς θαλάττης. ἀφ’ ὧν συνέβαλον οἱ μαντικοὶ μὴ μόνιμον αὐτῷ τὴν φυγὴν ἔσεσθαι· μεταβολῆς γὰρ εἶναι ταῦτα σημεῖα. πολλῶν δὲ φοιτώντων ἀνδρῶν ὑπ’ εὐνοίας καὶ τῶν Ἑλληνίδων πόλεων διαμιλλωμένων πρὸς αὑτὰς ταῖς πρεσβείαις, ὅμως ἀθυμῶν καὶ περίλυπος διῆγε τὰ πολλά, πρὸς τὴν Ἰταλίαν, ὥσπερ οἱ δυσέρωτες, ἀφορῶν, καὶ τῷ φρονήματι μικρὸς ἄγαν καὶ ταπεινὸς ὑπὸ τῆς συμφορᾶς γεγονὼς καὶ συνεσταλμένος, ὡς οὐκ ἄν τις ἄνδρα παιδείᾳ, συμβεβιωκότα τοσαύτῃ προσεδόκησε. καίτοι πολλάκις αὐτὸς ἠξίου τοὺς φίλους μὴ ῥήτορα καλεῖν αὐτόν, ἀλλὰ φιλόσοφον φιλοσοφίαν γὰρ ὡς ἔργον ᾑρῆσθαι, ῥητορικῇ δ’ ὀργάνῳ χρῆσθαι πολιτευόμενος ἐπὶ τὰς χρείας. ἀλλ’ ἡ δόξα δεινὴ τὸν λόγον, ὥσπερ βαφὴν, ἀποκλύσαι τῆς ψυχῆς, καὶ τὰ τῶν πολλῶν ἐνομόρξασθαι πάθη δι’ ὁμιλίαν καὶ συνήθειαν τοῖς πολιτευομένοις, ἄν μή τις εὖ μάλα φυλαττόμενος οὕτω συμφέρηται τοῖς ἐκτός ὡς τῶν πραγμάτων αὐτῶν, οὐ τῶν ἐπὶ τοῖς πράγμασι παθῶν συμμεθέξων.", "st": "Cic. 32.1"}, {"sp": "N", "t": "ὁ δὲ Κλώδιος ἐξελάσας τὸν Κικέρων κατέπρησε μὲν αὐτοῦ τὰς ἐπαύλεις, κατέπρησε δὲ τὴν οἰκίαν καὶ τῷ τόπῳ ναὸν Ἐλευθερίας ἐπῳκοδόμησε· τὴν δ’ ἄλλην οὐσίαν ἐπώλει καὶ διεκήρυττε καθ’ ἡμέραν, μηδὲν ὠνουμένου μηδενός, ἐκ δὲ τούτου φοβερὸς ὢν τοῖς ἀριστοκρατικοῖς, καὶ τὸν δῆμον ἀνειμένον εἰς ὕβριν πολλὴν καὶ θρασύτητα συνεφελκόμενος, ἐπεχείρει τῷ Πομπηίῳ, τῶν διῳκημένων ὑπ’ αὐτοῦ κατὰ τὴν στρατείαν ἔνια σπαράττων. ἐφ’ οἷς ὁ Πομπήιος ἀδοξῶν ἐκάκιζεν αὐτὸς ἑαυτὸν προέμενος τὸν Κικέρωνα καὶ πάλιν ἐκ μεταβολῆς παντοῖος ἐγίνετο πράττων κάθοδον αὐτῷ μετὰ τῶν φίλων, ἐνισταμένου δὲ τοῦ Κλωδίου συνέδοξε τῇ βουλῇ μηδὲν διὰ μέσου πρᾶγμα κυροῦν μηδὲ πράττειν δημόσιον, εἰ μὴ Κικέρωνι κάθοδος γένοιτο. τῶν δὲ περὶ Λέντλον ὑπατευόντων καὶ τῆς στάσεως πρόσω βαδιζούσης, ὥστε τρωθῆναι μὲν ἐν ἀγορᾷ δημάρχους, Κόιντον δὲ τὸν Κικέρωνος ἀδελφὸν ἐν τοῖς νεκροῖς ὡς τεθνηκότα κείμενον διαλαθεῖν, ὅ τε δῆμος ἤρχετο τρέπεσθαι τῇ γνώμῃ, καὶ τῶν δημάρχων Ἄννιος Μίλων πρῶτος ἐτόλμησε τὸν Κλώδιον εἰς δίκην ἀπάγειν βιαίων, καὶ Πομπηΐῳ πολλοὶ συνῆλθον ἔκ τε τοῦ δήμου καὶ τῶν πέριξ πόλεων, μεθ’ ὧν προελθὼν καὶ τὸν Κλώδιον ἀναστήσας ἐκ τῆς ἀγορᾶς ἐπὶ τὴν ψῆφον ἐκάλει τοὺς πολίτας. καὶ λέγεται μηδέποτε μηδὲν ἐκ τοσαύτης ὁμοφροσύνης ἐπιψηφίσασθαι τὸν δῆμον. ἡ δὲ σύγκλητος ἁμιλλωμένη πρὸς τὸν δῆμον ἔγραψεν ἐπαινεθῆναι τὰς πόλεις ὅσαι τὸν Κικέρωνα παρὰ τὴν φυγὴν ἐθεράπευσαν, καὶ τὴν οἰκίαν αὐτῷ καὶ τὰς ἐπαύλεις, ἃς Κλώδιος διεφθάρκει, τέλεσι δημοσίοις ἀνασταθῆναι.", "st": "Cic. 33.1"}, {"sp": "N", "t": "κατῄει δὲ Κικέρων ἑκκαιδεκάτῳ μηνὶ μετὰ τὴν φυγήν· καὶ τοσαύτη τὰς πόλεις χαρὰ καὶ σπουδὴ τοὺς ἀνθρώπους περὶ τὴν ἀπάντησιν εἶχεν ὥστε τὸ ῥηθὲν ὑπὸ Κικέρωνος ὕστερον ἐνδεέστερον εἶναι τῆς ἀληθείας, ἔφη γὰρ αὑτὸν ἐπὶ τῶν ὤμων τὴν Ἰταλίαν φέρουσαν εἰς τὴν Ῥώμην εἰσενεγκεῖν. ὅπου καὶ Κράσσος, ἐχθρὸς ὢν αὐτῷ πρὸ τῆς φυγῆς, τότε προθύμως ἀπήντα καὶ διελύετο, τῷ παιδὶ Ποπλίῳ χαριζόμενος, ὡς ἔλεγε, ζηλωτῇ τοῦ Κικέρωνος ὄντι.", "st": "Cic. 33.7"}, {"sp": "N", "t": "χρόνον δ’ οὐ πολὺν διαλιπὼν καὶ παραφυλάξας ἀποδημοῦντα τὸν Κλώδιον ἐπῆλθε μετὰ πολλῶν τῷ Καπιτωλίῳ, καὶ τὰς δημαρχικὰς δέλτους, ἐν αἷς ἀναγραφαὶ τῶν διῳκημένων ἦσαν, ἀπέσπασε καὶ διέφθειρεν. ἐγκαλοῦντος δὲ περὶ τούτου τοῦ Κλωδίου, τοῦ δὲ Κικέρωνος λέγοντος ὡς παρανόμως ἐκ πατρικίων εἰς δημαρχίαν παρέλθοι, καὶ κύριον οὐδὲν εἶναι τῶν πεπραγμένων ὑπ’ αὐτοῦ, Κάτων ἠγανάκτησε καὶ ἀντεῖπε, τὸν μὲν Κλώδιον οὐκ ἐπαινῶν, ἀλλὰ καὶ δυσχεραίνων τοῖς πεπολιτευμένοις, δεινὸν δὲ καὶ βίαιον ἀποφαίνων ἀναίρεσιν ψηφίσασθαι δογμάτων καὶ πράξεων τοσούτων τὴν σύγκλητον, ἐν αἷς εἶναι καὶ τὴν ἑαυτοῦ τῶν περὶ Κύπρον καὶ Βυζάντιον διοίκησιν. ἐκ τούτου προσέκρουσεν ὁ Κικέρων αὐτῷ πρόσκρουσιν εἰς οὐδὲν ἐμφανὲς προελθοῦσαν, ἀλλ’ ὥστε τῇ φιλοφροσύνῃ χρῆσθαι πρὸς ἀλλήλους ἀμαυρότερον.", "st": "Cic. 34.1"}, {"sp": "N", "t": "μετὰ ταῦτα Κλώδιον μὲν ἀποκτίννυσι Μίλων· καὶ διωκόμενος φόνου Κικέρωνα παρεστήσατο συνήγορον. ἡ δὲ βουλὴ φοβηθεῖσα μὴ κινδυνεύοντος ἀνδρὸς ἐνδόξου καὶ θυμοειδοῦς τοῦ Μίλωνος ταραχὴ γένηται περὶ τὴν πόλιν, ἐπέτρεψε Πομπηίῳ ταύτην τε καὶ τὰς ἄλλας κρίσεις βραβεῦσαι, παρέχοντα τῇ πόλει καὶ τοῖς δικαστηρίοις ἀσφάλειαν. ἐκείνου δὲ τὴν ἀγορὰν ἔτι νυκτὸς ἀπὸ τῶν ἄκρων περιλαβόντος τοῖς στρατιώταις, ὁ Μίλων τὸν Κικέρωνα δείσας μὴ πρὸς τὴν ὄψιν ἀηθείᾳ διαταραχθεὶς χεῖρον διαγωνίσηται, συνέπεισεν ἐν φορείῳ κομισθέντα πρὸς τὴν ἀγορὰν ἡσυχάζειν, ἄχρι οὗ συνίασιν οἱ κριταὶ καὶ πληροῦται τὸ δικαστήριον. ὁ δ’ οὐ μόνον ἦν, ὡς ἔοικεν, ἐν ὅπλοις ἀθαρσής, ἀλλὰ καὶ τῷ λέγειν μετὰ φόβου προσῄει, καὶ μόλις ἂν ἐπαύσατο παλλόμενος καὶ τρέμων ἐπὶ πολλῶν ἀγώνων ἀκμὴν τοῦ λόγου καὶ κατάστασιν λαβόντος. Λικιννίῳ δὲ Μουρήνᾳ φεύγοντι δίκην ὑπὸ Κάτωνος βοηθῶν, καὶ φιλοτιμούμενος Ὁρτήσιον ὑπερβαλεῖν εὐημερήσαντα, μέρος οὐδὲν ἀνεπαύσατο τῆς νυκτός, ὡς ὑπὸ τοῦ σφόδρα φροντίσαι καὶ διαγρυπνῆσαι κακωθεὶς ἐνδεέστερος αὐτοῦ φανῆναι. τότε δ’ οὖν ἐπὶ τὴν τοῦ Μίλωνος δίκην ἐκ τοῦ φορείου προελθών καὶ θεασάμενος τὸν Πομπήϊον ἄνω καθεζόμενον ὥσπερ ἐν στρατοπέδῳ, καὶ κύκλῳ τὰ ὅπλα περιλάμποντα τὴν ἀγοράν, συνεχύθη καὶ μόλις ἐνήρξατο τοῦ λόγου, κραδαινόμενος τὸ σῶμα καὶ τὴν φωνὴν ἐνισχόμενος, αὐτοῦ τοῦ Μίλωνος εὐθαρσῶς καὶ ἀνδρείως παρισταμένου τῷ ἀγῶνι καὶ κόμην θρέψαι καὶ μεταβαλεῖν ἐσθῆτα φαιὰν ἀπαξιώσαντος· ὅπερ οὐχ ἥκιστα δοκεῖ συναίτιον αὐτῷ γενέσθαι τῆς καταδίκης· ἀλλ’ ὅ γε Κικέρων διὰ ταῦτα φιλέταιρος μᾶλλον ἢ δειλὸς ἔδοξεν εἶναι.", "st": "Cic. 35.1"}, {"sp": "N", "t": "γίνεται δὲ καὶ τῶν ἱερέων οὓς Αὔγουρας Ῥωμαῖοι καλοῦσιν, ἀντὶ Κράσσου τοῦ νέου μετὰ τὴν ἐν Πάρθοις αὐτοῦ τελευτήν. εἶτα κλήρῳ λαχὼν τῶν ἐπαρχιῶν Κιλικίαν καὶ στρατὸν ὁπλιτῶν μυρίων καὶ δισχιλίων, ἱππέων δὲ δισχιλίων ἑξακοσίων, ἔπλευσε, προσταχθὲν αὐτῷ καὶ τὰ περὶ Καππαδοκίαν Ἀριοβαρζάνῃ τῷ βασιλεῖ φίλα καὶ πειθήνια παρασχεῖν. ταῦτα τε δὴ παρεστήσατο καὶ συνήρμοσεν ἀμέμπτως ἄτερ πολέμου, τούς τε Κίλικας ὁρῶν πρός τὸ Παρθικὸν πταῖσμα Ῥωμαίων καὶ τὸν ἐν Συρίᾳ νεωτερισμὸν ἐπηρμένους κατεπράυνεν ἡμέρως ἄρχων, καὶ δῶρα μὲν οὐδὲ τῶν βασιλέων διδόντων ἔλαβε, δείπνων δὲ τούς ἐπαρχικοὺς ἀνῆκεν αὐτὸς δὲ καθ’ ἡμέραν τοὺς χαρίεντας ἀνελάμβανεν ἑστιάσεσιν οὐ πολυτελῶς, ἀλλ’ ἐλευθερίως. ἡ δ’ οἰκία θυρωρὸν οὐκ εἶχεν, οὐδ’ αὐτὸς ὤφθη κατακείμενος ὑπ’ οὐδενός, ἀλλ’ ἕωθεν ἑστὼς ἢ περιπατῶν πρὸ τοῦ δωματίου τούς ἀσπαζομένους ἐδεξιοῦτο. λέγεται δὲ μήτε ῥάβδοις αἰκίσασθαί τινα μήτ’ ἐσθῆτα περισχίσαι μήτε βλασφημίαν ὑπ’ ὀργῆς ἢ ζημίας προσβαλεῖν μεθ’ ὕβρεων. ἀνευρὼν δὲ πολλὰ τῶν δημοσίων κεκλεμμένα τάς τε πόλεις εὐπόρους ἐποίησε, καὶ τούς ἀποτίνοντας οὐδὲν τούτου πλεῖον παθόντας ἐπιτίμους διεφύλαξεν. ἥψατο δὲ καὶ πολέμου, λῃστὰς τῶν περὶ τὸν Ἀμανὸν οἰκούντων τρεψάμενος· ἐφ’ ᾧ καὶ αὐτοκράτωρ ὑπὸ τῶν στρατιωτῶν ἀνηγορεύθη. Καιλίου δὲ τοῦ ῥήτορος δεομένου παρδάλεις αὐτῷ πρός τινα θέαν εἰς Ῥώμην ἐκ Κιλικίας ἀποστεῖλαι, καλλωπιζόμενος ἐπὶ τοῖς πεπραγμένοις γράφει πρός αὐτὸν οὐκ εἶναι παρδάλεις ἐν Κιλικίᾳ· πεφευγέναι γὰρ εἰς Καρίαν ἀγανακτούσας ὅτι μόναι πολεμοῦνται, πάντων εἰρήνην ἐχόντων, πλέων δ’ ἀπὸ τῆς ἐπαρχίας τοῦτο μὲν Ῥόδῳ προσέσχε, τοῦτο δ’ Ἀθήναις ἐνδιέτριψεν ἄσμενος πόθῳ τῶν πάλαι διατριβῶν. ἀνδράσι δὲ τοῖς πρώτοις ἀπὸ παιδείας συγγενόμενος καὶ τούς τότε φίλους καὶ συνήθεις ἀσπασάμενος καὶ τὰ πρέποντα θαυμασθεὶς ὑπὸ τῆς Ἑλλάδος εἰς τὴν πόλιν ἐπανῆλθεν, ἤδη τῶν πραγμάτων ὥσπερ ὑπὸ φλεγμονῆς ἀφισταμένων ἐπὶ τὸν ἐμφύλιον πόλεμον.", "st": "Cic. 36.1"}, {"sp": "N", "t": "ἐν μὲν οὖν τῇ βουλῇ ψηφιζομένων αὐτῷ θρίαμβον ἥδιον ἂν ἔφη παρακολουθῆσαι Καῖσαρ ι θριαμβεύοντι συμβάσεων γενομένων ἰδίᾳ δὲ συνεβούλευε πολλὰ μὲν Καίσαρι γράφων, πολλὰ δ’ αὑτοῦ Πομπηίου δεόμενος, πραΰνων ἑκάτερον καὶ παραμυθούμενος, ὡς δ’ ἦν ἀνήκεστα καὶ Καίσαρος ἐπερχομένου Πομπήιος οὐκ ἔμεινεν, ἀλλὰ μετὰ πολλῶν καὶ ἀγαθῶν ἀνδρῶν τὴν πόλιν ἐξέλιπε, ταύτης μὲν ἀπελείφθη τῆς φυγῆς ὁ Κικέρων, ἔδοξε δὲ Καίσαρι προστίθεσθαι. καὶ δῆλός ἐστι τῇ γνώμῃ πολλὰ ῥιπτασθεὶς ἐπ’ ἀμφότερα καὶ δυσπαθήσας. γράφει γὰρ ἐν ταῖς ἐπιστολαῖς διαπορεῖν ποτέρωσε χρὴ τρέπεσθαι, Πομπηίου μὲν ἔνδοξον καὶ καλὴν ὑπόθεσιν πρὸς τὸν πόλεμον ἔχοντος, Καίσαρος δ’ ἄμεινον τοῖς πράγμασι χρωμένου καὶ μᾶλλον ἑαυτὸν καὶ τοὺς φίλους σῴζοντος, ὥστ’ ἔχειν μὲν ὃν φύγῃ, μὴ ἔχειν δὲ πρὸς ὃν φύγῃ. Τρεβατίου δέ, τινος τῶν Καίσαρος ἑταίρων, γράψαντος ἐπιστολήν ὅτι Καῖσαρ οἴεται δεῖν μάλιστα μὲν αὐτὸν ἐξετάζεσθαι μεθ’ αὑτοῦ καὶ τῶν ἐλπίδων μετέχειν, εἰ δ’ ἀναδύεται διὰ γῆρας, εἰς τὴν Ἑλλάδα βαδίζειν κἀκεῖ καθήμενον ἡσυχίαν ἄγειν ἐκποδὼν ἀμφοτέροις γενόμενον, θαυμάσας ὁ Κικέρων ὅτι Καῖσαρ αὐτὸς οὐκ ἔγραψεν, ἀπεκρίνατο πρὸς ὀργὴν ὡς οὐδὲν ἀνάξιον πράξει τῶν πεπολιτευμένων. τὰ μὲν οὖν ἐν ταῖς ἐπιστολαῖς γεγραμμένα τοιαῦτα ἐστι.", "st": "Cic. 37.1"}, {"sp": "N", "t": "τοῦ δὲ Καίσαρος εἰς Ἰβηρίαν ἀπάραντος, εὐθὺς ὡς Πομπήιον ἔπλευσε· καὶ τοῖς μὲν ἄλλοις ἀσμένοις ὤφθη, Κάτων δ’ αὐτὸν ἰδὼν ἰδίᾳ πολλὰ κατεμέμφετο Πομπηίῳ προσθέμενον· αὐτῷ μὲν γὰρ οὐχὶ καλῶς ἔχειν ἐγκαταλιπεῖν ἣν ἀπ’ ἀρχῆς εἵλετο τῆς πολιτείας τάξιν, ἐκεῖνον δὲ χρησιμώτερον ὄντα τῇ πατρίδι καὶ τοῖς φίλοις εἰ μένων ἴσος ἐκεῖ πρὸς τὸ ἀποβαῖνον ἡρμόζετο, κατ’ οὐδένα λογισμὸν οὐδ’ ἐξ ἀνάγκης πολέμιον γεγονέναι Καίσαρι καὶ τοσούτου μεθέξοντα κινδύνου δεῦρ’ ἥκειν.", "st": "Cic. 38.1"}, {"sp": "N", "t": "οὗτοί τε δὴ τοῦ Κικέρωνος ἀνέστρεφον οἱ λόγοι τὴν γνώμην, καὶ τὸ μέγα μηδὲν αὐτῷ χρῆσθαι Πομπήιον. αἴτιος δ’ ἦν αὐτός οὐκ ἀρνούμενος μεταμέλεσθαι, φλαυρίζων δὲ τοῦ Πομπηίου τὴν παρασκευήν καὶ πρὸς τὰ βουλεύματα δυσκολαίνων ὑπούλως, καὶ τοῦ παρασκώπτειν τι καὶ λέγειν χαρίεν εἰς τοὺς συμμάχους οὐκ ἀπεχόμενος, ἀλλ’ αὐτός μὲν ἀγέλαστος ἀεὶ περιιὼν ἐν τῷ στρατοπέδῳ καὶ σκυθρωπός, ἑτέροις δὲ παρέχων γέλωτα μηδὲν δεομένοις. βέλτιον δὲ καὶ τούτων ὀλίγα παραθέσθαι. Δομιτίου τοίνυν ἄνθρωπον εἰς τάξιν ἡγεμονικὴν ἄγοντος οὐ πολεμικόν καὶ λέγοντος ὡς ἐπιεικὴς τὸν τρόπον ἐστι καὶ σώφρων, τί οὖν, εἶπεν, οὐκ ἐπίτροπον αὐτὸν τοῖς τέκνοις φυλάσσεις; ἐπαινούντων δέ τινων Θεοφάνην τὸν Λέσβιον, ὃς ἦν ἐν τῷ στρατοπέδῳ τεκτόνων ἔπαρχος, ὡς εὖ παραμυθήσαιτο Ῥοδίους τὸν στόλον ἀποβαλόντας, ἡλίκον, εἶπεν, ἀγαθόν ἐστι τὸ Γραικὸν ἔχειν ἔπαρχον Καίσαρος δὲ κατορθοῦντος τὰ πλεῖστα καὶ τρόπον τινὰ πολιορκοῦντος αὐτούς, Λέντλῳ μὲν εἰπόντι πυνθάνεσθαι στυγνοὺς εἶναι τοὺς Καίσαρος φίλους, ἀπεκρίνατο λέγεις αὐτοὺς δυσνοεῖν Καίσαρι. Μαρκίου δέ τινος ἥκοντος ἐξ Ἰταλίας νεωστὶ καὶ λέγοντος ἐν Ῥώμῃ φήμην ἐπικρατεῖν ὡς πολιορκοῖτο Πομπήιος, εἶτ’ ἐξέπλευσας, εἶπεν, ἵνα τοῦτο πιστεύσῃς αὐτός θεασάμενος; μετὰ δὲ τὴν ἧτταν Νοννίου μὲν εἰπόντος ὅτι δεῖ χρηστὰς ἐλπίδας ἔχειν, ἑπτὰ γὰρ ἀετοὺς ἐν τῷ στρατοπέδῳ τοῦ Πομπηίου λελεῖφθαι, καλῶς ἄν, ἔφη, παρῄνεις, εἰ κολοιοῖς ἐπολεμοῦμεν. Λαβιηνοῦ δὲ μαντείαις τισὶν ἰσχυριζομένου καὶ λέγοντος ὡς δεῖ περιγενέσθαι Πομπήιον, οὐκοῦν, ἔφη, στρατηγήματι τούτῳ χρώμενοι νῦν ἀποβεβλήκαμεν τὸ στρατόπεδον.", "st": "Cic. 38.2"}, {"sp": "N", "t": "ἀλλὰ γὰρ γενομένης τῆς κατὰ Φάρσαλον μάχης, ἧς οὐ μετέσχε δι’ ἀρρωστίαν, καὶ Πομπηίου φυγόντος, ὁ μὲν Κάτων καὶ στράτευμα συχνὸν ἐν Δυρραχίῳ καὶ στόλον ἔχων μέγαν ἐκεῖνον ἠξίου στρατηγεῖν κατὰ νόμον καὶ τὸ τῆς ὑπατείας ἀξίωμα προὔχοντα, διωθούμενος δὲ τὴν ἀρχὴν ὁ Κικέρων καὶ ὅλως φεύγων τὸ συστρατεύεσθαι παρ’ οὐδὲν ἦλθεν ἀναιρεθῆναι, Πομπηίου τοῦ νέου καὶ τῶν φίλων προδότην ἀποκαλούντων καὶ τὰ ξίφη σπασαμένων, εἰ μὴ Κάτων ἐνστὰς μόλις ἀφείλετο καὶ διῆκεν αὐτὸν ἐκ τοῦ στρατοπέδου, κατασχὼν δ’ εἷς Βρεντέσιον ἐνταῦθα διέτριβε, Καίσαρα περιμένων βραδύνοντα διὰ τὰς ἐν Ἀσίᾳ καὶ περὶ Αἴγυπτον ἀσχολίας. ἐπεὶ δ’ εἷς Τάραντα καθωρμισμένος ἀπηγγέλλετο καὶ πεζῇ παριϊὼν ἐκεῖθεν εἷς Βρεντέσιον, ὥρμησε πρὸς αὐτόν, οὐ πάνυ μὲν ὢν δύσελπις, αἰδούμενος δὲ πολλῶν παρόντων ἀνδρὸς ἐχθροῦ καὶ κρατοῦντος λαμβάνειν πεῖραν. οὐ μὴν ἐδέησεν αὐτῷ πρᾶξαί τι παρ’ ἀξίαν ἢ εἰπεῖν. ὁ γὰρ Καῖσαρ, ὡς εἶδεν αὐτὸν πολὺ πρὸ τῶν ἄλλων ἀπαντῶντα, κατέβη καὶ ἠσπάσατο καὶ διαλεγόμενος μόνῳ συχνῶν σταδίων ὁδὸν προῆλθεν. ἐκ δὲ τούτου διετέλει τιμῶν καὶ φιλοφρονούμενος, ὥστε καὶ γράψαντι λόγον ἐγκώμιον Κάτωνος ἀντιγράφων τόν τε λόγον αὐτοῦ καὶ τόν βίον ὡς μάλιστα τῷ Περικλέους ἐοικότα καὶ Θηραμένους ἐπαινεῖν. ὁ μὲν οὖν Κικέρωνος λόγος Κάτων, ὁ δὲ Καίσαρος Ἀντικάτων ἐπιγέγραπται.", "st": "Cic. 39.1"}, {"sp": "N", "t": "λέγεται δὲ καὶ Κοΐντου Λιγαρίου δίκην φεύγοντος ὅτι τῶν Καίσαρος πολεμίων εἷς ἐγεγόνει, καὶ Κικέρωνος αὐτῷ βοηθοῦντος, εἰπεῖν τόν Καίσαρα πρὸς τοὺς φίλους· τί κωλύει διὰ χρόνου Κικέρωνος ἀκοῦσαι λέγοντος, ἐπεὶ πάλαι κέκριται πονηρὸς ὁ ἀνὴρ καὶ πολέμιος; ἐπεὶ δ’ ἀρξάμενος λέγειν ὁ Κικέρων ὑπερφυῶς ἐκίνει καὶ προὔβαινεν αὐτῷ πάθει τε ποικίλος καὶ χάριτι θαυμαστὸς ὁ λόγος, πολλὰς μὲν ἱέναι χρόας ἐπὶ τοῦ προσώπου τόν Καίσαρα, πάσας δὲ τῆς ψυχῆς τρεπόμενον τροπὰς κατάδηλον εἶναι, τέλος δὲ τῶν κατὰ Φάρσαλον ἁψαμένου τοῦ ῥήτορος ἀγώνων ἐκπαθῆ γενόμενον τιναχθῆναι τῷ σώματι καὶ τῆς χειρὸς ἐκβαλεῖν ἔνια τῶν γραμματείων, τόν γοῦν ἄνθρωπον ἀπέλυσε τῆς αἰτίας βεβιασμένος.", "st": "Cic. 39.1b"}, {"sp": "N", "t": "ἐκ τούτου Κικέρων, εἰς μοναρχίαν τῆς πολιτείας μεθεστώσης, ἀφέμενος τοῦ τὰ κοινὰ πράττειν ἐσχόλαζε τοῖς βουλομένοις φιλοσοφεῖν τῶν νέων, καὶ σχεδὸν ἐκ τῆς πρὸς τούτους συνηθείας, εὐγενεστάτους καὶ πρώτους ὄντας, αὖθις ἴσχυεν ἐν τῇ πόλει μέγιστον. αὐτῷ δ’ ἔργον μὲν ἦν τὸ τοὺς φιλοσόφους συντελεῖν διαλόγους καὶ μεταφράζειν, καὶ τῶν διαλεκτικῶν ἢ φυσικῶν ὀνομάτων ἕκαστον εἰς Ῥωμαϊκὴν μεταβάλλειν διάλεκτον ἐκεῖνος γάρ ἐστιν, ὥς φασιν, ὁ καὶ τὴν φαντασίαν καὶ τὴν συγκατάθεσιν καὶ τὴν ἐποχὴν καὶ τὴν κατάληψιν, ἔτι δὲ τὸ ἄτομον, τὸ ἀμερές, τὸ κενὸν, ἄλλα τε πολλὰ τῶν τοιούτων ἐξονομάσας πρῶτος ἢ μάλιστα Ῥωμαίοις, τὰ μὲν μεταφοραῖς, τὰ δ’ οἰκειότησιν ἄλλαις γνώριμα καὶ προσήγορα μηχανησάμενος. τῇ δὲ πρὸς τὴν ποίησιν εὐκολίᾳ παίζων ἐχρῆτο. λέγεται γάρ, ὁπηνίκα ῥυείη πρὸς τὸ τοιοῦτον, τῆς νυκτὸς ἔπη ποιεῖν πεντακόσια.", "st": "Cic. 40.1"}, {"sp": "N", "t": "τὸ μὲν οὖν πλεῖστον τοῦ χρόνου τούτου περὶ Τοῦσκλον ἐν χωρίοις αὑτοῦ διάγων ἔγραφε πρὸς τοὺς φίλους Λαέρτου βίον ζῆν, εἴτε παίζων, ὡς ἔθος εἶχεν, εἴθ’ ὑπὸ φιλοτιμίας σπαργῶν πρὸς τὴν πολιτείαν καὶ ἀδημονῶν τοῖς καθεστῶσι. σπανίως δ’ εἰς ἄστυ θεραπείας ἕνεκα τοῦ Καίσαρος κατῄει, καὶ πρῶτος ἦν τῶν συναγορευόντων ταῖς τιμαῖς καὶ λέγειν ἀεί τι καινὸν εἰς τὸν ἄνδρα καὶ τὰ πραττόμενα φιλοτιμουμένων, οἷόν ἐστι καὶ τὸ περὶ τῶν Πομπηίου λεχθὲν εἰκόνων, ἃς ἀνῃρημένας καὶ καταβεβλημένας ὁ Καῖσαρ ἐκέλευσεν ἀνασταθῆναι· καὶ ἀνεστάθησαν. ἔφη γὰρ ὁ Κικέρων ὅτι ταύτῃ τῇ φιλανθρωπίᾳ Καῖσαρ τοὺς μὲν Πομπηίου ἵστησι, τοὺς δ’ αὑτοῦ πήγνυσιν ἀνδριάντας.", "st": "Cic. 40.1b"}, {"sp": "N", "t": "διανοούμενος δ’, ὡς λέγεται, τὴν πάτριον ἱστορίαν γραφῇ περιλαβεῖν καὶ πολλὰ συμμῖξαι τῶν Ἑλληνικῶν καὶ ὅλως τοὺς συνηγμένους λόγους αὐτῷ καὶ μύθους ἐνταῦθα τρέψαι, πολλοῖς μὲν δημοσίοις, πολλοῖς δ’ ἰδίοις κατελήφθη πράγμασιν ἀβουλήτοις καὶ πάθεσιν, ὧν αὐθαίρετα δοκεῖ πλεῖστα συμβῆναι. πρῶτον μὲν γὰρ ἀπεπέμψατο τὴν γυναῖκα Τερεντίαν ἀμεληθεὶς ὑπ’ αὐτῆς παρὰ τὸν πόλεμον, ὥστε καὶ τῶν ἀναγκαίων ἐφοδίων ἐνδεὴς ἀποσταλῆναι καὶ μηδ’ ὅτε κατῆρεν αὖθις εἰς Ἰταλίαν τυχεῖν εὐγνώμονος, αὐτὴ μὲν γὰρ οὐκ ἦλθεν, ἐν Βρεντεσίῳ διατρίβοντος αὐτοῦ πολὺν χρόνον, ἐρχομένῃ δὲ τῇ θυγατρί, παιδίσκῃ νέᾳ, τοσαύτην ὁδὸν, οὐ πομπὴν πρέπουσαν, οὐ χορηγίαν παρέσχεν, ἀλλὰ καὶ τὴν οἰκίαν τῷ Κικέρωνι πάντων ἔρημον καὶ κενὴν ἀπέδειξεν ἐπὶ πολλοῖς ὀφλήμασι καὶ μεγάλοις. αὗται γὰρ εἰσιν αἱ λεγόμεναι τῆς διαστάσεως εὐπρεπέσταται προφάσεις, τῇ δὲ Τερεντίᾳ καὶ ταύτας ἀρνουμένῃ λαμπρὰν ἐποίησε τὴν ἀπολογίαν αὐτὸς ἐκεῖνος μετ’ οὐ πολὺν χρόνον γήμας παρθένον, ὡς μὲν ἡ Τερεντία κατεφήμιζεν, ἔρωτι τῆς ὥρας, ὡς δὲ Τίρων ὁ τοῦ Κικέρωνος ἀπελεύθερος γέγραφεν, εὐπορίας ἕνεκεν πρὸς διάλυσιν δανείων. ἦν γὰρ ἡ παῖς σφόδρα πλουσία, καὶ τὴν οὐσίαν αὐτῆς ὁ Κικέρων ἐν πίστει κληρονόμος ἀπολειφθεὶς διεφύλαττεν. ὀφείλων δὲ πολλὰς μυριάδας ὑπὸ τῶν φίλων καὶ οἰκείων ἐπείσθη τὴν παῖδα γῆμαι παρ’ ἡλικίαν καὶ τοὺς δανειστὰς ἀπαλλάξαι τοῖς ἐκείνης χρησάμενος. Ἀντώνιος δὲ τοῦ γάμου μνησθεὶς ἐν ταῖς πρὸς τοὺς Φιλιππικοὺς ἀντιγραφαῖς ἐκβαλεῖν αὐτόν φησι γυναῖκα παρ’ ἡ ἐγήρασε· χαριέντως ἅμα τὴν οἰκουρίαν ὡς ἀπράκτου καὶ ἀστρατεύτου παρασκώπτων τοῦ Κικέρωνος. γήμαντι δ’ αὐτῷ μετ’ οὐ πολὺν χρόνον ἡ θυγάτηρ ἀπέθανε τίκτουσα παρὰ Λέντλῳ· τούτῳ γὰρ ἐγαμήθη μετὰ τὴν Πείσωνος τοῦ προτέρου ἀνδρὸς τελευτήν. καὶ συνῆλθον μὲν ἐπὶ τὴν παραμυθίαν τῷ Κικέρωνι πανταχόθεν οἱ φίλοι· βαρέως δ’ ἄγαν ἤνεγκε τὸ συμβεβηκός, ὥστε καὶ τὴν γαμηθεῖσαν ἀποπέμψασθαι δόξασαν ἡσθῆναι τῇ τελευτῇ τῆς Τυλλίας.", "st": "Cic. 41.1"}, {"sp": "N", "t": "τὰ μὲν οὖν κατ’ οἶκον οὕτως εἶχε τῷ Κικέρωνι. τῆς δ’ ἐπὶ Καίσαρα συνισταμένης πράξεως οὐ μετέσχε, καίπερ ὢν ἑταῖρος ἐν τοῖς μάλιστα Βρούτου καὶ βαρύνεσθαι τὰ παρόντα καὶ τὰ πάλαι ποθεῖν πράγματα δοκῶν ὡς ἕτερος οὐδείς. ἀλλ’ ἔδεισαν οἱ ἄνδρες αὐτοῦ τήν τε φύσιν ὡς ἐνδεᾶ τόλμης, τόν τε χρόνον, ἐν ᾧ καὶ ταῖς ἐρρωμενεστάταις φύσεσιν ἐπιλείπει τὸ θαρρεῖν. ὡς δ’ οὖν ἐπέπρακτο τοῖς περὶ Βροῦτον καὶ Κάσσιον τὸ ἔργον καὶ τῶν Καίσαρος φίλων συνισταμένων ἐπὶ τοὺς ἄνδρας αὖθις ἦν δέος ἐμφυλίοις πολέμοις περιπετῆ γενέσθαι τήν πόλιν, Ἀντώνιος μὲν ὑπατεύων τήν βουλὴν συνήγαγε καὶ βραχέα διελέχθη περὶ ὁμονοίας, Κικέρων δὲ πολλὰ πρὸς τὸν καιρὸν οἰκείως διελθών ἔπεισε τήν σύγκλητον Ἀθηναίους μιμησαμένην ἀμνηστίαν τῶν ἐπὶ Καίσαρι ψηφίσασθαι νεῖμαι δὲ τοῖς περὶ Κάσσιον καὶ Βροῦτον ἐπαρχίας. ἔσχε δὲ τούτων τέλος οὐδέν, ὁ γὰρ δῆμος αὐτὸς μὲν ἀφ’ ἑαυτοῦ πρὸς οἶκτον ἐξαχθείς ὡς εἶδε τόν νεκρὸν ἐκκομιζόμενον δι’ ἀγορᾶς, Ἀντωνίου δὲ καὶ τήν ἐσθῆτα δείξαντος αὐτοῖς αἵματος κατάπλεων καὶ κεκομμένην πάντῃ τοῖς ξίφεσιν, ἐκμανέντες ὑπ’ ὀργῆς ἐν ἀγορᾷ ζήτησιν ἐποιοῦντο τῶν ἀνδρῶν, καὶ πῦρ ἔχοντες ἐπὶ τὰς οἰκίας ἔθεον ὡς ὑφάψοντες. οἱ δὲ τοῦτον μὲν τῷ προπεφυλάχθαι διέφυγον τόν κίνδυνον, ἑτέρους δὲ πολλοὺς καὶ μεγάλους προσδοκῶντες ἐξέλιπον τήν πόλιν.", "st": "Cic. 42.1"}, {"sp": "N", "t": "εὐθὺς οὖν ὁ Ἀντώνιος ἐπῆρτο, καί πᾶσι μὲν ἦν φοβερὸς ὡς μοναρχήσων, τῷ δὲ Κικέρωνι φοβερώτατος. ἀναρρωννυμένην τε γὰρ αὐτῷ πάλιν ὁρῶν τὴν δύναμιν ἐν τῇ πολιτείᾳ καὶ τοῖς περὶ Βροῦτον ἐπιτήδειον εἰδώς ἤχθετο παρόντι. καί πού τι καί προϋπῆρχεν ὑποψίας αὐτοῖς πρὸς ἀλλήλους κατὰ τὴν τῶν βίων ἀνομοιότητα καί διαφοράν. ταῦτα δείσας ὁ Κικέρων πρῶτον μὲν ὥρμησε πρεσβευτὴς Δολοβέλλᾳ συνεκπλεῦσαι εἰς Συρίαν ἐπεὶ δ’ οἱ μέλλοντες ὑπατεύειν μετ’ Ἀντώνιον, Ἵρτιος καί Πάνσας, ἄνδρες ἀγαθοὶ καί ζηλωταὶ τοῦ Κικέρωνος, ἐδέοντο μὴ σφᾶς καταλιπεῖν, ὑποδεχόμενοι καταλύσειν Ἀντώνιον ἐκείνου παρόντος, ὁ δ’ οὔτ’ ἀπιστῶν παντάπασιν οὔτε πιστεύων Δολοβέλλαν μὲν εἴασε χαίρειν, ὁμολογήσας δὲ τοῖς περὶ τὸν Ἵρτιον τὸ θέρος ἐν Ἀθήναις διάξειν, ὅταν δ’ ἐκεῖνοι παραλάβωσι τὴν ἀρχήν, ἀφίξεσθαι πάλιν, αὐτὸς καθ’ ἑαυτὸν ἐξέπλευσε. γενομένης δὲ περὶ τόν πλοῦν διατριβῆς, καί λόγων ἀπὸ Ῥώμης, οἷα φιλεῖ, καινῶν προσπεσόντων, μεταβεβλῆσθαι μὲν Ἀντώνιον θαυμαστὴν μεταβολὴν καί πάντα πράττειν καί πολιτεύεσθαι πρὸς τὴν σύγκλητον, ἐνδεῖν δὲ τῆς ἐκείνου παρουσίας τὰ πράγματα μὴ τὴν ἀρίστην ἔχειν διάθεσιν, καταμεμψάμενος αὐτὸς αὐτοῦ τὴν πολλὴν εὐλάβειαν ἀνέστρεφεν αὖθις εἰς Ῥώμην. καί τῶν πρώτων οὐ διημάρτανεν ἐλπίδων τοσοῦτο πλῆθος ἀνθρώπων ὑπὸ χαρᾶς καί πόθου πρὸς τὴν ἀπάντησιν ἐξεχύθη, καὶ σχεδὸν ἡμερήσιον ἀνήλωσαν χρόνον αἱ περὶ τὰς πύλας καί τὴν εἴσοδον αὐτοῦ δεξιώσεις καί φιλοφροσύναι. τῇ δ’ ὑστεραίᾳ βουλὴν συναγαγόντος Ἀντωνίου καί καλοῦντος αὐτόν οὐκ ἦλθεν, ἀλλὰ κατέκειτο μαλακῶς ἔχειν ἐκ τοῦ κόπου σκηπτόμενος. ἐδόκει δὲ τἀληθὲς ἐπιβουλῆς εἶναι φόβος ἔκ τινος ὑποψίας καί μηνύσεως καθ’ ὁδὸν αὐτῷ προσπεσούσης. Ἀντώνιος δὲ χαλεπῶς μὲν εἶχεν ἐπὶ τῇ διαβολῇ καί στρατιώτας ἔπεμψεν ἄγειν αὐτόν ἢ καταπρῆσαι τὴν οἰκίαν κελεύσας, ἐνστάντων δὲ πολλῶν καί δεηθέντων ἐνέχυρα λαβὼν μόνον ἐπαύσατο. καί τὸ λοιπὸν οὕτως ἀντιπαρεξιόντες ἀτρέμα καί φυλαττόμενοι διετέλουν, ἄχρι οὗ Καῖσαρ ὁ νέος ἐξ Ἀπολλωνίας παραγενόμενος τόν τε κλῆρον ἀνεδέξατο τοῦ Καίσαρος ἐκείνου, καί περὶ τῶν δισχιλίων πεντακοσίων μυριάδων ἃς Ἀντώνιος ἐκ τῆς οὐσίας κατεῖχεν, εἰς διαφορὰν κατέστη πρὸς αὐτόν.", "st": "Cic. 43.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου Φίλιππος ὁ τὴν μητέρα τοῦ νέου Καίσαρος ἔχων καὶ Μάρκελλος ὁ τὴν ἀδελφὴν ἀφικόμενοι μετὰ τοῦ νεανίσκου πρὸς τὸν Κικέρωνα συνέθεντο, Κικέρωνα μὲν ἐκείνῳ τὴν ἀπὸ τοῦ λόγου καὶ τὴν ἀπὸ τῆς πολιτείας δύναμιν ἔν τε τῇ βουλῇ καὶ τῷ δήμῳ παρέχειν, ἐκεῖνον δὲ Κικέρωνι τὴν ἀπὸ τῶν χρημάτων καὶ τῶν ὅπλων ἀσφάλειαν. ἤδη γὰρ οὐκ ὀλίγους τῶν ὑπὸ Καίσαρι στρατευσαμένων περὶ αὑτὸν εἶχε τὸ μειράκιον. ἐδόκει δὲ καὶ μείζων τις αἰτία γεγονέναι τοῦ τὸν Κικέρωνα δέξασθαι προθύμως τὴν Καίσαρος φιλίαν. ἔτι γὰρ, ὡς ἔοικε, Πομπηίου ζῶντος καὶ Καίσαρος ἔδοξε κατὰ τοὺς ὕπνους ὁ Κικέρων καλεῖν τινα τοὺς τῶν συγκλητικῶν παῖδας εἰς τὸ Καπιτώλιον, ὡς μέλλοντος ἐξ αὐτῶν ἕνα τοῦ Διὸς ἀποδεικνύειν τῆς Ῥώμης ἡγεμόνα· τοὺς δὲ πολίτας ὑπὸ σπουδῆς θέοντας ἵστασθαι περὶ τὸν νεών, καὶ τοὺς παῖδας ἐν ταῖς περιπορφύροις καθέζεσθαι σιωπὴν ἔχοντας, ἐξαίφνης δὲ τῶν θυρῶν ἀνοιχθεισῶν καθ’ ἕνα τῶν παίδων ἀνισταμένων κύκλῳ παρὰ τὸν θεὸν παραπορεύεσθαι, τὸν δὲ πάντας ἐπισκοπεῖν καὶ ἀποπέμπειν ἀχθομένους. ὡς δ’ οὗτος ἦν προσιὼν κατ’ αὐτόν, ἐκτεῖναι τὴν δεξιὰν καὶ εἰπεῖν ὦ Ῥωμαῖοι, πέρας ὑμῖν ἐμφυλίων πολέμων οὗτος ἡγεμὼν γενόμενος. τοιοῦτόν φασιν ἐνύπνιον ἰδόντα τὸν Κικέρωνα τὴν μὲν ἰδέαν τοῦ παιδὸς ἐκμεμάχθαι καὶ κατέχειν ἐναργῶς, αὑτὸν δ’ οὐκ ἐπίστασθαι. μεθ’ ἡμέραν δὲ καταβαίνοντος εἰς τὸ πεδίον τὸ Ἄρειον αὐτοῦ, τοὺς παῖδας ἤδη γεγυμνασμένους ἀπέρχεσθαι, κἀκεῖνον ὀφθῆναι τῷ Κικέρωνι πρῶτον οἷος ὤφθη καθ’ ὕπνον, ἐκπλαγέντα δὲ πυνθάνεσθαι τίνων εἴη γονέων. ἦν δὲ πατρὸς Ὀκταουΐου τῶν οὐκ ἄγαν ἐπιφανῶν, Ἀττίας δὲ μητρός, ἀδελφιδῆς Καίσαρος, ὅθεν Καῖσαρ αὐτῷ παῖδας οὐκ ἔχων ἰδίους τὴν οὐσίαν ἑαυτοῦ καὶ τὸν οἶκον ἐν ταῖς διαθήκαις ἔδωκεν. ἐκ τούτου φασὶ τὸν Κικέρωνα τῷ παιδὶ κατὰ τὰς ἀπαντήσεις ἐντυγχάνειν ἐπιμελῶς, κἀκεῖνον οἰκείως δέχεσθαι τὰς φιλοφροσύνας καὶ γὰρ ἐκ τύχης αὐτῷ γεγονέναι συμβεβήκει Κικέρωνος ὑπατεύοντος.", "st": "Cic. 44.1"}, {"sp": "N", "t": "αὗται μὲν οὖν προφάσεις ἦσαν αἱ λεγόμεναι· τὸ δὲ πρὸς Ἀντώνιον μῖσος Κικέρωνα πρῶτον, εἶτα ἡ φύσις ἥττων οὖσα τιμῆς προσεποίησε Καίσαρι νομίζοντα προσλαμβάνειν τῇ πολιτείᾳ τὴν ἐκείνου δύναμιν. οὕτω γὰρ ὑπῄει τὸ μειράκιον αὐτόν ὥστε καὶ πατέρα προσαγορεύειν. ἐφ’ ᾧ σφόδρα Βροῦτος ἀγανακτῶν ἐν ταῖς πρὸς Ἀττικὸν ἐπιστολαῖς καθήψατο τοῦ Κικέρωνος, ὅτι διὰ φόβον Ἀντωνίου θεραπεύων τόν Καίσαρα δῆλός ἐστιν οὐκ ἐλευθερίαν τῇ πατρίδι πράττων, ἀλλὰ δεσπότην φιλάνθρωπον αὑτῷ μνώμενος. οὐ μὴν ἀλλὰ τόν γε παῖδα Κικέρωνος ὁ Βροῦτος ἐν Ἀθήναις διατρίβοντα παρὰ τοῖς φιλοσόφοις ἀναλαβὼν ἔσχεν ἐφ’ ἡγεμονίαις, καὶ πολλὰ χρώμενος αὐτῷ κατώρθου.", "st": "Cic. 45.1"}, {"sp": "N", "t": "τοῦ δὲ Κικέρωνος ἀκμὴν ἔσχεν ἡ δύναμις ἐν τῇ πόλει τότε μεγίστην, καὶ κρατῶν ὅσον ἐβούλετο τόν μὲν Ἀντώνιον ἐξέκρουσε καὶ κατεστασίασε καὶ πολεμήσοντας αὐτῷ τοὺς δύο ὑπάτους, Ἵρτιον καὶ Πάνσαν, ἐξέπεμψε, Καίσαρι δὲ ῥαβδούχους καὶ στρατηγικὸν κόσμον, ὡς δὴ προπολεμοῦντι τῆς πατρίδος, ἔπεισε ψηφίσασθαι τὴν σύγκλητον. ἐπεὶ δ’ Ἀντώνιος μὲν ἥττητο, τῶν δ’ ὑπάτων ἀμφοτέρων ἀποθανόντων ἐκ τῆς μάχης πρὸς Καίσαρα συνέστησαν αἱ δυνάμεις, δείσασα δ’ ἡ βουλὴ νέον ἄνδρα καὶ τύχῃ λαμπρᾷ κεχρημένον ἐπειρᾶτο τιμαῖς καὶ δωρεαῖς ἀποκαλεῖν αὐτοῦ τὰ στρατεύματα καὶ περισπᾶν τὴν δύναμιν, ὡς μὴ δεομένη τῶν προπολεμούντων Ἀντωνίου πεφευγότος, οὕτως ὁ Καῖσαρ φοβηθεὶς ὑπέπεμπε τῷ Κικέρωνι τοὺς δεομένους καὶ πείθοντας ὑπατείαν μὲν ἀμφοτέροις ὁμοῦ πράττειν, χρῆσθαι δὲ τοῖς πράγμασιν ὅπως αὐτὸς ἔγνωκε, παραλαμβάνοντα τὴν ἀρχήν, καὶ τὸ μειράκιον διοικεῖν ὀνόματος καὶ δόξης γλιχόμενον. ὡμολόγει δὲ Καῖσαρ αὐτὸς ὡς δεδιὼς κατάλυσιν καὶ κινδυνεύων ἔρημος γενέσθαι χρήσαιτο τῇ Κικέρωνος ἐν δέοντι φιλαρχίᾳ, προτρεψάμενος αὐτόν ὑπατείαν μετιέναι συμπράττοντος αὐτοῦ καὶ συναρχαιρεσιάζοντος.", "st": "Cic. 45.4"}, {"sp": "N", "t": "ἐνταῦθα μέντοι μάλιστα Κικέρων ἐπαρθεὶς ὑπὸ νέου γέρων καὶ φενακισθεὶς καὶ συναρχαιρεσιάσας καὶ παρασχὼν αὐτῷ τὴν σύγκλητον εὐθὺς μὲν ὑπὸ τῶν φίλων αἰτίαν εἶχεν, ὀλίγῳ δ’ ὕστερον αὑτὸν ἀπολωλεκὼς ᾔσθετο καὶ τοῦ δήμου προέμενος τὴν ἐλευθερίαν. αὐξηθεὶς γὰρ ὁ νεανίας καὶ τὴν ὑπατείαν λαβών Κικέρωνα μὲν εἴασε χαίρειν, Ἀντωνίῳ δὲ καὶ Λεπίδῳ φίλος γενόμενος καὶ τὴν δύναμιν εἰς ταὐτὸ συνενεγκών, ὥσπερ ἄλλο τι κτῆμα, τὴν ἡγεμονίαν ἐνείματο πρὸς αὐτούς, καὶ κατεγράφησαν ἄνδρες οὓς ἔδει θνῄσκειν, ὑπὲρ διακοσίους. πλείστην δὲ τῶν ἀμφισβητημάτων αὐτοῖς ἔριν ἡ Κικέρωνος προγραφὴ παρέσχεν, Ἀντωνίου μὲν ἀσυμβάτως ἔχοντος εἰ μὴ πρῶτος ἐκεῖνος ἀποθνῄσκοι, Λεπίδου δ’ Ἀντωνίῳ προστιθεμένου, Καίσαρος δὲ πρὸς ἀμφοτέρους ἀντέχοντος. ἐγίνοντο δ’ αἱ σύνοδοι μόνοις ἀπόρρητοι περὶ πόλιν Βονωνίαν ἐφ’ ἡμέρας τρεῖς, καὶ συνῄεσαν εἰς τόπον τινὰ πρόσω τῶν στρατοπέδων ποταμῷ περιρρεόμενον. λέγεται δὲ τὰς πρώτας ἡμέρας διαγωνισάμενος ὑπὲρ τοῦ Κικέρωνος ὁ Καῖσαρ ἐνδοῦναι τῇ τρίτῃ καὶ προέσθαι τὸν ἄνδρα, τὰ δὲ τῆς ἀντιδόσεως οὕτως εἶχεν. ἔδει Κικέρωνος ἐκστῆναι Καίσαρα, Παύλου δὲ τἀδελφοῦ Λέπιδον, Λευκίου δὲ Καίσαρος Ἀντώνιον, ὃς ἦν θεῖος αὐτῷ πρὸς μητρός, οὕτως ἐξέπεσον ὑπὸ θυμοῦ καὶ λύσσης τῶν ἀνθρωπίνων λογισμῶν, μᾶλλον δ’ ἀπέδειξαν ὡς οὐδὲν ἀνθρώπου θηρίον ἐστὶν ἀγριώτερον ἐξουσίαν πάθει προσλαβόντος.", "st": "Cic. 46.1"}, {"sp": "N", "t": "πραττομένων δὲ τούτων ὁ Κικέρων ἦν μὲν ἐν ἀγροῖς ἰδίοις περὶ Τοῦσκλον, ἔχων τὸν ἀδελφὸν μεθ’ αὑτοῦ· πυθόμενοι δὲ τὰς προγραφὰς ἔγνωσαν εἷς Ἄστυρα μεταβῆναι, χωρίον παράλιον τοῦ Κικέρωνος, ἐκεῖθεν δὲ πλεῖν εἷς Μακεδονίαν πρὸς Βροῦτον· ἤδη γὰρ ὑπὲρ αὐτοῦ λόγος ἐφοίτα κρατοῦντος, ἐκομίζοντο δ’ ἐν φορείοις ἀπειρηκότες ὑπὸ λύπης· καὶ κατὰ τὴν ὁδὸν ἐφιστάμενοι καὶ τὰ φορεῖα παραβάλλοντες ἀλλήλοις προσωλοφύροντο. μᾶλλον δ’ ὁ Κόιντος ἠθύμει, καὶ λογισμὸς αὐτὸν εἰσῄει τῆς ἀπορίας· οὐδὲν γὰρ ἔφη λαβεῖν οἴκοθεν, ἀλλὰ καὶ τῷ Κικέρωνι γλίσχρον ἦν ἐφόδιον ἄμεινον οὖν εἶναι τὸν μὲν Κικέρωνα προλαμβάνειν τῇ φυγῇ, αὐτὸν δὲ μεταθεῖν οἴκοθεν συσκευασάμενον. ταῦτ’ ἔδοξε· καὶ περιλαβόντες ἀλλήλους καὶ ἀνακλαυσάμενοι διελύθησαν.", "st": "Cic. 47.1"}, {"sp": "N", "t": "ὁ μὲν οὖν Κόιντος οὐ πολλαῖς ὕστερον ἡμέραις ὑπὸ τῶν οἰκετῶν προδοθεὶς τοῖς ζητοῦσιν ἀνῃρέθη μετὰ τοῦ παιδός. ὁ δὲ Κικέρων εἷς Ἄστυρα κομισθεὶς καὶ πλοῖον εὑρών εὐθὺς ἐνέβη καὶ παρέπλευσεν ἄχρι Κιρκαίου, πνεύματι χρώμενος. ἐκεῖθεν δὲ βουλομένων εὐθὺς αἴρειν τῶν κυβερνητῶν, εἴτε δείσας τὴν θάλασσαν εἴτ’ οὔπω παντάπασι τὴν Καίσαρος ἀπεγνωκὼς πίστιν, ἀπέβη καὶ παρῆλθε πεζῇ σταδίους ἑκατὸν ὡς εἷς Ῥώμην πορευόμενος. αὖθις δ’ ἀλύων καὶ μεταβαλλόμενος κατῄει πρὸς θάλασσαν εἷς Ἄστυρα. κἀκεῖ διενυκτέρευσεν ἐπὶ δεινῶν καὶ ἀπόρων λογισμῶν, ὥστε καὶ παρελθεῖν εἷς τὴν Καίσαρος οἰκίαν διενοήθη κρύφα καὶ σφάξας ἑαυτὸν ἐπὶ τῆς ἑστίας ἀλάστορα προσβαλεῖν. ἀλλὰ καὶ ταύτης αὐτὸν ἀπέκρουσε τῆς ὁδοῦ δέος βασάνων καὶ πολλὰ ταραχώδη καὶ παλίντροπα βουλεύματα τῆς γνώμης μεταλαμβάνων παρέδωκε τοῖς οἰκέταις ἑαυτὸν εἷς Καιήτην κατὰ πλοῦν κομίζειν, ἔχων ἐκεῖ χωρία καὶ καταφυγὴν ὥρᾳ θέρους φιλάνθρωπον, ὅταν ἥδιστον οἱ ἐτησίαι καταπνέωσιν.", "st": "Cic. 47.1b"}, {"sp": "N", "t": "ἔχει δ’ ὁ τόπος καὶ ναὸν Ἀπόλλωνος μικρὸν ὑπὲρ τῆς θαλάττης. ἐντεῦθεν ἀρθέντες ἀθρόοι κόρακες ὑπὸ κλαγγῆς προσεφέροντο τῷ πλοίῳ τοῦ Κικέρωνος ἐπὶ γῆν ἐρεσσομένῳ· καὶ καθίσαντες ἐπὶ τὴν κεραίαν ἑκατέρωθεν οἱ μὲν ἐβόων, οἱ δ’ ἔκοπτον τὰς τῶν μηρυμάτων ἀρχάς, καὶ πᾶσιν ἐδόκει τὸ σημεῖον εἶναι πονηρόν. ἀπέβη δ’ οὖν ὁ Κικέρων, καὶ παρελθὼν εἷς τὴν ἔπαυλιν ὡς ἀναπαυσόμενος κατεκλίθη. τῶν δὲ κοράκων οἱ πολλοὶ μὲν ἐπὶ τῆς θυρίδος διεκάθηντο φθεγγόμενοι θορυβῶδες, εἷς δὲ καταβὰς ἐπὶ τὸ κλινίδιον ἐγκεκαλυμμένου τοῦ Κικέρωνος ἀπῆγε τῷ στόματι κατὰ μικρὸν ἀπὸ τοῦ προσώπου τὸ ἱμάτιον. οἱ δ’ οἰκέται ταῦθ’ ὁρῶντες, καὶ κακίσαντες ἑαυτοὺς εἰ περιμένουσι τοῦ δεσπότου φονευομένου θεαταὶ γενέσθαι, θηρία δ’ αὐτῷ βοηθεῖ καὶ προκήδεται παρ’ ἀξίαν πράττοντος, αὐτοὶ δ’ οὐκ ἀμύνουσι, τὰ μὲν δεόμενοι, τὰ δὲ βίᾳ λαβόντες ἐκόμιζον ἐν τῷ φορείῳ πρὸς τὴν θάλασσαν.", "st": "Cic. 47.8"}, {"sp": "N", "t": "ἐν τούτῳ δ’ οἱ σφαγεῖς ἐπῆλθον, ἑκατοντάρχης Ἑρέννιος καὶ Ποπίλλιος χιλίαρχος, ᾧ πατροκτονίας ποτὲ δίκην φεύγοντι συνεῖπεν ὁ Κικέρων, ἔχοντες ὑπηρέτας. ἐπεὶ δὲ τὰς θύρας κεκλεισμένας εὑρόντες ἐξέκοψαν, οὐ φαινομένου τοῦ Κικέρωνος οὐδὲ τῶν ἔνδον εἰδέναι φασκόντων, λέγεται νεανίσκον τινά τεθραμμένον μὲν ὑπὸ τοῦ Κικέρωνος ἐν γράμμασιν ἐλευθερίοις καὶ μαθήμασιν, ἀπελεύθερον δὲ Κοΐντου τοῦ ἀδελφοῦ, Φιλόλογον τοὔνομα, φράσαι τῷ χιλιάρχῳ τὸ φορεῖον κομιζόμενον διὰ τῶν καταφύτων καὶ συσκίων περιπάτων ἐπὶ τὴν θάλατταν. ὁ μὲν οὖν χιλίαρχος ὀλίγους ἀναλαβὼν μεθ’ ἑαυτοῦ περιέθει πρὸς τὴν ἔξοδον, τοῦ δ’ Ἑρεννίου δρόμῳ φερομένου διὰ τῶν περιπάτων ὁ Κικέρων ᾔσθετο, καὶ τοὺς οἰκέτας ἐκέλευσεν ἐνταῦθα καταθέσθαι τὸ φορεῖον. αὐτός δ’, ὥσπερ εἰώθει, τῇ ἀριστερᾷ χειρὶ τῶν γενείων ἁπτόμενος ἀτενὲς ἐνεώρα τοῖς σφαγεῦσιν, αὐχμοῦ καὶ κόμης ἀνάπλεως καὶ συντετηκὼς ὑπὸ φροντίδων τὸ πρόσωπον, ὥστε τοὺς πλείστους ἐγκαλύψασθαι τοῦ Ἑρεννίου σφάζοντος αὐτόν. ἐσφάγη δὲ τὸν τράχηλον ἐκ τοῦ φορείου προτείνας, ἔτος ἐκεῖνο γεγονὼς ἑξηκοστὸν καί τέταρτον, τὴν δὲ κεφαλὴν ἀπέκοψεν αὐτοῦ καὶ τὰς χεῖρας, Ἀντωνίου κελεύσαντος, αἷς τοὺς Φιλιππικοὺς ἔγραψεν. αὐτός τε γὰρ ὁ Κικέρων τοὺς κατ’ Ἀντωνίου λόγους Φιλιππικοὺς ἐπέγραψε καὶ μέχρι νῦν τὰ βιβλία Φιλιππικοὶ καλοῦνται.", "st": "Cic. 48.1"}, {"sp": "N", "t": "τῶν δ’ ἀκρωτηρίων εἰς Ῥώμην κομισθέντων ἔτυχε μὲν ἀρχαιρεσίας τελῶν ὁ Ἀντώνιος, ἀκούσας δὲ καὶ ἰδὼν ἀνεβόησεν ὡς νῦν αἱ προγραφαὶ τέλος ἔχοιεν. τὴν δὲ κεφαλὴν καὶ τάς χεῖρας ἐκέλευσεν ὑπὲρ τῶν ἐμβόλων ἐπὶ τοῦ βήματος θεῖναι, θέαμα Ῥωμαίοις φρικτόν, οὐ τὸ Κικέρωνος ὁρᾶν πρόσωπον οἰομένοις, ἀλλὰ τῆς Ἀντωνίου ψυχῆς εἰκόνα. πλὴν ἕν γέ τι φρονήσας μέτριον ἐν τούτοις Πομπωνίᾳ τῇ Κοΐντου γυναικὶ τὸν Φιλόλογον παρέδωκεν. ἡ δὲ κυρία γενομένη τοῦ σώματος ἄλλαις τε δειναῖς ἐχρήσατο τιμωρίαις, καὶ τάς σάρκας ἀποτέμνοντα τάς αὐτοῦ κατὰ μικρὸν ὀπτᾶν, εἶτ’ ἐσθίειν ἠνάγκασεν. οὕτω γὰρ ἔνιοι τῶν συγγραφέων ἱστορήκασιν ὁ δ’ αὐτοῦ τοῦ Κικέρωνος ἀπελεύθερος Τίρων τὸ παράπαν οὐδὲ μέμνηται τῆς τοῦ Φιλολόγου προδοσίας.", "st": "Cic. 49.1"}, {"sp": "N", "t": "πυνθάνομαι δὲ Καίσαρα χρόνοις πολλοῖς ὕστερον εἰσελθεῖν πρὸς ἕνα τῶν θυγατριδῶν· τὸν δὲ βιβλίον ἔχοντα Κικέρωνος ἐν ταῖς χερσίν ἐκπλαγέντα τῷ ἱματίῳ περικαλύπτειν ἰδόντα δὲ Καίσαρα λαβεῖν καὶ διελθεῖν ἑστῶτα μέρος πολὺ τοῦ βιβλίου, πάλιν δ’ ἀποδιδόντα τῷ μειρακίῳ φάναι λόγιος ἁνὴρ, ὦ παῖ, λόγιος καὶ φιλόπατρις. ἐπεὶ μέντοι τάχιστα κατεπολέμησεν Ἀντώνιον ὑπατεύων αὐτὸς εἵλετο συνάρχοντα τοῦ Κικέρωνος τὸν υἱόν, ἐφ’ οὗ τάς τ’ εἰκόνας ἡ βουλὴ καθεῖλεν Ἀντωνίου καὶ τάς ἄλλας ἠκύρωσε τιμάς καὶ προσεψηφίσατο μηδενὶ τῶν Ἀντωνίων ὄνομα Μᾶρκον εἶναι, οὕτω τὸ δαιμόνιον εἰς τὸν Κικέρωνος οἶκον ἐπανήνεγκε τὸ τέλος τῆς Ἀντωνίου κολάσεως.", "st": "Cic. 49.5"}, {"sp": "HDR", "t": "Δημοσθένους καὶ Κικέρωνος σύγκρισις"}, {"sp": "N", "t": "ἅ μὲν οὖν ἄξια μνήμης τῶν περὶ Δημοσθένους καὶ Κικέρωνος ἱστορουμένων εἰς τὴν ἡμετέραν ἀφῖκται γνῶσιν, ταῦτ’ ἐστίν, ἀφεικὼς δὲ τὸ συγκρίνειν τὴν ἐν τοῖς λόγοις ἕξιν αὐτῶν, ἐκεῖνό μοι δοκῶ μὴ παρήσειν ἄρρητον, ὅτι Δημοσθένην μὲν εἰς τὸ ῥητορικὸν ἐνέτεινε πᾶν ὅσον εἶχεν ἐκ φύσεως ἢ ἀσκήσεως λόγιον, ὑπερβαλλόμενος ἐναργείᾳ μὲν καὶ δεινότητι τοὺς ἐπὶ τῶν ἀγώνων καὶ τῶν δικῶν συνεξεταζομένους, ὄγκῳ δὲ καὶ μεγαλοπρεπείᾳ τοὺς ἐπιδεικτικούς, ἀκριβείᾳ δὲ καὶ τέχνῃ τοὺς σοφιστάς· Κικέρων δὲ καὶ πολυμαθὴς καὶ ποικίλος τῇ περὶ τοὺς λόγους σπουδῇ γενόμενος συντάξεις μὲν ἰδίας φιλοσόφους ἀπολέλοιπεν οὐκ ὀλίγας εἰς τὸν Ἀκαδημαϊκὸν τρόπον, οὐ μὴν ἀλλὰ καὶ διὰ τῶν πρὸς τὰς δίκας καὶ τοὺς ἀγῶνας γραφομένων λόγων δῆλός ἐστιν ἐμπειρίαν τινὰ γραμμάτων παρεπιδείκνυσθαι βουλόμενος. ἔστι δὲ τις καὶ τοῦ ἤθους ἐν τοῖς λόγοις ἑκατέρου δίοψις. ὁ μὲν γὰρ Δημοσθενικὸς ἔξω παντὸς ὠραϊσμοῦ καὶ παιδιᾶς εἰς δεινότητα καὶ σπουδὴν συνηγμένος οὐκ ἐλλυχνίων ὄδωδεν, ὥσπερ ὁ Πυθέας ἔσκωπτεν, ἀλλ’ ὐδροποσίας καὶ φροντίδων καὶ τῆς λεγομένης πικρίας τοῦ τρόπου καὶ στυγνότητος,", "st": "Comp. Dem.–Cic. 1.1"}, {"sp": "N", "t": "Κικέρων δὲ πολλαχοῦ τῷ σκωπτικῷ πρὸς τὸ βωμολόχον ἐκφερόμενος καὶ πράγματα σπουδῆς ἄξια γέλωτι καὶ παιδιᾷ κατειρωνευόμενος ἐν ταῖς δίκαις εἰς τὸ χρειῶδες ἠφείδει τοῦ πρέποντος, ὥσπερ ἐν τῇ Καιλίου συνηγορίᾳ μηδὲν ἄτοπον ποιεῖν αὐτὸν ἐν τοσαύτῃ τρυφῇ καὶ πολυτελείᾳ ταῖς ἡδοναῖς χρώμενον· τὸ γὰρ ὧν ἔξεστι μὴ μετέχειν, μανικὸν εἶναι, καὶ ταῦτα ἐν ἡδονῇ τὸ εὔδαιμον τῶν ἐπιφανεστάτων φιλοσόφων τιθεμένων. λέγεται δὲ Κάτωνος Μουρήναν διώκοντος ὑπατεύων ἀπολογεῖσθαι καὶ πολλὰ διὰ τὸν Κάτωνα κωμῳδεῖν τὴν Στωικὴν αἵρεσιν ἐπὶ ταῖς ἀτοπίαις τῶν παραδόξων λεγομένων δογμάτων γέλωτος δὲ λαμπροῦ κατιόντος ἐκ τῶν περιεστώτων πρὸς τοὺς δικαστάς, ἡσυχῆ διαμειδιάσας ὁ Κάτων πρὸς τοὺς καθημένους εἰπεῖν ὡς γελοῖον, ὦ ἄνδρες, ἔχομεν ὕπατον. δοκεῖ δὲ καὶ γέλωτος οἰκεῖος ὁ Κικέρων γεγονέναι καὶ φιλοσκώπτης, τό τε πρόσωπον αὐτοῦ μειδίαμα καὶ γαλήνην παρεῖχε, τῷ δὲ Δημοσθένους ἀεί τις ἐπῆν σπουδή, καὶ τὸ πεφροντικὸς τοῦτο καὶ σύννουν οὐ ῥᾳδίως ἀπέλειπεν ὅθεν καὶ δύσκολον αὐτὸν οἱ ἐχθροὶ καὶ δύστροπον, ὡς αὐτός φησιν, ἀπεκάλουν.", "st": "Comp. Dem.–Cic. 1.4"}, {"sp": "N", "t": "ἔτι τοίνυν ἐν τοῖς συγγράμμασι κατιδεῖν ἔστι τὸν μὲν ἐμμελῶς καὶ ἀνεπαχθῶς τῶν εἰς αὑτὸν ἁπτόμενον ἐγκωμίων, ὅτε τούτου δεήσαι πρὸς ἕτερόν τι μεῖζον, τἆλλα δ’ εὐλαβῆ καὶ μέτριον· ἡ δὲ Κικέρωνος ἐν τοῖς λόγοις ἀμετρία τῆς περιαυτολογίας ἀκρασίαν τινὰ κατηγόρει πρὸς δόξαν, βοῶντος ὡς τὰ ὅπλα ἔδει τῇ τηβέννῳ καὶ τῇ γλώττῃ τὴν θριαμβικὴν ὑπείκειν δάφνην. τελευτῶν δ’ οὐ τὰ ἔργα καὶ τὰς πράξεις μόνον, ἀλλὰ καὶ τοὺς λόγους ἐπαινεῖ τοὺς εἰρημένους ὑφ’ αὑτοῦ καὶ γεγραμμένους, ὥσπερ Ἰσοκράτει καὶ Ἀναξιμένει τοῖς σοφισταῖς διαμειρακιευόμενος, οὐ τὸν Ῥωμαίων δῆμον ἄγειν ἀξιῶν καὶ ὀρθοῦν,", "st": "Comp. Dem.–Cic. 2.1"}, {"sp": "N", "t": "βριθύν, ὁπλιτοπάλαν, δάϊον ἀντιπάλοις.", "st": "Comp. Dem.–Cic. 2.1b"}, {"sp": "N", "t": "ἰσχύειν μὲν γὰρ διὰ λόγου τὸν πολιτευόμενον ἀναγκαῖον, ἀγαπᾶν δ’ ἀγεννὲς καὶ λιχνεύειν τὴν ἀπὸ τοῦ λόγου δόξαν. ὅθεν ἐμβριθέστερος ταύτῃ καὶ μεγαλοπρεπέστερος ὁ Δημοσθένης, τὴν μὲν αὑτοῦ δύναμιν ἐμπειρίαν τινὰ πολλῆς δεομένην τῆς παρὰ τῶν ἀκροωμένων εὐνοίας ἀποφαινόμενος, ἀνελευθέρους δὲ καὶ βαναύσους, ὥσπερ εἰσί, τοὺς ἐπὶ τούτῳ φυσωμένους ἡγούμενος.", "st": "Comp. Dem.–Cic. 2.3"}, {"sp": "N", "t": "ἡ μὲν οὖν ἐν τῷ δημηγορεῖν καὶ πολιτεύεσθαι δύναμις ὁμαλῶς ἀμφοτέροις ὑπῆρξεν, ὥστε καὶ τοὺς τῶν ὅπλων καὶ στρατοπέδων κυρίους δεῖσθαι, Δημοσθένους μὲν Χάρητα καὶ Διοπείθην καὶ Λεωσθένην, Κικέρωνος δὲ Πομπήϊον καὶ Καίσαρα τὸν νέον, ὡς αὐτὸς ὁ Καῖσαρ ἐν τοῖς πρὸς Ἀγρίππαν καὶ Μαικήναν ὑπομνήμασιν εἴρηκεν. ὃ δὲ δοκεῖ μάλιστα καὶ λέγεται τρόπον ἀνδρὸς ἐπιδεικνύναι καὶ βασανίζειν, ἐξουσία καὶ ἀρχὴ πᾶν πάθος κινοῦσα καὶ πᾶσαν ἀποκαλύπτουσα κακίαν, Δημοσθένει μὲν οὐχ ὑπῆρξεν, οὐδ’ ἔδωκε τοιαύτην διάπειραν ἑαυτοῦ, μηδεμίαν ἀρχὴν τῶν ἐπιφανῶν ἄρξας, ὃς οὐδὲ τῆς ὑφ’ αὑτοῦ συντεταγμένης ἐπὶ Φίλιππον ἐστρατήγησε δυνάμεως· Κικέρων δὲ ταμίας εἰς Σικελίαν καὶ ἀνθύπατος εἰς Κιλικίαν καὶ Καππαδοκίαν ἀποσταλείς, ἐν ᾧ καιρῷ τῆς φιλοπλουτίας ἀκμαζούσης, καὶ τῶν πεμπομένων στρατηγῶν καὶ ἡγεμόνων, ὡς τοῦ κλέπτειν ἀγεννοῦς ὄντος, ἐπὶ τὸ ἁρπάζειν τρεπομένων, οὐ τὸ λαμβάνειν ἐδόκει δεινόν, ἀλλ’ ὁ μετρίως τοῦτο ποιῶν ἠγαπᾶτο, πολλὴν μὲν ἐπίδειξιν ὑπεροψίας χρημάτων ἐποιήσατο, πολλὴν δὲ φιλανθρωπίας καὶ χρηστότητος. ἐν αὐτῇ δὲ τῇ Ῥώμῃ λόγῳ μὲν ἀποδειχθεὶς ὕπατος, ἐξουσίαν δὲ λαβὼν αὐτοκράτορος καὶ δικτάτορος ἐπὶ τοὺς περὶ Κατιλίναν, ἐμαρτύρησεν ἅμα τῷ Πλάτωνι μαντευομένῳ παῦλαν ἕξειν κακῶν τὰς πόλεις, ὅταν εἰς ταὐτὸ δύναμίς τε μεγάλη καὶ φρόνησις ἔκ τινος τύχης χρηστῆς ἀπαντήσῃ μετὰ δικαιοσύνης.", "st": "Comp. Dem.–Cic. 3.1"}, {"sp": "N", "t": "χρηματίσασθαι τοίνυν ἀπὸ τοῦ λόγου Δημοσθένης μὲν ἐπιψόγως λέγεται, λογογραφῶν κρύφα τοῖς περὶ Φορμίωνα καὶ Ἀπολλόδωρον ἀντιδίκοις, καὶ διαβληθεὶς μὲν ἐπὶ τοῖς βασιλικοῖς χρήμασιν, ὀφλὼν δὲ τῶν Ἁρπαλείων. εἰ δὲ ταῦτα τοὺς γράφοντας οὐκ ὀλίγοι δ’ εἰσὶν οὗτοι ψεύδεσθαι φαίημεν, ἀλλ’ ὅτι γε πρὸς δωρεὰς βασιλέων σὺν χάριτι καὶ τιμῇ διδομένας ἀντιβλέψαι Δημοσθένης οὐκ ἂν ἐτόλμησεν, οὐδ’ ἦν τοῦτο ἔργον ἀνθρώπου δανείζοντος ἐπὶ ναυτικοῖς, ἀμήχανον ἀντειπεῖν· περὶ δὲ Κικέρωνος, ὅτι καὶ Σικελιωτῶν ἀγορανομοῦντι καὶ βασιλέως τοῦ Καππαδοκῶν ἀνθυπατεύοντι καὶ τῶν ἐν Ῥώμῃ φίλων, ὅτ’ ἐξέπιπτε τῆς πόλεως, δωρουμένων πολλὰ καὶ δεομένων λαβεῖν ἀντέσχεν, εἴρηται.", "st": "Comp. Dem.–Cic. 3.5"}, {"sp": "N", "t": "καὶ μὴν ἥ γε φυγὴ τῷ μὲν αἰσχρὰ κλοπῆς ἁλόντι συνέπεσε, τῷ δὲ κάλλιστον ἔργον ἀνθρώπους ἀλιτηρίους ἐκκόψαντι τῆς πατρίδος, διὸ τοῦ μὲν οὐδεὶς λόγος ἐκπίπτοντος, ἐφ’ ᾧ δ’ ἡ σύγκλητος ἐσθῆτά τε διήλλαξε καὶ πένθος ἔσχε καὶ γνώμην ὑπὲρ οὐδενὸς εἰπεῖν ἐπείσθη πρότερον ἢ Κικέρωνι κάθοδον ψηφίσασθαι. τὴν μέντοι φυγὴν ἀργῶς ὁ Κικέρων διήνεγκεν ἐν Μακεδονίᾳ καθήμενος, τῷ δὲ Δημοσθένει καὶ ἡ φυγὴ μέγα μέρος τῆς πολιτείας γέγονε. συναγωνιζόμενος γάρ, ὥσπερ εἴρηται, τοῖς Ἕλλησι καὶ τοὺς Μακεδόνων πρέσβεις ἐξελαύνων ἐπήρχετο τὰς πόλεις, πολὺ βελτίων Θεμιστοκλέους καὶ Ἀλκιβιάδου παρὰ τὰς αὐτὰς τύχας φανεὶς πολίτης· καὶ μέντοι κατελθὼν αὖθις ἑαυτὸν ἐπέδωκεν εἰς τὴν αὐτὴν ταύτην πολιτείαν, καὶ διετέλει πολεμῶν πρὸς Ἀντίπατρον καὶ Μακεδόνας. Κικέρωνα δ’ ὠνείδισεν ἐν τῇ βουλῇ Λαίλιος αἰτουμένου Καίσαρος ὑπατείαν μετιέναι παρὰ νόμον, οὔπω γενειῶντος, σιωπῇ καθήμενον. ἔγραφε δὲ καὶ Βροῦτος ἐγκαλῶν ὡν μείζονα καὶ βαρυτέραν πεπαιδοτριβηκότι τυραννίδα τῆς ὑφ’ αὑτοῦ καταλυθείσης.", "st": "Comp. Dem.–Cic. 4.1"}, {"sp": "N", "t": "ἐπὶ πᾶσι δὲ τῆς τελευτῆς τὸν μὲν οἰκτείραι τις ἄν, ἄνδρα πρεσβύτην δι’ ἀγέννειαν ὑπὸ οἰκετῶν ἄνω καὶ κάτω περιφερόμενον καὶ περιφεύγοντα τὸν θάνατον καὶ ἀποκρυπτόμενον τοὺς οὐ πολὺ πρὸ τῆς φύσεως ἥκοντας ἐπ’ αὐτόν, εἶτ’ ἀποσφαγέντα· τοῦ δ’, εἰ καὶ μικρὰ πρὸς τὴν ἱκετείαν ἐνέδωκεν, ἀγαστὴ μὲν ἡ παρασκευὴ τοῦ φαρμάκου καὶ τήρησις, ἀγαστὴ δ’ ἡ χρῆσις, ὅτι τοῦ θεοῦ μὴ παρασχόντος αὐτῷ τὴν ἀσυλίαν, ὥσπερ ἐπὶ μείζονα βωμὸν καταφυγών, ἐκ τῶν ὅπλων καὶ τῶν δορυφόρων λαβὼν ἑαυτὸν ᾤχετο, τῆς Ἀντιπάτρου καταγελάσας ὠμότητος.", "st": "Comp. Dem.–Cic. 5.1"}, {"sp": "HDR", "t": "Δημήτριος"}, {"sp": "N", "t": "οἱ πρῶτοι τὰς τέχνας ἐοικέναι ταῖς αἰσθήσεσιν ὑπολαβόντες οὐχ ἥκιστά μοι δοκοῦσι τὴν περὶ τὰς κρίσεις αὐτῶν κατανοῆσαι δύναμιν, ᾗ τῶν ἐναντίων ὁμοίως ἐν ἑκατέρῳ γένει πεφύκαμεν ἀντιλαμβάνεσθαι. τοῦτο γὰρ αὐταῖς κοινόν ἐστι· τῇ δὲ πρὸς τὰ τέλη τῶν κρινομένων ἀναφορᾷ διαλλάττουσιν. ἡ μὲν γὰρ αἴσθησις οὐδέν τι μᾶλλον ἐπὶ λευκῶν ἢ μελάνων διαγνώσει γέγονεν, οὐδὲ γλυκέων ἢ πικρῶν, οὐδὲ μαλακῶν καὶ εἰκόντων ἢ σκληρῶν καὶ ἀντιτύπων, ἀλλ’ ἔργον αὐτῆς ἑκάστοις ἐντυγχάνουσαν ὑπὸ πάντων τε κινεῖσθαι καὶ κινουμένην πρὸς τὸ φρονοῦν ἀναφέρειν ὡς πέπονθεν. αἱ δὲ τέχναι μετὰ λόγου συνεστῶσαι πρὸς αἵρεσιν καὶ λῆψιν οἰκείου τινός, φυγὴν δὲ καὶ διάκρουσιν ἀλλοτρίου, τὰ μὲν ἀφ’ αὑτῶν προηγουμένως, τὰ δὲ ὑπὲρ τοῦ φυλάξασθαι κατὰ συμβεβηκὸς ἐπιθεωροῦσι· καὶ γὰρ ἰατρικῇ τὸ νοσερὸν καὶ ἁρμονικῇ τὸ ἐκμελές, ὅπως ἔχει, σκοπεῖν συμβέβηκε πρὸς τὴν τῶν ἐναντίων ἀπεργασίαν, αἵ τε πασῶν τελειόταται τεχνῶν, σωφροσύνη καὶ δικαιοσύνη καὶ φρόνησις, οὐ καλῶν μόνον καὶ δικαίων καὶ ὠφελίμων, ἀλλὰ καὶ βλαβερῶν καὶ αἰσχρῶν καὶ ἀδίκων κρίσεις οὖσαι, τὴν ἀπειρίᾳ τῶν κακῶν καλλωπιζομένην ἀκακίαν οὐκ ἐπαινοῦσιν, ἀλλ’ ἀβελτερίαν ἡγοῦνται καὶ ἄγνοιαν ὧν μάλιστα γινώσκειν προσήκει τοὺς ὀρθῶς βιωσομένους. οἱ μὲν οὖν παλαιοὶ Σπαρτιᾶται τοὺς εἵλωτας ἐν ταῖς ἑορταῖς πολὺν ἀναγκάζοντες πίνειν ἄκρατον εἰσῆγον εἰς τὰ συμπόσια, τοῖς νέοις οἷόν ἐστι τὸ μεθύειν ἐπιδεικνύντες· ἡμεῖς δὲ τὴν μὲν ἐκ διαστροφῆς ἑτέρων ἐπανόρθωσιν οὐ πάνυ φιλάνθρωπον οὐδὲ πολιτικὴν ἡγούμεθα, τῶν δὲ κεχρημένων ἀσκεπτότερον αὑτοῖς καὶ γεγονότων ἐν ἐξουσίαις καὶ πράγμασι μεγάλοις ἐπιφανῶν εἰς κακίαν, οὐ χεῖρον ἴσως ἐστὶ συζυγίαν μίαν ἢ δύο παρεμβαλεῖν εἰς τὰ παραδείγματα τῶν βίων, οὐκ ἐφ’ ἡδονῇ, μὰ Δία, καὶ διαγωγῇ τῶν ἐντυγχανόντων ποικίλλοντας τὴν γραφήν, ἀλλ’ ὥσπερ Ἰσμηνίας ὁ Θηβαῖος ἐπιδεικνύμενος τοῖς μαθηταῖς καὶ τοὺς εὖ καὶ τοὺς κακῶς αὐλοῦντας εἰώθει λέγειν, οὕτως αὐλεῖν δεῖ, καὶ πάλιν, οὕτως αὐλεῖν οὐ δεῖ, ὁ δ’ Ἀντιγενίδας καὶ ἥδιον ᾤετο τῶν ἀγαθῶν ἀκροᾶσθαι τοὺς νέους αὐλητῶν ἐὰν καὶ τῶν φαύλων πεῖραν λαμβάνωσιν, οὕτω μοι δοκοῦμεν καὶ ἡμεῖς προθυμότεροι τῶν βελτιόνων ἔσεσθαι καὶ θεαταὶ καὶ μιμηταὶ βίων εἰ μηδὲ τῶν φαύλων καὶ ψεγομένων ἀνιστορήτως ἔχοιμεν.", "st": "Demetr. 1.1"}, {"sp": "N", "t": "Περιέξει δὴ τοῦτο τὸ βιβλίον τὸν Δημητρίου τοῦ Πολιορκητοῦ βίον καὶ Ἀντωνίου τοῦ αὐτοκράτορος, ἀνδρῶν μάλιστα δὴ τῷ Πλάτωνι μαρτυρησάντων ὅτι καὶ κακίας μεγάλας, ὥσπερ ἀρετάς, αἱ μεγάλαι φύσεις ἐκφέρουσι. γενόμενοι δ’ ὁμοίως ἐρωτικοί, ποτικοί, στρατιωτικοί, μεγαλόδωροι, πολυτελεῖς, ὑβρισταί, καὶ τὰς κατὰ τύχην ὁμοιότητας ἀκολούθους ἔσχον. οὐ γὰρ μόνον ἐν τῷ λοιπῷ βίῳ μεγάλα μὲν κατορθοῦντες, μεγάλα δὲ σφαλλόμενοι, πλείστων δὲ ἐπικρατοῦντες, πλεῖστα δὲ ἀποβάλλοντες, ἀπροσδοκήτως δὲ πταίοντες, ἀνελπίστως δὲ πάλιν ἀναφέροντες διετέλεσαν, ἀλλὰ καὶ κατέστρεψαν, ὁ μὲν ἁλοὺς ὑπὸ τῶν πολεμίων, ὁ δὲ ἔγγιστα τοῦ παθεῖν τοῦτο γενόμενος.", "st": "Demetr. 1.7"}, {"sp": "N", "t": "Ἀντιγόνῳ τοίνυν δυεῖν υἱῶν ἐκ Στρατονίκης τῆς Κορράγου γενομένων, τὸν μὲν ἐπὶ τἀδελφῷ Δημήτριον, τὸν δ’ ἐπὶ τῷ πατρὶ Φίλιππον ὠνόμασεν. οὗτός ἐστιν ὁ τῶν πλείστων λόγος. ἔνιοι δὲ τὸν Δημήτριον οὐχ υἱόν, ἀλλ’ ἀδελφιδοῦν γενέσθαι τοῦ Ἀντιγόνου λέγουσιν· ἐπὶ νηπίῳ γὰρ αὐτῷ παντάπασι τοῦ πατρὸς τελευτήσαντος, εἶτα τῆς μητρὸς εὐθὺς τῷ Ἀντιγόνῳ γαμηθείσης, υἱὸν ἐκείνου νομισθῆναι. τὸν μὲν οὖν Φίλιππον οὐ πολλοῖς ἔτεσι τοῦ Δημητρίου νεώτερον ὄντα συνέβη τελευτῆσαι· Δημήτριος δὲ μεγέθει μὲν ἦν τοῦ πατρὸς ἐλάττων, καίπερ ὢν μέγας, ἰδέᾳ δὲ καὶ κάλλει προσώπου θαυμαστὸς καὶ περιττός, ὥστε τῶν πλαττόντων καὶ γραφόντων μηθένα τῆς ὁμοιότητος ἐφικέσθαι. τὸ γὰρ αὐτὸ χάριν καὶ βάρος καὶ φόβον καὶ ὥραν εἶχε, καὶ συνεκέκρατο τῷ νεαρῷ καὶ ἰταμῷ δυσμίμητος ἡρωϊκή τις ἐπιφάνεια καὶ βασιλικὴ σεμνότης. οὕτω δέ πως καὶ τὸ ἦθος ἐπεφύκει πρὸς ἔκπληξιν ἀνθρώπων ἅμα καὶ χάριν. ἥδιστος γὰρ ὢν συγγενέσθαι, σχολάζων τε περὶ πότους καὶ τρυφὰς καὶ διαίτας ἁβροβιώτατος βασιλέων, ἐνεργότατον αὖ πάλιν καὶ σφοδρότατον τὸ περὶ τὰς πράξεις ἐνδελεχὲς εἶχε καὶ δραστήριον· ᾗ καὶ μάλιστα τῶν θεῶν ἐζήλου τὸν Διόνυσον, ὡς πολέμῳ τε χρῆσθαι δεινότατον, εἰρήνην τε αὖθις ἐκ πολέμου τρέψαι πρὸς εὐφροσύνην καὶ χάριν ἐμμελέστατον.", "st": "Demetr. 2.1"}, {"sp": "N", "t": "ἦν μὲν οὖν καὶ φιλοπάτωρ διαφερόντως· τῇ δὲ περὶ τὴν μητέρα σπουδῇ καὶ τὸν πατέρα τιμῶν ἐφαίνετο δι’ εὔνοιαν ἀληθινὴν μᾶλλον ἢ θεραπείαν τῆς δυνάμεως. καί ποτε πρεσβείᾳ τινὶ τοῦ Ἀντιγόνου σχολάζοντος ἀπὸ θήρας ὁ Δημήτριος ἐπέστη· καὶ προσελθὼν τῷ πατρὶ καὶ φιλήσας, ὥσπερ εἶχε τὰς βολίδας, ἐκάθισε παρ’ αὐτόν. ὁ δὲ Ἀντίγονος ἀπιόντας ἤδη τοὺς πρέσβεις ἔχοντας τὰς ἀποκρίσεις μεγάλῃ φωνῇ προσαγορεύσας, καὶ τοῦτο, εἶπεν, ὦ ἄνδρες, ἀπαγγέλλετε περὶ ἡμῶν, ὅτι πρὸς ἀλλήλους οὕτως ἔχομεν, ὡς ἰσχύν τινα πραγμάτων βασιλικῶν καὶ δυνάμεως ἐπίδειξιν οὖσαν τὴν πρὸς υἱὸν ὁμόνοιαν καὶ πίστιν. οὕτως ἄρα πάντη δυσκοινώνητον ἡ ἀρχή, καὶ μεστὸν ἀπιστίας καὶ δυσνοίας, ὥστε ἀγάλλεσθαι τὸν μέγιστον τῶν Ἀλεξάνδρου διαδόχων καὶ πρεσβύτατον ὅτι μὴ φοβεῖται τὸν υἱόν, ἀλλὰ προσίεται τὴν λόγχην ἔχοντα τοῦ σώματος πλησίον. οὐ μὴν ἀλλὰ καὶ μόνος, ὡς εἰπεῖν, ὁ οἶκος οὗτος ἐπὶ πλείστας διαδοχὰς τῶν τοιούτων κακῶν ἐκαθάρευσε, μᾶλλον δὲ εἷς μόνος τῶν ἀπ’ Ἀντιγόνου Φίλιππος ἀνεῖλεν υἱόν. αἱ δὲ ἄλλαι σχεδὸν ἅπασαι διαδοχαὶ πολλῶν μὲν ἔχουσι παίδων, πολλῶν δὲ μητέρων φόνους καὶ γυναικῶν· τὸ μὲν γὰρ ἀδελφοὺς ἀναιρεῖν, ὥσπερ οἱ γεωμέτραι τὰ αἰτήματα λαμβάνουσιν, οὕτω συνεχωρεῖτο κοινόν τι νομιζόμενον αἴτημα καὶ βασιλικὸν ὑπὲρ ἀσφαλείας.", "st": "Demetr. 3.1"}, {"sp": "N", "t": "τοῦ μέντοι καὶ φιλάνθρωπον φύσει καὶ φιλέταιρον γεγονέναι τὸν Δημήτριον ἐν ἀρχῇ παράδειγμα τοιοῦτόν ἐστιν εἰπεῖν. Μιθριδάτης ὁ Ἀριοβαρζάνου παῖς ἑταῖρος ἦν αὐτοῦ καὶ καθ’ ἡλικίαν συνήθης, ἐθεράπευε δὲ Ἀντίγονον, οὔτε ὢν οὔτε δοκῶν πονηρός, ἐκ δὲ ἐνυπνίου τινὸς ὑποψίαν Ἀντιγόνῳ παρέσχεν. ἐδόκει γὰρ μέγα καὶ καλὸν πεδίον ἐπιὼν ὁ Ἀντίγονος ψῆγμά τι χρυσίου κατασπείρειν· ἐξ αὐτοῦ δὲ πρῶτον μὲν ὑποφύεσθαι θέρος χρυσοῦν, ὀλίγῳ δ’ ὕστερον ἐπανελθὼν ἰδεῖν οὐδὲν ἀλλ’ ἢ τετμημένην καλάμην. λυπούμενος δὲ καὶ περιπαθῶν ἀκοῦσαί τινων λεγόντων ὡς ἄρα Μιθριδάτης εἰς Πόντον Εὔξεινον οἴχεται, τὸ χρυσοῦν θέρος ἐξαμησάμενος. ἐκ τούτου διαταραχθεὶς καὶ τὸν υἱὸν ὁρκώσας σιωπήσειν, ἔφρασε τὴν ὄψιν αὐτῷ, καὶ ὅτι πάντως τὸν ἄνθρωπον ἐκποδὼν ποιεῖσθαι καὶ διαφθείρειν ἔγνωκεν. ἀκούσας δὲ ὁ Δημήτριος ἠχθέσθη σφόδρα, καὶ τοῦ νεανίσκου, καθάπερ εἰώθει, γενομένου παρ’ αὐτῷ καὶ συνόντος ἐπὶ σχολῆς, φθέγξασθαι μὲν οὐκ ἐτόλμησεν οὐδὲ τῇ φωνῇ κατειπεῖν διὰ τὸν ὅρκον, ὑπαγαγὼν δὲ κατὰ μικρὸν ἀπὸ τῶν φίλων, ὡς ἐγεγόνεσαν μόνοι καθ’ αὑτούς, τῷ στύρακι τῆς λόγχης κατέγραφεν εἰς τὴν γῆν ὁρῶντος αὐτοῦ, φεῦγε, Μιθριδάτα. συνεὶς δὲ ἐκεῖνος ἀπέδρα νυκτὸς εἰς Καππαδοκίαν. καὶ ταχὺ τὴν Ἀντιγόνῳ γενομένην ὄψιν ὕπαρ αὐτῷ συνετέλει τὸ χρεών. πολλῆς γὰρ καὶ ἀγαθῆς ἐκράτησε χώρας, καὶ τὸ τῶν Ποντικῶν βασιλέων γένος ὀγδόῃ που διαδοχῇ παυσάμενον ὑπὸ Ῥωμαίων ἐκεῖνος παρέσχε. ταῦτα μὲν οὖν εὐφυΐας δείγματα τοῦ Δημητρίου πρὸς ἐπιείκειαν καὶ δικαιοσύνην.", "st": "Demetr. 4.1"}, {"sp": "N", "t": "ἐπεὶ δέ, ὥσπερ ἐν τοῖς Ἐμπεδοκλέους στοιχείοις διὰ τὸ νεῖκος καὶ τὴν φιλίαν ἔνεστι διαφορὰ πρὸς ἄλληλα καὶ πόλεμος, μᾶλλον δὲ τοῖς ἀλλήλων ἁπτομένοις καὶ πελάζουσιν, οὕτω τὸν πᾶσι τοῖς Ἀλεξάνδρου διαδόχοις πρὸς ἀλλήλους ὄντα συνεχῆ πόλεμον αἱ τῶν πραγμάτων καὶ τῶν τόπων συνάφειαι πρὸς ἐνίους ἐποίουν ἐπιφανέστερον καὶ μᾶλλον ἐξέκᾳον, ὥσπερ Ἀντιγόνῳ τότε πρὸς Πτολεμαῖον, αὐτὸς μὲν Ἀντίγονος ἐν Φρυγίᾳ διέτριβε, Πτολεμαῖον δ’ ἀκούων ἐκ Κύπρου διαβάντα πορθεῖν Συρίαν καὶ τὰς πόλεις ἀπάγειν καὶ βιάζεσθαι, κατέπεμψε τὸν υἱὸν Δημήτριον, δύο καὶ εἴκοσιν ἐτῶν ὄντα καὶ στρατείας τότε πρῶτον αὐτοτελῶς ἐπὶ πράγμασι μεγάλοις ἁπτόμενον. οἷα δὲ νέος καὶ ἄπειρος ἀνδρὶ συμπεσὼν ἐκ τῆς Ἀλεξάνδρου παλαίστρας ἠθληκότι πολλοὺς καὶ μεγάλους καθ’ αὑτὸν ἀγῶνας, ἐσφάλη περὶ πόλιν Γάζαν ἡττηθείς, ὀκτακισχιλίων ἁλόντων καὶ πεντακισχιλίων ἀποθανόντων. ἀπέβαλε δὲ καὶ σκηνὴν καὶ χρήματα καὶ ὅλως σύμπασαν τὴν περὶ τὸ σῶμα θεραπείαν. ἀλλὰ ταῦτα μὲν αὐτῷ Πτολεμαῖος ἀπέπεμψε μετὰ τῶν φίλων, εὐγνώμονα καὶ φιλάνθρωπον ἀνειπὼν λόγον, ὡς οὐ περὶ πάντων ἅμα, περὶ δόξης δὲ καὶ ἀρχῆς πολεμητέον ἐστὶν αὐτοῖς. Δημήτριος δὲ δεξάμενος εὔξατο τοῖς θεοῖς μὴ πολὺν χρόνον ὀφειλέτην γενέσθαι Πτολεμαίῳ χάριτος, ἀλλὰ ταχέως ἀμείψασθαι διὰ τῶν ὁμοίων. καὶ πάθος οὐ μειρακίου παθὼν ἐν ἀρχῇ πράξεως ἀνατραπέντος, ἀλλ’ ἐμβριθοῦς στρατηγοῦ κεχρημένου πραγμάτων μεταβολαῖς, ἀνδρῶν τε συλλογῆς καὶ κατασκευῆς ὅπλων ἐπεμελεῖτο καὶ τὰς πόλεις διὰ χειρὸς εἶχε καὶ τοὺς ἀθροιζομένους ἐγύμναζεν.", "st": "Demetr. 5.1"}, {"sp": "N", "t": "Ἀντίγονος δὲ τὴν μάχην πυθόμενος Πτολεμαῖον μὲν ἀγενείους νενικηκότα ἔφη νῦν αὖθις διαγωνιεῖσθαι πρὸς ἄνδρας, τοῦ δὲ υἱοῦ τὸ φρόνημα καθελεῖν καὶ κολοῦσαι μὴ βουλόμενος οὐκ ἐνέστη πάλιν αἰτουμένῳ μάχεσθαι καθ’ αὑτόν, ἀλλ’ ἀφῆκε. καὶ μετ’ οὐ πολὺν χρόνον ἀφῖκτο Κίλλης, Πτολεμαίου στρατηγός, μετὰ λαμπρᾶς δυνάμεως, ὡς ἐξελάσων Συρίας Δημήτριον ἁπάσης, τῷ προηττῆσθαι καταφρονούμενον. ὁ δ’ ἐξαίφνης ἐπιπεσὼν οὐ προαισθομένῳ καὶ φοβήσας ἔλαβεν αὐτῷ στρατηγῷ τὸ στρατόπεδον· καὶ στρατιώτας μὲν ἑπτακισχιλίους ζῶντας εἷλε, χρημάτων δὲ παμπόλλων ἐκυρίευσεν. ἔχαιρε δὲ νικήσας οὐχ οἷς ἕξειν, ἀλλ’ οἷς ἀποδώσειν ἔμελλε, καὶ τῆς νίκης οὐ τὸν πλοῦτον οὕτως οὐδὲ τὴν δόξαν, ὡς τὴν διάλυσιν τοῦ φιλανθρωπεύματος ἐκείνου καὶ τὴν χάριν ἠγάπησεν. οὐ μὴν αὐτογνωμόνως ταῦτα ἔπραξεν, ἀλλ’ ἔγραψε τῷ πατρί. δόντος δ’ ἐκείνου καὶ κελεύσαντος ὃν βούλεται πᾶσι χρήσασθαι τρόπον, αὐτόν τε τὸν Κίλλην καὶ φίλους αὐτοῦ δωρησάμενος ἀφθόνως ἀπέπεμψε. τοῦτο τὸ πάθος Συρίας ἐξήλασε Πτολεμαῖον, Ἀντίγονον δὲ κατήγαγεν ἐκ Κελαινῶν χαίροντα τῇ νίκῃ καὶ ποθοῦντα θεάσασθαι τὸν υἱόν.", "st": "Demetr. 6.1"}, {"sp": "N", "t": "ἐκ τούτου δὲ τῶν Ἀράβων τοὺς καλουμένους Ναβαταίους ὑπαγαγέσθαι πεμφθεὶς ὁ Δημήτριος ἐκινδύνευσε μὲν εἰς τόπους ἀνύδρους ἐμπεσών, τῷ δὲ μὴ διαταραχθῆναι μηδ’ ἐκπλαγῆναι καταπληξάμενος τοὺς βαρβάρους, λείαν τε λαβὼν πολλὴν καὶ καμήλους ἑπτακοσίας παρ’ αὐτῶν ἀνεχώρησεν.", "st": "Demetr. 7.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Σέλευκος, ἐκπεσὼν μὲν ὑπὸ Ἀντιγόνου τῆς Βαβυλωνίας πρότερον, ὕστερον δὲ ἀναλαβὼν τὴν ἀρχὴν δι’ αὑτοῦ καὶ κρατῶν, ἀνέβη μετὰ δυνάμεως, τὰ συνοροῦντα τοῖς Ἰνδοῖς ἔθνη καὶ τὰς περὶ Καύκασον ἐπαρχίας προσαξόμενος, ἐλπίζων Δημήτριος ἔρημον εὑρήσειν τὴν Μεσοποταμίαν καὶ περάσας ἄφνω τὸν Εὐφράτην εἰς τὴν Βαβυλωνίαν παρεισπεσὼν ἔφθη, καὶ τῆς ἑτέρας ἄκρας (δύο γὰρ ἦσαν) ἐκκρούσας τὴν τοῦ Σελεύκου φρουρὰν καὶ κρατήσας ἰδίους ἐγκατέστησεν ἑπτακισχιλίους ἄνδρας. ἐκ δὲ τῆς χώρας ὅσα φέρειν ἢ ἄγειν ἠδύναντο τοὺς στρατιώτας ὠφελεῖσθαι καὶ λαμβάνειν κελεύσας, ἐπανῆλθεν ἐπὶ θάλασσαν βεβαιοτέραν Σελεύκῳ τὴν ἀρχὴν ἀπολιπών· ἐξίστασθαι γὰρ ἐδόκει τῷ κακοῦν ὡς μηκέτι προσήκουσαν αὐτοῖς. Πτολεμαίου μέντοι πολιορκοῦντος Ἁλικαρνασὸν ὀξέως βοηθήσας ἐξήρπασε τὴν πόλιν.", "st": "Demetr. 7.2"}, {"sp": "N", "t": "ἐνδόξου δὲ τῆς φιλοτιμίας ταύτης γενομένης, ὁρμὴ παρέστη θαυμάσιος αὐτοῖς ἐλευθεροῦν τὴν Ἑλλάδα πᾶσαν ὑπὸ Κασάνδρου καὶ Πτολεμαίου καταδεδουλωμένην. τούτου πόλεμον οὐδεὶς ἐπολέμησε τῶν βασιλέων καλλίω καὶ δικαιότερον· ἃς γὰρ ἅμα τοὺς βαρβάρους ταπεινοῦντες εὐπορίας συνήγαγον, εἰς τοὺς Ἕλληνας ὑπὲρ εὐδοξίας καὶ τιμῆς ἀνήλισκον. ὡς δὲ πρῶτον ἐδόκει πλεῖν ἐπὶ τὰς Ἀθήνας, τῶν φίλων εἰπόντος τινὸς πρὸς τὸν Ἀντίγονον ὅτι δεῖ ταύτην τὴν πόλιν, ἂν ἕλωσι, κατέχειν δι’ αὑτῶν, ἐπιβάθραν τῆς Ἑλλάδος οὖσαν, οὐ προσέσχεν ὁ Ἀντίγονος, ἀλλ’ ἐπιβάθραν μὲν ἔφη καλὴν καὶ ἀσάλευτον εἶναι τὴν εὔνοιαν, τὰς δὲ Ἀθήνας, ὥσπερ σκοπὴν τῆς οἰκουμένης, ταχὺ τῇ δόξῃ διαπυρσεύειν εἰς ἅπαντας ἀνθρώπους τὰς πράξεις. ἔπλει δὲ Δημήτριος ἔχων ἀργυρίου πεντακισχίλια τάλαντα καὶ στόλον νεῶν πεντήκοντα καὶ διακοσίων ἐπὶ τὰς Ἀθήνας, τὸ μὲν ἄστυ Δημητρίου τοῦ Φαληρέως Κασάνδρῳ διοικοῦντος, ἐν δὲ τῇ Μουνυχίᾳ φρουρᾶς καθεστώσης. εὐτυχίᾳ δὲ ἅμα καὶ προνοίᾳ χρησάμενος ἐπεφαίνετο τῷ Πειραιεῖ πέμπτῃ φθίνοντος Θαργηλιῶνος, προαισθομένου μὲν οὐδενός, ἐπεὶ δὲ ὤφθη πλησίον ὁ στόλος, ἁπάντων ὡς Πτολεμαϊκὰς τὰς ναῦς ὑποδέχεσθαι παρασκευαζομένων, ὀψὲ συμφρονήσαντες ἐβοήθουν οἱ στρατηγοί, καὶ θόρυβος ἦν, οἷον εἰκὸς ἐν ἀπροσδοκήτῳ πολεμίους ἀποβαίνοντας ἀναγκαζομένων ἀμύνεσθαι. τοῖς γὰρ στόμασι τῶν λιμένων ἀκλείστοις ἐπιτυχὼν ὁ Δημήτριος καὶ διεξελάσας ἐντὸς ἦν ἤδη καταφανὴς πᾶσι, καὶ διεσήμηνεν ἀπὸ τῆς νεὼς αἴτησιν ἡσυχίας καὶ σιωπῆς. γενομένου δὲ τούτου κήρυκα παραστησάμενος ἀνεῖπεν ὅτι πέμψειεν αὐτὸν ὁ πατὴρ ἀγαθῇ τύχῃ τοὺς Ἀθηναίους ἐλευθερώσοντα καὶ τὴν φρουρὰν ἐκβαλοῦντα καὶ τοὺς νόμους αὐτοῖς καὶ τὴν πάτριον ἀποδώσοντα πολιτείαν.", "st": "Demetr. 8.1"}, {"sp": "N", "t": "ἀναρρηθέντων δὲ τούτων οἱ μὲν πολλοὶ παραχρῆμα τὰς ἀσπίδας θέμενοι πρὸ τῶν ποδῶν ἀνεκρότησαν καὶ βοῶντες ἐκέλευον ἀποβαίνειν τὸν Δημήτριον, εὐεργέτην καὶ σωτῆρα προσαγορεύοντες· οἱ δὲ περὶ τὸν Φαληρέα πάντως μὲν ᾤοντο δεῖν δέχεσθαι τὸν κρατοῦντα, κἂν μηδὲν ὧν ἐπαγγέλλεται μέλλῃ βεβαιοῦν, ὅμως δὲ πρέσβεις δεομένους ἀπέστειλαν, οἷς ὁ Δημήτριος ἐντυχὼν φιλανθρώπως συνέπεμψε παρ’ ἑαυτοῦ τῶν πατρῴων φίλων τὸν Μιλήσιον Ἀριστόδημον. τοῦ δὲ Φαληρέως διὰ τὴν μεταβολὴν τῆς πολιτείας μᾶλλον τοὺς πολίτας ἢ τοὺς πολεμίους δεδοικότος, οὐκ ἠμέλησεν ὁ Δημήτριος, ἀλλὰ καὶ τὴν δόξαν αἰδεσθεὶς καὶ τὴν ἀρετὴν τοῦ ἀνδρὸς εἰς Θήβας αὐτόν, ὥσπερ ἐβούλετο, μετὰ ἀσφαλείας συνεξέπεμψεν. αὐτὸς δὲ τὴν μὲν πόλιν, οὐκ ἂν ἔφη, καίπερ ἐπιθυμῶν, ἰδεῖν πρότερον ἢ παντάπασιν ἐλευθερῶσαι τῆς φρουρᾶς ἀπαλλάξας· τῇ δὲ Μουνυχίᾳ χαράκωμα καὶ τάφρον περιβαλὼν διὰ μέσου, Μεγάροις ἐπέπλευσεν ὑπὸ Κασάνδρου φρουρουμένοις.", "st": "Demetr. 9.1"}, {"sp": "N", "t": "πυθόμενος δὲ τὴν Ἀλεξάνδρου τοῦ Πολυπέρχοντος γενομένην γυναῖκα Κρατησίπολιν ἐν Πάτραις διατρίβουσαν οὐκ ἂν ἀηδῶς γενέσθαι μετ’ αὐτοῦ, περιβόητον οὖσαν ἐπὶ κάλλει, καταλιπὼν τὴν δύναμιν ἐν τῇ Μεγαρικῇ προῆλθεν εὐζώνους τινὰς ἔχων σὺν αὑτῷ. καὶ τούτων πάλιν ἀποστρέψας ἀπεσκήνωσε χωρὶς ὑπὲρ τοῦ λαθεῖν τὴν γυναῖκα συνελθοῦσαν αὐτῷ. τοῦτό τινες αἰσθόμενοι τῶν πολεμίων ἐξαίφνης κατέδραμον ἐπ’ αὐτόν. ὁ δὲ φοβηθεὶς καὶ λαβὼν χλαμύδιον εὐτελὲς δρόμῳ φεύγων ἐξέφυγεν, ὀλίγου δεήσας αἰσχίστην ἅλωσιν ἐξ ἀκρασίας ἁλῶναι. τὴν δὲ σκηνὴν μετὰ τῶν χρημάτων ᾤχοντο λαβόντες οἱ πολέμιοι.", "st": "Demetr. 9.3"}, {"sp": "N", "t": "τῶν δὲ Μεγάρων ἁλόντων καὶ τῶν στρατιωτῶν ἐφ’ ἁρπαγὴν τραπομένων Ἀθηναῖοι παρῃτήσαντο πολλῇ δεήσει τοὺς Μεγαρεῖς· καὶ τὴν φρουρὰν ὁ Δημήτριος ἐκβαλὼν ἠλευθέρωσε τὴν πόλιν. ἔτι δὲ τοῦτο πράττων τοῦ φιλοσόφου Στίλπωνος ἐμνήσθη, δόξαν ἔχοντος ἀνδρὸς ᾑρημένου πως ἐν ἡσυχίᾳ καταβιῶναι. μεταπεμψάμενος οὖν αὐτὸν ἠρώτα μή τις εἴληφέ τι τῶν ἐκείνου. καὶ ὁ Στίλπων, οὐδείς, εἶπεν· οὐδένα γὰρ εἶδον ἐπιστάμαν ἀποφέροντα. τῶν δὲ θεραπόντων σχεδὸν ἁπάντων διακλαπέντων, ἐπεὶ πάλιν αὐτὸν ὁ Δημήτριος ἐφιλοφρονεῖτο καὶ τέλος ἀπαλλαττόμενος εἶπεν· ἐλευθέραν ὑμῶν, ὦ Στίλπων, ἀπολείπω τὴν πόλιν, ὀρθῶς, ἔφη, λέγεις· οὐδένα γὰρ ἁμῶν δοῦλον ἀπολέλοιπας.", "st": "Demetr. 9.5"}, {"sp": "N", "t": "ἐπεὶ δὲ πάλιν ἐπανελθὼν πρὸς τὴν Μουνυχίαν καὶ στρατοπεδεύσας ἐξέκοψε τὴν φρουρὰν καὶ κατέσκαψε τὸ φρούριον, οὕτως ἤδη τῶν Ἀθηναίων δεχομένων καὶ καλούντων παρελθὼν εἰς τὸ ἄστυ καὶ συναγαγὼν τὸν δῆμον ἀπέδωκε τὴν πάτριον πολιτείαν· καὶ προσυπέσχετο παρὰ τοῦ πατρὸς αὐτοῖς ἀφίξεσθαι σίτου πεντεκαίδεκα μυριάδας μεδίμνων καὶ ξύλων ναυπηγησίμων πλῆθος εἰς ἑκατὸν τριήρεις. Ἀθηναῖοι δὲ ἀπολαβόντες τὴν δημοκρατίαν ἔτει πεντεκαιδεκάτῳ, τὸν δὲ μέσον χρόνον ἀπὸ τῶν Λαμιακῶν καὶ τῆς περὶ Κραννῶνα μάχης λόγῳ μὲν ὀλιγαρχικῆς, ἔργῳ δὲ μοναρχικῆς καταστάσεως γενομένης διὰ τὴν τοῦ Φαληρέως δύναμιν, οὕτω λαμπρὸν ἐν ταῖς εὐεργεσίαις καὶ μέγαν φανέντα τὸν Δημήτριον ἐπαχθῆ καὶ βαρὺν ἐποίησαν τῶν τιμῶν ταῖς ἀμετρίαις ἃς ἐψηφίσαντο. πρῶτοι μὲν γὰρ ἀνθρώπων ἁπάντων τὸν Δημήτριον καὶ Ἀντίγονον βασιλεῖς ἀνηγόρευσαν, ἄλλως ἀφοσιουμένους τοὔνομα, καὶ τοῦτο δὴ μόνον τῶν βασιλικῶν ἔτι τοῖς ἀπὸ Φιλίππου καὶ Ἀλεξάνδρου περιεῖναι δοκοῦν ἄθικτον ἑτέροις καὶ ἀκοινώνητον· μόνοι δὲ σωτῆρας ἀνέγραψαν θεούς, καὶ τὸν ἐπώνυμον καὶ πάτριον ἄρχοντα καταπαύσαντες ἱερέα σωτήρων ἐχειροτόνουν καθ’ ἕκαστον ἐνιαυτόν· καὶ τοῦτον ἐπὶ τῶν ψηφισμάτων καὶ τῶν συμβολαίων προέγραφον. ἐνυφαίνεσθαι δὲ τῷ πέπλῳ μετὰ τῶν θεῶν αὐτοὺς ἐψηφίσαντο· καὶ τὸν τόπον ὅπου πρῶτον ἀπέβη τοῦ ἅρματος, καθιερώσαντες καὶ βωμὸν ἐπιθέντες Δημητρίου Καταιβάτου προσηγόρευσαν· ταῖς δὲ φυλαῖς δύο προσέθεσαν, Δημητριάδα καὶ Ἀντιγονίδα, καὶ τὴν βουλὴν τῶν πεντακοσίων πρότερον ἑξακοσίων ἐποίησαν, ἅτε δὴ φυλῆς ἑκάστης πεντήκοντα βουλευτὰς παρεχομένης.", "st": "Demetr. 10.1"}, {"sp": "N", "t": "τὸ δὲ ὑπερφυέστατον ἐνθύμημα τοῦ Στρατοκλέους (οὗτος γὰρ ἦν ὁ τῶν σοφῶν τούτων καὶ περιττῶν καινουργὸς ἀρεσκευμάτων), ἔγραψεν ὅπως οἱ πεμπόμενοι κατὰ ψήφισμα δημοσίᾳ πρὸς Ἀντίγονον ἢ Δημήτριον ἀντὶ πρεσβευτῶν θεωροὶ λέγοιντο, καθάπερ οἱ Πυθοῖ καὶ Ὀλυμπίαζε τὰς πατρίους θυσίας ὑπὲρ τῶν πόλεων ἀνάγοντες ἐν ταῖς Ἑλληνικαῖς ἑορταῖς. ἦν δὲ καὶ τἆλλα παράτολμος ὁ Στρατοκλῆς, καὶ βεβιωκὼς ἀσελγῶς καὶ τὴν τοῦ παλαιοῦ Κλέωνος ἀπομιμεῖσθαι δοκῶν βωμολοχίαν καὶ βδελυρίαν τῇ πρὸς τὸν δῆμον εὐχερείᾳ. ἔσχε δὲ τὴν ἑταίραν Φυλάκιον ἀνειληφώς· καί ποτε αὐτῷ πρὸς δεῖπνον ἐξ ἀγορᾶς πριαμένης ἐγκεφάλους καὶ τραχήλους, παπαί, εἶπε, τοιαῦτά γε ὠψώνηκας οἷς σφαιρίζομεν οἱ πολιτευόμενοι. τῆς δὲ περὶ Ἀμοργὸν ἥττης τῶν νεῶν συμβάσης τοῖς Ἀθηναίοις, φθάσας τοὺς ἀπαγγέλλοντας εἰσήλασεν ἐστεφανωμένος διὰ τοῦ Κεραμεικοῦ, καὶ προσαγγείλας ὅτι νενικήκασιν, εὐαγγέλια θύειν ἔγραψε καὶ κρεωδαισίαν τινὰ κατὰ φυλὴν ἐποίησεν. ὀλίγῳ δ’ ὕστερον τῶν τὰ ναυάγια κομιζόντων ἀπὸ τῆς μάχης παραγενομένων καὶ τοῦ δήμου πρὸς ὀργὴν καλοῦντος αὐτόν, ἰταμῶς ὑποστὰς τὸν θόρυβον, εἶτα, ἔφη, τί πεπόνθατε δεινόν, εἰ δύο ἡμέρας ἡδέως γεγόνατε; τοιαύτη μὲν ἡ τοῦ Στρατοκλέους θρασύτης.", "st": "Demetr. 11.1"}, {"sp": "N", "t": "ἦν δὲ ἄρα καὶ πυρὸς ἕτερα θερμότερα κατὰ τὸν Ἀριστοφάνη. γράφει γάρ τις ἄλλος ὑπερβαλλόμενος ἀνελευθερίᾳ τὸν Στρατοκλέα, δέχεσθαι Δημήτριον, ὁσάκις ἂν ἀφίκηται, τοῖς Δήμητρος καὶ Διονύσου ξενισμοῖς, τῷ δ’ ὑπερβαλλομένῳ λαμπρότητι καὶ πολυτελείᾳ τὴν ὑποδοχὴν ἀργύριον εἰς ἀνάθημα δημοσίᾳ δίδοσθαι. τέλος δὲ τῶν τε μηνῶν τὸν Μουνυχιῶνα Δημητριῶνα καὶ τῶν ἡμερῶν τὴν ἕνην καὶ νέαν Δημητριάδα προσηγόρευσαν, καὶ τῶν ἑορτῶν τὰ Διονύσια μετωνόμασαν Δημήτρια. ἐπεσήμηνε δὲ τοῖς πλείστοις τὸ θεῖον. ὁ μὲν γὰρ πέπλος, ᾧπερ ἐψηφίσαντο μετὰ τοῦ Διὸς καὶ τῆς Ἀθηνᾶς προσενυφῆναι Δημήτριον καὶ Ἀντίγονον, πεμπόμενος διὰ τοῦ Κεραμεικοῦ μέσος ἐρράγη θυέλλης ἐμπεσούσης· περὶ δὲ τοὺς βωμοὺς τοὺς ἐκείνων ἐξήνθησεν ἡ γῆ κύκλῳ πολὺ κώνειον, ἄλλως μηδὲ τῆς χώρας πολλαχοῦ φυόμενον· τῇ δὲ ἡμέρᾳ ᾗ τὰ τῶν Διονυσίων ἐγίνετο, τὴν πομπὴν κατέλυσαν ἰσχυρῶν πάγων γενομένων παρ’ ὥραν. καὶ πάχνης βαθείας ἐπιπεσούσης οὐ μόνον ἀμπέλους καὶ συκᾶς ἁπάσας ἀπέκαυσε τὸ ψῦχος, ἀλλὰ καὶ τοῦ σίτου τὸν πλεῖστον κατέφθειρεν ἐν χλόῃ. διὸ καὶ Φιλιππίδης ἐχθρὸς ὢν τοῦ Στρατοκλέους ἐν κωμῳδίᾳ πρὸς αὐτὸν ἐποίησε ταῦτα·", "st": "Demetr. 12.1"}, {"sp": "N", "t": "δι’ ὃν ἀπέκαυσεν ἡ πάχνη τὰς ἀμπέλους,<br>δι’ ὃν ἀσεβοῦνθ’ ὁ πέπλος ἐρράγη μέσος,<br>τὰς τῶν θεῶν τιμὰς ποιοῦντ’ ἀνθρωπίνας.", "st": "Demetr. 12.1b"}, {"sp": "N", "t": "ταῦτα καταλύει δῆμον, οὐ κωμῳδία.", "st": "Demetr. 12.1c"}, {"sp": "N", "t": "ἦν δὲ ὁ Φιλιππίδης Λυσιμάχου φίλος, καὶ πολλὰ δι’ αὐτὸν ὁ δῆμος εὖ ἔπαθεν ὑπὸ τοῦ βασιλέως. ἐδόκει δὲ καὶ πρὸς πρᾶξιν αὐτῷ καὶ πρὸς στρατείαν εὐσύμβολος ἀπαντήσας εἶναι καὶ ὀφθείς. ἄλλως δὲ καὶ διὰ τὸ ἦθος εὐδοκίμει, μηθὲν ἐνοχλῶν μηδ’ αὐλικῆς περιεργίας ἀναπιμπλάμενος. φιλοφρονουμένου δέ ποτε τοῦ Λυσιμάχου πρὸς αὐτὸν καὶ εἰπόντος, ὦ Φιλιππίδη, τίνος σοι τῶν ἐμῶν μεταδῶ; μόνον, ἔφη, βασιλεῦ, μὴ τῶν ἀπορρήτων. τοῦτον μὲν οὖν ἐπίτηδες ἐκείνῳ παρεθήκαμεν, τῷ ἀπὸ τοῦ βήματος τὸν ἀπὸ τῆς θυμέλης.", "st": "Demetr. 12.5"}, {"sp": "N", "t": "ὃ δὲ μάλιστα τῶν τιμῶν ὑπερφυὲς ἦν καὶ ἀλλόκοτον, ἔγραψε Δρομοκλείδης ὁ Σφήττιος ὑπὲρ τῆς τῶν ἀσπίδων ἀναθέσεως εἰς Δελφοὺς παρὰ Δημητρίου λαβεῖν χρησμόν. αὐτὴν δὲ παραγράψω τὴν λέξιν ἐκ τοῦ ψηφίσματος οὕτως ἔχουσαν· ἀγαθῇ τύχῃ. δεδόχθαι τῷ δήμῳ χειροτονῆσαι τὸν δῆμον ἕνα ἄνδρα ἐξ Ἀθηναίων, ὅστις ἀφικόμενος πρὸς τὸν Σωτῆρα καὶ καλλιερησάμενος ἐπερωτήσει τὸν Σωτῆρα πῶς ἂν εὐσεβέστατα καὶ κάλλιστα καὶ τὴν ταχίστην ὁ δῆμος τὴν ἀποκατάστασιν ποιήσαιτο τῶν ἀναθημάτων· ὅ τι δ’ ἂν χρήσῃ, ταῦτα πράττειν τὸν δῆμον. οὕτω καταμωκώμενοι τοῦ ἀνθρώπου προσδιέφθειραν αὐτόν, οὐδὲ ἄλλως ὑγιαίνοντα τὴν διάνοιαν.", "st": "Demetr. 13.1"}, {"sp": "N", "t": "ἀλλ’ ἔν γε ταῖς Ἀθήναις τότε σχολάζων ἠγάγετο χηρεύουσαν Εὐρυδίκην, ἣ Μιλτιάδου μὲν ἦν ἀπόγονος τοῦ παλαιοῦ, συνοικήσασα δὲ Ὀφέλᾳ τῷ Κυρήνης ἄρξαντι μετὰ τὴν ἐκείνου τελευτὴν ἀφίκετο πάλιν εἰς τὰς Ἀθήνας. οἱ μὲν οὖν Ἀθηναῖοι τὸν γάμον τοῦτον εἰς χάριν ἔθεντο καὶ τιμὴν τῆς πόλεως· ἄλλως δὲ ὁ Δημήτριος εὐχερής τις ἦν περὶ γάμους, καὶ πολλαῖς ἅμα συνῆν γυναιξίν, ὧν ἀξίωμα μέγιστον εἶχε καὶ τιμὴν Φίλα δι’ Ἀντίπατρον τὸν πατέρα καὶ διὰ τὸ προσυνῳκηκέναι Κρατερῷ, τῷ πλείστην εὔνοιαν αὑτοῦ παρὰ Μακεδόσι τῶν Ἀλεξάνδρου διαδόχων ἀπολιπόντι. ταύτην, ὡς ἔοικε, κομιδῆ νέον ὄντα τὸν Δημήτριον ἔπειθεν ὁ πατήρ, οὐκ οὖσαν αὐτῷ καθ’ ὥραν, ἀλλὰ πρεσβυτέραν, λαβεῖν· ἀπροθύμως δ’ ἔχοντι λέγεται πρὸς τὸ οὖς τὸ Εὐριπίδειον εἰπεῖν·", "st": "Demetr. 14.1"}, {"sp": "N", "t": "ὅπου τὸ κέρδος, παρὰ φύσιν γαμητέον,", "st": "Demetr. 14.1b"}, {"sp": "N", "t": "ὁμοιόπτωτόν τι τῷ δουλευτέον εὐθυρρημονήσας. τοιαύτη μὲν οὖν τις ἦν ἡ τοῦ Δημητρίου τιμὴ πρός τε Φίλαν καὶ τὰς ἄλλας γαμετὰς ὥστε πολλαῖς μὲν ἀνέδην ἑταίραις, πολλαῖς δὲ ἐλευθέραις συνεῖναι γυναιξί, καὶ μάλιστα δὴ περὶ τὴν ἡδονὴν ταύτην κακῶς ἀκοῦσαι τῶν τότε βασιλέων.", "st": "Demetr. 14.1c"}, {"sp": "N", "t": "ἐπεὶ δὲ ὁ πατὴρ αὐτὸν ἐκάλει Πτολεμαίῳ περὶ Κύπρου πολεμήσοντα, πείθεσθαι μὲν ἦν ἀναγκαῖον, ἀχθόμενος δὲ ὅτι τὸν ὑπὲρ τῆς Ἑλλάδος πόλεμον, ὄντα καλλίω καὶ λαμπρότερον, ἀπολείπει, προσέπεμψε Κλεωνίδῃ τῷ Πτολεμαίου στρατηγῷ φρουροῦντι Σικυῶνα καὶ Κόρινθον χρήματα προτείνων, ὥστε ἐλευθέρας ἀφεῖναι τὰς πόλεις. οὐ προσδεξαμένου δὲ ἐκείνου, διὰ ταχέων ἀναχθεὶς καὶ προσλαβὼν δύναμιν ἐπέπλευσε Κύπρῳ. καὶ Μενέλαον μέν, ἀδελφὸν Πτολεμαίου, μάχην συνάψας εὐθὺς ἐνίκησεν· αὐτοῦ δὲ Πτολεμαίου μετὰ δυνάμεως πεζικῆς ἅμα καὶ ναυτικῆς μεγάλης ἐπιφανέντος, ἐγένοντο μὲν ἀπειλαί τινες καὶ διάλογοι κομπώδεις, τοῦ μὲν ἀποπλεῖν Δημήτριον κελεύοντος πρὶν ὑπὸ τῆς δυνάμεως πάσης ἀθροισθείσης καταπατηθῆναι, Δημητρίου δὲ ἐκεῖνον ἀφεῖναι φάσκοντος, ἂν ὁμολογήσῃ Σικυῶνα καὶ Κόρινθον ἀπαλλάξειν τῆς φρουρᾶς. ὁ δὲ ἀγὼν οὐ μόνον αὐτοῖς ἐκείνοις, ἀλλὰ καὶ τοῖς ἄλλοις ἅπασι δυνάσταις πολλὴν εἶχε προσδοκίαν τῆς ἐπικρεμαμένης ἀδηλότητος, ὡς οὐ Κύπρον οὐδὲ Συρίαν, ἀλλὰ τὸ μέγιστον εὐθὺς εἶναι πάντων τῷ κρατοῦντι τῆς νίκης προστιθείσης.", "st": "Demetr. 15.1"}, {"sp": "N", "t": "αὐτὸς μὲν οὖν ὁ Πτολεμαῖος ἐπέπλει πεντήκοντα καὶ ἑκατὸν ναῦς ἔχων, ἐκ δὲ Σαλαμῖνος ἐκέλευσε Μενέλαον ἑξήκοντα ναυσίν, ὅταν μάλιστα σύστασιν ὁ ἀγὼν ἔχῃ, προσφερόμενον τὰς Δημητρίου κόπτειν ἐξόπισθεν καὶ διαταράττειν τὴν τάξιν. Δημήτριος δὲ ταῖς μὲν ἑξήκοντα ταύταις ἀντέταξε δέκα ναῦς (τοσαῦται γὰρ ἤρκουν στενὸν ὄντα τοῦ λιμένος ἐμφράξαι τὸν ἔκπλουν), αὐτὸς δὲ τὸ πεζὸν ἐκτάξας καὶ τοῖς ἀνατείνουσιν εἰς τὴν θάλασσαν ἀκρωτηρίοις περιχεάμενος, οὕτως ἀνήχθη ναυσὶν ἑκατὸν ὀγδοήκοντα· προσμίξας δὲ ῥώμῃ καὶ βίᾳ πολλῇ κατὰ κράτος ἐτρέψατο τὸν Πτολεμαῖον, αὐτὸν μέν, ὡς ἐνικήθη, διὰ ταχέων φυγόντα ναυσὶν ὀκτὼ μόναις (τοσαῦται γὰρ ἐκ πασῶν περιεσώθησαν, τῶν δὲ ἄλλων αἱ μὲν ἐν τῇ ναυμαχίᾳ διεφθάρησαν, ἑβδομήκοντα δὲ ἥλωσαν αὔτανδροι), τοῦ δὲ ἐν ὁλκάσι παρορμοῦντος ὄχλου θεραπόντων καὶ φίλων καὶ γυναικῶν, ἔτι δὲ ὅπλων καὶ χρημάτων καὶ μηχανημάτων ἁπλῶς οὐδὲν ἐξέφυγε τὸν Δημήτριον, ἀλλ’ ἔλαβε πάντα καὶ κατήγαγεν εἰς τὸ στρατόπεδον. ἐν δὲ τούτοις ἡ περιβόητος ἦν Λάμια, τὴν μὲν ἀρχὴν σπουδασθεῖσα διὰ τὴν τέχνην (ἐδόκει γὰρ αὐλεῖν οὐκ εὐκαταφρονήτως), ὕστερον δὲ καὶ τοῖς ἐρωτικοῖς λαμπρὰ γενομένη. τότε γοῦν ἤδη λήγουσα τῆς ὥρας καὶ πολὺ νεώτερον ἑαυτῆς λαβοῦσα τὸν Δημήτριον ἐκράτησε τῇ χάριτι καὶ κατέσχεν, ὥστε ἐκείνης εἶναι μόνης ἐραστήν, τῶν δ’ ἄλλων ἐρώμενον γυναικῶν.", "st": "Demetr. 16.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν ναυμαχίαν οὐδὲ ὁ Μενέλαος ἀντέσχεν, ἀλλὰ τήν τε Σαλαμῖνα παρέδωκε τῷ Δημητρίῳ καὶ τὰς ναῦς καὶ τὸ πεζόν, ἱππεῖς τε χιλίους καὶ διακοσίους καὶ μυρίους καὶ δισχιλίους ὁπλίτας.", "st": "Demetr. 16.1b"}, {"sp": "N", "t": "οὕτω δὲ λαμπρὰν καὶ καλὴν τὴν νίκην γενομένην ἔτι μᾶλλον ἐπικοσμῶν ὁ Δημήτριος εὐγνωμοσύνῃ καὶ φιλανθρωπίᾳ τοὺς νεκροὺς τῶν πολεμίων ἔθαψε μεγαλοπρεπῶς καὶ τοὺς αἰχμαλώτους ἀφῆκεν· Ἀθηναίοις δὲ χιλίας καὶ διακοσίας ἀπὸ τῶν λαφύρων ἐδωρήσατο πανοπλίας.", "st": "Demetr. 17.1"}, {"sp": "N", "t": "Αὐτάγγελον δὲ τῆς νίκης τῷ πατρὶ τὸν Μιλήσιον Ἀριστόδημον ἔπεμψε, πρωτεύοντα κολακείᾳ τῶν αὐλικῶν ἁπάντων, καὶ τότε παρεσκευασμένον, ὡς ἔοικε, τῶν κολακευμάτων τὸ μέγιστον ἐπενεγκεῖν τοῖς πράγμασιν. ὡς γὰρ ἐπέρασεν ἀπὸ τῆς Κύπρου, προσέχειν μὲν οὐκ εἴασε τῇ γῇ τὸ πλοῖον, ἀγκύρας δ’ ἀφεῖναι κελεύσας καὶ κατὰ ναῦν ἔχειν ἀτρέμα πάντας, αὐτὸς ἐμβὰς εἰς τὸ ἐφόλκιον ἐξῆλθε μόνος καὶ πρὸς τὸν Ἀντίγονον ἀνέβαινε, μετέωρον ὄντα τῇ προσδοκίᾳ τῆς μάχης καὶ διακείμενον ὡς εἰκός ἐστι διακεῖσθαι τοὺς περὶ πραγμάτων τηλικούτων ἀγωνιῶντας. τότε γε μὴν ἀκούσας ἐκεῖνον ἥκειν ἔτι μᾶλλον ἢ πρότερον ἔσχε ταραχωδῶς, καὶ μόλις μὲν αὑτὸν οἴκοι κατεῖχεν, ἄλλους δ’ ἐπ’ ἄλλοις ἔπεμπεν ὑπηρέτας καὶ φίλους πευσομένους τοῦ Ἀριστοδήμου περὶ τῶν γεγονότων. ἀποκρινομένου δὲ μηδὲν αὐτοῦ μηδενί, βάδην δὲ καὶ συνεστῶτι τῷ προσώπῳ μετὰ πολλῆς σιωπῆς προσιόντος, ἐκπλαγεὶς κομιδῆ καὶ μηκέτι καρτερῶν ὁ Ἀντίγονος ἐπὶ τὰς θύρας ἀπήντησε, πολλοῦ παραπέμποντος ἤδη τὸν Ἀριστόδημον ὄχλου καὶ συντρέχοντος ἐπὶ τὸ βασίλειον. ὡς οὖν ἐγγὺς ἦλθεν, ἐκτείνας τὴν δεξιὰν ἀνεβόησε μεγάλῃ τῇ φωνῇ χαῖρε, βασιλεῦ Ἀντίγονε, νικῶμεν Πτολεμαῖον ναυμαχίᾳ καὶ Κύπρον ἔχομεν καὶ στρατιώτας αἰχμαλώτους μυρίους ἑξακισχιλίους ὀκτακοσίους. ὁ δὲ Ἀντίγονος, καὶ σύ, νὴ Δία, χαῖρε, εἶπεν· οὕτω δὲ ἡμᾶς βασανίσας δίκην ὑφέξεις· βράδιον γὰρ ἀπολήψῃ τὸ εὐαγγέλιον.", "st": "Demetr. 17.2"}, {"sp": "N", "t": "ἐκ τούτου πρῶτον ἀνεφώνησε τὸ πλῆθος Ἀντίγονον καὶ Δημήτριον βασιλέας. Ἀντίγονον μὲν οὖν εὐθὺς ἀνέδησαν οἱ φίλοι, Δημητρίῳ δὲ ὁ πατὴρ ἔπεμψε διάδημα καὶ γράφων ἐπιστολὴν βασιλέα προσεῖπεν. οἱ δ’ ἐν Αἰγύπτῳ τούτων ἀπαγγελλομένων καὶ αὐτοὶ βασιλέα τὸν Πτολεμαῖον ἀνηγόρευσαν, ὡς μὴ δοκεῖν τοῦ φρονήματος ὑφίεσθαι διὰ τὴν ἧτταν. ἐπενείματο δὲ οὕτως τὸ πρᾶγμα τῷ ζήλῳ τοὺς διαδόχους. καὶ γὰρ Λυσίμαχος ἤρξατο φορεῖν διάδημα, καὶ Σέλευκος ἐντυγχάνων τοῖς Ἕλλησιν, ἐπεὶ τοῖς γε βαρβάροις πρότερον οὗτος ὡς βασιλεὺς ἐχρημάτιζε. Κάσανδρος δέ, τῶν ἄλλων αὐτὸν βασιλέα καὶ γραφόντων καὶ καλούντων, αὐτός, ὥσπερ πρότερον εἰώθει, τὰς ἐπιστολὰς ἔγραφε.", "st": "Demetr. 18.1"}, {"sp": "N", "t": "τοῦτο δὲ οὐ προσθήκην ὀνόματος καὶ σχήματος ἐξαλλαγὴν εἶχε μόνον, ἀλλὰ καὶ τὰ φρονήματα τῶν ἀνδρῶν ἐκίνησε καὶ τὰς γνώμας ἐπῆρε καὶ τοῖς βίοις καὶ ταῖς ὁμιλίαις αὐτῶν ὄγκον ἐνεποίησε καὶ βαρύτητα, καθάπερ τραγικῶν ὑποκριτῶν ἅμα τῇ σκηνῇ συμμεταβαλλόντων καὶ βάδισμα καὶ φωνὴν καὶ κατάκλισιν καὶ προσαγόρευσιν. ἐκ δὲ τούτων ἐγένοντο καὶ περὶ τὰς δικαιώσεις βιαιότεροι, τὴν εἰς πολλὰ παρέχουσαν αὐτοὺς ἐλαφροτέρους καὶ μαλακωτέρους τοῖς ὑπηκόοις πρότερον εἰρωνείαν τῆς ἐξουσίας ἀφελόντες. τοσοῦτον ἴσχυσε κόλακος φωνὴ μία καὶ τοσαύτης ἐνέπλησε τὴν οἰκουμένην μεταβολῆς.", "st": "Demetr. 18.3"}, {"sp": "N", "t": "Ἀντίγονος δὲ τοῖς πεπραγμένοις ὑπὸ Δημητρίου περὶ Κύπρον ἐπαρθεὶς εὐθὺς ἐστράτευσεν ἐπὶ Πτολεμαῖον, αὐτὸς μὲν ἄγων πεζῇ τὴν δύναμιν, Δημητρίου δὲ μεγάλῳ στόλῳ συμπαραπλέοντος. ὃν δὲ τρόπον ἔμελλε κρίνεσθαι τὰ πράγματα, Μήδιος, Ἀντιγόνου φίλος, ὄψιν εἶδε κατὰ τοὺς ὕπνους. ἐδόκει γὰρ αὐτὸν Ἀντίγονον ἀγωνίζεσθαι μετὰ τῆς στρατιᾶς ἁπάσης δίαυλον εὐρώστως καὶ ταχὺ τὸ πρῶτον, εἶτα κατὰ μικρὸν ἐνδιδόναι τὴν δύναμιν αὐτῷ· καὶ τέλος, ὡς ἔκαμψεν, ἀσθενῆ γενόμενον καὶ μεστὸν ἄσθματος οὐ ῥᾳδίως ἀναφέρειν. αὐτός τε οὖν ἐντυχὼν κατὰ γῆν πολλαῖς ἀπορίαις, καὶ Δημητρίου χειμῶνι μεγάλῳ καὶ κλύδωνι κινδυνεύσαντος εἰς τόπους ἀλιμένους καὶ χαλεποὺς ἐκριφῆναι, πολλὰς δὲ τῶν νεῶν ἀπολέσαντος, ἐπανῆλθεν ἄπρακτος.", "st": "Demetr. 19.1"}, {"sp": "N", "t": "ἦν δὲ τότε μικρὸν ἀπολείποντα γεγονὼς ἔτη ὀγδοήκοντα, μεγέθει δὲ καὶ βαρύτητι σώματος μᾶλλον ἢ διὰ τὸ γῆρας ἐπὶ τὰς στρατείας γεγονὼς δυσπαρακόμιστος ἐχρῆτο τῷ παιδὶ καὶ δι’ εὐτυχίαν καὶ δι’ ἐμπειρίαν ἤδη τὰ μέγιστα καλῶς διοικοῦντι, τρυφὰς δὲ καὶ πολυτελείας καὶ πότους αὐτοῦ μὴ βαρυνόμενος. εἰρήνης γὰρ οὔσης ἀφύβριζεν εἰς ταῦτα καὶ σχολάζων ἐχρῆτο πρὸς τὰς ἡδονὰς ἀνειμένως αὑτῷ καὶ κατακόρως, ἐν δὲ τοῖς πολέμοις ὡς οἱ φύσει σώφρονες ἔνηφε. λέγεται δὲ τῆς Λαμίας ἀναφανδὸν ἤδη κρατούσης, τὸν Ἀντίγονον ὑπὸ τοῦ Δημητρίου καταφιλούμενον ἥκοντος ἀπὸ ξένης εἰπεῖν ἅμα γελῶντα, δοκεῖς Λάμιαν, ὦ παῖ, καταφιλεῖν. πάλιν δέ ποτε πλείονας ἡμέρας ἐν πότοις γενομένου, καὶ πρόφασιν λέγοντος ὡς ῥεῦμα διοχλήσειεν αὐτόν, ἐπυθόμην, φάναι τὸν Ἀντίγονον, ἀλλὰ πότερον Θάσιον ἢ Χῖον ἦν τὸ ῥεῦμα; πυθόμενος δὲ αὖθις ἀσθενῶς ἔχειν αὐτὸν ἐβάδιζεν ὀψόμενος, καὶ τῶν καλῶν τινι περὶ θύρας ἀπήντησεν· εἰσελθὼν δὲ καὶ καθίσας παρ’ αὐτὸν ἥψατο τῆς χειρός· ἐκείνου δὲ εἰπόντος ὅτι νῦν ὁ πυρετὸς ἀποκεχώρηκεν, ἀμέλει, παιδίον, ἔφη, καὶ ἐμοὶ νῦν περὶ θύρας ἀπιὼν ἀπήντηκε. ταῦτα δὲ οὕτω πρᾴως ἔφερε τοῦ Δημητρίου διὰ τὴν ἄλλην πρᾶξιν. οἱ μὲν γὰρ Σκύθαι πίνοντες καὶ μεθυσκόμενοι παραψάλλουσι τὰς νευρὰς τῶν τόξων, οἷον ἐκλυόμενον ὑπὸ τῆς ἡδονῆς ἀνακαλούμενοι τὸν θυμόν, ἐκεῖνος δὲ τὰ μὲν ἡδονῇ διδοὺς ἁπλῶς ἑαυτόν, τὰ δὲ σπουδῇ, καὶ θάτερα τῶν ἑτέρων ἄκρατα μεταχειριζόμενος, οὐχ ἧττον ἦν δεινὸς ἐν ταῖς τοῦ πολέμου παρασκευαῖς.", "st": "Demetr. 19.3"}, {"sp": "N", "t": "ἀλλὰ καὶ παρασκευάσασθαι δύναμιν ἢ χρήσασθαι βελτίων ἐδόκει στρατηγὸς εἶναι, πάντα μὲν ἐκ περιουσίας ὑπάρχειν βουλόμενος ἐπὶ τὰς χρείας, τῆς δὲ περὶ τὰς ναῦς καὶ τὰ μηχανήματα μεγαλουργίας καὶ καθ’ ἡδονήν τινα τοῦ θεωρεῖν ἀπλήστως ἔχων. εὐφυὴς γὰρ ὢν καὶ θεωρητικὸς οὐκ εἰς παιδιὰς οὐδ’ εἰς διαγωγὰς ἀχρήστους ἔτρεψε τὸ φιλότεχνον, ὥσπερ ἄλλοι βασιλεῖς αὐλοῦντες καὶ ζωγραφοῦντες καὶ τορεύοντες. Ἀέροπος γὰρ ὁ Μακεδὼν τραπέζια μικρὰ καὶ λυχνίδια τεκταινόμενος, ὁπότε σχολάζοι, διῆγεν. Ἄτταλος δὲ ὁ Φιλομήτωρ ἐκήπευε τὰς φαρμακώδεις βοτάνας, οὐ μόνον ὑοσκύαμον καὶ ἐλλέβορον, ἀλλὰ καὶ κώνειον καὶ ἀκόνιτον καὶ δορύκνιον, αὐτὸς ἐν τοῖς βασιλείοις σπείρων καὶ φυτεύων, ὀπούς τε καὶ καρπὸν αὐτῶν ἔργον πεποιημένος εἰδέναι καὶ κομίζεσθαι καθ’ ὥραν. οἱ δὲ Πάρθων βασιλεῖς ἐσεμνύνοντο τὰς ἀκίδας τῶν βελῶν χαράττοντες αὐτοὶ καὶ παραθήγοντες. ἀλλὰ μὴν Δημητρίου καὶ τὸ βάναυσον ἦν βασιλικόν, καὶ μέγεθος ἡ μέθοδος εἶχεν, ἅμα τῷ περιττῷ καὶ φιλοτέχνῳ τῶν ἔργων ὕψος τι διανοίας καὶ φρονήματος συνεκφερόντων, ὥστε μὴ μόνον γνώμης καὶ περιουσίας, ἀλλὰ καὶ χειρὸς ἄξια φαίνεσθαι βασιλικῆς. μεγέθει μὲν γὰρ ἐξέπληττε καὶ τοὺς φίλους, κάλλει δὲ καὶ τοὺς πολεμίους ἔτερπε. τοῦτο δὲ ἔτι μᾶλλον ἀληθῶς ἢ κομψῶς εἴρηται. καὶ τὰς μὲν ἑκκαιδεκήρεις αὐτοῦ καὶ τὰς πεντεκαιδεκήρεις ἐθαύμαζον ἑστῶτες οἱ πολέμιοι παρὰ τὴν γῆν αὐτῶν πλεούσας, αἱ δ’ ἑλεπόλεις ὡς θέαμα τοῖς πολιορκουμένοις ἦσαν, ὡς αὐτὰ τὰ πράγματα μαρτυρεῖ. Λυσίμαχος μὲν γάρ, ἔχθιστος ὢν Δημητρίῳ τῶν βασιλέων καὶ πολιορκοῦντι Σόλους τοὺς Κιλικίους ἀντιτεταγμένος, ἔπεμψε παρακαλῶν ἐπιδεῖξαι τὰς μηχανὰς αὐτῷ καὶ τὰς ναῦς πλεούσας· ἐπιδείξαντος δὲ θαυμάσας ἀπῆλθε. Ῥόδιοι δὲ πολὺν χρόνον ὑπ’ αὐτοῦ πολιορκηθέντες, ἐπεὶ κατελύσαντο τὸν πόλεμον, ᾐτήσαντο τῶν μηχανῶν ἐνίας, ὅπως ὑπόμνημα τῆς ἐκείνου δυνάμεως ἅμα καὶ τῆς αὑτῶν ἀνδραγαθίας ἔχωσιν.", "st": "Demetr. 20.1"}, {"sp": "N", "t": "ἐπολέμησε δὲ Ῥοδίοις Πτολεμαίου συμμάχοις οὖσι, καὶ τὴν μεγίστην ἑλέπολιν τοῖς τείχεσι προσήγαγεν, ἧς ἕδρα μὲν ἦν τετράγωνος, ἑκάστην ἔχουσα τοῦ κάτω πλαισίου πλευρὰν ὀκτὼ καὶ τεσσαράκοντα πηχῶν, ἓξ δὲ καὶ ἑξήκοντα πηχῶν ὕψος εἶχεν, εἰς κορυφὴν συννεύουσα ταῖς ἄνω πλευραῖς στενωτέραν τῆς βάσεως. ἔνδοθεν μὲν οὖν στέγαις διεπέφρακτο καὶ χώραις πολλαῖς, τὸ δὲ πρὸς τοὺς πολεμίους αὐτῆς μέτωπον ἀνέῳκτο καθ’ ἑκάστην στέγην θυρίσιν, καὶ διὰ τούτων ἐξέπιπτε βέλη παντοδαπά· μεστὴ γὰρ ἦν ἀνδρῶν μαχομένων πᾶσαν ἰδέαν μάχης. καὶ τὸ μὴ κραδαινόμενον αὐτῆς μηδὲ κλινόμενον ἐν ταῖς κινήσεσιν, ἀλλ’ ὀρθὸν ἐν ἕδρᾳ καὶ ἀσάλευτον, ἰσορρόπως ἅμα ῥοίζῳ καὶ τόνῳ πολλῷ προχωροῦν, θάμβος ἅμα τῇ ψυχῇ καὶ χάριν τινα τῇ ὄψει τῶν θεωμένων παρεῖχε.", "st": "Demetr. 21.1"}, {"sp": "N", "t": "πρὸς δὲ τοῦτον τὸν πόλεμον αὐτῷ καὶ θώρακες ἐκομίσθησαν ἐκ Κύπρου δύο σιδηροῖ, μνῶν ὁλκῆς ἑκάτερος τεσσαράκοντα. δυσπάθειαν δὲ καὶ ῥώμην αὐτῶν ἐπιδεικνύμενος ὁ τεχνίτης Ζωΐλος ἐκέλευσεν ἐξ εἴκοσι βημάτων ἀφεῖναι καταπελτικὸν βέλος, οὗ προσπεσόντος ἀρραγὴς διέμεινεν ὁ σίδηρος, ἀμυχὴν δὲ μόλις ἔσχεν ἀμβλεῖαν, οἷον ἀπὸ γραφείου. τοῦτον αὐτὸς ἐφόρει· τὸν δ’ ἕτερον Ἄλκιμος ὁ Ἠπειρώτης, ἀνὴρ πολεμικώτατος τῶν σὺν αὐτῷ καὶ ῥωμαλεώτατος, ὃς μόνος ἐχρῆτο διταλάντῳ πανοπλίᾳ, τῶν ἄλλων χρωμένων ταλαντιαίᾳ· καὶ μαχόμενος ἐν Ῥόδῳ περὶ τὸ θέατρον ἔπεσεν.", "st": "Demetr. 21.3"}, {"sp": "N", "t": "εὐρώστως δὲ καὶ τῶν Ῥοδίων ἀμυνομένων, οὐδὲν ἄξιον λόγου πράττων ὁ Δημήτριος ὅμως ἐθυμομάχει πρὸς αὐτούς, ὅτι, Φίλας τῆς γυναικὸς αὐτῷ γράμματα καὶ στρώματα καὶ ἱμάτια πεμψάσης, λαβόντες τὸ πλοῖον, ὥσπερ εἶχε, πρὸς Πτολεμαῖον ἀπέστειλαν, καὶ τὴν Ἀθηναίων οὐκ ἐμιμήσαντο φιλανθρωπίαν, οἳ Φιλίππου πολεμοῦντος αὐτοῖς γραμματοφόρους ἑλόντες τὰς μὲν ἄλλας ἀνέγνωσαν ἐπιστολάς, μόνην δὲ τὴν Ὀλυμπιάδος οὐκ ἔλυσαν, ἀλλ’, ὥσπερ ἦν κατασεσημασμένη, πρὸς ἐκεῖνον ἀπέστειλαν. οὐ μὴν ἀλλά, καίπερ ἐπὶ τούτῳ σφόδρα δηχθεὶς ὁ Δημήτριος, εὐθὺς παρασχόντας λαβὴν οὐχ ὑπέμεινεν ἀντιλυπῆσαι τοὺς Ῥοδίους. ἔτυχε γὰρ αὐτοῖς ὁ Καύνιος Πρωτογένης γράφων τὴν περὶ τὸν Ἰάλυσον διάθεσιν, καὶ τὸν πίνακα μικρὸν ἀπολείποντα τοῦ τέλος ἔχειν ἔν τινι τῶν προαστείων ἔλαβεν ὁ Δημήτριος. πεμψάντων δὲ κήρυκα τῶν Ῥοδίων καὶ δεομένων φείσασθαι καὶ μὴ διαφθεῖραι τὸ ἔργον, ἀπεκρίνατο τὰς τοῦ πατρὸς εἰκόνας ἂν ἐμπρῆσαι μᾶλλον ἢ τέχνης πόνον τοσοῦτον. ἑπτὰ γὰρ ἔτεσι λέγεται συντελέσαι τὴν γραφὴν ὁ Πρωτογένης. καί φησιν ὁ Ἀπελλῆς οὕτως ἐκπλαγῆναι θεασάμενος τὸ ἔργον ὥστε καὶ φωνὴν ἐπιλιπεῖν αὐτόν, ὀψὲ δὲ εἰπεῖν ὅτι μέγας ὁ πόνος καὶ θαυμαστὸν τὸ ἔργον, οὐ μὴν ἔχειν γε χάριτας δι’ ἃς οὐρανοῦ ψαύειν τὰ ὑπ’ αὐτοῦ γραφόμενα. ταύτην μὲν οὖν τὴν γραφὴν εἰς ταὐτὸ ταῖς ἄλλαις συνωσθεῖσαν ἐν Ῥώμῃ τὸ πῦρ ἐπενείματο. τῶν δὲ Ῥοδίων κατεξανισταμένων τοῦ πολέμου, δεόμενον προφάσεως τὸν Δημήτριον Ἀθηναῖοι παραγενόμενοι διήλλαξαν ἐπὶ τῷ συμμαχεῖν Ῥοδίους Ἀντιγόνῳ καὶ Δημητρίῳ πλὴν ἐπὶ Πτολεμαῖον.", "st": "Demetr. 22.1"}, {"sp": "N", "t": "ἐκάλουν δὲ τὸν Δημήτριον οἱ Ἀθηναῖοι Κασάνδρου τὸ ἄστυ πολιορκοῦντος. ὁ δὲ ναυσὶν ἐπιπλεύσας τριακοσίαις τριάκοντα καὶ πολλοῖς ὁπλίταις, οὐ μόνον ἐξήλασε τῆς Ἀττικῆς τὸν Κάσανδρον, ἀλλὰ καὶ φεύγοντα μέχρι Θερμοπυλῶν διώξας καὶ τρεψάμενος, Ἡράκλειαν ἔλαβεν, ἑκουσίως αὐτῷ προσθεμένην, καὶ τῶν Μακεδόνων ἑξακισχιλίους μεταβαλομένους πρὸς αὐτόν. ἐπανιὼν δὲ τοὺς ἐντὸς Πυλῶν Ἕλληνας ἠλευθέρου, καὶ Βοιωτοὺς ἐποιήσατο συμμάχους, καὶ Κεγχρέας εἷλε· καὶ Φυλὴν καὶ Πάνακτον, ἐπιτειχίσματα τῆς Ἀττικῆς ὑπὸ Κασάνδρου φρουρούμενα, καταστρεψάμενος ἀπέδωκε τοῖς Ἀθηναίοις. οἱ δὲ καίπερ ἐκκεχυμένοι πρότερον εἰς αὐτὸν καὶ κατακεχρημένοι πᾶσαν φιλοτιμίαν, ἐξεῦρον ὅμως καὶ τότε πρόσφατοι καὶ καινοὶ ταῖς κολακείαις φανῆναι. τὸν γὰρ ὀπισθόδομον τοῦ Παρθενῶνος ἀπέδειξαν αὐτῷ κατάλυσιν· κἀκεῖ δίαιταν εἶχε, τῆς Ἀθηνᾶς λεγομένης ὑποδέχεσθαι καὶ ξενίζειν αὐτόν, οὐ πάνυ κόσμιον ξένον οὐδὲ ὡς παρθένῳ πρᾴως ἐπισταθμεύοντα. καίτοι τὸν ἀδελφὸν αὐτοῦ Φίλιππον αἰσθόμενός ποτε ὁ πατὴρ ἐν οἰκίᾳ καταλύοντα τρεῖς ἐχούσῃ νέας γυναῖκας, πρὸς ἐκεῖνον μὲν οὐδὲν ἐφθέγξατο, παρόντος δὲ ἐκείνου, τὸν σταθμοδότην μεταπεμψάμενος, οὗτος, εἶπεν, οὐκ ἐξάξεις μου τὸν υἱὸν ἐκ τῆς στενοχωρίας;", "st": "Demetr. 23.1"}, {"sp": "N", "t": "Δημήτριος δέ, τὴν Ἀθηνᾶν αὐτῷ προσῆκον, εἰ δι’ ἄλλο μηδέν, ὥς γε πρεσβυτέραν ἀδελφὴν αἰσχύνεσθαι (τοῦτο γὰρ ἐβούλετο λέγεσθαι), τοσαύτην ὕβριν εἰς παῖδας ἐλευθέρους καὶ γυναῖκας ἀστὰς κατεσκέδασε τῆς ἀκροπόλεως ὥστε δοκεῖν τότε μάλιστα καθαρεύειν τὸν τόπον, ὅτε Χρυσίδι καὶ Λαμίᾳ καὶ Δημοῖ καὶ Ἀντικύρᾳ, ταῖς πόρναις ἐκείναις, συνακολασταίνοι.", "st": "Demetr. 24.1"}, {"sp": "N", "t": "τὰ μὲν οὖν ἄλλα σαφῶς ἀπαγγέλλειν οὐ πρέπει διὰ τὴν πόλιν, τὴν δὲ Δημοκλέους ἀρετὴν καὶ σωφροσύνην ἄξιόν ἐστι μὴ παρελθεῖν. ἐκεῖνος γὰρ ἦν ἔτι παῖς ἄνηβος, οὐκ ἔλαθε δὲ τὸν Δημήτριον ἔχων τῆς εὐμορφίας τὴν ἐπωνυμίαν κατήγορον· ἐκαλεῖτο γὰρ Δημοκλῆς ὁ καλός. ὡς δὲ πολλὰ πειρώντων καὶ διδόντων καὶ φοβούντων ὑπ’ οὐδενὸς ἡλίσκετο, τέλος δὲ φεύγων τὰς παλαίστρας καὶ τὸ γυμνάσιον εἴς τι βαλανεῖον ἰδιωτικὸν ἐφοίτα λουσόμενος, ἐπιτηρήσας τὸν καιρὸν ὁ Δημήτριος ἐπεισῆλθεν αὐτῷ μόνῳ. καὶ ὁ παῖς, ὡς συνεῖδε τὴν περὶ αὑτὸν ἐρημίαν καὶ τὴν ἀνάγκην, ἀφελὼν τὸ πῶμα τοῦ χαλκώματος εἰς ζέον ὕδωρ ἐνήλατο καὶ διέφθειρεν αὑτόν, ἀνάξια μὲν παθών, ἄξια δὲ τῆς πατρίδος καὶ τοῦ κάλλους φρονήσας, οὐχ ὡς Κλεαίνετος ὁ Κλεομέδοντος, ὃς ὠφληκότι τῷ πατρὶ δίκην πεντήκοντα ταλάντων ἀφεθῆναι διαπραξάμενος καὶ γράμματα παρὰ Δημητρίου κομίσας πρὸς τὸν δῆμον οὐ μόνον ἑαυτὸν κατῄσχυνεν, ἀλλὰ καὶ τὴν πόλιν συνετάραξε. τὸν μὲν γὰρ Κλεομέδοντα τῆς δίκης ἀφῆκαν, ἐγράφη δὲ ψήφισμα μηδένα τῶν πολιτῶν ἐπιστολὴν παρὰ Δημητρίου κομίζειν. ἐπεὶ δὲ ἀκούσας ἐκεῖνος οὐκ ἤνεγκε μετρίως, ἀλλ’ ἠγανάκτησε, δείσαντες αὖθις οὐ μόνον τὸ ψήφισμα καθεῖλον, ἀλλὰ καὶ τῶν εἰσηγησαμένων καὶ συνειπόντων τοὺς μὲν ἀπέκτειναν, τοὺς δὲ ἐφυγάδευσαν, ἔτι δὲ προσεψηφίσαντο δεδόχθαι τῷ δήμῳ τῶν Ἀθηναίων πᾶν, ὅ τι ἂν ὁ βασιλεὺς Δημήτριος κελεύσῃ, τοῦτο καὶ πρὸς θεοὺς ὅσιον καὶ πρὸς ἀνθρώπους εἶναι δίκαιον. εἰπόντος δέ τινος τῶν καλῶν κἀγαθῶν ἀνδρῶν μαίνεσθαι τὸν Στρατοκλέα τοιαῦτα γράφοντα, Δημοχάρης ὁ Λευκονοεὺς μαίνοιτο μέντἄν, εἶπεν, εἰ μὴ μαίνοιτο. πολλὰ γὰρ ὁ Στρατοκλῆς ὠφελεῖτο διὰ τὴν κολακείαν. ὁ δὲ Δημοχάρης ἐπὶ τούτῳ διαβληθεὶς ἐφυγαδεύθη. τοιαῦτα ἔπραττον Ἀθηναῖοι φρουρᾶς ἀπηλλάχθαι καὶ τὴν ἐλευθερίαν ἔχειν δοκοῦντες.", "st": "Demetr. 24.2"}, {"sp": "N", "t": "Δημήτριος δὲ παρελθὼν εἰς Πελοπόννησον, οὐδενὸς ὑφισταμένου τῶν ἐναντίων, ἀλλὰ φευγόντων καὶ προϊεμένων τὰς πόλεις, προσηγάγετο τήν τε καλουμένην Ἀκτὴν καὶ Ἀρκαδίαν, πλὴν Μαντινείας, καὶ Ἄργος καὶ Σικυῶνα καὶ Κόρινθον ἐλύσατο τάλαντα δοὺς ἑκατὸν τοῖς φρουροῦσιν. ἐν Ἄργει μὲν οὖν τῆς τῶν Ἡραίων ἑορτῆς καθηκούσης, ἀγωνοθετῶν καὶ συμπανηγυρίζων τοῖς Ἕλλησιν, ἔγημε τὴν Αἰακίδου θυγατέρα, τοῦ Μολοττῶν βασιλέως, ἀδελφὴν δὲ Πύρρου, Δηϊδάμειαν. Σικυωνίους δὲ φήσας παρὰ τὴν πόλιν οἰκεῖν τὴν πόλιν, ἔπεισεν οὗ νῦν οἰκοῦσι μετοικίσασθαι· τῷ δὲ τόπῳ καὶ τοὔνομα τὴν πόλιν συμμεταβαλοῦσαν ἀντὶ Σικυῶνος Δημητριάδα προσηγόρευσεν. ἐν δὲ Ἰσθμῷ κοινοῦ συνεδρίου γενομένου καὶ πολλῶν ἀνθρώπων συνελθόντων, ἡγεμὼν ἀνηγορεύθη τῆς Ἑλλάδος, ὡς πρότερον οἱ περὶ Φίλιππον καὶ Ἀλέξανδρον· ὧν ἐκεῖνος οὐ παρὰ μικρὸν ἐνόμιζεν ἑαυτὸν εἶναι βελτίονα, τῇ τύχῃ τῇ παρούσῃ καὶ τῇ δυνάμει τῶν πραγμάτων ἐπαιρόμενος. Ἀλέξανδρος γοῦν οὐδένα τῶν ἄλλων βασιλέων ἀπεστέρησε τῆς ὁμωνυμίας, οὐδὲ αὑτὸν ἀνεῖπε βασιλέων βασιλέα, καίτοι πολλοῖς τὸ καλεῖσθαι καὶ εἶναι βασιλέας αὐτὸς δεδωκώς· ἐκεῖνος δὲ χλευάζων καὶ γελῶν τοὺς ἄλλον τινὰ πλὴν τοῦ πατρὸς καὶ αὐτοῦ βασιλέα προσαγορεύοντας, ἡδέως ἤκουε τῶν παρὰ πότον ἐπιχύσεις λαμβανόντων Δημητρίου βασιλέως, Σελεύκου δὲ ἐλεφαντάρχου, Πτολεμαίου δὲ ναυάρχου, Λυσιμάχου δὲ γαζοφύλακος, Ἀγαθοκλέους δὲ τοῦ Σικελιώτου νησιάρχου. τούτων δὲ πρὸς τοὺς βασιλεῖς ἐκφερομένων οἱ μὲν ἄλλοι βασιλεῖς κατεγέλων, Λυσίμαχος δ’ ἠγανάκτει μόνος εἰ σπάδοντα νομίζει Δημήτριος αὐτόν· ἐπιεικῶς γὰρ εἰώθεισαν εὐνούχους ἔχειν γαζοφύλακας. ἦν δὲ καὶ πάντων ἀπεχθέστατος ὁ Λυσίμαχος αὐτῷ, καὶ λοιδορῶν εἰς τὸν ἔρωτα τῆς Λαμίας ἔλεγε νῦν πρῶτον ἑωρακέναι πόρνην προερχομένην ἐκ τραγικῆς σκηνῆς· ὁ δὲ Δημήτριος ἔφη τὴν ἑαυτοῦ πόρνην σωφρονεστέραν εἶναι τῆς ἐκείνου Πηνελόπης.", "st": "Demetr. 25.1"}, {"sp": "N", "t": "τότε δ’ οὖν ἀναζευγνύων εἰς τὰς Ἀθήνας ἔγραψεν ὅτι βούλεται παραγενόμενος εὐθὺς μυηθῆναι καὶ τὴν τελετὴν ἅπασαν ἀπὸ τῶν μικρῶν ἄχρι τῶν ἐποπτικῶν παραλαβεῖν. τοῦτο δὲ οὐ θεμιτὸν ἦν οὐδὲ γεγονὸς πρότερον, ἀλλὰ τὰ μικρὰ τοῦ Ἀνθεστηριῶνος ἐτελοῦντο, τὰ δὲ μεγάλα τοῦ Βοηδρομιῶνος· ἐπώπτευον δὲ τοὐλάχιστον ἀπὸ τῶν μεγάλων ἐνιαυτὸν διαλείποντες. ἀναγνωσθέντων δὲ τῶν γραμμάτων μόνος ἐτόλμησεν ἀντειπεῖν Πυθόδωρος ὁ δᾳδοῦχος, ἐπέρανε δὲ οὐδέν· ἀλλὰ Στρατοκλέους γνώμην εἰπόντος Ἀνθεστηριῶνα τὸν Μουνυχιῶνα ψηφισαμένους καλεῖν καὶ νομίζειν, ἐτέλουν τῷ Δημητρίῳ τὰ πρὸς Ἄγραν· καὶ μετὰ ταῦτα πάλιν ἐξ Ἀνθεστηριῶνος ὁ Μουνυχιὼν γενόμενος Βοηδρομιὼν ἐδέξατο τὴν λοιπὴν τελετήν, ἅμα καὶ τὴν ἐποπτείαν τοῦ Δημητρίου προσεπιλαβόντος. διὸ καὶ Φιλιππίδης τὸν Στρατοκλέα λοιδορῶν ἐποίησεν·", "st": "Demetr. 26.1"}, {"sp": "N", "t": "ὁ τὸν ἐνιαυτὸν συντεμὼν εἰς μῆν’ ἕνα,<br>καὶ περὶ τῆς ἐν τῷ Παρθενῶνι κατασκηνώσεως·<br>ὁ τὴν ἀκρόπολιν πανδοκεῖον ὑπολαβὼν<br>καὶ τὰς ἑταίρας εἰσαγαγὼν τῇ παρθένῳ.", "st": "Demetr. 26.1b"}, {"sp": "N", "t": "πολλῶν δὲ γενομένων ἐν τῇ πόλει τότε πλημμελημάτων καὶ παρανομημάτων ἐκεῖνο μάλιστα λέγεται λυπῆσαι τοὺς Ἀθηναίους, ὅτι διακόσια καὶ πεντήκοντα τάλαντα πορίσαι ταχὺ καὶ δοῦναι προσταχθὲν αὐτοῖς καὶ τῆς εἰσπράξεως συντόνου καὶ ἀπαραιτήτου γενομένης, ἰδὼν ἠθροισμένον τὸ ἀργύριον ἐκέλευσε Λαμίᾳ καὶ ταῖς περὶ αὐτὴν ἑταίραις εἰς σμῆγμα δοθῆναι. ἡ γὰρ αἰσχύνη τῆς ζημίας καὶ τὸ ῥῆμα τοῦ πράγματος μᾶλλον ἠνώχλησε τοὺς ἀνθρώπους. ἔνιοι δὲ τοῦτο Θετταλοῖς, οὐκ Ἀθηναίοις, ὑπ’ αὐτοῦ συμβῆναι λέγουσι. χωρὶς δὲ τούτων αὐτὴ καθ’ ἑαυτὴν ἡ Λάμια τῷ βασιλεῖ παρασκευάζουσα δεῖπνον ἠργυρολόγησε πολλούς. καὶ τὸ δεῖπνον οὕτως ἤνθησε τῇ δόξῃ διὰ τὴν πολυτέλειαν ὥστε ὑπὸ Λυγκέως τοῦ Σαμίου συγγεγράφθαι. διὸ καὶ τῶν κωμικῶν τις οὐ φαύλως τὴν Λάμιαν Ἑλέπολιν ἀληθῶς προσεῖπε. Δημοχάρης δ’ ὁ Σόλιος τὸν Δημήτριον αὐτὸν ἐκάλει Μῦθον· εἶναι γὰρ αὐτῷ καὶ Λάμιαν.", "st": "Demetr. 27.1"}, {"sp": "N", "t": "οὐ μόνον δὲ ταῖς γαμεταῖς, ἀλλὰ καὶ τοῖς φίλοις τοῦ Δημητρίου ζῆλον καὶ φθόνον εὐημεροῦσα καὶ στεργομένη παρεῖχεν. ἀφίκοντο γοῦν τινες παρ’ αὐτοῦ κατὰ πρεσβείαν πρὸς Λυσίμαχον, οἷς ἐκεῖνος ἄγων σχολὴν ἐπέδειξεν ἔν τε τοῖς μηροῖς καὶ τοῖς βραχίοσιν ὠτειλὰς βαθείας ὀνύχων λεοντείων· καὶ διηγεῖτο τὴν γενομένην αὐτῷ μάχην πρὸς τὸ θηρίον, ὑπὸ Ἀλεξάνδρου συγκαθειρχθέντι τοῦ βασιλέως. οἱ δὲ γελῶντες ἔφασαν καὶ τὸν αὑτῶν βασιλέα δεινοῦ θηρίου δήγματα φέρειν ἐν τῷ τραχήλῳ, Λαμίας. ἦν δὲ θαυμαστὸν ὅτι τῆς φίλας ἐν ἀρχῇ τὸ μὴ καθ’ ἡλικίαν δυσχεραίνων, ἥττητο τῆς Λαμίας, καὶ τοσοῦτον ἤρα χρόνον, ἤδη παρηκμακυίας. Δημὼ γοῦν, ἡ ἐπικαλουμένη Μανία, παρὰ δεῖπνον αὐλούσης τῆς Λαμίας καὶ τοῦ Δημητρίου πυθομένου, τί σοι δοκεῖ; Γραῦς, εἶπεν, ὦ βασιλεῦ. πάλιν δὲ τραγημάτων παρατεθέντων κἀκείνου πρὸς αὐτὴν εἰπόντος, ὁρᾷς ὅσα μοι Λάμια πέμπει; πλείονα, ἔφη, πεμφθήσεταί σοι παρὰ τῆς ἐμῆς μητρός, ἐὰν θέλῃς καὶ μετ’ αὐτῆς καθεύδειν. ἀπομνημονεύεται δὲ τῆς Λαμίας καὶ πρὸς τὴν λεγομένην Βοκχώρεως κρίσιν ἀντίρρησις. ἐπεὶ γάρ τις ἐρῶν ἐν Αἰγύπτῳ τῆς ἑταίρας Θώνιδος ᾐτεῖτο συχνὸν χρυσίον, εἶτα κατὰ τοὺς ὕπνους δόξας αὐτῇ συγγενέσθαι τῆς ἐπιθυμίας ἐπαύσατο, δίκην ἔλαχεν ἡ Θωνὶς αὐτῷ τοῦ μισθώματος. ἀκούσας δὲ τὸν λόγον ὁ Βόκχωρις ἐκέλευσε τὸν ἄνθρωπον ὅσον ᾐτήθη χρυσίον ἠριθμημένον ἐν τῷ ἀγγείῳ διαφέρειν δεῦρο κᾀκεῖσε τῇ χειρί, τὴν δὲ ἑταίραν ἔχεσθαι τῆς σκιᾶς, ὡς τὴν δόξαν τῆς ἀληθείας σκιὰν οὖσαν. οὐκ ᾤετο ταύτην εἶναι τὴν κρίσιν ἡ Λάμια δικαίαν· οὐ γὰρ ἀπέλυσεν ἡ σκιὰ τῆς ἐπιθυμίας τοῦ ἀργυρίου τὴν ἑταίραν, τὸ δὲ ὄναρ ἔπαυσεν ἐρῶντα τὸν νεανίσκον. ταῦτα μὲν οὖν περὶ Λαμίας.", "st": "Demetr. 27.3"}, {"sp": "N", "t": "τὴν δὲ διήγησιν, ὥσπερ ἐκ κωμικῆς σκηνῆς, πάλιν εἰς τραγικὴν μετάγουσιν αἱ τύχαι καὶ αἱ πράξεις τοῦ ἀνδρὸς ὃν διηγούμεθα. τῶν γὰρ ἄλλων βασιλέων ἁπάντων συνισταμένων ἐπὶ τὸν Ἀντίγονον καὶ συμφερόντων εἰς ταὐτὸ τὰς δυνάμεις, ἀπῆρεν ὁ Δημήτριος ἐκ τῆς Ἑλλάδος, καὶ τῷ πατρὶ συμμίξας φιλοτιμουμένῳ παρ’ ἡλικίαν πρὸς τὸν πόλεμον, ἔτι μᾶλλον αὐτὸς ἐπερρώσθη. καίτοι δοκεῖ γε Ἀντίγονος, εἰ μικρῶν τινων ὑφεῖτο καὶ τῆς ἄγαν φιλαρχίας ἐχάλασε, μέχρι παντὸς ἂν αὑτῷ διαφυλάξαι κἀκείνῳ καταλιπεῖν τὸ πρῶτον εἶναι. φύσει δὲ βαρὺς ὢν καὶ ὑπερόπτης, καὶ τοῖς λόγοις οὐχ ἧττον ἢ τοῖς πράγμασι τραχύς, πολλοὺς καὶ νέους καὶ δυνατοὺς ἄνδρας ἐξηγρίαινε καὶ παρώξυνε· καὶ τήν γε τότε σύστασιν καὶ κοινωνίαν αὐτῶν ἔλεγεν ὥσπερ ὀρνίθων σπερμολόγων συνδρομὴν ἑνὶ λίθῳ καὶ ψόφῳ συνδιαταράξειν.", "st": "Demetr. 28.1"}, {"sp": "N", "t": "ἦγε δὲ πεζοὺς μὲν ἑπτακισμυρίων πλείους, ἱππεῖς δὲ μυρίους, ἐλέφαντας δὲ ἑβδομήκοντα πέντε, τῶν ἐναντίων ἐχόντων πεζοὺς μὲν ἑξακισμυρίους καὶ τετρακισχιλίους, ἱππεῖς δὲ πεντακοσίους τῶν ἐκείνου πλείονας, ἐλέφαντας δὲ τετρακοσίους, ἅρματα δὲ ἑκατὸν εἴκοσι. γενομένῳ δ’ ἐγγὺς αὐτῶν τροπὴν ἔσχεν ἡ διάνοια τῆς ἐλπίδος μᾶλλον ἢ τῆς γνώμης. ὑψηλὸς γὰρ εἶναι καὶ γαῦρος εἰωθὼς ἐν τοῖς ἀγῶσι καὶ χρώμενος φωνῇ τε μεγάλῃ καὶ λόγοις σοβαροῖς, πολλάκις δὲ καὶ τῷ παρασκῶψαί τι καὶ γελοῖον εἰπεῖν τῶν πολεμίων ἐν χερσὶν ὄντων ἐπιδειξάμενος εὐστάθειαν καὶ καταφρόνησιν, τότε σύννους ἑωρᾶτο καὶ σιωπηλὸς τὰ πολλά, καὶ τὸν υἱὸν ἀπέδειξε τῷ πλήθει καὶ συνέστησε διάδοχον. ὃ δὲ μάλιστα πάντες ἐθαύμασαν, ἐν τῇ σκηνῇ μόνος διελέχθη πρὸς αὐτόν, οὐκ εἰθισμένος ἔχειν οὐδὲ πρὸς ἐκεῖνον ἀπορρήτους κοινολογίας, ἀλλὰ ἴδιος ὢν γνώμῃ, εἶτα προστάττων φανερῶς καὶ χρώμενος οἷς βουλεύσαιτο καθ’ ἑαυτόν. λέγεται γοῦν μειράκιον ἔτι ὄντα τὸν Δημήτριον αὐτοῦ πυθέσθαι πότε μέλλουσιν ἀναζευγνύειν· τὸν δὲ εἰπεῖν πρὸς ὀργήν· ἀγωνιᾷς μὴ μόνος σὺ τῆς σάλπιγγος οὐκ ἀκούσῃς;", "st": "Demetr. 28.3"}, {"sp": "N", "t": "τότε μέντοι καὶ σημεῖα μοχθηρὰ κατεδουλοῦτο τὴν γνώμην αὐτῶν. Δημήτριος μὲν γὰρ ἔδοξε κατὰ τοὺς ὕπνους Ἀλέξανδρον ὡπλισμένον λαμπρῶς ἐρωτᾶν ὁποῖόν τι σύνθημα διδόναι πρὸς τὴν μάχην μέλλουσιν· αὐτοῦ δὲ φήσαντος, Δία καὶ Νίκην ἄπειμι τοίνυν, φάναι, πρὸς τοὺς ἐναντίους· ἐκεῖνοι γάρ με παραλαμβάνουσιν. Ἀντίγονος δὲ παραταττομένης ἤδη τῆς φάλαγγος ἐξιὼν προσέπταισεν, ὥστε πεσεῖν ὅλως ἐπὶ στόμα καὶ διατεθῆναι χαλεπῶς· ἀναστὰς δὲ καὶ τὰς χεῖρας ἀνατείνας πρὸς τὸν οὐρανὸν ᾐτήσατο νίκην παρὰ τῶν θεῶν ἢ θάνατον ἀναίσθητον πρὸ τῆς ἥττης.", "st": "Demetr. 29.1"}, {"sp": "N", "t": "γενομένης δὲ τῆς μάχης ἐν χερσὶ Δημήτριος ἔχων τοὺς πλείστους καὶ κρατίστους τῶν ἱππέων Ἀντιόχῳ τῷ Σελεύκου συνέπεσε, καὶ μέχρι τροπῆς τῶν πολεμίων λαμπρῶς ἀγωνισάμενος ἐν τῇ διώξει σοβαρᾷ καὶ φιλοτίμῳ παρὰ καιρὸν γενομένῃ τὴν νίκην διέφθειρεν. αὐτὸς μὲν γὰρ οὐκ ἔσχε πάλιν ἀναστρέψας συμμῖξαι τοῖς πεζοῖς τῶν ἐλεφάντων ἐν μέσῳ γενομένων, τὴν δὲ φάλαγγα γυμνὴν ἱππέων κατιδόντες οἱ περὶ Σέλευκον οὐκ ἐνέβαλον μέν, ὡς δὲ ἐμβαλοῦντες ἐφόβουν καὶ περιήλαυνον, μεταβάλλεσθαι διδόντες αὐτοῖς· ὃ καὶ συνέβη. πολὺ γὰρ μέρος ἀπορραγὲν ἑκουσίως μετεχώρησε πρὸς ἐκείνους, τὸ δὲ λοιπὸν ἐτράπη. φερομένων δὲ πολλῶν ἐπὶ τὸν Ἀντίγονον καί τινος τῶν περὶ αὐτὸν εἰπόντος, ἐπὶ σὲ οὗτοι, βασιλεῦ, τίνα γάρ, εἶπε, πλὴν ἐμοῦ σκοπὸν ἔχουσιν; ἀλλὰ Δημήτριος ἀφίξεται βοηθῶν. καὶ τοῦτο μέχρι παντὸς ἐλπίζων καὶ περισκοπῶν τὸν υἱὸν ἅμα πολλῶν ἀκοντισμάτων εἰς αὐτὸν ἀφεθέντων ἔπεσε· καὶ τῶν ἄλλων ἀπολιπόντων ὀπαδῶν καὶ φίλων μόνος παρέμεινε τῷ νεκρῷ Θώραξ ὁ Λαρισσαῖος.", "st": "Demetr. 29.3"}, {"sp": "N", "t": "οὕτω δὲ κριθείσης τῆς μάχης, οἱ μὲν νενικηκότες βασιλεῖς τὴν ὑπ’ Ἀντιγόνῳ καὶ Δημητρίῳ πᾶσαν ἀρχὴν ὥσπερ μέγα σῶμα κατακόπτοντες ἐλάμβανον μερίδας, καὶ προσδιενείμαντο τὰς ἐκείνων ἐπαρχίας αἷς εἶχον αὐτοὶ πρότερον. Δημήτριος δὲ μετὰ πεντακισχιλίων πεζῶν καὶ τετρακισχιλίων ἱππέων φεύγων καὶ συντόνως ἐλάσας εἰς Ἔφεσον, οἰομένων ἁπάντων ἀποροῦντα χρημάτων αὐτὸν οὐκ ἀφέξεσθαι τοῦ ἱεροῦ, φοβηθεὶς τοὺς στρατιώτας μὴ τοῦτο ποιήσωσιν, ἀνέστη διὰ ταχέων, καὶ τὸν πλοῦν ἐπὶ τῆς Ἑλλάδος ἐποιεῖτο, τῶν λοιπῶν ἐλπίδων ἐν Ἀθηναίοις ἔχων τὰς μεγίστας. καὶ γὰρ καὶ ναῦς ἐκεῖ καὶ χρήματα καὶ γυναῖκα Δηϊδάμειαν ἐτύγχανε καταλελοιπώς, καὶ βεβαιοτέραν οὐκ ἐνόμιζε καταφυγὴν εἶναι τοῖς πράγμασι τῆς Ἀθηναίων εὐνοίας. ὅθεν ἐπεὶ γενομένῳ περὶ τὰς Κυκλάδας αὐτῷ πρέσβεις Ἀθηναίων ἀπήντησαν ἀπέχεσθαι τῆς πόλεως παρακαλοῦντες, ὡς ἐψηφισμένου τοῦ δήμου μηδένα δέχεσθαι τῇ πόλει τῶν βασιλέων, τὴν δὲ Δηϊδάμειαν εἰς Μέγαρα ἐξέπεμψαν μετὰ τιμῆς καὶ πομπῆς πρεπούσης, τοῦ καθεστηκότος ἐξέστη δι’ ὀργὴν αὐτοῦ, καίπερ ἐνηνοχὼς ῥᾷστα τὴν ἄλλην ἀτυχίαν καὶ γεγονὼς ἐν τοιαύτῃ μεταβολῇ πραγμάτων οὐ ταπεινὸς οὐδ’ ἀγεννής. ἀλλὰ τὸ παρ’ ἐλπίδα διεψεῦσθαι τῶν Ἀθηναίων καὶ τὴν δοκοῦσαν εὔνοιαν ἐξεληλέγχθαι τοῖς πράγμασι κενὴν καὶ πεπλασμένην οὖσαν ὀδυνηρὸν ἦν αὐτῷ.", "st": "Demetr. 30.1"}, {"sp": "N", "t": "τὸ γὰρ φαυλότατον, ὡς ἔοικεν, εὐνοίας ὄχλων βασιλεῦσι καὶ δυνάσταις τεκμήριόν ἐστιν ὑπερβολὴ τιμῶν, ἧς ἐν τῇ προαιρέσει τῶν ἀποδιδόντων ἐχούσης τὸ καλὸν ἀφαιρεῖ τὴν πίστιν ὁ φόβος· τὰ γὰρ αὐτὰ καὶ δεδιότες ψηφίζονται καὶ φιλοῦντες. διόπερ οἱ νοῦν ἔχοντες οὐκ εἰς ἀνδριάντας οὐδὲ γραφὰς οὐδὲ ἀποθεώσεις, ἀλλὰ μᾶλλον εἰς τὰ ἔργα καὶ τὰς πράξεις τὰς ἑαυτῶν ἀποβλέποντες ἢ πιστεύουσιν, ὡς τιμαῖς, ἢ ἀπιστοῦσιν, ὡς ἀνάγκαις· ὡς οἵ γε δῆμοι πολλάκις ἐν αὐταῖς μάλιστα ταῖς τιμαῖς μισοῦσι τοὺς ἀμέτρως καὶ ὑπερόγκως καὶ παρ’ ἀκόντων λαμβάνοντας.", "st": "Demetr. 30.5"}, {"sp": "N", "t": "ὁ γοῦν Δημήτριος τότε δεινὰ μὲν ἡγούμενος πάσχειν, ἀδύνατος δὲ ὢν ἀμύνασθαι, προσέπεμψε τοῖς Ἀθηναίοις ἐγκαλῶν μετρίως, ἀξιῶν δὲ τὰς ναῦς ἀπολαβεῖν, ἐν αἷς ἦν καὶ ἡ τρισκαιδεκήρης. κομισάμενος δὲ παρέπλευσεν εἰς Ἰσθμόν, καὶ τῶν πραγμάτων αὐτῷ κακῶς ἐχόντων (ἐξέπιπτον γὰρ ἑκασταχόθεν αἱ φρουραὶ καὶ μεθίστατο πάντα πρὸς τοὺς πολεμίους) ἀπολιπὼν ἐπὶ τῆς Ἑλλάδος Πύρρον αὐτὸς ἄρας ἐπὶ τὴν Χερρόνησον ἔπλευσε· καὶ κακῶς ἅμα ποιῶν Λυσίμαχον ὠφέλει καὶ συνεῖχε τὴν περὶ αὑτὸν δύναμιν, ἀρχομένην ἀναλαμβάνειν καὶ γίνεσθαι πάλιν οὐκ εὐκαταφρόνητον. ὁ δὲ Λυσίμαχος ὑπὸ τῶν ἄλλων βασιλέων ἠμελεῖτο, μηδὲν ἐπιεικέστερος ἐκείνου δοκῶν εἶναι, τῷ δὲ μᾶλλον ἰσχύειν καὶ φοβερώτερος.", "st": "Demetr. 31.1"}, {"sp": "N", "t": "οὐ πολλῷ δὲ ὕστερον Σέλευκος ἐμνᾶτο πέμπων τὴν Δημητρίου καὶ Φίλας θυγατέρα Στρατονίκην, ἔχων μὲν ἐξ Ἀπάμας τῆς Περσίδος υἱὸν Ἀντίοχον, οἰόμενος δὲ τὰ πράγματα καὶ διαδόχοις ἀρκεῖν πλείοσι, καὶ δεῖσθαι τῆς πρὸς ἐκεῖνον οἰκειότητος, ἐπεὶ καὶ Λυσίμαχον ἑώρα τῶν Πτολεμαίου θυγατέρων τὴν μὲν ἑαυτῷ, τὴν δὲ Ἀγαθοκλεῖ τῷ υἱῷ λαμβάνοντα. Δημητρίῳ δ’ ἦν ἀνέλπιστος εὐτυχία κηδεῦσαι Σελεύκω. καὶ τὴν κόρην ἀναλαβὼν ἔπλει ταῖς ναυσὶ πάσαις εἰς Συρίαν, τῇ τε ἄλλῃ γῇ προσέχων ἀναγκαίως καὶ τῆς Κιλικίας ἁπτόμενος, ἣν Πλείσταρχος εἶχε μετὰ τὴν πρὸς Ἀντίγονον μάχην ἐξαίρετον αὐτῷ δοθεῖσαν ὑπὸ τῶν βασιλέων· ἦν δὲ Κασάνδρου Πλείσταρχος ἀδελφός. ἀδικεῖσθαι δὲ τὴν χώραν αὑτοῦ νομίζων ὑπὸ Δημητρίου κατὰ τὰς ἀποβάσεις, καὶ μέμψασθαι βουλόμενος τὸν Σέλευκον ὅτι τῷ κοινῷ διαλλάττεται πολεμίῳ δίχα τῶν ἄλλων βασιλέων, ἀνέβη πρὸς αὐτόν.", "st": "Demetr. 31.3"}, {"sp": "N", "t": "αἰσθόμενος δὲ τοῦτο Δημήτριος ὥρμησεν ἀπὸ θαλάσσης ἐπὶ Κυΐνδων· καὶ τῶν χρημάτων εὑρὼν ἔτι λοιπὰ χίλια καὶ διακόσια τάλαντα, ταῦτα συσκευασάμενος καὶ φθάσας ἐμβαλέσθαι διὰ ταχέων ἀνήχθη. καὶ παρούσης ἤδη Φίλας τῆς γυναικὸς αὐτῷ περὶ Ῥωσσὸν ἀπήντησε Σέλευκος. καὶ τὴν ἔντευξιν εὐθὺς ἄδολον καὶ ἀνύποπτον καὶ βασιλικὴν ἐποιοῦντο, πρότερον μὲν Σέλευκος ἑστιάσας ἐπὶ σκηνῆς ἐν τῷ στρατοπέδῳ Δημήτριον, αὖθις δὲ Δημήτριος ἐκεῖνον ἐν τῇ τρισκαιδεκήρει δεξάμενος. ἦσαν δὲ καὶ σχολαὶ καὶ κοινολογίαι καὶ συνδιημερεύσεις ἀφρούρων καὶ ἀνόπλων, ἄχρι οὗ Σέλευκος τὴν Στρατονίκην ἀναλαβὼν λαμπρῶς εἰς Ἀντιόχειαν ἀνέβη. Δημήτριος δὲ Κιλικίαν κατέσχε, καὶ Φίλαν τὴν γυναῖκα πρὸς Κάσανδρον ἔπεμψε τὸν ἀδελφόν, ἀπολυσομένην τὰς Πλειστάρχου κατηγορίας. ἐν δὲ τούτῳ Δηϊδάμεια πλεύσασα πρὸς αὐτὸν ἀπὸ τῆς Ἑλλάδος καὶ συγγενομένη χρόνον οὐ πολὺν ἐξ ἀρρωστίας τινὸς ἐτελεύτησε. γενομένης δὲ πρὸς Πτολεμαῖον διὰ Σελεύκου φιλίας αὐτῷ, ὡμολογήθη Πτολεμαΐδα τὴν Πτολεμαίου θυγατέρα λαβεῖν αὐτὸν γυναῖκα.", "st": "Demetr. 32.1"}, {"sp": "N", "t": "καὶ ταῦτα μὲν ἀστεῖα τοῦ Σελεύκου. Κιλικίαν δὲ ἀξιῶν χρήματα λαβόντα παραδοῦναι Δημήτριον, ὡς οὐκ ἔπειθε, Σιδῶνα καὶ Τύρον ἀπαιτῶν πρὸς ὀργὴν ἐδόκει βίαιος εἶναι καὶ δεινὰ ποιεῖν, εἰ τὴν ἀπ’ Ἰνδῶν ἄχρι τῆς κατὰ Συρίαν θαλάσσης ἅπασαν ὑφ’ αὑτῷ πεποιημένος οὕτως ἐνδεής ἐστιν ἔτι πραγμάτων καὶ πτωχὸς ὡς ὑπὲρ δυεῖν πόλεων ἄνδρα κηδεστὴν καὶ μεταβολῇ τύχης κεχρημένον ἐλαύνειν, λαμπρὰν τῷ Πλάτωνι μαρτυρίαν διδοὺς διακελευομένῳ μὴ τὴν οὐσίαν πλείω, τὴν δὲ ἀπληστίαν ποιεῖν ἐλάσσω τόν γε βουλόμενον ὡς ἀληθῶς εἶναι πλούσιον, ὡς ὅ γε μὴ παύων φιλοπλουτίαν, οὗτος οὔτε πενίας οὔτε ἀπορίας ἀπήλλακται.", "st": "Demetr. 32.4"}, {"sp": "N", "t": "οὐ μὴν ὑπέπτηξε Δημήτριος, ἀλλὰ φήσας οὐδ’ ἂν μυριάκις ἡττηθῇ μάχας ἄλλας ἐν Ἴψῳ γαμβρὸν ἀγαπήσειν ἐπὶ μισθῷ Σέλευκον, τὰς μὲν πόλεις ἐκρατύνατο φρουραῖς, αὐτὸς δὲ πυθόμενος Λαχάρη στασιάζουσιν Ἀθηναίοις ἐπιθέμενον τυραννεῖν, ἤλπιζε ῥᾳδίως ἐπιφανεὶς λήψεσθαι τὴν πόλιν. καὶ τὸ μὲν πέλαγος ἀσφαλῶς διεπεραιώθη μεγάλῳ στόλῳ, παρὰ δὲ τὴν Ἀττικὴν παραπλέων ἐχειμάσθη καὶ τὰς πλείστας ἀπέβαλε τῶν νεῶν, καὶ συνδιεφθάρη πλῆθος ἀνθρώπων οὐκ ὀλίγον. αὐτὸς δὲ σωθεὶς ἥψατο μέν τινος πολέμου πρὸς τοὺς Ἀθηναίους, ὡς δ’ οὐδὲν ἐπέραινε, πέμψας ναυτικὸν αὖθις ἀθροίσοντας αὐτὸς εἰς Πελοπόννησον παρῆλθε καὶ Μεσσήνην ἐπολιόρκει. καὶ προσμαχόμενος τοῖς τείχεσιν ἐκινδύνευσε, καταπελτικοῦ βέλους εἰς τὸ πρόσωπον αὐτῷ καὶ τὸ στόμα διὰ τῆς σιαγόνος ἐμπεσόντος. ἀναληφθεὶς δὲ καὶ πόλεις τινὰς ἀφεστώσας προσαγαγόμενος πάλιν εἰς τὴν Ἀττικὴν ἐνέβαλε, καὶ κρατήσας Ἐλευσῖνος καὶ Ῥαμνοῦντος ἔφθειρε τὴν χώραν, καὶ ναῦν τινα λαβὼν ἔχουσαν σῖτον καὶ εἰσάγουσαν τοῖς Ἀθηναίοις ἐκρέμασε τὸν ἔμπορον καὶ τὸν κυβερνήτην, ὥστε τῶν ἄλλων ἀποτρεπομένων διὰ φόβον σύντονον λιμὸν ἐν ἄστει γενέσθαι, πρὸς δὲ τῷ λιμῷ καὶ τῶν ἄλλων ἀπορίαν. ἁλῶν γοῦν μέδιμνον ὠνοῦντο τετταράκοντα δραχμῶν, ὁ δὲ τῶν πυρῶν μόδιος ὤνιος ἦν τριακοσίων. μικρὰν δὲ τοῖς Ἀθηναίοις ἀναπνοὴν παρέσχον ἑκατὸν πεντήκοντα νῆες φανεῖσαι περὶ Αἴγιναν, ἃς ἔπεμψεν ἐπικούρους αὐτοῖς Πτολεμαῖος. εἶτα Δημητρίῳ πολλῶν μὲν ἐκ Πελοποννήσου, πολλῶν δὲ ἀπὸ Κύπρου νεῶν παραγενομένων, ὥστε συμπάσας ἀθροισθῆναι τριακοσίας, ἔφυγον ἄραντες οἱ Πτολεμαίου, καὶ Λαχάρης ὁ τύραννος ἀπέδρα προέμενος τὴν πόλιν.", "st": "Demetr. 33.1"}, {"sp": "N", "t": "οἱ δὲ Ἀθηναῖοι, καίπερ ψηφισάμενοι θάνατον εἰ μνησθείη τις εἰρήνης καὶ διαλλαγῆς πρὸς Δημήτριον, εὐθὺς ἀνεῴγνυσαν τὰς ἐγγὺς πύλας καὶ πρέσβεις ἔπεμπον, οὐδὲν μὲν ἀπ’ ἐκείνου χρηστὸν προσδοκῶντες, ἐκβιαζομένης δὲ τῆς ἀπορίας, ἐν ᾗ δυσχερῶν πολλῶν συμπεσόντων λέγεταί τι καὶ τοιοῦτον γενέσθαι· πατέρα καὶ υἱὸν ἐν οἰκήματι καθέζεσθαι τὰ καθ’ ἑαυτοὺς ἀπεγνωκότας, ἐκ δὲ τῆς ὀροφῆς μῦν νεκρὸν ἐκπεσεῖν, τοὺς δέ, ὡς εἶδον, ἀναπηδήσαντας ἀμφοτέρους διαμάχεσθαι περὶ αὐτοῦ. τότε καὶ τὸν φιλόσοφον Ἐπίκουρον ἱστοροῦσι διαθρέψαι τοὺς συνήθεις κυάμους πρὸς ἀριθμὸν μετ’ αὐτῶν διανεμόμενον.", "st": "Demetr. 34.1"}, {"sp": "N", "t": "οὕτως οὖν τῆς πόλεως ἐχούσης εἰσελθὼν ὁ Δημήτριος, καὶ κελεύσας εἰς τὸ θέατρον ἀθροισθῆναι πάντας, ὅπλοις μὲν συνέφραξε τὴν σκηνὴν καὶ δορυφόροις τὸ λογεῖον περιέλαβεν, αὐτὸς δὲ καταβάς, ὥσπερ οἱ τραγῳδοί, διὰ τῶν ἄνω παρόδων, ἔτι μᾶλλον ἐκπεπληγμένων τῶν Ἀθηναίων τὴν ἀρχὴν τοῦ λόγου πέρας ἐποιήσατο τοῦ δέους αὐτῶν. καὶ γὰρ τόνου φωνῆς καὶ ῥημάτων πικρίας φεισάμενος, ἐλαφρῶς δὲ καὶ φιλικῶς μεμψάμενος αὐτοὺς διηλλάσσετο, καὶ δέκα μυριάδας σίτου μεδίμνων ἐπέδωκε, καὶ κατέστησεν ἀρχὰς αἳ μάλιστα τῷ δήμῳ προσφιλεῖς ἦσαν. συνιδὼν δὲ Δρομοκλείδης ὁ ῥήτωρ ὑπὸ χαρᾶς τὸν δῆμον ἔν τε φωναῖς ὄντα παντοδαπαῖς καὶ τοὺς ἀπὸ τοῦ βήματος ἐπαίνους τῶν δημαγωγῶν ἁμιλλώμενον ὑπερβαλέσθαι, γνώμην ἔγραψε Δημητρίῳ τῷ βασιλεῖ τὸν Πειραιᾶ παραδοθῆναι καὶ τὴν Μουνυχίαν. ἐπιψηφισθέντων δὲ τούτων ὁ Δημήτριος αὐτὸς ἐφ’ ἑαυτοῦ προσενέβαλε φρουρὰν εἰς τὸ Μουσεῖον, ὡς μὴ πάλιν ἀναχαιτίσαντα τὸν δῆμον ἀσχολίας αὐτῷ πραγμάτων ἑτέρων παρασχεῖν.", "st": "Demetr. 34.3"}, {"sp": "N", "t": "ἐχομένων δὲ τῶν Ἀθηνῶν εὐθὺς ἐπεβούλευε τῇ Λακεδαίμονι. καὶ περὶ Μαντίνειαν Ἀρχιδάμου τοῦ βασιλέως ἀπαντήσαντος αὐτῷ νικήσας μάχῃ καὶ τρεψάμενος εἰς τὴν Λακωνικὴν ἐνέβαλε. καὶ πρὸς αὐτῇ τῇ Σπάρτῃ πάλιν ἐκ παρατάξεως ἑλὼν πεντακοσίους καὶ διαφθείρας διακοσίους, ὅσον οὔπω τὴν πόλιν ἔχειν ἐδόκει μέχρι τῶν χρόνων ἐκείνων ἀνάλωτον οὖσαν. ἀλλ’ ἡ τύχη περὶ οὐδένα τῶν βασιλέων ἔοικεν οὕτω τροπὰς λαβεῖν μεγάλας καὶ ταχείας, οὐδ’ ἐν ἑτέροις πράγμασι τοσαυτάκις μικρὰ καὶ πάλιν μεγάλη καὶ ταπεινὴ μὲν ἐκ λαμπρᾶς, ἰσχυρὰ δὲ αὖθις ἐκ φαύλης γενέσθαι. διὸ καί φασιν αὐτὸν ἐν ταῖς χείροσι μεταβολαῖς πρὸς τὴν τύχην ἀναφθέγγεσθαι τὸ Αἰσχύλειον·", "st": "Demetr. 35.1"}, {"sp": "N", "t": "σύ τοί με φυσᾷς, σύ με καταίθειν μοι δοκεῖς.", "st": "Demetr. 35.1b"}, {"sp": "N", "t": "καὶ γὰρ τότε τῶν πραγμάτων οὕτως εὐπόρων αὐτῷ πρὸς ἀρχὴν καὶ δύναμιν ἐπιδιδόντων ἀγγέλλεται Λυσίμαχος μὲν πρῶτος ἀφῃρημένος αὐτοῦ τὰς ἐν Ἀσίᾳ πόλεις, Κύπρον δὲ Πτολεμαῖος ᾑρηκὼς ἄνευ μιᾶς πόλεως Σαλαμῖνος, ἐν δὲ Σαλαμῖνι πολιορκῶν τοὺς παῖδας αὐτοῦ καὶ τὴν μητέρα κατειλημμένους. οὐ μὴν ἀλλὰ καὶ ἡ τύχη, καθάπερ ἡ παρ’ Ἀρχιλόχῳ γυνὴ τῇ μὲν ὕδωρ ἐφόρει δολοφρονέουσα χειρί, τῇ δ’ ἑτέρῃ πῦρ, δεινοῖς αὐτὸν οὕτω καὶ φοβεροῖς ἀγγέλμασιν ἀποστήσασα τῆς Λακεδαίμονος, εὐθὺς ἑτέρας πραγμάτων καινῶν καὶ μεγάλων ἐπήνεγκεν ἐλπίδας ἐκ τοιαύτης αἰτίας.", "st": "Demetr. 35.3"}, {"sp": "N", "t": "ἐπεὶ Κασάνδρου τελευτήσαντος ὁ πρεσβύτατος αὐτοῦ τῶν παίδων Φίλιππος οὐ πολὺν χρόνον βασιλεύσας Μακεδόνων ἀπέθανεν, οἱ λοιποὶ δύο πρὸς ἀλλήλους ἐστασίαζον, θατέρου δὲ αὐτῶν Ἀντιπάτρου τὴν μητέρα Θεσσαλονίκην φονεύσαντος, ἅτερος ἐκάλει βοηθοὺς ἐκ μὲν Ἠπείρου Πύρρον, ἐκ δὲ Πελοποννήσου Δημήτριον. ἔφθασε δὲ Πύρρος ἐλθών, καὶ πολὺ μέρος Μακεδονίας ἀποτεμόμενος τῆς βοηθείας μισθὸν φοβερὸς μὲν ἦν ἤδη παροικῶν Ἀλεξάνδρῳ· Δημητρίου δέ, ὡς ἐδέξατο τὰ γράμματα, μετὰ τῆς δυνάμεως προσιόντος, ἔτι μᾶλλον ὁ νεανίας τοῦτον φοβηθεὶς διὰ τὸ ἀξίωμα καὶ τὴν δόξαν ἀπήντησεν αὐτῷ περὶ Δῖον, ἀσπαζόμενος μὲν καὶ φιλοφρονούμενος, οὐδὲν δὲ φάσκων ἔτι τῆς ἐκείνου δεῖσθαι τὰ πράγματα παρουσίας. ἦσαν οὖν ἐκ τούτων ὑποψίαι πρὸς ἀλλήλους αὐτοῖς, καὶ βαδίζοντι Δημητρίῳ πρὸς δεῖπνον ὑπὸ τοῦ νεανίσκου παρακεκλημένῳ μηνύει τις ἐπιβουλήν, ὡς ἐν αὐτῷ τῷ πότῳ μελλόντων αὐτὸν ἀνελεῖν.", "st": "Demetr. 36.1"}, {"sp": "N", "t": "ὁ δὲ μηδὲν διαταραχθείς, ἀλλὰ μικρὸν ὑφεὶς τῆς πορείας, ἐκέλευσε τοὺς μὲν ἡγεμόνας ἐν τοῖς ὅπλοις τὴν στρατιὰν ἔχειν, ἀκολούθους δὲ καὶ παῖδας, ὅσοι περὶ αὐτὸν ἦσαν (ἦσαν δὲ πολὺ πλείους τῶν Ἀλεξάνδρου), συνεισελθεῖν εἰς τὸν ἀνδρῶνα καὶ παραμένειν ἄχρι ἂν ἐξαναστῇ. τοῦτο δείσαντες οἱ περὶ τὸν Ἀλέξανδρον οὐκ ἐτόλμησαν ἐπιχειρῆσαι. καὶ ὁ μὲν Δημήτριος οὐκ ἔχειν αὐτῷ τὸ σῶμα ποτικῶς σκηψάμενος διὰ ταχέων ἀπῆλθε· τῇ δὲ ὑστεραίᾳ περὶ ἀναζυγὴν εἶχε, πράγματα νεώτερα προσπεπτωκέναι φάμενος αὐτῷ, καὶ παρῃτεῖτο συγγνώμην ἔχειν τὸν Ἀλέξανδρον, εἰ τάχιον ἀπαίρει· συνέσεσθαι γὰρ αὐτῷ μᾶλλον ἄλλοτε σχολάζων. ἔχαιρεν οὖν ὁ Ἀλέξανδρος, ὡς οὐ πρὸς ἔχθραν, ἀλλ’ ἑκουσίως ἐκ τῆς χώρας ἀπαίροντος αὐτοῦ, καὶ προέπεμπεν ἄχρι Θετταλίας. ἐπεὶ δὲ εἰς Λάρισσαν ἧκον, αὖθις ἀλλήλοις ἐπήγγελλον ἑστιάσεις ἀντεπιβουλεύοντες·", "st": "Demetr. 36.4"}, {"sp": "N", "t": "ὃ δὴ μάλιστα τὸν Ἀλέξανδρον ὑποχείριον ἐποίησε τῷ Δημητρίῳ. φυλάττεσθαι γὰρ ὀκνῶν, ὡς μὴ κἀκεῖνον ἀντιφυλάττεσθαι διδάξῃ, παθὼν ἔφθασε (δρᾶν μέλλοντος αὐτοῦ μὴ διαφυγεῖν ἐκεῖνον) ὃ ἐμηχανᾶτο. κληθεὶς γὰρ ἐπὶ δεῖπνον ἦλθε πρὸς τὸν Δημήτριον. ὡς δὲ ἐκεῖνος ἐξανέστη μεταξὺ δειπνῶν, φοβηθεὶς ὁ Ἀλέξανδρος συνεξανέστη καὶ κατὰ πόδας αὐτῷ πρὸς τὰς θύρας συνηκολούθει. γενόμενος οὖν ὁ Δημήτριος πρὸς ταῖς θύραις κατὰ τοὺς ἑαυτοῦ δορυφόρους καὶ τοῦτο μόνον εἰπών, κόπτε τὸν ἑπόμενον, αὐτὸς μὲν ὑπεξῆλθεν, ὁ δὲ Ἀλέξανδρος ὑπ’ ἐκείνων κατεκόπη καὶ τῶν φίλων οἱ προσβοηθοῦντες, ὧν ἕνα λέγουσι σφαττόμενον εἰπεῖν ὡς ἡμέρᾳ μιᾷ φθάσειεν αὐτοὺς ὁ Δημήτριος.", "st": "Demetr. 36.6"}, {"sp": "N", "t": "ἡ μὲν οὖν νὺξ οἷον εἰκὸς θόρυβον ἔσχεν. ἅμα δὲ ἡμέρᾳ ταραττομένοις τοῖς Μακεδόσι καὶ φοβουμένοις τὴν τοῦ Δημητρίου δύναμιν, ὡς ἐπῄει μὲν οὐδεὶς φοβερός, ὁ δὲ Δημήτριος ἔπεμπε βουλόμενος ἐντυχεῖν καὶ περὶ τῶν πεπραγμένων ἀπολογήσασθαι, θαρρεῖν παρέστη καὶ δέχεσθαι φιλανθρώπως αὐτόν. ὡς δὲ ἦλθεν, οὐ μακρῶν ἐδέησεν αὐτῷ λόγων, ἀλλὰ τῷ μισεῖν μὲν τὸν Ἀντίπατρον, φονέα μητρὸς ὄντα, βελτίονος δὲ ἀπορεῖν, ἐκεῖνον ἀνηγόρευσαν βασιλέα Μακεδόνων, καὶ παραλαβόντες εὐθὺς κατῆγον εἰς Μακεδονίαν. ἦν δὲ καὶ τοῖς οἴκοι Μακεδόσιν οὐκ ἀκούσιος ἡ μεταβολή, μεμνημένοις ἀεὶ καὶ μισοῦσιν ἃ Κάσανδρος εἰς Ἀλέξανδρον τεθνηκότα παρηνόμησεν. εἰ δέ τις ἔτι μνήμη τῆς Ἀντιπάτρου τοῦ παλαιοῦ μετριότητος ὑπελείπετο, καὶ ταύτην Δημήτριος ἐκαρποῦτο Φίλᾳ συνοικῶν καὶ τὸν ἐξ ἐκείνης υἱὸν ἔχων διάδοχον τῆς ἀρχῆς, ἤδη τότε μειράκιον ὄντα καὶ τῷ πατρὶ συστρατευόμενον.", "st": "Demetr. 37.1"}, {"sp": "N", "t": "οὕτω δὲ λαμπρᾷ κεχρημένος εὐτυχίᾳ πυνθάνεται μὲν περὶ τῶν τέκνων καὶ τῆς μητρὸς ὡς μεθεῖνται, δῶρα καὶ τιμὰς Πτολεμαίου προσθέντος αὐτοῖς, πυνθάνεται δὲ περὶ τῆς Σελεύκῳ γαμηθείσης θυγατρὸς ὡς Ἀντιόχῳ τῷ Σελεύκου συνοικεῖ καὶ βασίλισσα τῶν ἄνω βαρβάρων ἀνηγόρευται. συνέβη γάρ, ὡς ἔοικε, τὸν Ἀντίοχον ἐρασθέντα τῆς Στρατονίκης νέας οὔσης, ἤδη δὲ παιδίον ἐχούσης ἐκ τοῦ Σελεύκου, διακεῖσθαι κακῶς καὶ πολλὰ ποιεῖν τῷ πάθει διαμαχόμενον, τέλος δ’ ἑαυτοῦ καταγνόντα δεινῶν μὲν ἐπιθυμεῖν, ἀνήκεστα δὲ νοσεῖν, κεκρατῆσθαι δὲ τῷ λογισμῷ, τρόπον ἀπαλλαγῆς τοῦ βίου ζητεῖν καὶ παραλύειν ἀτρέμα καὶ θεραπείας ἀμελείᾳ καὶ τροφῆς ἀποχῇ τὸ σῶμα, νοσεῖν τινα νόσον σκηπτόμενον. Ἐρασίστρατον δὲ τὸν ἰατρὸν αἰσθέσθαι μὲν οὐ χαλεπῶς ἐρῶντος αὐτοῦ, τὸ δὲ οὗτινος ἐρᾷ δυστόπαστον ὂν ἐξανευρεῖν βουλόμενον ἀεὶ μὲν ἐν τῷ δωματίῳ διημερεύειν, εἰ δέ τις εἰσίοι τῶν ἐν ὥρᾳ μειρακίων ἢ γυναικῶν, ἐγκαθορᾶν τε τῷ προσώπῳ τοῦ Ἀντιόχου καὶ τὰ συμπάσχειν μάλιστα τῇ ψυχῇ τρεπομένῃ πεφυκότα μέρη καὶ κινήματα τοῦ σώματος ἐπισκοπεῖν. ὡς οὖν τῶν μὲν ἄλλων εἰσιόντων ὁμοίως εἶχε, τῆς δὲ Στρατονίκης καὶ καθ’ ἑαυτὴν καὶ μετὰ τοῦ Σελεύκου φοιτώσης πολλάκις ἐγίνετο τὰ τῆς Σαπφοῦς ἐκεῖνα περὶ αὐτὸν πάντα, φωνῆς ἐπίσχεσις, ἐρύθημα πυρῶδες, ὄψεων ὑπολείψεις, ἱδρῶτες ὀξεῖς, ἀταξία καὶ θόρυβος ἐν τοῖς σφυγμοῖς, τέλος δὲ τῆς ψυχῆς κατὰ κράτος ἡττημένης ἀπορία καὶ θάμβος καὶ ὠχρίασις,", "st": "Demetr. 38.1"}, {"sp": "N", "t": "ἐπὶ τούτοις προσλογιζόμενον τὸν Ἐρασίστρατον κατὰ τὸ εἰκὸς ὡς οὐκ ἂν ἑτέρας ἐρῶν βασιλέως υἱὸς ἐνεκαρτέρει τῷ σιωπᾶν μέχρι θανάτου, χαλεπὸν μὲν ἡγεῖσθαι τὸ φράσαι ταῦτα καὶ κατειπεῖν, οὐ μὴν ἀλλὰ πιστεύοντα τῇ πρὸς τὸν υἱὸν εὐνοίᾳ τοῦ Σελεύκου παρακινδυνεῦσαί ποτε, καὶ εἰπεῖν ὡς ἔρως μὲν εἴη τοῦ νεανίσκου τὸ πάθος, ἔρως δὲ ἀδύνατος καὶ ἀνίατος. ἐκπλαγέντος δὲ ἐκείνου καὶ πυθομένου πῶς ἀνίατος, ὅτι νὴ Δία, φάναι τὸν Ἐρασίστρατον, ἐρᾷ τῆς ἐμῆς γυναικός. εἶτα οὐκ ἄν, εἰπεῖν τὸν Σέλευκον, ἐπιδοίης, Ἐρασίστρατε, τῷ ἐμῷ παιδὶ φίλος ὢν τὸν γάμον, καὶ ταῦτα ὁρῶν ἡμᾶς ἐπὶ τούτῳ μόνῳ σαλεύοντας; οὐδὲ γὰρ ἂν σύ, φάναι, τοῦτο πατὴρ ὢν ἐποίησας, εἰ Στρατονίκης Ἀντίοχος ἐπεθύμησε. καὶ τὸν Σέλευκον εἴθε γάρ, ἑταῖρε, εἰπεῖν, ταχὺ μεταστρέψαι τις ἐπὶ ταῦτα καὶ μεταβάλοι θεῶν ἢ ἀνθρώπων τὸ πάθος· ὡς ἐμοὶ καὶ τὴν βασιλείαν ἀφεῖναι καλὸν Ἀντιόχου περιεχομένῳ. ταῦτα ἐμπαθῶς σφόδρα τοῦ Σελεύκου μετὰ πολλῶν δακρύων λέγοντος, ἐμβαλόντα τὴν δεξιὰν αὐτῷ τὸν Ἐρασίστρατον εἰπεῖν ὡς οὐδὲν Ἐρασιστράτου δέοιτο· καὶ γὰρ πατὴρ καὶ ἀνὴρ ὢν καὶ βασιλεὺς αὐτὸς ἅμα καὶ ἰατρὸς εἴη τῆς οἰκίας ἄριστος. ἐκ τούτου τὸν Σέλευκον ἐκκλησίαν ἀθροίσαντα πάνδημον εἰπεῖν ὅτι βούλεται καὶ διέγνωκε τῶν ἄνω πάντων τόπων Ἀντίοχον ἀποδεῖξαι βασιλέα καὶ Στρατονίκην βασιλίδα, ἀλλήλοις συνοικοῦντας· οἴεσθαι δὲ τὸν μὲν υἱὸν εἰθισμένον ἅπαντα πείθεσθαι καὶ κατήκοον ὄντα μηθὲν ἀντερεῖν αὐτῷ πρὸς τὸν γάμον· εἰ δ’ ἡ γυνὴ τῷ μὴ νενομισμένῳ δυσκολαίνοι, παρακαλεῖν τοὺς φίλους ὅπως διδάσκωσιν αὐτὴν καὶ πείθωσι καλὰ καὶ δίκαια τὰ δοκοῦντα βασιλεῖ μετὰ τοῦ συμφέροντος ἡγεῖσθαι. τὸν μὲν οὖν Ἀντιόχου καὶ Στρατονίκης γάμον ἐκ τοιαύτης γενέσθαι προφάσεως λέγουσι.", "st": "Demetr. 38.5"}, {"sp": "N", "t": "Δημήτριος δὲ μετὰ Μακεδονίαν καὶ Θετταλίαν ἦν παρειληφώς. ἔχων δὲ καὶ Πελοποννήσου τὰ πλεῖστα καὶ τῶν ἐκτὸς Ἰσθμοῦ Μέγαρα καὶ Ἀθήνας ἐπὶ Βοιωτοὺς ἐστράτευσε. καὶ πρῶτον μὲν ἐγένοντο συμβάσεις μέτριαι περὶ φιλίας πρὸς αὐτόν· ἔπειτα Κλεωνύμου τοῦ Σπαρτιάτου παραβαλόντος εἰς Θήβας μετὰ στρατιᾶς, ἐπαρθέντες οἱ Βοιωτοί, καὶ Πίσιδος ἅμα τοῦ Θεσπιέως, ὃς ἐπρώτευε δόξῃ καὶ δυνάμει τότε, συμπαρορμῶντος αὐτούς, ἀπέστησαν. ὡς δὲ ταῖς Θήβαις ἐπαγαγὼν τὰς μηχανὰς ὁ Δημήτριος ἐπολιόρκει καὶ φοβηθεὶς ὑπεξῆλθεν ὁ Κλεώνυμος, καταπλαγέντες οἱ Βοιωτοὶ παρέδωκαν ἑαυτούς. ὁ δὲ ταῖς πόλεσιν ἐμβαλὼν φρουρὰν καὶ πραξάμενος πολλὰ χρήματα, καὶ καταλιπὼν αὐτοῖς ἐπιμελητὴν καὶ ἁρμοστὴν Ἱερώνυμον τὸν ἱστορικόν, ἔδοξεν ἠπίως κεχρῆσθαι, καὶ μάλιστα διὰ Πίσιν. ἑλὼν γὰρ αὐτὸν οὐδὲν κακὸν ἐποίησεν, ἀλλὰ καὶ προσαγορεύσας καὶ φιλοφρονηθεὶς πολέμαρχον ἐν Θεσπιαῖς ἀπέδειξεν. οὐ πολλῷ δὲ ὕστερον ἁλίσκεται Λυσίμαχος ὑπὸ Δρομιχαίτου· καὶ πρὸς τοῦτο Δημητρίου κατὰ τάχος ἐξορμήσαντος ἐπὶ Θρᾴκην, ὥσπερ ἔρημα καταληψομένου, πάλιν ἀπέστησαν οἱ Βοιωτοί, καὶ Λυσίμαχος ἅμα διειμένος ἀπηγγέλλετο. ταχέως οὖν καὶ πρὸς ὀργὴν ἀναστρέψας ὁ Δημήτριος εὗρεν ἡττημένους ὑπὸ τοῦ παιδὸς Ἀντιγόνου μάχῃ τοὺς Βοιωτούς, καὶ τὰς Θήβας αὖθις ἐπολιόρκει.", "st": "Demetr. 39.1"}, {"sp": "N", "t": "Πύρρου δὲ Θεσσαλίαν κατατρέχοντος καὶ μέχρι Θερμοπυλῶν παραφανέντος, Ἀντίγονον ἐπὶ τῆς πολιορκίας ἀπολιπὼν αὐτὸς ὥρμησεν ἐπ’ ἐκεῖνον. ὀξέως δὲ φυγόντος, ἐν Θεσσαλίᾳ καταστήσας μυρίους ὁπλίτας καὶ χιλίους ἱππεῖς, αὖθις ἐνέκειτο ταῖς Θήβαις καὶ προσῆγε τὴν λεγομένην ἑλέπολιν, πολυπόνως καὶ κατὰ μικρὸν ὑπὸ βρίθους καὶ μεγέθους μοχλευομένην, ὡς μόλις ἐν δυσὶ μησὶ δύο σταδίους προελθεῖν. τῶν δὲ Βοιωτῶν ἐρρωμένως ἀμυνομένων καὶ τοῦ Δημητρίου πολλάκις φιλονεικίας ἕνεκα μᾶλλον ἢ χρείας μάχεσθαι καὶ κινδυνεύειν τοὺς στρατιώτας ἀναγκάζοντος, ὁρῶν ὁ Ἀντίγονος πίπτοντας οὐκ ὀλίγους καὶ περιπαθῶν, τί, ὦ πάτερ, ἔφη, παραναλισκομένους οὐκ ἀναγκαίως τούτους περιορῶμεν; ὁ δὲ παροξυνθείς, σὺ δέ, ἔφη, τί δυσχεραίνεις; ἢ διάμετρον ὀφείλεις τοῖς ἀποθνήσκουσιν; οὐ μὴν ἀλλὰ καὶ βουλόμενός γε μὴ δοκεῖν ἑτέρων ἀφειδεῖν μόνον, ἀλλὰ καὶ συγκινδυνεύειν τοῖς μαχομένοις, διελαύνεται τὸν τράχηλον ὀξυβελεῖ. καὶ δεινῶς μὲν ἔσχεν, οὐ μὴν ἀνῆκεν, ἀλλὰ εἷλε τὰς Θήβας πάλιν. καὶ παρελθὼν ἀνάτασιν μὲν καὶ φόβον ὡς τὰ δεινότατα πεισομένοις παρέσχεν, ἀνελὼν δὲ τρισκαίδεκα καὶ μεταστήσας τινας ἀφῆκε τοὺς ἄλλους. ταῖς μὲν οὖν Θήβαις οὔπω δέκατον οἰκουμέναις ἔτος ἁλῶναι δὶς ἐν τῷ χρόνῳ τούτῳ συνέπεσε.", "st": "Demetr. 40.1"}, {"sp": "N", "t": "τῶν δὲ Πυθίων καθηκόντων πρᾶγμα καινότατον ἐπέτρεψεν αὑτῷ ποιεῖν ὁ Δημήτριος. ἐπεὶ γὰρ Αἰτωλοὶ τὰ περὶ Δελφοὺς στενὰ κατεῖχον, ἐν Ἀθήναις αὐτὸς ἦγε τὸν ἀγῶνα καὶ τὴν πανήγυριν, ὡς δὴ προσῆκον αὐτόθι μάλιστα τιμᾶσθαι τὸν θεόν, ὃς καὶ πατρῷός ἐστι καὶ λέγεται τοῦ γένους ἀρχηγός.", "st": "Demetr. 40.1b"}, {"sp": "N", "t": "ἐντεῦθεν ἐπανελθὼν εἰς Μακεδονίαν καὶ μήτε αὐτὸς ἄγειν ἡσυχίαν πεφυκὼς τούς τε ἄλλους ὁρῶν ἐν ταῖς στρατείαις μᾶλλον αὐτῷ προσέχοντας, οἴκοι δὲ ταραχώδεις καὶ πολυπράγμονας ὄντας, ἐστράτευσεν ἐπ’ Αἰτωλούς· καὶ τὴν χώραν κακώσας καὶ Πάνταυχον ἐν αὐτῇ μέρος ἔχοντα τῆς δυνάμεως οὐκ ὀλίγον ἀπολιπὼν ἐπὶ Πύρρον αὐτὸς ἐχώρει καὶ Πύρρος ἐπ’ ἐκεῖνον· ἀλλήλων δὲ διαμαρτόντες, ὁ μὲν ἐπόρθει τὴν Ἤπειρον, ὁ δὲ Πανταύχῳ περιπεσὼν καὶ μάχην συνάψας αὐτὸν μὲν ἄχρι τοῦ δοῦναι καὶ λαβεῖν πληγὴν ἐν χερσὶ γενόμενον ἐτρέψατο, τῶν δὲ ἄλλων πολλοὺς μὲν ἀπέκτεινεν, ἐζώγρησε δὲ πεντακισχιλίους. καὶ τοῦτο μάλιστα Δημήτριον ἐκάκωσεν· οὐ γὰρ οὕτω μισηθεὶς ὁ Πύρρος ἀφ’ ὧν ἔπραξεν ὡς θαυμασθεὶς διὰ τὸ πλεῖστα τῇ χειρὶ κατεργάσασθαι, μέγα τε καὶ λαμπρὸν ἔσχεν ἀπὸ τῆς μάχης ἐκείνης ὄνομα παρὰ τοῖς Μακεδόσι· καὶ πολλοῖς ἐπῄει λέγειν τῶν Μακεδόνων ὡς ἐν μόνῳ τούτῳ τῶν βασιλέων εἴδωλον ἐνορῷτο τῆς Ἀλεξάνδρου τόλμης, οἱ δὲ ἄλλοι, καὶ μάλιστα Δημήτριος, ὡς ἐπὶ σκηνῆς τὸ βάρος ὑποκρίνοιντο καὶ τὸν ὄγκον τοῦ ἀνδρός. ἦν δὲ ὡς ἀληθῶς τραγῳδία μεγάλη περὶ τὸν Δημήτριον, οὐ μόνον ἀμπεχόμενον καὶ διαδούμενον περιττῶς καυσίαις διμίτροις καὶ χρυσοπαρύφοις ἁλουργίσιν, ἀλλὰ καὶ περὶ τοῖς ποσὶν ἐκ πορφύρας ἀκράτου συμπεπιλημένης χρυσοβαφεῖς πεποιημένον ἐμβάδας. ἦν δέ τις ὑφαινομένη χλανὶς αὐτῷ πολὺν χρόνον, ἔργον ὑπερήφανον, εἴκασμα τοῦ κόσμου καὶ τῶν κατ’ οὐρανὸν φαινομένων· ὃ κατελείφθη μὲν ἡμιτελὲς ἐν τῇ μεταβολῇ τῶν πραγμάτων, οὐδεὶς δὲ ἐτόλμησεν αὐτῇ χρήσασθαι, καίπερ οὐκ ὀλίγων ὕστερον ἐν Μακεδονίᾳ σοβαρῶν γενομένων βασιλέων.", "st": "Demetr. 41.1"}, {"sp": "N", "t": "οὐ μόνον δὲ τούτοις τοῖς θεάμασιν ἐλύπει τοὺς ἀνθρώπους ἀήθεις ὄντας, ἀλλὰ καὶ τρυφὴν καὶ δίαιταν ἐβαρύνοντο· καὶ μάλιστα δὴ τὸ δυσόμιλον αὐτοῦ καὶ δυσπρόσοδον. ἢ γὰρ οὐ παρεῖχε καιρὸν ἐντυχεῖν, ἢ χαλεπὸς ἦν καὶ τραχὺς ἐντυγχάνουσιν. Ἀθηναίων μὲν γάρ, περὶ οὓς ἐσπουδάκει μάλιστα τῶν Ἑλλήνων, ἔτη δύο πρεσβείαν κατέσχεν· ἐκ Λακεδαίμονος δὲ ἑνὸς πρεσβευτοῦ παραγενομένου καταφρονεῖσθαι δοκῶν ἠγανάκτησεν. ἀστείως μέντοι καὶ Λακωνικῶς ἐκεῖνος, εἰπόντος αὐτοῦ τί σὺ λέγεις; ἕνα Λακεδαιμόνιοι πρεσβευτὴν ἔπεμψαν; ναί, εἶπεν, ὦ βασιλεῦ, πρὸς ἕνα. δόξαντος δὲ αὐτοῦ ποτε δημοτικώτερον ἐξελαύνειν, καὶ πρὸς ἔντευξιν ἔχειν οὐκ ἀηδῶς, συνέδραμόν τινες ἐγγράφους ἀξιώσεις ἀναδιδόντες. δεξαμένου δὲ πάσας καὶ τῇ χλαμύδι συλλαβόντος ἥσθησαν οἱ ἄνθρωποι καὶ παρηκολούθουν· ὡς δὲ ἦλθεν ἐπὶ τὴν τοῦ Ἀξιοῦ γέφυραν, ἀναπτύξας τὴν χλαμύδα πάσας εἰς τὸν ποταμὸν ἐξέρριψε. καὶ τοῦτο δὴ δεινῶς ἠνίασε τοὺς Μακεδόνας ὑβρίζεσθαι δοκοῦντας, οὐ βασιλεύεσθαι, καὶ Φιλίππου μνημονεύοντας, ἢ τῶν μνημονευόντων ἀκούοντας, ὡς μέτριος ἦν περὶ ταῦτα καὶ κοινός. καί ποτε πρεσβυτέρου γυναίου κόπτοντος αὐτὸν ἐν παρόδῳ τινὶ καὶ δεομένου πολλάκις ἀκουσθῆναι, φήσας μὴ σχολάζειν, ἐγκραγόντος ἐκείνου καὶ μὴ βασίλευε εἰπόντος, δηχθεὶς σφόδρα καὶ πρὸς τούτῳ γενόμενος ἀνέστρεψεν εἰς τὴν οἰκίαν, καὶ πάντα ποιησάμενος ὕστερα, τοῖς ἐντυχεῖν βουλομένοις, ἀρξάμενος ἀπὸ τῆς πρεσβύτιδος ἐκείνης, ἐπὶ πολλὰς ἡμέρας ἐσχόλασεν.", "st": "Demetr. 42.1"}, {"sp": "N", "t": "οὐδὲν γὰρ οὕτως βασιλεῖ προσῆκον ὡς τὸ τῆς δίκης ἔργον. Ἄρης μὲν γὰρ τύραννος, ὥς φησι Τιμόθεος, νόμος δὲ πάντων βασιλεὺς κατὰ Πίνδαρόν ἐστι· καὶ τοὺς βασιλεῖς Ὅμηρός φησιν οὐχ ἑλεπόλεις οὐδὲ ναῦς χαλκήρεις, ἀλλὰ θέμιστας παρὰ τοῦ Διὸς λαμβάνοντας ῥύεσθαι καὶ φυλάσσειν, καὶ τοῦ Διὸς οὐ τὸν πολεμικώτατον οὐδὲ τὸν ἀδικώτατον καὶ φονικώτατον τῶν βασιλέων, ἀλλὰ τὸν δικαιότατον ὀαριστὴν καὶ μαθητὴν προσηγόρευκεν. ἀλλὰ Δημήτριος ἔχαιρε τῷ βασιλεῖ τῶν θεῶν ἀνομοιοτάτην ἐπιγραφόμενος προσωνυμίαν· ὁ μὲν γὰρ Πολιεὺς καὶ Πολιοῦχος, ὁ δὲ Πολιορκητὴς ἐπίκλησιν ἔσχεν. οὕτως ἐπὶ τὴν τοῦ καλοῦ χώραν τὸ αἰσχρὸν ὑπὸ δυνάμεως ἀμαθοῦς ἐπελθὸν συνῳκείωσε τῇ δόξῃ τὴν ἀδικίαν.", "st": "Demetr. 42.5"}, {"sp": "N", "t": "ὁ δ’ οὖν Δημήτριος ἐπισφαλέστατα νοσήσας ἐν Πέλλῃ μικροῦ τότε Μακεδονίαν ἀπέβαλε, καταδραμόντος ὀξέως Πύρρου καὶ μέχρις Ἐδέσσης προελθόντος. ἅμα δὲ τῷ κουφότερος γενέσθαι πάνυ ῥᾳδίως ἐξελάσας αὐτὸν ἐποιήσατό τινας ὁμολογίας, οὐ βουλόμενος ἐμποδὼν ὄντι συνεχῶς προσπταίων καὶ τοπομαχῶν ἧττον εἶναι πρὸς οἷς διενοεῖτο. διενοεῖτο δὲ οὐθὲν ὀλίγον, ἀλλὰ πᾶσαν ἀναλαμβάνειν τὴν ὑπὸ τῷ πατρὶ γενομένην ἀρχήν. καὶ τῆς ἐλπίδος ταύτης καὶ τῆς ἐπιβολῆς οὐκ ἀπελείπετο τὰ τῆς παρασκευῆς, ἀλλὰ στρατιᾶς μὲν ἤδη συνετέτακτο πεζῆς μυριάδας δέκα δισχιλίων ἀνδρῶν ἀποδεούσας, καὶ χωρὶς ἱππέας ὀλίγῳ δισχιλίων καὶ μυρίων ἐλάττους. στόλον δὲ νεῶν ἅμα πεντακοσίων καταβαλλόμενος τὰς μὲν ἐν Πειραιεῖ τρόπεις ἔθετο, τὰς δὲ ἐν Κορίνθῳ, τὰς δὲ ἐν Χαλκίδι, τὰς δὲ περὶ Πέλλαν, αὐτὸς ἐπιὼν ἑκασταχόσε καὶ διδάσκων ἃ χρὴ καὶ συντεχνώμενος, ἐκπληττομένων ἁπάντων οὐ τὰ πλήθη μόνον, ἀλλὰ καὶ τὰ μεγέθη τῶν ἔργων. οὐδεὶς γὰρ εἶδεν ἀνθρώπων οὔτε πεντεκαιδεκήρη ναῦν πρότερον οὔτε ἑκκαιδεκήρη, ἀλλ’ ὕστερον τεσσαρακοντήρη Πτολεμαῖος ὁ Φιλοπάτωρ ἐναυπηγήσατο, μῆκος διακοσίων ὀγδοήκοντα πηχῶν, ὕψος δὲ ἕως ἀκροστολίου πεντήκοντα δυεῖν δεόντων, ναύταις δὲ χωρὶς ἐρετῶν ἐξηρτυμένην τετρακοσίοις, ἐρέταις δὲ τετρακισχιλίοις, χωρὶς δὲ τούτων ὁπλίτας δεχομένην ἐπί τε τῶν παρόδων καὶ τοῦ καταστρώματος ὀλίγῳ τρισχιλίων ἀποδέοντας. ἀλλὰ θέαν μόνην ἐκείνη παρέσχε· καὶ μικρὸν ὅσον διαφέρουσα τῶν μονίμων οἰκοδομημάτων, φανῆναι πρὸς ἐπίδειξιν, οὐ χρείαν, ἐπισφαλῶς καὶ δυσέργως ἐκινήθη. τῶν δὲ Δημητρίου νεῶν οὐκ ἦν τὸ καλὸν ἀναγώνιστον, οὐδὲ τῷ περιττῷ τῆς κατασκευῆς ἀπεστεροῦντο τὴν χρείαν, ἀλλὰ τὸ τάχος καὶ τὸ ἔργον ἀξιοθεατότερον τοῦ μεγέθους παρεῖχον.", "st": "Demetr. 43.1"}, {"sp": "N", "t": "αἰρομένης οὖν τοσαύτης δυνάμεως ἐπὶ τὴν Ἀσίαν ὅσην μετ’ Ἀλέξανδρον οὐδεὶς ἔσχε πρότερον, οἱ τρεῖς συνέστησαν ἐπὶ τὸν Δημήτριον, Σέλευκος, Πτολεμαῖος, Λυσίμαχος· ἔπειτα κοινῇ πρὸς Πύρρον ἀποστείλαντες ἐκέλευον ἐξάπτεσθαι Μακεδονίας καὶ μὴ νομίζειν σπονδὰς αἷς Δημήτριος οὐκ ἐκείνῳ τὸ μὴ πολεμεῖσθαι δέδωκεν, ἀλλ’ εἴληφεν ἑαυτῷ τὸ πολεμεῖν οἷς βούλεται πρότερον. δεξαμένου δὲ Πύρρου πολὺς περιέστη πόλεμος ἔτι μέλλοντα Δημήτριον. ἅμα γὰρ τὴν μὲν Ἑλλάδα πλεύσας στόλῳ μεγάλῳ Πτολεμαῖος ἀφίστη, Μακεδονίαν δὲ Λυσίμαχος ἐκ Θρᾴκης, ἐκ δὲ τῆς ὁμόρου Πύρρος ἐμβαλόντες ἐλεηλάτουν. ὁ δὲ τὸν μὲν υἱὸν ἐπὶ τῆς Ἑλλάδος κατέλιπεν, αὐτὸς δὲ βοηθῶν Μακεδονίᾳ πρῶτον ὥρμησεν ἐπὶ Λυσίμαχον.", "st": "Demetr. 44.1"}, {"sp": "N", "t": "ἀγγέλλεται δὲ αὐτῷ Πύρρος ᾑρηκὼς πόλιν Βέροιαν. καὶ τοῦ λόγου ταχέως εἰς τοὺς Μακεδόνας ἐμπεσόντος οὐδὲν ἔτι τῷ Δημητρίῳ κατὰ κόσμον εἶχεν, ἀλλὰ καὶ ὀδυρμῶν καὶ δακρύων καὶ πρὸς ἐκεῖνον ὀργῆς καὶ βλασφημιῶν μεστὸν ἦν τὸ στρατόπεδον, καὶ συμμένειν οὐκ ἤθελον, ἀλλ’ ἀπιέναι, τῷ μὲν λόγῳ πρὸς τὰ οἴκοι, τῇ δὲ ἀληθείᾳ πρὸς τὸν Λυσίμαχον. ἔδοξεν οὖν τῷ Δημητρίῳ Λυσιμάχου μὲν ἀποστῆναι πορρωτάτω, πρὸς δὲ Πύρρον τρέπεσθαι· τὸν μὲν γὰρ ὁμόφυλον εἶναι καὶ πολλοῖς συνήθη δι’ Ἀλέξανδρον, ἔπηλυν δὲ καὶ ξένον ἄνδρα τὸν Πύρρον οὐκ ἂν αὑτοῦ προτιμῆσαι Μακεδόνας. τούτων μέντοι πολὺ διεψεύσθη τῶν λογισμῶν. ὡς γὰρ ἐγγὺς ἐλθὼν τῷ Πύρρῳ παρεστρατοπέδευσεν, ἀεὶ μὲν αὐτοῦ τὴν ἐν τοῖς ὅπλοις λαμπρότητα θαυμάζοντες, ἔκ τε τοῦ παλαιοτάτου καὶ βασιλικώτατον εἰθισμένοι νομίζειν τὸν ἐν τοῖς ὅπλοις κράτιστον, τότε δὲ καὶ πρᾴως κεχρῆσθαι τοῖς ἁλισκομένοις πυνθανόμενοι, πάντως δὲ καὶ πρὸς ἕτερον καὶ πρὸς τοῦτον ἀπαλλαγῆναι τοῦ Δημητρίου ζητοῦντες, ἀπεχώρουν λάθρα καὶ κατ’ ὀλίγους τό γε πρῶτον, εἶτα φανερῶς ἅπαν εἶχε κίνησιν καὶ ταραχὴν τὸ στρατόπεδον,", "st": "Demetr. 44.3"}, {"sp": "N", "t": "τέλος δὲ τῷ Δημητρίῳ τολμήσαντές τινες προσελθεῖν ἐκέλευον ἀπιέναι καὶ σώζειν αὑτόν· ἀπειρηκέναι γὰρ ἤδη Μακεδόνας ὑπὲρ τῆς ἐκείνου τρυφῆς πολεμοῦντας. οὗτοι μετριώτατοι τῶν λόγων ἐφαίνοντο τῷ Δημητρίῳ πρὸς τὴν τῶν ἄλλων τραχύτητα· καὶ παρελθὼν ἐπὶ σκηνήν, ὥσπερ οὐ βασιλεύς, ἀλλ’ ὑποκριτής, μεταμφιέννυται χλαμύδα φαιὰν ἀντὶ τῆς τραγικῆς ἐκείνης, καὶ διαλαθὼν ὑπεχώρησεν. ὁρμησάντων δὲ τῶν πλείστων εὐθὺς ἐφ’ ἁρπαγὴν καὶ πρὸς ἀλλήλους διαμαχομένων καὶ τὴν σκηνὴν διασπώντων, ἐπιφανεὶς ὁ Πύρρος ἐκράτησεν αὐτοβοεὶ καὶ κατέσχε τὸ στρατόπεδον. καὶ γίνεται πρὸς Λυσίμαχον αὐτῷ συμπάσης Μακεδονίας νέμησις, ἑπταετίαν ὑπὸ Δημητρίου βεβαίως ἀρχθείσης.", "st": "Demetr. 44.6"}, {"sp": "N", "t": "οὕτω δὲ τοῦ Δημητρίου τῶν πραγμάτων ἐκπεσόντος καὶ καταφυγόντος εἰς Κασάνδρειαν, ἡ γυνὴ Φίλα περιπαθὴς γενομένη προσιδεῖν μὲν οὐχ ὑπέμεινεν αὖθις ἰδιώτην καὶ φυγάδα τὸν τλημονέστατον βασιλέων Δημήτριον, ἀπειπαμένη δὲ πᾶσαν ἐλπίδα καὶ μισήσασα τὴν τύχην αὐτοῦ βεβαιοτέραν ἐν τοῖς κακοῖς οὖσαν ἢ τοῖς ἀγαθοῖς, πιοῦσα φάρμακον ἀπέθανε. Δημήτριος δὲ ἔτι τῶν λοιπῶν ναυαγίων ἔχεσθαι διανοηθεὶς ἀπῆρεν εἰς τὴν Ἑλλάδα καὶ τοὺς ἐκεῖ στρατηγοὺς καὶ φίλους συνῆγεν.", "st": "Demetr. 45.1"}, {"sp": "N", "t": "ἣν οὖν ὁ Σοφοκλέους Μενέλαος εἰκόνα ταῖς αὑτοῦ τύχαις παρατίθησιν,<br>ἀλλ’ οὑμὸς ἀεὶ πότμος ἐν πυκνῷ θεοῦ<br>τροχῷ κυκλεῖται καὶ μεταλλάσσει φύσιν,<br>ὥσπερ σελήνης δ’ ὄψις εὐφρόνας δύο<br>στῆναι δύναιτ’ ἂν οὔποτ’ ἐν μορφῇ μιᾷ,<br>ἀλλ’ ἐξ ἀδήλου πρῶτον ἔρχεται νέα<br>πρόσωπα καλλύνουσα καὶ πληρουμένη,<br>χὥτανπερ αὑτῆς εὐγενεστάτη φανῇ,<br>πάλιν διαρρεῖ κεἰς τὸ μηδὲν ἔρχεται,", "st": "Demetr. 45.2"}, {"sp": "N", "t": "ταύτῃ μᾶλλον ἄν τις ἀπεικάσαι τὰ Δημητρίου πράγματα καὶ τὰς περὶ αὐτὸν αὐξήσεις καὶ φθίσεις καὶ ἀναπληρώσεις καὶ ταπεινότητας, οὗ γε καὶ τότε παντάπασιν ἀπολείπειν καὶ κατασβέννυσθαι δοκοῦντος ἀνέλαμπεν αὖθις ἡ ἀρχή, καὶ δυνάμεις τινὲς ἐπιρρέουσαι κατὰ μικρὸν ἀνεπλήρουν τὴν ἐλπίδα. καὶ τό γε πρῶτον ἰδιώτης καὶ τῶν βασιλικῶν κοσμίων ἔρημος ἐπεφοίτα ταῖς πόλεσι, καί τις αὐτὸν ἐν Θήβαις τοιοῦτον θεασάμενος ἐχρήσατο τοῖς Εὐριπίδου στίχοις οὐκ ἀηδῶς·", "st": "Demetr. 45.3"}, {"sp": "N", "t": "μορφὴν ἀμείψας ἐκ θεοῦ βροτησίαν<br>πάρεστι Δίρκης νάματ’ Ἰσμηνοῦ θ’ ὕδωρ.", "st": "Demetr. 45.3b"}, {"sp": "N", "t": "ἐπεὶ δὲ ἅπαξ ὥσπερ εἰς ὁδὸν βασιλικὴν τὴν ἐλπίδα κατέστη καὶ συνίστατο πάλιν σῶμα καὶ σχῆμα περὶ αὑτὸν ἀρχῆς, Θηβαίοις μὲν ἀπέδωκε τὴν πολιτείαν, Ἀθηναῖοι δὲ ἀπέστησαν αὐτοῦ. καὶ τόν τε Δίφιλον, ὃς ἦν ἱερεὺς τῶν Σωτήρων ἀναγεγραμμένος, ἐκ τῶν ἐπωνύμων ἀνεῖλον, ἄρχοντας αἱρεῖσθαι πάλιν, ὥσπερ ἦν πάτριον, ψηφισάμενοι, τόν τε Πύρρον ἐκ Μακεδονίας μετεπέμποντο, μᾶλλον ἢ προσεδόκησαν ἰσχύοντα τὸν Δημήτριον ὁρῶντες. ὁ δὲ ὀργῇ μὲν ἐπῆλθεν αὐτοῖς καὶ πολιορκίαν περὶ τὸ ἄστυ συνεστήσατο καρτεράν, Κράτητος δὲ τοῦ φιλοσόφου πεμφθέντος ὑπὸ τοῦ δήμου πρὸς αὐτόν, ἀνδρὸς ἐνδόξου καὶ δυνατοῦ, τὰ μὲν οἷς ὑπὲρ τῶν Ἀθηναίων ἐδεῖτο πεισθείς, τὰ δὲ ἐξ ὧν ἐδίδασκε περὶ τῶν ἐκείνῳ συμφερόντων νοήσας ἔλυσε τὴν πολιορκίαν, καὶ συναγαγὼν ὅσαι νῆες ἦσαν αὐτῷ, καὶ στρατιώτας μυρίους καὶ χιλίους σὺν ἱππεῦσιν ἐμβιβάσας, ἐπὶ τὴν Ἀσίαν ἔπλει, Λυσιμάχου Καρίαν καὶ Λυδίαν ἀποστήσων.", "st": "Demetr. 46.1"}, {"sp": "N", "t": "δέχεται δὲ αὐτὸν Εὐρυδίκη περὶ Μίλητον, ἀδελφὴ Φίλας, ἄγουσα τῶν αὐτῆς καὶ Πτολεμαίου θυγατέρων Πτολεμαΐδα καθωμολογημένην ἐκείνῳ πρότερον διὰ Σελεύκου. ταύτην γαμεῖ Δημήτριος Εὐρυδίκης ἐκδιδούσης. καὶ μετὰ τὸν γάμον εὐθὺς ἐπὶ τὰς πόλεις τρέπεται, πολλῶν μὲν ἑκουσίως προστιθεμένων, πολλὰς δὲ καὶ βιαζόμενος. ἔλαβε δὲ καὶ Σάρδεις· καί τινες τῶν Λυσιμάχου στρατηγῶν ἀπεχώρησαν πρὸς αὐτὸν χρήματα καὶ στρατιὰν κομίζοντες. ἐπερχομένου δὲ Ἀγαθοκλέους τοῦ Λυσιμάχου μετὰ δυνάμεως ἀνέβαινεν εἰς Φρυγίαν, ἐγνωκώς, ἄνπερ Ἀρμενίας ἐπιλάβηται, Μηδίαν κινεῖν καὶ τῶν ἄνω πραγμάτων ἔχεσθαι, πολλὰς ἐξωθουμένῳ περιφυγὰς καὶ ἀναχωρήσεις ἐχόντων. ἑπομένου δὲ Ἀγαθοκλέους ἐν ταῖς συμπλοκαῖς περιῆν, ἐπισιτισμοῦ δὲ καὶ προνομῶν εἰργόμενος ἠπορεῖτο, καὶ τοῖς στρατιώταις δι’ ὑποψίας ἦν ὡς ἐπ’ Ἀρμενίαν καὶ Μηδίαν ἐκτοπίζων. ἅμα δὲ μᾶλλον ὁ λιμὸς ἐπέτεινε, καὶ διαμαρτία τις γενομένη περὶ τὴν τοῦ Λύκου διάβασιν πλῆθος ἀνθρώπων ἁρπασθὲν ὑπὸ τοῦ ῥεύματος ἀπώλεσεν. ὅμως δὲ τοῦ σκώπτειν οὐκ ἀπείχοντο· προγράφει δέ τις αὐτοῦ πρὸ τῆς σκηνῆς τὴν τοῦ Οἰδίποδος ἀρχὴν μικρὸν παραλλάξας·", "st": "Demetr. 46.3"}, {"sp": "N", "t": "τέκνον τυφλοῦ γέροντος Ἀντιγόνου· τίνας<br>χώρους ἀφίγμεθα;", "st": "Demetr. 46.3b"}, {"sp": "N", "t": "τέλος δὲ καὶ νόσου τῷ λιμῷ συνεπιτιθεμένης, ὥσπερ εἴωθεν, ἐπὶ βρώσεις ἀναγκαίας τρεπομένων, τοὺς πάντας οὐκ ἐλάσσονας ὀκτακισχιλίων ἀποβαλὼν ἀνῆγεν ὀπίσω τοὺς λοιπούς· καὶ καταβὰς εἰς Ταρσὸν ἐβούλετο μὲν ἀπέχεσθαι τῆς χώρας, οὔσης ὑπὸ Σελεύκῳ τότε, καὶ πρόφασιν ἐκείνῳ μηδεμίαν παρασχεῖν, ὡς δὲ ἦν ἀμήχανον, ἐν ταῖς ἐσχάταις ὄντων ἀπορίαις τῶν στρατιωτῶν, καὶ τοῦ Ταύρου τὰς ὑπερβολὰς Ἀγαθοκλῆς ἀπετείχισε, γράφει πρὸς Σέλευκον ἐπιστολὴν μακρόν τινα τῆς αὑτοῦ τύχης ὀδυρμόν, εἶτα πολλὴν ἱκεσίαν καὶ δέησιν ἔχουσαν ἀνδρὸς οἰκείου λαβεῖν οἶκτον, ἄξια καὶ πολεμίοις συναλγῆσαι πεπονθότος.", "st": "Demetr. 47.1"}, {"sp": "N", "t": "Ἐπικλασθέντος δέ πως Σελεύκου, καὶ γράψαντος τοῖς ἐκεῖ στρατηγοῖς ὅπως αὐτῷ τε τῷ Δημητρίῳ χορηγίαν βασιλικὴν καὶ τῇ δυνάμει τροφὴν ἄφθονον παρέχωσιν, ἐπελθὼν Πατροκλῆς, ἀνὴρ συνετὸς εἶναι δοκῶν καὶ Σελεύκῳ φίλος πιστός, οὐ τὸ τῆς δαπάνης ἔφη πλεῖστον εἶναι τῶν Δημητρίου στρατιωτῶν τρεφομένων, ἀλλ’ ἐνδιατρίβοντα τῇ χώρᾳ Δημήτριον οὐ καλῶς περιορᾶν αὐτόν, ὃς ἀεὶ βιαιότατος ὢν καὶ μεγαλοπραγμονέστατος βασιλέων νῦν ἐν τύχαις γέγονεν αἳ καὶ τοὺς φύσει μετρίους ἐξάγουσι τολμᾶν καὶ ἀδικεῖν. ἐκ τούτου παροξυνθεὶς ὁ Σέλευκος ἐξώρμησεν εἰς Κιλικίαν μετὰ πολλῆς δυνάμεως. ὁ δὲ Δημήτριος ἐκπλαγεὶς τῇ δι’ ὀλίγου μεταβολῇ τοῦ Σελεύκου καὶ φοβηθείς, ὑπέστειλε τοῖς ὀχυρωτάτοις τοῦ Ταύρου, καὶ διαπεμπόμενος ἠξίου μάλιστα μὲν αὐτὸν περιϊδεῖν τῶν αὐτονόμων τινὰ βαρβάρων κτησάμενον ἀρχήν, ἐν ᾗ καταβιώσεται πλάνης καὶ φυγῆς παυσάμενος, εἰ δὲ μή, τὸν χειμῶνα διαθρέψαι τὴν δύναμιν αὐτόθι, καὶ μὴ πάντων ἐνδεᾶ καὶ γυμνὸν ἐξελαύνειν καὶ προβάλλειν τοῖς πολεμίοις.", "st": "Demetr. 47.3"}, {"sp": "N", "t": "ἐπεὶ δὲ Σέλευκος ταῦτα πάντα ὑποπτεύων ἐκέλευσεν αὐτόν, εἰ βούλεται, δύο μῆνας ἐν τῇ Καταονίᾳ χειμάσαι, δόντα τοὺς πρώτους τῶν φίλων ὁμήρους, ἅμα δὲ τὰς εἰς Συρίαν ἀπετείχιζεν ὑπερβολάς, ἐγκλειόμενος, ὥσπερ θηρίον, ὁ Δημήτριος κύκλῳ καὶ περιβαλλόμενος, ὑπ’ ἀνάγκης τρέπεται πρὸς ἀλκήν, καὶ τήν τε χώραν κατέτρεχε καὶ τῷ Σελεύκῳ προσβάλλοντι συμπλεκόμενος ἀεὶ πλέον εἶχε. καί ποτε τῶν δρεπανηφόρων εἰς αὐτὸν ἀφεθέντων ὑποστὰς τροπὴν ἐποιήσατο, καὶ τῶν εἰς Συρίαν ὑπερβολῶν τοὺς ἀποτειχίζοντας ἐξελάσας ἐκράτησε. καὶ ὅλως ἐπῆρτο τῇ γνώμῃ, καὶ τοὺς στρατιώτας ἀνατεθαρρηκότας ὁρῶν παρεσκευάζετο διαγωνίσασθαι πρὸς τὸν Σέλευκον ἐπὶ τοῖς μεγίστοις ἄθλοις, ἠπορημένον ἤδη καὶ αὐτόν. ἀπέστρεψε μὲν γὰρ τὴν παρὰ Λυσιμάχου βοήθειαν ἀπιστῶν καὶ φοβούμενος, αὐτὸς δὲ καθ’ ἑαυτὸν ὤκνει τῷ Δημητρίῳ συνάψαι, δεδιὼς τὴν ἀπόνοιαν αὐτοῦ καὶ τὴν ἀεὶ μεταβολὴν ἐκ τῶν ἐσχάτων ἀποριῶν τὰς μεγίστας εὐτυχίας ἐπιφέρουσαν.", "st": "Demetr. 48.1"}, {"sp": "N", "t": "νόσος μέντοι βαρεῖα τὸν Δημήτριον ἐν τούτῳ καταλαβοῦσα τό τε σῶμα δεινῶς ἐκάκωσε καὶ τὰ πράγματα παντάπασι διέφθειρεν. οἱ μὲν γὰρ ἀπεχώρησαν πρὸς τοὺς πολεμίους, οἱ δὲ διερρύησαν αὐτοῦ τῶν στρατιωτῶν. μόλις δὲ ἐν ἡμέραις τεσσαράκοντα ῥαΐσας καὶ τοὺς ὑπολοίπους ἀναλαβών, καὶ ὁρμήσας, ὅσον ἰδεῖν καὶ δοξάσαι τοὺς πολεμίους, ἐπὶ Κιλικίας, εἶτα νυκτὸς ἄνευ σάλπιγγος ἄρας ἐπὶ θάτερα καὶ τὸν Ἀμανὸν ὑπερβαλὼν ἐπόρθει τὴν κάτω χώραν ἄχρι τῆς Κυρρηστικῆς.", "st": "Demetr. 48.4"}, {"sp": "N", "t": "ἐπιφανέντος δὲ τοῦ Σελεύκου καὶ ποιουμένου τὰς καταλύσεις ἐγγύς, ἀναστήσας ὁ Δημήτριος τὸ στράτευμα νυκτὸς ἐβάδιζεν ἐπ’ αὐτὸν ἀγνοοῦντα μέχρι πολλοῦ καὶ κοιμώμενον. αὐτομόλων δέ τινων παραγενομένων καὶ φρασάντων τὸν κίνδυνον, ἐκπλαγεὶς καὶ ἀναπηδήσας ἐκέλευσε σημαίνειν, ἅμα τὰς κρηπῖδας ὑποδούμενος καὶ βοῶν πρὸς τοὺς ἑταίρους ὡς θηρίῳ δεινῷ συμπέπλεκται. Δημήτριος δὲ τῷ θορύβῳ τῶν πολεμίων αἰσθόμενος ὅτι μεμήνυται, κατὰ τάχος ἀπῆγεν. ἅμα δ’ ἡμέρᾳ προσκειμένου τοῦ Σελεύκου, πέμψας τινὰ τῶν περὶ αὑτὸν ἐπὶ θάτερον κέρας ἐποίησέ τινα τροπὴν τῶν ἐναντίων. εἶτα μέντοι Σέλευκος αὐτὸς ἀφεὶς τὸν ἵππον καὶ τὸ κράνος ἀποθέμενος καὶ λαβὼν πέλτην ἀπήντα τοῖς μισθοφόροις, ἐπιδεικνύμενος αὑτὸν καὶ μεταβαλέσθαι παρακαλῶν, ἤδη ποτὲ συμφρονήσαντας ὅτι φειδόμενος ἐκείνων, οὐ Δημητρίου, χρόνον πολὺν διατετέλεκεν. ἐκ τούτου πάντες ἀσπαζόμενοι καὶ βασιλέα προσαγορεύοντες μεθίσταντο.", "st": "Demetr. 49.1"}, {"sp": "N", "t": "Δημήτριος δὲ πολλῶν μεταβολῶν αἰσθόμενος ἐσχάτην ἐκείνην ἥκουσαν ἐπ’ αὐτόν, ἐκκλίνας ἐπὶ τὰς Ἀμανίδας ἔφυγε πύλας, καὶ καταβαλὼν εἰς ὕλην τινὰ συνηρεφῆ μετὰ φίλων τινῶν καὶ ἀκολούθων ὀλίγων παντάπασιν ὄντων προσέμενε τὴν νύκτα, βουλόμενος, εἰ δύναιτο, τῆς ἐπὶ Καῦνον ὁδοῦ λαβέσθαι καὶ διεκπεσεῖν ἐπὶ τὴν θάλασσαν, οὗ τὸν ναύσταθμον εὑρήσειν ἤλπιζεν. ὡς δὲ ἔγνω μηδὲ ἐκείνης τῆς ἡμέρας ἐφόδιον ἔχοντας αὐτούς, ἐπ’ ἄλλων ἐγένετο λογισμῶν. εἶτα μέντοι Σωσιγένης ἐπῆλθεν, ἑταῖρος αὐτοῦ, χρυσοῦς τετρακοσίους ὑπεζωσμένος· καὶ ἀπὸ τούτων ἐλπίζοντες ἄχρι θαλάσσης διαγενήσεσθαι, πρὸς τὰς ὑπερβολὰς ἐχώρουν σκοταῖοι. πυρῶν δὲ καιομένων πρὸς αὐταῖς πολεμίων ἀπογνόντες ἐκείνην τὴν ὁδὸν αὖθις ἀνεχώρησαν εἰς τὸν αὐτὸν τόπον, οὔτε πάντες (ἔνιοι γὰρ ἀπέδρασαν) οὔτε ὁμοίως οἱ παραμένοντες πρόθυμοι· τολμήσαντος δέ τινος εἰπεῖν τι, ὡς Σελεύκῳ χρὴ τὸ σῶμα παραδοῦναι Δημήτριον, ὥρμησε μὲν τὸ ξίφος σπασάμενος ἀνελεῖν ἑαυτόν, οἱ δὲ φίλοι περιστάντες καὶ παραμυθούμενοι συνέπεισαν οὕτω ποιῆσαι. καὶ πέμπει πρὸς Σέλευκον ἐπιτρέπων ἐκείνῳ τὰ καθ’ ἑαυτόν.", "st": "Demetr. 49.4"}, {"sp": "N", "t": "ἀκούσας δὲ Σέλευκος οὐκ ἔφη τῇ Δημητρίου τύχῃ σώζεσθαι Δημήτριον, ἀλλὰ τῇ αὑτοῦ, μετὰ τῶν ἄλλων καλῶν αὐτῷ φιλανθρωπίας καὶ χρηστότητος ἐπίδειξιν διδούσῃ. καλέσας δὲ τοὺς ἐπιμελητὰς σκηνήν τε πηγνύναι βασιλικὴν ἐκέλευσε, καὶ τἆλλα πάντα ποιεῖν καὶ παρασκευάζειν εἰς ὑποδοχὴν καὶ θεραπείαν μεγαλοπρεπῶς. ἦν δέ τις Ἀπολλωνίδης παρὰ τῷ Σελεύκῳ, τοῦ Δημητρίου γεγονὼς συνήθης· τοῦτον εὐθὺς ἐξέπεμψε πρὸς αὐτόν, ὅπως ἡδίων γένηται καὶ θαρρῶν ὡς πρὸς οἰκεῖον ἄνδρα καὶ κηδεστὴν ἀπαντᾶν. φανερᾶς δὲ τῆς γνώμης αὐτοῦ γενομένης ὀλίγοι τὸ πρῶτον, εἶτα οἱ πλεῖστοι τῶν φίλων ἐξεπήδων παρὰ τὸν Δημήτριον, ἁμιλλώμενοι καὶ φθάνοντες ἀλλήλους· ἠλπίζετο γὰρ εὐθὺς παρὰ τῷ Σελεύκῳ μέγιστος ἔσεσθαι.", "st": "Demetr. 50.1"}, {"sp": "N", "t": "τοῦτο δὲ ἐκείνῳ μὲν εἰς φθόνον μετέβαλε τὸν ἔλεον, τοῖς δὲ κακοήθεσι καὶ βασκάνοις παρέσχεν ἀποτρέψαι καὶ διαφθεῖραι τὴν φιλανθρωπίαν τοῦ βασιλέως, ἐκφοβήσασιν αὐτόν, ὡς οὐκ εἰς ἀναβολάς, ἀλλ’ ἅμα τῷ πρῶτον ὀφθῆναι τὸν ἄνδρα, μεγάλων ἐσομένων ἐν τῷ στρατοπέδῳ νεωτερισμῶν. ἄρτι δὴ τοῦ Ἀπολλωνίδου πρὸς τὸν Δημήτριον ἀφιγμένου περιχαροῦς, καὶ τῶν ἄλλων ἐπερχομένων καὶ λόγους θαυμαστοὺς ἀπαγγελλόντων περὶ τοῦ Σελεύκου, καὶ τοῦ Δημητρίου μετὰ τηλικαύτην δυστυχίαν καὶ κακοπραγίαν, εἰ καὶ πρότερον ἐδόκει τὴν παράδοσιν τοῦ σώματος αἰσχρὰν πεποιῆσθαι, τότε μετεγνωκότος διὰ τὸ θαρρεῖν καὶ πιστεύειν ταῖς ἐλπίσιν, ἦλθε Παυσανίας ἔχων στρατιώτας ὁμοῦ πεζοὺς καὶ ἱππεῖς περὶ χιλίους. καὶ τούτοις περισχὼν τὸν Δημήτριον ἄφνω, τοὺς δὲ ἄλλους ἀποστήσας, Σελεύκῳ μὲν αὐτὸν εἰς ὄψιν οὐ κατέστησεν, εἰς δὲ Χερρόνησον τὴν Συριακὴν ἀπήγαγεν, ὅπου τὸ λοιπὸν ἰσχυρᾶς φυλακῆς ἐπισταθείσης θεραπεία μὲν ἧκεν ἱκανὴ παρὰ Σελεύκου καὶ χρήματα καὶ δίαιτα παρεσκευάζετο καθ’ ἡμέραν οὐ μεμπτή, δρόμοι δὲ καὶ περίπατοι βασιλικοὶ καὶ παράδεισοι θήρας ἔχοντες ἀπεδείχθησαν· ἦν δὲ καὶ τῶν φίλων τῶν συμφυγόντων τῷ βουλομένῳ συνεῖναι, καὶ παρ’ αὐτὸν τινες ὅμως ἐπιφοιτῶντες ἀπὸ τοῦ Σελεύκου ἧκον κομίζοντες ἐπιεικεῖς λόγους καὶ θαρρεῖν παρακαλοῦντες, ὡς, ὅταν πρῶτον Ἀντίοχος ἀφίκηται σὺν Στρατονίκῃ, διεθησόμενον.", "st": "Demetr. 50.3"}, {"sp": "N", "t": "ὁ δὲ Δημήτριος ἐν τῇ τοιαύτῃ τύχῃ γεγονὼς ἐπέστειλε τοῖς περὶ τὸν υἱὸν καὶ τοῖς περὶ Ἀθήνας καὶ Κόρινθον ἡγεμόσι καὶ φίλοις μήτε γράμμασιν αὐτοῦ μήτε σφραγῖδι πιστεύειν, ἀλλ’ ὥσπερ τεθνηκότος Ἀντιγόνῳ τὰς πόλεις καὶ τὰ λοιπὰ πράγματα διαφυλάττειν. Ἀντίγονος δὲ τὴν τοῦ πατρὸς σύλληψιν πυθόμενος καὶ βαρέως ἐνεγκὼν καὶ πενθίμην ἀναλαβὼν ἐσθῆτα πρός τε τοὺς ἄλλους βασιλεῖς ἔγραψε καὶ πρὸς αὐτὸν Σέλευκον, δεόμενος, καὶ πᾶν ὅ τι λοιπὸν ἦν αὐτοῖς παραδιδούς, καὶ πρὸ παντὸς ὁμηρεύειν ἕτοιμος ὢν αὐτὸς ὑπὲρ τοῦ πατρός. καὶ συνεδέοντο ταῦτα πόλεις τε πολλαὶ καὶ δυνάσται πλὴν Λυσιμάχου. Λυσίμαχος δὲ καὶ χρήματα πολλὰ πέμπων ὑπισχνεῖτο Σελεύκῳ κτείναντι Δημήτριον. ὁ δὲ ἐκεῖνον μὲν καὶ ἄλλως προβαλλόμενος ἔτι μᾶλλον ἐπὶ τούτῳ μιαρὸν ἡγεῖτο καὶ βάρβαρον, Ἀντιόχῳ δὲ τῷ παιδὶ καὶ Στρατονίκῃ φυλάττων Δημήτριον, ὡς ἐκείνων ἡ χάρις γένοιτο, παρῆγε τὸν χρόνον.", "st": "Demetr. 51.1"}, {"sp": "N", "t": "ὁ δὲ Δημήτριος, ὡς ἐν ἀρχῇ τὴν τύχην προσπεσοῦσαν ὑπέμεινε, καὶ ῥᾷον ἤδη φέρειν εἰθίζετο τὰ παρόντα, πρῶτον μὲν ἁμῶς γέ πως ἐκίνει τὸ σῶμα, θήρας, ἐφ’ ὅσον ἦν, καὶ δρόμων ἁπτόμενος, ἔπειτα κατὰ μικρὸν ὄκνου πρὸς αὐτὰ καὶ νωθείας ἐπίμπλατο, καὶ φέρων ἑαυτὸν εἰς πότους καὶ κύβους κατέβαλε καὶ τοῦ χρόνου τὸν πλεῖστον ἐν τούτοις διῆγεν, εἴτε τοὺς ἐν τῷ νήφειν ἀναλογισμοὺς τῶν παρόντων ἀποδιδράσκων καὶ παρακαλυπτόμενος τῇ μέθῃ τὴν διάνοιαν, εἴτε συγγνοὺς ἑαυτῷ τοῦτον εἶναι τὸν βίον, ὃν ἔκπαλαι ποθῶν καὶ διώκων ἄλλως ὑπ’ ἀνοίας καὶ κενῆς δόξης ἐπλάζετο καὶ πολλὰ μὲν ἑαυτῷ, πολλὰ δὲ ἑτέροις πράγματα παρεῖχεν, ἐν ὅπλοις καὶ στόλοις καὶ στρατοπέδοις τὸ ἀγαθὸν ζητῶν, ὃ νῦν ἐν ἀπραγμοσύνῃ καὶ σχολῇ καὶ ἀναπαύσει μὴ προσδοκήσας ἀνεύρηκε. τί γὰρ ἄλλο τῶν πολέμων καὶ τῶν κινδύνων πέρας ἐστὶ τοῖς φαύλοις βασιλεῦσι, κακῶς καὶ ἀνοήτως διακειμένοις, οὐχ ὅτι μόνον τρυφὴν καὶ ἡδονὴν ἀντὶ τῆς ἀρετῆς καὶ τοῦ καλοῦ διώκουσιν, ἀλλ’ ὅτι μηδὲ ἥδεσθαι μηδὲ τρυφᾶν ὡς ἀληθῶς ἴσασιν;", "st": "Demetr. 52.1"}, {"sp": "N", "t": "ὁ δ’ οὖν Δημήτριος ἔτος τρίτον ἐν τῇ Χερρονήσῳ καθειργμένος ὑπ’ ἀργίας καὶ πλησμονῆς καὶ οἴνου νοσήσας ἀπέθανεν, ἔτη τέσσαρα καὶ πεντήκοντα βεβιωκώς. καὶ Σέλευκος ἤκουσέ τε κακῶς καὶ μετενόησεν οὐ μετρίως ἐν ὑποψίᾳ τὸν Δημήτριον θέμενος τότε, καὶ μηδὲ Δρομιχαίτην, ἄνδρα βάρβαρον Θρᾷκα, μιμησάμενος οὕτω φιλανθρώπως καὶ βασιλικῶς ἁλόντι Λυσιμάχῳ χρησάμενον.", "st": "Demetr. 52.4"}, {"sp": "N", "t": "ἔσχε μέντοι καὶ τὰ περὶ τὴν ταφὴν αὐτοῦ τραγικήν τινα καὶ θεατρικὴν διάθεσιν. ὁ γὰρ υἱὸς Ἀντίγονος, ὡς ᾔσθετο τὰ λείψανα κομιζόμενα, πάσαις ἀναχθεὶς ταῖς ναυσὶν ἐπὶ νήσων ἀπήντησε· καὶ δεξάμενος εἰς τὴν μεγίστην τῶν ναυαρχίδων ἔθετο τὴν ὑδρίαν χρυσήλατον οὖσαν. αἱ δὲ πόλεις αἷς προσεῖχον, τοῦτο μὲν στεφάνους ἐπέφερον τῇ ὑδρίᾳ, τοῦτο δὲ ἄνδρας ἐν σχήματι πενθίμῳ συνθάψοντας καὶ συμπαραπέμψοντας ἀπέστελλον. εἰς δὲ Κόρινθον τοῦ στόλου καταπλέοντος ἥ τε κάλπις ἐκ πρύμνης περιφανὴς ἑωρᾶτο πορφύρᾳ βασιλικῇ καὶ διαδήματι κεκοσμημένη, καὶ παρειστήκεισαν ἐν ὅπλοις νεανίσκοι δορυφοροῦντες. ὁ δὲ τῶν τότε αὐλητῶν ἐλλογιμώτατος Ξενόφαντος ἐγγὺς καθεζόμενος προσηύλει τῶν μελῶν τὸ ἱερώτατον· καὶ πρὸς τοῦτο τῆς εἰρεσίας ἀναφερομένης μετὰ ῥυθμοῦ τινος, ἀπήντα ψόφος, ὥσπερ ἐν κοπετῷ, ταῖς τῶν αὐλημάτων περιόδοις· τὸν δὲ πλεῖστον οἶκτον καὶ ὀλοφυρμὸν αὐτὸς ὁ Ἀντίγονος τοῖς ἠθροισμένοις ἐπὶ τὴν θάλασσαν ὀφθεὶς ταπεινὸς καὶ δεδακρυμένος παρέσχεν. ἐπενεχθεισῶν δὲ τιμῶν καὶ στεφάνων περὶ Κόρινθον εἰς Δημητριάδα κομίσας ἔθηκε τὰ λείψανα, πόλιν ἐπώνυμον ἐκείνου, συνοικισθεῖσαν ἐκ μικρῶν τῶν περὶ τὴν Ἰωλκὸν πολιχνίων.", "st": "Demetr. 53.1"}, {"sp": "N", "t": "ἀπέλιπε δὲ γενεὰν ὁ Δημήτριος Ἀντίγονον μὲν ἐκ Φίλας καὶ Στρατονίκην, δύο δὲ Δημητρίους, τὸν μὲν Λεπτόν, ἐξ Ἰλλυρίδος γυναικός, τὸν δὲ ἄρξαντα Κυρήνης ἐκ Πτολεμαΐδος, ἐκ δὲ Δηϊδαμείας Ἀλέξανδρον, ὃς ἐν Αἰγύπτῳ κατεβίωσε. λέγεται δὲ καὶ Κόρραγον υἱὸν ἐξ Εὐρυδίκης αὐτῷ γενέσθαι. κατέβη δὲ ταῖς διαδοχαῖς τὸ γένος αὐτοῦ βασιλεῦον εἰς Περσέα τελευταῖον, ἐφ’ οὗ Ῥωμαῖοι Μακεδονίαν ὑπηγάγοντο.", "st": "Demetr. 53.4"}, {"sp": "N", "t": "διηγωνισμένου δὲ τοῦ Μακεδονικοῦ δράματος ὥρα τὸ Ῥωμαϊκὸν ἐπεισαγαγεῖν.", "st": "Demetr. 53.4b"}, {"sp": "HDR", "t": "Ἀντώνιος"}, {"sp": "N", "t": "Ἀντωνίου πάππος μὲν ἦν ὁ ῥήτωρ Ἀντώνιος, ὃν τῆς Σύλλα γενόμενον στάσεως Μάριος ἀπέκτεινε, πατὴρ δὲ ὁ Κρητικὸς ἐπικληθεὶς Ἀντώνιος, οὐχ οὕτω μὲν εὐδόκιμος ἐν τοῖς πολιτικοῖς ἀνὴρ οὐδὲ λαμπρός, εὐγνώμων δὲ καὶ χρηστός, ἄλλως τε καὶ πρὸς τὰς μεταδόσεις ἐλευθέριος, ὡς ἀφ’ ἑνὸς ἄν τις ἔργου καταμάθοι. κεκτημένος γὰρ οὐ πολλὰ καὶ διὰ τοῦτο τῇ φιλανθρωπίᾳ χρῆσθαι κωλυόμενος ὑπὸ τῆς γυναικός, ἐπεί τις ἀφίκετο τῶν συνήθων πρὸς αὐτὸν ἀργυρίου δεόμενος, ἀργύριον μὲν οὐκ εἶχε, παιδαρίῳ δὲ προσέταξεν εἰς ἀργυροῦν σκύφον ὕδωρ ἐμβαλόντι κομίσαι· καὶ κομίσαντος, ὡς ξύρεσθαι μέλλων κατέβρεχε τὰ γένεια. τοῦ δὲ παιδαρίου καθ’ ἑτέραν πρόφασιν ἐκποδὼν γενομένου, τὸν μὲν σκύφον ἔδωκε τῷ φίλῳ χρῆσθαι κελεύσας, ζητήσεως δὲ πολλῆς ἐν τοῖς οἰκέταις οὔσης ὁρῶν χαλεπαίνουσαν τὴν γυναῖκα καὶ βουλομένην καθ’ ἕκαστον ἐξετάζειν ὡμολόγησε, συγγνώμην ἔχειν δεηθείς.", "st": "Ant. 1.1"}, {"sp": "N", "t": "ἦν δὲ αὐτῷ γυνὴ Ἰουλία τοῦ Καισάρων οἴκου, ταῖς ἀρίσταις τότε καὶ σωφρονεστάταις ἐνάμιλλος. ὑπὸ ταύτης ὁ υἱὸς Ἀντώνιος ἐτράφη μετὰ τὴν τοῦ πατρὸς τελευτὴν Κορνηλίῳ Λέντλῳ γαμηθείσης, ὃν Κικέρων ἀπέκτεινε τῶν Κατιλίνα συνωμοτῶν γενόμενον. αὕτη δοκεῖ τῆς σφοδρᾶς ἔχθρας Ἀντωνίῳ πρὸς Κικέρωνα πρόφασις καὶ ἀρχὴ γενέσθαι. φησὶ γοῦν Ἀντώνιος οὐδὲ τὸν νεκρὸν αὐτοῖς ἀποδοθῆναι τοῦ Λέντλου πρότερον ἢ τῆς γυναικὸς τοῦ Κικέρωνος τὴν μητέρα δεηθῆναι. τοῦτο μὲν οὖν ὁμολογουμένως ψεῦδός ἐστιν· οὐδεὶς γὰρ εἴρχθη ταφῆς τῶν τότε κολασθέντων ὑπὸ τοῦ Κικέρωνος· Ἀντωνίῳ δὲ λαμπρῷ καθ’ ὥραν γενομένῳ τὴν Κουρίωνος φιλίαν καὶ συνήθειαν ὥσπερ τινὰ κῆρα προσπεσεῖν λέγουσιν, αὐτοῦ τε περὶ τὰς ἡδονὰς ἀπαιδεύτου γενομένου, καὶ τὸν Ἀντώνιον, ὡς μᾶλλον εἴη χειροήθης, εἰς πότους καὶ γύναια καὶ δαπάνας πολυτελεῖς καὶ ἀκολάστους ἐμβάλλοντος. ἐξ ὧν ὄφλημα βαρὺ καὶ παρ’ ἡλικίαν αὐτῷ συνήχθη πεντήκοντα καὶ διακοσίων ταλάντων. τοῦτο πᾶν ἐγγυησαμένου τοῦ Κουρίωνος ὁ πατὴρ αἰσθόμενος ἐξήλασε τὸν Ἀντώνιον ἐκ τῆς οἰκίας. ὁ δὲ βραχὺν μέν τινα χρόνον τῇ Κλωδίου τοῦ θρασυτάτου καὶ βδελυρωτάτου τῶν τότε δημαγωγῶν φορᾷ πάντα τὰ πράγματα ταραττούσῃ προσέμιξεν ἑαυτόν· ταχὺ δὲ τῆς ἐκείνου μανίας μεστὸς γενόμενος, καὶ φοβηθεὶς τοὺς συνισταμένους ἐπὶ τὸν Κλώδιον, ἀπῆρεν ἐκ τῆς Ἰταλίας εἰς τὴν Ἑλλάδα, καὶ διέτριβε τό τε σῶμα γυμνάζων πρὸς τοὺς στρατιωτικοὺς ἀγῶνας καὶ λέγειν μελετῶν. ἐχρῆτο δὲ τῷ καλουμένῳ μὲν Ἀσιανῷ ζήλῳ τῶν λόγων, ἀνθοῦντι μάλιστα κατ’ ἐκεῖνον τὸν χρόνον, ἔχοντι δὲ πολλὴν ὁμοιότητα πρὸς τὸν βίον αὐτοῦ, κομπώδη καὶ φρυαγματίαν ὄντα καὶ κενοῦ γαυριάματος καὶ φιλοτιμίας ἀνωμάλου μεστόν.", "st": "Ant. 2.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Γαβίνιος ἀνὴρ ὑπατικὸς εἰς Συρίαν πλέων ἀνέπειθεν αὐτὸν ὁρμῆσαι πρὸς τὴν στρατείαν, ἰδιώτης μὲν οὐκ ἂν ἔφη συνεξελθεῖν, ἀποδειχθεὶς δὲ τῶν ἱππέων ἄρχων συνεστράτευε. καὶ πρῶτον μὲν ἐπ’ Ἀριστόβουλον Ἰουδαίους ἀφιστάντα πεμφθεὶς αὐτὸς μὲν ἐπέβη τοῦ μεγίστου τῶν ἐρυμάτων πρῶτος, ἐκεῖνον δὲ πάντων ἐξήλασεν· εἶτα μάχην συνάψας καὶ τρεψάμενος ὀλίγοις τοῖς σὺν αὑτῷ τοὺς ἐκείνου πολλαπλασίους ὄντας ἀπέκτεινε πλὴν ὀλίγων ἅπαντας· αὐτὸς δὲ μετὰ τοῦ παιδὸς Ἀριστόβουλος ἥλω.", "st": "Ant. 3.1"}, {"sp": "N", "t": "μετὰ ταῦτα Γαβίνιον ἐπὶ μυρίοις ταλάντοις Πτολεμαίου πείθοντος εἰς Αἴγυπτον ἅμα συνεμβαλεῖν αὐτῷ καὶ τὴν βασιλείαν ἀναλαβεῖν, οἱ μὲν πλεῖστοι τῶν ἡγεμόνων ἠναντιοῦντο, καὶ Γαβίνιον δὲ ὄκνος τις εἶχε τοῦ πολέμου, καίπερ ἐξηνδραποδισμένον κομιδῆ τοῖς μυρίοις ταλάντοις, Ἀντώνιος δὲ καὶ πράξεων μεγάλων ἐφιέμενος καὶ τῷ Πτολεμαίῳ χαριζόμενος δεομένῳ συνέπεισε μὲν καὶ συνεξώρμησεν ἐπὶ τὴν στρατείαν τὸν Γαβίνιον, ἐπεὶ δὲ τοῦ πολέμου μᾶλλον ἐφοβοῦντο τὴν ἐπὶ τὸ Πηλούσιον ὁδόν, ἅτε δὴ διὰ ψάμμου βαθείας καὶ ἀνύδρου παρὰ τὸ Ἔκρηγμα καὶ τὰ τῆς Σερβωνίδος ἕλη γινομένης αὐτοῖς τῆς πορείας, ἃς Τυφῶνος μὲν ἐκπνοὰς Αἰγύπτιοι καλοῦσι, τῆς δ’ ἐρυθρᾶς θαλάσσης ὑπονόστησις εἶναι δοκεῖ καὶ διήθησις, ᾗ βραχυτάτῳ διορίζεται πρὸς τὴν ἐντὸς θάλασσαν ἰσθμῷ, πεμφθεὶς μετὰ τῶν ἱππέων ὁ Ἀντώνιος οὐ μόνον τὰ στενὰ κατέσχεν, ἀλλὰ καὶ Πηλούσιον ἑλών, πόλιν μεγάλην, καὶ τῶν ἐν αὐτῇ φρουρῶν κρατήσας, ἅμα καὶ τὴν ὁδὸν ἀσφαλῆ τῷ στρατεύματι καὶ τὴν ἐλπίδα τῆς νίκης ἐποίησε τῷ στρατηγῷ βέβαιον. ἀπέλαυσαν δὲ τῆς φιλοτιμίας αὐτοῦ καὶ οἱ πολέμιοι. Πτολεμαίου γὰρ ἅμα τῷ παρελθεῖν εἰς τὸ Πηλούσιον ὑπ’ ὀργῆς καὶ μίσους ὡρμημένου φονεύειν τοὺς Αἰγυπτίους ἐνέστη καὶ διεκώλυσεν. ἐν δὲ ταῖς μάχαις καὶ τοῖς ἀγῶσι μεγάλοις καὶ συχνοῖς γενομένοις πολλὰ καὶ τόλμης ἔργα καὶ προνοίας ἡγεμονικῆς ἀποδειξάμενος, ἐμφανέστατα δὲ τῷ κυκλώσασθαι καὶ περιβαλεῖν κατόπιν τοὺς πολεμίους τὴν νίκην τοῖς κατὰ στόμα παρασχών, ἀριστεῖα καὶ τιμὰς ἔλαβε πρεπούσας. οὐ διέλαθε δὲ τοὺς πολλοὺς οὐδὲ ἡ πρὸς Ἀρχέλαον αὐτοῦ τεθνηκότα φιλανθρωπία· γεγονὼς γὰρ αὐτῷ συνήθης καὶ ξένος ἐπολέμει μὲν ἀναγκαίως ζῶντι, τὸ δὲ σῶμα πεσόντος ἐξευρὼν καὶ κοσμήσας βασιλικῶς ἐκήδευσεν. ἐπὶ τούτοις Ἀλεξανδρεῦσί τε πλεῖστον αὑτοῦ λόγον κατέλιπε, καὶ Ῥωμαίων τοῖς στρατευομένοις ἀνὴρ ἔδοξε λαμπρότατος εἶναι.", "st": "Ant. 3.2"}, {"sp": "N", "t": "προσῆν δὲ καὶ μορφῆς ἐλευθέριον ἀξίωμα, καὶ πώγων τις οὐκ ἀγεννὴς καὶ πλάτος μετώπου καὶ γρυπότης μυκτῆρος ἐδόκει τοῖς γραφομένοις καὶ πλαττομένοις Ἡρακλέους προσώποις ἐμφερὲς ἔχειν τὸ ἀρρενωπόν. ἦν δὲ καὶ λόγος παλαιὸς Ἡρακλείδας εἶναι τοὺς Ἀντωνίους, ἀπ’ Ἄντωνος, παιδὸς Ἡρακλέους, γεγονότας. καὶ τοῦτον ᾤετο τὸν λόγον τῇ τε μορφῇ τοῦ σώματος, ὥσπερ εἴρηται, καὶ τῇ στολῇ βεβαιοῦν. ἀεὶ γάρ, ὅτε μέλλοι πλείοσιν ὁρᾶσθαι, χιτῶνα εἰς μηρὸν ἔζωστο, καὶ μάχαιρα μεγάλη παρήρτητο, καὶ σάγος περιέκειτο τῶν στερεῶν. οὐ μὴν ἀλλὰ καὶ τὰ τοῖς ἄλλοις φορτικὰ δοκοῦντα, μεγαλαυχία καὶ σκῶμμα καὶ κώθων ἐμφανὴς καὶ καθίσαι παρὰ τὸν ἐσθίοντα καὶ φαγεῖν ἐπιστάντα τραπέζῃ στρατιωτικῇ, θαυμαστὸν ὅσον εὐνοίας καὶ πόθου πρὸς αὐτὸν ἐνεποίει τοῖς στρατιώταις. ἦν δέ που καὶ τὸ ἐρωτικὸν οὐκ ἀναφρόδιτον, ἀλλὰ καὶ τούτῳ πολλοὺς ἐδημαγώγει, συμπράττων τε τοῖς ἐρῶσι καὶ σκωπτόμενος οὐκ ἀηδῶς εἰς τοὺς ἰδίους ἔρωτας.", "st": "Ant. 4.1"}, {"sp": "N", "t": "ἡ δ’ ἐλευθεριότης καὶ τὸ μηδὲν ὀλίγῃ χειρὶ μηδὲ φειδομένῃ χαρίζεσθαι στρατιώταις καὶ φίλοις ἀρχήν τε λαμπρὰν ἐπὶ τὸ ἰσχύειν αὐτῷ παρέσχε, καὶ μεγάλου γενομένου τὴν δύναμιν ἐπὶ πλεῖον ἐπῆρεν, ἐκ μυρίων ἄλλων ἁμαρτημάτων ἀνατρεπομένην. ἓν δέ τι τοῦ μεγαλοδώρου παράδειγμα διηγήσομαι. τῶν φίλων τινὶ μυριάδας ἐκέλευσε πέντε καὶ εἴκοσι δοθῆναι· τοῦτο Ῥωμαῖοι δεκίης καλοῦσι. τοῦ δ’ ἐπιτρόπου θαυμάσαντος καὶ ἵνα δείξῃ τὸ πλῆθος αὐτῷ καταβαλόντος ἐν μέσῳ τὸ ἀργύριον, ἠρώτησε παριὼν ὅ τι δὴ τοῦτο εἴη. τοῦ δ’ ἐπιτρόπου φήσαντος ὡς ὃ κελεύσειε δοθῆναι, συμβαλὼν αὐτοῦ τὴν κακοήθειαν ὁ Ἀντώνιος, ἐγὼ πλεῖον ᾤμην, ἔφη, τὸ δεκίης εἶναι· τοῦτο δὲ μικρόν ἐστιν· ὥστε ἄλλο πρόσθες αὐτῷ τοσοῦτον.", "st": "Ant. 4.4"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ὕστερον· ἐπεὶ δὲ τὰ Ῥωμαίων πράγματα διέστη, τῶν μὲν ἀριστοκρατικῶν Πομπηΐῳ παρόντι προσθεμένων, τῶν δὲ δημοτικῶν Καίσαρα καλούντων ἐκ Γαλατίας ἐν τοῖς ὅπλοις ὄντα, Κουρίων ὁ Ἀντωνίου φίλος ἐκ μεταβολῆς θεραπεύων τὰ Καίσαρος Ἀντώνιον προσηγάγετο, καὶ μεγάλην μὲν ἀπὸ τοῦ λέγειν ἐν τοῖς πολλοῖς ἔχων ἰσχύν, χρώμενος δὲ καὶ δαπάναις ἀφειδῶς ἀφ’ ὧν Καῖσαρ ἐχορήγει, δήμαρχον ἀπέδειξε τὸν Ἀντώνιον, εἶτα τῶν ἐπ’ οἰωνοῖς ἱερέων, οὓς Αὔγουρας καλοῦσιν. ὁ δὲ εὐθὺς εἰς τὴν ἀρχὴν παρελθὼν οὐ μικρὸν ἦν ὄφελος τοῖς πολιτευομένοις ὑπὲρ Καίσαρος. ἀλλὰ πρῶτον μὲν Μαρκέλλου τοῦ ὑπάτου Πομπηΐῳ τούς τε συνειλεγμένους ἤδη στρατιώτας παρεγγυῶντος καὶ καταλέγειν ἑτέρους διδόντος ἐμποδὼν ἔστη, διάταγμα γράψας ὅπως ἡ μὲν ἠθροισμένη δύναμις εἰς Συρίαν πλέῃ καὶ Βύβλῳ βοηθῇ πολεμοῦντι Πάρθοις, οὓς δὲ Πομπήϊος καταλέγει, μὴ προσέχωσιν αὐτῷ· δεύτερον δὲ τὰς Καίσαρος ἐπιστολὰς οὐ προσιεμένων οὐδὲ ἐώντων ἀναγινώσκεσθαι τῶν συγκλητικῶν, αὐτὸς ἰσχύων διὰ τὸ ἄρχειν ἀνέγνω, καὶ πολλοὺς μετέστησε τῇ γνώμῃ, δίκαια καὶ μέτρια Καίσαρος ἀξιοῦν ἀφ’ ὧν ἔγραψε δόξαντος. τέλος δὲ δυεῖν ἐρωτήσεων ἐν τῇ βουλῇ γενομένων, τῆς μὲν εἰ δοκεῖ Πομπήϊον ἀφεῖναι τὰ στρατεύματα, τῆς δὲ εἰ Καίσαρα, καὶ Πομπήϊον μὲν ὀλίγων τὰ ὅπλα καταθέσθαι, Καίσαρα δὲ πάντων παρ’ ὀλίγους κελευόντων, ἀναστὰς Ἀντώνιος ἠρώτησεν εἰ δοκεῖ καὶ Πομπήϊον ὁμοῦ καὶ Καίσαρα τὰ ὅπλα καταθέσθαι καὶ τὰς δυνάμεις ἀφεῖναι. ταύτην ἐδέξαντο λαμπρῶς τὴν γνώμην ἅπαντες, καὶ μετὰ βοῆς ἐπαινοῦντες τὸν Ἀντώνιον ἠξίουν ἐπιψηφίζεσθαι. μὴ βουλομένων δὲ τῶν ὑπάτων, αὖθις ἑτέρας οἱ Καίσαρος φίλοι προὔτειναν ἐπιεικεῖς εἶναι δοκούσας ἀξιώσεις, αἷς ὅ τε Κάτων ἀντέπιπτε καὶ Λέντλος ὑπατεύων ἐξέβαλε τῆς βουλῆς τὸν Ἀντώνιον. ὁ δὲ πολλὰ μὲν αὐτοῖς ἐξιὼν ἐπηράσατο, λαβὼν δὲ θεράποντος ἐσθῆτα καὶ μισθωσάμενος μετὰ Κασσίου Κοΐντου ζεῦγος, ἐξώρμησε πρὸς Καίσαρα· καὶ κατεβόων εὐθὺς ὀφθέντες ὡς οὐδένα κόσμον ἔτι τῶν ἐν Ῥώμῃ πραγμάτων ἐχόντων, ὅτε μηδὲ δημάρχοις παρρησίας μέτεστιν, ἀλλ’ ἐλαύνεται καὶ κινδυνεύει πᾶς ὁ φθεγξάμενος ὑπὲρ τῶν δικαίων.", "st": "Ant. 5.1"}, {"sp": "N", "t": "ἐκ τούτου λαβὼν τὴν στρατιὰν ὁ Καῖσαρ εἰς Ἰταλίαν ἐνέβαλε. διὸ καὶ Κικέρων ἐν τοῖς Φιλιππικοῖς ἔγραψε τοῦ μὲν Τρωϊκοῦ πολέμου τὴν Ἑλένην, τοῦ δ’ ἐμφυλίου τὸν Ἀντώνιον ἀρχὴν γενέσθαι, περιφανῶς ψευδόμενος. οὐ γὰρ οὕτως εὐχερὴς ἦν οὐδὲ ῥᾴδιος ὑπ’ ὀργῆς ἐκπεσεῖν τῶν λογισμῶν Γάϊος Καῖσαρ ὥστε, εἰ μὴ ταῦτα πάλαι ἔγνωστο πράττειν, οὕτως ἂν ἐπὶ καιροῦ τὸν κατὰ τῆς πατρίδος ἐξενεγκεῖν πόλεμον, ὅτι φαύλως ἠμφιεσμένον εἶδεν Ἀντώνιον καὶ Κάσσιον ἐπὶ ζεύγους μισθίου πεφευγότας πρὸς αὐτόν, ἀλλὰ ταῦτα πάλαι δεομένῳ προφάσεως σχῆμα καὶ λόγον εὐπρεπῆ τοῦ πολέμου παρέσχεν. ἦγε δὲ αὐτὸν ἐπὶ πάντας ἀνθρώπους ἃ καὶ πρότερον Ἀλέξανδρον καὶ πάλαι Κῦρον, ἔρως ἀπαρηγόρητος ἀρχῆς καὶ περιμανὴς ἐπιθυμία τοῦ πρῶτον εἶναι καὶ μέγιστον· ὧν τυχεῖν οὐκ ἦν μὴ Πομπηΐου καταλυθέντος.", "st": "Ant. 6.1"}, {"sp": "N", "t": "ὡς δ’ οὖν ἐπελθὼν ἐκράτησε τῆς Ῥώμης καὶ Πομπήϊον ἐξήλασε τῆς Ἰταλίας καὶ πρὸς τὰς ἐν Ἰβηρίᾳ Πομπηΐου δυνάμεις ἐπιστρέφειν ἔγνω πρότερον, εἶτα οὕτως παρασκευασάμενος στόλον ἐπὶ Πομπήϊον διαβαίνειν, Λεπίδῳ μὲν στρατηγοῦντι τὴν Ῥώμην, Ἀντωνίῳ δὲ δημαρχοῦντι τὰ στρατεύματα καὶ τὴν Ἰταλίαν ἐπέτρεψεν. ὁ δὲ τοῖς μὲν στρατιώταις εὐθὺς προσφιλὴς ἦν συγγυμναζόμενος καὶ συνδιαιτώμενος τὰ πολλὰ καὶ δωρούμενος ἐκ τῶν παρόντων, τοῖς δὲ ἄλλοις ἐπαχθής. καὶ γὰρ ἀδικουμένων ὑπὸ ῥᾳθυμίας ὠλιγώρει, καὶ πρὸς ὀργὴν ἠκροᾶτο τῶν ἐντυγχανόντων καὶ κακῶς ἐπὶ γυναιξὶν ἀλλοτρίαις ἤκουε. καὶ ὅλως τὴν Καίσαρος ἀρχήν, πάντα μᾶλλον ἢ τυραννίδα δι’ αὐτὸν ἐκεῖνον φανεῖσαν, οἱ φίλοι διέβαλλον, ὧν Ἀντώνιος ἀπ’ ἐξουσίας μεγίστης ἁμαρτάνειν μέγιστα δόξας τὴν πλείστην αἰτίαν ἔλαβεν.", "st": "Ant. 6.4"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἐπανελθὼν ὁ Καῖσαρ ἐκ τῆς Ἰβηρίας τὰ μὲν ἐγκλήματα παρεῖδεν αὐτοῦ, πρὸς δὲ τὸν πόλεμον ὡς ἐνεργῷ καὶ ἀνδρείῳ καὶ ἡγεμονικῷ χρώμενος οὐδαμῆ διήμαρτεν. αὐτὸς μὲν οὖν μετ’ ὀλίγων ἀπὸ Βρεντεσίου διαπεράσας τὸν Ἰόνιον ἔπεμψεν ὀπίσω τὰ πλοῖα, Γαβινίῳ καὶ Ἀντωνίῳ τὰς δυνάμεις ἐμβιβάζειν καὶ περαιοῦν κατὰ τάχος εἰς Μακεδονίαν ἐπιστείλας. Γαβινίου δὲ πρὸς τὸν πλοῦν χαλεπὸν ὄντα χειμῶνος ὥρᾳ καταδειλιάσαντος καὶ πεζῇ μακρὰν ὁδὸν περιάγοντος τὸν στρατόν, Ἀντώνιος ὑπὲρ Καίσαρος ἐν πολλοῖς ἀπειλημμένου πολεμίοις φοβηθεὶς Λίβωνα μὲν ἐφορμοῦντα τῷ στόματι τοῦ λιμένος ἀπεκρούσατο, πολλὰ τῶν λεπτῶν ἀκατίων ταῖς τριήρεσιν αὐτοῦ περιστήσας, ἐμβιβάσας δὲ ταῖς ναυσὶν ἱππεῖς ὀκτακοσίους καὶ δισμυρίους ὁπλίτας ἀνήχθη. καὶ γενόμενος καταφανὴς τοῖς πολεμίοις καὶ διωκόμενος τὸν μὲν ἐκ τούτων κίνδυνον διέφυγε, λαμπροῦ νότου κῦμα μέγα καὶ κοίλην θάλατταν ταῖς τριήρεσιν αὐτῶν περιστήσαντος, ἐκφερόμενος δὲ ταῖς ναυσὶ πρὸς κρημνοὺς καὶ φάραγγας ἀγχιβαθεῖς οὐδεμίαν ἐλπίδα σωτηρίας εἶχεν. ἄφνω δὲ τοῦ κόλπου πολὺν ἐκπνεύσαντος λίβα, καὶ τοῦ κλύδωνος ἀπὸ τῆς γῆς εἰς τὸ πέλαγος διαχεομένου, μεταβαλόμενος ἀπὸ τῆς γῆς καὶ πλέων σοβαρῶς ὁρᾷ ναυαγίων περίπλεων τὸν αἰγιαλόν. ἐνταῦθα γὰρ ἐξέβαλε τὸ πνεῦμα τὰς διωκούσας αὐτὸν τριήρεις, καὶ διεφθάρησαν οὐκ ὀλίγαι· καὶ σωμάτων πολλῶν καὶ χρημάτων ἐκράτησεν Ἀντώνιος, καὶ Λίσσον εἷλε, καὶ μέγα Καίσαρι παρέσχε θάρσος ἐν καιρῷ μετὰ τηλικαύτης ἀφικόμενος δυνάμεως.", "st": "Ant. 7.1"}, {"sp": "N", "t": "πολλῶν δὲ γινομένων καὶ συνεχῶν ἀγώνων ἐν πᾶσι μὲν ἦν διαπρεπής, δὶς δὲ φεύγοντας προτροπάδην τοὺς Καίσαρος ἀπαντήσας ἀνέστρεψε καὶ στῆναι καὶ συμβαλεῖν αὖθις τοῖς διώκουσιν ἀναγκάσας ἐνίκησεν. ἦν οὖν αὐτοῦ μετὰ Καίσαρα πλεῖστος ἐν τῷ στρατοπέδῳ λόγος· ἐδήλωσε δὲ Καῖσαρ ἣν ἔχοι περὶ αὐτοῦ δόξαν. ἐπεὶ γὰρ ἔμελλε τὴν τελευταίαν καὶ τὰ ὅλα κρίνασαν ἐν Φαρσάλῳ μάχην μάχεσθαι, τὸ μὲν δεξιὸν αὐτὸς εἶχε κέρας, τοῦ δ’ εὐωνύμου τὴν ἡγεμονίαν Ἀντωνίῳ παρέδωκεν, ὡς πολεμικωτάτῳ τῶν ὑφ’ ἑαυτῷ. μετὰ δὲ τὴν νίκην δικτάτωρ ἀναγορευθεὶς αὐτὸς μὲν ἐδίωκε Πομπήϊον, Ἀντώνιον δὲ ἵππαρχον ἑλόμενος εἰς Ῥώμην ἔπεμψεν. ἔστι δὲ ἡ ἀρχὴ δευτέρα τοῦ δικτάτορος παρόντος· ἂν δὲ μὴ παρῇ, πρώτη καὶ μόνη σχεδόν· ἡ γὰρ δημαρχία διαμένει, τὰς δὲ ἄλλας καταλύουσι πάσας δικτάτορος αἱρεθέντος.", "st": "Ant. 8.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τότε δημαρχῶν Δολοβέλλας, νέος ἀνὴρ καὶ νέων πραγμάτων ὀρεγόμενος, εἰσηγεῖτο χρεῶν ἀποκοπάς, καὶ τὸν Ἀντώνιον αὐτῷ τε φίλον ὄντα καὶ βουλόμενον ἀεὶ τοῖς πολλοῖς ἀρέσκειν ἔπειθε συμπράττειν καὶ κοινωνεῖν τοῦ πολιτεύματος. Ἀσινίου δὲ καὶ Τρεβελλίου τἀναντία παρακαλούντων ὑπόνοια δεινὴ κατὰ τύχην τῷ Ἀντωνίῳ προσέπεσεν ὡς ἀδικουμένῳ περὶ τὸν γάμον ὑπὸ τοῦ Δολοβέλλα. καὶ τὸ πρᾶγμα βαρέως ἐνεγκὼν τήν τε γυναῖκα τῆς οἰκίας ἐξήλασεν ἀνεψιὰν οὖσαν αὐτοῦ (θυγάτηρ γὰρ ἦν Γαΐου Ἀντωνίου τοῦ Κικέρωνι συνυπατεύσαντος), καὶ τοὺς περὶ Ἀσίνιον δεξάμενος ἐπολέμει τῷ Δολοβέλλᾳ. κατέλαβε γὰρ τὴν ἀγορὰν ἐκεῖνος ὡς βίᾳ κυρώσων τὸν νόμον. Ἀντώνιος δέ, καὶ τῆς βουλῆς ψηφισαμένης ὅπλων δεῖν ἐπὶ τὸν Δολοβέλλαν, ἐπελθὼν καὶ μάχην συνάψας ἀπέκτεινέ τέ τινας τῶν ἐκείνου καὶ τῶν ἰδίων ἀπέβαλε. τοῖς μὲν οὖν πολλοῖς ἐκ τούτων ἀπηχθάνετο, τοῖς δὲ χρηστοῖς καὶ σώφροσι διὰ τὸν ἄλλον βίον οὐκ ἦν ἀρεστός, ὡς Κικέρων φησίν, ἀλλ’ ἐμισεῖτο, βδελυττομένων αὐτοῦ μέθας ἀώρους καὶ δαπάνας ἐπαχθεῖς καὶ κυλινδήσεις ἐν γυναίοις, καὶ μεθ’ ἡμέραν μὲν ὕπνους καὶ περιπάτους ἀλύοντος καὶ κραιπαλῶντος, νύκτωρ δὲ κώμους καὶ θέατρα καὶ διατριβὰς ἐν γάμοις μίμων καὶ γελωτοποιῶν. λέγεται γοῦν, ὡς ἐν Ἱππίου ποτὲ τοῦ μίμου γάμοις ἑστιαθεὶς καὶ πιὼν διὰ νυκτός, εἶτα πρωῒ τοῦ δήμου καλοῦντος εἰς ἀγορὰν προελθὼν ἔτι τροφῆς μεστὸς ἐμέσειε, τῶν φίλων τινὸς ὑποσχόντος τὸ ἱμάτιον. ἦν δὲ καὶ Σέργιος ὁ μῖμος τῶν μέγιστον παρ’ αὐτῷ δυναμένων, καὶ Κυθηρὶς ἀπὸ τῆς αὐτῆς παλαίστρας γύναιον ἀγαπώμενον, ὃ δὴ καὶ τὰς πόλεις ἐπιὼν ἐν φορείῳ περιήγετο, καὶ τὸ φορεῖον οὐκ ἐλάττους ἢ τὸ τῆς μητρὸς αὐτοῦ περιέποντες ἠκολούθουν. ἐλύπουν δὲ καὶ χρυσῶν ἐκπωμάτων ὥσπερ ἐν πομπαῖς ταῖς ἀποδημίαις διαφερομένων ὄψεις, καὶ στάσεις ἐνόδιοι σκηνῶν, καὶ πρὸς ἄλσεσι καὶ ποταμοῖς ἀρίστων πολυτελῶν διαθέσεις, καὶ λέοντες ἅρμασιν ὑπεζευγμένοι, καὶ σωφρόνων ἀνδρῶν καὶ γυναικῶν οἰκίαι χαμαιτύπαις καὶ σαμβυκιστρίαις ἐπισταθμευόμεναι. δεινὸν γὰρ ἐποιοῦντο Καίσαρα μὲν αὐτὸν ἔξω τῆς Ἰταλίας θυραυλεῖν, τὰ περιόντα τοῦ πολέμου μεγάλοις πόνοις καὶ κινδύνοις ἀνακαθαιρόμενον, ἑτέρους δὲ δι’ ἐκεῖνον τρυφᾶν τοῖς πολίταις ἐνυβρίζοντας.", "st": "Ant. 9.1"}, {"sp": "N", "t": "ταῦτα καὶ τὴν στάσιν αὐξῆσαι δοκεῖ καὶ τὸ στρατιωτικὸν εἰς ὕβρεις δεινὰς καὶ πλεονεξίας ἀνεῖναι. διὸ καὶ Καῖσαρ ἐπανελθὼν Δολοβέλλᾳ τε συγγνώμην ἔδωκε, καὶ τὸ τρίτον αἱρεθεὶς ὕπατος οὐκ Ἀντώνιον, ἀλλὰ Λέπιδον εἵλετο συνάρχοντα. τὴν δὲ Πομπηΐου πωλουμένην οἰκίαν ὠνήσατο μὲν Ἀντώνιος, ἀπαιτούμενος δὲ τὴν τιμὴν ἠγανάκτει· καί φησιν αὐτὸς διὰ τοῦτο μὴ μετασχεῖν Καίσαρι τῆς εἰς Λιβύην στρατείας, ἐπὶ τοῖς προτέροις κατορθώμασιν οὐ τυχὼν ἀμοιβῆς. ἔοικε μέντοι τὸ πολὺ τῆς ἀβελτερίας αὐτοῦ καὶ ἀσωτίας ἀφελεῖν ὁ Καῖσαρ, οὐκ ἀναισθήτως τὰ πλημμελήματα δεξάμενος. ἀπαλλαγεὶς γὰρ ἐκείνου τοῦ βίου γάμῳ προσέσχε, Φουλβίαν ἀγαγόμενος τὴν Κλωδίῳ τῷ δημαγωγῷ συνοικήσασαν, οὐ ταλασίαν οὐδὲ οἰκουρίαν φρονοῦν γύναιον, οὐδὲ ἀνδρὸς ἰδιώτου κρατεῖν ἀξιοῦν, ἀλλ’ ἄρχοντος ἄρχειν καὶ στρατηγοῦντος στρατηγεῖν βουλόμενον, ὥστε Κλεοπάτραν διδασκάλια Φουλβίᾳ τῆς Ἀντωνίου γυναικοκρατίας ὀφείλειν, πάνυ χειροήθη καὶ πεπαιδαγωγημένον ἀπ’ ἀρχῆς ἀκροᾶσθαι γυναικῶν παραλαβοῦσαν αὐτόν.", "st": "Ant. 10.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ κἀκείνην ἐπειρᾶτο προσπαίζων καὶ μειρακιευόμενος ἱλαρωτέραν ποιεῖν ὁ Ἀντώνιος· οἷον ὅτε, Καίσαρι πολλῶν ἀπαντώντων μετὰ τὴν ἐν Ἰβηρίᾳ νίκην, καὶ αὐτὸς ἐξῆλθεν. εἶτα ἄφνω φήμης εἰς τὴν Ἰταλίαν ἐμπεσούσης ὡς ἐπίασιν οἱ πολέμιοι Καίσαρος τεθνηκότος, ἀνέστρεψεν εἰς Ῥώμην. λαβὼν δὲ θεράποντος ἐσθῆτα νύκτωρ ἐπὶ τὴν οἰκίαν ἦλθε, καὶ φήσας ἐπιστολὴν Φουλβίᾳ παρ’ Ἀντωνίου κομίζειν εἰσήχθη πρὸς αὐτὴν ἐγκεκαλυμμένος. εἶτα ἡ μὲν ἐκπαθὴς οὖσα, πρὶν ἢ τὰ γράμματα λαβεῖν ἠρώτησεν εἰ ζῇ ὁ Ἀντώνιος· ὁ δὲ τὴν ἐπιστολὴν σιωπῇ προτείνας ἀρξαμένην λύειν καὶ ἀναγινώσκειν περιβαλὼν κατεφίλησε.", "st": "Ant. 10.4"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ὀλίγα πολλῶν ὄντων ἕνεκα δείγματος ἐξενηνόχαμεν.", "st": "Ant. 10.4b"}, {"sp": "N", "t": "ἐκ δὲ Ἰβηρίας ἐπανιόντι Καίσαρι πάντες μὲν οἱ πρῶτοι πολλῶν ἡμερῶν ὁδὸν ἀπήντων, ἐτιμήθη δὲ Ἀντώνιος ἐκπρεπῶς ὑπ’ αὐτοῦ. κομιζόμενος γὰρ ἐπὶ ζεύγους διὰ τῆς Ἰταλίας Ἀντώνιον εἶχε μεθ’ ἑαυτοῦ συνοχούμενον, ὄπισθεν δὲ Βροῦτον Ἀλβῖνον καὶ τὸν τῆς ἀδελφιδῆς υἱὸν Ὀκταουϊανόν, ὃς μετὰ ταῦτα Καῖσαρ ὠνομάσθη καὶ Ῥωμαίων ἦρξε πλεῖστον χρόνον. ἐπεὶ δὲ τὸ πέμπτον ἀπεδείχθη Καῖσαρ ὕπατος, προσείλετο μὲν εὐθὺς συνάρχοντα τὸν Ἀντώνιον, ἐβούλετο δὲ τὴν ἀρχὴν ἀπειπάμενος Δολοβέλλᾳ παρεγγυῆσαι· καὶ τοῦτο πρὸς τὴν σύγκλητον ἐξήνεγκεν. Ἀντωνίου δὲ τραχέως ἀντιπεσόντος καὶ πολλὰ μὲν εἰπόντος κακὰ Δολοβέλλαν, οὐκ ἐλάττονα δὲ ἀκούσαντος, τότε μὲν αἰσχυνθεὶς τὴν ἀκοσμίαν ὁ Καῖσαρ ἀπηλλάγη. μετὰ δὲ ταῦτα προελθὼν ἀναγορεῦσαι τὸν Δολοβέλλαν, Ἀντωνίου τοὺς οἰωνοὺς ἐναντιοῦσθαι βοῶντος, εἶξε καὶ προήκατο Δολοβέλλαν ἀχθόμενον. ἐδόκει δὲ κᾀκεῖνον οὐδὲν ἧττον τοῦ Ἀντωνίου βδελύττεσθαι. λέγεται γὰρ ὡς, ἀμφοτέρους τινὸς ὁμοῦ διαβάλλοντος πρὸς αὐτόν, εἴποι, μὴ δεδιέναι τοὺς παχεῖς τούτους καὶ κομήτας, ἀλλὰ τοὺς ὠχροὺς καὶ λεπτοὺς ἐκείνους, Βροῦτον καὶ Κάσσιον ἀποδεικνύμενος, ὑφ’ ὧν ἔμελλεν ἐπιβουλευθεὶς ἀναιρεῖσθαι.", "st": "Ant. 11.1"}, {"sp": "N", "t": "κἀκείνοις δὲ τὴν εὐπρεπεστάτην πρόφασιν ἄκων παρέσχεν Ἀντώνιος. ἦν μὲν γὰρ ἡ τῶν Λυκαίων ἑορτὴ Ῥωμαίοις, ἣν Λουπερκάλια καλοῦσι, Καῖσαρ δὲ κεκοσμημένος ἐσθῆτι θριαμβικῇ καὶ καθήμενος ὑπὲρ βήματος ἐν ἀγορᾷ τοὺς διαθέοντας ἐθεᾶτο· διαθέουσι δὲ τῶν εὐγενῶν νέοι πολλοὶ καὶ τῶν ἀρχόντων, ἀληλιμμένοι λίπα, σκύτεσι λασίοις καθικνούμενοι μετὰ παιδιᾶς τῶν ἐντυγχανόντων. ἐν τούτοις ὁ Ἀντώνιος διαθέων τὰ μὲν πάτρια χαίρειν εἴασε, διάδημα δὲ δάφνης στεφάνῳ περιελίξας προσέδραμε τῷ βήματι, καὶ συνεξαρθεὶς ὑπὸ τῶν συνθεόντων ἐπέθηκε τῇ κεφαλῇ τοῦ Καίσαρος, ὡς δὴ βασιλεύειν αὐτῷ προσῆκον. ἐκείνου δὲ θρυπτομένου καὶ διακλίνοντος ἡσθεὶς ὁ δῆμος ἀνεκρότησε· καὶ πάλιν ὁ Ἀντώνιος ἐπῆγε, καὶ πάλιν ἐκεῖνος ἀπετρίβετο. καὶ πολὺν χρόνον οὕτω διαμαχομένων Ἀντωνίῳ μὲν ὀλίγοι τῶν φίλων βιαζομένῳ, Καίσαρι δὲ ἀρνουμένῳ πᾶς ὁ δῆμος ἐπεκρότει μετὰ βοῆς· ὃ καὶ θαυμαστὸν ἦν, ὅτι τοῖς ἔργοις τὰ τῶν βασιλευομένων ὑπομένοντες τοὔνομα τοῦ βασιλέως ὡς κατάλυσιν τῆς ἐλευθερίας ἔφευγον. ἀνέστη μὲν οὖν ὁ Καῖσαρ ἀχθεσθεὶς ἀπὸ τοῦ βήματος, καὶ τὸ ἱμάτιον ἀπάγων ἀπὸ τοῦ τραχήλου τῷ βουλομένῳ παρέχειν τὴν σφαγὴν ἐβόα. τὸν δὲ στέφανον ἑνὶ τῶν ἀνδριάντων αὐτοῦ περιτεθέντα δήμαρχοί τινες κατέσπασαν, οὓς ὁ δῆμος εὐφημῶν μετὰ κρότου παρείπετο, Καῖσαρ δὲ τῆς ἀρχῆς ἀπέστησεν.", "st": "Ant. 12.1"}, {"sp": "N", "t": "ταῦτα τοὺς περὶ Βροῦτον καὶ Κάσσιον ἐπέρρωσε· καὶ τῶν φίλων τοὺς πιστοὺς καταλέγοντες ἐπὶ τὴν πρᾶξιν ἐσκέπτοντο περὶ Ἀντωνίου. τῶν δὲ ἄλλων προσιεμένων τὸν ἄνδρα Τρεβώνιος ἀντεῖπεν· ἔφη γὰρ ὑφ’ ὃν χρόνον ἀπήντων ἐξ Ἰβηρίας ἐπανιόντι Καίσαρι, τοῦ Ἀντωνίου συσκηνοῦντος αὐτῷ καὶ συνοδεύοντος, ἅψασθαι τῆς γνώμης ἀτρέμα πως καὶ μετ’ εὐλαβείας, τὸν δὲ νοῆσαι μέν, οὐ δέξασθαι δὲ τὴν πεῖραν, οὐ μὴν οὐδὲ πρὸς Καίσαρα κατειπεῖν, ἀλλὰ πιστῶς κατασιωπῆσαι τὸν λόγον. ἐκ τούτου πάλιν ἐβουλεύοντο Καίσαρα κτείναντες ἐπισφάττειν Ἀντώνιον· ἐκώλυσε δὲ Βροῦτος, ἀξιῶν τὴν ὑπὲρ τῶν νόμων καὶ τῶν δικαίων τολμωμένην πρᾶξιν εἰλικρινῆ καὶ καθαρὰν ἀδικίας εἶναι. φοβούμενοι δὲ τήν τε ῥώμην τοῦ Ἀντωνίου καὶ τὸ τῆς ἀρχῆς ἀξίωμα, τάττουσιν ἐπ’ αὐτὸν ἐνίους τῶν ἐκ τῆς συνωμοσίας, ὅπως, ὅταν εἰσίῃ Καῖσαρ εἰς τὴν βουλὴν καὶ μέλλῃ δρᾶσθαι τὸ ἔργον, ἔξω διαλεγόμενοί τι καὶ σπουδάζοντες κατέχωσιν αὐτόν.", "st": "Ant. 13.1"}, {"sp": "N", "t": "τούτων δὲ πραττομένων ὡς συνετέθη, καὶ πεσόντος ἐν τῇ βουλῇ τοῦ Καίσαρος, εὐθὺς μὲν ὁ Ἀντώνιος ἐσθῆτα θεράποντος μεταλαβὼν ἔκρυψεν αὑτόν. ὡς δ’ ἔγνω τοὺς ἄνδρας ἐπιχειροῦντας μὲν οὐδενί, συνηθροισμένους δὲ εἰς τὸ Καπιτώλιον, ἔπεισε καταβῆναι λαβόντας ὅμηρον παρ’ αὐτοῦ τὸν υἱόν· καὶ Κάσσιον μὲν αὐτὸς ἐδείπνισε, Βροῦτον δὲ Λέπιδος. συναγαγὼν δὲ βουλὴν αὐτὸς μὲν ὑπὲρ ἀμνηστίας εἶπε καὶ διανομῆς ἐπαρχιῶν τοῖς περὶ Κάσσιον καὶ Βροῦτον, ἡ δὲ σύγκλητος ἐκύρωσε ταῦτα καὶ τῶν ὑπὸ Καίσαρος γεγονότων ἐψηφίσαντο μηδὲν ἀλλάττειν. ἐξῄει δὲ τῆς βουλῆς λαμπρότατος ἀνθρώπων ὁ Ἀντώνιος, ἀνῃρηκέναι δοκῶν ἐμφύλιον πόλεμον καὶ πράγμασι δυσκολίας ἔχουσι καὶ ταραχὰς οὐ τὰς τυχούσας ἐμφρονέστατα κεχρῆσθαι καὶ πολιτικώτατα.", "st": "Ant. 14.1"}, {"sp": "N", "t": "τούτων μέντοι ταχὺ τῶν λογισμῶν ἐξέσεισεν αὐτὸν ἡ παρὰ τῶν ὄχλων δόξα, πρῶτον ἐλπίσαντα βεβαίως ἔσεσθαι Βρούτου καταλυθέντος. ἔτυχε μὲν οὖν ἐκκομιζομένου Καίσαρος, ὥσπερ ἔθος ἦν, ἐν ἀγορᾷ διεξιὼν ἐγκώμιον· ὁρῶν δὲ τὸν δῆμον ὑπερφυῶς ἀγόμενον καὶ κηλούμενον ἐνέμιξε τοῖς ἐπαίνοις οἶκτον ἅμα καὶ δείνωσιν ἐπὶ τῷ πάθει, καὶ τῷ λόγῳ τελευτῶντι τούς τε χιτωνίσκους τοῦ τεθνηκότος ᾑμαγμένους καὶ διακεκομμένους τοῖς ξίφεσιν ἀνασείων, καὶ τοὺς εἰργασμένους ταῦτα καλῶν παλαμναίους καὶ ἀνδροφόνους, τοσοῦτον ὀργῆς ἐνέβαλε τοῖς ἀνθρώποις ὥστε τὸ μὲν σῶμα τοῦ Καίσαρος ἐν ἀγορᾷ καθαγίσαι, συνενεγκαμένους τὰ βάθρα καὶ τὰς τραπέζας, ἁρπάζοντας δὲ τοὺς ἀπὸ τῆς πυρᾶς δαλοὺς ἐπὶ τὰς οἰκίας θεῖν τῶν ἀπεκτονότων καὶ προσμάχεσθαι.", "st": "Ant. 14.3"}, {"sp": "N", "t": "διὰ ταῦτα τῶν περὶ Βροῦτον ἐκ τῆς πόλεως ἀπελθόντων οἵ τε φίλοι τοῦ Καίσαρος συνίσταντο πρὸς τὸν Ἀντώνιον, ἥ τε γυνὴ Καλπουρνία πιστεύσασα τῶν χρημάτων τὰ πλεῖστα κατέθετο πρὸς αὐτὸν ἐκ τῆς οἰκίας, εἰς λόγον τὰ σύμπαντα τετρακισχιλίων ταλάντων. ἔλαβε δὲ καὶ τὰ βιβλία τοῦ Καίσαρος, ἐν οἷς ὑπομνήματα τῶν κεκριμένων καὶ δεδογμένων ἦν ἀναγεγραμμένα· καὶ τούτοις παρεγγράφων οὓς ἐβούλετο, πολλοὺς μὲν ἄρχοντας ἀπεδείκνυε, πολλοὺς δὲ βουλευτάς, ἐνίους δὲ καὶ κατῆγε πεφυγαδευμένους καὶ καθειργμένους ἔλυεν, ὡς δὴ ταῦτα τῷ Καίσαρι δόξαντα. διὸ τούτους ἅπαντας ἐπισκώπτοντες οἱ Ῥωμαῖοι Χαρωνίτας ἐκάλουν· ἐλεγχόμενοι γὰρ εἰς τοὺς τοῦ νεκροῦ κατέφευγον ὑπομνηματισμούς. καὶ τἆλλα δὲ ἔπραττεν αὐτοκρατορικῶς ὁ Ἀντώνιος, αὐτὸς μὲν ὑπατεύων, τοὺς δὲ ἀδελφοὺς ἔχων συνάρχοντας, Γάϊον μὲν στρατηγόν, Λεύκιον δὲ δήμαρχον.", "st": "Ant. 15.1"}, {"sp": "N", "t": "ἐνταῦθα δὲ τῶν πραγμάτων ὄντων ὁ νέος ἀφικνεῖται Καῖσαρ εἰς Ῥώμην, ἀδελφιδῆς μὲν ὢν τοῦ τεθνηκότος υἱός, ὡς εἴρηται, κληρονόμος δὲ τῆς οὐσίας ἀπολελειμμένος, ἐν Ἀπολλωνία δὲ διατρίβων ὑφ’ ὃν χρόνον ἀνῄρητο Καῖσαρ. οὗτος εὐθὺς Ἀντώνιον, ὡς δὴ πατρῷον φίλον, ἀσπασάμενος τῶν παρακαταθηκῶν ἐμέμνητο. καὶ γὰρ ὤφειλε Ῥωμαίων ἑκάστῳ δραχμὰς ἑβδομήκοντα πέντε δοῦναι, Καίσαρος ἐν ταῖς διαθήκαις γράψαντος. Ἀντώνιος δὲ τὸ μὲν πρῶτον ὡς μειρακίου καταφρονῶν ἔλεγεν οὐχ ὑγιαίνειν αὐτόν, ἀλλὰ καὶ φρενῶν ἀγαθῶν καὶ φίλων ἔρημον ὄντα φορτίον ἀβάστακτον αἴρεσθαι τὴν Καίσαρος διαδοχήν· μὴ πειθομένου δὲ τούτοις, ἀλλ’ ἀπαιτοῦντος τὰ χρήματα, πολλὰ καὶ λέγων πρὸς ὕβριν αὐτοῦ καὶ πράττων διετέλει. δημαρχίαν τε γὰρ ἐνέστη μετιόντι, καὶ δίφρον χρυσοῦν τοῦ πατρός, ὥσπερ ἐψήφιστο, τιθέντος ἠπείλησεν εἰς φυλακὴν ἀπάξειν, εἰ μὴ παύσαιτο δημαγωγῶν. ἐπεὶ μέντοι Κικέρωνι δοὺς ἑαυτὸν ὁ νεανίας καὶ τοῖς ἄλλοις ὅσοι τὸν Ἀντώνιον ἐμίσουν, δι’ ἐκείνων μὲν ᾠκειοῦτο τὴν βουλήν, αὐτὸς δὲ τὸν δῆμον ἀνελάμβανε καὶ τοὺς στρατιώτας ἀπὸ τῶν κατοικιῶν συνῆγε, δείσας ὁ Ἀντώνιος εἰς λόγους αὐτῷ συνῆλθεν ἐν Καπιτωλίῳ, καὶ διηλλάγησαν.", "st": "Ant. 16.1"}, {"sp": "N", "t": "εἶτα κοιμώμενος ἐκείνης τῆς νυκτὸς ὄψιν εἶδεν ἄτοπον ὁ Ἀντώνιος. ἐδόκει γὰρ αὑτοῦ τὴν δεξιὰν χεῖρα βεβλῆσθαι κεραυνῷ. καὶ μεθ’ ἡμέρας ὀλίγας ἐνέπεσε λόγος ὡς ἐπιβουλεύοι Καῖσαρ αὐτῷ. Καῖσαρ δὲ ἀπελογεῖτο μέν, οὐκ ἔπειθε δέ· καὶ πάλιν ἦν ἐνεργὸς ἡ ἔχθρα, καὶ περιθέοντες ἀμφότεροι τὴν Ἰταλίαν τὸ μὲν ἱδρυμένον ἐν ταῖς κατοικίαις ἤδη τοῦ στρατιωτικοῦ μεγάλοις ἀνίστασαν μισθοῖς, τὸ δ’ ἐν ὅπλοις ἔτι τεταγμένον ὑποφθάνοντες ἀλλήλους προσήγοντο.", "st": "Ant. 16.4"}, {"sp": "N", "t": "τῶν δ’ ἐν τῇ πόλει Κικέρων μέγιστον δυνάμενος, καὶ παροξύνων ἐπὶ τὸν Ἀντώνιον ἅπαντας ἀνθρώπους, τέλος ἔπεισε τὴν βουλὴν ἐκεῖνον μὲν πολέμιον ψηφίσασθαι, Καίσαρι δὲ ῥαβδουχίαν πέμψαι καὶ στρατηγικὰ κόσμια, Πάνσαν δὲ καὶ Ἵρτιον ἀποστέλλειν ἐξελῶντας Ἀντώνιον ἐκ τῆς Ἰταλίας. οὗτοι δὲ ἦσαν ὕπατοι τότε· καὶ συμβαλόντες Ἀντωνίῳ περὶ πόλιν Μυτίνην, Καίσαρος παρόντος καὶ συμμαχομένου, τοὺς μὲν πολεμίους ἐνίκων, αὐτοὶ δὲ ἀπέθανον. φεύγοντι δὲ Ἀντωνίῳ πολλὰ συνέπιπτε τῶν ἀπόρων, ὁ δὲ λιμὸς ἀπορώτατον. ἀλλὰ φύσει παρὰ τὰς κακοπραγίας ἐγίνετο βέλτιστος ἑαυτοῦ καὶ δυστυχῶν ὁμοιότατος ἦν ἀγαθῷ, κοινοῦ μὲν ὄντος τοῦ αἰσθάνεσθαι τῆς ἀρετῆς τοῖς δι’ ἀπορίαν τινὰ σφαλλομένοις, οὐ μὴν ἁπάντων ἃ ζηλοῦσι μιμεῖσθαι καὶ φεύγειν ἃ δυσχεραίνουσιν ἐρρωμένων ἐν ταῖς μεταβολαῖς, ἀλλὰ καὶ μᾶλλον ἐνίων τοῖς ἔθεσιν ἐνδιδόντων ὑπὸ ἀσθενείας καὶ θραυομένων τὸν λογισμόν. ὁ δ’ οὖν Ἀντώνιος τότε θαυμαστὸν ἦν παράδειγμα τοῖς στρατιώταις, ἀπὸ τρυφῆς τοσαύτης καὶ πολυτελείας ὕδωρ τε πίνων διεφθαρμένον εὐκόλως, καὶ καρποὺς ἀγρίους καὶ ῥίζας προσφερόμενος. ἐβρώθη δὲ καὶ φλοιός, ὡς λέγεται, καὶ ζῴων ἀγεύστων πρότερον ἥψαντο τὰς Ἄλπεις ὑπερβάλλοντες.", "st": "Ant. 17.1"}, {"sp": "N", "t": "ἦν δὲ ὁρμὴ τοῖς ἐπέκεινα στρατεύμασιν ἐντυχεῖν, ὧν Λέπιδος ἦρχε, φίλος εἶναι δοκῶν Ἀντωνίου καὶ πολλὰ τῆς Καίσαρος φιλίας ἀπολελαυκέναι δι’ αὐτόν. ἐλθὼν δὲ καὶ παραστρατοπεδεύσας πλησίον, ὡς οὐθὲν ἀπήντα φιλάνθρωπον, ἔγνω παραβαλέσθαι. καὶ κόμη μὲν ἀτημελὴς καὶ βαθὺς πώγων μετὰ τὴν ἧτταν εὐθὺς ἦν αὐτῷ καθειμένος, λαβὼν δὲ φαιὸν ἱμάτιον ἐγγὺς προσῆγε τῷ χάρακι τοῦ Λεπίδου καὶ λέγειν ἤρξατο. πολλῶν δὲ καὶ πρὸς τὴν ὄψιν ἐπικλωμένων καὶ τοῖς λόγοις ἀγομένων, δείσας ὁ Λέπιδος τὰς σάλπιγγας ἐκέλευσε συνηχούσας ἀφελέσθαι τὸ κατακούεσθαι τὸν Ἀντώνιον. οἱ δὲ στρατιῶται μᾶλλον ᾤκτειραν καὶ διελέγοντο κρύφα, Λαίλιον καὶ Κλώδιον ἀποστείλαντες πρὸς αὐτόν, ἐσθῆτας λαβόντας ἑταιρευομένων γυναικῶν, οἳ τὸν Ἀντώνιον ἐκέλευον ἐπιχειρεῖν θαρροῦντα τῷ χάρακι· πολλοὺς γὰρ εἶναι δεξομένους καὶ τὸν Λέπιδον, εἰ βούλοιτο, κτενοῦντας. Ἀντώνιος δὲ Λεπίδου μὲν οὐκ εἴασεν ἅψασθαι, μεθ’ ἡμέραν δὲ τὸν στρατὸν ἔχων ἀπεπειρᾶτο τοῦ ποταμοῦ. καὶ πρῶτος αὐτὸς ἐμβὰς ἐπορεύετο πρὸς τὴν ἀντιπέρας ὄχθην, ὁρῶν ἤδη πολλοὺς τῶν Λεπίδου στρατιωτῶν τάς τε χεῖρας ὀρέγοντας αὐτῷ καὶ τὸν χάρακα διασπῶντας. εἰσελθὼν δὲ καὶ κρατήσας ἁπάντων ἡμερώτατα Λεπίδῳ προσηνέχθη. πατέρα γὰρ προσηγόρευσεν αὐτὸν ἀσπασάμενος· καὶ τῷ μὲν ἔργῳ πάντων αὐτὸς ἦν κύριος, ἐκείνῳ δ’ ὄνομα καὶ τιμὴν αὐτοκράτορος διετέλει φυλάττων. τοῦτο καὶ Πλάγκον αὐτῷ Μουνάτιον ἐποίησε προσθέσθαι, καθήμενον οὐ πρόσω μετὰ συχνῆς δυνάμεως. οὕτω δὲ μέγας ἀρθεὶς αὖθις ὑπερέβαλε τὰς Ἄλπεις, εἰς τὴν Ἰταλίαν ἄγων ἑπτακαίδεκα τέλη πεζῶν σὺν αὑτῷ καὶ μυρίους ἱππεῖς· χωρὶς δὲ φρουρὰν Γαλατίας ἓξ τάγματα λελοίπει μετὰ Οὐαρίου τινὸς τῶν συνήθων καὶ συμποτῶν, ὃν Κοτύλωνα προσηγόρευον.", "st": "Ant. 18.1"}, {"sp": "N", "t": "Καῖσαρ δὲ Κικέρωνι μὲν οὐκέτι προσεῖχε, τῆς ἐλευθερίας ὁρῶν περιεχόμενον, Ἀντώνιον δὲ προὐκαλεῖτο διὰ τῶν φίλων εἰς διαλύσεις. καὶ συνελθόντες οἱ τρεῖς εἰς νησῖδα ποταμῷ περιρρεομένην ἐπὶ τρεῖς ἡμέρας συνήδρευσαν. καὶ τἆλλα μὲν ἐπιεικῶς ὡμολογεῖτο, καὶ διενείμαντο τὴν σύμπασαν ἀρχὴν ὥσπερ οὐσίαν πατρῴαν ἀλλήλοις, ἡ δὲ περὶ τῶν ἀπολουμένων ἀνδρῶν ἀμφισβήτησις αὐτοῖς πλεῖστα πράγματα παρέσχε, τοὺς μὲν ἐχθροὺς ἀνελεῖν ἑκάστου, σῶσαι δὲ τοὺς προσήκοντας ἀξιοῦντος. τέλος δὲ τῇ πρὸς τοὺς μισουμένους ὀργῇ καὶ συγγενῶν τιμὴν καὶ φίλων εὔνοιαν προέμενοι, Κικέρωνος μὲν Ἀντωνίῳ Καῖσαρ ἐξέστη, τούτῳ δὲ Ἀντώνιος Λευκίου Καίσαρος, ὃς ἦν θεῖος αὐτῷ πρὸς μητρός· ἐδόθη δὲ καὶ Λεπίδῳ Παῦλον ἀνελεῖν τὸν ἀδελφόν· οἱ δέ φασιν ἐκστῆναι τοῦ Παύλου τὸν Λέπιδον ἐκείνοις ἀποθανεῖν αὐτὸν αἰτησαμένοις. οὐδὲν ὠμότερον οὐδὲ ἀγριώτερον τῆς διαμείψεως ταύτης δοκῶ γενέσθαι. φόνων γὰρ ἀντικαταλλασσόμενοι φόνους ὁμοίως μὲν οἷς ἐλάμβανον ἀνῄρουν οὓς ἐδίδοσαν, ἀδικώτεροι δὲ περὶ τοὺς φίλους ἦσαν, οὓς ἀπεκτίννυσαν μηδὲ μισοῦντες.", "st": "Ant. 19.1"}, {"sp": "N", "t": "ἐπὶ δ’ οὖν ταῖς διαλλαγαῖς ταύταις οἱ στρατιῶται περιστάντες ἠξίουν καὶ γάμῳ τινὶ τὴν φιλίαν συνάψαι Καίσαρα, λαβόντα τὴν Φουλβίας τῆς Ἀντωνίου γυναικὸς θυγατέρα Κλωδίαν. ὁμολογηθέντος δὲ καὶ τούτου τριακόσιοι μὲν ἐκ προγραφῆς ἐθανατώθησαν ὑπ’ αὐτῶν· Κικέρωνος δὲ σφαγέντος ἐκέλευσεν Ἀντώνιος τήν τε κεφαλὴν ἀποκοπῆναι καὶ τὴν χεῖρα τὴν δεξιάν, ᾗ τοὺς κατ’ αὐτοῦ λόγους ἔγραψε. καὶ κομισθέντων ἐθεᾶτο γεγηθὼς καὶ ἀνακαγχάζων ὑπὸ χαρᾶς πολλάκις· εἶτα ἐμπλησθεὶς ἐκέλευσεν ὑπὲρ τοῦ βήματος ἐν ἀγορᾷ τεθῆναι, καθάπερ εἰς τὸν νεκρὸν ὑβρίζων, οὐχ αὑτὸν ἐνυβρίζοντα τῇ τύχῃ καὶ καταισχύνοντα τὴν ἐξουσίαν ἐπιδεικνύμενος. ὁ δὲ θεῖος αὐτοῦ Καῖσαρ ζητούμενος καὶ διωκόμενος κατέφυγε πρὸς τὴν ἀδελφήν. ἡ δέ, τῶν σφαγέων ἐπιστάντων καὶ βιαζομένων εἰς τὸ δωμάτιον αὐτῆς, ἐν ταῖς θύραις στᾶσα καὶ διασχοῦσα τὰς χεῖρας ἐβόα πολλάκις· οὐκ ἀποκτενεῖτε Καίσαρα Λεύκιον, ἐὰν μὴ πρότερον ἐμὲ ἀποκτείνητε τὴν τὸν αὐτοκράτορα τεκοῦσαν. ἐκείνη μὲν οὖν τοιαύτη γενομένη διέκλεψε καὶ διέσωσε τὸν ἀδελφόν.", "st": "Ant. 20.1"}, {"sp": "N", "t": "ἦν δὲ καὶ τὰ πολλὰ Ῥωμαίοις ἐπαχθὴς ἡ τῶν τριῶν ἀρχή· καὶ τὸ πλεῖστον ὁ Ἀντώνιος τῆς αἰτίας εἶχε, πρεσβύτερος μὲν ὢν Καίσαρος, Λεπίδου δὲ δυνατώτερος, εἰς δὲ τὸν βίον ἐκεῖνον αὖθις τὸν ἡδυπαθῆ καὶ ἀκόλαστον, ὡς πρῶτον ἀνεχαίτισε τῶν πραγμάτων, ἐκκεχυμένος. προσῆν δὲ τῇ κοινῇ κακοδοξίᾳ τὸ διὰ τὴν οἰκίαν οὐ μικρὸν μῖσος, ἣν ᾤκει, Πομπηΐου τοῦ Μεγάλου γενομένην, ἀνδρὸς οὐχ ἧττον ἐπὶ σωφροσύνῃ καὶ τῷ τεταγμένως καὶ δημοτικῶς διαιτᾶσθαι θαυμασθέντος ἢ διὰ τοὺς τρεῖς θριάμβους. ἤχθοντο γὰρ ὁρῶντες αὐτὴν τὰ πολλὰ κεκλεισμένην μὲν ἡγεμόσι καὶ στρατηγοῖς καὶ πρέσβεσιν, ὠθουμένοις πρὸς ὕβριν ἀπὸ τῶν θυρῶν, μεστὴν δὲ μίμων καὶ θαυματοποιῶν καὶ κολάκων κραιπαλώντων, εἰς οὓς τὰ πλεῖστα κατανηλίσκετο τῶν χρημάτων τῷ βιαιοτάτῳ καὶ χαλεπωτάτῳ τρόπῳ ποριζομένων. οὐ γὰρ μόνον ἐπώλουν οὐσίας τῶν φονευομένων, ἐπισυκοφαντοῦντες οἰκείους καὶ γυναῖκας αὐτῶν, οὐδὲ τελῶν πᾶν ἐκίνησαν γένος, ἀλλὰ καὶ παρὰ ταῖς Ἑστιάσι πυθόμενοι παρθένοις παρακαταθήκας τινὰς κεῖσθαι καὶ ξένων καὶ πολιτῶν ἔλαβον ἐπελθόντες. ὡς δὲ οὐδὲν ἦν ἱκανὸν Ἀντωνίῳ, Καῖσαρ ἠξίωσε νείμασθαι τὰ χρήματα πρὸς αὐτόν. ἐνείμαντο δὲ καὶ τὸν στρατόν, ἐπὶ Βροῦτον καὶ Κάσσιον εἰς Μακεδονίαν στρατεύοντες ἀμφότεροι, Λεπίδῳ δὲ τὴν Ῥώμην ἐπέτρεψαν.", "st": "Ant. 21.1"}, {"sp": "N", "t": "ὡς μέντοι διαβάντες ἥψαντο πολέμου καὶ παρεστρατοπέδευσαν τοῖς πολεμίοις, Ἀντωνίου μὲν ἀντιτεταγμένου Κασσίῳ, Βρούτῳ δὲ Καίσαρος, οὐθὲν ἔργον ἐφάνη μέγα τοῦ Καίσαρος, ἀλλ’ Ἀντώνιος ἦν ὁ νικῶν πάντα καὶ κατορθῶν. τῇ μέν γε προτέρᾳ μάχῃ Καῖσαρ ὑπὸ Βρούτου κατὰ κράτος ἡττηθεὶς ἀπέβαλε τὸ στρατόπεδον, καὶ μικρὸν ἔφθη τοὺς διώκοντας ὑπεκφυγών· ὡς δὲ αὐτὸς ἐν τοῖς ὑπομνήμασι γέγραφε, τῶν φίλων τινὸς ὄναρ ἰδόντος ἀνεχώρησε πρὸ τῆς μάχης. Ἀντώνιος δὲ Κάσσιον ἐνίκησε· καίτοι γεγράφασιν ἔνιοι μὴ παραγενέσθαι τῇ μάχῃ τὸν Ἀντώνιον, ἀλλὰ προσγενέσθαι μετὰ τὴν μάχην ἤδη διώκουσι. Κάσσιον δὲ Πίνδαρος τῶν πιστῶν τις ἀπελευθέρων αὐτοῦ δεομένου καὶ κελεύοντος ἔσφαξεν· οὐ γὰρ ἔγνω νενικηκότα Βροῦτον. ὀλίγων δὲ ἡμερῶν διαγενομένων πάλιν ἐμαχέσαντο· καὶ Βροῦτος μὲν ἡττηθεὶς ἑαυτὸν ἀνεῖλεν, Ἀντώνιος δὲ τῆς νίκης ἠνέγκατο τῇ δόξῃ τὸ πλεῖστον, ἅτε δὴ καὶ νοσοῦντος τοῦ Καίσαρος. ἐπιστὰς δὲ τῷ Βρούτου νεκρῷ μικρὰ μὲν ὠνείδισεν ὑπὲρ τῆς Γαΐου τοῦ ἀδελφοῦ τελευτῆς (ἀνῃρήκει γὰρ ἐκεῖνον ὁ Βροῦτος ἐν Μακεδονίᾳ Κικέρωνι τιμωρῶν), φήσας δὲ μᾶλλον Ὁρτήσιον ἢ Βροῦτον αἰτιᾶσθαι τῆς τοῦ ἀδελφοῦ σφαγῆς Ὁρτήσιον μὲν ἐκέλευσεν ἐπισφάξαι τῷ μνήματι, Βρούτῳ δὲ τὴν αὑτοῦ φοινικίδα πολλῶν χρημάτων ἀξίαν οὖσαν ἐπέρριψε, καὶ τῶν ἀπελευθέρων τινὶ τῶν ἑαυτοῦ προσέταξε τῆς ταφῆς ἐπιμεληθῆναι. τοῦτον ὕστερον γνοὺς οὐ συγκατακαύσαντα τὴν φοινικίδα τῷ νεκρῷ καὶ πολλὰ τῆς εἰς τὴν ταφὴν δαπάνης ὑφῃρημένον ἀπέκτεινεν.", "st": "Ant. 22.1"}, {"sp": "N", "t": "ἐκ τούτου Καῖσαρ μὲν εἰς Ῥώμην ἐκομίζετο, δοκῶν οὐ περιέσεσθαι πολὺν χρόνον ἐκ τῆς ἀρρωστίας, Ἀντώνιος δὲ τὰς πρὸς ἕω πάσας ἐπαρχίας ἀργυρολογήσων διέβαινεν εἰς τὴν Ἑλλάδα, πολλὴν στρατιὰν ἄγων· ὑπεσχημένοι γὰρ ἑκάστῳ στρατιώτῃ δραχμὰς πεντακισχιλίας ἐδέοντο συντονωτέρου χρηματισμοῦ καὶ δασμολογίας. τοῖς μὲν οὖν Ἕλλησιν οὐκ ἄτοπος οὐδὲ φορτικὸς συνηνέχθη τό γε πρῶτον, ἀλλὰ καὶ τὸ παῖζον αὑτοῦ πρὸς ἀκροάσεις φιλολόγων καὶ θέας ἀγώνων καὶ μυήσεις ἔτρεπε, καὶ περὶ τὰς κρίσεις ἦν ἐπιεικής, καὶ φιλέλλην ἀκούων ἔχαιρεν, ἔτι δὲ μᾶλλον φιλαθήναιος προσαγορευόμενος, καὶ τῇ πόλει πλείστας δωρεὰς ἔδωκε. βουλομένων δέ τι καὶ Μεγαρέων καλὸν ἀντεπιδείξασθαι ταῖς Ἀθήναις καὶ τὸ βουλευτήριον ἰδεῖν αὐτὸν ἀξιωσάντων ἀναβὰς καὶ θεασάμενος, ὡς ἐπυνθάνοντο τί δοκοίη, μικρὸν μέν, ἔφη, σαπρὸν δέ. καὶ τὸν τοῦ Πυθίου νεὼν κατεμέτρησεν ὡς συντελέσων· τοῦτο γὰρ ὑπέσχετο πρὸς τὴν σύγκλητον.", "st": "Ant. 23.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Λεύκιον Κηνσωρῖνον ἐπὶ τῆς Ἑλλάδος καταλιπὼν εἰς Ἀσίαν διέβη καὶ τῶν ἐκεῖ πλούτων ἥψατο, καὶ βασιλεῖς ἐπὶ θύρας ἐφοίτων καὶ βασιλέων γυναῖκες ἁμιλλώμεναι δωρεαῖς πρὸς ἀλλήλας καὶ κάλλεσιν ἐφθείροντο πρὸς αὐτόν, ἐν Ῥώμῃ δὲ Καίσαρος στάσεσι καὶ πολέμοις ἀποτρυχομένου πολλὴν αὐτὸς ἄγων σχολὴν καὶ εἰρήνην ἀνεκυκλεῖτο τοῖς πάθεσιν εἰς τὸν συνήθη βίον, Ἀναξήνορες δὲ κιθαρῳδοὶ καὶ Ξοῦθοι χοραῦλαι καὶ Μητρόδωρός τις ὀρχηστὴς καὶ τοιοῦτος ἄλλος Ἀσιανῶν ἀκροαμάτων θίασος, ὑπερβαλλομένων λαμυρίᾳ καὶ βωμολοχίᾳ τὰς ἀπὸ τῆς Ἰταλίας κῆρας, εἰσερρύη καὶ διῴκει τὴν αὐλήν, οὐδὲν ἦν ἀνεκτόν, εἰς ταῦτα φορουμένων ἁπάντων. ἡ γὰρ Ἀσία πᾶσα, καθάπερ ἡ Σοφόκλειος ἐκείνη πόλις, ὁμοῦ μὲν θυμιαμάτων ἔγεμεν,", "st": "Ant. 24.1"}, {"sp": "N", "t": "ὁμοῦ δὲ παιάνων τε καὶ στεναγμάτων.", "st": "Ant. 24.1b"}, {"sp": "N", "t": "εἰς γοῦν Ἔφεσον εἰσιόντος αὐτοῦ γυναῖκες μὲν εἰς Βάκχας, ἄνδρες δὲ καὶ παῖδες εἰς Σατύρους καὶ Πᾶνας ἡγοῦντο διεσκευασμένοι, κιττοῦ δὲ καὶ θύρσων καὶ ψαλτηρίων καὶ συρίγγων καὶ αὐλῶν ἡ πόλις ἦν πλέα, Διόνυσον αὐτὸν ἀνακαλουμένων χαριδότην καὶ μειλίχιον. ἦν γὰρ ἀμέλει τοιοῦτος ἐνίοις, τοῖς δὲ πολλοῖς ὠμηστὴς καὶ ἀγριώνιος. ἀφῃρεῖτο γὰρ εὐγενεῖς ἀνθρώπους τὰ ὄντα μαστιγίαις καὶ κόλαξι χαριζόμενος. πολλῶν δὲ καὶ ζώντων ὡς τεθνηκότων αἰτησάμενοί τινες οὐσίας ἔλαβον. ἀνδρὸς δὲ Μάγνητος οἶκον ἐδωρήσατο μαγείρῳ περὶ ἕν, ὡς λέγεται, δεῖπνον εὐδοκιμήσαντι. τέλος δέ, ταῖς πόλεσι δεύτερον ἐπιβάλλοντος φόρον, ἐτόλμησεν Ὑβρέας ὑπὲρ τῆς Ἀσίας λέγων εἰπεῖν ἀγοραίως μὲν ἐκεῖνα καὶ πρὸς τὸν Ἀντωνίου ζῆλον οὐκ ἀηδῶς, εἰ δύνασαι δὶς λαβεῖν ἑνὸς ἐνιαυτοῦ φόρον, δύνασαι καὶ δὶς ἡμῖν ποιήσασθαι θέρος καὶ δὶς ὀπώραν, πρακτικῶς δὲ καὶ παραβόλως συναγαγὼν ὅτι μυριάδας εἴκοσι ταλάντων ἡ Ἀσία δέδωκε, ταῦτα, εἶπεν, εἰ μὲν οὐκ εἴληφας, ἀπαίτει παρὰ τῶν λαβόντων· εἰ δὲ λαβὼν οὐκ ἔχεις, ἀπολώλαμεν. ἐτρέψατο τούτῳ δεινῶς τὸν Ἀντώνιον· ἠγνόει γὰρ τὰ πολλὰ τῶν γιγνομένων, οὐχ οὕτω ῥᾴθυμος ὤν, ὡς δι’ ἁπλότητα πιστεύων τοῖς περὶ αὑτόν.", "st": "Ant. 24.4"}, {"sp": "N", "t": "ἐνῆν γὰρ ἁπλότης τῷ ἤθει καὶ βραδεῖα μὲν αἴσθησις, αἰσθανομένῳ δὲ τῶν ἁμαρτανομένων ἰσχυρὰ μετάνοια καὶ πρὸς αὐτοὺς ἐξομολόγησις τοὺς ἀγνωμονηθέντας, μέγεθος δὲ καὶ περὶ τὰς ἀμοιβὰς καὶ περὶ τὰς τιμωρίας. μᾶλλόν γε μὴν ἐδόκει χαριζόμενος ἢ κολάζων ὑπερβάλλειν τὸ μέτριον. ἡ δὲ περὶ τὰς παιδιὰς καὶ τὰς ἐπισκώψεις ὕβρις ἐν αὑτῇ τὸ φάρμακον εἶχεν. ἀντισκῶψαι γὰρ ἐξῆν καὶ ἀνθυβρίσαι, καὶ γελώμενος οὐχ ἧττον ἢ γελῶν ἔχαιρε. καὶ τοῦτο διελυμήνατο τὰ πολλὰ τῶν πραγμάτων. τοὺς γὰρ ἐν τῷ παίζειν παρρησιαζομένους οὐκ ἂν οἰηθεὶς σπουδάζοντας κολακεύειν αὐτὸν ἡλίσκετο ῥᾳδίως ὑπὸ τῶν ἐπαίνων, ἀγνοῶν ὅτι τὴν παρρησίαν τινὲς ὡς ὑποστῦφον ἥδυσμα τῇ κολακείᾳ παραμιγνύντες ἀφῄρουν τὸ πλήσμιον, τῇ παρὰ τὴν κύλικα θρασύτητι καὶ λαλιᾷ διαμηχανώμενοι τὴν ἐπὶ τῶν πραγμάτων ὕφεσιν καὶ συγκατάθεσιν μὴ πρὸς χάριν ὁμιλούντων, ἀλλὰ τῷ φρονεῖν ἡττωμένων φαίνεσθαι.", "st": "Ant. 24.7"}, {"sp": "N", "t": "τοιούτῳ δ’ οὖν ὄντι τὴν φύσιν Ἀντωνίῳ τελευταῖον κακὸν ὁ Κλεοπάτρας ἔρως ἐπιγενόμενος, καὶ πολλὰ τῶν ἔτι κρυπτομένων ἐν αὐτῷ καὶ ἀτρεμούντων παθῶν ἐγείρας καὶ ἀναβακχεύσας, εἴ τι χρηστὸν ἢ σωτήριον ὅμως ἀντεῖχεν, ἠφάνισε καὶ προσδιέφθειρεν. ἁλίσκεται δὲ τοῦτον τὸν τρόπον. ἁπτόμενος τοῦ Παρθικοῦ πολέμου ἔπεμψε πρὸς αὐτήν, κελεύων εἰς Κιλικίαν ἀπαντῆσαι λόγον ὑφέξουσαν ὧν ἐνεκαλεῖτο τοῖς περὶ Κάσσιον δοῦναι πολλὰ καὶ συμβαλέσθαι πρὸς τὸν πόλεμον. ὁ δὲ πεμφθεὶς Δέλλιος, ὡς εἶδε τὴν ὄψιν καὶ κατέμαθε τὴν ἐν τοῖς λόγοις δεινότητα καὶ πανουργίαν, εὐθὺς αἰσθόμενος ὅτι κακὸν μὲν οὐδὲ μελλήσει τι ποιεῖν γυναῖκα τοιαύτην Ἀντώνιος, ἔσται δὲ μεγίστη παρ’ αὐτῷ, τρέπεται πρὸς τὸ θεραπεύειν καὶ προτρέπεσθαι τὴν Αἰγυπτίαν, τοῦτο δὴ τὸ Ὁμηρικόν, ἐλθεῖν εἰς Κιλικίαν εὖ ἐντύνασαν ἓ αὐτὴν καὶ μὴ φοβεῖσθαι τὸν Ἀντώνιον, ἥδιστον ἡγεμόνων ὄντα καὶ φιλανθρωπότατον. ἡ δὲ καὶ Δελλίῳ πεισθεῖσα, καὶ τοῖς πρὸς Καίσαρα καὶ Γναῖον τὸν Πομπηΐου παῖδα πρότερον αὐτῇ γενομένοις ἀφ’ ὥρας συμβολαίοις τεκμαιρομένη, ῥᾷον ἤλπιζεν ὑπάξεσθαι τὸν Ἀντώνιον. ἐκεῖνοι μὲν γὰρ αὐτὴν ἔτι κόρην καὶ πραγμάτων ἄπειρον ἔγνωσαν, πρὸς δὲ τοῦτον ἔμελλε φοιτήσειν ἐν ᾧ μάλιστα καιροῦ γυναῖκες ὥραν τε λαμπροτάτην ἔχουσι καὶ τὸ φρονεῖν ἀκμάζουσι. διὸ πολλὰ μὲν συνεσκευάσατο δῶρα καὶ χρήματα καὶ κόσμον οἷον εἰκὸς ἦν ἀπὸ πραγμάτων μεγάλων καὶ βασιλείας εὐδαίμονος κομίζειν, τὰς δὲ πλείστας ἐν ἑαυτῇ καὶ τοῖς περὶ αὑτὴν μαγγανεύμασι καὶ φίλτροις ἐλπίδας θεμένη παρεγένετο.", "st": "Ant. 25.1"}, {"sp": "N", "t": "πολλὰ δὲ καὶ παρ’ αὐτοῦ καὶ παρὰ τῶν φίλων δεχομένη γράμματα καλούντων, οὕτω κατεφρόνησε καὶ κατεγέλασε τοῦ ἀνδρὸς ὥστε πλεῖν ἀνὰ τὸν Κύδνον ποταμὸν ἐν πορθμείῳ χρυσοπρύμνῳ, τῶν μὲν ἱστίων ἁλουργῶν ἐκπεπετασμένων, τῆς δὲ εἰρεσίας ἀργυραῖς κώπαις ἀναφερομένης πρὸς αὐλὸν ἅμα σύριγξι καὶ κιθάραις συνηρμοσμένον. αὐτὴ δὲ κατέκειτο μὲν ὑπὸ σκιάδι χρυσοπάστῳ κεκοσμημένη γραφικῶς ὥσπερ Ἀφροδίτη, παῖδες δὲ τοῖς γραφικοῖς Ἔρωσιν εἰκασμένοι παρ’ ἑκάτερον ἑστῶτες ἐρρίπιζον. ὁμοίως δὲ καὶ θεραπαινίδες αἱ καλλιστεύουσαι Νηρηΐδων ἔχουσαι καὶ Χαρίτων στολάς, αἱ μὲν πρὸς οἴαξιν, αἱ δὲ πρὸς κάλοις ἦσαν. ὀδμαὶ δὲ θαυμασταὶ τὰς ὄχθας ἀπὸ θυμιαμάτων πολλῶν κατεῖχον. τῶν δὲ ἀνθρώπων οἱ μὲν εὐθὺς ἀπὸ τοῦ ποταμοῦ παρωμάρτουν ἑκατέρωθεν, οἱ δὲ ἀπὸ τῆς πόλεως κατέβαινον ἐπὶ τὴν θέαν. ἐκχεομένου δὲ τοῦ κατὰ τὴν ἀγορὰν ὄχλου τέλος αὐτὸς ὁ Ἀντώνιος ἐπὶ βήματος καθεζόμενος ἀπελείφθη μόνος. καί τις λόγος ἐχώρει διὰ πάντων ὡς ἡ Ἀφροδίτη κωμάζοι παρὰ τὸν Διόνυσον ἐπ’ ἀγαθῷ τῆς Ἀσίας.", "st": "Ant. 26.1"}, {"sp": "N", "t": "ἔπεμψε μὲν οὖν καλῶν αὐτὴν ἐπὶ τὸ δεῖπνον· ἡ δὲ μᾶλλον ἐκεῖνον ἠξίου πρὸς ἑαυτὴν ἥκειν. εὐθὺς οὖν τινὰ βουλόμενος εὐκολίαν ἐπιδείκνυσθαι καὶ φιλοφροσύνην ὑπήκουσε καὶ ἦλθεν. ἐντυχὼν δὲ παρασκευῇ λόγου κρείττονι μάλιστα τῶν φώτων τὸ πλῆθος ἐξεπλάγη. τοσαῦτα γὰρ λέγεται καθίεσθαι καὶ ἀναφαίνεσθαι πανταχόθεν ἅμα, καὶ τοιαύταις πρὸς ἄλληλα κλίσεσι καὶ θέσεσι διακεκοσμημένα καὶ συντεταγμένα πλαισίων καὶ περιφερῶν τρόπῳ, ὥστε τῶν ἐν ὀλίγοις ἀξιοθεάτων καὶ καλῶν ἐκείνην γενέσθαι τὴν ὄψιν.", "st": "Ant. 26.4"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ πάλιν ἀνθεστιῶν αὐτὴν ἐφιλοτιμήθη μὲν ὑπερβαλέσθαι τὴν λαμπρότητα καὶ τὴν ἐμμέλειαν, ἀμφοῖν δὲ λειπόμενος, καὶ κρατούμενος ἐν αὐτοῖς ἐκείνοις, πρῶτος ἔσκωπτεν εἰς αὐχμὸν καὶ ἀγροικίαν τὰ παρ’ αὑτῷ. πολὺν δὲ ἡ Κλεοπάτρα καὶ τοῖς σκώμμασι τοῦ Ἀντωνίου τὸν στρατιώτην ἐνορῶσα καὶ βάναυσον, ἐχρῆτο καὶ τούτῳ πρὸς αὐτὸν ἀνειμένως ἤδη καὶ κατατεθαρρηκότως. καὶ γὰρ ἦν, ὡς λέγουσιν, αὐτὸ μὲν καθ’ αὑτὸ τὸ κάλλος αὐτῆς οὐ πάνυ δυσπαράβλητον, οὐδὲ οἷον ἐκπλῆξαι τοὺς ἰδόντας, ἁφὴν δ’ εἶχεν ἡ συνδιαίτησις ἄφυκτον, ἥ τε μορφὴ μετὰ τῆς ἐν τῷ διαλέγεσθαι πιθανότητος καὶ τοῦ περιθέοντος ἅμα πως περὶ τὴν ὁμιλίαν ἤθους ἀνέφερέ τι κέντρον. ἡδονὴ δὲ καὶ φθεγγομένης ἐπῆν τῷ ἤχῳ· καὶ τὴν γλῶτταν, ὥσπερ ὄργανόν τι πολύχορδον, εὐπετῶς τρέπουσα καθ’ ἣν βούλοιτο διάλεκτον ὀλίγοις παντάπασι δι’ ἑρμηνέως ἐνετύγχανε βαρβάροις, τοῖς δὲ πλείστοις αὐτὴ δι’ αὑτῆς ἀπεδίδου τὰς ἀποκρίσεις, οἷον Αἰθίοψι, Τρωγλοδύταις, Ἑβραίοις, Ἄραψι, Σύροις, Μήδοις, Παρθυαίοις. πολλῶν δὲ λέγεται καὶ ἄλλων ἐκμαθεῖν γλώττας, τῶν πρὸ αὐτῆς βασιλέων οὐδὲ τὴν Αἰγυπτίαν ἀνασχομένων παραλαβεῖν διάλεκτον, ἐνίων δὲ καὶ τὸ μακεδονίζειν ἐκλιπόντων.", "st": "Ant. 27.1"}, {"sp": "N", "t": "οὕτω δ’ οὖν τὸν Ἀντώνιον ἥρπασεν ὥστε, πολεμούσης μὲν ἐν Ῥώμῃ Καίσαρι Φουλβίας τῆς γυναικὸς ὑπὲρ τῶν ἐκείνου πραγμάτων, αἰωρουμένης δὲ Παρθικῆς στρατιᾶς περὶ τὴν Μεσοποταμίαν, ἧς Λαβιηνὸν οἱ βασιλέως στρατηγοὶ Παρθικὸν ἀναγορεύσαντες αὐτοκράτορα Συρίας ἐπιβατεύσειν ἔμελλον, οἴχεσθαι φερόμενον ὑπ’ αὐτῆς εἰς Ἀλεξάνδρειαν, ἐκεῖ δὲ μειρακίου σχολὴν ἄγοντος διατριβαῖς καὶ παιδιαῖς χρώμενον ἀναλίσκειν καὶ καθηδυπαθεῖν τὸ πολυτελέστατον, ὡς Ἀντιφῶν εἶπεν, ἀνάλωμα, τὸν χρόνον. ἦν γάρ τις αὐτοῖς σύνοδος ἀμιμητοβίων λεγομένη· καὶ καθ’ ἡμέραν εἱστίων ἀλλήλους, ἄπιστόν τινα ποιούμενοι τῶν ἀναλισκομένων ἀμετρίαν. διηγεῖτο γοῦν ἡμῶν τῷ πάππῳ Λαμπρίᾳ Φιλώτας ὁ Ἀμφισσεὺς ἰατρὸς εἶναι μὲν ἐν Ἀλεξανδρείᾳ τότε, μανθάνων τὴν τέχνην, γενόμενος δέ τινι τῶν βασιλικῶν ὀψοποιῶν συνήθης ἀναπεισθῆναι νέος ὢν ὑπ’ αὐτοῦ τὴν πολυτέλειαν καὶ τὴν παρασκευὴν τοῦ δείπνου θεάσασθαι. παρεισαχθεὶς οὖν εἰς τοὐπτανεῖον, ὡς τά τε ἄλλα πάμπολλα ἑώρα καὶ σῦς ἀγρίους ὀπτωμένους ὀκτώ, θαυμάσαι τὸ πλῆθος τῶν δειπνούντων.", "st": "Ant. 28.1"}, {"sp": "N", "t": "τὸν δὲ ὀψοποιὸν γελάσαι καὶ εἰπεῖν ὅτι πολλοὶ μὲν οὐκ εἰσὶν οἱ δειπνοῦντες, ἀλλὰ περὶ δώδεκα· δεῖ δ’ ἀκμὴν ἔχειν τῶν παρατιθεμένων ἕκαστον, ἣν ἀκαρὲς ὥρας μαραίνει. καὶ γὰρ αὐτίκα γένοιτ’ ἂν Ἀντώνιον δείπνου δεηθῆναι καὶ μετὰ μικρόν, ἂν δὲ οὕτω τύχῃ, παραγαγεῖν αἰτήσαντα ποτήριον ἢ λόγου τινὸς ἐμπεσόντος. ὅθεν οὐχ ἕν, ἀλλὰ πολλά, φάναι, δεῖπνα συντέτακται· δυσστόχαστος γὰρ ὁ καιρός. ταῦτα οὖν ὁ Φιλώτας ἔλεγε, καὶ χρόνου προϊόντος ἐν τοῖς θεραπεύουσι γενέσθαι τὸν πρεσβύτατον τῶν Ἀντωνίου παίδων, ὃν ἐκ Φουλβίας εἶχε, καὶ συνδειπνεῖν παρ’ αὐτῷ μετὰ τῶν ἄλλων ἑταίρων ἐπιεικῶς, ὁπότε μὴ δειπνοίη μετὰ τοῦ πατρός. ἰατρὸν οὖν ποτε θρασυνόμενον καὶ πράγματα πολλὰ παρέχοντα δειπνοῦσιν αὐτοῖς ἐπιστομίσαι τοιούτῳ σοφίσματι· τῷ πως πυρέττοντι δοτέον ψυχρόν· πᾶς δὲ ὁ πυρέττων πως πυρέττει· παντὶ ἄρα πυρέττοντι δοτέον ψυχρόν. πληγέντος δὲ τοῦ ἀνθρώπου καὶ σιωπήσαντος, ἡσθέντα τὸν παῖδα γελάσαι καὶ εἰπεῖν, ταῦτα, ὦ Φιλώτα, χαρίζομαι πάντα σοι, δείξαντα πολλῶν τινων καὶ μεγάλων ἐκπωμάτων μεστὴν τράπεζαν. αὐτοῦ δὲ τὴν μὲν προθυμίαν ἀποδεξαμένου, πόρρω δ’ ὄντος τοῦ νομίζειν ἐξουσίαν εἶναι παιδὶ τηλικούτῳ δωρεῖσθαι τοσαῦτα, μετὰ μικρὸν ἁψάμενόν τινα τῶν παίδων ἐν ἀγγείῳ τὰ ἐκπώματα προσφέρειν καὶ σημήνασθαι κελεύειν.", "st": "Ant. 28.4"}, {"sp": "N", "t": "ἀφοσιουμένου δὲ αὐτοῦ καὶ δεδοικότος λαβεῖν, τί, ὦ πόνηρε, φάναι τὸν ἄνθρωπον, ὀκνεῖς; οὐκ οἶδας ὡς ὁ διδοὺς Ἀντωνίου παῖς ἐστιν, ᾧ τοσαῦτα πάρεστι χρυσᾶ χαρίσασθαι; ἐμοὶ μέντοι πειθόμενος πάντα διάμειψαι πρὸς ἀργύριον ἡμῖν· ἴσως γὰρ ἂν καὶ ποθήσειεν ὁ πατὴρ ἔνια τῶν παλαιῶν ὄντα καὶ σπουδαζομένων κατὰ τὴν τέχνην ἔργων. ταῦτα μὲν οὖν ἡμῖν ἔλεγεν ὁ πάππος ἑκάστοτε διηγεῖσθαι τὸν Φιλώταν.", "st": "Ant. 28.7"}, {"sp": "N", "t": "ἡ δὲ Κλεοπάτρα τὴν κολακείαν οὐχ, ὥσπερ ὁ Πλάτων φησί, τετραχῆ, πολλαχῆ δὲ διελοῦσα, καὶ σπουδῆς ἁπτομένῳ καὶ παιδιᾶς ἀεί τινα καινὴν ἡδονὴν ἐπιφέρουσα καὶ χάριν, διεπαιδαγώγει τὸν Ἀντώνιον οὔτε νυκτὸς οὔτε ἡμέρας ἀνιεῖσα. καὶ γὰρ συνεκύβευε καὶ συνέπινε καὶ συνεθήρευε καὶ γυμναζόμενον ἐν ὅπλοις ἐθεᾶτο, καὶ νύκτωρ προσισταμένῳ θύραις καὶ θυρίσι δημοτῶν καὶ σκώπτοντι τοὺς ἔνδον συνεπλανᾶτο καὶ συνήλυε θεραπαινιδίου στολὴν λαμβάνουσα καὶ γὰρ ἐκεῖνος οὕτως ἐπειρᾶτο σκευάζειν ἑαυτόν. ὅθεν ἀεὶ σκωμμάτων, πολλάκις δὲ καὶ πληγῶν ἀπολαύσας ἐπανήρχετο· τοῖς δὲ πλείστοις ἦν δι’ ὑπονοίας. οὐ μὴν ἀλλὰ προσέχαιρον αὐτοῦ τῇ βωμολοχίᾳ καὶ συνέπαιζον οὐκ ἀρρύθμως οὐδὲ ἀμούσως οἱ Ἀλεξανδρεῖς, ἀγαπῶντες καὶ λέγοντες ὡς τῷ τραγικῷ πρὸς τοὺς Ῥωμαίους χρῆται προσώπῳ, τῷ δὲ κωμικῷ πρὸς αὐτούς.", "st": "Ant. 29.1"}, {"sp": "N", "t": "τὰ μὲν οὖν πολλὰ τῶν ὑπ’ αὐτοῦ παιζομένων διηγεῖσθαι πολὺς ἂν εἴη φλύαρος· ἐπεὶ δὲ ἁλιεύων ποτὲ καὶ δυσαγρῶν ἤχθετο παρούσης τῆς Κλεοπάτρας, ἐκέλευσε τοὺς ἁλιεῖς ὑπονηξαμένους κρύφα τῷ ἀγκίστρῳ περικαθάπτειν ἰχθῦς τῶν προεαλωκότων, καὶ δὶς ἢ τρὶς ἀνασπάσας οὐκ ἔλαθε τὴν Αἰγυπτίαν. προσποιουμένη δὲ θαυμάζειν τοῖς φίλοις διηγεῖτο, καὶ παρεκάλει τῇ ὑστεραίᾳ γενέσθαι θεατάς. ἐμβάντων δὲ πολλῶν εἰς τὰς ἁλιάδας καὶ τοῦ Ἀντωνίου τὴν ὁρμιὰν καθέντος, ἐκέλευσέ τινα τῶν αὑτῆς ὑποφθάσαντα καὶ προσνηξάμενον τῷ ἀγκίστρῳ περιπεῖραι Ποντικὸν τάριχος. ὡς δὲ ἔχειν πεισθεὶς ὁ Ἀντώνιος ἀνεῖλκε, γέλωτος, οἷον εἰκός, γενομένου, παράδος ἡμῖν, ἔφη, τὸν κάλαμον, αὐτόκρατορ, τοῖς Φαρίταις καὶ Κανωβίταις ἁλιεῦσιν· ἡ δὲ σὴ θήρα πόλεις εἰσὶ καὶ βασιλεῖαι καὶ ἤπειροι.", "st": "Ant. 29.3"}, {"sp": "N", "t": "τοιαῦτα ληροῦντα καὶ μειρακιευόμενον τὸν Ἀντώνιον ἀγγελίαι δύο καταλαμβάνουσιν, ἡ μὲν ἀπὸ Ῥώμης, Λεύκιον τὸν ἀδελφὸν αὐτοῦ καὶ Φουλβίαν τὴν γυναῖκα πρῶτον ἀλλήλοις στασιάσαντας, εἶτα Καίσαρι πολεμήσαντας, ἀποβεβληκέναι τὰ πράγματα καὶ φεύγειν ἐξ Ἰταλίας, ἑτέρα δὲ ταύτης οὐδὲν ἐπιεικεστέρα, Λαβιηνὸν ἐπάγοντα Πάρθους τὴν ἀπ’ Εὐφράτου καὶ Συρίας ἄχρι Λυδίας καὶ Ἰωνίας Ἀσίαν καταστρέφεσθαι. μόλις οὖν ὥσπερ ἐξυπνισθεὶς καὶ ἀποκραιπαλήσας ὥρμησε μὲν Πάρθοις ἐνίστασθαι καὶ μέχρι Φοινίκης προῆλθε, Φουλβίας δὲ γράμματα θρήνων μεστὰ πεμπούσης ἐπέστρεψεν εἰς τὴν Ἰταλίαν, ἄγων ναῦς διακοσίας. ἀναλαβὼν δὲ κατὰ πλοῦν τῶν φίλων τοὺς πεφευγότας ἐπυνθάνετο τοῦ πολέμου τὴν Φουλβίαν αἰτίαν γεγονέναι, φύσει μὲν οὖσαν πολυπράγμονα καὶ θρασεῖαν, ἐλπίζουσαν δὲ τῆς Κλεοπάτρας ἀπάξειν τὸν Ἀντώνιον εἴ τι γένοιτο κίνημα περὶ τὴν Ἰταλίαν. συμβαίνει δὲ ἀπὸ τύχης καὶ Φουλβίαν πλέουσαν πρὸς αὐτὸν ἐν Σικυῶνι νόσῳ τελευτῆσαι· διὸ καὶ μᾶλλον αἱ πρὸς Καίσαρα διαλλαγαὶ καιρὸν ἔσχον. ὡς γὰρ προσέμιξε τῇ Ἰταλίᾳ καὶ Καῖσαρ ἦν φανερὸς ἐκείνῳ μὲν οὐθὲν ἐγκαλῶν, αὐτὸς δ’ ὧν ἐνεκαλεῖτο τὰς αἰτίας τῇ Φουλβία προστριβόμενος, οὐκ εἴων ἐξελέγχειν οἱ φίλοι τὴν πρόφασιν, ἀλλὰ διέλυον ἀμφοτέρους καὶ διῄρουν τὴν ἡγεμονίαν, ὅρον ποιούμενοι τὸν Ἰόνιον, καὶ τὰ μὲν ἑῷα νέμοντες Ἀντωνίῳ, τὰ δ’ ἑσπέρια Καίσαρι, Λέπιδον δὲ Λιβύην ἔχειν ἐῶντες, ὑπατεύειν δὲ τάξαντες, ὅτε μὴ δόξειεν αὐτοῖς, φίλους ἑκατέρων παρὰ μέρος.", "st": "Ant. 30.1"}, {"sp": "N", "t": "ταῦτα ἔχειν καλῶς δοκοῦντα πίστεως ἐδεῖτο σφοδροτέρας, ἣν ἡ τύχη παρέσχεν. Ὀκταουία γὰρ ἦν ἀδελφὴ πρεσβυτέρα μέν, οὐχ ὁμομητρία δὲ Καίσαρι· ἐγεγόνει γὰρ ἐξ Ἀγχαρίας, ὁ δὲ ὕστερον ἐξ Ἀτίας. ἔστεργε δ’ ὑπερφυῶς τὴν ἀδελφήν, χρῆμα θαυμαστόν, ὡς λέγεται, γυναικὸς γενομένην. αὕτη, Γαΐου Μαρκέλλου τοῦ γήμαντος αὐτὴν οὐ πάλαι τεθνηκότος, ἐχήρευεν. ἐδόκει δὲ καὶ Φουλβίας ἀποιχομένης χηρεύειν Ἀντώνιος, ἔχειν μὲν οὐκ ἀρνούμενος Κλεοπάτραν, γάμῳ δὲ οὐχ ὁμολογῶν, ἀλλ’ ἔτι τῷ λόγῳ περί γε τούτου πρὸς τὸν ἔρωτα τῆς Αἰγυπτίας μαχόμενος. τοῦτον ἅπαντες εἰσηγοῦντο τὸν γάμον, ἐλπίζοντες τὴν Ὀκταουίαν ἐπὶ κάλλει τοσούτῳ σεμνότητα καὶ νοῦν ἔχουσαν, εἰς ταὐτὸν τῷ Ἀντωνίῳ παραγενομένην καὶ στερχθεῖσαν, ὡς εἰκὸς τοιαύτην γυναῖκα, πάντων πραγμάτων αὐτοῖς σωτηρίαν ἔσεσθαι καὶ σύγκρασιν. ὡς οὖν ἔδοξεν ἀμφοτέροις, ἀναβάντες εἰς Ῥώμην ἐπετέλουν τὸν Ὀκταουίας γάμον, οὐκ ἐῶντος μὲν νόμου πρὸ δέκα μηνῶν ἀνδρὸς τελευτήσαντος γαμεῖσθαι, τῆς δὲ συγκλήτου δόγματι τὸν χρόνον ἐκείνοις ἀνείσης.", "st": "Ant. 31.1"}, {"sp": "N", "t": "Σέξτου δὲ Πομπηΐου Σικελίαν μὲν ἔχοντος, Ἰταλίαν δὲ πορθοῦντος, ληστρίσι δὲ ναυσὶ πολλαῖς, ὧν Μηνᾶς ὁ πειρατὴς καὶ Μενεκράτης ἦρχον, ἄπλουν τὴν θάλασσαν πεποιηκότος, Ἀντωνίῳ δὲ κεχρῆσθαι δοκοῦντος φιλανθρώπως (ὑπεδέξατο γὰρ αὐτοῦ τὴν μητέρα τῇ Φουλβίᾳ συνεκπεσοῦσαν), ἔδοξε καὶ πρὸς τοῦτον διαλυθῆναι. καὶ συνῆλθον εἰς ταὐτὸν κατὰ τὴν ἐν Μισηνοῖς ἄκραν καὶ τὸ χῶμα, Πομπηΐῳ μὲν τοῦ στόλου παρορμοῦντος, Ἀντωνίῳ δὲ καὶ Καίσαρι τῶν πεζῶν παρακεκριμένων. ἐπεὶ δὲ συνέθεντο Πομπήϊον ἔχοντα Σαρδόνα καὶ Σικελίαν καθαράν τε λῃστηρίων παρέχειν τὴν θάλατταν καὶ σίτου τι τεταγμένον ἀποστέλλειν εἰς Ῥώμην, ἐκάλουν ἐπὶ δεῖπνον ἀλλήλους. κληρουμένων δὲ πρῶτος ἑστιᾶν αὐτοὺς ἔλαχε Πομπήϊος. ἐρομένου δὲ αὐτὸν Ἀντωνίου, ποῦ δειπνήσουσιν, ἐνταῦθα, ἔφη, δείξας τὴν στρατηγίδα ναῦν οὖσαν ἑξήρη πατρῷος γὰρ οἶκος αὕτη Πομπηΐῳ λέλειπται. ταῦτα δὲ εἰς τὸν Ἀντώνιον ὀνειδίζων ἔλεγεν, ἐπεὶ τὴν Πομπηΐου τοῦ πατρὸς γενομένην οἰκίαν ἐκεῖνος εἶχεν. ὁρμίσας δὲ τὴν ναῦν ἐπ’ ἀγκυρῶν καὶ διάβασίν τινα γεφυρώσας ἀπὸ τῆς ἄκρας ἀνελάμβανεν αὐτοὺς προθύμως. ἀκμαζούσης δὲ τῆς συνουσίας καὶ τῶν εἰς Κλεοπάτραν καὶ Ἀντώνιον ἀνθούντων σκωμμάτων, Μηνᾶς ὁ πειρατὴς τῷ Πομπηΐῳ προσελθὼν ὡς μὴ κατακούειν ἐκείνους, βούλει, φησί, τὰς ἀγκύρας τῆς νεὼς ὑποτέμω καὶ ποιήσω σε μὴ Σικελίας καὶ Σαρδόνος, ἀλλὰ τῆς Ῥωμαίων κύριον ἡγεμονίας; ὁ δὲ Πομπήϊος ἀκούσας καὶ πρὸς αὑτῷ γενόμενος βραχὺν χρόνον, ἔδει σε, φησίν, ὦ Μηνᾶ, τοῦτο ἐμοὶ μὴ προειπόντα ποιῆσαι· νυνὶ δὲ τὰ παρόντα στέργωμεν· ἐπιορκεῖν γὰρ οὐκ ἐμόν. οὗτος μὲν οὖν πάλιν ἀνθεστιαθεὶς ὑπ’ ἀμφοτέρων εἰς τὴν Σικελίαν ἀπέπλευσεν.", "st": "Ant. 32.1"}, {"sp": "N", "t": "Ἀντώνιος δὲ μετὰ τὰς διαλύσεις Οὐεντίδιον μὲν εἰς Ἀσίαν προὔπεμπε Πάρθοις ἐμποδὼν ἐσόμενον τοῦ πρόσω χωρεῖν, αὐτὸς δὲ Καίσαρι χαριζόμενος ἱερεὺς ἀπεδείχθη τοῦ προτέρου Καίσαρος· καὶ τἆλλα κοινῶς καὶ φιλικῶς ἐν τοῖς πολιτικοῖς καὶ μεγίστοις ἔπραττον. αἱ δὲ περὶ τὰς παιδιὰς ἅμιλλαι τὸν Ἀντώνιον ἐλύπουν ἀεὶ τοῦ Καίσαρος ἔλαττον φερόμενον. ἦν γάρ τις ἀνὴρ σὺν αὐτῷ μαντικὸς ἀπ’ Αἰγύπτου τῶν τὰς γενέσεις ἐπισκοπούντων, ὃς εἴτε Κλεοπάτρᾳ χαριζόμενος εἴτε χρώμενος ἀληθείᾳ πρὸς τὸν Ἀντώνιον ἐπαρρησιάζετο, λέγων τὴν τύχην αὐτοῦ λαμπροτάτην οὖσαν καὶ μεγίστην ὑπὸ τῆς Καίσαρος ἀμαυροῦσθαι, καὶ συνεβούλευε πορρωτάτω τοῦ νεανίσκου ποιεῖν ἑαυτόν. ὁ γὰρ σός, ἔφη, δαίμων τὸν τούτου φοβεῖται· καὶ γαῦρος ὢν καὶ ὑψηλὸς ὅταν ᾖ καθ’ ἑαυτόν, ὑπ’ ἐκείνου γίνεται ταπεινότερος ἐγγίσαντος καὶ ἀγεννέστερος. καὶ μέντοι τὰ γινόμενα τῷ Αἰγυπτίῳ μαρτυρεῖν ἐδόκει. λέγεται γὰρ ὅτι κληρουμένων μετὰ παιδιᾶς ἐφ’ ὅτῳ τύχοιεν ἑκάστοτε καὶ κυβευόντων ἔλαττον ἔχων ὁ Ἀντώνιος ἀπῄει. πολλάκις δὲ συμβαλόντων ἀλεκτρυόνας, πολλάκις δὲ μαχίμους ὄρτυγας, ἐνίκων οἱ Καίσαρος.", "st": "Ant. 33.1"}, {"sp": "N", "t": "ἐφ’ οἷς ἀνιώμενος ἀδήλως ὁ Ἀντώνιος καὶ μᾶλλόν τι τῷ Αἰγυπτίῳ προσέχων, ἀπῆρεν ἐκ τῆς Ἰταλίας, ἐγχειρίσας Καίσαρι τὰ οἰκεῖα· τὴν δὲ Ὀκταουίαν ἄχρι τῆς Ἑλλάδος ἐπήγετο θυγατρίου γεγονότος αὐτοῖς. διαχειμάζοντι δὲ αὐτῷ περὶ Ἀθήνας ἀπαγγέλλεται τὰ πρῶτα τῶν Οὐεντιδίου κατορθωμάτων, ὅτι μάχῃ τοὺς Πάρθους κρατήσας Λαβιηνὸν ἀπεκτόνοι καὶ Φαρναπάτην ἡγεμονικώτατον τῶν Ὑρώδου βασιλέως στρατηγῶν. ἐπὶ τούτοις εἱστία τοὺς Ἕλληνας, ἐγυμνασιάρχει δὲ Ἀθηναίοις, καὶ τὰ τῆς ἡγεμονίας παράσημα καταλιπὼν οἴκοι μετὰ τῶν γυμνασιαρχικῶν ῥάβδων ἐν ἱματίῳ καὶ φαικασίοις προῄει καὶ διαλαμβάνων τοὺς νεανίσκους ἐτραχήλιζεν.", "st": "Ant. 33.4"}, {"sp": "N", "t": "ἐξιέναι δὲ μέλλων ἐπὶ τὸν πόλεμον ἀπὸ τῆς ἱερᾶς ἐλαίας στέφανον ἔλαβε, καὶ κατά τι λόγιον ἀπὸ τῆς Κλεψύδρας ὕδατος ἐμπλησάμενος ἀγγεῖον ἐκόμιζεν. ἐν τούτῳ δὲ Πάκορον τὸν βασιλέως παῖδα, μεγάλῳ στρατῷ Πάρθων αὖθις ἐπὶ Συρίαν ἐλαύνοντα, συμπεσὼν Οὐεντίδιος ἐν τῇ Κυρρηστικῇ τρέπεται, καὶ διαφθείρει παμπόλλους, ἐν πρώτοις Πακόρου πεσόντος. τοῦτο τὸ ἔργον ἐν τοῖς ἀοιδιμωτάτοις γενόμενον Ῥωμαίοις τε τῶν κατὰ Κράσσον ἀτυχημάτων ἔκπλεω ποινὴν παρέσχε, καὶ Πάρθους αὖθις εἴσω Μηδίας καὶ Μεσοποταμίας συνέστειλε, τρισὶ μάχαις ἐφεξῆς κατὰ κράτος ἡττημένους. Οὐεντίδιος δὲ Πάρθους μὲν προσωτέρω διώκειν ἀπέγνω, φθόνον Ἀντωνίου δείσας, τοὺς δὲ ἀφεστῶτας ἐπιὼν κατεστρέφετο καὶ τὸν Κομμαγηνὸν Ἀντίοχον ἐν πόλει Σαμοσάτοις ἐπολιόρκει. δεομένου δὲ χίλια τάλαντα δοῦναι καὶ ποιεῖν Ἀντωνίῳ τὸ προσταττόμενον, ἐκέλευε πέμπειν πρὸς Ἀντώνιον. ἤδη γὰρ ἐγγὺς ἦν ἐπιών, καὶ τὸν Οὐεντίδιον οὐκ εἴα σπένδεσθαι τῷ Ἀντιόχῳ, βουλόμενος ἕν γε τοῦτο τῶν ἔργων ἐπώνυμον αὑτοῦ γενέσθαι καὶ μὴ πάντα διὰ Οὐεντιδίου κατορθοῦσθαι. τῆς δὲ πολιορκίας μῆκος λαμβανούσης καὶ τῶν ἔνδον, ὡς ἀπέγνωσαν τὰς διαλύσεις, πρὸς ἀλκὴν τραπομένων, πράττων οὐδέν, ἐν αἰσχύνῃ δὲ καὶ μεταγνώσει γενόμενος, ἀγαπητῶς ἐπὶ τριακοσίοις σπένδεται ταλάντοις πρὸς τὸν Ἀντίοχον· καὶ μικρὰ τῶν ἐν Συρίᾳ καταστησάμενος εἰς Ἀθήνας ἐπανῆλθε, καὶ τὸν Οὐεντίδιον οἷς ἔπρεπε τιμήσας ἔπεμψεν ἐπὶ τὸν θρίαμβον.", "st": "Ant. 34.1"}, {"sp": "N", "t": "οὗτος ἀπὸ Πάρθων ἄχρι δεῦρο τεθριάμβευκε μόνος, ἀνὴρ γένει μὲν ἀφανής, ἀπολαύσας δὲ τῆς Ἀντωνίου φιλίας τὸ λαβεῖν ἀφορμὰς πράξεων μεγάλων, αἷς κάλλιστα χρησάμενος ἐβεβαίωσε τὸν περὶ Ἀντωνίου λεγόμενον καὶ Καίσαρος λόγον, ὡς εὐτυχέστεροι δι’ ἑτέρων ἦσαν ἢ δι’ αὑτῶν στρατηγεῖν. καὶ γὰρ Σόσσιος Ἀντωνίου στρατηγὸς ἐν Συρίᾳ πολλὰ διεπράττετο, καὶ Κανίδιος ἀπολειφθεὶς ὑπ’ αὐτοῦ περὶ Ἀρμενίαν τούτους τε νικῶν καὶ τοὺς Ἰβήρων καὶ Ἀλβανῶν βασιλέας ἄχρι τοῦ Καυκάσου προῆλθεν. ἀφ’ ὧν ἐν τοῖς βαρβάροις ὄνομα καὶ κλέος ηὔξετο τῆς Ἀντωνίου δυνάμεως.", "st": "Ant. 34.5"}, {"sp": "N", "t": "αὐτὸς δὲ πάλιν ἔκ τινων διαβολῶν παροξυνθεὶς πρὸς Καίσαρα ναυσὶ τριακοσίαις ἔπλει πρὸς τὴν Ἰταλίαν· οὐ δεξαμένων δὲ τῶν Βρεντεσινῶν τὸν στόλον εἰς Τάραντα περιώρμισεν. ἐνταῦθα τὴν Ὀκταουίαν (συνέπλει γὰρ ἀπὸ τῆς Ἑλλάδος αὐτῷ) δεηθεῖσαν ἀποπέμπει πρὸς τὸν ἀδελφόν, ἔγκυον μὲν οὖσαν, ἤδη δὲ καὶ δεύτερον ἐξ αὐτοῦ θυγάτριον ἔχουσαν. ἡ δὲ ἀπαντήσασα καθ’ ὁδὸν Καίσαρι, καὶ παραλαβοῦσα τῶν ἐκείνου φίλων Ἀγρίππαν καὶ Μαικήναν, ἐνετύγχανε πολλὰ ποτνιωμένη καὶ πολλὰ δεομένη μὴ περιϊδεῖν αὐτὴν ἐκ μακαριωτάτης γυναικὸς ἀθλιωτάτην γενομένην. νῦν μὲν γὰρ ἅπαντας ἀνθρώπους εἰς αὐτὴν ἀποβλέπειν αὐτοκρατόρων δυεῖν, τοῦ μὲν γυναῖκα, τοῦ δὲ ἀδελφὴν οὖσαν· εἰ δὲ τὰ χείρω κρατήσειεν, ἔφη, καὶ γένοιτο πόλεμος, ὑμῶν μὲν ἄδηλον ὅτῳ κρατεῖν ἢ κρατεῖσθαι πέπρωται, τὰ ἐμὰ δ’ ἀμφοτέρως ἄθλια. τούτοις ἐπικλασθεὶς ὁ Καῖσαρ ἧκεν εἰρηνικῶς εἰς Τάραντα, καὶ θέαμα κάλλιστον οἱ παρόντες ἐθεῶντο, πολὺν μὲν ἐκ γῆς στρατὸν ἡσυχάζοντα, πολλὰς δὲ ναῦς ἀτρέμα πρὸς τοῖς αἰγιαλοῖς ἐχούσας, αὐτῶν δὲ καὶ φίλων ἀπαντήσεις καὶ φιλοφροσύνας. εἱστία δὲ Ἀντώνιος πρότερος, καὶ τοῦτο τῇ ἀδελφῇ Καίσαρος δόντος. ἐπεὶ δὲ ὡμολόγητο Καίσαρα μὲν Ἀντωνίῳ δοῦναι δύο τάγματα πρὸς τὸν Παρθικὸν πόλεμον, Ἀντώνιον δὲ Καίσαρι χαλκεμβόλους ἑκατόν, Ὀκταουία τῶν ὡμολογημένων χωρὶς ᾐτήσατο τῷ μὲν ἀδελφῷ παρὰ τοῦ ἀνδρὸς εἴκοσι μυοπάρωνας, τῷ δ’ ἀνδρὶ παρὰ τοῦ ἀδελφοῦ στρατιώτας χιλίους. οὕτω δὲ ἀλλήλων διακριθέντες ὁ μὲν εὐθὺς εἴχετο τοῦ πρὸς Πομπήϊον πολέμου, Σικελίας ἐφιέμενος, Ἀντώνιος δὲ Ὀκταουίαν μετὰ τῶν ἐξ ἐκείνης καὶ τοὺς ἐκ Φουλβίας παῖδας αὐτῷ παρακαταθέμενος εἰς τὴν Ἀσίαν ἀπεπέρασεν.", "st": "Ant. 35.1"}, {"sp": "N", "t": "εὕδουσα δ’ ἡ δεινὴ συμφορὰ χρόνον πολύν, ὁ Κλεοπάτρας ἔρως, δοκῶν κατευνάσθαι καὶ κατακεκηλῆσθαι. τοῖς βελτίοσι λογισμοῖς, αὖθις ἀνέλαμπε καὶ ἀνεθάρρει Συρία πλησιάζοντος αὐτοῦ. καὶ τέλος, ὥσπερ φησὶν ὁ Πλάτων τὸ δυσπειθὲς καὶ ἀκόλαστον τῆς ψυχῆς ὑποζύγιον, ἀπολακτίσας τὰ καλὰ καὶ σωτήρια πάντα Καπίτωνα Φοντήϊον ἔπεμψεν ἄξοντα Κλεοπάτραν εἰς Συρίαν. ἐλθούσῃ δὲ χαρίζεται καὶ προστίθησι μικρὸν οὐδὲν οὐδ’ ὀλίγον, ἀλλὰ Φοινίκην, κοίλην Συρίαν, Κύπρον, Κιλικίας πολλήν· ἔτι δὲ τῆς τε Ἰουδαίων τὴν τὸ βάλσαμον φέρουσαν καὶ τῆς Ναβαταίων Ἀραβίας ὅση πρὸς τὴν ἐκτὸς ἀποκλίνει θάλασσαν. αὗται μάλιστα Ῥωμαίους ἠνίασαν αἱ δωρεαί. καίτοι πολλοῖς ἐχαρίζετο τετραρχίας καὶ βασιλείας ἐθνῶν μεγάλων, ἰδιώταις οὖσι, πολλοὺς δ’ ἀφῃρεῖτο βασιλείας, ὡς Ἀντίγονον τὸν Ἰουδαῖον, ὃν καὶ προαγαγὼν ἐπελέκισεν, οὐδενὸς πρότερον ἑτέρου βασιλέως οὕτω κολασθέντος. ἀλλὰ τὸ αἰσχρὸν ἦν τῶν Κλεοπάτρας τιμῶν ἀνιαρότατον. ηὔξησε δὲ τὴν διαβολὴν παῖδας ἐξ αὐτῆς διδύμους ἀνελόμενος, καὶ προσαγορεύσας τὸν μὲν Ἀλέξανδρον, τὴν δὲ Κλεοπάτραν, ἐπίκλησιν δὲ τὸν μὲν Ἥλιον, τὴν δὲ Σελήνην. οὐ μὴν ἀλλ’ ἀγαθὸς ὢν ἐγκαλλωπίσασθαι τοῖς αἰσχροῖς ἔλεγε τῆς μὲν Ῥωμαίων ἡγεμονίας οὐ δι’ ὧν λαμβάνουσιν, ἀλλ’ ἐν οἷς χαρίζονται φαίνεσθαι τὸ μέγεθος· διαδοχαῖς δὲ καὶ τεκνώσεσι πολλῶν βασιλέων πλατύνεσθαι τὰς εὐγενείας. οὕτω γοῦν ὑφ’ Ἡρακλέους τεκνωθῆναι τὸν αὑτοῦ πρόγονον, οὐκ ἐν μιᾷ γαστρὶ θεμένου τὴν διαδοχὴν οὐδὲ νόμους Σολωνείους καὶ κυήσεως εὐθύνας δεδοικότος, ἀλλὰ τῇ φύσει πολλὰς γενῶν ἀρχὰς καὶ καταβολὰς ἀπολιπεῖν ἐφιέντος.", "st": "Ant. 36.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Φραάτου κτείναντος Ὑρώδην τὸν πατέρα καὶ τὴν βασιλείαν κατασχόντος ἄλλοι τε Πάρθων ἀπεδίδρασκον οὐκ ὀλίγοι, καὶ Μοναίσης, ἀνὴρ ἐπιφανὴς καὶ δυνατός, ἧκε φεύγων πρὸς Ἀντώνιον, τὰς μὲν ἐκείνου τύχας ταῖς Θεμιστοκλέους εἰκάσας, περιουσίαν δὲ τὴν ἑαυτοῦ καὶ μεγαλοφροσύνην τοῖς Περσῶν βασιλεῦσι παραβαλών, ἐδωρήσατο τρεῖς πόλεις αὐτῷ, Λάρισσαν καὶ Ἀρέθουσαν καὶ Ἱερὰν πόλιν, ἣν Βαμβύκην πρότερον ἐκάλουν. τοῦ δὲ Πάρθων βασιλέως τῷ Μοναίσῃ δεξιὰν καταπέμψαντος, ἄσμενος αὐτὸν ἀπέστειλεν ὁ Ἀντώνιος, ἐξαπατᾶν μὲν ἐγνωκὼς τὸν Φραάτην, ὡς εἰρήνης ἐσομένης, ἀξιῶν δὲ τὰς ἁλούσας ἐπὶ Κράσσου σημαίας καὶ τῶν ἀνδρῶν ἀπολαβεῖν τοὺς περιόντας. αὐτὸς δὲ Κλεοπάτραν εἰς Αἴγυπτον ἀποπέμψας ἐχώρει δι’ Ἀραβίας καὶ Ἀρμενίας, ὅπου συνελθούσης αὐτῷ τῆς δυνάμεως καὶ τῶν συμμάχων βασιλέων (πάμπολλοι δὲ ἦσαν οὗτοι, μέγιστος δὲ πάντων ὁ τῆς Ἀρμενίας Ἀρταουάσδης, ἑξακισχιλίους ἱππεῖς καὶ πεζοὺς ἑπτακισχιλίους παρέχων) ἐξήτασε τὸν στρατόν. ἦσαν δὲ Ῥωμαίων μὲν αὐτῶν ἑξακισμύριοι πεζοὶ καὶ τὸ Ῥωμαίοις συντεταγμένον ἱππικόν, Ἰβήρων καὶ Κελτῶν μύριοι, τῶν δὲ ἄλλων ἐθνῶν ἐγένοντο τρεῖς μυριάδες σὺν ἱππεῦσιν ὁμοῦ καὶ ψιλοῖς.", "st": "Ant. 37.1"}, {"sp": "N", "t": "τοσαύτην μέντοι παρασκευὴν καὶ δύναμιν, ἣ καὶ τοὺς πέραν Βάκτρων Ἰνδοὺς ἐφόβησε καὶ πᾶσαν ἐκράδανε τὴν Ἀσίαν, ἀνόνητον αὐτῷ διὰ Κλεοπάτραν γενέσθαι λέγουσι. σπεύδοντα γὰρ ἐκείνῃ συνδιαχειμάσαι, τὸν πόλεμον ἐξενεγκεῖν πρὸ καιροῦ καὶ πᾶσι χρήσασθαι τεταραγμένως, οὐκ ὄντα τῶν ἑαυτοῦ λογισμῶν, ἀλλ’ ὡς ὑπὸ φαρμάκων τινῶν ἢ γοητείας παπταίνοντα πρὸς ἐκείνην ἀεί, καὶ πρὸς τὸ τάχιον ἐπανελθεῖν μᾶλλον ἢ πρὸς τὸ κρατῆσαι τῶν πολεμίων γενόμενον.", "st": "Ant. 37.4"}, {"sp": "N", "t": "πρῶτον μὲν οὖν αὐτοῦ δέον ἐν Ἀρμενίᾳ διαχειμάσαι καὶ διαναπαῦσαι τὸν στρατόν, ὀκτακισχιλίων σταδίων ἀποτετρυμένον πορείᾳ, καὶ πρὶν ἢ κινεῖν ἐκ τῶν χειμαδίων Πάρθους ἔαρος ἀρχῇ Μηδίαν καταλαβεῖν, οὐκ ἠνέσχετο τὸν χρόνον, ἀλλ’ εὐθὺς ἦγεν ἐν ἀριστερᾷ λαβὼν Ἀρμενίαν, καὶ τῆς Ἀτροπατηνῆς ἁψάμενος ἐπόρθει τὴν χώραν. ἔπειτα μηχανημάτων αὐτῷ πρὸς πολιορκίαν ἀναγκαίων τριακοσίαις ἁμάξαις παραπεμπομένων, ἐν οἷς καὶ κριὸς ἦν ὀγδοήκοντα ποδῶν μῆκος, ὧν οὐδὲν ἐνεχώρει διαφθαρὲν ἐπὶ καιροῦ πάλιν γενέσθαι διὰ τὸ τὴν ἄνω χώραν πᾶν ξύλον ἀγεννὲς εἰς μῆκος καὶ μαλθακὸν ἐκφέρειν, ἐπειγόμενος ὡς ἐμπόδια τοῦ ταχύνειν ἀπέλιπε, φυλακήν τινα καὶ Στατιανὸν ἡγεμόνα τῶν ἁμαξῶν ἐπιστήσας, αὐτὸς δὲ Φραάτα μεγάλην πόλιν, ἐν ᾗ καὶ τέκνα καὶ γυναῖκες ἦσαν τοῦ τῆς Μηδίας βασιλέως, ἐπολιόρκει. τῆς δὲ χρείας εὐθὺς ὅσον ἥμαρτε τὰς μηχανὰς ἀπολιπὼν ἐξελεγχούσης, ὁμόσε χωρῶν ἔχου πρὸς τὴν πόλιν χῶμα σχολῇ καὶ πολυπόνως ἀνιστάμενον. ἐν τούτῳ δὲ καταβαίνων στρατιᾷ μεγάλῃ Φραάτης, ὡς ἤκουσε τὴν ἀπόλειψιν τῶν μηχανοφόρων ἁμαξῶν, ἔπεμψε τῶν ἱππέων πολλοὺς ἐπ’ αὐτάς, ὑφ’ ὧν περιληφθεὶς ὁ Στατιανὸς ἀποθνήσκει μὲν αὐτός, ἀποθνήσκουσι δὲ μύριοι τῶν μετ’ αὐτοῦ. τὰς δὲ μηχανὰς ἑλόντες οἱ βάρβαροι διέφθειραν. εἷλον δὲ παμπόλλους, ἐν οἷς καὶ Πολέμων ἦν ὁ βασιλεύς.", "st": "Ant. 38.1"}, {"sp": "N", "t": "τοῦτο πάντας μέν, ὡς εἰκός, ἠνίασε τοὺς περὶ Ἀντώνιον ἀνελπίστως ἐν ἀρχῇ πληγέντας· ὁ δὲ Ἀρμένιος Ἀρταουάσδης ἀπογνοὺς τὰ Ῥωμαίων ᾤχετο τὴν αὑτοῦ στρατιὰν ἀναλαβών, καίπερ αἰτιώτατος τοῦ πολέμου γενόμενος. ἐπιφανέντων δὲ λαμπρῶς τοῖς πολιορκοῦσι τῶν Πάρθων καὶ χρωμένων ἀπειλαῖς πρὸς ὕβριν, οὐ βουλόμενος Ἀντώνιος ἡσυχάζοντι τῷ στρατῷ τὸ δυσθυμοῦν καὶ καταπεπληγμένον ἐμμένειν καὶ αὔξεσθαι, δέκα τάγματα λαβὼν καὶ τρεῖς στρατηγίδας σπείρας ὁπλιτῶν, τοὺς δ’ ἱππεῖς ἅπαντας, ἐξήγαγε πρὸς σιτολογίαν, οἰόμενος οὕτως ἂν ἐπισπασθέντων μάλιστα τῶν πολεμίων ἐκ παρατάξεως μάχην γενέσθαι. προελθὼν δὲ μιᾶς ὁδὸν ἡμέρας, ὡς ἑώρα τοὺς Πάρθους κύκλῳ περιχεομένους καὶ προσπεσεῖν καθ’ ὁδὸν αὐτῷ ζητοῦντας, ἐξέθηκε μὲν τὸ τῆς μάχης σύμβολον ἐν τῷ στρατοπέδῳ, καθελὼν δὲ τὰς σκηνὰς ὡς οὐ μαχησόμενος, ἀλλ’ ἀπάξων, παρημείβετο τῶν βαρβάρων τὴν τάξιν οὖσαν μηνοειδῆ, κελεύσας ὅταν οἱ πρῶτοι τοῖς ὁπλίταις ἐν ἐφικτῷ δοκῶσιν εἶναι, τοὺς ἱππεῖς ἐναντίους εἰσελαύνειν. τοῖς δὲ Πάρθοις παρακεκριμένοις λόγου κρείττων ἡ τάξις ἐφαίνετο τῶν Ῥωμαίων, καὶ κατεθεῶντο παρεξιόντας ἐν διαστήμασιν ἴσοις ἀθορύβως καὶ σιωπῇ τοὺς ὑσσοὺς κραδαίνοντας. ὡς δὲ τὸ σημεῖον ἤρθη καὶ προσεφέροντο μετὰ κραυγῆς ἐπιστρέψαντες οἱ ἱππεῖς, τούτους μὲν ἠμύνοντο δεξάμενοι, καίπερ εὐθὺς ἐντὸς τοξεύματος γενομένους, τῶν δὲ ὁπλιτῶν συναπτόντων ἅμα βοῇ καὶ πατάγῳ τῶν ὅπλων, οἵ τε ἵπποι τοῖς Πάρθοις ἐξίσταντο ταρβοῦντες καὶ αὐτοὶ πρὶν εἰς χεῖρας ἐλθεῖν ἔφευγον.", "st": "Ant. 39.1"}, {"sp": "N", "t": "ὁ δὲ Ἀντώνιος ἐνέκειτο τῇ διώξει, καὶ μεγάλας εἶχεν ἐλπίδας ὡς τοῦ πολέμου τὸ σύμπαν ἢ τὸ πλεῖστον ἐκείνῃ τῇ μάχῃ διαπεπραγμένος. ἐπεὶ δὲ τῆς διώξεως γενομένης τοῖς μὲν πεζοῖς ἐπὶ πεντήκοντα στάδια, τοῖς δὲ ἱππεῦσιν ἐπὶ τρὶς τοσαῦτα, τοὺς πεπτωκότας τῶν πολεμίων καὶ τοὺς ἡλωκότας ἐπισκοποῦντες εὗρον αἰχμαλώτους μὲν τριάκοντα, νεκροὺς δὲ ὀγδοήκοντα μόνους, ἀπορία καὶ δυσθυμία πᾶσι παρέστη, δεινὸν εἶναι λογιζομένοις εἰ νικῶντες μὲν οὕτως ὀλίγους κτείνουσιν, ἡττώμενοι δὲ στερήσονται τοσούτων ὅσους ἀπέβαλον περὶ ταῖς ἁμάξαις. τῇ δ’ ὑστεραίᾳ συσκευασάμενοι τὴν ἐπὶ Φραάτων καὶ τοῦ στρατοπέδου προῆγον. ἐντυχόντες δὲ κατὰ τὴν ὁδὸν πρῶτον μὲν ὀλίγοις τῶν πολεμίων, ἔπειτα πλείοσι, τέλος δὲ πᾶσιν ὥσπερ ἀηττήτοις καὶ νεαλέσι προκαλουμένοις καὶ προσβάλλουσι πανταχόθεν, μοχθηρῶς καὶ πολυπόνως ἀπεσώθησαν εἰς τὸ στρατόπεδον. τῶν δὲ Μήδων ἐκδρομήν τινα ποιησαμένων ἐπὶ τὸ χῶμα καὶ τοὺς προμαχομένους φοβησάντων, ὀργισθεὶς ὁ Ἀντώνιος ἐχρήσατο τῇ λεγομένῃ δεκατείᾳ πρὸς τοὺς ἀποδειλιάσαντας. διελὼν γὰρ εἰς δεκάδας τὸ πλῆθος ἀφ’ ἑκάστης ἕνα τὸν λαχόντα κλήρῳ διέφθειρε, τοῖς δὲ ἄλλοις ἀντὶ πυρῶν ἐκέλευε κριθὰς μετρεῖσθαι.", "st": "Ant. 39.5"}, {"sp": "N", "t": "χαλεπὸς δὲ ἀμφοτέροις ἦν ὁ πόλεμος, καὶ τὸ μέλλον αὐτοῦ φοβερώτερον, Ἀντωνίῳ μὲν προσδοκῶντι λιμόν· οὐκέτι γὰρ ἦν ἄνευ τραυμάτων καὶ νεκρῶν πολλῶν ἐπισιτίσασθαι· Φραάτης δὲ τοὺς Πάρθους ἐπιστάμενος πάντα μᾶλλον ἢ χειμῶνος ἔξω προσταλαιπωρεῖν καὶ θυραυλεῖν δυναμένους, ἐφοβεῖτο μὴ τῶν Ῥωμαίων ἐγκαρτερούντων καὶ παραμενόντων ἀπολίπωσιν αὐτόν, ἤδη τοῦ ἀέρος συνισταμένου μετὰ φθινοπωρινὴν ἰσημερίαν. δόλον οὖν συντίθησι τοιόνδε. Πάρθων οἱ γνωριμώτατοι περὶ τὰς σιτολογίας καὶ τὰς ἄλλας ἀπαντήσεις μαλακώτερον τοῖς Ῥωμαίοις προσεφέροντο, λαμβάνειν τε παριέντες αὐτοῖς ἔνια καὶ τὴν ἀρετὴν ἐπαινοῦντες ὡς πολεμικωτάτων ἀνδρῶν καὶ θαυμαζομένων ὑπὸ τοῦ σφετέρου βασιλέως δικαίως. ἐκ δὲ τούτου προσελαύνοντες ἐγγυτέρω καὶ τοὺς ἵππους ἀτρέμα παραβάλλοντες ἐλοιδόρουν τὸν Ἀντώνιον, ὅτι βουλομένῳ Φραάτῃ διαλλαγῆναι καὶ φείσασθαι τοιούτων ἀνδρῶν καὶ τοσούτων ἀφορμὴν οὐ δίδωσιν, ἀλλὰ τοὺς χαλεποὺς καὶ μεγάλους κάθηται πολεμίους ἀναμένων, λιμὸν καὶ χειμῶνα, δι’ ὧν ἔργον ἐστὶ καὶ προπεμπομένους ὑπὸ Πάρθων ἀποφεύγειν. πολλῶν δὲ ταῦτα πρὸς τὸν Ἀντώνιον ἀναφερόντων, μαλασσόμενος ὑπὸ τῆς ἐλπίδος ὅμως οὐ πρότερον ἐπεκηρυκεύσατο πρὸς τὸν Πάρθον ἢ πυθέσθαι τῶν φιλοφρονουμένων ἐκείνων βαρβάρων εἰ τοῦ βασιλέως ταῦτα φρονοῦντος διαλέγοιντο. φασκόντων δὲ καὶ παρακαλούντων μὴ δεδιέναι μηδὲ ἀπιστεῖν, ἔπεμψέ τινας τῶν ἑταίρων πάλιν τὰς σημαίας ἀξιῶν ἀπολαβεῖν καὶ τοὺς αἰχμαλώτους, ὡς δὴ μὴ παντάπασιν ἀγαπᾶν τὸ σωθῆναι καὶ διαφυγεῖν νομισθείη. τοῦ δὲ Πάρθου ταῦτα μὲν ἐᾶν κελεύοντος, ἀπιόντι δὲ εὐθὺς εἰρήνην καὶ ἀσφάλειαν εἶναι φήσαντος, ὀλίγαις ἡμέραις συσκευασάμενος ἀνεζεύγνυεν. ὢν δὲ καὶ δήμῳ πιθανὸς ἐντυχεῖν καὶ στρατὸν ἄγειν διὰ λόγου παρ’ ὁντινοῦν τῶν τότε πεφυκώς, ἐξέλιπεν αὐτὸς αἰσχύνῃ καὶ κατηφείᾳ τὸ παραθαρρῦναι τὸ πλῆθος, Δομίτιον δὲ Ἀηνόβαρβον ἐκέλευε τοῦτο ποιῆσαι. καί τινες μὲν ἠγανάκτησαν ὡς ὑπερορώμενοι, τὸ δὲ πλεῖστον ἐπεκλάσθη καὶ συνεφρόνησε τὴν αἰτίαν· διὸ καὶ μᾶλλον ᾤοντο δεῖν ἀνταιδεῖσθαι καὶ πείθεσθαι τῷ στρατηγῷ.", "st": "Ant. 40.1"}, {"sp": "N", "t": "μέλλοντος δὲ αὐτοῦ τὴν αὐτὴν ὁδὸν ἄγειν ὀπίσω πεδινὴν καὶ ἄδενδρον οὖσαν, ἀνὴρ τῷ γένει Μάρδος, πολλὰ τοῖς Πάρθων ἤθεσιν ἐνωμιληκώς, ἤδη δὲ Ῥωμαίοις πιστὸς ἐν τῇ μάχῃ τῇ περὶ τὰς μηχανὰς γεγονώς, Ἀντωνίῳ προσελθὼν ἐκέλευε φεύγειν ἐν δεξιᾷ τῶν ὀρῶν ἐπιλαβόμενον, καὶ μὴ στρατὸν ὁπλίτην καὶ βαρὺν ἐν δρόμοις γυμνοῖς καὶ ἀναπεπταμένοις ὑποβαλεῖν ἵππῳ τοσαύτῃ καὶ τοξεύμασιν, ὃ δὴ τεχνώμενον τὸν Φραάτην ἀναστῆσαι τῆς πολιορκίας αὐτὸν ὁμολογίαις φιλανθρώποις· ἔσεσθαι δὲ αὐτὸς ἡγεμὼν ὁδοῦ βραχυτέρας καὶ μᾶλλον εὐπορίαν τῶν ἐπιτηδείων ἐχούσης.", "st": "Ant. 41.1"}, {"sp": "N", "t": "ταῦτα ἀκούσας ὁ Ἀντώνιος ἐβουλεύετο, καὶ Πάρθοις μὲν οὐκ ἐβούλετο δοκεῖν ἀπιστεῖν μετὰ σπονδάς, τὴν δὲ συντομίαν τῆς ὁδοῦ καὶ τὸ παρὰ κώμας οἰκουμένας ἔσεσθαι τὴν πορείαν ἐπαινῶν πίστιν ᾔτει τὸν Μάρδον. ὁ δὲ δῆσαι παρεῖχεν αὑτὸν ἄχρι οὗ καταστήσῃ τὸν στρατὸν εἰς Ἀρμενίαν, καὶ δεθεὶς ἡγεῖτο δύο ἡμέρας καθ’ ἡσυχίαν. τῇ δὲ τρίτῃ παντάπασι τοὺς Πάρθους ἀπεγνωκότος Ἀντωνίου καὶ βαδίζοντος ἀνειμένως διὰ τὸ θαρρεῖν, ἰδὼν ὁ Μάρδος ἀπόχωσιν ἐμβολῆς ποταμοῦ νεωστὶ διεσπασμένην καὶ τὸ ῥεῦμα πολὺ πρὸς τὴν ὁδόν, ᾗ πορευτέον ἦν, ἐκχεόμενον, συνῆκεν ὅτι τῶν Πάρθων ἔργον εἴη τοῦτο δυσκολίας ἕνεκα καὶ διατριβῆς ἐμποδὼν αὐτοῖς τὸν ποταμὸν τιθεμένων, καὶ τὸν Ἀντώνιον ὁρᾶν ἐκέλευε καὶ προσέχειν, ὡς τῶν πολεμίων ἐγγὺς ὄντων. ἄρτι δὲ αὐτοῦ καθιστάντος εἰς τάξιν τὰ ὅπλα καὶ δι’ αὐτῶν τοῖς ἀκοντισταῖς καὶ σφενδονήταις ἐκδρομὴν ἐπὶ τοὺς πολεμίους παρασκευάζοντος, ἐπεφάνησαν οἱ Πάρθοι καὶ περιήλαυνον ὡς κυκλωσόμενοι καὶ συνταράξοντες πανταχόθεν τὸν στρατόν. ἐκδραμόντων δὲ τῶν ψιλῶν ἐπ’ αὐτούς, πολλὰς μὲν διδόντες ἀπὸ τόξων, οὐκ ἐλάττονας δὲ ταῖς μολυβδίσι καὶ τοῖς ἀκοντίοις πληγὰς λαμβάνοντες ἀνεχώρουν· εἶτα ἐπῆγον αὖθις, ἄχρι οὗ συστρέψαντες οἱ Κελτοὶ τοὺς ἵππους ἐνέβαλον καὶ διεσκέδασαν αὐτοὺς οὐκέτι τῆς ἡμέρας ἐκείνης ὑπόδειγμα γενομένους.", "st": "Ant. 41.3"}, {"sp": "N", "t": "ἐκ τούτου μαθὼν ὁ Ἀντώνιος ὃ ποιεῖν ἔδει, πολλοῖς ἀκοντισταῖς καὶ σφενδονήταις οὐ μόνον τὴν οὐραγίαν, ἀλλὰ καὶ τὰς πλευρὰς ἑκατέρας στομώσας ἐν πλαισίῳ τὸν στρατὸν ἦγε, καὶ τοῖς ἱππόταις εἴρητο προσβάλλοντας τρέπεσθαι, τρεψαμένους δὲ μὴ πόρρω διώκειν, ὥστε τοὺς Πάρθους τὰς ἐφεξῆς τέσσαρας ἡμέρας οὐθὲν πλέον δράσαντας ἢ παθόντας ἀμβλυτέρους γεγονέναι καὶ τὸν χειμῶνα ποιουμένους πρόφασιν ἀπιέναι διανοεῖσθαι.", "st": "Ant. 42.1"}, {"sp": "N", "t": "τῇ δὲ πέμπτῃ Φλαούϊος Γάλλος, ἀνὴρ πολεμικὸς καὶ δραστήριος ἐφ’ ἡγεμονίας τεταγμένος, ᾔτησεν Ἀντώνιον προσελθὼν πλείονας ψιλοὺς ἀπ’ οὐρᾶς, καὶ τῶν ἀπὸ τοῦ στόματος ἱππέων τινὰς ὡς μέγα κατόρθωμα ποιήσων. δόντος δὲ προσβάλλοντας ἀνέκοπτε τοὺς πολεμίους, οὐχ, ὡς πρότερον, ὑπάγων ἅμα πρὸς τοὺς ὁπλίτας καὶ ἀναχωρῶν, ἀλλὰ ὑφιστάμενος καὶ συμπλεκόμενος παραβολώτερον. ὁρῶντες δὲ αὐτὸν οἱ τῆς οὐραγίας ἡγεμόνες ἀπορρηγνύμενον ἐκάλουν πέμποντες· ὁ δὲ οὐκ ἐπείθετο. Τίτιον δέ φασι τὸν ταμίαν καὶ τῶν σημαιῶν ἐπιλαβόμενον στρέφειν ὀπίσω καὶ λοιδορεῖν τὸν Γάλλον ὡς ἀπολλύντα πολλοὺς καὶ ἀγαθοὺς ἄνδρας. ἀντιλοιδοροῦντος δὲ ἐκείνου καὶ διακελευομένου τοῖς περὶ αὑτὸν μένειν, ὁ μὲν Τίτιος ἀπεχώρει· τὸν δὲ Γάλλον ὠθούμενον εἰς τοὺς κατὰ στόμα λανθάνουσι πολλοὶ περισχόντες ἐκ τῶν ὄπισθεν. βαλλόμενος δὲ πανταχόθεν ἐκάλει πέμπων ἀρωγήν. οἱ δὲ τοὺς ὁπλίτας ἄγοντες, ὧν καὶ Κανίδιος ἦν, ἀνὴρ παρὰ Ἀντωνίῳ δυνάμενος μέγιστον, οὐ μικρὰ δοκοῦσι διαμαρτεῖν. δέον γὰρ ἀθρόαν ἐπιστρέψαι τὴν φάλαγγα, πέμποντες κατ’ ὀλίγους ἐπιβοηθοῦντας, καὶ πάλιν ἡττωμένων τούτων ἑτέρους ἀποστέλλοντες, ἔλαθον ὀλίγου δεῖν ἥττης καὶ φυγῆς ὅλον ἀναπλήσαντες τὸ στρατόπεδον, εἰ μὴ ταχὺ μὲν αὐτὸς Ἀντώνιος μετὰ τῶν ὅπλων ἀπὸ τοῦ στόματος ἧκεν ὑπαντιάζων, ταχὺ δὲ τὸ τρίτον τάγμα διὰ τῶν φευγόντων ἐπὶ τοὺς πολεμίους ὠσάμενον ἔσχε τοῦ πρόσω διώκειν.", "st": "Ant. 42.2"}, {"sp": "N", "t": "ἀπέθανον δὲ τρισχιλίων οὐκ ἐλάττους, ἐκομίσθησαν δὲ ἐπὶ σκηνὰς τραυματίαι πεντακισχίλιοι· καὶ Γάλλος ἦν ἐν τούτοις, τέτταρσιν ἐναντίοις διαπεπαρμένος τοξεύμασιν. ἀλλ’ οὗτος μὲν ἐκ τῶν τραυμάτων οὐκ ἀνήνεγκε, τοὺς δ’ ἄλλους περιϊὼν ὁ Ἀντώνιος ἐπεσκόπει καὶ παρεθάρρυνε δεδακρυμένος καὶ περιπαθῶν. οἱ δὲ φαιδροὶ τῆς δεξιᾶς αὐτοῦ λαμβανόμενοι παρεκάλουν ἀπιόντα θεραπεύειν αὑτὸν καὶ μὴ κακοπαθεῖν, αὐτοκράτορα καλοῦντες, καὶ σώζεσθαι λέγοντες ἂν ἐκεῖνος ὑγιαίνῃ. καθόλου μὲν γὰρ οὔτ ἀλκαῖς οὔτε ὑπομοναῖς οὔτε ἡλικίᾳ λαμπρότερον ἄλλος αὐτοκράτωρ στρατὸν ἐκείνου δοκεῖ συναγαγεῖν ἐν τοῖς τότε χρόνοις· ἡ δὲ πρὸς αὐτὸν αἰδὼς τὸν ἡγεμόνα καὶ πειθαρχία μετ’ εὐνοίας, καὶ τὸ πάντας ὁμαλῶς, ἐνδόξους, ἀδόξους, ἄρχοντας, ἰδιώτας, τὴν παρὰ Ἀντωνίου τιμήν τε καὶ χάριν μᾶλλον αἱρεῖσθαι τῆς σωτηρίας καὶ τῆς ἀσφαλείας, οὐδὲ τοῖς πάλαι Ῥωμαίοις ἀπέλιπεν ὑπερβολήν. τούτου δὲ αἰτίαι πλείονες ἦσαν, ὡς προειρήκαμεν· εὐγένεια, λόγου δύναμις, ἁπλότης, τὸ φιλόδωρον καὶ μεγαλόδωρον, ἡ περὶ τὰς παιδιὰς καὶ τὰς ὁμιλίας εὐτραπελία. τότε δὲ καὶ συμπονῶν καὶ συναλγῶν τοῖς κακοπαθοῦσι, καὶ μεταδιδοὺς οὗ τις δεηθείη, προθυμοτέρους τῶν ἐρρωμένων τοὺς νοσοῦντας καὶ τετρωμένους ἐποίησε.", "st": "Ant. 43.1"}, {"sp": "N", "t": "τοὺς μέντοι πολεμίους ἀπαγορεύοντας ἤδη καὶ κάμνοντας οὕτως ἐπῆρεν ἡ νίκη καὶ τοσοῦτον τῶν Ῥωμαίων κατεφρόνησαν ὥστε καὶ νυκτὸς ἐπαυλίσασθαι τῷ στρατοπέδῳ, προσδοκῶντας αὐτίκα μάλα σκηνὰς ἐρήμους καὶ χρήματα διαρπάσειν ἀποδιδρασκόντων. ἅμα δ’ ἡμέρᾳ πολὺ πλείονες ἐπηθροίζοντο, καὶ λέγονται τετρακισμυρίων οὐκ ἐλάττονες ἱππόται γενέσθαι, βασιλέως καὶ τοὺς περὶ αὐτὸν ἀεὶ τεταγμένους ὡς ἐπὶ σαφεῖ καὶ βεβαίῳ κατορθώματι πέμψαντος· αὐτὸς μὲν γὰρ οὐδεμιᾷ μάχῃ παρέτυχεν. Ἀντώνιος δὲ βουλόμενος προσαγορεῦσαι τοὺς στρατιώτας ᾔτησε φαιὸν ἱμάτιον, ὡς οἰκτρότερος ὀφθείη. τῶν δὲ φίλων ἐναντιωθέντων ἐν τῇ στρατηγικῇ φοινικίδι προελθὼν ἐδημηγόρησε, τοὺς μὲν νενικηκότας ἐπαινῶν, ὀνειδίζων δὲ τοὺς φυγόντας. τῶν δὲ οἱ μὲν παρεκελεύοντο θαρρεῖν, οἱ δὲ ἀπολογούμενοι σφᾶς αὐτοὺς παρεῖχον, εἴτε βούλοιτο δεκατεύειν, εἴτε ἄλλῳ τρόπῳ κολάζειν· μόνον παύσασθαι δυσφοροῦντα καὶ λυπούμενον ἐδέοντο. πρὸς ταῦτα τὰς χεῖρας ἀνατείνας ἐπεύξατο τοῖς θεοῖς, εἴ τις ἄρα νέμεσις τὰς πρόσθεν εὐτυχίας αὐτοῦ μέτεισιν, εἰς αὐτὸν ἐλθεῖν, τῷ δ’ ἄλλῳ στρατῷ σωτηρίαν διδόναι καὶ νίκην.", "st": "Ant. 44.1"}, {"sp": "N", "t": "τῇ δὲ ὑστεραίᾳ φραξάμενοι βέλτιον προῆγον· καὶ τοῖς Πάρθοις ἐπιχειροῦσι πολὺς ἀπήντα παράλογος. οἰόμενοι γὰρ ἐφ’ ἁρπαγὴν καὶ λεηλασίαν, οὐ μάχην, ἐλαύνειν, εἶτα πολλοῖς βέλεσιν ἐντυγχάνοντες, ἐρρωμένους δὲ καὶ νεαλεῖς ταῖς προθυμίαις ὁρῶντες, αὖθις ἐξέκαμνον. ἐπεὶ δὲ καταβαίνουσιν αὐτοῖς ἀπὸ λόφων τινῶν ἐπικλινῶν ἐπέθεντο καὶ βραδέως ὑπεξάγοντας ἔβαλλον, ἐπιστρέψαντες οἱ θυρεοφόροι συνέκλεισαν εἴσω τῶν ὅπλων τοὺς ψιλούς, αὐτοὶ δὲ καθέντες εἰς γόνυ προὐβάλοντο τοὺς θυρεούς· οἱ δὲ ὄπισθεν ὑπερέσχον αὐτῶν τὰ ὅπλα κἀκείνων ὁμοίως ἕτεροι. τὸ δὲ σχῆμα παραπλήσιον ἐρέψει γινόμενον ὄψιν τε θεατρικὴν παρέχει, καὶ τῶν προβλημάτων στεγανώτατόν ἐστι πρὸς τοὺς ὀϊστοὺς ἀπολισθαίνοντας. οἱ μέντοι Πάρθοι τὴν εἰς γόνυ κλίσιν τῶν Ῥωμαίων ἀπαγόρευσιν ἡγούμενοι καὶ κάματον εἶναι, τὰ μὲν τόξα κατέθεντο, τοὺς δὲ κοντοὺς διαλαβόντες ἐγγὺς προσέμιξαν. οἱ δὲ Ῥωμαῖοι συναλαλάξαντες ἐξαίφνης ἀνέθορον, καὶ τοῖς ὑσσοῖς παίοντες ἐκ χειρὸς ἔκτεινάν τε τοὺς πρώτους καὶ τροπὴν ἔθεντο τῶν ἄλλων ἁπάντων. ἐγίνετο δὲ ταῦτα καὶ ταῖς ἄλλαις ἡμέραις ἐπὶ μικρὸν ἀνυόντων τῆς ὁδοῦ.", "st": "Ant. 45.1"}, {"sp": "N", "t": "καὶ λιμὸς ἥπτετο τοῦ στρατοῦ σῖτόν τε βραχὺν καὶ διὰ μάχης ποριζομένου καὶ τῶν πρὸς ἄλετον σκευῶν οὐκ εὐποροῦντος. τὰ γὰρ πολλὰ κατελείπετο, τῶν μὲν ἀποθνησκόντων ὑποζυγίων, τῶν δὲ τοὺς νοσοῦντας καὶ τραυματίας φερόντων. λέγεται δὲ χοῖνιξ Ἀττικὴ πυρῶν πεντήκοντα δραχμῶν ὤνιος γενέσθαι· τοὺς δὲ κριθίνους ἄρτους πρὸς ἀργύριον ἱστάντες ἀπεδίδοντο. τραπόμενοι δὲ πρὸς λάχανα καὶ ῥίζας ὀλίγοις μὲν ἐνετύγχανον τῶν συνήθων, ἀναγκαζόμενοι δὲ πειρᾶσθαι καὶ τῶν ἀγεύστων πρότερον ἥψαντό τινος πόας ἐπὶ θάνατον διὰ μανίας ἀγούσης. ὁ γὰρ φαγὼν οὐδὲν ἐμέμνητο τῶν ἄλλων οὐδὲ ἐγίνωσκεν, ἓν δ’ ἔργον εἶχε, κινεῖν καὶ στρέφειν πάντα λίθον, ὥς τι μεγάλης σπουδῆς ἄξιον διαπραττόμενος. ἦν δὲ μεστὸν τὸ πεδίον κεκυφότων χαμᾶζε καὶ τοὺς λίθους περιορυττόντων καὶ μεθιστάντων· τέλος δὲ χολὴν ἐμοῦντες ἔθνησκον, ἐπεὶ καὶ τὸ μόνον ἀντιπαθές, οἶνος, ἐξέλιπε. φθειρομένων δὲ πολλῶν καὶ τῶν Πάρθων οὐκ ἀφισταμένων πολλάκις ἀναφθέγξασθαι τὸν Ἀντώνιον ἱστοροῦσιν, ὦ μύριοι, θαυμάζοντα τοὺς μετὰ Ξενοφῶντος, ὅτι καὶ πλείονα καταβαίνοντες ὁδὸν ἐκ τῆς Βαβυλωνίας καὶ πολλαπλασίοις μαχόμενοι πολεμίοις ἀπεσώθησαν.", "st": "Ant. 45.4"}, {"sp": "N", "t": "οἱ δὲ Πάρθοι διαπλέξαι μὲν οὐ δυνάμενοι τὸν στρατὸν οὐδὲ διασπάσαι τὴν τάξιν, ἤδη δὲ πολλάκις ἡττημένοι καὶ πεφευγότες, αὖθις εἰρηνικῶς ἀνεμίγνυντο τοῖς ἐπὶ χιλὸν ἢ σῖτον προερχομένοις, καὶ τῶν τόξων τὰς νευρὰς ἐπιδεικνύντες ἀνειμένας, ἔλεγον ὡς αὐτοὶ μὲν ἀπίασιν ὀπίσω καὶ τοῦτο ποιοῦνται πέρας ἀμύνης, ὀλίγοι δὲ Μήδων ἀκολουθήσουσιν ἔτι μιᾶς ἢ δευτέρας ὁδὸν ἡμέρας οὐδὲν παρενοχλοῦντες, ἀλλὰ τὰς ἀπωτέρω κώμας φυλάττοντες. τούτοις τοῖς λόγοις ἀσπασμοί τε καὶ φιλοφροσύναι προσῆσαν, ὥστε πάλιν τοὺς Ῥωμαίους εὐθαρσεῖς γενέσθαι καὶ τὸν Ἀντώνιον ἀκούσαντα τῶν πεδίων ἐφίεσθαι μᾶλλον, ἀνύδρου λεγομένης εἶναι τῆς διὰ τῶν ὀρῶν. οὕτω δὲ ποιεῖν μέλλοντος ἧκεν ἀνὴρ ἐπὶ τὸ στρατόπεδον ἐκ τῶν πολεμίων ὄνομα Μιθριδάτης, ἀνεψιὸς Μοναίσου τοῦ παρ’ Ἀντωνίῳ γενομένου καὶ τὰς τρεῖς πόλεις δωρεὰν λαβόντος. ἠξίου δὲ αὐτῷ προσελθεῖν τινα τῶν Παρθιστὶ διαλεχθῆναι δυναμένων ἢ Συριστί. καὶ προσελθόντος Ἀλεξάνδρου τοῦ Ἀντιοχέως, ὃς ἦν Ἀντωνίῳ συνήθης, ὑπειπὼν ὃς εἴη, καὶ Μοναίσῃ τὴν χάριν ἀνάπτων, ἠρώτησε τὸν Ἀλέξανδρον εἰ λόφους συνεχεῖς καὶ ὑψηλοὺς ὁρᾷ πρόσωθεν. φήσαντος δὲ ὁρᾶν, ὑπ’ ἐκείνοις, ἔφη πανστρατιᾷ Πάρθοι λοχῶσιν ὑμᾶς. τὰ γὰρ μεγάλα πεδία τῶν λόφων τούτων ἐξήρτηται, καὶ προσδοκῶσιν ὑμᾶς ἐξηπατημένους ὑπ’ αὐτῶν ἐνταῦθα τρέψεσθαι, τὴν διὰ τῶν ὀρῶν ἀπολιπόντας. ἐκείνη μὲν οὖν ἔχει δίψος καὶ πόνον ὑμῖν συνήθη, ταύτῃ δὲ χωρῶν Ἀντώνιος ἴστω τὰς Κράσσου τύχας αὐτὸν ἐκδεχομένας.", "st": "Ant. 46.1"}, {"sp": "N", "t": "ὁ μὲν οὕτω φράσας ἀπῆλθεν· Ἀντώνιος δὲ ἀκούσας καὶ διαταραχθεὶς συνεκάλει τοὺς φίλους καὶ τὸν ἡγεμόνα τῆς ὁδοῦ Μάρδον οὐδὲ αὐτὸν ἄλλως φρονοῦντα. καὶ γὰρ ἄνευ πολεμίων ἐγίνωσκε τὰς διὰ τῶν πεδίων ἀνοδίας καὶ πλάνας χαλεπὰς καὶ δυστεκμάρτους οὔσας, τὴν δὲ τραχεῖαν ἀπέφαινεν οὐδὲν ἄλλο δυσχερὲς ἢ μιᾶς ἡμέρας ἀνυδρίαν ἔχουσαν. οὕτω δὴ τραπόμενος ταύτην ἦγε νυκτός, ὕδωρ ἐπιφέρεσθαι κελεύσας. ἀγγείων δὲ ἦν ἀπορία τοῖς πολλοῖς· διὸ καὶ τὰ κράνη πιμπλάντες ὕδατος ἐκόμιζον, οἱ δὲ διφθέραις ὑπολαμβάνοντες.", "st": "Ant. 47.1"}, {"sp": "N", "t": "ἤδη δὲ προχωρῶν ἀγγέλλεται τοῖς Πάρθοις καὶ παρὰ τὸ εἰωθὸς ἔτι νυκτὸς ἐδίωκον. ἡλίου δὲ ἀνίσχοντος ἥπτοντο τῶν ἐσχάτων ἀγρυπνίᾳ καὶ πόνῳ κακῶς διακειμένων· τεσσαράκοντα γὰρ καὶ διακοσίους ἐν τῇ νυκτὶ σταδίους κατηνύκεισαν· καὶ τὸ μὴ προσδοκῶσιν οὕτω ταχέως ἐπελθεῖν τοὺς πολεμίους ἀθυμίαν παρεῖχε. καὶ τὸ δίψος ἐπέτεινεν ὁ ἀγών· ἀμυνόμενοι γὰρ ἅμα προῆγον. οἱ δὲ πρῶτοι βαδίζοντες ἐντυγχάνουσι ποταμῷ ψυχρὸν μὲν ἔχοντι καὶ διαυγές, ἁλμυρὸν δὲ καὶ φαρμακῶδες ὕδωρ, ὃ ποθὲν εὐθὺς ὀδύνας ἑλκομένης τῆς κοιλίας καὶ τοῦ δίψους ἀναφλεγομένου παρεῖχε. καὶ ταῦτα τοῦ Μάρδου προλέγοντος οὐδὲν ἧττον ἐκβιαζόμενοι τοὺς ἀνείργοντας ἔπινον. Ἀντώνιος δὲ περιϊὼν ἐδεῖτο βραχὺν ἐγκαρτερῆσαι χρόνον· ἕτερον γὰρ οὐ πόρρω ποταμὸν εἶναι πότιμον, εἶτα τὴν λοιπὴν ἄφιππον καὶ τραχεῖαν, ὥστε παντάπασιν ἀποστρέψασθαι τοὺς πολεμίους. ἅμα δὲ καὶ τοὺς μαχομένους ἀνεκαλεῖτο καὶ κατάζευξιν ἐσήμαινεν, ὡς σκιᾶς γοῦν μεταλάβοιεν οἱ στρατιῶται.", "st": "Ant. 47.3"}, {"sp": "N", "t": "Πηγνυμένων οὖν τῶν σκηνῶν, καὶ τῶν Πάρθων εὐθύς, ὥσπερ εἰώθεισαν, ἀπαλλαττομένων, ἧκεν αὖθις ὁ Μιθριδάτης, καὶ τοῦ Ἀλεξάνδρου προσελθόντος παρῄνει μικρὸν ἡσυχάσαντα τὸν στρατὸν ἀνιστάναι καὶ σπεύδειν ἐπὶ τὸν ποταμόν, ὡς οὐ διαβησομένων Πάρθων, ἄχρι δὲ ἐκείνου διωξόντων. ταῦτα ἀπαγγείλας πρὸς Ἀντώνιον Ἀλέξανδρος ἐκφέρει παρ’ αὐτοῦ χρυσᾶ ποτήρια πάμπολλα καὶ φιάλας, ὧν ἐκεῖνος, ὅσα τῇ ἐσθῆτι κατακρύψαι δυνατὸς ἦν, λαβὼν ἀπήλαυνεν. ἔτι δὲ ἡμέρας οὔσης ἀναζεύξαντες ἐπορεύοντο, τῶν πολεμίων οὐ παρενοχλούντων, αὐτοὶ δὲ ἑαυτοῖς νύκτα χαλεπωτάτην πασῶν ἐκείνην καὶ φοβερωτάτην ἀπεργασάμενοι. τοὺς γὰρ ἔχοντας ἀργύριον ἢ χρυσίον ἀποκτιννύντες ἐσύλων καὶ τὰ χρήματα τῶν ὑποζυγίων ἀφήρπαζον· τέλος δὲ τοῖς Ἀντωνίου σκευοφόροις ἐπιχειρήσαντες ἐκπώματα καὶ τραπέζας πολυτελεῖς κατέκοπτον καὶ διενέμοντο.", "st": "Ant. 48.1"}, {"sp": "N", "t": "θορύβου δὲ πολλοῦ καὶ πλάνου τὸ στράτευμα πᾶν ἐπέχοντος (ᾤοντο γὰρ ἐπιπεπτωκότων τῶν πολεμίων τροπὴν γεγονέναι καὶ διασπασμόν) Ἀντώνιος ἕνα καλέσας τῶν δορυφορούντων αὐτὸν ἀπελευθέρων, ὄνομα Ῥάμνον, ὥρκωσεν, ὅταν κελεύσῃ, τὸ ξίφος αὐτοῦ διεῖναι καὶ τὴν κεφαλὴν ἀποτεμεῖν, ὡς μήτε ἁλῴη ζῶν ὑπὸ τῶν πολεμίων μήτε γνωσθείη τεθνηκώς. ἐκδακρυσάντων δὲ τῶν φίλων ὁ Μάρδος ἐθάρρυνε τὸν Ἀντώνιον, ὡς ἐγγὺς ὄντος τοῦ ποταμοῦ· καὶ γὰρ αὔρα τις ἀπορρέουσα νοτερὰ καὶ ψυχρότερος ἀὴρ ἀπαντῶν ἡδίω τὴν ἀναπνοὴν ἐποίει, καὶ τὸν χρόνον ἔφη τῆς πορείας οὕτω συμπεραίνειν τὸ μέτρον· οὐκέτι γὰρ ἦν πολὺ τὸ λειπόμενον τῆς νυκτός. ἅμα δ’ ἀπήγγελλον ἕτεροι τὸν θόρυβον ἐκ τῆς πρὸς αὑτοὺς ἀδικίας καὶ πλεονεξίας εἶναι. διὸ καὶ καταστῆσαι τὸ πλῆθος εἰς τάξιν ἐκ τῆς πλάνης καὶ τοῦ διασπασμοῦ βουλόμενος ἐκέλευσε σημαίνειν κατάζευξιν.", "st": "Ant. 48.3"}, {"sp": "N", "t": "ἤδη δ’ ὑπέλαμπεν ἡμέρα, καὶ τοῦ στρατοῦ κόσμον ἀρχομένου τινὰ λαμβάνειν καὶ ἡσυχίαν προσέπιπτε τοῖς τελευταίοις τὰ τῶν Πάρθων τοξεύματα, καὶ μάχης σημεῖον ἐδόθη τοῖς ψιλοῖς. οἱ δὲ ὁπλῖται πάλιν ὁμοίως κατερέψαντες ἀλλήλους τοῖς θυρεοῖς ὑπέμενον τοὺς βάλλοντας ἐγγὺς οὐ τολμῶντας συνελθεῖν. ὑπαγόντων δὲ κατὰ μικρὸν οὕτως τῶν πρώτων ὁ ποταμὸς ἐφάνη· καὶ τοὺς ἱππεῖς ἐπ’ αὐτῷ παρατάξας Ἀντώνιος ἐναντίους τοῖς πολεμίοις διεβίβαζε τοὺς ἀσθενεῖς πρώτους. ἤδη δὲ καὶ τοῖς μαχομένοις ἄδεια καὶ ῥᾳστώνη τοῦ πιεῖν ἦν. ὡς γὰρ εἶδον οἱ Πάρθοι τὸν ποταμόν, τάς τε νευρὰς ἀνῆκαν καὶ θαρροῦντας ἐκέλευον διαπερᾶν τοὺς Ῥωμαίους, πολλὰ τὴν ἀρετὴν αὐτῶν ἐγκωμιάζοντες. διαβάντες οὖν καθ’ ἡσυχίαν αὑτοὺς ἀνελάμβανον, εἶτα ὥδευον, οὐ πάνυ τι τοῖς Πάρθοις πιστεύοντες. ἕκτῃ δ’ ἡμέρᾳ μετὰ τὴν τελευταίαν μάχην ἐπὶ τὸν Ἀράξην ποταμὸν ἧκον, ὁρίζοντα Μηδίαν καὶ Ἀρμενίαν. ἐφάνη δὲ καὶ βάθει καὶ τραχύτητι χαλεπός· καὶ λόγος διῆλθεν ἐνεδρεύοντας αὐτόθι τοὺς πολεμίους ἐπιθήσεσθαι διαβαίνουσιν αὐτοῖς. ἐπεὶ δὲ ἀσφαλῶς διαπεράσαντες ἐπέβησαν τῆς Ἀρμενίας, ὥσπερ ἄρτι γῆν ἐκείνην ἰδόντες ἐκ πελάγους, προσεκύνουν καὶ πρὸς δάκρυα καὶ περιβολὰς ἀλλήλων ὑπὸ χαρᾶς ἐτρέποντο. προϊόντες δὲ διὰ χώρας εὐδαίμονος καὶ χρώμενοι πᾶσιν ἀνέδην ἐκ πολλῆς ἀπορίας, ὑδερικοῖς καὶ κοιλιακοῖς περιέπιπτον ἀρρωστήμασιν.", "st": "Ant. 49.1"}, {"sp": "N", "t": "ἐνταῦθα ποιησάμενος ἐξέτασιν αὐτῶν Ἀντώνιος εὗρε δισμυρίους πεζοὺς καὶ τετρακισχιλίους ἱππεῖς ἀπολωλότας, οὐ πάντας ὑπὸ τῶν πολεμίων, ἀλλ’ ὑπὲρ ἡμίσεις νοσήσαντας. ὥδευσαν μὲν οὖν ἀπὸ Φραάτων ἡμέρας ἑπτὰ καὶ εἴκοσι, μάχαις δὲ ὀκτὼ καὶ δέκα Πάρθους ἐνίκησαν, αἱ δὲ νῖκαι κράτος οὐκ εἶχον οὐδὲ βεβαιότητα μικρὰς ποιουμένων καὶ ἀτελεῖς τὰς διώξεις. ᾧ καὶ μάλιστα κατάδηλος ἦν Ἀρταουάσδης ὁ Ἀρμένιος Ἀντώνιον ἐκείνου τοῦ πολέμου τὸ τέλος ἀφελόμενος. εἰ γὰρ οὓς ἀπήγαγεν ἐκ Μηδίας ἱππεῖς ἑξακισχιλίους καὶ μυρίους παρῆσαν, ἐσκευασμένοι παραπλησίως Πάρθοις καὶ συνήθεις μάχεσθαι πρὸς αὐτούς, Ῥωμαίων μὲν τοὺς μαχομένους τρεπομένων, ἐκείνων δὲ τοὺς φεύγοντας αἱρούντων, οὐκ ἂν ὑπῆρξεν αὐτοῖς ἡττωμένοις ἀναφέρειν καὶ ἀνατολμᾶν τοσαυτάκις. ἅπαντες οὖν ὀργῇ παρώξυνον ἐπὶ τὴν τιμωρίαν τοῦ Ἀρμενίου τὸν Ἀντώνιον. ὁ δὲ λογισμῷ χρησάμενος οὔτε ἐμέμψατο τὴν προδοσίαν οὔτε ἀφεῖλε τῆς συνήθους φιλοφροσύνης καὶ τιμῆς πρὸς αὐτόν, ἀσθενὴς τῷ στρατῷ καὶ ἄπορος γεγονώς. ὕστερον μέντοι πάλιν ἐμβαλὼν εἰς Ἀρμενίαν, καὶ πολλαῖς ὑποσχέσεσι καὶ προκλήσεσι πείσας αὐτὸν ἐλθεῖν εἰς χεῖρας, συνέλαβε, καὶ δέσμιον καταγαγὼν εἰς Ἀλεξάνδρειαν, ἐθριάμβευσεν. ᾧ μάλιστα Ῥωμαίους ἐλύπησεν, ὡς τὰ καλὰ καὶ σεμνὰ τῆς πατρίδος Αἰγυπτίοις διὰ Κλεοπάτραν χαριζόμενος. ταῦτα μὲν οὖν ὕστερον ἐπράχθη.", "st": "Ant. 50.1"}, {"sp": "N", "t": "τότε δὲ διὰ πολλοῦ χειμῶνος ἤδη καὶ νιφετῶν ἀπαύστων ἐπειγόμενος ὀκτακισχιλίους ἀπέβαλε καθ’ ὁδόν. αὐτὸς δὲ καταβὰς ὀλιγοστὸς ἐπὶ θάλασσαν ἐν χωρίῳ τινὶ μεταξὺ Βηρυτοῦ κειμένῳ καὶ Σιδῶνος, Λευκὴ κώμη καλεῖται, Κλεοπάτραν περιέμενε· καὶ βραδυνούσης ἀδημονῶν ἤλυε, ταχὺ μὲν εἰς τὸ πίνειν καὶ μεθύσκεσθαι διδοὺς ἑαυτόν, οὐ καρτερῶν δὲ κατακείμενος, ἀλλὰ μεταξὺ πινόντων ἀνιστάμενος καὶ ἀναπηδῶν πολλάκις ἐπισκοπεῖν, ἕως ἐκείνη κατέπλευσεν, ἐσθῆτα πολλὴν καὶ χρήματα κομίζουσα τοῖς στρατιώταις. εἰσὶ δὲ οἱ λέγοντες ὅτι τὴν μὲν ἐσθῆτα παρ’ ἐκείνης λαβών, τὸ δὲ ἀργύριον ἐκ τῶν ἰδίων ἑαυτοῦ, διένειμεν ὡς ἐκείνης διδούσης.", "st": "Ant. 51.1"}, {"sp": "N", "t": "τῷ δὲ βασιλεῖ τῶν Μήδων γίνεται διαφορὰ πρὸς Φραόρτην τὸν Πάρθον, ἀρξαμένη μέν, ὥς φασιν, ὑπὲρ τῶν Ῥωμαϊκῶν λαφύρων, ὑπόνοιαν δὲ τῷ Μήδῳ καὶ φόβον ἀφαιρέσεως τῆς ἀρχῆς παρασχοῦσα. διὸ καὶ πέμπων ἐκάλει τὸν Ἀντώνιον, ἐπαγγελλόμενος συμπολεμήσειν μετὰ τῆς ἑαυτοῦ δυνάμεως. γενόμενος οὖν ἐπ’ ἐλπίδος μεγάλης ὁ Ἀντώνιος (ᾧ γὰρ ἐδόκει μόνῳ τοῦ κατειργάσθαι Πάρθους ἀπολιπεῖν, ἱππέων πολλῶν καὶ τοξοτῶν ἐνδεὴς ἐλθών, τοῦτο ἑώρα προσγινόμενον αὐτῷ χαριζομένῳ μᾶλλον ἢ δεομένῳ παρεσκευάζετο δι) Ἀρμενίας αὖθις ἀναβαίνειν καὶ συγγενόμενος τῷ Μήδῳ περὶ ποταμὸν Ἀράξην οὕτω κινεῖν τὸν πόλεμον.", "st": "Ant. 52.1"}, {"sp": "N", "t": "ἐν δὲ Ῥώμῃ βουλομένης Ὀκταουίας πλεῦσαι πρὸς Ἀντώνιον, ἐπέτρεψε Καῖσαρ, ὡς οἱ πλείους λέγουσιν, οὐκ ἐκείνῃ χαριζόμενος, ἀλλ’ ὅπως περιυβρισθεῖσα καὶ καταμεληθεῖσα πρὸς τὸν πόλεμον αἰτίαν εὐπρεπῆ παράσχοι. γενομένη δὲ ἐν Ἀθήναις ἐδέξατο γράμματα παρὰ Ἀντωνίου κελεύοντος αὐτόθι προσμένειν καὶ τὰ περὶ τὴν ἀνάβασιν δηλοῦντος. ἡ δέ, καίπερ ἀχθομένη καὶ νοοῦσα τὴν πρόφασιν, ὅμως ἔγραψε πυνθανομένη ποῖ κελεύει πεμφθῆναι τὰ κομιζόμενα πρὸς αὐτόν. ἐκόμιζε δὲ πολλὴν μὲν ἐσθῆτα στρατιωτικήν, πολλὰ δὲ ὑποζύγια καὶ χρήματα καὶ δῶρα τοῖς περὶ αὐτὸν ἡγεμόσι καὶ φίλοις· ἐκτὸς δὲ τούτων στρατιώτας ἐπιλέκτους δισχιλίους εἰς στρατηγικὰς σπείρας κεκοσμημένους ἐκπρεπέσι πανοπλίαις. ταῦτα Νίγρος τις Ἀντωνίου φίλος ἀποσταλεὶς παρ’ αὐτῆς ἔφραζε, καὶ προσετίθει τοὺς ἀξίους καὶ πρέποντας ἐπαίνους.", "st": "Ant. 53.1"}, {"sp": "N", "t": "αἰσθομένη δὲ ἡ Κλεοπάτρα τὴν Ὀκταουίαν ὁμόσε χωροῦσαν αὑτῇ, καὶ φοβηθεῖσα μὴ τοῦ τρόπου τῇ σεμνότητι καὶ τῇ Καίσαρος δυνάμει προσκτησαμένη τὸ καθ’ ἡδονὴν ὁμιλεῖν καὶ θεραπεύειν Ἀντώνιον ἄμαχος γένηται καὶ κρατήσῃ παντάπασι τοῦ ἀνδρός, ἐρᾶν αὐτὴ προσεποιεῖτο τοῦ Ἀντωνίου, καὶ τὸ σῶμα λεπταῖς καθῄρει διαίταις· τὸ δὲ βλέμμα προσιόντος ἐκπεπληγμένον, ἀπερχομένου δὲ τηκόμενον καὶ ταπεινούμενον ὑπεφαίνετο. πραγματευομένη δὲ πολλάκις ὀφθῆναι δακρύουσα ταχὺ τῶν δακρύων ἀφῄρει καὶ ἀπέκρυπτεν, ὡς δὴ βουλομένη λανθάνειν ἐκεῖνον. ἐπράττετο δὲ ταῦτα μέλλοντος τοῦ ἀνδρὸς ἐκ Συρίας ἀναβαίνειν πρὸς τὸν Μῆδον. οἱ δὲ κόλακες σπουδάζοντες ὑπὲρ αὐτῆς ἐλοιδόρουν τὸν Ἀντώνιον ὡς σκληρὸν καὶ ἀπαθῆ καὶ παραπολλύντα γύναιον εἰς ἕνα καὶ μόνον ἐκεῖνον ἀνηρτημένον. Ὀκταουίαν μὲν γὰρ πραγμάτων ἕνεκα διὰ τὸν ἀδελφὸν συνελθεῖν καὶ τὸ τῆς γαμετῆς ὄνομα καρποῦσθαι· Κλεοπάτραν δὲ τοσούτων ἀνθρώπων βασιλεύουσαν ἐρωμένην Ἀντωνίου καλεῖσθαι, καὶ τοὔνομα τοῦτο μὴ φεύγειν μηδ’ ἀπαξιοῦν, ἕως ὁρᾶν ἐκεῖνον ἔξεστι καὶ συζῆν· ἀπελαυνομένην δὲ τούτου μὴ περιβιώσεσθαι. τέλος δ’ οὖν οὕτω τὸν ἄνθρωπον ἐξέτηξαν καὶ ἀπεθήλυναν, ὥστε δείσαντα μὴ Κλεοπάτρα πρόηται τὸν βίον, εἰς Ἀλεξάνδρειαν ἐπανελθεῖν, τὸν δὲ Μῆδον εἰς ὥραν ἔτους ἀναβαλέσθαι, καίπερ ἐν στάσει τῶν Παρθικῶν εἶναι λεγομένων. οὐ μὴν ἀλλὰ τοῦτον μὲν ἀναβὰς αὖθις εἰς φιλίαν προσηγάγετο, καὶ λαβὼν ἑνὶ τῶν ἐκ Κλεοπάτρας υἱῶν γυναῖκα μίαν αὐτοῦ τῶν θυγατέρων ἔτι μικρὰν οὖσαν ἐγγυήσας ἐπανῆλθεν, ἤδη πρὸς τὸν ἐμφύλιον πόλεμον τετραμμένος.", "st": "Ant. 53.3"}, {"sp": "N", "t": "Ὀκταουίαν δὲ Καῖσαρ ὑβρίσθαι δοκοῦσαν, ὡς ἐπανῆλθεν ἐξ Ἀθηνῶν, ἐκέλευσε καθ’ ἑαυτὴν οἰκεῖν. ἡ δὲ οὐκ ἔφη τὸν οἶκον ἀπολείψειν τοῦ ἀνδρός, ἀλλὰ κἀκεῖνον αὐτόν, εἰ μὴ δι’ ἑτέρας αἰτίας ἔγνωκε πολεμεῖν Ἀντωνίῳ, παρεκάλει τὰ καθ’ ἑαυτὴν ἐᾶν, ὡς οὐδὲ ἀκοῦσαι καλόν, εἰ τῶν μεγίστων αὐτοκρατόρων ὁ μὲν δι’ ἔρωτα γυναικός, ὁ δὲ διὰ ζηλοτυπίαν εἰς ἐμφύλιον πόλεμον Ῥωμαίους κατέστησε. ταῦτα δὲ λέγουσα μᾶλλον ἐβεβαίου δι’ ἔργων. καὶ γὰρ ᾤκει τὴν οἰκίαν, ὥσπερ αὐτοῦ παρόντος ἐκείνου, καὶ τῶν τέκνων οὐ μόνον τῶν ἐξ ἑαυτῆς, ἀλλὰ καὶ τῶν ἐκ Φουλβίας γεγονότων, καλῶς καὶ μεγαλοπρεπῶς ἐπεμελεῖτο· καὶ τοὺς πεμπομένους ἐπὶ ἀρχάς τινας ἢ πράγματα τῶν Ἀντωνίου φίλων ὑποδεχομένη συνέπραττεν ὧν παρὰ Καίσαρος δεηθεῖεν. ἄκουσα δὲ ἔβλαπτε διὰ τούτων Ἀντώνιον· ἐμισεῖτο γὰρ ἀδικῶν γυναῖκα τοιαύτην. ἐμισήθη δὲ καὶ διὰ τὴν διανέμησιν ἣν ἐποιήσατο τοῖς τέκνοις ἐν Ἀλεξανδρείᾳ, τραγικὴν καὶ ὑπερήφανον καὶ μισορρώμαιον φανεῖσαν. ἐμπλήσας γὰρ ὄχλου τὸ γυμνάσιον καὶ θέμενος ἐπὶ βήματος ἀργυροῦ δύο θρόνους χρυσοῦς, τὸν μὲν ἑαυτῷ, τὸν δὲ Κλεοπάτρᾳ, καὶ τοῖς παισὶν ἑτέρους ταπεινοτέρους, πρῶτον μὲν ἀπέφηνε Κλεοπάτραν βασίλισσαν Αἰγύπτου καὶ Κύπρου καὶ Λιβύης καὶ κοίλης Συρίας, συμβασιλεύοντος αὐτῇ Καισαρίωνος, ὃς ἐκ Καίσαρος ἐδόκει τοῦ προτέρου γεγονέναι Κλεοπάτραν ἔγκυον καταλιπόντος· δεύτερον δὲ τοὺς ἐξ αὑτοῦ καὶ Κλεοπάτρας υἱοὺς βασιλεῖς βασιλέων ἀναγορεύσας Ἀλεξάνδρῳ μὲν Ἀρμενίαν ἀπένειμε καὶ Μηδίαν καὶ τὰ Πάρθων, ὅταν ὑπαγάγηται, Πτολεμαίῳ δὲ Φοινίκην καὶ Συρίαν καὶ Κιλικίαν. ἅμα δὲ καὶ προήγαγε τῶν παίδων Ἀλέξανδρον μὲν ἐσθῆτι Μηδικῇ τιάραν καὶ κίταριν ὀρθὴν ἐχούσῃ, Πτολεμαῖον δὲ κρηπῖσι καὶ χλανίδι καὶ καυσίᾳ διαδηματοφόρῳ κεκοσμημένον. αὕτη γὰρ ἦν σκευὴ τῶν ἀπ’ Ἀλεξάνδρου βασιλέων, ἐκείνη δὲ Μήδων καὶ Ἀρμενίων. ἀσπασαμένων δὲ τῶν παίδων τοὺς γονεῖς, τὸν μὲν Ἀρμενίων φυλακὴ περιΐστατο, τὸν δὲ Μακεδόνων. Κλεοπάτρα μὲν γὰρ καὶ τότε καὶ τὸν ἄλλον χρόνον εἰς πλῆθος ἐξιοῦσα στολὴν ἱερὰν Ἴσιδος ἐλάμβανε καὶ νέα Ἶσις ἐχρημάτιζε.", "st": "Ant. 54.1"}, {"sp": "N", "t": "ταῦτα δὲ εἰς σύγκλητον ἐκφέρων Καῖσαρ καὶ πολλάκις ἐν τῷ δήμῳ κατηγορῶν παρώξυνε τὸ πλῆθος ἐπ’ Ἀντώνιον. ἔπεμπε δὲ καὶ Ἀντώνιος ἀντεγκαλῶν ἐκείνῳ. μέγιστα δ’ ἦν ὧν ἐνεκάλει, πρῶτον μέν, ὅτι Πομπηΐου Σικελίαν ἀφελόμενος οὐκ ἔνειμε μέρος αὐτῷ τῆς νήσου· δεύτερον, ὅτι χρησάμενος ναῦς παρ’ αὐτοῦ πρὸς τὸν πόλεμον ἀπεστέρησε· τρίτον, ὅτι τὸν συνάρχοντα Λέπιδον ἐκβαλὼν τῆς ἀρχῆς καὶ ποιήσας ἄτιμον αὐτὸς ἔχει στρατὸν καὶ χώραν καὶ προσόδους τὰς ἐκείνῳ προσνεμηθείσας· ἐπὶ πᾶσιν, ὅτι τοῖς αὑτοῦ στρατιώταις ἅπασαν ὀλίγου δεῖν Ἰταλίαν κατακεκληρούχηκε, μηδὲν λιπὼν τοῖς ἐκείνου. πρὸς ταῦτα Καῖσαρ ἀπελογεῖτο Λέπιδον μὲν ὑβρίζοντα καταπαῦσαι τῆς ἀρχῆς, ἃ δὲ ἔσχηκε πολεμήσας, νεμήσεσθαι πρὸς Ἀντώνιον ὅταν κἀκεῖνος Ἀρμενίαν πρὸς αὐτόν· τοῖς δὲ στρατιώταις Ἰταλίας μὴ μετεῖναι· Μηδίαν γὰρ ἔχειν καὶ Παρθίαν αὐτούς, ἃς προσεκτήσαντο Ῥωμαίοις καλῶς ἀγωνισάμενοι μετὰ τοῦ αὐτοκράτορος.", "st": "Ant. 55.1"}, {"sp": "N", "t": "ταῦτα ἐν Ἀρμενίᾳ διατρίβων Ἀντώνιος ἤκουσε· καὶ Κανίδιον εὐθὺς ἐκέλευσεν ἑκκαίδεκα τέλη λαβόντα καταβαίνειν ἐπὶ θάλατταν. αὐτὸς δὲ Κλεοπάτραν ἀναλαβὼν εἰς Ἔφεσον ἧκε. καὶ τὸ ναυτικὸν ἐκεῖ συνῄει πανταχόθεν, ὀκτακόσιαι σὺν ὁλκάσι νῆες, ὧν Κλεοπάτρα παρεῖχε διακοσίας καὶ τάλαντα δισμύρια καὶ τροφὴν τῷ στρατῷ παντὶ πρὸς τὸν πόλεμον. Ἀντώνιος δὲ πεισθεὶς ὑπὸ Δομιτίου καί τινων ἄλλων ἐκέλευε Κλεοπάτραν πλεῖν ἐπ’ Αἰγύπτου κἀκεῖ διακαραδοκεῖν τὸν πόλεμον. ἡ δὲ φοβουμένη τὰς δι’ Ὀκταουίας πάλιν αὐτοῦ διαλύσεις ἔπεισε πολλοῖς Κανίδιον χρήμασιν Ἀντωνίῳ διαλεχθῆναι περὶ αὐτῆς, ὡς οὔτε δίκαιον ἀπελαύνεσθαι τοῦ πολέμου γυναῖκα συμβολὰς τηλικαύτας διδοῦσαν, οὔτε συμφέρον ἀθυμοτέρους ποιεῖν τοὺς Αἰγυπτίους μέγα μέρος τῆς ναυτικῆς δυνάμεως ὄντας· ἄλλως δὲ μηδὲ ὁρᾶν οὗτινος τῶν συστρατευόντων βασιλέων ἀπολείποιτο τὸ φρονεῖν Κλεοπάτρα, πολὺν μὲν χρόνον δι’ αὑτῆς κυβερνῶσα βασιλείαν τοσαύτην, πολὺν δὲ ἐκείνῳ συνοῦσα καὶ μανθάνουσα χρῆσθαι πράγμασι μεγάλοις. ταῦτα (ἔδει γὰρ εἰς Καίσαρα πάντα περιελθεῖν) ἐνίκα· καὶ συνιουσῶν τῶν δυνάμεων πλεύσαντες εἰς Σάμον ἐν εὐπαθείαις ἦσαν. ὥσπερ γὰρ βασιλεῦσι καὶ δυνάσταις καὶ τετράρχαις ἔθνεσί τε καὶ πόλεσι πάσαις ταῖς μεταξὺ Συρίας καὶ Μαιώτιδος καὶ Ἀρμενίας καὶ Ἰλλυριῶν προείρητο πέμπειν καὶ κομίζειν τὰς εἰς τὸν πόλεμον παρασκευάς, οὕτω πᾶσι τοῖς περὶ τὸν Διόνυσον τεχνίταις ἐπάναγκες ἦν εἰς Σάμον ἀπαντᾶν· καὶ τῆς ἐν κύκλῳ σχεδὸν ἁπάσης οἰκουμένης περιθρηνουμένης καὶ περιστεναζομένης, μία νῆσος ἐφ’ ἡμέρας πολλὰς κατηυλεῖτο καὶ κατεψάλλετο πληρουμένων θεάτρων καὶ χορῶν ἀγωνιζομένων. συνέθυε δὲ καὶ πόλις πᾶσα βοῦν πέμπουσα, καὶ βασιλεῖς διημιλλῶντο ταῖς ὑποδοχαῖς καὶ δωρεαῖς πρὸς ἀλλήλους. ὥστε καὶ λόγος διῄει, τίνες ἔσονται κρατήσαντες ἐν τοῖς ἐπινικίοις οἱ τοῦ πολέμου τὰς παρασκευὰς οὕτω πολυτελῶς ἑορτάζοντες.", "st": "Ant. 56.1"}, {"sp": "N", "t": "γενόμενος δὲ ἀπὸ τούτων τοῖς μὲν περὶ τὸν Διόνυσον τεχνίταις Πριήνην ἔδωκεν οἰκητήριον, αὐτὸς δὲ πλεύσας εἰς Ἀθήνας πάλιν ἐν παιδιαῖς ἦν καὶ θεάτροις. ζηλοτυποῦσα δὲ Κλεοπάτρα τὰς Ὀκταουίας ἐν τῇ πόλει τιμάς (ἠγαπήθη γὰρ ὑπὸ τῶν Ἀθηναίων ἡ Ὀκταουία μάλιστα) πολλαῖς ἀνελάμβανε φιλοτιμίαις τὸν δῆμον. οἱ δὲ τιμὰς αὐτῇ ψηφισάμενοι πρέσβεις ἔπεμψαν ἐπὶ τὴν οἰκίαν τὸ ψήφισμα κομίζοντας, ὧν εἷς ἦν Ἀντώνιος, ὡς δὴ πολίτης Ἀθηναίων· καὶ δὴ καταστὰς ἐπ’ αὐτῆς λόγον ὑπὲρ τῆς πόλεως διεξῆλθεν. εἰς δὲ Ῥώμην ἔπεμψε τοὺς Ὀκταουίαν ἐκ τῆς οἰκίας ἐκβαλοῦντας. ἀπελθεῖν δέ φασιν αὐτὴν τὰ μὲν τέκνα πάντα Ἀντωνίου μεθ’ ἑαυτῆς ἔχουσαν ἄνευ τοῦ πρεσβυτάτου τῶν ἐκ Φουλβίας (ἐκεῖνος γὰρ ἦν παρὰ τῷ πατρί), κλαίουσαν δὲ καὶ δυσφοροῦσαν εἰ δόξει μία τῶν αἰτιῶν τοῦ πολέμου καὶ αὐτὴ γεγονέναι. Ῥωμαῖοι δὲ ᾤκτειρον οὐκ ἐκείνην, ἀλλ’ Ἀντώνιον, καὶ μᾶλλον οἱ Κλεοπάτραν ἑωρακότες οὔτε κάλλει τῆς Ὀκταουίας οὔτε ὥρᾳ διαφέρουσαν.", "st": "Ant. 57.1"}, {"sp": "N", "t": "Καῖσαρ δὲ τὸ τάχος καὶ τὸ μέγεθος τῆς παρασκευῆς ἀκούσας ἐθορυβήθη, μὴ τοῦ θέρους ἐκείνου διαπολεμεῖν ἀναγκασθῇ. καὶ γὰρ ἐνέδει πολλά, καὶ τοὺς ἀνθρώπους ἐλύπουν αἱ τῶν χρημάτων εἰσπράξεις· ἀναγκαζόμενοι γὰρ οἱ μὲν ἄλλοι τὰ τέταρτα τῶν καρπῶν, οἱ δὲ ἐξελευθερικοὶ τῶν κτημάτων αὐτῶν τὰς ὀγδόας ἀποφέρειν κατεβόων αὐτοῦ, καὶ ταραχαὶ κατεῖχον ἐκ τούτων ἅπασαν τὴν Ἰταλίαν. ὅθεν ἐν τοῖς μεγίστοις ἁμαρτήμασιν Ἀντωνίου τὴν ἀναβολὴν τοῦ πολέμου τίθενται. καὶ γὰρ παρασκευάσασθαι χρόνον ἔδωκε Καίσαρι καὶ τὰς ταραχὰς τῶν ἀνθρώπων ἐξέλυσε. πραττόμενοι γὰρ ἠγριαίνοντο, πραχθέντες δὲ καὶ δόντες ἡσύχαζον. Τίτιος δὲ καὶ Πλάγκος, Ἀντωνίου φίλοι τῶν ὑπατικῶν, ὑπὸ Κλεοπάτρας προπηλακιζόμενοι (πλεῖστα γὰρ ἠναντιώθησαν αὐτῇ περὶ τοῦ συστρατεύειν) ἀποδράντες ᾤχοντο πρὸς Καίσαρα, καὶ περὶ τῶν Ἀντωνίου διαθηκῶν ἐγένοντο μηνυταί, τὰ γεγραμμένα συνειδότες. ἀπέκειντο δ’ αὗται παρὰ ταῖς Ἑστιάσι παρθένοις, καὶ Καίσαρος αἰτοῦντος οὐκ ἔδωκαν· εἰ δὲ βούλοιτο λαμβάνειν, ἐλθεῖν αὐτὸν ἐκέλευον. ἔλαβεν οὖν ἐλθών· καὶ πρῶτον μὲν αὐτὸς ἰδίᾳ τὰ γεγραμμένα διῆλθε, καὶ παρεσημήνατο τόπους τινὰς εὐκατηγορήτους· ἔπειτα τὴν βουλὴν ἀθροίσας ἀνεγίνωσκε, τῶν πλείστων ἀηδῶς ἐχόντων. ἀλλόκοτον γὰρ ἔδοξεν εἶναι καὶ δεινόν, εὐθύνας τινὰ διδόναι ζῶντα περὶ ὧν ἐβουλήθη γενέσθαι μετὰ τὴν τελευτήν. ἐπεφύετο δὲ τῶν γεγραμμένων μάλιστα τῷ περὶ τῆς ταφῆς. ἐκέλευε γὰρ αὑτοῦ τὸ σῶμα, κἂν ἐν Ῥώμῃ τελευτήσῃ, δι’ ἀγορᾶς πομπευθὲν εἰς Ἀλεξάνδρειαν ὡς Κλεοπάτραν ἀποσταλῆναι. Καλουΐσιος δὲ Καίσαρος ἑταῖρος ἔτι καὶ ταῦτα τῶν εἰς Κλεοπάτραν ἐγκλημάτων Ἀντωνίῳ προὔφερε· χαρίσασθαι μὲν αὐτῇ τὰς ἐκ Περγάμου βιβλιοθήκας, ἐν αἷς εἴκοσι μυριάδες βιβλίων ἁπλῶν ἦσαν· ἐν δὲ συνδείπνῳ πολλῶν παρόντων ἀναστάντα τρίβειν αὐτῆς τοὺς πόδας ἔκ τινος ὁρισμοῦ καὶ συνθήκης γενομένης· Ἐφεσίους δὲ ἀνασχέσθαι παρόντος αὐτοῦ κυρίαν τὴν Κλεοπάτραν ἀσπασαμένους· δικάζοντα δὲ πολλάκις τετράρχαις καὶ βασιλεῦσιν ἐπὶ βήματος δελτάρια τῶν ἐρωτικῶν ὀνύχινα καὶ κρυστάλλινα δέχεσθαι παρ’ αὐτῆς καὶ ἀναγινώσκειν· Φουρνίου δὲ λέγοντος, ὃς ἦν ἀξιώματος μεγάλου καὶ δεινότατος εἰπεῖν Ῥωμαίων, τὴν μὲν Κλεοπάτραν ἐν φορείῳ διὰ τῆς ἀγορᾶς κομίζεσθαι, τὸν δὲ Ἀντώνιον, ὡς εἶδεν, ἀναπηδήσαντα τὴν μὲν δίκην ἀπολιπεῖν, ἐκκρεμαννύμενον δὲ τοῦ φορείου παραπέμπειν ἐκείνην.", "st": "Ant. 58.1"}, {"sp": "N", "t": "ἀλλὰ τούτων μὲν ἐδόκει τὰ πλεῖστα καταψεύδεσθαι Καλουΐσιος· οἱ δὲ φίλοι τοῦ Ἀντωνίου περιϊόντες ἐν Ῥώμῃ τὸν δῆμον ἱκέτευον, ἕνα δὲ ἐξ αὑτῶν ἔπεμψαν Γεμίνιον δεόμενοι τοῦ Ἀντωνίου μὴ περιϊδεῖν αὑτὸν ἀποψηφισθέντα τῆς ἀρχῆς καὶ πολέμιον Ῥωμαίων ἀναγορευθέντα. Γεμίνιος δὲ πλεύσας εἰς τὴν Ἑλλάδα Κλεοπάτρᾳ μὲν ἦν ὕποπτος, ὡς ὑπὲρ Ὀκταουίας πράττων, σκωπτόμενος δὲ παρὰ δεῖπνον ἀεὶ καὶ κλισίαις ἀτίμοις προπηλακιζόμενος ἠνείχετο καιρὸν ἐντεύξεως ἀναμένων· κελευσθεὶς δὲ λέγειν ἐφ’ οἷς ἥκει παρὰ τὸ δεῖπνον, τὴν μὲν ἄλλην ἔφη νήφοντος εἶναι διάλεξιν, ἓν δὲ καὶ νήφων ἐπίστασθαι καὶ μεθύων, ὅτι καλῶς ἕξει πάντα Κλεοπάτρας εἰς Αἴγυπτον ἀπαλλαγείσης. πρὸς τοῦτο τοῦ Ἀντωνίου χαλεπήναντος ἡ Κλεοπάτρα καλῶς, ἔφη, πεποίηκας, ὦ Γεμίνιε, τὴν ἀλήθειαν ἄνευ βασάνων ἐξομολογησάμενος. Γεμίνιος μὲν οὖν μετ’ ὀλίγας ἡμέρας ἀποδρὰς εἰς Ῥώμην ᾤχετο. πολλοὺς δὲ καὶ τῶν ἄλλων φίλων οἱ Κλεοπάτρας κόλακες ἐξέβαλον τὰς παροινίας καὶ βωμολοχίας οὐχ ὑπομένοντας, ὧν καὶ Μάρκος ἦν Σιλανὸς καὶ Δέλλιος ὁ ἱστορικός. οὗτος δὲ καὶ δεῖσαί φησιν ἐπιβουλὴν ἐκ Κλεοπάτρας, Γλαύκου τοῦ ἰατροῦ φράσαντος αὐτῷ. προσέκρουσε δὲ Κλεοπάτρᾳ παρὰ δεῖπνον εἰπὼν αὐτοῖς μὲν ὀξίνην ἐγχεῖσθαι, Σάρμεντον δὲ πίνειν ἐν Ῥώμῃ Φαλερῖνον. ὁ δὲ Σάρμεντος ἦν τῶν Καίσαρος παιγνίων παιδάριον, ἃ δηλίκια Ῥωμαῖοι καλοῦσιν.", "st": "Ant. 59.1"}, {"sp": "N", "t": "ἐπεὶ δὲ παρεσκεύαστο Καῖσαρ ἱκανῶς, ψηφίζεται Κλεοπάτρᾳ πολεμεῖν, ἀφελέσθαι δὲ τῆς ἀρχῆς Ἀντώνιον ἧς ἐξέστη γυναικί. καὶ προσεπεῖπε Καῖσαρ ὡς Ἀντώνιος μὲν ὑπὸ φαρμάκων οὐδὲ αὑτοῦ κρατοίη, πολεμοῦσι δ’ αὐτοῖς Μαρδίων ὁ εὐνοῦχος καὶ Ποθεινὸς καὶ Εἰρὰς ἡ Κλεοπάτρας κουρεύτρια καὶ Χάρμιον, ὑφ’ ὧν τὰ μέγιστα διοικεῖται τῆς ἡγεμονίας.", "st": "Ant. 60.1"}, {"sp": "N", "t": "σημεῖα δὲ πρὸ τοῦ πολέμου τάδε γενέσθαι λέγεται. Πείσαυρα μέν, Ἀντωνίου πόλις κληρουχία, ᾠκισμένη παρὰ τὸν Ἀδρίαν, χασμάτων ὑπορραγέντων κατεπόθη. τῶν δὲ περὶ Ἄλβαν Ἀντωνίου λιθίνων ἀνδριάντων ἑνὸς ἱδρὼς ἀνεπίδυεν ἡμέρας πολλάς, ἀποματτόντων τινῶν οὐ παυόμενος. ἐν δὲ Πάτραις διατρίβοντος αὐτοῦ κεραυνοῖς ἐνεπρήσθη τὸ Ἡράκλειον· καὶ τῆς Ἀθήνησι γιγαντομαχίας ὑπὸ πνευμάτων ὁ Διόνυσος ἐκσεισθεὶς εἰς τὸ θέατρον κατηνέχθη· προσῳκείου δὲ ἑαυτὸν Ἀντώνιος Ἡρακλεῖ κατὰ γένος καὶ Διονύσῳ κατὰ τὸν τοῦ βίου ζῆλον, ὥσπερ εἴρηται, Διόνυσος νέος προσαγορευόμενος. ἡ δὲ αὐτὴ θύελλα καὶ τοὺς Εὐμενοῦς καὶ Ἀττάλου κολοσσοὺς ἐπιγεγραμμένους Ἀντωνείους Ἀθήνησιν ἐμπεσοῦσα μόνους ἐκ πολλῶν ἀνέτρεψε. ἡ δὲ Κλεοπάτρας ναυαρχὶς ἐκαλεῖτο μὲν Ἀντωνιάς, σημεῖον δὲ περὶ αὐτὴν δεινὸν ἐφάνη· χελιδόνες γὰρ ὑπὸ τὴν πρύμναν ἐνεόττευσαν· ἕτεραι δὲ ἐπελθοῦσαι καὶ ταύτας ἐξήλασαν καὶ τὰ νεόττια διέφθειραν.", "st": "Ant. 60.2"}, {"sp": "N", "t": "συνιόντων δὲ πρὸς τὸν πόλεμον Ἀντωνίῳ μὲν ἦσαν αἱ μάχιμοι νῆες οὐκ ἐλάττους πεντακοσίων, ἐν αἷς ὀκτήρεις πολλαὶ καὶ δεκήρεις κεκοσμημέναι σοβαρῶς καὶ πανηγυρικῶς, στρατοῦ δὲ μυριάδες δέκα, δισχίλιοι δ’ ἱππεῖς ἐπὶ μυρίοις. βασιλεῖς δὲ ὑπήκοοι συνεμάχουν Βόκχος ὁ Λιβύων καὶ Ταρκόνδημος ὁ τῆς ἄνω Κιλικίας, καὶ Καππαδοκίας μὲν Ἀρχέλαος, Παφλαγονίας δὲ Φιλάδελφος, Κομμαγηνῆς δὲ Μιθριδάτης, Σαδάλας δὲ Θρᾴκης. οὗτοι μὲν αὐτοὶ παρῆσαν, ἐκ δὲ Πόντου Πολέμων στρατὸν ἔπεμπε, καὶ Μάλχος ἐξ Ἀραβίας καὶ Ἡρώδης ὁ Ἰουδαῖος, ἔτι δὲ Ἀμύντας ὁ Λυκαόνων καὶ Γαλατῶν βασιλεύς· ἦν δὲ καὶ παρὰ τοῦ Μήδων βασιλέως ἀπεσταλμένη βοήθεια. Καίσαρι δὲ νῆες ἦσαν πρὸς ἀλκὴν πεντήκοντα καὶ διακόσιαι, στρατοῦ δὲ ὀκτὼ μυριάδες, ἱππεῖς δὲ παραπλήσιοι τὸ πλῆθος τοῖς πολεμίοις. ἦρχον δὲ Ἀντώνιος μὲν τῆς ἀπ’ Εὐφράτου καὶ Ἀρμενίας μέχρι πρὸς τὸν Ἰόνιον καὶ Ἰλλυριούς, Καῖσαρ δὲ ἀπ’ Ἰλλυριῶν τῆς ἐπὶ τὸν ἑσπέριον ὠκεανὸν καθηκούσης καὶ τῆς ἀπ’ ὠκεανοῦ πάλιν ἐπὶ τὸ Τυρρηνικὸν καὶ Σικελικὸν πέλαγος. Λιβύης δὲ τὴν Ἰταλία καὶ Γαλατίᾳ καὶ Ἰβηρίᾳ μέχρι στηλῶν Ἡρακλείων ἀντιπαρήκουσαν εἶχε Καῖσαρ· τὰ δὲ ἀπὸ Κυρήνης μέχρις Αἰθιοπίας Ἀντώνιος.", "st": "Ant. 61.1"}, {"sp": "N", "t": "οὕτω δὲ ἄρα προσθήκη τῆς γυναικὸς ἦν ὥστε τῷ πεζῷ πολὺ διαφέρων ἐβούλετο τοῦ ναυτικοῦ τὸ κράτος εἶναι διὰ Κλεοπάτραν, καὶ ταῦτα πληρωμάτων ἀπορίᾳ συναρπαζομένους ὁρῶν ὑπὸ τῶν τριηραρχῶν ἐκ τῆς πολλὰ δὴ τλάσης Ἑλλάδος ὁδοιπόρους, ὀνηλάτας, θεριστάς, ἐφήβους, καὶ οὐδὲ οὕτω πληρουμένας τὰς ναῦς, ἀλλὰ τὰς πλείστας ἀποδεεῖς καὶ μοχθηρῶς πλεούσας. Καῖσαρ δὲ οὐ πρὸς ὕψος οὐδὲ ὄγκον ἐπιδεικτικῶς πεπηγυίαις ναυσίν, εὐστρόφοις δὲ καὶ ταχείαις καὶ πεπληρωμέναις ἀκριβῶς ἐξηρτυμένον ἐν Τάραντι καὶ Βρεντεσίῳ συνέχων τὸ ναυτικόν, ἔπεμπε πρὸς Ἀντώνιον ἀξιῶν μὴ διατρίβειν τὸν χρόνον, ἀλλ’ ἔρχεσθαι μετὰ τῶν δυνάμεων· αὐτὸς δὲ τῷ μὲν στόλῳ παρέξειν ὅρμους ἀκωλύτους καὶ λιμένας, ὑποχωρήσειν δὲ τῷ πεζῷ τῆς παραλίας ἵππου δρόμον ἀπὸ θαλάττης, μέχρι ἂν ἀσφαλῶς ἀποβῇ καὶ στρατοπεδεύσηται. τούτοις ἀντικομπάξων Ἀντώνιος αὐτὸν μὲν εἰς μονομαχίαν προὐκαλεῖτο, καίπερ ὢν πρεσβύτερος· εἰ δὲ φεύγοι τοῦτο, περὶ Φάρσαλον ἠξίου τοῖς στρατεύμασιν, ὡς πάλαι Καῖσαρ καὶ Πομπήϊος, διαγωνίσασθαι. φθάνει δὲ Καῖσαρ, Ἀντωνίου περὶ τὸ Ἄκτιον ὁρμοῦντος, ἐν ᾧ τόπῳ νῦν ἡ Νικόπολις ἵδρυται, διαβαλὼν τὸν Ἰόνιον καὶ τῆς Ἠπείρου χωρίον ὃ Τορύνη καλεῖται κατασχών· θορυβουμένων δὲ τῶν περὶ τὸν Ἀντώνιον (ὑστέρει γὰρ ὁ πεζὸς αὐτοῖς) ἡ μὲν Κλεοπάτρα σκώπτουσα, τί δεινόν, ἔλεγεν, εἰ Καῖσαρ ἐπὶ τορύνῃ κάθηται;", "st": "Ant. 62.1"}, {"sp": "N", "t": "Ἀντώνιος δέ, ἅμα ἡμέρᾳ τῶν πολεμίων ἐπιπλεόντων, φοβηθεὶς μὴ τῶν ἐπιβατῶν ἐρήμους ἕλωσι τὰς ναῦς, τοὺς μὲν ἐρέτας ὁπλίσας ἐπὶ τῶν καταστρωμάτων παρέταξεν ὄψεως ἕνεκα, τοὺς δὲ ταρσοὺς τῶν νεῶν ἐγείρας καὶ πτερώσας ἑκατέρωθεν ἐν τῷ στόματι περὶ τὸ Ἄκτιον ἀντιπρῴρους συνεῖχεν, ὡς ἐνήρεις καὶ παρεσκευασμένας ἀμύνεσθαι. καὶ Καῖσαρ μὲν οὕτω καταστρατηγηθεὶς ἀπεχώρησεν. ἔδοξε δὲ καὶ τὸ ὕδωρ εὐμηχάνως ἐρύμασί τισιν ἐμπεριλαβὼν ἀφελέσθαι τοὺς πολεμίους, τῶν ἐν κύκλῳ χωρίων ὀλίγον καὶ πονηρὸν ἐχόντων. εὐγνωμόνως δὲ καὶ Δομιτίῳ προσηνέχθη παρὰ τὴν Κλεοπάτρας γνώμην. ἐπεὶ γὰρ ἐκεῖνος ἤδη πυρέττων εἰς μικρὸν ἐμβὰς ἀκάτιον πρὸς Καίσαρα μετέστη, βαρέως ἐνεγκὼν ὁ Ἀντώνιος ὅμως πᾶσαν αὐτῷ τὴν ἀποσκευὴν μετὰ τῶν φίλων καὶ τῶν θεραπόντων ἀπέπεμψε. καὶ Δομίτιος μέν, ὥσπερ ἐπὶ τῷ μὴ λαθεῖν τὴν ἀπιστίαν αὐτοῦ καὶ προδοσίαν μεταβαλλόμενος, εὐθὺς ἐτελεύτησεν.", "st": "Ant. 63.1"}, {"sp": "N", "t": "ἐγένοντο δὲ καὶ βασιλέων ἀποστάσεις, Ἀμύντου καὶ Δηϊοτάρου, πρὸς Καίσαρα. τὸ δὲ ναυτικὸν ἐν παντὶ δυσπραγοῦν καὶ πρὸς ἅπασαν ὑστερίζον βοήθειαν αὖθις ἠνάγκαζε τῷ πεζῷ προσέχειν τὸν Ἀντώνιον. ἔσχε δὲ καὶ Κανίδιον τὸν ἄρχοντα τοῦ πεζοῦ μεταβολὴ γνώμης παρὰ τὰ δεινά· καὶ συνεβούλευε Κλεοπάτραν μὲν ἀποπέμπειν, ἀναχωρήσαντα δὲ εἰς Θρᾴκην ἢ Μακεδονίαν πεζομαχίᾳ κρῖναι. καὶ γὰρ Δικόμης ὁ Γετῶν βασιλεὺς ὑπισχνεῖτο πολλῇ στρατιᾷ βοηθήσειν· οὐκ εἶναι δὲ αἰσχρὸν εἰ Καίσαρι γεγυμνασμένῳ περὶ τὸν Σικελικὸν πόλεμον ἐκστήσονται τῆς θαλάσσης, ἀλλὰ δεινὸν εἰ τῶν πεζῶν ἀγώνων ἐμπειρότατος ὢν Ἀντώνιος οὐ χρήσεται ῥώμῃ καὶ παρασκευῇ τοσούτων ὁπλιτῶν, εἰς ναῦς διανέμων καὶ καταναλίσκων τὴν δύναμιν.", "st": "Ant. 63.4"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ ἐξενίκησε Κλεοπάτρα διὰ τῶν νεῶν κριθῆναι τὸν πόλεμον, ἤδη πρὸς φυγὴν ὁρῶσα, καὶ τιθεμένη τὰ καθ’ ἑαυτήν, οὐχ ὅπου πρὸς τὸ νικᾶν ἔσται χρήσιμος, ἀλλ’ ὅθεν ἄπεισι ῥᾷστα τῶν πραγμάτων ἀπολλυμένων. ἦν δὲ μακρὰ σκέλη κατατείνοντα πρὸς τὸν ναύσταθμον τῆς στρατοπεδείας, δι’ ὧν ὁ Ἀντώνιος εἰώθει παριέναι μηδὲν ὑφορώμενος. οἰκέτου δὲ Καίσαρι φράσαντος ὡς δυνατὸν εἴη κατιόντα διὰ τῶν σκελῶν συλλαβεῖν αὐτόν, ἔπεμψε τοὺς ἐνεδρεύσοντας. οἱ δὲ παρὰ τοσοῦτον ἦλθον ὥστε συναρπάσαι τὸν προηγούμενον αὐτοῦ προεξαναστάντες· αὐτὸς δὲ δρόμῳ μόλις ὑπεξέφυγεν.", "st": "Ant. 63.5"}, {"sp": "N", "t": "ὡς δὲ ναυμαχεῖν ἐδέδοκτο, τὰς μὲν ἄλλας ἐνέπρησε ναῦς πλὴν ἑξήκοντα τῶν Αἰγυπτίων, τὰς δὲ ἀρίστας καὶ μεγίστας ἀπὸ τριήρους μέχρι δεκήρους ἐπλήρου, δισμυρίους ἐμβιβάζων ὁπλίτας καὶ δισχιλίους τοξότας. ἔνθα πεζομάχον ἄνδρα τῶν ταξιαρχῶν λέγουσι, παμπόλλους ἠγωνισμένον ἀγῶνας Ἀντωνίῳ καὶ κατατετριμμένον τὸ σῶμα, τοῦ Ἀντωνίου παριόντος ἀνακλαύσασθαι καὶ εἰπεῖν· ὦ αὐτόκρατορ, τί τῶν τραυμάτων τούτων ἢ τοῦ ξίφους καταγνοὺς ἐν ξύλοις πονηροῖς ἔχεις τὰς ἐλπίδας; Αἰγύπτιοι καὶ Φοίνικες ἐν θαλάσσῃ μαχέσθωσαν, ἡμῖν δὲ γῆν δός, ἐφ’ ἧς εἰώθαμεν ἑστῶτες ἀποθνήσκειν ἢ νικᾶν τοὺς πολεμίους. πρὸς ταῦτα μηδὲν ἀποκρινάμενος, ἀλλὰ τῇ χειρὶ καὶ τῷ προσώπῳ μόνον οἷον ἐγκελευσάμενος τὸν ἄνδρα θαρρεῖν, παρῆλθεν, οὐ χρηστὰς ἔχων ἐλπίδας, ὅς γε καὶ τοὺς κυβερνήτας τὰ ἱστία βουλομένους ἀπολιπεῖν ἠνάγκασεν ἐμβαλέσθαι καὶ κομίζειν, λέγων ὅτι δεῖ μηδένα φεύγοντα τῶν πολεμίων διαφυγεῖν.", "st": "Ant. 64.1"}, {"sp": "N", "t": "ἐκείνην μὲν οὖν τὴν ἡμέραν καὶ τρεῖς τὰς ἐφεξῆς μεγάλῳ πνεύματι κυμανθὲν τὸ πέλαγος τὴν μάχην ἐπέσχε, πέμπτῃ δὲ νηνεμίας καὶ γαλήνης ἀκλύστου γενομένης συνῄεσαν, Ἀντώνιος μὲν τὸ δεξιὸν κέρας ἔχων καὶ Ποπλικόλας, Κοίλιος δὲ τὸ εὐώνυμον, ἐν μέσῳ δὲ Μάρκος Ὀκτάβιος καὶ Μάρκος Ἰνστήϊος. Καῖσαρ δ’ ἐπὶ τοῦ εὐωνύμου τάξας Ἀγρίππαν αὑτῷ τὸ δεξιὸν κατέλιπε. τῶν δὲ πεζῶν τὸν μὲν Ἀντωνίου Κανίδιος, τὸν δὲ Καίσαρος Ταῦρος ἐπὶ τῆς θαλάττης παρατάξαντες ἡσύχαζον. αὐτῶν δὲ τῶν ἡγεμόνων Ἀντώνιος μὲν ἐπεφοίτα πανταχόσε κωπήρει, τοὺς στρατιώτας παρακαλῶν ὑπὸ βρίθους τῶν νεῶν ὥσπερ ἐκ γῆς ἑδραίους μάχεσθαι, τοῖς δὲ κυβερνήταις διακελευόμενος ὥσπερ ὁρμούσαις ἀτρέμα ταῖς ναυσὶ δέχεσθαι τὰς ἐμβολὰς τῶν πολεμίων, τὴν περὶ τὸ στόμα δυσχωρίαν φυλάττοντας. Καίσαρι δὲ λέγεται μὲν ἔτι σκότους ἀπὸ τῆς σκηνῆς κύκλῳ περιϊόντι πρὸς τὰς ναῦς ἄνθρωπος ἐλαύνων ὄνον ἀπαντῆσαι, πυθομένῳ δὲ τοὔνομα γνωρίσας αὐτὸν εἰπεῖν. ἐμοὶ μὲν Εὔτυχος ὄνομα, τῷ δὲ ὄνῳ Νίκων. διὸ καὶ τοῖς ἐμβόλοις τὸν τόπον κοσμῶν ὕστερον ἔστησε χαλκοῦν ὄνον καὶ ἄνθρωπον. ἐπιδὼν δὲ τὴν ἄλλην παράταξιν, ἐν πλοίῳ πρὸς τὸ δεξιὸν κομισθεὶς ἐθαύμασεν ἀτρεμοῦντας ἐν τοῖς στενοῖς τοὺς πολεμίους· ἡ γὰρ ὄψις ἦν τῶν νεῶν ἐπ’ ἀγκύραις ὁρμουσῶν. καὶ τοῦτο μέχρι πολλοῦ πεπεισμένος ἀνεῖχε τὰς ἑαυτοῦ περὶ ὀκτὼ στάδια τῶν ἐναντίων ἀφεστώσας. ἕκτη δὲ ἦν ὥρα, καὶ πνεύματος αἰρομένου πελαγίου δυσανασχετοῦντες οἱ Ἀντωνίου πρὸς τὴν διατριβήν, καὶ τοῖς ὕψεσι καὶ μεγέθεσι τῶν οἰκείων νεῶν πεποιθότες ὡς ἀπροσμάχοις, τὸ εὐώνυμον ἐκίνησαν· ἰδὼν δὲ Καῖσαρ ἥσθη καὶ πρύμναν ἐκρούσατο τῷ δεξιῷ, βουλόμενος ἔτι μᾶλλον ἐκ τοῦ κόλπου καὶ τῶν στενῶν ἔξω τοὺς πολεμίους ἐπισπάσασθαι, καὶ περιπλέων εὐήρεσι σκάφεσι τοῖς ἑαυτοῦ συμπλέκεσθαι πρὸς ναῦς ὑπ’ ὄγκου καὶ πληρωμάτων ὀλιγότητος ἀργὰς καὶ βραδείας.", "st": "Ant. 65.1"}, {"sp": "N", "t": "ἀρχομένου δὲ τοῦ ἀγῶνος ἐν χερσὶν εἶναι, ἐμβολαὶ μὲν οὐκ ἦσαν οὐδὲ ἀναρρήξεις νεῶν, τῶν μὲν Ἀντωνίου διὰ βάρος ῥύμην οὐκ ἐχουσῶν, ἣ μάλιστα ποιεῖ τὰς τῶν ἐμβόλων πληγὰς ἐνεργούς, τῶν δὲ Καίσαρος οὐ μόνον ἀντιπρῴρων συμφέρεσθαι πρὸς χαλκώματα στερεὰ καὶ τραχέα φυλασσομένων, ἀλλὰ μηδὲ κατὰ πλευρὰν ἐμβολὰς διδόναι θαρρουσῶν. ἀπεθραύοντο γὰρ τὰ ἔμβολα ῥᾳδίως ᾗ προσπέσοιε σκάφεσι τετραγώνων ξύλων μεγάλων σιδήρῳ συνηρμοσμένων πρὸς ἄλληλα δεδεμένοις. ἦν οὖν πεζομαχίᾳ προσφερὴς ὁ ἀγών· τὸ δὲ ἀληθέστερον εἰπεῖν, τειχομαχία. τρεῖς γὰρ ἅμα καὶ τέσσαρες περὶ μίαν τῶν Ἀντωνίου συνείχοντο, γέρροις καὶ δόρασι καὶ κοντοῖς χρωμένων καὶ πυροβόλοις· οἱ δὲ Ἀντωνίου καὶ καταπέλταις ἀπὸ ξυλίνων πύργων ἔβαλλον.", "st": "Ant. 66.1"}, {"sp": "N", "t": "Ἀγρίππου δὲ θάτερον κέρας εἰς κύκλωσιν ἐκτείνοντος, ἀντανάγειν Ποπλικόλας ἀναγκαζόμενος ἀπερρήγνυτο τῶν μέσων. θορυβουμένων δὲ τούτων καὶ συμπλεκομένων τοῖς περὶ τὸν Ἀρρούντιον, ἀκρίτου δὲ καὶ κοινῆς ἔτι τῆς ναυμαχίας συνεστώσης, αἰφνίδιον αἱ Κλεοπάτρας ἑξήκοντα νῆες ὤφθησαν αἰρόμεναι πρὸς ἀπόπλουν τὰ ἱστία καὶ διὰ μέσου φεύγουσαι τῶν μαχομένων· ἦσαν γὰρ ὀπίσω τεταγμέναι τῶν μεγάλων, καὶ διεκπίπτουσαι ταραχὴν ἐποίουν. οἱ δὲ ἐναντίοι θαυμάζοντες ἐθεῶντο, τῷ πνεύματι χρωμένας ὁρῶντες καὶ ἐπεχούσας πρὸς τὴν Πελοπόννησον. ἔνθα δὴ φανερὸν αὑτὸν Ἀντώνιος ἐποίησεν οὔτε ἄρχοντος οὔτε ἀνδρὸς οὔτε ὅλως ἰδίοις λογισμοῖς διοικούμενον, ἀλλ’ ὅπερ τις παίζων εἶπε, τὴν ψυχὴν τοῦ ἐρῶντος ἐν ἀλλοτρίῳ σώματι ζῆν, ἑλκόμενος ὑπὸ τῆς γυναικὸς ὥσπερ συμπεφυκὼς καὶ συμμεταφερόμενος. οὐ γὰρ ἔφθη τὴν ἐκείνης ἰδὼν ναῦν ἀποπλέουσαν, καὶ πάντων ἐκλαθόμενος καὶ προδοὺς καὶ ἀποδρὰς τοὺς ὑπὲρ αὐτοῦ μαχομένους καὶ θνήσκοντας, εἰς πεντήρη μετεμβάς, Ἀλεξᾶ τοῦ Σύρου καὶ Σκελλίου μόνων αὐτῷ συνεμβάντων, ἐδίωκε τὴν ἀπολωλεκυῖαν ἤδη καὶ προσαπολοῦσαν αὐτόν.", "st": "Ant. 66.3"}, {"sp": "N", "t": "ἐκείνη δὲ γνωρίσασα σημεῖον ἀπὸ τῆς νεὼς ἀνέσχε· καὶ προσενεχθεὶς οὕτω καὶ ἀναληφθεὶς ἐκείνην μὲν οὔτε εἶδεν οὔτε ὤφθη, παρελθὼν δὲ μόνος εἰς πρῴραν ἐφ’ ἑαυτοῦ καθῆστο σιωπῇ, ταῖς χερσὶν ἀμφοτέραις ἐχόμενος τῆς κεφαλῆς. ἐν τούτῳ δὲ λιβυρνίδες ὤφθησαν διώκουσαι παρὰ Καίσαρος· ὁ δὲ ἀντίπρῳρον ἐπιστρέφειν τὴν ναῦν κελεύσας τὰς μὲν ἄλλας ἀνέστειλεν, Εὐρυκλῆς δ’ ὁ Λάκων ἐνέκειτο σοβαρῶς, λόγχην τινὰ κραδαίνων ἀπὸ τοῦ καταστρώματος ὡς ἀφήσων ἐπ’ αὐτόν. ἐπιστάντος δὲ τῇ πρῴρᾳ τοῦ Ἀντωνίου καί τίς οὗτος, εἰπόντος, ὁ διώκων Ἀντώνιον; ἐγώ, εἶπεν, Εὐρυκλῆς ὁ Λαχάρους, τῇ Καίσαρος τύχῃ τὸν τοῦ πατρὸς ἐκδικῶν θάνατον. ὁ δὲ Λαχάρης ὑπ’ Ἀντωνίου λῃστείας αἰτίᾳ περιπεσὼν ἐπελεκίσθη. πλὴν οὐκ ἐνέβαλεν ὁ Εὐρυκλῆς εἰς τὴν Ἀντωνίου ναῦν, ἀλλὰ τὴν ἑτέραν τῶν ναυαρχίδων (δύο γὰρ ἦσαν) τῷ χαλκώματι πατάξας περιερρόμβησε, καὶ ταύτην τε πλαγίαν περιπεσοῦσαν εἷλε καὶ τῶν ἄλλων μίαν, ἐν ᾗ πολυτελεῖς σκευαὶ τῶν περὶ δίαιταν ἦσαν. ἀπαλλαγέντος δὲ τούτου πάλιν ὁ Ἀντώνιος εἰς τὸ αὐτὸ σχῆμα καθεὶς ἑαυτὸν ἡσυχίαν ἦγε· καὶ τρεῖς ἡμέρας καθ’ ἑαυτὸν ἐν πρῴρᾳ διαιτηθείς, εἴθ’ ὑπ’ ὀργῆς, εἴτ’ αἰδούμενος ἐκείνην, Ταινάρῳ προσέσχεν. ἐνταῦθα δ’ αὐτοὺς αἱ συνήθεις γυναῖκες πρῶτον μὲν εἰς λόγους ἀλλήλοις συνήγαγον, εἶτα συνδειπνεῖν καὶ συγκαθεύδειν ἔπεισαν.", "st": "Ant. 67.1"}, {"sp": "N", "t": "ἤδη δὲ καὶ τῶν στρογγύλων πλοίων οὐκ ὀλίγα καὶ τῶν φίλων τινὲς ἐκ τῆς τροπῆς ἠθροίζοντο πρὸς αὐτούς, ἀγγέλλοντες ἀπολωλέναι τὸ ναυτικόν, οἴεσθαι δὲ τὸ πεζὸν συνεστάναι. Ἀντώνιος δὲ πρὸς μὲν Κανίδιον ἀγγέλους ἔπεμπεν, ἀναχωρεῖν διὰ Μακεδονίας εἰς Ἀσίαν τῷ στρατῷ κατὰ τάχος κελεύων, αὐτὸς δὲ μέλλων ἀπὸ Ταινάρου πρὸς τὴν Λιβύην διαίρειν, ὁλκάδα μίαν, πολὺ μὲν νόμισμα, πολλοῦ δὲ ἀξίας ἐν ἀργύρῳ καὶ χρυσῷ κατασκευὰς τῶν βασιλικῶν κομίζουσαν, ἐξελόμενος τοῖς φίλοις ἐπέδωκε κοινῇ, νείμασθαι καὶ σώζειν ἑαυτοὺς κελεύσας. ἀρνουμένους δὲ καὶ κλαίοντας εὐμενῶς πάνυ καὶ φιλοφρόνως παραμυθησάμενος καὶ δεηθεὶς ἀπέστειλε, γράψας πρὸς Θεόφιλον τὸν ἐν Κορίνθῳ διοικητὴν ὅπως ἀσφάλειαν ἐκπορίσῃ καὶ ἀποκρύψῃ τοὺς ἄνδρας ἄχρι ἂν ἱλάσασθαι Καίσαρα δυνηθῶσιν. οὗτος ἦν Θεόφιλος Ἱππάρχου πατὴρ τοῦ πλεῖστον παρὰ Ἀντωνίῳ δυνηθέντος, πρώτου δὲ πρὸς Καίσαρα τῶν ἀπελευθέρων μεταβαλομένου καὶ κατοικήσαντος ὕστερον ἐν Κορίνθῳ.", "st": "Ant. 67.5"}, {"sp": "N", "t": "ταῦτα μὲν οὖν τὰ κατὰ τὸν Ἀντώνιον. ἐν Ἀκτίῳ δὲ πολὺν ὁ στόλος ἀντισχὼν Καίσαρι χρόνον, καὶ μέγιστον βλαβεὶς ὑπὸ τοῦ κλύδωνος ὑψηλοῦ κατὰ πρῴραν ἱσταμένου, μόλις ὥρας δεκάτης ἀπεῖπε. καὶ νεκροὶ μὲν οὐ πλείους ἐγένοντο πεντακισχιλίων, ἑάλωσαν δὲ τριακόσιαι νῆες, ὡς αὐτὸς ἀνέγραψε Καῖσαρ. ᾔσθοντο δὲ οὐ πολλοὶ πεφευγότος Ἀντωνίου, καὶ τοῖς πυθομένοις τὸ πρῶτον ἄπιστος ἦν ὁ λόγος, εἰ δέκα καὶ ἐννέα τάγματα πεζῶν ἀηττήτων καὶ δισχιλίους ἐπὶ μυρίοις ἱππεῖς ἀπολιπὼν οἴχεται, καθάπερ οὐ πολλάκις ἐπ’ ἀμφότερα τῇ τύχῃ κεχρημένος οὐδὲ μυρίων ἀγώνων καὶ πολέμων μεταβολαῖς ἐγγεγυμνασμένος. οἱ δὲ στρατιῶται καὶ πόθον τινὰ καὶ προσδοκίαν εἶχον ὡς αὐτίκα ποθὲν ἐπιφανησομένου· καὶ τοσαύτην ἐπεδείξαντο πίστιν καὶ ἀρετὴν ὥστε καὶ τῆς φυγῆς αὐτοῦ φανερᾶς γενομένης ἡμέρας ἑπτὰ συμμεῖναι, περιορῶντες ἐπιπρεσβευόμενον αὐτοῖς Καίσαρα. τέλος δέ, τοῦ στρατηγοῦ Κανιδίου νύκτωρ ἀποδράντος καὶ καταλιπόντος τὸ στρατόπεδον, γενόμενοι πάντων ἔρημοι καὶ προδοθέντες ὑπὸ τῶν ἀρχόντων, τῷ κρατοῦντι προσεχώρησαν.", "st": "Ant. 68.1"}, {"sp": "N", "t": "ἐκ τούτου Καῖσαρ μὲν ἐπ’ Ἀθήνας ἔπλευσε, καὶ διαλλαγεὶς τοῖς Ἕλλησι τὸν περιόντα σῖτον ἐκ τοῦ πολέμου διένειμε ταῖς πόλεσι πραττούσαις ἀθλίως καὶ περικεκομμέναις χρημάτων, ἀνδραπόδων, ὑποζυγίων. ὁ γοῦν πρόπαππος ἡμῶν Νίκαρχος διηγεῖτο τοὺς πολίτας ἅπαντας ἀναγκάζεσθαι τοῖς ὤμοις καταφέρειν μέτρημα πυρῶν τεταγμένον ἐπὶ τὴν πρὸς Ἀντίκυραν θάλασσαν, ὑπὸ μαστίγων ἐπιταχυνομένους· καὶ μίαν μὲν οὕτω φορὰν ἐνεγκεῖν, τὴν δὲ δευτέραν ἤδη μεμετρημένοις καὶ μέλλουσιν αἴρεσθαι νενικημένον Ἀντώνιον ἀγγελῆναι, καὶ τοῦτο διασῶσαι τὴν πόλιν· εὐθὺς γὰρ τῶν Ἀντωνίου διοικητῶν καὶ στρατιωτῶν φυγόντων διανείμασθαι τὸν σῖτον αὐτούς.", "st": "Ant. 68.4"}, {"sp": "N", "t": "Ἀντώνιος δὲ Λιβύης ἁψάμενος καὶ Κλεοπάτραν εἰς Αἴγυπτον ἐκ Παραιτονίου προπέμψας αὐτὸς ἀπέλαυεν ἐρημίας ἀφθόνου, σὺν δυσὶ φίλοις ἀλύων καὶ πλανώμενος, Ἕλληνι μὲν Ἀριστοκράτει ῥητορικῷ, Ῥωμαίῳ δὲ Λουκιλλίῳ, περὶ οὗ δι’ ἑτέρων γεγράφαμεν ὡς ἐν Φιλίπποις, ὑπὲρ τοῦ διαφυγεῖν Βροῦτον, αὐτὸς αὑτόν, ὡς δὴ Βροῦτος ὤν, ἐνεχείρισε τοῖς διώκουσι, καὶ διασωθεὶς ὑπ’ Ἀντωνίου διὰ τοῦτο, πιστὸς αὐτῷ καὶ βέβαιος ἄχρι τῶν ἐσχάτων καιρῶν παρέμεινεν. ἐπεὶ δὲ καὶ τὴν ἐν Λιβύη δύναμιν ὁ πεπιστευμένος ἀπέστησεν, ὁρμήσας ἑαυτὸν ἀνελεῖν καὶ διακωλυθεὶς ὑπὸ τῶν φίλων καὶ κομισθεὶς εἰς Ἀλεξάνδρειαν εὗρε Κλεοπάτραν ἐπιτολμῶσαν ἔργῳ παραβόλῳ καὶ μεγάλῳ. τοῦ γὰρ εἴργοντος ἰσθμοῦ τὴν ἐρυθρὰν ἀπὸ τῆς κατ’ Αἴγυπτον θαλάσσης καὶ δοκοῦντος Ἀσίαν καὶ Λιβύην ὁρίζειν, ᾗ σφίγγεται μάλιστα τοῖς πελάγεσι καὶ βραχύτατος εὖρός ἐστι, τριακοσίων σταδίων ὄντων, ἐνεχείρησεν ἄρασα τὸν στόλον ὑπερνεωλκῆσαι, καὶ καθεῖσα τὰς ναῦς εἰς τὸν Ἀραβικὸν κόλπον μετὰ χρημάτων πολλῶν καὶ δυνάμεως ἔξω κατοικεῖν, ἀποφυγοῦσα δουλείαν καὶ πόλεμον. ἐπεὶ δὲ τὰς πρώτας ἀνελκομένας τῶν νεῶν οἱ περὶ τὴν Πέτραν Ἄραβες κατέκαυσαν, ἔτι δὲ Ἀντώνιος τὸν ἐν Ἀκτίῳ στρατὸν ᾤετο συμμένειν, ἐπαύσατο, καὶ τὰς ἐμβολὰς ἐφύλαττεν. Ἀντώνιος δὲ τὴν πόλιν ἐκλιπὼν καὶ τὰς μετὰ τῶν φίλων διατριβάς, οἴκησιν ἔναλον κατεσκεύαζεν αὑτῷ περὶ τὴν Φάρον, εἰς τὴν θάλασσαν χῶμα προβαλών· καὶ διῆγεν αὐτόθι φυγὰς ἀνθρώπων, καὶ τὸν Τίμωνος ἀγαπᾶν καὶ ζηλοῦν βίον ἔφασκεν, ὡς δὴ πεπονθὼς ὅμοια· καὶ γὰρ αὐτὸς ἀδικηθεὶς ὑπὸ φίλων καὶ ἀχαριστηθείς, διὰ τοῦτο καὶ πᾶσιν ἀνθρώποις ἀπιστεῖν καὶ δυσχεραίνειν.", "st": "Ant. 69.1"}, {"sp": "N", "t": "ὁ δὲ Τίμων ἦν Ἀθηναῖος, καὶ γέγονεν ἡλικίᾳ μάλιστα κατὰ τὸν Πελοποννησιακὸν πόλεμον, ὡς ἐκ τῶν Ἀριστοφάνους καὶ Πλάτωνος δραμάτων λαβεῖν ἔστι. κωμῳδεῖται γὰρ ἐν ἐκείνοις ὡς δυσμενὴς καὶ μισάνθρωπος· ἐκκλίνων δὲ καὶ διωθούμενος ἅπασαν ἔντευξιν, Ἀλκιβιάδην, νέον ὄντα καὶ θρασύν, ἠσπάζετο καὶ κατεφίλει προθύμως. Ἀπημάντου δὲ θαυμάσαντος καὶ πυθομένου τὴν αἰτίαν, φιλεῖν ἔφη τὸν νεανίσκον εἰδὼς ὅτι πολλῶν Ἀθηναίοις κακῶν αἴτιος ἔσοιτο. τὸν δὲ Ἀπήμαντον μόνον ὡς ὅμοιον αὐτῷ καὶ ζηλοῦντα τὴν δίαιταν ἔστιν ὅτε προσίετο· καί ποτε τῆς τῶν Χοῶν οὔσης ἑορτῆς εἱστιῶντο καθ’ αὑτοὺς οἱ δύο, τοῦ δ’ Ἀπημάντου φήσαντος, ὡς καλόν, ὦ Τίμων, τὸ συμπόσιον ἡμῶν, εἴγε σύ, ἔφη, μὴ παρῆς. λέγεται δὲ Ἀθηναίων ἐκκλησιαζόντων ἀναβὰς ἐπὶ τὸ βῆμα ποιῆσαι σιωπὴν καὶ προσδοκίαν μεγάλην διὰ τὸ παράδοξον· εἶτα εἰπεῖν· ἔστι μοι μικρὸν οἰκόπεδον, ὦ ἄνδρες Ἀθηναῖοι, καὶ συκῆ τις ἐν αὐτῷ πέφυκεν, ἐξ ἧς ἤδη συχνοὶ τῶν πολιτῶν ἀπήγξαντο. μέλλων οὖν οἰκοδομεῖν τὸν τόπον ἐβουλήθην δημοσίᾳ προειπεῖν, ἵνα, ἂν ἄρα τινὲς ἐθέλωσιν ὑμῶν, πρὶν ἐκκοπῆναι τὴν συκῆν, ἀπάγξωνται. τελευτήσαντος δὲ αὐτοῦ καὶ ταφέντος Ἁλῆσι παρὰ τὴν θάλασσαν ὤλισθε τὰ προὔχοντα τοῦ αἰγιαλοῦ, καὶ τὸ κῦμα περιελθὸν ἄβατον καὶ ἀπροσπέλαστον ἀνθρώπῳ πεποίηκε τὸν τάφον. ἦν δ’ ἐπιγεγραμμένον·", "st": "Ant. 70.1"}, {"sp": "N", "t": "ἐνθάδ’ ἀπορρήξας ψυχὴν βαρυδαίμονα κεῖμαι.", "st": "Ant. 70.1b"}, {"sp": "N", "t": "τοὔνομα δ’ οὐ πεύσεσθε, κακοὶ δὲ κακῶς ἀπόλοισθε.", "st": "Ant. 70.1c"}, {"sp": "N", "t": "καὶ τοῦτο μὲν αὐτὸν ἔτι ζῶντα πεποιηκέναι λέγουσι, τὸ δὲ περιφερόμενον Καλλιμάχειόν ἐστι·", "st": "Ant. 70.1d"}, {"sp": "N", "t": "Τίμων μισάνθρωπος ἐνοικέω. ἀλλὰ πάρελθε,<br>οἰμώζειν εἴπας πολλὰ πάρελθε μόνον.", "st": "Ant. 70.1e"}, {"sp": "N", "t": "ταῦτα μὲν περὶ Τίμωνος ἀπὸ πολλῶν ὀλίγα. τῷ δὲ Ἀντωνίῳ Κανίδιός τε τῆς ἀποβολῆς τῶν ἐν Ἀκτίῳ δυνάμεων αὐτάγγελος ἦλθε, καὶ τὸν Ἰουδαῖον Ἡρώδην ἔχοντά τινα τάγματα καὶ σπείρας ἤκουσε Καίσαρι προσκεχωρηκέναι, καὶ τοὺς ἄλλους ὁμοίως δυνάστας ἀφίστασθαι καὶ μηδὲν ἔτι συμμένειν τῶν ἐκτός. οὐ μὴν διετάραξέ τι τούτων αὐτόν, ἀλλὰ ὥσπερ ἄσμενος τὸ ἐλπίζειν ἀποτεθειμένος, ἵνα καὶ τὸ φροντίζειν, τὴν μὲν ἔναλον ἐκείνην δίαιταν, ἣν Τιμώνειον ὠνόμαζεν, ἐξέλιπεν, ἀναληφθεὶς δὲ ὑπὸ τῆς Κλεοπάτρας εἰς τὰ βασίλεια πρὸς δεῖπνα καὶ πότους καὶ διανομὰς ἔτρεψε τὴν πόλιν, ἐγγράφων μὲν εἰς ἐφήβους τὸν Κλεοπάτρας παῖδα καὶ Καίσαρος, τὸ δὲ ἀπόρφυρον καὶ τέλειον ἱμάτιον Ἀντύλλῳ τῷ ἐκ Φουλβίας περιτιθείς, ἐφ’ οἷς ἡμέρας πολλὰς συμπόσια καὶ κῶμοι καὶ θαλίαι τὴν Ἀλεξάνδρειαν κατεῖχον. αὐτοὶ δὲ τὴν μὲν τῶν ἀμιμητοβίων ἐκείνην σύνοδον κατέλυσαν, ἑτέραν δὲ συνέταξαν οὐδέν τι λειπομένην ἐκείνης ἁβρότητι καὶ τρυφαῖς καὶ πολυτελείαις, ἣν συναποθανουμένων ἐκάλουν. ἀπεγράφοντο γὰρ οἱ φίλοι συναποθανουμένους ἑαυτούς, καὶ διῆγον εὐπαθοῦντες ἐν δείπνων περιόδοις. Κλεοπάτρα δὲ φαρμάκων θανασίμων συνῆγε παντοδαπὰς δυνάμεις, ὧν ἑκάστης τὸ ἀνώδυνον ἐλέγχουσα προὔβαλλε τοῖς ἐπὶ θανάτῳ φρουρουμένοις. ἐπεὶ δὲ ἑώρα τὰς μὲν ὠκυμόρους τὴν ὀξύτητα τοῦ θανάτου δι’ ὀδύνης ἐπιφερούσας, τὰς δὲ πρᾳοτέρας τάχος οὐκ ἐχούσας, τῶν θηρίων ἀπεπειρᾶτο, θεωμένης αὐτῆς ἕτερον ἑτέρῳ προσφερόντων. ἐποίει δὲ τοῦτο καθ’ ἡμέραν· καὶ σχεδὸν ἐν πᾶσι μόνον εὕρισκε τὸ δῆγμα τῆς ἀσπίδος ἄνευ σπασμοῦ καὶ στεναγμοῦ κάρον ὑπνώδη καὶ καταφορὰν ἐφελκόμενον, ἱδρῶτι μαλακῷ τοῦ προσώπου, καὶ τῶν αἰσθητηρίων ἀμαυρώσει παραλυομένων ῥᾳδίως καὶ δυσχεραινόντων πρὸς τὰς ἐξεγέρσεις καὶ ἀνακλίσεις, ὥσπερ οἱ βαθέως καθεύδοντες.", "st": "Ant. 71.1"}, {"sp": "N", "t": "ἅμα δὲ καὶ πρὸς Καίσαρα πρέσβεις ἔπεμπον εἰς Ἀσίαν, ἡ μὲν αἰτουμένη τὴν ἐν Αἰγύπτῳ τοῖς παισὶν ἀρχήν, ὁ δὲ ἀξιῶν Ἀθήνησιν, εἰ μὴ δοκοίη περὶ Αἴγυπτον, ἰδιώτης καταβιῶναι. φίλων δὲ ἀπορίᾳ καὶ ἀπιστίᾳ διὰ τὰς αὐτομολίας ὁ τῶν παίδων διδάσκαλος ἐπέμφθη πρεσβεύων Εὐφρόνιος. καὶ γὰρ Ἀλεξᾶς ὁ Λαοδικεύς, γνωρισθεὶς μὲν ἐν Ῥώμῃ διὰ Τιμαγένους καὶ πλεῖστον Ἑλλήνων δυνηθείς, γενόμενος δὲ τῶν Κλεοπάτρας ἐπ’ Ἀντώνιον ὀργάνων τὸ βιαιότατον καὶ τῶν ὑπὲρ Ὀκταουίας ἱσταμένων ἐν αὐτῷ λογισμῶν ἀνατροπεύς, ἐπέμφθη μὲν Ἡρώδην τὸν βασιλέα τῆς μεταβολῆς ἐφέξων, αὐτοῦ δὲ καταμείνας καὶ προδοὺς Ἀντώνιον ἐτόλμησεν εἰς ὄψιν ἐλθεῖν Καίσαρος, Ἡρώδῃ πεποιθώς. ὤνησε δὲ αὐτὸν οὐδὲν Ἡρώδης, ἀλλ’ εὐθὺς εἱρχθεὶς καὶ κομισθεὶς εἰς τὴν ἑαυτοῦ πατρίδα δέσμιος ἐκεῖ Καίσαρος κελεύσαντος ἀνῃρέθη. τοιαύτην μὲν Ἀλεξᾶς ἔτι ζῶντι δίκην Ἀντωνίῳ τῆς ἀπιστίας ἐξέτισε.", "st": "Ant. 72.1"}, {"sp": "N", "t": "Καῖσαρ δὲ τοὺς μὲν ὑπὲρ Ἀντωνίου λόγους οὐκ ἠνέσχετο, Κλεοπάτραν δὲ ἀπεκρίνατο μηδενὸς ἁμαρτήσεσθαι τῶν ἐπιεικῶν ἀνελοῦσαν Ἀντώνιον ἢ ἐκβαλοῦσαν. συνέπεμψε δὲ καὶ παρ’ αὑτοῦ τινα τῶν ἀπελευθέρων Θύρσον, οὐκ ἀνόητον ἄνθρωπον οὐδὲ ἀπιθάνως ἂν ἀφ’ ἡγεμόνος νέου διαλεχθέντα πρὸς γυναῖκα σοβαρὰν καὶ θαυμαστὸν ὅσον ἐπὶ κάλλει φρονοῦσαν. οὗτος ἐντυγχάνων αὐτῇ μακρότερα τῶν ἄλλων καὶ τιμώμενος διαφερόντως ὑπόνοιαν τῷ Ἀντωνίῳ παρέσχε, καὶ συλλαβὼν αὐτὸν ἐμαστίγωσεν, εἶτα ἀφῆκε πρὸς Καίσαρα γράψας ὡς ἐντρυφῶν καὶ περιφρονῶν παροξύνειεν αὐτόν, εὐπαρόξυντον ὑπὸ κακῶν ὄντα. σὺ δὲ εἰ μὴ φέρεις τὸ πρᾶγμα, ἔφη, μετρίως, ἔχεις ἐμὸν ἀπελεύθερον Ἵππαρχον. τοῦτον κρεμάσας μαστίγωσον, ἵνα ἴσον ἔχωμεν. ἐκ τούτου Κλεοπάτρα μὲν ἀπολυομένη τὰς αἰτίας καὶ ὑπονοίας ἐθεράπευεν αὐτὸν περιττῶς· καὶ τὴν ἑαυτῆς γενέθλιον ταπεινῶς διαγαγοῦσα καὶ ταῖς τύχαις πρεπόντως, τὴν ἐκείνου πᾶσαν ὑπερβαλλομένη λαμπρότητα καὶ πολυτέλειαν ἑώρτασεν, ὥστε πολλοὺς τῶν κεκλημένων ἐπὶ τὸ δεῖπνον πένητας ἐλθόντας ἀπελθεῖν πλουσίους. Καίσαρα δὲ Ἀγρίππας ἀνεκαλεῖτο πολλάκις ἀπὸ Ῥώμης γράφων ὡς τῶν ἐκεῖ πραγμάτων τὴν παρουσίαν αὐτοῦ ποθούντων.", "st": "Ant. 73.1"}, {"sp": "N", "t": "ἔσχεν οὖν ἀναβολὴν ὁ πόλεμος τότε· τοῦ δὲ χειμῶνος παρελθόντος αὖθις ἐπῄει διὰ Συρίας, οἱ δὲ στρατηγοὶ διὰ Λιβύης. ἁλόντος δὲ Πηλουσίου λόγος ἦν ἐνδοῦναι Σέλευκον οὐκ ἀκούσης τῆς Κλεοπάτρας. ἡ δὲ ἐκείνου μὲν γυναῖκα καὶ παῖδας Ἀντωνίῳ κτεῖναι παρεῖχεν, αὐτὴ δὲ θήκας ἔχουσα καὶ μνήματα κατεσκευασμένα περιττῶς εἴς τε κάλλος καὶ ὕψος, ἃ προσῳκοδόμησε τῷ ναῷ τῆς Ἴσιδος, ἐνταῦθα τῶν βασιλικῶν συνεφόρει τὰ πλείστης ἄξια σπουδῆς, χρυσόν, ἄργυρον, σμάραγδον, μαργαρίτην, ἔβενον, ἐλέφαντα, κινάμωμον· ἐπὶ πᾶσι δὲ δᾷδα πολλὴν καὶ στυππεῖον, ὥστε δείσαντα περὶ τῶν χρημάτων Καίσαρα, μὴ τραπομένη πρὸς ἀπόγνωσιν ἡ γυνὴ διαφθείρῃ καὶ καταφλέξῃ τὸν πλοῦτον, ἀεί τινας ἐλπίδας αὐτῇ φιλανθρώπους προσπέμπειν ἅμα τῷ στρατῷ πορευόμενον ἐπὶ τὴν πόλιν. ἱδρυθέντος δὲ αὐτοῦ περὶ τὸν ἱππόδρομον, Ἀντώνιος ἐπεξελθὼν ἠγωνίσατο λαμπρῶς καὶ τροπὴν τῶν Καίσαρος ἱππέων ἐποίησε, καὶ κατεδίωξεν ἄχρι τοῦ στρατοπέδου. μεγαλυνόμενος δὲ τῇ νίκῃ παρῆλθεν εἰς τὰ βασίλεια, καὶ τὴν Κλεοπάτραν κατεφίλησεν ἐν τοῖς ὅπλοις, καὶ τὸν ἠγωνισμένον προθυμότατα τῶν στρατιωτῶν συνέστησεν. ἡ δὲ ἀριστεῖον αὐτῷ θώρακα χρυσοῦν καὶ κράνος ἔδωκεν. ἐκεῖνος μὲν οὖν ὁ ἄνθρωπος λαβὼν ταῦτα διὰ νυκτὸς ηὐτομόλησε πρὸς Καίσαρα.", "st": "Ant. 74.1"}, {"sp": "N", "t": "πάλιν δὲ Ἀντώνιος ἔπεμπε Καίσαρα μονομαχῆσαι προκαλούμενος. ἀποκριναμένου δὲ ἐκείνου πολλὰς ὁδοὺς Ἀντωνίῳ παρεῖναι θανάτων, συμφρονήσας ὅτι τοῦ διὰ μάχης οὐκ ἔστιν αὐτῷ βελτίων θάνατος, ἔγνω καὶ κατὰ γῆν ἅμα καὶ θάλατταν ἐπιχειρεῖν. καὶ παρὰ δεῖπνον, ὡς λέγεται, τοὺς οἰκέτας ἐκέλευσεν ὑποχεῖν καὶ προθυμότερον εὐωχεῖν αὐτόν· ἄδηλον γάρ, εἰ τοῦτο ποιήσουσιν αὔριον ἢ δεσπόταις ἑτέροις ὑπηρετήσουσιν, αὐτὸς δὲ κείσεται σκελετὸς καὶ τὸ μηδὲν γενόμενος. τοὺς δὲ φίλους ἐπὶ τούτοις δακρύοντας ὁρῶν ἔφη μὴ προάξειν ἐπὶ τὴν μάχην, ἐξ ἧς αὑτῷ θάνατον εὐκλεᾶ μᾶλλον ἢ σωτηρίαν ζητεῖν καὶ νίκην.", "st": "Ant. 75.1"}, {"sp": "N", "t": "ἐν ταύτῃ τῇ νυκτὶ λέγεται, μεσούσης σχεδόν, ἐν ἡσυχίᾳ καὶ κατηφείᾳ τῆς πόλεως διὰ φόβον καὶ προσδοκίαν τοῦ μέλλοντος οὔσης, αἰφνίδιον ὀργάνων τε παντοδαπῶν ἐμμελεῖς τινας φωνὰς ἀκουσθῆναι καὶ βοὴν ὄχλου μετὰ εὐασμῶν καὶ πηδήσεων σατυρικῶν, ὥσπερ θιάσου τινὸς οὐκ ἀθορύβως ἐξελαύνοντος· εἶναι δὲ τὴν ὁρμὴν ὁμοῦ τι διὰ τῆς πόλεως μέσης ἐπὶ τὴν πύλην ἔξω τὴν τετραμμένην πρὸς τοὺς πολεμίους, καὶ ταύτῃ τὸν θόρυβον ἐκπεσεῖν πλεῖστον γενόμενον. ἐδόκει δὲ τοῖς ἀναλογιζομένοις τὸ σημεῖον ἀπολείπειν ὁ θεὸς Ἀντώνιον, ᾧ μάλιστα συνεξομοιῶν καὶ συνοικειῶν ἑαυτὸν διετέλεσεν.", "st": "Ant. 75.3"}, {"sp": "N", "t": "ἅμα δὲ ἡμέρᾳ τὸν πεζὸν αὐτὸς ἐπὶ τῶν πρὸ τῆς πόλεως λόφων ἱδρύσας ἐθεᾶτο τὰς ναῦς ἀνηγμένας καὶ ταῖς τῶν πολεμίων προσφερομένας· καὶ περιμένων ἔργον τι παρ’ ἐκείνων ἰδεῖν ἡσύχαζεν. οἱ δὲ ὡς ἐγγὺς ἐγένοντο, ταῖς κώπαις ἠσπάσαντο τοὺς Καίσαρος, ἐκείνων τε ἀντασπασαμένων μετεβάλοντο, καὶ πάσαις ἅμα ταῖς ναυσὶν ὁ στόλος εἷς γενόμενος ἐπέπλει πρὸς τὴν πόλιν ἀντίπρῳρος. τοῦτο Ἀντώνιος ἰδὼν ἀπελείφθη μὲν εὐθὺς ὑπὸ τῶν ἱππέων μεταβαλομένων, ἡττηθεὶς δὲ τοῖς πεζοῖς ἀνεχώρησεν εἰς τὴν πόλιν, ὑπὸ Κλεοπάτρας προδεδόσθαι βοῶν οἷς δι’ ἐκείνην ἐπολέμησεν. ἡ δὲ τὴν ὀργὴν αὐτοῦ φοβηθεῖσα καὶ τὴν ἀπόνοιαν εἰς τὸν τάφον κατέφυγε καὶ τοὺς καταρράκτας ἀφῆκε κλείθροις καὶ μοχλοῖς καρτεροὺς ὄντας· πρὸς δὲ Ἀντώνιον ἔπεμψε τοὺς ἀπαγγελοῦντας ὅτι τέθνηκε. πιστεύσας δὲ ἐκεῖνος καὶ εἰπὼν πρὸς αὑτόν, τί ἔτι μέλλεις, Ἀντώνιε; τὴν μόνην ἡ τύχη καὶ λοιπὴν ἀφῄρηκε τοῦ φιλοψυχεῖν πρόφασιν, εἰσῆλθεν εἰς τὸ δωμάτιον, καὶ τὸν θώρακα παραλύων καὶ διαστέλλων, ὦ Κλεοπάτρα, εἶπεν, οὐκ ἄχθομαί σου στερούμενος· αὐτίκα γὰρ εἰς ταὐτὸν ἀφίξομαι· ἀλλ’ ὅτι γυναικὸς ὁ τηλικοῦτος αὐτοκράτωρ εὐψυχίᾳ πεφώραμαι λειπόμενος.", "st": "Ant. 76.1"}, {"sp": "N", "t": "ἦν δέ τις οἰκέτης αὐτοῦ πιστὸς Ἔρως ὄνομα. τοῦτον ἐκ πολλοῦ παρακεκληκώς, εἰ δεήσειεν, ἀνελεῖν αὐτόν, ἀπῄτει τὴν ὑπόσχεσιν. ὁ δὲ σπασάμενος τὸ ξίφος ἀνέσχε μὲν ὡς παίσων ἐκεῖνον, ἀποστρέψας δὲ τὸ πρόσωπον ἑαυτὸν ἀπέκτεινε. πεσόντος δὲ αὐτοῦ πρὸς τοὺς πόδας ὁ Ἀντώνιος εὖγε, εἶπεν, ὦ Ἔρως, ὅτι μὴ δυνηθεὶς αὐτὸς ἐμὲ ποιεῖν ὃ δεῖ διδάσκεις· καὶ παίσας διὰ τῆς κοιλίας ἑαυτὸν ἀφῆκεν εἰς τὸ κλινίδιον. ἦν δὲ οὐκ εὐθυθάνατος ἡ πληγή. διὸ καὶ τῆς φορᾶς τοῦ αἵματος, ἐπεὶ κατεκλίθη, παυσαμένης, ἀναλαβὼν ἐδεῖτο τῶν παρόντων ἐπισφάττειν αὐτόν. οἱ δὲ ἔφευγον ἐκ τοῦ δωματίου βοῶντος καὶ σφαδάζοντος, ἄχρι οὗ παρὰ Κλεοπάτρας ἧκε Διομήδης ὁ γραμματεύς, κομίζειν αὐτὸν ὡς ἐκείνην εἰς τὸν τάφον κελευσθείς.", "st": "Ant. 76.4"}, {"sp": "N", "t": "γνοὺς οὖν ὅτι ζῇ, προθύμως ἐκέλευσεν ἄρασθαι τοῖς ὑπηρέταις τὸ σῶμα, καὶ διὰ χειρῶν προσεκομίσθη ταῖς θύραις τοῦ οἰκήματος. ἡ δὲ Κλεοπάτρα τὰς μὲν θύρας οὐκ ἀνέῳξεν, ἐκ δὲ θυρίδων τινῶν φανεῖσα σειρὰς καὶ καλώδια καθίει. καὶ τούτοις ἐναψάντων τὸν Ἀντώνιον ἀνεῖλκεν αὐτὴ καὶ δύο γυναῖκες, ἃς μόνας ἐδέξατο μεθ’ αὑτῆς εἰς τὸν τάφον. οὐδὲν ἐκείνου λέγουσιν οἰκτρότερον γενέσθαι οἱ παραγενόμενοι θέαμα. πεφυρμένος γὰρ αἵματι καὶ δυσθανατῶν εἵλκετο, τὰς χεῖρας ὀρέγων εἰς ἐκείνην καὶ παραιωρούμενος. οὐ γὰρ ἦν γυναιξὶ ῥᾴδιον τὸ ἔργον, ἀλλὰ μόλις ἡ Κλεοπάτρα ταῖν χεροῖν ἐμπεφυκυῖα καὶ κατατεινομένη τῷ προσώπῳ τὸν δεσμὸν ἀνελάμβανεν, ἐπικελευομένων τῶν κάτωθεν αὐτῇ καὶ συναγωνιώντων. δεξαμένη δὲ αὐτὸν οὕτως καὶ κατακλίνασα περιερρήξατο τε τοὺς πέπλους ἐπ’ αὐτῷ, καὶ τὰ στέρνα τυπτομένη καὶ σπαράττουσα ταῖς χερσί, καὶ τῷ προσώπῳ τοῦ αἵματος ἀναματτομένη, δεσπότην ἐκάλει καὶ ἄνδρα καὶ αὐτοκράτορα· καὶ μικροῦ δεῖν ἐπιλέληστο τῶν αὑτῆς κακῶν οἴκτῳ τῶν ἐκείνου. καταπαύσας δὲ τὸν θρῆνον αὐτῆς Ἀντώνιος ᾔτησε πιεῖν οἶνον, εἴτε διψῶν, εἴτε συντομώτερον ἐλπίζων ἀπολυθήσεσθαι. πιὼν δὲ παρῄνεσεν αὐτῇ τὰ μὲν ἑαυτῆς, ἂν ᾖ μὴ μετ’ αἰσχύνης, σωτήρια τίθεσθαι, μάλιστα τῶν Καίσαρος ἑταίρων Προκληΐῳ πιστεύουσαν, αὐτὸν δὲ μὴ θρηνεῖν ἐπὶ ταῖς ὑστάταις μεταβολαῖς, ἀλλὰ μακαρίζειν ὧν ἔτυχε καλῶν, ἐπιφανέστατος ἀνθρώπων γενόμενος καὶ πλεῖστον ἰσχύσας καὶ νῦν οὐκ ἀγεννῶς Ῥωμαῖος ὑπὸ Ῥωμαίου κρατηθείς.", "st": "Ant. 77.1"}, {"sp": "N", "t": "ὅσον δὲ ἀπολιπόντος αὐτοῦ Προκλήϊος ἧκε παρὰ Καίσαρος. ἐπεὶ γὰρ ἑαυτὸν πατάξας ὁ Ἀντώνιος ᾤχετο πρὸς Κλεοπάτραν κομιζόμενος, Δερκεταῖός τις τῶν δορυφόρων λαβὼν τὸ ἐγχειρίδιον αὐτοῦ καὶ ἀποκρύψας ὑπεξῆλθε, καὶ δραμὼν πρὸς Καίσαρα πρῶτος ἤγγειλε τὴν Ἀντωνίου τελευτήν, καὶ τὸ ξίφος ἔδειξεν ᾑμαγμένον. ὁ δὲ ὡς ἤκουσεν, ἐνδοτέρω τῆς σκηνῆς ἀποστὰς ἀπεδάκρυσεν ἄνδρα κηδεστὴν γενόμενον καὶ συνάρχοντα καὶ πολλῶν ἀγώνων καὶ πραγμάτων κοινωνόν. εἶτα τὰς ἐπιστολὰς λαβὼν καὶ τοὺς φίλους καλέσας ἀνεγίνωσκεν ὡς εὐγνώμονα γράφοντος αὐτοῦ καὶ δίκαια φορτικὸς ἦν καὶ ὑπερήφανος ἀεὶ περὶ τὰς ἀποκρίσεις ἐκεῖνος. ἐκ δὲ τούτου τὸν Προκλήϊον ἔπεμψε κελεύσας, ἢν δύνηται, μάλιστα τῆς Κλεοπάτρας ζώσης κρατῆσαι· καὶ γὰρ ἐφοβεῖτο περὶ τῶν χρημάτων, καὶ μέγα πρὸς δόξαν ἡγεῖτο τοῦ θριάμβου καταγαγεῖν ἐκείνην. εἰς μὲν οὖν χεῖρας τῷ Προκληΐῳ συνελθεῖν οὐκ ἠθέλησεν· ἐγίνοντο δὲ λόγοι τῷ οἰκήματι προσελθόντος ἔξωθεν αὐτοῦ κατὰ θύρας ἐπιπέδους, ἀποκεκλειμένας μὲν ὀχυρῶς, φωνῇ δὲ διέξοδον ἐχούσας. καὶ διελέχθησαν ἡ μὲν αἰτουμένη τοῖς παισὶ τὴν βασιλείαν, ὁ δὲ θαρρεῖν καὶ πάντα πιστεύειν Καίσαρι κελεύων.", "st": "Ant. 78.1"}, {"sp": "N", "t": "ὡς δὲ κατιδὼν τὸν τόπον ἀπήγγειλε Καίσαρι, Γάλλος μὲν ἐπέμφθη πάλιν ἐντευξόμενος αὐτῇ· καὶ πρὸς τὰς θύρας ἐλθὼν ἐπίτηδες ἐμήκυνε τὸν λόγον. ἐν τούτῳ δὲ Προκλήϊος κλίμακος προστεθείσης διὰ τῆς θυρίδος εἰσῆλθεν ᾗ τὸν Ἀντώνιον αἱ γυναῖκες ἐδέξαντο. καὶ πρὸς τὰς θύρας αὐτὰς εὐθύς, αἷς ἡ Κλεοπάτρα παρειστήκει προσέχουσα τῷ Γάλλῳ, κατέβαινεν ὑπηρέτας ἔχων δύο μεθ’ αὑτοῦ. τῶν δὲ συγκαθειργμένων τῇ Κλεοπάτρᾳ γυναικῶν τῆς ἑτέρας ἀνακραγούσης, τάλαινα Κλεοπάτρα, ζωγρεῖ, μεταστραφεῖσα καὶ θεασαμένη τὸν Προκλήϊον ὥρμησε μὲν αὑτὴν πατάξαι· παρεζωσμένη γὰρ ἐτύγχανέ τι τῶν λῃστρικῶν ξιφιδίων· προσδραμὼν δὲ ταχὺ καὶ περισχὼν αὐτὴν ταῖς χερσὶν ἀμφοτέραις ὁ Προκλήϊος, ἀδικεῖς, εἶπεν, ὦ Κλεοπάτρα, καὶ σεαυτὴν καὶ Καίσαρα, μεγάλην ἀφαιρουμένη χρηστότητος ἐπίδειξιν αὐτοῦ, καὶ διαβάλλουσα τὸν πρᾳότατον ἡγεμόνων ὡς ἄπιστον καὶ ἀδιάλλακτον. ἅμα δὲ καὶ τὸ ξίφος αὐτῆς παρείλετο, καὶ τὴν ἐσθῆτα, μὴ κρύπτοι τι φάρμακον, ἐξέσεισεν. ἐπέμφθη δὲ καὶ παρὰ Καίσαρος τῶν ἀπελευθέρων Ἐπαφρόδιτος, ᾧ προσετέτακτο ζῶσαν αὐτὴν φυλάττειν ἰσχυρῶς ἐπιμελόμενον, τἆλλα δὲ πρὸς τὸ ῥᾷστον ἐνδιδόναι καὶ ἥδιστον.", "st": "Ant. 79.1"}, {"sp": "N", "t": "αὐτὸς δὲ Καῖσαρ εἰσήλαυνεν εἰς τὴν πόλιν, Ἀρείῳ τῷ φιλοσόφῳ προσδιαλεγόμενος καὶ τὴν δεξιὰν ἐνδεδωκώς, ἵνα εὐθὺς ἐν τοῖς πολίταις περίβλεπτος εἴη καὶ θαυμάζοιτο τιμώμενος ὑπ’ αὐτοῦ διαπρεπῶς. εἰς δὲ τὸ γυμνάσιον εἰσελθὼν καὶ ἀναβὰς ἐπὶ βῆμά τι πεποιημένον, ἐκπεπληγμένων ὑπὸ δέους τῶν ἀνθρώπων καὶ προσπιπτόντων, ἀναστῆναι κελεύσας ἔφη πάσης αἰτίας τὸν δῆμον ἀφιέναι, πρῶτον μὲν διὰ τὸν κτίστην Ἀλέξανδρον· δεύτερον δὲ τῆς πόλεως θαυμάζων τὸ κάλλος καὶ τὸ μέγεθος· τρίτον δὲ Ἀρείῳ τῷ ἑταίρῳ χαριζόμενος. ταύτης δὴ τῆς τιμῆς ἔτυχε παρὰ Καίσαρος Ἄρειος, καὶ τῶν ἄλλων ἐξῃτήσατο συχνούς· ὧν ἦν καὶ Φιλόστρατος, ἀνὴρ εἰπεῖν μὲν ἐξ ἐπιδρομῆς τῶν πώποτε σοφιστῶν ἱκανώτατος, εἰσποιῶν δὲ μὴ προσηκόντως ἑαυτὸν τῇ Ἀκαδημείᾳ. διὸ καὶ Καῖσαρ αὐτοῦ βδελυττόμενος τὸν τρόπον οὐ προσίετο τὰς δεήσεις. ὁ δὲ πώγωνα πολιὸν καθεὶς καὶ φαιὸν ἱμάτιον περιβαλόμενος ἐξόπισθεν Ἀρείῳ παρηκολούθει, τοῦτον ἀεὶ τὸν στίχον ἀναφθεγγόμενος·", "st": "Ant. 80.1"}, {"sp": "N", "t": "σοφοὶ σοφοὺς σώζουσιν, ἂν ὦσιν σοφοί.", "st": "Ant. 80.1b"}, {"sp": "N", "t": "πυθόμενος δὲ Καῖσαρ, καὶ τοῦ φθόνου μᾶλλον Ἄρειον ἢ τοῦ δέους Φιλόστρατον ἀπαλλάξαι βουλόμενος, διῆκε.", "st": "Ant. 80.1c"}, {"sp": "N", "t": "τῶν δὲ Ἀντωνίου παίδων ὁ μὲν ἐκ Φουλβίας Ἄντυλλος ὑπὸ Θεοδώρου τοῦ παιδαγωγοῦ παραδοθεὶς ἀπέθανε· καὶ τὴν κεφαλὴν αὐτοῦ τῶν στρατιωτῶν ἀποτεμόντων, ὁ παιδαγωγὸς ἀφελὼν ὃν ἐφόρει περὶ τῷ τραχήλῳ πολυτιμότατον λίθον εἰς τὴν ζώνην κατέρραψεν· ἀρνησάμενος δὲ καὶ φωραθεὶς ἀνεσταυρώθη. τὰ δὲ Κλεοπάτρας παιδία φρουρούμενα μετὰ τῶν τρεφόντων ἐλευθέριον εἶχε δίαιταν. Καισαρίωνα δὲ τὸν ἐκ Καίσαρος γεγονέναι λεγόμενον ἡ μὲν μήτηρ ἐξέπεμψε μετὰ χρημάτων πολλῶν εἰς τὴν Ἰνδικὴν δι’ Αἰθιοπίας, ἕτερος δὲ παιδαγωγὸς ὅμοιος Θεοδώρῳ Ῥόδων ἀνέπεισεν ἐπανελθεῖν, ὡς Καίσαρος αὐτὸν ἐπὶ βασιλείαν καλοῦντος. βουλευομένου δὲ Καίσαρος Ἄρειον εἰπεῖν λέγουσιν·", "st": "Ant. 81.1"}, {"sp": "N", "t": "οὐκ ἀγαθὸν πολυκαισαρίη.", "st": "Ant. 81.1b"}, {"sp": "N", "t": "τοῦτον μὲν οὖν ὕστερον ἀπέκτεινε μετὰ τὴν Κλεοπάτρας τελευτήν. Ἀντώνιον δὲ πολλῶν αἰτουμένων θάψαι καὶ βασιλέων καὶ στρατηγῶν, οὐκ ἀφείλετο Κλεοπάτρας τὸ σῶμα Καῖσαρ, ἀλλὰ ἐθάπτετο ταῖς ἐκείνης χερσὶ πολυτελῶς καὶ βασιλικῶς, πᾶσιν ὡς ἐβούλετο χρῆσθαι λαβούσης. ἐκ δὲ λύπης ἅμα τοσαύτης καὶ ὀδύνης (ἀνεφλέγμηνε γὰρ αὐτῆς τὰ στέρνα τυπτομένης καὶ ἥλκωτο) πυρετῶν ἐπιλαβόντων ἠγάπησε τὴν πρόφασιν, ὡς ἀφεξομένη τροφῆς διὰ τοῦτο καὶ παραλύσουσα τοῦ ζῆν ἀκωλύτως ἑαυτήν. ἦν δὲ ἰατρὸς αὐτῇ συνήθης Ὄλυμπος, ᾧ φράσασα τἀληθὲς ἐχρῆτο συμβούλῳ καὶ συνεργῷ τῆς καθαιρέσεως, ὡς αὐτὸς ὁ Ὄλυμπος εἴρηκεν ἱστορίαν τινὰ τῶν πραγμάτων τούτων ἐκδεδωκώς. ὑπονοήσας δὲ Καῖσαρ ἀπειλὰς μέν τινας αὐτῇ καὶ φόβους περὶ τῶν τέκνων προσέβαλλεν, οἷς ἐκείνη καθάπερ μηχανήμασιν ὑπηρείπετο καὶ παρεδίδου τὸ σῶμα θεραπεύειν καὶ τρέφειν τοῖς χρῄζουσιν.", "st": "Ant. 82.1"}, {"sp": "N", "t": "ἧκε δὲ καὶ αὐτὸς ἡμέρας ὀλίγας διαλιπὼν ἐντευξόμενος αὐτῇ καὶ παρηγορήσων. ἡ δὲ ἔτυχε μὲν ἐν στιβάδι κατακειμένη ταπεινῶς, εἰσιόντι δ’ αὐτῷ μονοχίτων ἀναπηδήσασα προσπίπτει, δεινῶς μὲν ἐξηγριωμένη κεφαλὴν καὶ πρόσωπον, ὑπότρομος δὲ τῇ φωνῇ καὶ συντετηκυῖα ταῖς ὄψεσιν. ἦν δὲ πολλὰ καὶ τῆς περὶ τὸ στέρνον αἰκίας καταφανῆ· καὶ ὅλως οὐθὲν ἐδόκει τὸ σῶμα τῆς ψυχῆς ἔχειν βέλτιον. ἡ μέντοι χάρις ἐκείνη καὶ τὸ τῆς ὥρας ἰταμὸν οὐ κατέσβεστο παντάπασιν, ἀλλὰ καίπερ οὕτως διακειμένης ἔνδοθέν ποθεν ἐξέλαμπε καὶ συνεπεφαίνετο τοῖς κινήμασι τοῦ προσώπου. κελεύσαντος δὲ τοῦ Καίσαρος αὐτὴν κατακλιθῆναι καὶ πλησίον αὐτοῦ καθίσαντος, ἥψατο μέν τινος δικαιολογίας εἰς ἀνάγκην καὶ φόβον Ἀντωνίου τὰ πεπραγμένα τρεπούσης, ἐνισταμένου δὲ πρὸς ἕκαστον αὐτῇ τοῦ Καίσαρος ἐξελεγχομένη ταχὺ πρὸς οἶκτον μεθηρμόσατο καὶ δέησιν, ὡς δή τις ἂν μάλιστα τοῦ ζῆν περιεχομένη. τέλος δὲ τοῦ πλήθους τῶν χρημάτων ἀναγραφὴν ἔχουσα προσέδωκεν αὐτῷ· Σελεύκου δέ τινος τῶν ἐπιτρόπων ἐλέγχοντος ὡς ἔνια κρύπτουσαν καὶ διακλέπτουσαν, ἀναπηδήσασα καὶ τῶν τριχῶν αὐτοῦ λαβομένη πολλὰς ἐνεφόρει τῷ προσώπῳ πληγάς. τοῦ δὲ Καίσαρος μειδιῶντος καὶ καταπαύοντος αὐτήν, ἀλλ’ οὐ δεινόν, εἶπεν, ὦ Καῖσαρ, εἰ σὺ μὲν ἠξίωσας ἀφικέσθαι πρὸς ἐμὲ καὶ προσειπεῖν οὕτω πράττουσαν, οἱ δὲ δοῦλοί μου κατηγοροῦσιν εἴ τι τῶν γυναικείων ἀπεθέμην, οὐκ ἐμαυτῇ δήπουθεν, ἡ τάλαινα, κόσμον, ἀλλ’ ὅπως Ὀκταουία καὶ Λιβίᾳ τῇ σῇ μικρὰ δοῦσα δι’ ἐκείνων ἵλεώ σου τύχοιμι καὶ πραοτέρου; τούτοις ὁ Καῖσαρ ἥδετο, παντάπασιν αὐτὴν φιλοψυχεῖν οἰόμενος. εἰπὼν οὖν ὅτι καὶ ταῦτα ἐπιτρέπει καὶ τἆλλα πάσης ἐλπίδος αὐτῇ χρήσεται λαμπρότερον, ᾤχετο ἀπιών, ἐξηπατηκέναι μὲν οἰόμενος, ἐξηπατημένος δὲ μᾶλλον.", "st": "Ant. 83.1"}, {"sp": "N", "t": "ἦν δὲ Κορνήλιος Δολοβέλλας ἐπιφανὴς νεανίσκος ἐν τοῖς Καίσαρος ἑταίροις. οὗτος εἶχε πρὸς τὴν Κλεοπάτραν οὐκ ἀηδῶς· καὶ τότε χαριζόμενος αὐτῇ δεηθείσῃ κρύφα πέμψας ἐξήγγειλεν ὡς αὐτὸς μὲν ὁ Καῖσαρ ἀναζεύγνυσι πεζῇ διὰ Συρίας, ἐκείνην δὲ μετὰ τῶν τέκνων ἀποστέλλειν εἰς τρίτην ἡμέραν ἔγνωκεν. ἡ δὲ ἀκούσασα ταῦτα πρῶτον μὲν ἐδεήθη Καίσαρος ὅπως αὐτὴν ἐάσῃ χοὰς ἐπενεγκεῖν Ἀντωνίῳ· καὶ συγχωρήσαντος ἐπὶ τὸν τάφον κομισθεῖσα καὶ περιπεσοῦσα τῇ σορῷ μετὰ τῶν συνήθων γυναικῶν, ὦ φίλε Ἀντώνιε, εἶπεν, ἔθαπτον μέν σε πρώην ἔτι χερσὶν ἐλευθέραις, σπένδω δὲ νῦν αἰχμάλωτος οὖσα, καὶ φρουρουμένη μήτε κοπετοῖς μήτε θρήνοις αἰκίσασθαι τὸ δοῦλον τοῦτο σῶμα καὶ τηρούμενον ἐπὶ τοὺς κατὰ σοῦ θριάμβους. ἄλλας δὲ μὴ προσδέχου τιμὰς ἢ χοάς· ἀλλ’ αὗταί σοι τελευταῖαι Κλεοπάτρας ἀγομένης. ζῶντας μὲν γὰρ ἡμᾶς οὐθὲν ἀλλήλων διέστησε, κινδυνεύομεν δὲ τῷ θανάτῳ διαμείψασθαι τοὺς τόπους· σὺ μὲν ὁ Ῥωμαῖος ἐνταῦθα κείμενος, ἐγὼ δ’ ἡ δύστηνος ἐν Ἰταλίᾳ, τοσοῦτο τῆς σῆς μεταλαβοῦσα χώρας μόνον. ἀλλ’ εἰ δή τις τῶν ἐκεῖ θεῶν ἀλκὴ καὶ δύναμις (οἱ γὰρ ἐνταῦθα προὔδωκαν ἡμᾶς), μὴ πρόῃ ζῶσαν τὴν σεαυτοῦ γυναῖκα, μηδ’ ἐν ἐμοὶ περΐδῃς θριαμβευόμενον σεαυτόν, ἀλλ’ ἐνταῦθά με κρύψον μετὰ σεαυτοῦ καὶ σύνθαψον, ὡς ἐμοὶ μυρίων κακῶν ὄντων οὐδὲν οὕτω μέγα καὶ δεινόν ἐστιν ὡς ὁ βραχὺς οὗτος χρόνος ὃν σοῦ χωρὶς ἔζηκα.", "st": "Ant. 84.1"}, {"sp": "N", "t": "τοιαῦτα ὀλοφυραμένη καὶ στέψασα καὶ κατασπασαμένη τὴν σορὸν ἐκέλευσεν αὑτῇ λουτρὸν γενέσθαι. λουσαμένη δὲ καὶ κατακλιθεῖσα λαμπρὸν ἄριστον ἠρίστα. καί τις ἧκεν ἀπ’ ἀγροῦ κίστην τινὰ κομίζων· τῶν δὲ φυλάκων ὅ τι φέροι πυνθανομένων ἀνοίξας καὶ ἀφελὼν τὰ θρῖα σύκων ἐπίπλεων τὸ ἀγγεῖον ἔδειξε. θαυμασάντων δὲ τὸ κάλλος καὶ τὸ μέγεθος μειδιάσας παρεκάλει λαβεῖν· οἱ δὲ πιστεύσαντες ἐκέλευον εἰσενεγκεῖν. μετὰ δὲ τὸ ἄριστον ἡ Κλεοπάτρα δέλτον ἔχουσα γεγραμμένην καὶ κατασεσημασμένην ἀπέστειλε πρὸς Καίσαρα, καὶ τοὺς ἄλλους ἐκποδὼν ποιησαμένη πλὴν τῶν δυεῖν ἐκείνων γυναικῶν τὰς θύρας ἔκλεισε.", "st": "Ant. 85.1"}, {"sp": "N", "t": "Καῖσαρ δὲ λύσας τὴν δέλτον, ὡς ἐνέτυχε λιταῖς καὶ ὀλοφυρμοῖς δεομένης αὐτὴν σὺν Ἀντωνίῳ θάψαι, ταχὺ συνῆκε τὸ πεπραγμένον. καὶ πρῶτον μὲν αὐτὸς ὥρμησε βοηθεῖν, ἔπειτα τοὺς σκεψομένους κατὰ τάχος ἔπεμψεν. ἐγεγόνει δ’ ὀξὺ τὸ πάθος. δρόμῳ γὰρ ἐλθόντες καὶ τοὺς μὲν φυλάττοντας οὐδὲν ᾐσθημένους καταλαβόντες, τὰς δὲ θύρας ἀνοίξαντες, εὗρον αὐτὴν τεθνηκυῖαν ἐν χρυσῇ κατακειμένην κλίνῃ, κεκοσμημένην βασιλικῶς. τῶν δὲ γυναικῶν ἡ μὲν Εἰρὰς λεγομένη πρὸς τοῖς ποσὶν ἀπέθνησκεν, ἡ δὲ Χάρμιον ἤδη σφαλλομένη καὶ καρηβαροῦσα κατεκόσμει τὸ διάδημα τὸ περὶ τὴν κεφαλὴν αὐτῆς. εἰπόντος δέ τινος ὀργῇ· καλὰ ταῦτα, Χάρμιον· κάλλιστα μὲν οὖν, ἔφη, καὶ πρέποντα τῇ τοσούτων ἀπογόνῳ βασιλέων. πλέον δὲ οὐδὲν εἶπεν, ἀλλ’ αὐτοῦ παρὰ τὴν κλίνην ἔπεσε.", "st": "Ant. 85.3"}, {"sp": "N", "t": "λέγεται δὲ τὴν ἀσπίδα κομισθῆναι σὺν τοῖς σύκοις ἐκείνοις καὶ τοῖς θρίοις ἄνωθεν ἐπικαλυφθεῖσαν, οὕτω γὰρ τὴν Κλεοπάτραν κελεῦσαι, μηδὲ αὐτῆς ἐπισταμένης τῷ σώματι προσπεσεῖν τὸ θηρίον· ὡς δὲ ἀφαιροῦσα τῶν σύκων εἶδεν, εἰπεῖν· ἐνταῦθα ἦν ἄρα τοῦτο· καὶ τὸν βραχίονα παρασχεῖν τῷ δήγματι γυμνώσασαν. οἱ δὲ τηρεῖσθαι μὲν ἐν ὑδρίᾳ τὴν ἀσπίδα καθειργμένην φάσκουσιν, ἠλακάτῃ δέ τινι χρυσῇ τῆς Κλεοπάτρας ἐκκαλουμένης αὐτὴν καὶ διαγριαινούσης ὁρμήσασαν ἐμφῦναι τῷ βραχίονι. τὸ δὲ ἀληθὲς οὐδεὶς οἶδεν· ἐπεὶ καὶ φάρμακον αὐτὴν ἐλέχθη φορεῖν ἐν κνηστίδι κοίλῃ, τὴν δὲ κνηστίδα κρύπτειν τῇ κόμῃ· πλὴν οὔτε κηλὶς ἐξήνθησε τοῦ σώματος οὔτε ἄλλο φαρμάκου σημεῖον. οὐ μὴν οὐδὲ τὸ θηρίον ἐντὸς ὤφθη, συρμοὺς δέ τινας αὐτοῦ παρὰ θάλασσαν, ᾗ τὸ δωμάτιον ἀφεώρα καὶ θυρίδες ἦσαν, ἰδεῖν ἔφασκον. ἔνιοι δὲ καὶ τὸν βραχίονα τῆς Κλεοπάτρας ὀφθῆναι δύο νυγμὰς ἔχοντα λεπτὰς καὶ ἀμυδράς· οἷς ἔοικε πιστεῦσαι καὶ ὁ Καῖσαρ. ἐν γὰρ τῷ θριάμβῳ τῆς Κλεοπάτρας αὐτῆς εἴδωλον ἐκομίζετο καὶ τῆς ἀσπίδος ἐμπεφυκυίας. ταῦτα μὲν οὖν οὕτω λέγεται γενέσθαι.", "st": "Ant. 86.1"}, {"sp": "N", "t": "Καῖσαρ δέ, καίπερ ἀχθεσθεὶς ἐπὶ τῇ τελευτῇ τῆς γυναικός, ἐθαύμασε τὴν εὐγένειαν αὐτῆς· καὶ ταφῆναι τὸ σῶμα σὺν Ἀντωνίῳ λαμπρῶς καὶ βασιλικῶς ἐκέλευσεν. ἐντίμου δὲ καὶ τὰ γύναια κηδείας ἔτυχεν αὐτοῦ προστάξαντος. ἐτελεύτησε δὲ Κλεοπάτρα μὲν ἑνὸς δέοντα τεσσαράκοντα ἔτη βιώσασα, καὶ τούτων δύο καὶ εἴκοσι βασιλεύσασα, συνάρξασα δὲ Ἀντωνίῳ πλείω τῶν δεκατεσσάρων. Ἀντώνιον δὲ οἱ μὲν ἕξ, οἱ δὲ τρισὶ τὰ πεντήκοντα ὑπερβαλεῖν φασιν. αἱ μὲν οὖν Ἀντωνίου καθῃρέθησαν εἰκόνες, αἱ δὲ Κλεοπάτρας κατὰ χώραν ἔμειναν, Ἀρχιβίου τινὸς τῶν φίλων αὐτῆς δισχίλια τάλαντα Καίσαρι δόντος, ἵνα μὴ τὸ αὐτὸ ταῖς Ἀντωνίου πάθωσιν.", "st": "Ant. 86.4"}, {"sp": "N", "t": "Ἀντωνίου δὲ γενεὰν ἀπολιπόντος ἐκ τριῶν γυναικῶν ἑπτὰ παῖδας, ὁ πρεσβύτατος Ἄντυλλος ὑπὸ Καίσαρος ἀνῃρέθη μόνος· τοὺς λοιποὺς δὲ Ὀκταουία παραλαβοῦσα μετὰ τῶν ἐξ ἑαυτῆς ἔθρεψε. καὶ Κλεοπάτραν μὲν τὴν ἐκ Κλεοπάτρας Ἰόβᾳ τῷ χαριεστάτῳ βασιλέων συνῴκισεν, Ἀντώνιον δὲ τὸν ἐκ Φουλβίας οὕτω μέγαν ἐποίησεν ὥστε τὴν πρώτην παρὰ Καίσαρι τιμὴν Ἀγρίππου, τὴν δὲ δευτέραν τῶν Λιβίας παίδων ἐχόντων, τρίτον εἶναι καὶ δοκεῖν Ἀντώνιον. ἐκ δὲ Μαρκέλλου δυεῖν αὐτῇ θυγατέρων οὐσῶν, ἑνὸς δὲ υἱοῦ Μαρκέλλου, τοῦτον μὲν ἅμα παῖδα καὶ γαμβρὸν ἐποιήσατο Καῖσαρ, τῶν δὲ θυγατέρων Ἀγρίππᾳ τὴν ἑτέραν ἔδωκεν. ἐπεὶ δὲ Μάρκελλος ἐτελεύτησε κομιδῆ νεόγαμος καὶ Καίσαρι γαμβρὸν ἔχοντα πίστιν οὐκ εὔπορον ἦν ἐκ τῶν ἄλλων φίλων ἑλέσθαι, λόγον ἡ Ὀκταουία προσήνεγκεν ὡς χρὴ τὴν Καίσαρος θυγατέρα λαβεῖν Ἀγρίππαν, ἀφέντα τὴν ἑαυτῆς. πεισθέντος δὲ Καίσαρος πρῶτον, εἶτα Ἀγρίππου, τὴν μὲν αὑτῆς ἀπολαβοῦσα συνῴκισεν Ἀντωνίῳ, τὴν δὲ Καίσαρος Ἀγρίππας ἔγημεν. ἀπολειπομένων δὲ τῶν Ἀντωνίου καὶ Ὀκταουίας δυεῖν θυγατέρων τὴν μὲν Δομίτιος Ἀηνόβαρβος ἔλαβε, τὴν δὲ σωφροσύνῃ καὶ κάλλει περιβόητον Ἀντωνίαν Δροῦσος, ὁ Λιβίας υἱός, πρόγονος δὲ Καίσαρος. ἐκ τούτων ἐγένετο Γερμανικὸς καὶ Κλαύδιος· ὧν Κλαύδιος μὲν ὕστερον ἦρξε, τῶν δὲ Γερμανικοῦ παίδων Γάϊος μὲν ἄρξας ἐπιφανῶς οὐ πολὺν χρόνον ἀνῃρέθη μετὰ τέκνου καὶ γυναικός, Ἀγριππίνα δὲ υἱὸν ἐξ Ἀηνοβάρβου Λεύκιον Δομίτιον ἔχουσα Κλαυδίῳ Καίσαρι συνῴκησε. καὶ θέμενος τὸν υἱὸν αὐτῆς Κλαύδιος Νέρωνα Γερμανικὸν προσωνόμασεν. οὗτος ἄρξας ἐφ’ ἡμῶν ἀπέκτεινε τὴν μητέρα καὶ μικρὸν ἐδέησεν ὑπὸ ἐμπληξίας καὶ παραφροσύνης ἀνατρέψαι τὴν Ῥωμαίων ἡγεμονίαν, πέμπτος ἀπὸ Ἀντωνίου κατ’ ἀριθμὸν διαδοχῆς γενόμενος.", "st": "Ant. 87.1"}, {"sp": "HDR", "t": "Δημητρίου καὶ Ἀντωνίου σύγκρισις"}, {"sp": "N", "t": "ἐπεὶ τοίνυν μεγάλαι περὶ ἀμφοτέρους γεγόνασι μεταβολαί, πρῶτον τὰ τῆς δυνάμεως καὶ τῆς ἐπιφανείας σκοπῶμεν, ὅτι τῷ μὲν ἦν πατρῷα καὶ προκατειργασμένα, μέγιστον ἰσχύσαντος Ἀντιγόνου τῶν διαδόχων καὶ πρὸ τοῦ Δημήτριον ἐν ἡλικίᾳ γενέσθαι τὰ πλεῖστα τῆς Ἀσίας ἐπελθόντος καὶ κρατήσαντος· Ἀντώνιος δὲ χαρίεντος μὲν ἄλλως, ἀπολέμου δὲ καὶ μέγα μηδὲν εἰς δόξαν αὐτῷ καταλιπόντος γενόμενος πατρός, ἐπὶ τὴν Καίσαρος ἐτόλμησεν ἀρχήν, οὐδὲν αὐτῷ κατὰ γένος προσήκουσαν, ἐλθεῖν, καὶ τοῖς ἐκείνῳ προπεπονημένοις αὐτὸς ἑαυτὸν εἰσεποίησε διάδοχον. καὶ τοσοῦτον ἴσχυσεν, ἐκ μόνων τῶν περὶ αὐτὸν ὑπαρχόντων ὁρμώμενος, ὥστε δύο μοίρας τὰ σύμπαντα ποιησάμενος τὴν ἑτέραν ἑλέσθαι καὶ λαβεῖν τὴν ἐπιφανεστέραν, ἀπὼν δὲ αὐτὸς ὑπηρέταις τε καὶ ὑποστρατήγοις Πάρθους τε νικῆσαι πολλάκις καὶ τὰ περὶ Καύκασον ἔθνη βάρβαρα μέχρι τῆς Κασπίας ὤσασθαι θαλάσσης. μαρτύρια δὲ τοῦ μεγέθους αὐτῷ καὶ δι’ ἃ κακῶς ἀκούει. Δημητρίῳ μὲν γὰρ ὁ πατὴρ ἠγάπησε τὴν Ἀντιπάτρου Φίλαν ὡς κρείττονα συνοικῆσαι παρ’ ἡλικίαν, Ἀντωνίῳ δὲ ὁ Κλεοπάτρας γάμος ὄνειδος ἦν, γυναικὸς ὑπερβαλομένης δυνάμει καὶ λαμπρότητι πάντας πλὴν Ἀρσάκου τοὺς καθ’ αὑτὴν βασιλεῖς. ἀλλ’ οὕτως ἐποίησε μέγαν ἑαυτὸν ὥστε τοῖς ἄλλοις μειζόνων ἢ ἐβούλετο δοκεῖν ἄξιος.", "st": "Comp. Demetr.–Ant. 1.1"}, {"sp": "N", "t": "ἡ μέντοι προαίρεσις, ἀφ’ ἧς ἐκτήσαντο τὴν ἀρχήν, ἄμεμπτος ἐπὶ τοῦ Δημητρίου, κρατεῖν καὶ βασιλεύειν ἀνθρώπων εἰθισμένων κρατεῖσθαι καὶ βασιλεύεσθαι ζητοῦντος, ἡ δ’ Ἀντωνίου χαλεπὴ καὶ τυραννική, καταδουλουμένου τὸν Ῥωμαίων δῆμον ἄρτι διαφυγόντα τὴν ὑπὸ Καίσαρι μοναρχίαν. ὃ δ’ οὖν μέγιστον αὐτῷ καὶ λαμπρότατόν ἐστι τῶν εἰργασμένων, ὁ πρὸς Κάσσιον καὶ Βροῦτον πόλεμος, ἐπὶ τῷ τὴν πατρίδα καὶ τοὺς πολίτας ἀφελέσθαι τὴν ἐλευθερίαν ἐπολεμήθη. Δημήτριος δέ, καὶ πρὶν εἰς τύχας ἐλθεῖν ἀναγκαίας, ἐλευθερῶν τὴν Ἑλλάδα καὶ τῶν πόλεων ἐξελαύνων τὰς φρουρὰς διετέλεσεν, οὐχ ὥσπερ Ἀντώνιος, ὅτι τοὺς ἐλευθερώσαντας τὴν Ῥώμην ἀπέκτεινεν ἐν Μακεδονίᾳ, σεμνυνόμενος. ἓν τοίνυν ἐστὶ τῶν ἐπαινουμένων Ἀντωνίου, τὸ φιλόδωρον καὶ μεγαλόδωρον, ἐν ᾧ τοσοῦτον ὑπεραίρει Δημήτριος ὥστε χαρίσασθαι τοῖς πολεμίοις ὅσα τοῖς φίλοις οὐκ ἔδωκεν Ἀντώνιος. καίτοι ταφῆναί γε καὶ περισταλῆναι κελεύσας Βροῦτον ἐκεῖνος εὐδοκίμησεν· οὗτος δὲ καὶ τοὺς ἀποθανόντας τῶν πολεμίων πάντας ἐκήδευσε καὶ τοὺς ἁλόντας Πτολεμαίῳ μετὰ χρημάτων καὶ δωρεῶν ἀπέπεμψεν.", "st": "Comp. Demetr.–Ant. 2.1"}, {"sp": "N", "t": "ὑβρισταὶ μὲν εὐτυχοῦντες ἀμφότεροι, καὶ πρὸς τρυφὰς ἀνειμένοι καὶ ἀπολαύσεις. οὐκ ἂν εἴποι δέ τις ὡς Δημήτριον ἐν εὐπαθείαις καὶ συνουσίαις ὄντα πράξεων καιρὸς ἐξέφυγεν, ἀλλὰ τῇ περιουσίᾳ τῆς σχολῆς ἐπεισῆγε τὰς ἡδονάς, καὶ τὴν Λάμιαν ὥσπερ τὴν μυθικὴν ἀτεχνῶς παίζων καὶ νυστάζων ἐποιεῖτο διαγωγήν. ἐν δὲ ταῖς τοῦ πολέμου παρασκευαῖς οὐκ εἶχεν αὐτοῦ τὸ δόρυ κιττόν, οὐδὲ μύρων ὠδώδει τὸ κράνος, οὐδὲ γεγανωμένος καὶ ἀνθηρὸς ἐπὶ τὰς μάχας ἐκ τῆς γυναικωνίτιδος προῄει, κοιμίζων δὲ τοὺς θιάσους καὶ τὰ βακχεῖα καταπαύων ἀμφίπολος Ἄρεος ἀνιέρου, κατὰ τὸν Εὐριπίδην, ἐγίνετο, καὶ δι’ ἡδονὴν ἢ ῥαθυμίαν οὐθὲν ἁπλῶς ἔπταισεν.", "st": "Comp. Demetr.–Ant. 3.1"}, {"sp": "N", "t": "Ἀντώνιον δέ, ὥσπερ ἐν ταῖς γραφαῖς ὁρῶμεν τοῦ Ἡρακλέους τὴν Ὀμφάλην ὑφαιροῦσαν τὸ ῥόπαλον καὶ τὴν λεοντῆν ἀποδύουσαν, οὕτω πολλάκις Κλεοπάτρα παροπλίσασα καὶ καταθέλξασα συνέπεισεν ἀφέντα μεγάλας πράξεις ἐκ τῶν χειρῶν καὶ στρατείας ἀναγκαίας ἐν ταῖς περὶ Κάνωβον καὶ Ταφόσιριν ἀκταῖς ἀλύειν καὶ παίζειν μετ’ αὐτῆς. τέλος δέ, ὡς ὁ Πάρις, ἐκ τῆς μάχης ἀποδρὰς εἰς τοὺς ἐκείνης κατεδύετο κόλπους· μᾶλλον δὲ ὁ μὲν Πάρις ἡττηθεὶς ἔφυγεν εἰς τὸν θάλαμον, Ἀντώνιος δὲ Κλεοπάτραν διώκων ἔφυγε καὶ προήκατο τὴν νίκην.", "st": "Comp. Demetr.–Ant. 3.3"}, {"sp": "N", "t": "ἔτι Δημήτριος μέν, οὐ κεκωλυμένον, ἀλλ’ ἀπὸ Φιλίππου καὶ Ἀλεξάνδρου γεγονὸς ἐν ἔθει τοῖς Μακεδόνων βασιλεῦσιν, ἐγάνει γάνους πλείονας, ὥσπερ Λυσίμαχος καὶ Πτολεμαῖος, ἔσχε δὲ διὰ τιμῆς ὅσας ἔγημεν· Ἀντώνιος δὲ πρῶτον μὲν ὁμοῦ δύο γυναῖκας ἠγάγετο, πρᾶγμα μηδενὶ Ῥωμαίῳ τετολμημένον, ἔπειτα τὴν ἀστὴν καὶ δικαίως γαμηθεῖσαν ἐξήλασε τῇ ξένῃ καὶ μὴ κατὰ νόμους συνούσῃ χαριζόμενος· ὅθεν ἐκ γάμου τῷ μὲν οὐθέν, τῷ δὲ τὰ μέγιστα τῶν κακῶν ἀπήντησεν.", "st": "Comp. Demetr.–Ant. 4.1"}, {"sp": "N", "t": "ἀσέβημα μέντοι τοσοῦτον δι’ ἀσέλγειαν οὐθὲν ταῖς Ἀντωνίου πράξεσιν ὅσον ταῖς Δημητρίου πρόσεστιν. οἱ μὲν γὰρ ἱστορικοί φασι καὶ τῆς ἀκροπόλεως ὅλης εἴργεσθαι τὰς κύνας, διὰ τὸ τὴν μῖξιν ἐμφανῆ μάλιστα τοῦτο ποιεῖσθαι τὸ ζῷον· ὁ δὲ ἐν αὐτῷ τῷ Παρθενῶνι ταῖς τε πόρναις συνῆν καὶ τῶν ἀστῶν κατεπόρνευσε πολλάς· καὶ οὗ τις ἂν ἥκιστα τὰς τοιαύτας τρυφὰς καὶ ἀπολαύσεις οἴοιτο μετέχειν κακοῦ, τῆς ὠμότητος, τοῦτο ἔνεστι τῇ Δημητρίου φιληδονίᾳ, περιϊδόντος, μᾶλλον δὲ ἀναγκάσαντος, οἰκτρῶς ἀποθανεῖν τὸν κάλλιστον καὶ σωφρονέστατον Ἀθηναίων, φεύγοντα τὸ καθυβρισθῆναι. συνελόντι δὲ εἰπεῖν, Ἀντώνιος μὲν ἑαυτὸν διὰ τὴν ἀκρασίαν, Δημήτριος δὲ ἄλλους ἠδίκησε.", "st": "Comp. Demetr.–Ant. 4.2"}, {"sp": "N", "t": "πρὸς μέντοι γονεῖς ἄμεμπτον ἑαυτὸν εἰς ἅπαντα παρέσχεν ὁ Δημήτριος· Ἀντώνιος δὲ τὸν ἀδελφὸν τῆς μητρὸς ἐξέδωκεν ἐπὶ τῷ Κικέρωνα ἀποκτεῖναι, πρᾶγμα καὶ καθ’ ἑαυτὸ μιαρὸν καὶ ὠμόν, ὡς μόλις ἂν Ἀντώνιον ἐπ’ αὐτῷ συγγνώμης τυχεῖν, εἰ σωτηρίας τοῦ θείου μισθὸς ἦν ὁ Κικέρωνος θάνατος.", "st": "Comp. Demetr.–Ant. 5.1"}, {"sp": "N", "t": "ἃ τοίνυν ἐπιώρκησαν ἀμφότεροι καὶ παρεσπόνδησαν, ὁ μὲν Ἀρτάβαζον συλλαβών, ὁ δὲ Ἀλέξανδρον ἀποκτείνας, Ἀντωνίῳ μὲν ἔχει τὴν πρόφασιν ὁμολογουμένην· ἀπελείφθη γὰρ ἐν Μήδοις ὑπὸ Ἀρταβάζου καὶ προεδόθη· Δημήτριον δὲ πολλοὶ λέγουσι ψευδεῖς αἰτίας, ἐφ’ οἷς ἔδρασε, πλασάμενον κατηγορεῖν ἀδικηθέντα, οὐκ ἀδικήσαντα ἀμύνασθαι.", "st": "Comp. Demetr.–Ant. 5.2"}, {"sp": "N", "t": "πάλιν δὲ τῶν μὲν κατορθωμάτων αὐτουργὸς ὁ Δημήτριος γέγονε· καὶ τοὐναντίον ὁ Ἀντώνιος, ἐν οἷς οὐ παρῆν, καλλίστας καὶ μεγίστας διὰ τῶν στρατηγῶν ἀνῃρεῖτο νίκας.", "st": "Comp. Demetr.–Ant. 5.2b"}, {"sp": "N", "t": "ἐξέπεσον δὲ τῶν πραγμάτων ἀμφότεροι μὲν δι’ αὑτούς, οὐ μὴν ὁμοίως, ἀλλ’ ὁ μὲν ἐγκαταλειφθείς, ἀπέστησαν γὰρ αὐτοῦ Μακεδόνες, ὁ δὲ ἐγκαταλιπών, ἔφυγε γὰρ τοὺς ὑπὲρ αὐτοῦ κινδυνεύοντας· ὥστε τοῦ μὲν ἔγκλημα εἶναι τὸ δυσμενεῖς οὕτω πρὸς αὑτὸν ἀπεργάσασθαι τοὺς μαχομένους, τοῦ δὲ τὸ παρεσκευασμένην εὔνοιαν τοιαύτην καὶ πίστιν ἐγκαταλιπεῖν.", "st": "Comp. Demetr.–Ant. 6.1"}, {"sp": "N", "t": "τὸν δὲ θάνατον οὐδετέρου μὲν ἔστιν ἐπαινέσαι, ψεκτὸς δὲ ὁ Δημητρίου μᾶλλον. αἰχμάλωτός τε γὰρ ὑπέμεινε γενέσθαι, καὶ καθειρχθεὶς ἠγάπησεν ἐπικερδᾶναι τριετίαν, οἴνῳ καὶ γαστρὶ καθάπερ τὰ ζῷα χειροήθης γενόμενος. Ἀντώνιος δὲ δειλῶς μὲν καὶ οἰκτρῶς καὶ ἀτίμως, οὐ μὴν ἀλλὰ πρό γε τοῦ κύριον γενέσθαι τὸν πολέμιον τοῦ σώματος ἑαυτόν ἐξήγαγεν.", "st": "Comp. Demetr.–Ant. 6.2"}, {"sp": "HDR", "t": "Δίων"}, {"sp": "N", "t": "ἆρά γε, ὥσπερ ὁ Σιμωνίδης φησίν, ὦ Σόσσιε Σενεκίων, τοῖς Κορινθίοις οὐ μηνίειν τὸ Ἴλιον ἐπιστρατεύσασι μετὰ τῶν Ἀχαιῶν, ὅτι κἀκείνοις οἱ περὶ Γλαῦκον ἐξ ἀρχῆς Κορίνθιοι γεγονότες συνεμάχουν προθύμως, οὕτως εἰκὸς τῇ Ἀκαδημείᾳ μήτε Ῥωμαίους μήτε Ἕλληνας ἐγκαλεῖν ἴσον φερομένους ἐκ τῆς γραφῆς ταύτης, ἣ τόν τε Βρούτου περιέχει βίον καὶ τόν Δίωνος, ὧν ὁ μὲν αὐτῷ Πλάτωνι πλησιάσας, ὁ δὲ τοῖς λόγοις ἐντραφεὶς τοῖς Πλάτωνος, ὥσπερ ἐκ μιᾶς ὥρμησαν ἀμφότεροι παλαίστρας ἐπὶ τοὺς μεγίστους ἀγῶνας. καὶ τὸ μὲν ὅμοια πολλὰ καὶ ἀδελφὰ πράξαντας μαρτυρῆσαι τῷ καθηγεμόνι τῆς ἀρετῆς ὅτι δεῖ φρονήσει καὶ δικαιοσύνῃ δύναμιν ἐπὶ τὸ αὐτὸ καὶ τύχην συνελθεῖν, ἵνα κάλλος ἅμα καὶ μέγεθος αἱ πολιτικαὶ πράξεις λάβωσιν, οὐ θαυμαστόν ἐστιν. ὡς γὰρ Ἱππόμαχος ο ἀλείπτης ἔλεγε τοὺς γεγυμνασμένους παρ’ αὐτῷ καὶ κρέας ἐξ ἀγορᾶς ἰδὼν φέροντας ἐπιγνῶναι πόρρωθεν, οὕτω τόν λόγον ἐστὶν εἰκὸς τῶν πεπαιδευμένων ὁμοίως ἕπεσθαι ταῖς πράξεσιν, ἐμμέλειάν τινα καὶ ῥυθμὸν ἐπιφέροντα μετὰ τοῦ πρέποντος.", "st": "Dion 1.1"}, {"sp": "N", "t": "αἱ δὲ τύχαι, τοῖς συμπτώμασι μᾶλλον ἢ ταῖς προαιρέσεσιν οὖσαι αἱ αὐταί, συνάγουσι τῶν ἀνδρῶν τοὺς βίους εἰς ὁμοιότητα. προανῃρέθησαν γὰρ ἀμφότεροι τοῦ τέλους, εἰς ὃ προὔθεντο τὰς πράξεις ἐκ πολλῶν καὶ μεγάλων ἀγώνων καταθέσθαι μὴ δυνηθέντες. ὃ δὲ πάντων θαυμασιώτατον, ὅτι καὶ τὸ δαιμόνιον ἀμφοτέροις ὑπεδήλωσε τὴν τελευτήν, ὁμοίως ἑκατέρῳ φάσματος εἰς ὄψιν οὐκ εὐμενοῦς παραγενομένου. καίτοι λόγος τίς ἐστι τῶν ἀναιρούντων τὰ τοιαῦτα, μηδενὶ ἂν νοῦν ἔχοντι προσπεσεῖν φάντασμα δαίμονος μηδὲ εἴδωλον, Ἀλλὰ παιδάρια καὶ γύναια καὶ παραφόρους δι’ ἀσθένειαν ἀνθρώπους ἔν τινι πλάνῳ ψυχῆς ἢ δυσκρασίᾳ σώματος γενομένους δόξας ἐφέλκεσθαι κενὰς καὶ ἀλλοκότους, δαίμονα πονηρὸν ἐν αὑτοῖς τὴν δεισιδαιμονίαν ἔχοντας. εἰ δὲ Δίων καὶ Βροῦτος, ἄνδρες ἐμβριθεῖς καὶ φιλόσοφοι καὶ πρὸς οὐδὲν ἀκροσφαλεῖς οὐδ’ εὐάλωτοι πάθος, οὕτως ὑπὸ φάσματος διετέθησαν ὥστε καὶ φράσαι πρὸς ἑτέρους, οὐκ οἶδα μὴ τῶν πάνυ παλαιῶν τὸν ἀτοπώτατον ἀναγκασθῶμεν προσδέχεσθαι λόγον, ὡς τὰ φαῦλα δαιμόνια καὶ βάσκανα, προσφθονοῦντα τοῖς ἀγαθοῖς ἀνδράσι καὶ ταῖς πράξεσιν ἐνιστάμενα, ταραχὰς καὶ φόβους ἐπάγει, σείοντα καὶ σφάλλοντα τὴν ἀρετήν, ὡς μὴ διαμείναντες ἀπτῶτες ἐν τῷ καλῷ καὶ ἀκέραιοι βελτίονος ἐκείνων μοίρας μετὰ τὴν τελευτὴν τύχωσιν. ἀλλὰ ταῦτα μὲν εἰς ἄλλον ἀνακείσθω λόγον. ἐν τούτῳ δέ, δωδεκάτῳ τῶν παραλλήλων ὄντι βίων, τὸν τοῦ πρεσβυτέρου προεισαγάγωμεν.", "st": "Dion 2.1"}, {"sp": "N", "t": "Διονύσιος ὁ πρεσβύτερος εἰς τὴν ἀρχὴν καταστάς εὐθὺς ἔγημε τὴν Ἑρμοκράτους τοῦ Συρακουσίου θυγατέρα, ταύτην, οὔπω τῆς τυραννίδος ἱδρυμένης βεβαίως, ἀποστάντες οἱ Συρακούσιοι δεινὰς καὶ παρανόμους ὕβρεις εἰς τὸ σῶμα καθύβρισαν, ἐφ’ αἷς προήκατο τὸν βίον ἑκουσίως. Διονύσιος δὲ τὴν ἀρχὴν ἀναλαβὼν καὶ κρατυνάμενος αὖθις ἄγεται δύο γυναῖκας ἅμα, τὴν μὲν ἐκ Λοκρῶν ὄνομα Δωρίδα, τὴν δὲ ἐπιχώριον Ἀριστομάχην, θυγατέρα Ἱππαρίνου, πρωτεύσαντος ἀνδρὸς Συρακουσίων καὶ Διονυσίῳ συνάρξαντος ὅτε πρῶτον αὐτοκράτωρ ἐπὶ τὸν πόλεμον ᾑρέθη στρατηγός. λέγεται δ’ ἡμέρᾳ μὲν ἀμφοτέρας ἀγαγέσθαι μιᾷ καὶ μηδενὶ γενέσθαι φανερὸς ἀνθρώπων ὁποτέρᾳ προτέρᾳ συνέλθοι, τὸν δὲ ἄλλον χρόνον ἴσον νέμων ἑαυτὸν διατελεῖν ἑκατέρᾳ, κοινῇ μὲν εἰθισμένων δειπνεῖν μετ’ αὐτοῦ, παρὰ νύκτα δὲ ἐν μέρει συναναπαυομένων. καίτοι τῶν Συρακουσίων ἐβούλετο τὸ πλῆθος τὴν ἐγγενῆ πλέον ἔχειν τῆς ξένης· ἀλλὰ ἐκείνῃ προτέρᾳ ὑπῆρχε τεκούσῃ τὸν πρεσβεύοντα τῆς Διονυσίου γενεᾶς υἱὸν αὐτῇ βοηθεῖν πρὸς τὸ γένος. ἡ δὲ Ἀριστομάχη πολὺν χρόνον ἄπαις συνῴκει τῷ Διονυσίῳ καίπερ σπουδάζοντι περὶ τὴν ἐκ ταύτης τέκνωσιν, ὅς γε καὶ τὴν μητέρα τῆς Λοκρίδος αἰτιασάμενος καταφαρμακεύειν τὴν Ἀριστομάχην ἀπέκτεινε.", "st": "Dion 3.1"}, {"sp": "N", "t": "ταύτης ἀδελφὸς ὢν ὁ Δίων ἐν ἀρχῇ μὲν εἶχε τιμὴν ἀπὸ τῆς ἀδελφῆς, ὕστερον δὲ τοῦ φρονεῖν διδοὺς πεῖραν, ἤδη καθ’ ἑαυτὸν ἠγαπᾶτο παρὰ τῷ τυράννῳ. καὶ πρὸς ἅπασι τοῖς ἄλλοις εἴρητο τοῖς ταμίαις ὅ τι ἂν αἰτῇ Δίων διδόναι, δόντας δὲ πρὸς αὐτὸν αὐθημερὸν φράζειν. ὢν δὲ καὶ πρότερον ὑψηλὸς τῷ ἤθει καὶ μεγαλόφρων καὶ ἀνδρώδης, ἔτι μᾶλλον ἐπέδωκε πρὸς ταῦτα θείᾳ τινὶ τύχῃ Πλάτωνος εἰς Σικελίαν παραβαλόντος, κατ’ οὐδένα λογισμὸν ἀνθρώπινον· ἀλλὰ δαίμων τις, ὡς ἔοικε, πόρρωθεν ἀρχὴν ἐλευθερίας βαλλόμενος Συρακουσίοις, καὶ τυραννίδος κατάλυσιν μηχανώμενος, ἐκόμισεν ἐξ Ἰταλίας εἰς Συρακούσας Πλάτωνα καὶ Δίωνα συνήγαγεν εἰς λόγους αὐτῷ, νέον μὲν ὄντα κομιδῇ, πολὺ δὲ εὐμαθέστατον ἁπάντων τῶν Πλάτωνι συγγεγονότων καὶ ὀξύτατον ὑπακοῦσαι πρὸς ἀρετήν, ὡς αὐτὸς γέγραφε Πλάτων, καὶ τὰ πράγματα μαρτυρεῖ. τραφεὶς γὰρ ἐν ἤθεσιν ὑπὸ τυράννῳ ταπεινοῖς, καὶ βίου μὲν ἀνίσου καὶ καταφόβου, θεραπείας δὲ νεοπλούτου καὶ τρυφῆς ἀπειροκάλου καὶ διαίτης ἐν ἡδοναῖς καὶ πλεονεξίαις τιθεμένης τὸ καλὸν ἐθὰς καὶ μεστὸς γενόμενος, ὡς πρῶτον ἐγεύσατο λόγου καὶ φιλοσοφίας ἡγεμονικῆς πρὸς ἀρετήν, ἀνεφλέχθη τὴν ψυχὴν ταχύ, καὶ τῇ περὶ αὐτὸν εὐπειθείᾳ τῶν καλῶν ἀκάκως πάνυ καὶ νεωτερικῶς προσδοκήσας ὑπὸ τῶν αὐτῶν λόγων ὅμοια πείσεσθαι Διονύσιον, ἐσπούδασε καὶ διεπράξατο ποιησάμενος σχολὴν αὐτὸν ἐντυχεῖν Πλάτωνι καὶ ἀκοῦσαι.", "st": "Dion 4.1"}, {"sp": "N", "t": "γενομένης δὲ τῆς συνουσίας αὐτοῖς τὸ μὲν ὅλον περὶ ἀνδρὸς ἀρετῆς, πλείστων δὲ περὶ ἀνδρείας διαπορηθέντων, ὡς πάντας μᾶλλον ὁ Πλάτων ἢ τοὺς τυράννους ἀπέφαινεν ἀνδρείους, ἐκ δὲ τούτου τραπόμενος περὶ δικαιοσύνης ἐδίδασκεν ὡς μακάριος μὲν ὁ τῶν δικαίων, ἄθλιος δὲ ὁ τῶν ἀδίκων βίος, οὔτε τοὺς λόγους ἔφερεν ὁ τύραννος ὥσπερ ἐξελεγχόμενος, ἤχθετό τε τοῖς παροῦσι θαυμαστῶς ἀποδεχομένοις τὸν ἄνδρα καὶ κηλουμένοις ὑπὸ τῶν λεγομένων. τέλος δὲ θυμωθεὶς καὶ παροξυνθείς ἠρώτησεν αὐτόν ὅ τι δὴ βουλόμενος εἰς Σικελίαν παραγένοιτο. τοῦ δὲ φήσαντος ἀγαθὸν ἄνδρα ζητεῖν, ὑπολαβὼν ἐκεῖνος, ἀλλὰ νὴ τοὺς θεοὺς, εἶπε, καὶ φαίνῃ μήπω τοιοῦτον εὑρηκώς. οἱ μὲν οὖν περὶ τὸν Δίωνα τοῦτο τέλος ᾤοντο τῆς ὀργῆς γεγονέναι, καὶ τὸν Πλάτωνα σπεύδοντα συνεξέπεμπον ἐπὶ τριήρους, ἣ Πόλλιν ἐκόμιζεν εἰς τὴν Ἑλλάδα τὸν Σπαρτιάτην ὁ δὲ Διονύσιος κρύφα τοῦ Πόλλιδος ἐποιήσατο δέησιν μάλιστα μὲν ἀποκτεῖναι τὸν ἄνδρα κατὰ πλοῦν, εἰ δὲ μή, πάντως ἀποδόσθαι· βλαβήσεσθαι γὰρ οὐδέν, ἀλλ’ εὐδαιμονήσειν ὁμοίως, δίκαιον ὄντα, κἂν δοῦλος γένηται. διὸ καὶ λέγεται Πόλλις εἰς Αἴγιναν φέρων ἀποδόσθαι Πλάτωνα, πολέμου πρὸς Ἀθηναίους ὄντος αὐτοῖς καὶ ψηφίσματος ὅπως ὁ ληφθεὶς Ἀθηναίων ἐν Αἰγίνῃ πιπράσκηται.", "st": "Dion 5.1"}, {"sp": "N", "t": "οὐ μὴν ὅ γε Δίων ἔλαττον εἶχε παρὰ τῷ Διονυσίῳ τιμῆς ἢ πίστεως, ἀλλὰ πρεσβείας τε τὰς μεγίστας διῴκει καὶ πεμπόμενος πρὸς Καρχηδονίους ἐθαυμάσθη διαφερόντως· καὶ τὴν παρρησίαν ἔφερεν αὐτοῦ μόνου σχεδόν ἀδεῶς λέγοντος τὸ παριστάμενον, ὡς καὶ τὴν περὶ Γέλωνος ἐπίπληξιν. χλευαζομένης γὰρ, ὡς ἔοικε, τῆς Γέλωνος ἀρχῆς, αὐτόν τε τὸν Γέλωνα τοῦ Διονυσίου γέλωτα τῆς Σικελίας γεγονέναι φήσαντος, οἱ μὲν ἄλλοι τὸ σκῶμμα προσεποιοῦντο θαυμάζειν, ὁ δὲ Δίων δυσχεράνας, καὶ μὴν, ἔφη, σὺ τυραννεῖς διὰ Γέλωνα πιστευθείς· διὰ σὲ δὲ οὐδεὶς ἕτερος πιστευθήσεται. τῷ γὰρ ὄντι φαίνεται κάλλιστον μὲν Γέλων ἐπιδειξάμενος θέαμα μοναρχουμένην πόλιν, αἴσχιστον δὲ Διονύσιος.", "st": "Dion 5.8"}, {"sp": "N", "t": "ὄντων δὲ Διονυσίῳ παίδων τριῶν μὲν ἐκ τῆς Λοκρίδος, τεττάρων δὲ ἐξ Ἀριστομάχης, ὧν δύο ἦσαν θυγατέρες, Σωφροσύνη καὶ Ἀρέτη, Σωφροσύνη μὲν Διονυσίῳ τῷ υἱῷ συνῴκησεν, Ἀρέτη δὲ Θεαρίδῃ τῷ ἀδελφῷ. τελευτήσαντος δὲ τοῦ ἀδελφοῦ Θεαρίδου Δίων ἔλαβε τὴν Ἀρετήν ἀδελφιδῆν οὖσαν. ἐπεὶ δὲ νοσῶν ἔδοξεν ὁ Διονύσιος ἀβιώτως ἔχειν, ἐπεχείρησεν αὐτῷ διαλέγεσθαι περὶ τῶν ἐκ τῆς Ἀριστομάχης τέκνων ὁ Δίων, οἱ δ’ ἰατροὶ τῷ μέλλοντι τὴν ἀρχὴν διαδέχεσθαι χαριζόμενοι καιρὸν οὐ παρέσχον· ὡς δὲ Τίμαιός φησι, καὶ φάρμακον ὑπνωτικὸν αἰτοῦντι δόντες ἀφείλοντο τὴν αἴσθησιν αὐτοῦ, θανάτῳ συνάψαντες τὸν ὕπνον.", "st": "Dion 6.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ συλλόγου πρώτου τῶν φίλων γενομένου παρὰ τὸν νέον Διονύσιον οὕτω διελέχθη περὶ τῶν συμφερόντων πρὸς τὸν καιρὸν ὁ Δίων ὥστε τοὺς ἄλλους ἅπαντας τῇ μὲν φρονήσει παῖδας ἀποδεῖξαι, τῇ δὲ παρρησίᾳ δούλους τῆς τυραννίδος ἀγεννῶς καὶ περιφόβως τὰ πολλὰ πρὸς χάριν τῷ μειρακίῳ συμβουλεύοντας, μάλιστα δὲ αὐτοὺς ἐξέπληξε τὸν ἀπὸ Καρχηδόνος κίνδυνον ἐπικρεμάμενον τῇ ἀρχῇ δεδοικότας, ὑποσχόμενος, εἰ μὲν εἰρήνης δέοιτο Διονύσιος, πλεύσας εὐθὺς εἰς Λιβύην ὡς ἄριστα διαθήσεσθαι τὸν πόλεμον, εἰ δὲ πολεμεῖν προθυμοῖτο, θρέψειν αὐτὸς ἰδίοις τέλεσι καὶ παρέξειν εἰς τὸν πόλεμον αὐτῷ πεντήκοντα τριήρεις εὖ πλεούσας.", "st": "Dion 6.4"}, {"sp": "N", "t": "ὁ μὲν οὖν Διονύσιος ὑπερφυῶς τὴν μεγαλοψυχίαν ἐθαύμασε καὶ τὴν προθυμίαν ἠγάπησεν· οἱ δὲ ἐλέγχεσθαι τῇ λαμπρότητι καὶ ταπεινοῦσθαι τῇ δυνάμει τοῦ Δίωνος οἰόμενοι, ταύτην εὐθὺς ἀρχὴν λαβόντες, οὐδεμιᾶς ἐφείδοντο φωνῆς ᾗ τὸ μειράκιον ἐξαγριαίνειν ἔμελλον πρὸς αὐτόν, ὡς ὑπερχόμενον διὰ τῆς θαλάττης τυραννίδα καὶ περισπῶντα ταῖς ναυσὶ τὴν δύναμιν εἰς τοὺς Ἀριστομάχης παῖδας, ἀδελφιδοῦς ὄντας αὐτῷ. φανερώταται δὲ καὶ μέγισται τῶν εἰς φθόνον καὶ μῖσος αἰτιῶν ὑπῆρχον ἡ τοῦ βίου διαφορὰ καὶ τὸ τῆς διαίτης ἄμικτον. οἱ μὲν γὰρ, εὐθὺς ἐξ ἀρχῆς νέου τυράννου καὶ τεθραμμένου φαύλως ὁμιλίαν καὶ συνήθειαν ἡδοναῖς καὶ κολακείαις καταλαμβάνοντες, ἀεί τινας ἔρωτας καὶ διατριβὰς ἐμηχανῶντο ῥεμβώδεις περὶ πότους καὶ γυναῖκας, καὶ παιδιὰς ἑτέρας ἀσχήμονας, ὑφ’ ὧν ἡ τυραννὶς, ὥσπερ σίδηρος, μαλασσομένη, τοῖς μὲν ἀρχομένοις ἐφάνη φιλάνθρωπος, καὶ τὸ λίαν ἀπάνθρωπον ὑπανῆκεν, οὐκ ἐπιεικείᾳ τινὶ μᾶλλον ἢ ῥᾳθυμίᾳ τοῦ κρατοῦντος ἀμβλυνομένη. ἐκ δὲ τούτου προϊοῦσα καὶ νεμομένη κατὰ μικρὸν ἡ περὶ τὸ μειράκιον ἄνεσις τοὺς ἀδαμαντίνους δεσμοὺς ἐκείνους, οἷς ὁ πρεσβύτερος Διονύσιος ἔφη δεδεμένην ἀπολείπειν τὴν μοναρχίαν, ἐξέτηξε καὶ διέφθειρεν. ἡμέρας γὰρ, ὥς φασιν, ἐνενήκοντα συνεχῶς ἔπινεν ἀρξάμενος, καὶ τὴν αὐλὴν ἐν τῷ χρόνῳ τούτῳ σπουδαίοις ἀνδράσι καὶ λόγοις ἄβατον καὶ ἀνείσοδον οὖσαν μέθαι καὶ σκώμματα καὶ ψαλμοὶ καὶ ὀρχήσεις καὶ βωμολοχίαι κατεῖχον.", "st": "Dion 7.1"}, {"sp": "N", "t": "ἦν οὖν, ὡς εἰκὸς, ὁ Δίων ἐπαχθής εἰς οὐδὲν ἡδὺ καὶ νεωτερικὸν ἐνδιδοὺς ἑαυτόν, διὸ καὶ πιθανὰ κακιῶν προσρήματα ταῖς ἀρεταῖς ἐπιφέροντες αὐτοῦ διέβαλλον, ὑπεροψίαν τὴν σεμνότητα καὶ τὴν παρρησίαν αὐθάδειαν ἀποκαλοῦντες· καὶ νουθετῶν κατηγορεῖν ἐδόκει καὶ μὴ συνεξαμαρτάνων καταφρονεῖν. ἀμέλει δὲ καὶ φύσει τινὰ τὸ ἦθος ὄγκον εἶχεν αὐτοῦ καὶ τραχύτητα δυσπρόσοδον ἐντεύξει καὶ δυσξύμβολον. οὐ γὰρ μόνον ἀνδρὶ νέῳ καὶ διατεθρυμμένῳ τὰ ὦτα κολακείαις ἄχαρις ἦν συγγενέσθαι καὶ προσάντης, πολλοὶ δὲ καὶ τῶν πάνυ χρωμένων αὐτῷ καὶ τὴν ἁπλότητα καὶ τὸ γενναῖον ἀγαπώντων τοῦ τρόπου κατεμέμφοντο τῆς ὁμιλίας, ὡς ἀγροικότερον καὶ βαρύτερον πολιτικῶν χρειῶν τοῖς δεομένοις συναλλάσσοντα. περὶ ὧν καὶ Πλάτων ὕστερον ὥσπερ ἀποθεσπίζων ἔγραψε πρὸς αὐτόν ἐξευλαβεῖσθαι τὴν αὐθάδειαν ὡς ἐρημίᾳ συνοικοῦσαν. οὐ μὴν ἀλλὰ τότε πλείστου δοκῶν ἄξιος ὑπάρχειν διὰ τὰ πράγματα καὶ μόνος ἢ μάλιστα τὴν τυραννίδα σαλεύουσαν ἀνορθοῦν καὶ διαφυλάττειν, ἐγίνωσκεν οὐ πρὸς χάριν, ἀλλ’ ἄκοντος ὑπὸ χρείας τοῦ τυράννου πρῶτος ὢν καὶ μέγιστος.", "st": "Dion 8.1"}, {"sp": "N", "t": "αἰτίαν δέ τούτου τὴν ἀπαιδευσίαν εἶναι νομίζων ἐμβαλεῖν αὐτὸν εἰς διατριβὰς ἐλευθερίους ἐφιλοτιμεῖτο καὶ γεῦσαι λόγων καὶ μαθημάτων ἠθοποιῶν, ὡς ἀρετήν τε παύσαιτο δεδιὼς καὶ τοῖς καλοῖς χαίρειν ἐθισθείη. φύσει γὰρ οὐ γεγόνει τῶν φαυλοτάτων τυράννων ὁ Διονύσιος, ἀλλ’ ὁ πατὴρ, δεδοικώς μὴ φρονήματος μεταλαβὼν καὶ συγγενόμενος νοῦν ἔχουσιν ἀνθρώποις ἐπιβουλεύσειεν αὐτῷ καὶ παρέλοιτο τὴν ἀρχήν, ἐφρούρει κατάκλειστον οἴκοι, δι’ ἐρημίαν ὁμιλίας ἑτέρας καὶ ἀπειρίᾳ πραγμάτων, ὥς φασιν, ἁμάξια καὶ λυχνίας καὶ δίφρους ξυλίνους καὶ τραπέζας τεκταινόμενον. οὕτω γὰρ ἦν ἄπιστος καὶ πρὸς ἅπαντας ἀνθρώπους ὕποπτος καὶ προβεβλημένος διὰ φόβον ὁ πρεσβύτερος Διονύσιος ὥστε μηδὲ τῆς κεφαλῆς τὰς τρίχας ἀφελεῖν κουρικαῖς μαχαίραις, ἀλλὰ τῶν πλαστῶν τις ἐπιφοιτῶν ἄνθρακι τὴν κόμην περιέκαιεν. εἰσῄει δὲ πρὸς αὐτὸν εἰς τὸ δωμάτιον οὔτε ἀδελφὸς οὔθ’ υἱὸς ὡς ἔτυχεν ἠμφιεσμένος, ἀλλ’ ἔδει πρὶν εἰσελθεῖν ἀποδύντα τὴν ἑαυτοῦ στολὴν ἕκαστον ἑτέραν ἀναλαβεῖν, ὁραθέντα γυμνὸν ὑπὸ τῶν φυλαττόντων. ἐπεὶ δὲ Λεπτίνης ὁ ἀδελφὸς αὐτῷ ποτε χωρίου φύσιν ἐξηγούμενος λαβὼν λόγχην παρά τινος τῶν δορυφόρων ὑπέγραψε τὸν τόπον, ἐκείνῳ μὲν ἰσχυρῶς ἐχαλέπηνε, τὸν δέ δόντα τὴν λόγχην ἀπέκτεινεν. ἔλεγε δέ τοὺς φίλους φυλάττεσθαι νοῦν ἔχοντας εἰδὼς καὶ βουλομένους μᾶλλον τυραννεῖν ἢ τυραννεῖσθαι. καὶ Μαρσύαν δέ τινα τῶν προηγμένων ὑπ’ αὐτοῦ καὶ τεταγμένων ἐφ’ ἡγεμονίας ἀνεῖλε δόξαντα κατὰ, τοὺς ὕπνους σφάττειν αὐτόν, ὡς ἀπ’ ἐννοίας μεθημερινῆς καὶ διαλογισμοῦ τῆς ὄψεως ταύτης εἰς τὸν ὕπνον αὐτῷ παραγενομένης. ὁ μὲν δὴ Πλάτωνι θυμωθείς ὅτι μὴ πάντων αὐτὸν ἀνθρώπων ἀνδρειότατον ὄντα ἀπέφηνεν, οὕτω περίφοβον καὶ τοσούτων ὑπὸ δειλίας κακῶν μεστὴν εἶχε τὴν ψυχήν.", "st": "Dion 9.1"}, {"sp": "N", "t": "τὸν δ’ υἱὸν αὐτοῦ, καθάπερ εἴρηται, διαλελωβημένον ἀπαιδευσίᾳ καὶ συντετριμμένον τὸ ἦθος ὁ Δίων ὁρῶν παρεκάλει πρὸς παιδείαν τραπέσθαι καὶ δεηθῆναι τοῦ πρώτου τῶν φιλοσόφων πᾶσαν δέησιν ἐλθεῖν εἰς Σικελίαν· ἐλθόντι δὲ παρασχεῖν αὑτόν, ὅπως διακοσμηθεὶς τὸ ἦθος εἰς ἀρετῆς λόγον, καὶ πρὸς τὸ θειότατον ἀφομοιωθεὶς παράδειγμα τῶν ὄντων καὶ κάλλιστον, ᾧ τὸ πᾶν ἡγουμένῳ πειθόμενον ἐξ ἀκοσμίας κόσμος ἐστί, πολλὴν μὲν εὐδαιμονίαν ἑαυτῷ μηχανήσεται, πολλὴν δὲ τοῖς πολίταις, ὅσα νῦν ἐν ἀθυμίᾳ διοικοῦσι πρὸς ἀνάγκην τῆς ἀρχῆς, ταῦτα σωφροσύνῃ καὶ δικαιοσύνῃ μετ’ εὐμενείας πατρονομούμενα παρασχών καὶ γενόμενος βασιλεὺς ἐκ τυράννου. τοὺς γὰρ ἀδαμαντίνους δεσμοὺς οὐχ, ὥσπερ ὁ πατὴρ ἔλεγεν αὐτοῦ, φόβον καὶ βίαν καὶ νεῶν πλῆθος εἶναι καὶ βαρβάρων μυρίανδρον φυλακήν, εὔνοιαν δὲ καὶ προθυμίαν καὶ χάριν ἐγγενομένην ὑπ’ ἀρετῆς καὶ δικαιοσύνης, ἅ, καίπερ ὄντα μαλακώτερα τῶν συντόνων καὶ σκληρῶν ἐκείνων, ἰσχυρότερα πρὸς διαμονὴν ἡγεμονίας ὑπάρχειν. χωρὶς δὲ τούτων ἀφιλότιμον εἶναι καὶ ἄζηλον τὸν ἄρχοντα, τῷ μὲν σώματι περιττῶς ἀμπεχόμενον καὶ τῇ περὶ τὴν οἴκησιν ἁβρότητι καὶ κατασκευῇ λαμπρυνόμενον, ὁμιλίᾳ δὲ καὶ λόγῳ μηδὲν ὄντα τοῦ προστυχόντος σεμνότερον, μηδὲ τῆς ψυχῆς τὸ βασίλειον ἀξιοῦντα κεκοσμημένον ἔχειν βασιλικῶς καὶ πρεπόντως.", "st": "Dion 10.1"}, {"sp": "N", "t": "ταῦτα πολλάκις τοῦ Δίωνος παραινοῦντος, καὶ τῶν λόγων τοῦ Πλάτωνος ἔστιν οὕστινας ὑποσπείροντος, ἔσχεν ἔρως τὸν Διονύσιον ὀξὺς καὶ περιμανὴς τῶν τε λόγων καὶ τῆς συνουσίας τοῦ Πλάτωνος. εὐθὺς οὖν Ἀθήναζε πολλὰ μὲν ἐφοίτα γράμματα παρὰ τοῦ Διονυσίου, πολλαὶ δ’ ἐπισκήψεις παρὰ τοῦ Δίωνος, ἄλλαι δ’ ἐξ Ἰταλίας παρὰ τῶν Πυθαγορικῶν, διακελευομένων παραγενέσθαι καὶ νέας ψυχῆς ἐξουσίᾳ μεγάλῃ καὶ δυνάμει περιφερομένης ἐπιλαβέσθαι καὶ κατασχεῖν ἐμβριθεστέροις λογισμοῖς. Πλάτων μὲν οὖν, ὥς φησιν αὐτός, ἑαυτὸν αἰσχυνθεὶς μάλιστα, μὴ δόξειε λόγος εἶναί μόνον, ἔργου δ’ ἑκὼν οὐδενὸς ἂν ἅψασθαι, καὶ προσδοκήσας δι’ ἑνὸς ἀνδρὸς ὥσπερ ἡγεμονικοῦ μέρους ἐκκαθαρθέντος ὅλην ἰατρεύσειν Σικελίαν νοσοῦσαν, ὑπήκουσεν.", "st": "Dion 11.1"}, {"sp": "N", "t": "οἱ δὲ τῷ Δίωνι πολεμοῦντες φοβούμενοι τὴν τοῦ Διονυσίου μεταβολήν ἔπεισαν αὐτὸν ἀπὸ τῆς φυγῆς μεταπέμπεσθαι Φίλιστον, ἄνδρα καὶ πεπαιδευμένον περὶ λόγους καὶ τυραννικῶν ἠθῶν ἐμπειρότατον, ὡς ἀντίταγμα πρὸς Πλάτωνα καὶ φιλοσοφίαν ἐκεῖνον ἕξοντες. ὁ γὰρ δὴ Φίλιστος ἐξ ἀρχῆς τε τῇ τυραννίδι καθισταμένῃ προθυμότατον ἑαυτὸν παρέσχε, καὶ τὴν ἄκραν διεφύλαξε φρουραρχῶν ἐπὶ πολὺν χρόνον. ἦν δὲ λόγος ὡς καὶ τῇ μητρὶ πλησιάζοι τοῦ πρεσβυτέρου Διονυσίου, τοῦ τυράννου μὴ παντάπασιν ἀγνοοῦντος. ἐπεὶ δὲ Λεπτίνης, ἐκ γυναικὸς ἣν διαφθείρας ἑτέρῳ συνοικοῦσαν ἔσχε γενομένων αὐτῷ δυεῖν θυγατέρων, τὴν ἑτέραν ἔδωκε Φιλίστῳ μηδὲ φράσας πρὸς Διονύσιον, ὀργισθεὶς ἐκεῖνος τὴν μὲν γυναῖκα τοῦ Λεπτίνου δήσας ἐν πέδαις καθεῖρξε, τὸν δὲ Φίλιστον ἐξήλασε Σικελίας, φυγόντα παρὰ ξένους τινὰς εἰς τὸν Ἀδρίαν, ὅπου καὶ δοκεῖ τὰ πλεῖστα συνθεῖναι τῆς ἱστορίας σχολάζων. οὐ γὰρ ἐπανῆλθε τοῦ πρεσβυτέρου ζῶντος, ἀλλὰ μετὰ τὴν ἐκείνου τελευτήν, ὥσπερ εἴρηται, κατήγαγεν αὐτὸν ὁ πρὸς Δίωνα τῶν ἄλλων φθόνος, ὡς αὐτοῖς τε μᾶλλον ἐπιτήδειον ὄντα καὶ τῇ τυραννίδι βεβαιότερον.", "st": "Dion 11.4"}, {"sp": "N", "t": "οὗτος μὲν οὖν εὐθὺς κατελθὼν διεπεφύκει τῆς τυραννίδος τῷ δὲ Δίωνι καὶ παρ’ ἄλλων ἐτύγχανον οὖσαι διαβολαὶ καὶ κατηγορίαι πρός τὸν τύραννον, ὡς διειλεγμένῳ περὶ καταλύσεως τῆς ἀρχῆς πρός τε Θεοδότην καὶ πρός Ἡρακλείδην. ἤλπιζε μὲν γὰρ, ὡς ἔοικε, διὰ Πλάτωνος παραγενομένου τὸ δεσποτικὸν καὶ λίαν ἄκρατον ἀφελὼν τῆς τυραννίδος ἐμμελῆ τινα καὶ νόμιμον ἄρχοντα τὸν Διονύσιον καταστήσειν· εἰ δὲ ἀντιβαίνοι καὶ μὴ μαλάσσοιτο, καταλύσας ἐκεῖνον ἐγνώκει τὴν πολιτείαν ἀποδιδόναι Συρακουσίοις, οὐκ ἐπαινῶν μὲν δημοκρατίαν, πάντως δὲ βελτίω τυραννίδος ἡγούμενος τοῖς διαμαρτάνουσιν ὑγιαινούσης ἀριστοκρατίας.", "st": "Dion 12.1"}, {"sp": "N", "t": "ἐν τοιαύτῃ δὲ καταστάσει τῶν πραγμάτων ὄντων Πλάτων εἰς Σικελίαν ἀφικόμενος περὶ μὲν τὰς πρώτας ἀπαντήσεις θαυμαστῆς ἐτύγχανε φιλοφροσύνης καὶ τιμῆς. καὶ γὰρ ἅρμα τῶν βασιλικῶν αὐτῷ παρέστη κεκοσμημένον διαπρεπῶς ἀποβάντι τῆς τριήρους, καὶ θυσίαν ἔθυσεν ὁ τύραννος ὡς εὐτυχήματος μεγάλου τῇ ἀρχῇ προσγεγονότος. αἰδὼς δὲ συμποσίων καὶ σχηματισμὸς αὐλῆς καὶ πρᾳότης αὐτοῦ τοῦ τυράννου περὶ ἕκαστα τῶν χρηματιζομένων θαυμαστὰς ἐνέδωκεν ἐλπίδας μεταβολῆς τοῖς πολίταις. φορὰ δέ τις ἦν ἐπὶ λόγους καὶ φιλοσοφίαν ἁπάντων, καὶ τὸ τυραννεῖον, ὥς φασι, κονιορτὸς ὑπὸ πλήθους τῶν γεωμετρούντων κατεῖχεν. ἡμερῶν δὲ ὀλίγων διαγενομένων θυσία μὲν ἦν πάτριος ἐν τοῖς τυραννείοις τοῦ δὲ κήρυκος, ὥσπερ εἰώθει, κατευξαμένου διαμένειν τὴν τυραννίδα ἀσάλευτον πολλοὺς χρόνους, ὁ Διονύσιος λέγεται παρεστὼς, οὐ παύσῃ, φάναι, καταρώμενος ἡμῖν; τοῦτο κομιδῇ τοὺς περὶ τὸν Φίλιστον ἐλύπησεν, ἄμαχόν τινα τοῦ Πλάτωνος ἡγουμένους ἔσεσθαι χρόνῳ καὶ συνηθείᾳ τὴν δύναμιν, εἰ νῦν ἐκ συνουσίας ὀλίγης ἠλλοίωκεν οὕτω καὶ μεταβέβληκε τὴν γνώμην τὸ μειράκιον.", "st": "Dion 13.1"}, {"sp": "N", "t": "οὐκέτ’ οὖν καθ’ ἕνα καὶ λαθραίως, ἀλλὰ πάντες ἀναφανδὸν ἐλοιδόρουν τὸν Δίωνα, λέγοντες ὡς οὐ λέληθε κατεπᾴδων καὶ καταφαρμάσσων τῷ Πλάτωνος λόγῳ Διονύσιον, ὅπως ἀφέντος ἑκουσίως αὐτοῦ καὶ προεμένου τὴν ἀρχὴν ὑπολαβὼν εἰς τοὺς Ἀριστομάχης περιστήσῃ παῖδας, ὧν θεῖός ἐστιν. ἔνιοι δὲ προσεποιοῦντο δυσχεραίνειν, εἰ πρότερον μὲν Ἀθηναῖοι ναυτικαῖς καὶ πεζικαῖς δυνάμεσι μεγάλαις δεῦρο πλεύσαντες ἀπώλοντο καὶ διεφθάρησαν πρότερον ἢ λαβεῖν Συρακούσας, νυνὶ δὲ δι’ ἑνὸς σοφιστοῦ καταλύουσι τὴν Διονυσίου τυραννίδα, συμπείσαντες αὐτὸν ἐκ τῶν μυρίων δορυφόρων ἀποδράντα, καὶ καταλιπόντα τὰς τετρακοσίας τριήρεις καὶ τοὺς μυρίους ἱππεῖς καὶ τοὺς πολλάκις τοσούτους ὁπλίτας, ἐν Ἀκαδημείᾳ τὸ σιωπώμενον ἀγαθὸν ζητεῖν καὶ διὰ γεωμετρίας εὐδαίμονα γενέσθαι, τὴν ἐν ἀρχῇ καὶ χρήμασι καὶ τρυφαῖς εὐδαιμονίαν Δίωνι καὶ τοῖς Δίωνος ἀδελφιδοῖς προέμενον.", "st": "Dion 14.1"}, {"sp": "N", "t": "ἐκ τούτων ὑποψίας πρῶτον, εἶτα καὶ φανερωτέρας ὀργῆς καὶ διαφορᾶς γενομένης, ἐκομίσθη τις ἐπιστολὴ κρύφα πρὸς Διονύσιον, ἣν ἐγεγράφει Δίων πρὸς τοὺς Καρχηδονίων ἐπιμελητάς κελεύων, ὅταν Διονυσίῳ περὶ τῆς εἰρήνης διαλέγωνται, μὴ χωρὶς αὐτοῦ ποιήσασθαι τὴν ἔντευξιν, ὡς πάντα θησομένους ἀμεταπτώτως δι’ αὐτοῦ. ταύτην ἀναγνοὺς Διονύσιος Φιλίστῳ καὶ μετ’ ἐκείνου βουλευσάμενος, ὥς φησι Τίμαιος, ὑπῆλθε τὸν Δίωνα πεπλασμέναις διαλύσεσι· καὶ μέτρια σκηψάμενος διαλλάττεσθαί τε φήσας, μόνον τε ἀπαγαγὼν ὑπὸ τὴν ἀκρόπολιν πρὸς τὴν θάλασσαν, ἔδειξε τὴν ἐπιστολὴν καὶ κατηγόρησεν ὡς συνισταμένου μετὰ Καρχηδονίων ἐπ’ αὐτόν. ἀπολογεῖσθαι δὲ βουλομένου τοῦ Δίωνος οὐκ ἀνασχόμενος, ἀλλ’ εὐθὺς, ὡς εἶχεν, ἐνθέμενος εἰς ἀκάτιον προσέταξε τοῖς ναύταις κομίζοντας αὐτὸν ἐκθεῖναι πρὸς τὴν Ἰταλίαν.", "st": "Dion 14.4"}, {"sp": "N", "t": "γενομένου δὲ τούτου καὶ φανέντος ὠμοῦ τοῖς ἀνθρώποις, τὴν μὲν οἰκίαν τοῦ τυράννου πένθος εἶχε διὰ τὰς γυναῖκας, ἡ δὲ πόλις τῶν Συρακουσίων ἐπῆρτο πράγματα νεώτερα καὶ μεταβολὴν προσδεχομένη ταχεῖαν ἐκ τοῦ περὶ Δίωνα θορύβου καὶ τῆς πρὸς τὸν τύραννον ἀπιστίας τῶν ἄλλων. ἃ δὴ συνορῶν ὁ Διονύσιος καὶ δεδοικώς, τοὺς μὲν φίλους παρεμυθεῖτο καὶ τὰς γυναῖκας ὡς οὐ φυγῆς, ἀλλ’ ἀποδημίας τῷ Δίωνι γεγενημένης, ὡς μή τι χεῖρον ὀργῇ πρὸς τὴν αὐθάδειαν αὐτοῦ παρόντος ἁμαρτεῖν βιασθείη· δύο δὲ ναῦς παραδοὺς τοῖς Δίωνος οἰκείοις ἐκέλευσεν ἐνθεμένοις ὅσα βούλοιντο τῶν ἐκείνου χρήματα καὶ θεράποντας ἀπάγειν πρὸς αὐτὸν εἰς Πελοπόννησον. ἦν δ’ οὐσία μεγάλη τῷ Δίωνι καὶ σχεδόν τι τυραννικὴ πομπὴ καὶ κατασκευὴ περὶ τὴν δίαιταν, ἣν οἱ φίλοι συλλαβόντες ἐκόμιζον. ἄλλα δ’ ἐπέμπετο πολλὰ παρὰ τῶν γυναικῶν καὶ τῶν ἑταίρων, ὥστε χρημάτων ἕνεκα καὶ πλούτου λαμπρὸν ἐν τοῖς Ἕλλησιν εἶναι καὶ διαφανῆναι τῇ τοῦ φυγάδος εὐπορίᾳ τὴν τῆς τυραννίδος δύναμιν.", "st": "Dion 15.1"}, {"sp": "N", "t": "Πλάτωνα δὲ Διονύσιος εὐθὺς μὲν εἰς τὴν ἀκρόπολιν μετέστησεν, ἔντιμον αὐτῷ σχήματι ξενίας φιλανθρώπου φρουρὰν μηχανησάμενος, ὡς μὴ συμπλέοι Δίωνι μάρτυς ὧν ἠδίκητο. χρόνῳ δὲ καὶ συνδιαιτήσει, καθάπερ ψαύειν ἀνθρώπου θηρίον, ἐθισθεὶς ὑπομένειν τήν τε ὁμιλίαν αὐτοῦ καὶ τὸν λόγον, ἠράσθη τυραννικὸν ἔρωτα, μόνος ἀξιῶν ὑπὸ Πλάτωνος ἀντερᾶσθαι καὶ θαυμάζεσθαι μάλιστα πάντων, ἕτοιμος ὢν ἐπιτρέπειν τὰ πράγματα καὶ τὴν τυραννίδα μὴ προτιμῶντι τὴν πρὸς Δίωνα φιλίαν τῆς πρὸς αὐτόν, ἦν οὖν τῷ Πλάτωνι συμφορὰ τὸ πάθος αὐτοῦ τοῦτο, μαινομένου καθάπερ οἱ δυσέρωτες ὑπὸ ζηλοτυπίας, καὶ πολλὰς μὲν ὀργὰς ἐν ὀλίγῳ χρόνῳ, πολλὰς δὲ διαλλαγὰς καὶ δεήσεις ποιουμένου πρὸς αὐτόν, ἀκροᾶσθαι δὲ τῶν λόγων καὶ κοινωνεῖν τῆς περὶ φιλοσοφίαν πραγματείας σπουδάζοντος μὲν ὑπερφυῶς, αἰδουμένου δὲ τοὺς ἀποτρέποντας ὡς διαφθαρησομένου.", "st": "Dion 16.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ πολέμου τινὸς ἐμπεσόντος ἀποπέμπει τὸν Πλάτωνα, συνθέμενος εἰς ὥραν ἔτους μεταπέμψασθαι Δίωνα. καὶ τοῦτο μὲν εὐθὺς ἐψεύσατο, τὰς δὲ προσόδους τῶν κτημάτων ἀπέπεμπεν αὐτῷ, ἀξιῶν Πλάτωνα συγγνῶναι περὶ τοῦ χρόνου διὰ τὸν πόλεμον· εἰρήνης γὰρ γενομένης τάχιστα μεταπέμψεσθαι τὸν Δίωνα, καὶ ἀξιοῦν αὐτὸν ἡσυχίαν ἄγειν καὶ μηδὲν νεωτερίζειν μηδὲ βλασφημεῖν κατ’ αὐτοῦ πρὸς τοὺς Ἕλληνας.", "st": "Dion 16.4"}, {"sp": "N", "t": "ταῦτα ἐπειρᾶτο ποιεῖν Πλάτων, καὶ Δίωνα τρέψας ἐπὶ φιλοσοφίαν ἐν Ἀκαδημείᾳ συνεῖχεν. ᾤκει μὲν οὖν ἐν ἄστει παρὰ Καλλίππῳ τινὶ τῶν γνωρίμων, ἀγρὸν δὲ διαγωγῆς χάριν ἐκτήσατο, καὶ τοῦτον ὕστερον εἰς Σικελίαν πλέων Σπευσίππῳ δωρεὰν ἔδωκεν, ᾧ μάλιστα τῶν Ἀθήνησι φίλων ἐχρῆτο καὶ συνδιῃτᾶτο, βουλομένου τοῦ Πλάτωνος ὁμιλίᾳ χάριν ἐχούσῃ καὶ παιδιᾶς ἐμμελοῦς κατὰ καιρὸν ἁπτομένῃ κεραννύμενον ἀφηδύνεσθαι τοῦ Δίωνος τὸ ἦθος. τοιοῦτος δέ τις ὁ Σπεύσιππος ἦν· ᾗ καὶ σκῶψαι ἀγαθὸν αὐτὸν ἐν τοῖς Σίλλοις ὁ Τίμων προσηγόρευσεν. αὐτῷ δὲ Πλάτωνι χορηγοῦντι παίδων χορῷ τόν τε χορὸν ἤσκησεν ὁ Δίων καὶ τὸ δαπάνημα πᾶν ἐτέλεσε παρ’ ἑαυτοῦ, συγχωροῦντος τοῦ Πλάτωνος τὴν τοιαύτην φιλοτιμίαν πρὸς τοὺς Ἀθηναίους, ὡς ἐκείνῳ μᾶλλον εὔνοιαν ἢ δόξαν αὐτῷ φέρουσαν.", "st": "Dion 17.1"}, {"sp": "N", "t": "ἐπεφοίτα δὲ καὶ ταῖς ἄλλαις πόλεσιν ὁ Δίων, καὶ συνεσχόλαζε καὶ συνεπανηγύριζε τοῖς ἀρίστοις καὶ πολιτικωτάτοις ἀνδράσιν, οὐδὲν ἐν τῇ διαίτῃ σόλοικον ἐπιδεικνύμενος οὐδὲ τυραννικὸν οὐδὲ ἐπιτεθρυμμένον, ἀλλὰ σωφροσύνην καὶ ἀρετὴν καὶ ἀνδρείαν καὶ περὶ λόγους καὶ περὶ φιλοσοφίαν εὐσχήμονας διατριβάς. ἐφ’ οἷς εὔνοια παρὰ πάντων ἐγίνετο καὶ ζῆλος αὐτῷ τιμαί τε δημόσιαι καὶ ψηφίσματα παρὰ τῶν πόλεων. Λακεδαιμόνιοι δὲ καὶ Σπαρτιάτην αὐτὸν ἐποιήσαντο, τῆς Διονυσίου καταφρονήσαντες ὀργῆς, καίπερ αὐτοῖς τότε προθύμως ἐπὶ τοὺς Θηβαίους συμμαχοῦντος. λέγεται δέ ποτε τὸν Δίωνα τοῦ Μεγαρέως Πτοιοδώρου δεόμενον ἐπὶ τὴν οἰκίαν ἐλθεῖν ἦν δέ, ὡς ἔοικε, τῶν πλουσίων τις καὶ δυνατῶν ὁ Πτοιόδωρος· ὄχλον οὖν ἐπὶ θύραις ἰδὼν ὁ Δίων καὶ πλῆθος ἀσχολιῶν καὶ δυσέντευκτον αὐτὸν καὶ δυσπρόσοδον, ἀπιδὼν πρὸς τοὺς φίλους δυσχεραίνοντας καὶ ἀγανακτοῦντας, τί τοῦτον ἔφη, μεμφόμεθα; καὶ γὰρ αὐτοὶ πάντως ἐν Συρακούσαις ὅμοια τούτοις ἐποιοῦμεν.", "st": "Dion 17.6"}, {"sp": "N", "t": "χρόνου δὲ προϊόντος ὁ Διονύσιος ζηλοτυπῶν καὶ δεδοικὼς τοῦ Δίωνος τὴν παρὰ τοῖς Ἕλλησιν εὔνοιαν, ἐπαύσατο τὰς προσόδους ἀποστέλλων καὶ τὴν οὐσίαν παρέδωκεν ἰδίοις ἐπιτρόποις. βουλόμενος δὲ καὶ τὴν εἰς τοὺς φιλοσόφους διὰ Πλάτωνα κακοδοξίαν ἀναμάχεσθαι, πολλοὺς συνῆγε τῶν πεπαιδεῦσθαι δοκούντων. φιλοτιμούμενος δὲ τῷ διαλέγεσθαι περιεῖναι πάντων, ἠναγκάζετο τοῖς Πλάτωνος παρακούσμασι κακῶς χρῆσθαι. καὶ πάλιν ἐκεῖνον ἐπόθει, καὶ κατεγίνωσκεν αὐτός αὑτοῦ μὴ χρησάμενος παρόντι μηδὲ διακούσας ὅσα καλῶς εἶχεν. οἷα δὲ τύραννος ἔμπληκτος ἀεὶ ταῖς ἐπιθυμίαις καὶ πρὸς πᾶσαν ὀξύρροπος σπουδήν, εὐθὺς ὥρμησεν ἐπὶ τὸν Πλάτωνα, καὶ πᾶσαν μηχανὴν αἴρων, συνέπεισε τοὺς περὶ Ἀρχύταν Πυθαγορικοὺς τῶν ὁμολογουμένων ἀναδόχους γενομένους καλεῖν Πλάτωνα· δι’ ἐκείνου γὰρ αὐτοῖς ἐγεγόνει φιλία καὶ ξενία τὸ πρῶτον. οἱ δ’ ἔπεμψαν Ἀρχέδημον παρ’ αὐτόν· ἔπεμψε δὲ καὶ Διονύσιος τριήρη καὶ φίλους δεησομένους τοῦ Πλάτωνος· αὐτός τε σαφῶς καὶ διαρρήδην ἔγραψεν ὡς οὐδὲν ἂν γένοιτο τῶν μετρίων Δίωνι μὴ πεισθέντος Πλάτωνος ἐλθεῖν εἰς Σικελίαν, πεισθέντος δὲ πάντα. πολλαὶ δ’ ἀφίκοντο πρὸς Δίωνα παρὰ τῆς ἀδελφῆς καὶ γυναικὸς ἐπισκήψεις, δεῖσθαι Πλάτωνος ὑπακοῦσαι Διονυσίῳ καὶ μὴ πρόφασιν παρασχεῖν. οὕτω μὲν δή φησιν ὁ Πλάτων ἐλθεῖν τὸ τρίτον εἰς τὸν πορθμὸν τὸν περὶ Σκύλλαν,", "st": "Dion 18.1"}, {"sp": "N", "t": "ὄφρ’ ἔτι τὴν ὀλοὴν ἀναμετρήσειε Χάρυβδιν.", "st": "Dion 18.1b"}, {"sp": "N", "t": "ἐλθὼν δὲ μεγάλης μὲν αὐτὸν ἐνέπλησε χαρᾶς, μεγάλης δὲ πάλιν ἐλπίδος Σικελίαν, συνευχομένην καὶ συμφιλοτιμουμένην Πλάτωνα μὲν Φιλίστου περιγενέσθαι, φιλοσοφίαν δὲ τυραννίδος. ἦν δὲ πολλὴ μὲν τῶν γυναικῶν σπουδὴ περὶ αὐτόν, ἐξαίρετος δὲ παρὰ τῷ Διονυσίῳ πίστις, ἣν οὐδεὶς ἄλλος εἶχεν, ἀδιερεύνητον αὐτῷ πλησιάζειν. δωρεὰς δὲ χρημάτων πολλῶν καὶ πολλάκις τοῦ μὲν διδόντος, τοῦ δὲ μὴ δεχομένου, παρὼν Ἀρίστιππος ὁ Κυρηναῖος ἀσφαλῶς ἔφη μεγαλόψυχον εἶναι Διονύσιον· αὐτοῖς μὲν γὰρ μικρὰ διδόναι πλειόνων δεομένοις, Πλάτωνι δὲ πολλὰ μηδὲν λαμβάνοντι.", "st": "Dion 19.1"}, {"sp": "N", "t": "μετὰ δὲ τὰς πρώτας φιλοφροσύνας, ἀρξαμένου Πλάτωνος ἐντυγχάνειν περὶ Δίωνος, ὑπερθέσεις τὸ πρῶτον ἦσαν, εἶτα μέμψεις καὶ διαφοραὶ λανθάνουσαι τοὺς ἐκτός, ἐπικρυπτομένου Διονυσίου καὶ ταῖς ἄλλαις τὸν Πλάτωνα θεραπείαις καὶ τιμαῖς πειρωμένου παράγειν ἀπὸ τῆς Δίωνος εὐνοίας, οὐδ’ αὐτὸν ἔν γε τοῖς πρώτοις χρόνοις ἀποκαλύπτοντα τὴν ἀπιστίαν αὐτοῦ καὶ ψευδολογίαν, ἀλλ’ ἐγκαρτεροῦντα καὶ σχηματιζόμενον. οὕτω δὲ διακειμένων πρὸς ἀλλήλους καὶ λανθάνειν πάντας οἰομένων. ἑλίκων ὁ Κυζικηνός εἷς τῶν Πλάτωνος συνήθων ἡλίου προεῖπεν ἔκλειψιν καὶ γενομένης ὡς προεῖπε, θαυμασθεὶς ὑπὸ τοῦ τυράννου δωρεὰν ἔλαβεν ἀργυρίου τάλαντον. Ἀρίστιππος δὲ παίζων πρὸς τοὺς ἄλλους φιλοσόφους ἔφη τι καὶ αὐτὸς ἔχειν τῶν παραδόξων προειπεῖν. ἐκείνων δὲ φράσαι δεομένων, προλέγω τοίνυν, εἶπεν, ὀλίγου χρόνου Πλάτωνα καὶ Διονύσιον ἐχθροὺς γενησομένους. τέλος δὲ τὴν μὲν οὐσίαν τοῦ Δίωνος ὁ Διονύσιος ἐπώλει καὶ τὰ χρήματα κατεῖχε, Πλάτωνα δ’ ἐν τῷ περὶ τὴν οἰκίαν κήπῳ διαιτώμενον εἷς τοὺς μισθοφόρους μετέστησε πάλαι μισοῦντας αὐτὸν καὶ ζητοῦντας ἀνελεῖν ὡς πείθοντα Διονύσιον ἀφεῖναι τὴν τυραννίδα καὶ ζῆν ἀδορυφόρητον,", "st": "Dion 19.4"}, {"sp": "N", "t": "ἐν τοιούτῳ δὲ κινδύνῳ γενομένου τοῦ Πλάτωνος οἱ περὶ Ἀρχύταν πυθόμενοι ταχὺ πέμπουσι πρεσβείαν καὶ τριακόντορον, ἀπαιτοῦντες τὸν ἄνδρα παρὰ Διονυσίου καὶ λέγοντες ὡς αὐτοὺς λαβὼν ἀναδόχους τῆς ἀσφαλείας πλεύσειεν εἰς Συρακούσας. ἀπολεγομένου δὲ τοῦ Διονυσίου τὴν ἔχθραν ἑστιάσεσι καὶ φιλοφροσύναις περὶ τὴν προπομπήν, ἓν δέ τι προαχθέντος πρὸς αὐτὸν τοιοῦτον εἰπεῖν· ἦ που, Πλάτων, πολλὰ καὶ δεινὰ κατηγορήσεις ἡμῶν πρὸς τοὺς συμφιλοσοφοῦντας· ὑπομειδιάσας ἐκεῖνος ἀπεκρίνατο μὴ τοσαύτη λόγων ἐν Ἀκαδημείᾳ γένοιτο σπάνις ὥστε σοῦ τινα μνημονεῦσαι. τοιαύτην μὲν τὴν ἀποστολὴν τοῦ Πλάτωνος γενέσθαι λέγουσιν· οὐ μέντοι τὰ Πλάτωνος αὐτοῦ πάνυ τούτοις συνᾴδει.", "st": "Dion 20.1"}, {"sp": "N", "t": "Δίων δὲ καὶ τούτοις ἐχαλέπαινε, καὶ μετ’ ὀλίγον χρόνον ἐξεπολεμώθη παντάπασι πυθόμενος τὸ περὶ τὴν γυναῖκα, περὶ οὗ καὶ Πλάτων ᾐνίξατο γράφων πρὸς Διονύσιον, ἦν δὲ τοιοῦτον. μετὰ τὴν ἐκβολὴν τοῦ Δίωνος ἀποπέμπων Πλάτωνα Διονύσιος ἐκέλευσεν αὐτοῦ δι’ ἀπορρήτων πυθέσθαι, μή τι κωλύοι τὴν γυναῖκα πρὸς γάμον ἑτέρῳ δοθῆναι· καὶ γὰρ ἦν λόγος, εἴτ’ ἀληθὴς εἴτε συντεθεὶς ὑπὸ τῶν Δίωνα μισούντων, ὡς οὐ καθ’ ἡδονὴν ὁ γάμος εἴη Δίωνι γεγονὼς οὐδ’ εὐάρμοστος ἡ πρὸς τὴν γυναῖκα συμβίωσις. ὡς οὖν ἧκεν ὁ Πλάτων Ἀθήναζε καὶ τῷ Δίωνι περὶ πάντων ἐνέτυχε, γράφει πρὸς τὸν τύραννον ἐπιστολήν τὰ μὲν ἄλλα σαφῶς πᾶσιν, αὐτὸ δὲ τοῦτο μόνῳ γνώριμον ἐκείνῳ φράζουσαν, ὡς διαλεχθείη Δίωνι περὶ τοῦ πράγματος ἐκείνου καὶ σφόδρα δῆλος εἴη χαλεπαίνων, εἰ τοῦτο Διονύσιος ἐξεργάσαιτο. καὶ τότε μὲν ἔτι πολλῶν ἐλπίδων οὐσῶν πρὸς τὰς διαλύσεις οὐδὲν ἔπραξε περὶ τὴν ἀδελφὴν νεώτερον, ἀλλ’ εἴα μένειν αὐτὴν μετὰ τοῦ παιδίου τοῦ Δίωνος οἰκοῦσαν. ἐπεὶ δὲ παντάπασιν ἀσυμβάτως εἶχε καὶ Πλάτων αὖθις ἐλθὼν ἀπεπέμφθη πρὸς ἀπέχθειαν, οὕτω τὴν Ἀρετὴν ἄκουσαν ἑνὶ τῶν φίλων Τιμοκράτει δίδωσιν, οὐ μιμησάμενος τὴν κατά γε τοῦτο τοῦ πατρὸς ἐπιείκειαν.", "st": "Dion 21.1"}, {"sp": "N", "t": "ἐγεγόνει γὰρ, ὡς ἔοικε, κἀκείνῳ Πολύξενος ὁ τὴν ἀδελφὴν ἔχων αὐτοῦ Θέστην πολέμιος, ἀποδράντος οὖν αὐτοῦ διὰ φόβον καὶ φυγόντος ἐκ Σικελίας μεταπεμψάμενος ᾐτιᾶτο τὴν ἀδελφήν, ὅτι συνειδυῖα τὴν φυγὴν τοῦ ἀνδρὸς οὐ κατεῖπε πρὸς αὐτόν. ἡ δ’ ἀνεκπλήκτως καὶ νὴ Δί’ ἀφόβως· εἶθ’ οὕτω σοι δοκῶ, Διονύσιε, φαύλη γυνὴ γεγονέναι καὶ ἄνανδρος ὥστε προγνοῦσα τὴν φυγὴν τοῦ ἀνδρὸς οὐκ ἂν συνεκπλεῦσαι καὶ μετασχεῖν τῆς αὐτῆς τύχης; ἀλλ’ οὐ προέγνων ἐπεὶ καλῶς εἶχέ μοι μᾶλλον Πολυξένου γυναῖκα φεύγοντος ἢ σοῦ τυραννοῦντος ἀδελφὴν λέγεσθαι. ταῦτα τῆς Θέστης παρρησιασαμένης θαυμάσαι λέγουσι τὸν τύραννον.ἐθαύμασαν δὲ καὶ οἱ Συρακούσιοι τὴν ἀρετὴν τῆς γυναικός, ὥστε καὶ μετὰ τὴν κατάλυσιν τῆς τυραννίδος ἐκείνῃ τιμὴν καὶ θεραπείαν βασιλικὴν ὑπάρχειν, ἀποθανούσης δὲ δημοσίᾳ πρὸς τὴν ταφὴν ἐπακολουθῆσαι τοὺς πολίτας. ταῦτα μὲν οὖν οὐκ ἄχρηστον ἔχει τὴν παρέκβασιν.", "st": "Dion 21.7"}, {"sp": "N", "t": "ὁ δὲ Δίων ἐντεῦθεν ἤδη τρέπεται πρὸς πόλεμον, αὐτοῦ μὲν Πλάτωνος ἐκποδὼν ἱσταμένου δι’ αἰδῶ τῆς πρὸς Διονύσιον ξενίας καὶ γῆρας, Σπευσίππου δὲ καὶ τῶν ἄλλων ἑταίρων τῷ Δίωνι συλλαμβανόντων καὶ παρακελευομένων ἐλευθεροῦν Σικελίαν χεῖρας ὀρέγουσαν αὐτῷ καὶ προθύμως ὑποδεχομένην. ὅτε γὰρ ἐν Συρακούσαις Πλάτων διέτριβεν, οἱ περὶ Σπεύσιππον, ὡς ἔοικε, μᾶλλον ἀναμιγνύμενοι τοῖς ἀνθρώποις κατεμάνθανον τὴν διάνοιαν αὐτῶν, καὶ τὸ μὲν πρῶτον ἐφοβοῦντο τὴν παρρησίαν ὡς διάπειραν οὖσαν ὑπὸ τοῦ τυράννου, χρόνῳ δ’ ἐπίστευσαν. ὁ γὰρ αὐτὸς ἦν παρὰ πάντων λόγος δεομένων καὶ παρακελευομένων ἐλθεῖν Δίωνα μὴ ναῦς ἔχοντα μηδ’ ὁπλίτας μηδ’ ἵππους, ἀλλ’ αὐτὸν εἰς ὑπηρετικὸν ἐμβάντα χρῆσαι τὸ σῶμα καὶ τοὔνομα Σικελιώταις ἐπὶ τὸν Διονύσιον. ταῦτα τῶν περὶ Σπεύσιππον ἀγγελλόντων ἐπιρρωσθεὶς ἐξενολόγει κρύφα καὶ δι’ ἑτέρων ἐπικρυπτόμενος τὴν διάνοιαν. συνέπραττον δὲ καὶ τῶν πολιτικῶν πολλοὶ καὶ τῶν φιλοσόφων, ὅ τε Κύπριος Εὔδημος, εἰς ὃν Ἀριστοτέλης ἀποθανόντα τὸν περὶ ψυχῆς διάλογον ἐποίησε, καὶ Τιμωνίδης ὁ Λευκάδιος. συνέστησαν δὲ καὶ Μιλτᾶν αὐτῷ τὸν Θεσσαλόν, ἄνδρα μάντιν καὶ μετεσχηκότα τῆς ἐν Ἀκαδημείᾳ διατριβῆς. τῶν δ’ ὑπὸ τοῦ τυράννου πεφυγαδευμένων, οὐ μεῖον ἢ χιλίων ὄντων, πέντε καὶ εἴκοσι μόνοι τῆς στρατείας ἐκοινώνησαν, οἱ δ’ ἄλλοι προὔδοσαν ἀποδειλιάσαντες. ὁρμητήριον δ’ ἦν ἡ Ζακυνθίων νῆσος, εἰς ἣν οἱ στρατιῶται συνελέγησαν ὀκτακοσίων ἐλάττους γενόμενοι, γνώριμοι δὲ πάντες ἐκ πολλῶν καὶ μεγάλων στρατειῶν, καὶ τοῖς σώμασιν ἠσκημένοι διαφερόντως, ἐμπειρίᾳ δὲ καὶ τόλμῃ πολὺ πάντων κράτιστοι, καὶ δυνάμενοι πλῆθος ὅσον ἤλπιζεν ἕξειν ἐν Σικελίᾳ Δίων ὑπεκκαῦσαι καὶ συνεξορμῆσαι πρὸς ἀλκήν.", "st": "Dion 22.1"}, {"sp": "N", "t": "οὗτοι τὸ μὲν πρῶτον ἀκούσαντες ἐπὶ Διονύσιον καὶ Σικελίαν αἴρεσθαι τὸν στόλον, ἐξεπλάγησαν καὶ κατέγνωσαν, ὡς ὀργῆς τινος παραφροσύνῃ καὶ μανίᾳ τοῦ Δίωνος ἢ χρηστῶν ἐλπίδων ἀπορίᾳ ῥιπτοῦντος ἑαυτὸν εἰς ἀπεγνωσμένας πράξεις· καὶ τοῖς ἑαυτῶν ἡγεμόσι καὶ ξενολόγοις ὠργίζοντο μὴ προειποῦσιν εὐθὺς ἐξ ἀρχῆς τὸν πόλεμον. ἐπεὶ δὲ Δίων τῷ λόγῳ τὰ σαθρὰ τῆς τυραννίδος ἐπεξιὼν ἐδίδασκεν, ὡς οὐ στρατιώτας, ἀλλὰ μᾶλλον ἡγεμόνας αὐτοὺς κομίζοι Συρακουσίων καὶ τῶν ἄλλων Σικελιωτῶν πάλαι πρὸς ἀπόστασιν ἑτοίμων ὑπαρχόντων, μετὰ δὲ τὸν Δίωνα διαλεχθέντος αὐτοῖς Ἀλκιμένους, ὃς πρῶτος ὢν Ἀχαιῶν δόξῃ καὶ γένει συνεστράτευεν, ἐπείσθησαν.", "st": "Dion 23.1"}, {"sp": "N", "t": "ἦν μὲν οὖν θέρους ἀκμή καὶ κατεῖχον ἐτησίαι τὸ πέλαγος, ἡ δὲ σελήνη διχομηνίαν ἦγε. τῷ δ’ Ἀπόλλωνι θυσίαν μεγαλοπρεπῆ παρασκευάσας ὁ Δίων ἐπόμπευσε μετὰ τῶν στρατιωτῶν κεκοσμημένων ταῖς πανοπλίαις πρὸς τὸ ἱερόν· καὶ μετὰ τὴν θυσίαν ἐν τῷ σταδίῳ τῶν Ζακυνθίων κατακλιθέντας αὐτοὺς εἱστία, θαυμάζοντας ἀργυρῶν καὶ χρυσῶν ἐκπωμάτων καὶ τραπεζῶν ὑπερβάλλουσαν ἰδιωτικὸν πλοῦτον λαμπρότητα, καὶ λογιζομένους ὅτι παρηκμακὼς ἀνὴρ ἤδη καὶ τοσαύτης εὐπορίας κύριος οὐκ ἂν ἐπιχειροίη παραβόλοις πράγμασι χωρὶς ἐλπίδος βεβαίου καὶ φίλων ἐνδιδόντων ἐκεῖθεν αὐτῷ τὰς πλείστας καὶ μεγίστας ἀφορμάς.", "st": "Dion 23.3"}, {"sp": "N", "t": "μετὰ δὲ τὰς σπονδὰς καὶ τὰς νενομισμένας κατευχὰς ἐξέλιπεν ἡ σελήνη, καὶ τοῖς μὲν περὶ τὸν Δίωνα θαυμαστὸν οὐδὲν ἦν λογιζομένοις τὰς ἐκλειπτικὰς περιόδους καὶ τὴν γινομένην τοῦ σκιάσματος ἀπάντησιν πρὸς τὴν σελήνην καὶ τῆς γῆς τὴν ἀντίφραξιν πρὸς τὸν ἥλιον. ἐπεὶ δὲ τοῖς στρατιώταις διαταραχθεῖσιν ἔδει τινὸς παρηγορίας, Μιλτᾶς ὁ μάντις ἐν μέσῳ καταστὰς ἐκέλευε θαρρεῖν αὐτοὺς καὶ προσδοκᾶν τὰ κράτιστα· σημαίνειν γὰρ τὸ δαιμόνιον ἔκλειψίν τινος τῶν νῦν ἐπιφανῶν· ἐπιφανέστερον δὲ μηδὲν εἶναι τῆς Διονυσίου τυραννίδος, ἧς τὸ λαμπρὸν ἀποσβέσειν ἐκείνους εὐθὺς ἁψαμένους Σικελίας. τοῦτο μὲν οὖν ὁ Μιλτᾶς εἰς μέσον ἐξέθηκε πᾶσι τὸ δὲ τῶν μελισσῶν, αἳ περὶ τὰ πλοῖα τοῦ Δίωνος ὤφθησαν ἑσμὸν λαμβάνουσαι κατὰ πρύμναν, ἰδίᾳ πρὸς αὐτὸν καὶ τοὺς φίλους ἔφραζε δεδιέναι μὴ καλαὶ μὲν αἱ πράξεις αὐτοῦ γένωνται, χρόνον δ’ ὀλίγον ἀνθήσασαι μαρανθῶσι. λέγεται δὲ καὶ τῷ Διονυσίῳ πολλὰ τερατώδη παρὰ τοῦ δαιμονίου γενέσθαι σημεῖα. ἀετὸς μὲν γὰρ ἁρπάσας δοράτιόν τινος τῶν δορυφόρων ἀράμενος ὑψοῦ καὶ φέρων ἀφῆκεν εἰς τὸν βυθόν· ἡ δὲ προσκλύζουσα πρὸς τὴν ἀκρόπολιν θάλασσα μίαν ἡμέραν τὸ ὕδωρ γλυκὺ καὶ πότιμον παρέσχεν, ὥστε γευσαμένοις πᾶσι κατάδηλον εἶναι. χοῖροι δ’ ἐτέχθησαν αὐτῷ τῶν μὲν ἄλλων οὐδενὸς ἐνδεεῖς μορίων, ὦτα δ’ οὐκ ἔχοντες. ἀπεφαίνοντο δ’ οἱ μάντεις τοῦτο μὲν ἀποστάσεως καὶ ἀπειθείας εἶναι σημεῖον, ὡς οὐκέτι τῶν πολιτῶν ἀκουσομένων τῆς τυραννίδος, τὴν δὲ γλυκύτητα τῆς θαλάσσης μεταβολὴν καιρῶν ἀνιαρῶν καὶ πονηρῶν εἰς πράγματα χρηστὰ φέρειν Συρακουσίοις. ἀετὸς δὲ θεράπων Διός, λόγχη δὲ παράσημον ἀρχῆς καὶ δυναστείας· ἀφανισμὸν οὖν καὶ κατάλυσιν τῇ τυραννίδι βουλεύειν τὸν τῶν θεῶν μέγιστον. ταῦτα μὲν οὖν Θεόπομπος ἱστόρηκε.", "st": "Dion 24.1"}, {"sp": "N", "t": "τοὺς δὲ στρατιώτας τοὺς Δίωνος ἐξεδέξαντο στρογγύλαι δύο ναῦς, τρίτον δὲ πλοῖον οὐ μέγα καὶ δύο τριακόντοροι παρηκολούθουν. ὅπλα δέ, χωρὶς ὧν εἶχον οἱ στρατιῶται, δισχιλίας μὲν ἐκόμιζεν ἀσπίδας, βέλη δὲ καὶ δόρατα πολλὰ, καὶ πλῆθος ἐφοδίων ἄφθονον, ὅπως ἐπιλίπῃ μηδὲν αὐτοὺς ποντοποροῦντας, ἅτε δὴ τὸ σύμπαν ἐπὶ πνεύμασι καὶ θαλάσσῃ πεποιημένους τὸν πλοῦν διὰ τὸ τὴν γῆν φοβεῖσθαι καὶ πυνθάνεσθαι Φίλιστον ἐν Ἰαπυγίᾳ ναυλοχοῦντα παραφυλάττειν. ἀραιῷ δὲ καὶ μαλακῷ πνεύματι πλεύσαντες ἡμέρας δώδεκα, τῇ τρισκαιδεκάτῃ κατὰ Πάχυνον ἦσαν, ἄκραν τῆς Σικελίας. καὶ Πρῶτος μὲν ὁ κυβερνήτης κατὰ τάχος ἐκέλευσεν ἀποβαίνειν, ὡς, ἂν ἀποσπασθῶσι τῆς γῆς καὶ τὴν ἄκραν ἑκόντες ἀφῶσι, πολλὰς ἡμέρας καὶ νύκτας ἐν τῷ πελάγει τριβησομένους, ὥρᾳ θέρους νότον περιμένοντας. Δίων δὲ τὴν ἐγγὺς τῶν πολεμίων ἀπόβασιν δεδιὼς καὶ τῶν πρόσω μᾶλλον ἅψασθαι βουλόμενος παρέπλευσε τὸν Πάχυνον. ἐκ δὲ τούτου τραχὺς μὲν ἀπαρκτίας ἐπιπεσὼν ἤλαυνε πολλῷ κλύδωνι τὰς ναῦς ἀπὸ τῆς Σικελίας, ἀστραπαὶ δὲ καὶ βρονταὶ φανέντος Ἀρκτούρου συμπεσοῦσαι πολὺν ἐξ οὐρανοῦ χειμῶνα καὶ ῥαγδαῖον ὄμβρον ἐξέχεαν· ᾧ τῶν ναυτῶν συνταραχθέντων καὶ πλάνης γενομένης καθορῶσιν αἰφνίδιον ὑπὸ τοῦ κύματος ὠθουμένας τὰς ναῦς ἐπὶ τὴν πρὸς Λιβύῃ Κέρκιναν, ᾗ μάλιστα κρημνώδης ἀπήντα καὶ τραχεῖα προσφερομένοις αὐτοῖς ἡ νῆσος. μικρὸν οὖν δεήσαντες ἐκριφῆναι καὶ συντριβῆναι περὶ τὰς πέτρας ἐβιάζοντο πρὸς κοντὸν παραφερόμενοι μόλις, ἕως ὁ χειμὼν ἐλώφησε καὶ πλοίῳ συντυχόντες ἔγνωσαν ἐπὶ ταῖς καλουμέναις κεφαλαῖς τῆς μεγάλης Σύρτεως ὄντες. ἀθυμοῦσι δ’ αὐτοῖς πρὸς τὴν γαλήνην καὶ διαφερομένοις αὔραν τινὰ κατέσπειρεν ἡ χώρα νότιον, οὐ πάνυ προσδεχομένοις νότον οὐδὲ πιστεύουσι τῇ μεταβολῇ. κατὰ μικρὸν δὲ ῥωννυμένου τοῦ πνεύματος καὶ μέγεθος λαμβάνοντος ἐκτείναντες ὅσον ἦν ἱστίων, καὶ προσευξάμενοι τοῖς θεοῖς, πελάγιοι πρὸς τὴν Σικελίαν ἔφευγον ἀπὸ τῆς Λιβύης· καὶ θέοντες ἐλαφρῶς πεμπταῖοι κατὰ Μίνῳαν ὡρμίσαντο, πολισμάτιον ἐν τῇ Σικελίᾳ τῆς Καρχηδονίων ἐπικρατείας. ἔτυχε δὲ παρὼν ὁ Καρχηδόνιος ἄρχων Σύναλος ἐν τῷ χωρίῳ, ξένος ὢν καὶ φίλος Δίωνος.", "st": "Dion 25.1"}, {"sp": "N", "t": "ἀγνοῶν δὲ τὴν παρουσίαν αὐτοῦ καὶ τὸν στόλον, ἐπειρᾶτο κωλύειν τοὺς στρατιώτας ἀποβαίνοντας. οἱ δὲ μετὰ τῶν ὅπλων ἐκδραμόντες ἀπέκτειναν μὲν οὐδένα, ἀπειρήκει γὰρ ὁ Δίων διὰ τὴν οὖσαν αὐτῷ φιλίαν πρὸς τὸν Καρχηδόνιον, φεύγουσι δὲ συνεισπεσόντες αἱροῦσι τὸ χωρίον. ὡς δ’ ἀπήντησαν ἀλλήλοις οἱ ἡγεμόνες καὶ ἠσπάσαντο, Δίων μὲν ἀπέδωκε τὴν πόλιν Συνάλῳ, οὐδὲν ἀδικήσας, Σύναλος δὲ τοὺς στρατιώτας ἐξένιζε καὶ συμπαρεσκεύαζεν ὧν Δίων ἐδεῖτο.", "st": "Dion 25.13"}, {"sp": "N", "t": "μάλιστα δ’ αὐτοὺς ἐθάρρυνε τὸ συμβεβηκὸς αὐτομάτως περὶ τὴν ἀποδημίαν τοῦ Διονυσίου· νεωστὶ γὰρ ἐκπεπλευκὼς ἐτύγχανεν ὀγδοήκοντα ναυσὶν εἰς τὴν Ἰταλίαν. διὸ καὶ τοῦ Δίωνος παρακαλοῦντος ἐνταῦθα τοὺς στρατιώτας ἀναλαμβάνειν πολὺν χρόνον ἐν τῇ θαλάσσῃ κεκακωμένους, οὐχ ὑπέμειναν αὐτοὶ σπεύδοντες ἁρπάσαι τὸν καιρόν, ἀλλ’ ἐκέλευον ἡγεῖσθαι τὸν Δίωνα πρὸς τὰς Συρακούσας. ἀποσκευασάμενος οὖν τὰ περιόντα τῶν ὅπλων καὶ τῶν φορτίων ἐκεῖ, καὶ τοῦ Συνάλου δεηθεὶς, ὅταν ᾖ καιρὸς, ἀποστεῖλαι πρὸς αὐτόν, ἐβάδιζεν ἐπὶ τὰς Συρακούσας. πορευομένῳ δ’ αὐτῷ πρῶτον μὲν Ἀκραγαντίνων προσεχώρησαν ἱππεῖς διακόσιοι τῶν περὶ τὸ Ἔκνομον οἰκούντων, μετὰ δὲ τούτους Γελῷοι.", "st": "Dion 26.1"}, {"sp": "N", "t": "ταχὺ δὲ τῆς φήμης διαδραμούσης εἰς Συρακούσας Τιμοκράτης, ὁ τῇ Δίωνος γυναικὶ συνοικῶν, Διονυσίου δ’ ἀδελφῇ, τῶν ἀπολελειμμένων ἐν τῇ πόλει φίλων προεστώς, ἐκπέμπει κατὰ τάχος ἄγγελον τῷ Διονυσίῳ γράμματα κομίζοντα περὶ τῆς Δίωνος ἀφίξεως. αὐτὸς δὲ τοῖς κατὰ τὴν πόλιν προσεῖχε θορύβοις καὶ κινήμασιν, ἐπηρμένων μὲν πάντων, διὰ δ’ ἀπιστίαν ἔτι καὶ φόβον ἡσυχαζόντων. τῷ δὲ πεμφθέντι γραμματοφόρῳ τύχη τις συμπίπτει παράλογος.διαπλεύσας γὰρ εἰς τὴν Ἰταλίαν καὶ τὴν Ῥηγίνην διελθὼν, ἐπειγόμενος εἰς Καυλωνίαν πρὸς Διονύσιον ἀπήντησέ τινι τῶν συνήθων ἱερεῖον νεωστὶ τεθυμένον κομίζοντι· καὶ λαβὼν παρ’ αὐτοῦ μοῖραν τῶν κρεῶν ἐχώρει σπουδῇ. τῆς δὲ νυκτὸς μέρος ὁδεύσας καὶ μικρὸν ἀποδαρθεῖν ὑπὸ κόπου βιασθείς, ὡς εἶχε, παρὰ τὴν ὁδὸν ἐν ὕλῃ τινὶ κατέκλινεν ἑαυτόν. πρὸς δὲ τὴν ὀσμὴν λύκος ἐπελθὼν, καὶ λαβόμενος τῶν κρεῶν ἀναδεδεμένων ἐκ τῆς πήρας, ᾤχετο φέρων ἅμα σὺν αὐτοῖς τὴν πήραν, ἐν ᾗ τὰς ἐπιστολὰς ὁ ἄνθρωπος εἶχεν. ὡς δὲ διεγερθεὶς ᾔσθετο καὶ πολλὰ μάτην πλανηθεὶς καὶ διώξας οὐχ εὗρεν, ἔγνω μὴ πορεύεσθαι δίχα τῶν γραμμάτων πρὸς τὸν τύραννον, ἀλλ’ ἀποδρὰς ἐκποδὼν γενέσθαι.", "st": "Dion 26.5"}, {"sp": "N", "t": "Διονύσιος μὲν οὖν ὀψὲ καὶ παρ’ ἑτέρων ἔμελλε πυνθάνεσθαι τὸν ἐν Σικελίᾳ πόλεμον, Δίωνι δὲ πορευομένῳ Καμαριναῖοί τε προσέθεντο καὶ τῶν κατ’ ἀγροὺς Συρακουσίων ἀνισταμένων ἐπέρρει πλῆθος οὐκ ὀλίγον. οἱ δὲ μετὰ Τιμοκράτους τὰς Ἐπιπολὰς φυλάσσοντες Λεοντῖνοι καὶ Καμπανοί, λόγον ψευδῆ προσπέμψαντος εἰς αὐτοὺς τοῦ Δίωνος ὡς ἐπὶ τὰς πόλεις πρῶτον τρέποιτο τὰς ἐκείνων, ἀπολιπόντες ᾤχοντο τὸν Τιμοκράτην τοῖς οἰκείοις βοηθήσοντες. ὡς δ’ ἀπηγγέλη ταῦτα πρὸς τὸν Δίωνα περὶ τὰς Ἄκρας στρατοπεδεύοντα, νυκτὸς ἔτι τοὺς στρατιώτας ἀναστήσας πρὸς τὸν Ἄναπον ποταμὸν ἧκεν, ἀπέχοντα τῆς πόλεως δέκα σταδίους. ἐνταῦθα δὲ τὴν πορείαν ἐπιστήσας ἐσφαγιάζετο πρὸς τὸν ποταμόν, ἀνατέλλοντι τῷ ἡλίῳ προσευξάμενος· ἅμα δ’ οἱ μάντεις παρὰ τῶν θεῶν νίκην ἔφραζον αὐτῷ. καὶ θεασάμενοι τὸν Δίωνα διὰ τὴν θυσίαν ἐστεφανωμένον οἱ παρόντες ἀπὸ μιᾶς ὁρμῆς ἐστεφανοῦντο πάντες. ἦσαν δὲ πεντακισχιλίων οὐκ ἐλάττους προσγεγονότες κατὰ τὴν ὁδόν ὡπλισμένοι δὲ φαύλως ἐκ τοῦ προστυχόντος ἀνεπλήρουν τῇ προθυμίᾳ τὴν τῆς παρασκευῆς ἔνδειαν, ὥστε κινήσαντος τοῦ Δίωνος δρόμῳ χωρεῖν μετὰ χαρᾶς καὶ βοῆς ἀλλήλους παρακαλοῦντας ἐπὶ τὴν ἐλευθερίαν.", "st": "Dion 27.1"}, {"sp": "N", "t": "τῶν δ’ ἐν τῇ πόλει Συρακουσίων οἱ μὲν γνώριμοι καὶ χαρίεντες ἐσθῆτα καθαρὰν ἔχοντες ἀπήντων ἐπὶ τάς πύλας, οἱ δὲ πολλοὶ τοῖς τυράννου φίλοις ἐπετίθεντο καὶ συνήρπαζον τοὺς καλουμένους προσαγωγίδας, ἀνθρώπους ἀνοσίους καὶ θεοῖς ἐχθρούς, οἳ περιενόστουν ἐν τῇ πόλει καταμεμιγμένοι τοῖς Συρακουσίοις πολυπραγμονοῦντες καὶ διαγγέλλοντες τῷ τυράννῳ τάς τε διανοίας καὶ τάς φωνὰς ἑκάστων, οὗτοι μὲν οὖν πρῶτοι δίκην ἐδίδοσαν ὑπὸ τῶν προστυγχανόντων ἀποτυμπανιζόμενοι Τιμοκράτης δὲ συμμῖξαι τοῖς φρουροῦσι τὴν ἀκρόπολιν μὴ δυνηθείς ἵππον λαβὼν διεξέπεσε τῆς πόλεως καὶ πάντα φεύγων ἐνέπλησε φόβου καὶ ταραχῆς, ἐπὶ μεῖζον αἴρων τὰ τοῦ Δίωνος, ὡς μὴ δοκοίη μέτριόν τι δείσας ἀποβεβληκέναι τὴν πόλιν. ἐν τούτῳ δὲ καὶ Δίων προσερχόμενος ἤδη καταφανὴς ἦν, πρῶτος αὐτὸς ὡπλισμένος λαμπρῶς, καὶ παρ’ αὐτὸν ἔνθεν μὲν ὁ ἀδελφὸς Μεγακλῆς, ἔνθεν δὲ Κάλλιππος ὁ Ἀθηναῖος, ἐστεφανωμένοι. τῶν δὲ ξένων ἑκατὸν μὲν εἵποντο φύλακες περὶ τὸν Δίωνα, τοὺς δ’ ἄλλους ἦγον οἱ λοχαγοὶ διακεκοσμημένους, θεωμένων τῶν Συρακουσίων καὶ δεχομένων ὥσπερ ἱεράν τινα καὶ θεοπρεπῆ πομπὴν ἐλευθερίας καὶ δημοκρατίας δι’ ἐτῶν ὀκτὼ καὶ τετταράκοντα κατιούσης εἰς τὴν πόλιν.", "st": "Dion 28.1"}, {"sp": "N", "t": "ἐπεὶ δὲ εἰσῆλθεν ὁ Δίων κατὰ τὰς Τεμενίτιδας πύλας, τῇ σάλπιγγι καταπαύσας τὸν θόρυβον, ἐκήρυξεν ὅτι Δίων καὶ Μεγακλῆς ἥκοντες ἐπὶ καταλύσει τῆς τυραννίδος ἐλευθεροῦσι Συρακουσίους καὶ τοὺς ἄλλους Σικελιώτας ἀπὸ τοῦ τυράννου. βουλόμενος δὲ καὶ δι’ ἑαυτοῦ προσαγορεῦσαι τοὺς ἀνθρώπους ἀνῄει διὰ τῆς Ἀχραδινῆς, ἑκατέρωθεν παρὰ τὴν ὁδὸν τῶν Συρακουσίων ἱερεῖα καὶ τραπέζας καὶ κρατῆρας ἱστάντων, καὶ καθ’ οὓς γένοιτο προχύταις τε βαλλόντων καὶ προστρεπομένων ὥσπερ θεὸν κατευχαῖς. ἦν δ’ ὑπὸ τὴν ἀκρόπολιν καὶ τὰ Πεντάπυλα, Διονυσίου κατασκευάσαντος, ἡλιοτρόπιον καταφανὲς καὶ ὑψηλόν. ἐπὶ τοῦτο προβὰς ἐδημηγόρησε καὶ παρώρμησε τοὺς πολίτας ἀντέχεσθαι τῆς ἐλευθερίας. οἱ δὲ χαίροντες καὶ φιλοφρονούμενοι κατέστησαν ἀμφοτέρους αὐτοκράτορας στρατηγούς, καὶ προσείλοντο, βουλομένων καὶ δεομένων ἐκείνων, αὐτοῖς συνάρχοντας εἴκοσιν, ὧν ἡμίσεις ἦσαν ἐκ τῶν μετὰ Δίωνος ἀπὸ τῆς φυγῆς συγκατερχομένων. τοῖς δὲ μάντεσιν αὖθις ἐδόκει τὸ μὲν ὑπὸ πόδας λαβεῖν τὸν Δίωνα δημηγοροῦντα τὴν φιλοτιμίαν καὶ τὸ ἀνάθημα τοῦ τυράννου λαμπρὸν εἶναι σημεῖον ὅτι δ’ ἡλιοτρόπιον ἦν ἐφ’ οὗ βεβηκὼς ᾑρέθη στρατηγός, ὠρρώδουν μὴ τροπήν τινα τῆς τύχης αἱ πράξεις ταχεῖαν λάβωσιν. ἐκ τούτου τὰς μὲν Ἐπιπολὰς ἑλὼν τοὺς καθειργμένους τῶν πολιτῶν ἔλυσε, τὴν δὲ ἀκρόπολιν ἀπετείχισεν. ἑβδόμῃ δ’ ἡμέρᾳ Διονύσιος κατέπλευσεν εἰς τὴν ἀκρόπολιν, καὶ Δίωνι προσῆγον ἅμαξαι πανοπλίας ἃς Συνάλῳ κατέλιπε. ταύτας διένειμε τοῖς πολίταις, τῶν δ’ ἄλλων ἕκαστος ἑαυτὸν, ὡς δυνατὸν ἦν, ἐκόσμει καὶ παρεῖχεν ὁπλίτην πρόθυμον.", "st": "Dion 29.1"}, {"sp": "N", "t": "Διονύσιος δὲ πρῶτον ἰδίᾳ πρὸς Δίωνα πρέσβεις ἔπεμπεν ἀποπειρώμενος· ἔπειτα κελεύσαντος ἐκείνου διαλέγεσθαι κοινῇ Συρακουσίοις ὡς ἐλευθέροις οὖσιν, ἐγένοντο λόγοι διὰ τῶν πρέσβεων παρὰ τοῦ τυράννου φιλάνθρωποι, φόρων ὑπισχνουμένου μετριότητα καὶ ῥᾳστώνην στρατειῶν, ὧν ἂν αὐτοὶ σύμψηφοι γένωνται. ταῦτα ἐχλεύαζον οἱ Συρακούσιοι. Δίων δ’ ἀπεκρίνατο τοῖς πρέσβεσι μὴ διαλέγεσθαι πρὸς αὐτοὺς Διονύσιον, εἰ μὴ τὴν ἀρχὴν ἀφίησιν ἀφέντι δὲ συμπράξειν ἄδειαν αὐτός, κἂν ἄλλο τι τῶν μετρίων δύνηται, μεμνημένος τῆς οἰκειότητος. ταῦτα Διονύσιος ἐπῄνει, καὶ πάλιν ἔπεμπε πρέσβεις κελεύων ἥκειν τινὰς εἰς τὴν ἀκρόπολιν τῶν Συρακουσίων, οἷς τὰ μὲν πείθων, τὰ δὲ πειθόμενος διαλέξεται περὶ τῶν κοινῇ συμφερόντων, ἐπέμφθησαν οὖν ἄνδρες πρὸς αὐτὸν οὓς Δίων ἐδοκίμασε. καὶ λόγος πολὺς ἐκ τῆς ἄκρας εἰς τούς Συρακουσίους κατῄει Διονύσιον ἀφήσειν τὴν τυραννίδα καὶ μᾶλλον ἑαυτοῦ ποιήσεσθαι χάριν ἢ Δίωνος.", "st": "Dion 30.1"}, {"sp": "N", "t": "ἦν δὲ δόλος ἡ προσποίησις αὕτη τοῦ τυράννου καὶ σκευωρία κατὰ τῶν Συρακουσίων, τούς μὲν γὰρ ἐλθόντας πρὸς αὐτὸν ἐκ τῆς πόλεως συγκλείσας εἶχε, τούς δὲ μισθοφόρους πρὸς ὄρθρον ἐμπλήσας ἀκράτου δρόμῳ πρὸς τὸ περιτείχισμα τῶν Συρακουσίων ἐφῆκε· γενομένης δὲ τῆς προσβολῆς ἀνελπίστου καὶ τῶν βαρβάρων θράσει πολλῷ καὶ θορύβῳ καθαιρούντων τὸ διατείχισμα καὶ τοῖς Συρακουσίοις ἐπιφερομένων, οὐδεὶς ἐτόλμα μένων ἀμύνεσθαι, πλὴν τῶν ξένων τῶν Δίωνος, οἳ πρῶτον αἰσθόμενοι τὸν θόρυβον ἐξεβοήθησαν. οὐδ’ οὗτοι δὲ τῆς βοηθείας τὸν τρόπον συνεφρόνουν οὐδ’ εἰσήκουον ὑπὸ κραυγῆς καὶ πλάνης τῶν φευγόντων Συρακουσίων ἀναπεφυρμένων αὐτοῖς καὶ διεκθεόντων, πρίν γε δὴ Δίων, ἐπεὶ λέγοντος οὐδεὶς κατήκουεν, ἔργῳ τὸ πρακτέον ὑφηγήσασθαι βουλόμενος ἐμβάλλει πρῶτος εἰς τούς βαρβάρους, καὶ γίνεται περὶ αὐτὸν ὀξεῖα καὶ δεινὴ μάχη, γινωσκόμενον οὐχ ἧττον ὑπὸ τῶν πολεμίων ἢ τῶν φίλων· ὥρμησαν γὰρ ἅμα πάντες ἐμβοήσαντες. ὁ δ’ ἦν μὲν ἤδη βαρύτερος δι’ ἡλικίαν ἢ κατὰ τοιούτους ἀγῶνας, ἀλκῇ δὲ καὶ θυμῷ τούς προσφερομένους ὑφιστάμενος καὶ ἀνακόπτων τιτρώσκεται λόγχῃ τὴν χεῖρα, πρὸς δὲ τὰ ἄλλα βέλη καὶ τὰς ἐκ χειρὸς πληγὰς μόλις ὁ θώραξ ἤρκεσε διὰ τῆς ἀσπίδος δόρασι πολλοῖς καὶ λόγχαις τυπτόμενος ὧν κατακλασθέντων κατέπεσεν ὁ Δίων. εἶτα ἀναρπασθεὶς ὑπὸ τῶν στρατιωτῶν ἐκείνοις μὲν ἡγεμόνα Τιμωνίδην ἐπέστησεν, αὐτὸς δὲ τὴν πόλιν ἵππῳ περιελαύνων τούς τε Συρακουσίους ἔπαυε φυγῆς, καὶ τῶν ξένων τούς φυλάττοντας τὴν Ἀχραδινὴν ἀναστήσας ἐπῆγε τοῖς βαρβάροις ἀκμῆτας ἐκπεπονημένοις καὶ προθύμους ἀπαυδῶσιν ἤδη πρὸς τὴν πεῖραν. ἐλπίσαντες γὰρ ἅμα τῇ πρώτῃ ῥύμῃ τὴν πόλιν ἅπασαν ἐξ ἐπιδρομῆς καθέξειν, εἶτα παρὰ δόξαν ἐντυγχάνοντες ἀνδράσι πλήκταις καὶ μαχίμοις ἀνεστέλλοντο πρὸς τὴν ἀκρόπολιν. ἔτι δὲ μᾶλλον, ὡς ἐνέδωκαν, ἐπικειμένων τῶν Ἑλλήνων τραπόμενοι κατεκλείσθησαν εἰς τὸ τεῖχος, ἑβδομήκοντα μὲν καὶ τέσσαρας ἀποκτείναντες τῶν μετὰ Δίωνος, ἑαυτῶν δὲ πολλοὺς ἀποβαλόντες,", "st": "Dion 30.5"}, {"sp": "N", "t": "γενομένης δὲ λαμπρᾶς τῆς νίκης οἱ μὲν Συρακούσιοι τοὺς ξένους ἑκατὸν μναῖς ἐστεφάνωσαν, οἱ δὲ ξένοι Δίωνα χρυσῷ στεφάνῳ. κήρυκες δὲ παρὰ τοῦ Διονυσίου κατέβαινον ἐπιστολὰς πρὸς Δίωνα παρὰ τῶν οἰκείων γυναικῶν κομίζοντες, μία δ’ ἦν ἔξωθεν ἐπιγεγραμμένη, τῷ πατρὶ, παρ’ Ἱππαρίνου· τοῦτο γὰρ ἦν ὄνομα τῷ Δίωνος υἱῷ. καίτοι φησὶ Τίμαιος Ἀρεταῖον αὐτὸν ἀπὸ τῆς μητρὸς Ἀρετῆς καλεῖσθαι· Τιμωνίδῃ δὲ μᾶλλον, ὡς οἴομαι, περί γε τούτων πιστευτέον, ἀνδρὶ φίλῳ καὶ συστρατιώτῃ Δίωνος. αἱ μὲν οὖν ἄλλαι τοῖς Συρακουσίοις ἀνεγνώσθησαν ἐπιστολαί πολλὰς ἱκεσίας καὶ δεήσεις ἔχουσαι παρὰ τῶν γυναικῶν, τὴν δὲ παρὰ τοῦ παιδὸς εἶναι δοκοῦσαν οὐκ ἐώντων φανερῶς λυθῆναι βιασάμενος ὁ Δίων ἔλυσεν. ἦν δὲ παρὰ τοῦ Διονυσίου, τοῖς μὲν γράμμασι πρὸς τὸν Δίωνα, τοῖς δὲ πράγμασι πρὸς τοὺς Συρακοσίους διαλεγομένου, σχῆμα μὲν ἔχουσα δεήσεως καὶ δικαιολογίας, συγκειμένη δὲ πρὸς διαβολὴν τοῦ Δίωνος, ὑπομνήσεις τε γὰρ ἦσαν ὧν ὑπὲρ τῆς τυραννίδος ἔπραξε προθύμως, καὶ κατὰ τῶν φιλτάτων ἀπειλαὶ σωμάτων, ἀδελφῆς καί τέκνου καὶ γυναικός, ἐπισκήψεις τε δειναὶ μετ’ ὀλοφυρμῶν, καί τὸ μάλιστα κινῆσαν αὐτόν, ἀξιοῦντος μὴ καθαιρεῖν, ἀλλὰ παραλαμβάνειν τὴν τυραννίδα, μηδ’ ἐλευθεροῦν μισοῦντας ἀνθρώπους καὶ μνησικακοῦντας, ἀλλ’ αὐτὸν ἄρχειν, παρέχοντα τοῖς φίλοις καὶ οἰκείοις τὴν ἀσφάλειαν.", "st": "Dion 31.1"}, {"sp": "N", "t": "ἀναγινωσκομένων δὲ τούτων οὐχ, ὅπερ ἦν δίκαιον, εἰσῄει τοὺς Συρακοσίους ἐκπλήττεσθαι τὴν ἀπάθειαν καὶ τὴν μεγαλοψυχίαν τοῦ Δίωνος ὑπὲρ τῶν καλῶν καὶ δικαίων ἀπισχυριζομένου πρὸς τοιαύτας οἰκειότητας, ἀλλ’ ὑποψίας καὶ φόβου λαβόντες ἀρχήν, ὡς μεγάλης οὔσης ἀνάγκης ἐκείνῳ φείδεσθαι τοῦ τυράννου, πρὸς ἑτέρους ἤδη προστάτας ἀπέβλεπον καὶ μάλιστα πυνθανόμενοι καταπλεῖν Ἡρακλείδην ἀνεπτοήθησαν. ἦν δὲ τῶν φυγάδων Ἡρακλείδης, στρατηγικὸς μέν ἄνθρωπος καὶ γνώριμος ἀφ’ ἡγεμονίας ἣν ἔσχε παρὰ τοῖς τυράννοις, οὐκ ἀραρὼς δὲ τὴν γνώμην, ἀλλὰ πρὸς πάντα κοῦφος, ἥκιστα δὲ βέβαιος ἐν κοινωνίᾳ πραγμάτων ἀρχὴν ἐχόντων καὶ δόξαν. οὗτος ἐν Πελοποννήσῳ πρὸς Δίωνα στασιάσας ἔγνω καθ’ αὑτὸν ἰδιόστολος πλεῖν ἐπὶ τὸν τύραννον, εἴς τε Συρακούσας ἀφικόμενος ἑπτὰ τριήρεσι καὶ τρισὶ πλοίοις Διονύσιον μέν αὖθις εὗρε περιτετειχισμένον, ἐπηρμένους δὲ τοὺς Συρακουσίους. εὐθὺς οὖν ὑπεδύετο τὴν τῶν πολλῶν χάριν, ἔχων μέν τι καὶ φύσει πιθανὸν καὶ κινητικὸν ὄχλου θεραπεύεσθαι ζητοῦντος, ὑπολαμβάνων δὲ καὶ μετάγων ῥᾷον αὐτούς, οἳ τὸ σεμνὸν τοῦ Δίωνος ὡς βαρὺ καὶ δυσπολίτευτον ἀπεστρέφοντο διὰ τὴν γεγενημένην ἐκ τοῦ κρατεῖν ἄνεσιν καὶ θρασύτητα, πρὸ τοῦ δῆμος εἶναι τὸ δημαγωγεῖσθαι θέλοντες.", "st": "Dion 32.1"}, {"sp": "N", "t": "καὶ πρῶτον μὲν εἰς ἐκκλησίαν ἀφ’ αὑτῶν συνδραμόντες εἵλοντο τὸν Ἡρακλείδην ναύαρχον. ἐπεὶ δὲ Δίων παρελθὼν ᾐτιᾶτο τὴν ἐκείνῳ διδομένην ἀρχὴν ἀφαίρεσιν εἶναι τῆς πρότερον αὐτῷ δεδομένης, οὐκέτι γὰρ αὐτοκράτωρ μένειν, ἂν ἄλλος ἡγῆται τῶν κατὰ θάλασσαν, ἄκοντες οἱ Συρακούσιοι πάλιν ἀπεψηφίσαντο τὸν Ἡρακλείδην. γενομένων δὲ τούτων μεταπεμψάμενος αὐτὸν ὁ Δίων οἴκαδε, καὶ μικρὰ μεμψάμενος, ὡς οὐ καλῶς οὐδὲ συμφερόντως ὑπὲρ δόξης στασιάζοντα πρὸς αὐτὸν ἐν καιρῷ ῥοπῆς ὀλίγης δεομένῳ πρὸς ἀπώλειαν, αὖθις ἐκκλησίαν αὐτὸς συναγαγών ναύαρχον ἀπέδειξε τὸν Ἡρακλείδην, καὶ τοῦ σώματος ἔπεισε φυλακὴν δοῦναι τοὺς πολίτας, ὥσπερ αὐτὸς εἶχεν. ὁ δὲ τῷ μὲν λόγῳ καὶ τῷ σχήματι τὸν Δίωνα θεραπεύων καὶ χάριν ὁμολογῶν ἔχειν παρηκολούθει ταπεινός, ὑπηρετῶν τὸ κελευόμενον, κρύφα δὲ τοὺς πολλοὺς καὶ νεωτεριστὰς διαφθείρων καὶ ὑποκινῶν, θορύβοις τὸν Δίωνα περιέβαλλεν, εἰς ἅπασαν ἀπορίαν καθιστάμενον. εἴτε γὰρ ἀφιέναι κελεύοι Διονύσιον ὑπόσπονδον ἐκ τῆς ἄκρας, διαβολὴν εἶχε φείδεσθαι καὶ περισῴζειν ἐκεῖνον, εἴτε λυπεῖν μὴ βουλόμενος ἐπὶ τῆς πολιορκίας ἡσυχάζοι, διατηρεῖν ἐδόκει τὸν πόλεμον, ὡς μᾶλλον ἄρχοι καὶ καταπλήττοιτο τοὺς πολίτας.", "st": "Dion 33.1"}, {"sp": "N", "t": "ἦν δέ τις Σῶσις, ἄνθρωπος ἐκ πονηρίας καὶ θρασύτητος εὐδοκιμῶν παρὰ τοῖς Συρακουσίοις, περιουσίαν ἡγουμένοις ἐλευθερίας τὸ μέχρι τοιούτων ἀνεῖσθαι τὴν παρρησίαν. οὗτος ἐπιβουλεύων Δίωνι πρῶτον μὲν ἐκκλησίας οὔσης ἀναστὰς πολλὰ τοὺς Συρακουσίους ἐλοιδόρησεν, εἰ μὴ συνιᾶσιν ὡς ἐμπλήκτου καὶ μεθυούσης ἀπηλλαγμένοι τυραννίδος ἐγρηγορότα καὶ νήφοντα δεσπότην εἰλήφασιν· ἔπειτα φανερὸν τοῦ Δίωνος ἐχθρὸν ἀναδείξας ἑαυτόν τότε μὲν ἐκ τῆς ἀγορᾶς ἀπῆλθε, τῇ δ’ ὑστεραίᾳ γυμνὸς ὤφθη διὰ τῆς πόλεως θέων ἀνάπλεως αἵματος τὴν κεφαλὴν καὶ τὸ πρόσωπον, ὡς δή τινας φεύγων διώκοντας. ἐμβαλὼν δὲ τοιοῦτος εἰς τὴν ἀγορὰν ἔλεγεν ὑπὸ τῶν ξένων τοῦ Δίωνος ἐπιβεβουλεῦσθαι, καὶ τὴν κεφαλὴν ἐπεδείκνυε τετρωμένην· καὶ πολλοὺς εἶχε τοὺς συναγανακτοῦντας καὶ συνισταμένους κατὰ τοῦ Δίωνος, ὡς δεινὰ καὶ τυραννικὰ πράττοντος, εἰ φόνοις καὶ κινδύνοις τῶν πολιτῶν ἀφαιρεῖται τὴν παρρησίαν. οὐ μὴν ἀλλὰ, καίπερ ἀκρίτου καὶ ταραχώδους ἐκκλησίας γενομένης, παρελθὼν ὁ Δίων ἀπελογεῖτο καὶ τὸν Σῶσιν ἀπέφαινε τῶν Διονυσίου δορυφόρων ἑνὸς ἀδελφὸν ὄντα καὶ δι’ ἐκείνου πεπεισμένον στασιάσαι καὶ συνταράξαι τὴν πόλιν, οὐδεμιᾶς Διονυσίῳ σωτηρίας οὔσης, πλὴν τῆς ἐκείνων ἀπιστίας καὶ διαφορᾶς πρὸς αὑτούς, ἅμα δ’ οἱ μὲν ἰατροὶ τοῦ Σώσιδος τὸ τραῦμα καταμανθάνοντες εὕρισκον ἐξ ἐπιπολῆς μᾶλλον ἢ καταφορᾶς γεγενημένον. αἱ μὲν γὰρ ὑπὸ ξίφους πληγαὶ μάλιστα τὸ μέσον ὑπὸ βάρους πιέζουσι, τὸ δὲ τοῦ Σώσιδος λεπτὸν ἦν διόλου καὶ πολλὰς εἶχεν ἀρχάς, ὡς εἰκὸς, ὑπ’ ἀλγηδόνος ἀνιέντος, εἶτα αὖθις ἐπάγοντος. ἧκον δέ τινες τῶν γνωρίμων ξυρὸν κομίζοντες εἰς τὴν ἐκκλησίαν, καὶ διηγούμενοι βαδίζουσιν αὐτοῖς καθ’ ὁδὸν ἀπαντῆσαι τὸν Σῶσιν ᾑμαγμένον καὶ λέγοντα φεύγειν τοὺς Δίωνος ξένους ὡς ἀρτίως ὑπ’ ἐκείνων τετρωμένος· εὐθὺς οὖν διώκοντες ἄνθρωπον μὲν οὐδένα λαβεῖν, ὑπὸ πέτραν δὲ κοίλην κείμενον ἰδεῖν ξυρὸν, ὅθεν ἐκεῖνος ὤφθη προσερχόμενος.", "st": "Dion 34.1"}, {"sp": "N", "t": "ἦν μὲν οὖν ἤδη μοχθηρὰ τὰ περὶ τὸν Σῶσιν προσγενομένων δὲ τούτοις τοῖς ἐλέγχοις οἰκετῶν καταμαρτυρούντων ὡς ἔτι νυκτὸς ἐξέλθοι μόνος ἔχων τὸ ξυρόν, οἵ τε κατηγοροῦντες τοῦ Δίωνος ὑπεχώρησαν ὅ τε δῆμος καταψηφισάμενος θάνατον τοῦ Σώσιδος διηλλάσσετο τῷ Δίωνι.", "st": "Dion 35.1"}, {"sp": "N", "t": "τοὺς δὲ μισθοφόρους οὐδὲν ἧττον ἐν ὑποψίαις εἶχον, καὶ μάλιστα τῶν πλείστων ἀγώνων πρὸς τὸν τύραννον ἤδη γινομένων κατὰ θάλατταν, ἐπειδὴ Φίλιστος ἧκεν ἐξ Ἰαπυγίας ἔχων πολλὰς τριήρεις Διονυσίῳ βοηθήσων, καὶ τῶν ξένων ὄντων ὁπλιτῶν οὐδεμίαν ἔτι χρῆσιν ἐνόμιζον εἶναι πρὸς τὸν πόλεμον, ἀλλὰ κἀκείνους ἐφ’ ἑαυτοῖς ἔσεσθαι ναυβάταις οὖσι καὶ τὸ κράτος ἐκ τῶν νεῶν κτωμένοις. ἔτι δὲ μᾶλλον αὐτοὺς ἐπῆρεν εὐτυχία τις γενομένη κατὰ θάλασσαν, ἐν ᾗ νικήσαντες τὸν Φίλιστον ὠμῶς καὶ βαρβαρικῶς αὐτῷ προσηνέχθησαν. Ἔφορος μὲν οὖν φησιν ὡς ἁλισκομένης τῆς νεὼς ἑαυτὸν ἀνέλοι, Τιμωνίδης δὲ πραττομέναις ἐξ ἀρχῆς ταῖς πράξεσι ταύταις μετὰ Δίωνος παραγενόμενος καὶ γράφων πρὸς Σπεύσιππον τὸν φιλόσοφον ἱστορεῖ ζῶντα ληφθῆναι τῆς τριήρους εἰς τὴν γῆν ἐκπεσούσης τὸν Φίλιστον· καὶ πρῶτον μὲν ἀποδύσαντας αὐτοῦ τὸν θώρακα τοὺς Συρακουσίους καὶ γυμνὸν ἐπιδειξαμένους τὸ σῶμα προπηλακίζειν ὄντος ἤδη γέροντος· ἔπειτα τὴν κεφαλὴν ἀποτεμεῖν καὶ τοῖς παισὶ παραδοῦναι τὸ σῶμα, κελεύσαντας ἕλκειν διὰ τῆς Ἀχραδινῆς καὶ καταβαλεῖν εἰς τὰς Λατομίας. ἔτι δὲ μᾶλλον ἐφυβρίζων ὁ Τίμαιος ἐκ τοῦ σκέλους φησὶ τοῦ χωλοῦ τὰ παιδάρια τὸν νεκρὸν ἐφαψάμενα τοῦ Φιλίστου σύρειν διὰ τῆς πόλεως· χλευαζόμενον ὑπὸ τῶν Συρακουσίων πάντων, ὁρώντων τοῦ σκέλους ἑλκόμενον τὸν εἰπόντα μὴ δεῖν ἐκ τυραννίδος φεύγειν Διονύσιον ἵππῳ ταχεῖ χρώμενον, ἀλλὰ τοῦ σκέλους ἑλκόμενον. καίτοι τοῦτο Φίλιστος, ὡς ὑφ’ ἑτέρου λεχθέν, οὐχ ὑφ’ αὑτοῦ, πρὸς Διονύσιον ἐξήγγελκεν.", "st": "Dion 35.2"}, {"sp": "N", "t": "ἀλλὰ Τίμαιος οὐκ ἄδικον λαβὼν πρόφασιν τὴν ὑπὲρ τῆς τυραννίδος τοῦ Φιλίστου σπουδὴν καὶ πίστιν ἐμπίπλαται τῶν κατ’ αὐτοῦ βλασφημιῶν, ᾧ τοὺς μὲν ἀδικηθέντας τότε συγγνωστόν ἐστιν ἴσως ἄχρι τῆς εἰς ἀναίσθητον ὀργῆς χαλεποὺς γενέσθαι, τοὺς δὲ ὕστερον συγγράφοντας τὰ πεπραγμένα καὶ τῷ μὲν βίῳ μὴ λυπηθέντας αὐτοῦ, τῷ δὲ λόγῳ χρωμένους, ἡ δόξα παραιτεῖται μὴ μεθ’ ὕβρεως μηδὲ μετὰ βωμολοχίας ὀνειδίζειν τὰς συμφοράς, ὢν οὐδὲν ἀπέχει καὶ τὸν ἄριστον ἀνδρῶν ἐκ τύχης μετασχεῖν. οὐ μὴν οὐδὲ Ἔφορος ὑγιαίνει τὸν Φίλιστον ἐγκωμιάζων, ὃς, καίπερ ὢν δεινότατος ἀδίκοις πράγμασι καὶ πονηροῖς ἤθεσιν εὐσχήμονας αἰτίας περιβαλεῖν καὶ λόγους ἔχοντας κόσμον ἐξευρεῖν, αὐτὸς αὑτὸν οὐ δύναται πάντα μηχανώμενος ἐξελέσθαι τῆς γραφῆς, ὡς οὐ φιλοτυραννότατος ἀνθρώπων γένοιτο καὶ μάλιστα πάντων ἀεὶ ζηλώσας καὶ θαυμάσας τρυφὴν καὶ δύναμιν καὶ πλούτους καὶ γάμους τοὺς τῶν τυράννων· ἀλλὰ γὰρ Φιλίστου μὲν ὁ μήτε τὰς πράξεις ἐπαινῶν μήτε τὰς τύχας ὀνειδίζων ἐμμελέστατος.", "st": "Dion 36.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν Φιλίστου τελευτὴν Διονύσιος ἔπεμπε πρὸς Δίωνα τὴν μὲν ἀκρόπολιν ἐκείνῳ παραδιδοὺς καὶ τὰ ὅπλα καὶ τοὺς μισθοφόρους καὶ πέντε μηνῶν ἐντελῆ τούτοις μισθόν, αὐτὸς δὲ ἀξιῶν ὑπόσπονδος εἰς Ἰταλίαν ἀπελθεῖν κἀκεῖ κατοικῶν καρποῦσθαι τῆς Συρακουσίας τὸν καλούμενον Γύαρτα, πολλὴν καὶ ἀγαθὴν χώραν ἀνήκουσαν ἀπὸ θαλάττης εἰς τὴν μεσόγειον. οὐ προσδεξαμένου δὲ τοῦ Δίωνος, ἀλλὰ δεῖσθαι τῶν Συρακουσίων κελεύσαντος, οἱ μὲν Συρακούσιοι ζῶντα λήψεσθαι τὸν Διονύσιον ἐλπίσαντες ἀπήλασαν τοὺς πρέσβεις, ἐκεῖνος δὲ τὴν μὲν ἄκραν Ἀπολλοκράτει, τῷ πρεσβυτέρῳ τῶν παίδων, παρέδωκεν, αὐτὸς δὲ πνεῦμα τηρήσας ἐπίφορον καὶ τὰ τιμιώτατα τῶν σωμάτων καὶ τῶν χρημάτων ἐνθέμενος εἰς τὰς ναῦς λαθὼν τὸν ναύαρχον Ἡρακλείδην ἐξέπλευσεν.", "st": "Dion 37.1"}, {"sp": "N", "t": "ὁ δὲ κακῶς ἀκούων καὶ θορυβούμενος ὑπὸ τῶν πολιτῶν Ἵππωνά τινα τῶν δημαγωγῶν καθίησι προκαλεῖσθαι τὸν δῆμον ἐπὶ γῆς ἀναδασμόν, ὡς ἐλευθερίας ἀρχὴν οὖσαν τὴν ἰσότητα, δουλείας δὲ τὴν πενίαν τοῖς ἀκτήμοσι. συνηγορῶν δὲ τούτῳ καὶ τὸν Δίωνα καταστασιάζων ἐναντιούμενον ἔπεισε τοὺς Συρακουσίους ταῦτά ψηφίσασθαι καὶ τῶν ξένων τὸν μισθὸν ἀποστερεῖν καὶ στρατηγοὺς ἑτέρους ἑλέσθαι, τῆς ἐκείνου βαρύτητος ἀπαλλαγέντας. οἱ δ’, ὥσπερ ἐκ μακρᾶς ἀρρωστίας τῆς τυραννίδος εὐθὺς ἐπιχειροῦντες ἐξανίστασθαι, καὶ πράττειν τὰ τῶν αὐτονομουμένων παρὰ καιρόν, ἐσφάλλοντο μὲν αὐτοὶ ταῖς πράξεσιν, ἐμίσουν δὲ τὸν Δίωνα βουλόμενον ὥσπερ ἰατρὸν ἐν ἀκριβεῖ καὶ σωφρονούσῃ διαίτῃ κατασχεῖν τὴν πόλιν.", "st": "Dion 37.5"}, {"sp": "N", "t": "ἐκκλησιάζουσι δ’ αὐτοῖς ἐπὶ νέαις ἀρχαῖς, θέρους μεσοῦντος, ἐξαίσιοι βρονταὶ καὶ διοσημίαι πονηραὶ συνέβαινον ἐφ’ ἡμέρας δεκαπέντε συνεχῶς, ἀνιστᾶσαι τὸν δῆμον ὑπὸ δεισιδαιμονίας κωλυόμενον ἑτέρους ἀποδεῖξαι στρατηγούς. ἐπεὶ δὲ φυλάξαντες εὐδίαν σταθερὰν οἱ δημαγωγοὶ συνετέλουν τὰς ἀρχαιρεσίας, βοῦς ἁμαξεὺς οὐκ ἀήθης οὐδ’ ἄπειρος ὄχλων, ἄλλως δέ πως τότε πρὸς τὸν ἐλαύνοντα θυμωθεὶς καὶ φυγὼν ἀπὸ τοῦ ζυγοῦ, δρόμῳ πρὸς τὸ θέατρον ὥρμησε· καὶ τὸν μὲν δῆμον εὐθὺς ἀνέστησε καὶ διεσκέδασεν οὐδενὶ κόσμῳ φεύγοντα, τῆς δ’ ἄλλης πόλεως ἐπέδραμε σκιρτῶν καὶ ταράττων ὅσον ὕστερον οἱ πολέμιοι κατέσχον. οὐ μὴν ἀλλὰ ταῦτα χαίρειν ἐάσαντες οἱ Συρακούσιοι πέντε καὶ εἴκοσι στρατηγοὺς ἐχειροτόνησαν, ὧν εἷς ἦν Ἡρακλείδης· καὶ τοὺς ξένους ὑποπέμποντες κρύφα τοῦ Δίωνος ἀφίστασαν καὶ μετεκάλουν πρὸς αὑτούς, ἐπαγγελλόμενοι καὶ τῆς πολιτείας ἰσομοιρίαν. οἱ δὲ ταῦτα μὲν οὐ προσεδέξαντο, τὸν δὲ Δίωνα πιστῶς καὶ προθύμως μετὰ τῶν ὅπλων ἀναλαβόντες καὶ συμφράξαντες ὑπῆγον ἐκ τῆς πόλεως, ἀδικοῦντες μὲν οὐδένα, πολλὰ δὲ τοὺς ἐντυγχάνοντας εἰς ἀχαριστίαν καὶ μοχθηρίαν ὀνειδίζοντες. οἱ δὲ τῆς ὀλιγότητος αὐτῶν καὶ τοῦ μὴ προεπιχειρεῖν καταφρονήσαντες, καὶ γενόμενοι πολὺ πλείους ἐκείνων, ἐφώρμησαν ὡς ῥᾳδίως ἐπικρατήσοντες ἐν τῇ πόλει καὶ πάντας αὐτοὺς κατακτενοῦντες.", "st": "Dion 38.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ γεγονὼς ἀνάγκης καὶ τύχης ὁ Δίων ἢ μάχεσθαι τοῖς πολίταις ἢ μετὰ τῶν ξένων ἀποθανεῖν, πολλὰ μὲν ἱκέτευεν ὀρέγων τὰς χεῖρας τοῖς Συρακουσίοις καὶ τὴν ἀκρόπολιν περίπλεων πολεμίων οὖσαν ὑπερφαινομένων τὰ τείχη καὶ τὰ γενόμενα καθορώντων ἐπιδεικνύμενος· ὡς δ’ ἦν ἀπαραίτητος ἡ τῶν πολλῶν φορά καὶ κατεῖχεν ὥσπερ ἐν πελάγει τὸ τῶν δημαγωγῶν πνεῦμα τὴν πόλιν, ἐμβολῆς μὲν ἀποσχέσθαι τοῖς ξένοις προσέταξεν, ὅσον δ’ ἐπιδραμόντων μετὰ βοῆς καὶ τοῖς ὅπλοις τιναξαμένων οὐδεὶς ἔμεινε τῶν Συρακουσίων, ἀλλ’ ᾤχοντο φεύγοντες ἀνὰ τὰς ἀγυιάς, οὐδενὸς ἐπιδιώκοντος· εὐθὺς γὰρ ἀπέστρεψεν ὁ Δίων τοὺς ξένους καὶ προῆγεν εἰς Λεοντίνους.", "st": "Dion 39.1"}, {"sp": "N", "t": "οἱ δ’ ἄρχοντες τῶν Συρακουσίων καταγέλαστοι γεγονότες ὑπὸ τῶν γυναικῶν, καὶ τὴν αἰσχύνην ἀναλαβεῖν ζητοῦντες, αὖθις ὁπλίσαντες τοὺς πολίτας ἐδίωκον τὸν Δίωνα, καὶ κατέλαβον μὲν ἐπὶ διαβάσει τινὸς ποταμοῦ καὶ προσίππευσαν ἁψιμαχοῦντες· ὡς δ’ ἑώρων οὐκέτι πρᾴως οὐδὲ πατρικῶς ὑπομένοντα τὰς ἁμαρτίας αὐτῶν, ἀλλὰ θυμῷ τοὺς ξένους ἐπιστρέφοντα καὶ παραταττόμενον, αἰσχίονα φυγὴν τῆς προτέρας φυγόντες ὑπεχώρησαν εἰς τὴν πόλιν, οὐ πολλῶν ἀποθανόντων.", "st": "Dion 39.3"}, {"sp": "N", "t": "Δίωνα δὲ Λεοντῖνοι λαμπραῖς ἐδέχοντο τιμαῖς, καὶ τοὺς ξένους ἀνελάμβανον μισθοῖς καὶ πολιτείαις πρὸς δὲ τοὺς Συρακουσίους ἐπρέσβευον ἀξιοῦντες τὰ δίκαια τοῖς ξένοις ποιεῖν. οἱ δὲ πρέσβεις ἔπεμψαν κατηγορήσοντας Δίωνος τῶν δὲ συμμάχων ἁπάντων εἰς Λεοντίνους ἁθροισθέντων καὶ γενομένων λόγων ἐν αὐτοῖς, ἔδοξαν ἀδικεῖν οἱ Συρακούσιοι· τοῖς δὲ κριθεῖσιν ὑπὸ τῶν συμμάχων οὐκ ἐνέμειναν τρυφῶντες ἤδη καὶ μεγαλοφρονοῦντες ἐπὶ τῷ μηδενὸς ἀκούειν, ἀλλὰ χρῆσθαι δουλεύουσι καὶ φοβουμένοις τὸν δῆμον στρατηγοῖς.", "st": "Dion 40.1"}, {"sp": "N", "t": "ἐκ τούτου καταπλέουσιν εἰς τὴν πόλιν παρὰ Διονυσίου τριήρεις Νύψιον ἄγουσαι τὸν Νεαπολίτην, σῖτον καὶ χρήματα κομίζοντα τοῖς πολιορκουμένοις. γενομένης δὲ ναυμαχίας ἐνίκων μὲν οἱ Συρακούσιοι καὶ τέσσαρας τῶν τυραννικῶν νεῶν ἔλαβον, ὑβρίσαντες δὲ τῇ νίκῃ, καὶ δι’ ἀναρχίαν τὸ χαῖρον εἰς πότους καὶ συνουσίας μανικὰς τρέψαντες, οὕτω τῶν χρησίμων ἠμέλησαν ὥστε τὴν ἀκρόπολιν ἔχειν δοκοῦντες ἤδη καὶ τὴν πόλιν προσαπέβαλον. ὁ γὰρ Νύψιος ὁρῶν οὐδὲν ὑγιαῖνον ἐν τῇ πόλει μέρος, ἀλλὰ τὸν μὲν ὄχλον αὐλήμασι καὶ μέθαις εἰς νύκτα βαθεῖαν ἀφ’ ἡμέρας κατεχόμενον, τοὺς δὲ στρατηγοὺς ἐπιτερπομένους τε τούτῳ τῷ πανηγυρισμῷ καὶ προσάγειν ἀνάγκην μεθύουσιν ἀνθρώποις ὀκνοῦντας, ἄριστα τῷ καιρῷ χρησάμενος ἐπεχείρησε τῷ τειχίσματι καὶ κρατήσας καὶ διαθρύψας ἐφῆκε τοὺς βαρβάρους, κελεύσας χρῆσθαι τοῖς προστυγχάνουσιν ὡς βούλονται καὶ δύνανται. ταχέως μὲν οὖν οἱ Συρακούσιοι τὸ κακὸν ᾔσθοντο, βραδέως δὲ καὶ χαλεπῶς συνεβοήθουν ἐκπεπληγμένοι. πόρθησις γὰρ ἦν τὰ γινόμενα τῆς πόλεως, τῶν μὲν ἀνδρῶν φονευομένων, τῶν δὲ τειχῶν κατασκαπτομένων, γυναικῶν δὲ καὶ παίδων ἀγομένων εἰς τὴν ἀκρόπολιν μετ’ οἰμωγῆς, ἀπεγνωκότων δὲ τὰ πράγματα τῶν στρατηγῶν καὶ χρῆσθαι μὴ δυναμένων τοῖς πολίταις πρὸς τοὺς πολεμίους ἀναπεφυρμένους καὶ συμμεμιγμένους αὐτοῖς πανταχόθεν.", "st": "Dion 41.1"}, {"sp": "N", "t": "οὕτω δὲ τῶν κατὰ τὴν πόλιν ἐχόντων καὶ τοῦ κινδύνου πρὸς τὴν Ἀχραδινὴν πλησιάζοντος, εἰς ὃν μόνον ἦν καὶ λοιπὸν ἀπερείσασθαι τὴν ἐλπίδα πάντες μὲν ἐφρόνουν, ἔλεγε δὲ οὐδείς, αἰσχυνόμενοι τὴν ἀχαριστίαν καὶ τὴν ἀβουλίαν τὴν πρὸς Δίωνα. πλήν γε δὴ τῆς ἀνάγκης ἐκβιαζομένης παρὰ τῶν συμμάχων καὶ τῶν ἱππέων γίνεται φωνὴ καλεῖν Δίωνα καὶ μεταπέμπεσθαι τοὺς Πελοποννησίους ἐκ Λεοντίνων. ὡς δὲ πρῶτον ἠκούσθη καὶ ἀπετολμήθη τοῦτο, κραυγὴ καὶ χαρὰ καὶ δάκρυα τοὺς Συρακουσίους κατεῖχεν εὐχομένους ἐπιφανῆναι τὸν ἄνδρα καὶ ποθοῦντας τὴν ὄψιν αὐτοῦ καὶ μεμνημένους τῆς παρὰ τὰ δεινὰ ῥώμης καὶ προθυμίας, ὡς οὐ μόνον αὐτὸς ἦν ἀνέκπληκτος, ἀλλὰ κἀκείνους παρεῖχε θαρροῦντας καὶ ἀδεῶς τοῖς πολεμίοις συμφερομένους. εὐθὺς οὖν ἐκπέμπουσι πρὸς αὐτὸν ἀπὸ μὲν τῶν συμμάχων Ἀρχωνίδην καὶ Τελεσίδην, ἀπὸ δὲ τῶν ἱππέων πέντε τοὺς περὶ Ἑλλάνικον. οὗτοι διελάσαντες τὴν ὁδὸν ἵπποις ἀπὸ ῥυτῆρος ἧκον εἰς Λεοντίνους τῆς ἡμέρας ἤδη καταφερομένης. ἀποπηδήσαντες δὲ τῶν ἵππων καὶ τῷ Δίωνι πρώτῳ προσπεσόντες δεδακρυμένοι τὰς συμφορὰς τῶν Συρακοσίων ἔφραζον. ἤδη δὲ καὶ τῶν Λεοντίνων τινὲς ἀπήντων καὶ τῶν Πελοποννησίων ἡθροίζοντο πρὸς τὸν Δίωνα πολλοί, τῇ σπουδῇ καὶ τῇ δεήσει τῶν ἀνδρῶν ὑπονοοῦντες εἶναί τι καινότερον. εὐθὺς οὖν ἡγεῖτο πρὸς τὴν ἐκκλησίαν αὐτοῖς, καὶ συνδραμόντων προθύμως οἱ περὶ τὸν Ἀρχωνίδην καὶ τὸν Ἑλλάνικον εἰσελθόντες ἐξήγγειλάν τε βραχέως τὸ μέγεθος τῶν κακῶν, καὶ παρεκάλουν τοὺς ξένους ἐπαμῦναι τοῖς Συρακουσίοις, τὸ μνησικακεῖν ἀφέντας, ὡς μείζονα δίκην δεδωκότων αὐτῶν ἢ λαβεῖν ἂν οἱ κακῶς πεπονθότες ἠξίωσαν.", "st": "Dion 42.1"}, {"sp": "N", "t": "παυσαμένων δὲ τούτων σιγὴ μὲν εἶχε πολλὴ τὸ θέατρον ἀναστάντος δὲ τοῦ Δίωνος καὶ λέγειν ἀρξαμένου πολλὰ τῶν δακρύων ἐκπίπτοντα τὴν φωνὴν ἐπέσχεν· οἱ δὲ ξένοι παρεκάλουν θαρρεῖν καὶ συνήχθοντο. μικρὸν οὖν ἀναλαβὼν ἐκ τοῦ πάθους ἑαυτὸν ὁ Δίων, ἄνδρες, ἔφη, Πελοποννήσιοι καὶ σύμμαχοι, βουλευσομένους ὑμᾶς ἐνταῦθα περὶ ὑμῶν αὐτῶν συνήγαγον. ἐμοὶ δὲ περὶ ἐμαυτοῦ βουλεύεσθαι καλῶς οὐκ ἔχει Συρακουσῶν ἀπολλυμένων, ἀλλ’ εἰ σῶσαι μὴ δυναίμην, ἄπειμι τῷ πυρὶ καὶ τῷ πτώματι τῆς πατρίδος ἐνταφησόμενος. ὑμεῖς δέ, βουλόμενοι μὲν ἔτι καὶ νῦν βοηθεῖν τοῖς ἀβουλοτάτοις ἡμῖν καὶ δυστυχεστάτοις, ὑμέτερον ἔργον οὖσαν ὀρθοῦτε τὴν Συρακουσίων πόλιν· εἰ δὲ μεμφόμενοι Συρακουσίοις ὑπερόψεσθε, τῆς γε πρότερον ἀρετῆς καὶ προθυμίας περὶ ἐμὲ χάριν ἀξίαν κομίζοισθε παρὰ τῶν θεῶν, μεμνημένοι Δίωνος, ὡς οὔθ’ ὑμᾶς ἀδικουμένους πρότερον οὔθ’ ὕστερον τοὺς πολίτας δυστυχοῦντας ἐγκαταλιπόντος.", "st": "Dion 43.1"}, {"sp": "N", "t": "ἔτι δ’ αὐτοῦ λέγοντος οἱ μὲν ξένοι μετὰ κραυγῆς ἀνεπήδησαν ἄγειν καὶ βοηθεῖν κατὰ τάχος κελεύοντες, οἱ δὲ πρέσβεις τῶν Συρακουσίων περιβαλόντες ἠσπάσαντο πολλὰ μὲν ἐκείνῳ, πολλὰ δὲ τοῖς ξένοις ἀγαθὰ παρὰ τῶν θεῶν εὐχόμενοι. καταστάντος δὲ τὸν θορύβου παρήγγειλεν ὁ Δίων εὐθὺς ἀπιόντας παρασκευάζεσθαι καὶ δειπνήσαντας ἥκειν μετὰ τῶν ὅπλων εἰς αὐτὸν ἐκεῖνον τὸν τόπον, ἐγνωκὼς διὰ νυκτὸς βοηθεῖν.", "st": "Dion 43.6"}, {"sp": "N", "t": "ἐν δὲ ταῖς Συρακούσαις τῶν Διονυσίου στρατηγῶν, ἄχρι μὲν ἦν ἡμέρα, πολλὰ κακὰ τὴν πόλιν ἐργασαμένων, γενομένης δὲ νυκτὸς ἀναχωρησάντων εἰς τὴν ἀκρόπολιν καί τινας ἐξ ἑαυτῶν ὀλίγους ἀποβαλόντων, ἀναθαρρήσαντες οἱ δημαγωγοὶ τῶν Συρακουσίων, καί τοὺς πολεμίους ἐλπίσαντες ἀτρεμήσειν ἐπὶ τοῖς διαπεπραγμένοις, παρεκάλουν τοὺς πολίτας αὖθις ἐᾶν Δίωνα, κἂν προσίῃ μετὰ τῶν ξένων, μὴ δέχεσθαι μηδὲ παραχωρεῖν τῆς ἀρετῆς ἐκείνοις ὡς κρείττοσιν, ἀλλὰ σῴζειν τὴν πόλιν καί τὴν ἐλευθερίαν αὐτοὺς δι’ ἑαυτῶν. πάλιν οὖν ἐπέμποντο πρὸς τὸν Δίωνα, παρὰ μὲν τῶν στρατηγῶν ἀποτρέποντες, παρὰ δὲ τῶν ἱππέων καί τῶν γνωρίμων πολιτῶν ἐπισπεύδοντες τὴν πορείαν. καί διὰ τοῦτο βραδέως ἅμα καί κατὰ σπουδὴν πορευόμενος προσῄει. τῆς δὲ νυκτὸς προελθούσης οἱ μὲν μισοῦντες τὸν Δίωνα κατεῖχον τὰς πύλας ὡς ἀποκλείσοντες αὐτόν, ὁ δὲ Νύψιος, ἐκ τῆς ἄκρας αὖθις πολλῷ προθυμοτέρους γεγονότας καί πλείονας ἐφιεὶς τοὺς μισθοφόρους, τὸ μὲν προτείχισμα πᾶν εὐθὺς κατέσκαπτε, τὴν δὲ πόλιν κατέτρεχε καί διήρπαζεν. ἦν δὲ φόνος μὲν οὐκέτι μόνον ἀνδρῶν, ἀλλὰ καί γυναικῶν καὶ παίδων, ἁρπαγαὶ δ’ ὀλίγαι, φθόρος δὲ πάντων πολύς. ἀπεγνωκότος γὰρ ἤδη τὰ πράγματα τὸν Διονυσίου καί τοὺς Συρακουσίους δεινῶς μεμισηκότος, ὥσπερ ἐνταφιάσαι τὴν τυραννίδα τῇ πόλει πίπτουσαν ἐβούλετο. καί τοῦ Δίωνος προκαταλαμβάνοντες τὴν βοήθειαν ἐπὶ τὸν ὀξύτατον διὰ πυρὸς πάντων ὄλεθρον καί ἀφανισμὸν ἐχώρησαν, τὰ μὲν ἐγγὺς ἀπὸ χειρῶν δᾳσὶ καί λαμπάσιν ὑποπιμπράντες, εἰς δὲ τὰ πρόσω διασπείροντες ἀπὸ τόξων πυροβόλους. φευγόντων δὲ τῶν Συρακουσίων οἱ μὲν ἐν ταῖς ὁδοῖς ἐφονεύοντο καταλαμβανόμενοι, τὸ δὲ εἰς τὰς οἰκίας καταδυόμενον αὖθις ὑπὸ τοῦ πυρὸς ἐξέπιπτε, πολλῶν ἤδη φλεγομένων καί καταφερομένων ἐπὶ τοὺς διαθέοντας.", "st": "Dion 44.1"}, {"sp": "N", "t": "τοῦτο τὸ πάθος μάλιστα τὴν πόλιν ἀνέῳξε Δίωνι πάντων συμφωνησάντων. ἔτυχε μὲν γὰρ οὐκέτι σπουδῇ πορευόμενος, ὡς ἤκουσεν εἰς τὴν ἀκρόπολιν κατακεκλεῖσθαι τοὺς πολεμίους. προϊούσης δὲ τῆς ἡμέρας πρῶτον ἱππεῖς ἀπήντησαν αὐτῷ τὴν δευτέραν κατάληψιν ἀπαγγέλλοντες· ἔπειτα καὶ τῶν ὑπεναντιουμένων ἔνιοι παρῆσαν ἐπείγεσθαι δεόμενοι. συντείνοντος δὲ τοῦ κακοῦ μᾶλλον Ἡρακλείδης τὸν ἀδελφὸν ἐξέπεμψεν, εἶτα Θεοδότην τὸν θεῖον, ἱκετεύων ἀρήγειν, ὡς μηδενὸς ἀντέχοντος τοῖς πολεμίοις, αὐτοῦ δὲ τετρωμένου, τῆς δὲ πόλεως μικρὸν ἀπεχούσης ἀνατετράφθαι καὶ καταπεπρῆσθαι. τοιούτων ἀγγελμάτων τῷ Δίωνι προσπεσόντων ἔτι μὲν ἑξήκοντα σταδίους τῶν πυλῶν ἀπεῖχε· φράσας δὲ τὸν κίνδυνον τοῖς ξένοις καὶ παρακελευσάμενος οὐκέτι βάδην ἦγεν, ἀλλὰ δρόμῳ τὸ στράτευμα πρὸς τὴν πόλιν, ἄλλων ἐπ’ ἄλλοις ἀντιαζόντων καὶ δεομένων ἐπείγεσθαι. χρησάμενος δὲ θαυμαστῷ τάχει καὶ προθυμίᾳ τῶν ξένων εἰσέβαλε διὰ τῶν πυλῶν εἰς τὴν Ἑκατόμπεδον λεγομένην· καὶ τοὺς μὲν ἐλαφροὺς εὐθὺς ἀφῆκεν ἐλθεῖν πρὸς τοὺς πολεμίους, ὡς ἰδοῦσι θαρσῆσαι τοῖς Συρακουσίοις ἐγγένοιτο, τοὺς δ’ ὁπλίτας αὐτὸς συνέταττε καὶ τῶν πολιτῶν τοὺς ἐπιρρέοντας καὶ συνισταμένους, ὀρθίους λόχους ποιῶν καὶ διαιρῶν τὰς ἡγεμονίας, ὅπως πολλαχόθεν ἅμα προσφέροιτο φοβερώτερον.", "st": "Dion 45.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ταῦτα παρασκευασάμενος καὶ τοῖς θεοῖς προσευξάμενος ὤφθη διὰ τῆς πόλεως ἄγων ἐπὶ τοὺς πολεμίους, κραυγῇ καὶ χαρὰ καὶ πολὺς ἀλαλαγμὸς εὐχαῖς ὁμοῦ καὶ παρακλήσεσι μεμιγμένος ἐγίνετο παρὰ τῶν Συρακουσίων, τὸν μὲν Δίωνα σωτῆρα καὶ θεὸν ἀποκαλούντων, τοὺς δὲ ξένους ἀδελφοὺς καὶ πολίτας. οὐδεὶς δὲ φίλαυτος οὕτως ἦν καὶ φιλόψυχος παρὰ τὸν τότε καιρόν ὃς οὐ μᾶλλον ὑπὲρ μόνου Δίωνος ἢ τῶν ἄλλων ἁπάντων ἀγωνιῶν ἐφαίνετο, πρώτου πρὸς τὸν κίνδυνον πορευομένου δι’ αἵματος καὶ πυρὸς καὶ νεκρῶν πολλῶν κειμένων ἐν ταῖς πλατείαις.", "st": "Dion 46.1"}, {"sp": "N", "t": "ἦν μὲν οὖν καὶ τὰ παρὰ τῶν πολεμίων φοβερά παντάπασιν ἀπηγριωμένων καὶ παρατεταγμένων παρὰ τὸ τείχισμα χαλεπὴν ἔχον καὶ δυσεκβίαστον τὴν πρόσοδον ὁ δ’ ἐκ τοῦ πυρὸς κίνδυνος ἐτάραττε μᾶλλον τοὺς ξένους καὶ δύσεργον ἐποίει τὴν πορείαν. κύκλῳ γὰρ ὑπὸ τῆς φλογὸς περιελάμποντο τὰς οἰκίας περινεμομένης· καὶ διαπύροις ἐπιβαίνοντες ἐρειπίοις καὶ καταφερομένοις ἀπορρήγμασι μεγάλοις ὑποτρέχοντες ἐπισφαλῶς, καὶ πολὺν ὁμοῦ καπνῷ διαπορευόμενοι κονιορτόν, ἐπειρῶντο συνέχειν καὶ μὴ διασπᾶν τὴν τάξιν. ὡς δὲ προσέμιξαν τοῖς πολεμίοις, ἐν χερσὶ μὲν ὀλίγων πρὸς ὀλίγους ἐγίνετο μάχη διὰ τὴν στενότητα καὶ τὴν ἀνωμαλίαν τοῦ τόπου, κραυγῇ δὲ καὶ προθυμίᾳ τῶν Συρακουσίων ἐπιρρωσάντων ἐβιάσθησαν οἱ περὶ τὸν Νύψιον. καὶ τὸ μὲν πλεῖστον αὐτῶν εἰς τὴν ἀκρόπολιν ἐγγὺς οὖσαν ἀναφεῦγον ἐσῴζετο· τοὺς δ’ ἀπολειφθέντας ἔξω καὶ διασπαρέντας ἀνῄρουν οἱ ξένοι διώκοντες. ἀπόλαυσιν δὲ τῆς νίκης ἐν τῷ παραυτίκα καὶ χαρὰν καὶ περιβολὰς ἔργῳ τηλικούτῳ πρεπούσας οὐ παρέσχεν ὁ καιρός, ἐπὶ τὰς οἰκίας τραπομένων τῶν Συρακουσίων καὶ τὸ πῦρ μόλις ἐν τῇ νυκτὶ κατασβεσάντων.", "st": "Dion 46.3"}, {"sp": "N", "t": "ἡμέρα δ’ ὡς ἦν, τῶν μὲν ἄλλων οὐδεὶς ὑπέμεινε δημαγωγῶν, ἀλλὰ καταγνόντες ἑαυτῶν ἔφυγον, Ἡρακλείδης δὲ καὶ Θεοδότης αὐτοὶ κομίσαντες ἑαυτοὺς τῷ Δίωνι παρέδωκαν, ἀδικεῖν ὁμολογοῦντες καὶ δεόμενοι βελτίονος ἐκείνου τυχεῖν γεγόνασιν αὐτοὶ περὶ ἐκεῖνον· πρέπειν δὲ Δίωνι τήν ἄλλην ἅπασαν ἀρετὴν ἀσύγκριτον ἔχοντι καὶ πρὸς ὀργὴν κρείττονι φανῆναι τῶν ἠγνωμονηκότων, οἳ περὶ οὗ πρότερον ἐστασίασαν πρὸς αὐτόν νῦν ἥκουσιν ἡττᾶσθαι τῆς ἀρετῆς ὁμολογοῦντες. ταῦτα τῶν περὶ τὸν Ἡρακλείδην δεομένων οἱ μὲν φίλοι παρεκελεύοντο τῷ Δίωνι μὴ φείδεσθαι κακῶν καὶ βασκάνων ἀνθρώπων, ἀλλὰ καὶ τοῖς στρατιώταις χαρίσασθαι τὸν Ἡρακλείδην καὶ τοῦ πολιτεύματος ἐξελεῖν δημοκοπίαν, ἐπιμανὲς νόσημα, τυραννίδος οὐκ ἔλαττον. ὁ δὲ Δίων παραμυθούμενος αὐτοὺς ἔλεγεν ὡς τοῖς μὲν ἄλλοις στρατηγοῖς πρὸς ὅπλα καὶ πόλεμον ἡ πλείστη τῆς ἀσκήσεώς ἐστιν, αὐτῷ δὲ πολὺν χρόνον ἐν Ἀκαδημείᾳ μεμελέτηται θυμοῦ περιεῖναι καὶ φθόνου καὶ φιλονεικίας πάσης· ὧν ἐπίδειξίς ἐστιν οὐχ ἡ πρὸς φίλους καὶ χρηστοὺς μετριότης, ἀλλ’ εἴ τις ἀδικούμενος εὐπαραίτητος εἴη καὶ πρᾷος τοῖς ἁμαρτάνουσι· βούλεσθαι δ’ Ἡρακλείδου μὴ τοσοῦτον δυνάμει καὶ φρονήσει κρατῶν ὅσον χρηστότητι καὶ δικαιοσύνῃ φανῆναι· τὸ γὰρ ἀληθῶς βέλτιον ἐν τούτοις· αἱ δὲ τοῦ πολέμου κατορθώσεις, εἰ καὶ ἀνθρώπων μηδένα, τήν γε τύχην διαμφισβητοῦσαν ἔχουσιν. εἰ δ’ Ἡρακλείδης ἄπιστος καὶ κακὸς διὰ φθόνον, οὔ τοι καὶ Δίωνα δεῖν θυμῷ διαφθεῖραι τήν ἀρετήν· τὸ γὰρ ἀντιτιμωρεῖσθαι τοῦ προαδικεῖν νόμῳ δικαιότερον ὡρίσθαι, φύσει γινόμενον ἀπὸ μιᾶς ἀσθενείας. ἀνθρώπου δὲ κακίαν, εἰ καὶ χαλεπόν ἐστιν, οὐχ οὕτως ἄγριον εἶναι παντάπασι καὶ δύσκολον ὥστε μὴ μεταβάλλειν χάριτι νικηθεῖσαν ὑπὸ τῶν πολλάκις εὖ ποιούντων.", "st": "Dion 47.1"}, {"sp": "N", "t": "τοιούτοις χρησάμενος λογισμοῖς ὁ Δίων ἀφῆκε τοὺς περὶ τὸν Ἡρακλείδην. τραπόμενος δὲ πρὸς τὸ διατείχισμα, τῶν μὲν Συρακουσίων ἕκαστον ἐκέλευσεν ἕνα κόψαντα σταυρὸν ἐγγὺς καταβάλλειν, τοὺς δὲ ξένους ἐπιστήσας διὰ νυκτός, ἀναπαυομένων τῶν Συρακουσίων, ἔλαθεν ἀποσταυρώσας τὴν ἀκρόπολιν, ὥστε μεθ’ ἡμέραν τὸ τάχος καὶ τὴν ἐργασίαν θεασαμένους ὁμοίως θαυμάζειν τοὺς πολίτας καὶ τοὺς πολεμίους. θάψας δὲ τοὺς τεθνηκότας τῶν Συρακουσίων καὶ λυσάμενος τοὺς ἑαλωκότας, δισχιλίων οὐκ ἐλάττονας ὄντας, ἐκκλησίαν συνήγαγε. καὶ παρελθὼν Ἡρακλείδης εἰσηγήσατο γνώμην αὐτοκράτορα στρατηγὸν ἑλέσθαι Δίωνα κατὰ γῆν καὶ θάλασσαν. ἀποδεξαμένων δὲ τῶν ἀρίστων καὶ χειροτονεῖν κελευόντων ἐθορύβησεν ὁ ναυτικὸς ὄχλος καὶ βάναυσος, ἀχθόμενος ἐκπίπτοντι τῆς ναυαρχίας τῷ Ἡρακλείδῃ, καὶ νομίζων αὐτόν, εἰ καὶ τἆλλα μηδενὸς ἄξιός ἐστι, δημοτικώτερόν γε πάντως εἶναι τοῦ Δίωνος καὶ μᾶλλον ὑπὸ χεῖρα τοῖς πολλοῖς. ὁ δὲ Δίων τοῦτο μὲν ἐφῆκεν αὐτοῖς καὶ τὴν κατὰ θάλατταν ἀρχὴν ἀπέδωκε τῷ Ἡρακλείδῃ, πρὸς δὲ τῆς γῆς καὶ τῶν οἰκιῶν τὸν ἀναδασμὸν ὡρμημένοις ἐναντιωθείς καὶ τὰ πρότερον ψηφισθέντα περὶ τούτων ἀκυρώσας ἐλύπησεν. ὅθεν εὐθὺς ἑτέραν ἀρχὴν λαβὼν ὁ Ἡρακλείδης τοὺς συνεκπλεύσαντας μετ’ αὐτοῦ στρατιώτας καὶ ναύτας ἐν Μεσσήνῃ καθήμενος ἐδημαγώγει καὶ παρώξυνε κατὰ τοῦ Δίωνος ὡς τυραννεῖν μέλλοντος· αὐτὸς δὲ πρὸς Διονύσιον ἐποιεῖτο συνθήκας κρύφα διὰ Φάρακος τοῦ Σπαρτιάτου. καὶ τοῦτο τῶν γνωριμωτάτων Συρακουσίων ὑπονοησάντων, στάσις ἦν ἐν τῷ στρατοπέδῳ καὶ δι’ αὐτὴν ἀπορία καὶ σπάνις ἐν ταῖς Συρακούσαις, ὥστε παντάπασιν ἀμηχανεῖν τὸν Δίωνα καὶ κακῶς ἀκούειν ὑπὸ τῶν φίλων οὕτω δυσμεταχείριστον ἄνθρωπον καὶ διεφθαρμένον ὑπὸ φθόνου καὶ πονηρίας αὐξήσαντα καθ’ αὑτοῦ τὸν Ἡρακλείδην.", "st": "Dion 48.1"}, {"sp": "N", "t": "Φάρακος δὲ πρὸς Νέᾳ πόλει τῆς Ἀκραγαντίνης στρατοπεδεύοντος, ἐξαγαγὼν τοὺς Συρακουσίους ἐβούλετο μὲν ἐν ἑτέρῳ καιρῷ διαγωνίσασθαι πρὸς αὐτόν, Ἡρακλείδου δὲ καὶ τῶν ναυτῶν καταβοώντων ὡς οὐ βούλεται μάχῃ κρῖναι τὸν πόλεμον Δίων, ἀλλ’ ἀεὶ μένοντος ἄρχειν, ἀναγκασθεὶς συνέβαλε καὶ ἡττήθη. γενομένης δὲ τῆς τροπῆς οὐ βαρείας, ἀλλὰ μᾶλλον ὑφ’ ἑαυτῶν καὶ τοῦ στασιάζειν ταραχθέντων, αὖθις ὁ Δίων παρεσκευάζετο μάχεσθαι καὶ συνέταττε πείθων καὶ παραθαρρύνων. τῆς δὲ νυκτὸς ἀρχομένης ἀγγέλλεται πρὸς αὐτὸν Ἡρακλείδην ἄραντα τὸν στόλον πλεῖν ἐπὶ Συρακουσῶν, ἐγνωκότα τὴν πόλιν καταλαβεῖν κἀκεῖνον ἀποκλεῖσαι μετὰ τοῦ στρατεύματος, εὐθὺς οὖν ἀναλαβὼν τοὺς δυνατωτάτους καὶ προθυμοτάτους ἱππάσατο διὰ τῆς νυκτός· καὶ περὶ τρίτην ὥραν τῆς ἡμέρας πρὸς ταῖς πύλαις ἦν, σταδίους κατηνυκὼς ἑπτακοσίους. Ἡρακλείδης δὲ ταῖς ναυσὶν, ὡς ἁμιλλώμενος ὑστέρησεν, ἀποπλεύσας καὶ πλανώμενος ἐν ταῖς πράξεσιν ἀσκόπως ἐπιτυγχάνει Γαισύλῳ τῷ Σπαρτιάτῃ, φάσκοντι πλεῖν ἐφ’ ἡγεμονίᾳ Σικελιωτῶν ἐκ Λακεδαίμονος, ὡς πρότερόν ποτε Γύλιππος. ἄσμενος οὖν ἀναλαβὼν τοῦτον τὸν ἄνδρα καὶ περιαψάμενος ὥσπερ ἀλεξιφάρμακον τοῦ Δίωνος ἐπεδείκνυτο τοῖς συμμάχοις· καὶ κήρυκα πέμπων εἰς τὰς Συρακούσας ἐκέλευε δέχεσθαι τὸν Σπαρτιάτην ἄρχοντα τοὺς πολίτας. ἀποκριναμένου δὲ τοῦ Δίωνος ὡς εἰσὶν ἄρχοντες ἱκανοὶ τοῖς Συρακουσίοις, εἰ δὲ πάντως δέοι καὶ Σπαρτιάτου τοῖς πράγμασιν, αὐτὸς οὗτος εἶναι, κατὰ ποίησιν γεγονὼς Σπαρτιάτης, τὴν μὲν ἀρχὴν ὁ Γαίσυλος ἀπέγνω, πλεύσας δὲ πρὸς τὸν Δίωνα διήλλαξε τὸν Ἡρακλείδην ὅρκους δόντα καὶ πίστεις τὰς μεγίστας, αἷς αὐτὸς ὁ Γαισύλος ὤμοσε τιμωρὸς ἔσεσθαι Δίωνι καὶ κολαστὴς Ἡρακλείδου κακοπραγμονοῦντος.", "st": "Dion 49.1"}, {"sp": "N", "t": "ἐκ τούτου κατέλυσαν μὲν οἱ Συρακούσιοι τὸ ναυτικόν, οὐδὲν γὰρ ἦν ἔργον αὐτοῦ, μεγάλαι δὲ δαπάναι τοῖς πλέουσι, καὶ στάσεως ἀφορμαὶ τοῖς ἄρχουσι· τὴν δὲ ἄκραν ἐπολιόρκουν ἐξοικοδομήσαντες τὸ περιτείχισμα. μηδενὸς δὲ τοῖς πολιορκουμένοις βοηθοῦντος, ἐπιλιπόντος δὲ σίτου, τῶν δὲ μισθοφόρων γινομένων· πονηρῶν, ἀπογνοὺς ὁ υἱὸς τοῦ Διονυσίου τὰ πράγματα καὶ σπεισάμενος πρὸς τὸν Δίωνα τὴν μὲν ἄκραν ἐκείνῳ μετὰ τῶν ὅπλων καὶ τῆς ἄλλης κατασκευῆς παρέδωκεν, αὐτὸς δὲ τὴν μητέρα καὶ τὰς ἀδελφὰς ἀναλαβὼν καὶ πέντε πληρωσάμενος τριήρεις ἐξέπλει πρὸς τὸν πατέρα, τοῦ Δίωνος ἀσφαλῶς μὲν ἐκπέμποντος, οὐδενὸς δὲ τῶν ἐν Συρακούσαις ἀπολείποντος ἐκείνην τὴν ὄψιν, ἀλλὰ καὶ τοὺς μὴ περόντας ἐπιβοωμένων, ὅτι τὴν ἡμέραν ταύτην καὶ τὸν ἥλιον ἐλευθέραις ἀνίσχοντα ταῖς Συρακούσαις οὐκ ἐφορῶσιν. ὅπου γὰρ ἔτι νῦν τῶν λεγομένων κατὰ τῆς τύχης παραδειγμάτων ἐμφανέστατόν ἐστι καὶ μέγιστον ἡ Διονυσίου φυγή, τίνα χρὴ δοκεῖν αὐτῶν ἐκείνων τὴν τότε χαρὰν γενέσθαι καὶ πηλίκον φρονῆσαι τοὺς τὴν μεγίστην τῶν πώποτε τυραννίδων καθελόντας ἐλαχίσταις ἀφορμαῖς;", "st": "Dion 50.1"}, {"sp": "N", "t": "ἐκπλεύσαντος δὲ τοῦ Ἀπολλοκράτους, καὶ τοῦ Δίωνος εἰς τὴν ἀκρόπολιν βαδίζοντος, οὐκ ἐκαρτέρησαν αἱ γυναῖκες οὐδ’ ἀνέμειναν εἰσελθεῖν αὐτόν, ἀλλ’ ἐπὶ τὰς θύρας ἐξέδραμον, ἡ μὲν Ἀριστομάχη τὸν υἱὸν ἄγουσα τοῦ Δίωνος, ἡ δ’ Ἀρετὴ κατόπιν εἵπετο δακρύουσα, καὶ διαποροῦσα πῶς ἀσπάσηται καὶ προσείπῃ τὸν ἄνδρα κοινωνίας αὐτῇ πρὸς ἕτερον γεγενημένης. ἀσπασαμένου δ’ αὑτοῦ πρῶτον τὴν ἀδελφήν, εἶτα τὸ παιδίον, ἡ Ἀριστομάχη προσαγαγοῦσα τὴν Ἀρετήν, ἠτυχοῦμεν, ὦ Δίων, ἔφη, σοῦ φεύγοντος· ἥκων δὲ καὶ νικῶν ἀφῄρηκας ἡμῶν ἁπάντων τὰς κατηφείας, πλὴν μόνης ταύτης, ἣν ἐπεῖδον ἡ δυστυχὴς ἐγὼ σοῦ ζῶντος ἑτέρῳ συνελθεῖν βιασθεῖσαν. ὅτε οὖν σὲ κύριον ἡμῶν ἡ τύχη πεποίηκε, πῶς αὐτῇ διαιτᾷς ἐκείνην τὴν ἀνάγκην; πότερον ὡς θεῖον ἢ καὶ ὡς ἄνδρα σε ἀσπάσεται; τοιαῦτα τῆς Ἀριστομάχης λεγούσης ὁ Δίων ἐκδακρύσας προσηγάγετο φιλοστόργως τὴν γυναῖκα· καὶ παραδοὺς αὐτῇ τὸν υἱὸν ἐκέλευσεν εἰς τὴν οἰκίαν τὴν αὑτοῦ βαδίζειν, ὅπου καὶ αὐτὸς διῃτᾶτο, τὴν ἄκραν ἐπὶ τοῖς Συρακουσίοις ποιησάμενος.", "st": "Dion 51.1"}, {"sp": "N", "t": "οὕτω δὲ τῶν πραγμάτων αὐτῷ προκεχωρηκότων οὐδὲν ἀπολαῦσαι πρότερον ἠξίωσε τῆς παρούσης εὐτυχίας ἢ τὸ καὶ φίλοις χάριτας καὶ συμμάχοις δωρεάς, μάλιστα δὲ τοῖς ἐν ἄστει συνήθεσι καὶ ξένοις ἀπονεῖμαί τινα φιλανθρωπίας καὶ τιμῆς μερίδα, τῇ μεγαλοψυχίᾳ τὴν δύναμιν ὑπερβαλλόμενος, ἑαυτὸν δὲ λιτῶς καὶ σωφρόνως ἐκ τῶν τυχόντων διῴκει, θαυμαζόμενος ὅτι, μὴ μόνον Σικελίας τε καὶ Καρχηδόνος, ἀλλὰ καὶ τῆς Ἑλλάδος ὅλης ἀποβλεπούσης πρὸς αὐτὸν εὐημεροῦντα, καὶ μηδὲν οὕτω μέγα τῶν τότε νομιζόντων, μηδ’ ἐπιφανεστέρας περὶ ἄλλον ἡγεμόνα τόλμης καὶ τύχης γεγονέναι δοκούσης, οὕτω παρεῖχεν ἑαυτὸν ἐσθῆτι καὶ θεραπείᾳ καὶ τραπέζῃ μέτριον, ὥσπερ ἐν Ἀκαδημείᾳ συσσιτῶν μετὰ Πλάτωνος, οὐκ ἐν ξεναγοῖς καὶ μισθοφόροις διαιτώμενος, οἷς αἱ καθ’ ἑκάστην ἡμέραν πλησμοναὶ καὶ ἀπολαύσεις παραμυθία τῶν πόνων καὶ τῶν κινδύνων εἰσίν. ἀλλ’ ἐκείνῳ μὲν Πλάτων ἔγραφεν ὡς πρὸς ἕνα νῦν τῆς οἰκουμένης τοῦτον ἅπαντες ἀποβλέπουσιν, αὐτὸς δὲ ἐκεῖνος, ὡς ἔοικεν, ἀφεώρα πρὸς ἓν χωρίον μιᾶς πόλεως, τὴν Ἀκαδήμειαν, καὶ τοὺς αὐτόθι καὶ θεατὰς καὶ δικαστὰς ἐγίνωσκεν οὔτε πρᾶξιν οὔτε τόλμαν οὔτε νίκην τινὰ θαυμάζοντας, ἀλλὰ μόνον εἰ κοσμίως καὶ σωφρόνως τῇ τύχῃ χρῆται καὶ παρέχει μέτριον ἑαυτὸν ἐν πράγμασι μεγάλοις ἀποσκοποῦντας. τοῦ μέντοι περὶ τὰς ὁμιλίας ὄγκου καὶ τοῦ πρὸς τὸν δῆμον ἀτενοῦς ἐφιλονείκει μηδὲν ὑφελεῖν μηδὲ χαλάσαι, καίτοι τῶν πραγμάτων αὐτῷ χάριτος ἐνδεῶν ὄντων, καὶ Πλάτωνος ἐπιτιμῶντος, ὡς εἰρήκαμεν, καὶ γράφοντος ὅτι ἡ αὐθάδεια ἐρημίᾳ σύνοικός ἐστιν. ἀλλὰ φύσει τε φαίνεται πρὸς τὸ πιθανὸν δυσκεράστῳ κεχρημένος, ἀντισπᾶν τε τοὺς Συρακουσίους ἄγαν ἀνειμένους καὶ διατεθρυμμένους προθυμούμενος.", "st": "Dion 52.1"}, {"sp": "N", "t": "ὁ γὰρ Ἡρακλείδης αὖθις ἐπέκειτο· καὶ πρῶτον μὲν εἰς συνέδριον παρακαλούμενος οὐκ ἐβούλετο βαδίζειν ἰδιώτης γὰρ ὢν μετὰ τῶν ἄλλων ἐκκλησιάζειν πολιτῶν. ἔπειτα κατηγόρει τοῦ Δίωνος ὅτι τὴν ἄκραν οὐ κατέσκαψε καὶ τῷ δήμῳ τὸν Διονυσίου τάφον ὡρμημένῳ λῦσαι καὶ τὸν νεκρὸν ἐκβαλεῖν οὐκ ἐπέτρεψε, μεταπέμπεται δὲ ἐκ Κορίνθου συμβούλους καὶ συνάρχοντας, ἀπαξιῶν τοὺς πολίτας. τῷ δ’ ὄντι μετεπέμπετο τοὺς Κορινθίους ὁ Δίων, ἣν ἐπενόει πολιτείαν ῥᾷον ἐλπίζων καταστήσειν ἐκείνων παραγενομένων. ἐπενόει δὲ τὴν μὲν ἄκρατον δημοκρατίαν, ὡς οὐ πολιτείαν, ἀλλὰ παντοπώλιον οὖσαν πολιτειῶν, κατὰ τὸν Πλάτωνα, κωλύειν, Λακωνικὸν δέ τι καὶ Κρητικὸν σχῆμα μιξάμενος ἐκ δήμου καὶ βασιλείας, ἀριστοκρατίαν ἔχον τὴν ἐπιστατοῦσαν καὶ βραβεύουσαν τὰ μέγιστα, καθιστάναι καὶ κοσμεῖν, ὁρῶν καὶ τοὺς Κορινθίους ὀλιγαρχικώτερόν τε πολιτευομένους καὶ μὴ πολλὰ τῶν κοινῶν ἐν τῷ δήμῳ πράττοντας.", "st": "Dion 53.1"}, {"sp": "N", "t": "ὡς οὖν μάλιστα πρὸς ταῦτα τὸν Ἡρακλείδην ἐναντιώσεσθαι προσεδόκα, καὶ τἆλλα ταραχώδης καὶ εὐμετάθετος καὶ στασιαστικὸς ἦν, οὓς πάλαι βουλομένους αὐτὸν ἐκώλυεν ἀνελεῖν, τούτοις ἐπέτρεψε τότε· καὶ παρελθόντες εἰς τὴν οἰκίαν ἀποκτιννύουσιν αὐτόν. ἐλύπησε δὲ σφόδρα τοὺς Συρακουσίους ἀποθανών. ὅμως δὲ τοῦ Δίωνος ταφάς τε λαμπρὰς παρασκευάσαντος καὶ μετὰ τοῦ στρατεύματος ἑπομένου προπέμψαντος τὸν νεκρόν, εἶτα διαλεχθέντος αὐτοῖς, συνέγνωσαν ὡς οὐ δυνατὸν ἦν ταρασσομένην παύσασθαι τὴν πόλιν Ἡρακλείδου καὶ Δίωνος ἅμα πολιτευομένων.", "st": "Dion 53.5"}, {"sp": "N", "t": "ἦν δέ τις ἑταῖρος τοῦ Δίωνος ἐξ Ἀθηνῶν, Κάλλιππος, ὅν φησιν ὁ Πλάτων οὐκ ἀπὸ παιδείας, ἀλλ’ ἐκ μυσταγωγιῶν καὶ τῆς περιτρεχούσης ἑταιρείας γνώριμον αὐτῷ γενέσθαι καὶ συνήθη, μετασχὼν δὲ τῆς στρατείας καὶ τιμώμενος, ὥστε καὶ συνεισελθεῖν εἰς τὰς Συρακούσας πρῶτος τῶν ἑταίρων ἁπάντων, ἐστεφανωμένος καὶ λαμπρὸς ἐν τοῖς ἀγῶσι καὶ διάσημος. ἐπεὶ δέ, τῶν πρώτων καὶ βελτίστων φίλων τοῦ Δίωνος ἀνηλωμένων ὑπὸ τοῦ πολέμου, καὶ τεθνηκότος Ἡρακλείδου, τόν τε δῆμον ἑώρα τῶν Συρακουσίων ἔρημον ἡγεμόνος ὄντα καὶ τοὺς στρατιώτας τοὺς μετὰ Δίωνος προσέχοντας αὐτῷ μάλιστα, μιαρώτατος ἀνθρώπων γενόμενος καὶ παντάπασιν ἐλπίσας Σικελίαν ἆθλον ἕξειν τῆς ξενοκτονίας, ὡς δέ φασιν ἔνιοι, καὶ τάλαντα προσλαβὼν εἴκοσι τοῦ φόνου μισθὸν παρὰ τῶν πολεμίων, διέφθειρε καὶ παρεσκεύαζέ τινας τῶν ξένων ἐπὶ τόν Δίωνα, κακοηθεστάτην ἀρχὴν καὶ πανουργοτάτην ποιησάμενος. ἀεὶ γάρ τινας φωνὰς τῶν στρατιωτῶν πρὸς ἐκεῖνον ἢ λελεγμένας ἀληθῶς ἀναφέρων ἢ πεπλασμένας ὑφ’ αὐτοῦ, τοιαύτην ἐξουσίαν ἔλαβε διὰ τὴν πίστιν ὥστ’ ἐντυγχάνειν κρύφα καὶ διαλέγεσθαι μετὰ παρρησίας οἷς βούλοιτο κατὰ τοῦ Δίωνος, αὐτοῦ κελεύοντος, ἵνα μηδὲ εἰς λανθάνῃ τῶν ὑπούλως καὶ δυσμενῶς ἐχόντων. ἐκ δὲ τούτων συνέβαινε τοὺς μὲν πονηροὺς καὶ νοσοῦντας εὑρίσκειν ταχὺ καὶ συνιστάναι τόν Κάλλιππον, εἰ δέ τις ἀπωσάμενος τοὺς λόγους αὐτοῦ καὶ τὴν πεῖραν ἐξείποι πρὸς τόν Δίωνα, μὴ ταράττεσθαι μηδὲ χαλεπαίνειν ἐκεῖνον, ὡς ἃ προσέταττε τοῦ Καλλίππου περαίνοντος.", "st": "Dion 54.1"}, {"sp": "N", "t": "συνισταμένης δὲ τῆς ἐπιβουλῆς φάσμα γίνεται τῷ Δίωνι μέγα καὶ τερατῶδες, ἐτύγχανε μὲν γὰρ ὀψὲ τῆς ἡμέρας καθεζόμενος ἐν παστάδι τῆς οἰκίας μόνος ὢν πρὸς ἑαυτῷ τὴν διάνοιαν· ἐξαίφνης δὲ ψόφου γενομένου πρὸς θατέρῳ πέρατι τῆς στοᾶς, ἀποβλέψας ἔτι φωτὸς ὄντος εἶδε γυναῖκα μεγάλην, στολῇ μὲν καὶ προσώπῳ μηδὲν Ἐριννύος τραγικῆς παραλλάττουσαν, σαίρουσαν δὲ καλλύντρῳ τινὶ τὴν οἰκίαν. ἐκπλαγεὶς δὲ δεινῶς καὶ περίφοβος γενόμενος μετεπέμψατο τοὺς φίλους καὶ διηγεῖτο τὴν ὄψιν αὐτοῖς καὶ παραμένειν ἐδεῖτο καὶ συννυκτερεύειν, παντάπασιν ἐκστατικῶς ἔχων καὶ δεδοικὼς μὴ πάλιν εἰς ὄψιν αὐτῷ μονωθέντι τὸ τέρας ἀφίκηται. τοῦτο μὲν οὖν αὖθις οὐ συνέπεσε. μεθ’ ἡμέρας δ’ ὀλίγας ὁ υἱὸς αὐτοῦ σχεδὸν ἀντίπαις ὤν, ἔκ τινος λύπης καὶ ὀργῆς μικρὰν καὶ παιδικὴν ἀρχὴν λαβούσης, ἔρριψεν ἑαυτὸν ἀπὸ τοῦ τέγους ἐπὶ τὴν κεφαλὴν καὶ διεφθάρη.", "st": "Dion 55.1"}, {"sp": "N", "t": "ἐν τοιούτοις δὲ τοῦ Δίωνος ὄντος, ὁ Κάλλιππος ἔτι μᾶλλον εἴχετο τῆς ἐπιβουλῆς, καὶ λόγον εἰς τοὺς Συρακουσίους ἐξέδωκεν ὡς ὁ Δίων, ἄπαις γεγονώς, ἔγνωκε τὸν Διονυσίου καλεῖν Ἀπολλοκράτην καὶ ποιεῖσθαι διάδοχον, ἀδελφιδοῦν μὲν ὄντα τῆς ἑαυτοῦ γυναικός, θυγατριδοῦν δὲ τῆς ἀδελφῆς. ἤδη δὲ καὶ τὸν Δίωνα καὶ τὰς γυναῖκας ὑπόνοια τῶν πραττομένων εἶχε, καὶ μηνύσεις ἐγίγνοντο πανταχόθεν. ἀλλ’ ὁ μὲν Δίων, ὡς ἔοικεν, ἐπὶ τοῖς κατὰ τὸν Ἡρακλείδην ἀχθόμενος, καὶ τὸν φόνον ἐκεῖνον, ὥς τινα τοῦ βίου καὶ τῶν πράξεων αὐτῷ κηλῖδα περικειμένην, δυσχεραίνων ἀεὶ καὶ βαρυνόμενος, εἶπεν ὅτι πολλάκις ἤδη θνῄσκειν ἕτοιμός ἐστι καὶ παρέχειν τῷ βουλομένῳ σφάττειν αὐτόν, εἰ ζῆν δεήσει μὴ μόνον τοὺς ἐχθρούς, ἀλλὰ καὶ τοὺς φίλους φυλαττόμενον.", "st": "Dion 56.1"}, {"sp": "N", "t": "τὰς δὲ γυναῖκας ὁρῶν ὁ Κάλλιππος ἐξεταζούσας ἀκριβῶς τὸ πρᾶγμα, καὶ φοβηθείς, ἦλθε πρὸς αὐτὰς ἀρνούμενος καὶ δακρύων καὶ πίστιν ἣν βούλονται διδόναι βουλόμενος. αἱ δ’ ἠξίουν αὐτὸν ὀμόσαι τὸν μέγαν ὅρκον. ἦν δὲ τοιοῦτος· καταβὰς εἰς τὸ τῶν Θεσμοφόρων τέμενος ὁ διδοὺς τὴν πίστιν, ἱερῶν τινων γενομένων, περιβάλλεται τὴν πορφυρίδα τῆς θεοῦ, καὶ λαβὼν δᾷδα καιομένην ἀπόμνυσι. ταῦτα ποιήσας ὁ Κάλλιππος πάντα, καὶ τὸν ὅρκον ἀπομόσας, οὕτω κατεγέλασε τῶν θεῶν ὥστε περιμείνας τὴν ἑορτὴν ἧς ὤμοσε θεοῦ, δρᾷ τὸν φόνον ἐν τοῖς Κορείοις, οὐδὲν ἴσως τὸ περὶ τὴν ἡμέραν τῆς θεοῦ ποιησάμενος, ὡς ἀσεβουμένης πάντως, εἰ καὶ κατ’ ἄλλον χρόνον ἔσφαττε τὸν μύστην αὐτῆς ὁ μυσταγωγός.", "st": "Dion 56.4"}, {"sp": "N", "t": "ὄντων δὲ πλειόνων ἐν τῇ κοινωνίᾳ τῆς πράξεως, καθεζομένου Δίωνος ἐν οἰκήματι κλίνας τινὰς ἔχοντι μετὰ τῶν φίλων, οἱ μὲν ἔξω τὴν οἰκίαν περιέστησαν, οἱ δὲ πρὸς ταῖς θύραις τοῦ οἴκου καὶ ταῖς θυρίσιν ἦσαν. αὐτοὶ δ’ οἱ προσφέρειν τὰς χεῖρας μέλλοντες Ζακύνθιοι παρῆλθον ἄνευ ξιφῶν ἐν τοῖς χιτῶσιν. ἅμα δ’ οἱ μὲν ἔξω τὰς θύρας ἐπισπασάμενοι κατεῖχον, οἱ δὲ τῷ Δίωνι προσπεσόντες κατάγχειν ἐπειρῶντο καὶ συντρίβειν αὐτόν. ὡς δ’ οὐδὲν ἐπέραινον, ᾔτουν ξίφος· οὐδεὶς δ’ ἐτόλμα τὰς θύρας ἀνοῖξαι ι. συχνοὶ γὰρ ἦσαν ἔνδον οἱ μετὰ τοῦ Δίωνος, ὧν ἕκαστος οἰόμενος, ἂν ἐκεῖνον προῆται, διασώσειν ἑαυτόν, οὐκ ἐτόλμα βοηθεῖν. διατριβῆς δὲ γενομένης Λύκων ὁ Συρακούσιος ὀρέγει τινὶ τῶν Ζακυνθίων διὰ τῆς θυρίδος ἐγχειρίδιον, ᾧ καθάπερ ἱερεῖον τὸν Δίωνα κρατούμενον πάλαι καὶ δεδιττόμενον ἀπέσφαξαν. εὐθὺς δὲ καὶ τὴν ἀδελφὴν μετὰ τῆς γυναικὸς ἐγκύμονος οὔσης εἰς τὴν εἱρκτὴν ἐνέβαλον. καὶ συνέβη τῇ γυναικὶ τλημονέστατα λοχευθείσῃ τεκεῖν ἐν τῷ δεσμωτηρίῳ παιδάριον ἄρρεν· ὅπερ καὶ θρέψαι μᾶλλον παρεβάλοντο πείσασαι τοὺς φύλακας, ἤδη τοῦ Καλλίππου θορυβουμένου τοῖς πράγμασιν.", "st": "Dion 57.1"}, {"sp": "N", "t": "ἐν ἀρχῇ μὲν γὰρ ἀποκτείνας τὸν Δίωνα λαμπρὸς ἦν καί κατεῖχε τὰς Συρακούσας· καί πρὸς τὴν Ἀθηναίων ἔγραφε πόλιν, ἣν μάλιστα μετὰ τοὺς θεοὺς ὤφειλεν αἰδεῖσθαι καί δεδιέναι τηλικούτου μύσους ἁψάμενος. ἀλλ’ ἔοικεν ἀληθῶς λέγεσθαι τὸ τὴν πόλιν ἐκείνην φέρειν ἄνδρας ἀρετῇ τε τοὺς ἀγαθοὺς ἀρίστους καὶ κακίᾳ τοὺς φαύλους πονηροτάτους, καθάπερ αὐτῶν καί ἡ χώρα κάλλιστον μέλι καί κώνειον ὠκυμορώτατον ἀναδίδωσιν. οὐ μὴν πολὺν χρόνον ὁ Κάλλιππος ἔγκλημα τῆς τύχης καί τῶν θεῶν περιῆν, ὡς περιορώντων ἐξ ἀσεβήματος ἄνθρωπον τηλικούτου κτώμενον ἡγεμονίας καί πράγματα· ταχὺ δ’ ἀξίαν δίκην ἔδωκεν. ὁρμήσας μὲν γὰρ Κατάνην λαβεῖν, εὐθὺς ἀπέβαλε τὰς Συρακούσας ὅτε καί φασιν αὐτὸν εἰπεῖν ὅτι πόλιν ἀπολωλεκὼς τυρόκνηστιν εἴληφεν. ἐπιθέμενος δὲ Μεσσηνίοις καί τοὺς πλείστους στρατιώτας ἀπολέσας, ἐν οἷς ἦσαν οἱ Δίωνα κατακτείναντες, οὐδεμιᾶς δὲ πόλεως αὐτὸν ἐν Σικελίᾳ προσδεχομένης, ἀλλὰ μισούντων ἁπάντων καί προβαλλομένων, Ῥήγιον κατέσχεν. ἐκεῖ δὲ λυπρῶς πράττων καί κακῶς διατρέφων τοὺς μισθοφόρους, ὑπὸ Λεπτίνου καί Πολυπέρχοντος ἀνῃρέθη, χρησαμένων ξιφιδίῳ κατὰ τύχην ᾧ καί Δίωνα πληγῆναί φασιν. ἐγνώσθη δὲ τῷ μεγέθει (βραχὺ γὰρ ἦν, ὥσπερ τὰ Λακωνικά) καί τῇ κατασκευῇ τῆς τέχνης, εἰργασμένον γλαφυρῶς καί περιττῶς. τοιαύτην μὲν οὖν τίσιν Κάλλιππος ἔδωκε.", "st": "Dion 58.1"}, {"sp": "N", "t": "τὴν δ’ Ἀριστομάχην καί τὴν Ἀρετήν, ὡς ἀφείθησαν ἐκ τῆς εἱρκτῆς, ἀναλαβὼν Ἱκέτης ὁ Συρακούσιος, εἷς τῶν Δίωνος φίλων γεγονώς, ἐδόκει πιστῶς καί καλῶς περιέπειν. εἶτα συμπεισθεὶς ὑπὸ τῶν Δίωνος ἐχθρῶν καί παρασκευάσας πλοῖον αὐταῖς, ὡς εἷς Πελοπόννησον ἀποσταλησομέναις, ἐκέλευσε κατὰ πλοῦν ἀποσφάξαντας ἐκβαλεῖν εἷς τὴν θάλασσαν. οἱ δὲ ζώσας ἔτι καταποντισθῆναι λέγουσι, καί τὸ παιδίον μετ’ αὐτῶν. περιῆλθε δὲ καί τοῦτον ἀξία ποινὴ τῶν τετολμημένων, αὐτός τε γὰρ ὑπὸ Τιμολέοντος ἁλοὺς ἀπέθανε, καί θυγατέρας δύο προσαπέκτειναν αὐτοῦ Δίωνι τιμωροῦντες οἱ Συρακούσιοι, περὶ ὧν ἐν τῷ Τιμολέοντος βίῳ καθ’ ἕκαστα γέγραπται.", "st": "Dion 58.8"}, {"sp": "HDR", "t": "Βροῦτος"}, {"sp": "N", "t": "Μάρκου δὲ Βρούτου πρόγονος ἦν Ἰούνιος Βροῦτος, ὃν ἀνέστησαν ἐν Καπιτωλίῳ χαλκοῦν οἱ πάλαι Ῥωμαῖοι μέσον τῶν βασιλέων, ἐσπασμένον ξίφος, ὡς βεβαιότατα καταλύσαντα Ταρκυνίους. ἀλλ’ ἐκεῖνος μέν, ὥσπερ τὰ ψυχρήλατα τῶν ξιφῶν, σκληρὸν ἐκ φύσεως καὶ οὐ μαλακὸν ἔχων ὑπὸ λόγου τὸ ἦθος ἄχρι παιδοφονίας ἐξώκειλε τῷ θυμῷ τῷ κατὰ τῶν τυράννων, οὑτοσὶ δ’, ὑπὲρ οὗ γράφεται ταῦτα, παιδείᾳ καὶ λόγῳ διὰ φιλοσοφίας καταμίξας τὸ ἦθος, καὶ τὴν φύσιν ἐμβριθῆ καὶ πρᾳεῖαν οὖσαν ἐπεγείρας ταῖς πρακτικαῖς ὁρμαῖς, ἐμμελέστατα δοκεῖ κραθῆναι πρὸς τὸ καλόν, ὥστε καὶ τοὺς ἀπεχθανομένους αὐτῷ διὰ τὴν ἐπὶ Καίσαρα συνωμοσίαν, εἰ μέν τι γενναῖον ἡ πρᾶξις ἤνεγκε, Βρούτῳ προσάπτειν, τὰ δυσχερέστερα δὲ τῶν γεγονότων τρέπειν εἰς Κάσσιον, οἰκεῖον μέν ὄντα Βρούτου καὶ φίλον, ἁπλοῦν δὲ τῷ τρόπῳ καὶ καθαρὸν οὐχ ὁμοίως. Σερβιλία δὲ ἡ μήτηρ ἀνέφερε τὸ γένος εἰς Ἀάλαν Σερβίλιον, ὃς Μαιλίου Σπορίου τυραννίδα κατασκευαζομένου καὶ ταράττοντος τὸν δῆμον ἐγχειρίδιον λαβὼν ὑπὸ μάλης προῆλθεν εἰς ἀγοράν καὶ παραστὰς τῷ ἀνδρὶ πλησίον, ὡς ἐντυγχάνειν τι μέλλων καὶ διαλέγεσθαι, προσνεύσαντα πατάξας ἀπέκτεινε.", "st": "Brut. 1.1"}, {"sp": "N", "t": "τοῦτο μέν οὖν ὁμολογούμενόν ἐστι· τὸ δὲ πατρῷον γένος οἱ διὰ τὸν Καίσαρος φόνον ἔχθραν τινὰ καὶ δυσμένειαν ἀποδεικνύμενοι πρὸς Βροῦτον οὔ φασιν εἰς τὸν ἐκβαλόντα Ταρκυνίους ἀνήκειν οὐδὲν γὰρ ἐκείνῳ λειφθῆναι γένος ἀνελόντι τοὺς υἱούς, ἀλλὰ δημότην τοῦτον, οἰκονόμου υἱὸν ὄντα Βρούτου, ἄρτι καὶ πρῴην εἰς ἄρχοντα προελθεῖν. Ποσειδώνιος δ’ ὁ φιλόσοφος τοὺς μέν ἐνηλίκους φησὶν ἀπολέσθαι τοῦ Βρούτου παῖδας ὡς ἱστόρηται, τρίτον δὲ λειφθῆναι νήπιον, ἀφ’ οὗ τὸ γένος ὡρμῆσθαι· καὶ τῶν γε καθ’ αὑτὸν ἐκ τῆς οἰκίας γεγονότων ἐπιφανῶν ἀνδρῶν ἀναφέρειν ἐνίους πρὸς τὸν ἀνδριάντα τοῦ Βρούτου τὴν ὁμοιότητα τῆς ἰδέας, περὶ μέν οὖν τούτων τοσαῦτα.", "st": "Brut. 1.6"}, {"sp": "N", "t": "Σερβιλίας δὲ τῆς Βρούτου μητρὸς ἀδελφὸς ἦν Κάτων ὁ φιλόσοφος, ὃν μάλιστα Ῥωμαίων ἐζήλωσεν οὗτος θεῖον ὄντα καὶ πενθερὸν ὕστερον γενόμενον. τῶν δὲ Ἑλληνικῶν φιλοσόφων οὐδενὸς μὲν, ὡς ἁπλῶς εἰπεῖν, ἀνήκοος ἦν οὐδὲ ἀλλότριος, διαφερόντως δ’ ἐσπουδάκει πρὸς τοὺς ἀπὸ Πλάτωνος. καὶ τὴν νέαν καὶ μέσην λεγομένην Ἀκαδήμειαν οὐ πάνυ προσιέμενος ἐξήρτητο τῆς παλαιᾶς, καὶ διετέλει θαυμάζων μὲν Ἀντίοχον τὸν Ἀσκαλωνίτην, φίλον δὲ καὶ συμβιωτὴν τὸν ἀδελφὸν αὐτοῦ πεποιημένος Ἄριστον, ἄνδρα τῇ μὲν ἐν λόγοις ἕξει πολλῶν φιλοσόφων λειπόμενον, εὐταξίᾳ δὲ καὶ πρᾳότητι τοῖς πρώτοις ἐνάμιλλον. ὁ δ’Ἔμπυλος οὗ καὶ αὐτὸς ἐν ταῖς ἐπιστολαῖς καὶ οἱ φίλοι μέμνηνται πολλάκις ὡς συμβιοῦντος αὐτῷ, ῥήτωρ ἦν καὶ καταλέλοιπε μικρὸν μὲν, οὐ φαῦλον δὲ σύγγραμμα περὶ τῆς Καίσαρος ἀναιρέσεως, ὃ Βροῦτος ἐπιγέγραπται.", "st": "Brut. 2.1"}, {"sp": "N", "t": "Ῥωμαϊστὶ μὲν οὖν ἤσκητο πρὸς τὰς διεξόδους καὶ τοὺς ἀγῶνας ἱκανῶς ὁ Βροῦτος, Ἑλληνιστὶ δὲ τὴν ἀποφθεγματικὴν καὶ Λακωνικὴν ἐπιτηδεύων βραχυλογίαν ἐν ταῖς ἐπιστολαῖς ἐνιαχοῦ παράσημός ἐστιν. οἷον ἤδη καθεστηκὼς εἰς τὸν πόλεμον γράφει Περγαμηνοῖς· ἀκούω ὑμᾶς Δολοβέλλᾳ δεδωκέναι χρήματα· ἃ εἰ μὲν ἑκόντες ἔδοτε, ὁμολογεῖτε ἀδικεῖν· εἰ δὲ ἄκοντες, ἀποδείξατε τῷ ἐμοὶ ἑκόντες δοῦναι. πάλιν Σαμίοις· αἱ βουλαὶ ὑμῶν ὀλίγωροι, αἱ ὑπουργίαι βραδεῖαι. τί τούτων τέλος ἐννοεῖσθε; καὶ ἑτέραν Ξάνθιοι τὴν ἐμὴν εὐεργεσίαν ὑπεριδόντες τάφον ἀπονοίας ἐσχήκασι τὴν πατρίδα, Παταρεῖς δὲ πιστεύσαντες ἑαυτοὺς ἐμοὶ οὐδὲν ἐλλείπουσι διοικοῦντες τὰ καθ’ ἕκαστα τῆς ἐλευθερίας. ἐξὸν οὖν καὶ ὑμῖν ἢ τὴν Παταρέων κρίσιν ἢ τὴν Ξανθίων τύχην ἑλέσθαι. τὸ μὲν οὖν τῶν παρασήμων γένος ἐπιστολίων τοιοῦτόν ἐστιν.", "st": "Brut. 2.5"}, {"sp": "N", "t": "ἔτι δὲ μειράκιον ὢν Κάτωνι τῷ θείῳ συναπεδήμησεν εἰς Κύπρον ἐπὶ Πτολεμαῖον ἀποσταλέντι. Πτολεμαίου δὲ διαφθείραντος ἑαυτὸν ὁ Κάτων αὐτὸς ἐν Ῥόδῳ διατριβὴν ἔχων ἀναγκαίαν ἔτυχε μὲν ἤδη τινὰ τῶν φίλων Κανίδιον ἐπὶ τὴν τῶν χρημάτων φυλακὴν ἀπεσταλκώς, δείσας δ’ ἐκεῖνον ὡς οὐκ ἀφεξόμενον κλοπῆς, ἔγραψε τῷ Βρούτῳ πλεῖν τὴν ταχίστην εἰς Κύπρον ἐκ Παμφυλίας· ἐκεῖ γὰρ ἑαυτὸν ἀναλαμβάνων ἔκ τινος ἀσθενείας διῆγεν. ὁ δὲ καὶ μάλα ἄκων ἔπλευσε, τόν τε Κανίδιον αἰδούμενος ὡς ἀτίμως ἀπερριμμένον ὑπὸ τοῦ Κάτωνος, καὶ ὅλως τὴν τοιαύτην ἐπιμέλειαν καὶ διοίκησιν, ἅτε δὴ νέος καὶ σχολαστής, οὐκ ἐλευθέριον οὐδ’ ἑαυτοῦ ποιούμενος. οὐ μὴν ἀλλὰ καὶ περὶ ταῦτα συντείνας ἑαυτὸν ὑπὸ τοῦ Κάτωνος ἐπῃνέθη, καὶ τῆς οὐσίας ἐξαργυρισθείσης ἀναλαβὼν τὰ πλεῖστα τῶν χρημάτων εἰς Ῥώμην ἔπλευσεν.", "st": "Brut. 3.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τὰ πράγματα διέστη Πομπηΐου καί Καίσαρος ἐξενεγκαμένων τὰ ὅπλα καί τῆς ἡγεμονίας ταραχθείσης, ἐπίδοξος μὲν ἦν αἱρήσεσθαι τὰ Καίσαρος· ὁ γὰρ πατὴρ αὐτοῦ διὰ τὸν Πομπήϊον ἐτεθνήκει πρότερον· ἀξιῶν δὲ τὰ κοινὰ τῶν ἰδίων ἐπίπροσθεν ποιεῖσθαι καί τὴν Πομπηΐου νομίζων ὑπόθεσιν βελτίονα πρὸς τὸν πόλεμον εἶναι τῆς τοῦ Καίσαρος ἐκείνῳ προσέθετο. καίτοι πρότερον ἀπαντήσας οὐδὲ προσεῖπε τὸν Πομπήϊον, ἄγος ἡγούμενος μέγα πατρὸς φονεῖ διαλέγεσθαι τότε δ’ ὡς ἄρχοντι τῆς πατρίδος ὑποτάξας ἑαυτόν εἰς Κιλικίαν ἔπλευσε πρεσβευτὴς μετὰ Σηστίου τοῦ λαχόντος τὴν ἐπαρχίαν. ὡς δ’ἐκεῖ πράττειν οὐδὲν ἦν μέγα καί συνῄεσαν εἰς ταὐτὸ ἤδη Πομπήϊος καί Καῖσαρ ἀγωνιζόμενοι περὶ τῶν ὅλων, ἧκεν εἰς Μακεδονίαν ἐθελοντὴς τοῦ κινδύνου μεθέξων· ὅτε καί φασι Πομπήϊον ἡσθέντα καί θαυμάσαντα προσιόντος αὐτοῦ καθεζόμενον ἐξαναστῆναι καί περιβαλεῖν ὡς κρείττονα πάντων ὁρώντων. ἐν δὲ τῇ στρατείᾳ τῆς ἡμέρας ὅσα μὴ Πομπηΐῳ συνῆν περὶ λόγους καί βιβλία διέτριβεν, οὐ μόνον τὸν ἄλλον χρόνον, ἀλλὰ καί πρὸ τῆς μεγάλης μάχης. ἦν μὲν ἀκμὴ θέρους καί καῦμα πολύ πρὸς ἑλώδεσι χωρίοις ἐστρατοπεδευκότων, τῷ δὲ Βρούτῳ οὐ ταχέως ἧκον οἱ τὴν σκηνὴν κομίζοντες. ἐκπονηθεὶς δὲ περὶ ταῦτα, μεσημβρίας μόλις ἀλειψάμενος καί φαγὼν ὀλίγα, τῶν ἄλλων ἢ καθευδόντων ἢ πρὸς ἐπινοίᾳ καί φροντίδι τοῦ μέλλοντος ὄντων, αὐτὸς ἄχρι τῆς ἑσπέρας ἔγραφε συντάττων ἐπιτομὴν Πολυβίου.", "st": "Brut. 4.1"}, {"sp": "N", "t": "λέγεται δὲ καὶ Καῖσαρ οὐκ ἀμελεῖν τοῦ ἀνδρός, ἀλλὰ καὶ προειπεῖν τοῖς ὑφ’ ἑαυτὸν ἡγεμόσιν ἐν τῇ μάχῃ μὴ κτείνειν Βροῦτον, ἀλλὰ φείδεσθαι, καὶ παρασχόντα μὲν ἑκουσίως ἄγειν, εἰ δὲ ἀπομάχοιτο πρὸς τὴν σύλληψιν, ἐᾶν καὶ μὴ βιάζεσθαι· καὶ ταῦτα ποιεῖν τῇ μητρὶ τοῦ Βρούτου Σερβιλίᾳ χαριζόμενος. ἐγνώκει γὰρ, ὡς ἔοικε, νεανίας ὢν ἔτι τὴν Σερβιλίαν ἐπιμανεῖσαν αὐτῷ, καὶ καθ’ οὓς μάλιστα χρόνους ὁ ἔρως ἐπέφλεγε γενόμενον τὸν Βροῦτον ἐπέπειστό πως ἐξ ἑαυτοῦ γεγονέναι. λέγεται δὲ τῶν περὶ Κατιλίναν πραγμάτων μεγάλων ἐμπεπτωκότων εἰς τὴν σύγκλητον, ἃ μικρὸν ἐδέησεν ἀνατρέψαι τὴν πόλιν, ἑστάναι μὲν ὁμοῦ Κάτωνα καὶ Καίσαρα διαφερομένους περὶ γνώμης, ἐν τούτῳ δὲ γραμματιδίου μικροῦ προσδοθέντος ἔξωθεν Καίσαρι, τὸν μὲν ἀναγινώσκειν σιωπῇ, Κάτωνα δὲ βοᾶν ὡς δεινὰ ποιεῖ Καῖσαρ ἐντεύξεις καὶ γράμματα παρὰ τῶν πολεμίων προσδεχόμενος. θορυβησάντων δὲ πολλῶν, καὶ τοῦ Καίσαρος τὸ δελτάριον, ὡς εἶχε, τῷ Κάτωνι προσδόντος, ἀναγνόντα Σερβιλίας τῆς ἀδελφῆς ἀκόλαστον ἐπιστόλιον ἐκεῖνο μὲν ῥῖψαι πρὸς τὸν Καίσαρα καὶ εἰπεῖν κράτει, μέθυσε πρὸς δὲ τὴν γνώμην καὶ τὸν λόγον αὖθις ἐξ ἀρχῆς τραπέσθαι. οὕτω μὲν ἦν ὁ πρὸς Καίσαρα Σερβιλίας ἔρως περιβόητος.", "st": "Brut. 5.1"}, {"sp": "N", "t": "γενομένης δὲ τῆς κατὰ Φάρσαλον ἥττης καὶ Πομπηΐου μὲν ἐπὶ θάλασσαν διεκπεσόντος, πολιορκουμένου δὲ τοῦ χάρακος, ἔλαθεν ὁ Βροῦτος κατὰ πύλας πρὸς τόπον ἑλώδη καὶ μεστὸν ὑδάτων καὶ καλάμου φερούσας ἐξελθών καὶ διὰ νυκτὸς ἀποσωθεὶς εἰς Λάρισσαν. ἐκεῖθεν δὲ γράψαντος αὐτοῦ Καῖσαρ ἥσθη τε σωζομένῳ, καὶ κελεύσας πρὸς αὑτὸν ἐλθεῖν οὐ μόνον ἀφῆκε τῆς αἰτίας, ἀλλὰ καὶ τιμώμενον ἐν τοῖς μάλιστα περὶ αὑτὸν εἶχεν. οὐδενὸς δ’ ὅπῃ φεύγοι Πομπήϊος εἰπεῖν ἔχοντος, ἀλλ’ ἀπορίας οὔσης, ὁδόν τινα σὺν τῷ Βρούτῳ βαδίζων μόνος ἀπεπειρᾶτο τῆς γνώμης. καὶ δόξαντος ἔκ τινων διαλογισμῶν ἄριστα περὶ τῆς Πομπηΐου τεκμαίρεσθαι φυγῆς, ἀφεὶς τἆλλα τὴν ἐπ’ Αἰγύπτου συνέτεινεν. ἀλλὰ Πομπήϊον μὲν, ὥσπερ εἴκασε Βροῦτος, Αἰγύπτῳ προσβαλόντα τὸ πεπρωμένον ἐδέξατο. Καίσαρα δὲ καὶ πρὸς Κάσσιον ἐπράϋνε Βροῦτος. καὶ δὴ καὶ τῷ τῶν Λιβύων βασιλεῖ προηγορῶν μὲν ἡττᾶτο τοῦ μεγέθους τῶν κατηγοριῶν, δεόμενος δὲ καὶ παραιτούμενος περὶ τούτου πολλὴν αὐτῷ διέσωσε τῆς ἀρχῆς, λέγεται δὲ Καῖσαρ, ὅτε πρῶτον ἤκουσεν αὐτοῦ λέγοντος, εἰπεῖν πρὸς τοὺς φίλους· οὗτος ὁ νεανίας οὐκ οἶδα μὲν ὃ βούλεται, πᾶν δ’ ὃ βούλεται σφόδρα βούλεται. τὸ γὰρ ἐμβριθὲς αὐτοῦ καὶ μὴ ῥᾳδίως μηδὲ παντὸς ὑπήκοον τοῦ δεομένου πρὸς χάριν, ἀλλ’ ἐκ λογισμοῦ καὶ προαιρέσεως τῶν καλῶν πρακτικόν, ὅποι τρέψειεν, ἰσχυραῖς ἐχρῆτο ταῖς ὁρμαῖς καὶ τελεσιουργοῖς. πρὸς δὲ τὰς ἀδίκους δεήσεις ἀκολάκευτος ἦν, καὶ τὴν ὑπὸ τῶν ἀναισχύντως λιπαρούντων ἧτταν, ἣν ἔνιοι δυσωπεῖσθαι καλοῦσιν, αἰσχίστην ἀνδρὶ μεγάλῳ ποιούμενος εἰώθει λέγειν ὡς οἱ μηδὲν ἀρνεῖσθαι δυνάμενοι δοκοῦσιν αὐτῷ μὴ καλῶς τὴν ὥραν διατεθεῖσθαι.", "st": "Brut. 6.1"}, {"sp": "N", "t": "μέλλων δὲ διαβαίνειν εἰς Λιβύην Καῖσαρ ἐπὶ Κάτωνα καὶ Σκηπίωνα Βρούτῳ τὴν ἐντὸς Ἄλπεων Γαλατίαν ἐπέτρεψεν εὐτυχίᾳ τινὶ τῆς ἐπαρχίας· τὰς γὰρ ἄλλας ὕβρει καὶ πλεονεξίᾳ τῶν πεπιστευμένων ὥσπερ αἰχμαλώτους διαφορούντων, ἐκείνοις καὶ τῶν πρόσθεν ἀτυχημάτων παῦλα καὶ παραμυθία Βροῦτος ἦν. καὶ τὴν χάριν εἰς Καίσαρα πάντων ἀνῆπτεν, ὡς αὐτῷ μετὰ τὴν ἐπάνοδον περιϊόντι τὴν Ἰταλίαν ἥδιστον θέαμα τὰς ὑπὸ Βρούτῳ πόλεις γενέσθαι, καὶ Βροῦτον αὐτόν, αὔξοντα τὴν ἐκείνου τιμὴν καὶ συνόντα κεχαρισμένως.", "st": "Brut. 6.10"}, {"sp": "N", "t": "ἐπεὶ δὲ πλειόνων στρατηγιῶν οὐσῶν τὴν μέγιστον ἔχουσαν ἀξίωμα, καλουμένην δὲ πολιτικήν, ἐπίδοξος ἦν ἢ Βροῦτος ἕξειν ἢ Κάσσιος, οἱ μὲν αὐτοὺς λέγουσιν ἐξ αἰτιῶν προτέρων ἡσυχῇ διαφερομένους ἔτι μᾶλλον ὑπὲρ τούτου διαστασιάσαι, καίπερ οἰκείους ὄντας· Ἰουνίᾳ γὰρ, ἀδελφῇ Βρούτου, συνῴκει Κάσσιος· οἱ δὲ Καίσαρος ἔργον γενέσθαι τὴν φιλονεικίαν ταύτην, ἑκατέρῳ κρύφα δι’ ἐλπίδων ἐνδιδόντος ἑαυτόν, ἄχρι οὗ προαχθέντες οὕτω καὶ παροξυνθέντες εἰς ἀγῶνα κατέστησαν. ἠγωνίζετο δὲ Βροῦτος εὐκλείᾳ καὶ ἀρετῇ πρὸς πολλὰ τοῦ Κασσίου καὶ λαμπρὰ τὰ Παρθικὰ νεανιεύματα. Καῖσαρ δ’ ἀκούσας καὶ βουλευόμενος ἐν τοῖς φίλοις εἶπε· δικαιότερα μὲν λέγει Κάσσιος, Βρούτῳ δὲ τὴν πρώτην δοτέον. ἀπεδείχθη δὲ Κάσσιος ἐφ’ ἑτέρᾳ στρατηγός, οὐ τοσοῦτον εὐνοίας ἔχων δι’ ἣν ἔλαβεν ὅσον ὀργῆς ὧν ἀπέτυχε.", "st": "Brut. 7.1"}, {"sp": "N", "t": "Βροῦτος δὲ καὶ τἆλλα μετεῖχε τῆς Καίσαρος δυνάμεως ὅσον ἐβούλετο. βουλομένῳ γὰρ ὑπῆρχεν εἶναι τῶν φίλων πρώτῳ καὶ δύνασθαι πλεῖστον· ἀλλ’ εἷλκεν αὐτὸν ἡ περὶ Κάσσιον ἑταιρεία καὶ ἀπέστρεφεν, αὐτῷ μὲν οὔπω Κασσίῳ διηλλαγμένον ἐξ ἐκείνης τῆς φιλοτιμίας, ἀκούοντα δὲ τῶν φίλων διακελευομένων μὴ περιορᾶν αὑτὸν ὑπὸ Καίσαρος μαλασσόμενον καὶ κηλούμενον, ἀλλὰ φεύγειν τὰς τυραννικὰς φιλοφροσύνας καὶ χάριτας, αἷς οὐ τιμῶντα τὴν ἀρετήν, ἀλλ’ ἐκτέμνοντα τὴν ἀλκὴν καὶ τὸν θυμὸν ὑπερείποντα χρῆσθαι πρὸς αὐτόν.", "st": "Brut. 7.6"}, {"sp": "N", "t": "οὐ μὴν οὐδὲ Καῖσαρ ἀνύποπτος ἦν πάμπαν οὐδ’ ἀδιάβλητος πρὸς αὐτόν, ἀλλὰ τὸ μὲν φρόνημα καὶ τὸ ἀξίωμα καὶ τοὺς φίλους ἐδεδίει τοῦ ἀνδρός, ἐπίστευε δὲ τῷ ἤθει. καὶ πρῶτον μὲν Ἀντωνίου καὶ Δολοβέλλα λεγομένων νεωτερίζειν οὐκ ἔφη τοὺς παχεῖς καὶ κομήτας ἐνοχλεῖν, ἀλλὰ τοὺς ὠχροὺς καὶ ἰσχνοὺς ἐκείνους· Βροῦτον λέγων καὶ Κάσσιον. ἔπειτα τὸν Βροῦτον τινῶν διαβαλλόντων καὶ φυλάττεσθαι παρακελευομένων τῇ χειρὶ τοῦ σώματος ἁπτόμενος εἶπε τί δέ; οὐκ ἂν ὑμῖν δοκεῖ Βροῦτος ἀναμεῖναι τουτὶ τὸ σαρκίον; ὡς οὐδενὶ προσῆκον ἄλλῳ μεθ’ ἑαυτὸν ἢ Βρούτῳ δύνασθαι τοσοῦτον. καὶ μέντοι δοκεῖ πρῶτος ἂν ἐν τῇ πόλει γενέσθαι βεβαίως, ὀλίγον χρόνον ἀνασχόμενος Καίσαρι δευτερεῦσαι καὶ παρακμάσαι τὴν δύναμιν αὐτοῦ καὶ μαρανθῆναι τὴν ἐπὶ τοῖς κατορθώμασιν ἐάσας δόξαν. ἀλλὰ Κάσσιος, ἀνὴρ θυμοειδὴς καὶ μᾶλλον ἰδίᾳ μισοκαῖσαρ ἢ κοινῇ μισοτύραννος, ἐξέκαυσε καὶ κατήπειξε. λέγεται δὲ Βροῦτος μὲν τὴν ἀρχὴν βαρύνεσθαι, Κάσσιος δὲ τὸν ἄρχοντα μισεῖν, ἄλλα τε κατ’ αὐτοῦ ποιούμενος ἐγκλήματα καὶ λεόντων ἀφαίρεσιν, οὓς Κάσσιος μὲν ἀγορανομεῖν μέλλων παρεσκευάσατο, Καῖσαρ δὲ καταληφθέντας ἐν Μεγάροις, ὅθ’ ἡ πόλις ἥλω διὰ Καληνοῦ, κατέσχε. ταῦτα τὰ θηρία συμφορὰν λέγεται μεγάλην γενέσθαι Μεγαρεῦσιν. οἱ μὲν γὰρ ἤδη τῆς πόλεως καταλαμβανομένης διέσπασαν τὰ κλεῖθρα καὶ τοὺς δεσμοὺς ἀνῆκαν, ὡς ἐμποδὼν εἴη τὰ θηρία τοῖς ἐπιφερομένοις, τὰ δ’ ὤρουσεν εἰς αὐτοὺς ἐκείνους καὶ διαθέοντας ἀνόπλους ἥρπαζεν, ὥστε καὶ τοῖς πολεμίοις τὴν ὄψιν οἰκτρὰν γενέσθαι.", "st": "Brut. 8.1"}, {"sp": "N", "t": "τῷ δ’ οὖν Κασσίῳ ταύτην μάλιστά φασιν αἰτίαν ὑπάρξαι τῆς ἐπιβουλῆς· οὐκ ὀρθῶς λέγοντες. ἐξ ἀρχῆς γὰρ ἦν τῇ φύσει τοῦ Κασσίου δυσμένειά τις καὶ χαλεπότης πρὸς τὸ γένος τῶν τυράννων, ὡς ἐδήλωσεν ἔτι παῖς ὢν βαδίζων εἰς ταὐτὸ τῷ τοῦ Σύλλα παιδὶ Φαύστῳ διδασκαλεῖον. ὁ μὲν γὰρ ἐν τοῖς παισὶ μεγαληγορῶν τὴν τοῦ πατρὸς ἐπῄνει μοναρχίαν· ὁ δὲ Κάσσιος ἐπαναστὰς κονδύλους ἐνέτριβεν αὐτῷ. βουλομένων δὲ τῶν ἐπιτρόπων τοῦ Φαύστου καὶ οἰκείων ἐπεξιέναι καὶ δικάζεσθαι Πομπήϊος ἐκώλυσε, καὶ συναγαγὼν εἰς ταὐτὸ τοὺς παῖδας ἀμφοτέρους ἀνέκρινε περὶ τοῦ πράγματος. ἔνθα δὴ λέγεται τὸν Κάσσιον εἰπεῖν ἄγε δή, ὦ Φαῦστε, τόλμησον ἐναντίον τούτου φθέγξασθαι τὸν λόγον ἐκεῖνον ἐφ’ ᾧ παρωξύνθην, ἵνα σου πάλιν ἐγὼ συντρίψω τὸ στόμα.", "st": "Brut. 9.1"}, {"sp": "N", "t": "τοιοῦτος μὲν ὁ Κάσσιος· Βροῦτον δὲ πολλοὶ μὲν λόγοι παρὰ τῶν συνήθων, πολλαῖς δὲ φήμαις καὶ γράμμασιν ἐξεκαλοῦντο καὶ παρώρμων ἐπὶ τὴν πρᾶξιν οἱ πολῖται. τῷ μὲν γὰρ ἀνδριάντι τοῦ προπάτορος Βρούτου τοῦ καταλύσαντος τὴν τῶν βασιλέων ἀρχήν ἐπέγραφον εἴθε νῦν ἦς, Βροῦτε· καὶ ὤφελε ζῆν Βροῦτος. τὸ δ’αὐτοῦ Βρούτου βῆμα στρατηγοῦντος εὑρίσκετο μεθ’ ἡμέραν ἀνάπλεων γραμμάτων τοιούτων Βροῦτε, καθεύδεις; καὶ οὐκ εἶ Βροῦτος ἀληθῶς. αἴτιοι δὲ τούτων οἱ Καίσαρος κόλακες ἄλλας τε τιμὰς ἐπιφθόνους ἀνευρίσκοντες αὐτῷ καὶ διαδήματα τοῖς ἀνδριᾶσι νύκτωρ ἐπιτιθέντες, ὡς τοὺς πολλοὺς ὑπαξόμενοι βασιλέα προσειπεῖν ἀντὶ δικτάτορος. τοὐναντίον δ’ ἀπήντησεν, ὡς ἐν τοῖς περὶ Καίσαρος ἀκριβῶς γέγραπται.", "st": "Brut. 9.5"}, {"sp": "N", "t": "Κασσίῳ δὲ πειρῶντι τοὺς φίλους ἐπὶ Καίσαρα πάντες ὡμολόγουν, εἰ Βροῦτος ἡγοῖτο· δεῖσθαι γὰρ οὐ χειρῶν οὐδὲ τόλμης τὴν πρᾶξιν, ἀλλὰ δόξης ἀνδρὸς οἷος οὗτός ἐστιν, ὥσπερ καταρχομένου καὶ βεβαιοῦντος αὐτῷ τῷ παρεῖναι τὸ δίκαιον· εἰ δὲ μή, καὶ δρῶντας ἀθυμοτέρους ἔσεσθαι καὶ δράσαντας ὑποπτοτέρους· ὡς οὐκ ἂν ἐκείνου τὸ ἔργον, εἰ καλὴν αἰτίαν εἶχεν, ἀπειπαμένου. ταῦτα συμφρονήσας ἐνέτυχε Βρούτῳ πρότερος ἐκ τῆς διαφορᾶς ἐκείνης, καὶ μετὰ τὰς διαλύσεις καὶ φιλοφροσύνας ἠρώτησεν εἰ τῇ νουμηνίᾳ τοῦ Μαρτίου μηνὸς ἔγνωκεν εἰς σύγκλητον παρεῖναι· πυνθάνεσθαι γὰρ ὡς λόγον ὑπὲρ βασιλείας Καίσαρος οἱ φίλοι τότε καθήσοιεν. φήσαντος δὲ τοῦ Βρούτου μὴ παριέναι, τί οὖν, εἶπεν ὁ Κάσσιος, ἂν καλῶσιν ἡμᾶς; ἐμὸν ἔργον, ἔφη ὁ Βροῦτος, ἤδη τὸ μὴ σιωπᾶν, ἀλλ’ ἀμύνειν τῇ πατρίδι καὶ προαποθνῄσκειν τῆς ἐλευθερίας. καὶ ὁ Κάσσιος ἐπαρθείς, τίς δ’, εἶπε, Ῥωμαίων ἀνέξεται σοῦ προαποθνῄσκοντος; ἆρα ἀγνοεῖς, ὦ Βροῦτε, σεαυτόν; ἢ τὸ βῆμά σου δοκεῖς καταγράφειν τοὺς ὑφάντας καὶ τοὺς καπήλους, οὐχὶ τοὺς πρώτους καὶ κρατίστους ταῦτα ποιεῖν, παρὰ μὲν τῶν ἄλλων στρατηγῶν ἐπιδόσεις καὶ θέας καὶ μονομάχους, παρὰ σοῦ δὲ ὡς ὄφλημα πατρικὸν τὴν κατάλυσιν τῆς τυραννίδος ἀπαιτοῦντας, αὐτοὺς δ’ ὑπὲρ σοῦ πάντα πάσχειν προθύμους ὄντας, οἷον ἀξιοῦσι καὶ προσδέχονται φανέντος; ἐκ τούτου περιβαλὼν τὸν Βροῦτον ἠσπάζετο, καὶ διαλυθέντες οὕτως ἐτρέποντο πρὸς τοὺς φίλους.", "st": "Brut. 10.1"}, {"sp": "N", "t": "ἦν δέ τις Γάϊος Λιγάριος τῶν Πομπηΐου φίλων, ὃν ἐπὶ τούτῳ κατηγορηθέντα Καῖσαρ ἀπέλυσεν. οὗτος, οὐχ ἧς ἀφείθη δίκης χάριν ἔχων, ἀλλὰ δι’ ἣν ἐκινδύνευσεν ἀρχὴν βαρυνόμενος, ἐχθρὸς ἦν Καίσαρι, τῶν δὲ περὶ Βροῦτον ἐν τοῖς μάλιστα συνήθης. πρὸς τοῦτον ἀσθενοῦντα Βροῦτος εἰσελθών, ὦ Λιγάριε, εἶπεν, ἐν οἵῳ καιρῷ νοσεῖς. κἀκεῖνος εὐθὺς εἰς ἀγκῶνα διαναστὰς καὶ λαβόμενος αὐτοῦ τῆς δεξιᾶς, ἀλλ’ εἴ τι, φησὶν, ὦ Βροῦτε, σεαυτοῦ φρονεῖς ἄξιον, ὑγιαίνω.", "st": "Brut. 11.1"}, {"sp": "N", "t": "ἐκτούτου διαπειρώμενοι κρύφα τῶν γνωρίμων οἷς ἐπίστευον ἀνεκοινοῦντο καὶ προσελάμβανον, οὐ μόνον τῶν συνήθων ποιούμενοι τὴν αἵρεσιν, ἀλλ’ ὅσους ἠπίσταντο τολμητὰς ὄντας ἀγαθοὺς καὶ θανάτου καταφρονητάς. διὸ καὶ Κικέρωνα, τοῦτο μέν πίστεως, τοῦτο δὲ εὐνοίας ἕνεκα πρῶτον ὄντα παρ’ αὐτοῖς, ἀπεκρύψαντο, μὴ τῷ φύσει τόλμης ἐνδεὴς εἶναι προσειληφὼς ὑπὸ χρόνου γεροντικὴν εὐλάβειαν, εἶτα πάντα καθ’ ἕκαστον ἀνάγων τοῖς λογισμοῖς εἰς ἄκραν ἀσφάλειαν, ἀμβλύνῃ τὴν ἀκμὴν αὐτῶν τῆς προθυμίας τάχους δεομένην. ἐπεὶ καὶ τῶν ἄλλων ἑταίρων ὁ Βροῦτος Στατίλιόν τε παρέλιπε τὸν Ἐπικούρειον καὶ Φαώνιον ἐραστὴν Κάτωνος, ὅτι πόρρωθεν αὐτοῖς τοιαύτην τινὰ κύκλῳ περιβαλόντος ἐν τῷ διαλέγεσθαι καὶ συμφιλοσοφεῖν πεῖραν, ὁ μέν Φαώνιος ἀπεκρίνατο χεῖρον εἶναι μοναρχίας παρανόμου πόλεμον ἐμφύλιον, ὁ δὲ Στατίλιος ἔφη τῷ σοφῷ καὶ νοῦν ἔχοντι διὰ φαύλους καὶ ἀνοήτους κινδυνεύειν καὶ ταράττεσθαι μὴ καθήκειν. παρὼν δὲ Λαβεὼν ἀντεῖπεν ἀμφοτέροις. καὶ ὁ Βροῦτος τότε μέν ὡς ἔχοντός τι τοῦ λόγου χαλεπὸν καὶ δύσκριτον ἀπεσιώπησεν, ὕστερον δὲ Λαβεῶνι κοινοῦται τὸ βούλευμα. δεξαμένου δὲ προθύμως, τὸν ἕτερον Βροῦτον, ἐπίκλησιν Ἀλβῖνον, ἄλλως μέν οὐκ ὄντα ῥέκτην οὐδὲ θαρραλέον, ἐρρωμένον δὲ πλήθει μονομάχων οὓς ἐπὶ θέᾳ Ῥωμαίων ἔτρεφε, καὶ παρὰ Καίσαρι πιστευόμενον, ἐδόκει προσάγεσθαι. Κασσίου δὲ καὶ Λαβεῶνος αὐτῷ διαλεγομένων οὐδὲν ἀπεκρίνατο, Βρούτῳ δ’ αὐτὸς ἐντυχὼν ἰδίᾳ καὶ μαθὼν ὅτι τῆς πράξεως ἡγεμών ἐστιν, ὡμολόγησε συμπράξειν προθύμως. καὶ τῶν ἄλλων δὲ τοὺς πλείστους καὶ ἀρίστους ἡ δόξα τοῦ Βρούτου προσήγετο. καὶ μήθ’ ὅρκον συνομόσαντες μήτε πίστιν καθ’ ἱερῶν λαβόντες ἢ δόντες, οὕτως ἅπαντες ἔσχον ἐν ἑαυτοῖς καὶ κατεσιώπησαν καὶ συνδιήνεγκαν ὥστε μαντείαις καὶ φάσμασι καὶ ἱεροῖς ὑπὸ τῶν θεῶν προδεικνυμένην ἄπιστον γενέσθαι τὴν πρᾶξιν.", "st": "Brut. 12.1"}, {"sp": "N", "t": "ὁ δὲ Βροῦτος, ἅτε δὴ τὰ πρῶτα τῆς Ῥώμης φρονήματα καί γένη καί ἀρετὰς ἐξηρτημένος ἑαυτοῦ καί περινοῶν πάντα τὸν κίνδυνον, ἔξω μὲν ἐπειρᾶτο κατέχειν παρ’ ἑαυτῷ καί κατακοσμεῖν τὴν διάνοιαν, οἴκοι δὲ καί νύκτωρ οὐκ ἦν ὁ αὐτός, ἀλλὰ τὰ μὲν ἄκοντα τῶν ὕπνων αὐτὸν ἠ φροντὶς ἐξέφερε, τὰ δὲ μᾶλλον ἐνδυόμενος τῷ λογισμῷ καί διατρίβων ἐν ταῖς ἀπορίαις οὐκ ἐλάνθανε τὴν γυναῖκα συναναπαυομένην, ὅτι μεστός ἐστι ταραχῆς ἀήθους καί κυκλεῖ τι παρ’ ἑαυτῷ δύσφορον βούλευμα καί δυσεξέλικτον.", "st": "Brut. 13.1"}, {"sp": "N", "t": "ἡ δὲ Πορκία θυγάτηρ μὲν, ὥσπερ εἴρηται, Κάτωνος ἦν, εἶχε δ’ αὐτὴν ὁ Βροῦτος ἀνεψιὸς ὢν οὐκ ἐκ παρθενίας, ἀλλὰ τοῦ προτέρου τελευτήσαντος ἀνδρὸς ἔλαβε κόρην οὖσαν ἔτι καί παιδίον ἔχουσαν ἐξ ἐκείνου μικρόν, ᾧ Βύβλος ἦν ὄνομα· καί τι βιβλίδιον μικρὸν ἀπομνημονευμάτων Βρούτου γεγραμμένον ὑπ’ αὐτοῦ διασῴζεται. φιλόστοργος δ’ ἡ Πορκία καί φίλανδρος οὖσα καί μεστὴ φρονήματος νοῦν ἔχοντος, οὐ πρότερον ἐπεχείρησεν ἀνερέσθαι τὸν ἄνδρα περὶ τῶν ἀπορρήτων ἢ λαβεῖν ἑαυτῆς τοιαύτην διάπειραν. λαβοῦσα μαχαίριον ᾧ τοὺς ὄνυχας οἱ κουρεῖς ἀφαιροῦσι, καί πάσας ἐξελάσασα τοῦ θαλάμου τὰς ὀπαδούς, τομὴν ἐνέβαλε τῷ μηρῷ βαθεῖαν, ὥστε ῥύσιν αἵματος πολλὴν γενέσθαι καί μετὰ μικρὸν ὀδύνας τε νεανικὰς καί φρικώδεις πυρετοὺς ἐπιλαβεῖν ἐκ τοῦ τραύματος. ἀγωνιῶντος δὲ τοῦ Βρούτου καί δυσφοροῦντος ἐν ἀκμῇ τῆς ἀλγηδόνος οὖσα διελέχθη πρὸς αὐτὸν οὕτως· ἐγὼ, Βροῦτε, Κάτωνος οὖσα θυγάτηρ εἰς τὸν σὸν ἐδόθην οἶκον οὐχ ὥσπερ αἱ παλλακευόμεναι, κοίτης μεθέξουσα καί τραπέζης μόνον, ἀλλὰ κοινωνὸς μὲν ἀγαθῶν εἶναι, κοινωνὸς δὲ ἀνιαρῶν. τὰ μὲν οὖν σὰ πάντα περὶ τὸν γάμον ἄμεμπτα· τῶν δὲ παρ’ ἐμοῦ τίς ἀπόδειξις ἢ χάρις, εἰ μήτε σοι πάθος ἀπόρρητον συνδιοίσω μήτε φροντίδα πίστεως δεομένην; οἶδ’ὅτι γυναικεία φύσις ἀσθενὴς δοκεῖ λόγον ἐνεγκεῖν ἀπόρρητον ἀλλ’,’ ἔστι τίς, ὦ Βροῦτε, καί τροφῆς ἀγαθῆς καί ὁμιλίας χρηστῆς εἰς ἦθος ἰσχύς· ἐμοὶ δὲ καί τὸ Κάτωνος εἶναι θυγατέρα καί τὸ Βρούτου γυναῖκα πρόσεστιν οἷς πρότερον μὲν ἧττον ἐπεποίθειν, νῦν δ’ ἐμαυτὴν ἔγνωκα καί πρὸς πόνον ἀήττητον εἶναι. ταῦτ’ εἰποῦσα δείκνυσιν αὐτῷ τὸ τραῦμα καί διηγεῖται τὴν πεῖραν. ὁ δ’ ἐκπλαγεὶς καί ἀνατείνας τὰς χεῖρας ἐπεύξατο δοῦναι τοὺς θεοὺς αὐτῷ κατορθοῦντι τὴν πρᾶξιν ἀνδρὶ Πορκίας ἀξίῳ φανῆναι. καί τότε μὲν ἀνελάμβανε τὴν γυναῖκα.", "st": "Brut. 13.3"}, {"sp": "N", "t": "προγραφείσης δὲ βουλῆς, εἰς ἣν ἐπίδοξος ἦν ἀφίξεσθαι Καῖσαρ, ἔγνωσαν ἐπιχειρεῖν· καὶ γὰρ ἁθρόοι μετ’ ἀλλήλων ἀνυπόπτως ἔσεσθαι τότε, καὶ πάντας ἕξειν ὁμοῦ τοὺς ἀρίστους καὶ πρώτους ἄνδρας, ἔργου μεγάλου πραχθέντος εὐθὺς ἀντιλαμβανομένους τῆς ἐλευθερίας. ἐδόκει δὲ καὶ τὸ τοῦ τόπου θεῖον εἶναι καὶ πρὸς αὐτῶν στοὰ γὰρ ἦν μία τῶν περὶ τὸ θέατρον, ἐξέδραν ἔχουσα ἐν ᾗ Πομπηΐου τις εἰκὼν εἱστήκει, τῆς πόλεως στησαμένης ὅτε ταῖς στοαῖς καὶ τῷ θεάτρῳ τὸν τόπον ἐκεῖνον ἐκόσμησεν. εἰς ταύτην οὖν ἡ σύγκλητος ἐκαλεῖτο τοῦ Μαρτίου μηνὸς μάλιστα μεσοῦντος (εἰδοὺς Μαρτίας τὴν ἡμέραν Ῥωμαῖοι καλοῦσιν), ὥστε καὶ δαίμων τις ἐδόκει τὸν ἄνδρα τῇ Πομπηΐου δίκῃ προσάξειν.", "st": "Brut. 14.1"}, {"sp": "N", "t": "ἐλθούσης δὲ τῆς ἡμέρας Βροῦτος μὲν ὑποζωσάμενος ἐγχειρίδιον μόνης συνειδυίας τῆς γυναικὸς προῆλθεν, οἱ δ’ ἄλλοι πρὸς Κάσσιον ἁθροισθέντες τὸν υἱὸν αὐτοῦ τὸ καλούμενον ἀνδρεῖον ἱμάτιον ἀναλαμβάνοντα κατῆγον εἰς ἀγοράν. ἐκεῖθεν δὲ πάντες εἰς τὴν Πομπηΐου στοὰν ἐμβαλόντες διέτριβον, ὡς αὐτίκα Καίσαρος ἀφιξομένου πρὸς τὴν σύγκλητον. ἔνθα δὴ μάλιστα τῶν ἀνδρῶν τὸ ἀπαθὲς καὶ παρὰ τὰ δεινὰ καθεστηκὸς ἐθαύμασεν ἄν τις εἰδὼς τὸ μέλλον, ὅτι πολλοῖς διὰ τὸ στρατηγεῖν ἀναγκαζόμενοι χρηματίζειν οὐ μόνον πρᾴως ἠκροῶντο τῶν ἐντυγχανόντων καὶ διαφερομένων ὥσπερ σχολάζοντες, ἀλλὰ καὶ τὰς κρίσεις ἑκάστοις ἀκριβεῖς καὶ μετὰ γνώμης ἐδίδοσαν, ἐπιμελῶς προσέχοντες. ἐπεὶ δέ τις μὴ βουλόμενος δίκην ὑποσχεῖν ἐπεκαλεῖτο Καίσαρα καὶ πολὺς ἦν βοῶν καὶ μαρτυρόμενος, ἀποβλέψας ὁ Βροῦτος εἰς τοὺς παρόντας, ἐμὲ Καῖσαρ, εἶπεν, οὔτε κωλύει ποιεῖν τὰ κατὰ τοὺς νόμους οὔτε κωλύσει.", "st": "Brut. 14.4"}, {"sp": "N", "t": "καίτοι πολλὰ θορυβώδη κατὰ τύχην αὐτοῖς προσέπεσε· πρῶτον μὲν καὶ μάλιστα τὸ βραδύνειν τὸν Καίσαρα τῆς ἡμέρας προηκούσης καὶ δυσιεροῦντα κατέχεσθαι μὲν ὑπὸ τῆς γυναικὸς οἴκοι, κωλύεσθαι δὲ προελθεῖν ὑπὸ τῶν μάντεων. δεύτερον δὲ Κάσκᾳ τῶν συνειδότων ἑνὶ προσελθών τις καὶ λαβόμενος τῆς δεξιᾶς, σὺ μὲν, εἶπεν, ἀπεκρύψω τὸ ἀπόρρητον, ὦ Κάσκα, πρὸς ἡμᾶς, Βροῦτος δέ μοι πάντα μεμήνυκεν. ἐκπλαγέντος δὲ τοῦ Κάσκα γελάσας ἐκεῖνος, πόθεν, ἔφη, ταχέως οὕτως, ὦ μακάριε, πεπλούτηκας ὥστ’ εἰς ἀγορανομίαν ἀποδύεσθαι; παρὰ τοσοῦτον μὲν ὁ Κάσκας ἦλθε σφαλεὶς ἀμφιβολίᾳ προέσθαι τὸ ἀπόρρητον· αὐτὸν δὲ Βροῦτον καὶ Κάσσιον ἀνὴρ βουλευτικὸς Ποπίλιος Λαίνας ἀσπασάμενος προθυμότερον καὶ ψιθυρίσας ἠρέμα, συνεύχομαι, φησὶν, ὑμῖν ἐκτελεῖν ἃ κατὰ νοῦν ἔχετε καὶ παρακελεύομαι μὴ βραδύνειν· οὐ γὰρ σιωπᾶται τὸ πρᾶγμα. καὶ ταῦτ’ εἰπὼν ἀπέστη πολλὴν ὑποψίαν ἐμβαλὼν τοῦ πεπύσθαι τὴν πρᾶξιν.", "st": "Brut. 15.1"}, {"sp": "N", "t": "ἐν τούτῳ δέ τις οἴκοθεν ἔθει πρὸς τὸν Βροῦτον ἀγγέλλων αὐτῷ τὴν γυναῖκα θνῄσκειν. ἡγὰρ Πορκία πρὸς τὸ μέλλον ἐκπαθὴς οὖσα καὶ τὸ μέγεθος μὴ φέρουσα τῆς φροντίδος ἑαυτήν τε μόλις οἴκοι κατεῖχε, καὶ πρὸς πάντα θόρυβον καὶ βοήν, ὥσπερ αἱ κατάσχετοι τοῖς βακχικοῖς πάθεσιν, ἐξᾴττουσα τῶν μὲν εἰσιόντων ἀπ’ ἀγορᾶς ἕκαστον ἀνέκρινεν ὅ τι πράττοι Βροῦτος, ἑτέρους δὲ συνεχῶς ἐξέπεμπε. τέλος δὲ τοῦ χρόνου μῆκος λαμβάνοντος οὐκέτ’ ἀντεῖχεν ἡ τοῦ σώματος δύναμις, ἀλλ’ ἐξελύθη καὶ κατεμαραίνετο τῆς ψυχῆς ἀλυούσης διὰ τὴν ἀπορίαν καὶ παρελθεῖν μὲν εἰς τὸ δωμάτιον οὐκ ἔφθη, περιΐστατο δ’ αὐτὴν, ὥσπερ ἐτύγχανεν, ἐν μέσῳ καθεζομένην λιποθυμία καὶ θάμβος ἀμήχανον, ἥ τε χρόα μεταβολὴν ἐλάμβανε καὶ τὴν φωνὴν ἐπέσχητο παντάπασιν. αἱ δὲ θεράπαιναι πρὸς τὴν ὄψιν ἀνωλόλυξαν, καὶ τῶν γειτόνων συνδραμόντων ἐπὶ θύρας ταχὺ προῆλθε φήμη καὶ διεδόθη λόγος ὡς τεθνηκυίας αὐτῆς. οὐ μὴν ἀλλ’ ἐκείνην μὲν ἀναλάμψασαν ἐν βραχεῖ καὶ παρ’ ἑαυτῇ γενομένην αἱ γυναῖκες ἐθεράπευον ὁ δὲ Βροῦτος ὑπὸ τοῦ λόγου προσπεσόντος αὐτῷ συνεταράχθη μὲν, ὡς εἰκός, οὐ μήν γε κατέλιπε τὸ κοινὸν οὐδ’ ἐρρύη πρὸς τὸ οἰκεῖον ὑπὸ τοῦ πάθους.", "st": "Brut. 15.5"}, {"sp": "N", "t": "ἤδη δὲ Καῖσαρ ἀπηγγέλλετο προσιών ἐν φορείῳ κομιζόμενος. ἐγνώκει γὰρ ἐπὶ τοῖς ἱεροῖς ἀθυμῶν μηδὲν ἐπικυροῦν τότε τῶν μειζόνων, ἀλλ’ ὑπερβάλλεσθαι σκηψάμενος ἀσθένειαν. ἐκβάντι δ’ αὐτῷ τοῦ φορείου προσρυεὶς Ποπίλιος Λαίνας, ἐκεῖνος ὁ μικρῷ πρόσθεν εὐξάμενος τοῖς περὶ Βροῦτον ἐπιτυγχάνειν καί κατορθοῦν, διελέγετο πλείω χρόνον ἐφισταμένῳ καί προσέχοντι τὸν νοῦν. οἱ δὲ συνωμόται (λεγέσθω γὰρ οὕτως) τῆς μὲν φωνῆς οὐκ ἐπαΐοντες αὐτοῦ, τεκμαιρόμενοι δ’ ἀφ’ ὧν ὑπενόουν μήνυσιν εἶναι τῆς ἐπιβουλῆς τὴν κοινολογίαν, ἀνέπεσόν τε ταῖς γνώμαις, καί πρὸς ἀλλήλους ἔβλεψαν ἀνθομολογούμενοι διὰ τῶν προσώπων ὡς χρὴ μὴ περιμένειν σύλληψιν, ἀλλ’ εὐθὺς ἀποθνῄσκειν δι’ αὑτῶν. Κασσίου δ’ ἤδη καί τινων ἄλλων τὰς χεῖρας ἐπιβεβληκότων ταῖς λαβαῖς ὑπὸ τὰ ἱμάτια καί σπωμένων τὰ ἐγχειρίδια, Βροῦτος ἐγκατιδὼν τῷ τοῦ Λαίνα σχήματι δεομένου σπουδὴν καί οὐχὶ κατηγοροῦντος, ἐφθέγξατο μὲν οὐδὲν διὰ τὸ πολλοὺς ἀλλοτρίους ἀναμεμῖχθαι, φαιδρῷ δὲ τῷ προσώπῳ τοὺς περὶ Κάσσιον ἐθάρρυνε. καί μετὰ μικρὸν ὁ Λαίνας τὴν δεξιὰν τοῦ Καίσαρος καταφιλήσας ἀπέστη, φανερὸς γενόμενος ὡς ὑπὲρ ἑαυτοῦ καί τῶν αὑτῷ τινος διαφερόντων ἐποιεῖτο τὴν ἔντευξιν.", "st": "Brut. 16.1"}, {"sp": "N", "t": "τῆς δὲ βουλῆς εἰς τὴν ἐξέδραν προεισελθούσης οἱ μὲν ἄλλοι τὸν δίφρον τοῦ Καίσαρος περιέστησαν ὡς ἐντυγχάνειν τι μέλλοντες αὐτῷ. καὶ Κάσσιον μὲν λέγεται τρέποντα τὸ πρόσωπον εἰς τὴν εἰκόνα τοῦ Πομπηΐου παρακαλεῖν ὥσπερ αἰσθανόμενον, Τρεβώνιος δὲ περὶ τὰς θύρας Ἀντώνιον ἐπισπασάμενος καὶ προσομιλῶν ἔξω κατέσχε. Καίσαρι δὲ εἰσιόντι μὲν ἡ σύγκλητος ὑπεξανέστη, καθεζόμενον δ’ εὐθὺς ἐκεῖνοι περιέσχον ἁθρόοι, Τίλλιον Κίμβρον ἐξ ἑαυτῶν προβάλλοντες ὑπὲρ ἀδελφοῦ φυγάδος δεόμενον· καὶ συνεδέοντο πάντες, ἁπτόμενοί τε χειρῶν καὶ στέρνα καὶ κεφαλὴν κατεφίλουν. ἀποτριβομένου δὲ τὰς δεήσεις τὸ πρῶτον, εἶθ’, ὡς οὐκ ἀνίεσαν, ἐξανισταμένου βίᾳ, Τίλλιος μὲν ἀμφοτέραις ταῖς χερσὶν ἐκ τῶν ὤμων κατέσπασε τὸ ἱμάτιον, Κάσκας δὲ πρῶτος (εἱστήκει γὰρ ὄπισθεν) ἀνασπάσας τὸ ξίφος διελαύνει, οὐκ εἰς βάθος, παρὰ τὸν ὦμον. ἀντιλαμβανομένου δὲ τῆς λαβῆς τοῦ Καίσαρος καὶ μέγα Ῥωμαϊστὶ ἀνακραγόντος, ἀνόσιε Κάσκα, τί ποιεῖς; ἐκεῖνος Ἑλληνιστὶ τὸν ἀδελφὸν προσαγορεύσας ἐκέλευσε βοηθεῖν. ἤδη δὲ παιόμενος ὑπὸ πολλῶν καὶ κύκλῳ περιβλέπων καὶ διώσασθαι βουλόμενος, ὡς εἶδε Βροῦτον ἑλκόμενον ξίφος ἐπ’ αὐτόν, τὴν χεῖρα τοῦ Κάσκα κρατῶν ἀφῆκε, καὶ τῷ ἱματίῳ τὴν κεφαλὴν ἐγκαλυψάμενος παρέδωκε τὸ σῶμα ταῖς πληγαῖς. οἱ δ’ἀφειδῶς ἀναπεπλεγμένοι πολλοῖς περὶ τὸ σῶμα χρώμενοι τοῖς ξίφεσιν ἀλλήλους ἐτίτρωσκον, ὥστε καὶ Βροῦτον εἰς τὴν χεῖρα πληγὴν λαβεῖν τοῦ φόνου συνεφαπτόμενον, πίμπλασθαι δὲ τοῦ αἵματος ἅπαντας.", "st": "Brut. 17.1"}, {"sp": "N", "t": "οὕτω δ’ ἀποθανόντος αὐτοῦ Βροῦτος μὲν εἰς μέσον προελθὼν ἐβούλετο λέγειν καὶ κατεῖχε θαρρύνων τὴν σύγκλητον· ἡ δ’ ὑπὸ δέους ἔφευγεν ἀτάκτως, καὶ περὶ τὰς θύρας ὠθισμὸς ἦν καὶ τάραχος, οὐδενὸς διώκοντος οὐδὲ κατεπείγοντος. ἰσχυρῶς γὰρ ἐδέδοκτο μηδένα κτείνειν ἕτερον, ἀλλὰ πάντας ἐπὶ τὴν ἐλευθερίαν ἀνακαλεῖσθαι. καὶ τοῖς μὲν ἄλλοις πᾶσιν, ὁπηνίκα διεσκοποῦντο τὴν πρᾶξιν, ἤρεσκεν Ἀντώνιον ἐπισφάττειν Καίσαρι, μοναρχικὸν ἄνδρα καὶ ὑβριστὴν, ἰσχύν τε πεποιημένον ὁμιλίᾳ καὶ συνηθείᾳ πρὸς τὸ στρατιωτικόν, καὶ μάλισθ’ ὅτι τῷ φύσει σοβαρῷ καὶ μεγαλοπράγμονι προσειλήφει τὸ τῆς ὑπατείας ἀξίωμα τότε Καίσαρι συνάρχων. ἀλλὰ Βροῦτος ἐνέστη πρὸς τὸ βούλευμα, πρῶτον μὲν ἰσχυριζόμενος τῷ δικαίῳ, δεύτερον δ’ ὑποτιθεὶς ἐλπίδα τῆς μεταβολῆς. οὐγὰρ ἀπεγίνωσκεν εὐφυᾶ καὶ φιλότιμον ἄνδρα καὶ δόξης ἐραστὴν τὸν Ἀντώνιον, ἐκποδὼν Καίσαρος γενομένου, συνεφάψεσθαι τῇ πατρίδι τῆς ἐλευθερίας, ἐπισπασθέντα τῷ ζήλῳ πρὸς τὸ καλὸν ὑπ’ αὐτῶν. οὕτω μὲν Ἀντώνιον Βροῦτος περιεποίησεν ἐν δὲ τῷ τότε φόβῳ μεταβαλὼν ἐσθῆτα δημοτικὴν ἔφυγεν.", "st": "Brut. 18.1"}, {"sp": "N", "t": "οἱ δὲ περὶ Βροῦτον εἰς τὸ Καπετώλιον ἐχώρουν, ᾑμαγμένοι τὰς χεῖρας, καὶ τὰ ξίφη γυμνὰ δεικνύντες ἐπὶ τὴν ἐλευθερίαν παρεκάλουν τοὺς πολίτας. τὸ μὲν οὖν πρῶτον ἦσαν ἀλαλαγμοί, καὶ διαδρομαὶ τῷ πάθει κατὰ τύχην ἐπιγινόμεναι πλείονα τὸν θόρυβον ἐποίησαν· ὡς δ’οὔτε φόνος ἄλλος οὔθ’ ἁρπαγή τινος ἐγίνετο τῶν κειμένων, θαρροῦντες ἀνέβαινον οἵ τε βουλευταὶ καὶ τῶν δημοτῶν πολλοὶ πρὸς τοὺς ἄνδρας εἰς τὸ Καπετώλιον. ἁθροισθέντος δὲ τοῦ πλήθους διελέχθη Βροῦτος ἐπαγωγὰ τοῦ δήμου καὶ πρέποντα τοῖς πεπραγμένοις. ἐπαινούντων δὲ καὶ κατιέναι βοώντων θαρροῦντες κατέβαινον εἰς ἀγοράν, οἱ μὲν ἄλλοι συνεπόμενοι μετ’ ἀλλήλων, Βροῦτον δὲ πολλοὶ τῶν ἐπιφανῶν περιέποντες ἐν μέσῳ πάνυ λαμπρῶς κατῆγον ἀπὸ τῆς ἄκρας καὶ κατέστησαν ἐπὶ τῶν ἐμβόλων. πρὸς δὲ τὴν ὄψιν οἱ πολλοί, καίπερ μιγάδες ὄντες καὶ παρεσκευασμένοι θορυβεῖν, διέτρεσαν καὶ τὸ μέλλον ἐδέχοντο κόσμῳ καὶ σιωπῇ. προελθόντος δ’ αὐτοῦ πάντες ἡσυχίαν τῷ λόγῳ παρέσχον ὅτι δ’ οὐ πᾶσι πρὸς ἡδονὴν ἐγεγόνει τὸ ἔργον, ἐδήλωσαν ἀρξαμένου λέγειν Κίννα καὶ κατηγορεῖν Καίσαρος ἀναρρηγνύμενοι πρὸς ὀργὴν καὶ κακῶς τὸν Κίνναν λέγοντες, ὥστε πάλιν τοὺς ἄνδρας εἰς τὸ Καπετώλιον ἀπελθεῖν. ἔνθα δὴ δεδιὼς πολιορκίαν ὁ Βροῦτος ἀπέπεμπε τοὺς ἀρίστους τῶν συναναβάντων, οὐκ ἀξιῶν τῆς αἰτίας μὴ μετέχοντας αὐτοὺς συνυποδύεσθαι τὸν κίνδυνον.", "st": "Brut. 18.7"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τῇ ὑστεραίᾳ τῆς βουλῆς συνελθούσης εἰς τὸ τῆς Γῆς ἱερόν, Ἀντωνίου δὲ καὶ Πλάγκου καὶ Κικέρωνος εἰπόντων περὶ ἀμνηστίας καὶ ὁμονοίας, ἔδοξε μὴ μόνον ἄδειαν εἶναι τοῖς ἀνδράσιν, ἀλλὰ καὶ γνώμην ὑπὲρ τιμῶν προθεῖναι τοὺς ὑπάτους, καὶ ταῦτ’ ἐπιψηφισάμενοι διελύθησαν. Ἀντωνίου δὲ τὸν υἱὸν εἰς τὸ Καπετώλιον ὁμηρεύσοντα πέμψαντος κατῆλθον οἱ περὶ Βροῦτον, ἀσπασμοί τε καὶ δεξιώσεις ἐγένοντο πάντων ἀναμειχθέντων. καὶ Κάσσιον μὲν Ἀντώνιος εἱστία παραλαβών, Βροῦτον δὲ Λέπιδος, τοὺς δὲ ἄλλους, ὥς τις εἶχε πρὸς ἕκαστον ἢ συνηθείας ἢ φιλοφροσύνης. ἅμα δ’ ἡμέρᾳ πάλιν συνελθόντες οἱ βουλευταὶ πρῶτον μὲν Ἀντωνίῳ τιμὰς ἔδοσαν ὡς καταπαύσαντι πολέμων ἐμφυλίων ἀρχήν ἔπειτα τῶν περὶ Βροῦτον ἦσαν ἔπαινοι τῶν παρόντων, καὶ τέλος ἐπαρχιῶν διανομαί. Βρούτῳ μὲν γὰρ ἐψηφίσαντο Κρήτην, Κασσίῳ δὲ Λιβύην, Τρεβωνίῳ δὲ Ἀσίαν καὶ Κίμβρῳ Βιθυνίαν, τῷ δ’ ἑτέρῳ Βρούτῳ τὴν περὶ τὸν Ἠριδανὸν Γαλατίαν.", "st": "Brut. 19.1"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα περὶ τῶν Καίσαρος διαθηκῶν καὶ ταφῆς αὐτοῦ λόγων ἐμπεσόντων, καὶ τῶν περὶ τὸν Ἀντώνιον ἀξιούντων τάς τε διαθήκας ἀναγνωσθῆναι καὶ τοῦ σώματος ἐκφορὰν γενέσθαι μὴ κεκρυμμένην μηδ’ ἄτιμον, ὡς μὴ καὶ τοῦτο παροξύνῃ τὸν δῆμον, Κάσσιος μὲν ἰσχυρῶς ἀντέλεγεν, εἶξε δὲ Βροῦτος καὶ συνεχώρησε, δεύτερον ἁμαρτεῖν τοῦτο δόξας. καὶ γὰρ Ἀντωνίου φεισάμενος αἰτίαν ἔσχεν ἐπιτειχίσαι τῇ συνωμοσίᾳ βαρὺν καὶ δύσμαχον πολέμιον, καὶ τὰ περὶ τὴν ταφὴν ὃν ὁ Ἀντώνιος ἠξίου τρόπον ἐάσας γενέσθαι τοῦ παντὸς σφαλῆναι. πρῶτον μὲν γὰρ ἐν ταῖς διαθήκαις δεδομένων κατ’ ἄνδρα Ῥωμαίοις πᾶσι δραχμῶν ἑβδομήκοντα πέντε καὶ τῷ δήμῳ τῶν πέραν τοῦ ποταμοῦ κήπων ἀπολελειμμένων, οὗ νῦν ἐστι Τύχης ἱερόν, εὔνοια θαυμαστὴ καὶ πόθος αὐτοῦ τοὺς πολίτας εἷλεν· ἔπειτα τοῦ σώματος εἰς τὴν ἀγορὰν κομισθέντος Ἀντώνιος ἔπαινον, ὥσπερ ἔθος ἐστὶ, διεξελθών, καὶ τὰ πλήθη κινούμενα πρὸς τὸν λόγον ὁρῶν, εἰς οἶκτον μετέβαλε, καὶ τὴν ἐσθῆτα λαβὼν τὴν Καίσαρος ᾑμαγμένην ἀνέπτυξεν, ἐπιδεικνύμενος τάς διακοπὰς καὶ τῶν τραυμάτων τὸ πλῆθος. ἦν οὖν ἰδεῖν οὐδὲν ἔτι κόσμῳ γινόμενον· ἀλλ’ οἱ μὲν ἐβόων τοὺς ἀνδροφόνους ἀναιρεῖν, οἱ δ’, ὥσπερ ἐπὶ Κλωδίου τοῦ δημαγωγοῦ πρότερον, ἀπὸ τῶν ἐργαστηρίων τὰ βάθρα καὶ τάς τραπέζας ἀνασπῶντες καὶ συγκομίζοντες εἰς ταὐτό παμμεγέθη πυρὰν ἔνησαν· καὶ τὸν νεκρὸν ἐπιθέντες ἐν μέσῳ πολλῶν μὲν ἱερῶν, πολλῶν δ’ ἀσύλων καὶ ἀβεβήλων τόπων καθήγιζον. ὡς δὲ τὸ πῦρ ἐξέλαμψεν, ἀλλαχόθεν ἄλλος προσφερόμενοι καὶ δαλοὺς ἀνασπῶντες ἡμιφλέκτους διέθεον ἐπὶ τάς οἰκίας τῶν ἀνῃρηκότων αὐτὸν ὡς ἐμπρήσοντες.", "st": "Brut. 20.1"}, {"sp": "N", "t": "ἀλλ’ ἐκεῖνοι μὲν εὖ πεφραγμένοι πρότερον ἀπεκρούσαντο τὸν κίνδυνον ἦν δέ τις Κίννας, ποιητικὸς ἀνὴρ, οὐδὲν τῆς αἰτίας μετέχων, ἀλλὰ καὶ φίλος Καίσαρος γεγονώς. οὗτος ὄναρ ᾤετο καλούμενος ὑπὸ Καίσαρος ἐπὶ δεῖπνον ἀρνεῖσθαι, τὸν δὲ λιπαρεῖν καὶ βιάζεσθαι, τέλος δ’ ἄγειν λαβόμενον τῆς χειρὸς εἰς ἀχανῆ τόπον καὶ σκοτεινόν, αὐτὸν δ’ ἄκοντα καὶ τεθαμβημένον ἕπεσθαι. ταύτην ἰδόντι τὴν ὄψιν αὐτῷ συνέβη πυρέττειν διὰ νυκτός· ὅμως δ’ ἕωθεν ἐκκομιζομένου τοῦ σώματος αἰδούμενος μὴ παρεῖναι προῆλθεν εἰς τὸν ὄχλον ἤδη διαγριαινόμενον. ὀφθεὶς δὲ καὶ δόξας οὐχ ὅσπερ ἦν Κίννας εἶναι, ἀλλ’ ἐκεῖνος ὁ Καίσαρα πρὸς τὴν ἐκκλησίαν ἔναγχος λοιδορήσας, διεσπάσθη.", "st": "Brut. 20.8"}, {"sp": "N", "t": "τοῦτο τὸ πάθος μάλιστα μετά γε τὴν Ἀντωνίου μεταβολὴν δείσαντες οἱ περὶ Βροῦτον ἀνεχώρησαν ἐκ τῆς πόλεως· καὶ διέτριβον ἐν Ἀντίῳ τὸ πρῶτον ὡς, ὅταν παρακμάσῃ καὶ μαρανθῇ τὸ τῆς ὀργῆς, αὖθις εἰς Ῥώμην κατιόντες. ὃ ῥᾳδίως ἔσεσθαι προσεδόκων ἐν πλήθεσι φορὰς ἀσταθμήτους καὶ ταχείας φερομένοις, καὶ τὴν σύγκλητον εὔνουν ἔχοντες, ἣ τοὺς Κίνναν διασπασαμένους χαίρειν ἐάσασα τοὺς ἐπὶ τὰς οἰκίας τὰς ἐκείνων ἐπελθόντας ἀνεζήτει καὶ συνελάμβανεν, ἤδη δὲ καὶ ὁ δῆμος ἀχθόμενος, Ἀντωνίου σχεδὸν εἰς μοναρχίαν καθισταμένου, Βροῦτον ἐπόθει καὶ προσεδοκᾶτο τὰς θέας ἄξειν παρὼν αὐτός, ἃς ὤφειλε στρατηγῶν παρασχεῖν. αἰσθόμενος δὲ πολλοὺς τῶν ὑπὸ Καίσαρος ἐστρατευμένων καὶ γῆν καὶ πόλεις παρ’ ἐκείνου λαβόντων ἐπιβουλεύοντας αὐτῷ καὶ κατ’ ὀλίγους παρεισρέοντας εἰς τὴν πόλιν οὐκ ἐθάρρησεν ἐλθεῖν, ἀλλ’ ὁ δῆμος ἐθεᾶτο μὴ παρόντος ἐκείνου τὰς θέας, ἀφειδῶς πάνυ χορηγουμένας καὶ περιττῶς. θηρία τε γὰρ πάμπολλα συνεωνημένος ἐκέλευσε μηδὲν ἀποδόσθαι μηδ’ ὑπολιπεῖν, ἀλλὰ πᾶσι καταχρήσασθαι, καὶ τῶν περὶ τὸν Διόνυσον τεχνιτῶν αὐτὸς εἰς Νέαν πόλιν καταβὰς ἐνέτυχε πλείστοις· περὶ δὲ Κανουτίου τινὸς εὐημεροῦντος ἐν τοῖς θεάτροις ἔγραφε πρὸς τοὺς φίλους ὅπως πείσαντες αὐτὸν εἰσαγάγωσιν Ἑλλήνων γὰρ οὐδένα βιασθῆναι προσήκειν. ἔγραφε δὲ καὶ Κικέρωνι, πάντως παρατυχεῖν ταῖς θέαις δεόμενος.", "st": "Brut. 21.1"}, {"sp": "N", "t": "ἐν τοιαύτῃ δὲ καταστάσει τῶν πραγμάτων ὄντων ἑτέρα γίνεται μεταβολή τοῦ νέου Καίσαρος ἐπελθόντος. οὗτος ἦν μὲν ἐξ ἀδελφιδῆς Καίσαρος, γράμματι δὲ παῖς ὑπ’ αὐτοῦ καὶ κληρονόμος ἀπολελειμμένος. ἐν δ’Ἀπολλωνίᾳ διέτριβεν ὅτε Καῖσαρ ἀνῃρέθη, σχολάζων περὶ λόγους κἀκεῖνον ἐπὶ Πάρθους ἐλαύνειν εὐθὺς ἐγνωκότα προσμένων. ἅμα δὲ τῷ πυθέσθαι τὸ πάθος ἦλθεν εἰς Ῥώμην· καὶ δημαγωγίας ἀρχὴν τοὔνομα Καίσαρος θέμενος ἑαυτῷ καὶ διανέμων τὸ καταλειφθὲν ἀργύριον τοῖς πολίταις Ἀντώνιόν τε κατεστασίαζε καὶ χρήματα διαδιδοὺς συνίστη καὶ συνῆγε πολλοὺς τῶν ὑπὸ Καίσαρος ἐστρατευμένω. ἐπεὶ δὲ Κικέρων τῷ πρὸς Ἀντώνιον μίσει τὰ Καίσαρος ἔπραττε, τούτῳ μὲν ὁ Βροῦτος ἐπέπληττεν ἰσχυρῶς, γράφων ὡς οὐ δεσπότην βαρύνοιτο Κικέρων, ἀλλὰ μισοῦντα δεσπότην φοβοῖτο, καὶ πολιτεύοιτο δουλείας αἵρεσιν φιλανθρώπου γράφων καὶ λέγων ὡς χρηστός ἐστι Καῖσαρ. οἱ δὲ πρόγονοι, φησὶν, ἡμῶν οὐδὲ πρᾴους δεσπότας ὑπέμενον. αὐτῷ δ’ εἰς τοῦτο καιροῦ μήτε πολεμεῖν βεβαίως δεδόχθαι μήτε ἡσυχάζειν, ἀλλ’ ἓν μόνον εἶναι βεβουλευμένον, τὸ μὴ δουλεύειν· θαυμάζειν δὲ Κικέρωνος, εἰ πόλεμον μὲν ἐμφύλιον καὶ κινδυνώδη δέδοικεν, αἰσχρὰν δὲ καὶ ἄδοξον εἰρήνην οὐ φοβεῖται, τοῦ δ’ Ἀντώνιον ἐκβαλεῖν τῆς τυραννίδος μισθὸν αἰτεῖ τὸ Καίσαρα καταστῆσαι τύραννον.", "st": "Brut. 22.1"}, {"sp": "N", "t": "ἐν μὲν οὖν ταῖς πρώταις ἐπιστολαῖς τοιοῦτος ὁ Βροῦτος· ἤδη δὲ τῶν μὲν ὡς Καίσαρα, τῶν δ’ ὡς Ἀντώνιον διισταμένων, ὠνίων δὲ τῶν στρατοπέδων ὥσπερ ὑπὸ κήρυκι προστιθεμένων τῷ πλέον διδόντι, παντάπασι καταγνοὺς τῶν πραγμάτων ἔγνω καταλιπεῖν Ἰταλίαν, καὶ πεζῇ διὰ Λευκανίας εἰς Ἐλέαν ἐπὶ θάλασσαν ἧκεν. ὅθεν ἡ Πορκία μέλλουσα πάλιν εἰς Ῥώμην ἀποτραπέσθαι λανθάνειν μὲν ἐπειρᾶτο περιπαθῶς ἔχουσα, γραφὴ δέ τις αὐτὴν προὔδωκε τἆλλα γενναίαν οὖσαν. ἦν γὰρ ἐκ τῶν Ἑλληνικῶν διάθεσις, προπεμπόμενος Ἕκτωρ ὑπὸ Ἀνδρομάχης κομιζομένης παρ’ αὐτοῦ τὸ παιδίον, ἐκείνῳ δὲ προσβλεπούσης. ταῦτα θεωμένην τὴν Πορκίαν ἡ τοῦ πάθους εἰκὼν ἐξέτηξεν εἰς δάκρυα· καὶ πολλάκις φοιτῶσα τῆς ἡμέρας ἔκλαιεν. Ἀκιλίου δέ τινος τῶν Βρούτου φίλων τὰ πρὸς Ἕκτορα τῆς Ἀνδρομάχης ἔπη διελθόντος,", "st": "Brut. 23.1"}, {"sp": "N", "t": "Ἕκτορ, ἀτὰρ σύ μοί ἐσσι πατὴρ καὶ πότνια μήτηρ<br>ἠδὲ κασίγνητος, σὺ δέ μοί θαλερὸς παρακοίτης,", "st": "Brut. 23.1b"}, {"sp": "N", "t": "μειδιάσας ὁ Βροῦτος, ἀλλ’ οὐκ ἐμοί γ’, εἶπε, πρὸς Πορκίαν ἔπεισι φάναι τὰ τοῦ Ἕκτορος,", "st": "Brut. 23.6"}, {"sp": "N", "t": "ἱστόν ἠλακάτην τε καὶ ἀμφιπόλοισι κέλευε·", "st": "Brut. 23.6b"}, {"sp": "N", "t": "σώματος γὰρ ἀπολείπεται φύσει τῶν ἴσων ἀνδραγαθημάτων, γνώμῃ δ’ ὑπὲρ τῆς πατρίδος, ὥσπερ ἡμεῖς, ἀριστεύει. ταῦτα μὲν ὁ τῆς Πορκίας υἱὸς ἱστόρηκε Βύβλος.", "st": "Brut. 23.6c"}, {"sp": "N", "t": "ἀναχθεὶς δ’ ὁ Βροῦτος ἐκεῖθεν ἐπ’ Ἀθηνῶν ἔπλει. δεξαμένου δὲ τοῦ δήμου προθύμως αὐτὸν εὐφημίαις καί ψηφίσμασι διῃτᾶτο μὲν παρὰ ξένῳ τινί, Θεομνήστου δ’ ἀκροώμενος τοῦ Ἀκαδημιακοῦ καί Κρατίππου τοῦ Περιπατητικοῦ καί συμφιλοσοφῶν ἐδόκει παντάπασιν ἀργεῖν καί σχολάζειν. ἔπραττε δὲ τὰ πρὸς τὸν πόλεμον ἀνυπόπτως. καί γὰρ εἰς Μακεδονίαν ἔπεμψεν Ἡρόστρατον οἰκειούμενος τοὺς ἐπὶ τῶν ἐκεῖ στρατοπέδων, καί τοὺς σχολάζοντας ἀπὸ Ῥώμης ἐν ἄστει νέους ἀνελάμβανε καί συνεῖχεν. ὧν ἦν καί Κικέρωνος υἱός, ὃν ἐπαινεῖ διαφερόντως, καί φησιν, εἴτ’ ἐγρήγορεν εἴτ’ ἐνυπνιάζεται, θαυμάζειν οὕτω γενναῖον ὄντα καί μισοτύραννον.", "st": "Brut. 24.1"}, {"sp": "N", "t": "ἀρξάμενος δὲ τῶν πραγμάτων ἀναφανδὸν ἅπτεσθαι, καί πυθόμενος πλοῖα Ῥωμαϊκὰ μεστὰ χρημάτων ἐξ Ἀσίας προσφέρεσθαι καί στρατηγὸν ἐπιπλεῖν ἄνδρα χαρίεντα καί γνώριμον, ἀπήντησεν αὐτῷ περὶ Κάρυστον· ἐντυχὼν δὲ καί πείσας καί παραλαβὼν τὰ πλοῖα λαμπροτέραν ὑποδοχὴν ἐποιεῖτο. καί γὰρ ἦν ἡμέρα καθ’ ἣν ἐγεγόνει πρῶτον ὁ Βροῦτος, ὡς οὖν ἐλθόντες εἰς τὸ πίνειν ἐπιχύσεις ἐποιοῦντο νίκης τε Βρούτου καὶ Ῥωμαίων ἐλευθερίας, ἔτι μᾶλλον αὐτοὺς ῥῶσαι βουλόμενος ᾔτησε ποτήριον μεῖζον καί λαβὼν, ἀπ’ οὐδεμιᾶς προφάσεως ἀνεφώνησε τὸν στίχον τοῦτον·", "st": "Brut. 24.4"}, {"sp": "N", "t": "ἀλλά με μοῖρ’ ὀλοὴ καί Λητοῦς ἔκτανεν υἱός.", "st": "Brut. 24.4b"}, {"sp": "N", "t": "ἔτι δὲ καί πρὸς τούτοις ἱστοροῦσιν, ὅτε τὴν τελευταίαν ἐν Φιλίπποις μαχούμενος ἐξῄει μάχην, σύνθημα παρ’ αὐτοῦ τοῖς στρατιώταις Ἀπόλλωνα δοθῆναι. διὸ καί τῆς συμφορᾶς τίθενται σημεῖον ἐκείνην τὴν ἀναφώνησιν.", "st": "Brut. 24.7"}, {"sp": "N", "t": "ἐκτούτου πεντήκοντα μὲν αὐτῷ μυριάδας Ἀντίστιος ἀφ’ ὧν ἦγε καὶ αὐτὸς εἰς Ἰταλίαν χρημάτων δίδωσιν, ὅσοι δὲ περὶ Θεσσαλίαν ἔτι τῆς Πομπηΐου στρατιᾶς ἐπλανῶντο συνέρρεον ἀσμένως πρὸς αὐτόν ἱππεῖς δὲ πεντακοσίους ἀφείλετο Κίννα πρὸς Δολοβέλλαν ἄγοντος εἰς Ἀσίαν. ἐπιπλεύσας τε τῇ Δημητριάδι, πολλῶν ὅπλων ἐξαγομένων πρὸς Ἀντώνιον, ἃ Καίσαρος τοῦ προτέρου κελεύσαντος ἐπὶ τὸν Παρθικὸν ἐποιήθη πόλεμον, ἐκράτησεν. Ὁρτησίου δὲ τοῦ στρατηγοῦ παραδόντος αὐτῷ Μακεδονίαν, καὶ τῶν ἐν κύκλῳ βασιλέων καὶ δυναστῶν συνισταμένων καὶ προστιθεμένων, ἀγγέλλεται Γάϊος, ὁ Ἀντωνίου ἀδελφὸς, ἐξ Ἰταλίας διαβεβηκὼς βαδίζειν εὐθὺς ἐπὶ τὰς δυνάμεις ἃς ἐν Ἐπιδάμνῳ καὶ Ἀπολλωνίᾳ Βατίνιος συνεῖχε. βουλόμενος οὖν φθάσαι καὶ προλαβεῖν ὁ Βροῦτος ἐξαίφνης ἀναστήσας τοὺς σὺν αὐτῷ διὰ χωρίων χαλεπῶν νιφόμενος ἐπορεύετο· καὶ πολὺ προῆλθε τοὺς κομίζοντας τὸ ἄριστον, ἐγγὺς οὖν Ἐπιδάμνου γενόμενος διὰ κόπον καὶ ψῦχος ἐβουλιμίασε. συμπίπτει δὲ μάλιστα τὸ πάθος χιόνος οὔσης πονοῦσι καὶ κτήνεσι καὶ ἀνθρώποις, εἴτε τοῦ θερμοῦ διὰ περίψυξιν καὶ πύκνωσιν, ὅταν ἐντὸς ἅπαν καθειρχθῇ, τὴν τροφὴν ἁθρόως ἀναλίσκοντος, εἴτε δριμεῖα καὶ λεπτὴ τῆς χιόνος διαλυομένης ἰοῦσα πνοὴ τέμνει τὸ σῶμα καὶ διαφθείρει τὸ θερμὸν ἐξ αὐτοῦ θύραζε διασπειρόμενον. τὰς γὰρ ἐφιδρώσεις παρέχειν δοκεῖ τὸ θερμὸν ἀπαντῶντι τῷ ψυχρῷ περὶ τὴν ἐπιφάνειαν σβεννύμενον. ὑπὲρ ὧν ἐν ἑτέροις μᾶλλον ἠπόρηται.", "st": "Brut. 25.1"}, {"sp": "N", "t": "Λιποθυμοῦντος δὲ τοῦ Βρούτου καὶ μηδενὸς ἔχοντος ἐν τῷ στρατοπέδῳ μηδὲν ἐδώδιμον, ἠναγκάσθησαν οἱ περὶ αὐτὸν ἐπὶ τοὺς πολεμίους καταφυγεῖν καὶ ταῖς πύλαις προσελθόντες ἄρτον ᾔτουν τοὺς φύλακας. οἱ δὲ διακούσαντες τὸ σύμπτωμα τοῦ Βρούτου παρῆσαν αὐτοί καὶ σιτία καὶ ποτὰ κομίζοντες, ἀνθ’ ὧν ὁ Βροῦτος, ὡς τὴν πόλιν παρέλαβεν, οὐ μόνον τούτοις, ἀλλὰ καὶ πᾶσι διὰ τούτους φιλανθρώπως ἐχρήσατο.", "st": "Brut. 26.1"}, {"sp": "N", "t": "Γάϊος δ’ Ἀντώνιος Ἀπολλωνίᾳ προσβαλὼν ἐκεῖ τοὺς ἐγγὺς ὄντας ἐκάλει στρατιώτας. ἐπεὶ δ’ οὗτοί τε πρὸς Βροῦτον ᾤχοντο καὶ τοὺς Ἀπολλωνιάτας ᾔσθετο τὰ Βρούτου φρονοῦντας, ἐκλιπὼν τὴν πόλιν εἰς Βουθρωτὸν ἐβάδιζε. καὶ πρῶτον μὲν ἀπόλλυσι τρεῖς σπείρας καθ’ ὁδὸν ὑπὸ Βρούτου κατακοπείσας· ἔπειτα τοὺς περὶ τὴν Βυλλίδα τόπους προκαταληφθέντας ἐπιχειρῶν ἐκβιάζεσθαι καὶ μάχην συνάψας Κικέρωνι νικᾶται. τούτῳ γὰρ ὁ Βροῦτος ἐχρῆτο στρατηγῷ καὶ πολλὰ δι’ αὐτοῦ κατώρθωσε. λαβὼν δὲ τὸν Γάϊον ἐν χωρίοις ἑλώδεσι μακρὰν διεσπασμένον οὐκ εἴασεν ἐμβαλεῖν, ἀλλὰ περιίππευσε, φείδεσθαι κελεύων, ὡς μετὰ μικρὸν ἰδίων ἐσομένων. ὃ καὶ συνέβη, παρέδοσαν γὰρ ἑαυτοὺς καὶ τὸν στρατηγόν, ὥστε μεγάλην ἤδη περὶ τὸν Βροῦτον δύναμιν εἶναι. χρόνον μὲν οὖν πολὺν ἐν τιμῇ τὸν Γάϊον ἦγε καὶ τὰ παράσημα τῆς ἀρχῆς οὐκ ἀφῄρει, καίπερ, ὥς φασιν, ἄλλων τε πολλῶν καὶ Κικέρωνος ἀπὸ Ῥώμης γραφόντων καὶ κελευόντων ἀναιρεῖν· ἀρξάμενον δὲ κρύφα τοῖς ἡγεμόσι διαλέγεσθαι καὶ ποιήσαντα νεωτερισμὸν ἐνθέμενος εἰς ναῦν ἐφύλαττε. τῶν δὲ διαφθαρέντων στρατιωτῶν εἰς Ἀπολλωνίαν ἀποστάντων καὶ καλούντων ἐκεῖ τὸν Βροῦτον, οὐκ ἔφη τοῦτο πάτριον εἶναι Ῥωμαίοις, ἀλλ’ ἐκείνους πρὸς τὸν ἄρχοντα χρῆναι βαδίζοντας αὐτοὺς παραιτεῖσθαι τὴν ἐπὶ τοῖς ἡμαρτημένοις ὀργήν. ἐλθοῦσι δὲ καὶ δεομένοις συγγνώμην ἔδωκε.", "st": "Brut. 26.3"}, {"sp": "N", "t": "μέλλοντι δ’ αὐτῷ διαβαίνειν εἰς τὴν Ἀσίαν ἧκεν ἀγγελία περὶ τῆς ἐν Ῥώμῃ μεταβολῆς, ὁ γὰρ νέος Καῖσαρ ηὐξήθη μὲν ὑπὸ τῆς βουλῆς ἐπ’ Ἀντώνιον, ἐκβαλὼν δὲ τῆς Ἰταλίας ἐκεῖνον αὐτὸς ἤδη φοβερὸς ἦν, ὑπατείαν τε μνώμενος παρὰ νόμον, καὶ στρατεύματα τρέφων μεγάλα, τῆς πόλεως οὐδὲν δεομένης. ὁρῶν δὲ καὶ ταῦτα τὴν βουλὴν βαρυνομένην καὶ πρὸς τὸν Βροῦτον ἀφορῶσαν ἔξω καὶ ψηφιζομένην ἐκείνῳ καὶ βεβαιοῦσαν τὰς ἐπαρχίας, ἔδεισε. καὶ τὸν μὲν Ἀντώνιον πέμπων εἰς φιλίαν προὐκαλεῖτο, τὰς δὲ δυνάμεις τῇ πόλει περιστήσας ὑπατείαν ἔλαβεν, οὔπω πάνυ μειράκιον ὤν, ἀλλ’ εἰκοστὸν ἄγων ἔτος, ὡς αὐτὸς ἐν τοῖς ὑπομνήμασιν εἴρηκεν. εὐθὺς δὲ δίκας φόνου κατὰ τῶν περὶ τὸν Βροῦτον εἰσῆγεν, ὡς ἄνδρα πρῶτον ἐν ἀρχαῖς ταῖς μεγίσταις ἀνῃρηκότων ἄκριτον καὶ κατήγορον ἐπέστησε Βρούτου μὲν Λεύκιον Κορνιφίκιον, Κασσίου δὲ Μᾶρκον Ἀγρίππαν. ὠφλίσκανον οὖν τὰς δίκας ἐρήμας ἀναγκαζομένων φέρειν ψῆφον τῶν δικαστῶν. λέγεται δὲ τοῦ κήρυκος, ὥσπερ εἴωθεν, ἀπὸ τοῦ βήματος τὸν Βροῦτον ἐπὶ τὴν δίκην καλοῦντος, τὸ μὲν πλῆθος ἐπιδήλως στενάξαι, τοὺς δ’ ἀρίστους κύψαντας εἰς γῆν ἡσυχίαν ἄγειν, Πόπλιον δὲ Σιλίκιον ὀφθῆναι δακρύσαντα, καὶ διὰ τὴν αἰτίαν ταύτην ὀλίγον ὕστερον ἕνα τῶν προγραφέντων ἐπὶ θανάτῳ γενέσθαι. μετὰ ταῦτα διαλλαγέντες οἱ τρεῖς, Καῖσαρ, Ἀντώνιος, Λέπιδος, διενείμαντο τὰς ἐπαρχίας σφαγάς τε καὶ προγραφὰς ἀνδρῶν διακοσίων ἐποίησαν, ἐν οἷς καὶ Κικέρων ἀπέθανε.", "st": "Brut. 27.1"}, {"sp": "N", "t": "τούτων οὖν εἰς Μακεδονίαν ἀπαγγελθέντων ἐκβιασθεὶς ὁ Βροῦτος ἔγραψεν Ὁρτησίῳ κτεῖναι Γάϊον Ἀντώνιον, ὡς δὴ Βρούτῳ τε καὶ Κικέρωνι τιμωρῶν, τῷ μὲν ὄντι φίλῳ, τῷ δὲ καὶ κατὰ γένος προσήκοντι. διὰ ταῦθ’ ὕστερον Ἀντώνιος Ὁρτήσιον ἐν Φιλίπποις λαβὼν τῷ μνήματι τοῦ ἀδελφοῦ προσέσφαξε. Βροῦτος δὲ τῆς Κικέρωνος τελευτῆς τῇ αἰτίᾳ φησὶν αἰσχύνεσθαι μᾶλλον ἢ τῷ πάθει συναλγεῖν, ἐγκαλεῖν δὲ τοῖς ἐπὶ Ῥώμης φίλοις· δουλεύειν γὰρ αὑτῶν αἰτίᾳ μᾶλλον ἢ τῶν τυραννούντων, καὶ καρτερεῖν ὁρῶντας καὶ παρόντας ἃ μηδ’ ἀκούειν αὐτοῖς ἀνεκτὸν ἦν.", "st": "Brut. 28.1"}, {"sp": "N", "t": "περαιώσας δὲ τὸν στρατὸν εἰς Ἀσίαν ἤδη λαμπρὸν ὄντα, ναυτικὸν μὲν ἐξηρτύετο στόλον ἐν Βιθυνίᾳ καὶ περὶ Κύζικον, πεζῇ δ’ αὐτὸς ἐπιὼν καθίστατο τὰς πόλεις καὶ τοῖς δυνάσταις ἐχρημάτιζε, καὶ πρὸς Κάσσιον ἔπεμπεν εἰς Συρίαν ἀπ’ Αἰγύπτου μετακαλῶν· οὐ γὰρ ἀρχὴν κτωμένους αὐτούς, ἀλλ’ ἐλευθεροῦντας τὴν πατρίδα τὴν δύναμιν, ᾗ καταλύσουσι τοὺς τυράννους, συνάγοντας πλανᾶσθαι· δεῖν οὖν μεμνημένους καὶ φυλάττοντας τὴν ὑπόθεσιν μὴ μακρὰν ἀπηρτῆσθαι τῆς Ἰταλίας, ἀλλ’ ἐκεῖσε σπεύδειν καὶ βοηθεῖν τοῖς πολίταις.", "st": "Brut. 28.3"}, {"sp": "N", "t": "ὑπακούσαντος δὲ τοῦ Κασσίου καὶ καταβαίνοντος ἀπήντα καὶ περὶ Σμύρναν ἀλλήλοις ἐνετύγχανον ἀφ’ οὗ πρῶτον ἐν Πειραιεῖ χωρισθέντες ὥρμησαν ὁ μὲν εἰς Συρίαν, ὁ δὲ εἰς Μακεδονίαν. ἦν οὖν ἡδονή τε μεγάλη καὶ θάρσος αὐτοῖς ἐκ τῆς παρούσης ἑκατέρῳ δυνάμεως. ὁρμήσαντες γὰρ ἐκ τῆς Ἰταλίας ὅμοια φυγάδων τοῖς ἀτιμοτάτοις ἀχρήματοι καὶ ἄνοπλοι, μὴ ναῦν ἑνήρη, μὴ στρατιώτην ἕνα, μὴ πόλιν ἔχοντες, οὐ πολλοῦ πάνυ χρόνου διαγενομένου συνῆλθον εἰς ταὐτό καὶ ναυσὶ καὶ πεζῷ καὶ ἵπποις καὶ χρήμασιν ἀξιόμαχοι διαγωνίσασθαι περὶ τῆς Ῥωμαίων ἡγεμονίας ὄντες.", "st": "Brut. 28.6"}, {"sp": "N", "t": "ἐβούλετο μὲν οὖν ἴσον ἔχειν τιμῆς καὶ παρέχειν ὁ Κάσσιος, ἔφθανε δ’ ὁ Βροῦτος ὡς τὰ πολλὰ φοιτῶν πρὸς αὐτόν ἡλικίᾳ τε προὔχοντα καὶ σώματι πονεῖν ὁμοίως μὴ δυναμένῳ χρώμενον. ἦν δὲ δόξα Κάσσιον μὲν εἶναι δεινὸν ἐν τοῖς πολεμικοῖς, ὀργῇ δὲ τραχὺν καὶ φόβῳ μᾶλλον ἄρχοντα, πρὸς δὲ τοὺς συνήθεις ὑγρότερον τῷ γελοίῳ καὶ φιλοσκώπτην· Βροῦτον δὲ λέγουσι δι’ ἀρετὴν φιλεῖσθαι μὲν ὑπὸ τῶν πολλῶν, ἐρᾶσθαι δ’ ὑπὸ τῶν φίλων, θαυμάζεσθαι δ’ ὑπὸ τῶν ἀρίστων, μισεῖσθαι δὲ μηδ’ ὑπὸ τῶν πολεμίων, ὅτι πρᾷος ὁ ἀνὴρ διαφερόντως καὶ μεγαλόφρων καὶ πρὸς πᾶσαν ὀργὴν καὶ ἡδονὴν καὶ πλεονεξίαν ἀπαθής, ὄρθιον δὲ τὴν γνώμην καὶ ἄκαμπτον ἑστῶσαν ὑπὲρ τοῦ καλοῦ καὶ δικαίου διαφυλάττων. καὶ μέγιστον ὑπῆρχεν αὐτῷ πρὸς εὔνοιαν καὶ δόξαν ἡ τῆς προαιρέσεως πίστις. οὔτε γὰρ ἐκεῖνος ὁ μέγας Πομπήϊος, εἰ Καίσαρα καθεῖλεν, ἠλπίζετο βεβαίως προήσεσθαι τοῖς νόμοις τὴν δύναμιν, ἀλλ’ ἀεὶ τὰ πράγματα καθέξειν, ὑπατείας ὀνόματι καὶ δικτατορίας ἤ τινος ἄλλης μαλακωτέρας ἀρχῆς παραμυθούμενος τὸν δῆμον· Κάσσιόν δὲ τοῦτον, σφοδρὸν ἄνδρα καὶ θυμοειδῆ καὶ πολλαχοῦ πρὸς τὸ κερδαλέον ἐκφερόμενον τοῦ δικαίου, παντὸς μᾶλλον ᾤοντο πολεμεῖν καὶ πλανᾶσθαι καὶ κινδυνεύειν αὑτῷ τινα δυναστείαν κατασκευαζόμενον, οὐκ ἐλευθερίαν τοῖς πολίταις. τὰ μὲν γὰρ ἔτι τούτων πρεσβύτερα, Κίνναι καὶ Μάριοι καὶ Κάρβωνες, ἆθλον ἐν μέσῳ καὶ λείαν προθέμενοι τὴν πατρίδα, μονονουχὶ ῥητῶς ὑπὲρ τυραννίδος ἐπολέμησαν. Βρούτῳ δὲ λέγουσι μηδὲ τοὺς ἐχθροὺς προσβάλλειν τοιαύτην δμεαβολήν, ἀλλ’ Ἀντωνίου γε καὶ πολλοὺς ἀκοῦσαι λέγοντος ὡς μόνον οἴοιτο Βροῦτον ἐπιθέσθαι Καίσαρι προαχθέντα τῇ λαμπρότητι καὶ τῷ φαινομένῳ καλῷ τῆς πράξεως, τοὺς δ’ ἄλλους ἐπὶ τὸν ἄνδρα συστῆναι μισοῦντας καὶ φθονοῦντας. ὅθεν Βροῦτος οὐ τῇ δυνάμει τοσοῦτον ὅσον τῇ ἀρετῇ δῆλός ἐστιν ἐξ ὧν γράφει πεποιθώς. γράφει δὲ πρὸς Ἀττικόν ἤδη τῷ κινδύνῳ πλησιάζων ἐν τῷ καλλίστῳ τῆς τύχης εἶναι τὰ καθ’ αὑτόν ἢ γὰρ νικήσας ἐλευθερώσειν τὸν Ῥωμαίων δῆμον ἢ δουλείας ἀποθανὼν ἀπαλλαγήσεσθαι· καὶ τῶν ἄλλων ἀσφαλῶς αὐτοῖς καὶ βεβαίως ἐχόντων ἓν ἄδηλον εἶναι, πότερον βιώσονται μετ’ ἐλευθερίας ἢ τεθνήξονται. Μᾶρκον δ’ Ἀντώνιον ἀξίαν φησὶ τῆς ἀνοίας διδόναι δίκην, ὃς ἐν Βρούτοις καὶ Κασσίοις καὶ Κάτωσι συναριθμεῖσθαι δυνάμενος προσθήκην ἑαυτὸν Ὀκταβίῳ δέδωκε· κἂν μὴ νῦν ἡττηθῇ μετ’ ἐκείνου, μικρὸν ὕστερον ἐκείνῳ μαχεῖται. ταῦτα μὲν οὖν ἀποθεσπίσαι καλῶς πρὸς τὸ μέλλον ἔοικεν.", "st": "Brut. 29.1"}, {"sp": "N", "t": "ἐν δὲ τῇ Σμύρνῃ τότε τῶν χρημάτων, ἃ πολλὰ συνειλόχει Κάσσιος, ἠξίου μεταλαβεῖν τὰ γὰρ ὄντα κατανηλωκέναι ναυπηγούμενος στόλον τοσοῦτον ᾧ πᾶσαν ὑφ’ ἑαυτοῖς ἕξουσι τὴν ἐντὸς θάλασσαν. οὐκ εἴων μὲν οὖν τὸν Κάσσιον οἱ φίλοι διδόναι, λέγοντες ὡς οὐ δίκαιον, ἃ σὺ φειδόμενος διαφυλάττεις Καὶ φθόνῳ συνάγεις, ἐκεῖνον λαβόντα δημαγωγεῖν Καὶ χαρίζεσθαι τοῖς στρατιώταις· οὐ μὴν ἀλλ’ ἔδωκεν αὐτῷ τρίτον μέρος ἁπάντων. καὶ πάλιν διαστάντες ἐπὶ τὰς προσηκούσας ἑκατέρῳ πράξεις, Κάσσιος μὲν ἑλὼν Ῥόδον οὐκ ἐπιεικῶς ἐχρῆτο τοῖς πράγμασι, Καὶ ταῦτα περὶ τὴν εἴσοδον τοῖς προσαγορεύουσιν αὐτὸν βασιλέα Καὶ κύριον ἀποκρινάμενος· οὔτε βασιλεὺς οὔτε κύριος, τοῦ δὲ κυρίου Καὶ βασιλέως φονεὺς Καὶ κολαστής. Βροῦτος δὲ Λυκίους ᾔτει χρήματα Καὶ στρατόν. ἐπεὶ δὲ Ναυκράτης ὁ δημαγωγὸς ἀνέπεισε τὰς πόλεις ἀφίστασθαι Καὶ λόφους τινὰς ὡς εἴρξοντες παρόδου τὸν Βροῦτον κατελάβοντο, πρῶτον μὲν ἀριστοποιουμένοις αὐτοῖς ἐπέπεμψεν ἱππεῖς, ὑφ’ ὧν ἑξακόσιοι διεφθάρησαν, ἔπειτα τὰ χωρία καὶ πολίχνας λαμβάνων ἀπέλυεν ἄνευ λύτρων ἅπαντας ὡς προσαξόμενος εὐνοίᾳ τὸ ἔθνος. οἱ δ’ ἦσαν αὐθάδεις, ἃ μὲν ἐβλάπτοντο πρὸς ὀργὴν τιθέμενοι, τῆς δ’ ἐπιεικείας καὶ φιλανθρωπίας καταφρονοῦντες, ἄχρι οὗ συνελάσας εἰς Ξάνθον αὐτῶν τοὺς μαχιμωτάτους ἐπολιόρκει. τοῦ δὲ ποταμοῦ παρὰ τὴν πόλιν παραρρέοντος ὑπονηχόμενοι διεδίδρασκον. ἡλίσκοντο δὲ δικτύων διὰ πόρου καθιεμένων εἰς βυθόν, ὧν τὰ ἄκρα κώδωσι προσηρτημένοις διεσήμαινεν εὐθὺς τὸν ἐνσχεθέντα. μηχαναῖς δέ τισι τῶν Ξανθίων νύκτωρ ἐπιδραμόντων Καὶ πῦρ ἐμβαλόντων, ὡς ἀπεκλείσθησαν αἰσθομένων τῶν Ῥωμαίων πρὸς τὸ τεῖχος Καὶ πνεῦμα λαμπρὸν ἀνερρίπιζεν ἐπὶ τὰς ἐπάλξεις τὴν φλόγα τῶν ἐγγὺς οἰκιῶν ἀντιλαμβανομένην, δείσας ὁ Βροῦτος ὑπὲρ τῆς πόλεως ἐκέλευσε κατασβεννύναι Καὶ βοηθεῖν.", "st": "Brut. 30.1"}, {"sp": "N", "t": "τοὺς δὲ Λυκίους δεινή τις ἐξαίφνης πρὸς ἀπόνοιαν ὁρμὴ καὶ λόγου κρείσσων κατέσχεν, ἣν ἄν τις ἔρωτι θανάτου μάλιστα προσεικάσειεν· οἵ γε μετὰ παίδων καὶ γυναικῶν ἐλεύθεροί τε καὶ δοῦλοι καὶ πᾶσα ἡλικία τοὺς μὲν πολεμίους πρὸς τὴν φλόγα βοηθοῦντας ἀπὸ τῶν τειχῶν ἔβαλλον, αὐτοὶ δὲ κάλαμον καὶ ξύλα καὶ πᾶν ὑπέκκαυμα προσφέροντες ἦγον ἐπὶ τὴν πόλιν τὸ πῦρ, ὀρέγοντες αὐτῷ πᾶσαν ὕλην καὶ πάντα τρόπον ἐξερεθίζοντες καὶ συνεκτρέφοντες. ὡς δ’ἡ φλὸξ ῥυεῖσα καὶ διαζώσασα πανταχόθεν τὴν πόλιν διέλαμψε πολλή, περιπαθῶν ἐπὶ τοῖς γινομένοις ὁ Βροῦτος ἔξωθεν παρίππευε προθυμούμενος βοηθεῖν, καὶ τὰς χεῖρας ὀρέγων τοῖς Ξανθίοις ἐδεῖτο φείδεσθαι καὶ σῴζειν τὴν πόλιν, οὐδενὸς αὐτῷ προσέχοντος, ἀλλὰ πάντα τρόπον ἑαυτοὺς ἀπολλύντων, οὐ μόνον ἀνδρῶν τε καὶ γυναικῶν, ἀλλὰ καὶ τὰ παιδία τὰ μικρὰ μετὰ κραυγῆς καὶ ἀλαλαγμοῦ τὰ μὲν εἰς τὸ πῦρ ἥλλετο, τὰ δ’ ἄνωθεν ἀπὸ τῶν τειχῶν ἐξετραχήλιζεν αὑτά, τὰ δὲ τοῖς ξίφεσι τῶν πατέρων ὑπέβαλλε τὰς σφαγὰς γυμνοῦντα καὶ κελεύοντα παίειν. ὤφθη δὲ τῆς πόλεως διαφθαρείσης γυνή κρεμαμένη μὲν ἐξ ἀγχόνης, παιδίον δὲ νεκρὸν ἐξηρτημένη τοῦ τραχήλου, λαμπάδι δὲ καιομένῃ τὴν οἰκίαν ὑφάπτουσα. καὶ τοῦ θεάματος τραγικοῦ φανέντος ἰδεῖν μὲν οὐχ ὑπέμεινεν ὁ Βροῦτος, ἐδάκρυσε δὲ ἀκούσας· καὶ γέρας ἐκήρυξε τῶν στρατιωτῶν ὅστις ἂν δυνηθῇ Λύκιον ἄνδρα περισῶσαι. φασὶ δὲ μόνους ἑκατὸν πεντήκοντα γενέσθαι τοὺς μὴ διαφυγόντας τὸ σωθῆναι. Ξάνθιοι μὲν οὖν διὰ πολλῶν χρόνων ὥσπερ εἱμαρμένην περίοδον διαφθορᾶς ἀποδιδόντες τὴν τῶν προγόνων ἀνενεώσαντο τῇ τόλμῃ τύχην καὶ γὰρ ἐκεῖνοι τὴν πόλιν ὁμοίως ἐπὶ τῶν Περσικῶν κατακαύσαντες ἑαυτοὺς διέφθειραν.", "st": "Brut. 31.1"}, {"sp": "N", "t": "Βροῦτος δὲ τὴν Παταρέων πόλιν ὁρῶν ἀπισχυριζομένην πρὸς αὐτόν, ὤκνει μὲν ἐπιχειρεῖν καὶ διηπορεῖτο, τὴν αὐτὴν δεδιὼς ἀπόνοιαν, ἔχων δὲ γυναῖκας αὐτῶν αἰχμαλώτους ἀφῆκεν ἄνευ λύτρων. αἱ δ’ἀνδρῶν τε καὶ πατέρων ἐπιφανῶν οὖσαι διηγούμεναι τὸν Βροῦτον, ὡς ἀνὴρ εἴη σωφρονέστατος καὶ δικαιότατος, ἔπεισαν εἶξαι καὶ παραδοῦναι τὴν πόλιν. ἐκ δὲ τούτου καὶ πάντες οἱ λοιποὶ προσεχώρησαν ἐπιτρέψαντες ἑαυτοὺς ἐκείνῳ, τυχόντες δὲ χρηστοῦ καὶ παρ’ ἐλπίδας εὐγνώμονος, ὅς γε, Κασσίου Ῥοδίους ὑπὸ τὸν αὐτὸν χρόνον ἀναγκάσαντος ἰδίᾳ μὲν ὃν ἐκέκτηντο χρυσὸν καὶ ἄργυρον εἰσενεγκεῖν ἅπαντας (ἐξ οὗ συνήχθη περὶ ὀκτακισχίλια τάλαντα), δημοσίᾳ δὲ τὴν πόλιν ἄλλοις πεντακοσίοις ζημιώσαντος, αὐτὸς ἑκατὸν καὶ πεντήκοντα τάλαντα Λυκίους πραξάμενος, ἄλλο δὲ οὐδὲν ἀδικήσας, ἀνέζευξεν ἐπ’ Ἰωνίας.", "st": "Brut. 32.1"}, {"sp": "N", "t": "πολλὰ μὲν οὖν ἄξια μνήμης ἔργα καὶ τιμαῖς ἀπεδείξατο καὶ κολάσεσι τῶν ἀξίων ᾧ δ’ αὐτός τε ἥσθη μάλιστα καὶ Ῥωμαίων οἱ κράτιστοι, τοῦτο διηγήσομαι. Πομπηΐου Μάγνου προσβαλόντος Αἰγύπτῳ κατὰ Πηλούσιον, ὁπηνίκα τὴν μεγάλην ἀρχὴν ἀποβαλὼν ὑπὸ Καίσαρος ἔφυγεν, οἱ τοῦ βασιλέως ἔτι παιδὸς ὄντος ἐπιτροπεύοντες ἐν βουλῇ μετὰ τῶν φίλων ἦσαν, οὐ κατὰ ταὐτὰ ταῖς γνώμαις φερόμενοι. τοῖς μὲν γὰρ ἐδόκει δέχεσθαι, τοῖς δ’ ἀπωθεῖν Αἰγύπτου τὸν ἄνδρα. Θεόδοτος δέ τις Χῖος, ἐπὶ μισθῷ ῥητορικῶν λόγων διδάσκαλος τῷ βασιλεῖ συνών, ἠξιωμένος δὲ τότε τοῦ συνεδρίου δι’ ἐρημίαν ἀνδρῶν βελτιόνων, ἀμφοτέρους διαμαρτάνοντας ἀπέφαινε, καὶ τοὺς ἀναλαβεῖν καὶ τοὺς ἀφεῖναι κελεύοντας τὸν Πομπήϊον· ἓν γὰρ εἶναι συμφέρον ἐκ τῶν παρόντων, δεξαμένους ἀποκτεῖναι. καὶ προσεπεῖπε τοῦ λόγου παυόμενος, ὅτι νεκρὸς οὐ δάκνει. προσθεμένου δὲ τῇ γνώμῃ τοῦ συνεδρίου παράδειγμα τῶν ἀπίστων καὶ ἀπροσδοκήτων ἔκειτο Πομπήϊος Μᾶγνος, τῆς Θεοδότου ῥητορείας καὶ δεινότητος ἔργον, ὡς αὐτός ὁ σοφιστὴς ἔλεγε μεγαλαυχούμενος. ὀλίγῳ δ’ ὕστερον ἐπελθόντος Καίσαρος, οἱ μὲν δίκας τιννύοντες ἀπώλλυντο κακοὶ κακῶς, Θεόδοτος δὲ παρὰ τῆς τύχης χρόνον εἰς ἄδοξον καὶ ἄπορον καὶ πλάνητα βίον ἐπιδανεισάμενος τότε Βροῦτον ἐπιόντα τὴν Ἀσίαν οὐκ ἔλαθεν, ἀλλ’ ἀναχθεὶς καὶ κολασθεὶς ὄνομα τοῦ θανάτου πλέον ἔσχεν ἢ τοῦ βίου.", "st": "Brut. 33.1"}, {"sp": "N", "t": "Κάσσιον δὲ Βροῦτος εἰς Σάρδεις ἐκάλει, καὶ προσιόντι μετὰ τῶν φίλων ἀπήντησε· καὶ πᾶς ὁ στρατὸς ὡπλισμένος αὐτοκράτορας ἀμφοτέρους προσηγόρευσεν. οἷα δ’ ἐν πράγμασι μεγάλοις καὶ φίλοις πολλοῖς καὶ ἡγεμόσιν αἰτιῶν αὐτοῖς πρὸς ἀλλήλους ἐγγενομένων καὶ διαβολῶν, πρὶν ἕτερόν τι ποιεῖν, εὐθὺς ἐκ πορείας καθ’ αὐτούς ἐν οἰκήματι γενόμενοι κεκλεισμένων τῶν θυρῶν καὶ μηδενὸς παρόντος, ἐχρῶντο μέμψεσι πρῶτον, εἶτ’ ἐλέγχοις καὶ κατηγορίαις. ἐκ δὲ τούτου πρὸς δάκρυα καὶ παρρησίαν μετὰ πάθους ἐκφερομένων, θαυμάζοντες οἱ φίλοι τὴν τραχύτητα τῆς ὀργῆς καὶ τὸν τόνον, ἔδεισαν μή τι ἐκ τούτου γένηται· προσελθεῖν δὲ ἀπείρητο. Μᾶρκος δὲ Φαώνιος, ἐραστὴς γεγονὼς Κάτωνος, οὐ λόγῳ μᾶλλον ἢ φορᾷ τινι καὶ πάθει μανικῷ φιλοσοφῶν, ἐβάδιζεν εἴσω πρὸς αὐτούς κωλυόμενος ὑπὸ τῶν οἰκετῶν. ἀλλ’ ἔργον ἦν ἐπιλαβέσθαι Φαωνίου πρὸς ὁτιοῦν ὀρούσαντος· σφοδρὸς γὰρ ἦν ἐν πᾶσι καὶ πρόχειρος, ἐπεὶ τό γε βουλευτὴν εἶναι Ῥωμαίων ἑαυτὸν οὐδενὸς ἄξιον ἡγεῖτο, τῷ δὲ κυνικῷ τῆς παρρησίας πολλάκις ἀφῄρει τὴν χαλεπότητα, καὶ τὸ ἄκαιρον αὐτοῦ μετὰ παιδιᾶς δεχομένων. βίᾳ δὴ τότε τῶν παρόντων διωσάμενος τὰς θύρας εἰσῆλθε, μετὰ πλάσματος φωνῆς ἔπη περαίνων οἷς τὸν Νέστορα χρώμενον Ὅμηρος πεποίηκεν", "st": "Brut. 34.1"}, {"sp": "N", "t": "ἀλλὰ πίθεσθ’· ἄμφω δὲ νεωτέρω ἐστὸν ἐμεῖο,", "st": "Brut. 34.1b"}, {"sp": "N", "t": "καὶ τὰ ἑξῆς. ἐφ’οἷς ὁ μὲν Κάσσιος ἐγέλασεν, ὁ δὲ Βροῦτος ἐξέβαλεν αὐτόν ἁπλόκυνα καὶ ψευδόκυνα προσαγορεύων. οὐ μὴν ἀλλὰ τότε τοῦτο τῆς πρὸς ἀλλήλους διαφορᾶς ποιησάμενοι πέρας εὐθὺς διελύθησαν. καὶ Κασσίου δεῖπνον παρέχοντος ἐκάλει τοὺς φίλους Βροῦτος, ἤδη δὲ κατακειμένων Φαώνιος ἧκε λελουμένος· μαρτυρομένου δὲ Βρούτου μὴ κεκλημένον αὐτόν ἥκειν καὶ κελεύοντος ἀπάγειν ἐπὶ τὴν ἀνωτάτω κλίνην, βίᾳ παρελθὼν εἰς τὴν μέσην κατεκλίθη· καὶ παιδιὰν ὁ πότος ἔσχεν οὐκ ἄχαριν οὐδ’ ἀφιλόσοφον.", "st": "Brut. 34.7"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ Βροῦτος ἄνδρα Ῥωμαῖον ἐστρατηγηκότα καὶ πεπιστευμένον ὑπ’ αὐτοῦ, Λεύκιον Πέλλαν, Σαρδιανῶν κατηγορούντων ἐπὶ κλοπαῖς δημοσίᾳ καταγνοὺς ἠτίμωσε· καὶ τὸ πρᾶγμα Κάσσιον οὐ μετρίως ἐλύπησεν. αὐτὸς γὰρ ὀλίγαις ἡμέραις ἔμπροσθεν ἐπὶ τοῖς αὐτοῖς ἐλεγχθέντας ἀδικήμασι δύο φίλους ἰδίᾳ νουθετήσας φανερῶς ἀφῆκε καὶ διετέλει χρώμενος. ὅθεν ᾐτιᾶτο τὸν Βροῦτον ὡς ἄγαν ὄντα νόμιμον καὶ δίκαιον ἐν καιρῷ πολιτείας δεομένῳ καὶ φιλανθρωπίας. ὁ δὲ τῶν εἰδῶν τῶν Μαρτίων ἐκέλευεν αὐτὸν μνημονεύειν ἐκείνων, ἐν αἷς Καίσαρα ἔκτειναν, οὐκ αὐτὸν ἄγοντα καὶ φέροντα πάντας ἀνθρώπους, ἀλλ’ ἑτέρων δύναμιν ὄντα ταῦτα πρασσόντων· ὡς, εἴτις ἔστι πρόφασις καλὴ μεθ’ ἧς ἀμελεῖται τὸ δίκαιον, ἄμεινον ἦν τοὺς Καίσαρος φίλους ὑπομένειν ἢ τοὺς ἑαυτῶν περιορᾶν ἀδικοῦντας. ἐκείνοις μὲν γὰρ ἀνανδρίας, ἀδικίας δὲ δόξα μετὰ κινδύνων ἡμῖν καὶ πόνων πρόσεστι. τοιαύτη μὲν ἡ τοῦ Βρούτου προαίρεσις ἦν.", "st": "Brut. 35.1"}, {"sp": "N", "t": "ἐπεὶ δὲ διαβαίνειν ἐξ Ἀσίας ἔμελλον, λέγεται τῷ Βρούτῳ μέγα σημεῖον γενέσθαι. φύσει μέν γάρ ἦν ἐπεγρήγορος ὁ ἀνήρ καὶ τόν ὕπνον εἰς ὀλίγου χρόνου μόριον ἀσκήσει καὶ σωφροσύνῃ συνῆγεν, ἡμέρας μέν οὐδέποτε κοιμώμενος, νύκτωρ δὲ τοσοῦτον ὅσον οὔτε τι πράττειν οὔτε τῳ διαλέγεσθαι, πάντων ἀναπαυομένων, παρεῖχε. τότε δὲ τοῦ πολέμου συνεστῶτος ἐν χερσὶν ἔχων τὰς ὑπὲρ τῶν ὅλων πράξεις, καὶ τεταμένος τῇ φροντίδι πρὸς τὸ μέλλον, ὁπηνίκα πρῶτον ἀφ’ ἑσπέρας ἐπινυστάξειε τοῖς σιτίοις, ἤδη τὸ λοιπὸν ἐχρῆτο τῇ νυκτὶ πρὸς τὰ κατεπείγοντα τῶν πραγμάτων. εἰ δὲ συνέλοι καὶ κατοικονομήσειε τὴν περὶ ταῦτα χρείαν, ἀνεγίνωσκε βιβλίον μέχρι τρίτης φυλακῆς, καθ’ ἣν εἰώθεσαν ἑκατόνταρχοι καὶ χιλίαρχοι φοιτᾶν πρὸς αὐτόν. ὡς οὖν ἔμελλεν ἐξ Ἀσίας διαβιβάζειν τὸ στράτευμα, νὺξ μὲν ἦν βαθυτάτη, φῶς δ’ εἶχεν οὐ πάνυ λαμπρὸν ἡ σκηνή, πᾶν δὲ τὸ στρατόπεδον σιωπῇ κατεῖχεν. ὁ δὲ συλλογιζόμενός τι καὶ σκοπῶν πρὸς ἑαυτόν ἔδοξεν αἰσθέσθαι τινὸς εἰσιόντος, ἀποβλέψας δὲ πρὸς τὴν εἴσοδον ὁρᾷ δεινὴν καὶ ἀλλόκοτον ὄψιν ἐκφύλου σώματος καὶ φοβεροῦ, σιωπῇ παρεστῶτος αὐτῷ. τολμήσας δὲ ἐρέσθαι, τίς ποτ’ ὢν, εἶπεν, ἀνθρώπων ἢ θεῶν, ἢ τί βουλόμενος ἥκεις ὡς ἡμᾶς; ὑποφθέγγεται δ’ αὐτῷ τὸ φάσμα· ὁ σὸς, ὦ Βροῦτε, δαίμων κακός· ὄψει δέ με περὶ Φιλίππους. καὶ ὁ Βροῦτος οὐ διαταραχθεὶς, ὄψομαι, εἶπεν.", "st": "Brut. 36.1"}, {"sp": "N", "t": "ἀφανισθέντος δ’ αὐτοῦ τοὺς παῖδας ἐκάλει· μήτε δ’ ἀκοῦσαί τινα φωνὴν μήτ’ ἰδεῖν ὄψιν φασκόντων, τότε μὲν ἐπηγρύπνησεν· ἅμα δ’ ἡμέρᾳ τραπόμενος πρὸς Κάσσιον ἔφραζε τὴν ὄψιν. ὁ δὲ τοῖς Ἐπικούρου λόγοις χρώμενος καὶ περὶ τούτων ἔθος ἔχων διαφέρεσθαι πρὸς τὸν Βροῦτον, ἡμέτερος οὗτος, εἶπεν, ὦ Βροῦτε, λόγος, ὡς οὐ πάντα πάσχομεν ἀληθῶς οὐδ’ ὁρῶμεν, ἀλλ’ ὑγρὸν μέν τι χρῆμα καὶ ἀπατηλὸν ἡ αἴσθησις, ἔτι δ’ ὀξυτέρα ἡ διάνοια κινεῖν αὑτὸ καὶ μεταβάλλειν ἀπ’ οὐδενὸς ὑπάρχοντος ἐπὶ πᾶσαν ἰδέαν. κηρῷ μὲν γὰρ ἔοικεν ἡ τύπωσις, ψυχῇ δ’ ἀνθρώπου, τὸ πλαττόμενον καὶ τὸ πλάττον ἐχούσῃ τὸ αὐτό, ῥᾷστα ποικίλλειν αὑτὴν καὶ σχηματίζειν δι’ ἑαυτῆς ὑπάρχει. δηλοῦσι δὲ αἱ κατὰ τοὺς ὕπνους τροπαὶ τῶν ὀνείρων, ἃς τρέπεται τὸ φανταστικόν ἐξ ἀρχῆς βραχείας παντοδαπὰ καὶ πάθη καὶ εἴδωλα γινόμενον. κινεῖσθαι δ’ ἀεὶ πέφυκε· κίνησις δ’ αὐτῷ φαντασία τις ἢ νόησις. σοὶ δὲ καὶ τὸ σῶμα ταλαιπωρούμενον φύσει τὴν διάνοιαν αἰωρεῖ καὶ παρατρέπει. δαίμονας δ’ οὔτ’ εἶναι πιθανόν οὔτε ὄντας ἀνθρώπων ἔχειν εἶδος ἢ φωνὴν ἢ δύναμιν εἰς ἡμᾶς διήκουσαν· ὡς ἔγωγ’ ἂν ἐβουλόμην, ἵνα μὴ μόνον ὅπλοις καὶ ἵπποις καὶ ναυσὶ τοσαύταις, ἀλλὰ καὶ θεῶν ἀρωγαῖς ἐπεθαρροῦμεν, ὁσιωτάτων ἔργων καὶ καλλίστων ἡγεμόνες ὄντες. τοιούτοις μὲν ὁ Κάσσιος ἐπράϋνε λόγοις τὸν Βροῦτον.", "st": "Brut. 37.1"}, {"sp": "N", "t": "ἐμβαινόντων δὲ τῶν στρατιωτῶν ἐπὶ τὰς πρώτας σημαίας ἀετοὶ δύο συγκατασκήψαντες ὁμοῦ συνδιεκομίζοντο, καὶ παρηκολούθουν ὑπὸ τῶν στρατιωτῶν τρεφόμενοι μέχρι Φιλίππων, ἐκεῖ δ’ ἡμέρᾳ μιᾷ πρὸ τῆς μάχης ᾤχοντο ἀποπτάμενοι.", "st": "Brut. 37.7"}, {"sp": "N", "t": "τὰ μὲν οὖν πλεῖστα τῶν ἐν ποσὶν ἐθνῶν ἐτύγχανεν ὁ Βροῦτος ὑπήκοα πεποιημένος. εἰ δέ τις ἢ πόλις ἢ δυνάστης παρεῖτο, τότε πάντας προσαγόμενοι μέχρι τῆς κατὰ Θάσον θαλάσσης προῆλθον. ἐκεῖ δὲ τῶν περὶ Νορβανὸν ἐν τοῖς Στενοῖς λεγομένοις καὶ περὶ τὸ Σύμβολον στρατοπεδευόντων, περιελθόντες αὐτοὺς ἠνάγκασαν ἀποστῆναι καὶ προέσθαι τὰ χωρία. μικροῦ δὲ καὶ τὴν δύναμιν αὐτῶν λαβεῖν ἐδέησαν, ὑπολειπομένου διὰ νόσον Καίσαρος, εἰ μὴ προσεβοήθησεν Ἀντώνιος ὀξύτητι θαυμαστῇ χρησάμενος, ὥστ’ ἀπιστεῖν τοὺς περὶ Βροῦτον. ἦλθε δὲ Καῖσαρ ὕστερον ἡμέραις δέκα, καὶ κατεστρατοπέδευσεν ἐναντίον Βρούτου, Κασσίου δὲ Ἀντώνιος.", "st": "Brut. 38.1"}, {"sp": "N", "t": "τὰ δ’ ἐν μέσῳ τῶν στρατοπέδων πεδία Ῥωμαῖοι κάμπους Φιλίππους καλοῦσι· καὶ μέγισται τότε Ῥωμαίων δυνάμεις ἀλλήλαις συνεφέροντο. πλήθει μὲν οὖν οὐ παρ’ ὀλίγον ἐλείποντο τῶν περὶ Καίσαρα, κόσμῳ δ’ ὅπλων καὶ λαμπρότητι θαυμαστὸν ἐξεφάνη τὸ Βρούτου στράτευμα. χρυσὸς γὰρ ἦν αὐτοῖς τὰ πλεῖστα τῶν ὅπλων καὶ ἄργυρος ἀφειδῶς καταχορηγηθείς, καίπερ εἰς τἆλλα τοῦ Βρούτου σώφρονι διαίτῃ καὶ κεκολασμένῃ χρῆσθαι τοὺς ἡγεμόνας ἐθίζοντος. τὸν δ’ ἐν χερσὶ καὶ περὶ τὸ σῶμα πλοῦτον ᾤετό τι καὶ φρονήματος παρέχειν τοῖς φιλοτιμοτέροις, τοὺς δὲ φιλοκερδεῖς καὶ μαχιμωτέρους ποιεῖν, ὥσπερ κτημάτων τῶν ὅπλων περιεχομένους.", "st": "Brut. 38.5"}, {"sp": "N", "t": "οἱ μὲν οὖν περὶ Καίσαρα καθαρμὸν ἐν τῷ χάρακι ποιησάμενοι, μικρόν τι σίτου καί δραχμὰς κατ’ ἄνδρα πέντε διένειμαν εἷς θυσίαν, οἱ δὲ περὶ Βροῦτον καταγνόντες αὐτῶν τῆς ἀπορίας ἢ μικρολογίας, πρῶτον μὲν ἐν ὑπαίθρῳ τὸν στρατὸν, ὥσπερ ἔθος ἐστὶν, ἐκάθηραν, ἔπειθ’ ἱερείων πλήθη κατὰ λόχους καί δραχμὰς ἑκάστῳ πεντήκοντα διαδόντες, εὐνοίᾳ καί προθυμίᾳ τῆς δυνάμεως πλέον εἶχον. οὐ μὴν ἀλλὰ σημεῖον ἐν τῷ καθαρμῷ μοχθηρὸν ἔδοξε Κασσίῳ γενέσθαι, τὸν γὰρ στέφανον αὐτῷ κατεστραμμένον ὁ ῥαβδοῦχος προσήνεγκε. λέγεται δὲ καί πρότερον ἐν θέᾳ τινὶ καί πομπῇ χρυσῆν Κασσίου Νίκην διαφερομένην πεσεῖν, ὀλισθόντος τοῦ φέροντος. ἔτι δ’ ὄρνεά τε σαρκοφάγα πολλὰ καθ’ ἡμέραν ἐπεφαίνετο τῷ στρατοπέδῳ, καί μελισσῶν ὤφθησαν ἑσμοὶ συνιστάμενοι περὶ τόπον τινὰ τοῦ χάρακος ἐντός, ὃν ἐξέκλεισαν οἱ μάντεις ἀφοσιούμενοι τὴν δεισιδαιμονίαν ἀτρέμα καί τόν Κάσσιον αὑτὸν ὑποφέρουσαν ἐκ τῶν Ἐπικούρου λόγων, τοὺς δὲ στρατιώτας παντάπασι δεδουλωμένην.", "st": "Brut. 39.1"}, {"sp": "N", "t": "ὅθεν οὐδ’ ἦν πρόθυμος διὰ μάχης ἐν τῷ παρόντι γενέσθαι τὴν κρίσιν, ἀλλὰ τρίβειν ἠξίου χρόνῳ τόν πόλεμον, ἐρρωμένους χρήμασιν, ὅπλων δὲ καί σωμάτων πλήθει λειπομένους. Βροῦτος δὲ καί πρότερον ἔσπευδε τῷ ταχίστῳ τῶν κινδύνων διακριθεὶς ἢ τῇ πατρίδι τὴν ἐλευθερίαν ἀναλαβεῖν ἢ πάντας ἀνθρώπους ἐνοχλουμένους δαπάναις καί στρατείαις καί προστάγμασιν ἀπαλλάξαι κακῶν, καί τότε τοὺς περὶ αὑτὸν ἱππεῖς ὁρῶν ἐν τοῖς προάγωσι καί ταῖς ἁψιμαχίαις εὐημεροῦντας καί κρατοῦντας ἐξῆρτο τὸ φρόνημα· καί τινες αὐτομολίαι γενόμεναι πρὸς τοὺς πολεμίους καί διαβολαὶ καθ’ ἑτέρων καί ὑπόνοιαι πολλοὺς τῶν Κασσίου φίλων μετέστησαν ἐν τῷ συνεδρίῳ πρὸς Βροῦτον. εἷς δὲ τῶν Βρούτου φίλων Ἀτίλλιος ἠναντιοῦτο, τόν γε χειμῶνα περιμεῖναι κελεύων. ἐρομένου δὲ τοῦ Βρούτου τινὶ βελτίων ἔσεσθαι νομίζει μετ’ ἐνιαυτόν, εἰ μηδὲν, εἶπεν, ἄλλο, πλείω βιώσομαι χρόνον. πρὸς τοῦτο Κάσσιος ἐδυσχέρανε, καί τοῖς ἄλλοις προσέκρουσεν οὐ μετρίως ὁ Ἀτίλλιος. ἐδέδοκτο δὴ μάχεσθαι τῇ ὑστεραίᾳ.", "st": "Brut. 39.7"}, {"sp": "N", "t": "καὶ Βροῦτος μὲν ἐν ἐλπίσι καλαῖς καὶ λογισμοῖς φιλοσόφοις γενόμενος παρὰ τὸ δεῖπνον ἀνεπαύετο· Κάσσιον δὲ Μεσσάλας φησὶ δειπνεῖν τε καθ’ ἑαυτόν ὀλίγους τῶν συνήθων παραλαβόντα, καὶ σύννουν ὁρᾶσθαι καὶ σιωπηλόν, οὐ φύσει τοιοῦτον ὄντα· παυσαμένου δὲ τοῦ δείπνου λαβόμενον τῆς χειρὸς αὐτοῦ σφόδρα τοσοῦτον εἰπεῖν, ὥσπερ εἰώθει φιλοφρονούμενος, Ἑλληνικῇ φωνῇ· μαρτύρομαί σε, Μεσσάλα, ταὐτὰ Πομπηΐῳ Μάγνῳ πάσχειν, ἀναγκαζόμενος διὰ μιᾶς μάχης ἀναρρῖψαι τὸν περὶ τῆς πατρίδος κύβον. ἀγαθὴν μέντοι ψυχὴν ἔχωμεν εἰς τὴν Τύχην ἀφορῶντες, κἂν βουλευσώμεθα κακῶς, ἀπιστεῖν οὐ δίκαιον. ταῦτα εἰπόντα φησὶν ό Μεσσάλας τελευταῖα πρὸς αὐτὸν ἀσπάσασθαι τὸν Κάσσιον εἶναι δὲ κεκλημένος εἰς τὴν ὑστεραίαν ἐπὶ δεῖπνον ὑπ’ αὐτοῦ γενέθλιον οὖσαν.", "st": "Brut. 40.1"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ προὔκειτο μὲν τῷ Βρούτου χάρακι καὶ τῷ Κασσίου σύμβολον ἀγῶνος φοινικοῦς χιτών, αὐτοὶ δὲ συνῆλθον εἰς τὸ μέσον τῶν στρατοπέδων καὶ λέγει Κάσσιος· εἴημεν, ὦ Βροῦτε, νικᾶν καὶ συνεῖναι τὸν πάντα χρόνον ἀλλήλοις εὖ πράξαντας· ἐπεὶ δὲ τὰ μέγιστα τῶν ἀνθρωπίνων ἀδηλότατα, καὶ τῆς μάχης παρὰ γνώμην κριθείσης οὐ ῥᾴδιον αὖθις ἀλλήλους ἰδεῖν, τί γινώσκεις περὶ φυγῆς καὶ τελευτῆς; καὶ ὁ Βροῦτος ἀπεκρίνατο· νέος ὢν ἐγὼ, Κάσσιε, καὶ πραγμάτων ἄπειρος, οὐκ οἶδ’ ὅπως ἐν φιλοσοφίᾳ λόγον ἀφῆκα μέγαν. ᾐτιασάμην Κάτωνα διαχρησάμενον ἑαυτόν, ὡς οὐχ ὅσιον οὐδ’ ἀνδρὸς ἔργον ὑποχωρεῖν τῷ δαίμονι καὶ μὴ δέχεσθαι τὸ συμπῖπτον ἀδεῶς, ἀλλ’ ἀποδιδράσκειν. νυνὶ δ’ ἀλλοῖος ἐν ταῖς τύχαις γίνομαι· καὶ θεοῦ καλῶς τὰ παρόντα μὴ βραβεύσαντος οὐ δέομαι πάλιν ἄλλας ἐλπίδας ἐξελέγχειν καὶ παρασκευάς, ἀλλ’ ἀπαλλάξομαι τὴν Τύχην ἐπαινῶν· Μαρτίαις εἰδοῖς δοὺς τῇ πατρίδι τὸν ἐμαυτοῦ βίον ἄλλον ἔζησα δι’ ἐκείνην ἐλεύθερον καὶ ἔνδοξον. ἐπὶ τούτοις Κάσσιος ἐμειδίασε καὶ τὸν Βροῦτον ἀσπασάμενος, ταῦτα, ἔφη, φρονοῦντες ἴωμεν ἐπὶ τοὺς πολεμίους, ἢ γὰρ νικήσομεν ἢ νικῶντας οὐ φοβηθησόμεθα.", "st": "Brut. 40.5"}, {"sp": "N", "t": "μετὰ ταῦτα περὶ τάξεως αὐτοῖς λόγος ἐγένετο τῶν φίλων παρόντων, καὶ Βροῦτος ᾐτεῖτο Κάσσιον αὐτὸς ἡγεῖσθαι τοῦ δεξιοῦ κέρατος, ὃ δι’ ἐμπειρίαν καὶ ἡλικίαν μᾶλλον ᾤοντο Κασσίῳ προσήκειν. οὐ μὴν ἀλλὰ καὶ τοῦτο Κάσσιος ἔδωκε, καὶ τῶν ταγμάτων τὸ μαχιμώτατον ἔχοντα Μεσσάλαν ἐκέλευσεν ἐπὶ τοῦ δεξιοῦ καταστῆναι. καὶ Βροῦτος εὐθὺς ἐξῆγε τοὺς ἱππεῖς κεκοσμημένους διαπρεπῶς, καὶ τὸ πεζὸν οὐ σχολαίτερον παρενέβαλλεν.", "st": "Brut. 40.10"}, {"sp": "N", "t": "ἔτυχον δ’ οἱ περὶ Ἀντώνιον ἀπὸ τῶν ἑλῶν, οἷς περιεστρατοπέδευον, ἐμβάλλοντες τάφρους εἰς τὸ πεδίον καὶ τὰς ἐπὶ θάλασσαν ὁδοὺς τοῦ Κασσίου περικόπτοντες. ἐφήδρευε δὲ Καῖσαρ, οὐ παρὼν αὐτὸς δι’ ἀσθένειαν, ἀλλ’ ἡ δύναμις, οὐ πάνυ μαχεῖσθαι προσδοκῶσα τοὺς πολεμίους, ἀλλὰ μόνον ἐκδρομαῖς χρῆσθαι πρὸς τὰ ἔργα καὶ βέλεσιν ἐλαφροῖς καὶ θορύβοις τοὺς ὀρύσσοντας ἐπιταράσσειν· καὶ τοῖς ἀντιτεταγμένοις οὐ προσέχοντες ἐθαύμαζον τὴν περὶ τὰς τάφρους κραυγήν ἄσημον οὖσαν καὶ πολλὴν προσφερομένην. ἐν τούτῳ γραμματείων τε παρὰ Βρούτου τοῖς ἡγεμόσι φοιτώντων, ἐν οἷς ἦν τὸ σύνθημα γεγραμμένον, αὐτοῦ τε παρεξιόντος ἵππῳ τὰ τάγματα καὶ παραθαρρύνοντος, ὀλίγοι μὲν ἔφθασαν ἀκοῦσαι τὸ σύνθημα παρεγγυώμενον, οἱ δὲ πλεῖστοι μὴ προσμείναντες ὁρμῇ μιᾷ καὶ ἀλαλαγμῷ προσεφέροντο τοῖς πολεμίοις. γενομένης δὲ δι’ ἀταξίαν ταύτην ἀνωμαλίας καὶ διασπασμοῦ τῶν ταγμάτων τὸ Μεσσάλα πρῶτον, εἶτα τὰ συνεζευγμένα παρήλλαττε τὸ Καίσαρος ἀριστερόν· καὶ βραχέα τῶν ἐσχάτων θιγόντες καὶ καταβαλόντες οὐ πολλούς, ἀλλ’ ὑπερκεράσαντες, ἐμπίπτουσιν εἰς τὸ στρατόπεδον. καὶ Καῖσαρ μέν, ὡς αὐτὸς ἐν τοῖς ὑπομνήμασιν ἱστορεῖ, τῶν φίλων τινὸς Ἀρτωρίου Μάρκου καθ’ ὕπνον ἰδόντος ὄψιν κελεύουσαν ἐκστῆναι Καίσαρα καὶ μετελθεῖν ἐκ τοῦ χάρακος, ἔφθασε μικρὸν ὑπεκκομισθεὶς ἔδοξέ τε τεθνάναι. τὸ γὰρ φορεῖον κενὸν ἀκοντίοις καὶ ὑσσοῖς βάλλοντες διήλασαν. ἦν δὲ φόνος ἐν τῷ στρατοπέδῳ τῶν ἁλισκομένων, καὶ δισχίλιοι Λακεδαιμονίων ἥκοντες ἐπίκουροι νεωστὶ συγκατεκόπησαν.", "st": "Brut. 41.1"}, {"sp": "N", "t": "οἱ δὲ μὴ κυκλωσάμενοι τοὺς Καίσαρος, ἀλλὰ συμπεσόντες, ῥᾳδίως μὲν ἀπετρέψαντο τεταραγμένους, καὶ διέφθειραν ἐν χερσὶν τρία τάγματα, καὶ συνεισέπεσον εἰς τὸ στρατόπεδον τοῖς φεύγουσιν ὑπὸ ῥύμης τοῦ κρατεῖν συνενεχθέντες, μεθ’ ἑαυτῶν ἔχοντες τὸν Βροῦτον· ὃ δ’ οὐ συνεῖδον οἱ νικῶντες ἐδείκνυε τοῖς ἡττημένοις ὁ καιρός. εἰς γὰρ τὰ γυμνὰ καὶ παραρρηγνύμενα τῆς ἐναντίας φάλαγγος, ᾗ τὸ δεξιὸν ἀπεσπάσθη πρὸς τὴν δίωξιν, ὠσάμενοι τὸ μὲν μέσον οὐκ ἐξέωσαν, ἀλλ’ ἀγῶνι μεγάλῳ συνείχοντο, τὸ δ’ εὐώνυμον ἀταξίᾳ καὶ ἀγνοίᾳ τῶν γενομένων ἐτρέψαντο καὶ καταδιώξαντες εἰς τὸν χάρακα διεπόρθουν οὐδετέρου τῶν αὐτοκρατόρων παρόντος. Ἀντώνιός τε γὰρ, ὥς φασιν, ἐκκλίνας ἐν ἀρχῇ τὴν ἔφοδον εἰς τὸ ἕλος ἀνεχώρησε, καὶ Καῖσαρ οὐδαμοῦ φανερὸς ἦν ἐκπεσὼν τοῦ χάρακος, ἀλλὰ Βρούτῳ τινὲς ὡς ἀνῃρηκότες αὐτὸν ἐπεδείκνυον ᾑμαγμένα τὰ ξίφη, φράζοντες ἰδέαν ἣν εἶχε καὶ ἡλικίαν. ἤδη δὲ τὸ μέσον ἐξεώκει φόνῳ πολλῷ τοὺς ἀντιτεταγμένους, καὶ παντελῶς ἐδόκει κρατεῖν ὁ Βροῦτος, ὥσπερ ὁ Κάσσιος κρατεῖσθαι. καὶ τοῦτο μόνον αὐτῶν διέφθειρε τὰ πράγματα, τοῦ μὲν ὡς νικῶντι Κασσίῳ μὴ βοηθήσαντος, τοῦ δὲ Βροῦτον ὡς ἀπολωλότα μὴ περιμείναντος· ἐπεὶ τῆς γε νίκης ὅρον ὃ Μεσσάλας τίθεται τὸ τρεῖς ἀετοὺς καὶ πολλὰ σημεῖα λαβεῖν τῶν πολεμίων, ἐκείνους δὲ μηδέν.", "st": "Brut. 42.1"}, {"sp": "N", "t": "ἀναχωρῶν δ’ ὁ Βροῦτος ἤδη διαπεπορθημένων τῶν Καίσαρος ἐθαύμασε τὸ Κασσίου στρατήγιον οὐχ ὁρῶν ὑψηλὸν, ὥσπερ εἰώθει, περιφαινόμενον, οὐδὲ τἆλλα κατὰ χώραν· ἐρήριπτο γὰρ εὐθὺς τὰ πλεῖστα καὶ κατέσπαστο τῶν πολεμίων ἐμπεσόντων. ἀλλ’ οἱ δοκοῦντες ὀξύτερον βλέπειν τῶν ἑταίρων ἔφραζον αὐτῷ πολλὰ μὲν ὁρᾶν κράνη λάμποντα, πολλοὺς δὲ ἀργυροῦς θυρεοὺς ἐν τῷ χάρακι τοῦ Κασσίου διαφερομένους· οὔκουν δοκεῖν αὐτοῖς οὔτ’ ἀριθμὸν οὔθ’ ὁπλισμὸν εἶναι τῶν ἀπολελειμμένων φυλάκων οὐ μὴν οὐδὲ πλῆθος ἐπέκεινα φαίνεσθαι νεκρῶν ὅσον εἰκὸς ἦν νενικημένων κατὰ κράτος ταγμάτων τοσούτων. ταῦτα πρῶτον ἔννοιαν κατέστησε τῷ Βρούτῳ τοῦ συμπτώματος· καὶ καταλιπὼν φρουρὰν ἐν τῷ στρατοπέδῳ τῶν πολεμίων ἀνεκαλεῖτο τοὺς διώκοντας καὶ συνῆγεν ὡς Κασσίῳ βοηθήσων.", "st": "Brut. 42.6"}, {"sp": "N", "t": "ἐπέπρακτο δ’ οὕτω τὰ κατ’ αὐτόν, οὔτε τὴν πρώτην ἐκδρομὴν τῶν περὶ Βροῦτον ἡδέως εἶδεν ἄνευ συνθήματος καὶ προστάγματος γενομένην, οὔθ’ ὅτε κρατοῦντες εὐθὺς ὥρμησαν ἐφ’ ἁρπαγὴν καὶ ὠφέλειαν, τοῦ περιϊέναι καὶ κυκλοῦσθαι τοὺς πολεμίους ἀμελήσαντες, ἤρεσκεν αὐτῷ τὰ πραττόμενα. μελλήσει δέ τινι καὶ διατριβῇ μᾶλλον ἢ προθυμίᾳ καὶ λογισμῷ στρατηγῶν ὑπὸ τοῦ δεξιοῦ τῶν πολεμίων περιελαμβάνετο· καὶ τῶν ἱππέων εὐθὺς ἀπορραγέντων φυγῇ πρὸς τὴν θάλασσαν ὁρῶν καὶ τοὺς πεζοὺς ἐνδιδόντας ἐπειρᾶτο κατέχειν καὶ παρακαλεῖν. ἑνὸς δὲ σημειοφόρου φεύγοντος ἀφαρπάσας τὸ σημεῖον ἔπηξε πρὸ τῶν ποδῶν, μηδὲ τῶν περὶ τὸ σῶμα τεταγμένων αὑτοῦ προθύμως ἔτι συμμενόντων. οὕτω δὴ βιασθεὶς ἀνεχώρησε μετ’ ὀλίγων ἐπὶ λόφον ἔχοντα πρὸς τὸ πεδίον σκοπάς. ἀλλ’ αὐτὸς μὲν οὐδὲν κατεῖδεν ἢ μόλις τὸν χάρακα πορθούμενον, ἦν γὰρ ἀσθενὴς τὴν ὄψιν, οἱ δὲ περὶ αὐτὸν ἱππεῖς ἑώρων πολλοὺς προσελαύνοντας, οὓς ὁ Βροῦτος ἔπεμψεν. εἴκασε δ’ ὁ Κάσσιος πολεμίους εἶναι καὶ διώκειν ἐπ’ αὐτόν. ὅμως δὲ τῶν παρόντων ἕνα Τιτίνιον ἀπέστειλε κατοψόμενον. οὗτος οὐκ ἔλαθε τοὺς ἱππέας προσιών, ἀλλ’, ὡς εἶδον ἄνδρα φίλον καὶ Κασσίῳ πιστόν, ἀλαλάξαντες ὑφ’ ἡδονῆς οἱ μὲν συνήθεις ἠσπάζοντό τε καὶ ἐδεξιοῦντο καταπηδῶντες ἀπὸ τῶν ἵππων, οἱ δ’ ἄλλοι περὶ αὐτὸν ἐν κύκλῳ περιελαύνοντες ἅμα παιᾶνι καὶ πατάγῳ διὰ χαρᾶς ἀμετρίαν τὸ μέγιστον ἀπειργάσαντο κακόν.", "st": "Brut. 43.1"}, {"sp": "N", "t": "ἔδοξε γὰρ ὁ Κάσσιος ἀληθῶς ὑπὸ τῶν πολεμίων ἔχεσθαι τὸν Τιτίνιον, καὶ τοῦτο δὴ φήσας, φιλοψυχοῦντες ἀνεμείναμεν ἄνδρα φίλον ἁρπαζόμενον ὑπὸ τῶν πολεμίων ἰδεῖν, ἀπεχώρησεν εἴς τινα σκηνὴν ἔρημον, ἕνα τῶν ἀπελευθέρων ἐφελκυσάμενος, Πίνδαρον, ὃν ἐκ τῶν κατὰ Κράσσον ἀτυχημάτων ἐπὶ ταύτην εἶχε τὴν ἀνάγκην ὑφ’ αὑτοῦ παρεσκευασμένον. ἀλλὰ Πάρθους μὲν διέφυγε, τότε δὲ τὰς χλαμύδας ἐπὶ τὴν κεφαλὴν ἀναγαγὼν καὶ γυμνώσας τὸν τράχηλον ἀποκόψαι παρέσχεν. εὑρέθη γὰρ ἡ κεφαλὴ δίχα τοῦ σώματος, τὸν δὲ Πίνδαρον οὐδεὶς εἶδεν ἀνθρώπων μετὰ τὸν φόνον, ἐξ οὗ καὶ παρέσχεν ἐνίοις δόξαν ἀνελεῖν τὸν ἄνδρα μὴ κελευσθείς. ὀλίγῳ δ’ ὕστερον οἵ θ’ ἱππεῖς ἐγένοντο φανεροί, καὶ Τιτίνιος ἐστεφανωμένος ὑπ’ αὐτῶν ἀνῄει πρὸς Κάσσιον. ὡς δὲ κλαυθμῷ καὶ βοῇ τῶν φίλων ὀδυρομένων καὶ δυσφορούντων ἔγνω τὸ πάθος τοῦ στρατηγοῦ καὶ τὴν ἄγνοιαν, ἐσπάσατο τὸ ξίφος καὶ πολλὰ κακίσας τῆς βραδυτῆτος ἑαυτὸν ἀπέσφαξε.", "st": "Brut. 43.7"}, {"sp": "N", "t": "Βροῦτος δὲ τὴν μὲν ἧτταν ἐγνωκὼς τοῦ Κασσίου προσήλαυνε, τὸν δὲ θάνατον ἐγγὺς ἤδη τοῦ χάρακος ἤκουσε. καὶ τὸ μὲν σῶμα περικλαύσας, καὶ προσαγορεύσας ἔσχατον ἄνδρα Ῥωμαίων τὸν Κάσσιον, ὡς οὐκέτι τῇ πόλει τηλικούτου φρονήματος ἐγγενέσθαι δυναμένου, περιέστειλε καὶ ἀπέπεμψεν εἰς Θάσον, ὡς μὴ σύγχυσιν αὐτόθι παράσχοι κηδευόμενον. αὐτὸς δὲ τοὺς στρατιώτας συναγαγὼν παρεμυθήσατο· καὶ πάντων ὁρῶν ἀπεστερημένους τῶν ἀναγκαίων ὑπέσχετο κατ’ ἄνδρα δισχιλίας δραχμὰς ἀντὶ τῶν ἀπολωλότων. οἱ δὲ πρός τε τοὺς λόγους ἀνεθάρρησαν αὐτοῦ καὶ τῆς δωρεᾶς ἐθαύμασαν τὸ μέγεθος· καὶ μετὰ βοῆς προὔπεμψαν ἀπιόντα, μεγαλύνοντες ὡς μόνον ἀήττητον ἐν τῇ μάχῃ τῶν τεσσάρων αὐτοκρατόρων γεγενημένον. ἐμαρτύρει δὲ τὸ ἔργον ὅτι τῇ μάχῃ περιέσεσθαι καλῶς ἐπίστευεν· ὀλίγοις γὰρ τάγμασιν ἅπαντας ἐτρέψατο τοὺς ἀντιστάντας. εἰ δὲ πᾶσιν ἐχρήσατο πρός τὴν μάχην καὶ μὴ παρελθόντες οἱ πλεῖστοι τοὺς πολεμίους ἐπὶ τὰ τῶν πολεμίων ὥρμησαν, οὐδὲν ἂν ἐδόκει μέρος αὐτῶν ἀπολιπεῖν ἀήττητον.", "st": "Brut. 44.1"}, {"sp": "N", "t": "ἔπεσον δὲ τούτων μὲν ὀκτακισχίλιοι σὺν τοῖς στρατευομένοις οἰκέταις, οὓς Βρίγας ὁ Βροῦτος ὠνόμαζε· τῶν δ’ ἐναντίων Μεσσάλας φησὶν οἴεσθαι πλείους ἢ διπλασίους. διὸ καὶ μᾶλλον ἠθύμουν ἐκεῖνοι πρὶν ἢ Κασσίου θεράπων ὄνομα Δημήτριος ἀφίκετο πρὸς Ἀντώνιον ἑσπέρας, εὐθὺς ἀπὸ τοῦ νεκροῦ τὰς χλαμύδας λαβὼν καὶ τὸ ξίφος. ὦν κομισθέντων οὕτως ἐθάρρησαν ὥστε ἅμ’ ἡμέρᾳ προάγειν ὡπλισμένην ἐπὶ μάχῃ τὴν δύναμιν. Βρούτῳ δὲ τῶν στρατοπέδων ἑκατέρου σαλεύοντος ἐπισφαλῶς τὸ μὲν γὰρ αὐτοῦ καταπεπλησμένον αἰχμαλώτων ἐδεῖτο φυλακῆς ἀκριβοῦς, τὸ δὲ Κασσίου τὴν μεταβολὴν τοῦ ἄρχοντος οὐ ῥᾳδίως ἔφερεν, ἀλλὰ καὶ φθόνου τι καὶ μίσους ἡττημένοις ἐνῆν αὐτοῖς πρὸς τὸ νενικηκός, ὁπλίσαι μὲν ἔδοξε τὸ στράτευμα, μάχης δ’ ἀπέσχετο. τῶν δ’ αἰχμαλώτων τὸ μὲν δουλικὸν πλῆθος ἐνειλούμενον ὑπόπτως τοῖς ὅπλοις ἐκέλευσεν ἀναιρεθῆναι, τῶν δ’ ἐλευθέρων τοὺς μὲν ἀπέλυε φάσκων ὑπὸ τῶν πολεμίων μᾶλλον ἡλωκέναι αὐτοὺς καὶ παρ’ ἐκείνοις αἰχμαλώτους εἶναι καὶ δούλους, παρ’ αὑτῷ δ’ ἐλευθέρους καὶ πολίτας· ὡς δὲ τοὺς φίλους ἑώρα καὶ τοὺς ἡγεμόνας ἀδιαλλάκτως ἔχοντας, ἀποκρύπτων καὶ συνεκπέμπων ἔσῳζεν. ἦν δέ τις Βολούμνιος μῖμος καὶ Σακουλίων γελωτοποιὸς ἡλωκότες, οὓς ἐν οὐδενὶ λόγῳ τιθεμένου τοῦ Βρούτου προσάγοντες οἱ φίλοι κατηγόρουν ὡς οὐδὲ νῦν τοῦ λέγειν καὶ σκώπτειν πρὸς ὕβριν αὐτῶν ἀπεχομένους. ἐπεὶ δὲ Βροῦτος μὲν ἐσίγα πρὸς ἑτέραις ὢν φροντίσι, Μεσσάλας δὲ Κορβῖνος ἐδικαίου πληγαῖς κολασθέντας ἐπὶ σκηνῆς γυμνοὺς ἀποδοθῆναι τοῖς στρατηγοῖς τῶν πολεμίων, ὅπως εἰδῶσιν οἵων δέονται στρατευόμενοι συμποτῶν καὶ συνήθων, ἔνιοι μὲν τῶν παρόντων ἐγέλασαν, Πόπλιος δὲ Κάσκας, ὁ πρῶτος Καίσαρα πατάξας, οὐ καλῶς, ἔφη, τεθνηκότι Κασσίῳ παίζοντες καὶ γελωτοποιοῦντες ἐναγίζομεν σὺ δέ, εἶπεν, ὦ Βροῦτε, δείξεις ὅπως ἔχεις μνήμης πρὸς τὸν στρατηγόν ἢ κολάσας ἢ φυλάξας τοὺς χλευασομένους καὶ κακῶς ἐροῦντας αὐτόν. πρὸς τοῦτο Βροῦτος εὖ μάλα δυσχεράνας, τί οὖν, εἶπεν, ἐμοῦ πυνθάνεσθε, Κάσκα, καὶ οὐ πράττετε τὸ δόξαν ὑμῖν; ταύτην ἐκεῖνοι τὴν ἀπόκρισιν συγκατάθεσιν ποιησάμενοι κατὰ τῶν ἀθλίων ἀνθρώπων, διέφθειραν αὐτοὺς ἀπαγαγόντες.", "st": "Brut. 45.1"}, {"sp": "N", "t": "ἐκτούτου τὴν δωρεὰν ἀπέδωκε τοῖς στρατιώταις, καὶ μικρὰ μεμψάμενος ἐπὶ τῷ τὸ σύνθημα μὴ λαβόντας ἄνευ παραγγέλματος ἀτακτότερον ἐναλέσθαι τοῖς πολεμίοις, ὑπέσχετο καλῶς ἀγωνισαμένοις δύο πόλεις εἰς ἁρπαγὴν καὶ ὠφέλειαν ἀνήσειν, Θεσσαλονίκην καὶ Λακεδαίμονα. τοῦτο τῷ Βρούτου βίῳ μόνον ἔνεστι τῶν ἐγκλημάτων ἀναπολόγητον, εἰ καὶ πολὺ τούτων δεινότερα νικητήρια τοῖς στρατευομένοις Ἀντώνιος καὶ Καῖσαρ ἐξέτισαν, ὀλίγου δεῖν πάσης Ἰταλίας τοὺς παλαιοὺς οἰκήτορας ἐξελάσαντες, ἵνα χώραν ἐκεῖνοι καὶ πόλεις τὰς μὴ προσηκούσας λάβωσιν. ἀλλὰ τούτοις μὲν ἄρχειν καὶ κρατεῖν ὑπέκειτο τοῦ πολέμου τέλος, Βρούτῳ δὲ διὰ δόξαν ἀρετῆς οὔτε νικᾶν οὔτε σῴζεσθαι συνεχωρεῖτο παρὰ τῶν πολλῶν ἢ μετὰ τοῦ καλοῦ καὶ δικαίου, καὶ ταῦτα Κασσίου τεθνηκότος, ὃς αἰτίαν εἶχε καὶ Βροῦτον ἐνάγειν εἰς ἔνια τῶν βιαιοτέρων. ἀλλ’ ὥσπερ ἐν πλῷ πηδαλίου συντριβέντος ἕτερα ξύλα προσηλοῦν καὶ προσαρμόττειν ἐπιχειροῦσιν, οὐκ εὖ μέν, ἀναγκαῖα δὲ, μαχόμενοι πρὸς τὴν χρείαν, οὕτω Βροῦτος ἐν δυνάμει τοσαύτῃ καὶ μετεώροις πράγμασιν οὐκ ἔχων ἰσορροποῦντα στρατηγόν ἠναγκάζετο χρῆσθαι τοῖς παροῦσι καὶ πολλὰ πράσσειν καὶ λέγειν τῶν ἐκείνοις δοκούντων. ἐδόκει δ’ ὅσα τοὺς Κασσίου στρατιώτας ᾤοντο βελτίους παρέξειν δυσμεταχείριστοι γὰρ ἦσαν, ἐν μὲν τῷ στρατοπέδῳ δι’ ἀναρχίαν θρασυνόμενοι, πρὸς δὲ τοὺς πολεμίους διὰ τὴν ἧτταν ἀποδειλιῶντες.", "st": "Brut. 46.1"}, {"sp": "N", "t": "οὐδὲν δὲ βέλτιον εἶχε τὰ πράγματα τοῖς περὶ Καίσαρα καὶ Ἀντώνιον, ἀγορᾷ τε χρωμένοις ἀναγκαῖα καὶ διὰ κοιλότητα τοῦ στρατοπέδου χειμῶνα μοχθηρὸν προσδοκῶσιν. εἱλούμενοι γὰρ πρὸς ἕλεσι καὶ μετὰ τὴν μάχην ὄμβρων φθινοπωρινῶν ἐπιγενομένων πηλοῦ κατεπίμπλαντο τὰς σκηνὰς καὶ ὕδατος παραχρῆμα πηγνυμένου διὰ ψῦχος. ἐν τούτῳ δ’ οὖσιν αὐτοῖς ἧκεν ἀγγελία περὶ τῆς κατὰ θάλατταν γενομένης ἀτυχίας περὶ τὴν στρατιάν. ἐξ Ἰταλίας γὰρ πολλὴν κομιζομένην παρὰ Καίσαρος αἱ Βρούτου νῆες ἐπιπεσοῦσαι διέφθειραν, ὧν ὀλίγοι παντάπασι τοὺς πολεμίους διαφυγόντες ὑπὸ λιμοῦ τῶν ἱστίων καὶ τῶν σχοινίων ἐσθίοντες διεγένοντο. ταῦτ’ ἀκούσαντες ἔσπευδον διὰ μάχης κριθῆναι πρὶν αἰσθέσθαι τὸν Βροῦτον ὅσον αὐτῷ γέγονεν εὐτυχίας. καὶ γὰρ ἡμέρᾳ μιᾷ συνέβη τόν τε κατὰ γῆν ἅμα καὶ τόν κατὰ θάλατταν ἀγῶνα κριθῆναι. τύχῃ δέ τινι μᾶλλον ἢ κακίᾳ τῶν ἐν ταῖς ναυσὶν ἡγεμόνων ἠγνόησε τὸ κατόρθωμα Βροῦτος ἡμερῶν εἴκοσι διαγενομένων. οὐ γὰρ ἂν εἰς δευτέραν μάχην προῆλθε, τὰ μὲν ἀναγκαῖα τῇ στρατιᾷ παρεσκευασμένος εἰς πολὺν χρόνον, ἐν καλῷ δὲ τῆς χώρας ἱδρυμένος, ὥστε καὶ χειμῶνος ἀπαθὲς καὶ πρὸς τοὺς πολεμίους δυσεκβίαστον ἔχειν τὸ στρατόπεδον, τῷ δὲ κρατεῖν βεβαίως τῆς θαλάττης καὶ νενικηκέναι πεζῇ τὸ καθ’ αὑτὸν ἐπ’ ἐλπίδων μεγάλων καὶ φρονήματος γεγονώς.", "st": "Brut. 47.1"}, {"sp": "N", "t": "ἀλλὰ τῶν πραγμάτων, ὡς ἔοικεν, οὐκέτι πολλοῖς ὄντων καθεκτῶν, ἀλλὰ μοναρχίας δεομένων, ὁ θεὸς, ἐξάγειν καὶ μεταστῆσαι τόν μόνον ἐμποδὼν ὄντα τῷ κρατεῖν δυναμένῳ βουλόμενος, ἀπέκοψε τὴν τύχην ἐκείνην, καίπερ ἐγγυτάτω τοῦ μὴ λαθεῖν τόν Βροῦτον ἀφικομένην, μέλλοντος γὰρ αὐτοῦ μάχεσθαι πρὸ μιᾶς ἡμέρας ὀψὲ Κλώδιός τις ἐκ τῶν πολεμίων αὐτόμολος ἧκεν, ἀγγέλλων ὅτι διεφθαρμένον ᾐσθημένοι τόν στόλον οἱ περὶ Καίσαρα σπεύδουσι διαγωνίσασθαι. ταῦτα λέγων ὁ ἄνθρωπος οὐκ εἶχε πίστιν οὐδ’ εἰς ὄψιν ἦλθε τῷ Βρούτῳ, καταφρονηθεὶς παντάπασιν ὡς μηδὲν ἀκηκοὼς ὑγιές ἢ τὰ ψευδῆ πρὸς χάριν ἀπαγγέλλων.", "st": "Brut. 47.7"}, {"sp": "N", "t": "ἐν ἐκείνῃ δὲ τῇ νυκτὶ πάλιν φασὶν εἰς ὄψιν ἐλθεῖν τὸ φάσμα τῷ Βρούτῳ, καὶ τὴν αὐτὴν ἐπιδειξάμενον ὄψιν οὐδὲν εἰπεῖν, ἀλλ’ οἴχεσθαι. Πόπλιος δὲ Βολούμνιος, ἀνὴρ φιλόσοφος καὶ συνεστρατευμένος ἀπ’ ἀρχῆς Βρούτῳ, τοῦτο μὲν οὐ λέγει τὸ σημεῖον, μελισσῶν δέ φησι τὸν πρῶτον ἀετὸν ἀνάπλεων γενέσθαι· καὶ τῶν ταξιάρχων τινὸς ἀπ’ αὐτομάτου τὸν βραχίονα μύρον ῥόδινον ἐξανθεῖν, καὶ πολλάκις ἐξαλείφοντας καὶ ἀπομάττοντας μηδὲν περαίνειν. καὶ πρὸ τῆς μάχης αὐτῆς ἀετοὺς δύο συμπεσόντας ἀλλήλοις ἐν μεταιχμίῳ τῶν στρατοπέδων μάχεσθαι, καὶ σιγὴν ἄπιστον ἔχειν τὸ πεδίον θεωμένων ἁπάντων, εἶξαι δὲ καὶ φυγεῖν τὸν κατὰ Βροῦτον. ὁ δὲ Αἰθίοψ περιβόητος γέγονεν ὁ τῆς πύλης ἀνοιχθείσης ἀπαντήσας τῷ φέροντι τὸν ἀετὸν καὶ κατακοπεὶς ταῖς μαχαίραις ὑπὸ τῶν στρατιωτῶν οἰωνισαμένων.", "st": "Brut. 48.1"}, {"sp": "N", "t": "προαγαγὼν δὲ τὴν φάλαγγα καὶ καταστήσας ἐναντίαν τοῖς πολεμίοις ἐπεῖχε πολὺν χρόνον· ὑποψίαι γὰρ αὐτῷ καὶ μηνύσεις κατά τινων προσέπιπτον ἐπισκοποῦντι τὸ στράτευμα· καὶ τοὺς ἱππέας ἑώρα μάχης ἄρχειν οὐ πάνυ προθύμους ὄντας, ἀλλ’ ἀεὶ προσμένοντας τὸ τῶν πεζῶν ἔργον. εἶτ’ ἐξαίφνης ἀνὴρ πολεμικὸς καὶ τετιμημένος ἐπ’ ἀνδρείᾳ διαπρεπῶς παρὰ τὸν Βροῦτον αὑτὸν ἐξιππασάμενος μεταβάλλεται πρὸς τοὺς πολεμίους· Καμουλᾶτος δὲ ἐκαλεῖτο. τοῦτον ἰδὼν ὁ Βροῦτος ἤλγησεν ἰσχυρῶς· καὶ τὰ μὲν ὑπ’ ὀργῆς, τὰ δὲ φόβῳ μείζονος μεταβολῆς καὶ προδοσίας εὐθὺς ἐπὶ τοὺς ἐναντίους ἦγεν, εἰς ὥραν ἐνάτην τοῦ ἡλίου καταφερομένου. καὶ τῷ μὲν καθ’ αὑτὸν ἐκράτησε μέρει καὶ προῆλθεν ὑποχωροῦντι τῷ ἀριστερῷ τῶν πολεμίων ἐγκείμενος· καὶ συνεπέρρωσαν οἱ ἱππεῖς ἅμα τοῖς πεζοῖς ἐμβαλόντες τεταραγμένοις· τὸ δ’ ἕτερον κέρας, ὡς μὴ κυκλωθείη, τῶν ἡγεμόνων ἀντιπαρεξαγόντων, πλήθει δὲ λειπομένων, διεσπᾶτο μέσον καὶ γιγνόμενον ἀσθενὲς οὐκ ἀντεῖχε τοῖς ἐναντίοις, ἀλλ’ ἔφυγε πρῶτον. οἱ δὲ τοῦτο διακόψαντες εὐθὺς ἐκυκλοῦντο τὸν Βροῦτον, αὑτὸν μὲν ὅσα καὶ στρατηγικῆς καὶ στρατιωτικῆς ἀρετῆς ἔργα καὶ χειρὶ καὶ γνώμῃ παρὰ τὰ δεινὰ πρὸς τὸ νικᾶν ἀποδεικνύμενον, ᾧ δὲ πλέον ἔσχε τῇ προτέρᾳ μάχῃ, τούτῳ βλαπτόμενον. τῶν μὲν γὰρ πολεμίων τὸ νικηθὲν εὐθὺς ἀπολώλει τότε· τῶν δὲ Κασσίου τραπέντων ὀλίγοι διεφθάρησαν, οἱ δὲ σῳζόμενοι τῷ προηττῆσθαι περιδεεῖς ὄντες ἀνέπλησαν ἀθυμίας καὶ ταραχῆς τὸ πλεῖστον τοῦ στρατεύματος, ἐνταῦθα καὶ Μᾶρκος ὁ Κάτωνος υἱός ἐν τοῖς ἀρίστοις καὶ γενναιοτάτοις; τῶν νέων μαχόμενος καὶ καταπονούμενος οὐκ ἔφυγεν οὐδ’εἶξεν, ἀλλὰ χρώμενός τε τῇ χειρὶ καὶ φράζων ὅστις εἴη, καὶ πατρόθεν ὀνομάζων, ἔπεσεν ἐπὶ πολλοῖς νεκροῖς τῶν πολεμίων. ἔπιπτον δὲ καὶ τῶν ἄλλων οἱ κράτιστοι τοῦ Βρούτου προκινδυνεύοντες.", "st": "Brut. 49.1"}, {"sp": "N", "t": "ἦν δέ τις Λουκίλλιος, ἀνὴρ ἀγαθὸς, ἐν τοῖς ἑταίροις, οὗτος ὁρῶν βαρβάρους τινὰς ἱππέας ἐν τῇ διώξει τῶν μὲν ἄλλων οὐδένα ποιουμένους λόγον, ἐλαύνοντας δὲ ῥύδην ἐπὶ τὸν Βροῦτον, ἔγνω παρακινδυνεύσας ἐμποδὼν αὐτοῖς γενέσθαι. καὶ μικρὸν ὑπολειφθεὶς αὐτός ἔφη Βροῦτος εἶναι· καὶ πιθανὸς ἦν πρὸς Ἀντώνιον δεόμενος ἄγειν ἑαυτόν, ὡς Καίσαρα δεδοικώς, ἐκείνῳ δὲ θαρρῶν. οἱ δ’ἀσπασάμενοι τὸ εὕρημα καὶ τύχῃ τινὶ θαυμαστῇ κεχρῆσθαι νομίζοντες ἦγον τὸν ἄνδρα σκότους ἤδη, προπέμψαντες ἐξ αὑτῶν τινας ἀγγέλους παρὰ τὸν Ἀντώνιον. αὐτός τε οὖν ἡσθεὶς ἀπήντα τοῖς ἄγουσι, καὶ τῶν ἄλλων οἱ πυνθανόμενοι ζῶντα Βροῦτον κομίζεσθαι συνετρόχαζον, οἱ μὲν ἐλεεινὸν ἡγούμενοι τῆς τύχης, οἱ δὲ τῆς δόξης ἀνάξιον, ἄγραν βαρβάρων ὑπὸ φιλοψυχίας γενόμενον. ἐπεὶ δ’ ἐγγὺς ἦσαν, ὁ μὲν Ἀντώνιος ὑπέστη, διαπορῶν ὅπως χρὴ δέξασθαι τὸν Βροῦτον, ὁ δὲ Λουκίλλιος προσαχθεὶς μάλα τεθαρρηκώς Μᾶρκον μὲν, εἶπεν, Ἀντώνιε, Βροῦτον οὐδεὶς ᾕρηκεν οὐδ’ ἂν ἕλοι πολέμιος· μὴ τοσοῦτον ἡ τύχῃ κρατήσειε τῆς ἀρετῆς. ἀλλ’ ἐκεῖνος εὑρεθήσεται ζῶν ἤ που καὶ νεκρὸς ἀξίως κείμενος ἑαυτοῦ. ἐγὼ δὲ τοὺς σοὺς στρατιώτας παρακρουσάμενος ἥκω, παθεῖν οὐδὲν ἐπὶ τούτῳ τῶν ἀνηκέστων παραιτούμενος. ταῦτ’ εἰπόντος τοῦ Λουκιλλίου καὶ πάντων ἐκπλαγέντων Ἀντώνιος πρὸς τοὺς κομίσαντας αὐτὸν ἀποβλέψας, ἦ που χαλεπῶς, εἶπεν, ὦ συστρατιῶται, φέρετε τῇ ἁμαρτίᾳ περιυβρίσθαι δοκοῦντες. ἀλλ’ εὖ ἴστε κρείττονα τῆς ζητουμένης ἄγρας ᾑρηκότες. πολέμιον γὰρ ζητοῦντες ἥκετε φίλον ἡμῖν κομίζοντες· ὡς ἐγὼ Βρούτῳ μὲν οὐκ οἶδα μὰ τοὺς θεοὺς ὅ τι ἂν ἐχρησάμην ζῶντι· τοιούτων δ’ ἀνδρῶν φίλων τυγχάνοιμι μᾶλλον ἢ πολεμίων. ταῦτ’ εἰπὼν καὶ τὸν Λουκίλλιον ἀσπασάμενος τότε μὲν ἑνὶ τῶν φίλων συνέστησεν, ὕστερον δὲ χρώμενος εἰς πάντα πιστῷ καὶ βεβαίῳ διετέλεσε.", "st": "Brut. 50.1"}, {"sp": "N", "t": "Βροῦτος δὲ διαβάς τι ῥεῖθρον ὑλῶδες καὶ παράκρημνον ἤδη σκότους ὄντος οὐ πολὺ προῆλθεν, ἀλλ’ ἐν τόπῳ κοίλῳ καὶ πέτραν ἔχοντι μεγάλην προκειμένην καθίσας, ὀλίγων περὶ αὐτὸν ἡγεμόνων καὶ φίλων ὄντων, πρῶτα μὲν ἀποβλέψας εἰς τὸν οὐρανὸν ἀστέρων ὄντα μεστόν ἀνεφθέγξατο δύο στίχους, ὧν τὸν ἕτερον Βολούμνιος ἀνέγραψε·", "st": "Brut. 51.1"}, {"sp": "N", "t": "Ζεῦ, μὴ λάθοι σε τῶνδ’ ὃς αἴτιος κακῶν·<br>τοῦ δ’ ἑτέρου φησὶν ἐπιλαθέσθαι.", "st": "Brut. 51.1b"}, {"sp": "N", "t": "μετὰ δὲ μικρὸν τῶν ἐν τῇ μάχῃ πρὸ αὐτοῦ πεσόντων ἑταίρων ἕκαστον ὀνομάζων μάλιστα τῇ Φλαβίου μνήμῃ καὶ τῇ Λαβεῶνος ἐπεστέναξεν. ἦν δ’ αὐτοῦ πρεσβευτὴς ὁ Λαβεών, ὁ δὲ Φλάβιος ἔπαρχος τῶν τεχνιτῶν. ἐν τούτῳ δέ τις αὐτός τε διψήσας καὶ τὸν Βροῦτον ὁρῶν ὁμοίως ἔχοντα, λαβὼν κράνος ἐπὶ τὸν ποταμὸν κατέδραμε. ψόφου δὲ κατὰ θάτερα προσπεσόντος Βολούμνιος προῆλθε κατοψόμενος, καὶ σὺν αὐτῷ Δάρδανος ὁ ὑπασπιστής. ἐπανελθόντες δὲ μετὰ μικρὸν ἠρώτησαν περὶ τοῦ πώματος, ἠθικῶς δὲ σφόδρα μειδιάσας ὁ Βροῦτος πρὸς τὸν Βολούμνιον ἐκπέποται, εἶπεν, ἀλλ’ ἕτερον ὑμῖν κομισθήσεται πεμφθεὶς δ’ ὁ αὐτός ἐκινδύνευσεν ὑπὸ τῶν πολεμίων ἁλῶναι καὶ μόλις ἐσώθη τετρωμένος. εἰκάζοντι δὲ αὐτῷ μὴ πολλοὺς ἐν τῇ μάχῃ τεθνάναι Στατύλλιος ὑπέστη διὰ τῶν πολεμίων ἐκπαισάμενος (ἄλλως γὰρ οὐκ ἦν) κατόψεσθαι τὸ στρατόπεδον, καὶ πυρσὸν ἄρας ἄνπερ εὕρῃ τἀκεῖ σῳζόμενα, πάλιν ἀφίξεσθαι πρὸς αὐτόν. ὁ μὲν οὖν πυρσὸς ἤρθη τοῦ Στατυλλίου παρελθόντος εἰς τὸ στρατόπεδον, ὡς δ’ οὐκ ἐπανῄει χρόνῳ πολλῷ Βροῦτος εἶπεν ἂν ζῇ Στατύλλιος, ἀφίξεται. συνέβη δ’ αὐτὸν ἐπανερχόμενον ἐμπεσεῖν εἰς τοὺς πολεμίους καὶ διαφθαρῆναι.", "st": "Brut. 51.2"}, {"sp": "N", "t": "προϊούσης δὲ τῆς νυκτός ἀποκλίνας, ὡς ἔτυχε καθεζόμενος, πρὸς οἰκέτην ἑαυτοῦ Κλεῖτον ἐλάλει. σιωπῶντος δὲ τοῦ Κλείτου καὶ δακρύοντος, αὖθις ἐπισπασάμενος τὸν ὑπασπιστὴν Δάρδανον ἰδίᾳ τινὰς αὐτῷ προσέφερε λόγους. τέλος δὲ τὸν Βολούμνιον αὐτὸν Ἑλληνιστὶ τῶν λόγων καὶ τῆς ἀσκήσεως ὑπεμίμνῃσκε· καὶ παρεκάλει τῇ χειρὶ συνεφάψασθαι τοῦ ξίφους αὐτῷ καὶ συνεπερεῖσαι τὴν πληγήν. τοῦ δὲ Βολουμνίου διωσαμένου καὶ τῶν ἄλλων ὁμοίως ἐχόντων, εἰπόντος δέ τινος ὡς δεῖ μὴ μένειν, ἀλλὰ φεύγειν, ἐξαναστὰς, πάνυ μὲν οὖν, ἔφη, φευκτέον· ἀλλ’ οὐ διὰ τῶν ποδῶν, ἀλλὰ διὰ τῶν χειρῶν. ἐμβαλὼν δὲ τὴν δεξιὰν ἑκάστῳ μάλα φαιδρός ἥδεσθαι μὲν ἔφη μεγάλην ἡδονήν ὅτι τῶν φίλων αὐτὸν οὐδεὶς ἐψεύσατο, τῇ τύχῃ δ’ ἐγκαλεῖν ὑπὲρ τῆς πατρίδος· ἑαυτὸν δὲ τῶν νενικηκότων μακαριώτερον νομίζειν, οὐκ ἐχθὲς οὐδὲ πρώην μόνον, ἀλλὰ καὶ νῦν, ἀπολείποντα δόξαν ἀρετῆς, ἣν οὔτε ὅπλοις οὔτε χρήμασιν ἀπολείψουσιν οἱ κεκρατηκότες, ὡς μὴ δοκεῖν ὅτι δικαίους ἄνδρας ἄδικοι καὶ κακοὶ χρηστοὺς ἀπολέσαντες οὐ προσηκόντως ἄρχουσι. δεηθεὶς δὲ καὶ παρακαλέσας σῴζειν ἑαυτούς ἀνεχώρησεν ἀπωτέρω μετὰ δυεῖν ἢ τριῶν, ἐν οἷς ἦν καὶ Στράτων ὁ ἀπὸ λόγων ῥητορικῶν γεγονὼς αὐτῷ συνήθης. καὶ τοῦτον ἔγγιστα παραστησάμενος ἑαυτῷ καὶ τὸ ξίφος γυμνὸν ἐπὶ τῆς λαβῆς τοῖς χερσὶν ἀμφοτέραις ἐρείσας καὶ περιπεσών ἐτελεύτησεν. οἱ δέ φασιν οὐκ αὐτὸν, ἀλλὰ τὸν Στράτωνα, πολλὰ πάνυ τοῦ Βρούτου δεηθέντος, ἀποστρέψαντα τὴν ὄψιν ὑποστῆσαι τὸ ξίφος· ἐκεῖνον δὲ ῥύμῃ προσβαλόντα τὸ στέρνον καὶ διώσαντα συντόμως ἀποθανεῖν.", "st": "Brut. 52.1"}, {"sp": "N", "t": "τοῦτον δὲ τὸν Στράτωνα Μεσσάλας ἑταῖρος ὢν Βρούτῳ Καίσαρι διαλλαγεὶς ἐπὶ σχολῆς ποτε προσήγαγε, καὶ δακρύσας εἶπεν· οὗτός ἐστιν, ὦ Καῖσαρ, ὁ ἀνήρ, ὁ τῷ ἐμῷ Βρούτῳ τὴν τελευταίαν ὑπουργήσας χάριν. ἀποδεξάμενος οὖν ὁ Καῖσαρ ἔσχεν αὐτὸν ἔν τε τοῖς πόνοις καὶ ἐν τοῖς περὶ Ἄκτιον ἀγῶσιν ἕνα τῶν περὶ αὐτὸν ἀγαθῶν γενομένων Ἑλλήνων. αὐτὸν δὲ τὸν Μεσσάλαν λέγουσιν ὕστερον ἐπαινούμενον ὑπὸ Καίσαρος ὅτι, καίπερ ἐν Φιλίπποις πολεμιώτατος αὐτοῖς γενόμενος διὰ Βροῦτον, ἐν Ἀκτίῳ προθυμότατον ἑαυτὸν παρέσχεν, ἐγώ τοι, φάναι, ὦ Καῖσαρ, ἀεὶ τῆς βελτίονος καὶ δικαιοτέρας τιμῆς καὶ μερίδος ἐγενόμην.", "st": "Brut. 53.1"}, {"sp": "N", "t": "τὸν δὲ Βροῦτον ὁ Ἀντώνιος ἀνευρὼν τεθνηκότα τὸ μὲν σῶμα τῇ πολυτελεστάτῃ τῶν ἑαυτοῦ φοινικίδων περιβαλεῖν ἐκέλευσεν, ὕστερον δὲ τὴν φοινικίδα κεκλεμμένην αἰσθόμενος ἀπέκτεινε τὸν ὑφελόμενον. τὰ δὲ λείψανα πρὸς τὴν μητέρα τοῦ Βρούτου Σερβιλίαν ἀπέπεμψε. Πορκίαν δὲ τὴν Βρούτου γυναῖκα Νικόλαος ὁ φιλόσοφος ἱστορεῖ καὶ Οὐαλέριος Μάξιμος βουλομένην ἀποθανεῖν, ὡς οὐδεὶς ἐπέτρεπε τῶν φίλων, ἀλλὰ προσέκειντο καὶ παρεφύλαττον, ἐκ τοῦ πυρὸς ἀναρπάσασαν ἄνθρακας καταπιεῖν καὶ τὸ στόμα συγκλείσασαν καὶ μύσασαν οὕτω διαφθαρῆναι. καίτοι φέρεταί τις ἐπιστολὴ Βρούτου πρὸς τοὺς φίλους ἐγκαλοῦντος αὐτοῖς καὶ ὀλοφυρομένου περὶ τῆς Πορκίας, ὡς ἀμεληθείσης ὑπ’ αὐτῶν καὶ προελομένης διὰ νόσον καταλιπεῖν τὸν βίον. ἔοικεν οὖν ὁ Νικόλαος ἠγνοηκέναι τὸν χρόνον, ἐπεὶ τό γε πάθος καὶ τὸν ἔρωτα τῆς γυναικὸς καὶ τὸν τρόπον τῆς τελευτῆς ὑπονοῆσαι δίδωσι καὶ τὸ ἐπιστόλιον, εἴπερ ἄρα τῶν γνησίων ἐστίν.", "st": "Brut. 53.4"}, {"sp": "HDR", "t": "Δίωνος καὶ Βρούτου σύγκρισις"}, {"sp": "N", "t": "πολλῶν τοίνυν τοῖς ἀνδράσιν ὑπαρξάντων καλῶν, ἐν τοῖς πρώτοις δὲ τοῦ μεγίστους ἐλαχίσταις ἀφορμαῖς γενέσθαι, τοῦτο τῷ Δίωνι κάλλιστόν ἐστιν. οὐ γὰρ εἶχε τὸν ἀμφισβητοῦντα, καθάπερ ὁ Βροῦτος Κάσσιον, ἄνδρα πρὸς μὲν ἀρετὴν καὶ δόξαν οὐχ ὁμοίως ἀξιόπιστον, εἰς δὲ τὸν πόλεμον οὐκ ἐλάττονας τόλμῃ καὶ δεινότητι καὶ πράξει συμβολὰς παρασχόμενον, ᾧ γε καὶ τοῦ παντὸς ἔργου προσποιοῦσιν ἔνιοι τὴν ἀρχήν, ἡγεμόνα τῆς ἐπὶ Καίσαρα γνώμης τοῦτον ἀτρεμοῦντι Βρούτῳ γενέσθαι λέγοντες. Δίων δ’ ὥσπερ ὅπλα καὶ πλοῖα καὶ στρατιωτικὴν δύναμιν, οὕτω καὶ φίλους καὶ συνεργοὺς ἐπὶ τὴν πρᾶξιν αὐτὸς ἑαυτῷ φαίνεται κτησάμενος. οὐ μὴν οὐδ’ ὡς Βροῦτος ἐκ τῶν πραγμάτων αὑτῶν καὶ τοῦ πολέμου πλοῦτον ἔσχε καὶ δύναμιν, οὕτω καὶ Δίων, ἀλλὰ τῷ πολέμῳ προεισήνεγκεν αὐτὸς τὸν ἑαυτοῦ πλοῦτον, ὑπὲρ τῆς τῶν πολιτῶν ἐλευθερίας τοῖς τῆς φυγῆς ἐφοδίοις προκαταχρησάμενος. ἔτι δὲ Βροῦτος μὲν καὶ Κάσσιος, οὐκ ὂν ἀσφαλὲς ἡσυχίαν ἄγειν ἐκπεσοῦσι τῆς Ῥώμης, ἀλλ’ ὠφληκόσι δίκην θανάτου καὶ διωκομένοις, ἀναγκαίως εἰς τὸν πόλεμον κατέφυγον καὶ τὰ σώματα τοῖς ὅπλοις παρακαταθέμενοι διεκινδύνευσαν ὑπὲρ αὑτῶν τὸ πλέον ἢ τῶν πολιτῶν, Δίων δ’ ἀδεέστερον ἐν τῇ φυγῇ τοῦ φυγαδεύσαντος τυράννου καὶ ἥδιον διάγων ἀνέρριψεν ἑκὼν κίνδυνον τοσοῦτον ἐπὶ τῷ σῶσαι Σικελίαν.", "st": "Comp. Dion–Brut. 1.1"}, {"sp": "N", "t": "καὶ μὴν οὐχ ὅμοιον Διονυσίου Συρακουσίοις ἡ Καίσαρος ἀπαλλαγῆναι Ῥωμαίοις. ὁ μὲν γὰρ οὐδ’ ἠρνεῖτο τύραννος εἶναι κακῶν τε μυρίων ἐμπεπλήκει Σικελίαν· ἡ δὲ Καίσαρος ἀρχὴ συνισταμένη μὲν οὐκ ὀλίγα τοῖς ἐναντιουμένοις πράγματα παρέσχε, δεξαμένοις δὲ καὶ κρατηθεῖσιν ὄνομα καὶ δόκησις ἐφάνη μόνον, ἔργον δ’ ἀπ’ αὐτῆς οὐδὲν ὠμὸν οὐδὲ τυραννικὸν ὑπῆρξεν, ἀλλὰ καὶ δεομένοις ἔδοξε τοῖς πράγμασι μοναρχίας πρᾳότατος ὥσπερ ἰατρὸς ὑπ’ αὐτοῦ τοῦ δαίμονος δεδόσθαι. διὸ Καίσαρα μὲν εὐθὺς ἐπόθησεν ὁ Ῥωμαίων δῆμος, ὥστε χαλεπὸς γενέσθαι καὶ ἀπαραίτητος τοῖς ἀπεκτονόσι, Δίωνα δ’ ἡ Διονυσίου πάρεσις ἐκ Συρακουσῶν καὶ τὸ μὴ κατασκάψαι τοῦ προτέρου τυράννου τὸν τάφον ἐπαίτιον μάλιστα πρὸς τοὺς πολίτας ἐποίησεν.", "st": "Comp. Dion–Brut. 2.1"}, {"sp": "N", "t": "ἐν αὐταῖς τοίνυν ταῖς πολεμικαῖς πράξεσιν ὁ μὲν Δίων ἄμεμπτος γέγονε στρατηγός, ὡς μὲν αὐτὸς ἐβουλεύετο τοῖς πράγμασιν ἄριστα χρώμενος, ἃ δ’ ἐπταίσθη δι’ ἑτέρους ἀναλαβὼν καὶ μεταστήσας ἐπὶ τὸ βέλτιον· ὁ δὲ Βροῦτος τὸν ἔσχατον ἀγῶνα ὑπὲρ τῶν ὅλων οὔθ’ ὑποστῆναι δοκεῖ φρονίμως οὔτε σφαλεὶς ἐπανόρθωσιν εὑρεῖν, ἀλλ’ ἀπεῖπε καὶ προεῖτο τὰς ἐλπίδας, οὐδ’ ὅσον Πομπήϊος ἐπιτολμήσας τῇ τύχῃ· καὶ ταῦτα πολλῆς μὲν αὐτόθι λειπομένης ἐλπίδος ἐν τοῖς ὅπλοις, ταῖς δὲ ναυσὶ κρατῶν πάσης βεβαίως τῆς θαλάσσης.", "st": "Comp. Dion–Brut. 3.1"}, {"sp": "N", "t": "ὃ δὲ μέγιστόν ἐστιν ὧν ἐγκαλοῦσι Βρούτῳ, τὸ σωθέντα τῇ Καίσαρος χάριτι καὶ σώσαντα τῶν συνεαλωκότων ὅσους ἐβούλετο καὶ φίλον νομιζόμενον καὶ προτιμηθέντα πολλῶν αὐτόχειρα τοῦ σώσαντος γενέσθαι, τοῦτ’ οὐκ ἄν τις εἴποι κατὰ Δίωνος. ἀλλὰ τοὐναντίον, οἰκεῖος μὲν ὢν Διονυσίῳ καὶ φίλος ὤρθου τὰ πράγματα καὶ συνδιεφύλαττεν, ἐκπεσὼν δὲ τῆς πατρίδος καὶ ἀδικηθεὶς περὶ τὴν γυναῖκα καὶ τὴν οὐσίαν ἀπολέσας ἐκ προφανοῦς εἰς πόλεμον κατέστη νόμιμον καὶ δίκαιον. ἢ τοῦτ’ ἀντιστρέφει πρῶτον; ὃ γὰρ εἰς ἔπαινον ὑπάρχει τοῖς ἀνδράσι μέγιστον, ἡ πρὸς τοὺς τυράννους ἀπέχθεια καὶ μισοπονηρία, τοῦτ’ εἰλικρινές ἐστι τῷ Βρούτῳ καὶ καθαρόν, ἰδίᾳ γὰρ οὐδὲν ἐγκαλῶν Καίσαρι τῆς κοινῆς προεκινδύνευεν ἐλευθερίας· ὁ δ’ εἰ μὴ κακῶς ἔπαθεν αὐτός, οὐκ ἂν ἐπολέμησε, καὶ τοῦτο δηλοῦται ταῖς Πλάτωνος ἐπιστολαῖς, ἐξ ὧν δῆλός ἐστιν ὡς ἀποβληθεὶς τῆς τυραννίδος, οὐκ ἀποστάς, κατέλυσε Διονύσιον. ἔτι Βροῦτον μὲν καὶ Πομπηΐῳ φίλον ἐποίησεν, ἐχθρὸν ὄντα, καὶ πολέμιον Καίσαρι, τὸ κοινῇ συμφέρον, ὡς ἔχθρας ὅρῳ καὶ φιλίας ἑνὶ χρώμενον τῷ δικαίῳ· Δίων δὲ πρὸς χάριν ὤρθου πολλὰ Διονύσιον, ὅτ’ ἦν βέβαιος αὑτῷ, καὶ πρὸς ὀργὴν ἀπιστηθεὶς ἐπολέμησε. διὸ τούτῳ μὲν οὐδ’ οἱ φίλοι πάντες ἐπίστευσαν, ὡς μεταστήσας Διονύσιον οὐκ ἂν βεβαιώσαιτο τὴν ἀρχὴν αὑτῷ, πρᾳοτέρῳ τυραννίδος ὀνόματι παραγαγὼν τοὺς πολίτας, περὶ δὲ τοῦ Βρούτου τῶν ἐχθρῶν ἦν ἀκούειν ὅτι μόνος τῶν ἐπὶ Καίσαρα συναραμένων ἕνα προὔθετο σκοπὸν ἀπ’ ἀρχῆς ἄχρι τέλους τὴν πάτριον ἀποδοῦναι Ῥωμαίοις πολιτείαν.", "st": "Comp. Dion–Brut. 3.4"}, {"sp": "N", "t": "ἄνευ γε μὴν τούτων ὁ πρὸς Διονύσιον ἀγὼν οὐχ ὅμοιος ἦν δήπου τῷ πρὸς Καίσαρα. Διονυσίου μὲν γὰρ οὐδεὶς ὅστις οὐκ ἂν κατεφρόνησε τῶν συνήθων ἐν μέθαις καὶ κύβοις καὶ γυναιξὶ τὰς πλείστας ποιουμένου διατριβάς· τὸ δὲ τὴν Καίσαρος κατάλυσιν εἰς νοῦν ἐμβαλέσθαι καὶ μὴ φοβηθῆναι τὴν δεινότητα καὶ δύναμιν καὶ τύχην, οὗ καὶ τοὔνομα τοὺς Παρθυαίων καὶ Ἰνδῶν βασιλεῖς οὐκ εἴα καθεύδειν, ὑπερφυοῦς ἦν ψυχῆς καὶ πρὸς μηθὲν ὑφίεσθαι φόβῳ τοῦ φρονήματος δυναμένης. διὸ τῷ μὲν ὀφθέντι μόνον ἐν Σικελίᾳ μυριάδες οὐκ ὀλίγαι συνέστησαν ἐπὶ Διονύσιον· ἡ δὲ Καίσαρος δόξα καὶ πεσόντος ὤρθου τοὺς φίλους, καὶ τοὔνομα τὸν χρησάμενον ἦρεν ἐκ παιδὸς ἀμηχάνου πρῶτον εὐθὺς εἶναι Ῥωμαίων, ὡς ἀλεξιφάρμακον τοῦτο πρὸς τὴν Ἀντωνίου περιαψάμενον ἔχθραν καὶ δύναμιν.", "st": "Comp. Dion–Brut. 4.1"}, {"sp": "N", "t": "εἰ δὲ φήσει τις ὅτι μεγάλοις μὲν ἀγῶσιν ὁ Δίων ἐξέβαλε τὸν τύραννον, Καίσαρα δὲ Βροῦτος ἔκτεινε γυμνὸν καὶ ἀφύλακτον, αὐτὸ τοῦτο δεινότητος ἄκρας καὶ στρατηγίας ἦν ἔργον, ἄνδρα τοσαύτην περιβεβλημένον δύναμιν ἀφύλακτον λαβεῖν καὶ γυμνόν. οὐ γὰρ ἐξαίφνης οὐδὲ μόνος ἢ σὺν ὀλίγοις ἐπιπεσὼν ἀνεῖλεν, ἀλλ’ ἐκ πολλοῦ συνθεὶς τὸ βούλευμα καὶ μετὰ πολλῶν ἐπιθέμενος, ὧν οὐδεὶς ἐψεύσατ’ αὐτόν, ἢ γὰρ εὐθὺς ἔκρινε τοὺς ἀρίστους ἢ τῷ προκρῖναι τοὺς πιστευθέντας ἀγαθοὺς ἐποίησε. Δίων δὲ εἴτε κρίνας κακῶς ἐπίστευσεν ἑαυτὸν πονηροῖς εἴτε χρώμενος ἐποίησεν ἐκ χρηστῶν πονηρούς, οὐδέτερον παθεῖν ἀνδρὶ φρονίμῳ προσῆκεν. ἐπιτιμᾷ δὲ καὶ Πλάτων αὐτῷ τοιούτους ἑλομένῳ φίλους, ὑφ’ ὧν ἀπώλετο.", "st": "Comp. Dion–Brut. 4.5"}, {"sp": "N", "t": "καὶ Δίωνος μὲν τιμωρὸς οὐδεὶς ἐφάνη πεσόντος· ἀλλὰ Βροῦτον καὶ τῶν πολεμίων Ἀντώνιος μὲν ἔθαψεν ἐνδόξως, Καῖσαρ δὲ καὶ τὰς τιμὰς ἐτήρησεν. ἕστηκε δὲ χαλκοῦς ἀνδριὰς ἐν Μεδιολάνῳ τῆς ἐντὸς Ἄλπεων Γαλατίας, τοῦτον ὕστερον ἰδὼν ὁ Καῖσαρ εἰκονικὸν ὄντα καὶ χαριέντως εἰργασμένον παρῆλθεν εἶτ’ ἐπιστὰς μετὰ μικρὸν ἀκροωμένων πολλῶν τοὺς ἄρχοντας ἐκάλει, φάσκων ἔκσπονδον αὐτῶν τὴν πόλιν εἰληφέναι πολέμιον ἔχουσαν παρ’ αὑτῇ. τὸ μὲν οὖν πρῶτον, ὡς εἰκὸς, ἠρνοῦντο, καὶ τίνα λέγοι διαποροῦντες εἰς ἀλλήλους ἀπέβλεψαν. ὡς δ’ ἐπιστρέψας ὁ Καῖσαρ πρὸς τὸν ἀνδριάντα καὶ συναγαγὼν τὸ πρόσωπον, ἀλλ’ οὐχ οὗτος, ἔφη, πολέμιος ὢν ἡμέτερος ἐνταῦθα ἕστηκεν; ἔτι μᾶλλον καταπλαγέντες ἐσιώπησαν. ὁ δὲ μειδιάσας ἐπῄνεσέ τε τοὺς Γαλάτας ὡς τοῖς φίλοις καὶ παρὰ τὰς τύχας βεβαίους ὄντας, καὶ τὸν ἀνδριάντα κατὰ χώραν μένειν ἐκέλευσε.", "st": "Comp. Dion–Brut. 5.1"}, {"sp": "HDR", "t": "Ἀρτοξέρξης"}, {"sp": "N", "t": "ὁ μὲν πρῶτος Ἀρτοξέρξης, τῶν ἐν Πέρσαις βασιλέων πραότητι καὶ μεγαλοψυχίᾳ πρωτεύσας, Μακρόχειρ ἐπεκαλεῖτο τὴν δεξιὰν μείζονα τῆς ἑτέρας ἔχων, Ξέρξου δὲ ἦν υἱός· ὁ δὲ δεύτερος, περὶ οὗ τάδε γράφεται, Μνήμων ἐπικληθείς ἐκ θυγατρὸς ἦν ἐκεῖνον. Δαρείου γὰρ καὶ Παρυσάτιδος παῖδες ἐγένοντο τέσσαρες, πρεσβύτατος μὲν Ἀρτοξέρξης, μετ’ ἐκεῖνον δὲ Κῦρος, νεώτεροι δὲ τούτων Ὀστάνης καὶ Ὀξάθρης. ὁ μὲν οὖν Κῦρος ἀπὸ Κύρου τοῦ παλαιοῦ τοὔνομα ἔσχεν, ἐκείνῳ δὲ ἀπὸ τοῦ ἡλίου γενέσθαι φασί Κῦρον γὰρ καλεῖν Πέρσας τὸν ἥλιον. ὁ δὲ Ἀρτοξέρξης Ἀρσίκας πρότερον ἐκαλεῖτο· καίτοι Δείνων φησὶν ὅτι Ὀάρσης, ἀλλὰ τὸν Κτησίαν, εἰ καὶ τἆλλα μύθων ἀπιθάνων καὶ παραφόρων ἐμβέβληκεν εἰς τὰ βιβλία παντοδαπὴν πυλαίαν, οὐκ εἰκός ἐστιν ἀγνοεῖν τοὔνομα τοῦ βασιλέως παρ’ ᾧ διέτριβε θεραπεύων αὐτὸν καὶ γυναῖκα καὶ μητέρα καὶ παῖδας.", "st": "Art. 1.1"}, {"sp": "N", "t": "ὁ μὲν οὖν Κῦρος ἔντονόν τι καὶ σφοδρὸν εὐθὺς ἐκ πρώτης ἡλικίας εἶχεν, ἅτερος δὲ πραότερος ἐδόκει περὶ πάντα καὶ ταῖς ὁρμαῖς φύσει μαλακώτερος εἶναι, γυναῖκα δὲ καλὴν καὶ ἀγαθὴν ἔλαβε μὲν τῶν γονέων κελευόντων, ἐφύλαξε δὲ κωλυόντων τὸν γὰρ ἀδελφὸν αὐτῆς ἀποκτείνας ὁ βασιλεὺς ἐβουλεύετο κἀκείνην ἀνελεῖν, ὁ δὲ Ἀρσίκας τῆς μητρὸς ἱκέτης γενόμενος καὶ πολλὰ κατακλαύσας μόλις ἔπεισε μήτε ἀποκτεῖναι μήτε αὐτοῦ διαστῆσαι τὴν ἄνθρωπον. ἡ δὲ μήτηρ ὑπῆρχε τὸν Κῦρον μᾶλλον φιλοῦσα καὶ βουλομένη βασιλεύειν ἐκεῖνον, διὸ καὶ τοῦ πατρὸς νοσοῦντος ἤδη μετάπεμπτος ἀπὸ θαλάσσης γενόμενος παντάπασιν ἀνέβαινεν εὔελπις ὤν, ὡς κατειργασμένης ἐκείνης διάδοχον αὐτὸν ἀποδειχθῆναι τῆς ἀρχῆς. καὶ γὰρ εἶχεν εὐπρεπῆ λόγον ἡ Παρύσατις, ᾧ καὶ Ξέρξης ὁ παλαιὸς ἐχρήσατο, Δημαράτου διδάξαντος, ὡς Ἀρσίκαν μὲν ἰδιώτῃ, Κῦρον δὲ βασιλεύοντι Δαρείῳ τεκεῖν. οὐ μὴν ἔπεισεν, ἀλλ’ ὁ πρεσβύτερος ἀπεδείχθη βασιλεύς, Ἀρτοξέρξης μετονομασθείς, Κῦρος δὲ Λυδίας σατράπης καὶ τῶν ἐπὶ θαλάσσης στρατηγός.", "st": "Art. 2.1"}, {"sp": "N", "t": "ὀλίγῳ δ’ ὕστερον ἢ τελευτῆσαι Δαρεῖον ἐξήλασεν εἰς Πασαργάδας ὁ βασιλεύς, ὅπως τελεσθείη τὴν βασιλικὴν τελετὴν ὑπὸ τῶν ἐν Πέρσαις ἱερέων, ἔστι δὲ θεᾶς πολεμικῆς ἱερόν, ἣν Ἀθηνᾶν ἂν τις εἰκάσειεν. εἰς τοῦτο δεῖ τὸν τελούμενον παρελθόντα τὴν μὲν ἰδίαν ἀποθέσθαι στολήν, ἀναλαβεῖν δὲ ἣν Κῦρος ὁ παλαιὸς ἐφόρει πρὶν ἢ βασιλεὺς γενέσθαι, καὶ σύκων παλάθης ἐμφαγόντα τερμίνθου κατατραγεῖν καὶ ποτήριον ἐκπιεῖν ὀξυγάλακτος. εἰ δὲ πρὸς τούτοις ἕτερ’ ἄττα δρῶσιν, ἄδηλόν ἐστι τοῖς ἄλλοις. ταῦτα δρᾶν Ἀρτοξέρξου μέλλοντος ἀφίκετο Τισαφέρνης πρὸς αὐτόν ἄγων ἕνα τῶν ἱερέων, ὃς ἐν παισὶ Κύρου τῆς νομιζομένης ἀγωγῆς ἐπιστάτης γενόμενος καὶ διδάξας μαγεύειν αὐτόν οὐδενὸς ἧττον ἐδόκει Περσῶν ἀνιᾶσθαι μὴ ἀποδειχθέντος ἐκείνου βασιλέως διὸ καὶ πίστιν ἔσχε κατηγορῶν Κύρου. κατηγόρει δὲ ὡς μέλλοντος ἐνεδρεύειν ἐν τῷ ἱερῷ, καὶ ἐπειδὰν ἐκδύηται τὴν ἐσθῆτα ὁ βασιλεύς, ἐπιτίθεσθαι καὶ διαφθείρειν αὐτόν, οἱ μὲν ἐκ ταύτης τῆς διαβολῆς τὴν σύλληψιν γενέσθαι φασίν, οἱ δὲ καὶ παρελθεῖν τὸν Κῦρον εἰς τὸ ἱερὸν καὶ παραδοθῆναι κρυπτόμενον ὑπὸ τοῦ ἱερέως. μέλλοντα δὲ αὐτόν ἤδη ἀποθνῄσκειν ἡ μήτηρ περισχοῦσα ταῖς ἀγκάλαις καὶ τοῖς βοστρύχοις περιελίξασα καὶ συλλαβοῦσα τὸν ἐκείνου τράχηλον πρὸς τὸν αὑτῆς, ὀδυρομένη πολλὰ καὶ ποτνιωμένη παρῃτήσατο καὶ κατέπεμψεν αὖθις ἐπὶ θάλατταν, οὐκ ἀγαπῶντα τὴν ἀρχὴν ἐκείνην, οὐδὲ μεμνημένον τῆς διέσεως, ἀλλὰ τῆς συλλήψεως, καὶ δι’ ὀργὴν σπαργῶντα μᾶλλον ἢ πρότερον ἐπὶ τὴν βασιλείαν.", "st": "Art. 3.1"}, {"sp": "N", "t": "ἔνιοι δέ φασιν οὐκ ἀρκούμενον οἷς ἐλάμβανεν εἰς τὸ καθ’ ἡμέραν δεῖπνον ἀποστῆναι βασιλέως, εὐήθη λέγοντες, εἰ γὰρ ἄλλο μηδέν, ἀλλὰ ἡ μήτηρ ὑπῆρχε, χρῆσθαι καὶ λαμβάνειν ὅσα βούλοιτο τῶν αὑτῆς παρέχουσα καὶ διδοῦσα, μαρτυρεῖ δὲ τῷ πλούτῳ καὶ τὸ μισθοφορικόν πολλαχόθι διὰ τῶν φίλων καὶ ξένων αὐτῷ παρατρεφόμενον, ὡς Ξενοφῶν εἴρηκεν. ἀθρόους μὲν γὰρ οὐ συνήγαγεν, ἔτι τὴν παρασκευὴν ἐπικρυπτόμενος, ἀλλαχόθι δὲ ἄλλους ἐπὶ πολλαῖς προφάσεσι ξενολογοῦντας εἶχε. βασιλέως δὲ ἥ τε μήτηρ παροῦσα τὰς ὑποψίας ἀφῄρει, καὶ Κῦρος αὐτὸς ἀεὶ θεραπευτικῶς ἔγραφε, τὰ μὲν αἰτούμενος παρ’ αὐτοῦ, τὰ δὲ Τισαφέρνους ἀντικατηγορῶν, ὡς δὴ πρὸς ἐκεῖνον αὐτῷ ζήλου καὶ ἀγῶνος ὄντος.", "st": "Art. 4.1"}, {"sp": "N", "t": "ἦν δέ τις καὶ μέλλησις ἐν τῇ φύσει τοῦ βασιλέως, ἐπιείκεια φαινομένη τοῖς πολλοῖς. ἐν ἀρχῇ δὲ καὶ πάνυ ζηλοῦν ἔδοξε τὴν Ἀρτοξέρξου τοῦ ὁμωνύμου πραότητα, ἡδίω τε ἑαυτὸν παρέχων ἐντυγχάνεσθαι, καὶ περὶ τὸ τιμᾶν καὶ χαρίζεσθαι τὸ κατ’ ἀξίαν ὑπερβάλλων, κολάσεως δὲ πάσης ἀφαιρῶν τὸ ἐφυβρίζον καὶ ἡδόμενον, ἐν δὲ τῷ δέχεσθαι χάριτας οὐχ ἧττον τοῖς διδοῦσιν ἢ τοῖς λαμβάνουσιν ἐν τῷ διδόναι φαινόμενος εὔχαρις καὶ φιλάνθρωπος. οὐδὲν γὰρ ἦν οὕτως μικρόν τι τῶν διδομένων ὃ μὴ προσεδέξατο προθύμως, ἀλλὰ καὶ ῥόαν μίαν ὑπερφυῆ μεγέθει προσενέγκαντος Ὠμίσου τινὸς αὐτῷ, νὴ τὸν Μίθραν, εἶπεν, οὗτος ὁ ἀνὴρ καὶ πόλιν ἂν ἐκ μικρᾶς ταχὺ ποιήσειε μεγάλην πιστευθείς.", "st": "Art. 4.3"}, {"sp": "N", "t": "ἐπεὶ δὲ ἄλλων ἄλλα προσφερόντων καθ’ ὁδὸν αὐτουργὸς ἄνθρωπος οὐδὲν ἐπὶ καιροῦ φθάσας εὑρεῖν τῷ ποταμῷ προσέδραμε καὶ ταῖν χεροῖν ὑπολαβὼν τοῦ ὕδατος προσήνεγκεν, ἡσθεὶς ὁ Ἀρτοξέρξης φιάλην ἔπεμψεν αὐτῷ χρυσῆν καὶ χιλίους δαρεικούς. Εὐκλείδᾳ δὲ τῷ Λάκωνι, πολλὰ παρρησιαζομένῳ πρὸς αὐτὸν αὐθαδῶς, ἐκέλευσεν εἰπεῖν τὸν χιλίαρχον ὅτι σοὶ μὲν ἔξεστιν εἰπεῖν ἃ βούλει, ἐμοὶ δὲ καὶ λέγειν καὶ ποιεῖν. ἐν δὲ θήρᾳ τινὶ Τηριβάζου δείξαντος αὐτῷ τόν κάνδυν ἐσχισμένον, ἠρώτησεν ὅ τι δεῖ ποιεῖν. ἐκείνου δὲ εἰπόντος, ἄλλον αὐτὸς ἔνδυσαι, τοῦτον δὲ ἐμοὶ δός, οὕτως ἐποίησεν, εἰπών, δίδωμι μὲν, ὦ Τηρίβαζε, σοὶ τοῦτον, φορεῖν δὲ ἀπαγορεύω. τοῦ δὲ Τηριβάζου μὴ φροντίσαντος ἦν γὰρ οὐ πονηρός, ὑπόκουφος δὲ καὶ παράφορος, ἀλλὰ τόν τε κάνδυν εὐθὺς ἐκεῖνον ἐνδύντος καὶ δέραια χρυσᾶ καὶ γυναικεῖα τῶν βασιλικῶν περιθεμένου, πάντες μὲν ἠγανάκτουν οὐ γὰρ ἐξῆν, ὁ μέντοι βασιλεὺς κατεγέλασε καὶ εἶπε· δίδωμί σοι καὶ τὰ χρυσία φορεῖν ὡς γυναικὶ καὶ τὴν στολὴν ὡς μαινομένῳ. τραπέζης δὲ τῆς αὐτῆς μηδενὸς μετέχοντος ἀλλ’ ἢ μητρὸς βασιλέως ἢ γαμετῆς γυναικός, καθεζομένων τῆς μὲν ὑπ’ αὐτόν, τῆς δὲ μητρὸς ὑπὲρ αὐτόν, Ἀρτοξέρξης καὶ τοὺς ἀδελφοὺς ἐπὶ τὴν αὐτὴν ἐκάλει τράπεζαν, Ὀστάνην καὶ Ὀξάθρην, νεωτέρους ὄντας, ἐν δὲ τοῖς μάλιστα κεχαρισμένην ὄψιν παρεῖχε τοῖς Πέρσαις ἡ τῆς γυναικὸς Στατείρας ἁρμάμαξα γυμνὴ τῶν παραπετασμάτων ἀεὶ προφερομένη καὶ διδοῦσα ταῖς δημότισιν ἀσπάσασθαί αὐτὴν καὶ προσελθεῖν, ὅθεν ἠγαπᾶτο τοῖς πολλοῖς ἡ βασίλεια.", "st": "Art. 5.1"}, {"sp": "N", "t": "τὸν μέντοι Κῦρον οἱ νεωτερισταὶ καὶ πολυπράγμονες ὡς λαμπρὸν ἄνδρα τῇ ψυχῇ καὶ πολεμικὸν διαφερόντως καὶ φιλέταιρον ᾤοντο τὰ πράγματα ποθεῖν, καὶ τὸ μέγεθος τῆς ἡγεμονίας βασιλέως δεῖσθαι φρόνημα καὶ φιλοτιμίαν ἔχοντος. οὐχ ἧττον οὖν τοῖς ἄνω πιστεύων ὁ Κῦρος ἢ τοῖς περὶ αὑτόν ἐπεχείρει τῷ πολέμῳ· καὶ Λακεδαιμονίοις ἔγραφε παρακαλῶν βοηθεῖν καὶ συνεκπέμπειν ἄνδρας, οἷς ἔφη δώσειν, ἂν μὲν πεζοὶ παρῶσιν, ἵππους, ἂν δὲ ἱππεῖς, συνωρίδας· ἐὰν δ’ ἀγροὺς ἔχωσι, κώμας· ἐὰν δὲ κώμας, πόλεις· μισθοῦ δὲ τοῖς στρατευομένοις οὐκ ἀριθμόν, ἀλλὰ μέτρον ἔσεσθαι. μεγαληγορῶν δὲ περὶ αὑτοῦ πολλά καὶ καρδίαν ἔφη τοῦ ἀδελφοῦ φορεῖν βαρυτέραν καὶ φιλοσοφεῖν μᾶλλον καὶ μαγεύειν βέλτιον, οἶνον δὲ πλείονα πίνειν καὶ φέρειν ἐκεῖνον δὲ ὑπὸ δειλίας καὶ μαλακίας ἐν μὲν τοῖς κυνηγεσίοις μηδὲ ἐφ’ ἵππου, ἐν δὲ τοῖς κινδύνοις μηδὲ ἐπὶ τοῦ θρόνου καθῆσθαι. Λακεδαιμόνιοι μὲν οὖν σκυτάλην πρὸς Κλέαρχον ἀπέστειλαν ὑπηρετεῖν Κύρῳ πάντα κελεύοντες. ὁ δὲ Κῦρος ἀνέβαινεν ἐπὶ βασιλέα βαρβαρικήν τε πολλὴν ἔχων δύναμιν καὶ μισθοφόρους Ἕλληνας ὀλίγῳ τρισχιλίων καὶ μυρίων ἀποδέοντας, ἄλλας ἐπ’ ἄλλαις ποιούμενος προφάσεις τῆς στρατείας. οὐ μὴν ἔλαθέ γε εἰς πολὺν χρόνον, ἀλλ’ ἧκε βασιλεῖ Τισαφέρνης αὐτάγγελος· καὶ πολὺς θόρυβος εἶχε τὰ βασίλεια, τῆς τε Παρυσάτιδος τὴν πλείστην αἰτίαν τοῦ πολέμου φερομένης, καὶ τῶν φίλων αὐτῆς ἐν ὑποψίαις ὄντων καὶ διαβολαῖς. μάλιστα δὲ ἠνία τὴν Παρύσατιν ἡ Στάτειρα τῷ πολέμῳ περιπαθοῦσα καὶ βοῶσα, ποῦ νῦν αἱ πίστεις ἐκεῖναι; ποῦ δὲ αἱ δεήσεις, αἷς ἐξελομένη τὸν ἐπιβουλεύσαντα τῷ ἀδελφῷ πολέμου καὶ κακῶν ἐμπέπληκας ἡμᾶς; ἐκ δὴ τούτων μισοῦσα τὴν Στάτειραν ἡ Παρύσατις, καὶ φύσει βαρύθυμος οὖσα καὶ βάρβαρος ἐν ὀργαῖς καὶ μνησικακίαις, ἐπεβούλευεν αὐτὴν ἀνελεῖν. ἐπεὶ δὲ Δείνων μὲν ἐν τῷ πολέμῳ συντελεσθῆναι τὴν ἐπιβουλὴν εἴρηκε, Κτησίας δὲ ὕστερον, ὃν οὔτε ἀγνοεῖν τὸν χρόνον εἰκός ἐστι παρόντα ταῖς πράξεσιν, οὔτε ἑκὼν αἰτίαν εἶχεν ἐκ τοῦ χρόνου μεταστῆσαι τὸ ἔργον, ὡς ἐπράχθη διηγούμενος, οἷα πάσχει πολλάκις ὁ λόγος αὐτοῦ πρὸς τὸ μυθῶδες καὶ δραματικὸν ἐκτρεπόμενος τῆς ἀληθείας, τοῦτο μὲν ἣν ἐκεῖνος ἀπέδωκε χώραν ἕξει.", "st": "Art. 6.1"}, {"sp": "N", "t": "Κύρῳ δὲ προσιόντι φῆμαι καὶ λόγοι προσέπιπτον, ὡς οὐ μάχεσθαι βασιλέως εὐθὺς ἐγνωκότος οὐδὲ συνδραμεῖν εἰς χεῖρας αὐτῷ σπεύδοντος, ἀλλ’ ἐν Πέρσαις ὑπομένειν ἄχρι ἂν αἱ δυνάμεις ἐκεῖ πανταχόθεν συνέλθωσι. καὶ γὰρ τάφρον εὖρος ὀργυιῶν δέκα καὶ βάθος ἴσων ἐπὶ σταδίους διὰ τοῦ πεδίου τετρακοσίους ἐνέβαλε· καὶ ταύτης τε περιεῖδε τὸν Κῦρον ἐντὸς παρελθόντα καὶ Βαβυλῶνος αὐτῆς οὐ μακρὰν γενόμενον. Τηριβάζου δέ, ὥς φασι, πρώτου τολμήσαντος εἰπεῖν ὡς οὐ δεῖ φυγομαχεῖν οὐδὲ Μηδίας ἐκστάντα καὶ Βαβυλῶνος ἅμα καὶ Σούσων ἐνδύεσθαι τῇ Περσίδι, πολλαπλασίαν μὲν ἔχοντα δύναμιν τῶν πολεμίων, μυρίους δὲ σατράπας καὶ στρατηγούς Κύρου καὶ φρονεῖν καὶ μάχεσθαι βελτίονας, ὥρμησε διαγωνίσασθαι τὴν ταχίστην.", "st": "Art. 7.1"}, {"sp": "N", "t": "καὶ τὸ μὲν πρῶτον ἐξαίφνης καταφανεὶς ἐνενήκοντα μυριάσι στρατοῦ διακεκοσμημέναις λαμπρῶς, τοὺς πολεμίους ἀσυντάκτους καὶ ἀνόπλους διὰ τὸ θαρρεῖν καὶ καταφρονεῖν ὁδοιποροῦντας ἐξέπληξε καὶ συνετάραξεν, ὥστε σὺν θορύβῳ καὶ βοῇ πολλῇ μόλις εἰς τάξιν καθίστασθαι τὸν Κῦρον· ἔπειτα σιγῇ καὶ σχέδην ἐπάγων θαῦμα τοῖς Ἕλλησι τῆς εὐταξίας παρεῖχε, κραυγὰς ἀτάκτους καὶ σκιρτήματα καὶ πολὺν τάραχον αὐτῶν καὶ διασπασμὸν ἐν πλήθει τοσούτῳ προσδεχομένοις. εὖ δὲ καὶ κατὰ τοὺς Ἕλληνας ἀντέταξε τῶν δρεπανηφόρων τὰ ῥωμαλεώτατα πρὸ τῆς ἑαυτοῦ φάλαγγος, ὡς πρὶν ἐν χερσὶ γενέσθαι διακόψοντα τὰς τάξεις βίᾳ τῆς εἰσελάσεως.", "st": "Art. 7.3"}, {"sp": "N", "t": "τὴν δὲ μάχην ἐκείνην πολλῶν μὲν ἀπηγγελκότων, Ξενοφῶντος δὲ μονονουχὶ δεικνύοντος ὄψει, καὶ τοῖς πράγμασιν, ὡς οὐ γεγενημένοις, ἀλλὰ γινομένοις, ἐφιστάντος ἀεὶ τὸν ἀκροατὴν ἐμπαθῆ καὶ συγκινδυνεύοντα διὰ Τὴν ἐνάργειαν, οὐκ ἔστι νοῦν ἔχοντος ἐπεξηγεῖσθαι, πλὴν ὅσα τῶν ἀξίων λόγου παρῆλθεν εἰπεῖν ἐκεῖνον. ὁ μὲν οὖν τόπος, ἐν ᾧ παρετάξαντο, Κούναξα καλεῖται καὶ Βαβυλῶνος ἀπέχει σταδίους πεντακοσίους. Κῦρον δὲ πρὸ τῆς μάχης Κλεάρχου παρακαλοῦντος ἐξόπισθεν τῶν μαχομένων εἶναι καὶ μὴ κινδυνεύειν αὐτόν εἰπεῖν φασι, τί λέγεις, ὦ Κλέαρχε; σὺ κελεύεις με τὸν βασιλείας ὀρεγόμενον ἀνάξιον εἶναι βασιλείας; ἁμαρτόντος δὲ Κύρου μέγα τῷ δῦναι προπετῶς εἰς μέσα τὰ δεινὰ καὶ μὴ φυλάξασθαι τὸν κίνδυνον, οὐχ ἧττον ἥμαρτεν, εἰ μὴ καὶ μᾶλλον, Κλέαρχος ἀντιτάξαι κατὰ τὸν βασιλέα μὴ θελήσας τοὺς Ἕλληνας, ἀλλὰ προσμίξας τῷ ποταμῷ τὸ δεξιόν, ὡς μὴ κυκλωθείη. τὴν γὰρ ἀσφάλειαν ἐξ ἅπαντος διώκοντα καὶ πλεῖστον λόγον ἔχοντα τοῦ μηδὲν παθεῖν οἴκοι μένειν ἦν κράτιστον. ὁ δὲ μυρίους σταδίους ἀπὸ θαλάσσης ἐν ὅπλοις ἀναβεβηκώς μηδενὸς ἀναγκάζοντος, ἀλλ’ ὅπως Κῦρον εἰς τὸν θρόνον καθίσῃ τὸν βασίλειον, εἶτα περισκοπῶν χώραν καὶ τάξιν, οὐκ ἀφ’ ἧς σώσειε τὸν ἡγεμόνα καὶ μισθοδότην, ἀλλ’ ἐν τίνι θέμενος ἑαυτὸν ἀσφαλῶς μαχεῖται καθ’ ἡσυχίαν, ὅμοιος ἦν ὑπὸ δέους τῶν παρόντων ἐκβεβληκότι τοὺς περὶ τῶν ὅλων λογισμοὺς καὶ προιεμένῳ τὴν τῆς στρατείας ὑπόθεσιν. ὅτι γὰρ οὐδεὶς ἂν ὑπέμεινε τῶν τεταγμένων περὶ βασιλέα τοὺς Ἕλληνας ἐμπεσόντας, ὠσθέντων δ’ ἐκείνων καὶ βασιλέως φυγόντος ἢ πεσόντος ὑπῆρχε Κύρῳ νικῶντι σῴζεσθαι καὶ βασιλεύειν, ἐκ τῶν πεπραγμένων δῆλόν ἐστι. διὸ Τὴν Κλεάρχου μᾶλλον εὐλάβειαν ἢ τὸ τὸν Κύρου θράσος αἰτιατέον ὡς τὰ πράγματα καὶ Κῦρον ἀπολέσασαν. εἰ γὰρ αὐτὸς ἐσκόπει βασιλεύς ὅπου τάξας τοὺς Ἕλληνας ἀβλαβεστάτοις χρήσεται πολεμίοις, οὐκ ἂν ἑτέραν ἐξεῦρεν ἢ Τὴν ἀπωτάτω χώραν ἑαυτοῦ καὶ τῶν περὶ ἑαυτόν, ἀφ’ ἧς οὔτε νικηθεὶς αὐτὸς ᾔσθετο καὶ Κῦρος ἔφθη κατακοπεὶς ἢ χρησάμενός τι τῇ Κλεάρχου νίκῃ. καίτοι Κῦρος τὸ συμφέρον οὐκ ἠγνόησεν, ἀλλ’ ἐκεῖ Κλέαρχον ἐκέλευε τάττεσθαι κατὰ μέσον, ὁ δ’ αὑτῷ μέλειν εἰπὼν ὅπως ἕξει κάλλιστα, τὸ πᾶν διέφθειρεν.", "st": "Art. 8.1"}, {"sp": "N", "t": "οἱ μὲν γὰρ Ἕλληνες ὅσον ἐβούλοντο τοὺς βαρβάρους ἐνίκων καὶ διώκοντες ἐπὶ πλεῖστον προῆλθον· Κύρῳ δὲ γενναῖον ἵππον, ἄστομον δὲ καὶ ὑβριστὴν ἐλαύνοντι, Πασακᾶν καλούμενον, ὡς Κτησίας φησίν, ἀντεξήλασεν ὁ Καδουσίων ἄρχων Ἀρταγέρσης μέγα βοῶν, ὦ τὸ κάλλιστον ἐν Πέρσαις ὄνομα Κύρου καταισχύνων, ἀδικώτατε ἀνδρῶν καὶ ἀφρονέστατε, κακοὺς μὲν Ἕλληνας ἔρχῃ κακὴν ὁδὸν ἄγων ἐπὶ τὰ Περσῶν ἀγαθά, δεσπότην δὲ σεαυτοῦ καὶ ἀδελφὸν ἐλπίζων ἀναιρήσειν, ὃς σοῦ μυριάκις μυρίους δούλους ἔχει κρείσσονας. αὐτίκα δὲ πειράσῃ· πρότερον γὰρ ἀπολεῖς ἐνταῦθα τὴν σεαυτοῦ κεφαλὴν ἢ θεάσασθαι τὸ βασιλέως πρόσωπον. ταῦτα εἰπὼν ἐξηκόντισεν ἐπ’ αὐτόν. ὁ δὲ θώραξ στερεῶς ἀντέσχε, καὶ οὐκ ἐτρώθη μὲν ὁ Κῦρος, ἐκραδάνθη δὲ τῆς πληγῆς ἰσχυρᾶς προσπεσούσης. ἀποστρέψαντος δὲ τὸν ἵππον τοῦ Ἀρταγέρσου βαλὼν ὁ Κῦρος ἔτυχε, καὶ διήλασε παρὰ τὴν κλεῖδα διὰ τοῦ τραχήλου τὴν αἰχμήν.", "st": "Art. 9.1"}, {"sp": "N", "t": "τὸν μὲν οὖν Ἀρταγέρσην ἀποθανεῖν ὑπὸ τοῦ Κύρου σχεδὸν ἅπαντες ὁμολογοῦσι· περὶ δὲ τῆς αὐτοῦ Κύρου τελευτῆς ἐπεὶ Ξενοφῶν ἁπλῶς καὶ συντόμως, ἅτε δὴ μὴ παρὼν αὐτός, εἶπεν, οὐδὲν ἴσως κωλύει τὰ Δείνωνος ἰδίᾳ καὶ πάλιν τὰ Κτησίου διελθεῖν.", "st": "Art. 9.4"}, {"sp": "N", "t": "φησὶν οὖν ὁ μὲν Δείνων ὅτι τοῦ Ἀρταγέρσου πεσόντος εἰσελάσας βιαίως ὁ Κῦρος εἰς τοὺς προτεταγμένους τοῦ βασιλέως κατέτρωσεν αὐτοῦ τὸν ἵππον, ὁ δὲ ἀπερρύη Τηριβάζου δὲ ἀναβαλόντος αὐτὸν ἐπ’ ἄλλον ἵππον ταχὺ καὶ εἰπόντος, ὦ βασιλεῦ, μέμνησο τῆς ἡμέρας ταύτης· οὐ γὰρ ἀξία λήθης ἐστί, πάλιν ὁ Κῦρος ἐνσείσας τῷ ἵππῳ κατέβαλε τὸν Ἀρτοξέρξην. πρὸς δὲ τὴν τρίτην ἐπέλασιν δυσανασχετήσας ὁ βασιλεὺς, καὶ εἰπὼν πρὸς τοὺς παρόντας ὡς βέλτιόν ἐστι μὴ ζῆν, ἀντεξήλαυνε τῷ Κύρῳ προπετῶς καὶ ἀπερισκέπτως εἰς ἐναντία βέλη φερομένῳ. καὶ βάλλει μὲν αὐτὸς ἀκοντίῳ, βάλλουσι δὲ οἱ. περὶ αὐτόν, πίπτει δὲ ὁ Κῦρος, ὡς μὲν ἔνιοι λέγουσι, πληγεὶς ὑπὸ τοῦ βασιλέως, ὡς δὲ ἕτεροί τινες, Καρὸς ἀνθρώπου πατάξαντος, ᾧ γέρας ἔδωκε τῆς πράξεως ταύτης ὁ βασιλεὺς ἀλεκτρυόνα χρυσοῦν ἐπὶ δόρατος ἀεὶ πρὸ τῆς τάξεως ἐν ταῖς στρατείαις κομίζειν· καὶ γὰρ αὐτοὺς τοὺς Κᾶρας ἀλεκτρυόνας οἱ Πέρσαι διὰ τοὺς λόφους, οἷς κοσμοῦσι τὰ κράνη, προσηγόρευον.", "st": "Art. 10.1"}, {"sp": "N", "t": "ἡ δὲ Κτησίου διήγησις, ὡς ἐπιτεμόντι πολλὰ συντόμως ἀπαγγεῖλαι, τοιαύτη τίς ἐστι. Κῦρος ἀποκτείνας Ἀρταγέρσην ἤλαυνεν εἰς αὐτὸν βασιλέα τὸν ἵππον, καὶ αὐτὸς εἰς ἐκεῖνον, ἀμφότεροι σιωπῇ· φθάνει δὲ βαλὼν Ἀριαῖος ὁ Κύρου φίλος βασιλέα, καὶ οὐκ ἔτρωσε· βασιλεὺς δὲ ἀφεὶς τὸ δόρυ Κύρου μὲν οὐκ ἔτυχε, Σατιφέρνην δέ, πιστὸν ἄνδρα Κύρῳ καὶ γενναῖον, ἔβαλε καὶ ἀπέκτεινε. Κῦρος δ’ ἐπ’ αὐτὸν ἐξακοντίσας διὰ τοῦ θώρακος ἔτρωσε τὸ στῆθος, ὅσον ἐνδῦναι δύο δακτύλους τὸ ἀκόντιον, πεσεῖν δὲ αὐτὸν ὑπὸ τῆς πληγῆς ἀπὸ τοῦ ἵππου. φυγῆς δὲ καὶ ταραχῆς τῶν περὶ αὐτὸν γενομένης, ὁ μὲν ἀναστὰς μετ’ ὀλίγων, ἐν οἷς καὶ Κτησίας ἦν, λόφον τινὰ πλησίον καταλαβὼν ἡσύχαζε Κῦρον δὲ τοῖς πολεμίοις ἐνειλούμενον ὁ ἵππος ἐξέφερεν ὑπὸ θυμοῦ μακράν, ἤδη σκότους ὄντος ἀγνοούμενον ὑπὸ τῶν πολεμίων καὶ ζητούμενον ὑπὸ τῶν φίλων. ἐπαιρόμενος δὲ τῇ νίκῃ καὶ μεστὸς ὢν ὁρμῆς καὶ θράσους διεξήλαυνε βοῶν, Ἐξίστασθε, πενιχροί. τοῦτο δὲ περσιστὶ πολλάκις αὑτοῦ βοῶντος, οἱ μὲν ἐξίσταντο προσκυνοῦντες, ἀποπίπτει δὲ τῆς κεφαλῆς ἡ τιάρα τοῦ Κύρου. καὶ παρατρέχων νεανίας Πέρσης ὄνομα Μιθριδάτης ἀκοντίῳ βάλλει τὸν κρόταφον αὑτοῦ παρὰ τὸν ὀφθαλμόν, ἀγνοῶν ὅστις εἴη. πολὺ δὲ αἷμα τοῦ τραύματος ἐκβαλόντος ἰλιγγιάσας καὶ καρωθεὶς ὁ Κῦρος ἔπεσε, καὶ ὁ μὲν ἵππος ὑπεκφυγὼν ἐπλάζετο, τὸν δ’ ἐφίππειον πῖλον ἀπορρυέντα λαμβάνει τοῦ τὸν Κῦρον βαλόντος ἀκόλουθος αἵματος περίπλεω, τὸν δὲ Κῦρον ἐκ τῆς πληγῆς ἀναφέροντα χαλεπῶς καὶ μόλις εὐνοῦχοί τινες ὀλίγοι παρόντες ἐπεχείρουν ἐπ’ ἄλλον ἵππον ἀναθέσθαι καὶ σῴζειν. ἀδυνάτως δ’ ἔχοντα καὶ δι’ αὑτοῦ προθυμούμενον βαδίζειν ὑπολαβόντες ἦγον, τῷ μὲν σώματι καρηβαροῦντα καὶ σφαλλόμενον, οἰόμενον δὲ νικᾶν ἀκούοντα τῶν φευγόντων ἀνακαλουμένων Κῦρον βασιλέα καὶ φείδεσθαι δεομένων. ἐν δὲ τούτῳ Καύνιοί τινες ἄνθρωποι κακόβιοι καὶ ἄποροι καὶ ταπεινῶν ὑπουργημάτων ἕνεκα τῇ τοῦ βασιλέως στρατιᾷ παρακολουθοῦντες ἔτυχον συναναμιχθέντες ὡς φίλοις τοῖς περὶ τὸν Κῦρον. ὡς δὲ μόλις· συνεῖδον τὰ ἐπιθωρακίδια φοινικᾶ, λευκοῖς χρωμένων τῶν βασιλικῶν ἁπάντων, ἔγνωσαν πολεμίους ὄντας, εἷς οὖν ἐκείνων ἐτόλμησεν ἀγνοῶν ἐξόπισθεν βαλεῖν τὸν Κῦρον ἀκοντίῳ. τῆς δὲ περὶ τὴν ἰγνύαν φλεβὸς ἀναρραγείσης πεσὼν ὁ Κῦρος ἅμα παίει πρός τινι λίθῳ τὸν τετρωμένον κρόταφον καὶ ἀποθνῄσκει, τοιοῦτος μὲν ὁ Κτησίου λόγος, ᾧ καθάπερ ἀμβλεῖ ξιφιδίῳ μόλις ἀναιρῶν τὸν ἄνθρωπον ἀνῄρηκεν.", "st": "Art. 11.1"}, {"sp": "N", "t": "ἤδη δὲ αὐτοῦ τεθνηκότος Ἀρτασύρας ὁ βασιλέως ὀφθαλμὸς ἔτυχεν ἵππῳ παρεξελαύνων. γνωρίσας οὖν τοὺς εὐνούχους ὀλοφυρομένους ἠρώτησε τὸν πιστότατον αὐτῶν, τίνα τοῦτον, ὦ Παρίσκα, κλαίεις παρακαθήμενος; ὁ δὲ εἶπεν οὐχ ὁρᾷς, ὦ Ἀρτασύρα, Κῦρον τεθνηκότα; θαυμάσας οὖν ὁ Ἀρτασύρας τῷ μὲν εὐνούχῳ θαρρεῖν παρεκελεύσατο καὶ φυλάττειν τὸν νεκρόν, αὐτὸς δὲ συντείνας πρὸς τὸν Ἀρτοξέρξην, ἀπεγνωκότα μὲν ἤδη τὰ πράγματα, κακῶς δὲ καὶ τὸ σῶμα διακείμενον ὑπό τε δίψης καὶ τοῦ τραύματος, χαίρων φράζει ὡς αὐτὸς ἴδοι τεθνηκότα Κῦρον. ὁ δὲ πρῶτον μὲν εὐθὺς ὥρμησεν αὐτὸς ἰέναι, καὶ τὸν Ἀρτασύραν ἄγειν ἐκέλευσεν ἐπὶ τὸν τόπον· ἐπεὶ δὲ πολὺς ἦν λόγος τῶν Ἑλλήνων καὶ φόβος ὡς διωκόντων καὶ πάντα νικώντων καὶ κρατούντων, ἔδοξε πλείονας πέμψαι τοὺς κατοψομένους· καὶ τριάκοντα λαμπάδας ἔχοντες ἐπέμφθησαν. αὐτῷ δὲ μικρὸν ἀπολείποντι τοῦ τεθνάναι διὰ τὸ διψῆν Σατιβαρζάνης ὁ εὐνοῦχος περιθέων ἐζήτει ποτόν οὐ γὰρ εἶχε τὸ χωρίον ὕδωρ, οὐδὲ ἦν ἐγγὺς τὸ στρατόπεδον· μόλις οὖν ἐπιτυγχάνει τῶν Καυνίων ἐκείνων τῶν κακοβίων ἑνὸς ἐν ἀσκίῳ φαύλῳ διεφθαρμένον ὕδωρ καὶ πονηρὸν ἔχοντος, ὅσον ὀκτὼ κοτύλας καὶ λαβὼν τοῦτο καὶ κομίσας τῷ βασιλεῖ δίδωσιν. ἐκπιόντα δὲ ἅπαν ἠρώτησεν εἰ μὴ πάνυ δυσχεραίνει τὸ ποτόν. ὁ δὲ ὤμοσε τοὺς θεοὺς μήτε οἶνον ἡδέως οὕτως πώποτε πεπωκέναι μήτε ὕδωρ τὸ κουφότατον καὶ καθαρώτατον, ὥστε, ἔφη, τὸν δόντα σοι τοῦτο ἄνθρωπον, ἂν ἐγὼ μὴ δυνηθῶ ζητήσας ἀμείψασθαι, τοὺς θεοὺς εὔχομαι ποιῆσαι μακάριον καὶ πλούσιον.", "st": "Art. 12.1"}, {"sp": "N", "t": "ἐν δὲ τούτῳ προσήλαυνον οἱ τριάκοντα λαμπροὶ καί περιχαρεῖς, ἀναγγέλλοντες αὐτῷ τὴν ἀνέλπιστον εὐτυχίαν. ἤδη δὲ καί πλήθει τῶν συντρεχόντων πάλιν πρὸς αὐτὸν καί συνισταμένων ἐθάρρει, καί κατέβαινεν ἀπὸ τοῦ λόφου φωτὶ πολλῷ περιλαμπόμενος. ὡς δὲ ἐπέστη τῷ νεκρῷ, καὶ κατὰ δή τινα νόμον Περσῶν ἡ δεξιὰ χεὶρ ἀπεκόπη καί ἡ κεφαλὴ τοῦ σώματος, ἐκέλευσε τὴν κεφαλὴν αὑτῷ κομισθῆναι καί τῆς κόμης δραξάμενος οὔσης βαθείας καί λασίας ἐπεδείκνυε τοῖς ἀμφιδοξοῦσιν ἔτι καί φεύγουσιν. οἱ δὲ ἐθαύμαζον καί προσεκύνουν, ὥστε ταχὺ μυριάδας ἑπτὰ περὶ αὐτὸν γενέσθαι καί συνεισελάσαι πάλιν εἰς τὸ στρατόπεδον. ἐξεληλάκει δέ, ὡς ὁ Κτησίας φησίν, ἐπὶ τὴν μάχην τεσσαράκοντα μυριάσιν· οἱ δὲ περὶ Δείνωνα καὶ Ξενοφῶντα πολὺ πλείονας γενέσθαι λέγουσι τὰς μεμαχημένας. ἀριθμὸν δὲ νεκρῶν ὁ Κτησίας ἐνακισχιλίους ἀνενεχθῆναί φησι πρὸς τὸν Ἀρτοξέρξην, αὐτῷ δὲ δισμυρίων οὐκ ἐλάττους φανῆναι τοὺς κειμένους, ταῦτα μὲν οὖν ἔχει διαμφισβήτησιν· ἐκεῖνο δὲ τοῦ Κτησίου λαμπρὸν ἤδη ψεῦσμα, τὸ πεμφθῆναι φάναι πρὸς τοὺς Ἕλληνας αὐτὸν μετὰ Φαλίνου τοῦ Ζακυνθίου καί τινων ἄλλων. ὁ γὰρ Ξενοφῶν ἠπίστατο συνδιατρίβοντα βασιλεῖ Κτησίαν· μέμνηται γὰρ ι αὐτοῦ καί τοῖς βιβλίοις τούτοις ἐντετυχηκὼς δῆλός ἐστιν οὐκ ἂν οὖν ἐλθόντα καί λόγων τοσούτων ἑρμηνέα γενόμενον παρῆκεν ἀνώνυμον, Φαλῖνον δὲ τὸν Ζακύνθιον ὠνόμαζεν. ἀλλὰ δαιμονίως ὁ Κτησίας, ὡς ἔοικε, φιλότιμος ὢν καί οὐχ ἧττον φιλολάκων καί φιλοκλέαρχος ἀεί τινας ἐν τῇ διηγήσει χώρας ἑαυτῷ δίδωσιν, ἐν αἷς γενόμενος πολλὰ καί καλὰ μεμνήσεται Κλεάρχου καί τῆς Λακεδαίμονος.", "st": "Art. 13.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν μάχην δῶρα κάλλιστα μὲν ἐξέπεμψε καὶ μέγιστα τῷ Ἀρταγέρσου παιδὶ τοῦ πεσόντος ὑπὸ Κύρου, καλῶς δὲ καὶ Κτησίαν καὶ τοὺς ἄλλους ἐτίμησε. τὸν δὲ Καύνιον ἐκεῖνον ἐξ ἐξανευρών, ὃς ἐπέδωκε τὸ ἀσκίον, ἐξ ἀδόξου καὶ πένητος ἔντιμον καὶ πλούσιον ἐποίησεν· ἦν δέ τις ἐπιμέλεια καὶ περὶ τὰς τῶν ἐξαμαρτόντων δικαιώσεις. Ἀρβάκην μὲν γάρ τινα Μῆδον ἐν τῇ μάχῃ πρὸς Κῦρον φυγόντα καὶ πάλιν ἐκείνου πεσόντος μεταστάντα, δειλίαν καὶ μαλακίαν καταγνούς, οὐ προδοσίαν οὐδὲ κακόνοιαν, ἐκέλευσε γυμνὴν ἀναλαβόντα πόρνην περιβάδην ἐπὶ τοῦ τραχήλου δι’ ἡμέρας ὅλης ἐν ἀγορᾷ περιφέρειν· ἑτέρου δὲ πρὸς τῷ μεταστῆναι ψευσαμένου καταβαλεῖν δύο τῶν πολεμίων, προσέταξε διαπεῖραι τρισὶ βελόναις τὴν γλῶτταν. οἰόμενος δὲ καὶ βουλόμενος δοκεῖν καὶ λέγειν πάντας ἀνθρώπους ὡς αὐτὸς ἀπεκτόνοι Κῦρον, Μιθριδάτῃ τε τῷ βαλόντι πρώτῳ Κῦρον ἐξέπεμψε δῶρα καὶ λέγειν ἐκέλευσε τοὺς διδόντας ὡς τούτοις σε τιμᾷ ὁ βασιλεύς ὅτι τὸν ἐφίππειον Κύρου πῖλον εὑρὼν ἀνήνεγκας· τοῦ δὲ Καρός, ὑφ’ οὗ τὴν ἰγνύαν πληγεὶς ὁ Κῦρος ἔπεσε, καὶ αὐτοῦ δωρεὰν αἰτοῦντος, ἐκέλευσεν εἰπεῖν τοὺς διδόντας ὅτι σοὶ ταῦτα δίδωσιν βασιλεύς εὐαγγελίων δευτερεῖα πρῶτος γὰρ Ἀρτασύρας, μετ’ ἐκεῖνον δὲ σύ τὴν Κύρου τελευτὴν ἀπήγγειλας. ὁ μὲν οὖν Μιθριδάτης ἀπῆλθε σιωπῇ λυπούμενος τὸν δὲ ἄθλιον Κᾶρα κοινόν τι πάθος ἐξ ἀβελτερίας κατέσχε. διαφθαρεὶς γὰρ ὑπὸ τῶν παρόντων, ὡς ἔοικεν, ἀγαθῶν, καὶ ἀναπεισθεὶς εὐθὺς ἀντιποιεῖσθαι τῶν ὑπὲρ αὐτόν, οὐκ ἠξίου τὰ δοθέντα μισθὸν εὐαγγελίων ἔχειν, ἀλλ’ ἠγανάκτει μαρτυρόμενος καὶ βοῶν ὅτι Κῦρον οὐδεὶς ἕτερος, ἀλλ’ αὐτὸς ἀπεκτόνοι, καὶ τὴν δόξαν ἀδίκως ἀποστεροῖτο, ταῦτα δὲ ἀκούσας ὁ βασιλεύς σφόδρα παρωξύνθη καὶ τὴν κεφαλὴν ἐκέλευσεν ἀποτεμεῖν τοῦ ἀνθρώπου. παροῦσα δ’ ἡ μήτηρ, μὴ σύ γε, εἶπεν, οὕτω τὸν Κᾶρα τοῦτον, ὦ βασιλεῦ, τὸν ὄλεθρον ἀπαλλάξῃς, ἀλλὰ παρ’ ἐμοῦ τὸν ἄξιον ἀπολήψεται μισθὸν ὧν τολμᾷ λέγειν ἐπιτρέψαντος δὲ τοῦ βασιλέως ἐκέλευσε τοὺς ἐπὶ τῶν τιμωριῶν ἡ Παρύσατις λαβόντας τὸν ἄνθρωπον ἐφ’ ἡμέρας δέκα στρεβλοῦν, εἶτα τοὺς ὀφθαλμοὺς ἐξορύξαντας εἰς τὰ ὦτα θερμὸν ἐντήκειν χαλκὸν ἕως ἀποθάνῃ.", "st": "Art. 14.1"}, {"sp": "N", "t": "κακῶς δὲ ἀπώλετο καὶ Μιθριδάτης μετ’ ὀλίγον χρόνον ἐκ τῆς αὐτῆς ἀβελτερίας. κληθεὶς γὰρ ἐπὶ δεῖπνον ἔνθα καὶ βασιλέως καὶ τῆς μητρὸς εὐνοῦχοι παρῆσαν, ἧκεν ἐσθῆτι καὶ χρυσῷ κεκοσμημένος οἷς ἔλαβε παρὰ βασιλέως. ἐπεὶ δὲ εἰς τὸ πίνειν ἀφίκοντο, λέγει πρὸς αὐτὸν ὁ μέγιστον δυνάμενος τῶν Παρυσάτιδος εὐνούχων ὡς καλὴν μὲν ἐσθῆτά σοι ταύτην, ὦ Μιθριδάτα, ὁ βασιλεὺς δέδωκε, καλὰ δὲ στρεπτὰ καὶ ψέλια· πολλοῦ δὲ ἄξιος ὁ ἀκινάκης. ἦ μακάριόν σε καὶ περίβλεπτον ἅπασι πεποίηκεν. ἤδη δὲ μεθύων ὁ Μιθριδάτης, τί δὲ ταῦτα ἔστιν, εἶπεν, ὦ Σπαραμίζη; μειζόνων γὰρ ἐγὼ καὶ καλλιόνων βασιλεῖ τὴν ἡμέραν ἐκείνην ἄξιον ἐμαυτὸν παρέσχον. καὶ ὁ Σπαραμίζης ἐπιμειδιάσας, φθόνος μὲν οὐδεὶς, ὦ Μιθριδάτα, εἶπεν ἐπεὶ δέ φασιν Ἕλληνες οἶνον καὶ ἀλήθειαν εἶναι, τί λαμπρὸν, ὦ τᾶν, ἢ μέγα, πῖλον εὑρεῖν ἵππου περιρρυέντα καὶ τοῦτον ἀνενεγκεῖν; ταῦτα δὲ οὐκ ἀγνοῶν τὸ ἀληθὲς ἔλεγεν, ἀλλὰ βουλόμενος ἐκκαλύψαι πρὸς τοὺς παρόντας ὑπεκίνει τὴν κουφότητα τοῦ ἀνθρώπου λάλου καὶ ἀκρατοῦς γεγονότος διὰ τὸν οἶνον. εἶπεν οὖν μὴ κατασχών ὑμεῖς μὲν, ὅ τι βούλεσθε, πίλους λέγετε καὶ φλυάρους· ἐγὼ δὲ ὑμῖν λέγω διαρρήδην ὑπὸ ταύτης ἀνῃρῆσθαι Κῦρον τῆς χειρός, οὐ γὰρ ὡς Ἀρταγέρσης ἠκόντισα κενὸν καὶ μάταιον, ἀλλὰ τοῦ μὲν ὀφθαλμοῦ μικρὸν ἥμαρτον, τὸν δὲ κροτάφου τυχὼν καὶ διελάσας κατέβαλον τὸν ἄνδρα καὶ τέθνηκεν ὑπ’ ἐκείνου τοῦ τραύματος· οἱ μὲν οὖν ἄλλοι τὸ τέλος ἤδη τοῦ Μιθριδάτου καὶ τὴν κακοδαιμονίαν ὁρῶντες εἰς τὴν γῆν ἔκυψαν ὁ δ’ ἑστιῶν αὐτούς, ὦ τᾶν, ἔφη, Μιθριδάτα, πίνωμεν ἐν τῷ παρόντι καὶ ἐσθίωμεν τὸν βασιλέως δαίμονα προσκυνοῦντες, λόγους δὲ μείζους ἢ καθ’ ἡμᾶς ἐάσωμεν.", "st": "Art. 15.1"}, {"sp": "N", "t": "ἐκ τούτου τῇ μὲν Παρυσάτιδι φράζει τὸν λόγον ὁ εὐνοῦχος, ἐκείνη δὲ βασιλεῖ βασιλεὺς δὲ ἠγανάκτησεν ὥσπερ ἐξελεγχόμενος καὶ τὸ κάλλιστον καὶ ἥδιστον ἀπολλύων τῆς νίκης, ἐβούλετο γὰρ βαρβάρους ἅπαντας πεπεῖσθαι καὶ Ἕλληνας ὡς ἐν ταῖς ἐξελάσεσι καὶ συμπλοκαῖς δοὺς καὶ λαβὼν πληγήν ἐτρώθη μὲν αὐτός, ἔκτεινε δὲ ἐκεῖνον, ἐκέλευσεν οὖν τὸν Μιθριδάτην ἀποθανεῖν σκαφευθέντα.", "st": "Art. 16.1"}, {"sp": "N", "t": "τὸ δὲ σκαφευθῆναι τοιοῦτόν ἐστι· σκάφας δύο πεποιημένας ἐφαρμόζειν ἀλλήλαις λαβόντες, εἰς τὴν ἑτέραν κατακλίνουσι τὸν κολαζόμενον ὕπτιον· εἶτα τὴν ἑτέραν ἐπάγοντες καὶ συναρμόζοντες, ὥστε τὴν κεφαλὴν καὶ τὰς χεῖρας ἔξω καὶ τοὺς πόδας ἀπολαμβάνεσθαι, τὸ δὲ ἄλλο σῶμα πᾶν ἀποκεκρύφθαι, διδόασιν ἐσθίειν τῷ ἀνθρώπῳ, κἂν μὴ θέλῃ, προσβιάζονται κεντοῦντες τὰ ὄμματα· φαγόντι δὲ πιεῖν μέλι καὶ γάλα συγκεκραμένον ἐγχέουσιν εἰς τὸ στόμα καὶ κατὰ τοῦ προσώπου καταχέουσιν. εἶτα πρὸς τὸν ἥλιον ἀεὶ στρέφουσιν ἐναντία τὰ ὄμματα, καὶ μυιῶν προσκαθημένων πλῆθος πᾶν ἀποκρύπτεται τὸ πρόσωπον, ἐντὸς δὲ ποιοῦντος ὅσα ποιεῖν ἀναγκαῖόν ἐστιν ἐσθίοντας ἀνθρώπους καὶ πίνοντας, εὐλαὶ καὶ σκώληκες ὑπὸ φθορᾶς καὶ σηπεδόνος ἐκ τοῦ περιττώματος ἀναζέουσιν, ὑφ’ ὧν ἀναλίσκεται τὸ σῶμα διαδυομένων εἰς τὰ ἐντός. ὅταν γὰρ ἤδη φανερὸς ᾖ τεθνηκὼς ὁ ἄνθρωπος, ἀφαιρεθείσης τῆς ἐπάνω σκάφης ὁρῶσι τὴν μὲν σάρκα κατεδηδεσμένην, περὶ δὲ τὰ σπλάγχνα τοιούτων θηρίων ἑσμοὺς ἐσθιόντων καὶ προσπεφυκότων. οὕτως ὁ Μιθριδάτης ἑπτακαίδεκα ἡμέρας φθειρόμενος μόλις ἀπέθανε.", "st": "Art. 16.2"}, {"sp": "N", "t": "λοιπὸς δ’ ἦν τῇ Παρυσάτιδι σκοπὸς ὁ τὴν κεφαλὴν ἀποτεμὼν καὶ τὴν χεῖρα τοῦ Κύρου Μασαβάτης, βασιλέως εὐνοῦχος, ὡς οὖν αὐτὸς οὐδεμίαν καθ’ ἑαυτοῦ λαβὴν παρεδίδου, τοιοῦτον ἐπιβουλῆς τρόπον ἡ Παρύσατις συνέθηκεν. ἦν τά τε ἀλλὰ θυμόσοφος γυνὴ καὶ δεινὴ κυβεύειν διὸ καὶ βασιλεῖ πρὸ τοῦ πολέμου πολλάκις συνεκύβευε μετὰ δὲ τὸν πόλεμον διαλυθεῖσα πρὸς αὐτόν οὐκ ἔφευγε τὰς φιλοφροσύνας, ἀλλὰ καὶ συνέπαιζε καὶ τῶν ἐρωτικῶν ἐκοινώνει συμπράττουσα καὶ παροῦσα, καὶ ὅλως μικρότατον αὐτοῦ τῇ Στατείρᾳ μετεδίδου χρῆσθαι καὶ συνεῖναι, μισοῦσά τε μάλιστα πάντων ἐκείνην καὶ μέγιστον αὐτὴ βουλομένη δύνασθαι. λαβοῦσα δή ποτε τὸν Ἀρτοξέρξην ὡρμημένον ἀλύειν σχολῆς οὔσης προὐκαλεῖτο περὶ χιλίων δαρεικῶν κυβεῦσαι· καὶ κυβεύοντα περιεῖδε νικῆσαι καὶ τὸ χρυσίον ἀπέδωκε, προσποιουμένη δὲ ἀνιᾶσθαι καὶ φιλονεικεῖν ἐκέλευσεν αὖθις ἐξ ἀρχῆς περὶ εὐνούχου διακυβεῦσαι· κἀκεῖνος ὑπήκουσε. ποιησάμενοι δὲ συνθήκας πέντε μὲν ἑκάτερον ὑπεξελέσθαι τοὺς πιστοτάτους, ἐκ δὲ τῶν λοιπῶν ὃν ἂν ὁ νικῶν ἕληται, δοῦναι τὸν ἡττώμενον, ἐπὶ τούτοις ἐκύβευον. σφόδρα δὴ γενομένη πρὸς τῷ πράγματι καὶ σπουδάσασα περὶ τὴν παιδιάν, εὖ δέ πως αὐτῇ καὶ τῶν κύβων πεσόντων, νικήσασα λαμβάνει τὸν Μασαβάτην οὐ γὰρ ἦν ἐν τοῖς ὑπεξῃρημένοις. καὶ πρὶν ἐν ὑποψίᾳ, γενέσθαι βασιλέα τοῦ πράγματος ἐγχειρίσασα τοῖς ἐπὶ τῶν τιμωριῶν προσέταξεν ἐκδεῖραι ζῶντα, καὶ τὸ μὲν σῶμα πλάγιον διὰ τριῶν σταυρῶν ἀναπῆξαι, τὸ δὲ δέρμα χωρὶς διαπατταλεῦσαι. γενομένων δὲ τούτων καὶ βασιλέως χαλεπῶς φέροντος καὶ παροξυνομένου πρὸς αὐτήν, εἰρωνευομένη μετὰ γέλωτος, ὡς ἡδύς, ἔφασκεν, εἶ καὶ μακάριος, εἰ χαλεπαίνεις διὰ γέροντα πονηρὸν εὐνοῦχον, ἐγὼ δὲ χιλίους ἐκκυβευθεῖσα δαρεικοὺς σιωπῶ καὶ στέργω. βασιλεὺς μὲν οὖν ἐφ’ οἷς ἐξηπατήθη μεταμελόμενος ἡσυχίαν ἦγεν, ἡ δὲ Στάτειρα καὶ πρὸς τἆλλα φανερῶς ἠναντιοῦτο καὶ τούτοις ἐδυσχέραινεν, ὡς ἄνδρας εὐνούχους καὶ πιστοὺς βασιλεῖ διὰ Κῦρον ὠμῶς καὶ παρανόμως ἀπολλυούσης αὐτῆς.", "st": "Art. 17.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Κλέαρχον καὶ τοὺς ἄλλους στρατηγοὺς Τισαφέρνης ἐξηπάτησε καὶ παρεσπόνδησεν ὅρκων γενομένων καὶ συλλαβὼν ἀνέπεμψεν ἐν πέδαις δεδεμένους, δεηθῆναί φησιν αὐτοῦ τὸν Κλέαρχον ὁ Κτησίας ὅπως κτενὸς εὐπορήσειε. τυχόντα δὲ καὶ τημελήσαντα τὴν κεφαλήν ἡσθῆναί τε τῇ χρείᾳ καὶ τὸν δακτύλιον αὐτῷ δοῦναι, σύμβολον φιλίας πρὸς τοὺς ἐν Λακεδαίμονι συγγενεῖς καὶ οἰκείους· εἶναι δὲ γλυφὴν ἐν τῇ σφραγῖδι Καρυάτιδας ὀρχουμένας. τὰ δὲ πεμπόμενα σιτία τῷ Κλεάρχῳ τοὺς συνδεδεμένους στρατιώτας ἀφαιρεῖσθαι καὶ καταναλίσκειν, ὀλίγα τῷ Κλεάρχῳ διδόντας ἀπ’ αὐτῶν, ἰάσασθαι δὲ καὶ τοῦτό φησιν ὁ Κτησίας, πλείονα τῷ Κλεάρχῳ πέμπεσθαι διαπραξάμενος, ἰδίᾳ, δὲ ἕτερα τοῖς στρατιώταις δίδοσθαι· καὶ ταῦτα μὲν ὑπουργῆσαι καὶ παρασχεῖν χάριτι καὶ γνώμῃ τῆς Παρυσάτιδος. πεμπομένου δὲ καθ’ ἡμέραν τῷ Κλεάρχῳ κωλῆνος ἐπὶ τοῖς σιτίοις, παρακαλεῖν αὐτὸν καὶ διδάσκειν ὡς χρὴ μικρὸν εἰς τὸ κρέας ἐμβαλόντα μαχαίριον ἀποκρύψαντα πέμψαι καὶ μὴ περιιδεῖν ἐν τῇ βασιλέως ὠμότητι τὸ τέλος αὐτοῦ γενόμενον· αὐτὸς δὲ φοβούμενος μὴ ἐθελῆσαι, βασιλέα δὲ τῇ μὲν μητρὶ παραιτουμένῃ μὴ κτεῖναι τὸν Κλέαρχον ὁμολογῆσαι καὶ ὀμόσαι· πεισθέντα δὲ αὖθις ὑπὸ τῆς Στατείρας ἀποκτεῖναι πάντας πλὴν Μένωνος. ἐκ δὲ τούτου τὴν Παρύσατιν ἐπιβουλεῦσαι τῇ Στατείρᾳ καὶ συσκευάσασθαι τὴν φαρμακείαν κατ’ αὐτῆς, οὐκ εἰκότα λέγων, ἀλλὰ πολλὴν ἀλογίαν ἔχοντα τῆς αἰτίας, εἰ δεινὸν ἔργον οὕτως ἔδρασε καὶ παρεκινδύνευσεν ἡ Παρύσατις διὰ Κλέαρχον, ἀνελεῖν τολμήσασα τὴν γνησίαν βασιλέως γυναῖκα καὶ τέκνων κοινωνὸν ἐπὶ βασιλείᾳ τρεφομένων. ἀλλὰ ταῦτα μὲν οὐκ ἄδηλον ὡς ἐπιτραγῳδεῖται τῇ Κλεάρχου μνήμῃ, καὶ γὰρ ἀναιρεθέντων φησὶ τῶν στρατηγῶν τοὺς μὲν ἄλλους ὑπὸ κυνῶν σπαράττεσθαι καὶ ὀρνέων, τῷ δὲ Κλεάρχου νεκρῷ θύελλαν ἀνέμου γῆς θῖνα πολλὴν φέρουσαν ἐπιχῶσαι καὶ ἐπικρύψαι τὸ σῶμα· φοινίκων δέ τινων διασπαρέντων ὀλίγῳ χρόνῳ θαυμαστὸν ἄλσος ἀναφῦναι καὶ κατασκιάσαι τὸν τόπον, ὥστε καὶ βασιλεῖ σφόδρα μεταμέλειν, ὡς ἄνδρα θεοῖς φίλον ἀνῃρηκότι τὸν Κλέαρχον.", "st": "Art. 18.1"}, {"sp": "N", "t": "ἡ δ’ οὖν Παρύσατις, μίσους τε πρὸς τὴν Στάτειραν ἐξ ἀρχῆς ὑποκειμένου καὶ ζηλοτυπίας, ὁρῶσα τὴν μὲν αὑτῆς δύναμιν αἰδουμένου βασιλέως καὶ τιμῶντος οὖσαν, τὴν δ’ ἐκείνης ἔρωτι καὶ πίστει βέβαιον καὶ ἰσχυράν, ἐπεβούλευσεν ὑπὲρ τῶν μεγίστων, ὡς ᾤετο, παραβαλλομένη. θεράπαιναν εἶχε πιστὴν καὶ δυναμένην παρ’ αὐτή μέγιστον ὄνομα Γίγιν, ἣν ὁ μὲν Δείνων ὑπουργῆσαι τῇ φαρμακείᾳ φησί, συγγνῶναι δὲ μόνον ἄκουσαν ὁ Κτησίας. τὸν δὲ δόντα τὸ φάρμακον οὗτος μὲν ὀνομάζει Βελιτάραν, ὁ δὲ Δείνων Μελάνταν. ἐκ δὲ τῆς πρόσθεν ὑποψίας καὶ διαφορᾶς ἀρξάμεναι πάλιν εἰς τὸ αὐτὸ φοιτᾶν καὶ συνδειπνεῖν ἀλλήλαις, ὅμως τῷ δεδιέναι καὶ φυλάττεσθαι τοῖς αὐτοῖς σιτίοις καὶ ἀπὸ τῶν αὐτῶν ἐχρῶντο. γίνεται δὲ μικρὸν ἐν Πέρσαις ὀρνίθιον, ᾧ περιττώματος οὐδέν ἐστιν, ἀλλ’ ὅλον διάπλεων πιμελῆς τὰ ἐντός· καὶ νομίζουσιν ἀνέμῳ καὶ δρόσῳ τρέφεσθαι τὸ ζῷον ὀνομάζεται δὲ ῥυντάκης. τοῦτό φησιν ὁ Κτησίας μικρᾷ μαχαιρίδι κεχρισμένῃ τῷ φαρμάκῳ κατὰ θάτερα τὴν Παρύσατιν διαιροῦσαν ἐκμάξαι τῷ ἑτέρῳ μέρει τὸ φάρμακον· καὶ τὸ μὲν ἄχραντον καὶ καθαρὸν εἰς τὸ στόμα βαλοῦσαν αὐτὴν ἐσθίειν, δοῦναι δὲ τῇ Στατείρᾳ πεφαρμαγμένον· ὁ δὲ Δείνων οὐ τὴν Παρύσατιν, ἀλλὰ τὸν Μελάνταν τέμνοντα τῷ μαχαιρίῳ τὰ φαρμασσόμενα τῶν κρεῶν τιθέναι κατὰ τὴν Στάτειραν. ἀποθνῄσκουσα δ’ οὖν ἡ γυνὴ μετὰ πόνων μεγάλων καὶ σπαραγμῶν αὐτή τε συνῃσθάνετο τοῦ κακοῦ καὶ βασιλεῖ παρέσχεν ὑποψίαν κατὰ τῆς μητρός, εἰδότι τὸ θηριῶδες αὑτῆς καὶ δυσμείλικτον. ὅθεν εὐθὺς ἐπὶ τὴν ζήτησιν ὁρμήσας τοὺς μὲν ὑπηρέτας καὶ τραπεζοκόμους τῆς μητρὸς συνέλαβε καὶ κατεστρέβλωσε, τὴν δὲ Γίγιν ἡ Παρύσατις πολὺν χρόνον εἶχεν οἴκοι μεθ’ αὑτῆς καὶ βασιλέως ἐξαιτοῦντος οὐκ ἔδωκεν, ἀλλ’ ὕστερον αὑτῆς δεηθείσης εἰς τὸν οἶκον ἀφεθῆναι νυκτός, αἰσθόμενος καὶ λόχον ὑφεὶς συνήρπασε καὶ κατέγνω θάνατον. ἀποθνῄσκουσι δὲ οἱ φαρμακεῖς ἐν Πέρσαις κατὰ νόμον οὕτως· λίθος ἐστὶ πλατύς, ἐφ’ οὗ τὴν κεφαλὴν καταθέντες αὐτῶν ἑτέρῳ λίθῳ παίουσι καὶ πιέζουσιν, ἄχρι οὗ συνθλάσωσι τὸ πρόσωπον καὶ τὴν κεφαλήν, ἡ μὲν οὖν Γίγις οὕτως ἀπέθανε, τὴν δὲ Παρύσατιν ὁ Ἀρτοξέρξης ἄλλο μὲν οὐδὲν οὔτε εἶπε κακὸν οὔτε ἐποίησεν, εἰς δὲ Βαβυλῶνα βουλομένην ἐξέπεμψεν εἰπὼν, ἕως ἐκείνη περίεστιν αὐτὸς οὐκ ὄψεσθαι Βαβυλῶνα, τὰ μὲν κατὰ τὴν οἰκίαν οὕτως εἶχεν.", "st": "Art. 19.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τοὺς Κύρῳ συναναβάντας Ἕλληνας σπουδάσας λαβεῖν ὁ βασιλεὺς οὐδὲν ἧττον ἢ Κύρου περιγενέσθαι καί τὴν βασιλείαν· κατασχεῖν οὐκ ἔλαβεν, ἀλλὰ Κῦρον τὸν ἡγεμόνα καί τοὺς αὑτῶν στρατηγοὺς ἀποβαλόντες ἐξ αὑτῶν μονονουχὶ τῶν βασιλείων ἐσώθησαν, ἐξελέγξαντες καί ἀποφήναντες τὰ Περσῶν καί βασιλέως πράγματα χρυσὸν ὄντα πολὺν καί τρυφὴν καί γυναῖκας, τὰ δὲ ἄλλα τῦφον καί ἀλαζονείαν, πᾶσα μὲν ἡ Ἑλλὰς ἐξεθάρρησε καί κατεφρόνησε τῶν βαρβάρων, Λακεδαιμονίοις δὲ καί δεινὸν ἐφαίνετο μὴ νῦν γε δουλείας ἐξελέσθαι τοὺς τὴν Ἀσίαν κατοικοῦντας Ἕλληνας μηδὲ παῦσαι προπηλακιζομένους ὑπ’ αὑτῶν, πρότερον δὲ διὰ Θίμβρωνος, εἶτα διὰ Δερκυλλίδου πολεμοῦντες, οὐδὲν δὲ πράττοντες ἀξιόλογον, Ἀγησιλάῳ τῷ βασιλεῖ τὸν πόλεμον ἐπέτρεψαν. ὁ δὲ περαιωθεὶς ναυσὶν εἰς Ἀσίαν εὐθὺς ἦν ἐνεργὸς καί δόξαν εἶχε μεγάλην καί Τισσαφέρνην παραταξάμενος ἐνίκησε καί τὰς πόλεις ἀφίστη. τούτων δὲ γενομένων συμφρονήσας ὁ Ἀρτοξέρξης ὃν τρόπον αὐτοῖς ἐστι πολεμητέον, ἔπεμψε Τιμοκράτην τὸν Ῥόδιον εἰς τὴν Ἑλλάδα χρυσίον πολὺ κομίζοντα, διδόναι καί διαφθείρειν τοὺς πλεῖστον ἐν ταῖς πόλεσι δυναμένους κελεύσας, καί πόλεμον Ἑλληνικὸν κινεῖν ἐπὶ τὴν Λακεδαίμονα. τοῦ δὲ Τιμοκράτους ταῦτα πράττοντος καί τῶν μεγίστων πόλεων συνισταμένων καί τῆς Πελοποννήσου διαταραττομένης, μετεπέμποντο τὸν Ἀγησίλαον ἐκ τῆς Ἀσίας οἱ ἄρχοντες, ὅτε δὴ καί φασιν αὐτὸν ἀπιόντα πρὸς τοὺς φίλους εἰπεῖν ὡς τρισμυρίοις τοξόταις ἐξελαύνοιτο τῆς Ἀσίας ὑπὸ βασιλέως· τὸ γὰρ Περσικὸν νόμισμα τοξότην ἐπίσημον εἶχεν.", "st": "Art. 20.1"}, {"sp": "N", "t": "ἐξέβαλε δὲ καὶ τῆς θαλάττης Λακεδαιμονίους Κόνωνι τῷ Ἀθηναίῳ μετὰ Φαρναβάζου στρατηγῷ χρησάμενος. ὁ γὰρ Κόνων διέτριβε μὲν ἐν Κύπρῳ μετὰ τὴν ἐν Αἰγὸς ποταμοῖς ναυμαχίαν, οὐ τὴν ἀσφάλειαν ἀγαπῶν, ἀλλὰ τὴν τῶν πραγμάτων μεταβολὴν, ὥσπερ ἐν πελάγει τροπὴν, περιμένων. ὁρῶν δὲ καὶ τοὺς ἑαυτοῦ λογισμοὺς δυνάμεως καὶ τὴν βασιλέως δύναμιν ἀνδρὸς ἔμφρονος δεομένην, ἔπεμψεν ἐπιστολὴν βασιλεῖ περὶ ὧν διενοεῖτο. καὶ ταύτην ἐκέλευσε τὸν κομίζοντα μάλιστα μὲν ἀποδοῦναι διὰ Ζήνωνος τοῦ Κρητὸς ἢ Πολυκρίτου τοῦ Μενδαίου τούτων δ’ ἦν ὁ μὲν Ζήνων ὀρχηστής, ὁ δὲ Πολύκριτος ἰατρός· ἂν δὲ οὗτοι μὴ παρῶσι, διὰ Κτησίου τοῦ ἰατροῦ. λέγεται δὲ ὁ Κτησίας τὴν ἐπιστολὴν λαβὼν παρεγγράψαι τοῖς ὑπὸ τοῦ Κόνωνος ἐπεσταλμένοις ὅπως καὶ Κτησίαν ἀποστείλῃ πρὸς αὑτόν, ὡς ὠφέλιμον ὄντα ταῖς ἐπὶ θαλάσσῃ πράξεσιν. ὁ δὲ Κτησίας αὐτὸν ἀφ’ ἑαυτοῦ βασιλέα φησὶ προσθεῖναι τὴν λειτουργίαν αὐτῷ ταύτην.", "st": "Art. 21.1"}, {"sp": "N", "t": "ἀλλ’ ἐπεὶ κρατήσας τῇ περὶ Κνίδον ναυμαχίᾳ διὰ Φαρναβάζου καὶ Κόνωνος ἀφείλετο τὴν κατὰ θάλατταν ἀρχὴν Λακεδαιμονίους, ἐπέστρεψε πᾶσαν ὁμοῦ τὴν Ἑλλάδα πρὸς αὑτόν, ὥστε καὶ τὴν περιβόητον εἰρήνην βραβεῦσαι τοῖς Ἕλλησι τὴν ἐπ’ Ἀνταλκίδου προσαγορευομένην. ὁ δὲ Ἀνταλκίδας Σπαρτιάτης ἦν, Λέοντος υἱός, καὶ σπουδάσας βασιλεῖ διεπράξατο τὰς ἐν Ἀσίᾳ, πόλεις Ἑλληνίδας ἁπάσας καὶ νήσους, ὅσαι προσκυροῦσιν Ἀσίᾳ, παρεῖναι Λακεδαιμονίους αὐτῷ κεκτῆσθαι φόρων ὑποτελεῖς, εἰρήνης γενομένης τοῖς Ἕλλησιν, εἰ δεῖ τὴν τῆς Ἑλλάδος ὕβριν καὶ προδοσίαν εἰρήνην καλεῖν, ἧς πόλεμος οὐδεὶς ἀκλεέστερον ἤνεγκε τέλος τοῖς κρατηθεῖσι.", "st": "Art. 21.4"}, {"sp": "N", "t": "διὸ καὶ τοὺς ἄλλους Σπαρτιάτας ἀεὶ βδελυττόμενος ὁ Ἀρτοξέρξης, καὶ νομίζων, ὥς φησι Δείνων, ἀνθρώπων ἁπάντων ἀναιδεστάτους εἶναι, τὸν Ἀνταλκίδαν ὑπερηγάπησεν εἰς Πέρσας ἀναβάντα. καί ποτε λαβὼν ἕνα τῶν ἀνθινῶν στεφάνων καὶ βάψας εἰς μύρον τὸ πολυτελέστατον, ἀπὸ δείπνου ἔπεμψε τῷ Ἀνταλκίδᾳ καὶ πάντες ἐθαύμασαν τὴν φιλοφροσύνην. ἦν δέ, ὡς ἔοικεν, ἐπιτήδειος οὗτος ἐντρυφηθῆναι καὶ τοιοῦτον λαβεῖν στέφανον, ἐξορχησάμενος ἐν Πέρσαις τὸν Λεωνίδαν καὶ τὸν Καλλικρατίδαν. ὁ μὲν γὰρ Ἀγησίλαος, ὡς ἔοικε, πρὸς τὸν εἰπόντα, φεῦ τῆς Ἑλλάδος, ὅπου μηδίζουσιν ἡμῖν οἱ Λάκωνες, οὐ μᾶλλον, εἶπεν, οἱ Μῆδοι λακωνίζουσι; τοῦ δὲ ῥήματος ἡ κομψότης τὴν τοῦ πράγματος αἰσχύνην οὐκ ἀφεῖλεν, ἀλλὰ τὴν μὲν ἡγεμονίαν ἀπώλεσαν ἐν Λεύκτροις ἀγωνισάμενοι κακῶς, ἡ δὲ δόξα τῆς Σπάρτης προαπώλετο ταῖς ὁμολογίαις ἐκείναις.", "st": "Art. 22.1"}, {"sp": "N", "t": "ἄχρι μὲν οὖν ἐπρώτευεν ἡ Σπάρτη, ξένον ἐποιεῖτο καὶ φίλον ὠνόμαζεν ἑαυτοῦ τὸν Ἀνταλκίδαν ἐπεὶ δὲ ἡττήθησαν ἐν Λεύκτροις, ταπεινὰ πράττοντες ἐδέοντο μὲν χρημάτων καὶ τὸν Ἀγησίλαον εἰς Αἴγυπτον ἐξέπεμψαν, ὁ δὲ Ἀνταλκίδας ἀνέβη πρὸς τὸν Ἀρτοξέρξην παρακαλῶν ἐπαρκέσαι τοῖς Λακεδαιμονίοις. ὁ δ’ οὕτως ἐξημέλησε καὶ παρεῖδε καὶ ἀπέρριψεν αὐτόν, ὥστε καταβάντα καὶ χλευαζόμενον ὑπὸ τῶν ἐχθρῶν, φοβούμενον δὲ καὶ τοὺς ἐφόρους, ἀποκαρτερῆσαι.", "st": "Art. 22.3"}, {"sp": "N", "t": "ἀνέβη δὲ πρὸς τὸν βασιλέα καὶ Ἰσμηνίας ὁ Θηβαῖος καὶ Πελοπίδας ἤδη τὴν ἐν Λεύκτροις μάχην νενικηκώς. ἀλλ’ οὗτος μὲν οὐδὲν αἰσχρὸν ἐποίησεν· Ἰσμηνίας δὲ προσκυνῆσαι κελευόμενος ἐξέβαλε πρὸ αὑτοῦ χαμᾶζε τὸν δακτύλιον, εἶτα κύψας ἀνείλετο καὶ παρέσχε δόξαν προσκυνοῦντος. Τιμαγόρᾳ δὲ τῷ Ἀθηναίῳ διὰ Βηλούριδος τοῦ γραμματέως εἰσπέμψαντι γραμματίδιον ἀπόρρητον ἡσθεὶς μυρίους τε δαρεικοὺς ἔδωκε, καὶ γάλακτος βοείου δεομένῳ δι’ ἀσθένειαν ὀγδοήκοντα βοῦς ἀμέλγεσθαι παρηκολούθουν ἔτι δὲ κλίνην καὶ στρώματα καὶ τοὺς στρωννύντας ἔπεμψεν, ὡς οὐ μεμαθηκότων Ἑλλήνων ὑποστρωννύναι, καὶ φορεῖς τοὺς κομίζοντας αὐτὸν μέχρι θαλάσσης μαλακῶς ἔχοντα. παρόντι δὲ δεῖπνον ἐπέμπετο λαμπρότατον, ὥστε καὶ τὸν ἀδελφὸν τοῦ βασιλέως, Ὀστάνην, ὦ Τιμαγόρα, φάναι, μέμνησο ταύτης τῆς τραπέζης· οὐ γὰρ ἐπὶ μικροῖς οὕτω σοι κεκοσμημένη παράκειται. τοῦτο δ’ ἦν ὀνειδισμὸς εἰς προδοσίαν μᾶλλον ἢ χάριτος ὑπόμνησις. Τιμαγόρου μὲν οὖν διὰ τὴν δωροδοκίαν Ἀθηναῖοι θάνατον κατέγνωσαν.", "st": "Art. 22.5"}, {"sp": "N", "t": "ὁ δὲ Ἀρτοξέρξης ἓν ἀντὶ πάντων ὧν ἐλύπει τοὺς Ἕλληνας εὔφραινε, Τισαφέρνην τὸν ἔχθιστον αὐτοῖς καὶ δυσμενέστατον ἀποκτείνας. ἀπέκτεινε δὲ ταῖς διαβολαῖς αὐτοῦ τῆς Παρυσάτιδος συνεπιθεμένης. οὐ γὰρ ἐνέμεινε τῇ ὀργῇ πολὺν χρόνον ὁ βασιλεύς, ἀλλὰ διηλλάγη τῇ μητρὶ καὶ μετεπέμψατο, νοῦν μὲν ὁρῶν ἔχουσαν καὶ φρόνημα βασιλείας ἄξιον, αἰτίας δὲ μηδεμιᾶς οὔσης ἐμποδὼν ἔτι δι’ ἣν ὑπόψονται συνόντες ἀλλήλοις ἢ λυπήσουσιν. ἐκ δὲ τούτου πάντα πρὸς χάριν ὑπουργοῦσα βασιλεῖ, καὶ τῷ πρὸς μηδὲν ὧν ἐκεῖνος ἔπραττε δυσκολαίνειν ἔχουσα τὸ δύνασθαι παρ’ αὐτῷ καὶ τυγχάνειν ἁπάντων, ᾔσθετο τῆς ἑτέρας τῶν θυγατέρων, Ἀτόσσης, ἐρῶντος ἔρωτα δεινόν, ἐπικρυπτομένου δὲ δι’ ἐκείνην οὐχ ἥκιστα καὶ κολάζοντος τὸ πάθος, ὥς φασιν ἔνιοι, καίτοι γεγενημένης ἤδη πρὸς τὴν παρθένον ὁμιλίας αὐτῷ λαθραίας. ὡς οὖν ὑπώπτευσεν ἡ Παρύσατις, τὴν παῖδα μᾶλλον ἢ πρότερον ἠσπάζετο, καὶ πρὸς τὸν Ἀρτοξέρξην ἐπῄνει τό τε κάλλος αὐτῆς καὶ τὸ ἦθος, ὡς βασιλικῆς καὶ μεγαλοπρεποῦς. τέλος οὖν γῆμαι τὴν κόρην ἔπεισε καὶ γνησίαν ἀποδεῖξαι γυναῖκα, χαίρειν ἐάσαντα δόξας Ἑλλήνων καὶ νόμους, Πέρσαις δὲ νόμον αὐτὸν ὑπὸ τοῦ θεοῦ καὶ δικαιωτὴν αἰσχρῶν καὶ καλῶν ἀποδεδειγμένον. ἔνιοι μέντοι λέγουσιν, ὧν ἐστι καὶ Ἡρακλείδης ὁ Κυμαῖος, οὐ μίαν μόνον τῶν θυγατέρων, ἀλλὰ καὶ δευτέραν, Ἄμηστριν, γῆμαι τὸν Ἀρτοξέρξην, περὶ ἧς ὀλίγον ὕστερον ἀπαγγελοῦμεν. τὴν δ’ Ἄτοσσαν οὕτως ἠγάπησεν ὁ πατὴρ συνοικοῦσαν ὥστε ἀλφοῦ κατανεμηθέντος αὐτῆς τὸ σῶμα δυσχερᾶναι μὲν ἐπὶ τούτῳ μηδ’ ὁτιοῦν, εὐχόμενος δὲ περὶ αὐτῆς τῇ Ἥρᾳ προσκυνῆσαι μόνην θεῶν ἐκείνην, ταῖς χερσὶ τῆς γῆς ἁψάμενος, δῶρά τε τῇ θεῷ τοσαῦτα πέμψαι τοὺς σατράπας καὶ φίλους αὐτοῦ κελεύσαντος ὥστε τὰ μεταξὺ τοῦ ἱεροῦ καὶ τῶν βασιλείων ἑκκαίδεκα στάδια χρυσοῦ καὶ ἀργύρου καὶ πορφύρας καὶ ἵππων ἐμπλησθῆναι.", "st": "Art. 23.1"}, {"sp": "N", "t": "πόλεμον δὲ πρὸς μὲν Αἰγυπτίους διὰ Φαρναβάζου καὶ Ἰφικράτους ἐξενεγκὼν ἀπέτυχε, στασιασάντων ἐκείνων· ἐπὶ δὲ Καδουσίους αὐτὸς ἐστράτευσε τριάκοντα μυριάσι πεζῶν καὶ μυρίοις ἱππεῦσιν. ἐμβαλὼν δὲ εἰς χώραν τραχύτητι χαλεπὴν καὶ ὁμιχλώδη καὶ τῶν ἀπὸ σπόρου καρπῶν ἄγονον, ἀπίοις δὲ καὶ μήλοις καὶ τοιούτοις ἄλλοις ἀκροδρύοις τρέφουσαν ἀνθρώπους πολεμικοὺς καὶ θυμοειδεῖς, ἔλαθε μεγάλαις ἀπορίαις καὶ κινδύνοις περιπεσών. οὐδὲν γὰρ ἐδώδιμον ἦν λαμβάνειν οὐδὲ ἔξωθεν ἐπεισάγεσθαι, τὰ δὲ ὑποζύγια μόνον κατέκοπτον, ὥστε ὄνου κεφαλὴν μόλις δραχμῶν ἑξήκοντα ὤνιον εἶναι. τὸ δὲ βασιλικὸν δεῖπνον ἐξελείφθη· καὶ τῶν ἵππων ὀλίγοι περιῆσαν ἔτι, τοὺς δὲ ἄλλους ἐσθίοντες κατανηλώκεσαν.", "st": "Art. 24.1"}, {"sp": "N", "t": "ἐνταῦθα Τηρίβαζος, ἀνὴρ πολλάκις μὲν ἐν πρώτῃ δι’ ἀνδραγαθίαν τάξει γενόμενος, πολλάκις δὲ ἀπορριφεὶς διὰ κουφότητα καὶ τότε ταπεινὰ πράττων καὶ περιορώμενος, ἔσωσε βασιλέα καὶ τὸν στρατόν. ὄντων γὰρ δυεῖν ἐν τοῖς Καδουσίοις βασιλέων, ἑκατέρου δὲ χωρὶς στρατοπεδεύοντος, ἐντυχὼν τῷ Ἀρτοξέρξῃ καὶ φράσας περὶ ὧν διενοεῖτο πράττειν, ἐβάδιζεν αὐτὸς πρὸς τὸν ἕτερον τῶν Καδουσίων, καὶ πρὸς τὸν ἕτερον κρύφα τὸν υἱὸν ἔπεμπεν. ἐξηπάτα δὲ ἑκάτερον ἑκάτερος, λέγων ὡς ἅτερος ἐπιπρεσβεύεται πρὸς τὸν Ἀρτοξέρξην φιλίαν μόνῳ πράττων ἑαυτῷ καὶ συμμαχίαν· οὐκοῦν, εἰ σωφρονεῖ, χρῆναι πρότερον ἐντυγχάνειν ἐκείνῳ, αὐτὸν δὲ συμπράξειν ἅπαντα. τούτοις ἐπείσθησαν ἀμφότεροι, καὶ φθάνειν ἀλλήλους νομίζοντες ὁ μὲν τῷ Τηριβάζῳ συνέπεμψε πρέσβεις, ὁ δὲ τῷ παιδὶ τοῦ Τηριβάζου. διατριβῆς δὲ γενομένης ὑποψίαι καὶ διαβολαὶ κατὰ τοῦ Τηριβάζου τῷ Ἀρτοξέρξῃ προσέπιπτον αὐτὸς δὲ δυσθύμως εἶχε καὶ μετενόει πιστεύσας τῷ Τηριβάζῳ, καὶ τοῖς φθονοῦσιν ἐγκαλεῖν παρεῖχεν. ἐπεὶ δὲ ἧκεν ὁ Τηρίβαζος, ἧκε δὲ καὶ ὁ υἱὸς αὐτοῦ τοὺς Καδουσίους ἄγοντες, ἐγένοντο δὲ σπονδαὶ πρὸς ἀμφοτέρους καὶ εἰρήνη, μέγας ὢν ὁ Τηρίβαζος ἤδη καὶ λαμπρὸς ἀνεζεύγνυε μετὰ τοῦ βασιλέως, ἐπιδεικνυμένου πᾶσαν τήν δειλίαν καὶ τήν μαλακίαν οὐ τρυφῆς καὶ πολυτελείας, ὥσπερ οἱ πολλοὶ νομίζουσιν, ἔκγονον οὖσαν, ἀλλὰ μοχθηρᾶς φύσεως καὶ ἀγεννοῦς καὶ δόξαις πονηραῖς ἑπομένης. οὔτε γὰρ χρυσὸς οὔτε κάνδυς οὔτε ὁ τῶν μυρίων καὶ δισχιλίων ταλάντων περικείμενος ἀεὶ τῷ βασιλέως σώματι κόσμος ἐκεῖνον ἀπεκώλυε πονεῖν καὶ ταλαιπωρεῖν, ὥσπερ οἱ τυχόντες, ἀλλὰ τήν τε φαρέτραν ἐνημμένος καὶ τήν πέλτην φέρων αὐτὸς ἐβάδιζε πρῶτος ὁδοὺς ὀρεινὰς καὶ προσάντεις, ἀπολιπὼν τὸν ἵππον, ὥστε τοὺς ἄλλους πτεροῦσθαι καὶ συνεπικουφίζεσθαι τήν ἐκείνου προθυμίαν καὶ ῥώμην ὁρῶντας· καὶ γὰρ διακοσίων καὶ πλειόνων σταδίων κατήνυεν ἡμέρας ἑκάστης πορείαν.", "st": "Art. 24.3"}, {"sp": "N", "t": "ἐπεὶ δὲ εἰς σταθμὸν κατέβη βασιλικόν παραδείσους ἔχοντα θαυμαστοὺς καὶ κεκοσμημένους διαπρεπῶς ἐν τῷ πέριξ ἀδένδρῳ καὶ ψιλῷ χωρίῳ, κρύους ὄντος, ἐπέτρεψε τοῖς στρατιώταις ἐκ τοῦ παραδείσου ξυλίζεσθαι τὰ δένδρα κόπτοντας, μήτε πεύκης μήτε κυπαρίττου φειδομένους. ὀκνούντων δὲ καὶ φειδομένων διὰ τὰ κάλλη καὶ τὰ μεγέθη, λαβὼν πέλεκυν αὐτὸς ὅπερ ἦν μέγιστον καὶ κάλλιστον τῶν φυτῶν ἔκοψεν. ἐκ δὲ τούτου ξυλιζόμενοι καὶ πολλὰ πυρὰ ποιοῦντες εὐμαρῶς ἐνυκτέρευσαν. οὐ μὴν ἀλλὰ πολλοὺς καὶ ἀγαθοὺς ἀποβαλὼν ἄνδρας, ἵππους δὲ ὁμοῦ τι πάντας ἐπανῆλθε. καὶ δόξας καταφρονεῖσθαι διὰ τὴν ἀτυχίαν καὶ τὴν ἀπότευξιν τῆς στρατείας, ἐν ὑποψίαις εἶχε τοὺς πρώτους· καὶ πολλοὺς μὲν ἀνῄρει δι’ ὀργήν, πλείονας δὲ φοβούμενος, ἡ γὰρ δειλία φονικώτατόν ἐστιν ἐν ταῖς τυραννίσιν, ἵλεων δὲ καὶ πρᾶον καὶ ἀνύποπτον ἡ θαρραλεότης. διὸ καὶ τῶν θηρίων τὰ ἀτιθάσευτα καὶ δυσεξημέρωτα ψοφοδεῆ καὶ δειλά, τὰ δὲ γενναῖα πιστεύοντα μᾶλλον διὰ τὸ θαρρεῖν οὐ φεύγει τὰς φιλοφροσύνας.", "st": "Art. 25.1"}, {"sp": "N", "t": "ὁ δὲ Ἀρτοξέρξης ἤδη πρεσβύτερος ὢν ᾐσθάνετο τοὺς υἱοὺς ἀγῶνα περὶ τῆς βασιλείας ἐν τοῖς φίλοις καὶ τοῖς δυνατοῖς ἔχοντας, οἱ μὲν γὰρ εὐγνώμονες ἠξίουν, ὡς ἔλαβεν αὐτός, οὕτως ἀπολιπεῖν πρεσβεῖα Δαρείῳ τὴν ἀρχήν, ὁ δὲ νεώτατος Ὦχος ὀξὺς ὢν καὶ βίαιος εἶχε μὲν καὶ τῶν περὶ τὸ βασίλειον οὐκ ὀλίγους σπουδαστάς, ἤλπιζε δὲ μάλιστα κατεργάσεσθαι τὸν πατέρα διὰ τῆς Ἀτόσσης. ἐκείνην γὰρ ἐθεράπευεν ὡς γαμησομένην καὶ συμβασιλεύσουσαν αὐτῷ μετὰ τὴν τοῦ πατρὸς τελευτήν. ἦν δὲ λόγος ὅτι καὶ ζῶντος ἐλάνθανεν αὐτῇ πλησιάζων, ἀλλὰ τοῦτο μὲν ἠγνόησεν ὁ Ἀρτοξέρξης· ταχὺ δὲ βουλόμενος ἐκκροῦσαι τῆς ἐλπίδος τὸν Ὦχον, ὅπως μὴ τὰ αὐτὰ Κύρῳ τολμήσαντος αὐτοῦ πόλεμοι καὶ ἀγῶνες αὖθις καταλάβωσι τὴν βασιλείαν, ἀνέδειξε τὸν Δαρεῖον βασιλέα πεντηκοστὸν ἔτος γεγονότα, καὶ τὴν καλουμένην κίταριν ὀρθὴν φέρειν ἔδωκε. νόμου δὲ ὄντος ἐν Πέρσαις δωρεὰν αἰτεῖν τὸν ἀναδειχθέντα καὶ διδόναι τὸν ἀναδείξαντα πᾶν τὸ αἰτηθὲν, ἄνπερ ᾖ δυνατόν, ᾔτησεν Ἀσπασίαν ὁ Δαρεῖος τὴν μάλιστα σπουδασθεῖσαν ὑπὸ Κύρου, τότε δὲ τῷ βασιλεῖ παλλακευομένην. ἦν δὲ Φωκαῒς τὸ γένος ἀπ’ Ἰωνίας, ἐλευθέρων γονέων καὶ τεθραμμένη κοσμίως. ἐπεὶ δὲ Κύρου δειπνοῦντος εἰσήχθη μεθ’ ἑτέρων γυναικῶν, αἱ μὲν ἄλλαι παρακαθεζόμεναι προσπαίζοντος αὐτοῦ καὶ ἁπτομένου καὶ σκώπτοντος οὐκ ἀηδῶς ἐνεδέχοντο τὰς φιλοφροσύνας, ἐκείνη δὲ παρὰ τὴν κλίνην εἱστήκει σιωπῇ καὶ Κύρου καλοῦντος οὐχ ὑπήκουε βουλομένων δὲ προσάγειν τῶν κατευναστῶν, οἰμώξεται μέντοι τούτων, εἶπεν, ὃς ἂν ἐμοὶ προσαγάγῃ τὰς χεῖρας ἔδοξεν οὖν ἄχαρις τοῖς παροῦσιν εἶναι καὶ ἄγροικος. ὁ δὲ Κῦρος ἡσθεὶς ἐγέλασε, καὶ εἶπε πρὸς τὸν ἀγαγόντα τὰς γυναῖκας, ἆρα ἤδη συνορᾷς ὅτι μοι μόνην ταύτην ἐλευθέραν καὶ ἀδιάφθορον ἥκεις κομίζων; ἐκ δὲ τούτου προσεῖχεν ἀρξάμενος αὐτῇ, καὶ μάλιστα πασῶν ἔστερξε καὶ σοφὴν προσηγόρευσεν. ἑάλω δὲ Κύρου πεσόντος ἐν τῇ μάχῃ καὶ διαρπαζομένου τοῦ στρατοπέδου.", "st": "Art. 26.1"}, {"sp": "N", "t": "ταύτην ὁ Δαρεῖος αἰτήσας ἠνίασε τὸν πατέρα· δύσζηλα γὰρ τὰ βαρβαρικὰ δεινῶς περὶ τὸ ἀκόλαστον, ὥστε μὴ μόνον τὸν προσελθόντα καὶ θιγόντα παλλακῆς βασιλέως, ἀλλὰ καὶ τὸν ἐν πορείᾳ προεξελθόντα καὶ διεξελάσαντα τὰς ἁμάξας ἐφ’ αἷς κομίζονται, θανάτῳ κολάζεσθαι. καίτοι τὴν μὲν Ἄτοσσαν εἶχεν ἔρωτι ποιησάμενος γυναῖκα παρὰ τὸν νόμον, ἑξήκοντα δὲ καὶ τριακόσιαι παρετρέφοντο κάλλει διαφέρουσαι παλλακίδες, οὐ μὴν ἀλλὰ καὶ αἰτηθεὶς ἐκείνην ἐλευθέραν ἔφησεν εἶναι καὶ λαμβάνειν ἐκέλευσε βουλομένην, ἄκουσαν δὲ μὴ βιάζεσθαι. μεταπεμφθείσης δὲ τῆς Ἀσπασίας καὶ παρ’ ἐλπίδας τοῦ βασιλέως ἑλομένης τὸν Δαρεῖον, ἔδωκε μὲν ὑπ’ ἀνάλκης τοῦ νόμου, δοὺς δὲ ὀλίγον ὕστερον ἀφείλετο. τῆς γὰρ Ἀρτέμιδος τῆς ἐν Ἐκβατάνοις, ἣν Ἀναῗτιν καλοῦσιν, ἱέρειαν ἀνέδειξεν αὐτήν, ὅπως ἁγνὴ διάγῃ τὸν ἐπίλοιπον βίον, οἰόμενος οὐ χαλεπήν, ἀλλὰ καὶ μετρίαν τινὰ καὶ παιδιᾷ μεμιγμένην ταύτην λήψεσθαι δίκην παρὰ τοῦ παιδός. ὁ δ’ ἤνεγκεν οὐ μετρίως, εἴτ’ ἔρωτι τῆς Ἀσπασίας περιπαθὴς γεγονώς, εἴτε ὑβρίσθαι καὶ κεχλευάσθαι νομίζων ὑπὸ τοῦ πατρός.", "st": "Art. 27.1"}, {"sp": "N", "t": "αἰσθόμενος δ’ αὐτὸν οὕτως ἔχοντα Τηρίβαζος ἔτι μᾶλλον ἐξετράχυνεν, ἐν τοῖς ἐκείνου συνιδὼν τὰ καθ’ αὑτόν, ἦν δὲ τοιαῦτα, πλειόνων οὐσῶν βασιλεῖ θυγατέρων ὡμολόγησε Φαρναβάζῳ μὲν Ἀπάμαν δώσειν γυναῖκα, Ῥοδογούνην δὲ Ὀρόντῃ, Τηριβάζῳ δὲ Ἄμηστριν. καὶ τοῖς μὲν ἄλλοις ἔδωκε, Τηρίβαζον δὲ ἐψεύσατο γήμας αὐτὸς τὴν Ἄμηστριν, ἀντ’ ἐκείνης δὲ τῷ Τηριβάζῳ τὴν νεωτάτην Ἄτοσσαν ἐνεγύησεν. ἐπεὶ δὲ καὶ ταύτην ἐρασθεὶς ἔγημεν, ὡς εἴρηται, παντάπασι δυσμενῶς πρὸς αὐτὸν ὁ Τηρίβαζος ἔσχεν, οὐδὲ ἄλλως στάσιμος ὢν τὸ ἦθος, ἀλλ’ ἀνώμαλος καὶ παράφορος. διὸ καὶ νῦν μὲν εὐημερῶν ὅμοια τοῖς πρώτοις, νῦν δὲ προσκρούων καὶ σκορακιζόμενος οὐδεμίαν ἔφερεν ἐμμελῶς μεταβολήν, ἀλλὰ καὶ τιμώμενος ἦν ἐπαχθὴς ὑπὸ χαυνότητος, καὶ τὸ κολουόμενον οὐ ταπεινὸν οὐδὲ ἡσυχαῖον, ἀλλὰ τραχὺ καὶ ἀγέρωχον εἶχε.", "st": "Art. 27.4"}, {"sp": "N", "t": "πῦρ οὖν ἐπὶ πῦρ ἐγένετο τῷ νεανίσκῳ προσκείμενος ὁ Τηρίβαζος ἀεὶ καὶ λέγων ὡς οὐδὲν ὀνίνησιν ἡ κίταρις ἑστῶσα περὶ τῇ κεφαλῇ τοὺς ὑφ’ αὑτῶν μὴ ζητοῦντας ὀρθοῦσθαι τοῖς πράγμασι, κἀκεῖνον ἀβέλτερα φρονεῖν, εἰ, τοῦ μὲν ἀδελφοῦ διὰ τῆς γυναικωνίτιδος ἐνδυομένου τοῖς πράγμασι, τοῦ δὲ πατρὸς οὕτως ἔμπληκτον ἦθος καὶ ἀβέβαιον ἔχοντος, οἴεται βέβαιον αὐτῷ τὴν διαδοχὴν ὑπάρχειν. ὁ γὰρ Ἑλληνικοῦ χάριν γυναίου τὸν ἄψευστον ἐν Πέρσαις ψευσάμενος νόμον οὐ δή που πιστός ἐστι τὰς περὶ τῶν μεγίστων ὁμολογίας ἐμπεδώσειν. οὐ ταὐτὸ δ’ εἶναι τὸ μὴ τυχεῖν Ὤχῳ κἀκείνῳ τὸ στέρεσθαι τῆς βασιλείας· Ὦχον μὲν γὰρ οὐδένα κωλύσειν ἰδιώτην βιοῦν μακαρίως, ἐκείνῳ δ’ ἀποδεδειγμένῳ βασιλεῖ βασιλεύειν ἀνάγκην ἢ μηδὲ ζῆν εἶναι.", "st": "Art. 28.1"}, {"sp": "N", "t": "καθόλου μὲν οὖν ἴσως, τὸ Σοφόκλειον,<br>ταχεῖα πειθὼ τῶν κακῶν ὁδοιπορεῖ·", "st": "Art. 28.3"}, {"sp": "N", "t": "λεία γάρ τις ἡ πορεία καὶ κατάντης ἐπὶ τὸ βουλόμενον. βούλονται δὲ οἱ πλεῖστοι τὰ φαῦλα δι’ ἀπειρίαν τῶν καλῶν καὶ ἄγνοιαν· οὐ μὴν ἀλλὰ τὸ μέγεθος τὸ τῆς ἀρχῆς καὶ τὸ πρὸς τὸν Ὦχον τοῦ Δαρείου δέος ὑπόθεσιν τῷ Τηριβάζῳ παρεῖχε· Κυπρογένεια δ’ οὐ πάμπαν ἀναίτιος, ἡ τῆς Ἀσπασίας ἀφαίρεσις.", "st": "Art. 28.3b"}, {"sp": "N", "t": "ἐπέδωκεν οὖν ἑαυτὸν τῷ Τηριβάζῳ· καὶ πολλῶν ἤδη συνισταμένων, εὐνοῦχος ἐδήλωσε τῷ βασιλεῖ τὴν ἐπιβουλὴν καὶ τὸν τρόπον, εἰδὼς ἀκριβῶς ὅτι νυκτὸς ἐγνώκασιν ἐν τῷ θαλάμῳ κατακείμενον ἀναιρεῖν αὐτὸν ἐπεισελθόντες. ἀκούσαντι δὲ τῷ Ἀρτοξέρξῃ καὶ τὸ παριδεῖν κίνδυνον τηλικοῦτον, ἀμελήσαντα τῆς διαβολῆς, δεινὸν ἐδόκει, καὶ τὸ πιστεῦσαι μηδενὸς ἐλέγχου γενομένου δεινότερον. οὕτως οὖν ἐποίει· τὸν μὲν εὐνοῦχον ἐκείνοις ἐκέλευσε παρεῖναι καὶ παρακολουθεῖν, αὐτὸς δὲ τοῦ θαλάμου τὸν ὄπισθεν τῆς κλίνης τοῖχον ἐκκόψας καὶ θυρώσας κατεκάλυψεν αὐλαίᾳ τὰς θύρας, ἐνστάσης δὲ τῆς ὥρας καὶ φράσαντος τοῦ εὐνούχου τὸν καιρόν, ἐπὶ τῆς κλίνης ὑπέμεινε καὶ οὐκ ἐξανέστη πρότερον ἢ τῶν ἐπ’ αὐτὸν ἐρχομένων τὰ πρόσωπα κατιδεῖν καὶ γνωρίσαι σαφῶς ἕκαστον. ὡς δὲ εἶδεν ἐσπασμένους τὰ ἐγχειρίδια καὶ προσφερομένους, ταχὺ τὴν αὐλαίαν ὑπολαβὼν ἀνεχώρησεν εἰς τὸ ἐντὸς οἴκημα καὶ τὰς θύρας ἐπήρραξε κράζων. ὀφθέντες οὖν οἱ σφαγεῖς ὑπ’ αὐτοῦ, πράξαντες δὲ μηθέν, ἀπεχώρουν φυγῇ διὰ θυρῶν, καὶ τοὺς περὶ τὸν Τηρίβαζον ἐκέλευον ἀποχωρεῖν ὡς φανεροὺς γεγονότας. οἱ μὲν οὖν ἄλλοι διαλυθέντες ἔφυγον ὁ δὲ Τηρίβαζος συλλαμβανόμενος πολλοὺς ἀπέκτεινε τῶν βασιλέως δορυφόρων καὶ μόγις ἀκοντίῳ πληγεὶς πόρρωθεν ἔπεσε, τῷ δὲ Δαρείῳ μετὰ τῶν τέκνων ἀναχθέντι καθίσας τοὺς βασιλείους δικαστάς, οὐ παρὼν αὐτός, ἀλλ’ ἑτέρων κατηγορησάντων, ἐκέλευσεν ὑπηρέτας τὴν ἑκάστου γραψαμένους ἀπόφασιν ὡς αὐτὸν ἐπανενεγκεῖν. ἀποφηναμένων δὲ πάντων ὁμοίως καὶ καταγνόντων τοῦ Δαρείου θάνατον, οἱ μὲν ὑπηρέται συλλαβόντες αὐτὸν εἰς οἴκημα πλησίον ἀπήγαγον, ὁ δὲ δήμιος κληθεὶς ἧκε μὲν ξυρὸν ἔχων, ᾧ τὰς κεφαλὰς ἀποτέμνουσι τῶν κολαζομένων, ἰδὼν δὲ τὸν Δαρεῖον ἐξεπλάγη καὶ ἀνεχώρει πρὸς τὰς θύρας ἀποβλέπων, ὡς; οὐ δυνησόμενος οὐδὲ τολμήσων αὐτόχειρ γενέσθαι βασιλέως. ἔξωθεν δὲ τῶν δικαστῶν ἀπειλούντων καὶ διακελευομένων ἀναστρέψας καὶ τῇ ἑτέρᾳ χειρὶ δραξάμενος τῆς κόμης αὐτοῦ καὶ καταγαγών ἀπέτεμε τῷ ξυρῷ τὸν τράχηλον.", "st": "Art. 29.1"}, {"sp": "N", "t": "ἔνιοι δέ φασι τὴν κρίσιν γενέσθαι βασιλέως αὐτοῦ παρόντος, τὸν δὲ Δαρεῖον, ὡς κατελαμβάνετο τοῖς ἐλέγχοις, ἐπὶ στόμα πεσόντα δεῖσθαι καὶ ἱκετεύειν· τὸν δὲ ὑπ’ ὀργῆς ἀναστάντα καὶ σπασάμενον τὸν ἀκινάκην τύπτειν ἕως ἀπέκτεινεν εἶτα εἰς τὴν αὐλὴν προελθόντα τὸν Ἥλιον προσκυνῆσαι καὶ εἰπεῖν εὐφραίνεσθε ἀπιόντες, ὦ Πέρσαι, καὶ λέγετε τοῖς ἄλλοις ὅτι τοῖς ἄθεσμα καὶ παράνομα διανοηθεῖσιν ὁ μέγας Ὠρομάζης δίκην ἐπιτέθεικεν.", "st": "Art. 29.7"}, {"sp": "N", "t": "ἡ μὲν οὖν ἐπιβουλὴ τοιοῦτον ἔσχε τέλος, ὁ δὲ Ὦχος ἤδη μὲν ἦν ταῖς ἐλπίσι λαμπρός ὑπὸ τῆς Ἀτόσσης ἐπαιρόμενος, ἔτι δὲ ἐφοβεῖτο τῶν μὲν γνησίων τὸν ὑπόλοιπον Ἀριάσπην, τῶν δὲ νόθων Ἀρσάμην. ὁ μὲν γὰρ Ἀριάσπης οὐ διὰ τὸ πρεσβύτερος εἶναι τοῦ Ὤχου, πρᾶος δὲ καὶ ἁπλοῦς καὶ φιλάνθρωπος, ἠξιοῦτο βασιλεύειν ὑπὸ τῶν Περσῶν ὁ δὲ Ἀρσάμης καὶ νοῦν ἔχειν ἐδόκει καὶ μάλιστα τῷ πατρὶ προσφιλὴς ὢν οὐκ ἐλάνθανε τὸν Ὦχον. ἐπιβουλεύων οὖν ἀμφοτέροις καὶ δολερὸς ὢν ὁμοῦ καὶ φονικός ἐχρήσατο τῇ μὲν ὠμότητι τῆς φύσεως πρὸς τὸν Ἀρσάμην, τῇ δὲ κακουργίᾳ καὶ δεινότητι πρὸς τὸν Ἀριάσπην. ὑπέπεμψε γὰρ πρὸς αὐτὸν εὐνούχους καὶ φίλους βασιλέως ἀπειλάς τινας ἀεὶ καὶ λόγους φοβεροὺς ἀπαγγέλλοντας, ὡς τοῦ πατρὸς ἐγνωκότος ἀποκτιννύειν αὐτὸν ὠμῶς καὶ ἐφυβρίστως. οἱ δὲ ταῦτα καθ’ ἡμέραν ἐκφέρειν δοκοῦντες ὡς ἀπόρρητα, καὶ τὰ μὲν μέλλειν, τὰ δὲ ὅσον οὔπω πράσσειν βασιλέα λέγοντες, οὕτως ἐξέπληξαν τὸν ἄνθρωπον καὶ τοσαύτην ἐνέβαλον πτοίαν αὐτῷ καὶ ταραχὴν καὶ δυσθυμίαν εἰς τοὺς λογισμούς, ὥστε φάρμακον σκευάσαντα τῶν θανασίμων καὶ πιόντα τοῦ ζῆν ἀπαλλαγῆναι. πυθόμενος δὲ ὁ βασιλεὺς τὸν τρόπον τῆς τελευτῆς, ἐκεῖνον μὲν ἀπέκλαυσε, τὴν δ’ αἰτίαν ὑπώπτευεν. ἐλέγχειν δὲ καὶ ζητεῖν ἐξαδυνατῶν διὰ γῆρας ἔτι μᾶλλον ἠσπάζετο τὸν Ἀρσάμην, καὶ δῆλος ἦν μάλιστα πιστεύων ἐκείνῳ καὶ παρρησιαζόμενος. ὅθεν οἱ περὶ τὸν Ὦχον οὐκ ἀνεβάλοντο τὴν πρᾶξιν, ἀλλ’ Ἀρπάτην υἱὸν Τηριβάζου παρασκευάσαντες ἀπέκτειναν δι’ ἐκείνου τὸν ἄνθρωπον. ἦν μὲν οὖν ἐπὶ ῥοπῆς μικρᾶς ὁ Ἀρτοξέρξης διὰ τὸ γῆρας ἤδη τότε· προσπεσόντος δὲ αὐτῷ τοῦ περὶ τὸν Ἀρσάμην πάθους οὐδὲ ὀλίγον ἀντέσχεν, ἀλλ’ εὐθὺς ὑπὸ λύπης καὶ δυσθυμίας ἀπεσβέσθη, βιώσας μὲν ἐνενήκοντα καὶ τέσσαρα ἔτη, βασιλεύσας δὲ δύο καὶ ἑξήκοντα, δόξας δὲ πρᾶος εἶναι καὶ φιλυπήκοος οὐχ ἥκιστα διὰ τὸν υἱὸν Ὦχον ὠμότητι καὶ μιαιφονίᾳ πάντας ὑπερβαλόμενον.", "st": "Art. 30.1"}, {"sp": "HDR", "t": "Ἄρατος"}, {"sp": "N", "t": "παροιμίαν τινὰ παλαιὰν, ὦ Πολύκρατες, δείσας μοι δοκεῖ τὸ δύσφημον αὐτῆς, ὁ φιλόσοφος Χρύσιππος, οὐχ ὃν ἔχει τρόπον, ἀλλ’ ὡς αὐτὸς ᾤετο βέλτιον εἶναι, διατίθεται,", "st": "Arat. 1.1"}, {"sp": "N", "t": "τίς πατέρ’ αἰνήσει, εὶ μὴ εὐδαίμονες υἱοί;", "st": "Arat. 1.1b"}, {"sp": "N", "t": "Διονυσόδωρος δὲ ὁ Τροιζήνιος ἐλέγχων αὐτὸν ἀντεκτίθησι τὴν ἀληθινὴν οὕτως ἔχουσαν<br>τίς πατέρ’ αἰνήσει, εἰ μὴ κακοδαίμονες υἱοί;", "st": "Arat. 1.1c"}, {"sp": "N", "t": "καί φησι τοὺς ἀφ’ αὑτῶν οὐδενὸς ἀξίους ὄντας, ὑποδυομένους δὲ προγόνων τινῶν ἀρεταῖς καί πλεονάζοντας ἐν τοῖς ἐκείνων ἐπαίνοις ὑπὸ τῆς παροιμίας ἐπιστομίζεσθαι· ἀλλ’ ᾧ γε φύσει τὸ γενναῖον ἐπιπρέπει ἐκ πατέρων, κατὰ Πίνδαρον, ὥσπερ σοί πρὸς τὸ κάλλιστον ἀφομοιοῦντι τῶν οἴκοθεν παραδειγμάτων τὸν βίον, εὔδαιμον ἂν εἴη τὸ μεμνῆσθαι τῶν ἀπὸ γένους ἀρίστων, ἀκούοντας περὶ αὑτῶν ἀεί τι καί λέγοντας. οὐ γὰρ ἰδίων ἀπορίᾳ καλῶν ἐξαρτῶσιν ἀλλοτρίων ἐπαίνων τὴν δόξαν, ἀλλὰ τοῖς ἐκείνων τὰ οἰκεῖα συνάπτοντες, ὡς καί τοῦ γένους καί τοῦ βίου καθηγεμόνας εὐφημοῦσι. διὸ κἀγὼ τὸν Ἀράτου τοῦ σοῦ πολίτου καί προπάτορος βίον, ὃν οὔτε τῇ δόξῃ τῇ περὶ σεαυτὸν οὔτε τῇ δυνάμει καταισχύνεις, ἀπέσταλκά σοί συγγραψάμενος, οὐχ ὡς οὐχὶ πάντων ἀκριβέστατά σοί μεμεληκὸς ἐξ ἀρχῆς ἐπίστασθαι τὰς ἐκείνου πράξεις, ἀλλ’ ὅπως οἱ παῖδές σου Πολυκράτης καί Πυθοκλῆς οἰκείοις παραδείγμασιν ἐντρέφωνται, τὰ μὲν ἀκούοντες, τὰ δὲ ἀναγινώσκοντες, ἅπερ αὐτοὺς μιμεῖσθαι προσήκει, φιλαύτου γὰρ ἀνδρός, οὐ φιλοκάλου, παντὸς ἀεὶ βέλτιστον ἡγεῖσθαι.", "st": "Arat. 1.2"}, {"sp": "N", "t": "ἡ Σικυωνίων πόλις, ἐπεὶ τὸ πρῶτον ἐκ τῆς ἀκράτου καὶ Δωρικῆς ἀριστοκρατίας ὥσπερ ἁρμονίας συγχυθείσης εἰς στάσεις ἐνέπεσε καὶ φιλοτιμίας δημαγωγῶν, οὐκ ἐπαύσατο νοσοῦσα καὶ ταραττομένη καὶ τύραννον ἐκ τυράννου μεταβάλλουσα, μέχρι οὗ Κλέωνος ἀναιρεθέντος εἵλοντο Τιμοκλείδαν ἄρχοντα καὶ Κλεινίαν, ἄνδρας ἐνδόξους τὰ μάλιστα καὶ ἐν δυνάμει τῶν πολιτῶν ὄντας. ἤδη δέ τινα τῆς πολιτείας κατάστασιν ἔχειν δοκούσης Τιμοκλείδας μὲν ἀπέθανεν, Ἀβαντίδας δὲ ὁ Πασέου τυραννίδα πράττων ἑαυτῷ τὸν Κλεινίαν ἀπέκτεινε καὶ τῶν φίλων καὶ οἰκείων τοὺς μὲν ἐξέβαλε, τοὺς δὲ ἀνεῖλεν. ἐζήτει δὲ καὶ τὸν υἱὸν αὐτοῦ, Ἄρατον, ἀνελεῖν, ἑπταετῆ καταλελειμμένον. ἐν δὲ τῇ περὶ τὴν οἰκίαν ταραχῇ συνεκπεσὼν τοῖς φεύγουσιν ὁ παῖς, καὶ πλανώμενος ἐν τῇ πόλει περίφοβος καὶ ἀβοήθητος, κατὰ τύχην ἔλαθεν εἰς οἰκίαν παρελθὼν γυναικός, ἀδελφῆς μὲν Ἀβαντίδου, Προφάντῳ δὲ τῷ Κλεινίου ἀδελφῷ γεγαμημένης, ὄνομα Σωσοῦς. αὕτη δὲ καὶ τὸ ἦθος οὖσα γενναία καὶ σὺν θεῷ τινι τὸ παιδίον οἰομένη καταπεφευγέναι πρὸς αὐτήν ἀπέκρυψεν ἔνδον, εἶτα νυκτὸς εἰς Ἄργος ὑπεξέπεμψεν.", "st": "Arat. 2.1"}, {"sp": "N", "t": "οὕτω δ’ ἐκκλαπέντι τῷ Ἀράτῳ καὶ διαφυγόντι τὸν κίνδυνον εὐθὺς μὲν ἐνεφύετο καὶ συνηύξετο τὸ σφοδρὸν καὶ διάπυρον μῖσος ἐπὶ τοὺς τυράννους, τρεφόμενος δὲ παρὰ τοῖς ἐν Ἄργει ξένοις καὶ φίλοις πατρῴοις ἐλευθερίως, καὶ τὸ σῶμα βλαστάνον ὁρῶν εἰς εὐεξίαν καὶ μέγεθος, ἐπέδωκεν ἑαυτὸν ἀσκήσει τῇ περὶ παλαίστραν, ὥστε καὶ πένταθλον ἀγωνίσασθαι καὶ στεφάνων τυχεῖν. ἐπιφαίνεται δ’ ἀμέλει καὶ ταῖς εἰκόσιν ἀθλητική τις ἰδέα, καὶ τὸ συνετὸν τοῦ προσώπου καὶ βασιλικὸν οὐ παντάπασιν ἀρνεῖται τὴν ἀδηφαγίαν καὶ τὸ σκαφεῖον. ὅθεν ἐνδεέστερον ἴσως ἢ πολιτικῷ προσῆκον ἦν ἀνδρὶ περὶ τὸν λόγον ἐσπούδασε καίτοι γεγονέναι κομψότερον εἰπεῖν ἢ δοκεῖ τισιν ἐκ τῶν ὑπομνημάτων κρίνουσιν, ἃ παρέργως καὶ ὑπὸ χεῖρα διὰ τῶν ἐπιτυχόντων ὀνομάτων ἁμιλλησάμενος κατέλιπε.", "st": "Arat. 3.1"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον Ἀβαντίδαν μὲν οἱ περὶ Δεινίαν καὶ Ἀριστοτέλη τὸν διαλεκτικόν, εἰωθότα τοῖς λόγοις αὐτῶν κατ’ ἀγορὰν σχολαζόντων ἑκάστοτε παρεῖναι καὶ συμφιλονεικεῖν, ἐμβαλόντες εἰς τοιαύτην διατριβὴν καὶ κατασκευάσαντες ἐπιβουλὴν ἀνεῖλον, Πασέαν δὲ τὸν Ἀβαντίδου πατέρα τὴν ἀρχὴν ὑπολαβόντα Νικοκλῆς δολοφονήσας ἑαυτὸν ἀνέδειξε τύραννον. τοῦτον ἐμφερέστατον λέγουσι τὴν ὄψιν Περιάνδρῳ τῷ Κυψέλου γενέσθαι, καθάπερ Ἀλκμαίωνι μὲν τῷ Ἀμφιάρεω τὸν Πέρσην Ὀρόντην, Ἕκτορι δὲ τὸν Λακεδαιμόνιον νεανίσκον, ὃν ἱστορεῖ Μυρτίλος ὑπὸ πλήθους τῶν θεωμένων, ὡς τοῦτο ἔγνωσαν, καταπατηθῆναι.", "st": "Arat. 3.3"}, {"sp": "N", "t": "τοῦ δὲ Νικοκλέους τέσσαρας μῆνας τυραννοῦντος, ἐν οἷς πολλὰ κακὰ τὴν πόλιν ἐργασάμενος ἐκινδύνευσεν ὑπὸ Αἰτωλῶν ἐπιβουλευομένην αὐτὴν ἀποβαλεῖν, ἤδη μειράκιον ὁ Ἄρατος ὢν ἀξίωμα λαμπρὸν εἶχε δι’ εὐγένειαν Καὶ φρόνημα, ὃ διέφαινεν οὐ μικρὸν οὐδὲ ἀργόν, ἐμβριθὲς δὲ Καὶ παρ’ ἡλικίαν ἀσφαλεστέρᾳ γνώμῃ κεκραμένον. ὅθεν οἵ τε φυγάδες μάλιστα τὸν νοῦν ἐκείνῳ προσεῖχον, ὅ τε Νικοκλῆς οὐκ ἠμέλει τῶν πραττομένων, ἀλλ’ ἀδήλως ἀπεθεώρει Καὶ παρεφύλαττεν αὑτοῦ τὴν ὁρμήν, τόλμημα μὲν οὐδὲν τηλικοῦτον δεδιὼς οὐδὲ ἔργον οὐδὲν οὕτω παρακεκινδυνευμένον, ὑποπτεύων δὲ τοῖς βασιλεῦσιν αὐτὸν διαλέγεσθαι φίλοις οὖσι Καὶ ξένοις πατρῴοις. καὶ γὰρ ἀληθῶς ὁ Ἄρατος ἐπεχείρησε τὴν ὁδὸν ἐκείνην βαδίζειν. ὡς δὲ Ἀντίγονος μὲν ὑπισχνούμενος ἠμέλει Καὶ παρῆγε τὸν χρόνον, αἱ δὲ ἀπ’ Αἰγύπτου Καὶ παρὰ Πτολεμαίου μακρὰν ἦσαν ἐλπίδες, ἔγνω δι’ αὑτοῦ καταλύειν τὸν τύραννον.", "st": "Arat. 4.1"}, {"sp": "N", "t": "πρώτοις δὲ κοινοῦται τὴν γνώμην Ἀριστομάχῳ καὶ Ἐκδήλῳ. τούτων ὁ μὲν ἐκ Σικυῶνος ἦν φυγάς, ὁ δὲ Ἔκδηλος Ἀρκὰς ἐκ Μεγάλης πόλεως, ἀνὴρ φιλόσοφος καὶ πρακτικός, Ἀρκεσιλάου τοῦ Ἀκαδημιακοῦ γεγονὼς ἐν ἄστει συνήθης. δεξαμένων δὲ τούτων προθύμως διελέγετο τοῖς ἄλλοις φυγάσιν, ὧν ὀλίγοι μὲν αἰσχυνθέντες ἐγκαταλιπεῖν τὴν ἐλπίδα μετεῖχον τῶν πραττομένων, οἱ δὲ πολλοὶ καὶ τὸν Ἄρατον ἐπειρῶντο κατακωλύειν ὡς ἀπειρίᾳ πραγμάτων θρασυνόμενον.", "st": "Arat. 5.1"}, {"sp": "N", "t": "βουλευομένου δ’ αὐτοῦ χωρίον τι τῆς Σικυωνίας καταλαβεῖν, ὅθεν ὡρμημένος διαπολεμήσει πρὸς τὸν τύραννον, ἧκεν εἰς Ἄργος ἀνὴρ Σικυώνιος ἐκ τῆς εἱρκτῆς ἀποδεδρακώς· ἦν δὲ τῶν φυγάδων ἑνὸς Ξενοκλέους ἀδελφός· καὶ τῷ Ἀράτῳ προσαχθεὶς ὑπὸ τοῦ Ξενοκλέους ἔλεγε τοῦ τείχους καθ’ ὃν ὑπερβὰς αὐτὸς ἐσώθη τόπον, ἐντὸς μὲν ὀλίγου δεῖν ἐπίπεδον εἶναι, προσπεφυκότα χωρίοις πετρώδεσι καὶ ὑψηλοῖς, τὸ δὲ ἔξωθεν ὕψος ὑπὸ κλιμάκων οὐ πάνυ ἀνέφικτον. ὡς δὲ ταῦτα ἤκουσεν ὁ Ἄρατος, ἐκπέμπει μετὰ τοῦ Ξενοκλέους οἰκέτας ἰδίους δύο, Σεύθαν τε καὶ Τέχνωνα, κατασκεψομένους τὸ τεῖχος, ἐγνωκὼς, εἰ δύναιτο, κρύφα καὶ πρὸς ἕνα κίνδυνον ὀξέως τὸ πᾶν ἀναρρῖψαι μᾶλλον ἢ μακρῷ πολέμῳ καὶ φανεροῖς ἀγῶσιν ἰδιώτης ἀντικαθίστασθαι πρὸς τύραννον. ὡς δ’ ἐπανῆλθον οἱ περὶ τὸν Ξενοκλέα τοῦ μὲν τείχους εἰληφότες μέτρα καὶ τοῦ τόπου τὴν φύσιν ἀπαγγέλλοντες οὐκ ἄπορον οὐδὲ χαλεπήν, τὸ δὲ λαθεῖν προσελθόντας ἐργῶδες εἶναι φάσκοντες ὑπὸ κηπουροῦ τινος κυναρίων, μικρῶν μέν, ἐκτόπως δὲ μαχίμων καὶ ἀπαρηγορήτων, εὐθὺς ἐνίστατο τὴν πρᾶξιν.", "st": "Arat. 5.3"}, {"sp": "N", "t": "ἡ μὲν οὖν τῶν ὅπλων παρασκευὴ συνήθης ἦν, πάντων, ὡς ἔπος εἰπεῖν, τότε κλωπείαις χρωμένων καὶ καταδρομαῖς ἐπ’ ἀλλήλους· τὰς δὲ κλίμακας Εὐφράνωρ ὁ μηχανοποιὸς ἀναφανδὸν ἐπήξατο, τῆς τέχνης αὐτῷ τὸ ἀνύποπτον διδούσης, ἐπεὶ καὶ αὐτὸς ἦν τῶν φυγάδων. ἄνδρας δὲ αὐτῷ τῶν μὲν ἐν Ἄργει φίλων ἕκαστος ἐξ ὀλίγων δέκα παρέσχεν, αὐτὸς δὲ τῶν ἰδίων οἰκετῶν τριάκοντα καθώπλισεν. ἐμισθώσατο δὲ καὶ διὰ Πρώτου Ξενοφίλου τῶν ἀρχικλώπων οὐ πολλοὺς στρατιώτας, οἷς διεδόθη λόγος ὡς ἐπὶ τὰς ἵππους τὰς βασιλικὰς εἰς τὴν Σικυωνίαν ἔξοδος ἔσοιτο. καὶ προεπέμφθησαν οἱ πολλοὶ σποράδες ἐπὶ τὸν Πολυγνώτου πύργον, ἐκεῖ κελευσθέντες περιμεῖναι. προεπέμφθη δὲ καὶ Καφισίας ὑπ’ αὐτοῦ μετὰ τεσσάρων ἄλλων εὔζωνος, οὓς ἔδει πρὸς τὸν κηπουρὸν ἀφικέσθαι σκοταίους, φάσκοντας ὁδοιπόρους εἶναι, καὶ καταυλισαμένους αὐτόν τε συγκλεῖσαι καὶ τοὺς κύνας· οὐ γὰρ ἦν ἄλλῃ παρελθεῖν. τὰς δὲ κλίμακας διαλυτὰς οὔσας ἐμβαλόντες εἰς ἀχάνας καὶ κατακαλύψαντες ἐφ’ ἁμαξῶν προαπέστειλαν.", "st": "Arat. 6.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ κατασκόπων τινῶν ἐν Ἄργει τοῦ Νικοκλέους φανέντων καὶ περιιέναι λεγομένων ἀδήλως καὶ παραφυλάττειν τὸν Ἄρατον, ἅμ’ ἡμέρᾳ προελθὼν καὶ φανερὸς ὢν ἐν ἀγορᾷ διέτριβε μετὰ τῶν φίλων εἶτ’ ἀλειψάμενος ἐν τῷ γυμνασίῳ καὶ παραλαβών τινας ἐκ τῆς παλαίστρας τῶν εἰωθότων πίνειν καὶ ῥᾳθυμεῖν μετ’ αὐτοῦ νεανίσκων ἀπῆγεν οἴκαδε· καὶ μετὰ μικρὸν ἑωρᾶτο τῶν οἰκετῶν αὐτοῦ δι’ ἀγορᾶς ὁ μὲν στεφάνους φέρων, ὁ δὲ λαμπάδας ὠνούμενος, ὁ δὲ τοῖς εἰθισμένοις παρὰ πότον ψάλλειν καὶ αὐλεῖν γυναίοις διαλεγόμενος. ταῦτα δὲ οἱ κατάσκοποι πάντα ὁρῶντες ἐξηπάτηντο καὶ πρὸς ἀλλήλους ἀναγελῶντες ἔλεγον οὐδὲν ἦν ἄρα τυράννου δειλότερον, εἰ καὶ Νικοκλῆς τηλικαύτην πόλιν ἔχων καὶ τοσαύτην δύναμιν ὀρρωδεῖ μειράκιον εἰς ἡδονὰς καὶ πότους μεθημερινοὺς τὰ τῆς φυγῆς ἐφόδια καταχρώμενον.", "st": "Arat. 6.4"}, {"sp": "N", "t": "οἱ μὲν οὖν οὕτω παραλογισθέντες ἀπηλλάγησαν· ὁ δὲ Ἄρατος εὐθὺς μετ’ ἄριστον ἐξελθὼν καὶ συνάψας πρὸς τὸν Πολυγνώτου πύργον τοῖς στρατιώταις εἰς Νεμέαν προῆγεν, ὅπου τὴν πρᾶξιν ἐξέφηνε τοῖς πολλοῖς τότε πρῶτον, ὑποσχέσεις τε καὶ παρακλήσεις ἐποιήσατο· καὶ σύνθημα παραδοὺς Ἀπόλλωνα ὑπερδέξιον προῆγεν ἐπὶ τὴν πόλιν, συμμέτρως τῇ περιφορᾷ τῆς σελήνης ἐπιταχύνων καὶ πάλιν ἀνιεὶς τὴν πορείαν, ὥστε τῷ μὲν φωτὶ χρῆσθαι καθ’ ὁδόν, ἤδη δὲ δυομένης περὶ τὸν κῆπον εἶναι πλησίον τοῦ τείχους. ἐνταῦθα Καφισίας ἀπήντησεν αὐτῷ, τῶν μὲν κυναρίων οὐ κρατήσας ἔφθη γὰρ ἀποπηδήσαντα, τὸν δὲ κηπουρὸν ἐγκεκλεικώς. ἀθύμους δὲ τοὺς πλείστους γενομένους καὶ κελεύοντας ἀπαλλάττεσθαι παρεθάρρυνεν ὁ Ἄρατος, ὡς ἀπάξων, ἂν οἱ κύνες ἄγαν ἐνοχλῶσιν αὐτοῖς. ἅμα δὲ τοὺς τὰς κλίμακας φέροντας προπέμψας, ὧν Ἔκδηλος ἡγεῖτο καὶ Μνασίθεος, αὐτὸς ἐπηκολούθει σχολαίως, ἤδη τῶν κυναρίων εὐτόνως ὑλακτούντων καὶ συμπαρατρεχόντων τοῖς περὶ τὸν Ἔκδηλον. οὐ μὴν ἀλλὰ προσέμιξάν τε τῷ τείχει καὶ προσήρεισαν τὰς κλίμακας ἀσφαλῶς. ἀναβαινόντων δὲ τῶν πρώτων, ὁ τὴν ἑωθινὴν φυλακὴν παραδιδοὺς ἐφώδευε κώδωνι, καὶ φῶτα πολλὰ καὶ θόρυβος ἦν τῶν ἐπιπορευομένων, οἱ δέ, ὥσπερ εἶχον, αὐτοῦ πτήξαντες ἐπὶ τῶν κλιμάκων τούτους μὲν οὐ χαλεπῶς ἔλαθον, ἄλλης δὲ φυλακῆς ἐναντίας ταύτῃ προσερχομένης εἰς τὸν ἔσχατον κίνδυνον ἦλθον. ὡς δὲ κἀκείνην διέφυγον παρελθοῦσαν, εὐθὺς ἀνέβαινον οἱ πρῶτοι Μνασίθεος καὶ Ἔκδηλος, καὶ τὰς ἑκατέρωθεν ὁδοὺς τοῦ τείχους διαλαβόντες ἀπέστελλον Τέχνωνα πρὸς Ἄρατον ἐπείγεσθαι κελεύοντες.", "st": "Arat. 7.1"}, {"sp": "N", "t": "ἦν δὲ οὐ πολὺ διάστημα ἀπὸ τοῦ κήπου πρὸς τὸ τεῖχος καὶ τὸν πύργον, ἐν ᾧ κύων μέγας ἐφρούρει θηρατικός. αὐτὸς μὲν οὖν οὐκ ᾔσθετο τὴν ἔφοδον, εἴτε φύσει νωθὴς ὢν, εἴτε μεθ’ ἡμέραν κατάκοπος γεγονώς. τῶν δὲ τοῦ κηπουροῦ κυναρίων κάτωθεν ἐκκαλουμένων αὐτόν ὑπεφθέγγετο τυφλὸν καὶ ἄσημον τὸ πρῶτον, εἶτα μᾶλλον ἐπέτεινε παρερχομένων. καὶ κατεῖχεν ἤδη πολὺς ὑλαγμὸς τὸ χωρίον, ὥστε τὸν πέραν φύλακα κραυγῇ μεγάλῃ πυνθάνεσθαι τοῦ κυνηγοῦ, πρός τίνα τραχέως οὕτως ὁ κύων ὑλακτεῖ, καὶ μή τι γίνεται καινότερον. ὁ δ’ ἀπὸ τοῦ πύργου αὐτῷ ἀντεφώνησε μηδὲν εἶναι δεινόν, ἀλλὰ τὸν κύνα πρὸς τὸ φῶς τῶν τειχοφυλάκων καὶ τὸν ψόφον τοῦ κώδωνος παρωξύνθαι. τοῦτο μάλιστα τοὺς Ἀράτου στρατιώτας ἐπέρρωσεν, οἰομένους τὸν κυνηγὸν ἐπικρύπτειν κοινωνοῦντα τῇ πράξει, εἶναι δὲ πολλοὺς καὶ ἄλλους ἐν τῇ πόλει τοὺς συνεργοῦντας. οὐ μὴν ἀλλὰ τῷ τείχει προσβαλόντων χαλεπὸς ἦν ὁ κίνδυνος καὶ μῆκος ἐλάμβανε, τῶν κλιμάκων κραδαινομένων εἰ μὴ καθ’ ἕνα καὶ σχολαίως ἀναβαίνοιεν ἡ δὲ ὥρα κατήπειγεν, ἤδη φθεγγομένων ἀλεκτρυόνων, καὶ ὅσον οὔπω τῶν ἐξ ἀγροῦ τι φέρειν εἰωθότων πρὸς ἀγορὰν ἐπερχομένων. διὸ καὶ σπεύδων ὁ Ἄρατος ἀνέβαινε, τεσσαράκοντα τῶν πάντων ἀναβεβηκότων πρὸ αὐτοῦ· καὶ προσδεξάμενος ἔτι τῶν κάτωθεν ὀλίγους ἐπὶ τὴν οἰκίαν τοῦ τυράννου καὶ τὸ στρατήγιον ἀνῆλθεν ἐνταῦθα γὰρ οἱ μισθοφόροι παρενυκτέρευον. ἄφνω δὲ ἐπιπεσὼν αὐτοῖς καὶ συλλαβὼν ἅπαντας, οὐδένα δὲ ἀποκτείνας, εὐθὺς διεπέμπετο πρὸς τοὺς φίλους ἀνακαλούμενος. ἕκαστον ἀπ’ οἰκίας. καὶ συνδραμόντων πανταχόθεν, ἡμέρα μὲν ὑπέλαμπεν ἤδη καὶ τὸ θέατρον ἦν ὄχλου μεστόν, ἔτι πρὸς τὴν ἄδηλον αἰωρουμένων φήμην καὶ σαφὲς οὐδὲν εἰδότων ὑπὲρ τῶν πραττομένων, πρίν γε δὴ προελθὼν ὁ κῆρυξ εἶπεν ὡς Ἄρατος ὁ Κλεινίου παρακαλεῖ τοὺς πολίτας ἐπὶ τὴν ἐλευθερίαν.", "st": "Arat. 8.1"}, {"sp": "N", "t": "τότε δὲ πιστεύσαντες ἥκειν ἃ πάλαι προσεδόκων, ὥρμησαν ἀθρόοι πρὸς τὰς θύρας τοῦ τυράννου πῦρ ἐπιφέροντες. ἤρθη δὲ φλὸξ μεγάλη καὶ καταφανὴς μέχρι Κορίνθου τῆς οἰκίας ἀναφθείσης, ὥστε θαυμάσαντας τοὺς ἐν Κορίνθῳ παρὰ μικρὸν ὁρμῆσαι πρὸς τὴν βοήθειαν. ὁ μὲν οὖν Νικοκλῆς ἔλαθε διά τινων ὑπονόμων ὑπεκδὺς καὶ ἀποδρὰς ἐκ τῆς πόλεως, οἱ δὲ στρατιῶται καταπαύσαντες μετὰ τῶν Σικυωνίων τὸ πῦρ διήρπαζον τὴν οἰκίαν. καὶ οὔτε ταῦτα ἐκώλυσεν ὁ Ἄρατος, τά τε λοιπὰ χρήματα τῶν τυράννων εἰς μέσον ἔθηκε τοῖς πολίταις. ἀπέθανε δὲ οὐδεὶς οὐδὲ ἐτρώθη τὸ παράπαν τῶν ἐπελθόντων οὐδὲ τῶν πολεμίων, ἀλλὰ καθαρὰν καὶ ἄθικτον αἵματος ἐμφυλίου τὴν πρᾶξιν ἡ τύχη διεφύλαξε.", "st": "Arat. 9.1"}, {"sp": "N", "t": "κατήγαγε δὲ φυγάδας τοὺς μὲν ὑπὸ Νικοκλέους ἐκπεπτωκότας ὀγδοήκοντα, τοὺς δὲ ἐπὶ τῶν ἔμπροσθεν τυράννων οὐκ ἐλάττους πεντακοσίων, οἷς μακρὰ μὲν ἡ πλάνη καὶ ὁμοῦ τι πεντηκονταετὴς ἐγεγόνει. κατελθόντες δὲ οἱ πλεῖστοι πένητες, ὧν κύριοι πρότερον ἦσαν ἐπελαμβάνοντο, καὶ βαδίζοντες ἐπὶ τὰ χωρία καὶ τὰς οἰκίας δεινὴν ἀπορίαν τῷ Ἀράτῳ παρεῖχον, ἐπιβουλευομένην μὲν ἔξωθεν καὶ φθονουμένην ὑπ’ Ἀντιγόνου τὴν πόλιν ὁρῶντι διά τὴν ἐλευθερίαν, ταραττομένην δὲ ὑφ’ αὑτῆς καὶ στασιάζουσαν.", "st": "Arat. 9.3"}, {"sp": "N", "t": "ὅθεν ἐκ τῶν παρόντων ἄριστα κρίνας προσέμιξεν αὐτὴν φέρων τοῖς Ἀχαιοῖς· καὶ Δωριεῖς ὄντες ὑπέδυσαν ἑκουσίως ὄνομα καὶ πολιτείαν τὴν Ἀχαιῶν οὔτε ἀξίωμα λαμπρὸν οὔτε μεγάλην ἰσχὺν ἐχόντων τότε. μικροπολῖται γὰρ ἦσαν οἱ πολλοί, καὶ γῆν οὔτε χρηστὴν οὔτε ἄφθονον ἐκέκτηντο, καὶ θαλάττῃ προσῴκουν ἀλιμένῳ, τὰ πολλὰ κατὰ ῥαχίας ἐκφερομένῃ πρὸς τὴν ἤπειρον. ἀλλὰ μάλιστα δὴ διέδειξαν οὗτοι τὴν Ἑλληνικὴν ἀλκὴν ἀπρόσμαχον οὖσαν, ὁσάκις τύχοι κόσμου καὶ συντάξεως ὁμοφρονούσης καὶ νοῦν ἔχοντος ἡγεμόνος, οἳ τῆς μὲν πάλαι τῶν Ἑλλήνων ἀκμῆς οὐδὲν, ὡς εἰπεῖν, μέρος ὄντες, ἐν δὲ τῷ τότε μιᾶς ἀξιολόγου πόλεως σύμπαντες ὁμοῦ δύναμιν οὐκ ἔχοντες, εὐβουλίᾳ καὶ ὁμονοίᾳ, καὶ ὅτι τῷ πρώτῳ κατ’ ἀρετὴν ἐδύναντο μὴ φθονεῖν, ἀλλὰ πείθεσθαι καὶ ἀκολουθεῖν, οὐ μόνον αὑτοὺς ἐν μέσῳ πόλεων καὶ δυνάμεων τηλικούτων καὶ τυραννίδων διεφύλαξαν ἐλευθέρους, ἀλλὰ καὶ τῶν ἄλλων Ἑλλήνων ὡς πλείστους ἐλευθεροῦντες καὶ σῴζοντες διετέλουν.", "st": "Arat. 9.4"}, {"sp": "N", "t": "ἦν δὲ Ἄρατος τῷ τρόπῳ πολιτικός, μεγαλόφρων, ἀκριβέστερος εἰς τὰ κοινὰ μᾶλλον τῶν ἰδίων, πικρῶς μισοτύραννος, ἔχθρας ὅρῳ καὶ φιλίας ἀεὶ τῷ κοινῷ συμφέροντι χρώμενος. ὅθεν οὐχ οὕτως δοκεῖ γεγονέναι φίλος ἀκριβής, ὡς ἐχθρὸς εὐγνώμων καὶ πρᾶος, ὑπὸ τῆς πολιτείας ἐπ’ ἀμφότερα τῷ καιρῷ μεταβαλλόμενος, ὁμονοίας ἐθνῶν καὶ κοινωνίας πόλεων καὶ συνεδρίου καὶ θεάτρου μίαν φωνὴν ἀφιέντος ὡς οὐδενὸς ἄλλου τῶν καλῶν ἐραστής, πολέμῳ καὶ ἀγῶνι χρήσασθαι φανερῶς ἀθαρσὴς καὶ δύσελπις, κλέψαι δὲ πράγματα καὶ συσκευάσασθαι κρύφα πόλεις καὶ τυράννους ἐπηβολώτατος. διὸ καὶ πολλὰ τῶν ἀνελπίστων κατορθώσας ἐν οἷς ἐτόλμησεν, οὐκ ἐλάττονα δοκεῖ τῶν δυνατῶν ἐγκαταλιπεῖν δι’ εὐλάβειαν. οὐ γὰρ μόνον, ὡς ἔοικε, θηρίων τινῶν ὄψεις ἐνεργοὶ διὰ σκότους οὖσαι μεθ’ ἡμέραν ἀποτυφλοῦνται ξηρότητι καὶ λεπτότητι τῆς περὶ τὸν ὀφθαλμὸν ὑγρότητος μὴ φερούσης τὴν πρὸς τὸ φῶς σύγκρασιν, ἀλλὰ καὶ δεινότης τίς ἐστιν ἀνθρώπου καὶ σύνεσις ἐν τοῖς ὑπαίθροις καὶ διακεκηρυγμένοις εὐτάρακτος φύσει, πρὸς δὲ τὰς ἐπικρύφους καὶ λαθραίους ἀναθαρσοῦσα πράξεις. τὴν δὲ τοιαύτην ἀνωμαλίαν ἔνδεια λόγου φιλοσόφου περὶ τὰς εὐφυΐας ἀπεργάζεται, τὴν ἀρετὴν, ὥσπερ καρπὸν αὐτοφυῆ καὶ ἀγεώργητον, ἐκφερούσας δίχα τῆς ἐπιστήμης, ταῦτα μὲν οὖν ἐξεταζέσθω τοῖς παραδείγμασιν.", "st": "Arat. 10.1"}, {"sp": "N", "t": "ὁ δὲ Ἄρατος, ἐπεὶ κατέμιξε τοῖς Ἀχαιοῖς ἑαυτὸν καὶ τὴν πόλιν, ἐν τοῖς ἱππεῦσι στρατευόμενος ἠγαπᾶτο δι’ εὐπείθειαν ὑπὸ τῶν ἀρχόντων, ὅτι, καίπερ συμβολὰς τῷ κοινῷ μεγάλας δεδωκὼς τὴν ἑαυτοῦ δόξαν καὶ τὴν τῆς πατρίδος δύναμιν, ὡς ἑνὶ τῶν ἐπιτυχόντων χρῆσθαι παρεῖχεν αὑτῷ τὸν ἀεὶ στρατηγοῦντα τῶν Ἀχαιῶν, εἴτε Δυμαῖος, εἴτε Τριταιεὺς, εἴτε μικροτέρας τινὸς ὢν τύχοι πόλεως. ἧκε δὲ αὐτῷ καὶ χρημάτων δωρεὰ παρὰ τοῦ βασιλέως πέντε καὶ εἴκοσι τάλαντα, ταῦτα ἔλαβε μὲν ὁ Ἄρατος, λαβὼν δὲ τοῖς ἑαυτοῦ πολίταις ἐπέδωκεν ἀπορουμένοις εἴς τε τἆλλα καὶ λύτρωσιν αἰχμαλώτων.", "st": "Arat. 11.1"}, {"sp": "N", "t": "ἐπεὶ δὲ οἱ φυγάδες ἦσαν ἀπαρηγόρητοι τοῖς ἔχουσι τὰς κτήσεις ἐνοχλοῦντες, ἥ τε πόλις ἐκινδύνευεν ἀνάστατος γενέσθαι, μίαν ὁρῶν ἐλπίδα τὴν Πτολεμαίου φιλανθρωπίαν ὥρμησεν ἐκπλεῦσαι καὶ δεηθῆναι τοῦ βασιλέως ὅπως αὐτῷ χρήματα συμβάληται πρὸς τὰς διαλύσεις. ἀνήχθη μὲν οὖν ἀπὸ Μοθώνης ὑπὲρ Μαλέας, ὡς τῷ διὰ πόρου δρόμῳ χρησόμενος. πρὸς δὲ μέγα πνεῦμα καὶ πολλὴν θάλασσαν ἐκ πελάγους κατιοῦσαν ἐνδόντος τοῦ κυβερνήτου, παραφερόμενος μόλις ἥψατο τῆς Ἀδρίας πολεμίας οὔσης, ἐκρατεῖτο γὰρ ὑπὸ Ἀντιγόνου καὶ φυλακὴν εἶχεν· ἣν φθάσας ἀπέβη, καὶ τὴν ναῦν καταλιπὼν ἀπεχώρησε μακρὰν ἀπὸ θαλάσσης ἔχων ἕνα τῶν φίλων σὺν αὑτῷ Τιμάνθην. καὶ καταβαλόντες ἑαυτοὺς εἴς τινα τόπον ὕλης γέμοντα χαλεπῶς ἐνυκτέρευον. ὀλίγῳ δὲ ὕστερον ὁ φρούραρχος ἐπελθὼν καὶ ζητῶν τὸν Ἄρατον ὑπὸ τῶν θεραπόντων ἐξηπατήθη τῶν ἐκείνου, δεδιδαγμένων λέγειν ὡς εὐθὺς ἀποδρὰς εἰς Εὔβοιαν ἐξέπλευσε. τὰ μέντοι κομιζόμενα καὶ τὴν ναῦν καὶ τοὺς θεράποντας ἀπέφηνε πολέμια καὶ κατέσχε.", "st": "Arat. 12.1"}, {"sp": "N", "t": "μετὰ δὲ ἡμέρας οὐ πολλὰς ἐν ἀπόροις ὄντι τῷ Ἀράτῳ γίνεταί τις εὐτυχία, Ῥωμαϊκῆς νεὼς παραβαλούσης κατὰ τὸν τόπον ἐν ᾧ τὰ μὲν ἐπὶ σκοπὴν ἀνιών, τὰ δὲ κρυπτόμενος διῆγεν. ἔπλει μὲν οὖν ἡ ναῦς εἰς Συρίαν, ἐπέβη δὲ πείσας τὸν ναύκληρον ἄχρι Καρίας διακομισθῆναι· καὶ διεκομίσθη κινδύνοις αὖθις οὐκ ἐλάττοσι χρησάμενος κατὰ θάλατταν. ἐκ δὲ Καρίας χρόνῳ πολλῷ περαιωθεὶς εἰς Αἴγυπτον αὐτόθεν τε τῷ βασιλεῖ διακειμένῳ πρὸς αὐτὸν οἰκείως ἐνέτυχε, καὶ τεθεραπευμένῳ γραφαῖς καὶ πίναξιν ἀπὸ τῆς Ἑλλάδος, ἐν οἷς κρίσιν ἔχων οὐκ ἄμουσον ὁ Ἄρατος ἀεί τι τῶν τεχνικῶν καὶ περιττῶν, μάλιστα δὲ Παμφίλου καὶ Μελάνθου, συνάγων καὶ κτώμενος ἀπέστελλεν.", "st": "Arat. 12.4"}, {"sp": "N", "t": "ἤνθει γὰρ ἔτι δόξα τῆς Σικυωνίας μούσης καὶ χρηστογραφίας, ὡς μόνης ἀδιάφθορον ἐχούσης τὸ καλόν, ὥστε καὶ Ἀπελλῆν ἐκεῖνον ἤδη θαυμαζόμενον ἀφικέσθαι καὶ συγγενέσθαι τοῖς ἀνδράσιν ἐπὶ ταλάντῳ, τῆς δόξης μᾶλλον ἢ τῆς τέχνης δεόμενον μεταλαβεῖν. διὸ τὰς μὲν ἄλλας εἰκόνας τῶν τυράννων ἀνεῖλεν εὐθὺς ὁ Ἄρατος, ὅτε τὴν πόλιν ἠλευθέρωσε, περὶ δὲ τῆς Ἀριστράτου κατὰ Φίλιππον ἀκμάσαντος ἐβουλεύσατο πολὺν χρόνον. ἐγράφη μὲν γὰρ ὑπὸ πάντων τῶν περὶ τὸν Μέλανθον ἅρματι νικηφόρῳ παρεστὼς ὁ Ἀρίστρατος, Ἀπελλοῦ συνεφαψαμένου τῆς γραφῆς, ὡς Πολέμων ὁ περιηγητὴς ἱστόρηκεν. ἦν δὲ τὸ ἔργον ἀξιοθέατον, ὥστε γνάμπτεσθαι τὸν Ἄρατον ὑπὸ τῆς τέχνης, αὖθίς τε μίσει τῷ πρὸς τοὺς τυράννους ἐξαγόμενον κελεύειν καθαιρεῖν. τὸν οὖν ζωγράφον Νεάλκη φίλον ὄντα τοῦ Ἀράτου παραιτεῖσθαί φασι καὶ δακρύειν, ὡς δ’ οὐκ ἔπειθεν, εἰπεῖν ὅτι τοῖς τυράννοις πολεμητέον, οὐ τοῖς τῶν τυράννων. ἐάσωμεν οὖν τὸ ἅρμα καὶ τὴν Νίκην, αὐτὸν δέ σοι παρέξω τὸν Ἀρίστρατον ἐγὼ παραχωροῦντα τοῦ πίνακος ἐπιτρέψαντος οὖν τοῦ Ἀράτου διήλειψεν ὁ Νεάλκης τὸν Ἀρίστρατον, εἰς δὲ τὴν χώραν φοίνικα μόνον ἐνέγραψεν, ἄλλο δὲ οὐδὲν ἐτόλμησε παραβαλεῖν. τοὺς δὲ πόδας ἐξαλειφομένου τοῦ Ἀριστράτου διαλαθεῖν ὑπὸ τὸ ἅρμα λέγουσιν.", "st": "Arat. 13.1"}, {"sp": "N", "t": "ἔκ τε δὴ τούτων ὁ Ἄρατος ἠγαπᾶτο, καὶ διδοὺς πεῖραν ἔτι μᾶλλον ἥψατο τοῦ βασιλέως, καὶ δωρεὰν ἔλαβε τῇ πόλει πεντήκοντα καὶ ἑκατὸν τάλαντα, καὶ τούτων τεσσαράκοντα μὲν εὐθὺς μεθ’ ἑαυτοῦ κομίζων εἰς Πελοπόννησον κατῆρε, τὰ δὲ λοιπὰ διελὼν εἰς δόσεις ὁ βασιλεὺς ὕστερον κατά μέρος ἀπέστειλεν.", "st": "Arat. 13.4"}, {"sp": "N", "t": "ἦν μὲν οὖν μέγα καὶ τὸ χρήματα τοσαῦτα πορίσαι τοῖς πολίταις, ὅσων μικρὸν μέρος ἄλλοι στρατηγοὶ καὶ δημαγωγοὶ λαμβάνοντες παρὰ βασιλέων ἠδίκουν καὶ κατεδουλοῦντο καὶ προέπινον αὐτοῖς τὰς πατρίδας, μείζων δὲ ἡ διὰ τῶν χρημάτων τούτων κατασκευασθεῖσα τοῖς μὲν ἀπόροις πρὸς τοὺς πλουσίους διάλυσις καὶ ὁμόνοια, τῷ δὲ δήμῳ παντὶ σωτηρία καὶ ἀσφάλεια, θαυμαστὴ δὲ ἡ τοῦ ἀνδρὸς ἐν δυνάμει τοσαύτῃ μετριότης. ἀποδειχθεὶς γὰρ αὐτοκράτωρ διαλλακτὴς καὶ κύριος ὅλως ἐπὶ τὰς φυγαδικὰς οἰκονομίας μόνος οὐχ ὑπέμεινεν, ἀλλὰ πεντεκαίδεκα τῶν πολιτῶν προσκατέλεξεν ἑαυτῷ, μεθ’ ὧν πόνῳ πολλῷ καὶ μεγάλαις πραγματείαις κατειργάσατο καὶ συνήρμοσε φιλίαν καὶ εἰρήνην τοῖς πολίταις. ἐφ’ οἷς οὐ μόνον κοινῇ σύμπαντες οἱ πολῖται τιμὰς ἀπέδοσαν αὐτῷ πρεπούσας, ἀλλὰ καὶ κατ’ ἰδίαν οἱ φυγάδες εἰκόνα χαλκῆν ἀναστήσαντες ἐπέγραψαν τόδε τὸ ἐλεγεῖον·", "st": "Arat. 14.1"}, {"sp": "N", "t": "βουλαὶ μὲν καὶ ἄεθλα καὶ ἁ περὶ Ἑλλάδος ἀλκά<br>τοῦδ’ ἀνδρὸς στάλαις πλάθεται Ἡρακλέους·<br>ἄμμες δ’ εἰκόν’, Ἄρατε, τεὰν νόστοιο τυχόντες<br>στάσαμεν ἀντ’ ἀρετᾶς ἠδὲ δικαιοσύνας<br>σωτῆρος σωτῆρσι θεοῖς, ὅτι πατρίδι τᾷ σᾷ<br>δαιμόνιον θείαν τ’ ὤπασας εὐνομίαν.", "st": "Arat. 14.3"}, {"sp": "N", "t": "ταῦτα διαπραξάμενος ὁ Ἄρατος τοῦ μὲν πολιτικοῦ φθόνου μείζων ἐγεγόνει διὰ τὰς χάριτας, Ἀντίγονος δ’ ὁ βασιλεὺς ἀνιώμενος ἐπ’ αὐτῷ καὶ βουλόμενος ἢ μετάγειν ὅλως τῇ φιλίᾳ πρὸς αὑτὸν ἢ διαβάλλειν πρὸς τὸν Πτολεμαῖον, ἄλλας τε φιλανθρωπίας ἐνεδείκνυτο μὴ πάνυ προσιεμένῳ, καὶ θύων θεοῖς ἐν Κορίνθῳ μερίδας εἰς Σικυῶνα τῷ Ἀράτῳ διέπεμπε. καὶ παρὰ τὸ δεῖπνον, ἑστιωμένων πολλῶν, εἰς μέσον φθεγξάμενος, ᾬμην, ἔφη, τὸν Σικυώνιον τοῦτον νεανίσκον ἐλευθέριον εἶναι τῇ φύσει μόνον καὶ φιλοπολίτην· ὁ δὲ καὶ βίων ἔοικε καὶ πραγμάτων βασιλικῶν ἱκανὸς εἶναι κριτής, πρότερον γὰρ ἡμᾶς ὑπερεώρα ταῖς ἐλπίσιν ἔξω βλέπων καὶ τὸν Αἰγύπτιον ἐθαύμαζε πλοῦτον, ἐλέφαντας καὶ στόλους καὶ αὐλὰς ἀκούων, νυνὶ δὲ ὑπὸ σκηνὴν ἑωρακὼς πάντα τὰ ἐκεῖ πράγματα τραγῳδίαν ὄντα καὶ σκηνογραφίαν ὅλος ἡμῖν προσκεχώρηκεν. αὐτός τε οὖν ἀποδέχομαι τὸ μειράκιον ἐγνωκὼς εἰς ἅπαντα χρῆσθαι, καὶ ὑμᾶς ἀξιῶ φίλον νομίζειν. τούτους τοὺς λόγους ὑπόθεσιν λαβόντες οἱ φθονεροὶ καὶ κακοήθεις διημιλλῶντο ταῖς ἐπιστολαῖς ἀλλήλοις, πολλὰ καὶ δυσχερῆ κατὰ τοῦ Ἀράτου τῷ Πτολεμαίῳ γράφοντες, ὥστε κἀκεῖνον ἐγκαλοῦντα πέμψαι. ταῖς μὲν οὖν περιμαχήτοις καὶ διαπύροις τοξευομέναις ἔρωσι φιλίαις βασιλέων καὶ τυράννων τοσοῦτον προσῆν φθόνου καὶ κακοηθείας.", "st": "Arat. 15.1"}, {"sp": "N", "t": "ὁ δὲ Ἄρατος αἱρεθεὶς στρατηγὸς τὸ πρῶτον ὑπὸ τῶν Ἀχαιῶν τὴν μὲν ἀντιπέρας Λοκρίδα καὶ Καλυδωνίαν ἐπόρθησε, Βοιωτοῖς δὲ μετὰ μυρίων στρατιωτῶν βοηθῶν ὑστέρησε τῆς μάχης, ἣν ὑπὸ Αἰτωλῶν περὶ Χαιρώνειαν ἡττήθησαν, Ἀβοιωκρίτου τε τοῦ βοιωτάρχου καὶ χιλίων σὺν αὐτῷ πεσόντων. ἐνιαυτῷ δὲ ὕστερον αὖθις στρατηγῶν ἐνίστατο τὴν περὶ τὸν Ἀκροκόρινθον πρᾶξιν, οὐ Σικυωνίων οὐδ’ Ἀχαιῶν κηδόμενος, ἀλλὰ κοινήν τινα τῆς Ἑλλάδος ὅλης τυραννίδα, τὴν Μακεδόνων φρουράν, ἐκεῖθεν ἐξελάσαι διανοούμενος. Χάρης μὲν γὰρ ὁ Ἀθηναῖος ἔν τινι μάχῃ πρὸς τοὺς βασιλέως στρατηγοὺς εὐτυχήσας ἔγραψε τῷ δήμῳ τῶν Ἀθηναίων ὡς νενικήκοι τῆς ἐν Μαραθῶνι μάχης ἀδελφήν ταύτην δὲ τὴν πρᾶξιν οὐκ ἂν ἁμάρτοι τις ἀδελφήν προσειπὼν τῆς Πελοπίδου τοῦ Θηβαίου καὶ Θρασυβούλου τοῦ Ἀθηναίου τυραννοκτονίας, πλὴν ὅτι τῷ μὴ πρὸς Ἕλληνας, ἀλλὰ ἐπακτὸν ἀρχὴν γεγονέναι καὶ ἀλλόφυλον αὕτη διήνεγκεν. ὁ μὲν γὰρ Ἰσθμός ἐμφράσσων τὰς θαλάσσας, εἰς ταὐτὸ συνάγει τὼ τόπῳ καὶ συνάπτει τὴν ἤπειρον ἡμῶν, ὁ δὲ Ἀκροκόρινθος, ὑψηλὸν ὄρος, ἐκ μέσης ἀναπεφυκὼς τῆς Ἑλλάδος, ὅταν λάβῃ φρουράν, ἐνίσταται καὶ ἀποκόπτει τὴν ἐντὸς Ἰσθμοῦ πᾶσαν ἐπιμιξιῶν τε καὶ παρόδων καὶ στρατειῶν ἐργασίας τε κατὰ γῆν καὶ κατὰ θάλατταν, καὶ ἕνα κύριον ποιεῖ τὸν ἄρχοντα καὶ κατέχοντα φρουρᾷ τὸ χωρίον, ὥστε μὴ παίζοντα δοκεῖν τὸν νεώτερον Φίλιππον, ἀλλ’ ἀληθῶς, ἑκάστοτε πέδας τῆς Ἑλλάδος τὴν Κορινθίων πόλιν προσαγορεύειν.", "st": "Arat. 16.1"}, {"sp": "N", "t": "πᾶσι μὲν οὖν περιμάχητος ἦν ὁ τόπος ἀεὶ καὶ βασιλεῦσι καὶ δυνάσταις, ἡ δὲ Ἀντιγόνου σπουδὴ περὶ αὐτὸν οὐδὲν ἀπέλιπε πάθει τῶν ἐμμανεστάτων ἐρώτων, ἀλλ’ ὅλος ἀνήρτητο ταῖς φροντίσιν ὅπως ἀφαιρήσεται δόλῳ τοὺς ἔχοντας, ἐπεὶ φανερῶς ἀνέλπιστος ἦν ἡ ἐπιχείρησις. Ἀλεξάνδρου γὰρ, ὑφ’ ὃν τὸ χωρίον ἦν, ἀποθανόντος ὡς λέγεται φαρμάκοις ὑπ’ αὐτοῦ, Νικαίας δὲ τῆς ἐκείνου γυναικὸς ἐπὶ τῶν πραγμάτων γενομένης καὶ φυλαττούσης τὸν Ἀκροκόρινθον, εὐθὺς ὑποπέμπων Δημήτριον τὸν υἱὸν αὐτῇ, καὶ γλυκείας ἐλπίδας ἐνδιδοὺς γάμων βασιλικῶν καὶ συμβιώσεως πρὸς οὐκ ἀηδὲς ἐντυχεῖν γυναικὶ πρεσβυτέρᾳ μειράκιον, αὐτὴν μὲν ᾑρήκει, τῷ παιδὶ χρησάμενος ὥσπερ ἄλλῳ τινὶ τῶν δελεασμάτων ἐπ’ αὐτῇ, τὸν δὲ τόπον οὐ προϊεμένης, ἀλλ’ ἐγκρατῶς φυλαττούσης, ἀμελεῖν προσποιούμενος ἔθυε γάμους αὐτῶν ἐν Κορίνθῳ, καὶ θέας ἐπετέλει καὶ πότους συνῆγε καθ’ ἡμέραν, ὡς ἄν τις μάλιστα παίζειν καὶ σχολάζειν τὴν διάνοιαν ὑφ’ ἡδονῆς καὶ φιλοφροσύνης ἀφεικώς. ἐπεὶ δὲ καιρὸς ἦν, ᾄδοντος Ἀμοιβέως ἐν τῷ θεάτρῳ, παρέπεμπε τὴν Νίκαιαν αὐτὸς ἐπὶ τὴν θέαν ἐν φορείῳ κεκοσμημένῳ βασιλικῶς, ἀγαλλομένην τε τῇ τιμῇ καὶ πορρωτάτω τοῦ μέλλοντος οὖσαν. γενόμενος δὲ τῆς ὁδοῦ κατὰ τὴν ἐκτροπὴν τὴν ἄνω φέρουσαν, ἐκείνην μὲν ἐκέλευσε προάγειν εἰς τὸ θέατρον, αὐτὸς δὲ χαίρειν μὲν Ἀμοιβέα, χαίρειν δὲ τοὺς γάμους ἐάσας ἀνῄει πρὸς τὸν Ἀκροκόρινθον ἁμιλλώμενος παρ’ ἡλικίαν καὶ κεκλεισμένην τὴν πύλην εὑρών, ἔκοπτε τῇ βακτηρίᾳ κελεύων ἀνοίγειν. οἱ δ’ ἔνδον ἀνέῳξαν καταπλαγέντες. οὕτω δὲ τοῦ τόπου κρατήσας, οὐ κατέσχεν αὑτόν, ἀλλ’ ἔπινε παίζων ὑπὸ χαρᾶς ἐν τοῖς στενωποῖς, καὶ δι’ ἀγορᾶς αὐλητρίδας ἔχων καὶ στεφάνους περικείμενος, ἀνὴρ γέρων καὶ τηλικαύταις πραγμάτων μεταβολαῖς κεχρημένος, ἐκώμαζε δεξιούμενος καὶ προσαγορεύων τοὺς ἀπαντῶντας, οὕτως ἄρα καὶ λύπης καὶ φόβου μᾶλλον ἐξίστησι καὶ σάλον παρέχει τῇ ψυχῇ τὸ χαίρειν ἄνευ λογισμοῦ παραγινόμενον.", "st": "Arat. 17.1"}, {"sp": "N", "t": "ἀλλὰ γὰρ Ἀντίγονος μὲν, ὥσπερ εἴρηται, κτησάμενος τὸν Ἀκροκόρινθον ἐφύλαττε, μετὰ τῶν ἄλλων οἷς ἐπίστευε μάλιστα καὶ Περσαῖον ἐπιστήσας ἄρχοντα τὸν φιλόσοφον. ὁ δὲ Ἄρατος ἔτι μὲν καὶ Ἀλεξάνδρου ζῶντος ἐπεχείρησε τῇ πράξει, γενομένης δὲ συμμαχίας τοῖς Ἀχαιοῖς πρὸς τὸν Ἀλέξανδρον ἐπαύσατο. τότε δὲ αὖθις ἐξ ὑπαρχῆς ἑτέραν ἔλαβε τῆς πράξεως ὑπόθεσιν τοιαύτην.", "st": "Arat. 18.1"}, {"sp": "N", "t": "ἦσαν ἐν Κορίνθῳ τέσσαρες ἀδελφοὶ Σύροι τὸ γένος, ὧν εἷς ὄνομα Διοκλῆς ἐν τῷ φρουρίῳ μισθοφορῶν διέτριβεν. οἱ δὲ τρεῖς κλέψαντες βασιλικὸν χρυσίον ἦλθον εἷς Σικυῶνα πρὸς Αἰγίαν τινὰ τραπεζίτην, ᾧ διὰ τὴν ἐργασίαν ὁ Ἄρατος ἐχρῆτο. καὶ μέρος μὲν εὐθὺς διέθεντο τοῦ χρυσίου, τὸ δὲ λοιπὸν εἷς αὐτῶν Ἐργῖνος ἐπιφοιτῶν ἡσυχῇ κατήλλαττεν. ἐκ δὲ τούτου γενόμενος τῷ Αἰγίᾳ συνήθης, καὶ προαχθεὶς εἷς λόγον ὑπ’ αὐτοῦ περὶ τῆς φρουρᾶς, ἔφη πρὸς τὸν ἀδελφὸν ἀναβαίνων πρὸς τὸ κρημνῶδες ἐντομὴν καθεωρακέναι πλαγίαν, ἄγουσαν ᾗ χθαμαλώτατον ἐπῳκοδόμηται τῷ φρουρίῳ τὸ τεῖχος, προσπαίξαντος δὲ αὐτῷ τοῦ Αἰγίου καὶ εἰπόντος· εἶτα, ὦ βέλτιστε, διὰ μικρὸν οὕτω χρυσίου ἀνασπᾶτε τὰς βασιλικὰς πράξεις, δυνάμενοι μίαν ὥραν πολλῶν ἀποδόσθαι χρημάτων; ἢ γὰρ οὐχὶ καὶ τοιχωρύχοις καὶ προδόταις ἁλοῦσιν ἅπαξ ἀποθανεῖν ὑπάρχει; γελάσας ὁ Ἐργῖνος τότε μὲν ὡμολόγησεν ἀποπειρᾶσθαι τοῦ Διοκλέους τοῖς γὰρ ἄλλοις ἀδελφοῖς μὴ πάνυ τι πιστεύειν, ὀλίγαις δὲ ὕστερον ἡμέραις ἐπανελθὼν συντίθεται τὸν Ἄρατον ἄξειν πρὸς τὸ τεῖχος, ὅπου τὸ ὕψος οὐ μεῖζον ἦν πεντεκαίδεκα ποδῶν, καὶ τἆλλα συμπράξειν μετὰ τοῦ Διοκλέους.", "st": "Arat. 18.3"}, {"sp": "N", "t": "ὁ δὲ Ἄρατος ἐκείνοις μὲν ἑξήκοντα τάλαντα δώσειν κατορθώσας ὡμολόγησεν, ἢν δὲ ἀποτύχῃ, σωθῇ δὲ μετ’ ἐκείνων, οἰκίαν ἑκατέρῳ καὶ τάλαντον. ἐπεὶ δὲ ἔδει παρὰ τῷ Αἰγίᾳ τὰ ἑξήκοντα τάλαντα κεῖσθαι τοῖς περὶ τὸν Ἐργῖνον, ὁ δὲ Ἄρατος οὔτε αὐτὸς εἶχεν οὔτε ἐβούλετο δανειζόμενος αἴσθησιν ἑτέρῳ τῆς πράξεως παρασχεῖν, λαβὼν τῶν ἐκπωμάτων τὰ πολλὰ καὶ τὰ χρυσία τῆς γυναικὸς ὑπέθηκε τῷ Αἰγίᾳ πρὸς τὸ ἀργύριον. οὕτω γὰρ ἐπῆρτο τῇ ψυχῇ καὶ τοσοῦτον ἔρωτα τῶν καλῶν πράξεων εἶχεν, ὥστε τὸν Φωκίωνα καὶ τὸν Ἐπαμεινώνδαν ἐπιστάμενος Ἑλλήνων δικαιοτάτους καὶ κρατίστους γεγονέναι δοκοῦντας ἐπὶ τῷ διώσασθαι δωρεὰς μεγάλας καὶ μὴ προέσθαι χρημάτων τὸ καλόν, αὐτὸς εἰς ταῦτα δαπανᾶσθαι κρύφα καὶ προεισφέρειν, ἐν οἷς ἐκινδύνευε μόνος ὑπὲρ πάντων οὐδὲ εἰδότων τὰ πραττόμενα, ᾑρεῖτο. τίς γὰρ οὐκ ἂν θαυμάσειε καὶ συναγωνίσαιτο ἔτι νῦν τῇ μεγαλοψυχίᾳ τοῦ ἀνδρός, ὠνουμένου χρημάτων τοσούτων κίνδυνον τηλικοῦτον, καὶ τὰ τιμιώτατα δοκοῦντα τῶν κτημάτων ὑποτιθέντος, ὅπως παρεισαχθεὶς νυκτὸς εἰς τοὺς πολεμίους διαγωνίσηται περὶ τῆς ψυχῆς, ἐνέχυρον λαβὼν τὴν ἐλπίδα τοῦ καλοῦ παρ’ αὐτῶν, ἄλλο δὲ οὐδέν;", "st": "Arat. 19.1"}, {"sp": "N", "t": "οὖσαν δὲ καθ’ αὑτὴν ἐπισφαλῆ τὴν πρᾶξιν ἐπισφαλεστέραν ἐποίησεν ἁμαρτία τις εὐθὺς ἐν ἀρχῇ συμβᾶσα δι’ ἄγνοιαν. ὁ γὰρ οἰκέτης τοῦ Ἀράτου Τέχνων ἐπέμφθη μὲν ὡς μετὰ τοῦ Διοκλέους κατασκεψόμενος τὸ τεῖχος, οὔπω δ’ ἦν τῷ Διοκλεῖ πρότερον ἐντετυχηκὼς κατ’ ὄψιν, ἀλλὰ τὴν μορφὴν αὐτοῦ καὶ τὸ εἶδος δοκῶν κατέχειν ἐξ ὧν ὁ Ἐργῖνος ἐπεσήμηνεν οὐλοκόμην καὶ μελάγχρουν καὶ ἀγένειον. ἐλθὼν οὖν ὅπου συνετέτακτο, τὸν Ἐργῖνον ὡς ἀφιξόμενον μετὰ τὸν Διοκλέους ἀνέμενε πρὸ τῆς πόλεως πρὸ τοῦ καλουμένου Ὄρνιθος, ἐν δὲ τούτῳ πρῶτος ἀδελφὸς Ἐργίνου καὶ Διοκλέους ὄνομα Διονύσιος οὐ συνειδὼς τὴν πρᾶξιν οὐδὲ κοινωνῶν, ὅμοιος δὲ τῷ Διοκλεῖ, προσῄει κατὰ τύχην. ὁ δὲ Τέχνων πρὸς τὰ σημεῖα τῆς μορφῆς τῇ ὁμοιότητι κινηθείς ἠρώτησε τὸν ἄνθρωπον εἴ τι συμβόλαιον αὐτῷ πρὸς Ἐργῖνον εἴη. φήσαντος δὲ ἀδελφὸν εἶναι, παντάπασιν ὁ Τέχνων ἐπείσθη τῷ Διοκλεῖ διαλέγεσθαι καὶ μήτε τοὔνομα πυθόμενος μήτ’ ἄλλο μηδὲν προσμείνας τεκμήριον ἐμβάλλει τε τὴν δεξιὰν αὐτῷ καὶ περὶ τῶν συγκειμένων πρὸς τὸν Ἐργῖνον ἐλάλει κἀκεῖνον ἀνέκρινεν. ὁ δὲ δεξάμενος αὐτοῦ τὴν ἁμαρτίαν πανούργως ὡμολόγει τε πάντα καὶ πρὸς τὴν πόλιν ἀναστρέψας ὑπῆγεν ἀνυπόπτως διαλεγόμενος. ἤδη δὲ πλησίον ὄντος αὐτοῦ καὶ μέλλοντος ὅσον οὔπω τὸν Τέχνωνα διαλαμβάνειν, ἀπὸ τύχης αὖ πάλιν ὁ Ἐργῖνος αὐτοῖς ἀπήντησεν. αἰσθόμενος δὲ τὴν ἀπάτην καὶ τὸν κίνδυνον διὰ νεύματος ἐδήλωσε τῷ Τέχνωνι φεύγειν καὶ ἀποπηδήσαντες ἀμφότεροι δρόμῳ πρὸς τὸν Ἄρατον ἀπεσώθησαν. οὐ μὴν ἀπέκαμε ταῖς ἐλπίσιν ἐκεῖνος, ἀλλ’ ἔπεμψεν εὐθὺς τὸν Ἐργῖνον χρυσίον τε τῷ Διονυσίῳ κομίζοντα καὶ δεησόμενον αὐτοῦ σιωπᾶν. ὁ δὲ καὶ τοῦτο ἐποίησε καὶ τὸν Διονύσιον ἄγων μεθ’ ἑαυτοῦ πρὸς τὸν Ἄρατον ἦλθεν. ἐλθόντα δὲ αὐτὸν οὐκέτι διῆκαν, ἀλλὰ δήσαντες ἐφύλαττον ἐν οἰκίσκῳ κατακεκλεισμένον αὐτοὶ δὲ παρεσκευάζοντο πρὸς τὴν ἐπίθεσιν.", "st": "Arat. 20.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἦν ἕτοιμα πάντα, τὴν μὲν ἄλλην δύναμιν ἐκέλευσεν ἐπὶ τῶν ὅπλων νυκτερεύειν, ἀναλαβὼν δὲ λογάδας τετρακοσίους οὐδ’ αὐτοὺς εἰδότας τὰ πραττόμενα, πλὴν ὀλίγων, ἦγε πρὸς τὰς πύλας παρὰ τὸ Ἡραῖον. ἦν δὲ τοῦ ἔτους ἡ περὶ θέρος ἀκμάζον ὥρα, τοῦ δὲ μηνὸς πανσέληνος, ἡ δὲ νὺξ ἀνέφελος καὶ καταφανής, ὥστε καὶ φόβον τὰ ὅπλα παρέχειν ἀντιλάμποντα πρὸς τήν σελήνην, μὴ τοὺς φύλακας οὐ λάθωσιν. ἤδη δὲ τῶν πρώτων ἐγγὺς ὄντων ἀπὸ θαλάσσης ἀνέδραμε νέφη καὶ κατέσχε τήν τε πόλιν αὐτὴν καὶ τὸν ἔξω τόπον ἐπίσκιον γενόμενον, ἐνταῦθα δὲ οἱ μὲν ἄλλοι συγκαθίσαντες ὑπελύοντο τὰς κρηπῖδας οὔτε γὰρ ψόφον ποιοῦσι πολὺν οὔτε ὀλισθήματα λαμβάνουσι γυμνοῖς τοῖς ποσὶν ἀντιλαμβανόμενοι τῶν κλιμάκων ὁ δὲ Ἐργῖνος ἑπτὰ λαβὼν νεανίσκους ἐσταλμένους ὁδοιπορικῶς ἔλαθε τῇ πύλῃ προσμίξας. καὶ τὸν πυλωρὸν ἀποκτιννύουσι καὶ τοὺς μετ’ αὐτοῦ φύλακας, ἅμα δὲ αἵ τε κλίμακες προσετίθεντο καὶ κατὰ σπουδὴν ὁ Ἄρατος ὑπερβιβάσας ἑκατὸν ἄνδρας, τοὺς δ’ ἄλλους ἕπεσθαι κελεύσας ὡς ἂν δύνωνται τάχιστα, τὰς κλίμακας ἀναρπάσας ἐχώρει διὰ τῆς πόλεως μετὰ τῶν ἑκατὸν ἐπὶ τήν ἄκραν, ἤδη περιχαρὴς διὰ τὸ λανθάνειν ὡς κατορθῶν.", "st": "Arat. 21.1"}, {"sp": "N", "t": "καί πως ἔτι πρόσωθεν αὐτοῖς ἀπήντα σὺν φωτὶ φυλακὴ τεσσάρων ἀνδρῶν οὐ καθορωμένοις ἔτι γὰρ ἦσαν ἐν τῷ σκιαζομένῳ τῆς σελήνης· ἐκείνους δὲ προσιόντας ἐξ ἐναντίας καθορῶσι. μικρὸν οὖν ὑποστείλας τειχίοις τισὶ καὶ οἰκοπέδοις, ἐνέδραν ἐπὶ τοὺς ἄνδρας καθίζει, καὶ τρεῖς μὲν αὐτῶν ἐμπεσόντες ἀποθνῄσκουσιν, ὁ δὲ τέταρτος πληγεὶς ξίφει τήν κεφαλήν ἔφυγε, βοῶν ἔνδον εἶναι τοὺς πολεμίους. καὶ μετὰ μικρὸν αἵ τε σάλπιγγες ἐπεσήμαινον, ἥ τε πόλις ἐξανίστατο πρὸς τὰ γινόμενα, πλήρεις τε ἦσαν οἵ στενωποὶ διαθεόντων, καὶ φῶτα πολλὰ, τὰ μὲν κάτωθεν ἤδη, τὰ δὲ ἄνωθεν ἀπὸ τῆς ἄκρας περιέλαμπε, καὶ κραυγὴ συνερρήγνυτο πανταχόθεν ἄσημος.", "st": "Arat. 21.4"}, {"sp": "N", "t": "ἐν τούτῳ δὲ ὁ μὲν Ἄρατος ἐμφὺς τῇ πορείᾳ παρὰ τὸ κρημνῶδες ἡμιλλᾶτο, βραδέως καὶ ταλαιπώρως τὸ πρῶτον, οὐ κατακρατῶν, ἀλλ’ ἀποπλανώμενος τοῦ τρίβου παντάπασιν ἐνδεδυκότος καὶ πεοισκιαζομένου ταῖς τραχύτησι καὶ διὰ πολλῶν ἑλιγμῶν καὶ παραβολῶν περαίνοντος πρὸς τὸ τεῖχος, εἶτα θαυμάσιον οἷον ἡ σελήνη λέγεται διαστέλλουσα τὰ νέφη καὶ ὑπολαμποῦσα, τῆς ὁδοῦ τὸ χαλεπώτατον σαφηνίζειν, ἕως ἥψατο τοῦ τείχους καθ’ ὃν ἔδει τόπον· ἐκεῖ δὲ πάλιν συνεσκίασε καὶ ἀπέκρυψε νεφῶν συνελθόντων.", "st": "Arat. 22.1"}, {"sp": "N", "t": "οἱ δὲ περὶ τὰς πύλας ἔξω περὶ τὸ Ἡραῖον ἀπολειφθέντες τοῦ Ἀράτου στρατιῶται, τριακόσιοι τὸ πλῆθος ὄντες, ὥς ποτε παρεισέπεσον εἰς τὴν πόλιν θορύβου τε παντοδαποῦ καὶ φώτων γέμουσαν, οὐ δυνηθέντες ἐξανευρεῖν τὸν αὐτὸν τρίβον οὐδ’ εἰς ἴχνος ἐμβῆναι τῆς ἐκείνων πορείας, ἔπτηξαν ἀθρόοι πρός τινι παλινσκίῳ λαγόνι τοῦ κρημνοῦ συστείλαντες ἑαυτούς, καὶ διεκαρτέρουν ἐνταῦθα περιπαθοῦντες καὶ δυσανασχετοῦντες. βαλλομένων γὰρ ἀπὸ τῆς ἄκρας ἤδη τῶν περὶ τὸν Ἄρατον καὶ μαχομένων, ἀλαλαγμὸς ἐναγώνιος ἐχώρει κάτω, καὶ κραυγὴ περιήχει, διὰ τὴν ἀπὸ τῶν ὀρῶν ἀνάκλασιν συγκεχυμένη καὶ ἄδηλος ὅθεν εἴληφε τὴν ἀρχήν, διαπορούντων δὲ αὐτῶν ἐφ’ ὅ τι χρὴ τραπέσθαι μέρος, Ἀρχέλαος ὁ τῶν βασιλικῶν ἡγεμὼν στρατιώτας ἔχων πολλοὺς μετὰ κραυγῆς ἀνέβαινε καὶ σαλπίγγων, ἐπιφερόμενος τοῖς περὶ τὸν Ἄρατον, καὶ παρήλλαττε τοὺς τριακοσίους. οἱ δὲ ὥσπερ ἐξ ἐνέδρας ἀναστάντες ἐμβάλλουσιν αὐτῷ καὶ διαφθείρουσιν οἷς ἐπέθεντο πρώτοις, τοὺς δὲ ἄλλους καὶ τὸν Ἀρχέλαον φοβήσαντες ἐτρέψαντο καὶ κατεδίωξαν ἄχρι τοῦ σκεδασθῆναι περὶ τὴν πόλιν διαλυθέντας. ἄρτι δὲ τούτων νενικηκότων Ἐργῖνος ἀπὸ τῶν ἄνω μαχομένων ἦλθεν, ἀγγέλλων συμπεπλέχθαι τοῖς πολεμίοις τὸν Ἄρατον ἀμυνομένοις εὐρώστως, καὶ μέγαν ἀγῶνα περὶ αὐτὸ τὸ τεῖχος εἶναι, καὶ τάχους δεῖν τῆς βοηθείας. οἱ δὲ εὐθὺς ἐκέλευον ἡγεῖσθαι· καὶ προσβαίνοντες ἅμα φωνῇ διεσήμαινον ἑαυτούς, ἐπιθαρρύνοντες τοὺς φίλους· ἥ τε πανσέληνος ἀπέφαινε τὰ ὅπλα πλείονα φαινόμενα τοῖς πολεμίοις διὰ τὸ μῆκος τῆς πορείας, καὶ τὸ τῆς νυκτὸς ἠχῶδες τὸν ἀλαλαγμὸν ἀπὸ πολλαπλασιόνων ἢ τοσούτων ἐποίει δοκεῖν φέρεσθαι. τέλος δὲ συνερείσαντες ἐξωθοῦσι τοὺς πολεμίους καὶ καθυπέρτεροι τῆς ἄκρας ἦσαν καὶ τὸ φρούριον εἶχον, ἡμέρας ἤδη διαυγούσης, ὅ τε ἥλιος εὐθὺς ἐπέλαμπε τῷ ἔργῳ, καὶ παρῆν ἐκ Σικυῶνος ἡ λοιπὴ δύναμις τῷ Ἀράτῳ, δεχομένων κατὰ πύλας τῶν Κορινθίων προθύμως καὶ τοὺς βασιλικοὺς συλλαμβανόντων.", "st": "Arat. 22.2"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀσφαλῶς ἐδόκει πάντα ἔχειν, κατέβαινεν εἰς τὸ θέατρον ἀπὸ τῆς ἄκρας, πλήθους ἀπείρου συρρέοντος ἐπιθυμίᾳ τῆς τε ὄψεως αὐτοῦ καὶ τῶν λόγων οἷς ἔμελλε χρῆσθαι πρὸς τοὺς Κορινθίους. ἐπιστήσας δὲ ταῖς παρόδοις ἑκατέρωθεν τοὺς Ἀχαιούς, αὐτὸς ἀπὸ τῆς σκηνῆς εἰς μέσον προῆλθε, τεθωρακισμένος καὶ τῷ προσώπῳ διὰ τὸν κόπον καὶ τὴν ἀγρυπνίαν ἠλλοιωμένος, ὥστε τῆς ψυχῆς τὸ γαυρούμενον καὶ χαῖρον ὑπὸ τῆς περὶ τὸ σῶμα βαρύτητος κατακρατεῖσθαι. τῶν δὲ ἀνθρώπων ἅμα τῷ προσελθεῖν αὐτὸν ἐκχυθέντων ταῖς φιλοφροσύναις, μεταλαβὼν εἰς τὴν δεξιὰν τὸ δόρυ, καὶ τὸ γόνυ καὶ τὸ σῶμα τῇ ῥοπῇ μικρὸν ἐγκλίνας καὶ ἀπερεισάμενος, εἱστήκει πολὺν χρόνον σιωπῇ δεχόμενος αὐτῶν τοὺς κρότους καὶ τὰς ἐπιβοήσεις, ἐπαινούντων μὲν τὴν ἀρετήν, ζηλούντων δὲ τὴν τύχην. ὡς δὲ ἐπαύσαντο καὶ κατέστησαν, συναγαγὼν ἑαυτὸν διεξῆλθε λόγον ὑπὲρ τῶν ’ Ἀχαιῶν τῇ πράξει πρέποντα, καὶ συνέπεισε τοὺς Κορινθίους Ἀχαιοὺς γενέσθαι, καὶ τῶν πυλῶν τὰς κλεῖς ἀπέδωκε τότε πρῶτον ἀπὸ τῶν Φιλιππικῶν καιρῶν ὑπ’ ἐκείνοις γενομένας· τῶν δὲ Ἀντιγόνου στρατηγῶν Ἀρχέλαον μὲν ἀφῆκεν ὑποχείριον γενόμενον, Θεόφραστον δὲ ἀνεῖλεν οὐ βουλόμενον ἀπαλλάττεσθαι· Περσαῖος δὲ τῆς ἄκρας ἁλισκομένης εἰς Κεγχρεὰς διεξέπεσεν. ὕστερον δὲ λέγεται σχολάζων πρὸς τὸν εἰπόντα μόνον αὐτῷ δοκεῖν στρατηγὸν εἶναι τὸν σοφόν, ἀλλὰ νὴ θεούς, φάναι, τοῦτο μάλιστα κἀμοί ποτε τῶν Ζήνωνος ἤρεσκε δογμάτων νῦν δὲ μεταβάλλομαι νουθετηθεὶς ὑπὸ τοῦ Σικυωνίου νεανίου. ταῦτα μὲν περὶ Περσαίου πλείονες ἱστοροῦσιν.", "st": "Arat. 23.1"}, {"sp": "N", "t": "ὁ δὲ Ἄρατος εὐθὺς τό τε Ἡραῖον ὑφ’ ἑαυτῷ καὶ τὸ Λέχαιον ἐποιήσατο· καὶ νεῶν μὲν εἰκοσιπέντε βασιλικῶν ἐκυρίευσεν, ἵππους δὲ πεντακοσίους καὶ Σύρους τετρακοσίους ἀπέδοτο τόν τε Ἀκροκόρινθον ἐφύλαττον οἱ Ἀχαιοὶ τετρακοσίοις ὁπλίταις καὶ πεντήκοντα κυσὶ καὶ κυνηγοῖς ἴσοις ἐν τῷ φρουρίῳ τρεφομένοις.", "st": "Arat. 24.1"}, {"sp": "N", "t": "οἱ μὲν οὖν Ῥωμαῖοι τὸν Φιλοποίμενα θαυμάζοντες Ἑλλήνων ἔσχατον προσηγόρευον, ὡς μηδενὸς μεγάλου μετ’ ἐκεῖνον ἐν τοῖς Ἕλλησι γενομένου· ἐγὼ δὲ τῶν Ἑλληνικῶν πράξεων ταύτην ἐσχάτην καὶ νεωτάτην φαίην ἂν πεπρᾶχθαι, τοῦτο μὲν τόλμῃ, τοῦτο δὲ τύχῃ ταῖς ἀρίσταις ἐνάμιλλον, ὡς ἐδήλωσεν εὐθὺς τὰ γινόμενα. Μεγαρεῖς τε γὰρ ἀποστάντες Ἀντιγόνου τῷ Ἀράτῳ προσέθεντο, καὶ Τροιζήνιοι μετὰ Ἐπιδαυρίων συνετάχθησαν εἰς τοὺς Ἀχαιούς, ἔξοδόν τε πρώτην θέμενος εἰς τὴν Ἀττικὴν ἐνέβαλε, καὶ τὴν Σαλαμῖνα διαβὰς ἐλεηλάτησεν, ὥσπερ ἐξ εἱρκτῆς λελυμένῃ τῇ δυνάμει τῶν Ἀχαιῶν ἐφ’ ὅ τι βούλοιτο χρώμενος. Ἀθηναίοις δὲ τοὺς ἐλευθέρους ἀφῆκεν ἄνευ λύτρων, ἀρχὰς ἀποστάσεως ἐνδιδοὺς αὐτοῖς. Πτολεμαῖον δὲ σύμμαχον ἐποίησε τῶν Ἀχαιῶν, ἡγεμονίαν ἔχοντα πολέμου καὶ κατὰ γῆν καὶ θάλατταν. οὕτω δὲ ἴσχυσεν ἐν τοῖς Ἀχαιοῖς, ὥστ’, εἰ μὴ κατ’ ἐνιαυτὸν ἐξῆν, παρ’ ἐνιαυτὸν αἱρεῖσθαι στρατηγὸν αὐτόν, ἔργῳ δὲ καὶ γνώμῃ διὰ παντὸς ἄρχειν. ἑώρων γὰρ αὐτὸν οὐ πλοῦτον, οὐ δόξαν, οὐ φιλίαν βασιλικήν, οὐ τὸ τῆς αὑτοῦ πατρίδος συμφέρον, οὐκ ἄλλο τι τῆς αὐξήσεως τῶν Ἀχαιῶν ἐπίπροσθεν ποιούμενον. ἡγεῖτο γὰρ ἀσθενεῖς ἰδίᾳ τὰς πόλεις ὑπαρχούσας σῴζεσθαι δι’ ἀλλήλων ὥσπερ ἐνδεδεμένας τῷ κοινῷ συμφέροντι, καὶ καθάπερ τὰ μέρη τοῦ σώματος ζῶντα καὶ συμπνέοντα διὰ τὴν πρὸς ἄλληλα συμφυΐαν, ὅταν ἀποσπασθῇ καὶ γένηται χωρίς, ἀτροφεῖ καὶ σήπεται, παραπλησίως τὰς πόλεις ἀπόλλυσθαι μὲν ὑπὸ τῶν διασπώντων τὸ κοινόν, αὔξεσθαι δὲ ὑπ’ ἀλλήλων, ὅταν ὅλου τινὸς μεγάλου μέρη γενόμεναι κοινῆς προνοίας τυγχάνωσιν.", "st": "Arat. 24.2"}, {"sp": "N", "t": "ὁρῶν δὲ τοὺς ἀρίστους τῶν προσοίκων αὐτονομουμένους, Ἀργείοις δὲ δουλεύουσιν ἀχθόμενος, ἐπεβούλευεν ἀνελεῖν τὸν τύραννον αὐτῶν Ἀριστόμαχον, ἅμα τῇ τε πόλει θρεπτήρια τὴν ἐλευθερίαν ἀποδοῦναι φιλοτιμούμενος καὶ τοῖς Ἀχαιοῖς προσκομίσαι τὴν πόλιν· οἱ μὲν οὖν τολμῶντες εὑρέθησαν, ὧν Αἰσχύλος προειστήκει καὶ Χαριμένης ὁ μάντις ξίφη δὲ οὐκ εἶχον, ἀλλ’ ἀπείρητο κεκτῆσθαι καὶ ζημίαι μεγάλαι τοῖς κεκτημένοις ἐπῆσαν ὑπὸ τοῦ τυράννου, κατασκευάσας οὖν ὁ Ἄρατος αὐτοῖς ἐν Κορίνθῳ μικρὰς παραξιφίδας ἐνέρραψεν εἰς σάγματα· καὶ ταῦτα περιθεὶς ὑποζυγίοις σκεύη τινὰ παρημελημένα κομίζουσιν εἰς Ἄργος ἀπέστειλε. Χαριμένους δὲ τοῦ μάντεως προσλαβόντος ἐπὶ τὴν πρᾶξιν ἄνθρωπον, οἱ περὶ τὸν Αἰσχύλον ἠγανάκτησαν καὶ δι’ ἑαυτῶν ἔπραττον, τοῦ Χαριμένους καταγνόντες. αἰσθόμενος δὲ ἐκεῖνος ὀργῇ κατεμήνυσε τοὺς ἄνδρας ἤδη βαδίζοντας ἐπὶ τὸν τύραννον· ὧν οἱ πλεῖστοι φθάσαντες ἐξ ἀγορᾶς ἀπέφυγον καὶ διεξέπεσον εἰς Κόρινθον.", "st": "Arat. 25.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ χρόνου βραχέος διελθόντος ἀποθνῄσκει μὲν ὑπὸ δούλων Ἀριστόμαχος, ὑπολαμβάνει δὲ τὴν ἀρχὴν φθάσας Ἀρίστιππος, ἐξωλέστερος ἐκείνου τύραννος, ὅσοι δὴ τῶν Ἀχαιῶν ἐν ἡλικίᾳ παρόντες ἔτυχον, τούτους ἀναλαβὼν ὁ Ἄρατος ἐβοήθει πρὸς τὴν πόλιν ὀξέως, οἰόμενος εὑρήσειν τὰ τῶν Ἀργείων πρόθυμα. τῶν δὲ πολλῶν ἤδη διὰ συνήθειαν ἐθελοδούλως ἐχόντων καὶ μηδενὸς ἀφισταμένου πρὸς αὐτόν, ἀνεχώρησεν ἔγκλημα κατεσκευακὼς τοῖς Ἀχαιοῖς ὡς ἐν εἰρήνῃ πόλεμον ἐξενηνοχόσι. καὶ δίκην ἔσχον ἐπὶ τούτῳ παρὰ Μαντινεῦσιν, ἣν Ἀράτου μὴ παρόντος Ἀρίστιππος εἷλε διώκων καὶ μνῶν ἐτιμήθη τριάκοντα. τὸν δὲ Ἄρατον αὐτὸν ἅμα καὶ μισῶν καὶ δεδοικώς ἐπεβούλευεν ἀνελεῖν συνεργοῦντος Ἀντιγόνου τοῦ βασιλέως· καὶ πανταχοῦ σχεδὸν ἦσαν οἱ τοῦτο πράττοντες αὐτοῖς καὶ καιρὸν ἐπιτηροῦντες.", "st": "Arat. 25.4"}, {"sp": "N", "t": "ἀλλ’ οὐδὲν οἷον ἀληθινὴ καὶ βέβαιος εὔνοια φυλακτήριον ἀνδρὸς ἄρχοντος, ὅταν γὰρ ἐθισθῶσιν οἵ τε πολλοὶ καὶ οἱ δυνατοὶ μὴ τὸν ἡγούμενον, ἀλλ’ ὑπὲρ τοῦ ἡγουμένου δεδιέναι, πολλοῖς μὲν ὄμμασιν ὁρᾷ, διὰ πολλῶν δὲ ὤτων ἀκούει, καὶ προαισθάνεται τὰ γινόμενα … διὸ καὶ βούλομαι τὸν λόγον ἐπιστήσας ἐνταῦθά που διεξελθεῖν περὶ τῆς Ἀριστίππου διαίτης, ἣν ἡ ζηλοτυπουμένη τυραννὶς αὐτῷ καὶ ὁ τῆς μακαρίας καὶ περιβοήτου μοναρχίας ὄγκος περιέθηκεν.", "st": "Arat. 25.7"}, {"sp": "N", "t": "ἐκεῖνος γὰρ Ἀντίγονον μὲν ἔχων σύμμαχον, τρέφων δὲ πολλοὺς ἕνεκα τῆς τοῦ σώματος ἀσφαλείας, οὐδένα δὲ ἐν τῇ πόλει ζῶντα τῶν ἐχθρῶν ὑπολελοιπώς, τοὺς μὲν δορυφόρους καὶ φύλακας ἔξω παρεμβάλλειν ἐκέλευεν ἐν τῷ περιστύλῳ, τοὺς δὲ οἰκέτας, ὁπότε δειπνήσαι, τάχιστα πάντας ἐξελαύνων καὶ τὴν μέταυλον ἀποκλείων μετὰ τῆς ἐρωμένης αὐτὸς εἰς οἴκημα κατεδύετο μικρὸν ὑπερῷον, θύρᾳ καταρρακτῇ κλειόμενον· ἧς ὑπεράνω τὴν κλίνην ἐπιτιθεὶς ἐκάθευδεν, ὡς εἰκὸς καθεύδειν τὸν οὕτως ἔχοντα, ταραχωδῶς καὶ περιφόβως. τὸ δὲ κλιμάκιον ἡ τῆς ἐρωμένης μήτηρ ὑφαιροῦσα κατέκλειεν εἰς ἕτερον οἴκημα, καὶ πάλιν ἅμ’ ἡμέρᾳ προσετίθει καὶ κατεκάλει τὸν θαυμαστὸν τύραννον, ὥσπερ ἑρπετὸν ἐκ φωλεοῦ κατερχόμενον. ὁ δὲ οὐχ ὅπλοις κατὰ βίαν, νόμῳ δὲ ὑπ’ ἀρετῆς ἀκατάπαυστον ἀρχὴν περιπεποιημένος, ἐν ἱματίῳ καὶ χλαμυδίῳ τῷ τυχόντι, τῶν πώποτε τυράννων κοινὸς ἀποδεδειγμένος ἐχθρός, ἄχρι τῆς τήμερον ἡμέρας γένος εὐδοκιμώτατον ἀπολέλοιπεν ἐν τοῖς Ἕλλησιν. ἐκείνων δὲ τῶν τὰς ἄκρας καταλαμβανόντων καὶ τοὺς δορυφόρους τρεφόντων καὶ τὰ ὅπλα καὶ τὰς πύλας καὶ τοὺς καταρράκτας προβαλλομένων ὑπὲρ τῆς τοῦ σώματος ἀσφαλείας ὀλίγοι τὸν ἐκ πληγῆς θάνατον, ὥσπερ οἱ λαγωοὶ, διέφυγον οἶκος δὲ ἢ γένος ἢ τάφος ἔχων τιμωμένην μνήμην οὐδενὸς λέλειπται.", "st": "Arat. 26.1"}, {"sp": "N", "t": "πρὸς δ’ οὖν τὸν Ἀρίστιππον ὁ Ἄρατος καὶ κρύφα πολλάκις καὶ φανερῶς προσέπταισεν ἐπιχειρήσας καταλαμβάνειν τὸ Ἄργος, ἅπαξ δὲ κλίμακας προσθεὶς μετ’ ὀλίγων ἐπὶ τὸ τεῖχος ἀνέβη παραβόλως, καὶ τοὺς βοηθοῦντας ἐνταῦθα τῶν φυλάκων ἀπέκτεινεν. εἶτα ἡμέρας ἐπιφανείσης καὶ τοῦ τυράννου πανταχόθεν αὐτῷ προσβάλλοντος, οἱ μὲν Ἀργεῖοι, καθάπερ οὐχ ὑπὲρ τῆς ἐκείνων ἐλευθερίας τῆς μάχης οὔσης, ἀλλ’ ὡς τὸν ἀγῶνα τῶν Νεμείων βραβεύοντες, ἴσοι καὶ δίκαιοι θεαταὶ καθῆντο τῶν γινομένων, πολλὴν ἡσυχίαν ἄγοντες, ὁ δὲ Ἄρατος εὐρώστως ἀμυνόμενος λόγχῃ μὲν ἐκ χειρὸς διελαύνεται τὸν μηρόν, ἐκράτησε δὲ τῶν τόπων ἐν οἷς ἦν, καὶ οὐκ ἐξεώσθη μέχρι νυκτὸς ἐνοχλούμενος ὑπὸ τῶν πολεμίων. εἰ δὲ καὶ τὴν νύκτα τῷ πόνῳ προσεταλαιπώρησεν, οὐκ ἂν διήμαρτεν ὁ γὰρ τύραννος ἤδη περὶ δρασμὸν εἶχε καὶ πολλὰ τῶν ἰδίων ἐπὶ θάλασσαν προεξέπεμψε νῦν δὲ τοῦτο μὲν οὐδενὸς ἐξαγγείλαντος πρὸς τὸν Ἄρατον, ὕδατος δὲ ἐπιλιπόντος, ἑαυτῷ δὲ χρήσασθαι διὰ τὸ τραῦμα μὴ δυνάμενος, ἀπήγαγε τοὺς στρατιώτας.", "st": "Arat. 27.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ταύτην ἀπέγνω τὴν ὁδόν, ἐμβαλὼν φανερῶς τῷ στρατοπέδῳ τὴν Ἀργολίδα χώραν ἐπόρθει καὶ περὶ τὸν Χάρητα ποταμὸν ἰσχυρᾶς μάχης γενομένης πρὸς Ἀρίστιππον· αἰτίαν ἔσχεν ὡς ἐγκαταλιπὼν τὸν ἀγῶνα καὶ προέμενος τὸ νίκημα· τῆς γὰρ ἄλλης δυνάμεως ὁμολογουμένως ἐπικρατούσης καὶ τῷ διωγμῷ πολὺ προελθούσης εἰς τοὔμπροσθεν, αὐτὸς οὐχ οὕτως ἐκβιασθεὶς ὑπὸ τῶν καθ’ αὑτόν, ὡς ἀπιστῶν τῷ κατορθώματι καὶ φοβηθείς, ἀνεχώρησε τεταραγμένος εἰς τὸ στρατόπεδον. ἐπεὶ δὲ ἀπὸ τῆς διώξεως ἐπανελθόντες οἱ λοιποὶ χαλεπῶς ἔφερον ὅτι τρεψάμενοι τοὺς πολεμίους καὶ πολὺ πλείονας ἐκείνων καταβαλόντες ἢ σφῶν αὐτῶν ἀπολέσαντες παραλελοίπασι τοῖς ἡττημένοις στῆσαι κατ’ αὐτῶν τρόπαιον, αἰσχυνθεὶς πάλιν ἔγνω διαμάχεσθαι περὶ τοῦ τροπαίου, καὶ μίαν ἡμέραν διαλιπὼν αὖθις ἐξέτασσε τὴν στρατιάν. ὡς δὲ ᾔσθετο πλείονας γεγονότας καὶ θαρραλεώτερον ἀνθισταμένους τοὺς περὶ τὸν τύραννον, οὐκ ἐτόλμησεν, ἀλλ’ ἀπῆλθε τοὺς νεκροὺς ὑποσπόνδους ἀνελόμενος. οὐ μὴν ἀλλὰ τῇ περὶ τὴν ὁμιλίαν καὶ πολιτείαν ἐμπειρίᾳ καὶ χάριτι τὴν διαμαρτίαν ταύτην ἀναμαχόμενος προσηγάγετο τὰς Κλεωνὰς τοῖς Ἀχαιοῖς, καὶ τὸν ἀγῶνα τῶν Νεμείων ἤγαγεν ἐν Κλεωναῖς, ὡς πάτριον ὄντα καὶ μᾶλλον προσήκοντα τούτοις. ἤγαγον δὲ καὶ Ἀργεῖοι, καὶ συνεχύθη τότε πρῶτον ἡ δεδομένη τοῖς ἀγωνισταῖς ἀσυλία καὶ ἀσφάλεια, πάντας τῶν Ἀχαιῶν, ὅσους ἔλαβον ἠγωνισμένους ἐν Ἄργει, διὰ τῆς χώρας πορευομένους ὡς πολεμίους ἀποδομένων. οὕτω σφοδρὸς ἦν καὶ ἀπαραίτητος ἐν τῷ μισεῖν τοὺς τυράννους.", "st": "Arat. 28.1"}, {"sp": "N", "t": "ὀλίγῳ δὲ ὕστερον ἀκούσας τὸν Ἀρίστιππον ἐπιβουλεύειν μὲν ταῖς Κλεωναῖς, φοβεῖσθαι δὲ ἐκεῖνον ἐν Κορίνθῳ καθεζόμενον, ἤθροισεν ἐκ παραγγέλματος στρατείαν. καὶ σιτία κελεύσας πλειόνων ἡμερῶν κομίζειν εἰς Κεγχρεὰς κατῆλθεν, ἐκκαλούμενος δι’ ἀπάτης τὸν Ἀρίστιππον ὡς αὐτοῦ μὴ παρόντος ἐπιθέσθαι τοῖς Κλεωναίοις ὃ καὶ συνέβη, παρῆν γὰρ εὐθὺς ἐξ Ἄργους ἔχων τὴν δύναμιν. ὁ δὲ Ἄρατος εἰς Κόρινθον ἤδη σκοταῖος ἐκ Κεγχρεῶν ὑποστρέψας, καὶ τὰς ὁδοὺς φυλακαῖς διαλαβών, ἦγε τοὺς Ἀχαιοὺς ἑπομένους οὕτω μὲν εὐτάκτως, οὕτω δὲ ταχέως καὶ προθύμως ὥστε μὴ μόνον ὁδεύοντας, ἀλλὰ καὶ παρελθόντας εἰς τὰς Κλεωνὰς ἔτι νυκτὸς οὔσης καὶ συνταξαμένους ἐπὶ μάχην ἀγνοεῖσθαι καὶ λανθάνειν τὸν Ἀρίστιππον. ἅμα δὲ ἡμέρᾳ τῶν πυλῶν ἀνοιχθεισῶν καὶ τῆς σάλπιγγος ἐγκελευσαμένης, δρόμῳ καὶ ἀλαλαγμῷ προσπεσὼν τοῖς πολεμίοις εὐθὺς ἐτρέψατο, καὶ κατεῖχε διώκων ᾗ μάλιστα φεύγειν ὑπενόει τὸν Ἀρίστιππον, ἐκτροπὰς πολλὰς τῶν χωρίων ἐχόντων. γενομένης δὲ τῆς διώξεως ἄχρι Μυκηνῶν, ὁ μὲν τύραννος ὑπὸ Κρητός τινος, ὡς Δεινίας ἱστορεῖ, τοὔνομα Τραγίσκου, καταληφθεὶς ἀποσφάττεται, τῶν δὲ ἄλλων ἔπεσον ὑπὲρ χιλίους πεντακοσίους. ὁ δὲ Ἄρατος οὕτω λαμπρῶς εὐτυχήσας καὶ μηδένα τῶν αὐτοῦ στρατιωτῶν ἀποβαλών, ὅμως οὐκ ἔλαβε τὸ Ἄργος οὐδὲ ἠλευθέρωσε, τῶν περὶ Ἀγίαν καὶ τὸν νεώτερον Ἀριστόμαχον μετὰ δυνάμεως βασιλικῆς παρεισπεσόντων καὶ κατασχόντων τὰ πράγματα.", "st": "Arat. 29.1"}, {"sp": "N", "t": "τὸ μὲν οὖν πολὺ τῆς διαβολῆς καὶ λόγους καὶ σκώμματα καὶ βωμολοχίας παρείλετο τῶν κολακευόντων τοὺς τυράννους καὶ διεξιόντων, ἐκείνοις χαριζομένων, ὡς τοῦ στρατηγοῦ τῶν Ἀχαιῶν ἐκταράττοιτο μὲν ἡ κοιλία παρὰ τὰς μάχας, κάρος δὲ προσπίπτοι καὶ ἴλιγγος ἅμα τῷ παραστῆναι τὸν σαλπιγκτήν, ἐκτάξας δὲ τὴν δύναμιν καὶ τὸ σύνθημα παρεγγυήσας, καὶ πυθόμενος τῶν ὑποστρατήγων καὶ λοχαγῶν, μή τις αὐτοῦ χρεία παρόντος βεβλῆσθαι γὰρ τοὺς ἀστραγάλους, ἀπέρχοιτο καραδοκήσων πόρρωθεν τὸ συμβησόμενον. ταῦτα γὰρ οὕτως ἴσχυσεν ὥστε καὶ τοὺς φιλοσόφους ἐν ταῖς σχολαῖς ζητοῦντας εἰ τὸ πάλλεσθαι τὴν καρδίαν καὶ τὸ χρῶμα τρέπεσθαι καὶ τὴν κοιλίαν ἐξυγραίνεσθαι παρὰ τὰ φαινόμενα δεινὰ δειλίας ἐστὶν ἢ δυσκρασίας τινὸς περὶ τὸ σῶμα καὶ ψυχρότητος, ὀνομάζειν ἀεὶ τὸν Ἄρατον ὡς ἀγαθὸν μὲν ὄντα στρατηγόν, ἀεὶ δὲ ταῦτα πάσχοντα παρὰ τοὺς ἀγῶνας.", "st": "Arat. 29.5"}, {"sp": "N", "t": "ὡς δ’ οὖν τὸν Ἀρίστιππον ἀνεῖλεν, εὐθὺς ἐπεβούλευσε Λυδιάδῃ τῷ Μεγαλοπολίτῃ τυραννοῦντι τῆς ἑαυτοῦ πατρίδος, ὁ δὲ οὐκ ὢν ἀγεννὴς οὐδὲ ἀφιλότιμος τὴν φύσιν, οὐδὲ ὥσπερ οἱ πολλοὶ τῶν μονάρχων ἀκρασίᾳ. καὶ πλεονεξίᾳ πρὸς ταύτην ῥυεὶς τὴν ἀδικίαν, ἀλλ’ ἐπαρθεὶς ἔρωτι δόξης ἔτι νέος καὶ λόγους ψευδεῖς καὶ κενοὺς λεγομένους περὶ τυραννίδος, ὡς μακαρίου καὶ θαυμαστοῦ πράγματος, εἰς μέγα φρόνημα παραδεξάμενος ἀνοήτως, καὶ καταστήσας ἑαυτὸν τύραννον ταχὺ μεστὸς ἦν τῆς ἐκ μοναρχίας βαρύτητος. ἅμα δὲ ζηλῶν εὐημεροῦντα καὶ δεδοικὼς ἐπιβουλεύοντα τὸν Ἄρατον ὥρμησε καλλίστην ὁρμὴν μεταβαλόμενος, πρῶτον μὲν ἑαυτὸν ἐλευθερῶσαι μίσους καὶ φόβου καὶ φρουρᾶς καὶ δορυφόρων, εἶτα τῆς πατρίδος εὐεργέτης γενέσθαι καὶ μεταπεμψάμενος τὸν Ἄρατον ἀφῆκε τὴν ἀρχήν, καὶ τὴν πόλιν εἰς τοὺς Ἀχαιοὺς μετεκόμισεν. ἐφ’ οἷς μεγαλύνοντες αὐτὸν οἱ Ἀχαιοὶ στρατηγὸν εἵλοντο.", "st": "Arat. 30.1"}, {"sp": "N", "t": "φιλοτιμούμενος δὲ εὐθὺς ὑπερβαλεῖν δόξῃ τὸν Ἄρατον ἄλλας τε πολλὰς πράξεις οὐκ ἀναγκαίας εἶναι δοκούσας καὶ στρατείαν ἐπὶ Λακεδαιμονίους παρήγγελλεν. ἐνιστάμενος δὲ ὁ Ἄρατος αὐτῷ φθονεῖν ἐδόκει· καὶ τό γε δεύτερον ὁ Λυδιάδης στρατηγὸς ᾑρέθη, ἀντιπράττοντος ἄντικρυς Ἀράτου καὶ σπουδάζοντος ἑτέρῳ παραδοθῆναι τὴν ἀρχήν, αὐτὸς μὲν γὰρ, ὡς εἴρηται, παρ’ ἐνιαυτὸν ἦρχε. μέχρι μὲν οὖν τρίτης στρατηγίας ὁ Λυδιάδης εὖ φερόμενος διετέλει καὶ παρ’ ἐνιαυτὸν ἦρχεν ἐναλλὰξ τῷ Ἀράτῳ στρατηγῶν· φανερὰν δὲ ἐξενεγκάμενος ἔχθραν καὶ πολλάκις αὐτοῦ κατηγορήσας ἐν τοῖς Ἀχαιοῖς ἀπερρίφη καὶ παρώφθη, πεπλασμένῳ δοκῶν ἤθει πρὸς ἀληθινὴν καὶ ἀκέραιον ἀρετὴν ἁμιλλᾶσθαι. καὶ καθάπερ τῷ κόκκυγί φησιν Αἴσωπος, ἐρωτῶντι τοὺς λεπτοὺς ὄρνιθας ὅ τι φεύγοιεν αὐτόν, εἰπεῖν ἐκείνους ὡς ἔσται ποτὲ ἱέραξ, οὕτως ἔοικε τῷ Λυδιάδῃ παρακολουθεῖν ἐκ τῆς τυραννίδος ὑποψία βλάπτουσα τὴν φύσιν αὐτοῦ τῆς μεταβολῆς.", "st": "Arat. 30.3"}, {"sp": "N", "t": "ὁ δὲ Ἄρατος εὐδοκίμησε καὶ περὶ τὰς Αἰτωλικὰς πράξεις, ὅτε συμβαλεῖν μὲν αὐτοῖς πρὸ τῆς Μεγαρικῆς ὡρμημένων τῶν Ἀχαιῶν, καὶ τοῦ βασιλέως τῶν Λακεδαιμονίων Ἄγιδος ἀφικομένου μετὰ δυνάμεως καὶ συνεξορμῶντος ἐπὶ τὴν μάχην τοὺς Ἀχαιούς, ἐναντιωθεὶς καὶ πολλὰ μὲν ὀνείδη, πολλὰ δ’ εἰς μαλακίαν καὶ ἀτολμίαν καὶ σκώμματα καὶ χλευασμὸν ὑπομείνας οὐ προήκατο τὸν τοῦ συμφέροντος λογισμὸν διὰ τὸ φαινόμενον αἰσχρόν, ἀλλὰ παρεχώρησε τοῖς πολεμίοις ὑπερβαλοῦσι τὴν Γεράνειαν ἀμαχεὶ παρελθεῖν εἰς Πελοπόννησον. ὡς μέντοι παρελθόντες ἐξαίφνης Πελλήνην κατέλαβον, οὐκέτ’ ἦν ὁ αὐτός, οὐδ’ ἔμελλε διατρίβων καὶ περιμένων ἀθροισθῆναι καὶ συνελθεῖν εἰς ταὐτὸ πανταχόθεν τὴν δύναμιν, ἀλλ’ εὐθὺς ὥρμησε μετὰ τῶν παρόντων ἐπὶ τοὺς πολεμίους ἐν τῷ κρατεῖν ἀσθενεστάτους δι’ ἀταξίαν καὶ ὕβριν ὄντας. ἅμα γὰρ τῷ παρελθεῖν εἰς τὴν πόλιν οἱ μὲν στρατιῶται διασπαρέντες ἐν ταῖς οἰκίαις ἦσαν, ἐξωθοῦντες ἀλλήλους καὶ διαμαχόμενοι περὶ τῶν χρημάτων, ἡγεμόνες δὲ καὶ λοχαγοὶ τὰς γυναῖκας καὶ τὰς θυγατέρας τῶν Πελληνέων περιιόντες ἥρπαζον, καὶ τὰ κράνη τὰ αὑτῶν ἀφαιροῦντες ἐκείναις περιετίθεσαν τοῦ μηδένα λαβεῖν ἄλλον, ἀλλὰ τῷ κράνει δῆλον εἶναι τὸν δεσπότην ἑκάστης· οὕτω δὲ διακειμένοις αὐτοῖς καὶ ταῦτα πράττουσιν ἐξαίφνης ὁ Ἄρατος ἐπιπεσὼν προσηγγέλθη. καὶ γενομένης ἐκπλήξεως, οἵαν εἰκὸς ἐν ἀταξίᾳ τοιαύτῃ, πρὶν ἢ πάντας πυθέσθαι τὸν κίνδυνον οἱ πρῶτοι περὶ τὰς πύλας τοῖς Ἀχαιοῖς καὶ τὰ προάστεια συμπεσόντες ἔφευγον ἤδη νενικημένοι, καὶ κατεπίμπλασαν ἐλαυνόμενοι προτροπάδην ἀπορίας τοὺς συνισταμένους καὶ προσβοηθοῦντας.", "st": "Arat. 31.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ τῷ ταράχῳ μία τῶν αἰχμαλώτων, Ἐπιγήθους ἀνδρὸς ἐνδόξου θυγάτηρ, αὐτὴ δὲ κάλλει καὶ μεγέθει σώματος εὐπρεπής, ἔτυχε μὲν ἐν τῷ ἱερῷ καθεζομένη τῆς Ἀρτέμιδος, οὗ κατέστησεν αὐτὴν ὁ ἐπιλεκτάρχης ἑλὼν ἑαυτῷ καὶ περιθεὶς τὴν τριλοφίαν, ἄφνω δὲ ἐκδραμοῦσα πρὸς τὸν θόρυβον, ὡς ἔστη πρὸ τῶν θυρῶν τοῦ ἱεροῦ καὶ κατέβλεψεν εἰς τοὺς μαχομένους ἄνωθεν ἔχουσα τὴν τριλοφίαν, αὐτοῖς τε τοῖς πολίταις θέαμα σεμνότερον ἢ κατ’ ἄνθρωπον ἐφάνη, καὶ τοῖς πολεμίοις φάσμα θεῖον ὁρᾶν δοκοῦσι φρίκην ἐνέβαλε καὶ θάμβος, ὥστε μηδένα τρέπεσθαι πρὸς ἀλκήν.", "st": "Arat. 32.1"}, {"sp": "N", "t": "αὐτοὶ δὲ Πελληνεῖς λέγουσι τὸ βρέτας τῆς θεοῦ τὸν μὲν ἄλλον ἀποκεῖσθαι χρόνον ἄψαυστον, ὅταν δὲ κινηθὲν ὑπὸ τῆς ἱερείας ἐκφέρηται, μηδένα προσβλέπειν ἐναντίον, ἀλλ’ ἀποτρέπεσθαι πάντας οὐ γὰρ ἀνθρώποις μόνον ὅραμα φρικτὸν εἶναι καὶ χαλεπόν, ἀλλά καὶ δένδρα ποιεῖν ἄφορα καὶ καρποὺς ἀπαμβλίσκειν, δι’ ὧν ἂν κομίζηται. τοῦτο δὴ τότε τὴν ἱέρειαν ἐξενεγκαμένην καὶ τρέπουσαν ἀεὶ κατὰ τοὺς Αἰτωλοὺς ἀντιπρόσωπον ἔκφρονας καταστῆσαι καὶ παρελέσθαι τὸν λογισμόν. ὁ δὲ Ἄρατος οὐδὲν ἐν τοῖς ὑπομνήμασιν εἴρηκε τοιοῦτον, ἀλλά φησι τρεψάμενος τοὺς Αἰτωλοὺς καὶ φεύγουσι συνεισπεσὼν εἰς τὴν πόλιν ἐξελάσαι κατὰ κράτος, ἑπτακοσίους δὲ ἀποκτεῖναι. τὸ δὲ ἔργον ἐν τοῖς μεγίστοις διεβοήθη, καὶ Τιμάνθης ὁ ζωγράφος ἐποίησεν ἐμφαντικῶς τῇ διαθέσει τὴν μάχην ἔχουσαν.", "st": "Arat. 32.3"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ πολλῶν ἐθνῶν καὶ δυναστῶν ἐπὶ τοὺς Ἀχαιοὺς συνισταμένων εὐθὺς ὁ Ἄρατος ἔπραττε φιλίαν πρὸς τοὺς Αἰτωλούς, καὶ Πανταλέοντι τῷ πλεῖστον Αἰτωλῶν δυναμένῳ συνεργῷ χρησάμενος οὐ μόνον εἰρήνην, ἀλλὰ καὶ συμμαχίαν τοῖς Ἀχαιοῖς πρὸς τοὺς Αἰτωλοὺς ἐποίησε.", "st": "Arat. 33.1"}, {"sp": "N", "t": "τοὺς δὲ Ἀθηναίους σπουδάζων ἐλευθερῶσαι διεβλήθη καὶ κακῶς ἤκουσεν ὑπὸ τῶν Ἀχαιῶν, ὅτι σπονδὰς πεποιημένων αὐτῶν πρὸς τοὺς Μακεδόνας καὶ ἀνοχὰς ἀγόντων ἐπεχείρησε τὸν Πειραιᾶ καταλαβεῖν. αὐτὸς δὲ ἀρνούμενος ἐν τοῖς ὑπομνήμασιν οἷς ἀπολέλοιπεν Ἐργῖνον αἰτιᾶται, μεθ’ οὗ τὰ περὶ τὸν Ἀκροκόρινθον ἔπραξεν. ἐκεῖνον γὰρ ἰδίᾳ τῷ Πειραιεῖ προσβαλόντα καὶ τῆς κλίμακος συντριβείσης διωκόμενον ὀνομάζειν καὶ καλεῖν συνεχῶς Ἄρατον ὥσπερ παρόντα, καὶ διαφυγεῖν οὕτως ἐξαπατήσαντα τοὺς πολεμίους. οὐ μὴν δοκεῖ πιθανῶς ἀπολογεῖσθαι· τὸν γὰρ Ἐργῖνον, ἄνθρωπον ἰδιώτην καὶ Σύρον, ἀπ’ οὐδενὸς ἦν εἰκότος ἐπὶ νοῦν βαλέσθαι τὴν τηλικαύτην πρᾶξιν, εἰ μὴ τὸν Ἄρατον εἶχεν ἡγεμόνα καὶ παρ’ ἐκείνου τὴν δύναμιν καὶ τὸν καιρὸν εἰλήφει πρὸς τὴν ἐπίθεσιν. ἐδήλωσε δὲ καὶ αὐτὸς ὁ Ἄρατος οὐ δὶς οὐδὲ τρίς, ἀλλὰ πολλάκις, ὥσπερ οἱ δυσέρωτες, ἐπιχειρήσας τῷ Πειραιεῖ καὶ πρὸς τὰς διαμαρτίας οὐκ ἀποκαμών, ἀλλὰ τῷ παρὰ μικρὸν ἀεὶ καὶ σύνεγγυς ἀποσφάλλεσθαι τῶν ἐλπίδων πρὸς τὸ θαρρεῖν ἀνακαλούμενος, ἅπαξ δὲ καὶ τὸ σκέλος ἔσπασε διὰ τοῦ Θριασίου φεύγων καὶ τομὰς ἔλαβε πολλὰς θεραπευόμενος, καὶ πολὺν χρόνον ἐν φορείῳ κομιζόμενος ἐποιεῖτο τὰς στρατείας.", "st": "Arat. 33.2"}, {"sp": "N", "t": "Ἀντιγόνου δὲ ἀποθανόντος καὶ Δημητρίου τὴν βασιλείαν παραλαβόντος ἔτι μᾶλλον ἐνέκειτο ταῖς Ἀθήναις καὶ ὅλως κατεφρόνει τῶν Μακεδόνων. διὸ καὶ κρατηθέντος αὐτοῦ μάχῃ περὶ Φυλακίαν ὑπὸ Βίθυος τοῦ Δημητρίου στρατηγοῦ, καὶ λόγου γενομένου πολλοῦ μὲν, ὡς ἑάλωκε, πολλοῦ δὲ ὡς τέθνηκεν, ὁ μὲν τὸν Πειραιᾶ φρουρῶν Διογένης ἔπεμψεν ἐπιστολὴν εἰς Κόρινθον ἐξίστασθαι τῆς πόλεως κελεύων τοὺς Ἀχαιούς, ἐπειδὴ Ἄρατος ἀπέθανεν ἔτυχε δὲ τῶν γραμμάτων κομισθέντων παρὼν αὐτὸς ἐν Κορίνθῳ, καὶ διατριβὴν οἱ τοῦ Διογένους καὶ γέλωτα πολὺν παρασχόντες ἀπηλλάγησαν, αὐτὸς δὲ ὁ βασιλεὺς ἐκ Μακεδονίας ναῦν ἔπεμψεν, ἐφ’ ἧς κομισθήσεται πρὸς αὐτὸν ὁ Ἄρατος δεδεμένος. πᾶσαν δὲ Ἀθηναῖοι κουφότητα κολακείας τῆς πρὸς Μακεδόνας ὑπερβάλλοντες ἐστεφανηφόρησαν ὅτε πρῶτον ἠγγέλθη τεθνηκώς, διὸ καὶ πρὸς ὀργὴν εὐθὺς ἐκστρατεύσας ἐπ’ αὐτούς ἄχρι τῆς Ἀκαδημείας προῆλθεν εἶτα πεισθεὶς οὐδὲν ἠδίκησεν.", "st": "Arat. 34.1"}, {"sp": "N", "t": "οἱ δὲ Ἀθηναῖοι συμφρονήσαντες αὐτοῦ τὴν ἀρετήν, ἐπεὶ Δημητρίου τελευτήσαντος ὥρμησαν ἐπὶ τὴν ἐλευθερίαν, ἐκεῖνον ἐκάλουν. ὁ δέ, καίπερ ἑτέρου μὲν ἄρχοντος τότε τῶν Ἀχαιῶν, αὐτὸς δὲ ἀρρωστίᾳ μακρᾷ κλινήρης ὑπάρχων, ὅμως ἐν φορείῳ κομιζόμενος ὑπήντησε τῇ πόλει πρὸς τὴν χρείαν, καὶ τὸν ἐπὶ τῆς φρουρᾶς Διογένη συνέπεισεν ἀποδοῦναι τόν τε Πειραιᾶ καὶ τὴν Μουνυχίαν καὶ τὴν Σαλαμῖνα καὶ τὸ Σούνιον τοῖς Ἀθηναίοις ἐπὶ πεντήκοντα καὶ ἑκατὸν ταλάντοις, ὧν αὐτὸς ὁ Ἄρατος εἴκοσι τῇ πόλει συνεβάλετο. προσεχώρησαν δ’ εὐθὺς Αἰγινῆται καὶ Ἑρμιονεῖς τοῖς Ἀχαιοῖς, ἥ τε πλείστη τῆς Ἀρκαδίας αὐτοῖς συνετέλει. καὶ Μακεδόνων μὲν ἀσχόλων ὄντων διά τινας προσοίκους καὶ ὁμόρους πολέμους, Αἰτωλῶν δὲ συμμαχούντων, ἐπίδοσιν μεγάλην ἡ τῶν Ἀχαιῶν ἐλάμβανε δύναμις.", "st": "Arat. 34.4"}, {"sp": "N", "t": "ὁ δὲ Ἄρατος ἐξεργαζόμενος τὴν παλαιὰν ὑπόθεσιν, καὶ δυσανασχετῶν τὴν ἐν Ἄργει τυραννίδα γειτνιῶσαν αὐτοῖς, ἔπειθε πέμπων τὸν Ἀριστόμαχον εἰς μέσον θεῖναι καὶ προσαγαγεῖν τοῖς Ἀχαιοῖς τὴν πόλιν, καὶ ζηλώσαντα Λυδιάδην ἔθνους τηλικούτου μετ’ εὐφημίας καὶ τιμῆς στρατηγὸν εἶναι μᾶλλον ἢ μιᾶς πόλεως κινδυνεύοντα καὶ μισούμενον τύραννον. ὑπακούσαντος δὲ τοῦ Ἀριστομάχου καὶ κελεύσαντος αὐτῷ πεντήκοντα τάλαντα πέμψαι τὸν Ἄρατον, ὅπως ἀπαλλάξῃ καὶ διαλύσηται τοὺς παρ’ αὐτῷ στρατευομένους, καὶ τῶν χρημάτων ποριζομένων, ὁ Λυδιάδης ἔτι στρατηγῶν καὶ φιλοτιμούμενος ἴδιον αὐτοῦ πολίτευμα τοῦτο πρὸς τοὺς Ἀχαιοὺς γενέσθαι, τοῦ μὲν Ἀράτου κατηγόρει πρὸς Ἀριστόμαχον ὡς δυσμενῶς καὶ ἀδιαλλάκτως ἀεὶ πρὸς τοὺς τυράννους ἔχοντος, αὐτῷ δὲ πείσας τὴν πρᾶξιν ἐπιτρέψαι προσήγαγε τοῖς Ἀχαιοῖς τὸν ἄνθρωπον. ἔνθα δὴ μάλιστα φανερὰν ἐποίησαν οἱ σύνεδροι τῶν Ἀχαιῶν τὴν πρὸς τὸν Ἄρατον εὔνοιαν καὶ πίστιν. ἀντειπόντος μὲν γὰρ αὐτοῦ δι’ ὀργήν ἀπήλασαν τοὺς περὶ τὸν Ἀριστόμαχον ἐπεὶ δὲ συμπεισθεὶς πάλιν αὐτὸς ἤρξατο περὶ αὐτῶν διαλέγεσθαι παρὼν, πάντα ταχέως καὶ προθύμως ἐψηφίσαντο, καὶ προσεδέξαντο μὲν τοὺς Ἀργείους καὶ Φλιασίους εἰς τὴν πολιτείαν, ἐνιαυτῷ δὲ ὕστερον καὶ τὸν Ἀριστόμαχον εἵλοντο στρατηγόν.", "st": "Arat. 35.1"}, {"sp": "N", "t": "ὁ δὲ εὐημερῶν παρὰ τοῖς Ἀχαιοῖς καὶ βουλόμενος εἰς τὴν Λακωνικὴν ἐμβαλεῖν ἐκάλει τὸν Ἄρατον ἐξ Ἀθηνῶν, ὁ δὲ ἔγραφε μὲν αὐτῷ τὴν στρατείαν ἀπαγορεύων καὶ τῷ Κλεομένει θράσος ἔχοντι καὶ παραβόλως αὐξανομένῳ συμπλέκεσθαι τοὺς Ἀχαιοὺς μὴ βουλόμενος, ὡρμημένου δὲ πάντως ὑπήκουσε καὶ παρὼν συνεστράτευεν. ὅτε δὴ καὶ κωλύσας περὶ τὸ Παλλάντιον τοῦ Κλεομένους ἐπιφανέντος αὐτοῖς μάχην συνάψαι τὸν Ἀριστόμαχον ὑπὸ Λυδιάδου κατηγορήθη, καὶ περὶ τῆς στρατηγίας εἰς ἀγῶνα καὶ ἀντιπαραγγελίαν αὐτῷ καταστάς ἐκράτησε τῇ χειροτονίᾳ καὶ τὸ δωδέκατον ᾑρέθη στρατηγός.", "st": "Arat. 35.4"}, {"sp": "N", "t": "ἐν ταύτῃ τῇ στρατηγίᾳ περὶ τὸ Λύκαιον ἡττηθεὶς ὑπὸ τοῦ Κλεομένους ἔφυγε· καὶ πλανηθεὶς νυκτὸς ἔδοξε μὲν τεθνάναι καὶ πάλιν οὗτος ὁ λόγος κατ’ αὐτοῦ πολὺς ἐξεφοίτησεν εἰς τοὺς Ἕλληνας· ἀνασωθεὶς δὲ καὶ τοὺς στρατιώτας συναγαγών οὐκ ἠγάπησεν ἀσφαλῶς ἀπελθεῖν, ἀλλ’ ἄριστα τῷ καιρῷ χρησάμενος οὐδενὸς προσδοκῶντος οὐδὲ συλλογιζομένου τὸ μέλλον ἐξαίφνης ἐπέπεσε Μαντινεῦσι συμμάχοις οὖσι τοῦ Κλεομένους· καὶ τὴν πόλιν ἑλών φρουρὰν ἐνέβαλε καὶ τοὺς μετοίκους πολίτας ἐποίησεν αὐτῶν, καὶ μόνος ἃ νικῶντες οὐκ ἂν ῥᾳδίως ἔσχον ἐκτήσατο νενικημένοις τοῖς Ἀχαιοῖς.", "st": "Arat. 36.1"}, {"sp": "N", "t": "αὖθις δὲ τῶν Λακεδαιμονίων ἐπὶ Μεγάλην πόλιν στρατευσάντων βοηθήσας ὤκνει μὲν ἁψιμαχοῦντι τῷ Κλεομένει λαβὴν παρασχεῖν καὶ τοῖς Μεγαλοπολίταις βιαζομένοις ἀντεῖχεν, οὔτε ἄλλως πρὸς τὰς κατὰ στόμα μάχας εὖ πεφυκώς καὶ τότε λειπόμενός τε πλήθει καὶ πρὸς ἄνδρα τολμητὴν καὶ νέον ἤδη παρακμάζοντι τῷ θυμῷ καὶ κεκολασμένῃ τῇ φιλοτιμίᾳ συνεστηκώς, καὶ νομίζων ἣν διὰ τοῦ τολμᾶν ἐκεῖνος ἐξ οὐχ ὑπαρχόντων ἐκτᾶτο δόξαν αὑτῷ κεκτημένῳ φυλακτέον εἶναι διὰ τῆς εὐλαβείας.", "st": "Arat. 36.3"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τῶν ψιλῶν ἐκδραμόντων καὶ ὠσαμένων τοὺς Σπαρτιάτας ἄχρι τὸν στρατοπέδου καὶ περὶ τὰς σκηνὰς διασπαρέντων, ὁ μὲν Ἄρατος οὐδ’ ὥς ἐπήγαγεν, ἀλλ’ ἐν μέσῳ λαβὼν χαράδραν ἐπέστησε καὶ κατεκώλυσε διαβῆναι τοὺς ὁπλίτας· ὁ δὲ Λυδιάδης περιπαθῶν πρὸς τὰ γιγνόμενα καὶ τὸν Ἄρατον κακίζων ἀνεκαλεῖτο τοὺς ἱππεῖς ὡς αὑτόν, ἀξιῶν ἐπιφανῆναι τοῖς διώκουσι καὶ μὴ προέσθαι τὸ νίκημα μηδὲ ἐγκαταλιπεῖν αὑτόν ὑπὲρ τῆς πατρίδος ἀγωνιζόμενον. πολλῶν δὲ συστραφέντων καὶ ἀγαθῶν ἐπιρρωσθεὶς ἐνέβαλε τῷ δεξιῷ τῶν πολεμίων καὶ τρεψάμενος ἐδίωκεν, ὑπὸ θυμοῦ καὶ φιλοτιμίας ἀταμιεύτως ἐπισπασθεὶς εἰς χωρία σκολιὰ καὶ μεστὰ δένδρων πεφυτευμένων καὶ τάφρων πλατειῶν, ἐν οἷς ἐπιθεμένου τοῦ Κλεομένους ἔπεσε λαμπρῶς ἀγωνισάμενος τὸν κάλλιστον τῶν ἀγώνων ἐπὶ θύραις τῆς πατρίδος. οἱ δ’ ἄλλοι φεύγοντες εἰς τὴν φάλαγγα καὶ συνταράξαντες τοὺς ὁπλίτας ὅλον τὸ στράτευμα τῆς ἥττης ἐνέπλησαν. αἰτίαν δὲ μεγάλην ὁ Ἄρατος ἔλαβε δόξας προέσθαι τὸν Λυδιάδην· καὶ βιασθεὶς ὑπὸ τῶν Ἀχαιῶν ἀπερχομένων πρὸς ὀργήν ἠκολούθησεν αὐτοῖς εἰς Αἴγιον. ἐκεῖ δὲ συνελθόντες ἐψηφίσαντο μὴ διδόναι χρήματα αὐτῷ μηδὲ μισθοφόρους τρέφειν ἀλλ’ αὑτῷ πορίζειν, εἰ δέοιτο πολεμεῖν.", "st": "Arat. 37.1"}, {"sp": "N", "t": "οὕτω δὲ προπηλακισθείς ἐβουλεύσατο μὲν εὐθὺς ἀποθέσθαι τὴν σφραγῖδα καὶ τὴν στρατηγίαν ἀφεῖναι, λογισμῷ δὲ χρησάμενος τότε μὲν ὑπέμεινε, καὶ πρὸς Ὀρχομενὸν ἐξαγαγὼν τοὺς Ἀχαιούς μάχην ἔθετο πρὸς Μεγιστόνουν τὸν Κλεομένους πατρῳόν, ἐν ᾗ κρατήσας τριακοσίους μὲν ἀπέκτεινε, ζῶντα δὲ τὸν Μεγιστόνουν συνέλαβεν. εἰωθὼς δὲ στρατηγεῖν παρ’ ἐνιαυτόν, ὡς ἡ τάξις αὐτῷ περιῆλθε, καλούμενος ἐξωμόσατο, καὶ Τιμόξενος ᾑρέθη στρατηγός, ἐδόκει δὲ ἡ μὲν πρὸς τοὺς ὄχλους ὀργὴ πρόφασις εἶναι λεγομένη τῆς ἐξωμοσίας ἀπίθανος, αἰτία δ’ ἀληθὴς τὰ περιεστῶτα τοὺς Ἀχαιούς, οὐκέθ’ ὡς πρότερον ἀτρέμα καὶ σχέδην τοῦ Κλεομένους ἐπιβαίνοντος οὐδ’ ἐμπλεκομένου ταῖς πολιτικαῖς ἀρχαῖς, ἀλλ’ ἐπεὶ τοὺς ἐφόρους ἀποκτείνας καὶ τὴν χώραν ἀναδασάμενος καὶ πολλοὺς τῶν μετοίκων ἐμβαλὼν εἰς τὴν πολιτείαν ἔσχεν ἰσχὺν ἀνυπεύθυνον, εὐθὺς ἐπικειμένου τοῖς Ἀχαιοῖς καὶ τῆς ἡγεμονίας ἑαυτὸν ἀξιοῦντος.", "st": "Arat. 38.1"}, {"sp": "N", "t": "διὸ καὶ μέμφονται τὸν Ἄρατον ἐν σάλῳ μεγάλῳ καὶ χειμῶνι τῶν πραγμάτων φερομένων ὥσπερ κυβερνήτην ἀφέντα καὶ προέμενον ἑτέρῳ τοὺς οἴακας, ὅτε καλῶς εἶχε καὶ ἀκόντων ἐπιστάντα σῴζειν τὸ κοινόν· εἰ δ’ ἀπεγνώκει τὰ πράγματα καὶ τὴν δύναμιν τῶν Ἀχαιῶν, εἶξαι τῷ Κλεομένει, καὶ μὴ πάλιν τὴν Πελοπόννησον ἐκβαρβαρῶσαι φρουραῖς Μακεδόνων, μηδὲ πληρῶσαι τὸν Ἀκροκόρινθον Ἰλλυρικῶν ὅπλων καὶ Γαλατικῶν, μηδὲ οὓς αὐτὸς ἐν ταῖς πράξεσι καταστρατηγῶν καὶ καταπολιτευόμενος, ἐν δὲ τοῖς ὑπομνήμασι λοιδορῶν διετέλει, τούτους ἐπάγεσθαι δεσπότας ταῖς πόλεσι συμμάχους ὑποκοριζόμενον. εἰ δὲ Κλεομένης ἦν, λεγέσθω γὰρ οὕτως, παράνομος καὶ τυραννικός, ἀλλ’ Ἡρακλεῖδαι πατέρες αὐτῷ καὶ Σπάρτη πατρίς, ἧς τὸν ἀφανέστατον ἄξιον ἀντὶ τοῦ πρώτου Μακεδόνων ἡγεμόνα ποιεῖσθαι τοὺς ἔν τινι λόγῳ τὴν Ἑλληνικὴν τιθεμένους εὐγένειαν.", "st": "Arat. 38.4"}, {"sp": "N", "t": "καίτοι Κλεομένης ᾔτει τὴν ἀρχὴν παρὰ τῶν Ἀχαιῶν ὡς πολλὰ ποιήσων ἀγαθὰ τὰς πόλεις ἀντὶ τῆς τιμῆς καὶ τῆς προσηγορίας ἐκείνης, Ἀντίγονος δὲ καὶ κατὰ γῆν καὶ κατὰ θάλατταν αὐτοκράτωρ ἡγεμὼν ἀναγορευθείς οὐχ ὑπήκουσε πρὶν τὸν μισθὸν αὐτῷ τῆς ἡγεμονίας ὁμολογηθῆναι τὸν Ἀκροκόρινθον, ἀτεχνῶς τὸν Αἰσώπου μιμησάμενος κυνηγόν. οὐ γὰρ πρότερον ἐπέβη τοῖς Ἀχαιοῖς δεομένοις καὶ ὑποβάλλουσιν αὑτοὺς διὰ τῶν πρεσβειῶν καὶ τῶν ψηφισμάτων ἢ τῇ φρουρᾷ καὶ τοῖς ὁμήροις ὥσπερ χαλινουμένους ἀνασχέσθαι. καίτοι πᾶσαν ὁ Ἄρατος ἀφίησι φωνὴν ἀπολογιζόμενος τὴν ἀνάγκην, ὁ Πολύβιος δὲ αὐτὸν ἐκ πολλοῦ φησι καὶ πρὸ τῆς ἀνάγκης ὑφορώμενον τὸ θράσος τὸ τοῦ Κλεομένους κρύφα τῷ Ἀντιγόνῳ διαλέγεσθαι, καὶ τοὺς Μεγαλοπολίτας προκαθιέναι δεομένους Ἀχαιῶν ἐπικαλεῖσθαι τὸν Ἀντίγονον.", "st": "Arat. 38.6"}, {"sp": "N", "t": "οὗτοι γὰρ ἐπιέζοντο τῷ πολέμῳ μάλιστα, συνεχῶς ἄγοντος αὑτοὺς καὶ φέροντος τοῦ Κλεομένους. ὁμοίως δὲ καὶ Φύλαρχος ἱστόρηκε περὶ τούτων, ᾧ μὴ τοῦ Πολυβίου μαρτυροῦντος οὐ πάνυ τι πιστεύειν ἄξιον ἦν. ἐνθουσιᾷ γὰρ ὅταν ἅψηται τοῦ Κλεομένους, ὑπ’ εὐνοίας, καὶ καθάπερ ἐν δίκῃ τῇ ἱστορίᾳ τῷ μὲν ἀντιδικῶν διατελεῖ, τῷ δὲ συναγορεύων.", "st": "Arat. 38.8"}, {"sp": "N", "t": "ἀπέβαλον δ’ οὖν οἱ Ἀχαιοὶ τὴν Μαντίνειαν, πάλιν ἑλόντος αὐτὴν τοῦ Κλεομένους, καὶ μάχῃ μεγάλῃ περὶ τὸ Ἑκατόμβαιον ἡττηθέντες οὕτω κατεπλάγησαν ὥστε πέμπειν εὐθὺς ἐφ’ ἡγεμονίᾳ τὸν Κλεομένη καλοῦντες εἰς Ἄργος. ὁ δὲ Ἄρατος ὡς ᾔσθετο βαδίζοντα καὶ περὶ Λέρναν ὄντα μετὰ τῆς δυνάμεως, φοβηθεὶς ἀπέστελλε πρέσβεις τοὺς ἀξιοῦντας ὡς παρὰ φίλους καὶ συμμάχους αὐτὸν ἥκειν μετὰ τριακοσίων, εἰ δὲ ἀπιστεῖ, λαβεῖν ὁμήρους, ταῦτα ὕβριν εἶναι καὶ χλευασμὸν αὑτοῦ φήσας ὁ Κλεομένης ἀνέζευξεν, ἐπιστολὴν γράψας τοῖς Ἀχαιοῖς ἐγκλήματα πολλὰ κατὰ τοῦ Ἀράτου καὶ διαβολὰς ἔχουσαν. ἔγραφε δὲ κἀκεῖνος ἐπιστολὰς κατὰ τοῦ Κλεομένους· καὶ ἐφέροντο λοιδορίαι καὶ βλασφημίαι μέχρι γάμων καὶ γυναικῶν ἀλλήλους κακῶς λεγόντων.", "st": "Arat. 39.1"}, {"sp": "N", "t": "ἐκ τούτου κήρυκα πέμψας ὁ Κλεομένης πόλεμον προεροῦντα τοῖς Ἀχαιοῖς, μικροῦ μὲν ἔλαθε τὴν Σικυωνίων πόλιν ἁρπάσας διὰ προδοσίας, ἐγγύθεν δὲ ἀποτραπεὶς Πελλήνῃ προσέβαλε καὶ τοῦ στρατηγοῦ τῶν Ἀχαιῶν ἐκπεσόντος ἔσχε τὴν πόλιν. ὀλίγῳ δὲ ὕστερον καὶ Φενεὸν ἔλαβε καὶ Πεντέλειον. εἶτ’ εὐθὺς Ἀργεῖοι προσεχώρησαν αὐτῷ καὶ Φλιάσιοι φρουρὰν ἐδέξαντο· καὶ ὅλως οὐδὲν ἔτι τῶν ἐπικτήτων βέβαιον ἦν τοῖς Ἀχαιοῖς, ἀλλὰ θόρυβος πολὺς ἄφνω περιειστήκει τὸν Ἄρατον, ὁρῶντα τὴν Πελοπόννησον κραδαινομένην καὶ τὰς πόλεις ἐξανισταμένας ὑπὸ τῶν νεωτεριζόντων πανταχόθεν.", "st": "Arat. 39.4"}, {"sp": "N", "t": "Ἠτρέμει γὰρ οὐδὲν οὐδὲ ἔστεργεν ἐπὶ τοῖς παροῦσιν, ἀλλὰ καὶ Σικυωνίων αὐτῶν καὶ Κορινθίων ἐγένοντο πολλοὶ καταφανεῖς διειλεγμένοι τῷ Κλεομένει καὶ πάλαι πρὸς τὸ κοινὸν ἰδίων ἐπιθυμίᾳ, δυναστειῶν ὑπούλως ἔχοντες. ἐπὶ τούτους ἐξουσίαν ἀνυπεύθυνον ὁ Ἄρατος λαβών τοὺς μὲν ἐν Σικυῶνι διεφθαρμένους ἀπέκτεινε, τοὺς δὲ ἐν Κορίνθῳ πειρώμενος ἀναζητεῖν καὶ κολάζειν ἐξηγρίαινε τὸ πλῆθος ἤδη νοσοῦν καὶ βαρυνόμενον τὴν ὑπὸ τοῖς Ἀχαιοῖς πολιτείαν. συνδραμόντες οὖν εἰς τὸ τοῦ Ἀπόλλωνος ἱερόν μετεπέμποντο τὸν Ἄρατον, ἀνελεῖν ἢ συλλαβεῖν πρὸ τῆς ἀποστάσεως ἐγνωκότες. ὁ δὲ ἧκε μὲν αὐτὸς ἐφελκόμενος τὸν ἵππον ὡς οὐκ ἀπιστῶν οὐδὲ ὑποπτεύων, ἀναπηδησάντων δὲ πολλῶν καὶ λοιδορουμένων αὐτῷ καὶ κατηγορούντων εὖ πως καθεστῶτι τῷ προσώπῳ καὶ τῷ λόγῳ πράως ἐκέλευε καθίσαι καὶ μὴ βοᾶν ἀτάκτως ἑστῶτας, ἀλλὰ καὶ τοὺς περὶ θύρας ὄντας εἴσω παριέναι· καὶ ταῦθ’ ἅμα λέγων ὑπεξῄει βάδην ὡς παραδώσων τινὶ τὸν ἵππον. οὕτως δὲ ὑπεκδύς καὶ τοῖς ὑπαντῶσι τῶν Κορινθίων ἀθορύβως διαλεγόμενος καὶ κελεύων πρὸς τὸ Ἀπολλώνιον βαδίζειν, ὡς ἔλαθε πλησίον τῆς ἄκρας γενόμενος, ἀναπηδήσας ἐπὶ τὸν ἵππον καὶ Κλεοπάτρῳ τῷ ἄρχοντι τῆς φρουρᾶς διακελευσάμενος ἐγκρατῶς φυλάττειν ἀφίππευσεν εἰς Σικυῶνα, τριάκοντα μὲν αὐτῷ στρατιωτῶν ἑπομένων, τῶν δὲ ἄλλων ἐγκαταλιπόντων καὶ διαρρυέντων.", "st": "Arat. 40.1"}, {"sp": "N", "t": "αἰσθόμενοι δ’ οἱ Κορίνθιοι μετ’ ὀλίγον τὴν ἀπόδρασιν αὐτοῦ καὶ διώξαντες, ὡς οὐ κατέλαβον, μετεπέμψαντο τὸν Κλεομένη καὶ παρέδοσαν τὴν πόλιν οὐδὲν οἰομένῳ λαμβάνειν παρ’ αὐτῶν τοσοῦτον ὅσου διήμαρτεν ἀφέντων Ἄρατον. οὗτος μὲν οὖν, προσγενομένων αὐτῷ τῶν τὴν λεγομένην Ἀκτὴν κατοικούντων καὶ τὰς πόλεις ἐγχειρισάντων, ἀπεσταύρου καὶ περιετείχιζε τὸν Ἀκροκόρινθον.", "st": "Arat. 40.5"}, {"sp": "N", "t": "τῷ δὲ Ἀράτῳ συνῆλθον εἰς Σικυῶνα τῶν Ἀχαιῶν οὐ πολλοί· καὶ γενομένης ἐκκλησίας ᾑρέθη στρατηγὸς αὐτοκράτωρ, καὶ περιεστήσατο φρουρὰν ἐκ τῶν ἑαυτοῦ πολιτῶν, τριάκοντα μὲν ἔτη καὶ τρία πεπολιτευμένος ἐν τοῖς Ἀχαιοῖς, πεπρωτευκὼς δὲ καὶ δυνάμει καὶ δόξῃ τῶν Ἑλλήνων, τότε δὲ ἔρημος καὶ ἄπορος συντετριμμένος, ὥσπερ ἐπὶ ναυαγίου τῆς πατρίδος ἐν τοσούτῳ σάλῳ καὶ κινδύνῳ διαφερόμενος. καὶ γὰρ Αἰτωλοὶ δεομένου βοηθεῖν ἀπείπαντο, καὶ τὴν Ἀθηναίων πόλιν χάριτι τοῦ Ἀράτου πρόθυμον οὖσαν οἱ περὶ Εὐρυκλείδην καὶ Μικίωνα διεκώλυσαν. ὄντων δὲ τῷ Ἀράτῳ καὶ χρημάτων ἐν Κορίνθῳ καὶ οἰκίας, ὁ Κλεομένης ἥψατο μὲν οὐδενός οὐδὲ ἄλλον εἴασε, μεταπεμψάμενος δὲ τοὺς φίλους αὐτοῦ καὶ τοὺς διοικητάς ἐκέλευε πάντα διοικεῖν καὶ φυλάσσειν ὡς Ἀράτῳ λόγον ὑφέξοντας· ἰδίᾳ δὲ πρὸς αὐτὸν ἔπεμψε Τρίπυλον καὶ πάλιν Μεγιστόνουν τὸν πατρῳόν ὑπισχνούμενος ἄλλα τε πολλὰ καὶ δώδεκα τάλαντα σύνταξιν ἐνιαύσιον, ὑπερβαλλόμενος τῷ ἡμίσει Πτολεμαῖον ἐκεῖνος γὰρ ἓξ τάλαντα τῷ Ἀράτῳ κατ’ ἐνιαυτὸν ἀπέστελλεν. ἠξίου δὲ τῶν Ἀχαιῶν ἡγεμὼν ἀναγορευθῆναι καὶ κοινῇ μετ’ αὐτῶν φυλάσσειν τὸν Ἀκροκόρινθον. τοῦ δὲ Ἀράτου φήσαντος ὡς οὐκ ἔχοι τὰ πράγματα, μᾶλλον δὲ ὑπ’ αὐτῶν ἔχοιτο, καὶ κατειρωνεύσασθαι δόξαντος, ἐμβαλὼν εὐθὺς τὴν Σικυωνίαν ἐπόρθει καὶ κατέφθειρε καὶ προσεκάθητο τῇ πόλει τρεῖς μῆνας, ἐγκαρτεροῦντος τοῦ Ἀράτου καὶ διαποροῦντος εἰ δέξεται τὸν Ἀντίγονον ἐπὶ τῷ παραδοῦναι τὸν Ἀκροκόρινθον· ἄλλως γὰρ οὐκ ἐβούλετο βοηθεῖν.", "st": "Arat. 41.1"}, {"sp": "N", "t": "οἱ μὲν οὖν Ἀχαιοὶ συνεληλυθότες εἰς Αἴγιον ἐκεῖ τὸν Ἄρατον ἐκάλουν. ἦν δὲ κίνδυνος, τοῦ Κλεομένους πρὸς τῇ πόλει στρατοπεδεύοντος, διελθεῖν. καὶ κατεῖχον οἱ πολῖται, δεόμενοι καὶ προήσεσθαι τὸ σῶμα τῶν πολεμίων ἐγγὺς ὄντων οὐ φάσκοντες· ἐξήρτηντο δὲ αὐτοῦ καὶ γυναῖκες ἤδη καὶ παῖδες ὥσπερ πατρὸς κοινοῦ καὶ σωτῆρος περιεχόμενοι καὶ δακρύοντες. οὐ μὴν ἀλλὰ θαρρύνας καὶ παραμυθησάμενος αὐτούς ἐξίππευσεν ἐπὶ τὴν θάλατταν, ἔχων δέκα φίλους καὶ τὸν υἱὸν ἤδη νεανίαν ὄντα· καὶ παρορμούντων ἐκεῖ πλοίων, ἐπιβάντες εἰς Αἴγιον παρεκομίσθησαν ἐπὶ τὴν ἐκκλησίαν, ἐν ᾗ καλεῖν τὸν Ἀντίγονον ἐψηφίσαντο καὶ παραδιδόναι τὸν Ἀκροκόρινθον. ἔπεμψε δὲ καὶ τὸν υἱὸν Ἄρατος πρὸς αὐτὸν μετὰ τῶν ἄλλων ὁμήρων, ἐφ’ οἷς οἱ Κορίνθιοι χαλεπῶς φέροντες τά τε χρήματα διήρπασαν αὐτοῦ καὶ τὴν οἰκίαν τῷ Κλεομένει δωρεὰν ἔδωκαν.", "st": "Arat. 42.1"}, {"sp": "N", "t": "τοῦ δ’ Ἀντιγόνου πρὸς προσιόντος ἤδη μετὰ τῆς δυνάμεως ἦγε δὲ πεζοὺς δισμυρίους Μακεδόνας, ἱππεῖς δὲ χιλίους καὶ τριακοσίους ἀπήντα μετὰ τῶν δημιουργῶν ὁ Ἄρατος αὐτῷ κατὰ θάλατταν εἰς Πηγάς, λαθὼν τοὺς πολεμίους, οὐ πάνυ τι θαρρῶν τὸν Ἀντίγονον οὐδὲ πιστεύων τοῖς Μακεδόσιν. ᾔδει γὰρ ηὐξημένον ἑαυτὸν ἐζ ὧν ἐκείνους κακῶς ἐποίησε καὶ πρώτην εἰληφότα μεγίστην ὑπόθεσιν τῆς πολιτείας τὴν πρὸς Ἀντίγονον τὸν παλαιὸν ἔχθραν. ἀλλὰ ὁρῶν ἀπαραίτητον ἐπικειμένην ἀνάγκην καὶ τὸν καιρόν, ᾧ δουλεύουσιν οἱ δοκοῦντες ἄρχειν, ἐχώρει πρὸς τὸ δεινόν. ὁ δὲ Ἀντίγονος, ὥς τις αὐτῷ προσιόντα τὸν Ἄρατον ἔφρασε, τοὺς μὲν ἄλλους ἠσπάσατο μετρίως καὶ κοινῶς, ἐκεῖνον δὲ καὶ περὶ τὴν πρώτην ἀπάντησιν ἐδέξατο τῇ τιμῇ περιττῶς, καὶ τἆλλα πειρώμενος ἀνδρὸς ἀγαθοῦ καὶ νοῦν ἔχοντος ἐνδοτέρω τῆς χρείας προσηγάγετο.", "st": "Arat. 43.1"}, {"sp": "N", "t": "καὶ γὰρ ἦν ὁ Ἄρατος οὐ μόνον ἐν πράγμασι μεγάλοις ὠφέλιμος, ἀλλὰ καὶ σχολάζοντι βασιλεῖ συγγενέσθαι παρ’ ὁντινοῦν ἐπίχαρις. διό, καίπερ ὢν νέος ὁ Ἀντίγονος, ὡς κατενόησε τὴν φύσιν τοῦ ἀνδρὸς μηδὲν ἀργὸν εἰς φιλίαν βασιλικὴν οὖσαν, οὐ μόνον Ἀχαιῶν, ἀλλὰ καὶ Μακεδόνων τῶν σὺν αὐτῷ πάντων μάλιστα χρώμενος ἐκείνῳ διετέλει· καὶ τὸ σημεῖον ἀπέβαινεν ὡς ὁ θεὸς ἐπὶ τῶν ἱερῶν ἔδειξε. λέγεται γὰρ οὐ πρὸ πολλοῦ θύοντι τῷ Ἀράτῳ δύο χολὰς ἐν ἥπατι φανῆναι μιᾷ πιμελῇ περιεχομένας· καὶ τὸν μάντιν εἰπεῖν ὡς ταχὺ πρὸς τὰ ἔχθιστα καὶ πολεμιώτατα σύνεισιν εἰς ἄκραν φιλίαν. τότε μὲν οὖν παρήνεγκε τὸ ῥηθέν, οὐδὲ ἄλλως πολὺ νέμων πίστεως ἱεροῖς καὶ μαντεύμασιν, ἀλλὰ τῷ λογισμῷ χρώμενος. ἐπεὶ δὲ ὕστερον εὖ χωροῦντι τῷ πολέμῳ συναγαγὼν ὁ Ἀντίγονος ἑστίασιν ἐν Κορίνθῳ καὶ πολλοὺς ὑποδεχόμενος τὸν Ἄρατον ἐπάνω κατέκλινεν ἑαυτοῦ, καὶ μετὰ μικρὸν αἰτήσας περιβόλαιον ἠρώτησεν εἰ δοκεῖ κἀκείνῳ ψῦχος εἶναι, τοῦ δὲ καὶ πάνυ ῥιγοῦν φήσαντος, ἐκέλευσε προσχωρεῖν ἐγγυτέρω καὶ δάπιδος κομισθείσης ἀμφοτέρους ὁμοῦ περιέβαλον οἱ παῖδες, τότε δὴ τὸν Ἄρατον ἀναμνησθέντα τῶν ἱερῶν ἐκείνων γέλως ἔλαβε, καὶ διηγεῖτο τῷ βασιλεῖ τὸ σημεῖον καὶ τὴν προαγόρευσιν. ἀλλὰ ταῦτα μὲν ἐπράχθη χρόνοις ὕστερον.", "st": "Arat. 43.3"}, {"sp": "N", "t": "ἐν δὲ ταῖς Πηγαῖς δόντες καὶ λαβόντες ὅρκους εὐθὺς ἐβάδιζον ἐπὶ τοὺς πολεμίους, καὶ περὶ τὴν πόλιν ἀγῶνες ἦσαν, εὖ πεφραγμένου τοῦ Κλεομένους καὶ τῶν Κορινθίων ἀμυνομένων προθύμως. ἐν τούτῳ δὲ Ἀριστοτέλης ὁ Ἀργεῖος φίλος ὢν Ἀράτου διαπέμπεται κρύφα πρὸς αὐτόν, ὡς ἀποστήσων τὴν πόλιν, εἰ στρατιώτας ἐκεῖνος ἔχων ἔλθοι. τοῦ δὲ Ἀράτου φράσαντος τῷ Ἀντιγόνῳ καὶ μετὰ χιλίων καὶ πεντακοσίων εἰς Ἐπίδαυρον ἐξ Ἰσθμοῦ πλοίοις κομιζομένου κατὰ τάχος, οἱ μὲν Ἀργεῖοι προεξαναστάντες ἐπέθεντο τοῖς τοῦ Κλεομένους καὶ κατέκλεισαν εἰς τὴν ἀκρόπολιν, ὁ δὲ Κλεομένης πυθόμενος ταῦτα, καὶ δείσας μὴ κατασχόντες οἱ πολέμιοι τὸ Ἄργος ἀποκόψωσιν αὐτὸν τῆς οἴκαδε σωτηρίας, ἐκλιπὼν Τὸν Ἀκροκόρινθον ἔτι νυκτὸς ἐβοήθει. καὶ παρελθὼν μὲν εἰς Ἄργος ἔφθη καὶ τροπήν τινα τῶν πολεμίων ἐποίησεν, ὀλίγῳ δὲ ὕστερον Ἀράτου προσφερομένου καὶ τοῦ βασιλέως ἐπιφαινομένου μετὰ τῆς δυνάμεως ἀπεχώρησεν εἰς Μαντίνειαν. ἐκ τούτου τοῖς μὲν Ἀχαιοῖς πάλιν αἱ πόλεις ἅπασαι προσεχώρησαν, Ἀντίγονος δὲ Τὸν Ἀκροκόρινθον παρέλαβεν, Ἄρατος δὲ στρατηγὸς αἱρεθεὶς ὑπ’ Ἀργείων ἔπεισεν αὐτοὺς Ἀντιγόνῳ τά τε τῶν τυράννων καὶ τὰ τῶν προδοτῶν χρήματα δωρεὰν δοῦναι. τὸν δὲ Ἀριστόμαχον ἐν Κεγχρεαῖς στρεβλώσαντες κατεπόντισαν, ἐφ’ ᾧ καὶ μάλιστα κακῶς ἤκουσεν ὁ Ἄρατος, ὡς ἄνθρωπον οὐ πονηρόν, ἀλλὰ καὶ κεχρημένον ἐκείνῳ καὶ πεπεισμένον ἀφεῖναι τὴν ἀρχὴν καὶ προσαγαγεῖν τοῖς Ἀχαιοῖς τὴν πόλιν, ὅμως περιιδὼν παρανόμως ἀπολλύμενον.", "st": "Arat. 44.1"}, {"sp": "N", "t": "ἤδη δὲ καὶ τῶν ἄλλων ἐκείνῳ τὰς αἰτίας ἐπέφερον, οἷον ὅτι τὴν μὲν Κορινθίων πόλιν Ἀντιγόνῳ δωρεὰν ἔδωκαν, ὥσπερ κώμην τὴν τυχοῦσαν, τὸν Ὀρχομενὸν δὲ συνεχώρησαν αὐτῷ διαρπάσαντι φρουρὰν ἐμβαλεῖν Μακεδονικήν, ἐψηφίσαντο δὲ ἄλλῳ μὴ γράφειν βασιλεῖ μηδὲ πρεσβεύειν πρὸς ἄλλον ἄκοντος Ἀντιγόνου, τρέφειν τε καὶ μισθοδοτεῖν ἠναγκάζοντο τοὺς Μακεδόνας, θυσίας δὲ καὶ πομπὰς καὶ ἀγῶνας Ἀντιγόνῳ συνετέλουν, ἀρξαμένων τῶν Ἀράτου πολιτῶν καὶ δεξαμένων τῇ πόλει τὸν Ἀντίγονον ὑπ’ Ἀράτου ξενιζόμενον, ᾐτιῶντο πάντων ἐκεῖνον, ἀγνοοῦντες ὅτι τὰς ἡνίας ἐκείνῳ παραδεδωκὼς καὶ τῇ ῥύμῃ τῆς βασιλικῆς ἐφελκόμενος ἐξουσίας οὐδενὸς ἦν ἢ μόνης φωνῆς ἔτι κύριος, ἐπισφαλῆ τὴν παρρησίαν ἐχούσης. ἐπεὶ φανερῶς γε πολλὰ τῶν πραττομένων ἐλύπει τὸν Ἄρατον, ὥσπερ τὸ περὶ τῶν εἰκόνων ὁ γὰρ Ἀντίγονος τὰς μὲν τῶν ἐν Ἄργει τυράννων καταβεβλημένας ἀνέστησε, τὰς δὲ τῶν ἑλόντων τὸν Ἀκροκόρινθον ἑστώσας ἀνέτρεψε πλὴν μιᾶς τῆς ἐκείνου· καὶ πολλὰ περὶ τούτων δεηθεὶς ὁ Ἄρατος οὐκ ἔπεισεν. ἐδόκει δὲ καὶ τὰ περὶ Μαντίνειαν οὐχ Ἑλληνικῶς διῳκῆσθαι τοῖς Ἀχαιοῖς. κρατήσαντες γὰρ αὐτῶν δι’ Ἀντιγόνου τοὺς μὲν ἐνδοξοτάτους καὶ πρώτους ἀπέκτειναν, τῶν δ’ ἄλλων τοὺς μὲν ἀπέδοντο, τοὺς δ’ εἰς Μακεδονίαν ἀπέστειλαν ἐν πέδαις δεδεμένους, παῖδας δὲ καὶ γυναῖκας ἠνδραποδίσαντο, τοῦ δὲ συναχθέντος ἀργυρίου τὸ τρίτον αὐτοὶ διείλοντο, τὰς δὲ δύο μοίρας ἔνειμαν τοῖς Μακεδόσι. καὶ ταῦτα μὲν ἔσχε τὸν τῆς ἀμύνης νόμον καὶ γὰρ εἰ δεινὸν ἄνδρας ὁμοφύλους καὶ συγγενεῖς οὕτω μεταχειρίσασθαι δι’ ὀργήν, ἀλλ’ ἐν ἀνάγκαις γλυκὺ γίνεται καὶ σκληρόν, κατὰ Σιμωνίδην, ὥσπερ ἀλγοῦντι τῷ θυμῷ καὶ φλεγμαίνοντι θεραπείαν καὶ ἀναπλήρωσιν προσφερόντων. τὰ δὲ μετὰ ταῦτα πραχθέντα περὶ τὴν πόλιν οὔτ’ εἰς καλὴν οὔτ’ εἰς ἀναγκαίαν ἔστι θέσθαι τῷ Ἀράτῳ πρόφασιν. τῶν γὰρ Ἀχαιῶν τὴν πόλιν παρ’ Ἀντιγόνου δωρεὰν λαβόντων καὶ κατοικίζειν ἐγνωκότων αὐτὸς οἰκιστὴς αἱρεθεὶς καὶ στρατηγὸς ὢν ἐψηφίσατο μηκέτι καλεῖν Μαντίνειαν, ἀλλ’ Ἀντιγόνειαν, ὃ καὶ μέχρι νῦν καλεῖται, καὶ δοκεῖ δι’ ἐκεῖνον ἡ μὲν ἐρατεινὴ Μαντίνεια παντάπασιν ἐξαληλίφθαι, διαμένει δὲ ἡ πόλις ἐπώνυμος τῶν ἀπολεσάντων καὶ ἀνελόντων τοὺς πολίτας.", "st": "Arat. 45.1"}, {"sp": "N", "t": "ἐκ τούτου Κλεομένης μὲν ἡττηθεὶς μάχῃ μεγάλῃ περὶ Σελλασίαν ἐξέλιπε τὴν Σπάρτην καὶ ἀπέπλευσεν εἰς Αἴγυπτον, Ἀντίγονος δὲ πάντα τὰ δίκαια καὶ φιλάνθρωπα τῷ Ἀράτῳ πεποιηκὼς ἀνέζευξεν εἰς Μακεδονίαν, κἀκεῖ νοσῶν ἤδη τὸν διάδοχον τῆς βασιλείας Φίλιππον, οὔπω πάνυ μειράκιον ὄντα, πέμπων εἰς Πελοπόννησον Ἀράτῳ μάλιστα προσέχειν ἐκέλευσε καὶ δι’ ἐκείνου ταῖς πόλεσιν ἐντυχεῖν καὶ γνωρισθῆναι τοῖς Ἀχαιοῖς. καὶ μέντοι καὶ παραλαβὼν αὐτὸν ὁ Ἄρατος οὕτως διέθηκεν ὥστε πολλῆς μὲν εὐνοίας πρὸς αὐτόν, πολλῆς δὲ πρὸς τὰς Ἑλληνικὰς πράξεις φιλοτιμίας καὶ ὁρμῆς μεστὸν εἰς Μακεδονίαν ἀποστεῖλαι.", "st": "Arat. 46.1"}, {"sp": "N", "t": "τελευτήσαντος δὲ Ἀντιγόνου καταφρονήσαντες Αἰτωλοὶ τῶν Ἀχαιῶν διὰ τὴν ῥᾳθυμίαν ἐθισθέντες γὰρ ἀλλοτρίαις σώζεσθαι χερσὶ καὶ τοῖς Μακεδόνων ὅπλοις αὑτοὺς ὑπεσταλκότες ἐν ἀργίᾳ πολλῇ καὶ ἀταξίᾳ διῆγον ἐπέθεντο τοῖς κατὰ Πελοπόννησον πράγμασι· καὶ τὴν μὲν Πατρέων καὶ Δυμαίων λεηλασίαν ὁδοῦ πάρεργον ἐποιήσαντο, τὴν δὲ Μεσσήνην ἐμβαλόντες ἐπόρθουν. ἐφ’ οἷς ὁ Ἄρατος ἀγανακτῶν καὶ τὸν στρατηγοῦντα τότε τῶν Ἀχαιῶν Τιμόξενον ὁρῶν ὀκνοῦντα καὶ διατρίβοντα τὸν χρόνον, ἤδη τῆς στρατηγίας αὐτῷ τελευτώσης, αὐτὸς ᾑρημένος ἄρχειν μετ’ ἐκεῖνον προέλαβεν ἡμέραις πέντε τὴν ἀρχὴν ἕνεκα τοῦ βοηθῆσαι Μεσσηνίοις. καὶ συναγαγὼν τοὺς Ἀχαιούς τοῖς τε σώμασιν ἀγυμνάστους ὄντας καὶ ταῖς διανοίαις ἐκλελυμένους πρὸς τὸν πόλεμον ἡττᾶται περὶ Καφύας· καὶ θυμικώτερον ἐστρατηγηκέναι δόξας οὕτως αὖ πάλιν ἀπημβλύνθη καὶ προήκατο τὰ πράγματα καὶ τὰς ἐλπίδας, ὥστε πολλάκις λαβὴν τοὺς Αἰτωλοὺς παρασχόντας ἀνέχεσθαι καὶ περιορᾶν ὥσπερ κωμάζοντας ἐν τῇ Πελοποννήσῳ μετὰ πολλῆς ἀσελγείας καὶ θρασύτητος. αὖθις οὖν τὰς χεῖρας ὀρέγοντες εἰς Μακεδονίαν ἐπεσπῶντο καὶ κατῆγον ἐπὶ τὰς Ἑλληνικὰς πράξεις τὸν Φίλιππον, οὐχ ἥκιστα διὰ τὴν πρὸς τὸν Ἄρατον εὔνοιαν αὐτοῦ καὶ πίστιν ἐλπίζοντες εὐκόλῳ περὶ πάντα χρήσεσθαι καὶ χειροήθει.", "st": "Arat. 47.1"}, {"sp": "N", "t": "καὶ τότε πρῶτον Ἀπελλοῦ καί Μεγαλέου καί τινων αὐλικῶν ἄλλων διαβαλλόντων τὸν Ἄρατον ἀναπεισθεὶς ὁ βασιλεὺς, καί συναρχαιρεσιάσας τοῖς ἀπὸ τῆς ἐναντίας στάσεως, ἐσπούδασε τοὺς Ἀχαιοὺς ἑλέσθαι στρατηγὸν Ἐπήρατον. ὡς δ’ ἐκείνου μὲν καταφρονουμένου τελέως ὑπὸ τῶν Ἀχαιῶν, τοῦ δὲ Ἀράτου παραμελοῦντος ἐγίνετο τῶν χρησίμων οὐδέν, ἔγνω διαμαρτάνων τοῦ παντὸς ὁ Φίλιππος, καί ἀνακρουσάμενος αὖθις ἐπὶ τὸν Ἄρατον ὅλος ἦν ἐκεῖνον, καί τῶν πραγμάτων αὐτῷ πρός τε δύναμιν καί πρός εὐδοξίαν ἐπιδιδόντων ἐξήρτητο τοῦ ἀνδρός, ὡς δι’ ἐκεῖνον εὐδοκιμῶν καί αὐξόμενος. ἐδόκει τε πᾶσιν ὁ Ἄρατος οὐ μόνον δημοκρατίας, ἀλλὰ καί βασιλείας ἀγαθὸς εἶναι παιδαγωγός· ἡ γὰρ προαίρεσις αὐτοῦ καί τὸ ἦθος ὡς χρῶμα ταῖς πράξεσι τοῦ βασιλέως ἐπεφαίνετο. καί γὰρ ἡ πρός Λακεδαιμονίους ἁμαρτόντας μετριότης τοῦ νεανίσκου καί ἡ πρός Κρῆτας ὁμιλία, δι’ ἧς ὅλην προσηγάγετο τὴν νῆσον ἡμέραις ὀλίγαις, ἥ τε πρός Αἰτωλοὺς στρατεία γενομένη θαυμαστῶς ἐνεργός εὐπειθείας μὲν τῷ Φιλίππῳ δόξαν, εὐβουλίας δὲ τῷ Ἀράτῳ προσετίθει. καί διὰ ταῦτα μᾶλλον οἱ βασιλικοὶ φθονοῦντες, ὡς οὐδὲν ἐπέραινον κρύφα διαβάλλοντες, ἀναφανδὸν ἐλοιδοροῦντο καὶ προσέκρουον αὐτῷ παρὰ τοὺς πότους μετὰ πολλῆς ἀσελγείας καί βωμολοχίας· ἅπαξ δὲ καί λίθοις βάλλοντες ἀπιόντα εἰς τὴν σκηνὴν μετὰ τὸ δεῖπνον κατεδίωξαν. ἐφ’ οἷς ὁ Φίλιππος ὀργισθείς εὐθὺς μὲν αὐτοὺς ἐζημίωσεν εἴκοσι ταλάντοις, ὕστερον δὲ λυμαίνεσθαι τὰ πράγματα καὶ ταράττειν δοκοῦντας ἀπέκτεινεν.", "st": "Arat. 48.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τῆς τύχης εὐροούσης ἐπαιρόμενος τοῖς πράγμασι πολλὰς μὲν ἀνέφυε καὶ μεγάλας ἐπιθυμίας, ἡ δ’ ἔμφυτος κακία, τὸν παρὰ φύσιν σχηματισμὸν ἐκβιαζομένη καὶ ἀναδύουσα, κατὰ μικρὸν ἀπεγύμνου καὶ διέφαινεν αὐτοῦ τὸ ἦθος, πρῶτον μὲν ἰδίᾳ τὸν νεώτερον Ἄρατον ἠδίκει περὶ τὴν γυναῖκα καὶ πολὺν χρόνον ἐλάνθανεν ἐφέστιος ὢν καὶ ξενιζόμενος ὑπ’ αὐτῶν· ἔπειτα πρὸς τὰς Ἑλληνικὰς ἐξετραχύνετο πολιτείας καὶ φανερὸς ἦν ἤδη τὸν Ἄρατον ἀποσειόμενος. ἀρχὴν δὲ ὑποψίας τὰ Μεσσηνιακὰ παρέσχε, στασιασάντων γὰρ αὐτῶν ὁ μὲν Ἄρατος ὑστέρει βοηθῶν, ὁ δὲ Φίλιππος ἡμέρᾳ μιᾷ πρότερον ἐλθὼν εἰς τὴν πόλιν εὐθὺς οἶστρόν τινα κατ’ ἀλλήλων ἐνέβαλε τοῖς ἀνθρώποις, ἰδίᾳ μὲν ἐρωτῶν τούς στρατηγοὺς τῶν Μεσσηνίων εἰ νόμους κατὰ τῶν πολλῶν οὐκ ἔχουσιν, ἰδίᾳ δὲ πάλιν τούς τῶν πολλῶν προεστῶτας εἰ χεῖρας κατὰ τῶν τυραννούντων οὐκ ἔχουσιν. ἐκ δὲ τούτου θαρρήσαντες οἱ μὲν ἄρχοντες ἐπελαμβάνοντο τῶν δημαγωγῶν, ἐκεῖνοι δὲ μετὰ τῶν πολλῶν ἐπελθόντες τούς τε ἄρχοντας ἀπέκτειναν καὶ τῶν ἄλλων ὀλίγον ἀπολείποντας διακοσίων.", "st": "Arat. 49.1"}, {"sp": "N", "t": "οὕτω δέ δεινὸν ἔργον ἐξειργασμένου τοῦ Φιλίππου, καὶ συγκρούοντος ἔτι μᾶλλον ἑαυτοῖς τοὺς Μεσσηνίους, ἐπελθὼν ὁ Ἄρατος αὐτός τε δῆλος ἦν φέρων βαρέως καὶ τὸν υἱὸν ἐπιτιμῶντα πικρῶς τῷ Φιλίππῳ καὶ λοιδορούμενον οὐκ ἐκώλυσεν. ἐδόκει δὲ ὁ νεανίσκος ἐρᾶν τὸν Φιλίππου· καὶ τότε λέγων εἶπε πρὸς αὐτόν ὡς οὐδὲ καλὸς ἔτι φαίνοιτο τὴν ὄψιν αὐτῷ τοιαῦτα δράσας, ἀλλὰ πάντων αἴσχιστος. ὁ δὲ Φίλιππος ἐκείνῳ μὲν οὐδὲν ἀντεῖπε, καίπερ ἐπίδοξος ὢν, ὑπ’ ὀργῆς καὶ πολλάκις ἐξυλακτήσας λέγοντος αὐτοῦ, τὸν δὲ πρεσβύτερον, ὡς ἐνηνοχὼς πράως τὰ λεχθέντα καί τις ὢν μέτριος καὶ πολιτικὸς τὴν φύσιν, ἀνέστησεν ἐκ τοῦ θεάτρου τὴν δεξιὰν ἐμβαλὼν, καὶ προσῆγεν εἰς τὸν Ἰθωμάταν τῷ τε Διὶ θύσων καὶ θεωρήσων τὸν τόπον. ἔστι γὰρ οὐχ ἧττον εὐερκὴς τοῦ Ἀκροκορίνθου, καὶ λαβὼν φρουρὰν γίνεται χαλεπὸς καὶ δυσεκβίαστος τοῖς παροικοῦσιν. ἀναβὰς δὲ καὶ θύσας, ὡς προσήνεγκεν αὐτῷ τὰ σπλάγχνα τοῦ βοὸς ὁ μάντις, ἀμφοτέραις ταῖς χερσὶν ὑπολαβὼν ἐδείκνυε τῷ τε Ἀράτῳ καὶ τῷ Φαρίῳ Δημητρίῳ, παρὰ μέρος ἀποκλίνων εἰς ἑκάτερον καὶ πυνθανόμενος τί καθορῶσιν ἐν τοῖς ἱεροῖς, κρατοῦντα τῆς ἄκρας αὐτόν ἢ τοῖς Μεσσηνίοις ἀποδιδόντα. γελάσας οὖν ὁ Δημήτριος, εἰ μὲν, ἔφη, μάντεως ἔχεις ψυχήν, ἀφήσεις τὸν τόπον εἰ δὲ βασιλέως, ἀμφοτέρων τῶν κεράτων τὸν βοῦν καθέξεις, αἰνιττόμενος τὴν Πελοπόννησον, ὡς, εἰ προσλάβοι τὸν Ἰθωμάταν τῷ Ἀκροκορίνθῳ, παντάπασιν ἐσομένην ὑποχείριον καὶ ταπεινήν. ὁ δὲ Ἄρατος ἐπὶ πολὺ μὲν ἡσύχαζε, δεομένου δὲ τοῦ Φιλίππου τὸ φαινόμενον λέγειν, πολλὰ μὲν, εἶπεν, ὦ Φίλιππε, Κρητῶν ὄρη καὶ μεγάλα, πολλαὶ δὲ Βοιωτῶν ἄκραι καὶ Φωκέων ἐκπεφύκασι τῆς γῆς· εἰσὶ δέ που πολλοὶ καὶ τῆς Ἀκαρνάνων τοῦτο μὲν χερσαῖοι, τοῦτο δ’ ἔναλοι τόποι θαυμαστὰς ὀχυρότητας ἔχοντες· ἀλλ’ οὐδένα τούτων κατείληφας, καὶ πάντες ἑκουσίως σοι ποιοῦσι τὸ προστασσόμενον. λῃσταὶ γὰρ ἐμφύονται πέτραις καὶ κρημνῶν περιέχονται, βασιλεῖ δὲ πίστεως καὶ χάριτος ἰσχυρότερον οὐδὲν οὐδὲ ὀχυρώτερον. ταῦτα σοι τὸ Κρητικὸν ἀνοίγει πέλαγος, ταῦτα τὴν Πελοπόννησον. ἀπὸ τούτων ὁρμώμενος σὺ τοσοῦτος ἡλικίαν τῶν μὲν ἡγεμών, τῶν δὲ κύριος ἤδη καθέστηκας ἔτι λέγοντος αὐτοῦ τὰ μὲν σπλάγχνα τῷ μάντει παρέδωκεν ὁ Φίλιππος, ἐκεῖνον δὲ πῆς χειρὸς ἐπισπασάμενος, δεῦρο τοίνυν, ἔφη, τὴν αὐτὴν ὁδὸν ἴωμεν ὥσπερ ἐκβεβιασμένος ὑπ’ αὐτοῦ καὶ τὴν πόλιν ἀφῃρημένος.", "st": "Arat. 50.1"}, {"sp": "N", "t": "ὁ δὲ Ἄρατος ἀπορρέων ἤδη τῆς αὐλῆς καὶ κατὰ μικρὸν ἑαυτὸν ἀνακομιζόμενος ἐκ τῆς πρὸς τὸν Φίλιππον συνηθείας, διαβαίνοντος εἰς Ἤπειρον αὐτοῦ καὶ δεομένου συστρατεύειν, ἀπείπατο καὶ κατέμεινε, δεδιὼς ἀναπλησθῆναι δόξης πονηρᾶς ἀφ’ ὧν ἐκεῖνος ἔπραττεν. ἐπεὶ δὲ τάς τε ναῦς ὑπὸ Ῥωμαίων ἀπολέσας αἴσχιστα καὶ ὅλως ἀποτυχὼν ταῖς πράξεσιν ἐπανῆλθεν εἰς Πελοπόννησον, καὶ τοὺς Μεσσηνίους αὖθις ἐπιχειρήσας φενακίζειν καὶ μὴ λαθὼν ἠδίκει φανερῶς καὶ τὴν χώραν αὐτῶν ἐπόρθει, παντάπασιν ὁ Ἄρατος ἀπεστράφη καὶ διεβλήθη πρὸς αὐτόν, ἤδη καὶ τῶν περὶ τὴν γυναικωνῖτιν ἀδικημάτων αἰσθόμενος καὶ φέρων ἀνιαρῶς αὐτός, ἀποκρυπτόμενος δὲ τὸν υἱόν· εἰδέναι γὰρ ὑβρισμένον περιῆν, ἄλλο δὲ οὐδέν, ἀμύνασθαι μὴ δυναμένῳ. μεγίστην γὰρ ὁ Φίλιππος δοκεῖ καὶ παραλογωτάτην μεταβαλέσθαι μεταβολήν, ἐξ ἡμέρου βασιλέως καὶ μειρακίου σώφρονος ἀνὴρ ἀσελγὴς καὶ τύραννος ἐξώλης γενόμενος, τὸ δὲ οὐκ ἦν ἄρα μεταβολὴ φύσεως, ἀλλ’ ἐπίδειξις ἐν ἀδείᾳ κακίας πολὺν χρόνον διὰ φόβον ἀγνοηθείσης.", "st": "Arat. 51.1"}, {"sp": "N", "t": "ὅτι γὰρ ἦν μεμιγμένον αἰσχύνῃ καὶ φόβῳ τὸ πρὸς τὸν Ἄρατον αὐτοῦ πάθος ἀπ’ ἀρχῆς συντεθραμμένον, ἐδήλωσεν οἷς ἔπραξε περὶ αὐτόν, ἐπιθυμῶν γὰρ ἀνελεῖν τὸν ἄνδρα καὶ νομίζων οὐδ’ ἂν ἐλεύθερος ἐκείνου ζῶντος εἶναι, μή τί γε τύραννος ἢ βασιλεύς, βίᾳ μὲν οὐδὲν ἐπεχείρησε, Ταυρίωνα δὲ τῶν στρατηγῶν τινα καὶ φίλων ἐκέλευσεν ἀδήλῳ τρόπῳ τοῦτο πρᾶξαι, μάλιστα διὰ φαρμάκων, αὐτοῦ μὴ παρόντος. ὁ δὲ ποιησάμενος τὸν Ἄρατον συνήθη φάρμακον αὐτῷ δίδωσιν, οὐκ ὀξὺ καὶ σφοδρόν, ἀλλὰ τῶν θέρμας τε μαλακὰς τὸ πρῶτον ἐν τῷ σώματι καὶ βῆχα κινούντων ἀμβλεῖαν, εἶτα οὕτως κατὰ μικρὸν εἰς φθορὰν περαινόντων. οὐ μὴν ἔλαθέ γε τὸν Ἄρατον ἀλλ’ ὡς οὐδὲν ἦν ὄφελος ἐλέγχοντι, πράως καὶ σιωπῇ τὸ πάθος, ὡς δή τινα νόσον κοινὴν καὶ συνήθη νοσῶν, διήντλει. πλὴν ἑνός γε τῶν συνήθων ἐν τῷ δωματίῳ παρόντος ἀναπτύσας δίαιμον, ἰδόντος ἐκείνου καὶ θαυμάσαντος, ταῦτα, εἶπεν, ὦ Κεφάλων, ἐπίχειρα τῆς βασιλικῆς φιλίας.", "st": "Arat. 52.1"}, {"sp": "N", "t": "οὕτω δὲ αὐτοῦ τελευτήσαντος ἐν Αἰγίῳ τὸ ἑπτακαιδέκατον στρατηγοῦντος, καὶ τῶν Ἀχαιῶν φιλοτιμουμένων ἐκεῖ γενέσθαι ταφὰς καὶ μνήματα πρέποντα τῷ βίῳ τὸν ἀνδρός, Σικυώνιοι συμφορὰν ἐποιοῦντο μὴ παρ’ αὐτοῖς τεθῆναι τὸ σῶμα. καὶ τοὺς μὲν Ἀχαιοὺς ἔπεισαν ἐφιέναι, νόμου δὲ ὄντος ἀρχαίου μηδένα θάπτεσθαι τειχῶν ἐντός, ἰσχυρᾶς τε τῷ νόμῳ δεισιδαιμονίας προσούσης, ἔπεμψαν εἰς Δελφοὺς ὑπὲρ τούτων ἐρησόμενοι τὴν Πυθίαν. ἡ δὲ αὐτοῖς ἀναιρεῖ τὸν χρησμὸν τόνδε·", "st": "Arat. 53.1"}, {"sp": "N", "t": "βουλεύῃ, Σικυών, ζωάγριον αἰὲν Ἀράτου,<br>ἀμφ’ ὁσίῃ θαλίῃ τε κατοιχομένοιο ἄνακτος;", "st": "Arat. 53.1b"}, {"sp": "N", "t": "ὡς τὸ βαρυνόμενον τῷδ’ ἀνέρι καὶ τὸ βαρῦνον<br>γαίης ἔστ’ ἀσέβημα καὶ οὐρανοῦ ἠδὲ θαλάσσης.", "st": "Arat. 53.1c"}, {"sp": "N", "t": "κομισθείσης δὲ τῆς μαντείας οἵ τε Ἀχαιοὶ σύμπαντες ἥσθησαν, καὶ διαφερόντως οἱ Σικυώνιοι μεταβαλόντες εἰς ἑορτὴν τὸ πένθος εὐθὺς ἐκ τοῦ Αἰγίου τὸν νεκρὸν ἐστεφανωμένοι καὶ λευχειμονοῦντες ὑπὸ παιάνων καὶ χορῶν εἰς τὴν πόλιν ἀνῆγον, καὶ τόπον ἐξελόμενοι περίοπτον ὥσπερ οἰκιστὴν καὶ σωτῆρα τῆς πόλεως ἐκήδευσαν. καὶ καλεῖται μέχρι νῦν Ἀράτειον, καὶ θύουσιν αὐτῷ θυσίαν, τὴν μέν, ᾗ τὴν πόλιν ἀπήλλαξε τῆς τυραννίδος ἡμέρᾳ πέμπτῃ Δαισίου μηνός, ὃν Ἀθηναῖοι καλοῦσιν Ἀνθεστηριῶνα, καὶ τὴν θυσίαν ἐκείνην Σωτήρια προσαγορεύουσι, τὴν δὲ τοῦ μηνὸς ἐν ἡ γενέσθαι τὸν ἄνδρα διαμνημονεύουσι. τῆς μὲν οὖν προτέρας ὁ τὸν Διὸς τοῦ Σωτῆρος κατήρχετο θυηπόλος, τῆς δὲ δευτέρας ὁ τὸν Ἀράτου, στρόφιον οὐχ ὁλόλευκον, ἀλλὰ μεσοπόρφυρον ἔχων, μέλη δὲ ᾔδετο πρὸς κιθάραν ὑπὸ τῶν περὶ τὸν Διόνυσον τεχνιτῶν, καὶ συνεπόμπευεν ὁ γυμνασίαρχος ἡγούμενος τῶν τε παίδων καὶ τῶν ἐφήβων, εἶτα ἐφείπετο ἡ βουλὴ στεφανηφοροῦσα καὶ τῶν ἄλλων πολιτῶν ὁ βουλόμενος. ὧν ἔτι δείγματα μικρὰ ταῖς ἡμέραις ἐκείναις ἐξοσιούμενοι διαφυλάττουσιν αἱ δὲ πλεῖσται τῶν τιμῶν ὑπὸ χρόνου καὶ πραγμάτων ἄλλων ἐκλελοίπασιν.", "st": "Arat. 53.3"}, {"sp": "N", "t": "ἀλλὰ γὰρ ὁ μὲν πρεσβύτερος Ἄρατος οὕτω βιῶσαι καὶ τοιοῦτος γενέσθαι τὴν φύσιν ἱστορεῖται· τὸν δὲ υἱὸν αὐτοῦ μιαρὸς ὢν φύσει καὶ μετ’ ὠμότητος ὑβριστὴς ὁ Φίλιππος οὐ θανασίμοις, ἀλλὰ μανικοῖς ἐξέστησε τοῦ λογισμοῦ φαρμάκοις· καὶ παρέτρεψεν εἰς δεινὰς καὶ ἀλλοκότους ἐπιφοράς, πράξεων ἀτόπων καὶ σὺν αἰσχύνῃ παθῶν ὀλεθρίων ὀρεγόμενον, ὥστε τὸν θάνατον αὐτῷ, καίπερ ὄντι νέῳ καὶ ἀνθοῦντι, μὴ συμφοράν, ἀλλ’ ἀπόλυσιν κακῶν καὶ σωτηρίαν γενέσθαι. δίκας γε μὴν ὁ Φίλιππος οὐ μεμπτὰς Διὶ ξενίῳ καὶ φιλίῳ τῆς ἀνοσιουργίας ταύτης τίνων διετέλεσε, καταπολεμηθεὶς μὲν γὰρ ὑπὸ Ῥωμαίων ἐπέτρεψεν ἐκείνοις τὰ καθ’ αὑτόν, ἐκπεσὼν δὲ τῆς ἄλλης ἀρχῆς καὶ τὰς ναῦς; πλὴν πέντε πάσας προέμενος καὶ χίλια προσεκτίσειν ὁμολογήσας τάλαντα καὶ τὸν υἱὸν ὁμηρεύσοντα παραδούς δι’ οἶκτον ἔτυχε Μακεδονίας καὶ τῶν συντελούντων. ἀποκτείνων δὲ ἀεὶ τοὺς ἀρίστους καὶ συγγενεστάτους φρίκης ἐνέπλησε καὶ μίσους ὅλην τὴν βασιλείαν πρὸς αὑτόν. ἔν δὲ μόνον ἐν τοσούτοις κακοῖς εὐτύχημα κτησάμενος, υἱὸν ἀρετῇ διαφέροντα, τοῦτον φθόνῳ καὶ ζηλοτυπίᾳ τῆς παρὰ Ῥωμαίοις τιμῆς ἀνεῖλε, Περσεῖ δὲ θατέρῳ τὴν ἀρχὴν παρέδωκεν, ὅν οὐ γνήσιον, ἀλλ’ ὑπόβλητον εἶναί φασιν, ἐκ Γναθαινίου τινὸς ἀκεστρίας γενόμενον. τοῦτον Αἰμίλιος ἐθριάμβευσε καὶ κατέστρεψεν ἐνταῦθα τῆς Ἀντιγονικῆς βασιλείας ἡ διαδοχή, τὸ δὲ Ἀράτου γένος ἐν τῇ Σικυῶνι καὶ τῇ Πελλήνῃ διέμεινε καθ’ ἡμᾶς.", "st": "Arat. 54.1"}, {"sp": "HDR", "t": "Γάλβας"}, {"sp": "N", "t": "ὁ μὲν Ἀθηναῖος Ἰφικράτης τὸν μισθοφόρον ἠξίου στρατιώτην καὶ φιλόπλουτον εἶναι καὶ φιλήδονον, ὅπως ταῖς ἐπιθυμίαις χορηγίαν ἐπιζητῶν ἀγωνίζηται παραβολώτερον, οἱ δὲ πλεῖστοι, καθάπερ ἐρρωμένον σῶμα, τὸ στρατιωτικὸν ἀξιοῦσιν ἰδίᾳ μηδέποτε χρώμενον ὁρμῇ συγκινεῖσθαι τῇ τοῦ στρατηγοῦ. διὸ καὶ Παῦλον Αἰμίλιον λέγουσι τὴν ἐν Μακεδονίᾳ δύναμιν παραλαβόντα λαλιᾶς καὶ περιεργίας, οἷον διαστρατηγοῦσαν, ἀνάπλεων, παρεγγυῆσαι τὴν χεῖρα ποιεῖν ἑτοίμην καὶ τὴν μάχαιραν ὀξεῖαν ἕκαστον, αὐτῷ δὲ τῶν ἄλλων μελήσειν. ὁ δὲ Πλάτων οὐδὲν ἔργον ὁρῶν ἄρχοντος ἀγαθοῦ καὶ στρατηγοῦ στρατιᾶς μὴ σωφρονούσης μηδὲ ὁμοπαθούσης, ἀλλὰ τὴν πειθαρχικὴν ἀρετὴν ὁμοίως τῇ βασιλικῇ νομίζων φύσεως γενναίας καὶ τροφῆς φιλοσόφου δεῖσθαι, μάλιστα τῷ πρᾴῳ καὶ φιλανθρώπῳ τὸ θυμοειδὲς καὶ δραστήριον ἐμμελῶς ἀνακεραννυμένης, ἄλλα τε πάθη πολλὰ καὶ τὰ Ῥωμαίοις συμπεσόντα μετὰ τὴν Νέρωνος τελευτὴν ἔχει μαρτύρια καὶ παραδείγματα τοῦ μηδὲν εἶναι φοβερώτερον ἀπαιδεύτοις χρωμένης καὶ ἀλόγοις ὁρμαῖς ἐν ἡγεμονίᾳ στρατιωτικῆς δυνάμεως. Δημάδης μὲν γὰρ Ἀλεξάνδρου τελευτήσαντος εἴκαζε τὴν Μακεδόνων στρατιὰν ἐκτετυφλωμένῳ τῷ Κύκλωπι, πολλὰς κινουμένην ὁρῶν κινήσεις ἀτάκτους καὶ παραφόρους· τὴν δὲ Ῥωμαίων ἡγεμονίαν ὅμοια τοῖς λεγομένοις Τιτανικοῖς πάθεσι καὶ κινήμασι κατελάμβανεν, εἰς πολλὰ διασπωμένην ἅμα καὶ πολλαχόθεν αὖθις ἑαυτῇ συμπίπτουσαν, οὐχ οὕτως ὑπὸ φιλαρχίας τῶν ἀναγορευομένων αὐτοκρατόρων, ὡς φιλοπλουτίας καὶ ἀκολασίας τὸν στρατιωτικοῦ δι’ ἀλλήλων ὥσπερ ἥλους τοὺς ἡγεμόνας ἐκκρούοντος. καίτοι Διονύσιος Φεραῖον ἄρξαντα Θετταλῶν δέκα μῆνας, εἶτα εὐθὺς ἀναιρεθέντα, τὸν τραγικὸν ἀνεκάλει τύραννον, ἐπισκώπτων τὸ τάχος τῆς μεταβολῆς, ἡ δὲ τῶν Καισάρων ἑστία, τὸ Παλάτιον, ἐν ἐλάσσονι χρόνῳ τέσσαρας αὐτοκράτορας ὑπεδέξατο, τὸν μὲν εἰσαγόντων ὥσπερ διὰ σκηνῆς, τὸν δ’ ἐξαγόντων. ἀλλ’ ἦν γε παραμυθία τοῖς κακῶς πάσχουσι μία τὸ μὴ δεηθῆναι δίκης ἑτέρας ἐπὶ τοὺς αἰτίους, ἀλλ’ ὁρᾶν αὐτοὺς ὑφ’ ἑαυτῶν φονευομένους, πρῶτον δὲ καὶ δικαιότατα πάντων τὸν δελεάσαντα καὶ διδάξαντα τοσοῦτον ἐλπίζειν ἐπὶ μεταβολῇ Καίσαρος ὅσον αὐτὸς ὑπέσχετο, κάλλιστον ἔργον διαβαλὼν τῷ μισθῷ, τὴν ἀπὸ Νέρωνος ἀποστασίαν προδοσίαν γενομένην.", "st": "Galb. 1.1"}, {"sp": "N", "t": "Νυμφίδιος γὰρ Σαβῖνος ὢν ἔπαρχος, ὥσπερ εἴρηται, μετὰ Τιγελλίνου τῆς αὐλῆς, ἐπεὶ τὰ Νέρωνος ἀπέγνωστο παντάπασι καὶ δῆλος ἦν ἀποδρασόμενος εἰς Αἴγυπτον, ἔπεισε τὸ στρατιωτικόν, ὡς μηκέτι παρόντος, ἀλλ’ ἤδη πεφευγότος, αὐτοκράτορα Γάλβαν ἀναγορεῦσαι, καὶ δωρεὰν ὑπέσχετο κατ’ ἄνδρα τοῖς αὐλικοῖς καὶ στρατηγικοῖς προσαγορευομένοις δραχμὰς ἑπτακισχιλίας πεντακοσίας, τοῖς δὲ ἐκτὸς στρατευομένοις πεντήκοντα καὶ διακοσίας ἐπὶ χιλίαις, ὅσον ἀμήχανον ἦν συναγαγεῖν μὴ πλείονα μυριάκις κακὰ παρασχόντα πᾶσιν ἀνθρώποις ὧν Νέρων παρέσχε. τοῦτο γὰρ εὐθὺς μὲν ἀπώλεσε Νέρωνα, μετ’ ὀλίγον δὲ Γάλβαν τὸν μὲν γὰρ ὡς ληψόμενοι προήκαντο, τὸν δὲ μὴ λαμβάνοντες ἀπέκτειναν. εἶτα τὸν τοσοῦτον δώσοντα ζητοῦντες ἔφθησαν ἐν ταῖς ἀποστάσεσι καὶ προδοσίαις ἀναλώσαντες αὑτοὺς ἢ τυχόντες ὧν ἤλπισαν. τὰ μὲν οὖν καθ’ ἕκαστα τῶν γενομένων ἀπαγγέλλειν ἀκριβῶς τῆς πραγματικῆς ἱστορίας ἐστίν, ὅσα δὲ ἄξια λόγου τοῖς τῶν Καισάρων ἔργοις καὶ πάθεσι συμπέπτωκεν, οὐδὲ ἐμοὶ προσήκει παρελθεῖν.", "st": "Galb. 2.1"}, {"sp": "N", "t": "Γάλβας Σουλπίκιος ὅτι μὲν ἰδιώτης πλουσιώτατος ἁπάντων εἰς τὸν Καισάρων παρῆλθεν οἶκον, ὁμολογεῖται μέγα δὲ ἔχων εὐγενείας ἀξίωμα τὸν Σερουΐων οἶκον, αὐτὸς ἐφρόνει μεῖζον ἐπὶ τῇ Κάτλου συγγενείᾳ, πρωτεύσαντος ἀνδρὸς ἀρετῇ καὶ δόξῃ τῶν καθ’ ἑαυτόν, εἰ καὶ τὸ δύνασθαι μᾶλλον ἑκὼν ἑτέροις παρῆκεν. ἦν δέ τι καὶ Λιβίᾳ τῇ Καίσαρος γυναικὶ κατὰ γένος προσήκων ὁ Γάλβας, καὶ διὰ τοῦτο Λιβίας παρασχούσης ὕπατος ἐκ Παλατίου προῆλθε. λέγεται δὲ καὶ στρατεύματος ἐν Γερμανίᾳ καλῶς ἄρξαι καὶ Λιβύης ἀνθύπατος γενόμενος σὺν ὀλίγοις ἐπαινεθῆναι. τὸ δὲ εὔκολον αὐτοῦ τῆς διαίτης καὶ φειδωλὸν ἐν δαπάναις καὶ ἀπέριττον αἰτίαν ἔσχεν αὐτοκράτορος γενομένου μικρολογίας, ἣν ἕωλόν τινα δόξαν εὐταξίας ἔφερε καὶ σωφροσύνης. ἐπέμφθη δὲ ὑπὸ Νέρωνος Ἰβηρίας ἄρχων, οὔπω δεδιδαγμένου φοβεῖσθαι τοὺς ἐν ἀξιώμασι μεγάλους τῶν πολιτῶν. ἐκείνῳ δὲ καὶ φύσει δοκοῦντι πρᾴῳ γεγονέναι προσετίθει πίστιν εὐλαβείας τὸ γῆρας.", "st": "Galb. 3.1"}, {"sp": "N", "t": "ἐπεὶ δέ, τῶν ἀλιτηρίων ἐπιτρόπων ὠμῶς καὶ ἀγρίως τὰς ἐπαρχίας ἐκείνῳ διαφορούντων, ἄλλο μὲν εἶχεν οὐδὲν βοηθεῖν, αὐτῷ δὲ τῷ φανερὸς εἶναι συναλγῶν καὶ συναδικούμενος ἁμῶς γέ πως ἀναπνοήν τινα καὶ παραμυθίαν τοῖς καταδικαζομένοις καὶ πωλουμένοις παρέσχε· καὶ ποιημάτων εἰς Νέρωνα γινομένων καὶ πολλαχοῦ περιφερομένων καὶ ᾀδομένων, οὐκ ἐκώλυεν οὐδὲ συνηγανάκτει τοῖς ἐπιτρόποις· ἐφ’ οἷς ἔτι μᾶλλον ἠγαπᾶτο ὑπὸ τῶν ἀνθρώπων. καὶ γὰρ ἦν ἤδη συνήθης, ἔτος ὄγδοον ἐκεῖνο τὴν ἀρχὴν ἔχων ἐν ᾧ Ἰούνιος Οὐίνδιξ ἐπανέστη Νέρωνι, Γαλατίας ὢν στρατηγός. λέγεται μὲν οὖν καὶ πρὸ τῆς ἐμφανοῦς ἀποστάσεως γράμματα πρὸς αὐτὸν ἀφικέσθαι παρὰ τοῦ Οὐίνδικος, οἷς μήτε πιστεῦσαι μήτε μηνῦσαι καὶ κατειπεῖν, ὡς ἕτεροι τῶν ἡγεμονικῶν ἐπιστολὰς αὐτοῖς γραφείσας ἔπεμψαν πρὸς Νέρωνα καὶ διέφθειραν ὅσον ἐπ’ αὐτοῖς τὴν πρᾶξιν, ἧς ὕστερον μετασχόντες ὡμολόγησαν αὑτῶν οὐδὲν ἧττον ἢ ἐκείνου προδόται γεγονέναι. ἀλλ’ ἐπειδὴ λαμπρῶς τὸν πόλεμον ἐκφήνας ὁ Οὐίνδιξ ἔγραψε τῷ Γάλβᾳ παρακαλῶν ἀναδέξασθαι τὴν ἡγεμονίαν καὶ παρασχεῖν ἑαυτὸν ἰσχυρῷ σώματι ζητοῦντι κεφαλήν, ταῖς Γαλατίαις δέκα μυριάδας ἀνδρῶν ὡπλισμένων ἐχούσαις ἄλλας τε πλείονας ὁπλίσαι δυναμέναις, προὔθηκε βουλὴν τοῖς φίλοις. ὧν οἱ μὲν ἠξίουν περιμένειν καραδοκοῦντα τίνα κίνησιν ἡ Ῥώμη καὶ φορὰν ἕξει πρὸς τὸν νεωτερισμόν· Τίτος δὲ Οὐίνιος ὁ τοῦ στρατηγικοῦ τάγματος ἡγεμὼν αὐτοῖς εἶπεν· ὦ Γάλβα, τίνα τρόπον βουλεύεσθε; τὸ γὰρ ζητεῖν Νέρωνι εἰ πιστοὶ μενοῦμεν, οὐκ ἤδη μενόντων ἐστίν, ὡς οὖν ὑπάρχοντος ἐχθροῦ Νέρωνος οὐ δὴ προετέον τὴν τοῦ Οὐίνδικος φιλίαν, ἢ καὶ κατηγορητέον εὐθὺς αὐτοῦ καὶ πολεμητέον, ὅτι σὲ βούλεται Ῥωμαίους ἔχειν ἄρχοντα μᾶλλον ἢ Νέρωνα τύραννον.", "st": "Galb. 4.1"}, {"sp": "N", "t": "ἐκ τούτου προγράμματι μὲν ἐδήλωσεν ὁ Γάλβας ἡμέραν ἐν ᾗ τὰς κατά μέρος ἐλευθερώσεις ἀποδώσει τοῖς δεομένοις, λαλιὰ δὲ καὶ φήμη προεκπεσοῦσα πλῆθος ἀνθρώπων ἤθροισε προθύμων ἐπὶ τὸν νεωτερισμόν. οὐκ ἔφθη γοῦν φανερὸς ἐπὶ τοῦ βήματος γενόμενος, καὶ πάντες αὐτὸν ὁμοφώνως αὐτοκράτορα προσεῖπον. ὁ δὲ ταύτην μὲν εὐθὺς οὐ προσεδέξατο τὴν προσηγορίαν, κατηγορήσας δὲ τοῦ Νέρωνος, καὶ τῶν ἀνῃρημένων ἀνδρῶν ὑπ’ αὐτοῦ τοὺς ἐπιφανεστάτους ὀλοφυράμενος, ὡμολόγησεν ἐπιδώσειν τῇ πατρίδι τὴν ἑαυτοῦ πρόνοιαν, οὔτε Καῖσαρ οὔτε αὐτοκράτωρ, στρατηγὸς δὲ συγκλήτου καὶ δήμου Ῥωμαίων ὀνομαζόμενος.", "st": "Galb. 5.1"}, {"sp": "N", "t": "ὅτι δ’ ὀρθῶς ὁ Οὐίνδιξ καὶ λελογισμένως ἐξεκαλεῖτο τὸν Γάλβαν ἐπὶ τὴν ἡγεμονίαν, ἐπιστώσατο μάρτυρι τῷ Νέρωνι. προσποιούμενος γὰρ ἐκείνου καταφρονεῖν καὶ παρ’ οὐδὲν ἡγεῖσθαι τὰ Γαλατῶν, ἅμα τῷ πυθέσθαι τὰ περὶ Γάλβαν ἔτυχε δὲ λελουμένος καὶ ἀριστῶν ἀνέτρεψε τὴν τράπεζαν. οὐ μὴν ἀλλὰ συγκλήτου ψηφισαμένης πολέμιον τὸν Γάλβαν αὐτός τε παίζειν καὶ θρασύνεσθαι πρὸς τοὺς φίλους βουλόμενος, οὐ φαύλην ἔφη πρόρρησιν ἐμπεπτωκέναι λογισμοῦ δεομένῳ χρημάτων αὐτῷ· καὶ τὰ μὲν Γαλατῶν, ὅταν ὑποχείριοι γένωνται, λαφυραγωγήσεσθαι, ἡ δὲ Γάλβα πάρεστιν οὐσία χρῆσθαι καὶ πωλεῖν ἤδη πολεμίου πεφηνότος. οὗτός τε δὴ τὰ Γάλβα πιπράσκειν ἐκέλευε, καὶ Γάλβας ἀκούσας, ὅσα Νέρωνος ἦν ἐν Ἰβηρίᾳ κηρύττων εὕρισκε πολλοὺς προθυμοτέρους ὠνητάς.", "st": "Galb. 5.3"}, {"sp": "N", "t": "ἀφισταμένων δὲ πολλῶν τοῦ Νέρωνος καὶ πάντων ἐπιεικῶς τῷ Γάλβᾳ προστιθεμένων, μόνος Κλώδιος Μάκρος ἐν Λιβύῃ καὶ Οὐεργίνιος Ῥοῦφος ἐν Γαλατίᾳ τοῦ Γερμανικοῦ στρατεύματος ἡγούμενος αὐτοὶ καθ’ ἑαυτοὺς ἔπραττον, οὐ τὴν αὐτὴν αἵρεσιν ἔχοντες. ἀλλ’ ὁ μὲν Κλώδιος, ἐν ἁρπαγαῖς πραγμάτων γεγονὼς καὶ φόνοις ἀνδρῶν δι’ ὠμότητα καὶ πλεονεξίαν, δῆλος ἦν ἐν τῷ μήτε κατέχειν μήτε ἀφιέναι τὴν ἀρχὴν δύνασθαι περιφερόμενος; Οὐεργίνιος δὲ ταγμάτων ἐπιστατῶν δυνατωτάτων πολλάκις αὐτὸν ἀναγορευόντων αὐτοκράτορα καὶ βιαζομένων οὔτε αὐτὸς ἔφη λήψεσθαι τὴν ἡγεμονίαν οὔτε ἄλλῳ περιόψεσθαι διδομένην, ὃν ἂν μὴ ἡ σύγκλητος ἕληται. ταῦτα τὸν Γάλβαν οὐ μετρίως ἐθορύβει τὸ πρῶτον· ἐπεὶ δὲ τὰ Οὐεργινίου καὶ Οὐίνδικος στρατεύματα τρόπον τινὰ βίᾳ τοὺς ἡγεμόνας, ὥσπερ ἡνιόχους κρατῆσαι χαλινῶν μὴ δυνηθέντας, εἰς μάχην ἐξενεγκόντα μεγάλην συνέρραξαν, καὶ Οὐίνδικος ἑαυτὸν ἀνελόντος ἐπὶ δισμυρίοις Γαλατῶν πεσοῦσι, διῆλθε λόγος ὡς βουλομένων πάντων ἐπὶ νίκῃ τοσαύτῃ τὸν Οὐεργίνιον ἀναδέξασθαι τὴν ἡγεμονίαν ἢ πάλιν μεταβαλουμένων πρὸς Νέρωνα, τότε δὴ παντάπασι περίφοβος γενόμενος ὁ Γάλβας ἔγραψε τῷ Οὐεργινίῳ, παρακαλῶν κοινοπραγεῖν καὶ διαφυλάσσειν ἅμα τὴν ἡγεμονίαν καὶ τὴν ἐλευθερίαν Ῥωμαίοις· αὖθις δὲ μετὰ τῶν φίλων εἰς Κλουνίαν, Ἰβηρικὴν πόλιν, ἀναχωρήσας ἐν τῷ μετανοεῖν περὶ τῶν γεγονότων καὶ ποθεῖν τὴν συνήθη καὶ σύντροφον ἀπραγμοσύνην μᾶλλον ἢ πράττειν τι τῶν ἀναγκαίων διέτριβεν.", "st": "Galb. 6.1"}, {"sp": "N", "t": "ἦν δὲ θέρος ἤδη, καὶ βραχὺ πρὸ δείλης ἧκεν ἀπὸ Ῥώμης Ἴκελος ἀνὴρ ἀπελεύθερος ἑβδομαῖος. πυθόμενος δὲ τὸν Γάλβαν ἀναπαύεσθαι καθ’ ἑαυτὸν ἐβάδιζε συντόνως ἐπὶ τὸ δωμάτιον αὐτοῦ, καὶ βίᾳ τῶν θαλαμηπόλων ἀνοίξας καὶ παρελθὼν ἀπήγγειλεν ὅτι καὶ ζῶντος ἔτι τοῦ Νέρωνος, οὐκ ὄντος δὲ φανεροῦ, τὸ στράτευμα πρῶτον, εἶτα ὁ δῆμος καὶ ἡ σύγκλητος αὐτοκράτορα τὸν Γάλβαν ἀναγορεύσειεν, ὀλίγον δὲ ὕστερον ἀπαγγελθείη τεθνηκὼς ἐκεῖνος· οὐ μὴν αὐτός γε πιστεύσας ἔφη τοῖς ἀπαγγέλλουσιν, ἀλλὰ ἐπελθὼν τῷ νεκρῷ καὶ κείμενον θεασάμενος, οὕτως ἐξελθεῖν. ταῦτα ἀπαγγελλόμενα λαμπρὸν ἦρε τὸν Γάλβαν, καὶ συνέδραμε πλῆθος ἀνδρῶν ἐπὶ θύρας ἐκτεθαρρηκότων ὑπ’ αὐτοῦ βεβαίως, καίτοι τὸ τάχος ἦν ἄπιστον. ἀλλὰ καὶ δυσὶν ἡμέραις ὕστερον Οὐίνιος Τίτος ἀπὸ στρατοπέδου μεθ’ ἑτέρων ἀφίκετο τὰ δόξαντα τῇ συγκλήτῳ καθ’ ἕκαστον ἀπαγγέλλων. οὗτος μὲν οὖν εἰς τάξιν ἔντιμον προήχθη· τῷ δ’ ἀπελευθέρῳ δακτυλίους τε χρυσοῦς ἔδωκε καὶ Μαρκιανὸς ὁ Ἴκελος ἤδη καλούμενος εἶχε τὴν πρώτην ἐν τοῖς ἀπελευθέροις δύναμιν.", "st": "Galb. 7.1"}, {"sp": "N", "t": "ἐν δὲ Ῥώμῃ Νυμφίδιος Σαβῖνος, οὐκ ἠρέμα καὶ κατὰ μικρόν, ἀλλὰ συλλήβδην ὁμοῦ, πάντα πράγματα φέρων περιήνεγκεν εἰς ἑαυτόν, ὡς Γάλβαν μὲν ὄντα πρεσβύτην καὶ μόλις εἰς Ῥώμην ἐξαρκέσοντα φοράδην κομισθῆναι διὰ γῆρας ἦν γὰρ ἐτῶν τριῶν καὶ ἑβδομήκοντα· τὰ δὲ αὐτόθι στρατεύματα, καὶ πάλαι πρὸς αὐτὸν εὐνόως ἔχοντα καὶ νῦν ἑνὸς ἐξηρτημένα μόνου, διὰ τὸ τῆς δωρεᾶς μέγεθος εὐεργέτην ἐκεῖνον ἡγεῖσθαι, Γάλβαν δὲ χρεωφειλέτην. εὐθὺς οὖν Τιγελλίνῳ μὲν τῷ συνάρχοντι προσέταξεν ἀποθέσθαι τὸ ξίφος, ὑποδοχὰς δὲ ποιούμενος ἐδείπνιζε τοὺς ὑπατικοὺς καὶ τοὺς ἡγεμονικούς, ἔτι τὸ Γάλβα προστιθεὶς ὄνομα ταῖς κλήσεσιν, ἔν τε τῷ στρατοπέδῳ πολλοὺς παρεσκεύασε λέγειν ὡς πεμπτέον ἐστὶ πρὸς Γάλβαν αἰτουμένους ἔπαρχον εἰσαεὶ Νυμφίδιον ἄνευ συνάρχοντος.", "st": "Galb. 8.1"}, {"sp": "N", "t": "ἃ δὲ ἡ σύγκλητος εἰς τιμὴν ἔπραττεν αὐτοῦ καὶ δύναμιν, ἀνακαλοῦσα εὐεργέτην καὶ συντρέχουσα καθ’ ἡμέραν ἐπὶ θύρας καὶ παντὸς ἐξάρχειν δόγματος ἀξιοῦσα καὶ βεβαιοῦν, ἔτι περαιτέρω τόλμης ἀνῆγεν αὐτόν, ὥστε ὀλίγου χρόνου τοῖς θεραπεύουσι μὴ μόνον ἐπίφθονον, ἀλλὰ καὶ φοβερὸν εἶναι. τῶν δ’ ὑπάτων οἰκέτας δημοσίους προχειρισαμένων τὰ δόγματα κομίζοντας τῷ αὐτοκράτορι, καὶ τὰ καλούμενα διπλώματα σεσημασμένα δόντων, ἃ γνωρίζοντες οἱ κατὰ πόλιν ἄρχοντες ἐν ταῖς τῶν ὀχημάτων ἀμοιβαῖς ἐπιταχύνουσι τὰς προπομπὰς τῶν γραμματηφόρων, οὐ μετρίως ἠγανάκτησεν ὅτι μὴ παρ’ αὐτοῦ καὶ σφραγῖδα καὶ στρατιώτας λαβόντες ἀνέπεμψαν, ἀλλὰ λέγεται καὶ βουλεύσασθαι περὶ τῶν ὑπάτων, εἶτα τὴν ὀργὴν ἀπολογησαμένοις καὶ δεηθεῖσιν ἀνῆκε. τῷ δὲ δήμῳ χαριζόμενος οὐκ ἐκώλυε τὸν παραπίπτοντα τῶν Νέρωνος ἀποτυμπανίζειν. Σπῖκλον μὲν οὖν τὸν μονομάχον ἀνδριάσι Νέρωνος ἑλκομένοις ὑποβαλόντες ἐν ἀγορᾷ διέφθειραν, Ἀπόνιον δέ τινα τῶν κατηγορικῶν ἀνατρέψαντες ἁμάξας λιθοφόρους ἐπήγαγον, ἄλλους δὲ διέσπασαν πολλούς, ἐνίους μηδὲν ἀδικοῦντας, ὥστε καὶ Μαύρικον, ἄνδρα τῶν ἀρίστων καὶ ὄντα καὶ δοκοῦντα, πρὸς τὴν σύγκλητον εἰπεῖν ὅτι φοβεῖται μὴ ταχὺ Νέρωνα ζητήσωσιν.", "st": "Galb. 8.3"}, {"sp": "N", "t": "οὕτω δὲ προσάγων ὁ Νυμφίδιος ἐγγυτέρω ταῖς ἐλπίσιν οὐκ ἔφευγε Γαΐου Καίσαρος υἱὸς λέγεσθαι τοῦ μετὰ Τιβέριον ἄρξαντος. ἐγνώκει γὰρ ὁ Γάϊος, ὡς ἔοικε, τὴν τεκοῦσαν αὐτὸν ἔτι μειράκιον ὢν οὐκ ἀειδῆ τὴν ὄψιν οὖσαν, ἐκ δ’ ἀκεστρίας ἐπιμισθίου Καλλίστῳ, Καίσαρος ἀπελευθέρῳ, γεγενημένην. ἀλλ’ ἦν ἡ πρὸς Γάϊον ἔντευξις αὐτῆς, ὡς ἔοικε, νεωτέρα τῆς Νυμφιδίου γενέσεως, αἰτίαν δὲ ἔσχεν ἐκ Μαρτιανοῦ τοῦ μονομάχου γεγονέναι, τῆς Νυμφιδίας ἐρασθείσης διὰ δόξαν αὐτοῦ, καὶ μᾶλλον ἐδόκει καθ’ ὁμοιότητα τῆς ἰδέας ἐκείνῳ προσήκειν. ἀλλ’ ὁμολογῶν γε Νυμφιδίας εἶναι μητρὸς ἔργον μὲν αὑτοῦ μόνου τὴν Νέρωνος ἐποιεῖτο κατάλυσιν, ἆθλα δὲ αὐτῆς οὐ νομίζων ἱκανὰ καρποῦσθαι τὰς τιμὰς καὶ τὰ χρήματα καὶ τὸ Σπόρῳ τοῦ Νέρωνος συγκαθεύδειν, ὃν εὐθὺς ἀπὸ τῆς πυρᾶς ἔτι καιομένου τοῦ νεκροῦ μεταπεμψάμενος ἐκεῖνος ἐν γαμετῆς εἶχε τάξει καὶ Ποππαίαν προσηγόρευεν, ἐπὶ τὴν διαδοχὴν παρεδύετο τῆς ἡγεμονίας. καὶ τὰ μὲν αὐτὸς ἐν Ῥώμῃ διὰ τῶν φίλων ὑπειργάζετο, καὶ γυναικῶν τινων αὐτῷ καὶ συγκλητικῶν ἀνδρῶν κρύφα συλλαμβανομένων, ἕνα δὲ τῶν φίλων, Γελλιανόν, εἰς Ἰβηρίαν ἔπεμψεν κατασκεψόμενον.", "st": "Galb. 9.1"}, {"sp": "N", "t": "τῷ δὲ Γάλβᾳ μετὰ τὴν Νέρωνος τελευτὴν ἐχώρει πάντα. Οὐεργίνιος δὲ Ῥοῦφος ἀμφίβολος ὢν ἔτι φροντίδα παρεῖχε, μὴ τῷ δυνάμεως πολλῆς καὶ μαχιμωτάτης ἄρχειν προσειληφὼς τὸ νενικηκέναι Οὐίνδικα καὶ κεχειρῶσθαι μέγα μέρος τῆς Ῥωμαίων ἡγεμονίας, ἐν σάλῳ γενομένην ἀποστατικῷ Γαλατίαν ἅπασαν, ὑπακούσαι τοῖς παρακαλοῦσιν αὐτὸν ἐπὶ τὴν ἀρχήν. οὐδενὸς γὰρ ἦν ὄνομα μεῖζον, οὐδὲ εἶχε δόξαν οὐδεὶς ὅσην ὁ Οὐεργίνιος, ὡς μεγίστη ῥοπὴ τοῖς Ῥωμαίων πράγμασι τυραννίδος ὁμοῦ χαλεπῆς καὶ Γαλατικῶν πολέμων ἀπαλλαγῇ γενόμενος, ἀλλ’ ἐκεῖνος τότε τοῖς ἐξ ἀρχῆς ἐμμένων λογισμοῖς ἐφύλαττε τῇ συγκλήτῳ τὴν αἵρεσιν τοῦ αὐτοκράτορος. καίτοι φανερᾶς γε τῆς Νέρωνος τελευτῆς γενομένης τό τε πλῆθος ἐνέκειτο τῷ Οὐεργινίῳ πάλιν, καὶ τῶν χιλιάρχων τις τῶν ἐν τῇ σκηνῇ σπασάμενος τὸ ξίφος ἐκέλευε τὸν Οὐεργίνιον δέχεσθαι τὴν ἡγεμονίαν ἢ τὸν σίδηρον. ἐπεὶ δὲ Φάβιος Οὐάλης ἄρχων ἑνὸς τάγματος ὥρκωσε πρῶτος εἰς Γάλβαν, καὶ γράμματα ἧκεν ἀπὸ Ῥώμης περὶ ὧν ἡ σύγκλητος ἐψηφίσατο, χαλεπῶς μὲν καὶ μόλις, ἔπεισε δ’ οὖν τοὺς στρατιώτας αὐτοκράτορα τὸν Γάλβαν ἀνειπεῖν καὶ πέμψαντος αὐτοῦ διάδοχον Φλάκκον Ὁρδεώνιον ἐδέξατο. καὶ παραδοὺς ἐκείνῳ τὴν δύναμιν αὐτὸς ἀπήντησε τῷ Γάλβᾳ πρόσω χωροῦντι, καὶ συνανέστρεφεν, οὔτε ὀργῆς οὔτε τιμῆς ἐπιδήλου τυγχάνων. αἴτιος δὲ τοῦ μὲν αὐτὸς ὁ Γάλβας αἰδούμενος τὸν ἄνδρα, τοῦ δὲ οἱ φίλοι καὶ μάλιστα Οὐίνιος Τίτος, ὑπὸ φθόνου τὸν Οὐεργίνιον οἰόμενος μὲν κολούειν, ἠγνόει δὲ ἄρα τῷ Οὐεργινίου χρηστῷ δαίμονι συνεργῶν, ἤδη τὸν ἄνδρα πολέμων καὶ κακῶν, ὅσα τοὺς ἄλλους ἡγεμόνας κατέσχεν, ἐκτὸς εἰς βίον ἀκύμονα καὶ γῆρας εἰρήνης καὶ ἡσυχίας μεστὸν ὑπεκτιθεμένῳ.", "st": "Galb. 10.1"}, {"sp": "N", "t": "Γάλβαν δὲ περὶ Νάρβωνα, πόλιν Γαλατικήν, οἱ παρὰ τῆς συγκλήτου πρέσβεις ἐντυχόντες ἠσπάζοντο, καὶ παρεκάλουν ἐπιφανῆναι τῷ δήμῳ ποθοῦντι ταχέως, ὁ δὲ τάς τε ἄλλας παρεῖχεν ἐντεύξεις καὶ συνουσίας αὐτοῖς φιλανθρώπους καὶ δημοτικάς, πρός τε τάς ἑστιάσεις πολλῆς κατασκευῆς καὶ θεραπείας βασιλικῆς παρούσης, ἣν ἐκ τῶν Νέρωνος ὁ Νυμφίδιος αὐτῷ προσέπεμψεν, οὐδενὶ χρώμενος ἐκείνων, ἀλλὰ τοῖς ἑαυτοῦ πᾶσιν, εὐδοκίμει, μεγαλόφρων ἀνὴρ καὶ κρείττων ἀπειροκαλίας φαινόμενος. ταχὺ μέντοι τὰ γενναῖα ταῦτα καὶ ἄτυφα καὶ πολιτικὰ δημαγωγίαν Οὐίνιος ἀποφαίνων καὶ κομψότητα μεγάλων ἀπαξιοῦσαν αὑτήν, ἔπεισε χρήμασί τε χρῆσθαι τοῖς Νέρωνος καὶ περὶ τάς ὑποδοχὰς μὴ φείδεσθαι τῆς βασιλικῆς πολυτελείας, καὶ ὅλως αἴσθησιν αὑτοῦ κατὰ μικρὸν ὑπὸ τῷ Οὐινίῳ γενησομένου παρεῖχεν ὁ πρεσβύτης.", "st": "Galb. 11.1"}, {"sp": "N", "t": "ἦν δὲ Οὐίνιος ἀργυρίου μὲν ἐσχάτως καὶ παρ’ ὁντινοῦν ἥττων, ἔνοχος δὲ καὶ τοῖς περὶ γυναῖκας ἁμαρτήμασιν. ἔτι γὰρ ὢν νέος καὶ στρατευόμενος ὑπὸ Καλβισίῳ Σαβίνῳ τὴν πρώτην στρατείαν ἀκόλαστον οὖσαν τὴν γυναῖκα τοῦ ἡγεμόνος παρεισήγαγε νύκτωρ εἰς τὸ στρατόπεδον ἐν ἐσθῆτι στρατιωτικῇ καὶ διέφθειρεν ἐν τοῖς ἀρχείοις, ἃ πριγκίπια καλοῦσι Ῥωμαῖοι. ἐπὶ τούτῳ δὲ Γάϊος Καῖσαρ ἔδησεν αὐτόν ἐκείνου δὲ ἀποθανόντος εὐτυχίᾳ χρησάμενος ἀπελύθη, δειπνῶν δὲ παρὰ Κλαυδίῳ Καίσαρι ποτήριον ἀργυροῦν ὑφείλετο πυθόμενος δὲ ὁ Καῖσαρ τῇ ὑστεραίᾳ πάλιν αὐτόν ἐπὶ δεῖπνον ἐκάλεσεν, ἐλθόντι δὲ ἐκέλευσεν ἐκείνῳ μηδὲν ἀργυροῦν, ἀλλὰ κεράμεα πάντα προσφέρειν καὶ παρατιθέναι τοὺς ὑπηρέτας. τοῦτο μὲν οὖν διὰ τὴν Καίσαρος μετριότητα κωμικωτέραν γενομένην γέλωτος, οὐκ ὀργῆς ἄξιον ἔδοξεν ἃ δὲ τὸν Γάλβαν ἔχων ὑφ’ αὑτῷ καὶ δυνάμενος μέγιστον ἐπὶ χρήμασιν, ἔπραττε, τραγικῶν παθῶν καὶ συμφορῶν μεγάλων τοῖς μὲν αἰτίαν, τοῖς δὲ πρόφασιν παρέσχεν.", "st": "Galb. 12.1"}, {"sp": "N", "t": "ὁ γὰρ Νυμφίδιος εὐθὺς ἐπανελθόντος τοῦ Γελλιανοῦ πρὸς αὐτόν, ὃν ἔπεμψε τοῦ Γάλβᾳ τρόπον τινὰ κατάσκοπον, ἀκούσας τῆς μὲν αὐλῆς καὶ τῶν δορυφόρων ἔπαρχον ἀποδεδεῖχθαι Κορνήλιον Λάκωνα, τὸ δὲ σύμπαν εἶναι τοῦ Οὐινίου κράτος, αὐτῷ δὲ μηδέποτε τοῦ Γάλβᾳ στῆναι πλησίον ἐγγεγονέναι μηδὲ ἐντυχεῖν ἰδίᾳ, πάντων αὐτὸν ὑφορωμένων καὶ διαφυλαττόντων, ἐθορυβήθη· καὶ συναγαγὼν τοὺς ἡγεμόνας τοῦ στρατεύματος ἔφη Γάλβαν μὲν αὐτὸν εἶναι πρεσβύτην ἐπιεικῆ καὶ μέτριον, ἐλάχιστα δὲ τοῖς αὑτοῦ χρώμενον λογισμοῖς ὑπὸ Οὐινίου καὶ Λάκωνος οὐκ εὖ διοικεῖσθαι. πρὶν οὖν λαθεῖν αὐτοὺς ἣν ἔσχε Τιγελλῖνος ἰσχὺν ἐν τοῖς πράγμασι κτησαμένους, πεμπτέον εἶναι πρὸς τὸν ἡγεμόνα πρέσβεις ἀπὸ στρατοπέδου τοὺς διδάξοντας ὅτι τῶν φίλων δύο μόνους τούτους ἀποσκευασάμενος ἡδίων παρέσται πᾶσι καὶ ποθεινότερος. ἐπεὶ δὲ ταῦτα λέγων οὐκ ἔπειθεν, ἀλλ’ ἄτοπον ἐδόκει καὶ ἀλλόκοτον ἡγεμόνα πρεσβύτην, ὥσπερ ἄρτι γευόμενον ἐξουσίας μειράκιον, οἷς χρήσεται φίλοις ἢ μή, ῥυθμίζειν, ἑτέραν ὁδὸν τραπόμενος ἔγραφε τῷ Γάλβᾳ δεδιττόμενος, νῦν μὲν ὡς ὕπουλα καὶ μετέωρα πολλὰ τῆς πόλεως ἐχούσης, νῦν δὲ Κλώδιον Μάκρον ἐν Λιβύῃ τὰ σιτηγὰ κατέχειν, αὖθις δὲ παρακινεῖν τὰ Γερμανικὰ τάγματα, καὶ περὶ τῶν ἐν Συρίᾳ καὶ Ἰουδαίᾳ δυνάμεων ὅμοια πυνθάνεσθαι. τοῦ δὲ Γάλβᾳ μὴ πάνυ τὸν νοῦν προσέχοντος αὐτῷ μηδὲ πιστεύοντος ἔγνω προεπιχειρεῖν καίτοι Κλώδιος Κέλσος Ἀντιοχεύς, ἀνὴρ ἔμφρων, εὔνους δὲ ἐκείνῳ καὶ πιστός, ἀπηγόρευε, λέγων οὐκ ἂν οἴεσθαι μίαν ἐν Ῥώμῃ συνοικίαν Καίσαρα προσειπεῖν Νυμφίδιον. ἀλλὰ πολλοὶ κατεγέλων, καὶ Μιθριδάτης ὁ Ποντικὸς ἐπισκώπτων τὴν φαλακρότητα καὶ ῥυσσότητα τοῦ Γάλβᾳ νῦν ἔφη τινὰ δοκεῖν εἶναι Ῥωμαίοις, ὀφθέντα δὲ φανεῖσθαι τῶν ἡμερῶν τούτων ἃς καλεῖται Καῖσαρ, ὄνειδος.", "st": "Galb. 13.1"}, {"sp": "N", "t": "ἔδοξεν οὖν περὶ μέσας νύκτας εἰς τὴν παρεμβολὴν παραγαγόντας ἀναδεικνύειν αὐτοκράτορα τὸν Νυμφίδιον. πρῶτος δὲ τῶν χιλιάρχων Ἀντώνιος Ὁνωράτος ἑσπέρας γενομένης τοὺς ὑφ’ ἑαυτῷ στρατιώτας συναγαγὼν ἐκάκιζε μὲν αὑτόν, ἐκάκιζε δὲ ἐκείνους ἐν ὀλίγῳ χρόνῳ τροπὰς τοσαύτας τρεπομένους κατ’ οὐδένα λογισμὸν οὐδὲ αἵρεσιν ἀμεινόνων, ἀλλὰ δαίμονός τινος αὐτοὺς ἐκ προδοσίας εἰς προδοσίαν ἐλαύνοντος. καὶ τὰ μὲν πρῶτα προφάσεις ἔχειν τὰ Νέρωνος ἐγκλήματα· νῦν δὲ Γάλβαν προδιδόναι, τίνα φόνον μητρὸς ἐγκαλοῦντας ἢ σφαγὴν γυναικός, ἢ ποίαν αἰδουμένους θυμέλην ἢ τραγῳδίαν τοῦ αὐτοκράτορος; ἀλλ’ οὐδὲ ἐκεῖνον ἐπὶ τούτοις ὑπεμείναμεν ἐγκαταλιπεῖν, ἀλλὰ Νυμφιδίῳ πεισθέντες ὅτι πρῶτος ἡμᾶς ἐγκατέλιπε καὶ πέφευγεν εἰς Αἴγυπτον. πότερον οὖν Νέρωνι Γάλβαν ἐπιθυσώμεθα, καὶ τὸν ἐκ Νυμφιδίας ἑλόμενοι Καίσαρα τὸν ἐκ Λιβίας ἀνέλωμεν, ὡς τὸν ἐξ Ἀγριππίνης ἀνείλομεν; ἢ τούτῳ δίκην ἐπιθέντες ὧν δέδρακε, τιμωροὶ μὲν Νέρωνος, Γάλβα δὲ φύλακες ἀγαθοὶ καὶ πιστοὶ φανῶμεν;", "st": "Galb. 14.1"}, {"sp": "N", "t": "ταῦτα λέγοντι τῷ χιλιάρχῳ προσέθεντο πάντες οἱ στρατιῶται, καὶ τοὺς ἄλλους προσιόντες ἐμμένειν παρεκάλουν τῇ πρὸς τὸν αὐτοκράτορα πίστει· καὶ τοὺς πλείους μετέστησαν. ἀρθείσης δὲ βοῆς, εἴτε πεισθεὶς ὁ Νυμφίδιος, ὥς φασιν ἔνιοι, καλεῖν αὐτὸν ἤδη τοὺς στρατιώτας, εἴτε προλαβεῖν σπεύδων τὸ θορυβοῦν ἔτι καὶ διστάζον, ὑπὸ φωτὶ πολλῷ προῄει, λόγον τινὰ κομίζων ἐν βιβλίῳ γεγραμμένον ὑπὸ Κιγγωνίου Βάρρωνος, ὃν ἐκμεμελετήκει πρὸς τοὺς στρατιώτας εἰπεῖν. ἰδὼν δὲ κεκλεισμένας τοῦ στρατοπέδου τὰς πύλας καὶ περὶ τὰ τείχη πολλοὺς ὡπλισμένους ἔδεισε· καὶ προσιὼν ἠρώτα τί βούλονται καί τινος κελεύσαντος ἐν ὅπλοις γεγόνασιν. ἀπαντώσης δ’ αὐτῷ παρὰ πάντων μιᾶς φωνῆς, Γάλβαν αὐτοκράτορα γινώσκειν, κἀκεῖνος ὁμόσε χωρῶν ἐπευφήμει καὶ τοὺς ἑπομένους ἐκέλευε. τῶν δὲ παρὰ τὰς πύλας παρέντων αὐτὸν εἰσελθεῖν μετ’ ὀλίγων αὐτὸς ἀκοντίζεται λόγχῃ· καὶ ταύτην μὲν ἐδέξατο πρὸ αὐτοῦ θυρεῷ Σεπτίμιος, ἄλλων δὲ γυμνοῖς ξίφεσιν ἐπιφερομένων φυγὼν καὶ διωχθεὶς ἐν οἰκήματι στρατιώτου σφάττεται. καὶ τὸν νεκρὸν εἰς μέσον ἑλκύσαντες καὶ περιβαλόντες κιγκλίδα θέαμα τοῖς βουλομένοις μεθ’ ἡμέραν παρέσχον.", "st": "Galb. 14.4"}, {"sp": "N", "t": "οὕτω δὲ τοῦ Νυμφιδίου καταστρέψαντος ὁ Γάλβας πυθόμενος, καί τῶν συνωμοτῶν αὐτοῦ κελεύσας ἀποθανεῖν ὅσοι μὴ δι’ αὑτῶν εὐθὺς ἀπέθανον, ἐν οἷς ἦν καί Κιγγώνιος ὁ τὸν λόγον γράψας καί Μιθριδάτης ὁ Ποντικός, ἔδοξε μὴ νομίμως, εἰ καί δικαίως, μηδὲ δημοτικῶς ἀνῃρηκέναι πρὸ κρίσεως ἄνδρας οὐκ ἀσήμους, ἕτερον γὰρ ἡγεμονίας σχῆμα προσεδέχοντο πάντες, ἐξαπατώμενοι συνήθως ὑπὸ τῶν ἐν ἀρχῇ λεγομένων. ἔτι δὲ μᾶλλον ἠνίασεν αὐτοὺς ἀνὴρ ὑπατικὸς καί Νέρωνι πιστὸς ἀποθανεῖν κελευσθείς, Πετρώνιος Τουρπιλιανός. Μάκρον γὰρ ἐν Λιβύῃ διὰ Τρεβωνίου καὶ Φοντήϊον ἐν Γερμανίᾳ διὰ Οὐάλεντος ἀνελὼν πρόφασιν εἶχεν ἐν ὅπλοις καί στρατοπέδοις ὄντας φοβηθῆναι. Τουρπιλιανὸν δέ, γέροντα γυμνὸν καί ἄνοπλον, λόγου μεταλαβεῖν οὐδὲν ἐκώλυεν, εἴ τις ἣν ἐπαγγέλλεται μετριότητα τοῖς πράγμασιν ἔργῳ φυλάξειν ἔμελλε.", "st": "Galb. 15.1"}, {"sp": "N", "t": "ταῦτα μὲν οὖν τοιαύτας ἔχει μέμψεις. ἐπεὶ δὲ προσιὼν ἀπεῖχε τῆς πόλεως περὶ πέντε καί εἴκοσι σταδίους, ἐνετύγχανεν ἀκοσμίᾳ καί θορύβῳ τῶν ἐρετῶν τὴν ὁδὸν προκατεχόντων καὶ περικεχυμένων πανταχόθεν, οὗτοι δὲ ἦσαν οὓς εἰς ἓν τάγμα ὁ Νέρων συλλοχίσας ἀπέφηνε στρατιώτας· καί τότε παρόντες ἐκβεβαιώσασθαι τὴν στρατείαν οὔτ’ ὀφθῆναι τοῖς ἀπαντῶσιν οὔτ’ ἀκουσθῆναι παρίεσαν τὸν αὐτοκράτορα, ἀλλ’ ἐθορύβουν βοῇ σημεῖα τῷ τάγματι καί χώραν αἰτοῦντες, ἐκείνου δὲ ὑπερτιθεμένου καί πάλιν εἰπεῖν κελεύσαντος, ἀρνήσεως σχῆμα τὴν ἀναβολὴν εἶναι φάσκοντες ἠγανάκτουν καί παρείποντο μὴ φειδόμενοι βοῆς. ἐνίων δὲ καί τὰς μαχαίρας σπασαμένων, ἐκέλευσε τοὺς ἱππεῖς ἐμβαλεῖν αὐτοῖς ὁ Γάλβας. ὑπέστη δὲ οὐδεὶς ἐκείνων, ἀλλ’ οἱ μὲν εὐθὺς ἀνατραπέντες, οἱ δὲ φεύγοντες διεφθάρησαν, οὐ χρηστὸν οὐδὲ αἴσιον ποιοῦντες τῷ Γάλβᾳ τὸν οἰωνὸν εἰσιόντι διὰ πολλοῦ φόνου καί νεκρῶν τοσούτων εἰς τὴν πόλιν. ἀλλ’ εἰ καί τις αὐτοῦ κατεφρόνει πρότερον ἀσθενοῦς καί γέροντος ὁρωμένου, τότε πᾶσι φρικώδης καί φοβερὸς ἐγένετο.", "st": "Galb. 15.3"}, {"sp": "N", "t": "βουλόμενος δὲ τῆς περὶ τὰς δωρεὰς ἀμετρίας καὶ πολυτελείας τοῦ Νέρωνος ἀποδεικνύναι μεγάλην μεταβολήν, ἀστοχεῖν ἐδόκει τοῦ πρέποντος. Κάνου γὰρ αὐλήσαντος αὑτῷ παρὰ δεῖπνον (ἀκρόαμα δὲ ἦν ὁ Κάνος εὐδοκιμούμενον ἐπαινέσας καὶ ἀποδεξάμενος ἐκέλευσεν αὑτῷ κομισθῆναι τὸ γλωσσόκομον· καὶ λαβὼν χρυσοῦς τινας ἐπέδωκε τῷ Κάνῳ, φήσας ἐκ τῶν ἰδίων, οὐκ ἐκ τῶν δημοσίων χαρίζεσθαι. τὰς δὲ δωρεὰς ἃς Νέρων ἔδωκε τοῖς περὶ σκηνὴν καὶ παλαίστραν, ἀπαιτεῖσθαι συντόνως κελεύσας πλὴν τοῦ δεκάτου μέρους, εἶτα μικρὰ καὶ γλίσχρα κομιζόμενος ἀνηλώκεσαν γὰρ οἱ πλεῖστοι τῶν λαβόντων, ἐφήμεροι καὶ σατυρικοὶ τοῖς βίοις ἄνθρωποι τοὺς πριαμένους παρ) αὐτῶν ἢ λαβόντας ὁτιοῦν ἀνεζήτει καὶ παρ’ ἐκείνων ἐξέπραττε. τοῦ δὲ πράγματος ὅρον οὐκ ἔχοντος, ἀλλὰ πόρρω νεμομένου καὶ προϊόντος ἐπὶ πολλούς, αὐτὸς μὲν ἠδόξει, φθόνον δὲ καὶ μῖσος εἶχεν Οὐίνιος, ὡς τοῖς μὲν ἄλλοις ἅπασιν ἀνελεύθερον παρέχων τὸν ἡγεμόνα καὶ μικρολόγον, αὐτὸς δὲ χρώμενος ἀσώτως καὶ λαμβάνων πάντα καὶ πιπράσκων. ὁ μὲν γὰρ Ἡσίοδος", "st": "Galb. 16.1"}, {"sp": "N", "t": "ἀρχομένου τε πίθου καὶ λήγοντος κορέσασθαι", "st": "Galb. 16.1b"}, {"sp": "N", "t": "φησὶ δεῖν, ὁ δὲ Οὐίνιος ὁρῶν ἀσθενῆ καὶ γέροντα τὸν Γάλβαν ἐνεπίμπλατο τῆς τύχης, ὡς ἅμα μὲν ἀρχομένης, ἅμα δὲ φθινούσης.", "st": "Galb. 16.1c"}, {"sp": "N", "t": "ὁ δὲ πρεσβύτης ἠδικεῖτο τὰ μὲν πρῶτα τοῦ Οὐινίου κακῶς διοικοῦντος, ἃ δὲ αὐτὸς ὀρθῶς προῃρεῖτο διαβάλλοντος ἢ κωλύοντος· οἷον ἦν τὸ περὶ τὰς κολάσεις τῶν Νερωνιανῶν. ἀπέκτεινε γὰρ τοὺς πονηρούς, ἐν οἷς ἦν ὁ Ἥλιος καὶ Πολύκλειτος καὶ Πετῖνος καὶ Πατρόβιος. ὁ δὲ δῆμος ἐκρότει, καὶ δι’ ἀγορᾶς αὐτῶν ἀγομένων ἐβόα καλὴν μὲν εἶναι καὶ θεοφιλῆ πομπήν, ἀπαιτεῖν δὲ καὶ θεοὺς καὶ ἀνθρώπους τὸν διδάσκαλον καὶ παιδαγωγὸν τῆς τυραννίδος Τιγελλῖνον. ἐφθάκει δὲ ὁ γενναῖος προειληφὼς ἀρραβῶσι μεγάλοις τὸν Οὐίνιον. εἶτα Τουρπιλιανὸς μέν, ὅτι μὴ προεδίδου μηδὲ ἐμίσει τὸν ἡγεμόνα τοιοῦτον ὄντα μισούμενος, ἄλλο δὲ μηδὲ ἓν μέγα συναδικήσας, ἀπέθανεν ὁ δὲ καὶ ποιήσας ἄξιον θανάτου Νέρωνα καὶ γενόμενον τοιοῦτον ἐγκαταλιπὼν καὶ προδοὺς περιῆν, μέγα δίδαγμα τοῦ μηδὲν ἄπρακτον εἶναι παρὰ Οὐινίῳ μηδὲ ἀνέλπιστον τοῖς διδοῦσιν. οὐδενὸς γὰρ οὕτω θεάματος ἐρασθεὶς ὁ Ῥωμαίων δῆμος ὡς τοῦ Τιγελλῖνον ἰδεῖν ἀπαγόμενον, οὐδὲ παυσάμενος ἐν πᾶσι θεάτροις καὶ σταδίοις αἰτούμενος ἐκεῖνον, ἐπεπλήχθη διαγράμματι τοῦ αὐτοκράτορος Τιγελλῖνον μὲν οὐ πολὺν ἔτι βιώσεσθαι φάσκοντος χρόνον ὑπὸ φθινάδος νόσου δαπανώμενον, ἐκείνους δὲ παραιτουμένου μὴ διαγριαίνειν μηδὲ τυραννικὴν ποιεῖν τὴν ἡγεμονίαν. ἀχθομένου δὲ τοῦ δήμου καταγελῶντες ὁ μὲν Τιγελλῖνος ἔθυσε σωτήρια καὶ παρεσκεύασε λαμπρὰν ἑστίασιν, ὁ δὲ Οὐίνιος ἀναστὰς παρὰ τοῦ αὐτοκράτορος μετὰ δεῖπνον ἐκώμασεν ὡς ἐκεῖνον, ἄγων τὴν θυγατέρα χήραν οὖσαν. καὶ προὔπιεν ὁ Τιγελλῖνος αὐτῇ πέντε καὶ εἴκοσι μυριάδας ἀργυρίου, καὶ τῶν παλλακίδων τὴν ἀγελαρχοῦσαν ἐκέλευσε τὸν περιδέραιον κόσμον ἀφελομένην ἐκείνῃ περιάψαι, πεντεκαίδεκα μυριάδων εἶναι λεγόμενον.", "st": "Galb. 17.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου καί τὰ μετρίως πραττόμενα διαβολὴν εἶχεν, ὡς τὰ πρὸς τοὺς Γαλάτας Οὐΐνδικι συναραμένους. ἐδόκουν γὰρ οὐ φιλανθρωπίᾳ τοῦ αὐτοκράτορος, ἀλλὰ ὠνούμενοι παρὰ Οὐινίου τυγχάνειν ἀνέσεώς τε δασμῶν καί πολιτείας. οἱ μὲν οὖν πολλοὶ διὰ ταῦτα πρὸς τὴν ἡγεμονίαν ἀπηχθάνοντο, τοὺς δὲ στρατιώτας τὴν δωρεὰν μὴ κομιζομένους ἐν ἀρχῇ μὲν ἐλπὶς παρῆγεν ὡς, εἰ καί μὴ τοσοῦτον, ἀλλ’ ὅσον Νέρων ἔδωκεν, ἀποδώσοντος. ἐπεὶ δὲ μεμφομένους ἀκούσας ἀφῆκε φωνὴν ἡγεμόνι μεγάλῳ πρέπουσαν, εἰπὼν εἰωθέναι καταλέγειν στρατιώτας, οὐκ ἀγοράζειν, πυθομένοις τοῦτο δεινὸν εἰσῆλθε μῖσος καί ἄγριον πρὸς αὐτόν, ἐδόκει γὰρ οὐκ αὐτὸς ἀποστερεῖν μόνος, ἀλλὰ νομοθετεῖν καί διδάσκειν τοὺς μεθ’ αὑτὸν αὐτοκράτορας.", "st": "Galb. 18.1"}, {"sp": "N", "t": "ἀλλὰ τὸ μὲν ἐν Ῥώμῃ τυφλὸν ἦν ἔτι κίνημα, καί τις αἰδὼς ἅμα πρὸς παρόντα τὸν Γάλβαν ἀμβλύτητα καί μέλλησιν ἐνεποίει τῷ νεωτερισμῷ, καί τὸ μηδεμίαν ἀρχὴν ἐμφανῆ μεταβολῆς ὁρᾶσθαι συνέστελλε καί συνέκρυπτεν ἁμῶς γέ πως τὴν δυσμένειαν αὐτῶν, οἱ δὲ πρότερον ὑπὸ Οὐεργινίῳ γενόμενοι, τότε δὲ ὄντες ὑπὸ Φλάκκῳ περὶ Γερμανίαν, μεγάλων μὲν ἀξιοῦντες αὑτοὺς διὰ τὴν μάχην ἣν ἐμαχέσαντο πρὸς Οὐΐνδικα, μηδενὸς δὲ τυγχάνοντες, ἀπαρηγόρητοι τοῖς ἄρχουσιν ἦσαν. αὑτὸν δὲ τὸν Φλάκκον ὑπὸ συντόνου ποδάγρας ἀδύνατον ὄντα τῷ σώματι καὶ πραγμάτων ἄπειρον ἐν οὐδενὶ λόγῳ τὸ παράπαν ἐποιοῦντο. καί ποτε θέας οὔσης, καί τῶν χιλιάρχων καί λοχαγῶν τὸ Ῥωμαίοις σύνηθες εὐτυχίαν ἐπευχομένων τῷ αὐτοκράτορι Γάλβᾳ, διεθορύβησαν οἱ πολλοὶ τὸ πρῶτον, εἶτα ταῖς εὐχαῖς ἐπιμενόντων ἐκείνων ἀντεφώνουν εἰ ἄξιος.", "st": "Galb. 18.3"}, {"sp": "N", "t": "τοιαῦτα δὲ ἕτερα καὶ τῶν ὑπὸ Τιγελλίνῳ ταγμάτων ὑβριζόντων πολλάκις, ἐπέμπετο γράμματα τῷ Γάλβᾳ παρὰ τῶν ἐπιτρόπων ὁ δὲ φοβηθεὶς ὡς μὴ μόνον διὰ τὸ γῆρας, ἀλλὰ καὶ διὰ τήν ἀπαιδίαν καταφρονούμενος, ἐβουλεύετο παῖδα θέσθαι τῶν ἐπιφανῶν τινα νεανίσκον καὶ διάδοχον ἀποδεῖξαι τῆς ἀρχῆς. ἦν δέ Μάρκος Ὄθων, ἀνὴρ γένει μὲν οὐκ ἀφανής, τρυφῇ δὲ καὶ φιληδονίαις εὐθὺς ἐκ παίδων ἐν ὀλίγοις Ῥωμαίων διεφθαρμένος, ὡς δὲ τὸν Ἀλέξανδρον Ὅμηρος Ἑλένης; πόσιν ἠϋκόμοιο, μηδὲν ἔχοντα πρὸς δόξαν ἄλλο σεμνύνων ἀπὸ τῆς γυναικός, ὀνομάζει πολλάκις, οὕτως γεγονὼς περιβόητος ἐν Ῥώμῃ διὰ τὸν Ποππαίας γάμον, ἧς ἤρα μὲν ὁ Νέρων Κρισπίνῳ συνούσης, ἔτι δ’ αἰδούμενος τήν ἑαυτοῦ γυναῖκα καὶ τήν μητέρα φοβούμενος ὑφῆκε τὸν Ὄθωνα πειρῶντα τήν Ποππαίαν. φίλῳ δὲ τῷ Ὄθωνι καὶ συμβιωτῇ διὰ τήν ἀσωτίαν ἐχρῆτο, καὶ σκωπτόμενος ὑπ’ αὐτοῦ πολλάκις εἰς μικρολογίαν καὶ ἀνελευθερίαν ἔχαιρε, λέγεται δέ ποτε μύρῳ τῶν πολυτελῶν χρισαμένου τοῦ Νέρωνος καὶ τὸν Ὄθωνα καταβρέξαντος, ἐκεῖνος πάλιν τῇ ὑστεραίᾳ δεχόμενος αὐτὸν ἅμα πολλαχόθεν ἀργυροῦς καὶ χρυσοῦς προβαλεῖν ἄφνω σωλῆνας, ὥσπερ ὕδωρ τὸ μύρον ἐκχέοντας καὶ κατακλύζοντας, ἀλλὰ τήν γε Ποππαίαν προμοιχεύσας τῷ Νέρωνι, καὶ διαφθείρας ταῖς εἰς ἐκεῖνον ἐλπίσιν, ἔπεισεν ἀποστῆναι τοῦ ἀνδρός. ἐλθούσης δὲ παρ’ αὐτὸν ὡς γαμετῆς οὐκ ἠγάπα μετέχων, ἀλλ’ ἤσχαλλε μεταδιδούς, οὐδὲ αὐτῆς ἀχθομένης, ὥς φασι, τῇ ζηλοτυπίᾳ τῆς Ποππαίας. καὶ γὰρ ἀποκλεῖσαι τὸν Νέρωνα λέγεται μὴ παρόντος τοῦ Ὄθωνος, εἴτε τῆς ἡδονῆς ἀφαιροῦσα τὸ πλήσμιον, εἴτε, ὥς φασιν ἔνιοι, βαρυνομένη τὸν Καίσαρος γάμον, ἐραστῇ δὲ μὴ φεύγουσα χρῆσθαι διὰ τὸ φιλακόλαστον. ἐκινδύνευσεν οὖν ὁ Ὄθων ἀποθανεῖν· καὶ παράλογον ἦν ὅτι τήν γυναῖκα καὶ ἀδελφὴν ἀποκτείνας διὰ τὸν Ποππαίας γάμον ἐφείσατο τοῦ Ὄθωνος.", "st": "Galb. 19.1"}, {"sp": "N", "t": "Σενέκαν δὲ εἶχεν εὔνουν κἀκείνου τὸν Νέρωνα πείσαντος καὶ παραινέσαντος ἐξεπέμφθη Λυσιτανῶν στρατηγὸς ἐπὶ τὸν Ὠκεανόν. καὶ παρέσχεν ἑαυτὸν οὐκ ἄχαριν οὐδὲ ἐπαχθῆ τοῖς ὑπηκόοις, εἰδὼς φυγῆς ὑποκόρισμα καὶ παρακάλυμμα τὴν ἀρχὴν αὐτῷ δεδομένην. ἀποστάντος δὲ Γάλβα πρῶτος αὐτῷ προσεχώρησε τῶν ἡγεμόνων, καὶ φέρων ὅσον εἶχεν ἐν ἐκπώμασι καὶ τραπέζαις ἄργυρον καὶ χρυσὸν ἔδωκε κατακόψαι ποιουμένῳ νόμισμα, καὶ τῶν οἰκετῶν ἐδωρήσατο τοὺς εἰθισμένους περὶ δίαιταν ἡγεμόνι ἐμμελῶς ὑπουργεῖν. καὶ τὰ ἄλλα πιστὸς ἦν αὐτῷ, καὶ διδοὺς πεῖραν οὐδενὸς ἧττον ἐδόκει πραγμάτων ἔμπειρος εἶναι· καὶ βαδίζοντι τὴν ὁδὸν ἅπασαν ἐφ’ ἡμέρας πολλὰς συνοχούμενος διετέλεσεν. ἐν δὲ τῇ συνοδίᾳ καὶ τῇ συνηθείᾳ τὸν Οὐίνιον ἐξεθεράπευσεν ὁμιλίᾳ καὶ δώροις, μάλιστα δὲ τῶν πρωτείων ὑφιέμενος αὐτῷ τό γε μετ’ ἐκεῖνον δύνασθαι δι’ ἐκεῖνον εἶχε βεβαίως, τῷ δὲ ἀνεπιφθόνῳ περιῆν, προῖκα συμπράττων πάντα τοῖς δεομένοις, καὶ παρέχων ἑαυτὸν εὐπροσήγορον καὶ φιλάνθρωπον ἅπασι. πλεῖστα δὲ τοῖς στρατιωτικοῖς συνελάμβανε καὶ προῆγε πολλοὺς ἐφ’ ἡγεμονίας, τὰ μὲν αἰτούμενος ἀπὸ τοῦ αὐτοκράτορος, τὰ δὲ τὸν Οὐίνιον καὶ τοὺς ἀπελευθέρους παρακαλῶν Ἴκελον καὶ Ἀσιατικόν οὗτοι γὰρ ἦσαν ἐν δυνάμει μάλιστα τῶν περὶ τὴν αὐλήν. ὁσάκις δὲ τὸν Γάλβαν εἱστία, τὴν παραφυλάττουσαν ἀεὶ σπεῖραν ἐδέκαζε χρυσοῦν ἑκάστῳ διανέμων, οἷς τιμᾶν αὐτὸν ἐδόκει καταπολιτευόμενος καὶ δημαγωγῶν τὸ στρατιωτικόν.", "st": "Galb. 20.1"}, {"sp": "N", "t": "ἀλλ’ οὖν βουλευομένου γε τοῦ Γάλβα περὶ διαδόχου τὸν Ὄθωνα παρεισῆγεν ὁ Οὐίνιος, οὐδὲ τοῦτο προῖκα πράσσων, ἀλλ’ ἐπὶ γάμῳ τῆς θυγατρός, ὁμολογίας γενομένης γαμεῖν αὐτὴν τὸν Ὄθωνα παῖδα τοῦ Γάλβα καὶ διάδοχον ἀποδειχθέντα τῆς ἡγεμονίας, ὁ δὲ Γάλβας ἀεὶ μὲν ἦν δῆλος πρὸ τοῦ ἰδίου τὸ κοινὸν τιθέμενος καὶ ζητῶν οὐχ χ αὑτῷ θέσθαι τὸν ἥδιστον, ἀλλὰ Ῥωμαίοις τὸν ὠφελιμώτατον. δοκεῖ δὲ μηδ’ ἂν ἐπὶ τοῖς ἰδίοις χρήμασι μόνον ἑλέσθαι τὸν Ὄθωνα κληρονόμον, ἀκόλαστον εἰδὼς καὶ πολυτελῆ καὶ πεντακισχιλίων μυριάδων ὀφλήμασι βεβαπτισμένον. ὅθεν ἀκούσας τοῦ Οὐινίου σιωπῇ καὶ πρᾴως ὑπερέθετο τὴν διάθεσιν. ἀποδείξας δ’ αὑτὸν ὕπατον καὶ συνάρχοντα τὸν Οὐίνιον ἐπίδοξος ἦν ἔτους ἀρχῇ τὸν διάδοχον ἀναγορεύσειν καὶ τὸ στρατιωτικὸν ἡδέως εἶχε τὸν Ὄθωνα παρ’ ὁντινοῦν ἄλλον ἀναγορευθῆναι.", "st": "Galb. 21.1"}, {"sp": "N", "t": "καταλαμβάνει δ’ αὐτὸν ἔτι μέλλοντα καὶ βουλευόμενον ἐκραγέντα τὰ Γερμανικά, κοινῇ γὰρ ἅπαντες οἱ στρατευόμενοι τὸν Γάλβαν ἐμίσουν οὐκ ἀποδιδόντα τὴν δωρεάν, ἰδίας δὲ ἐκεῖνοι προφάσεις ἐποιοῦντο Οὐεργίνιόν τε Ῥοῦφον ἀπερριμμένον ἀτίμως καὶ Γαλατῶν τοὺς πολεμήσαντας αὐτοῖς δωρεῶν τυγχάνοντας, ὅσοι δὲ μὴ προσέθεντο Οὐΐνδικι κολαζομένους, ᾧ μόνῳ τὸν Γάλβαν χάριν εἰδέναι καὶ τιμᾶν τεθνηκότα καὶ γεραίρειν δημοσίοις ἐναγισμοῖς, ὡς ὑπ’ ἐκείνου Ῥωμαίων ἀποδεδειγμένον αὐτοκράτορα. τοιούτων ἀναφανδὸν ἤδη λόγων ἐν τῷ στρατοπέδῳ περιφερομένων ἐπῆλθεν ἡ νουμηνία τοῦ πρώτου μηνός, ἣν καλάνδας Ἰανουαρίας καλοῦσι· τοῦ δὲ Φλάκκου συναγαγόντος αὐτοὺς ἐπὶ τὸν ὅρκον ὃν ἔθος ἐστὶν ὀμνύειν ὑπὲρ τοῦ αὐτοκράτορος, τὰς μὲν εἰκόνας τοῦ Γάλβα προσελθόντες ἀνέτρεψαν καὶ κατέσπασαν, αὐτοὶ δὲ ὀμόσαντες ὑπὲρ συγκλήτου καὶ δήμου Ῥωμαίων διελύθησαν. εἶτα τοῖς ἡγεμονικοῖς παρίστατο δεδοικέναι τὴν ἀναρχίαν ὡς ἀπόστασιν. λέγει δέ τις ἐν αὐτοῖς· τί πάσχομεν, ὦ συστρατιῶται, μήτ’ ἄλλον ἡγεμόνα ποιούμενοι μήτε τὸν νῦν ὄντα φυλάττοντες, ὥσπερ οὐ Γάλβαν, ἀλλ’ ὅλως ἄρχοντα καὶ τὸ ἄρχεσθαι φεύγοντες; Φλάκκον μὲν οὖν Ὁρδεώνιον οὐδὲν ἄλλο ἢ σκιὰν ὄντα Γάλβα καὶ εἴδωλον ἐατέον, ἡμέρας δὲ μιᾶς ὁδὸν ἀφέστηκεν ἡμῶν Οὐϊτέλλιος, ὁ τῆς ἑτέρας Γερμανίας ἡγούμενος, πατρός τε τιμητοῦ καὶ τρὶς ὑπάτου γενομένου καὶ Κλαυδίῳ Καίσαρι τρόπον τινὰ συνάρξαντος, αὐτός τε τὴν λοιδορουμένην ὑπ’ ἐνίων πενίαν δεῖγμα λαμπρὸν ἔχων χρηστότητος καὶ μεγαλοφροσύνης, φέρε, τοῦτον ἑλόμενοι δείξωμεν ἀνθρώποις πᾶσιν ὡς Ἰβήρων καὶ Λυσιτανῶν ἀμείνους ἐσμὲν αὐτοκράτορα αἱρεῖσθαι.", "st": "Galb. 22.1"}, {"sp": "N", "t": "ταῦτα τῶν μὲν ἤδη προσιεμένων, τῶν δ’ οὐ προσιεμένων, εἷς ὑπεξελθὼν σημαιοφόρος ἀπήγγειλε τῷ Οὐϊτελλίῳ νυκτός, ἑστιωμένων πολλῶν παρ’ αὐτῷ. τοῦ δὲ λόγου διαπεσόντος εἷς τὰ στρατεύματα πρῶτος Φάβιος Οὐάλης, ἡγεμὼν ἑνὸς τάγματος, τῇ ὑστεραίᾳ μετὰ ἱππέων συχνῶν ἐλάσας αὐτοκράτορα τὸν Οὐϊτέλλιον προσεῖπεν. ὁ δὲ τὰς μὲν ἔμπροσθεν ἡμέρας ἐδόκει διωθεῖσθαι καὶ ἀναδύεσθαι, τὸ μέγεθος τῆς ἀρχῆς φοβούμενος, τότε δέ φασιν οἴνου διάπλεων καὶ τροφῆς ὄντα μεσημβρινῆς προελθεῖν καὶ ὑπακοῦσαι Γερμανικὸν ὄνομα θεμένων αὐτῷ, τὸ δὲ Καίσαρος οὐ προσδεξάμενον. εὐθὺς δὲ καὶ τὸ μετὰ Φλάκκου στράτευμα τοὺς καλοὺς ἐκείνους καὶ δημοκρατικοὺς εἷς σύγκλητον ὅρκους ἀφέντες ὤμοσαν Οὐϊτελλίῳ τῷ αὐτοκράτορι ποιήσειν τὸ προστασσόμενον.", "st": "Galb. 22.6"}, {"sp": "N", "t": "οὕτω μὲν ἀνηγορεύθη Οὐϊτέλλιος αὐτοκράτωρ ἐν Γερμανίᾳ. πυθόμενος δὲ τὸν ἐκεῖ νεωτερισμὸν ὁ Γάλβας οὐκέτι τὴν εἰσποίησιν ἀνεβάλλετο. γινώσκων δὲ τῶν φίλων ἐνίους μὲν ὑπὲρ Δολοβέλλα, τοὺς δὲ πλείστους ὑπὲρ Ὄθωνος ἀρχαιρεσιάζοντας, ὧν οὐδέτερον ἐδοκίμαζεν αὐτός, ἄφνω μηδὲν προειπὼν μετεπέμψατο Πείσωνα, Κράσσου καὶ Σκριβωνίας ἔκγονον, οὓς Νέρων ἀνῃρήκει, νεανίαν ἐν τῇ πρὸς πᾶσαν ἀρετὴν εὐφυΐᾳ τὸ κόσμιον καὶ αὐστηρὸν ἐμφανέστατα ἔχοντα· καὶ κατέβαινεν εἰς τὸ στρατόπεδον ἐκεῖνον ἀποδείξων Καίσαρα καὶ διάδοχον. καίτοι μεγάλαι μὲν εὐθὺς ἐξιόντι διοσημίαι παρηκολούθουν, ἀρξαμένου δὲ τὰ μὲν λέγειν ἐν τῷ στρατοπέδῳ, τὰ δὲ ἀναγινώσκειν, τοσαυτάκις ἐβρόντησε καὶ κατήστραψε, καὶ τοσοῦτος ὄμβρος καὶ ζόφος ἐξεχύθη εἰς τὸ στρατόπεδον καὶ τὴν πόλιν, ὡς κατάδηλον εἶναι μὴ προσιέμενον μηδὲ ἐπαινοῦν τὸ δαιμόνιον γινομένην οὐκ ἐπ’ ἀγαθῷ τὴν εἰσποίησιν. ἦν δὲ καὶ τὰ τῶν στρατιωτῶν ὕπουλα καὶ σκυθρωπὰ μηδὲ τότε δωρεᾶς αὐτοῖς δοθείσης.", "st": "Galb. 23.1"}, {"sp": "N", "t": "τοῦ δὲ Πείσωνος οἱ παρόντες ἐθαύμασαν τῇ τε φωνῇ τεκμαιρόμενοι καὶ τῷ προσώπῳ τὸ τηλικαύτην χάριν ἀνεμπλήκτως, οὐ μὴν ἀναισθήτως δεχόμενον, ὥσπερ αὖ τοῦ Ὄθωνος ἐπεφαίνετο πολλὰ σημεῖα τῇ μορφῇ πικρῶς καὶ σὺν ὀργῇ τῆς ἐλπίδος τὴν ἀπότευξιν φέροντος, ἧς πρῶτος ἀξιωθεὶς καὶ τοῦ τυχεῖν ἐγγυτάτω γενόμενος τὸ μὴ τυχεῖν ἐποιεῖτο σημεῖον ἔχθους ἅμα καὶ κακονοίας τοῦ Γάλβα πρὸς αὐτόν. ὅθεν οὐδὲ ἄφοβος ἦν περὶ τοῦ μέλλοντος, ἀλλὰ καὶ τὸν Πείσωνα δεδιὼς καὶ τὸν Γάλβαν προβαλλόμενος καὶ τῷ Οὐινίῳ χαλεπαίνων ἀπῄει πολλῶν παθῶν πλήρης, οὐδὲ γὰρ τὸ ἐλπίζον ἐκλιπεῖν οὐδὲ ἀπαγορεῦσαι παντάπασιν εἴων οἱ περὶ αὐτὸν ὄντες ἀεὶ μάντεις καὶ Χαλδαῖοι, εἰς τὰ μάλιστα δὲ Πτολεμαῖος ἰσχυριζόμενος τῷ προειπεῖν πολλάκις ὡς οὐκ ἀποκτενεῖ Νέρων αὐτόν, ἀλλὰ τεθνήξεται πρότερος, αὐτὸς δὲ περιέσται καὶ ἄρξει Ῥωμαίων ἐκεῖνο γὰρ ἀληθὲς ἀποδείξας ἠξίου μηδὲ ταῦτα ἀπελπίζειν· οὐχ ἥκιστα δ’ οἱ συναχθόμενοι κρύφα καὶ συνεπιστένοντες ὡς ἀχάριστα πεπονθότι. πλεῖστοι δὲ τῶν περὶ Τιγελλῖνον καὶ Νυμφίδιον ἐν τιμῇ γεγονότων ἀπερριμμένοι τότε καὶ ταπεινὰ πράττοντες ἐφθείροντο πρὸς αὐτὸν καὶ συνηγανάκτουν καὶ παρώξυνον.", "st": "Galb. 23.4"}, {"sp": "N", "t": "ἐν δὲ τούτοις Οὐετούριος καὶ Βάρβιος, ὁ μὲν ὀπτίων, ὁ δὲ τεσσεράριος· οὕτω γὰρ καλοῦνται οἱ διαγγέλων καὶ διοπτήρων ὑπηρεσίας τελοῦντες. μεθ’ ὧν Ὄθωνος ἀπελεύθερος Ὀνόμαστος ἐπιφοιτῶν τοὺς μὲν ἀργυρίῳ, τοὺς δὲ ἐλπίσι διέφθειρεν ἤδη σαθροὺς ὄντας καὶ δεομένους προφάσεως. οὐ γὰρ ἦν ἡμερῶν τεσσάρων ἔργον ὑγιαίνοντος στρατοπέδου μεταστῆσαι πίστιν, ὅσαι μεταξὺ τῆς εἰσποιήσεως ἐγένοντο καὶ τῆς σφαγῆς, ἕκτῃ γὰρ ἀνῃρέθησαν, ἣν ἄγουσι Ῥωμαῖοι πρὸ δεκαοκτὼ καλανδῶν Φεβρουαρίων.", "st": "Galb. 24.1"}, {"sp": "N", "t": "ἐκείνῃ γὰρ ἕωθεν εὐθὺς ὁ μὲν Γάλβας ἔθυεν ἐν Παλατίῳ τῶν φίλων παρόντων, ὁ δὲ θύτης Ὀμβρίκιος ἅμα τῷ λαβεῖν εἰς τὰς χεῖρας τοῦ ἱερείου τὰ σπλάγχνα καὶ προσιδεῖν οὐ δι’ αἰνιγμῶν, ἀλλ’ ἄντικρυς ἔφη σημεῖα μεγάλης ταραχῆς, καὶ μετὰ δόλου κίνδυνον ἐκ κεφαλῆς ἐπικείμενον τῷ αὐτοκράτορι, μονονουχὶ τὸν Ὄθωνα τοῦ θεοῦ χειρὶ ληπτὸν παραδιδόντος. παρῆν γὰρ ὄπισθεν τοῦ Γάλβα, καὶ προσεῖχε τοῖς λεγομένοις καὶ δεικνυμένοις ὑπὸ τοῦ Ὀμβρικίου. θορυβουμένῳ δὲ αὐτῷ καὶ χρόας ἀμείβοντι παντοδαπὰς ὑπὸ δέους παραστὰς Ὀνόμαστος ἀπελεύθερος ἥκειν ἔφη καὶ περιμένειν αὐτὸν οἴκοι τοὺς ἀρχιτέκτονας, ἦν δὲ σύμβολον καιροῦ, πρὸς ὃν ἔδει ἀπαντῆσαι τὸν Ὄθωνα τοῖς στρατιώταις. εἰπὼν οὖν, ὅτι παλαιὰν ἐωνημένος οἰκίαν βούλεται τὰ ὕποπτα δεῖξαι τοῖς πωληταῖς, ἀπῆλθε, καὶ διὰ τῆς Τιβερίου καλουμένης οἰκίας καταβὰς ἐβάδιζεν εἰς ἀγοράν, οὗ χρυσοῦς εἱστήκει κίων, εἰς ὃν αἱ τετμημέναι τῆς Ἰταλίας ὁδοὶ πᾶσαι τελευτῶσιν.", "st": "Galb. 24.2"}, {"sp": "N", "t": "ἐνταῦθα τοὺς πρώτους ἐκδεξαμένους αὐτὸν καὶ προσειπόντας αὐτοκράτορά φασι μὴ πλείους τριῶν καὶ εἴκοσι γενέσθαι, διό, καίπερ οὐ κατὰ τὴν τοῦ σώματος μαλακίαν καὶ θηλύτητα τῇ ψυχῇ διατεθρυμμένος, ἀλλὰ ἰταμὸς ὢν πρὸς τὰ δεινὰ καὶ ἄτρεπτος, ἀπεδειλίασεν. οἱ δὲ παρόντες οὐκ εἴων, ἀλλὰ τοῖς ξίφεσι γυμνοῖς περιϊόντες αὐτοῦ τὸ φορεῖον ἐκέλευον αἴρεσθαι, παραφθεγγομένου πολλάκις ἀπολωλέναι καὶ τοὺς φορειαφόρους ἐπιταχύνοντος. ἐξήκουον γὰρ ἔνιοι θαυμάζοντες μᾶλλον ἢ ταραττόμενοι διὰ τὴν ὀλιγότητα τῶν ἀποτετολμημένων, φερομένῳ δὲ οὕτω δι’ ἀγορᾶς ἀπήντησαν ἕτεροι τοσοῦτοι, καὶ πάλιν κατὰ τρεῖς καὶ τέτταρας ἄλλοι προσεπέλαζον. εἶτα συνανέστρεφον ἅπαντες ἀνακαλούμενοι Καίσαρα καὶ γυμνὰ τὰ ξίφη προϊσχόμενοι. τῶν δὲ χιλιάρχων ὁ τὴν φυλακὴν ἔχων τοῦ στρατοπέδου Μαρτίαλις, ὥς φασι, μὴ συνειδώς, ἐκπλαγεὶς δὲ τῷ ἀπροσδοκήτῳ καὶ φοβηθεὶς ἐφῆκεν εἰσελθεῖν. γενομένῳ δὲ ἐντὸς οὐδεὶς ἀντέπεσεν. οἱ γὰρ ἀγνοοῦντες τὰ πραττόμενα τοῖς εἰδόσι καὶ συνεστῶσιν ἐκ παρασκευῆς ἐμπεριεχόμενοι καθ’ ἕνα καὶ δύο σποράδες, ὑπὸ δέους τὸ πρῶτον, εἶτα πεισθέντες ἐπηκολούθησαν.", "st": "Galb. 25.1"}, {"sp": "N", "t": "εἰς δὲ τὸ Παλάτιον εὐθὺς μὲν ἀπηγγέλη τῷ Γάλβᾳ παρόντος ἔτι τοῦ θύτου καὶ τῶν ἱερῶν ἐν χερσὶν ὄντων, ὥστε καὶ τοὺς πάνυ πρὸς τὰ τοιαῦτα δυσπειθῶς καὶ ἀτενῶς ἔχοντας ἐκπλήττεσθαι καὶ θαυμάζειν τὸ θεῖον ὄχλου δὲ παντοδαποῦ συρρέοντος ἐξ ἀγορᾶς, αὐτῷ μὲν Οὐίνιος καὶ Λάκων καὶ τῶν ἀπελευθέρων ἔνιοι γυμνὰ τὰ ξίφη προϊσχόμενοι παρέστησαν, ὁ δὲ Πείσων προελθὼν τοῖς φυλάττουσι τὴν αὐλὴν δορυφόροις ἐνετύγχανε. τοῦ δ’ Ἰλλυρικοῦ τάγματος ἐν τῇ καλουμένῃ παστάδι Βιψανίᾳ στρατοπεδεύοντος ἀπεστάλη Μάριος Κέλσος, ἀνὴρ ἀγαθός, προκαταληψόμενος.", "st": "Galb. 25.4"}, {"sp": "N", "t": "βουλευομένου δὲ τοῦ Γάλβᾳ προελθεῖν, καὶ Οὐινίου μὲν οὐκ ἐῶντος, Κέλσου δὲ καὶ Λάκωνος παρορμώντων καὶ σφοδρότερον τοῦ Οὐινίου καθαπτομένων, θροῦς διῆλθε πολὺς ὡς ἀνῃρημένου τοῦ Ὄθωνος ἐν τῷ στρατοπέδῳ· καὶ μετὰ μικρὸν ὤφθη Ἰούλιος Ἄττικος τῶν οὐκ ἀσήμων ἐν τοῖς δορυφόροις στρατευόμενος γυμνῷ τῷ ξίφει προσφερόμενος καὶ βοῶν ἀνῃρηκέναι τὸν Καίσαρος πολέμιον ὠσάμενος δὲ διὰ τῶν προεστώτων ἔδειξε τῷ Γάλβᾳ τὸ ξίφος ᾑμαγμένον. ὁ δὲ βλέψας πρὸς αὐτόν, τίς σε, εἶπεν, ἐκέλευσε; τοῦ δὲ ἀνθρώπου τὴν πίστιν εἰπόντος καὶ τὸν ὅρκον ὃν ὤμοσε, καὶ τοῦ πλήθους ἐπιβοῶντος ὡς εὖ, καὶ κροτοῦντος, ἐμβὰς εἰς τὸ φορεῖον ἐκομίζετο τῷ τε Διῒ θῦσαι καὶ φανῆναι τοῖς πολίταις βουλόμενος. ἐμβαλόντος δὲ εἰς τὴν ἀγοράν, ὥσπερ τροπαία πνεύματος, ἀπήντησε φήμη κρατεῖν τὸν Ὄθωνα τοῦ στρατεύματος. οἷα δὲ ἐν πλήθει τοσούτῳ, τῶν μὲν ἀναστρέφειν, τῶν δὲ προϊέναι, τῶν δὲ θαρρεῖν, τῶν δὲ ἀπιστεῖν βοώντων, καὶ τοῦ φορείου, καθάπερ ἐν κλύδωνι, δεῦρο κἀκεῖ διαφερομένου καὶ πυκνὸν ἀπονεύοντος, ἐφαίνοντο πρῶτον ἱππεῖς, εἶτα ὁπλῖται διὰ τῆς Παύλου βασιλικῆς προσφερόμενοι, μιᾷ φωνῇ μέγα βοῶντες ἐκποδὼν ἵστασθαι τὸν ἰδιώτην. τῶν μὲν οὖν πολλῶν δρόμος ἦν, οὐ φυγῇ σκιδναμένων, ἀλλ’ ἐπὶ τὰς στοὰς καὶ τὰ μετέωρα τῆς ἀγορᾶς, ὥσπερ θέαν καταλαμβανόντων. Ἀτιλλίου δὲ Βεργελίωνος εἰκόνα Γάλβᾳ προσουδίσαντος, ἀρχὴν τοῦ πολέμου ποιησάμενοι περιηκόντισαν τὸ φορεῖον ὡς δὲ οὐκ ἔτυχον αὐτοῦ, προσῆγον ἐσπασμένοις τοῖς ξίφεσιν. ἤμυνε δὲ οὐδεὶς οὐδὲ ὑπέστη πλὴν ἑνὸς ἀνδρός, ὃν μόνον ἥλιος ἐπεῖδεν ἐν μυριάσι τοσαύταις ἄξιον τῆς Ῥωμαίων ἡγεμονίας· Σεμπρώνιος ἦν Δῆνσος ἑκατοντάρχης, οὐδὲν ἰδίᾳ χρηστὸν ὑπὸ Γάλβᾳ πεπονθώς, τῷ δὲ καλῷ καὶ τῷ νόμῳ βοηθῶν προέστη τοῦ φορείου, καὶ τὸ κλῆμα πρῶτον, ᾧ κολάζουσιν ἑκατοντάρχαι τοὺς πληγῶν δεομένους, ἐπαράμενος τοῖς ἐπιφερομένοις ἐβόα καὶ διεκελεύετο φείδεσθαι τοῦ αὐτοκράτορος. ἔπειτα συμπλεκομένων αὐτῷ σπασάμενος τὸ ξίφος ἠμύνατο πολὺν χρόνον, ἕως τυφθεὶς τὰς ἰγνύας ἔπεσε.", "st": "Galb. 26.1"}, {"sp": "N", "t": "τὸν δέ Γάλβαν, ἀποκλιθέντος τοῦ φορείου περὶ τὸν Κουρτίου καλούμενον λάκκον, ἐκκυλισθέντα τεθωρακισμένον ἔτυπτον ἐπιδραμόντες. ὁ δὲ τὴν σφαγὴν προτείνας, δρᾶτε, εἶπεν, εἰ τοῦτο τῷ δήμῳ Ῥωμαίων ἄμεινόν ἐστι. πολλὰς μὲν οὖν ἔλαβε πληγὰς εἴς τε τὰ σκέλη καὶ τοὺς βραχίονας, ἀπέσφαξε δὲ αὐτόν, ὡς οἱ πλεῖστοι λέγουσι, Καμούριός τις ἐκ τοῦ πεντεκαιδεκάτου τάγματος, ἔνιοι δὲ Τερέντιον, οἱ δὲ Λεκάνιον ἱστοροῦσιν, οἱ δὲ Φάβιον Φάβουλον, ὃν καί φασιν ἀποκόψαντα τὴν κεφαλὴν κομίζειν τῷ ἱματίῳ συλλαβόντα, διὰ τὴν ψιλότητα δυσπερίληπτον οὖσαν· ἔπειτα τῶν σὺν αὐτῷ κρύπτειν οὐκ ἐώντων, ἀλλ’ ἐκφανῆ πᾶσι ποιεῖν τὴν ἀνδραγαθίαν, περιπείραντα περὶ λόγχην καί ἀναπήλαντα πρεσβύτου πρόσωπον, ἄρχοντός τε κοσμίου καί ἀρχιερέως καί ὑπάτου, δρόμῳ χωρεῖν, ὥσπερ αἱ βάκχαι, πολλάκις μεταστρεφόμενον, καί κραδαίνοντα τὴν λόγχην αἵματι καταρρεομένην.", "st": "Galb. 27.1"}, {"sp": "N", "t": "τὸν δ’ Ὄθωνα, τῆς κεφαλῆς κομισθείσης, ἀνακραγεῖν λέγουσιν οὐδέν ἐστι τοῦτο, ὦ συστρατιῶται, τὴν Πείσωνός μοι κεφαλὴν δείξατε. μετ’ ὀλίγον δὲ ἧκε κομιζομένη τρωθεὶς γὰρ ἔφευγεν ὁ νεανίσκος, καί καταδιωχθεὶς ὑπὸ Μούρκου τινὸς ἀπεσφάγη πρὸς τῷ ἱερῷ τῆς Ἑστίας, ἀπεσφάττετο δὲ καί Οὐίνιος ὁμολογῶν κοινωνὸς γεγονέναι τῆς ἐπὶ τὸν Γάλβαν συνωμοσίας· ἐβόα γὰρ ἀποθνήσκειν παρὰ τὴν Ὄθωνος γνώμην. ἀλλὰ γὰρ καί τούτου τὴν κεφαλὴν ἀποτεμόντες καί Λάκωνος ἐκόμισαν πρὸς τὸν Ὄθωνα δωρεὰς αἰτοῦντες. ὡς δέ φησιν Ἀρχίλοχος,", "st": "Galb. 27.4"}, {"sp": "N", "t": "ἑπτὰ γὰρ νεκρῶν πεσόντων, οὓς ἐμάρψαμεν ποσίν,<br>χίλιοι φονῆες ἐσμέν,", "st": "Galb. 27.4b"}, {"sp": "N", "t": "οὕτως τότε πολλοὶ τοῦ φόνου μὴ συνεφαψάμενοι, χεῖρας δὲ καί ξίφη καθαιμάσσοντες ἐπεδείκνυντο καὶ δωρεὰς ᾔτουν βιβλία διδόντες τῷ Ὄθωνι. εἴκοσι γοῦν καί ἑκατὸν εὑρέθησαν ὕστερον ἐκ τῶν γραμματίων, οὓς ὁ Οὐϊτέλλιος ἀναζητήσας ἅπαντας ἀπέκτεινεν. ἧκε δὲ καί Μάριος Κέλσος εἰς τὴν παρεμβολήν. καί πολλῶν αὐτοῦ κατηγορούντων ὅτι τοὺς στρατιώτας ἔπειθε τῷ Γάλβᾳ βοηθεῖν, καί τοῦ πλήθους ἀποκτιννύειν βοῶντος, Ὄθων οὐκ ἐβούλετο· φοβούμενος δὲ ἀντιλέγειν οὐχ οὕτως ἔφη ταχέως ἀποκτενεῖν αὐτόν· εἶναι γὰρ ἃ δεῖ πρότερον ἐκπυθέσθαι παρὰ τοῦ ἀνδρός, ἐκέλευσεν οὖν δήσαντας φυλάττειν, καί παρέδωκε τοῖς μάλιστα πιστευομένοις.", "st": "Galb. 27.6"}, {"sp": "N", "t": "εὐθὺς δὲ βουλὴ συνεκαλεῖτο. καὶ καθάπερ ἄλλοι γεγονότες ἢ θεῶν ἄλλων γεγονότων συνελθόντες ὤμνυον ὅρκον ὑπὲρ τοῦ Ὄθωνος, ὃν αὐτὸς ὀμόσας οὐκ ἐτήρησε· καὶ Καίσαρα καὶ Σεβαστὸν ἀνηγόρευον, ἔτι τῶν νεκρῶν ἀκεφάλων ἐν ταῖς ὑπατικαῖς ἐσθῆσιν ἐρριμμένων ἐπὶ τῆς ἀγορᾶς. ταῖς δὲ κεφαλαῖς ὡς οὐδὲν εἶχον ἔτι χρῆσθαι, τὴν μὲν Οὐινίου τῇ θυγατρὶ δισχιλίων καὶ πεντακοσίων δραχμῶν ἀπέδοντο, τὴν δὲ Πείσωνος ἡ γυνὴ ἔλαβεν Οὐερανία δεηθεῖσα, τὴν δὲ Γάλβα τοῖς Πατροβίου δούλοις ἐδωρήσαντο. λαβόντες δὲ ἐκεῖνοι καὶ πάντα τρόπον αἰκισάμενοι καὶ καθυβρίσαντες ἔρριψαν ᾗ τοὺς ὑπὸ τῶν Καισάρων κολαζομένους θανατοῦσιν ὁ δὲ τόπος Σεσσώριον καλεῖται, τὸ δὲ σῶμα τοῦ Γάλβα Πρίσκος Ἑλβίδιος ἀνείλετο, τοῦ Ὄθωνος ἐπιτρέψαντος ἔθαψε δὲ νυκτὸς Ἀργεῖος ἀπελεύθερος.", "st": "Galb. 28.1"}, {"sp": "N", "t": "τοιαῦτα τὰ κατὰ τὸν Γάλβαν, ἄνδρα μήτε γένει μήτε πλούτῳ πολλῶν ἀπολειφθέντα Ῥωμαίων, ὁμοῦ δὲ πλούτῳ καὶ γένει πρωτεύσαντα πάντων τῶν καθ’ αὑτόν, πέντε αὐτοκρατόρων ἡγεμονίαις ἐμβιώσαντα μετὰ τιμῆς καὶ δόξης, ὥστε τῇ δόξῃ μᾶλλον ἢ τῇ δυνάμει καθελεῖν Νέρωνα. τῶν γὰρ συνεπιτιθεμένων τότε τοὺς μὲν οὐδεὶς ἠξίωσε τῆς ἡγεμονίας, οἱ δὲ ἑαυτοὺς ἀπηξίωσαν, Γάλβας δὲ καὶ κληθεὶς καὶ ὑπακούσας αὐτοκράτωρ καὶ τῇ Οὐΐνδικος ἐμπαρασχὼν ὄνομα τόλμῃ, κίνημα καὶ νεωτερισμὸν αὐτοῦ λεγομένην τὴν ἀπόστασιν ἐποίησε πόλεμον ἐμφύλιον, ἀνδρὸς ἡγεμονικοῦ τυχοῦσαν. ὅθεν οὐχ ἑαυτῷ τὰ πράγματα λαμβάνειν, ἀλλὰ μᾶλλον ἑαυτὸν οἰόμενος διδόναι τοῖς πράγμασιν, ἄρχειν ἠξίου τῶν ὑπὸ Τιγελλίνου καὶ Νυμφιδίου τετιθασευμένων ὡς Σκηπίων ἦρχε καὶ Φαβρίκιος καὶ Κάμιλλος τῶν τότε Ῥωμαίων. ὑπερειπόμενος δὲ τῷ γήρᾳ, ἄχρι τῶν ὅπλων καὶ τῶν στρατευμάτων ἄκρατος ἦν καὶ ἀρχαῖος αὐτοκράτωρ, Οὐινίῳ δὲ καὶ Λάκωνι καὶ τοῖς ἀπελευθέροις πάντα τὰ πράγματα πωλοῦσι παρέχων ἑαυτόν, οἷον Νέρων παρεῖχε τοῖς ἀπληστοτάτοις, οὐδένα ποθοῦντα τὴν ἀρχήν, οἰκτείραντας δὲ τοὺς πολλοὺς τὸν θάνατον ἀπέλιπεν.", "st": "Galb. 29.1"}, {"sp": "HDR", "t": "Ὄθων"}, {"sp": "N", "t": "ὁ δὲ νεώτερος αὐτοκράτωρ ἅμ’ ἡμέρᾳ προελθὼν εἰς τὸ Καπιτώλιον ἔθυσε· καὶ κελεύσας Μάριον Κέλσον ἀχθῆναι πρὸς αὑτὸν ἠσπάσατο καὶ διελέχθη φιλανθρώπως, καὶ παρεκάλεσε τῆς αἰτίας ἐπιλαθέσθαι μᾶλλον ἢ τῆς ἀφέσεως μνημονεύειν. τοῦ δὲ Κέλσου μήτε ἀγεννῶς ἀποκριναμένου μήτ’ ἀναισθήτως, ἀλλά φήσαντος αὐτὸ τοῦ τρόπου διδόναι τὸ ἔγκλημα πίστιν, ἐγκεκλῆσθαι γὰρ ὅτι Γάλβᾳ βέβαιον ἑαυτὸν παρέσχεν, ᾧ χάριν οὐδεμίαν ὤφειλεν, ἠγάσθησαν οἱ παρόντες ἀμφοτέρων καὶ τὸ στρατιωτικὸν ἐπῄνεσεν. ἐν δὲ συγκλήτῳ πολλὰ δημοτικὰ καὶ φιλάνθρωπα διαλεχθείς, ὃν μὲν αὐτὸς ὑπατεύειν χρόνον ἤμελλε, τούτου μέρος ἔνειμεν Οὐεργινίῳ Ῥούφῳ, τοῖς δὲ ἀποδεδειγμένοις ὑπὸ Νέρωνος ἢ Γάλβα πᾶσιν ἐτήρησε τὰς ὑπατείας. ἱερωσύναις δὲ τοὺς καθ’ ἡλικίαν προήκοντας ἢ δόξαν ἐκόσμησε. τοῖς δὲ ἐπὶ Νέρωνος φυγοῦσι καὶ κατελθοῦσιν ἐπὶ Γάλβα συγκλητικοῖς πᾶσιν ἀπέδωκεν ὅσα μὴ πεπραμένα τῶν κτημάτων ἑκάστου ἐξεύρισκεν. ὅθεν οἱ πρῶτοι καὶ κράτιστοι πεφρικότες πρότερον ὡς οὐκ ἀνδρός, ἀλλά τινος ἢ Ποινῆς ἢ παλαμναίου δαίμονος ἄφνω τοῖς πράγμασιν ἐπιπεπτωκότος, ἡδίους ἐγένοντο ταῖς ἐλπίσι πρὸς τὴν ἡγεμονίαν ὥσπερ διαμειδιῶσαν.", "st": "Oth. 1.1"}, {"sp": "N", "t": "ὁμοῦ δὲ Ῥωμαίους πάντας οὐδὲν εὔφρανεν οὕτως οὐδὲ ᾠκειώσατο πρὸς αὐτὸν ὡς τὰ περὶ Τιγελλῖνον. ἐλελήθει μὲν γὰρ ἤδη κολαζόμενος αὐτῷ τῷ φόβῳ τῆς κολάσεως ἣν ὡς χρέος ἀπῄτει δημόσιον ἡ πόλις, καὶ νοσήμασιν ἀνηκέστοις σώματος, αὐτάς τε τὰς ἀνοσίους καὶ ἀρρήτους ἐν γυναιξὶ πόρναις καὶ ἀκαθάρτοις ἐγκυλινδήσεις, αἷς ἔτι προσέσπαιρε δυσθανατοῦντος αὐτοῦ τὸ ἀκόλαστον ἐπιδραττόμενον, ἐσχάτην τιμωρίαν ἐποιοῦντο καὶ πολλῶν ἀντάξια θανάτων οἱ σωφρονοῦντες. ἠνία δὲ τοὺς πολλοὺς ὅμως τόν ἥλιον ὁρῶν μετὰ τοσούτους καὶ τοιούτους δι’ αὐτὸν οὐχ ὁρῶντας. ἔπεμψεν οὖν ἐπ’ αὐτὸν ὁ Ὄθων εἰς τοὺς περὶ Σινόεσσαν ἀγρούς· ἐκεῖ γὰρ διῃτᾶτο, πλοίων παρορμούντων, ὡς φευξόμενος ἀπωτέρω. καὶ τόν γε πεμφθέντα χρυσίῳ πολλῷ πείθειν ἐπεχείρησε παρεῖναι· μὴ πεισθέντι δὲ δῶρα μὲν ἔδωκεν οὐδὲν ἧττον, ἐδεήθη δὲ ὑπομεῖναι ἕως ἂν ἀποξύρηται τό γένειον· καὶ λαβὼν αὐτὸς ἑαυτὸν ἐλαιμοτόμησεν.", "st": "Oth. 2.1"}, {"sp": "N", "t": "οὕτω δὲ τῷ δήμῳ τὴν δικαιοτάτην ἡδονὴν ἀποδοὺς ὁ Καῖσαρ, αὐτὸς ἰδίας ἔχθρας οὐδενὶ τοπαράπαν ἐμνησικάκησε, τοῖς δὲ πολλοῖς χαριζόμενος οὐκ ἔφευγε τὸ πρῶτον ἐν τοῖς θεάτροις Νέρων προσαγορεύεσθαι· καί τινων εἰκόνας Νέρωνος εἰς τοὐμφανὲς προθεμένων οὐκ ἐκώλυσε. Κλούβιος δὲ Ῥοῦφος εἰς Ἰβηρίαν φησὶ κομισθῆναι διπλώματα, οἷς ἐκπέμπουσι τοὺς γραμματηφόρους, τὸ τοῦ Νέρωνος θετὸν ὄνομα προσγεγραμμένον ἔχοντα τῷ τοῦ Ὄθωνος. οὐ μὴν ἀλλὰ τοὺς πρώτους καί κρατίστους αἰσθόμενος ἐπὶ τούτῳ δυσχεραίνοντας ἐπαύσατο.", "st": "Oth. 3.1"}, {"sp": "N", "t": "τοιαύτην δὲ τῆς ἡγεμονίας κατάστασιν αὐτῷ λαμβανούσης, οἱ μισθοφόροι χαλεποὺς παρεῖχον ἑαυτούς, ἀπιστεῖν παρακελευόμενοι καί φυλάττεσθαι καί κολούειν τοὺς ἀξιολόγους, εἴτ’ ἀληθῶς φοβούμενοι δι’ εὔνοιαν, εἴτε προφάσει χρώμενοι ταύτῃ τοῦ ταράττειν καί πολεμοποιεῖν. Κρισπῖνον δὲ πέμψαντος αὐτοῦ τὴν ἑπτακαιδεκάτην σπεῖραν Ὠστίας ἀπάξοντα, κἀκείνου νυκτὸς ἔτι συσκευαζομένου καί τὰ ὅπλα ταῖς ἁμάξαις ἐπιτιθέντος, οἱ θρασύτατοι πάντες ἐβόων οὐδὲν ὑγιὲς τὸν Κρισπῖνον ἥκειν διανοούμενον, ἀλλὰ τὴν σύγκλητον ἐπιχειρεῖν πράγμασι νεωτέροις, καὶ τὰ ὅπλα κατὰ Καίσαρος, οὐ Καίσαρι παρακομίζεσθαι. τοῦ δὲ λόγου πολλῶν ἁπτομένου καί παροξύνοντος, οἱ μὲν ἐπελαμβάνοντο τῶν ἁμαξῶν, οἱ δὲ τοὺς ἐνισταμένους ἑκατοντάρχας δύο καί τὸν Κρισπῖνον αὐτὸν ἀπέκτειναν, πάντες δὲ διασκευασάμενοι καί παρακαλέσαντες ἀλλήλους Καίσαρι βοηθεῖν ἤλαυνον εἰς τὴν Ῥώμην καί πυθόμενοι παρ’ αὐτῷ δειπνεῖν ὀγδοήκοντα συγκλητικούς, ἐφέροντο πρὸς τὰ βασίλεια, νῦν καιρὸν εἶναι λέγοντες ἐν ταὐτῷ πάντας ἀνελεῖν τοὺς Καίσαρος πολεμίους. ἡ μὲν οὖν πόλις ὡς αὐτίκα διαρπαγησομένη θόρυβον εἶχε πολύν, ἐν δὲ τοῖς βασιλείοις ἦσαν διαδρομαί, καί τὸν Ὄθων α δεινὴ κατελάμβανεν ἀπορία. φοβούμενος γὰρ ὑπὲρ τῶν ἀνδρῶν αὐτὸς ἦν φοβερὸς ἐκείνοις, καί πρὸς αὑτὸν ἀνηρτημένους ἑώρα ταῖς ὄψεσιν ἀναύδους καί περιδεεῖς, ἐνίους καί μετὰ γυναικῶν ἥκοντας ἐπὶ τὸ δεῖπνον. ἅμα δὲ τοὺς ἐπάρχους ἀπέστελλε τοῖς στρατιώταις διαλέγεσθαι καί πραΰνειν κελεύσας, ἅμα δὲ τοὺς κεκλημένους ἄνδρας ἀναστήσας καθ’ ἑτέρας θύρας ἀφῆκε· καί μικρὸν ἔφθησαν ὑπεκφυγόντες, διὰ τῶν μισθοφόρων ὠθουμένων εἰς τὸν ἀνδρῶνα καί πυνθανομένων τί γεγόνασιν οἱ Καίσαρος πολέμιοι. τότε μὲν οὖν ὀρθὸς ἀπὸ τῆς κλίνης πολλὰ παρηγορήσας καί δεηθεὶς καί μηδὲ δακρύων φεισάμενος μόλις ἀπέπεμψεν αὐτούς· τῇ δ’ ὑστεραίᾳ δωρησάμενος ἅπαντας κατ’ ἄνδρα χιλίαις καί διακοσίαις καί πεντήκοντα δραχμαῖς εἰσῆλθεν εἰς τὸ στρατόπεδον, καί τὸ μὲν πλῆθος ἐπῄνεσεν, ὡς πρὸς αὐτὸν εὔνουν καί πρόθυμον, ὀλίγους δέ τινας οὐκ ἐπ’ ἀγαθῷ φήσας ὑποικουρεῖν, διαβάλλοντας αὐτοῦ τὴν μετριότητα καί τὴν ἐκείνων εὐστάθειαν, ἠξίου συναγανακτεῖν καί συγκολάζειν. ἐπαινούντων δὲ πάντων καί κελευόντων, δύο μόνους παραλαβών, οἷς οὐδεὶς ἔμελλεν ἄχθεσθαι κολασθεῖσιν, ἀπηλλάγη.", "st": "Oth. 3.3"}, {"sp": "N", "t": "ταῦτα οἱ μὲν ἀγαπῶντες ἤδη καὶ πιστεύοντες ἐθαύμαζον τὴν μεταβολήν, οἱ δ’ ἀναγκαῖα πολιτεύματα πρὸς τὸν καιρὸν ἡγοῦντο, δημαγωγοῦντος αὐτοῦ διὰ τὸν πόλεμον. ἤδη γὰρ ἠγγέλλετο βεβαίως Οὐϊτέλλιος ἀξίωμα καὶ δύναμιν αὐτοκράτορος ἀνειληφώς· καὶ πτεροφόροι συνεχῶς ἐφοίτων ἀεί τι προσχωρεῖν ἐκείνῳ φράζοντες, ἕτεροι δὲ τὰ Παννονικὰ καὶ τὰ Δαλματικὰ καὶ τὰ περὶ Μυσίαν στρατεύματα δηλοῦντες ᾑρῆσθαι μετὰ τῶν ἡγεμόνων Ὄθωνα. ταχὺ δὲ ἀφίκετο καὶ παρὰ Μουκιανοῦ γράμματα καὶ παρὰ Οὐεσπεσιανοῦ φίλια, τοῦ μὲν ἐν Συρίᾳ, τοῦ δὲ ἐν Ἰουδαίᾳ μεγάλας δυνάμεις ἐχόντων, ὑφ’ ὧν ἐπαιρόμενος ἔγραψεν Οὐϊτελλίῳ παραινῶν στρατιωτικὰ φρονεῖν, ὡς χρήματα πολλὰ δώσοντος αὐτοῦ καὶ πόλιν, ἐν ᾗ βιώσεται ῥᾷστον καὶ ἥδιστον βίον μεθ’ ἡσυχίας. ἀντέγραψε δὲ κἀκεῖνος αὐτῷ κατειρωνευόμενος ἡσυχῆ πρῶτον ἐκ δὲ τούτου διερεθιζόμενοι πολλὰ βλάσφημα καὶ ἀσελγῆ χλευάζοντες ἀλλήλοις ἔγραφον, οὐ ψευδῶς μέν, ἀνοήτως δὲ καὶ γελοίως θατέρου τὸν ἕτερον ἃ προσῆν ἀμφοτέροις ὀνείδη λοιδοροῦντος. ἀσωτίας γὰρ καὶ μαλακίας καὶ ἀπειρίας πολέμων καὶ τῶν πρόσθεν ἐπὶ πενίᾳ χρεῶν πλήθους ἔργον ἦν εἰπεῖν ὁποτέρῳ μεῖον αὐτῶν μέτεστι.", "st": "Oth. 4.1"}, {"sp": "N", "t": "σημείων δὲ καὶ φαντασμάτων πολλῶν λεγομένων, τὰ μὲν ἄλλα φήμας ἀδεσπότους καὶ ἀμφιβόλους εἶχεν, ἐν δὲ Καπιτωλίῳ Νίκης ἐφεστώσης ἅρματι τὰς ἡνίας πάντες εἶδον ἀφειμένας ἐκ τῶν χειρῶν, ὥσπερ κρατεῖν μὴ δυναμένης, καὶ τὸν ἐν μεσοποταμίᾳ νήσῳ Γαΐου Καίσαρος ἀνδριάντα μήτε σεισμοῦ γεγονότος μήτε πνεύματος ἀφ’ ἑσπέρας μεταστραφέντα πρὸς τὰς ἀνατολάς· ὅ φασι συμβῆναι περὶ τὰς ἡμέρας ἐκείνας ἐν αἷς οἱ περὶ Οὐεσπεσιανὸν ἐμφανῶς ἤδη τῶν πραγμάτων ἀντελαμβάνοντο. καὶ τὸ περὶ τὸν Θύμβριν δὲ σύμπτωμα σημεῖον ἐποιοῦντο οἱ πολλοὶ μοχθηρόν. ἦν μὲν γὰρ ὥρα περὶ ἣν μάλιστα οἱ ποταμοὶ πλήθουσιν, ἀλλ’ οὔπω τοσοῦτος ἤρθη πρότερον, οὐδὲ ἀπώλεσε τοσαῦτα καὶ διέφθειρεν, ὑπερχυθεὶς καὶ κατακλύσας πολὺ μέρος τῆς πόλεως, πλεῖστον δὲ ἐν ᾧ τὸν ἐπὶ πράσει διαπωλοῦσι σῖτον, ὡς δεινὴν ἀπορίαν ἡμερῶν συχνῶν κατασχεῖν.", "st": "Oth. 4.4"}, {"sp": "N", "t": "ἐπεὶ δὲ τὰς Ἄλπεις κατέχοντες ἤδη προσηγγέλλοντο Κεκίνας καὶ Οὐάλης Οὐϊτελλίῳ στρατηγοῦντες, ἐν Ῥώμῃ Δολοβέλλας, εὐπατρίδης ἀνήρ, ὑποψίαν παρεῖχε τοῖς μισθοφόροις νεώτερα φρονεῖν. ἐκεῖνον μὲν οὖν, εἴτε αὐτὸν εἴτε ἄλλον δεδοικώς, εἰς πόλιν Ἀκύνιον παρέπεμψε παραθαρρύνας. καταλέγων δὲ τῶν ἐν τέλει συνεκδήμους ἔταξεν ἐν τούτοις καὶ Λεύκιον τὸν Οὐϊτελλίου ἀδελφόν, οὔτε προσθεὶς οὐδὲν οὔτε ἀφελὼν ἧς εἶχε τιμῆς. ἰσχυρῶς δὲ καὶ τῆς μητρὸς ἐπεμελήθη τοῦ Οὐϊτελλίου καὶ τῆς γυναικός, ὅπως μηδὲν φοβήσονται περὶ αὑτῶν, τῆς δὲ Ῥώμης φύλακα Φλαούιον Σαβῖνον, ἀδελφὸν Οὐεσπεσιανοῦ, κατέστησεν, εἴτε καὶ τοῦτο πράξας ἐπὶ τιμῇ Νέρωνος παρ’ ἐκείνου γὰρ εἰλήφει τὴν ἀρχὴν ὁ Σαβῖνος, ἀφείλετο δὲ Γάλβας αὐτόν, εἴτε μᾶλλον εὔνοιαν ἐνεδείκνυτο Οὐεσπεσιανῷ καὶ πίστιν αὔξων Σαβῖνον.", "st": "Oth. 5.1"}, {"sp": "N", "t": "αὐτὸς μὲν οὖν ἐν Βριξίλλῳ, πόλει τῆς Ἰταλίας περὶ τὸν Ἠριδανὸν ἀπελείφθη, στρατηγοὺς δὲ τῶν δυνάμεων ἐξέπεμψε Μάριόν τε Κέλσον καὶ Σουητώνιον Παυλῖνον ἔτι τε Γάλλον καὶ Σπουρίναν, ἄνδρας ἐνδόξους, χρήσασθαι δὲ μὴ δυνηθέντας ἐπὶ τῶν πραγμάτων ὡς προῃροῦντο τοῖς ἑαυτῶν λογισμοῖς δι’ ἀταξίαν καὶ θρασύτητα τῶν στρατιωτῶν. οὐ γὰρ ἠξίουν ἑτέρων ἀκούειν, ὡς παρ’ αὑτῶν τοῦ αὐτοκράτορος τὸ ἄρχειν ἔχοντος. ἦν μὲν οὖν οὐδὲ τὰ τῶν πολεμίων ὑγιαίνοντα παντάπασιν οὐδὲ χειροήθη τοῖς ἡγεμόσιν, ἀλλ’ ἔμπληκτα καὶ σοβαρὰ διὰ τὴν αὐτὴν αἰτίαν. οὐ μὴν ἀλλ’ ἐκείνοις ἐμπειρία γε παρῆν τοῦ μάχεσθαι καὶ τὸ κάμνειν ἐθάδες ὄντες οὐκ ἔφευγον, οὗτοι δὲ μαλακοὶ μὲν ἦσαν ὑπὸ σχολῆς καὶ διαίτης ἀπολέμου, πλεῖστον χρόνον ἐν θεάτροις καὶ πανηγύρεσι καὶ παρὰ σκηνὴν βεβιωκότες, ὕβρει δὲ καὶ κόμπῳ ἐπαμπέχειν ἐβούλοντο, προσποιήσασθαι τὰς λειτουργίας ὡς κρείττονες ἀπαξιοῦντες, οὐχ ὡς ἀδύνατοι φέρειν. ὁ δὲ Σπουρίνας προσβιαζόμενος αὐτοὺς ἐκινδύνευσε μικρὸν ἐλθόντας ἀνελεῖν αὐτόν. ὕβρεως δὲ καὶ βλασφημίας οὐδεμιᾶς ἐφείσαντο, προδότην καὶ λυμεῶνα τῶν Καίσαρος καιρῶν καὶ πραγμάτων λέγοντες, ἔνιοι δὲ καὶ μεθυσθέντες ἤδη νυκτὸς ἦλθον ἐπὶ τὴν σκηνὴν ἐφόδιον αἰτοῦντες· εἶναι γὰρ αὐτοῖς πρὸς Καίσαρα βαδιστέον, ὅπως ἐκείνου κατηγορήσωσιν.", "st": "Oth. 5.3"}, {"sp": "N", "t": "ὤνησε δὲ τὰ πράγματα καὶ Σπουρίναν ἐν τῷ παραυτίκα λοιδορία περὶ Πλακεντίαν γενομένη τῶν στρατιωτῶν, οἱ γὰρ Οὐϊτελλίου τοῖς τείχεσι προσβάλλοντες ἐχλεύαζον τοὺς Ὄθωνος ἑστῶτας παρὰ τὰς ἐπάλξεις, σκηνικοὺς καὶ πυρριχιστὰς καὶ Πυθίων καὶ Ὀλυμπίων θεωρούς, πολέμου δὲ καὶ στρατείας ἀπείρους καὶ ἀθεάτους ἀποκαλοῦντες, καὶ μέγα φρονοῦντας ἐπὶ τῷ γέροντος ἀνόπλου κεφαλὴν ἀποτεμεῖν, τὸν Γάλβαν λέγοντες, εἰς δὲ ἀγῶνα καὶ μάχην ἀνδρῶν οὐκ ἂν ἐκφανῶς καταβάντας. οὕτω γὰρ ἐταράχθησαν ὑπὸ τούτων τῶν ὀνειδῶν καὶ διεκάησαν ὥστε προσπεσεῖν τῷ Σπουρίνᾳ, δεόμενοι χρῆσθαι καὶ προστάττειν αὐτοῖς, οὐδένα κίνδυνον οὐδὲ πόνον ἀπολεγομένοις. ἰσχυρᾶς δὲ συστάσης τειχομαχίας καὶ μηχανημάτων πολλῶν προσαχθέντων ἐκράτησαν οἱ τοῦ Σπουρίνα, καὶ φόνῳ πολλῷ τοὺς ἐναντίους ἀποκρουσάμενοι διετήρησαν ἔνδοξον πόλιν καὶ τῶν Ἰταλῶν οὐδεμιᾶς ἧττον ἀνθοῦσαν.", "st": "Oth. 6.1"}, {"sp": "N", "t": "ἦσαν δὲ καὶ τὰ ἄλλα τῶν Οὐϊτελλίου στρατηγῶν οἱ Ὄθωνος ἐντυχεῖν ἀλυπότεροι καὶ πόλεσι καὶ ἰδιώταις ἐκείνων δὲ Κεκίνας μὲν οὔτε φωνὴν οὔτε σχῆμα δημοτικός, ἀλλ’ ἐπαχθὴς καὶ ἀλλόκοτος, σώματος μεγάλου, Γαλατικῶς ἀναξυρίσι καὶ χειρῖσιν ἐνεσκευασμένος, σημείοις καὶ ἄρχουσι Ῥωμαϊκοῖς διαλεγόμενος. καὶ τὴν γυναῖκα παρέπεμπον αὐτῷ λογάδην ἱππεῖς ὀχουμένην ἵππῳ κεκοσμημένην ἐπιφανῶς. Φάβιον δὲ Οὐάλεντα τὸν ἕτερον στρατηγὸν οὔτε ἁρπαγαὶ πολεμίων οὔτε κλοπαὶ καὶ δωροδοκίαι παρὰ συμμάχων ἐνεπίμπλασαν χρηματιζόμενον, ἀλλὰ καὶ ἐδόκει διὰ τοῦτο βραδέως ὁδεύων ὑστερῆσαι τῆς προτέρας μάχης. οἱ δὲ τὸν Κεκίναν αἰτιῶνται, σπεύδοντα τὴν νίκην ἑαυτοῦ γενέσθαι πρὶν ἐκεῖνον ἐλθεῖν, ἄλλοις τε μικροτέροις περιπεσεῖν ἁμαρτήμασι καὶ μάχην οὐ κατὰ καιρὸν οὐδὲ γενναίως συνάψαι, μικροῦ πάντα τὰ πράγματα διαφθείρασαν αὐτοῖς.", "st": "Oth. 6.3"}, {"sp": "N", "t": "ἐπεὶ γὰρ ἀποκρουσθεὶς τῆς Πλακεντίας ὁ Κεκίνας ἐπὶ Κρεμώνην ὥρμησεν, ἑτέραν πόλιν εὐδαίμονα καὶ μεγάλην, πρῶτος μὲν Ἄννιος Γάλλος πρὸς Πλακεντίαν Σπουρίνᾳ βοηθῶν, ὡς ἤκουσε καθ’ ὁδὸν τοὺς Πλακεντίνους περιγεγονέναι, κινδυνεύειν δὲ τοὺς ἐν Κρεμώνῃ, μετήγαγεν ἐκεῖ τὸ στράτευμα καὶ κατεστρατοπέδευσε πλησίον τῶν πολεμίων ἔπειτα καὶ τῶν ἄλλων ἕκαστος ἐβοήθει τῷ στρατηγῷ. τοῦ δὲ Κεκίνα λοχίσαντος εἰς λάσια χωρία καὶ ὑλώδη πολλοὺς ὁπλίτας, ἱππεῖς δὲ προεξελάσαι κελεύσαντος, κἂν συνάψωσιν οἱ πολέμιοι κατὰ μικρὸν ἀναχωρεῖν καὶ ἀναφεύγειν, ἄχρι ἂν ὑπάγοντες οὕτως ἐμβάλωσιν αὐτοὺς εἰς τὴν ἐνέδραν, ἐξήγγειλαν αὐτόμολοι τῷ Κέλσῳ. καὶ οὗτος μὲν ἱππεῦσιν ἀγαθοῖς ἀντεξελάσας, πεφυλαγμένως δὲ χρώμενος τῇ διώξει καὶ τὴν ἐνέδραν περισχὼν καὶ συνταράξας, ἐκάλει τοὺς ὁπλίτας ἐκ τοῦ στρατοπέδου. καὶ δοκοῦσιν ἂν ἐπελθόντες ἐν καιρῷ μηδένα λιπεῖν τῶν πολεμίων, ἀλλὰ πᾶν τὸ μετὰ Κεκίνα στράτευμα συντρῖψαι καὶ ἀνελεῖν ἐπισπόμενοι τοῖς ἱππεῦσι· νυνὶ δὲ ὁ Παυλῖνος ὀψὲ καὶ σχολῇ προσβοηθήσας αἰτίαν ἔσχεν ἐνδεέστερον τῆς δόξης στρατηγῆσαι δι’ εὐλάβειαν. οἱ δὲ πολλοὶ τῶν στρατιωτῶν καὶ προδοσίαν ἐνεκάλουν αὐτῷ, καὶ παρώξυνον τὸν Ὄθωνα, μεγαληγοροῦντες ὡς νενικηκότων αὐτῶν, τῆς δὲ νίκης οὐκ ἐπὶ πᾶν προελθούσης κακίᾳ τῶν στρατηγῶν. ὁ δὲ Ὄθων οὐχ οὕτως ἐπίστευεν αὐτοῖς ὡς ἐβούλετο μὴ δοκεῖν ἀπιστεῖν. ἔπεμψεν οὖν Τιτιανὸν ἐπὶ τὰ στρατεύματα τὸν ἀδελφὸν καὶ Πρόκλον τὸν ἔπαρχον, ὃς εἶχεν ἔργῳ τὴν πᾶσαν ἀρχήν, πρόσχημα δὲ ἦν ὁ Τιτιανός. οἱ δὲ περὶ τὸν Κέλσον καὶ Παυλῖνον ἄλλως ἐφείλκοντο συμβούλων ὄνομα καὶ φίλων, ἐξουσίαν καὶ δύναμιν ἐν τοῖς πράγμασι μηδεμίαν ἔχοντες, ἦν δὲ θορυβώδη καὶ τὰ παρὰ τοῖς πολεμίοις, μάλιστα δὲ τοῖς ὑπὸ τῷ Οὐάλεντι· καὶ τῆς περὶ τὴν ἐνέδραν μάχης ἀπαγγελθείσης ἐχαλέπαινον ὅτι μὴ παρεγένοντο μηδὲ ἤμυναν ἀνδρῶν τοσούτων ἀποθανόντων, μόλις δὲ πείσας καὶ παραιτησάμενος ὡρμημένους αὐτοὺς βάλλειν ἀνέζευξε καὶ συνῆψε τοῖς περὶ Κεκίναν.", "st": "Oth. 7.1"}, {"sp": "N", "t": "ὁ δὲ Ὄθων παραγενόμενος εἰς Βητριακὸν εἰς τὸ στρατόπεδον ἔστι δὲ πολίχνη πλησίον Κρεμώνης τὸ Βητριακόν ἐβουλεύετο περὶ τῆς μάχης, καὶ Πρόκλῳ μὲν ἐδόκει καὶ Τιτιανῷ, τῶν στρατευμάτων ὄντων προθύμων καὶ προσφάτου τῆς νίκης, διαγωνίσασθαι καὶ μὴ καθῆσθαι τὴν ἀκμὴν ἀμβλύνοντα τῆς δυνάμεως καὶ περιμένοντα Οὐϊτέλλιον αὐτὸν ἐκ Γαλατίας ἐπελθεῖν· Παυλῖνος δὲ τοῖς μὲν πολεμίοις ἔφη πάντα μεθ’ ὧν μαχοῦνται παρεῖναι, καὶ μηδὲν ἐνδεῖν, Ὄθωνι δὲ τῆς ἤδη παρούσης οὐκ ἐλάττονα προσδόκιμον εἶναι δύναμιν ἐκ Μυσίας καὶ Παννονίας, ἂν τὸν αὑτοῦ περιμένῃ καιρόν, ἀλλὰ μὴ στρατηγῇ πρὸς τὸν τῶν πολεμίων. οὐ γὰρ ἀμβλυτέροις γε χρήσεσθαι τότε τοῖς νῦν θαρροῦσιν ἀπ’ ἐλαττόνων, ἂν πλείονας τοὺς ἀγωνιζομένους προσλάβωσιν, ἀλλ’ ἐκ περιουσίας ἀγωνιεῖσθαι· καὶ χωρὶς δὲ τούτου τὴν διατριβὴν εἶναι πρὸς αὐτῶν ἐν ἀφθόνοις πᾶσιν ὄντων, ἐκείνοις δὲ τὸν χρόνον ἀπορίαν παρέξειν τῶν ἀναγκαίων ἐν πολεμίᾳ καθεζομένοις. ταῦτα λέγοντι Παυλίνῳ Μάριος Κέλσος ἐγένετο σύμψηφος. Ἄννιος δὲ Γάλλος οὐ παρῆν μέν, ἀλλ’ ἐθεραπεύετο πεπτωκὼς ἀφ’ ἵππου, γράψαντος δὲ Ὄθωνος αὐτῷ συνεβούλευσε μὴ σπεύδειν, ἀλλὰ τὴν ἐκ Μυσίας περιμένειν δύναμιν ἤδη καθ’ ὁδὸν οὖσαν. οὐ μὴν ἐπείθετο τούτοις, ἀλλὰ ἐκράτησαν οἱ πρὸς τὴν μάχην παρορμῶντες.", "st": "Oth. 8.1"}, {"sp": "N", "t": "αἰτίαι δὲ πλείονες ἄλλαι ὑπ’ ἄλλων λέγονται προδήλως δὲ οἱ στρατηγικοὶ προσαγορευόμενοι καὶ τάξιν ἔχοντες δορυφόρων, τότε μᾶλλον ἀληθινῆς γευόμενοι στρατείας καὶ τὰς ἐν Ῥώμῃ διατριβὰς καὶ διαίτας ἀπολέμους καὶ πανηγυρικὰς ποθοῦντες, οὐκ ἦσαν καθεκτοὶ σπεύδοντες ἐπὶ τὴν μάχην, ὡς εὐθὺς ἐξ ἐπιδρομῆς ἀναρπασόμενοι τούς ἐναντίους. δοκεῖ δὲ μηδὲ αὐτὸς Ὄθων ἐξαναφέρειν ἔτι πρὸς τὴν ἀδηλότητα μηδὲ ὑπομένειν ἀηθείᾳ καὶ μαλακότητι τούς περὶ τῶν δεινῶν λογισμούς, ἐκπονούμενος δὲ ταῖς φροντίσι σπεύδειν ἐγκαλυψάμενος, ὥσπερ ἀπὸ κρημνοῦ, μεθεῖναι τὰ πράγματα πρὸς τὸ συντυχόν. καὶ τοῦτο μὲν διηγεῖτο Σεκοῦνδος ὁ ῥήτωρ ἐπὶ τῶν ἐπιστολῶν γενόμενος τοῦ Ὄθωνος. ἑτέρων δὲ ἦν ἀκούειν ὅτι τοῖς στρατεύμασιν ἀμφοτέροις παρίσταντο ὁρμαὶ πολλαὶ ὡς εἰς ταὐτὸ συνελθεῖν καὶ μάλιστα μὲν αὐτοὺς ὁμοφρονήσαντας ἐκ τῶν παρόντων ἡγεμονικῶν ἑλέσθαι τὸν ἄριστον, εἰ δὲ μή, τὴν σύγκλητον ὁμοῦ καθίσαντας ἐφεῖναι τὴν αἵρεσιν ἐκείνῃ τοῦ αὐτοκράτορος. καὶ οὐκ ἀπεικός ἐστι, μηδετέρου τότε τῶν προσαγορευομένων αὐτοκρατόρων εὐδοκιμοῦντος, ἐπιπίπτειν τοιούτους διαλογισμοὺς τοῖς γνησίοις καὶ διαπόνοις καὶ σωφρονοῦσι τῶν στρατιωτῶν, ὡς ἔχθιστον εἴη καὶ δεινόν, ἃ πάλαι διὰ Σύλλαν καὶ Μάριον, εἶτα Καίσαρα καὶ Πομπήϊον ᾠκτείροντο δρῶντες ἀλλήλους καὶ πάσχοντες οἱ πολῖται, ταῦτα νῦν ὑπομένειν ἢ Οὐϊτελλίῳ λαιμαργίας καὶ οἰνοφλυγίας ἢ τρυφῆς καὶ ἀκολασίας Ὄθωνι τὴν ἡγεμονίαν χορήγημα προθεμένους. ταῦτ’ οὖν ὑπονοοῦσι τούς τε περὶ τὸν Κέλσον αἰσθανομένους ἐμβαλεῖν διατριβήν, ἐλπίζοντας ἄνευ μάχης καὶ πόνων κριθήσεσθαι τὰ πράγματα, καὶ τούς περὶ τὸν Ὄθωνα φοβουμένους ἐπιταχῦναι τὴν μάχην.", "st": "Oth. 9.1"}, {"sp": "N", "t": "αὐτὸς δὲ πάλιν εἰς Βρίξιλλον ἀνεχώρησε, καὶ τοῦτο προσεξαμαρτών, οὐχ ὅτι μόνον τὴν ἐν ὀφθαλμοῖς αὐτοῦ παρόντος αἰδῶ καὶ φιλοτιμίαν ἀφεῖλε τῶν ἀγωνιζομένων, ἀλλὰ καὶ τοὺς ἐρρωμενεστάτους καὶ προθυμοτάτους δι’ αὐτὸν ἱππεῖς καὶ πεζοὺς ἀπαγαγὼν φυλακὴν τοῦ σώματος ὡσπερεὶ στόμωμα τῆς δυνάμεως ἀπέκοψε.", "st": "Oth. 10.1"}, {"sp": "N", "t": "συνέβη δὲ ταῖς ἡμέραις ἐκείναις καὶ περὶ τὸν Ἠριδανὸν ἀγῶνα γενέσθαι, τοῦ μὲν Κεκίνα ζευγνύντος τὴν διάβασιν, τῶν δὲ Ὄθωνος εἰργόντων καὶ προσμαχομένων. ὡς δὲ οὐδὲν ἐπέραινον, ἐνθεμένων εἰς τὰ πλοῖα δᾷδα θείου καὶ πίττης ἀνάπλεων, διὰ τοῦ πόρου πνεῦμα προσπεσὸν ἄφνω τὴν παρεσκευασμένην ὕλην ἐπὶ τοὺς πολεμίους ἐξερρίπιζε. καπνοῦ δὲ πρῶτον, εἶτα λαμπρᾶς φλογὸς ἐκπεσούσης, ταραττόμενοι καὶ ἀποπηδῶντες εἰς τὸν ποταμὸν τάς τε ναῦς ἀνέτρεπον καὶ τὰ σώματα τοῖς πολεμίοις μετὰ γέλωτος παρεῖχον. οἱ δὲ Γερμανοὶ τοῖς Ὄθωνος μονομάχοις περὶ νησῖδα τοῦ ποταμοῦ προσμίξαντες ἐκράτησαν καὶ διέφθειραν αὐτῶν οὐκ ὀλίγους.", "st": "Oth. 10.2"}, {"sp": "N", "t": "γενομένων δὲ τούτων, καὶ τῶν ἐν Βητριακῷ στρατιωτῶν τοῦ Ὄθωνος ἐκφερομένων μετ’ ὀργῆς ἐπὶ τὴν μάχην, προήγαγεν αὐτοὺς ὁ Πρόκλος ἐκ τοῦ Βητριακοῦ, καὶ κατεστρατοπέδευσεν ἀπὸ πεντήκοντα σταδίων οὕτως ἀπείρως καὶ καταγελάστως ὥστε, τῆς μὲν ὥρας ἐαρινῆς οὔσης, τῶν δὲ κύκλῳ πεδίων πολλὰ νάματα καὶ ποταμοὺς ἀεννάους ἐχόντων, ὕδατος σπάνει πιέζεσθαι. τῇ δὲ ὑστεραίᾳ βουλόμενον προάγειν ἐπὶ τοὺς πολεμίους ὁδὸν οὐκ ἐλάττονα σταδίων ἑκατὸν οἱ περὶ τὸν Παυλῖνον οὐκ εἴων, ἀλλ’ ᾤοντο δεῖν περιμένειν καὶ μὴ προπονεῖν ἑαυτούς, μηδὲ εὐθὺς ἐκ πορείας μάχην τίθεσθαι πρὸς ἄνδρας ὡπλισμένους καὶ παρατεταγμένους καθ’ ἡσυχίαν, ἐν ὅσῳ χρόνῳ προΐασιν αὐτοὶ τοσαύτην ὁδὸν ἀναμεμιγμένων ὑποζυγίων καὶ ἀκολούθων. οὔσης δὲ περὶ τούτων ἀντιλογίας ἐν τοῖς στρατηγοῖς ἦλθε παρ’ Ὄθωνος ἱππεὺς τῶν καλουμένων Νομάδων γράμματα κομίζων κελεύοντα μὴ μένειν μηδὲ διατρίβειν, ἀλλ’ ἄγειν εὐθὺς ἐπὶ τοὺς πολεμίους, ἐκεῖνοι μὲν οὖν ἄραντες ἐχώρουν, ὁ δὲ Κεκίνας πυθόμενος τὴν ἔφοδον αὐτῶν ἐθορυβήθη, καὶ κατὰ σπουδὴν ἀπολιπὼν τὰ ἔργα καὶ τὸν ποταμὸν ἧκεν εἰς τὸ στρατόπεδον. ὡπλισμένων δὲ ἤδη τῶν πολλῶν, καὶ τὸ σύνθημα παραλαμβανόντων παρὰ τοῦ Οὐάλεντος, ἐν ὅσῳ τὴν τάξιν διελάγχανε τὰ τάγματα, τοὺς ἀρίστους τῶν ἱππέων προεξέπεμψαν.", "st": "Oth. 11.1"}, {"sp": "N", "t": "ἐμπίπτει δὲ τοῖς προτεταγμένοις τῶν Ὄθωνος ἐκ δή τινος αἰτίας δόξα καὶ λόγος ὡς μεταβαλουμένων τῶν Οὐϊτελλίου στρατηγῶν πρὸς αὐτούς, ὡς οὖν ἐγγὺς ἦσαν, ἠσπάσαντο φιλίως συστρατιώτας προσαγορεύσαντες. ἐκείνων δὲ τὴν προσαγόρευσιν οὐκ εὐμενῶς, ἀλλὰ μετὰ θυμοῦ καὶ φωνῆς πολεμικῆς ἀμειψαμένων, τοῖς μὲν ἀσπασαμένοις ἀθυμία, τοῖς δὲ λοιποῖς ὑπόνοια κατὰ τῶν ἀσπασαμένων ὡς προδιδόντων παρέστη. καὶ τοῦτο πρῶτον αὑτοὺς ἐτάραξεν ἤδη τῶν πολεμίων ἐν χερσὶν ὄντων, εἶτα τῶν ἄλλων οὐδὲν ἦν κόσμῳ γινόμενον, ἀλλὰ πολλὴν μὲν ἀταξίαν τὰ σκευοφόρα τοῖς μαχομένοις ἐμπλαζόμενα παρεῖχε, πολλοὺς δὲ τὰ χωρία διασπασμοὺς ἐποίει τάφρων ὄντα μεστὰ καὶ ὀρυγμάτων, ἃ φοβούμενοι καὶ περιϊόντες ἠναγκάζοντο φύρδην καὶ κατὰ μέρη πολλὰ συμπλέκεσθαι τοῖς ἐναντίοις. μόναι δὲ δύο λεγεῶνες οὕτω γὰρ τὰ τάγματα Ῥωμαῖοι καλοῦσιν, ἐπίκλησιν ἡ μὲν Οὐϊτελλίου Ἅρπαξ, ἡ δὲ Ὄθωνος Βοηθός, εἰς πεδίον ἐξελίξασαι ψιλὸν καὶ ἀναπεπταμένον, νόμιμόν τινα μάχην, συμπεσοῦσαι φαλαγγηδόν, ἐμάχοντο πολὺν χρόνον. οἱ μὲν οὖν Ὄθωνος ἄνδρες ἦσαν εὔρωστοι καὶ ἀγαθοί, πολέμου δὲ καὶ μάχης τότε πρῶτον πεῖραν λαμβάνοντες· οἱ δὲ Οὐϊτελλίου πολλῶν ἀγώνων ἐθάδες, ἤδη δὲ γηραιοὶ καὶ παρακμάζοντες.", "st": "Oth. 12.1"}, {"sp": "N", "t": "ὁρμήσαντες οὖν ἐπ’ αὑτοὺς οἱ Ὄθωνος ἐώσαντο καὶ τόν ἀετὸν ἀφείλοντο, πάντας ὁμοῦ τι τοὺς προμάχους ἀποκτείναντες· οἱ δὲ ὑπὸ αἰσχύνης καὶ ὀργῆς ἐμπεσόντες αὐτοῖς τόν τε πρεσβευτὴν τοῦ τάγματος Ὀρφίδιον ἔκτειναν καὶ πολλὰ τῶν σημείων ἥρπασαν. τοῖς δὲ μονομάχοις ἐμπειρίαν τε καὶ θάρσος ἔχειν πρὸς τὰς συμπλοκὰς δοκοῦσιν ἐπήγαγεν Οὔαρος Ἀλφῆνος τοὺς καλουμένους Βατάβους. εἰσὶ δὲ Γερμανῶν ἱππεῖς ἄριστοι, νῆσον οἰκοῦντες ὑπὸ τοῦ Ῥήνου περιρρεομένην. τούτους ὀλίγοι μὲν τῶν μονομάχων ὑπέστησαν, οἱ δὲ πλεῖστοι φεύγοντες ἐπὶ τόν ποταμὸν ἐμπίπτουσιν εἰς σπείρας τῶν πολεμίων αὐτόθι τεταγμένας, ὑφ’ ὧν ἀμυνόμενοι πάντες ὁμαλῶς διεφθάρησαν. αἴσχιστα δὲ ἠγωνίσαντο πάντων οἱ στρατηγικοί, μηδὲ ὅσον ἐν χερσὶ γενέσθαι τοὺς ἐναντίους ὑπομείναντες, ἀλλὰ καὶ τοὺς ἀηττήτους ἔτι φόβου καὶ ταραχῆς ἀνεπίμπλασαν φεύγοντες δι’ αὐτῶν, οὐ μὴν ἀλλὰ πολλοί γε τῶν Ὄθωνος νενικηκότες τοὺς καθ’ αὑτοὺς ἐβιάσαντο καὶ διεξέπεσον διὰ τῶν πολεμίων κρατούντων εἰς τὸ στρατόπεδον.", "st": "Oth. 12.4"}, {"sp": "N", "t": "τῶν δὲ στρατηγῶν οὔτε Πρόκλος οὔτε Παυλῖνος συνεισελθεῖν ἐτόλμησαν, ἀλλ’ ἐξέκλιναν φοβούμενοι τοὺς στρατιώτας ἤδη τὴν αἰτίαν ἐπὶ τοὺς στρατηγοὺς τρέποντας. Ἄννιος δὲ Γάλλος ἀνελάμβανεν ἐν τῇ πόλει καὶ παρεμυθεῖτο τοὺς ἐκ τῆς μάχης συλλεγομένους, ὡς ἀγχωμάλου γεγενημένης καὶ πολλοῖς κεκρατηκότας μέρεσι τῶν πολεμίων. Μάριος δὲ Κέλσος τοὺς ἐν τέλει συναγαγὼν ἐκέλευσε σκοπεῖν τὸ κοινόν, ὡς ἐπὶ συμφορᾷ τηλικαύτῃ καὶ φόνῳ τοσούτῳ πολιτῶν μηδὲ Ὄθωνος, εἴπερ ἀνὴρ ἀγαθός ἐστιν, ἐθελήσοντος ἔτι πειρᾶσθαι τῆς τύχης, ὅπου καὶ Κάτων καὶ Σκηπίων, Καίσαρι κρατοῦντι μετὰ Φάρσαλον εἶξαι μὴ θελήσαντες, αἰτίαν ἔχουσιν ὡς πολλοὺς καὶ ἀγαθοὺς ἄνδρας ἐν Λιβύῃ παραναλώσαντες οὐκ ἀναγκαίως, καίπερ ἀγωνιζόμενοι περὶ τῆς Ῥωμαίων ἐλευθερίας. τὰ γὰρ ἄλλα κοινὴν ἡ τύχη παρέχουσα πᾶσιν ἑαυτὴν ἓν οὐκ ἀφαιρεῖται τῶν ἀγαθῶν, τὸ κἂν πταίσωσιν εὐλογιστεῖν πρὸς τὰ συντυγχάνοντα.", "st": "Oth. 13.1"}, {"sp": "N", "t": "ταῦτα λέγων ἔπειθε τοὺς ἡγεμονικούς, ἐπεὶ δὲ πειρώμενοι τοὺς στρατιώτας ἑώρων εἰρήνης δεομένους καὶ Τιτιανὸς ἐκέλευε πρεσβεύειν ὑπὲρ ὁμονοίας, ἔδοξε Κέλσῳ καὶ Γάλλῳ βαδίζειν καὶ διαλέγεσθαι τοῖς περὶ τὸν Κεκίναν καὶ Οὐάλεντα. βαδίζουσι δὲ αὐτοῖς ἀπήντησαν ἑκατοντάρχαι τὴν μὲν δύναμιν ἤδη κεκινημένην λέγοντες ἐρχομένην ἐπὶ τὸ Βητριακόν, αὐτοὶ δὲ ὑπὸ τῶν στρατηγῶν ἀπεστάλθαι περὶ ὁμονοίας, ἐπαινέσαντες οὖν οἱ περὶ τὸν Κέλσον ἐκέλευσαν αὐτοὺς ἀναστρέψαντας πάλιν ἀπαντᾶν μετ’ αὐτῶν τοῖς περὶ τὸν Κεκίναν. ἐπεὶ δὲ ἐγγὺς ἦσαν, ἐκινδύνευσεν ὁ Κέλσος. ἔτυχον γὰρ οἱ περὶ τὴν ἐνέδραν ἡττημένοι πρότερον ἱππεῖς προεξελαύνοντες. ὡς οὖν προσιόντα τὸν Κέλσον κατεῖδον, εὐθὺς βοήσαντες ὥρμησαν ἐπ αὐτόν, οἱ δὲ ἑκατοντάρχαι προέστησαν ἀνείργοντες· καὶ τῶν ἄλλων λοχαγῶν φείδεσθαι βοώντων οἱ περὶ τὸν Κεκίναν πυθόμενοι καὶ προσελάσαντες τὴν ἀκοσμίαν ταχὺ τῶν ἱππέων ἔπαυσαν, τὸν δὲ Κέλσον ἀσπασάμενοι φιλοφρόνως ἐβάδιζον μετ’ αὐτῶν εἰς τὸ Βητριακόν. ἐν δὲ τούτῳ μετάνοια Τιτιανὸν ἔσχεν ἐκπέμψαντα τοὺς πρέσβεις· καὶ τῶν στρατιωτῶν τοὺς θρασυνομένους αὖθις ἀνεβίβαζεν ἐπὶ τὰ τείχη καὶ τοὺς ἄλλους παρεκάλει βοηθεῖν. τοῦ δὲ Κεκίνα προσελάσαντος τῷ ἵππῳ καὶ τὴν δεξιὰν ὀρέγοντος οὐδεὶς ἀντέσχεν, ἀλλ’ οἱ μὲν ἀπὸ τῶν τειχῶν ἠσπάζοντο τοὺς στρατιώτας, οἱ δὲ τὰς πύλας ἀνοίξαντες ἐξῄεσαν καὶ ἀνεμίγνυντο τοῖς προσήκουσιν. ἠδίκει δὲ οὐδείς, ἀλλὰ καὶ φιλοφροσύναι καὶ δεξιώσεις ἦσαν, ὤμοσαν δὲ πάντες περὶ τοῦ Οὐϊτελλίου καὶ προσεχώρησαν.", "st": "Oth. 13.4"}, {"sp": "N", "t": "οὕτω μὲν οἱ πλεῖστοι τῶν παραγενομένων ἀπαγγέλλουσι γενέσθαι τὴν μάχην, οὐδὲ αὐτοὶ σαφῶς ὁμολογοῦντες εἰδέναι τὰ καθ’ ἕκαστα διὰ τὴν ἀταξίαν καὶ τὴν ἀνωμαλίαν. ἐμοὶ δὲ ὕστερον ὁδεύοντι διὰ τοῦ πεδίου Μέστριος Φλῶρος, ἀνὴρ ὑπατικὸς τῶν τότε μὴ κατὰ γνώμην, ἀλλ’ ἀνάγκῃ μετὰ τοῦ Ὄθωνος γενομένων, νεὼν ὄντα παλαιὸν ἐπιδείξας διηγεῖτο μετὰ τὴν μάχην ἐπελθὼν ἰδεῖν νεκρῶν σωρὸν τηλικοῦτον ὥστε τοὺς ἐπιπολῆς ἅπτεσθαι τῶν ἀετῶν. καὶ τὴν αἰτίαν ἔφη ζητῶν οὔτε αὐτὸς εὑρεῖν οὔτε παρ’ ἄλλου του πυθέσθαι. θνήσκειν μὲν γὰρ παρά τοὺς ἐμφυλίους πολέμους, ὅταν τροπὴ γένηται, πλείονας εἰκός ἐστι ι, τῷ μηδέν α ζωγρεῖν, χρῆσθαι γὰρ οὐκ ἔστι τοῖς ἁλισκομένοις, ἡ δ’ ἐπὶ τοσοῦτο σωρεία καὶ συμφόρησις οὐκ ἔχει τὴν αἰτίαν εὐσυλλόγιστον.", "st": "Oth. 14.1"}, {"sp": "N", "t": "τῷ δὲ Ὄθωνι πρῶτον μὲν ἀσαφής, ὥσπερ εἴωθε περὶ τῶν τηλικούτων, προσέπεσε λόγος· ἐπεὶ δὲ καὶ τετρωμένοι τινὲς ἧκον ἐκ τῆς μάχης ἀπαγγέλλοντες, τοὺς μὲν φίλους ἧττον ἄν τις ἐθαύμασεν οὐκ ἐῶντας ἀπαγορεύειν, ἀλλὰ θαρρεῖν παρακελευομένους, τὸ δὲ τῶν στρατιωτῶν πάθος ἅπασαν ὑπερέβαλε πίστιν. ὡς οὐδεὶς ἀπῆλθεν, οὐδὲ μετέστη πρὸς τοὺς κρατοῦντας, οὐδ’ ὤφθη τὸ καθ’ αὑτὸν ζητῶν ἀπεγνωσμένου τοῦ ἡγεμόνος, πάντες δ’ ὁμαλῶς ἐπὶ θύρας ἦλθον, ἐκάλουν αὐτοκράτορα, προελθόντος ἐγίνοντο προστρόπαιοι, μετὰ βοῆς καὶ ἱκεσίας χειρῶν ἥπτοντο, προσέπιπτον, ἐδάκρυον, ἐδέοντο μὴ σφᾶς ἐγκαταλιπεῖν, μὴ προδοῦναι τοῖς πολεμίοις, ἀλλὰ χρῆσθαι μέχρι ἂν ἐμπνέωσι καὶ ψυχαῖς καὶ σώμασιν ὑπὲρ αὑτοῦ, ταῦτα ὁμοῦ πάντες ἱκέτευον. εἷς δὲ τῶν ἀφανεστέρων ἀνατείνας τὸ ξίφος καὶ εἰπών, ἴσθι, Καῖσαρ, οὕτως ὑπὲρ σοῦ παρατεταγμένους ἅπαντας, ἀπέσφαξεν ἑαυτόν.", "st": "Oth. 15.1"}, {"sp": "N", "t": "ἀλλὰ τούτων οὐδὲν ἐπέκλασε τὸν Ὄθωνα, φαιδρῷ δὲ καὶ καθεστῶτι προσώπῳ πανταχόσε τὰς ὄψεις περιαγαγών, ταύτην, εἶπεν, ὦ συστρατιῶται, τὴν ἡμέραν ἐκείνης, ἐν ᾗ με πρῶτον ἐποιήσατε αὐτοκράτορα, μακαριωτέραν ἡγοῦμαι, τοιούτους ὁρῶν ὑμᾶς καὶ τηλικούτων ἀξιούμενος. ἀλλὰ μὴ μείζονος ἀποστερεῖτε, τοῦ καλῶς ἀποθανεῖν ὑπὲρ τοσούτων καὶ τοιούτων πολιτῶν, εἰ τῆς Ῥωμαίων ἡγεμονίας ἄξιος γέγονα, δεῖ με τῆς ἐμῆς ψυχῆς ὑπὲρ τῆς πατρίδος ἀφειδεῖν. οἶδα τὴν νίκην τοῖς ἐναντίοις οὔτε βεβαίαν οὔτε ἰσχυρὰν οὖσαν. ἀπαγγέλλουσι τὴν ἐκ Μυσίας ἡμῶν δύναμιν οὐ πολλῶν ἡμερῶν ὁδὸν ἀπέχειν, ἤδη καταβαίνουσαν ἐπὶ τὸν Ἀδρίαν. Ἀσία καὶ Συρία καὶ Αἴγυπτος καὶ τὰ πολεμοῦντα Ἰουδαίοις στρατεύματα μεθ’ ἡμῶν, ἥ τε σύγκλητος παρ’ ἡμῖν καί τέκνα τῶν ἐναντίων καὶ γυναῖκες, ἀλλ’ οὐκ ἔστι πρὸς Ἀννίβαν οὐδὲ Πύρρον οὐδὲ Κίμβρους ὁ πόλεμος ὑπὲρ τῆς Ἰταλίας, ἀλλὰ Ῥωμαίοις πολεμοῦντες ἀμφότεροι τὴν πατρίδα καὶ νικῶντες ἀδικοῦμεν καὶ νικώμενοι. καὶ γὰρ τὸ ἀγαθὸν τοῦ κρατοῦντος ἐκείνῃ κακόν ἐστι. πιστεύσατε πολλάκις ὅτι δύναμαι κάλλιον ἀποθανεῖν ἢ ἄρχειν. οὐ γὰρ ὁρῶ τί τηλικοῦτον Ῥωμαίοις ὄφελος ἔσομαι κρατήσας, ἡλίκον ἐπιδοὺς ἐμαυτὸν ὑπὲρ εἰρήνης καὶ ὁμονοίας, καὶ τοῦ μὴ πάλιν ἡμέραν τοιαύτην ἐπιδεῖν τὴν Ἰταλίαν.", "st": "Oth. 15.4"}, {"sp": "N", "t": "τοιαῦτα διαλεχθείς, καὶ πρὸς τούς ἐνίστασθαι καὶ παρακαλεῖν ἐπιχειροῦντας ἀπισχυρισάμενος, τούς τε φίλους ἐκέλευεν ἀπαλλάττεσθαι καὶ τῶν συγκλητικῶν τούς παρόντας· τοῖς δὲ μὴ παροῦσιν ἐπέστελλε καὶ γράμματα πρὸς τὰς πόλεις, ὅπως παρακομισθῶσιν ἐντίμως καὶ μετὰ ἀσφαλείας. προσαγόμενος δὲ τὸν ἀδελφιδοῦν Κοκκήϊον, ἔτι μειράκιον ὄντα, θαρρεῖν παρεκάλει καὶ μὴ δεδιέναι Οὐϊτέλλιον, οὗ καὶ μητέρα καὶ γενεὰν καὶ γυναῖκα αὐτός, ὥσπερ οἰκείων κηδόμενος, διαφυλάξαι. διὰ τοῦτο γὰρ οὐδὲ θέσθαι παῖδα βουλόμενος αὐτόν, ἀλλ’ ἀναβαλέσθαι τὴν εἰσποίησιν, ὅπως συνάρχοι κρατήσαντος αὐτοῦ, μὴ προσαπόλοιτο πταίσαντος· ἐκεῖνο δέ, εἶπεν, ὦ παῖ, παρεγγυῶμαί σοι τελευταῖον, μήτε ἐπιλαθέσθαι παντάπασι μήτε ἄγαν μνημονεύειν ὅτι Καίσαρα θεῖον ἔσχες.", "st": "Oth. 16.1"}, {"sp": "N", "t": "γενόμενος δὲ ἀπὸ τούτων μετὰ μικρὸν ἤκουσε θορύβου καὶ βοῆς ἐπὶ θύραις, οἱ γὰρ στρατιῶται τῶν συγκλητικῶν τοῖς ἀπιοῦσι διηπείλουν ἀποσφάξειν, εἰ μὴ παραμενοῦσιν, ἀλλὰ οἰχήσονται τὸν αὐτοκράτορα καταλιπόντες. πάλιν οὖν προῆλθεν ὑπὲρ τῶν ἀνδρῶν φοβηθείς, καὶ τούς στρατιώτας, οὐκέτι δεητικὸς οὐδὲ πρᾷος, ἀλλὰ τραχὺς ὀφθείς, καὶ μετ’ ὀργῆς εἰς τὸ θορυβοῦν μάλιστα διαβλέψας, ἀπελθεῖν ἐποίησεν εἴξαντας καὶ διατρέσαντας.", "st": "Oth. 16.3"}, {"sp": "N", "t": "ἤδη δὲ ἑσπέρας οὔσης ἐδίψησε, καὶ πιὼν ὀλίγον ὕδατος, δυεῖν ὄντων αὐτῷ ξιφῶν, ἑκατέρου κατεμάνθανε τὸ σπάσμα πολὺν χρόνον, καὶ τὸ ἕτερον ἀπέδωκε, θάτερον δὲ εἰς τὰς ἀγκάλας ἀναλαβὼν τοὺς οἰκέτας προσεκαλεῖτο. καὶ φιλοφρονούμενος διένεμε τῶν χρημάτων τῷ μὲν πλέον, τῷ δὲ ἔλαττον, οὐχ ὥσπερ ἀλλοτρίων ἀφειδῶν, ἀλλὰ τὸ κατ’ ἀξίαν καὶ τὸ μέτριον ἐπιμελῶς φυλάττων. ἀποπέμψας δὲ τούτους ἤδη τὸ λοιπὸν ἀνεπαύετο τῆς νυκτός, ὥστε τοὺς κατευναστὰς αἰσθάνεσθαι βαθέως αὐτοῦ καθεύδοντος. ὄρθρου δὲ καλέσας ἀπελεύθερον ᾧ συνδιῴκησε τὰ περὶ τοὺς συγκλητικούς, μαθεῖν προσέταξε καὶ πυθόμενος γεγονέναι τοῖς ἀπερχομένοις ὧν ἕκαστος ἔχρῃζεν, ἴθι τοίνυν, ἔφη, σύ, καὶ ποίει τοῖς στρατιώταις ἐμφανῆ σεαυτόν, εἰ μὴ θέλεις κακῶς ὑπ’ αὐτῶν ἀποθανεῖν ὡς ἐμοὶ συμπράξας τὸν θάνατον. ἐξελθόντος δὲ τοῦ ἀνθρώπου τὸ ξίφος ὑποστήσας ὀρθὸν ἀμφοτέραις ταῖς χερσί, καὶ περιπεσὼν ἄνωθεν, ὅσον ἅπαξ στενάξαι μόνον ᾔσθετο τοῦ πόνου καὶ τοῖς ἐκτὸς αἴσθησιν παρέσχεν. ἀραμένων δὲ τῶν παίδων οἰμωγὴν εὐθὺς ἅπαν τὸ στρατόπεδον καὶ τὴν πόλιν ἐπεῖχε κλαυθμός· καὶ μετὰ βοῆς οἱ στρατιῶται εἰσέπεσον ἐπὶ τὰς θύρας καὶ ὠλοφύροντο, περιπαθοῦντες καὶ λοιδοροῦντες ἑαυτοὺς μὴ φυλάξαντας τὸν αὐτοκράτορα μηδὲ κωλύσαντας ἀποθανεῖν ὑπὲρ αὐτῶν. ἀπέστη δὲ οὐδεὶς τῶν κατ’ αὐτόν, ἐγγὺς ὄντων τῶν πολεμίων, ἀλλὰ κοσμήσαντες τὸ σῶμα καὶ πυρὰν κατασκευάσαντες ἐξεκόμιζον ἐν τοῖς ὅπλοις οἱ φθάσαντες ὑποδῦναι καὶ βαστάσαι τὸ λέχος ἐπιγαυρούμενοι. τῶν δὲ ἄλλων οἱ μὲν τὸ τραῦμα τοῦ νεκροῦ κατεφίλουν προσπίπτοντες, οἱ δὲ ἥπτοντο τῶν χειρῶν, οἱ δὲ προσεκύνουν πόρρωθεν. ἔνιοι δὲ τῇ πυρᾷ λαμπάδας ὑφέντες ἑαυτοὺς ἀπέσφαξαν, οὐδὲν ἐκδήλως οὔτε πεπονθότες χρηστὸν ὑπὸ τοῦ τεθνηκότος οὔτε πείσεσθαι δεινὸν ὑπὸ τοῦ κρατοῦντος δεδιότες. ἀλλ’ ἔοικε μηδενὶ τῶν πώποτε τυράννων ἢ βασιλέων δεινὸς οὕτως ἔρως ἐγγενέσθαι καὶ περιμανὴς τοῦ ἄρχειν, ὡς ἐκεῖνοι τοῦ ἄρχεσθαι καὶ ὑπακούειν Ὄθωνος ἠράσθησαν οὕς γε μηδ’ ἀποθανόντος ὁ πόθος προὔλιπεν, ἀλλὰ παρέμεινεν εἰς ἀνήκεστον ἔχθος Οὐϊτελλίῳ τελευτήσας.", "st": "Oth. 17.1"}, {"sp": "N", "t": "τὰ μὲν οὖν ἄλλα καιρὸν οἰκεῖον ἔχει λεχθῆναι· κρύψαντες δὲ τῇ γῇ τὰ λείψανα τοῦ Ὄθωνος οὔτε μεγέθει σήματος οὔτ’ ἐπιγραφῆς ὄγκῳ τὸν τάφον ἐποίησαν ἐπίφθονον. εἶδον δὲ ἐν Βριξίλλῳ γενόμενος καὶ μνῆμα μέτριον καὶ τὴν ἐπιγραφὴν οὕτως ἔχουσαν, εἰ μεταφρασθείη· δηλώσει Μάρκου Ὄθωνος.", "st": "Oth. 18.1"}, {"sp": "N", "t": "ἀπέθανε δὲ Ὄθων ἔτη μὲν ἑπτὰ καὶ τριάκοντα βιώσας, ἄρξας δὲ τρεῖς μῆνας, ἀπολιπὼν δὲ μὴ χείρονας μηδ’ ἐλάττους τῶν τὸν βίον αὐτοῦ ψεγόντων τούς ἐπαινοῦντας τὸν θάνατον, βιώσας γὰρ οὐδὲν ἐπιεικέστερον Νέρωνος ἀπέθανεν εὐγενέστερον.", "st": "Oth. 18.2"}, {"sp": "N", "t": "οἱ δὲ στρατιῶται Πολλίωνος τοῦ ἑτέρου τῶν ἐπάρχων ὀμνύειν εὐθὺς εἰς τὸν Οὐϊτέλλιον κελεύσαντος ἐδυσχέραινον· καὶ πυθόμενοι τῶν συγκλητικῶν ἐνίους ἔτι παρεῖναι τούς μὲν ἄλλους ἀφῆκαν, Οὐεργινίῳ δὲ Ῥούφῳ πράγματα παρεῖχον ἅμα τοῖς ὅπλοις ἐλθόντες ἐπὶ τὴν οἰκίαν καὶ κατακαλοῦντες αὖθις καὶ κελεύοντες ἄρχειν ἢ πρεσβεύειν ὑπὲρ αὐτῶν. ὁ δὲ τὴν ἡγεμονίαν ἡττωμένων παραλαβεῖν, νενικηκότων πρότερον μὴ θελήσας, μανικὸν ἡγεῖτο πρεσβεύειν δὲ πρὸς τούς Γερμανοὺς δεδιώς, πολλὰ βεβιάσθαι παρὰ γνώμην ὑπ’ αὐτοῦ δοκοῦντας, ἔλαθε δι’ ἑτέρων θυρῶν ἐκποδὼν ποιήσας ἑαυτόν. ὡς δὲ τοῦτο ἔγνωσαν οἱ στρατιῶται, τούς τε ὅρκους ἐδέξαντο καὶ τοῖς περὶ τὸν Κεκίναν προσέθεντο συγγνώμης τυχόντες.", "st": "Oth. 18.3"}], []);})();
